import Foundation
import CoreBluetooth
import UIKit

/// One-shot owner for an obsolete CoreBluetooth restoration namespace. It
/// never scans or connects; it only cancels peripherals restored from the
/// contaminated v1 stream-5 trial so they cannot compete with production v2.
private final class AtriaLegacyBLECentralCleaner: NSObject, CBCentralManagerDelegate {
    let id = UUID()
    private var central: CBCentralManager?
    private var releaseWorkItem: DispatchWorkItem?
    private var restoredPeripheralCount = 0
    private var didFinish = false
    private let onFinished: (UUID) -> Void

    init(restoreIdentifier: String, onFinished: @escaping (UUID) -> Void) {
        self.onFinished = onFinished
        super.init()
        central = CBCentralManager(delegate: self,
                                   queue: nil,
                                   options: [CBCentralManagerOptionRestoreIdentifierKey: restoreIdentifier])
    }

    deinit {
        releaseWorkItem?.cancel()
    }

    func centralManagerDidUpdateState(_ central: CBCentralManager) {
        // A namespace with no restored peripherals has completed its only
        // purpose as soon as CoreBluetooth settles its initial state. Keep a
        // short grace turn so a restoration callback queued beside this one
        // can supersede the release with the longer cancellation grace below.
        guard restoredPeripheralCount == 0 else { return }
        scheduleRelease(after: 0.5)
    }

    func centralManager(_ central: CBCentralManager, willRestoreState dict: [String: Any]) {
        let peripherals = (dict[CBCentralManagerRestoredStatePeripheralsKey] as? [CBPeripheral]) ?? []
        restoredPeripheralCount = peripherals.count
        for peripheral in peripherals {
            central.cancelPeripheralConnection(peripheral)
        }
        AtriaDebugLog("ATRIADBG ble_restore status=cleanup_obsolete_namespace peripherals=%d", peripherals.count)
        // Cancellation is asynchronous. Retain this obsolete central only
        // long enough for CoreBluetooth to enqueue the disconnects, then
        // release its restoration/XPC session instead of leaking it for the
        // entire application process.
        scheduleRelease(after: peripherals.isEmpty ? 0.5 : 2)
    }

    private func scheduleRelease(after delay: TimeInterval) {
        guard !didFinish else { return }
        releaseWorkItem?.cancel()
        let work = DispatchWorkItem { [weak self] in
            guard let self, !self.didFinish else { return }
            self.didFinish = true
            self.central = nil
            self.onFinished(self.id)
        }
        releaseWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
    }
}

@MainActor
private final class PowerThermalGovernor {
    enum Mode: String {
        case nominal
        case fair
        case serious
        case critical
    }

    private(set) var mode: Mode = .nominal
    private var observers: [NSObjectProtocol] = []
    var onChange: ((Mode) -> Void)?
    var onThermalStateChange: ((ProcessInfo.ThermalState) -> Void)?

    init() {
        refresh(notify: false)
        observers.append(NotificationCenter.default.addObserver(
            forName: ProcessInfo.thermalStateDidChangeNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                self.onThermalStateChange?(ProcessInfo.processInfo.thermalState)
                self.refresh(notify: true)
            }
        })
        observers.append(NotificationCenter.default.addObserver(
            forName: .NSProcessInfoPowerStateDidChange,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in self?.refresh(notify: true) }
        })
    }

    deinit {
        for observer in observers {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    var cadenceMultiplier: Double {
        switch mode {
        case .nominal:
            return 1
        case .fair:
            return 1.5
        case .serious:
            return 2.5
        case .critical:
            return 4
        }
    }

    var shouldSuspendNonEssentialWork: Bool {
        mode == .critical
    }

    var shouldDeferNonEssentialAnalysis: Bool {
        mode == .serious || mode == .critical
    }

    /// True only under genuine device heat. `mode` deliberately maps Low
    /// Power Mode to `.serious` so analysis cadence slows on a draining
    /// battery, but LPM is a user battery preference, not thermal danger:
    /// an overnight phone left in Low Power Mode must still be allowed to
    /// admit the durable history drain that credits its banked coverage.
    /// The 2026-07-28 locked-phone strand proof concerned real `.serious`
    /// heat and remains honored by callers using this property.
    var shouldDeferDurableHistoryAdmissionForHeat: Bool {
        let thermal = ProcessInfo.processInfo.thermalState
        return thermal == .serious || thermal == .critical
    }

    private func refresh(notify: Bool) {
        let next = Self.mode(thermalState: ProcessInfo.processInfo.thermalState,
                             lowPower: ProcessInfo.processInfo.isLowPowerModeEnabled)
        guard next != mode else { return }
        mode = next
        if notify {
            onChange?(next)
        }
    }

    private static func mode(thermalState: ProcessInfo.ThermalState, lowPower: Bool) -> Mode {
        if thermalState == .critical {
            return .critical
        }
        if thermalState == .serious || lowPower {
            return .serious
        }
        if thermalState == .fair {
            return .fair
        }
        return .nominal
    }
}

/// Process-local edge for a restored foreground link whose first interactive
/// glance arrives before CoreBluetooth delivers this epoch's first accepted HR.
/// The edge is deliberately memory-only: a foreground attempt may arm it once,
/// and the next accepted HR consumes it whether or not the app is still active.
/// Consequently background delivery and later one-Hz HR callbacks cannot turn
/// the glance checkpoint into a persistence or request loop.
struct AtriaBLEForegroundGlanceCheckpointRetryGate: Sendable {
    private(set) var isAwaitingFreshHeartRate = false

    mutating func recordForegroundAttempt(started: Bool) {
        isAwaitingFreshHeartRate = !started
    }

    mutating func consumeAfterAcceptedHeartRate(
        applicationIsActive: Bool
    ) -> Bool {
        guard isAwaitingFreshHeartRate else { return false }
        isAwaitingFreshHeartRate = false
        return applicationIsActive
    }
}

/// Process-local admission for the durable interrupted-drain authority probe.
/// Accepted HR arrives at roughly one hertz, but the authority is a canonical,
/// fully validated recovery record rather than live telemetry. Probe it once
/// per callback epoch, coalesce while that read is in flight, and only retry a
/// failed read after a bounded cooldown. A new callback epoch is always allowed
/// to supersede an older in-flight or completed probe.
struct AtriaBLEPersistedDrainAuthorityProbeGate: Sendable {
    private(set) var inFlightEpoch: UInt64?
    private(set) var completedEpoch: UInt64?
    private(set) var retryEpoch: UInt64?
    private(set) var retryNotBefore: Date?

    mutating func begin(
        epoch: UInt64,
        now: Date,
        eligible: Bool
    ) -> Bool {
        guard eligible,
              completedEpoch != epoch,
              inFlightEpoch != epoch else { return false }
        if retryEpoch == epoch,
           let retryNotBefore,
           now < retryNotBefore {
            return false
        }
        inFlightEpoch = epoch
        if retryEpoch != epoch {
            retryEpoch = nil
            retryNotBefore = nil
        }
        return true
    }

    mutating func finish(
        epoch: UInt64,
        succeeded: Bool,
        now: Date,
        retryDelay: TimeInterval
    ) {
        guard inFlightEpoch == epoch else { return }
        inFlightEpoch = nil
        if succeeded {
            completedEpoch = epoch
            retryEpoch = nil
            retryNotBefore = nil
        } else {
            retryEpoch = epoch
            retryNotBefore = now.addingTimeInterval(max(0, retryDelay))
        }
    }

    mutating func abandon(epoch: UInt64) {
        guard inFlightEpoch == epoch else { return }
        inFlightEpoch = nil
    }
}

private enum AtriaBLEPersistedDrainAuthorityProbeResult: Sendable {
    case loaded(AtriaHistoricalFullDrainCoverageStore.Authority?)
    case failed(String)
}

private enum AtriaBLEPersistedDrainAuthorityReleaseResult: Sendable {
    case released(Bool)
    case failed(String)
}

/// A bounded, process-local scheduling claim for an exact motion-bank ticket
/// whose first transport admission reached the archive-warm gate. This never
/// authorizes BLE history: warm-ready must re-enter the typed ticket selector,
/// which remints exact peripheral/object/epoch authority before any command.
struct AtriaBLEConnectedMotionBankArchiveWarmRetryGate: Sendable {
    enum Resolution: Equatable, Sendable {
        case none
        case retry(ticketID: String)
        case rearm(ticketID: String)
    }

    private(set) var ticketID: String?
    private(set) var deadline: Date?

    var isHolding: Bool { ticketID != nil }

    mutating func hold(
        ticketID: String,
        now: Date,
        waitLimit: TimeInterval
    ) {
        self.ticketID = ticketID
        deadline = now.addingTimeInterval(max(0, waitLimit))
    }

    func shouldSuppressHotPath(
        now: Date,
        applicationIsActive: Bool,
        archiveStillWarming: Bool
    ) -> Bool {
        guard ticketID != nil,
              let deadline else { return false }
        return applicationIsActive
            && archiveStillWarming
            && now < deadline
    }

    mutating func resolveWarmReady(now: Date) -> Resolution {
        resolveReady(now: now)
    }

    mutating func resolveReady(now: Date) -> Resolution {
        guard let ticketID,
              let deadline else { return .none }
        self.ticketID = nil
        self.deadline = nil
        return now < deadline
            ? .retry(ticketID: ticketID)
            : .rearm(ticketID: ticketID)
    }

    mutating func resolveFallback(
        expectedTicketID: String? = nil
    ) -> Resolution {
        guard let ticketID,
              expectedTicketID == nil || expectedTicketID == ticketID else {
            return .none
        }
        self.ticketID = nil
        deadline = nil
        return .rearm(ticketID: ticketID)
    }
}

/// Bounded first refusal for an attempts-zero motion ticket when restoration
/// discovers TX before this connection has delivered its first accepted HR.
/// The reservation is scheduling state only: accepted HR clears it before the
/// typed ticket selector remints exact object/epoch authority. If HR does not
/// arrive promptly, present 0x69 capture wins and the durable ticket remains
/// available at the next intentional boundary.
struct AtriaBLEConnectedMotionBankPreFreshHRArmGate: Sendable {
    private(set) var ticketID: String?
    private(set) var deadline: Date?

    var isHolding: Bool { ticketID != nil }

    @discardableResult
    mutating func hold(
        ticketID: String,
        now: Date,
        waitLimit: TimeInterval
    ) -> Bool {
        if self.ticketID == ticketID, deadline != nil {
            return false
        }
        self.ticketID = ticketID
        deadline = now.addingTimeInterval(max(0, waitLimit))
        return true
    }

    func blocksArm(ticketID: String, now: Date) -> Bool {
        self.ticketID == ticketID
            && deadline.map { now < $0 } == true
    }

    mutating func consumeForAcceptedHeartRate() -> String? {
        defer {
            ticketID = nil
            deadline = nil
        }
        return ticketID
    }

    mutating func resolveFallback(
        expectedTicketID: String? = nil
    ) -> String? {
        guard let ticketID,
              expectedTicketID == nil || expectedTicketID == ticketID else {
            return nil
        }
        self.ticketID = nil
        deadline = nil
        return ticketID
    }
}

/// Process-local successor fence for an explicit workout that physically
/// disconnected an in-flight WHOOP history page. The old callback epoch is
/// retained only as provenance: a 0x69 arm may resume after an accepted 2A37
/// sample proves a strictly newer epoch for the same strap. TX discovery,
/// lifecycle replay, and stale callbacks cannot consume this reservation.
struct AtriaBLEWorkoutHistoryPreemptionSuccessorGate: Sendable {
    private(set) var predecessorSource: AtriaBLECallbackEpochFence.Source?

    var isAwaitingReplacementAcceptedHeartRate: Bool {
        predecessorSource != nil
    }

    mutating func install(
        predecessorSource: AtriaBLECallbackEpochFence.Source
    ) {
        self.predecessorSource = predecessorSource
    }

    /// A predecessor reservation is meaningful only for that same saved
    /// strap. Retire it synchronously when the user connects a replacement so
    /// old provenance cannot black out motion capture on the new device.
    mutating func blocksArm(for peripheralID: UUID) -> Bool {
        guard let predecessorSource else { return false }
        guard predecessorSource.peripheralID == peripheralID else {
            self.predecessorSource = nil
            return false
        }
        return true
    }

    mutating func retire() {
        predecessorSource = nil
    }

    @discardableResult
    mutating func consumeAfterAcceptedHeartRate(
        source: AtriaBLECallbackEpochFence.Source,
        sourceIsCurrent: Bool
    ) -> Bool {
        guard sourceIsCurrent,
              let predecessorSource,
              source.peripheralID == predecessorSource.peripheralID,
              source.epoch > predecessorSource.epoch else {
            return false
        }
        self.predecessorSource = nil
        return true
    }
}

/// Connects to the strap over BLE and publishes the reliable, relevant data:
/// live heart rate, battery level, connection state — plus a raw log of the
/// proprietary stream for later protocol decoding.
@MainActor
final class AtriaBLEManager: NSObject, ObservableObject {
    /// Diagnostics-only accounting for the existing historical drain.  This is
    /// deliberately kept on the main actor with the orchestrator: it observes
    /// callback/order/persistence outcomes, but never participates in protocol
    /// decisions or changes the reducer's state.
    private struct HistoricalDrainTelemetry {
        var generation: UInt64 = 0
        var startedAt = Date()
        var lastProgressAt = Date()
        var stream5Received = 0
        var admitted = 0
        var decoded = 0
        var decodeErrors = 0
        var persisted = 0
        var persistErrors = 0
        var flushStarted = 0
        var flushSucceeded = 0
        var flushErrors = 0
        var ackSent = 0
        var ackSucceeded = 0
        var ackErrors = 0
        var pendingHighWater = 0

        mutating func reset(generation: UInt64, now: Date = Date()) {
            self = Self(generation: generation, startedAt: now, lastProgressAt: now)
        }

        mutating func observePending(_ depth: Int) {
            pendingHighWater = max(pendingHighWater, max(0, depth))
        }

        mutating func noteProgress(now: Date = Date()) {
            lastProgressAt = now
        }
    }

    /// Captured synchronously at CoreBluetooth delegate entry. Main-actor work
    /// must carry this token so callbacks queued by a dead link cannot mutate a
    /// newer history generation after reconnect.
    private nonisolated let bleCallbackEpochFence = AtriaBLECallbackEpochFence()
    /// A replacement CBCentralManager does not synchronously cancel callbacks
    /// already queued by the retired instance. Fence every central delegate
    /// entry with exact object identity and a replacement generation.
    private nonisolated let centralEventFence = AtriaBLECentralEventFence()

    // Compatibility aliases keep the manager's publication call sites stable;
    // validation and reconstruction are owned by the Foundation-only preparer.
    typealias ResearchAggregates = AtriaActiveSessionRestorePreparer.ResearchAggregates
    typealias ActiveSessionRestorePreparation = AtriaActiveSessionRestorePreparer.Preparation

    nonisolated static func validatedResearchAggregates(
        from record: ActiveSessionJournalRecord
    ) -> ResearchAggregates? {
        AtriaActiveSessionRestorePreparer.validatedResearchAggregates(from: record)
    }

    nonisolated static func prepareActiveSessionJournalRestore(
        _ record: ActiveSessionJournalRecord?,
        now: Date,
        maxAge: TimeInterval,
        maxSamples: Int,
        segmentGapLimit: TimeInterval,
        biologicalSex: AthleteProfile.BiologicalSex
    ) -> ActiveSessionRestorePreparation {
        AtriaActiveSessionRestorePreparer.prepare(
            record,
            now: now,
            maxAge: maxAge,
            maxSamples: maxSamples,
            segmentGapLimit: segmentGapLimit,
            biologicalSex: biologicalSex
        )
    }

    private let debugForceUnknownStrapGeneration: Bool
    static let thermalJournalCheckpointInterval: TimeInterval = 60

    struct LiveHeartWindow: Equatable {
        var sparkline: [Int]
        var average: Int?
        var peak: Int?

        static let empty = LiveHeartWindow(sparkline: [], average: nil, peak: nil)
    }

    private struct ParsedRealtimePacket {
        let realtimeUnix: UInt32
        let hr: Int
        let rrValues: [Int]
        let truncated: Bool
        let frameTime: Date
    }

    private struct ParsedHeartRatePacket {
        let hr: Int
        let rrValues: [Int]
        let truncated: Bool
        /// `nil` means the optional HRS contact-status bits were unsupported.
        /// This is diagnostic evidence only; it never gates accepted HR/RR.
        let sensorContactDetected: Bool?
        let rrFlagPresent: Bool
        let frameTime: Date
    }

    private struct PendingHeartRateUpdate {
        let packet: ParsedHeartRatePacket?
        let rawData: Data
        /// Callback receipt time is separate from the decoded frame timestamp.
        /// It is the only honest boundary available if a queued callback is
        /// discarded before MainActor processing.
        let receivedAt: Date
        let callbackSource: AtriaBLECallbackEpochFence.Source
    }

    private struct PendingRealtimeUpdate {
        let packet: ParsedRealtimePacket
        let callbackSource: AtriaBLECallbackEpochFence.Source
    }

    private struct HeartRateIngressOverflow {
        let droppedCount: Int
        let firstDroppedAt: Date
        let lastDroppedAt: Date

        func merged(with next: HeartRateIngressOverflow) -> HeartRateIngressOverflow {
            HeartRateIngressOverflow(
                droppedCount: droppedCount + next.droppedCount,
                firstDroppedAt: min(firstDroppedAt, next.firstDroppedAt),
                lastDroppedAt: max(lastDroppedAt, next.lastDroppedAt)
            )
        }
    }

    private struct PendingHeartRateDrainBatch {
        let updates: [PendingHeartRateUpdate]
        let overflows: [PendingHeartRateIngressOverflow]
    }

    private struct PendingHeartRateIngressOverflow {
        let overflow: HeartRateIngressOverflow
        let callbackSource: AtriaBLECallbackEpochFence.Source
    }

    struct HeartRateIngressDropReceipt: Equatable, Sendable {
        let receivedAt: Date
        let callbackSource: AtriaBLECallbackEpochFence.Source
    }

    struct HeartRateIngressDropAttribution: Equatable, Sendable {
        let droppedCount: Int
        let firstDroppedAt: Date
        let lastDroppedAt: Date
        let callbackSource: AtriaBLECallbackEpochFence.Source
    }

    private struct LongWearSupervisorConfig: Equatable {
        let label: String
        let rest: Int
        let maxHR: Int
        let checkpointInterval: TimeInterval
        let diagnosticInterval: TimeInterval
        let autoSaveInterval: TimeInterval
        let noDataTimeout: TimeInterval
        let noDataCheckInterval: TimeInterval
        let hrContinuityTimeout: TimeInterval
        let rrPresenceTimeout: TimeInterval
        let acceptedHRTimeout: TimeInterval

        var baseTickInterval: TimeInterval {
            max(3, min(noDataCheckInterval, diagnosticInterval, autoSaveInterval, hrContinuityTimeout / 2, 60))
        }
    }

    enum CollectionProfile: String, CaseIterable, Identifiable {
        case batterySaver
        case balanced
        case maxCoverage

        var id: String { rawValue }

        var label: String {
            switch self {
            case .batterySaver: return "Saver"
            case .balanced: return "Balanced"
            case .maxCoverage: return "Coverage"
            }
        }

        var detail: String {
            switch self {
            case .batterySaver: return "Cooler cadence, slower recovery"
            case .balanced: return "Default overnight profile"
            case .maxCoverage: return "Fastest stale-data response"
            }
        }

        fileprivate var cadenceMultiplier: Double {
            switch self {
            case .batterySaver: return 1.75
            case .balanced: return 1.0
            case .maxCoverage: return 0.75
            }
        }

        fileprivate var staleTimeoutMultiplier: Double {
            switch self {
            case .batterySaver: return 1.4
            case .balanced: return 1.0
            case .maxCoverage: return 0.85
            }
        }

        fileprivate static func load(defaults: UserDefaults = .standard) -> CollectionProfile {
            guard let raw = defaults.string(forKey: CollectionProfileDefaults.profile),
                  let profile = CollectionProfile(rawValue: raw) else {
                return .balanced
            }
            return profile
        }
    }

    nonisolated static func shouldBeginStalledStreamRepair(lastRepairAt: Date?,
                                                           now: Date,
                                                           cooldown: TimeInterval = stalledStreamRepairCooldown) -> Bool {
        guard let lastRepairAt else { return true }
        return now.timeIntervalSince(lastRepairAt) >= cooldown
    }

    nonisolated static func hrvRefreshMinimumInterval(isRecording: Bool,
                                                      foregroundInteractive: Bool) -> TimeInterval {
        if isRecording { return captureHRVRefreshMinimumInterval }
        return foregroundInteractive
            ? foregroundLiveHRVRefreshMinimumInterval
            : backgroundLiveHRVRefreshMinimumInterval
    }

    nonisolated static func shouldRefreshHRVAnalysis(now: Date,
                                                     lastAnalysisAt: Date?,
                                                     isRecording: Bool,
                                                     foregroundInteractive: Bool) -> Bool {
        guard let lastAnalysisAt else { return true }
        let age = now.timeIntervalSince(lastAnalysisAt)
        // Wall-clock changes must not strand the persisted cadence marker in
        // the future. Fail open once, then the successful analysis persists a
        // new marker in the current clock domain. This mirrors the live-session
        // checkpoint gate and keeps both normal wear and explicit captures
        // recoverable after travel/manual clock correction.
        guard age >= 0 else { return true }
        return age >= hrvRefreshMinimumInterval(
            isRecording: isRecording,
            foregroundInteractive: foregroundInteractive
        )
    }

    nonisolated static func shouldAttemptHRVAnalysis(now: Date,
                                                     lastReadyAnalysisAt: Date?,
                                                     lastAttemptAt: Date?,
                                                     isRecording: Bool,
                                                     hasReadySnapshot: Bool,
                                                     cleanWindowSeconds: TimeInterval,
                                                     latestRRSampleAt: Date? = nil,
                                                     foregroundInteractive: Bool) -> Bool {
        if isRecording {
            return shouldRefreshHRVAnalysis(now: now,
                                            lastAnalysisAt: lastAttemptAt,
                                            isRecording: true,
                                            foregroundInteractive: foregroundInteractive)
        }
        if let lastReadyAnalysisAt,
           !shouldRefreshHRVAnalysis(now: now,
                                     lastAnalysisAt: lastReadyAnalysisAt,
                                     isRecording: false,
                                     foregroundInteractive: foregroundInteractive) {
            return false
        }
        guard cleanWindowSeconds >= 300 else { return false }
        guard let lastAttemptAt else { return true }
        let attemptAge = now.timeIntervalSince(lastAttemptAt)
        // A failed automatic attempt is persisted across reconnects and
        // relaunches. Treat a
        // future marker as invalid instead of waiting for the wall clock to
        // catch up before trying another qualified window.
        guard attemptAge >= 0 else { return true }

        // A successful ready snapshot keeps the four-hour metric cadence above.
        // Once that cadence is due, a failed/cancelled attempt must not suppress a
        // newly clean five-minute RR window for another four hours. Retry only
        // after a bounded interval and only when fresh RR evidence has arrived.
        if let lastReadyAnalysisAt, lastAttemptAt <= lastReadyAnalysisAt {
            return true
        }
        guard attemptAge >= normalWearHRVFailedAttemptRetryInterval,
              let latestRRSampleAt,
              latestRRSampleAt > lastAttemptAt else {
            return false
        }
        return true
    }

    nonisolated static func shouldUseProprietaryRealtimeRRForMetrics(
        standardRecentlyActive: Bool,
        layoutVersion: String = proprietaryRealtimeRRLayoutVersion
    ) -> Bool {
        !standardRecentlyActive
            && validatedProprietaryRealtimeRRLayoutVersions.contains(layoutVersion)
    }

    nonisolated static func encodedReadyHRVSnapshot(_ snapshot: HRVSnapshot) -> Data? {
        guard snapshot.isReady else { return nil }
        return try? JSONEncoder().encode(snapshot)
    }

    nonisolated static func decodedReadyHRVSnapshot(_ data: Data?,
                                                    now: Date,
                                                    maxAge: TimeInterval = maxPersistedReadyHRVAge) -> HRVSnapshot? {
        guard let data,
              let snapshot = try? JSONDecoder().decode(HRVSnapshot.self, from: data),
              snapshot.isReady else {
            return nil
        }
        let age = now.timeIntervalSince(snapshot.analyzedAt)
        guard age >= -300, age <= maxAge else { return nil }
        return snapshot
    }

    private enum ParsedProprietaryUpdate {
        case realtime(ParsedRealtimePacket)
        case commandResponse(AtriaFrame)
        case historyMetadata([UInt8])
        case historical([UInt8])
        case unknown(payload: [UInt8], fullFrame: [UInt8])
    }

    private enum PendingProprietaryMainActorWork {
        case r10Metadata(payloadLength: Int)
        case frame(
            Data,
            parsedUpdate: ParsedProprietaryUpdate?,
            storedFrame: AtriaFrame?,
            historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
        )
    }

    private struct PendingProprietaryCallbackBatch {
        let callbackSource: AtriaBLECallbackEpochFence.Source
        let peripheral: CBPeripheral
        let characteristicUUID: CBUUID
        let receivedAt: Date
        let work: [PendingProprietaryMainActorWork]
    }

    private struct ProprietaryWriteCompletion {
        let generation: UInt64?
        let entry: AtriaWhoopWriteCompletionLedger.Entry
        let succeeded: Bool
        let errorDomain: String?
        let errorCode: Int?
    }

    private enum AwaitedHistoryWriteResult: Equatable {
        case confirmed
        case securityRequired
        case rejected
        case failed
        case timedOut
    }

    private enum ProductionHistoryRangeResult {
        case success(AtriaWhoop4HistoryCursorRange)
        case failure(AwaitedHistoryWriteResult)
    }

    private struct RRWindowSummary {
        let frames: Int
        let rrFrames: Int
        let fraction: Double
        let span: TimeInterval
        let frameMaxGap: TimeInterval
        let sourceLabel: String
        let firstTimestamp: Date?
    }

    private struct RRBatchAppendPayload {
        let intervals: [RRInterval]
        let beatTimes: [Date]
        let rrPoints: [SavedSession.RRPoint]
    }

    private struct RecentBreathworkRRSampleCache {
        let archiveRevision: UInt64
        let maxAge: TimeInterval
        let nowBucket: Int
        let samples: [AtriaBreathworkSession.RRSample]
    }

    private struct LongWearSessionAnalysis {
        let snapshot: SavedSession?
        let readiness: WorkoutReadiness?
    }

    private struct SampleDiagnosticsSnapshot {
        var rawNotifications: Int
        var acceptedSamples: Int
        var zeroSamples: Int
        var heldArtifacts: Int
        var droppedArtifacts: Int
        var rawGaps: Int
        var acceptedGaps: Int
        var maxRawGap: TimeInterval
        var maxAcceptedGap: TimeInterval
        var lastStatus: String
        var lastReason: String

        static let empty = SampleDiagnosticsSnapshot(rawNotifications: 0,
                                                     acceptedSamples: 0,
                                                     zeroSamples: 0,
                                                     heldArtifacts: 0,
                                                     droppedArtifacts: 0,
                                                     rawGaps: 0,
                                                     acceptedGaps: 0,
                                                     maxRawGap: 0,
                                                     maxAcceptedGap: 0,
                                                     lastStatus: "none",
                                                     lastReason: "none")

        static func load() -> SampleDiagnosticsSnapshot {
            let defaults = UserDefaults.standard
            return SampleDiagnosticsSnapshot(rawNotifications: defaults.integer(forKey: SampleDefaults.rawNotifications),
                                             acceptedSamples: defaults.integer(forKey: SampleDefaults.acceptedSamples),
                                             zeroSamples: defaults.integer(forKey: SampleDefaults.zeroSamples),
                                             heldArtifacts: defaults.integer(forKey: SampleDefaults.heldArtifacts),
                                             droppedArtifacts: defaults.integer(forKey: SampleDefaults.droppedArtifacts),
                                             rawGaps: defaults.integer(forKey: SampleDefaults.rawGaps),
                                             acceptedGaps: defaults.integer(forKey: SampleDefaults.acceptedGaps),
                                             maxRawGap: defaults.double(forKey: SampleDefaults.maxRawGap),
                                             maxAcceptedGap: defaults.double(forKey: SampleDefaults.maxAcceptedGap),
                                             lastStatus: defaults.string(forKey: SampleDefaults.lastStatus) ?? "none",
                                             lastReason: defaults.string(forKey: SampleDefaults.lastReason) ?? "none")
        }
    }

    private func assignIfChanged<Value: Equatable>(_ keyPath: ReferenceWritableKeyPath<AtriaBLEManager, Value>,
                                                   _ newValue: Value) {
        if self[keyPath: keyPath] != newValue {
            self[keyPath: keyPath] = newValue
        }
    }

    // MARK: Published state for the UI
    enum Status: String { case poweredOff = "Bluetooth off", scanning = "Scanning…",
        connecting = "Connecting…", connected = "Connected", disconnected = "Disconnected" }

    enum FirstUseConnectionEvidence: Equatable {
        case provisionalConnection
        case whoopService
        case standardHeartRateMeasurement
    }

    enum ConnectedIdentityPromotionDisposition: Equatable {
        case preserveSavedBehavior
        case awaitFirstUseValidation
        case promoteFirstUseIdentity
        case rejectUnqualifiedStandardHeartRate
    }

    enum ScanDiscoveryMode: Equatable {
        case filtered
        case broad
    }

    struct ScanOrchestrationPlan: Equatable {
        let mode: ScanDiscoveryMode
        let schedulesWidening: Bool
        let schedulesRetry: Bool
    }

    /// User-facing recovery state. This deliberately represents only transport
    /// progress and durable coverage, never a conclusion inferred from rows.
    enum HistoricalRecoveryPresentation: Equatable {
        case idle
        case syncing(savedRecords: Int)
        case verified
        case partial(savedRecords: Int)
        case needsAttention
    }

    enum OfficialAppCoexistenceRisk: String {
        case advisory
        case suspected
        case cleared

        fileprivate static func load(defaults: UserDefaults = .standard) -> OfficialAppCoexistenceRisk {
            guard let raw = defaults.string(forKey: LinkDefaults.officialAppCoexistenceRisk),
                  let value = OfficialAppCoexistenceRisk(rawValue: raw) else {
                return .advisory
            }
            return value
        }

        var label: String {
            switch self {
            case .advisory:
                return "Strap check"
            case .suspected:
                return "Another app may interfere"
            case .cleared:
                return "Atria owns strap"
            }
        }
    }

    enum AtriaStrapModel: String {
        case unknown
        case strap3
        case strap4
        case strap4Class
        case strap5
        case strapMG

        var supportsSpO2: Bool {
            switch self {
            case .strap4, .strap4Class, .strap5, .strapMG: return true
            case .unknown, .strap3: return false
            }
        }

        var supportsSkinTemp: Bool {
            switch self {
            case .strap4, .strap4Class, .strap5, .strapMG: return true
            case .unknown, .strap3: return false
            }
        }

        var supportsGenerationSpecificDecode: Bool {
            switch self {
            case .strap4, .strap5, .strapMG: return true
            case .unknown, .strap3, .strap4Class: return false
            }
        }

        var supportsECG: Bool { self == .strapMG }
        var supportsBloodPressure: Bool { self == .strapMG }
    }

