    /// the same retained vault entry after warmup completes.
    nonisolated static func waitForHistoricalArchiveWarm(
        _ group: DispatchGroup,
        timeout: TimeInterval
    ) -> Bool {
        group.wait(timeout: .now() + max(0, timeout)) == .success
