    private enum CommandWriteMode: String {
        case withoutResponse = "wwr"
        case withResponse = "wr"
    }

    private nonisolated static func discoveryCharacteristics(for service: CBUUID) -> [CBUUID]? {
        switch service {
        case UUIDs.heartRateService:
            return [UUIDs.heartRateMeasure]
        case UUIDs.batteryService:
            return [UUIDs.batteryLevel, UUIDs.batteryLevelStatus]
        case UUIDs.deviceInfoService:
            return [UUIDs.manufacturerName, UUIDs.modelNumber,
                    UUIDs.firmwareRevision, UUIDs.hardwareRevision]
        case UUIDs.strapService:
            return [UUIDs.strapTX] + UUIDs.allNotify
        default:
            return nil
        }
    }

    nonisolated static func alreadyActiveProprietaryNotifications(
        _ states: [(uuid: CBUUID, isNotifying: Bool)]
    ) -> Set<CBUUID> {
        Set(states.compactMap { state in
            guard state.isNotifying, UUIDs.allNotify.contains(state.uuid) else { return nil }
            return state.uuid
        })
    }

    /// Protected long wear intentionally combines standard 2A37 heart rate with
    /// the single proprietary stream-5 R10 motion subscription. This is the
    /// production strap-only step transport; the rollback/suppression gate is
    /// evaluated before discovery and ingestion, so this helper must not add a
    /// second, contradictory research-only gate after stream 5 is already live.
    nonisolated static func shouldObservePassiveR10InProtectedStandardHR(
        characteristicUUID: CBUUID
    ) -> Bool {
        characteristicUUID == UUIDs.strapStream5
    }

    /// The complete proprietary characteristic set for protected production is
    /// deliberately small: stream 5 supplies R10 motion and TX is retained for
    /// the single leased activation command. Physical testing rejected adding
    /// the otherwise useful stream-4 battery event channel because it caused
    /// rapid reconnect churn. A latched rollback suppresses both without
    /// changing the standard 2A37 heart-rate subscription.
    nonisolated static func protectedStandardHRStrapCharacteristics(
        streamSuppressed: Bool,
        cleanOwner: ProtectedR10CleanOwner = .legacy
    ) -> [CBUUID]? {
        guard !streamSuppressed else { return nil }
        if cleanOwner == .protectedV9 {
            return protectedR10ResponseEventDataNotifyOrder + [UUIDs.strapTX]
        }
        return [UUIDs.strapStream5, UUIDs.strapTX]
    }

    /// Protected production keeps standard HR and the standard battery service
    /// available independently of the proprietary R10 rollback. 2A19 remains
    /// notification-only; 2A1B may use one bounded standard read outside
    /// history ownership. Neither path authorizes a custom command.
    nonisolated static func protectedStandardHRServices(
        streamSuppressed: Bool
    ) -> [CBUUID] {
        var services = [UUIDs.heartRateService, UUIDs.batteryService]
        if !streamSuppressed {
            services.append(UUIDs.strapService)
        }
        return services
    }

    /// Protected production uses the two standard Battery Service
    /// characteristics: 2A19 is the percentage and 2A1B is the charger state.
    /// 2A19 is notification-only in this profile. 2A1B is not a proprietary
    /// stream and never authorizes a command; a current-link CCCD completion or
    /// bounded standard read response is required before it can surface
    /// Charging.
    nonisolated static func protectedStandardHRCharacteristics(
        for service: CBUUID,
        streamSuppressed: Bool,
        cleanOwner: ProtectedR10CleanOwner = .legacy
    ) -> [CBUUID]? {
        switch service {
        case UUIDs.heartRateService:
            return [UUIDs.heartRateMeasure]
        case UUIDs.batteryService:
            return [UUIDs.batteryLevel, UUIDs.batteryLevelStatus]
        case UUIDs.strapService:
            return protectedStandardHRStrapCharacteristics(
                streamSuppressed: streamSuppressed,
                cleanOwner: cleanOwner
            )
        default:
            return nil
        }
    }

    /// Mirrors the protected discovery contract at the ingest boundary. A
    /// restored legacy proprietary notification is ignored; only production
    /// R10, or the explicitly pending one-shot battery response, can enter the
    /// decoder while standard-HR protection is active.
    nonisolated static func shouldAcceptProtectedProprietaryNotification(
        characteristicUUID: CBUUID,
        streamSuppressed: Bool,
        pendingOneShotBatteryResponse: Bool,
        historyRecoveryActive: Bool = false
    ) -> Bool {
        historyRecoveryActive
            || (characteristicUUID == UUIDs.strapStream5 && !streamSuppressed)
            || pendingOneShotBatteryResponse
    }

    /// One exhaustive owner decision for strap-service discovery. BOTH
    /// delegate stages (service and characteristic discovery) must route
    /// through this. The 2026-08-13 04:30 IST physical stall (cutover true,
    /// sequence false, zero IMU frames) was the characteristic stage
    /// suppressing the protected-v9 profile whenever any workout-bank flag
    /// was set — which is precisely when the motion requalifier runs. A
    /// pending/proving v9 bring-up temporarily outranks the bank; the bank's
    /// durable ticket/config is never touched and resumes at the v9 terminal.
    enum AtriaStrapDiscoveryOwner: String, CaseIterable {
        case history
        case diagnostic
        case protectedV9BringUp
        case workoutBank
        case standardHR
    }

    nonisolated static func resolveStrapDiscoveryOwner(
        historyRecoveryActive: Bool,
        diagnosticActive: Bool,
        standardHROnlyMode: Bool,
        protectedV9Owner: Bool,
        launchOrProofActive: Bool,
        workoutBankTransportRequested: Bool
    ) -> AtriaStrapDiscoveryOwner {
        if historyRecoveryActive { return .history }
        if diagnosticActive { return .diagnostic }
        if standardHROnlyMode, protectedV9Owner, launchOrProofActive {
            return .protectedV9BringUp
        }
        if standardHROnlyMode, workoutBankTransportRequested {
            return .workoutBank
        }
        return .standardHR
    }

    /// The four durable workout-bank request flags, read identically by both
    /// discovery stages (previously duplicated inline in each callback).
    nonisolated static func workoutBankTransportCurrentlyRequested(
        _ defaults: UserDefaults
    ) -> Bool {
        defaults.object(forKey: WorkoutMotionDefaults.ownerStartedAt) != nil
            || defaults.bool(forKey: Self.workoutHistoricalMotionBankEnabledKey)
            || defaults.bool(forKey: Self.workoutHistoricalMotionBankStopPendingKey)
            || defaults.bool(forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey)
    }

    nonisolated static let protectedV9BringUpTraceKey = "atria.protectedV9.bringUpTrace.v1"
    private static let protectedV9BringUpTraceLimit = 48

    /// Bounded, versioned edge receipts for the protected-v9 dense bring-up.
    /// Console capture is unreliable across reconnects, so every seam that
    /// can decline or stall the profile leaves a durable receipt carrying
    /// enough authority (connection generation, owner state, bank flag,
    /// peripheral hash) to reject a stale edge. No payload bytes, no health
    /// samples, never written per IMU frame.
    private func recordProtectedV9BringUpEdge(_ edge: String) {
        let defaults = UserDefaults.standard
        let generation = Int(connectedAt?.timeIntervalSince1970 ?? 0)
        let bank = Self.workoutBankTransportCurrentlyRequested(defaults)
        let owner = defaults.string(
            forKey: Self.protectedR10CleanOwnerStateKey
        ) ?? "none"
        let peripheralHash = peripheral.map {
            String($0.identifier.uuidString.prefix(8))
        } ?? "none"
        let line = "t=\(Int(Date().timeIntervalSince1970)) edge=\(edge) gen=\(generation) owner=\(owner) bank=\(bank ? 1 : 0) ph=\(peripheralHash)"
        var lines = (defaults.string(forKey: Self.protectedV9BringUpTraceKey) ?? "")
            .split(separator: "\n", omittingEmptySubsequences: true)
            .map(String.init)
        lines.append(line)
        if lines.count > Self.protectedV9BringUpTraceLimit {
            lines.removeFirst(lines.count - Self.protectedV9BringUpTraceLimit)
        }
        defaults.set(lines.joined(separator: "\n"),
                     forKey: Self.protectedV9BringUpTraceKey)
    }

    /// Protected-v9 discovery owns the normal response/event/data profile, but
    /// must step aside while the generation-bound history transport owns those
    /// same characteristics. Returning from the delegate after its inner guard
    /// rejected history used to swallow TX and every history subscription.
    nonisolated static func shouldUseProtectedV9CharacteristicHandler(
        standardHROnlyMode: Bool,
        historyRecoveryActive: Bool,
        strapService: Bool,
        protectedV9Owner: Bool,
        launchOrProofActive: Bool
    ) -> Bool {
        standardHROnlyMode
            && !historyRecoveryActive
            && strapService
            && protectedV9Owner
            && launchOrProofActive
    }

    private func batteryNotificationTransportIsActive(
        now: Date,
        defaults: UserDefaults = .standard
    ) -> Bool {
        let linkConnected = peripheral?.state == .connected && status == .connected
        guard linkConnected else { return false }
        let confirmationSupportsCurrentConnection = Self.batteryNotificationConfirmationSupportsCurrentConnection(
            confirmedAt: (defaults.object(forKey: BatteryDefaults.notificationConfirmedAt) as? Double)
                .map(Date.init(timeIntervalSince1970:)),
            lastError: defaults.string(forKey: BatteryDefaults.notificationLastError),
            connectionStartedAt: batteryConnectionRestoredSamePeripheral ? nil : connectedAt,
            linkConnected: linkConnected,
            now: now
        )
        // `CBCharacteristic.isNotifying` can remain true after CoreBluetooth
        // reports a value-delivery error. The error revokes this epoch until a
        // successful subscription-state callback clears it; the stale object
        // flag must never renew the display lease by itself.
        return Self.batteryNotificationTransportEvidenceIsUsable(
            characteristicIsNotifying: batteryLevelCharacteristic?.isNotifying == true,
            confirmationSupportsCurrentConnection: confirmationSupportsCurrentConnection,
            lastError: defaults.string(forKey: BatteryDefaults.notificationLastError)
        )
    }

    /// A genuine reconnect may not receive a 2A19 callback until the integer
    /// percentage changes. Keep a recent, already-validated mid-range baseline
    /// visible as *Recent* when live HR proves the same saved strap is currently
    /// connected. This is display-only evidence: callers must not clear
    /// `requiresFreshConfirmation`, renew a live lease, or schedule battery
    /// alerts from it. A disputed/rejected callback belongs to the *new*
    /// notification epoch; it must block promotion, but it must not erase the
    /// separately accepted baseline. Keeping that baseline visible as Recent
    /// avoids a permanent Pending UI while a false restoration sentinel is
    /// quarantined.
    private func freshConnectedCachedBatteryBaselineIsDisplayable(
        now: Date,
        defaults: UserDefaults = .standard
    ) -> Bool {
        let linkConnected = peripheral?.state == .connected && status == .connected
        let savedPeripheralIdentifier = defaults
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        return Self.freshConnectedCachedBatteryBaselineIsDisplayEligible(
            level: batteryLevel,
            acceptedAt: lastAcceptedBatteryLevelAt,
            source: defaults.string(forKey: BatteryDefaults.source) ?? "none",
            displayedIsCached: displayedBatteryLevelIsCached,
            requiresFreshConfirmation: defaults.bool(
                forKey: BatteryDefaults.requiresFreshConfirmation
            ),
            linkConnected: linkConnected,
            sameSavedPeripheral: peripheral?.identifier == savedPeripheralIdentifier,
            now: now
        )
    }

    private func recentReconnectBatteryBaselineIsDisplayable(
        now: Date,
        defaults: UserDefaults = .standard
    ) -> Bool {
        let linkConnected = peripheral?.state == .connected && status == .connected
        let savedPeripheralIdentifier = defaults
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        let sameSavedPeripheral = peripheral?.identifier == savedPeripheralIdentifier
        let connectionStartedAt = connectedAt ?? batteryBaselineValidationStartedAt
        let currentConnectionHasHeartRate = lastRawHRNotificationAt.map {
            $0 >= connectionStartedAt
        } ?? false
        return Self.recentReconnectBatteryBaselineIsDisplayEligible(
            level: batteryLevel,
            acceptedAt: lastAcceptedBatteryLevelAt,
            source: defaults.string(forKey: BatteryDefaults.source) ?? "none",
            displayedIsCached: displayedBatteryLevelIsCached,
            requiresFreshConfirmation: defaults.bool(
                forKey: BatteryDefaults.requiresFreshConfirmation
            ),
            linkConnected: linkConnected,
            sameSavedPeripheral: sameSavedPeripheral,
            currentConnectionHasHeartRate: currentConnectionHasHeartRate,
            hasPendingDisputedReading: pendingBatteryDropCandidate != nil,
            currentNotificationEpochHadRejectedCallback:
                batteryNotificationEpochHadRejectedCallback,
            now: now
        )
    }

    /// Single projection gate for every UI/notification consumer. A raw
    /// in-memory percentage is not display truth after its independent 2A19
    /// evidence expires, even if HR continues on another characteristic.
    func displayableBatteryLevel(now: Date = Date()) -> Int? {
        let defaults = UserDefaults.standard
        let requiresFreshConfirmation = defaults.bool(
            forKey: BatteryDefaults.requiresFreshConfirmation
        )
        let activeAcceptedNotification = batteryNotificationTransportIsActive(
            now: now,
            defaults: defaults
        )
            && !displayedBatteryLevelIsCached
        let restoredNotificationLease = Self.notificationLeaseSupportsBatteryDisplay(
            level: batteryLevel,
            source: defaults.string(forKey: BatteryDefaults.source) ?? "none",
            requiresFreshConfirmation: requiresFreshConfirmation,
            linkConnected: peripheral?.state == .connected && status == .connected,
            notificationLeaseAt: (defaults.object(forKey: BatteryDefaults.notificationLeaseAt) as? Double)
                .map(Date.init(timeIntervalSince1970:)),
            now: now
        )
        let recentReconnectBaseline = recentReconnectBatteryBaselineIsDisplayable(
            now: now,
            defaults: defaults
        )
        let freshConnectedCachedBaseline = freshConnectedCachedBatteryBaselineIsDisplayable(
            now: now,
            defaults: defaults
        )
        guard (0...100).contains(batteryLevel) else { return nil }
        if recentReconnectBaseline { return batteryLevel }
        if freshConnectedCachedBaseline { return batteryLevel }
        guard !requiresFreshConfirmation,
              (Self.batteryLevelIsFresh(lastAcceptedAt: lastAcceptedBatteryLevelAt,
                                        now: now)
                || activeAcceptedNotification
                || restoredNotificationLease) else { return nil }
        return batteryLevel
    }

    /// Timestamp for the level-bearing packet behind the current display
    /// projection. UI callers use this only to age an explicitly Recent value;
    /// it is not a substitute for current charge-state evidence.
    var lastVerifiedBatteryLevelAt: Date? {
        lastAcceptedBatteryLevelAt
    }

    /// Freshness corroboration for the change-driven Battery Service stream.
    /// This does not replace the level packet's timestamp. It only proves that
    /// the same connected strap still has an active, error-free 2A19 lease;
    /// silence then means the integer percentage has not changed. Restoration
    /// boundary values stay packet-timed because 0/10/100 can be sentinels.
    func batteryDisplayCorroboratedAt(now: Date = Date()) -> Date? {
        guard let level = displayableBatteryLevel(now: now),
              (11...99).contains(level) else {
            return lastAcceptedBatteryLevelAt
        }
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: BatteryDefaults.requiresFreshConfirmation),
              batteryNotificationTransportIsActive(now: now, defaults: defaults),
              let leaseAt = (defaults.object(forKey: BatteryDefaults.notificationLeaseAt) as? Double)
                .map(Date.init(timeIntervalSince1970:)),
              leaseAt <= now,
              now.timeIntervalSince(leaseAt) <= Self.batteryDisplayFreshnessLimit else {
            return lastAcceptedBatteryLevelAt
        }
        return max(lastAcceptedBatteryLevelAt ?? leaseAt, leaseAt)
    }

    private struct HistoryClockRef {
        let device: UInt32
        let wall: UInt32
        var driftSeconds: Int { Int(wall) - Int(device) }
        var snappedDriftSeconds: Int {
            let drift = driftSeconds
            guard abs(drift) >= 86_400 else { return drift }
            let granularity = 300
            if drift >= 0 {
                return ((drift + granularity / 2) / granularity) * granularity
            }
            return ((drift - granularity / 2) / granularity) * granularity
        }
    }

    override convenience init() {
        self.init(startsBluetooth: true)
    }

    /// A retained restore transaction must fail closed before CoreBluetooth is
    /// constructed: state restoration can synchronously reconnect a saved
    /// peripheral from the manager initializer itself.
    init(startsBluetooth: Bool) {
        let arguments = ProcessInfo.processInfo.arguments
#if DEBUG
        let fastDrainReconciliationOnly = arguments.contains(
            AtriaWhoop4SacrificialFastDrainReceiptVerifier
                .reconciliationModeArgument
        )
        let fixtureIndex = arguments.firstIndex(of: "--atria-ui-fixture")
        let fixtureValue = fixtureIndex.flatMap { index -> String? in
            let next = arguments.index(after: index)
            guard arguments.indices.contains(next) else { return nil }
            return arguments[next]
        }
        debugForceUnknownStrapGeneration = fixtureValue == "unknown-strap-generation"
#else
        debugForceUnknownStrapGeneration = false
#endif
        super.init()
#if DEBUG
        // Reconciliation is a bookkeeping-only process mode. Return before
        // motion-bank repair, archive warmup, session restoration, or
        // CoreBluetooth construction so the verified receipt can authorize
        // only the narrowly scoped old-gap retirement below.
        if fastDrainReconciliationOnly {
            reconcileVerifiedSacrificialFastDrainIfRequested(
                arguments: arguments
            )
            bluetoothStartupSuspended = true
            AtriaDebugLog(
                "ATRIADBG ble_manager_init status=suspended reason=verified_fast_drain_reconciliation_no_ble"
            )
            return
        }
#endif
        let launchDefaults = UserDefaults.standard
        let persistedBankWasEnabled = launchDefaults.bool(
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        )
        let persistedStrapIdentifier = launchDefaults.string(
            forKey: LinkDefaults.savedPeripheralUUID
        )
        if persistedBankWasEnabled,
           let persistedStrapIdentifier,
           AtriaWhoop4MotionBankCoverageLedger.retireOrphanedOpenCoverage(
               lastObservedAt:
                   persistedLastRawNotificationAt(defaults: launchDefaults),
               strapIdentifier: persistedStrapIdentifier,
               defaults: launchDefaults
           ) {
            launchDefaults.set(
                false,
                forKey: Self.workoutHistoricalMotionBankEnabledKey
            )
            launchDefaults.set(
                true,
                forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey
            )
            launchDefaults.removeObject(
                forKey: Self.workoutHistoricalMotionBankArmedAtKey
            )
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=orphaned_process_epoch_closed action=retain_only_through_last_durable_hr_rearm_after_fresh_hr"
            )
        }
        let repairedWorkoutTruncatedBanks =
            AtriaWhoop4MotionBankCoverageLedger
                .repairWorkoutTruncatedOffloadCoverage()
        if repairedWorkoutTruncatedBanks > 0 {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=workout_truncated_coverage_repaired tickets=%d action=request_complete_durable_bank_interval",
                repairedWorkoutTruncatedBanks
            )
        }
        let repairedCrossConnectionBanks =
            AtriaWhoop4MotionBankCoverageLedger
                .repairCrossConnectionCoverage()
        if repairedCrossConnectionBanks > 0 {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=cross_connection_coverage_repaired tickets=%d action=retry_only_proven_connection_epochs_no_synthetic_coverage",
                repairedCrossConnectionBanks
            )
        }
        // Do not let the first recovered history frame pay the cost of
        // rebuilding the exact-identity index over every retained raw chunk.
        // This lane is deliberately detached from CoreBluetooth and performs
        // no transport work or recovery-state mutation.
        beginHistoricalArchiveWarmBackgroundLease()
        historicalArchiveWarmGroup.enter()
        let archiveWarmGroup = historicalArchiveWarmGroup
        historicalArchiveWarmQueue.async { [weak self] in
            defer {
                archiveWarmGroup.leave()
                Task { @MainActor [weak self] in
                    self?.endHistoricalArchiveWarmBackgroundLease(status: "finished")
                }
            }
            do {
                AtriaDebugLog("ATRIADBG historical_archive_warm status=started action=identity_store_open_only")
                try HistoricalArchive.warmDurableIdentityStoreForBackgroundRecovery()
                AtriaDebugLog("ATRIADBG historical_archive_warm status=ready action=no_archive_append_no_ack_no_coverage")
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.historicalArchiveWarmState = .ready
                    self.historicalArchiveWarmFailure = nil
                    self.resumeConnectedMotionBankAfterArchiveWarmReadyIfNeeded()
                    self.resumePendingForcedHistoricalSyncAfterLivePersistenceIfNeeded(
                        reason: "historical_archive_warm_ready"
                    )
                }
            } catch {
                // The replay journal remains intact. A later retry will reopen
                // the store normally and still cannot send an ACK from this
                // background warmup failure.
                AtriaDebugLog("ATRIADBG historical_archive_warm status=deferred error=%@ action=retain_orphan_raw_no_ack_no_coverage",
                              String(describing: error))
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.historicalArchiveWarmState = .failed
                    self.historicalArchiveWarmFailure = String(describing: error)
                    self.releaseConnectedMotionBankArchiveWarmFirstRefusal(
                        reason: "archive_warm_failed"
                    )
                }
            }
        }
        // A process crash cannot resume the old reducer/ACK gate. Preserve the
        // bounded ingress journal until a later verified owner can archive its
        // exact raw frames. It is not ACK/coverage authority, but it can still
        // contain real strap rows not yet in the canonical archive. The single
        // journal has a hard 32 MiB cap, so retaining it across a disconnected
        // launch cannot grow user storage without bound.
        let ingressDirectory = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        )[0].appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionDirectoryName,
            isDirectory: true
        )
        let orphanIngressURL = ingressDirectory.appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionFileName
        )
        if FileManager.default.fileExists(atPath: orphanIngressURL.path) {
            AtriaDebugLog("ATRIADBG historyIngress status=retained reason=orphan_pending_archive action=await_verified_owner_no_ack_no_coverage")
        }
        // Launch-scoped transport authority must be parsed even when this
        // instance exists only to retain an obsolete restoration namespace.
        // Parsing below the early return made a fresh diagnostic/recovery
        // launch silently inherit stale process configuration.
        applyEarlyHistoricalLaunchConfiguration(arguments: arguments)
        guard startsBluetooth else {
            bluetoothStartupSuspended = true
            AtriaDebugLog("ATRIADBG ble_manager_init status=suspended reason=restore_marker_retained")
            return
        }
        motionCompactStoreObserver =
            NotificationCenter.default.addObserver(
                forName: AtriaWhoop4MotionTickCompactStore
                    .didSynchronizeNotification,
                object: nil,
                queue: .main
            ) { [weak self] _ in
                Task { @MainActor in
                    // Ticket verification must run after the exact compact
                    // generation is fsynced. Terminal callbacks can arrive
                    // while the archive queue is still materializing rows;
                    // this boundary clears every newly qualified ticket
                    // without starting another BLE transaction.
                    self?.evaluatePendingWorkoutHistoricalMotionBankOffload(
                        reason: "compact_generation_durable",
                        allowRetry: false
                    )
                }
            }
        // Drain-keeping P5: observe the phone's charging edge to resume the drain
        // when we plug in (a good background-execution window). Enabling battery
        // monitoring is required to read UIDevice.batteryState.
        UIDevice.current.isBatteryMonitoringEnabled = true
        lastPhoneChargingState = Self.phoneStateIsCharging(UIDevice.current.batteryState)
        phoneChargeStateObserver = NotificationCenter.default.addObserver(
            forName: UIDevice.batteryStateDidChangeNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in self?.handlePhoneChargeStateEdgeIfNeeded() }
        }
        // Retention must not depend on a history attempt eventually reaching a
        // terminal callback: normal long wear can leave one attempt open for a
        // long time. This starts one bounded, non-transport maintenance pass
        // after launch; later lifecycle and terminal edges coalesce behind it.
        scheduleHistoricalAdmissionLedgerMaintenance(reason: "manager_init")
        strapStepCalibrationCaptureUntil = AtriaStrapCalibrationArchive.configuredCaptureUntil(
            arguments: arguments
        )
        if let strapStepCalibrationCaptureUntil {
            AtriaDebugLog("ATRIADBG strap_step_calibration status=enabled until_utc=%@ source=existing_protected_r10 transport_mutations=0",
                          ISO8601DateFormatter().string(from: strapStepCalibrationCaptureUntil))
        }
        let defaults = UserDefaults.standard
        lastHRVAnalysisAt = defaults.object(
            forKey: HRVCadenceDefaults.lastReadyAnalysisAt
        ) as? Date
        lastNormalWearHRVAnalysisAttemptAt = Self.readNormalWearHRVAnalysisAttemptDate(
            userDefaults: defaults
        )
        if let cachedSnapshot = Self.decodedReadyHRVSnapshot(
            defaults.data(forKey: HRVCadenceDefaults.readySnapshot),
            now: Date()
        ) {
            latestReadyHRVSnapshot = cachedSnapshot
            hrvSnapshot = cachedSnapshot
            hrv = Int(cachedSnapshot.rmssd.rounded())
            hrvQuality = cachedSnapshot.readinessMessage
            lastHRVAnalysisAt = max(lastHRVAnalysisAt ?? .distantPast,
                                    cachedSnapshot.analyzedAt)
        } else {
            defaults.removeObject(forKey: HRVCadenceDefaults.readySnapshot)
        }
#if DEBUG
        if debugForceUnknownStrapGeneration {
            strapModel = .unknown
            researchProbeGenerationGate = AtriaResearchProbe.GenerationGate()
            AtriaDebugLog("ATRIADBG strap_generation_fixture status=forced_unknown source=ui_fixture action=show_early_support_banner")
        }
#endif
        if arguments.contains("--atria-reset-capture-defaults") {
            resetProductionCaptureDefaultsForDebug()
        }
        if arguments.contains("--atria-full-protocol-mode") {
            UserDefaults.standard.set(false, forKey: LongWearDefaults.enabled)
            UserDefaults.standard.set(false, forKey: RadioDefaults.standardHROnly)
            longWearModeEnabled = false
            standardHROnlyMode = false
            standardHROnlyEnabled = false
            forceFreshScanOnRestore = true
        } else {
            bootstrapProductionCaptureDefaultsIfNeeded(arguments: arguments)
            migrateAutomaticLongWearDefaultIfNeeded(arguments: arguments)
            if Self.migrateAlwaysOnLongWearIfNeeded(defaults: defaults,
                                                    arguments: arguments) {
                longWearModeEnabled = true
                updateSessionPointCacheMode()
                AtriaDebugLog("ATRIADBG long_wear_mode status=migrated_always_on action=enabled reason=orphaned_legacy_toggle")
            }
            migrateStableR10TransportDefaultIfNeeded(arguments: arguments)
            migrateOfflineSyncDefaultIfNeeded(arguments: arguments)
            migrateProtectedR10HistoryInterlockIfNeeded()
            migrateFailedProprietaryBatteryRefreshIfNeeded()
            isolateRecentProtectedR10DisconnectStormIfNeeded()
            restoreInterruptedFullDrainLaunchIntentIfNeeded(defaults: defaults)
            // Drain-keeping continuity (2026-08-07): a persisted backlog must
            // restart the P3 maintenance backstop in THIS process too. After a
            // jetsam kill mid-catch-up, no gap-detection or re-arm lane may run
            // for tens of minutes, and the ticker used to stay down with it.
            startRangeLossBackfillMaintenanceTickerIfNeeded(
                reason: "launch_persisted_backlog"
            )
            let launchNow = Date()
            // A user-started workout is an explicit request for the strap's
            // motion stream.  Pure-HR fallback is the right fail-safe for
            // unattended all-day wear, but silently keeping that fallback
            // during an active workout guarantees that steps and movement are
            // absent.  Requalification is still bounded by the existing
            // physical-qualification credential and cooldown in
            // `prepareProtectedR10CleanOwnerAtLaunch`; this only authorizes the
            // already-safe launch-time attempt when durable workout intent is
            // present.
            let persistedMotionLeaseIsCurrent = (defaults.object(
                forKey: WorkoutMotionDefaults.ownerStartedAt
            ) as? Double).map {
                let age = launchNow.timeIntervalSince1970 - $0
                return age >= -AtriaPendingWorkoutIntent.bleContinuityFutureTolerance
                    && age <= AtriaPendingWorkoutIntent.bleContinuityMaxAge
            } ?? false
            let launchWorkoutIntent = AtriaPendingWorkoutIntentStore.shared
                .launchSnapshot()
            let explicitWorkoutIntentActive = launchWorkoutIntent.map {
                guard $0.endedAt == nil else { return false }
                let age = launchNow.timeIntervalSince($0.startedAt)
                return age >= -AtriaPendingWorkoutIntent.bleContinuityFutureTolerance
                    && age <= AtriaPendingWorkoutIntent.bleContinuityMaxAge
            } ?? false
            #if DEBUG
            let gate4StationaryQualificationRequested = arguments.contains(
                "--atria-gate4-auto-arm-stationary-motion"
            )
            #else
            let gate4StationaryQualificationRequested = false
            #endif
            // `ownerStartedAt` is shared by the safe all-day 0x69 motion bank
            // and manual workouts. Its presence alone must not authorize the
            // proprietary realtime-R10 cutover: doing so strands ordinary
            // all-day wear in protected_launch_pending while the bank
            // transport simultaneously owns motion. Only an explicit workout
            // intent (or the debug qualification drill) may trade the
            // physically proven pure-HR owner for that bounded experiment.
            let explicitWorkoutNeedsMotion = explicitWorkoutIntentActive
                || gate4StationaryQualificationRequested
            let persistedLeaseStartedAt = defaults.object(
                forKey: WorkoutMotionDefaults.ownerStartedAt
            ) as? Double
            let lastWorkoutRequalifyLease = defaults.object(
                forKey: Self.protectedR10WorkoutRequalifyLeaseKey
            ) as? Double
            let isNewWorkoutRequalifyLease =
                gate4StationaryQualificationRequested
                || (explicitWorkoutIntentActive
                    && (persistedLeaseStartedAt.map {
                        lastWorkoutRequalifyLease == nil
                            || abs($0 - lastWorkoutRequalifyLease!) > 0.001
                    } ?? false))
            AtriaDebugLog("ATRIADBG protected_r10 status=launch_requalify_eligibility pending_intent=%d persisted_lease=%d allow=%d owner=%@ state=%@",
                          explicitWorkoutIntentActive ? 1 : 0,
                          persistedMotionLeaseIsCurrent ? 1 : 0,
                          explicitWorkoutNeedsMotion ? 1 : 0,
                          protectedR10CleanOwner.rawValue,
                          protectedR10CleanOwnerState.rawValue)
            let cleanOwnerPreparation = Self.prepareProtectedR10CleanOwnerAtLaunch(
                defaults: defaults,
                allowFallbackRequalification: explicitWorkoutNeedsMotion,
                bypassCooldownForNewWorkoutLease: isNewWorkoutRequalifyLease,
                now: launchNow
            )
            if cleanOwnerPreparation == .requalifiedProtectedV9FromFallback,
               let persistedLeaseStartedAt {
                defaults.set(persistedLeaseStartedAt,
                             forKey: Self.protectedR10WorkoutRequalifyLeaseKey)
            }
            if cleanOwnerPreparation != .none {
                AtriaDebugLog("ATRIADBG protected_r10 status=clean_owner_launch preparation=%@ owner=%@ state=%@ action=select_unique_namespace_before_primary_central",
                              String(describing: cleanOwnerPreparation),
                              protectedR10CleanOwner.rawValue,
                              protectedR10CleanOwnerState.rawValue)
            }
            if arguments.contains("--atria-long-wear-mode") {
                UserDefaults.standard.set(true, forKey: CaptureDefaults.configured)
                UserDefaults.standard.set(true, forKey: LongWearDefaults.userSelected)
                UserDefaults.standard.set(true, forKey: LongWearDefaults.enabled)
                longWearModeEnabled = true
            }
        }
        if !arguments.contains("--atria-full-protocol-mode"),
           strapStepCalibrationCaptureUntil == nil,
           arguments.contains("--atria-standard-hr-only") || arguments.contains("--atria-long-wear-mode") {
            standardHROnlyMode = true
            standardHROnlyEnabled = true
            forceFreshScanOnRestore = true
        }
        if !arguments.contains("--atria-full-protocol-mode"),
           !arguments.contains("--atria-standard-hr-only"),
           !arguments.contains("--atria-long-wear-mode"),
           strapStepCalibrationCaptureUntil == nil {
            // The protected mode is not HR-only: it keeps 2A37 plus the
            // stream-5 R10 motion transport used by strap-native steps while
            // omitting the broader proprietary profile that failed physical
            // stability A/B testing.
            let storedMode = standardHROnlyMode
            let resolvedMode = Self.shouldUseStandardHROnlyAtNormalLaunch(
                userSelectedBatterySaver: defaults.bool(
                    forKey: RadioDefaults.standardHROnlyUserSelected
                ),
                persistedStandardHROnly: defaults.bool(
                    forKey: RadioDefaults.standardHROnly
                )
            )
            defaults.set(resolvedMode, forKey: RadioDefaults.standardHROnly)
            standardHROnlyMode = resolvedMode
            standardHROnlyEnabled = resolvedMode
            if storedMode != resolvedMode {
                forceFreshScanOnRestore = true
            }
            recordRadioMode(resolvedMode ? "protected_r10_minimal" : "full_protocol",
                            reason: resolvedMode
                                ? "stable_hr_r10_launch"
                                : "explicit_full_protocol_launch")
        }
        if motionHandshakeDiagnostic == nil,
           Self.shouldForceStableTransportForSuppressedR10(
                streamSuppressed: protectedR10StreamSuppressed,
                explicitFullProtocolDiagnostic:
                    arguments.contains("--atria-full-protocol-mode")
           ) {
            // Physical e3bc545 evidence: the durable pure-HR fallback and the
            // old explicit full-protocol preference coexisted. Every reconnect
            // delivered 9-14 valid HR samples, then timed out in ~13 seconds
            // because discovery expanded back into proprietary services. The
            // safety fuse must govern the effective runtime profile without
            // overwriting the user's stored preference; an explicit motion
            // requalification owns clearing the fuse later.
            if !standardHROnlyMode {
                forceFreshScanOnRestore = true
            }
            standardHROnlyMode = true
            standardHROnlyEnabled = true
            recordRadioMode(
                "pure_hr_fallback",
                reason: "r10_stream_suppressed_transport_fuse"
            )
        }
        if let diagnostic = motionHandshakeDiagnostic {
            // This is an isolated transport experiment, not a persisted radio
            // preference. Normal long-wear supervisors, offline recovery and
            // production characteristic discovery must remain out of the run.
            longWearModeEnabled = false
            standardHROnlyMode = false
            standardHROnlyEnabled = false
            forceFreshScanOnRestore = false
            let now = Date().timeIntervalSince1970
            defaults.set(diagnostic.runID, forKey: "atria.motionHandshake.runID")
            defaults.set("configured", forKey: "atria.motionHandshake.status")
            defaults.set(now, forKey: "atria.motionHandshake.configuredAt")
            defaults.set(diagnostic.addHRDelay, forKey: "atria.motionHandshake.addHRDelay")
            defaults.set(diagnostic.sendSingleR10Activation,
                         forKey: "atria.motionHandshake.singleR10ActivationConsented")
            defaults.set(diagnostic.useResponseEventDataProfile,
                         forKey: "atria.motionHandshake.responseEventDataProfileConsented")
            defaults.set(diagnostic.sendR10IMUSequence,
                         forKey: "atria.motionHandshake.r10IMUSequenceConsented")
            defaults.set(diagnostic.restoreIdentifier, forKey: "atria.motionHandshake.restoreIdentifier")
            AtriaDebugLog("ATRIADBG motion_handshake status=configured run=%@ restore=%@ add_hr_after_s=%.1f single_3f01=%d response_event_data=%d r10_imu_sequence=%d isolation=diagnostic_profile_then_hr_no_offline_no_battery",
                          diagnostic.runID,
                          diagnostic.restoreIdentifier,
                          diagnostic.addHRDelay,
                          diagnostic.sendSingleR10Activation ? 1 : 0,
                          diagnostic.useResponseEventDataProfile ? 1 : 0,
                          diagnostic.sendR10IMUSequence ? 1 : 0)
        }
        reconcileOrphanedBackgroundHistoryLeaseAtLaunch()
        if motionHandshakeDiagnostic == nil {
            scheduleStaleArmedRangeLossBackfillReconciliation(reason: "ble_manager_init")
        }
        hydrateCachedBatteryStateIfFresh()
        updateSessionPointCacheMode()
        logActiveMotionIMUCheckPlanIfRequested(arguments: arguments)
        powerThermalGovernor.onChange = { [weak self] mode in
            guard let self else { return }
            AtriaDebugLog("ATRIADBG power_thermal_governor mode=%@ multiplier=%.1f low_power=%d thermal=%@",
                  mode.rawValue,
                  self.effectiveThermalCadenceMultiplier,
                  ProcessInfo.processInfo.isLowPowerModeEnabled ? 1 : 0,
                  Self.thermalStateLabel(ProcessInfo.processInfo.thermalState))
            if mode == .nominal || mode == .fair {
                // Raw power eligibility is rechecked here because the
                // governor's effective mode folds Low Power Mode into
                // `.serious`. Only a genuinely cool, non-LPM edge releases the
                // bounded same-link admission deadline; the next accepted-HR
                // typed selector (or natural checkpoint) owns the retry.
                if !Self
                    .shouldParkConnectedMotionBankHistoryForPowerPressure(
                        thermalState: ProcessInfo.processInfo.thermalState,
                        lowPowerModeEnabled:
                            ProcessInfo.processInfo.isLowPowerModeEnabled
                    ) {
                    self.connectedMotionBankHistoryAdmissionRetryNotBefore = nil
                }
                self.scheduleStaleArmedRangeLossBackfillReconciliation(reason: "thermal_pressure_recovered")
                self.scheduleRangeLossBackfillIfNeeded(reason: "thermal_pressure_recovered")
                _ = self.offerConnectedRawCatchUpPublicationYieldIfNeeded(
                    reason: "power_thermal_governor_ready"
                )
            }
        }
        powerThermalGovernor.onThermalStateChange = { [weak self] state in
            guard let self,
                  self.connectedRawHistoryCatchUpContinuationPending else {
                return
            }
            // During a publication lease whose one bounded offer is still in
            // flight, a fair/nominal edge may reoffer only after that task exits.
            // Outside that lease, preserve the prior raw-edge behavior: the
            // next accepted 2A37 beat still mints the exact transport token.
            if self.connectedRawHistoryCatchUpPublicationYield != nil {
                if state == .nominal || state == .fair {
                    _ = self.offerConnectedRawCatchUpPublicationYieldIfNeeded(
                        reason: "raw_thermal_ready"
                    )
                }
                return
            }
            if state != .critical {
                self.connectedRawHistoryCatchUpEvaluationNotBefore = nil
            }
        }
        if motionHandshakeDiagnostic == nil {
            let obsoleteRestoreIdentifiers = [
                "com.adidshaft.atria.ble-central",
                "com.adidshaft.atria.ble-central-v2",
                "com.adidshaft.atria.ble-central-v3",
            ]
            legacyCentralCleaners = obsoleteRestoreIdentifiers.map { identifier in
                AtriaLegacyBLECentralCleaner(
                    restoreIdentifier: identifier
                ) { [weak self] cleanerID in
                    self?.legacyCentralCleaners.removeAll {
                        $0.id == cleanerID
                    }
                }
            }
        }
        // Begin journal recovery before CoreBluetooth can deliver restored or
        // newly connected packets. HR/realtime callbacks are held in the same
        // FIFO used by session boundaries until this recovery resolves.
        restoreActiveSessionJournalIfNeeded(reason: "ble_manager_init")
        // Hold the private delegate lane until the exact manager object is in
        // the identity fence. Without this tiny construction barrier an
        // immediate state-restoration callback could beat `install` and be
        // discarded as though it came from a retired manager.
        let initialBaseRestoreIdentifier = baseCentralRestoreIdentifier
        let initialRestoreIdentifier = centralRestoreIdentifier
        installedCentralBaseIdentifier = initialBaseRestoreIdentifier
        installedCentralRestoreIdentifier = initialRestoreIdentifier
        let delegateQueue = centralDelegateQueue
        delegateQueue?.suspend()
        central = CBCentralManager(delegate: self,
                                   queue: delegateQueue,
                                   options: [
                                       CBCentralManagerOptionRestoreIdentifierKey:
                                           initialRestoreIdentifier,
                                       CBCentralManagerOptionShowPowerAlertKey: true
        ])
        centralEventFence.install(central)
        delegateQueue?.resume()
        #if DEBUG
        // Physical Gate 4 seam: arm the same bounded calibration-owned motion
        // lease as the in-app developer control without depending on the Home
        // UI or iPhone Mirroring becoming active. It remains debug-only and
        // self-expires after three minutes.
        if arguments.contains("--atria-gate4-auto-arm-stationary-motion") {
            Task { @MainActor [weak self] in
                try? await Task.sleep(for: .seconds(2))
                guard let self, !Task.isCancelled else { return }
                let until = Date().addingTimeInterval(3 * 60)
                self.armStepCalibrationCapture(
                    until: until,
                    allowsPreparationReconnect: false
                )
                UserDefaults.standard.set(
                    Date().timeIntervalSince1970,
                    forKey: "atria.gate4.stationaryAutoArm.startedAt"
                )
                UserDefaults.standard.set(
                    until.timeIntervalSince1970,
                    forKey: "atria.gate4.stationaryAutoArm.expiresAt"
                )
                AtriaDebugLog(
                    "ATRIADBG gate4_stationary_auto_arm status=armed duration_s=180 action=debug_only_same_calibration_lease"
                )
            }
        }
        #endif
        restoreStrapStepLedgerAtLaunch()
        // A CoreBluetooth restoration relaunch is CPU-budgeted background
        // time; the crash-resume re-verification below re-hashes the sealed
        // five-artifact set and has produced cpu_resource_fatal terminations
        // when it consumed that budget. The pending job is durable: it is
        // reconciled again before the next history generation arms, or on the
        // next genuinely active launch.
        if UIApplication.shared.applicationState == .active {
            _ = reconcileConsumedHistoricalTerminalPublicationIfNeeded(
                reason: "ble_manager_init"
            )
        }
    }

#if DEBUG
    /// Reconciles only app-owned recovery bookkeeping after an independently
    /// completed sacrificial fast drain. The launch exits before constructing
    /// CoreBluetooth, and this function has no transport object or command
    /// path. A byte-for-byte, fail-closed receipt proof is mandatory before any
    /// old gap or draining authority is retired.
    private func reconcileVerifiedSacrificialFastDrainIfRequested(
        arguments: [String]
    ) {
        let mode =
            AtriaWhoop4SacrificialFastDrainReceiptVerifier
                .reconciliationModeArgument
        guard arguments.contains(mode) else { return }
        do {
            let runID =
                try AtriaWhoop4SacrificialFastDrainReceiptVerifier
                    .reconciliationRunID(arguments: arguments)
            let documentDirectory = FileManager.default.urls(
                for: .documentDirectory,
                in: .userDomainMask
            )[0]
            let receiptURL =
                AtriaWhoop4SacrificialFastDrainReceiptVerifier
                    .receiptURL(
                        documentDirectory: documentDirectory,
                        runID: runID
                    )
            let proof =
                try AtriaWhoop4SacrificialFastDrainReceiptVerifier
                    .verify(
                        jsonl: Data(contentsOf: receiptURL),
                        expectedRunID: runID
                    )
            // Retire the obsolete draining authority first. If the following
            // ledger rewrite fails or the process exits, the exact gap rows
            // remain fail-closed and a later bookkeeping-only launch can retry
            // them. Performing these writes in the opposite order could erase
            // the only gap record before a throwing authority mutation.
            let authorityRetired =
                try historicalFullDrainCoverageStore
                    .abandonDrainingAuthorityAfterVerifiedStrapHistoryReset(
                        completedAtUnix:
                            proof.completedAt.timeIntervalSince1970
                    )
            guard let retirement = AtriaHistoricalGapLedger
                .retireWindowsBeforeVerifiedStrapHistoryReset(
                    completedAt: proof.completedAt
                ) else {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_fast_drain_reconcile status=rejected reason=gap_ledger_retirement_failed run=%@ ble_commands=0 local_metric_mutation=0 pairing_mutation=0",
                    runID.uuidString
                )
                return
            }
            let defaults = UserDefaults.standard
            if retirement.remainingWindows == 0 {
                defaults.set(
                    false,
                    forKey: OfflineSyncDefaults.rangeLossBackfillPending
                )
                defaults.removeObject(
                    forKey: OfflineSyncDefaults.rangeLossBackfillReason
                )
                defaults.removeObject(
                    forKey: OfflineSyncDefaults.recoveryWindowStart
                )
                defaults.removeObject(
                    forKey: OfflineSyncDefaults.recoveryWindowEnd
                )
                assignIfChanged(\.rangeLossBackfillPending, false)
            }
            AtriaDebugLog(
                "ATRIADBG sacrificial_fast_drain_reconcile status=verified run=%@ completed_at=%.3f pre_pending=%u post_pending=%u acknowledged_chunks=%d discarded_records=%d retired_pre_drain_gaps=%d remaining_gaps=%d retired_pre_drain_draining_authority=%d pending_flag_cleared=%d ble_commands=0 metric_archive_mutation=0 session_mutation=0 workout_mutation=0 sleep_mutation=0 pairing_mutation=0",
                proof.runID.uuidString,
                proof.completedAt.timeIntervalSince1970,
                proof.preflightPendingRecords,
                proof.postflightPendingRecords,
                proof.acknowledgedChunks,
                proof.historicalRecordsDiscarded,
                retirement.retiredWindows,
                retirement.remainingWindows,
                authorityRetired ? 1 : 0,
                retirement.remainingWindows == 0 ? 1 : 0
            )
        } catch {
            AtriaDebugLog(
                "ATRIADBG sacrificial_fast_drain_reconcile status=rejected reason=%@ ble_commands=0 local_metric_mutation=0 session_mutation=0 workout_mutation=0 sleep_mutation=0 pairing_mutation=0",
                String(describing: error)
            )
        }
    }

    /// Explicit attended cleanup after a separately completed sacrificial
    /// history reset. The receipt verifier is pure and fail-closed; no state is
    /// changed unless it proves the exact nine-byte command, logical response,
    /// and postflight cursor collapse for the supplied run ID.
    private func reconcileVerifiedSacrificialHistoryTrimIfRequested(
        arguments: [String]
    ) {
        let mode = "--atria-reconcile-verified-sacrificial-history-trim"
        guard arguments.contains(mode) else { return }
        let runIDIndexes = arguments.indices.filter {
            arguments[$0]
                == AtriaWhoop4SacrificialHistoryTrimPolicy.runIDArgument
        }
        guard runIDIndexes.count == 1 else {
            AtriaDebugLog(
                "ATRIADBG sacrificial_history_trim_reconcile status=rejected reason=run_id_count_%d local_metric_mutation=0 pairing_mutation=0",
                runIDIndexes.count
            )
            return
        }
        let valueIndex = arguments.index(after: runIDIndexes[0])
        guard valueIndex < arguments.endIndex,
              let runID = UUID(uuidString: arguments[valueIndex]) else {
            AtriaDebugLog(
                "ATRIADBG sacrificial_history_trim_reconcile status=rejected reason=invalid_run_id local_metric_mutation=0 pairing_mutation=0"
            )
            return
        }
        let receiptURL = FileManager.default.urls(
            for: .documentDirectory,
            in: .userDomainMask
        )[0]
            .appendingPathComponent(
                "atria-sacrificial-history-trim",
                isDirectory: true
            )
            .appendingPathComponent(
                "read-only-history-\(runID.uuidString).jsonl"
            )
        do {
            let proof =
                try AtriaWhoop4SacrificialHistoryTrimReceiptVerifier.verify(
                    jsonl: Data(contentsOf: receiptURL),
                    expectedRunID: runID
                )
            // Authority-first keeps the gap ledger as the recoverable source
            // of truth if either durable mutation fails between the two
            // stores. Repeating this reconciliation is idempotent.
            let authorityRetired =
                try historicalFullDrainCoverageStore
                    .abandonDrainingAuthorityAfterVerifiedStrapHistoryReset(
                        completedAtUnix:
                            proof.completedAt.timeIntervalSince1970
                    )
            guard let retirement = AtriaHistoricalGapLedger
                .retireWindowsBeforeVerifiedStrapHistoryReset(
                    completedAt: proof.completedAt
                ) else {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_history_trim_reconcile status=rejected reason=gap_ledger_retirement_failed run=%@ local_metric_mutation=0 pairing_mutation=0",
                    runID.uuidString
                )
                return
            }
            let defaults = UserDefaults.standard
            if retirement.remainingWindows == 0 {
                defaults.set(
                    false,
                    forKey: OfflineSyncDefaults.rangeLossBackfillPending
                )
                defaults.removeObject(
                    forKey: OfflineSyncDefaults.rangeLossBackfillReason
                )
                defaults.removeObject(
                    forKey: OfflineSyncDefaults.recoveryWindowStart
                )
                defaults.removeObject(
                    forKey: OfflineSyncDefaults.recoveryWindowEnd
                )
                assignIfChanged(\.rangeLossBackfillPending, false)
            }
            AtriaDebugLog(
                "ATRIADBG sacrificial_history_trim_reconcile status=verified run=%@ completed_at=%.3f pre_pending=%u post_pending=%u retired_pre_reset_gaps=%d remaining_gaps=%d retired_pre_reset_draining_authority=%d metric_archive_mutation=0 session_mutation=0 workout_mutation=0 pairing_mutation=0",
                proof.runID.uuidString,
                proof.completedAt.timeIntervalSince1970,
                proof.preflightPendingRecords,
                proof.postflightPendingRecords,
                retirement.retiredWindows,
                retirement.remainingWindows,
                authorityRetired ? 1 : 0
            )
        } catch {
            AtriaDebugLog(
                "ATRIADBG sacrificial_history_trim_reconcile status=rejected reason=%@ run=%@ local_metric_mutation=0 pairing_mutation=0",
                String(describing: error),
                runID.uuidString
            )
        }
    }
#endif

    private func applyEarlyHistoricalLaunchConfiguration(arguments: [String]) {
#if DEBUG
        reconcileVerifiedSacrificialHistoryTrimIfRequested(
            arguments: arguments
        )
        if arguments.contains(
            AtriaWhoop4SacrificialFastDrainPolicy.modeArgument
        ) {
            do {
                let authorization =
                    try AtriaWhoop4SacrificialFastDrainPolicy
                        .authorizeLaunch(arguments: arguments)
                let consumed = UserDefaults.standard.string(
                    forKey: Self.sacrificialFastDrainConsumedRunIDKey
                )
                let activeRoot = UserDefaults.standard.string(
                    forKey: Self.sacrificialFastDrainActiveRootRunIDKey
                )
                guard AtriaWhoop4SacrificialFastDrainPolicy.admitsRootLaunch(
                    authorization: authorization,
                    consumedRunID: consumed,
                    activeRootRunID: activeRoot
                ) else {
                    AtriaDebugLog(
                        "ATRIADBG sacrificial_fast_drain status=rejected reason=root_authorization_unavailable run=%@ consumed=%@ active_root=%@ commands=0",
                        authorization.runID.uuidString,
                        consumed ?? "none",
                        activeRoot ?? "none"
                    )
                    return
                }
                sacrificialFastDrainRequested = true
                sacrificialFastDrainRunID = authorization.runID
                sacrificialFastDrainSession = .init(
                    authorization: authorization
                )
                func evidenceArgument(after flag: String) -> UInt32? {
                    guard let index = arguments.firstIndex(of: flag) else {
                        return nil
                    }
                    let valueIndex = arguments.index(after: index)
                    guard arguments.indices.contains(valueIndex) else {
                        return nil
                    }
                    return UInt32(arguments[valueIndex])
                }
                let evidenceStart = evidenceArgument(
                    after: "--atria-history-discard-evidence-start"
                )
                let evidenceEnd = evidenceArgument(
                    after: "--atria-history-discard-evidence-end"
                )
                if let evidenceStart,
                   let evidenceEnd,
                   AtriaBLEReadOnlyExactRangeCapturePolicy.payload(
                    startUnix: evidenceStart,
                    endUnix: evidenceEnd
                   ) != nil {
                    sacrificialFastDrainEvidenceStartUnix = evidenceStart
                    sacrificialFastDrainEvidenceEndUnix = evidenceEnd
                }
                readOnlyHistoryCaptureRequested = true
                historyOnlyProbeEnabled = true
                historySkipDataRangeRequest = true
                _ = historyTransportPhaseFence.activate(generation: 0)
                realtimeStartRetries = 0
                AtriaDebugLog(
                    "ATRIADBG sacrificial_fast_drain status=configured run=%@ trace=2200,1600,17<strap_token>...,2200 fabricated_ack=0 local_data_mutation=0",
                    authorization.runID.uuidString
                )
            } catch {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_fast_drain status=rejected reason=%@ commands=0",
                    String(describing: error)
                )
            }
        }
        if arguments.contains(
            AtriaWhoop4SacrificialHistoryTrimPolicy.modeArgument
        ) {
            do {
                let authorization =
                    try AtriaWhoop4SacrificialHistoryTrimPolicy
                        .authorizeLaunch(arguments: arguments)
                let consumed = UserDefaults.standard.string(
                    forKey: Self.oneShotHistoryTrimConsumedRunIDKey
                )
                guard consumed != authorization.runID.uuidString else {
                    AtriaDebugLog(
                        "ATRIADBG sacrificial_history_trim status=rejected reason=run_id_already_consumed run=%@ commands=0",
                        authorization.runID.uuidString
                    )
                    return
                }
                oneShotHistoryTrimRequested = true
                oneShotHistoryTrimRunID = authorization.runID
                oneShotHistoryTrimPhase = .preflight
                oneShotHistoryTrimIssued = false
                readOnlyHistoryCaptureRequested = true
                historyOnlyProbeEnabled = true
                historySkipDataRangeRequest = true
                _ = historyTransportPhaseFence.activate(generation: 0)
                realtimeStartRetries = 0
                AtriaDebugLog(
                    "ATRIADBG sacrificial_history_trim status=configured run=%@ trace=2200,19fefefefefefefefe00,2200 retry=0 local_data_mutation=0",
                    authorization.runID.uuidString
                )
            } catch {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_history_trim status=rejected reason=%@ commands=0",
                    String(describing: error)
                )
            }
        }
#endif
        if arguments.contains("--atria-gate2-full-drain-proof") {
            let gapID: UUID? = {
                guard let index = arguments.firstIndex(
                    of: "--atria-gate2-full-drain-gap-id"
                ) else { return nil }
                let valueIndex = arguments.index(after: index)
                guard arguments.indices.contains(valueIndex) else { return nil }
                return UUID(uuidString: arguments[valueIndex])
            }()
            gate2FullDrainRequestedGapID = gapID
            gate2FullDrainProofEnabled = gapID != nil
            AtriaDebugLog(
                "ATRIADBG gate2_full_drain status=%@ gap=%@ selector=0 exact_16_payload=0 automatic=0 action=%@",
                gapID == nil ? "rejected_missing_gap_id" : "configured",
                gapID?.uuidString ?? "none",
                gapID == nil
                    ? "no_transport"
                    : "attended_verified_page_transport_only"
            )
        }
        if arguments.contains("--atria-read-only-clock-probe") {
            readOnlyClockProbeRequested = true
            historyOnlyProbeEnabled = true
            historySkipDataRangeRequest = true
            _ = historyTransportPhaseFence.activate(generation: 0)
            realtimeStartRetries = 0
            AtriaDebugLog(
                "ATRIADBG read_only_clock status=configured allowlist=0b00 clock_write=0 history_command=0 ack=0 mode_change=0"
            )
        }
        if arguments.contains("--atria-read-only-history-capture")
            || arguments.contains("--atria-read-only-exact-range-capture") {
            readOnlyHistoryCaptureRequested = true
            readOnlyExactRangeCaptureRequested = arguments.contains(
                "--atria-read-only-exact-range-capture"
            )
            if readOnlyExactRangeCaptureRequested {
                func argumentUInt32(after flag: String) -> UInt32? {
                    guard let index = arguments.firstIndex(of: flag) else {
                        return nil
                    }
                    let valueIndex = arguments.index(after: index)
                    guard arguments.indices.contains(valueIndex) else {
                        return nil
                    }
                    return UInt32(arguments[valueIndex])
                }
                if let start = argumentUInt32(
                    after: "--atria-read-only-exact-range-start"
                ),
                   let end = argumentUInt32(
                    after: "--atria-read-only-exact-range-end"
                   ),
                   let payload = AtriaBLEReadOnlyExactRangeCapturePolicy.payload(
                    startUnix: start,
                    endUnix: end
                   ) {
                    readOnlyExactRangeUsesExplicitArguments = true
                    readOnlyExactRangeStartUnix = start
                    readOnlyExactRangeEndUnix = end
                    readOnlyExactRangePayload = payload
                }
            }
            if readOnlyExactRangeCaptureRequested,
               let index = arguments.firstIndex(
                    of: "--atria-read-only-exact-range-gap-id"
               ) {
                let valueIndex = arguments.index(after: index)
                if arguments.indices.contains(valueIndex) {
                    readOnlyExactRangeRequestedGapID = UUID(
                        uuidString: arguments[valueIndex]
                    )
                }
            }
            historyOnlyProbeEnabled = true
            // Select only the physically verified RX + stream-5 notification
            // profile. The dedicated runner still sends 22/00 itself.
            historySkipDataRangeRequest = true
            _ = historyTransportPhaseFence.activate(generation: 0)
            realtimeStartRetries = 0
            AtriaDebugLog("ATRIADBG readOnlyHistory status=configured mode=%@ allowlist=%@ ack=0 clock_write=0 seek=0 realtime_stop=0 mode_change=0",
                          readOnlyExactRangeCaptureRequested ? "exact_range" : "full_drain_observation",
                          readOnlyExactRangeCaptureRequested
                              ? "2200,16<start_le32+end_le32>,1400"
                              : "2200,1600,1400")
        }
        if arguments.contains("--atria-history-clock-handshake") || arguments.contains("--atria-history-clock-sync") {
            historyClockSyncEnabled = true
        }
        if arguments.contains("--atria-history-skip-range") {
            historySkipDataRangeRequest = true
        }
        if let initIndex = arguments.firstIndex(of: "--atria-history-init-sweep"),
           arguments.indices.contains(arguments.index(after: initIndex)) {
            historyInitSweepCommands = arguments[arguments.index(after: initIndex)]
                .split(separator: ",")
                .compactMap { Self.parseHexBytes(String($0)) }
                .filter { !$0.isEmpty }
        }
        if let modeIndex = arguments.firstIndex(of: "--atria-probe-command-mode"),
           arguments.indices.contains(arguments.index(after: modeIndex)) {
            let mode = arguments[arguments.index(after: modeIndex)]
            if mode == CommandWriteMode.withResponse.rawValue {
                probeCommandMode = .withResponse
            } else if mode == CommandWriteMode.withoutResponse.rawValue {
                probeCommandMode = .withoutResponse
            }
        }
        guard arguments.contains("--atria-history-only-probe") else { return }
        historyOnlyProbeEnabled = true
        _ = historyTransportPhaseFence.activate(
            generation: offlineHistoricalSyncGeneration
        )
        realtimeStartRetries = 0
        AtriaDebugLog("ATRIADBG realtimeConfig history_only_probe=1 phase=early realtime_start=skipped cmd22=%d init_sweep=%d mode=%@",
              historySkipDataRangeRequest ? 0 : 1,
              historyInitSweepCommands.isEmpty ? 0 : 1,
              probeCommandMode.rawValue)
    }

    private static func thermalStateLabel(_ state: ProcessInfo.ThermalState) -> String {
        switch state {
        case .nominal:
            return "nominal"
        case .fair:
            return "fair"
        case .serious:
            return "serious"
        case .critical:
            return "critical"
        @unknown default:
            return "unknown"
        }
    }

    private func hydrateCachedBatteryStateIfFresh(
        maxAge: TimeInterval = activeBatterySubscriptionBaselineMaximumAge
    ) {
        recentReconnectBatteryBaselineProjectionPublished = false
        batteryBaselineValidationStartedAt = Date()
        let invalidated = Self.invalidateImplausibleCachedBatteryTransitionIfNeeded() ||
            Self.invalidateUnverifiedCachedBatterySentinelIfNeeded()
        if invalidated {
            WidgetSnapshotPublisher.invalidateBatteryProjection()
            LocalNotificationScheduler.invalidateDisputedBatterySideEffects(
                reason: "launch_disputed_battery_transition"
            )
        }
        let defaults = UserDefaults.standard
        // `requiresFreshConfirmation` survives a relaunch by design. It must
        // block the persisted percentage from becoming fresh/live truth, but
        // it must not prevent hydration from retaining a previously accepted
        // mid-range value as an explicitly aged reconnect baseline. Otherwise
        // every launch turns a truthful 18% into "Battery pending" until the
        // change-driven 2A19 characteristic happens to emit a new integer.
        let cached = Self.cachedBattery(
            maxAge: maxAge,
            permitPendingReconnectBaseline: true
        )
        // A notification lease belongs to the process/connection epoch that
        // created it. It may help select a comparison baseline above, but it
        // must be revoked before this launch marks that baseline pending.
        defaults.removeObject(forKey: BatteryDefaults.notificationLeaseAt)
        defaults.set(true, forKey: BatteryDefaults.requiresFreshConfirmation)
        if cached.usable, !Self.isBatterySentinel(cached.level) {
            // Preserve a recent credible mid-range value while fresh live reads
            // are being corroborated. It is explicitly marked cached and never
            // refreshes its timestamp, so normal freshness rules still expire it.
            batteryLevel = cached.level
            displayedBatteryLevelIsCached = true
            batteryReadingIsRecentBaseline = true
            let acceptedAt = defaults.object(forKey: BatteryDefaults.at) as? Double
            lastAcceptedBatteryLevelAt = acceptedAt.map(Date.init(timeIntervalSince1970:))
            defaults.set(cached.level, forKey: BatteryDefaults.credibleLevel)
            if let acceptedAt { defaults.set(acceptedAt, forKey: BatteryDefaults.credibleAt) }
        } else if let credible = defaults.object(forKey: BatteryDefaults.credibleLevel) as? Int,
                  let credibleAt = defaults.object(forKey: BatteryDefaults.credibleAt) as? Double,
                  !Self.isBatterySentinel(credible),
                  Date().timeIntervalSince1970 - credibleAt >= 0,
                  Date().timeIntervalSince1970 - credibleAt <= maxAge {
            batteryLevel = credible
            displayedBatteryLevelIsCached = true
            batteryReadingIsRecentBaseline = true
            lastAcceptedBatteryLevelAt = Date(timeIntervalSince1970: credibleAt)
        } else {
            batteryLevel = -1
            displayedBatteryLevelIsCached = false
            batteryReadingIsRecentBaseline = false
            lastAcceptedBatteryLevelAt = nil
        }
        // A persisted percentage is useful only as a comparison baseline. It
        // must not remain visible in widgets while the new connection is still
        // proving a fresh level-bearing packet series.
        WidgetSnapshotPublisher.invalidateBatteryProjection()
        batteryChargeStatus = .levelOnly
        batteryIsCharging = false
        batteryRecentlyDropping = false
    }

    private func promoteReconnectBatteryBaselineIfSafe(
        now: Date,
        heartRateReceivedAt: Date? = nil,
        validatedR10ReceivedAt: Date? = nil,
        reason: String
    ) {
        let defaults = UserDefaults.standard
        let connectionStartedAt = connectedAt ?? batteryBaselineValidationStartedAt
        let currentConnectionHasHeartRate = heartRateReceivedAt.map {
            $0 >= connectionStartedAt
        } ?? false
        let currentConnectionHasValidatedR10 = validatedR10ReceivedAt.map {
            $0 >= connectionStartedAt
        } ?? false
        let notificationTransportActive = batteryNotificationTransportIsActive(
            now: now,
            defaults: defaults
        )
        guard Self.shouldPromoteReconnectBatteryBaseline(
            level: batteryLevel,
            acceptedAt: lastAcceptedBatteryLevelAt,
            source: defaults.string(forKey: BatteryDefaults.source) ?? "none",
            displayedIsCached: displayedBatteryLevelIsCached,
            requiresFreshConfirmation: defaults.bool(forKey: BatteryDefaults.requiresFreshConfirmation),
            notificationActive: notificationTransportActive,
            linkConnected: peripheral?.state == .connected && status == .connected,
            currentConnectionHasHeartRate: currentConnectionHasHeartRate,
            currentConnectionHasValidatedR10: currentConnectionHasValidatedR10,
            hasPendingDisputedReading: pendingBatteryDropCandidate != nil,
            currentNotificationEpochHadRejectedCallback: batteryNotificationEpochHadRejectedCallback,
            now: now
        ) else { return }

        displayedBatteryLevelIsCached = false
        batteryReadingIsRecentBaseline = true
        defaults.removeObject(forKey: BatteryDefaults.requiresFreshConfirmation)
        defaults.set(now.timeIntervalSince1970,
                     forKey: BatteryDefaults.notificationLeaseAt)
        // The percentage is now displayable only as an explicitly aged recent
        // baseline under the active change-driven lease. Charge state remains
        // level-only until an independent rise/event proves Charging or a
        // decline proves Not Charging.
        assignIfChanged(\.batteryIsCharging, false)
        assignIfChanged(\.batteryChargeStatus, .levelOnly)
        assignIfChanged(\.batteryRecentlyDropping, false)
        let persistedChargeStatus = BatteryChargeStatus(
            rawValue: defaults.string(forKey: BatteryDefaults.chargeStatus) ?? ""
        ) ?? .levelOnly
        let persistedChargeAt = (defaults.object(forKey: BatteryDefaults.chargeAt) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        if !Self.shouldRetainPersistedChargingAcrossReconnect(
            persistedStatus: persistedChargeStatus,
            persistedAt: persistedChargeAt,
            batteryRecentlyDropping: batteryRecentlyDropping,
            now: now
        ) {
            Self.persistBatteryChargeStatusProjection(.levelOnly,
                                                      source: "reconnect_2A19_baseline",
                                                      defaults: defaults,
                                                      now: now)
        }
        batteryProjectionRevision &+= 1
        AtriaDebugLog("ATRIADBG battery level=%d source=%@ status=accepted reason=%@ detail=recent_midrange_active_2a19_and_current_connection_hr accepted_age_s=%.1f",
                      batteryLevel,
                      defaults.string(forKey: BatteryDefaults.source) ?? "none",
                      reason,
                      lastAcceptedBatteryLevelAt.map { now.timeIntervalSince($0) } ?? -1)
    }

    /// A validated mid-range baseline is allowed to become displayable as
    /// "Recent" once live HR proves that the same saved strap is connected.
    /// Because that proof arrives on the HR channel, it needs a one-shot battery
    /// projection invalidation even though the percentage itself did not change.
    private func publishRecentReconnectBatteryBaselineIfNeeded(now: Date) {
        guard !recentReconnectBatteryBaselineProjectionPublished,
              recentReconnectBatteryBaselineIsDisplayable(now: now) else { return }
        recentReconnectBatteryBaselineProjectionPublished = true
        batteryProjectionRevision &+= 1
        AtriaDebugLog("ATRIADBG battery status=recent_baseline_published level=%d reason=accepted_hr_current_connection",
                      batteryLevel)
    }

    private func revokeBatteryNotificationLease(reason: String, now: Date = Date()) {
        let defaults = UserDefaults.standard
        defaults.removeObject(forKey: BatteryDefaults.notificationLeaseAt)
        defaults.set(true, forKey: BatteryDefaults.requiresFreshConfirmation)
        displayedBatteryLevelIsCached = (11...99).contains(batteryLevel)
        recentReconnectBatteryBaselineProjectionPublished = false
        batteryReadingIsRecentBaseline = displayedBatteryLevelIsCached
        assignIfChanged(\.batteryIsCharging, false)
        assignIfChanged(\.batteryChargeStatus, .levelOnly)
        assignIfChanged(\.batteryRecentlyDropping, false)
        Self.persistBatteryChargeStatusProjection(.levelOnly,
                                                  source: "notification_lease_revoked",
                                                  defaults: defaults,
                                                  now: now)
        batteryProjectionRevision &+= 1
        AtriaDebugLog("ATRIADBG battery status=pending reason=%@ detail=notification_lease_revoked level=%d",
                      reason,
                      batteryLevel)
    }

    /// A 2A19 value callback error invalidates the subscription epoch even when
    /// CoreBluetooth leaves `isNotifying` true. Preserve the last packet-fresh
    /// accepted percentage and its original timestamp, but revoke all transport
    /// lease proof and force a CCCD off/on cycle before another lease can exist.
    private func recoverBatteryNotificationAfterValueError(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        errorDescription: String,
        receivedAt: Date
    ) {
        guard Self.shouldAllowAncillaryGATTRefresh(
            historyTransportOwnsLink: recoveredDataProjectionDeferralIsActive
        ) else {
            batteryNotificationRecoveryTask?.cancel()
            batteryNotificationRecoveryTask = nil
            pendingNotifyReenableUUIDs.remove(characteristic.uuid)
            AtriaDebugLog("ATRIADBG battery source=2A19 status=recovery_deferred reason=history_transport_owned action=no_cccd_or_discovery")
            return
        }
        let defaults = UserDefaults.standard
        batteryNotificationEpochHadRejectedCallback = true
        defaults.set(receivedAt.timeIntervalSince1970,
                     forKey: BatteryDefaults.notificationLastCallbackAt)
        defaults.set(errorDescription,
                     forKey: BatteryDefaults.notificationLastError)
        defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
        revokeBatteryNotificationLease(reason: "2A19_value_callback_error",
                                       now: receivedAt)

        guard peripheral.state == .connected,
              status == .connected,
              characteristic.properties.contains(.notify)
                || characteristic.properties.contains(.indicate) else {
            peripheral.discoverServices([Self.UUIDs.batteryService])
            return
        }
        batteryLevelCharacteristic = characteristic
        batteryNotificationRecoveryTask?.cancel()
        batteryNotificationRecoveryTask = nil
        batteryNotificationRecoveryAttempt = 0
        defaults.set(receivedAt.timeIntervalSince1970,
                     forKey: BatteryDefaults.notificationRequestedAt)
        if characteristic.isNotifying {
            pendingNotifyReenableUUIDs.insert(characteristic.uuid)
            peripheral.setNotifyValue(false, for: characteristic)
            armBatteryNotificationRecoveryWatchdog(
                peripheral: peripheral,
                characteristic: characteristic,
                reason: "value_error_disable"
            )
            AtriaDebugLog("ATRIADBG battery source=2A19 status=subscription_invalidated action=disable_then_resubscribe")
        } else {
            peripheral.setNotifyValue(true, for: characteristic)
            armBatteryNotificationRecoveryWatchdog(
                peripheral: peripheral,
                characteristic: characteristic,
                reason: "value_error_enable"
            )
            AtriaDebugLog("ATRIADBG battery source=2A19 status=subscription_invalidated action=resubscribe")
        }
    }

    /// Every requested CCCD transition gets a bounded watchdog because
    /// CoreBluetooth is allowed to omit a completion callback during link
    /// churn. A callback replaces/cancels this task; otherwise the ladder
    /// advances from retry to rediscovery to the existing paced reconnect path.
    private func armBatteryNotificationRecoveryWatchdog(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        reason: String
    ) {
        batteryNotificationRecoveryTask?.cancel()
        guard Self.shouldAllowAncillaryGATTRefresh(
            historyTransportOwnsLink: recoveredDataProjectionDeferralIsActive
        ) else {
            batteryNotificationRecoveryTask = nil
            pendingNotifyReenableUUIDs.remove(characteristic.uuid)
            AtriaDebugLog("ATRIADBG battery source=2A19 status=recovery_deferred reason=history_transport_owned action=no_watchdog")
            return
        }
        let attempt = batteryNotificationRecoveryAttempt
        let delay = min(4.0, 0.75 * pow(2.0, Double(attempt)))
        batteryNotificationRecoveryTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(delay))
            guard let self, !Task.isCancelled else { return }
            self.batteryNotificationRecoveryTask = nil
            guard let peripheral else { return }
            guard Self.shouldAllowAncillaryGATTRefresh(
                historyTransportOwnsLink: self.recoveredDataProjectionDeferralIsActive
            ) else {
                self.pendingNotifyReenableUUIDs.remove(characteristic.uuid)
                AtriaDebugLog("ATRIADBG battery source=2A19 status=recovery_deferred reason=history_transport_owned action=no_retry_discovery_or_reconnect")
                return
            }
            let connected = peripheral.state == .connected && self.status == .connected
            let action = Self.batteryNotificationRecoveryAction(
                connected: connected,
                isNotifying: characteristic.isNotifying,
                attempt: attempt
            )
            guard action != .waitForConnection else { return }
            self.batteryNotificationRecoveryAttempt = attempt + 1
            switch action {
            case .retryDisable:
                self.pendingNotifyReenableUUIDs.insert(characteristic.uuid)
                peripheral.setNotifyValue(false, for: characteristic)
                self.armBatteryNotificationRecoveryWatchdog(
                    peripheral: peripheral,
                    characteristic: characteristic,
                    reason: "\(reason)_retry_disable"
                )
            case .enable:
                peripheral.setNotifyValue(true, for: characteristic)
                self.armBatteryNotificationRecoveryWatchdog(
                    peripheral: peripheral,
                    characteristic: characteristic,
                    reason: "\(reason)_retry_enable"
                )
            case .rediscover:
                self.batteryLevelCharacteristic = nil
                peripheral.discoverServices([Self.UUIDs.batteryService])
                self.armBatteryNotificationRecoveryWatchdog(
                    peripheral: peripheral,
                    characteristic: characteristic,
                    reason: "\(reason)_rediscover"
                )
            case .reconnect:
                self.pendingNotifyReenableUUIDs.remove(characteristic.uuid)
                self.requestFreshScanReconnect(
                    peripheral: peripheral,
                    reason: "battery_2A19_notification_recovery"
                )
            case .waitForConnection:
                break
            }
            AtriaDebugLog("ATRIADBG battery source=2A19 status=recovery action=%@ attempt=%d reason=%@",
                          String(describing: action),
                          attempt,
                          reason)
        }
    }

    private func completeBatteryNotificationRecovery() {
        batteryNotificationRecoveryTask?.cancel()
        batteryNotificationRecoveryTask = nil
        batteryNotificationRecoveryAttempt = 0
        pendingNotifyReenableUUIDs.remove(Self.UUIDs.batteryLevel)
    }

    private func recordBatteryChargeEvidence(_ status: BatteryChargeStatus,
                                             reason: String,
                                             observedAt: Date = Date()) {
        guard status == .charging else {
            lastActiveBatteryChargeEvidenceAt = nil
            assignIfChanged(\.batteryChargeLastVerifiedAt, nil)
            batteryChargeExpirationTask?.cancel()
            batteryChargeExpirationTask = nil
            return
        }

        lastActiveBatteryChargeEvidenceAt = observedAt
        assignIfChanged(\.batteryChargeLastVerifiedAt, observedAt)
        scheduleBatteryChargeExpiration(reason: reason)
    }

    private func scheduleBatteryChargeExpiration(
        reason: String,
        after delay: TimeInterval = activeBatteryChargeDisplayMaxAge
    ) {
        batteryChargeExpirationTask?.cancel()
        batteryChargeExpirationTask = Task { @MainActor in
            try? await Task.sleep(for: .seconds(max(0, delay)))
            expireStaleBatteryChargeStatus(reason: reason)
        }
    }

    private func expireStaleBatteryChargeStatus(reason: String) {
        let now = Date()
        let decision = Self.batteryChargeLeaseDecision(
            status: batteryChargeStatus,
            lastEvidenceAt: lastActiveBatteryChargeEvidenceAt,
            now: now
        )
        if case .inactive = decision { return }
        if case .retain(let remaining) = decision, remaining > 0 {
            scheduleBatteryChargeExpiration(reason: reason, after: remaining)
            return
        }

        let age = lastActiveBatteryChargeEvidenceAt.map { now.timeIntervalSince($0) } ?? .infinity

        assignIfChanged(\.batteryIsCharging, false)
        assignIfChanged(\.batteryChargeStatus, .levelOnly)
        assignIfChanged(\.batteryChargeLastVerifiedAt, nil)
        lastActiveBatteryChargeEvidenceAt = nil
        batteryChargeExpirationTask = nil
        persistBatteryChargeStatus(.levelOnly, source: "live_charge_timeout")
        AtriaDebugLog("ATRIADBG battery_charge status=expired reason=%@ age_s=%.0f action=level_only",
              reason,
              age)
    }

