    private func bootstrapProductionCaptureDefaultsIfNeeded(arguments: [String]) {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: CaptureDefaults.configured) else { return }
        defaults.set(true, forKey: CaptureDefaults.configured)
        defaults.set(true, forKey: CaptureDefaults.protectedLongWearMigrated)
        defaults.set(true, forKey: CaptureDefaults.strapStepFullProtocolMigrated)
        defaults.set(true, forKey: CaptureDefaults.stableR10TransportMigrated)
        defaults.set(true, forKey: LongWearDefaults.enabled)
        defaults.set(true, forKey: RadioDefaults.standardHROnly)
        defaults.set(true, forKey: OfflineSyncDefaults.enabled)
        if defaults.object(forKey: LongWearDefaults.checkpointInterval) == nil {
            defaults.set(60.0, forKey: LongWearDefaults.checkpointInterval)
        }
        if defaults.object(forKey: LongWearDefaults.diagnosticInterval) == nil {
            defaults.set(15.0, forKey: LongWearDefaults.diagnosticInterval)
        }
        if defaults.object(forKey: LongWearDefaults.workoutAutoSaveInterval) == nil {
            defaults.set(15.0, forKey: LongWearDefaults.workoutAutoSaveInterval)
        }
        if defaults.object(forKey: LongWearDefaults.noDataTimeout) == nil {
            defaults.set(75.0, forKey: LongWearDefaults.noDataTimeout)
        }
        if defaults.object(forKey: LongWearDefaults.noDataCheckInterval) == nil {
            defaults.set(15.0, forKey: LongWearDefaults.noDataCheckInterval)
        }
        if defaults.object(forKey: LongWearDefaults.acceptedHRTimeout) == nil {
            defaults.set(45.0, forKey: LongWearDefaults.acceptedHRTimeout)
        }
        if defaults.string(forKey: LongWearDefaults.label) == nil {
            defaults.set("All-day wear", forKey: LongWearDefaults.label)
        }
        if defaults.string(forKey: CollectionProfileDefaults.profile) == nil {
            defaults.set(CollectionProfile.balanced.rawValue, forKey: CollectionProfileDefaults.profile)
        }
        collectionProfile = CollectionProfile.load(defaults: defaults)
        longWearModeEnabled = true
        updateSessionPointCacheMode()
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        let explicitMode = arguments.contains("--atria-standard-hr-only") || arguments.contains("--atria-long-wear-mode") ? 1 : 0
        recordRadioMode("protected_r10_minimal", reason: "stable_hr_r10_default")
        AtriaDebugLog("ATRIADBG capture_defaults status=enabled mode=protected_r10_minimal long_wear_default=1 strap_steps_background=1 offline_sync_default=1 reason=first_normal_launch explicit_mode_arg=%d checkpoint_interval_s=60 live_workout_interval_s=15 workout_autosave_interval_s=15 no_data_timeout_s=75 accepted_hr_timeout_s=45 hr_continuity_timeout_s=6 recovery_policy=staged_read_reassert_then_fresh_scan",
              explicitMode)
    }

    private func migrateAutomaticLongWearDefaultIfNeeded(arguments: [String]) {
        let defaults = UserDefaults.standard
        guard !arguments.contains("--atria-full-protocol-mode") else { return }
        guard defaults.bool(forKey: CaptureDefaults.configured) else { return }
        guard !defaults.bool(forKey: LongWearDefaults.userSelected) else { return }
        guard !defaults.bool(forKey: CaptureDefaults.protectedLongWearMigrated) else { return }

        defaults.set(true, forKey: CaptureDefaults.protectedLongWearMigrated)
        defaults.set(true, forKey: LongWearDefaults.enabled)
        defaults.set(true, forKey: RadioDefaults.standardHROnly)
        longWearModeEnabled = true
        updateSessionPointCacheMode()
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        forceFreshScanOnRestore = true
        recordRadioMode("protected_r10_minimal", reason: "protected_default_migration")
        AtriaDebugLog("ATRIADBG long_wear_mode status=migrated_default action=enabled reason=protected_background_collection_default")
    }

    /// Continuous strap capture is a product invariant. Older builds let the
    /// user disable it, then later removed that control; preserving the hidden
    /// false value strands the app in foreground-only collection and prevents
    /// sleep/activity evidence from being journaled. Full-protocol diagnostics
    /// remain isolated and never consume the production migration.
    @discardableResult
    nonisolated static func migrateAlwaysOnLongWearIfNeeded(
        defaults: UserDefaults = .standard,
        arguments: [String] = ProcessInfo.processInfo.arguments
    ) -> Bool {
        guard !arguments.contains("--atria-full-protocol-mode") else { return false }
        guard defaults.bool(forKey: CaptureDefaults.configured) else { return false }

        // `alwaysOnLongWearMigrated` records that the old preference was
        // retired; it must not turn the migration into a one-shot guard. A UI
        // or intent build from before the retirement can leave `enabled=false`
        // after that marker was already written. Trusting that orphaned value
        // on a later launch silently disables the supervisor that journals
        // sleep/all-day motion and performs bounded standard battery refreshes.
        let needsRepair =
            !defaults.bool(forKey: CaptureDefaults.alwaysOnLongWearMigrated)
            || !defaults.bool(forKey: LongWearDefaults.enabled)
            || defaults.bool(forKey: LongWearDefaults.userSelected)
        guard needsRepair else { return false }

        defaults.set(true, forKey: CaptureDefaults.alwaysOnLongWearMigrated)
        defaults.set(true, forKey: LongWearDefaults.enabled)
        // This does not change the independent battery-saver/radio preference.
        defaults.set(false, forKey: LongWearDefaults.userSelected)
        return true
    }

    private func migrateOfflineSyncDefaultIfNeeded(arguments: [String]) {
        guard !arguments.contains("--atria-full-protocol-mode") else { return }
        guard UserDefaults.standard.object(forKey: OfflineSyncDefaults.enabled) == nil else { return }
        UserDefaults.standard.set(true, forKey: OfflineSyncDefaults.enabled)
        AtriaDebugLog("ATRIADBG offline_sync status=migrated_default action=enabled reason=stored_session_backfill_default")
    }

    /// Rollbacks written before the history/R10 ownership interlock were
    /// contaminated by historical-recovery reconnects. Clear that obsolete
    /// cooldown exactly once after upgrading so existing users can qualify the
    /// corrected transport immediately instead of keeping frozen steps for up
    /// to six hours. No health, workout, sleep, archive, or calibration data is
    /// touched.
    private func migrateProtectedR10HistoryInterlockIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: Self.protectedR10HistoryInterlockMigrationKey) else { return }
        defaults.set(true, forKey: Self.protectedR10HistoryInterlockMigrationKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(0, forKey: Self.protectedR10RetryCountKey)
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.removeObject(forKey: "atria.protectedR10.rollbackAt")
        defaults.set("history_interlock_migration", forKey: "atria.protectedR10.rollbackReason")
        defaults.set("qualification_pending", forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG protected_r10 status=migrated_history_interlock action=clear_contaminated_rollback_preserve_user_data")
    }

    /// A stream can deliver valid R10 records yet still destabilize the physical
    /// BLE link. If the latest connection repeatedly ended within seconds and a
    /// motion frame was present immediately before that edge, isolate the next
    /// launch onto a fresh HR + standard-battery CoreBluetooth owner. This is a
    /// continuity fuse, not a permanent capability decision: an explicitly
    /// armed calibration run clears it so the transport can be tested again.
    private func isolateRecentProtectedR10DisconnectStormIfNeeded(now: Date = Date()) {
        let defaults = UserDefaults.standard
        let lastDisconnectAt = defaults.double(forKey: "atria.ble.lastDisconnectDiagnosticAt")
        let connectedDuration = defaults.double(forKey: "atria.ble.lastConnectedDuration")
        let lastR10At = defaults.double(forKey: RadioDefaults.passiveR10LastValidAt)
        guard lastDisconnectAt > 0,
              lastR10At > 0,
              Self.shouldIsolateRecentProtectedR10DisconnectStorm(
                alreadySuppressed: defaults.bool(forKey: Self.protectedR10StreamSuppressedKey),
                consecutiveEarlyDisconnects: defaults.integer(
                    forKey: Self.protectedR10EarlyDisconnectsKey
                ),
                lastDisconnectAge: now.timeIntervalSince1970 - lastDisconnectAt,
                connectedDuration: connectedDuration,
                lastR10Age: now.timeIntervalSince1970 - lastR10At
              ) else { return }
        if strapStepCalibrationCaptureUntil != nil {
            AtriaStrapCalibrationArchive.shared.flush()
            defaults.removeObject(
                forKey: AtriaStrapCalibrationArchive.captureUntilDefaultsKey
            )
            strapStepCalibrationCaptureUntil = nil
            stepCalibrationCaptureArmedAt = nil
            stepCalibrationMotionStreamReady = false
        }
        defaults.set(true, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(false, forKey: Self.protectedR10PassiveReprobePendingKey)
        defaults.set(now.timeIntervalSince1970,
                     forKey: Self.protectedR10DisconnectStormAtKey)
        defaults.set("short_links_with_fresh_r10",
                     forKey: Self.protectedR10DisconnectStormReasonKey)
        defaults.set("isolated_hr_battery_after_disconnect_storm",
                     forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG protected_r10 status=stream_isolated reason=disconnect_storm connected_s=%.1f r10_before_disconnect_s=%.1f action=fresh_pure_hr_owner_next_launch",
                      connectedDuration,
                      abs(lastDisconnectAt - lastR10At))
    }

    /// The retired 0x1A experiment could leave 2A37 alive while R10 stayed
    /// silent. One clean link rebuild is required to restore the strap's live
    /// motion mode; persist the intent so it happens once across app upgrades.
    private func migrateFailedProprietaryBatteryRefreshIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: BatteryDefaults.proprietaryRefreshRecoveryMigrated) else { return }
        defaults.set(true, forKey: BatteryDefaults.proprietaryRefreshRecoveryMigrated)
        guard defaults.string(forKey: BatteryDefaults.proprietaryRefreshLastFailure) != nil else { return }
        defaults.set(true, forKey: BatteryDefaults.proprietaryRefreshRecoveryPending)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.set("battery_probe_recovery_pending", forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=recovery_migrated action=one_clean_link_rebuild")
    }

    @discardableResult
    private func beginRetiredBatteryProbeRecoveryIfNeeded(_ peripheral: CBPeripheral) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: BatteryDefaults.proprietaryRefreshRecoveryPending) else { return false }
        defaults.set(false, forKey: BatteryDefaults.proprietaryRefreshRecoveryPending)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.removeObject(forKey: "atria.protectedR10.rollbackAt")
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.set("battery_probe_recovery_rebuild", forKey: RadioDefaults.passiveR10Status)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: "atria.battery.proprietaryRefresh.recoveryStartedAt")
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=recovery_start action=cancel_once_then_reconnect_known")
        requestFreshScanReconnect(peripheral: peripheral,
                                  reason: "retired_battery_probe_recovery",
                                  intent: .rebuildConnection)
        return true
    }

    private func migrateStableR10TransportDefaultIfNeeded(arguments: [String]) {
        let defaults = UserDefaults.standard
        guard !arguments.contains("--atria-full-protocol-mode") else { return }
        guard defaults.bool(forKey: CaptureDefaults.configured) else { return }
        let migrationWasRecorded = defaults.bool(forKey: CaptureDefaults.stableR10TransportMigrated)
        let userSelectedRadioMode = defaults.bool(forKey: RadioDefaults.standardHROnlyUserSelected)
        guard Self.shouldMigrateAutomaticModeToProtectedR10(
            migrationWasRecorded: migrationWasRecorded,
            userSelectedRadioMode: userSelectedRadioMode
        ) else { return }
        defaults.set(true, forKey: CaptureDefaults.stableR10TransportMigrated)
        defaults.set(true, forKey: RadioDefaults.standardHROnly)
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        forceFreshScanOnRestore = true
        recordRadioMode("protected_r10_minimal", reason: "stable_hr_r10_migration")
        AtriaDebugLog("ATRIADBG radio_mode status=migrated mode=protected_r10_minimal reason=physical_ab_stability strap_steps_background=1 phone_step_fallback=0")
    }

    /// Migrate only automatic/default radio state. A user who explicitly chose
    /// the diagnostic full profile or the stable minimal profile keeps it.
    nonisolated static func shouldMigrateAutomaticModeToProtectedR10(
        migrationWasRecorded: Bool,
        userSelectedRadioMode: Bool
    ) -> Bool {
        !migrationWasRecorded && !userSelectedRadioMode
    }

    /// Normal wear defaults to the physically verified minimal HR + R10 path.
    /// Despite the legacy storage name, this mode retains strap-native motion;
    /// only an explicit user selection may persist the broader profile.
    nonisolated static func shouldUseStandardHROnlyAtNormalLaunch(
        userSelectedBatterySaver: Bool,
        persistedStandardHROnly: Bool
    ) -> Bool {
        userSelectedBatterySaver ? persistedStandardHROnly : true
    }

    /// The disconnect-storm fuse is a transport safety decision, not a UI
    /// preference. Once it has isolated proprietary R10, a stale persisted
    /// "full protocol" choice must not rediscover the very services the fuse
    /// removed. A command-line diagnostic may still opt into that profile
    /// explicitly; ordinary launches stay on standard HR + battery until a
    /// bounded motion requalification clears the fuse.
    nonisolated static func shouldForceStableTransportForSuppressedR10(
        streamSuppressed: Bool,
        explicitFullProtocolDiagnostic: Bool
    ) -> Bool {
        streamSuppressed && !explicitFullProtocolDiagnostic
    }

    /// A temporary diagnostic full-protocol override must restore the exact
    /// prior profile. The automatic prior is now the stable R10-capable mode,
    /// so user ownership no longer changes the restoration result.
    nonisolated static func standardHROnlyModeAfterFullProtocolOverride(
        modeBeforeOverride: Bool,
        userSelectedBatterySaver: Bool
    ) -> Bool {
        _ = userSelectedBatterySaver
        return modeBeforeOverride
    }

    func setStandardHROnlyEnabled(_ enabled: Bool) {
        UserDefaults.standard.set(true, forKey: CaptureDefaults.configured)
        UserDefaults.standard.set(true, forKey: RadioDefaults.standardHROnlyUserSelected)
        applyStandardHROnly(enabled: enabled, persist: true, reconnect: true, reason: "user_toggle")
    }

    /// Enables the bounded raw-motion archive immediately for an in-app step
    /// calibration run. Normally the production protected connection already
    /// carries R10 on stream 5. If the disconnect-storm fuse isolated motion,
    /// explicit calibration clears that fuse and rediscovers only the minimal
    /// R10 service; it still never reads battery or starts offline history.
    func armStepCalibrationCapture(
        until requestedUntil: Date = Date().addingTimeInterval(
            AtriaStrapCalibrationArchive.defaultArmDuration
        ),
        allowsPreparationReconnect: Bool = true
    ) {
        let now = Date()
        let captureUntil = max(requestedUntil, now.addingTimeInterval(60))
        UserDefaults.standard.set(
            captureUntil.timeIntervalSince1970,
            forKey: AtriaStrapCalibrationArchive.captureUntilDefaultsKey
        )
        strapStepCalibrationCaptureUntil = captureUntil
        stepCalibrationCaptureArmedAt = now
        stepCalibrationMotionStreamReady = false
        // Guided calibration owns the dense motion stream exactly like an
        // explicit workout, so the card never depends on a parallel workout
        // being started by hand (2026-07-16 02:35 IST failure mode).
        workoutMotionCalibrationHoldUntil = captureUntil
        beginWorkoutMotionLease(startedAt: now, reason: "step_calibration_arm")
        if protectedR10StreamSuppressed {
            UserDefaults.standard.set(false,
                                      forKey: Self.protectedR10StreamSuppressedKey)
            UserDefaults.standard.set("explicit_calibration_reprobe",
                                      forKey: RadioDefaults.passiveR10Status)
            if let peripheral, peripheral.state == .connected {
                peripheral.discoverServices([Self.UUIDs.strapService])
            }
        }

        // Calibration is an explicit foreground operation and cannot begin
        // honestly without a new CRC-valid R10 frame. A cached active CCCD can
        // leave HR live while motion stays silent indefinitely; after a short
        // passive grace, rebuild that one connection exactly once. This does
        // not read battery, start history sync, or advance the 0/6 sequence.
        stepCalibrationMotionPreparationTask?.cancel()
        if allowsPreparationReconnect {
            stepCalibrationMotionPreparationTask = Task { @MainActor [weak self] in
                try? await Task.sleep(for: .seconds(4))
                guard let self, !Task.isCancelled else { return }
                self.stepCalibrationMotionPreparationTask = nil
                let checkAt = Date()
                guard Self.stepCalibrationMotionPreparationNeedsReconnect(
                    armedAt: self.stepCalibrationCaptureArmedAt,
                    motionStreamReady: self.stepCalibrationMotionStreamReady,
                    lastR10FrameAt: self.lastR10MotionFrameAt,
                    connected: self.status == .connected
                        && self.peripheral?.state == .connected,
                    now: checkAt
                ), let peripheral = self.peripheral else { return }
                self.requestFreshScanReconnect(
                    peripheral: peripheral,
                    reason: "step_calibration_stale_r10",
                    intent: .rebuildConnection
                )
                AtriaDebugLog("ATRIADBG strap_step_calibration status=motion_recovery_requested reason=no_fresh_r10_after_arm action=one_clean_link_rebuild")
            }
        } else {
            stepCalibrationMotionPreparationTask = nil
            AtriaDebugLog(
                "ATRIADBG strap_step_calibration status=preparation_reconnect_suppressed reason=gate4_stationary_probe action=observe_exact_command_epoch"
            )
        }

        AtriaDebugLog(
            "ATRIADBG strap_step_calibration status=armed_runtime until_utc=%@ source=developer_sequence transport=minimal_protected_r10 battery_reads=0 offline_sync=0 commands=0",
            ISO8601DateFormatter().string(from: captureUntil)
        )
    }

    /// Ends passive archival without touching the live transport.
    func finishStepCalibrationCapture(reason: String = "sequence_complete") {
        stepCalibrationMotionPreparationTask?.cancel()
        stepCalibrationMotionPreparationTask = nil
        AtriaStrapCalibrationArchive.shared.flush()
        UserDefaults.standard.removeObject(
            forKey: AtriaStrapCalibrationArchive.captureUntilDefaultsKey
        )
        strapStepCalibrationCaptureUntil = nil
        stepCalibrationCaptureArmedAt = nil
        stepCalibrationMotionStreamReady = false
        workoutMotionCalibrationHoldUntil = nil
        if !AtriaPendingWorkoutIntent.isActiveForBLEContinuity() {
            // Only calibration held the lease; a concurrently running explicit
            // workout keeps its own ownership untouched.
            endWorkoutMotionLease(reason: "step_calibration_\(reason)")
        }

        AtriaDebugLog(
            "ATRIADBG strap_step_calibration status=disarmed reason=%@ transport_unchanged=1 standard_hr_only=%d long_wear_unchanged=1",
            reason,
            standardHROnlyMode ? 1 : 0
        )
    }

    nonisolated static func stepCalibrationMotionPreparationNeedsReconnect(
        armedAt: Date?,
        motionStreamReady: Bool,
        lastR10FrameAt: Date?,
        connected: Bool,
        now: Date,
        passiveGrace: TimeInterval = 4
    ) -> Bool {
        guard connected,
              !motionStreamReady,
              let armedAt,
              now >= armedAt,
              now.timeIntervalSince(armedAt) >= passiveGrace else { return false }
        return lastR10FrameAt.map { $0 < armedAt } ?? true
    }

    func setLongWearModeEnabled(_ enabled: Bool, rest: Int, maxHR: Int) {
        UserDefaults.standard.set(true, forKey: CaptureDefaults.configured)
        UserDefaults.standard.set(true, forKey: LongWearDefaults.userSelected)
        UserDefaults.standard.set(enabled, forKey: LongWearDefaults.enabled)
        longWearModeEnabled = enabled
        updateSessionPointCacheMode()
        if enabled {
            let standardOnly = Self.shouldUseStandardHROnlyInProtectedBackground(
                userSelectedBatterySaver: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnlyUserSelected),
                persistedStandardHROnly: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnly),
                streamSuppressed: protectedR10StreamSuppressed
            )
            applyStandardHROnly(enabled: standardOnly, persist: false, reconnect: true, reason: "long_wear")
            startLongWearMode(rest: rest, maxHR: maxHR, reason: "user_toggle")
        } else {
            stopLongWearMode(reason: "user_toggle")
        }
    }

    func setCollectionProfile(_ profile: CollectionProfile, rest: Int, maxHR: Int) {
        guard profile != collectionProfile else { return }
        UserDefaults.standard.set(profile.rawValue, forKey: CollectionProfileDefaults.profile)
        collectionProfile = profile
        AtriaDebugLog("ATRIADBG collection_profile status=selected profile=%@ cadence_multiplier=%.2f stale_timeout_multiplier=%.2f",
                      profile.rawValue,
                      profile.cadenceMultiplier,
                      profile.staleTimeoutMultiplier)
        guard longWearModeEnabled else { return }
        startLongWearMode(rest: rest, maxHR: maxHR, reason: "collection_profile")
    }

    func applyPersistentLongWearModeIfNeeded(rest: Int, maxHR: Int) {
        guard UserDefaults.standard.bool(forKey: LongWearDefaults.enabled) else {
            longWearModeEnabled = false
            updateSessionPointCacheMode()
            return
        }
        longWearModeEnabled = true
        updateSessionPointCacheMode()
        guard !foregroundInteractiveMode else {
            return
        }
        let standardOnly = Self.shouldUseStandardHROnlyInProtectedBackground(
            userSelectedBatterySaver: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnlyUserSelected),
            persistedStandardHROnly: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnly),
            streamSuppressed: protectedR10StreamSuppressed
        )
        applyStandardHROnly(enabled: standardOnly, persist: false, reconnect: false, reason: "long_wear_persisted")
        if !standardOnly {
            rediscoverFullProtocolServicesIfConnected(reason: "long_wear_persisted_strap_steps")
        }
        startLongWearMode(rest: rest, maxHR: maxHR, reason: "persisted")
    }

    private func startLongWearMode(rest: Int, maxHR: Int, reason: String) {
        let defaults = UserDefaults.standard
        let checkpointSeconds = defaults.object(forKey: LongWearDefaults.checkpointInterval) as? Double ?? 60
        let diagnosticSeconds = defaults.object(forKey: LongWearDefaults.diagnosticInterval) as? Double ?? 15
        let autoSaveSeconds = defaults.object(forKey: LongWearDefaults.workoutAutoSaveInterval) as? Double ?? 15
        let noDataTimeout = defaults.object(forKey: LongWearDefaults.noDataTimeout) as? Double ?? 75
        let noDataCheckInterval = defaults.object(forKey: LongWearDefaults.noDataCheckInterval) as? Double ?? 15
        let acceptedHRTimeout = defaults.object(forKey: LongWearDefaults.acceptedHRTimeout) as? Double ?? 45
        let profile = collectionProfile
        let cadenceMultiplier = profile.cadenceMultiplier
        let staleTimeoutMultiplier = profile.staleTimeoutMultiplier
        let noDataWatchdogTimeout = max(60, min(noDataTimeout * staleTimeoutMultiplier, 600))
        let acceptedHRWatchdogTimeout = max(35, min(acceptedHRTimeout * staleTimeoutMultiplier, 180))
        let hrContinuityTimeout = Self.hrContinuityWatchdogTimeout(
            acceptedHRTimeout: acceptedHRWatchdogTimeout
        )
        let label = defaults.string(forKey: LongWearDefaults.label) ?? "All-day wear"
        captureLabel = label
        restoreActiveSessionJournalIfNeeded(reason: reason)
        let config = LongWearSupervisorConfig(
            label: label,
            rest: rest,
            maxHR: maxHR,
            checkpointInterval: max(10, min(checkpointSeconds * cadenceMultiplier, 3_600)),
            diagnosticInterval: max(5, min(diagnosticSeconds * cadenceMultiplier, 300)),
            autoSaveInterval: max(5, min(autoSaveSeconds * cadenceMultiplier, 300)),
            noDataTimeout: noDataWatchdogTimeout,
            noDataCheckInterval: max(5, min(noDataCheckInterval * cadenceMultiplier, 300)),
            hrContinuityTimeout: hrContinuityTimeout,
            rrPresenceTimeout: max(20, min(acceptedHRWatchdogTimeout * 2, 120)),
            acceptedHRTimeout: acceptedHRWatchdogTimeout
        )
        cacheDutyCycleRestHR(rest)
        scheduleLongWearSupervisor(config: config)
        ensureForegroundKeepaliveWatchdog(reason: reason)
        AtriaDebugLog("ATRIADBG long_wear_mode enabled=1 reason=%@ radio_mode=%@ supervisor=1 collection_profile=%@ cadence_multiplier=%.2f stale_timeout_multiplier=%.2f checkpoint_interval_s=%.0f live_workout_interval_s=%.0f workout_autosave_interval_s=%.0f no_data_timeout_s=%.0f no_data_check_interval_s=%.0f hr_continuity_timeout_s=%.0f supervisor_base_tick_s=%.0f accepted_hr_timeout_s=%.0f disconnect_reconnect_policy=staged_read_reassert_then_fresh_scan label=%@ rest_hr=%d max_hr=%d",
              reason,
              standardHROnlyMode ? "standard_hr_only" : "full_protocol",
              profile.rawValue,
              cadenceMultiplier,
              staleTimeoutMultiplier,
              config.checkpointInterval,
              config.diagnosticInterval,
              config.autoSaveInterval,
              config.noDataTimeout,
              config.noDataCheckInterval,
              config.hrContinuityTimeout,
              config.baseTickInterval,
              config.acceptedHRTimeout,
              label,
              rest,
              maxHR)
    }

    /// WHOOP 4's accepted 2A37 cadence is not guaranteed to be one second.
    /// Physical long-wear evidence showed healthy CRC-valid R10 alongside
    /// ordinary 8–14 second HR intervals; the former 6-second timeout therefore
    /// reset notifications continuously and induced a reconnect feedback loop.
    /// Keep continuity repair meaningfully earlier than the accepted-HR failure
    /// gate, but never earlier than a plausible healthy strap interval.
    nonisolated static func hrContinuityWatchdogTimeout(
        acceptedHRTimeout: TimeInterval
    ) -> TimeInterval {
        max(20, min(acceptedHRTimeout * (2.0 / 3.0), 45))
    }

    private func stopLongWearMode(reason: String) {
        stopForegroundKeepaliveWatchdog(reason: reason)
        pauseLongWearAutomation(reason: reason)
        UserDefaults.standard.set(false, forKey: CheckpointDefaults.armed)
        UserDefaults.standard.set("long_wear_stopped", forKey: CheckpointDefaults.lastStatus)
        AtriaDebugLog("ATRIADBG long_wear_mode enabled=0 reason=%@ checkpoint_cancelled=1 live_workout_cancelled=1 workout_autosave_cancelled=1 no_data_watchdog_cancelled=1 hr_continuity_watchdog_cancelled=1 accepted_hr_watchdog_cancelled=1",
              reason)
    }

    private func pauseLongWearAutomation(reason: String) {
        delayedSessionSaveTask?.cancel()
        liveWorkoutDiagnosticTask?.cancel()
        workoutAutoSaveTask?.cancel()
        longWearSupervisorTask?.cancel()
        activeLongWearSupervisorConfig = nil
        noDataWatchdogTask?.cancel()
        debugNoDataWatchdogTask?.cancel()
        hrContinuityWatchdogTask?.cancel()
        rrPresenceWatchdogTask?.cancel()
        debugHRContinuityWatchdogTask?.cancel()
        acceptedHRWatchdogTask?.cancel()
        debugAcceptedHRWatchdogTask?.cancel()
        longWearSupervisorTask = nil
        UserDefaults.standard.set(false, forKey: CheckpointDefaults.armed)
        AtriaDebugLog("ATRIADBG long_wear_mode paused=1 reason=%@ foreground_interactive=%d",
              reason,
              foregroundInteractiveMode ? 1 : 0)
    }

    private func elevateLongWearRadioForInteractiveForegroundIfNeeded(reason: String) {
        guard longWearModeEnabled else { return }
        guard standardHROnlyMode else { return }
        guard !offlineHistoricalSyncInProgress else { return }
        // Protected standard mode now carries 2A37 plus the physically proven
        // minimal stream5/TX/3F01 motion path. Foregrounding must not expand it
        // into legacy full protocol (extra CCCDs/reads/commands), which would
        // undo the isolation that made simultaneous HR and R10 stable.
        reassertHeartRateNotificationsIfConnected(reason: "\(reason)_protected_r10")
        sendProtectedR10ActivationIfReady()
        AtriaDebugLog("ATRIADBG radio_mode mode=standard_hr_only reason=%@ action=preserve_protected_r10_no_full_protocol_escalation",
                      reason)
    }

    private func isRRProtectedSleepWindow(now: Date) -> Bool {
        let hour = Calendar.current.component(.hour, from: now)
        return hour >= 21 || hour < 11
    }

    private func restoreProtectedLongWearRadioIfNeeded(reason: String) {
        guard longWearModeEnabled else { return }
        guard !offlineHistoricalSyncInProgress else { return }
        let standardOnly = Self.shouldUseStandardHROnlyInProtectedBackground(
            userSelectedBatterySaver: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnlyUserSelected),
            persistedStandardHROnly: UserDefaults.standard.bool(forKey: RadioDefaults.standardHROnly),
            streamSuppressed: protectedR10StreamSuppressed
        )
        // Already in the desired mode: leave the active proprietary stream and
        // HR subscription untouched. Rediscovery resets realtimeArmed and would
        // create an avoidable background gap.
        guard standardHROnlyMode != standardOnly else { return }
        applyStandardHROnly(enabled: standardOnly,
                            persist: false,
                            reconnect: standardOnly,
                            reason: reason)
        if !standardOnly {
            rediscoverFullProtocolServicesIfConnected(reason: "\(reason)_strap_steps")
        }
    }

    func handleInteractiveForeground(rest: Int, maxHR: Int) {
        let now = Date()
        // CoreBluetooth can remain in an impossible settled state even after
        // the system radio is available. A scene activation is a fresh chance
        // to run the bounded manager-session recovery when no new state
        // callback arrived while the app was backgrounded.
        resumeCentralUnavailableRecoveryIfNeeded()
        // A scene-active callback is not a workout intent. WHOOP pages can be
        // silent for several minutes between their first row and the remaining
        // burst, so cancelling here made an ordinary lock/unlock or screen wake
        // perpetually restart the same unacknowledged page. A persisted manual
        // workout still preempts through beginWorkoutMotionLease; foregrounding
        // alone must leave the loss-safe history owner intact.
        if let lastInteractiveForegroundHandlingAt,
           now.timeIntervalSince(lastInteractiveForegroundHandlingAt) < 1 {
            // UIKit and SwiftUI can report the same foreground transition.
            // Keep the already-live link healthy without repeating journal
            // restore, supervisor replacement, or service rediscovery.
            ensureForegroundKeepaliveWatchdog(reason: "scene_active_coalesced")
            reassertHeartRateNotificationsIfConnected(reason: "scene_active_coalesced")
            reassertR10NotificationIfConnected(reason: "scene_active_coalesced")
            return
        }
        lastInteractiveForegroundHandlingAt = now
        let activeExplicitWorkout = Self.explicitMotionOwnershipBlocksHistory(
            pendingWorkoutIntentActive:
                AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            inMemoryLeaseHeld: workoutMotionOwnerStartedAt != nil,
            calibrationHoldActive:
                workoutMotionCalibrationHoldUntil.map { Date() < $0 } == true
        )
        if Self.shouldUseFastWorkoutForegroundResume(
            activeExplicitWorkout: activeExplicitWorkout,
            hasLiveSession: !session.isEmpty,
            linkConnected: status == .connected && peripheral?.state == .connected
        ) {
            foregroundInteractiveMode = true
            ensureForegroundKeepaliveWatchdog(reason: "scene_active_workout_fast")
            reassertHeartRateNotificationsIfConnected(reason: "scene_active_workout_fast")
            reassertR10NotificationIfConnected(reason: "scene_active_workout_fast")
            updateDutyCycleState(reason: "scene_active_workout_fast", now: now)
            AtriaDebugLog("ATRIADBG foreground_resume path=workout_fast samples=%d connected=1 action=preserve_live_pipeline",
                          session.count)
            return
        }
        // Give a glance-eligible compact motion bank first refusal before any
        // deferred whole-archive consumer work can set the global
        // materialization-in-flight gate. Closing is only a scheduling edge;
        // the resulting ticket must still mint exact live-source authority and
        // pass atomic canonical admission. Heavy terminal projection stays
        // durable for its ordinary safe-background lane.
        let motionBankGlanceCheckpointStarted =
            checkpointHistoricalMotionBankOnGlanceIfNeeded(
                at: now,
                reason: "scene_active"
            )
        foregroundGlanceCheckpointRetryGate.recordForegroundAttempt(
            started: motionBankGlanceCheckpointStarted
        )
        scheduleStaleArmedRangeLossBackfillReconciliation(reason: "scene_active")
        // Opening the app is never permission to interrupt a healthy realtime
        // link. Ordinary history remains queued; only the exact compact bank
        // token above may share the link without cancelling its realtime owner.
        if !motionBankGlanceCheckpointStarted,
           !foregroundGlanceCheckpointRetryGate.isAwaitingFreshHeartRate,
           !historicalRadioTransportOwnsLink {
            resumeDeferredTerminalConsumerMaterializationIfNeeded(
                reason: "scene_active"
            )
            // A publication deferred for foreground in an EARLIER process leaves
            // no in-memory generation for the resume above to replay, so pending
            // consumer publication could sit unresolved across any number of
            // foregrounds (2026-08-06: gapResolvedConsumersPending survived four
            // foregrounds this way). Re-enter the top-level path too — it is
            // fully self-guarded (authority status, foreground, ledger, fresh
            // HR, transport ownership) and no-ops when nothing is pending.
            resumePendingFullDrainPublicationIfNeeded(
                reason: "scene_active_pending_publication"
            )
            _ = reconcileConsumedHistoricalTerminalPublicationIfNeeded(
                reason: "scene_active"
            )
        }
        resumeForegroundScanIfNeeded(reason: "scene_active")
        restoreActiveSessionJournalIfNeeded(reason: "scene_active_foreground")
        // Arm the silent-link safety net whenever we are foreground + long-wear,
        // including a fresh foreground launch where foregroundInteractiveMode is
        // already true (the all-night, screen-on scenario). Idempotent: only
        // starts when not already running.
        ensureForegroundKeepaliveWatchdog(reason: "scene_active")
        if longWearModeEnabled {
            startLongWearMode(rest: rest, maxHR: maxHR, reason: "scene_active_foreground")
        }
        reassertHeartRateNotificationsIfConnected(reason: "scene_active")
        reassertR10NotificationIfConnected(reason: "scene_active")
        elevateLongWearRadioForInteractiveForegroundIfNeeded(reason: "scene_active_interactive")
        if foregroundInteractiveMode {
            return
        }
        foregroundInteractiveMode = true
        guard longWearModeEnabled else {
            return
        }
        AtriaDebugLog("ATRIADBG long_wear_mode foreground_interactive=1 action=keep_supervisor_and_keepalive_armed rest_hr=%d max_hr=%d",
              rest,
              maxHR)
    }

    private func reassertHeartRateNotificationsIfConnected(reason: String) {
        if motionHandshakeDiagnostic != nil {
            recordMotionHandshakeEvidence(event: "foreground_hr_reassert_blocked", detail: reason)
            return
        }
        guard status == .connected, let peripheral else { return }
        if dutyCycleState == .sparseSentinel {
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=skipped reason=%@ detail=duty_cycle_sparse", reason)
            return
        }
        guard peripheral.state == .connected else {
            recomputeConnectionStatus(reason: "foreground_notify_reassert_peripheral_not_connected")
            if !reconnectToSavedPeripheralIfPossible(reason: "\(reason)_notify_reassert_peripheral_state_\(peripheral.state.rawValue)") {
                startScan(reason: "\(reason)_notify_reassert_peripheral_state_\(peripheral.state.rawValue)")
            }
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=peripheral_not_connected reason=%@ peripheral_state=%d action=reconnect_known_strap",
                          reason,
                          peripheral.state.rawValue)
            return
        }
        if let characteristic = heartRateCharacteristic {
            // A healthy CoreBluetooth subscription survives ordinary app
            // switches. Toggling it off/on on every foreground edge discards
            // in-flight 2A37 samples and was visible as a short workout gap
            // after returning to Atria. Repair only a stale or non-notifying
            // subscription; the keepalive watchdog remains the deeper safety
            // net for a link that goes silent later.
            if Self.shouldPreserveHeartRateNotificationOnForeground(
                isNotifying: characteristic.isNotifying,
                lastRawNotificationAt: lastRawHRNotificationAt,
                now: Date()
            ) {
                AtriaDebugLog("ATRIADBG ble_notify_reassert status=preserved reason=%@ source=foreground_return action=keep_healthy_subscription",
                              reason)
            } else {
                resetHeartRateNotifyIfNeeded(peripheral: peripheral,
                                             characteristic: characteristic,
                                             reason: reason)
            }
            if characteristic.properties.contains(.read) {
                peripheral.readValue(for: characteristic)
            }
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=requested reason=%@ source=foreground_return action=keep_connection",
                          reason)
            return
        }
        guard peripheral.state == .connected else { return }
        peripheral.discoverServices([UUIDs.heartRateService])
        AtriaDebugLog("ATRIADBG ble_notify_reassert status=discover_services reason=%@ source=foreground_return action=keep_connection",
                      reason)
    }

    /// R10 can stop while 2A37 HR remains healthy. Preserve an active stream5
    /// subscription, but repair a genuinely inactive CCCD without reconnecting
    /// or toggling the healthy HR notification.
    private func reassertR10NotificationIfConnected(reason: String,
                                                     now: Date = Date()) {
        guard motionHandshakeDiagnostic == nil,
              r10TransportIsExpected,
              status == .connected,
              let peripheral,
              peripheral.state == .connected else { return }

        if standardHROnlyMode {
            if strapStream5NotifyConfirmed {
                AtriaDebugLog("ATRIADBG r10_notify_repair status=preserved reason=%@ action=keep_initial_profile_cccd",
                              reason)
            } else {
                // The liveness/foreground path can race the first CoreBluetooth
                // notification-state callback. It may observe `false` while the
                // one allowed initial subscribe is still in flight, so it must
                // never decide fallback. The callback itself owns confirmed
                // error/inactive fallback; restored-cache discovery owns the
                // no-callback case.
                AtriaDebugLog("ATRIADBG r10_notify_repair status=awaiting_initial_profile reason=%@ action=no_mid_link_cccd_or_fallback",
                              reason)
            }
            // Physical V4 evidence showed that enabling or disabling stream 5
            // on an established protected link causes rapid disconnects. Only
            // initial characteristic discovery may establish this CCCD.
            return
        }

        guard let strapService = peripheral.services?.first(where: {
            $0.uuid == Self.UUIDs.strapService
        }) else {
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG r10_notify_repair status=discover_service reason=%@ action=no_reconnect",
                          reason)
            return
        }
        guard let characteristics = strapService.characteristics else {
            peripheral.discoverCharacteristics([Self.UUIDs.strapStream5, Self.UUIDs.strapTX],
                                               for: strapService)
            AtriaDebugLog("ATRIADBG r10_notify_repair status=discover_characteristics reason=%@ action=no_reconnect",
                          reason)
            return
        }
        guard let stream5 = characteristics.first(where: {
            $0.uuid == Self.UUIDs.strapStream5
        }), stream5.properties.contains(.notify) else {
            peripheral.discoverCharacteristics([Self.UUIDs.strapStream5, Self.UUIDs.strapTX],
                                               for: strapService)
            return
        }
        if stream5.isNotifying {
            strapStream5NotifyConfirmed = true
            ensureR10LivenessWatchdog(reason: "\(reason)_stream5_active")
            AtriaDebugLog("ATRIADBG r10_notify_repair status=preserved reason=%@ action=keep_active_cccd",
                          reason)
            return
        }
        guard Self.shouldRepairR10Notification(
            expected: r10TransportIsExpected,
            connected: true,
            isNotifying: stream5.isNotifying,
            lastRepairAt: lastR10NotifyRepairAt,
            now: now
        ) else { return }
        lastR10NotifyRepairAt = now
        strapStream5NotifyConfirmed = false
        peripheral.setNotifyValue(true, for: stream5)
        AtriaDebugLog("ATRIADBG r10_notify_repair status=requested reason=%@ action=enable_stream5_no_reconnect",
                      reason)
    }

    /// A healthy active subscription survives foreground transitions untouched.
    /// Inactive enables are coalesced by `heartRateNotificationEnableGate`.
    nonisolated static let foregroundHealthyNotificationWindow: TimeInterval = 12

    nonisolated static func shouldPreserveHeartRateNotificationOnForeground(
        isNotifying: Bool,
        lastRawNotificationAt: Date?,
        now: Date,
        healthyWindow: TimeInterval = foregroundHealthyNotificationWindow
    ) -> Bool {
        guard isNotifying, let lastRawNotificationAt else { return false }
        let age = now.timeIntervalSince(lastRawNotificationAt)
        return age >= 0 && age <= healthyWindow
    }

    private func beginStalledStreamRepair(source: String, now: Date = Date()) -> Bool {
        guard Self.shouldBeginStalledStreamRepair(lastRepairAt: lastStalledStreamRepairAt,
                                                  now: now) else {
            let remaining = max(0, Self.stalledStreamRepairCooldown
                - now.timeIntervalSince(lastStalledStreamRepairAt ?? now))
            AtriaDebugLog("ATRIADBG stalled_stream_repair status=cooldown source=%@ remaining_s=%.1f action=wait_for_data",
                          source,
                          remaining)
            return false
        }
        lastStalledStreamRepairAt = now
        AtriaDebugLog("ATRIADBG stalled_stream_repair status=started source=%@ cooldown_s=%.1f",
                      source,
                      Self.stalledStreamRepairCooldown)
        return true
    }

    @discardableResult
    private func requestHeartRateNotificationEnableIfNeeded(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        reason: String,
        now: Date = Date()
    ) -> HeartRateNotificationEnableDisposition {
        let supportsNotifications = characteristic.properties.contains(.notify)
            || characteristic.properties.contains(.indicate)
        let disposition = heartRateNotificationEnableGate.disposition(
            now: now,
            peripheralID: peripheral.identifier,
            peripheralConnected: peripheral.state == .connected,
            supportsNotifications: supportsNotifications,
            isNotifying: characteristic.isNotifying
        )
        if disposition == .request {
            peripheral.setNotifyValue(true, for: characteristic)
        }
        AtriaDebugLog("ATRIADBG ble_notify_enable status=%@ reason=%@ notifying=%d peripheral_state=%d",
                      String(describing: disposition),
                      reason,
                      characteristic.isNotifying ? 1 : 0,
                      peripheral.state.rawValue)
        return disposition
    }

    private func resetHeartRateNotifyIfNeeded(peripheral: CBPeripheral,
                                              characteristic: CBCharacteristic,
                                              reason: String) {
        if characteristic.isNotifying {
            if characteristic.properties.contains(.read) {
                peripheral.readValue(for: characteristic)
            }
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=preserved reason=%@ action=read_or_observe_active",
                          reason)
            return
        }
        _ = requestHeartRateNotificationEnableIfNeeded(
            peripheral: peripheral,
            characteristic: characteristic,
            reason: reason
        )
    }

    // MARK: - Duty cycle (daytime power saver)

    @Published private(set) var dutyCycleState: DutyCycleState = .fullCapture
    /// Escalation latch: full-rate capture until this instant. Extended while HR
    /// stays over rest+10; a workout therefore keeps full coverage end-to-end.
    private var dutyCycleEscalatedUntil: Date?
    /// Rest baseline cached from the params the app already passes in.
    private var dutyCycleRestHR: Int = 60
    private var lastSparsePollAt: Date?
    static let dutyCycleSparsePollInterval: TimeInterval = 180
    static let dutyCycleEscalationOverRest = 15
    static let dutyCycleSustainOverRest = 10
    static let dutyCycleEscalationHold: TimeInterval = 10 * 60

    var dutyCycleEnabled: Bool {
        UserDefaults.standard.bool(forKey: DutyCycleDefaults.enabled)
            || ProcessInfo.processInfo.arguments.contains("--atria-enable-duty-cycle")
    }

    func cacheDutyCycleRestHR(_ rest: Int) {
        if rest > 0 { dutyCycleRestHR = rest }
    }

    /// Learned sleep window in minutes-after-midnight, written by the session
    /// store from confirmed sleeps; falls back to 23:30-10:30.
    private func dutyCycleSleepWindow(defaults: UserDefaults = .standard) -> (start: Int, end: Int) {
        let start = defaults.integer(forKey: DutyCycleDefaults.sleepWindowStartMin)
        let end = defaults.integer(forKey: DutyCycleDefaults.sleepWindowEndMin)
        guard start > 0 || end > 0 else { return (23 * 60 + 30, 10 * 60 + 30) }
        return (min(max(start, 0), 1439), min(max(end, 0), 1439))
    }

    private func isInsideDutyCycleSleepWindow(now: Date = Date(), calendar: Calendar = .current) -> Bool {
        let window = dutyCycleSleepWindow()
        let components = calendar.dateComponents([.hour, .minute], from: now)
        let minutes = (components.hour ?? 0) * 60 + (components.minute ?? 0)
        if window.start <= window.end {
            return minutes >= window.start && minutes <= window.end
        }
        // Window crosses midnight (the normal case: ~23:30 -> ~10:30).
        return minutes >= window.start || minutes <= window.end
    }

    /// Called on accepted HR (notify or sparse poll): elevated HR escalates to
    /// full capture instantly and keeps extending the latch while elevated.
    func noteDutyCycleHeartRate(_ bpm: Int, now: Date = Date()) {
        guard dutyCycleEnabled else { return }
        if bpm >= dutyCycleRestHR + Self.dutyCycleEscalationOverRest {
            let wasEscalated = dutyCycleEscalatedUntil.map { $0 > now } ?? false
            dutyCycleEscalatedUntil = now.addingTimeInterval(Self.dutyCycleEscalationHold)
            if !wasEscalated {
                AtriaDebugLog("ATRIADBG duty_cycle status=escalated reason=hr_over_rest bpm=%d rest=%d",
                              bpm,
                              dutyCycleRestHR)
                updateDutyCycleState(reason: "hr_escalation")
            }
        } else if bpm >= dutyCycleRestHR + Self.dutyCycleSustainOverRest,
                  let until = dutyCycleEscalatedUntil, until > now {
            dutyCycleEscalatedUntil = now.addingTimeInterval(Self.dutyCycleEscalationHold)
        }
    }

    /// Recompute the desired state and apply transitions. Cheap; called from the
    /// keepalive tick, scene changes, and escalation events.
    func updateDutyCycleState(reason: String, now: Date = Date()) {
        let desired: DutyCycleState
        let defaults = UserDefaults.standard
        if !dutyCycleEnabled
            || !longWearModeEnabled
            || isInsideDutyCycleSleepWindow(now: now)
            || foregroundHighFrequencyDisplayMode
            || isRecording
            || defaults.bool(forKey: DutyCycleDefaults.focusFullCapture)
            || (dutyCycleEscalatedUntil.map { $0 > now } ?? false) {
            desired = .fullCapture
        } else {
            desired = .sparseSentinel
        }
        // Publish before applying the CCCD transition. A discovery callback on
        // CoreBluetooth's delegate queue can now honor the current intent
        // synchronously without crossing to MainActor first.
        heartRateCaptureIntent.update(
            continuousCaptureWanted: desired != .sparseSentinel
        )
        if desired == dutyCycleState {
            // Enforcement is idempotent, not edge-triggered: unguarded reasserts
            // (scene flips, reconnect discovery) can silently re-enable notify
            // while the state stays sparse — re-apply notify-off when seen.
            if desired == .sparseSentinel,
               status == .connected, let peripheral, peripheral.state == .connected,
               let characteristic = heartRateCharacteristic,
               characteristic.isNotifying {
                peripheral.setNotifyValue(false, for: characteristic)
                AtriaDebugLog("ATRIADBG duty_cycle action=hr_notify_off reason=reenforce_%@", reason)
            }
            return
        }
        dutyCycleState = desired
        AtriaDebugLog("ATRIADBG duty_cycle state=%@ reason=%@ sleep_window=%d rest=%d",
                      desired.rawValue,
                      reason,
                      isInsideDutyCycleSleepWindow(now: now) ? 1 : 0,
                      dutyCycleRestHR)
        switch desired {
        case .sparseSentinel:
            // Notify OFF on the live HR link. The protected battery percentage
            // subscription is independent and may emit only when the strap has
            // a new standard 2A19 value.
            if status == .connected, let peripheral, peripheral.state == .connected,
               let characteristic = heartRateCharacteristic,
               characteristic.properties.contains(.notify) {
                peripheral.setNotifyValue(false, for: characteristic)
                AtriaDebugLog("ATRIADBG duty_cycle action=hr_notify_off reason=%@", reason)
            }
        case .fullCapture:
            reassertHeartRateNotificationsIfConnected(reason: "duty_cycle_\(reason)")
        }
    }

    /// 2A1B is the standard charger-state characteristic. Its subscription is
    /// independent of the proprietary history transport, just as 2A19 is:
    /// history ownership may permit a missing CCCD to be enabled but never a
    /// read, discovery reset, custom command, or reconnect. Its callback is
    /// still rejected unless CoreBluetooth confirms this epoch's CCCD change.
    private func ensureBatteryStatusNotificationForCurrentEpoch(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        reason: String
    ) {
        guard status == .connected,
              peripheral.state == .connected,
              characteristic.properties.contains(.notify)
                || characteristic.properties.contains(.indicate) else {
            return
        }
        guard !characteristic.isNotifying else { return }
        UserDefaults.standard.set(
            Date().timeIntervalSince1970,
            forKey: BatteryDefaults.statusNotificationRequestedAt
        )
        peripheral.setNotifyValue(true, for: characteristic)
        AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=subscribe_requested reason=%@ history_transport_owned=%d no_read=1",
                      reason,
                      recoveredDataProjectionDeferralIsActive ? 1 : 0)
    }

    /// Bounded fallback for firmware that restores the 2A1B CCCD without
    /// delivering an initial charger-state notification. It uses the standard
    /// Battery Service only, never runs during proprietary history ownership,
    /// and follows the app's existing battery-refresh cadence.
    private func requestBatteryStatusReadForCurrentEpoch(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        reason: String
    ) {
        let defaults = UserDefaults.standard
        defaults.set(
            Int(characteristic.properties.rawValue),
            forKey: BatteryDefaults.statusProperties
        )
        guard !recoveredDataProjectionDeferralIsActive else {
            AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=read_skipped reason=%@ detail=history_transport_owned",
                          reason)
            return
        }
        guard status == .connected,
              self.peripheral?.identifier == peripheral.identifier,
              peripheral.state == .connected,
              characteristic.properties.contains(.read) else {
            AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=read_skipped reason=%@ detail=not_readable_or_not_current props=%lu",
                          reason,
                          characteristic.properties.rawValue)
            return
        }
        let now = Date()
        if let requestedAt = batteryStatusReadRequestedAt,
           now.timeIntervalSince(requestedAt) < 15 {
            return
        }
        batteryStatusReadRequestedAt = now
        defaults.set(now.timeIntervalSince1970,
                     forKey: BatteryDefaults.statusReadRequestedAt)
        defaults.removeObject(forKey: BatteryDefaults.statusReadLastError)
        peripheral.readValue(for: characteristic)
        AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=read_requested reason=%@ props=%lu",
                      reason,
                      characteristic.properties.rawValue)
    }

    func requestStrapStatusRead(reason: String) {
        let batteryLevelReadTransportActive =
            Self.batteryLevelReadTransportIsActive(
                offlineSyncInProgress: offlineHistoricalSyncInProgress,
                historyPhaseActive: historyOnlyProbeMode,
                readOnlyCaptureActive: readOnlyHistoryCaptureActive
            )
        if batteryLevelReadTransportActive {
            guard status == .connected,
                  let peripheral,
                  peripheral.state == .connected,
                  let batteryLevelCharacteristic else {
                AtriaDebugLog("ATRIADBG strap_status_refresh status=deferred reason=%@ detail=history_transport_owned action=no_battery_characteristic_or_discovery",
                              reason)
                return
            }
            let action = Self.historyOwnedBatteryRefreshAction(
                canNotify: batteryLevelCharacteristic.properties.contains(.notify)
                    || batteryLevelCharacteristic.properties.contains(.indicate),
                isNotifying: batteryLevelCharacteristic.isNotifying
            )
            if action == .subscribe {
                UserDefaults.standard.set(Date().timeIntervalSince1970,
                                          forKey: BatteryDefaults.notificationRequestedAt)
                peripheral.setNotifyValue(true, for: batteryLevelCharacteristic)
                AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ detail=history_transport_owned source=2A19_new_subscription no_read=1",
                              reason)
            } else {
                AtriaDebugLog("ATRIADBG strap_status_refresh status=deferred reason=%@ detail=history_transport_owned action=%@ no_read=1 no_discovery=1",
                              reason,
                              action == .awaitNotification ? "await_2A19_notification" : "2A19_unavailable")
            }
            return
        }
        guard motionHandshakeDiagnostic == nil else {
            recordMotionHandshakeEvidence(event: "battery_read_blocked", detail: reason)
            return
        }
        guard status == .connected, let peripheral, peripheral.state == .connected else {
            AtriaDebugLog("ATRIADBG strap_status_read status=skipped reason=%@ detail=not_connected", reason)
            return
        }
        if let batteryStatusCharacteristic {
            requestBatteryStatusReadForCurrentEpoch(
                peripheral: peripheral,
                characteristic: batteryStatusCharacteristic,
                reason: reason
            )
        }
        if let batteryLevelCharacteristic {
            let action = Self.standardBatteryRefreshAction(
                canRead: batteryLevelCharacteristic.properties.contains(.read),
                canNotify: batteryLevelCharacteristic.properties.contains(.notify)
                    || batteryLevelCharacteristic.properties.contains(.indicate),
                isNotifying: batteryLevelCharacteristic.isNotifying
            )
            switch action {
            case .read:
                lastBatteryReadRequestedAt = Date()
                peripheral.readValue(for: batteryLevelCharacteristic)
                AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ source=2A19_read",
                              reason)
            case .subscribe:
                lastBatteryReadRequestedAt = Date()
                UserDefaults.standard.set(Date().timeIntervalSince1970,
                                          forKey: BatteryDefaults.notificationRequestedAt)
                peripheral.setNotifyValue(true, for: batteryLevelCharacteristic)
                AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ source=2A19_new_subscription",
                              reason)
            case .awaitNotification:
                // This timestamp only throttles refresh attempts; it is never
                // used as battery-value freshness evidence.
                let now = Date()
                lastBatteryReadRequestedAt = now
                let defaults = UserDefaults.standard
                switch Self.existingBatteryNotificationAction(
                    currentEpochConfirmed: batteryNotificationTransportIsActive(
                        now: now,
                        defaults: defaults
                    ),
                    recoveryInFlight: batteryNotificationRecoveryTask != nil
                        || pendingNotifyReenableUUIDs.contains(batteryLevelCharacteristic.uuid)
                ) {
                case .awaitCurrentEpoch:
                    promoteReconnectBatteryBaselineIfSafe(
                        now: now,
                        heartRateReceivedAt: lastRawHRNotificationAt,
                        validatedR10ReceivedAt: lastR10MotionFrameAt,
                        reason: "2A19_existing_notify_active"
                    )
                    AtriaDebugLog("ATRIADBG strap_status_refresh status=awaiting reason=%@ source=2A19_existing_subscription",
                                  reason)
                case .refreshUnconfirmedEpoch:
                    // `didConnect` deliberately invalidates the previous link's
                    // notification proof. If CoreBluetooth then hands discovery
                    // a cached `isNotifying == true` characteristic, establish a
                    // real epoch with the same bounded off/on recovery used for
                    // callback failures. Never issue an explicit 2A19 read.
                    batteryNotificationEpochHadRejectedCallback = true
                    if defaults.string(forKey: BatteryDefaults.notificationLastError) == nil {
                        defaults.set("cached_notify_unconfirmed",
                                     forKey: BatteryDefaults.notificationLastError)
                    }
                    defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
                    defaults.set(now.timeIntervalSince1970,
                                 forKey: BatteryDefaults.notificationRequestedAt)
                    revokeBatteryNotificationLease(
                        reason: "2A19_cached_notify_unconfirmed",
                        now: now
                    )
                    pendingNotifyReenableUUIDs.insert(batteryLevelCharacteristic.uuid)
                    peripheral.setNotifyValue(false, for: batteryLevelCharacteristic)
                    armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: batteryLevelCharacteristic,
                        reason: "cached_notify_unconfirmed_disable"
                    )
                    AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ source=2A19_cached_subscription_epoch_refresh",
                                  reason)
                case .awaitRecovery:
                    AtriaDebugLog("ATRIADBG strap_status_refresh status=awaiting reason=%@ source=2A19_subscription_recovery",
                                  reason)
                }
            case .unavailable:
                lastBatteryReadRequestedAt = Date()
                AtriaDebugLog("ATRIADBG strap_status_refresh status=skipped reason=%@ detail=2A19_not_readable_or_notifiable",
                              reason)
            }
            return
        }
        peripheral.discoverServices([UUIDs.batteryService])
        AtriaDebugLog("ATRIADBG strap_status_refresh status=requested reason=%@ services=battery", reason)
    }

    private func scheduleBatteryConfirmationRead(incomingLevel: Int) {
        if batteryConfirmationReadTask != nil,
           let scheduledLevel = batteryConfirmationReadLevel,
           abs(scheduledLevel - incomingLevel) <= 2 {
            return
        }
        batteryConfirmationReadTask?.cancel()
        let delay = Self.batteryConfirmationRetryDelay(incomingLevel: incomingLevel)
        batteryConfirmationReadLevel = incomingLevel
        batteryConfirmationReadTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(delay))
            guard let self, !Task.isCancelled else { return }
            self.batteryConfirmationReadTask = nil
            self.batteryConfirmationReadLevel = nil
            guard let peripheral,
                  peripheral.state == .connected,
                  self.status == .connected else { return }
            self.requestStrapStatusRead(reason: "battery_confirmation_notify")
        }
    }

    private func rediscoverFullProtocolServicesIfConnected(reason: String) {
        guard status == .connected, let peripheral, peripheral.state == .connected else { return }
        txCharacteristic = nil
        realtimeArmed = false
        activeProprietaryNotifyUUIDs.removeAll()
        strapStream5NotifyConfirmed = false
        peripheral.discoverServices(discoveryServicesForCurrentMode)
        AtriaDebugLog("ATRIADBG radio_mode full_protocol_discovery status=requested reason=%@ action=keep_connection",
                      reason)
    }

    /// Runs while long-wear is enabled, including app-switch/background
    /// transitions. It does nothing while data flows. If the link is `.connected`
    /// but has produced no 2A37 packet for an extended window, it re-asserts the
    /// subscription, then escalates to a fresh-scan reconnect if silence
    /// persists. requestFreshScanReconnect already backs off exponentially.
    private func ensureForegroundKeepaliveWatchdog(reason: String) {
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard longWearModeEnabled || activeExplicitWorkout else {
            stopForegroundKeepaliveWatchdog(reason: reason)
            return
        }
        guard foregroundKeepaliveTask == nil else {
            UserDefaults.standard.set(reason, forKey: KeepaliveDefaults.lastReason)
            AtriaDebugLog("ATRIADBG foreground_keepalive armed=1 reason=%@ action=keep_existing_owner",
                          reason)
            return
        }
        startForegroundKeepaliveWatchdog(reason: reason)
    }

    private func startForegroundKeepaliveWatchdog(reason: String) {
        foregroundKeepaliveTask?.cancel()
        foregroundKeepaliveTask = nil
        foregroundKeepaliveReassertAt = nil
        foregroundKeepaliveLastJournalFlushAt = nil
        foregroundKeepaliveLastRawNotifications = sampleDiagnostics.rawNotifications
        let silenceTimeout: TimeInterval = 75
        let initialSilenceTimeout: TimeInterval = 8
        let initialReconnectWindow: TimeInterval = 20
        let checkInterval: TimeInterval = 20
        let armedAt = Date()
        let defaults = UserDefaults.standard
        defaults.set(true, forKey: KeepaliveDefaults.armed)
        defaults.set(armedAt.timeIntervalSince1970, forKey: KeepaliveDefaults.armedAt)
        defaults.set("armed", forKey: KeepaliveDefaults.lastStatus)
        defaults.set(reason, forKey: KeepaliveDefaults.lastReason)
        defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
        defaults.set(0.0, forKey: KeepaliveDefaults.lastSilence)
        defaults.removeObject(forKey: KeepaliveDefaults.tickStartedAt)
        defaults.removeObject(forKey: KeepaliveDefaults.lastTickAt)
        AtriaDebugLog("ATRIADBG foreground_keepalive armed=1 reason=%@ silence_timeout_s=%.0f check_interval_s=%.0f",
              reason, silenceTimeout, checkInterval)
        runForegroundKeepaliveTick(
            armedAt: armedAt,
            silenceTimeout: silenceTimeout,
            initialSilenceTimeout: initialSilenceTimeout,
            initialReconnectWindow: initialReconnectWindow
        )
        foregroundKeepaliveTask = Task { @MainActor in
            while !Task.isCancelled {
                let governedInterval = checkInterval * effectiveThermalCadenceMultiplier
                try? await Task.sleep(for: .seconds(governedInterval))
                if Task.isCancelled { break }
                runForegroundKeepaliveTick(
                    armedAt: armedAt,
                    silenceTimeout: silenceTimeout,
                    initialSilenceTimeout: initialSilenceTimeout,
                    initialReconnectWindow: initialReconnectWindow
                )
            }
        }
        defaults.synchronize()
    }

    private func runForegroundKeepaliveTick(
        armedAt: Date,
        silenceTimeout: TimeInterval,
        initialSilenceTimeout: TimeInterval,
        initialReconnectWindow: TimeInterval
    ) {
        let now = Date()
        let defaults = UserDefaults.standard
        defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.tickStartedAt)
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard Self.isBLEContinuityRelevant(
            longWearEnabled: longWearModeEnabled,
            activeExplicitWorkout: activeExplicitWorkout
        ) else {
            defaults.set("disabled", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("wait_continuity_owner", forKey: KeepaliveDefaults.lastAction)
            return
        }
        if Self.shouldKeepaliveObserveOnlyDuringHistory(
            offlineHistoricalSyncInProgress: offlineHistoricalSyncInProgress,
            historyOnlyProbeEnabled: historyOnlyProbeEnabled,
            historyTransportPhaseActive: historyOnlyProbeMode
        ) {
            // A durable request or configured probe may keep this broad
            // observe-only gate true while no proprietary operation actually
            // owns GATT. Let the battery path apply its narrower transport
            // predicate so readable 2A19 stays fresh without permitting any
            // HR repair, discovery reset, reconnect, or history command here.
            if Self.shouldRequestBatteryRefresh(
                lastRequestedAt: lastBatteryReadRequestedAt,
                now: now
            ) {
                requestStrapStatusRead(reason: "keepalive_history_boundary_freshness")
            }
            foregroundKeepaliveReassertAt = nil
            defaults.set("history_transport_owned", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=history_transport_owned action=observe_only battery_refresh_evaluated=1 no_2a37_read_or_discovery=1 no_reconnect=1")
            return
        }
        defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.lastTickAt)
        defaults.set(defaults.integer(forKey: KeepaliveDefaults.ticks) + 1, forKey: KeepaliveDefaults.ticks)
        if peripheral == nil {
            recomputeConnectionStatus(reason: "foreground_keepalive_missing_peripheral")
            defaults.set("missing_peripheral", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("reconnect_known_strap", forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=missing_peripheral action=reconnect_known_strap saved=%d",
                          hasSavedStrap ? 1 : 0)
            if !reconnectToSavedPeripheralIfPossible(reason: "foreground_keepalive_missing_peripheral") {
                startScan(reason: "foreground_keepalive_missing_peripheral")
            }
            return
        }
        guard status == .connected, let peripheral else { return }
        guard peripheral.state == .connected else {
            recomputeConnectionStatus(reason: "foreground_keepalive_peripheral_not_connected")
            defaults.set("peripheral_not_connected", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("reconnect_known_strap", forKey: KeepaliveDefaults.lastAction)
            defaults.set(Double(peripheral.state.rawValue), forKey: KeepaliveDefaults.lastPeripheralState)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=peripheral_not_connected peripheral_state=%d action=reconnect_known_strap saved=%d",
                          peripheral.state.rawValue,
                          hasSavedStrap ? 1 : 0)
            if !reconnectToSavedPeripheralIfPossible(reason: "foreground_keepalive_peripheral_state_\(peripheral.state.rawValue)") {
                startScan(reason: "foreground_keepalive_peripheral_state_\(peripheral.state.rawValue)")
            }
            return
        }
        defaults.set(Double(peripheral.state.rawValue), forKey: KeepaliveDefaults.lastPeripheralState)
        // Fall back to the keepalive's own arm time so silence is always
        // measurable — a state-restored connection (the overnight case)
        // can have no lastRawHRNotificationAt and no connectedAt at all,
        // which previously left this watchdog unable to ever fire.
        let reference = Self.latestLinkActivity([lastRawHRNotificationAt, connectedAt, armedAt]) ?? armedAt
        let silence = now.timeIntervalSince(reference)
        let hasSeenPacket = lastRawHRNotificationAt != nil
        let effectiveSilenceTimeout = hasSeenPacket ? silenceTimeout : initialSilenceTimeout
        defaults.set(silence, forKey: KeepaliveDefaults.lastSilence)
        let currentRawNotifications = sampleDiagnostics.rawNotifications
        let previousRawNotifications = foregroundKeepaliveLastRawNotifications
        foregroundKeepaliveLastRawNotifications = currentRawNotifications
        defaults.set(currentRawNotifications, forKey: KeepaliveDefaults.lastRawNotifications)
        let rawNotificationDelta: Int?
        if let previousRawNotifications {
            let delta = currentRawNotifications - previousRawNotifications
            rawNotificationDelta = delta
            defaults.set(delta, forKey: KeepaliveDefaults.lastRawNotificationDelta)
        } else {
            rawNotificationDelta = nil
        }
        defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.lastSampleCheckAt)
        let applicationActive = UIApplication.shared.applicationState == .active
        updateDutyCycleState(reason: "keepalive_tick", now: now)
        if Self.shouldRequestBatteryRefresh(lastRequestedAt: lastBatteryReadRequestedAt, now: now) {
            requestStrapStatusRead(reason: "keepalive_freshness")
        }
        let batteryNotificationTransportActive = batteryNotificationTransportIsActive(
            now: now,
            defaults: defaults
        )
        let recentReconnectBatteryBaselineDisplayable =
            recentReconnectBatteryBaselineIsDisplayable(
                now: now,
                defaults: defaults
            )
        let savedPeripheralIdentifier = defaults
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        let reconnectBatteryBaselineAwaitingProof =
            Self.reconnectBatteryBaselineIsAwaitingProof(
                level: batteryLevel,
                acceptedAt: lastAcceptedBatteryLevelAt,
                source: defaults.string(forKey: BatteryDefaults.source) ?? "none",
                displayedIsCached: displayedBatteryLevelIsCached,
                requiresFreshConfirmation: defaults.bool(
                    forKey: BatteryDefaults.requiresFreshConfirmation
                ),
                linkConnected: peripheral.state == .connected && status == .connected,
                sameSavedPeripheral: peripheral.identifier == savedPeripheralIdentifier,
                validationStartedAt: batteryBaselineValidationStartedAt,
                now: now
            )
        if batteryLevel >= 0,
           !Self.batteryLevelIsFresh(lastAcceptedAt: lastAcceptedBatteryLevelAt, now: now),
           !recentReconnectBatteryBaselineDisplayable,
           !reconnectBatteryBaselineAwaitingProof,
           !(batteryNotificationTransportActive
                && !displayedBatteryLevelIsCached
                && !UserDefaults.standard.bool(forKey: BatteryDefaults.requiresFreshConfirmation)) {
            // A connected HR stream is not evidence that the independent 2A19
            // value is current. Fail closed instead of keeping a stale low/full
            // percentage on every screen and notification surface.
            assignIfChanged(\.batteryLevel, -1)
            assignIfChanged(\.batteryIsCharging, false)
            assignIfChanged(\.batteryChargeStatus, .levelOnly)
            assignIfChanged(\.batteryRecentlyDropping, false)
            batteryReadingIsRecentBaseline = false
            UserDefaults.standard.set(true, forKey: BatteryDefaults.requiresFreshConfirmation)
            UserDefaults.standard.removeObject(forKey: BatteryDefaults.notificationLeaseAt)
            pendingBatteryDropCandidate = nil
            batteryProjectionRevision &+= 1
            AtriaDebugLog("ATRIADBG battery status=hidden reason=stale_live_value max_age_s=%.0f",
                          Self.batteryDisplayFreshnessLimit)
        }
        if batteryLevel >= 0,
           batteryNotificationTransportActive,
           !displayedBatteryLevelIsCached,
           !UserDefaults.standard.bool(forKey: BatteryDefaults.requiresFreshConfirmation) {
            // Keep the persisted/widget projection current without pretending a
            // new level packet arrived. The raw packet timestamp remains in
            // BatteryDefaults.at; only this subscription lease advances.
            UserDefaults.standard.set(now.timeIntervalSince1970,
                                      forKey: BatteryDefaults.notificationLeaseAt)
        }
        // While the notify stream is silent but the link is up, poll 2A37 by
        // read every tick. Low-battery evidence so far only proves coarse HR
        // may be available here; RR/detail still requires notification recovery.
        // In sparse duty-cycle mode the SAME read-poll is the sentinel, but at
        // the sparse interval instead of every tick.
        let sparseDue = dutyCycleState != .sparseSentinel
            || (lastSparsePollAt.map { now.timeIntervalSince($0) >= Self.dutyCycleSparsePollInterval } ?? true)
        if applicationActive,
           dutyCycleState == .sparseSentinel,
           silence > 15,
           sparseDue,
           let characteristic = heartRateCharacteristic,
           characteristic.properties.contains(.read) {
            lastSparsePollAt = now
            AtriaDebugLog("ATRIADBG duty_cycle action=sparse_poll interval_s=%.0f", Self.dutyCycleSparsePollInterval)
            peripheral.readValue(for: characteristic)
            defaults.set(now.timeIntervalSince1970, forKey: KeepaliveDefaults.lastReadPollAt)
        }
        // Immediate stall detection: uses the persisted last-packet timestamp
        // so it fires on the very first tick after a launch/foreground return.
        // The previous delta-based check needed a second tick that a
        // suspended-or-starved process never delivered.
        let persistedLastPacketInterval = defaults.double(forKey: SampleDefaults.lastRawNotificationAt)
        let lastPacketAt = Self.latestLinkActivity([
            lastRawHRNotificationAt,
            persistedLastPacketInterval > 0 ? Date(timeIntervalSince1970: persistedLastPacketInterval) : nil,
            connectedAt,
        ]) ?? armedAt
        let stallCooldownOK = lastStallHardReconnectAt.map { now.timeIntervalSince($0) >= 120 } ?? true
        let subscribeGraceOK = connectedAt.map { now.timeIntervalSince($0) > 25 } ?? true
        let packetAge = now.timeIntervalSince(lastPacketAt)
        let usefulGattReference = Self.latestLinkActivity([lastGattActivityAt, connectedAt, armedAt])
            ?? armedAt
        let usefulGattGap = max(0, now.timeIntervalSince(usefulGattReference))
        let continuityDisposition = Self.heartRateContinuityRecoveryDisposition(
            rawHeartRateGap: max(0, packetAge),
            usefulGattGap: usefulGattGap,
            adaptiveTimeout: effectiveSilenceTimeout,
            peripheralConnected: peripheral.state == .connected,
            hasHeartRateCharacteristic: heartRateCharacteristic != nil,
            heartRateIsNotifying: heartRateCharacteristic?.isNotifying == true,
            canReadHeartRate: heartRateCharacteristic?.properties.contains(.read) == true,
            canNotifyHeartRate: heartRateCharacteristic?.properties.contains(.notify) == true
        )
        updateStrapStreamState(reason: "foreground_keepalive",
                               rawNotificationDelta: rawNotificationDelta,
                               notifying: heartRateCharacteristic?.isNotifying,
                               defaults: defaults)
        if strapStreamState == .lowBatteryShutoff,
           packetAge > Self.staleHeartRatePacketThreshold {
            foregroundKeepaliveReassertAt = nil
            defaults.set("low_battery_shutoff", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("suppress_hard_reconnect", forKey: KeepaliveDefaults.lastAction)
            markLowBatteryReconnectSuppressed(reason: "low_battery_shutoff", defaults: defaults, now: now)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=low_battery_shutoff battery=%d packet_age_s=%.0f action=suppress_hard_reconnect",
                          batteryLevel,
                          packetAge)
            return
        }
        // Sparse duty-cycle intentionally silences 2A37. The sparse read poll
        // and battery refresh above still run, but no silence duration may turn
        // that intentional state into a connection rebuild.
        if dutyCycleState == .sparseSentinel {
            foregroundKeepaliveReassertAt = nil
            defaults.set("sparse_expected_silence", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
            return
        }
        if applicationActive,
           !offlineHistoricalSyncInProgress,
           subscribeGraceOK,
           stallCooldownOK,
           Self.shouldPerformForegroundKeepaliveHardRebuild(
            isSparseSentinel: dutyCycleState == .sparseSentinel,
            disposition: continuityDisposition
           ) {
            foregroundKeepaliveReassertAt = nil
            defaults.set("sample_counter_stalled", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("hard_reconnect", forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=sample_counter_stalled raw_notifications=%d packet_age_s=%.0f useful_gatt_gap_s=%.0f action=hard_reconnect",
                          currentRawNotifications,
                          packetAge,
                          usefulGattGap)
            forceHardReconnectForPacketStall(peripheral: peripheral,
                                             reason: "foreground_keepalive_all_gatt_silent_120s")
            return
        }
        guard silence >= effectiveSilenceTimeout else {
            foregroundKeepaliveReassertAt = nil
            defaults.set("observing", forKey: KeepaliveDefaults.lastStatus)
            defaults.set("observe", forKey: KeepaliveDefaults.lastAction)
            // Keep the live session crash-safe even during a long foreground
            // stretch. persistActiveSessionJournalIfNeeded skips unchanged
            // values, so this once-a-minute checkpoint is cheap.
            if foregroundKeepaliveLastJournalFlushAt.map({ now.timeIntervalSince($0) >= 60 }) ?? true {
                foregroundKeepaliveLastJournalFlushAt = now
                flushActiveSessionJournal(reason: "foreground_keepalive_crash_safety")
            }
            return
        }
        // First escalation keeps an active subscription untouched. Read 2A37
        // when possible; only enable notifications when CoreBluetooth says the
        // characteristic is not currently notifying.
        if foregroundKeepaliveReassertAt == nil {
            foregroundKeepaliveReassertAt = now
            let action: String
            switch continuityDisposition {
            case .readHeartRate:
                if let characteristic = heartRateCharacteristic {
                    peripheral.readValue(for: characteristic)
                }
                action = "read_2a37_keep_notify"
            case .enableHeartRateNotifications:
                if let characteristic = heartRateCharacteristic {
                    _ = requestHeartRateNotificationEnableIfNeeded(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        reason: "foreground_keepalive"
                    )
                }
                action = "enable_2a37_once"
            case .rediscoverHeartRateService:
                peripheral.discoverServices([UUIDs.heartRateService])
                action = "rediscover_2a37_service"
            case .reconnectKnownPeripheral:
                reconnectKnownPeripheralImmediately(
                    peripheral,
                    reason: "foreground_keepalive_corebluetooth_disconnected"
                )
                action = "reconnect_known_peripheral"
            case .observe, .rebuildConnection:
                action = "observe_live_link"
            }
            defaults.set("silent", forKey: KeepaliveDefaults.lastStatus)
            defaults.set(action, forKey: KeepaliveDefaults.lastAction)
            AtriaDebugLog("ATRIADBG foreground_keepalive status=silent silence_s=%.0f useful_gatt_gap_s=%.0f action=%@ notifying=%@",
                          silence,
                          usefulGattGap,
                          action,
                          heartRateCharacteristic.map { $0.isNotifying ? "1" : "0" } ?? "missing")
            return
        }
        // Keep observing/repairing the characteristic until the 120-second
        // all-useful-GATT gate above proves that the whole connection is dead.
        let reconnectWindow = hasSeenPacket ? silenceTimeout : initialReconnectWindow
        guard now.timeIntervalSince(foregroundKeepaliveReassertAt ?? now) >= reconnectWindow else { return }
        foregroundKeepaliveReassertAt = nil
        defaults.set("silent", forKey: KeepaliveDefaults.lastStatus)
        defaults.set("observe_until_all_gatt_silent", forKey: KeepaliveDefaults.lastAction)
        AtriaDebugLog("ATRIADBG foreground_keepalive status=silent silence_s=%.0f useful_gatt_gap_s=%.0f action=observe_until_all_gatt_silent",
                      silence,
                      usefulGattGap)
    }

    nonisolated static func shouldKeepaliveObserveOnlyDuringHistory(
        offlineHistoricalSyncInProgress: Bool,
        historyOnlyProbeEnabled: Bool,
        historyTransportPhaseActive: Bool
    ) -> Bool {
        offlineHistoricalSyncInProgress
            || historyOnlyProbeEnabled
            || historyTransportPhaseActive
    }

    nonisolated static func historicalTransportOwnershipIsActive(
        offlineSyncInProgress: Bool,
        historyProbeEnabled: Bool,
        historyPhaseActive: Bool,
        readOnlyRequested: Bool,
        readOnlyActive: Bool,
        postHistoryLiveRestorationPending: Bool,
        explicitRequestPending: Bool,
        freshOwnerCutoverPending: Bool,
        freshOwnerConnectionArmed: Bool,
        explicitLaunchIntentPending: Bool
    ) -> Bool {
        historicalRadioTransportOwnershipIsActive(
            offlineSyncInProgress: offlineSyncInProgress,
            historyProbeEnabled: historyProbeEnabled,
            historyPhaseActive: historyPhaseActive,
            readOnlyRequested: readOnlyRequested,
            readOnlyActive: readOnlyActive,
            postHistoryLiveRestorationPending:
                postHistoryLiveRestorationPending,
            freshOwnerCutoverPending: freshOwnerCutoverPending,
            freshOwnerConnectionArmed: freshOwnerConnectionArmed
        )
            || explicitRequestPending
            || explicitLaunchIntentPending
    }

    nonisolated static func historicalRadioTransportOwnershipIsActive(
        offlineSyncInProgress: Bool,
        historyProbeEnabled: Bool,
        historyPhaseActive: Bool,
        readOnlyRequested: Bool,
        readOnlyActive: Bool,
        postHistoryLiveRestorationPending: Bool,
        freshOwnerCutoverPending: Bool,
        freshOwnerConnectionArmed: Bool
    ) -> Bool {
        offlineSyncInProgress
            || historyProbeEnabled
            || historyPhaseActive
            || readOnlyRequested
            || readOnlyActive
            || postHistoryLiveRestorationPending
            || freshOwnerCutoverPending
            || freshOwnerConnectionArmed
    }

    nonisolated static func recoveredDataProjectionShouldDefer(
        isExactRecoveryPublication: Bool,
        broadHistoricalOwnershipActive: Bool,
        radioHistoricalOwnershipActive: Bool
    ) -> Bool {
        isExactRecoveryPublication
            ? radioHistoricalOwnershipActive
            : broadHistoricalOwnershipActive
    }

    /// A history owner belongs to the BLE epoch which armed it.  If that epoch
    /// was interrupted, it must not suppress standard 2A37 discovery on the
    /// replacement connection.  A deliberately armed fresh-owner cutover is
    /// the sole exception: it is the one case allowed to carry history
    /// ownership across a disconnect.
    nonisolated static func shouldReleaseInterruptedHistoryOwnerForLiveReconnect(
        offlineSyncInProgress: Bool,
        historyPhaseActive: Bool,
        disconnectObservedWithHistoryOwner: Bool,
        freshOwnerCutoverPending: Bool,
        freshOwnerAdmissionPending: Bool,
        freshOwnerConnectionArmed: Bool
    ) -> Bool {
        guard disconnectObservedWithHistoryOwner,
              offlineSyncInProgress || historyPhaseActive else {
            return false
        }
        return !freshOwnerCutoverPending
            && !freshOwnerAdmissionPending
            && !freshOwnerConnectionArmed
    }

    nonisolated static func shouldAllowAncillaryGATTRefresh(
        historyTransportOwnsLink: Bool
    ) -> Bool {
        !historyTransportOwnsLink
    }

    private func stopForegroundKeepaliveWatchdog(reason: String) {
        guard foregroundKeepaliveTask != nil else { return }
        foregroundKeepaliveTask?.cancel()
        foregroundKeepaliveTask = nil
        foregroundKeepaliveReassertAt = nil
        UserDefaults.standard.set(false, forKey: KeepaliveDefaults.armed)
        UserDefaults.standard.set("stopped", forKey: KeepaliveDefaults.lastStatus)
        UserDefaults.standard.set(reason, forKey: KeepaliveDefaults.lastReason)
        UserDefaults.standard.set("stop", forKey: KeepaliveDefaults.lastAction)
        AtriaDebugLog("ATRIADBG foreground_keepalive armed=0 reason=%@", reason)
    }

    func setForegroundHighFrequencyDisplayMode(_ enabled: Bool) {
        guard foregroundHighFrequencyDisplayMode != enabled else { return }
        foregroundHighFrequencyDisplayMode = enabled
        updateDutyCycleState(reason: enabled ? "live_screen_open" : "live_screen_closed")
    }

    func handleUnattendedMode(rest: Int, maxHR: Int, reason: String) {
        if !foregroundInteractiveMode {
            ensureForegroundKeepaliveWatchdog(reason: reason)
            return
        }
        foregroundInteractiveMode = false
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard Self.isBLEContinuityRelevant(
            longWearEnabled: longWearModeEnabled,
            activeExplicitWorkout: activeExplicitWorkout
        ) else {
            stopForegroundKeepaliveWatchdog(reason: reason)
            return
        }
        ensureForegroundKeepaliveWatchdog(reason: reason)
        if longWearModeEnabled {
            if Self.shouldRestoreProtectedLongWearRadioInBackground(
                activeExplicitWorkout: activeExplicitWorkout
            ) {
                restoreProtectedLongWearRadioIfNeeded(reason: reason)
            }
            startLongWearMode(rest: rest, maxHR: maxHR, reason: reason)
        }
        AtriaDebugLog("ATRIADBG long_wear_mode foreground_interactive=0 action=resume_automation reason=%@ rest_hr=%d max_hr=%d",
              reason,
              rest,
              maxHR)
    }

    func handleSceneBackgroundTransition(reason: String,
                                         rest: Int,
                                         maxHR: Int,
                                         flushRealtimeState: Bool = true) {
        foregroundInteractiveMode = false
        releaseConnectedMotionBankPreFreshHRFirstRefusal(
            reason: "scene_background_\(reason)"
        )
        releaseConnectedMotionBankArchiveWarmFirstRefusal(
            reason: "scene_background_\(reason)"
        )
        releaseConnectedMotionBankAdmissionLedgerFirstRefusal(
            reason: "scene_background_\(reason)"
        )
        releaseConnectedMotionBankLocalDependencyFirstRefusal(
            reason: "scene_background_\(reason)"
        )
        centralUnavailableRecoveryScheduleGeneration &+= 1
        centralUnavailableRecoveryTask?.cancel()
        centralUnavailableRecoveryTask = nil
        if flushRealtimeState {
            flushLifecycleRealtimeState(reason: reason)
        }
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        if longWearModeEnabled {
            // A live workout owns its current radio mode. In particular, R10 step
            // calibration needs full protocol in the background; downgrading to
            // standard-HR-only here reconnects and loses both steps and HR.
            if Self.shouldRestoreProtectedLongWearRadioInBackground(
                activeExplicitWorkout: activeExplicitWorkout
            ) {
                restoreProtectedLongWearRadioIfNeeded(reason: reason)
            }
            startLongWearMode(rest: rest, maxHR: maxHR, reason: reason)
        } else {
            ensureForegroundKeepaliveWatchdog(reason: reason)
        }
        reassertHeartRateNotificationsIfConnected(reason: reason)
        reassertR10NotificationIfConnected(reason: reason)
        scheduleHistoricalAdmissionLedgerMaintenance(reason: "\(reason)_lifecycle")
        AtriaDebugLog("ATRIADBG long_wear_mode foreground_interactive=0 action=background_keep_link reason=%@ connected=%d",
              reason,
              status == .connected ? 1 : 0)
    }

    @discardableResult
    private func retainPendingOfflineHistoricalSyncRequest(
        reason: String,
        force: Bool,
        explicitRequest: Bool,
        explicitPostWorkoutBankRequest: Bool = false,
        preserveConnectedRealtimeOwner: Bool = false
    ) -> PendingOfflineHistoricalSyncRequest {
        let existing = pendingOfflineHistoricalSyncRequest
        let retained = Self.coalescedPendingOfflineHistoricalSyncRequest(
            existing: existing,
            reason: reason,
            force: force,
            explicitRequest: explicitRequest,
            explicitPostWorkoutBankRequest:
                explicitPostWorkoutBankRequest
                    || transientMotionBankRequestAuthorization,
            preserveConnectedRealtimeOwner:
                preserveConnectedRealtimeOwner
                    || transientConnectedRealtimeOwnerPreservation
        )
        // An exact connected raw slice is process-local capability, never a
        // persisted/replayable request bit. If a synchronous prerequisite moves
        // underneath it, return the candidate for diagnostics but leave any
        // existing pending authority untouched; the next bounded fresh-HR
        // evaluation must mint a new exact object/epoch token.
        if transientConnectedRawHistoryCatchUpRequestAuthority != nil {
            return retained
        }
        pendingOfflineHistoricalSyncRequest = retained
        if let authority =
                transientConnectedMotionBankHistoryRequestAuthority {
            pendingConnectedMotionBankSchedulingTicketID =
                authority.ticketID
        } else if existing == nil {
            pendingConnectedMotionBankSchedulingTicketID = nil
        }
        return retained
    }

    private func takePendingOfflineHistoricalSyncRequest()
        -> PendingOfflineHistoricalSyncRequest? {
        defer {
            pendingOfflineHistoricalSyncRequest = nil
            pendingConnectedMotionBankSchedulingTicketID = nil
        }
        return pendingOfflineHistoricalSyncRequest
    }

    /// Starts the potentially expensive SQLite open/migration away from the
    /// main actor and returns `true` only once the exact admission authority is
    /// ready. The retained request is resumed from a later accepted live-HR
    /// callback, so this helper never seizes or restarts the BLE link itself.
    @discardableResult
    private func prepareHistoricalAdmissionLedgerIfNeeded(reason: String) -> Bool {
        if historicalAdmissionLedger != nil { return true }
        guard historicalAdmissionLedgerPreparationTask == nil else {
            return false
        }

        let documents = FileManager.default.urls(
            for: .documentDirectory,
            in: .userDomainMask
        )[0]
        let retiredIndexURL = documents.appendingPathComponent(
            "atria-historical/retired-replay-v1/exact-identities-v3.sqlite"
        )
        let applicationSupport = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        )[0]
        let ledgerURL = applicationSupport
            .appendingPathComponent(
                "atria-historical/history-admission-v1",
                isDirectory: true
            )
            .appendingPathComponent("whoop4-full-drain.sqlite")

        historicalAdmissionLedgerPreparationFailure = nil
        UserDefaults.standard.set(
            "preparing_durable_history_ledger",
            forKey: OfflineSyncDefaults.lastStatus
        )
        AtriaDebugLog(
            "ATRIADBG historyAdmission status=preparing reason=%@ action=keep_live_owner_open_sqlite_off_main",
            reason
        )
        historicalAdmissionLedgerPreparationTask = Task { @MainActor [weak self] in
            let prepared = await Task.detached(
                priority: .utility
            ) {
                do {
                    let retiredIndex = try AtriaHistoricalRetiredReplayIndex(
                        databaseURL: retiredIndexURL
                    )
                    let ledger = try AtriaWhoop4HistoryAdmissionLedger(
                        databaseURL: ledgerURL,
                        retiredReplayLookup: { strapIdentifier, frame in
                            try retiredIndex.contains(
                                strapIdentifier: strapIdentifier,
                                whoopFrame: frame
                            )
                        }
                    )
                    return Result<
                        AtriaWhoop4HistoryAdmissionLedger,
                        Error
                    >.success(ledger)
                } catch {
                    return .failure(error)
                }
            }.value

            guard let self else { return }
            self.historicalAdmissionLedgerPreparationTask = nil
            switch prepared {
            case .success(let ledger):
                self.historicalAdmissionLedger = ledger
                self.historicalAdmissionLedgerPreparationFailure = nil
                UserDefaults.standard.set(
                    "durable_history_ledger_ready",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                AtriaDebugLog(
                    "ATRIADBG historyAdmission status=ready reason=%@ action=resume_retained_request_after_live_persistence",
                    reason
                )
                self.resumeConnectedMotionBankAfterAdmissionLedgerReadyIfNeeded()
                self.resumePendingForcedHistoricalSyncAfterLivePersistenceIfNeeded(
                    reason: "history_admission_ledger_ready"
                )
                // A terminal drain restored at launch needs the same ledger to
                // prove coverage and publish consumers. Without this resume it
                // fails once with `admissionIdentityNotDurable`, then leaves
                // the newer workout gap waiting behind the old terminal.
                self.resumePendingFullDrainPublicationIfNeeded(
                    reason: "history_admission_ledger_ready"
                )
                self.scheduleRangeLossBackfillIfNeeded(
                    reason: "history_admission_ledger_ready"
                )
            case .failure(let error):
                let detail = String(describing: error)
                self.historicalAdmissionLedgerPreparationFailure = detail
                UserDefaults.standard.set(
                    "durable_history_ledger_failed",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                AtriaDebugLog(
                    "ATRIADBG historyAdmission status=prepare_failed reason=%@ error=%@ action=retain_gap_keep_live_no_history_command",
                    reason,
                    detail
                )
                self.releaseConnectedMotionBankAdmissionLedgerFirstRefusal(
                    reason: "history_admission_ledger_failed"
                )
            }
        }
        return false
    }

    /// A user/research request may resume after a current-epoch HR sample has
    /// entered the journal. A post-workout bank request may not: the
    /// pending tuple intentionally lacks the exact ticket/object/epoch token
    /// required to share the live link, so only the typed motion-bank selector
    /// may retry it. A generic forced automatic request remains ineligible.
    nonisolated static func pendingForcedHistoricalSyncMayResumeAfterLivePersistence(
        force: Bool,
        explicitRequest: Bool,
        explicitPostWorkoutBankRequest _: Bool,
        preserveConnectedRealtimeOwner _: Bool = false
    ) -> Bool {
        // A post-workout Boolean is scheduling metadata, never the typed
        // ticket/object/epoch authority needed on a connected live owner.
        // If a real user/research request was coalesced with it, that distinct
        // explicit authority remains eligible at the bounded generic cadence.
        return force && explicitRequest
    }

    nonisolated static let pendingForcedHistoricalSyncLiveResumeRetryInterval:
        TimeInterval = 60

    nonisolated static func pendingForcedHistoricalSyncUsesLiveHotPathCadence(
        trigger: String
    ) -> Bool {
        trigger == "accepted_hr" || trigger == "accepted_hr_batch"
    }

    /// A persisted *interrupted* full drain is recovery evidence, not a user
    /// command. Reclaiming a just-restored live link for that old request
    /// creates a reconnect loop, so preserve its exact gap and wait for
    /// ordinary retry policy or a new explicit diagnostic instead.
    private func resumePendingForcedHistoricalSyncAfterLivePersistenceIfNeeded(
        reason: String
    ) {
        guard let pending = pendingOfflineHistoricalSyncRequest,
              Self
                .pendingForcedHistoricalSyncMayResumeAfterLivePersistence(
                    force: pending.force,
                    explicitRequest: pending.explicitRequest,
                    explicitPostWorkoutBankRequest:
                        pending.explicitPostWorkoutBankRequest,
                    preserveConnectedRealtimeOwner:
                        pending.preserveConnectedRealtimeOwner
                ),
              !freshHistoryOwnerBoundaryFailureLatched,
              !offlineHistoricalSyncInProgress,
              !AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
              !historicalConsumerMaterializationInFlight,
              postHistoryLiveRestorationTask == nil,
              peripheral?.state == .connected,
              status == .connected,
              let connectedAt,
              let lastAcceptedHRAt,
              lastAcceptedHRAt >= connectedAt else { return }
        if Self.shouldDeferInterruptedFullDrainRelaunchAfterLivePersistence(
            pendingReason: pending.reason
        ), persistedDrainResumeAllowed {
            _ = takePendingOfflineHistoricalSyncRequest()
            explicitHistoryLaunchIntentPending = false
            deferInterruptedFullDrainForCurrentLiveConnection = true
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            let defaults = UserDefaults.standard
            defaults.set("deferred_interrupted_full_drain_live_priority",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(pending.reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_interrupted_full_drain_live_priority reason=%@ trigger=%@ action=retain_exact_gap_no_fresh_owner_cutover",
                          pending.reason,
                          reason)
            scheduleInterruptedFullDrainReacquisitionIfNeeded(reason: pending.reason)
            return
        }
        let now = Date()
        if Self.pendingForcedHistoricalSyncUsesLiveHotPathCadence(
            trigger: reason
        ),
           pendingForcedHistoricalSyncLiveResumeAttemptedRequest == pending,
           let retryNotBefore =
                pendingForcedHistoricalSyncLiveResumeRetryNotBefore,
           now < retryNotBefore {
            return
        }
        pendingForcedHistoricalSyncLiveResumeAttemptedRequest = pending
        pendingForcedHistoricalSyncLiveResumeRetryNotBefore =
            now.addingTimeInterval(
                Self.pendingForcedHistoricalSyncLiveResumeRetryInterval
            )
        _ = takePendingOfflineHistoricalSyncRequest()
        AtriaDebugLog("ATRIADBG offline_sync status=resuming_explicit_force reason=%@ trigger=%@ action=flush_live_journal_then_acquire_history_owner",
                      pending.reason,
                      reason)
        let resumed = requestOfflineHistoricalSyncIfNeeded(
            reason: pending.reason,
            force: pending.force,
            explicitResearchRequest: pending.explicitRequest,
            explicitPostWorkoutBankRequest:
                pending.explicitPostWorkoutBankRequest,
            preserveConnectedRealtimeOwner:
                pending.preserveConnectedRealtimeOwner
        )
        if resumed {
            pendingForcedHistoricalSyncLiveResumeAttemptedRequest = nil
            pendingForcedHistoricalSyncLiveResumeRetryNotBefore = nil
        }
    }

    nonisolated static func shouldResumeInterruptedFullDrainAtLaunch(
        rangeLossBackfillPending: Bool,
        authorityStatus: AtriaHistoricalFullDrainCoverageStore.Authority.Status?,
        exactGapFingerprintStillPending: Bool
    ) -> Bool {
        rangeLossBackfillPending
            && authorityStatus == .draining
            && exactGapFingerprintStillPending
    }

    /// Launch restoration normally carries the interrupted authority through
    /// `pendingOfflineHistoricalSyncRequest`.  That in-memory handoff can be
    /// superseded by another launch-time recovery task before the first HR
    /// callback, even though the durable authority and exact gap are still
    /// valid.  A fresh accepted HR is the safe place to reconcile that state:
    /// it may admit only the existing live-first/cooldown-gated reacquisition.
    nonisolated static func shouldRearmPersistedInterruptedFullDrainFromFreshHR(
        rangeLossBackfillPending: Bool,
        authorityStatus: AtriaHistoricalFullDrainCoverageStore.Authority.Status?,
        exactGapFingerprintStillPending: Bool,
        activeExplicitWorkout: Bool,
        historySyncInProgress: Bool,
        consumerMaterializationInFlight: Bool
    ) -> Bool {
        shouldResumeInterruptedFullDrainAtLaunch(
            rangeLossBackfillPending: rangeLossBackfillPending,
            authorityStatus: authorityStatus,
            exactGapFingerprintStillPending: exactGapFingerprintStillPending
        )
        && !activeExplicitWorkout
        && !historySyncInProgress
        && !consumerMaterializationInFlight
    }

    /// The launch marker restores a durable recovery candidate, not permission
    /// to interrupt the first healthy live connection after a radio outage.
    nonisolated static func shouldDeferInterruptedFullDrainRelaunchAfterLivePersistence(
        pendingReason: String
    ) -> Bool {
        pendingReason == "interrupted_full_drain_relaunch"
    }

    /// The only reasons allowed through the disabled-production gate, and only
    /// while a durable `.draining` authority with a pending exact gap exists.
    /// Both resume an already-admitted transport transaction; neither can
    /// start a new full-flash drain for a new gap.
    nonisolated static func isPersistedDrainAuthorityResumeReason(
        _ reason: String
    ) -> Bool {
        reason == "interrupted_full_drain_bounded_reacquisition"
            || reason == "interrupted_full_drain_relaunch"
    }

    /// A process expiry is not a terminal no-rows result. Permit exactly one
    /// later re-acquisition for the same durable authority only after the
    /// current link has been stable long enough to establish that live capture
    /// recovered. A changed gap gets a fresh opportunity; the same gap is
    /// held for the persisted cooldown to avoid reconnect churn. A productive
    /// slice is durable progress, not permission to immediately reclaim the
    /// radio: live HR and the motion bank need a stable epoch between slices.
    nonisolated static func shouldReacquireInterruptedFullDrain(
        stableLiveSeconds: TimeInterval,
        requiredStableLiveSeconds: TimeInterval,
        activeExplicitWorkout: Bool,
        historySyncInProgress: Bool,
        consumerMaterializationInFlight: Bool,
        gapFingerprint: String,
        lastReacquisitionGapFingerprint: String?,
        lastReacquisitionAtUnix: TimeInterval?,
        priorAttemptYieldedRows: Bool,
        nowUnix: TimeInterval,
        cooldown: TimeInterval
    ) -> Bool {
        guard stableLiveSeconds.isFinite,
              requiredStableLiveSeconds.isFinite,
              requiredStableLiveSeconds >= 0,
              stableLiveSeconds >= requiredStableLiveSeconds,
              !activeExplicitWorkout,
              !historySyncInProgress,
              !consumerMaterializationInFlight,
              !gapFingerprint.isEmpty,
              nowUnix.isFinite,
              cooldown.isFinite,
              cooldown >= 0 else { return false }
        guard gapFingerprint == lastReacquisitionGapFingerprint,
              let lastReacquisitionAtUnix,
              lastReacquisitionAtUnix.isFinite,
              nowUnix >= lastReacquisitionAtUnix else {
            return true
        }
        _ = priorAttemptYieldedRows
        return nowUnix - lastReacquisitionAtUnix >= cooldown
    }

    /// The first accepted HR after a reconnect necessarily arrives before the
    /// live-stability interval.  It is nevertheless the one reliable moment
    /// to arm the bounded timer: the deferred launch intent is consumed by
    /// that callback, so requiring the interval *here* leaves no later event
    /// that can schedule the existing drain.  Eligibility and cooldown remain
    /// checked again when the timer fires, immediately before BLE ownership is
    /// reacquired.
    nonisolated static func shouldScheduleInterruptedFullDrainReacquisition(
        activeExplicitWorkout: Bool,
        historySyncInProgress: Bool,
        consumerMaterializationInFlight: Bool,
        freshOwnerBoundaryFailureLatched: Bool,
        gapFingerprint: String
    ) -> Bool {
        !activeExplicitWorkout
            && !historySyncInProgress
            && !consumerMaterializationInFlight
            && !freshOwnerBoundaryFailureLatched
            && !gapFingerprint.isEmpty
    }

    /// Only an unexpected physical loss of the active full-drain owner earns a
    /// later live-first reacquisition. Intentional cutovers, user disconnects,
    /// and watchdog transport resets already have their own bounded ownership
    /// paths and must never turn into an extra history-command loop.
    nonisolated static func shouldRetainInterruptedFullDrainReacquisition(
        fullDrainAuthorityActive: Bool,
        userRequestedDisconnect: Bool,
        recentAppCancel: Bool
    ) -> Bool {
        fullDrainAuthorityActive && !userRequestedDisconnect && !recentAppCancel
    }

    nonisolated static func interruptedFullDrainGapFingerprint(
        _ gap: AtriaHistoricalFullDrainCoverageStore.PendingGap
    ) -> String {
        "\(gap.gapIdentifier)|\(gap.gapLedgerGeneration)|\(gap.startUnix)|\(gap.endUnix)|\(gap.reason)"
    }

    /// The initial live-first deferral below protects a just-restored strap
    /// connection. Do not leave a durable `.draining` authority parked
    /// forever, though: when iOS killed the process mid-drain, no terminal
    /// transport result exists. This resumes the existing exact gap once, not
    /// a selector sweep or a new protocol variant.
    /// The autonomous resume lane is retired (see
    /// `AtriaHistoricalFullDrainCoverageIntegration.persistedDrainResumeEnabled`).
    /// The seekless oldest-first replay is structurally sealed: even if the
    /// integration flag is flipped back on, the autonomous lane stays paused
    /// until `exactRangeSeekAvailable` proves a real seek exists -- at which
    /// point the replay is no longer the non-convergent path this retirement
    /// removed. An attended seek experiment still needs a real armed drain to
    /// intercept, so the debug selector-sweep launch argument re-opens the lane
    /// for that bounded, operator-supervised run only (that run is how the seek
    /// gets proven in the first place, so it must not require the seek).
    nonisolated static func persistedDrainResumeAllowed(
        integrationEnabled: Bool,
        exactRangeSeekAvailable: Bool,
        attendedSelectorSweepEnabled: Bool
    ) -> Bool {
        (integrationEnabled && exactRangeSeekAvailable) || attendedSelectorSweepEnabled
    }

    private var persistedDrainResumeAllowed: Bool {
        if gate2FullDrainProofEnabled,
           gate2FullDrainRequestedGapID != nil {
            return true
        }
        return Self.persistedDrainResumeAllowed(
            integrationEnabled: AtriaHistoricalFullDrainCoverageIntegration
                .persistedDrainResumeEnabled,
            exactRangeSeekAvailable: AtriaHistoricalFullDrainCoverageIntegration
                .exactRangeTransportAuthorityAvailable,
            attendedSelectorSweepEnabled: historySelectorSweepEnabled
        )
    }

    private func scheduleInterruptedFullDrainReacquisitionIfNeeded(
        reason: String
    ) {
        guard persistedDrainResumeAllowed else {
            logPersistedDrainResumePaused(reason: reason,
                                          action: "preserve_live_no_cutover")
            return
        }
        // Every one of these refusals used to be silent, which made a
        // non-arming drain undiagnosable in the field: the only observable was
        // the absence of a log line. Name the first failing precondition.
        let scheduleAuthority = try? historicalFullDrainCoverageStore.load()
        let scheduleBlocker: String? = {
            if interruptedFullDrainReacquisitionTask != nil { return "task_already_scheduled" }
            if freshHistoryOwnerBoundaryFailureLatched { return "fresh_owner_boundary_failure_latched" }
            if !deferInterruptedFullDrainForCurrentLiveConnection { return "no_deferred_drain_for_this_connection" }
            if offlineHistoricalSyncInProgress { return "history_sync_in_progress" }
            if AtriaPendingWorkoutIntent.isActiveForBLEContinuity() { return "explicit_workout_active" }
            if historicalConsumerMaterializationInFlight { return "consumer_materialization_in_flight" }
            if peripheral?.state != .connected { return "peripheral_not_connected" }
            if status != .connected { return "status_not_connected" }
            if connectedAt == nil { return "no_connected_at" }
            guard let lastAcceptedHRAt else { return "no_accepted_hr_this_connection" }
            if let connectedAt, lastAcceptedHRAt < connectedAt { return "accepted_hr_older_than_connection" }
            guard let scheduleAuthority else { return "authority_unreadable" }
            if scheduleAuthority.status != .draining {
                return "authority_status_\(scheduleAuthority.status.rawValue)"
            }
            return nil
        }()
        if let scheduleBlocker {
            AtriaDebugLog("ATRIADBG offline_sync status=reacquisition_not_scheduled reason=%@ blocker=%@",
                          reason, scheduleBlocker)
            return
        }
        guard let connectedAt, let authority = scheduleAuthority else { return }

        let fingerprint = Self.interruptedFullDrainGapFingerprint(authority.gap)
        guard Self.shouldScheduleInterruptedFullDrainReacquisition(
            activeExplicitWorkout: false,
            historySyncInProgress: false,
            consumerMaterializationInFlight: false,
            freshOwnerBoundaryFailureLatched:
                freshHistoryOwnerBoundaryFailureLatched,
            gapFingerprint: fingerprint
        ) else {
            AtriaDebugLog("ATRIADBG offline_sync status=reacquisition_not_scheduled reason=%@ blocker=policy_declined fingerprint=%@",
                          reason, fingerprint)
            return
        }

        let now = Date()
        let stableSeconds = now.timeIntervalSince(connectedAt)
        let wait = max(0, requiredInterruptedDrainStableInterval - stableSeconds)
        interruptedFullDrainReacquisitionTask = Task { @MainActor [weak self] in
            guard let self else { return }
            if wait > 0 { try? await Task.sleep(for: .seconds(wait)) }
            defer { self.interruptedFullDrainReacquisitionTask = nil }
            // Same rule as the scheduling guard: a refusal after the stability
            // wait must say which precondition lapsed. A link that drops
            // mid-wait is the common case and used to look identical to a
            // never-scheduled task.
            let firedAuthority = try? self.historicalFullDrainCoverageStore.load()
            let fireBlocker: String? = {
                if Task.isCancelled { return "task_cancelled" }
                if self.freshHistoryOwnerBoundaryFailureLatched {
                    return "fresh_owner_boundary_failure_latched"
                }
                if !self.deferInterruptedFullDrainForCurrentLiveConnection { return "defer_cleared_by_disconnect" }
                if self.offlineHistoricalSyncInProgress { return "history_sync_in_progress" }
                if AtriaPendingWorkoutIntent.isActiveForBLEContinuity() { return "explicit_workout_active" }
                if self.historicalConsumerMaterializationInFlight { return "consumer_materialization_in_flight" }
                if self.peripheral?.state != .connected { return "peripheral_not_connected" }
                if self.status != .connected { return "status_not_connected" }
                guard let currentConnectedAt = self.connectedAt else { return "no_connected_at" }
                guard let currentAcceptedAt = self.lastAcceptedHRAt else { return "no_accepted_hr_this_connection" }
                if currentAcceptedAt < currentConnectedAt { return "accepted_hr_older_than_connection" }
                guard let firedAuthority else { return "authority_unreadable" }
                if firedAuthority.status != .draining {
                    return "authority_status_\(firedAuthority.status.rawValue)"
                }
                return nil
            }()
            if let fireBlocker {
                AtriaDebugLog("ATRIADBG offline_sync status=reacquisition_not_fired reason=%@ blocker=%@ waited_s=%.1f",
                              reason, fireBlocker, wait)
                return
            }
            guard let currentConnectedAt = self.connectedAt,
                  let currentAuthority = firedAuthority else { return }
            let currentFingerprint = Self.interruptedFullDrainGapFingerprint(
                currentAuthority.gap
            )
            let now = Date()
            guard Self.shouldReacquireInterruptedFullDrain(
                stableLiveSeconds: now.timeIntervalSince(currentConnectedAt),
                requiredStableLiveSeconds: self.requiredInterruptedDrainStableInterval,
                activeExplicitWorkout: false,
                historySyncInProgress: false,
                consumerMaterializationInFlight: false,
                gapFingerprint: currentFingerprint,
                lastReacquisitionGapFingerprint: UserDefaults.standard.string(
                    forKey: OfflineSyncDefaults.interruptedFullDrainReacquisitionGapFingerprint
                ),
                lastReacquisitionAtUnix: UserDefaults.standard.object(
                    forKey: OfflineSyncDefaults.interruptedFullDrainReacquisitionAt
                ) as? Double,
                priorAttemptYieldedRows: UserDefaults.standard.bool(
                    forKey: OfflineSyncDefaults.lastDrainAttemptYieldedRows
                ),
                nowUnix: now.timeIntervalSince1970,
                cooldown: self.interruptedFullDrainReacquisitionCooldown
            ) else {
                AtriaDebugLog("ATRIADBG offline_sync status=reacquisition_not_fired reason=%@ blocker=policy_declined stable_s=%.1f required_s=%.1f yielded_rows=%d fingerprint=%@",
                              reason,
                              now.timeIntervalSince(currentConnectedAt),
                              self.requiredInterruptedDrainStableInterval,
                              UserDefaults.standard.bool(
                                  forKey: OfflineSyncDefaults.lastDrainAttemptYieldedRows
                              ) ? 1 : 0,
                              currentFingerprint)
                return
            }

            UserDefaults.standard.set(
                currentFingerprint,
                forKey: OfflineSyncDefaults.interruptedFullDrainReacquisitionGapFingerprint
            )
            UserDefaults.standard.set(
                now.timeIntervalSince1970,
                forKey: OfflineSyncDefaults.interruptedFullDrainReacquisitionAt
            )
            self.deferInterruptedFullDrainForCurrentLiveConnection = false
            UserDefaults.standard.set("interrupted_full_drain_reacquisition_started",
                                      forKey: OfflineSyncDefaults.lastStatus)
            UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=interrupted_full_drain_reacquisition_started reason=%@ stable_s=%.1f action=reacquire_existing_gap_once_no_new_protocol",
                          reason,
                          now.timeIntervalSince(currentConnectedAt))
            _ = self.requestOfflineHistoricalSyncIfNeeded(
                reason: "interrupted_full_drain_bounded_reacquisition",
                force: true,
                explicitResearchRequest: true
            )
        }
    }

    /// Reconcile the persisted authority after a process relaunch.  This is
    /// deliberately separate from the pending-request path above so an
    /// unrelated launch recovery cannot consume the in-memory handoff and
    /// strand a durable `.draining` authority forever.  The same 60-second
    /// stable-live window and persisted five-minute cooldown remain the sole
    /// path to a new history owner.
    private func rearmPersistedInterruptedFullDrainAfterFreshHRIfNeeded(
        reason: String,
        callbackSource: AtriaBLECallbackEpochFence.Source
    ) {
        let currentPeripheral = peripheral
        let currentConnectedAt = connectedAt
        let exactConnection = currentPeripheral?.identifier
            == callbackSource.peripheralID
            && currentPeripheral.map(ObjectIdentifier.init)
                == callbackSource.peripheralObjectID
            && currentConnectedAt != nil
        let linkLive = currentPeripheral?.state == .connected
            && status == .connected
        let freshLiveSample: Bool = {
            guard let currentConnectedAt, let lastAcceptedHRAt else {
                return false
            }
            return lastAcceptedHRAt >= currentConnectedAt
        }()
        let workoutActive = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        let authorityStatus = lastPersistedDrainAuthorityStatus
        let diagnostic = "link=\(linkLive ? 1 : 0) fresh=\(freshLiveSample ? 1 : 0) workout=\(workoutActive ? 1 : 0) sync=\(offlineHistoricalSyncInProgress ? 1 : 0) materializing=\(historicalConsumerMaterializationInFlight ? 1 : 0) authority=\(authorityStatus) defer=\(deferInterruptedFullDrainForCurrentLiveConnection ? 1 : 0)"
        if diagnostic != lastPersistedDrainRearmDiagnostic {
            lastPersistedDrainRearmDiagnostic = diagnostic
            UserDefaults.standard.set(diagnostic,
                                      forKey: "atria.offlineSync.persistedDrainRearmDiagnostic")
            AtriaDebugLog("ATRIADBG offline_sync persisted_drain_rearm %@", diagnostic)
        }
        let eligible = linkLive
            && freshLiveSample
            && !workoutActive
            && !offlineHistoricalSyncInProgress
            && !historicalConsumerMaterializationInFlight
            && !freshHistoryOwnerBoundaryFailureLatched
            && exactConnection
            && bleCallbackEpochFence.owns(source: callbackSource)
        let now = Date()
        guard persistedDrainAuthorityProbeGate.begin(
            epoch: callbackSource.epoch,
            now: now,
            eligible: eligible
        ) else { return }

        persistedDrainAuthorityProbeGeneration &+= 1
        let probeGeneration = persistedDrainAuthorityProbeGeneration
        guard let probeConnectedAt = currentConnectedAt else {
            persistedDrainAuthorityProbeGate.abandon(
                epoch: callbackSource.epoch
            )
            return
        }
        persistedDrainAuthorityProbeTask?.cancel()
        let coverageStore = historicalFullDrainCoverageStore
        persistedDrainAuthorityProbeTask = Task { @MainActor [weak self] in
            let loaded = await Task.detached(priority: .utility) {
                do {
                    return AtriaBLEPersistedDrainAuthorityProbeResult.loaded(
                        try coverageStore.load()
                    )
                } catch {
                    return .failed(String(describing: error))
                }
            }.value

            guard let self,
                  probeGeneration == self.persistedDrainAuthorityProbeGeneration else {
                return
            }
            self.persistedDrainAuthorityProbeTask = nil
            guard !Task.isCancelled,
                  self.persistedDrainProbeContextIsCurrent(
                      callbackSource: callbackSource,
                      connectedAt: probeConnectedAt
                  ),
                  self.persistedDrainRearmIsEligibleForCurrentConnection(
                      callbackSource: callbackSource,
                      connectedAt: probeConnectedAt
                  ) else {
                self.persistedDrainAuthorityProbeGate.abandon(
                    epoch: callbackSource.epoch
                )
                return
            }

            switch loaded {
            case .loaded(let authority):
                self.lastPersistedDrainAuthorityStatus =
                    authority?.status.rawValue ?? "none"
                let handled = await self.applyPersistedInterruptedFullDrainAuthority(
                    authority,
                    reason: reason,
                    callbackSource: callbackSource,
                    connectedAt: probeConnectedAt,
                    probeGeneration: probeGeneration
                )
                self.persistedDrainAuthorityProbeGate.finish(
                    epoch: callbackSource.epoch,
                    succeeded: handled,
                    now: Date(),
                    retryDelay: Self.persistedDrainAuthorityProbeRetryDelay
                )
            case .failed(let detail):
                self.persistedDrainAuthorityProbeGate.finish(
                    epoch: callbackSource.epoch,
                    succeeded: false,
                    now: Date(),
                    retryDelay: Self.persistedDrainAuthorityProbeRetryDelay
                )
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=persisted_drain_probe_failed reason=%@ error=%@ action=retry_off_main_after_cooldown",
                    reason,
                    detail
                )
            }
        }
    }

    private func persistedDrainProbeContextIsCurrent(
        callbackSource: AtriaBLECallbackEpochFence.Source,
        connectedAt probeConnectedAt: Date
    ) -> Bool {
        guard let currentPeripheral = peripheral else { return false }
        return bleCallbackEpochFence.owns(source: callbackSource)
            && currentPeripheral.identifier == callbackSource.peripheralID
            && ObjectIdentifier(currentPeripheral)
                == callbackSource.peripheralObjectID
            && connectedAt == probeConnectedAt
    }

    private func persistedDrainRearmIsEligibleForCurrentConnection(
        callbackSource: AtriaBLECallbackEpochFence.Source,
        connectedAt probeConnectedAt: Date
    ) -> Bool {
        guard persistedDrainProbeContextIsCurrent(
                  callbackSource: callbackSource,
                  connectedAt: probeConnectedAt
              ),
              peripheral?.state == .connected,
              status == .connected,
              let lastAcceptedHRAt,
              lastAcceptedHRAt >= probeConnectedAt else { return false }
        return !AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
            && !offlineHistoricalSyncInProgress
            && !historicalConsumerMaterializationInFlight
            && !freshHistoryOwnerBoundaryFailureLatched
    }

    @discardableResult
    private func applyPersistedInterruptedFullDrainAuthority(
        _ authority: AtriaHistoricalFullDrainCoverageStore.Authority?,
        reason: String,
        callbackSource: AtriaBLECallbackEpochFence.Source,
        connectedAt probeConnectedAt: Date,
        probeGeneration: UInt64
    ) async -> Bool {
        guard probeGeneration == persistedDrainAuthorityProbeGeneration,
              persistedDrainProbeContextIsCurrent(
                  callbackSource: callbackSource,
                  connectedAt: probeConnectedAt
              ) else { return false }
        let authorityStatus = authority?.status.rawValue ?? "none"
        let diagnostic = "link=1 fresh=1 workout=0 sync=0 materializing=0 authority=\(authorityStatus) defer=\(deferInterruptedFullDrainForCurrentLiveConnection ? 1 : 0)"
        if diagnostic != lastPersistedDrainRearmDiagnostic {
            lastPersistedDrainRearmDiagnostic = diagnostic
            UserDefaults.standard.set(
                diagnostic,
                forKey: "atria.offlineSync.persistedDrainRearmDiagnostic"
            )
            AtriaDebugLog("ATRIADBG offline_sync persisted_drain_rearm %@", diagnostic)
        }
        if interruptedFullDrainReacquisitionPendingAfterTransportLoss,
           authority?.status != .draining {
            // A terminal or absent authority can never reacquire BLE. Fold the
            // old accepted-HR transport-loss probe into this one off-main
            // result so the hot path has no second canonical store load.
            interruptedFullDrainReacquisitionPendingAfterTransportLoss = false
        }
        guard let authority else { return true }

        if interruptedFullDrainReacquisitionPendingAfterTransportLoss,
           authority.status == .draining {
            interruptedFullDrainReacquisitionPendingAfterTransportLoss = false
            if persistedDrainResumeAllowed {
                deferInterruptedFullDrainForCurrentLiveConnection = true
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=interrupted_full_drain_live_recovery_armed reason=%@ authority=%@ action=wait_stable_live_then_reacquire_existing_gap_once",
                    reason,
                    authority.authorityIdentifier
                )
                scheduleInterruptedFullDrainReacquisitionIfNeeded(
                    reason: "interrupted_full_drain_transport_loss"
                )
                return true
            }
            logPersistedDrainResumePaused(
                reason: reason,
                action: "no_live_connection_claim_range_loss_lane_free"
            )
        }

        // The coverage authority is fsynced alongside every accepted history
        // boundary and is the ownership record being resumed.  A compacted or
        // migrated secondary gap-ledger index must not be allowed to strand
        // that authority after a process restart; `pending` on this exact
        // authority remains the durable proof that it has not completed.
        let exactGapStillPending = authority.gap.pending
        guard Self.shouldRearmPersistedInterruptedFullDrainFromFreshHR(
            rangeLossBackfillPending: UserDefaults.standard.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
            ),
            authorityStatus: authority.status,
            exactGapFingerprintStillPending: exactGapStillPending,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            historySyncInProgress: offlineHistoricalSyncInProgress,
            consumerMaterializationInFlight: historicalConsumerMaterializationInFlight
        ) else { return true }

        // Live-first ordering: history recovery must never seize a link that
        // is still proving itself. The hold is no longer unconditional —
        // locked live reconnect was physically accepted (3 consecutive passes,
        // 2026-07-24, commit 0c1fcff) — so this path now arms the SAME bounded
        // reacquisition every other resume uses: >=60s stable live HR plus
        // the persisted five-minute cooldown, at most one attempt per gap
        // fingerprint per cooldown. Cancelling the timer here on every
        // accepted-HR batch was the freeze that kept a durable `.draining`
        // authority held forever (observed stable_s=600 with no action).
        let now = Date()
        let stableSeconds = now.timeIntervalSince(probeConnectedAt)
        // Only claim this connection for a persisted drain if that drain can
        // actually run. While the resume lane is paused nothing will ever
        // consume the claim, and the flag would otherwise latch on every
        // accepted-HR sample and permanently starve the ordinary range-loss
        // backfill lane, which gates on it at
        // `scheduleRangeLossBackfillIfNeeded` and
        // `attemptQualifiedRangeLossBackfillAfterAcceptedHRIfNeeded`.
        guard persistedDrainResumeAllowed else {
            guard probeGeneration == persistedDrainAuthorityProbeGeneration,
                  persistedDrainProbeContextIsCurrent(
                      callbackSource: callbackSource,
                      connectedAt: probeConnectedAt
                  ) else { return false }
            let coverageStore = historicalFullDrainCoverageStore
            let authorityIdentifier = authority.authorityIdentifier
            let recoveryMutationGeneration =
                persistedDrainRecoveryMutationGeneration
            let releaseResult = await Task.detached(priority: .utility) {
                do {
                    return AtriaBLEPersistedDrainAuthorityReleaseResult.released(
                        try coverageStore
                            .releaseInterruptedDrainingAuthorityWhenResumeDisabled(
                                authorityIdentifier: authorityIdentifier
                            )
                    )
                } catch {
                    return .failed(String(describing: error))
                }
            }.value
            guard probeGeneration == persistedDrainAuthorityProbeGeneration,
                  persistedDrainProbeContextIsCurrent(
                      callbackSource: callbackSource,
                      connectedAt: probeConnectedAt
                  ),
                  persistedDrainRearmIsEligibleForCurrentConnection(
                      callbackSource: callbackSource,
                      connectedAt: probeConnectedAt
                  ),
                  !persistedDrainResumeAllowed,
                  persistedDrainRecoveryMutationGeneration
                    == recoveryMutationGeneration else {
                return false
            }
            switch releaseResult {
            case .released(let released):
                logPersistedDrainResumePaused(
                    reason: reason,
                    action: released
                        ? "release_stale_transport_authority_keep_gap_and_rows"
                        : "no_live_connection_claim_range_loss_lane_free"
                )
                if released {
                    // The production full-flash resume lane is disabled
                    // because it cannot target this gap. Do not immediately
                    // turn the released transport receipt into another full
                    // drain. The exact gap remains in its durable ledger and
                    // continues to present as missing coverage.
                    rangeLossBackfillTask?.cancel()
                    rangeLossBackfillTask = nil
                    pendingOfflineHistoricalSyncRequest = nil
                    pendingConnectedMotionBankSchedulingTicketID = nil
                    UserDefaults.standard.set(
                        false,
                        forKey:
                            OfflineSyncDefaults.rangeLossBackfillPending
                    )
                    assignIfChanged(\.rangeLossBackfillPending, false)
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        let published =
                            await self.requestAndAwaitRecoveredDataPublication?(
                                "disabled_interrupted_drain_partial_metrics"
                            ) ?? false
                        UserDefaults.standard.set(
                            published
                                ? "partial_history_published_gap_preserved"
                                : "partial_history_publication_deferred",
                            forKey: OfflineSyncDefaults.lastStatus
                        )
                        self.onHistoricalTransportOwnershipReleased?(
                            "interrupted_gap_uncovered"
                        )
                    }
                }
            case .failed(let detail):
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=interrupted_authority_release_failed reason=%@ authority=%@ error=%@ action=retain_fail_closed",
                    reason,
                    authorityIdentifier,
                    detail
                )
                return false
            }
            return true
        }
        deferInterruptedFullDrainForCurrentLiveConnection = true
        if interruptedFullDrainReacquisitionTask == nil {
            UserDefaults.standard.set("deferred_awaiting_stable_live_reacquisition",
                                      forKey: OfflineSyncDefaults.lastStatus)
            UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_awaiting_stable_live_reacquisition reason=%@ authority=%@ stable_s=%.1f action=arm_bounded_reacquisition_preserve_live_link",
                          reason,
                          authority.authorityIdentifier,
                          stableSeconds)
        }
        scheduleInterruptedFullDrainReacquisitionIfNeeded(
            reason: "persisted_drain_stable_live_\(reason)"
        )
        return true
    }

    /// A full-drain authority is a durable transport transaction, not merely a
    /// diagnostic snapshot. If iOS replaces the process before HISTORY_COMPLETE,
    /// ordinary launch must reacquire the history owner from the already-fsynced
    /// admission cursor. Otherwise the app silently falls back to live HR and
    /// leaves the missing window pending forever unless a Mac supplies a debug
    /// launch argument. Only `.draining` is eligible here: terminal authorities
    /// resume their publication journal elsewhere and must never seize BLE again.
    private func restoreInterruptedFullDrainLaunchIntentIfNeeded(
        defaults: UserDefaults
    ) {
        guard persistedDrainResumeAllowed else {
            logPersistedDrainResumePaused(reason: "interrupted_full_drain_relaunch",
                                          action: "preserve_live_no_cutover")
            return
        }
        let authority = try? historicalFullDrainCoverageStore.load()
        let exactGapFingerprintStillPending = authority.flatMap { authority in
            UUID(uuidString: authority.gap.gapIdentifier).flatMap { gapID in
                AtriaHistoricalGapLedger.recoveryCandidate(
                    id: gapID,
                    startUnix: authority.gap.startUnix,
                    endUnix: authority.gap.endUnix,
                    reason: authority.gap.reason
                )
            }
        } != nil
        guard Self.shouldResumeInterruptedFullDrainAtLaunch(
            rangeLossBackfillPending: defaults.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
            ),
            authorityStatus: authority?.status,
            exactGapFingerprintStillPending: exactGapFingerprintStillPending
        ) else { return }
        explicitHistoryLaunchIntentPending = true
        retainPendingOfflineHistoricalSyncRequest(
            reason: "interrupted_full_drain_relaunch",
            force: true,
            explicitRequest: true
        )
        defaults.set("pending_interrupted_full_drain_relaunch",
                     forKey: OfflineSyncDefaults.lastStatus)
        defaults.set("interrupted_full_drain_relaunch",
                     forKey: OfflineSyncDefaults.lastReason)
        AtriaDebugLog("ATRIADBG offline_sync status=pending_interrupted_full_drain_relaunch authority=%@ action=await_current_epoch_hr_then_resume_durable_cursor",
                      authority?.authorityIdentifier ?? "none")
    }

    nonisolated static func shouldDeferHistoricalSyncUntilArchiveWarmReady(
        warmState: HistoricalArchiveWarmState,
        syncInProgress: Bool
    ) -> Bool {
        warmState != .ready && !syncInProgress
    }

    /// A crash can leave a `.draining` authority after its exact gap row was
    /// resolved or compacted. That authority no longer owns recoverable work
    /// and must not block the next real exact-gap request. Terminal authorities
    /// remain immutable; a still-pending matching fingerprint is never cleared.
    @discardableResult
    private func reconcileStaleDrainingFullDrainAuthority(
        _ authority: AtriaHistoricalFullDrainCoverageStore.Authority,
        reason: String
    ) -> Bool {
        guard authority.status == .draining,
              let gapID = UUID(uuidString: authority.gap.gapIdentifier),
              AtriaHistoricalGapLedger.recoveryCandidate(
                  id: gapID,
                  startUnix: authority.gap.startUnix,
                  endUnix: authority.gap.endUnix,
                  reason: authority.gap.reason
              ) == nil else {
            return false
        }
        let windows = AtriaHistoricalGapLedger.windows()
        do {
            let cleared: Bool
            if let changed = windows.first(where: { $0.id == gapID }),
               let changedEnd = changed.end {
                cleared = try historicalFullDrainCoverageStore
                    .abandonDrainingAuthorityIfGapFingerprintChanged(
                        gapIdentifier: authority.gap.gapIdentifier,
                        observedStartUnix: changed.start.timeIntervalSince1970,
                        observedEndUnix: changedEnd.timeIntervalSince1970,
                        observedReason: changed.reason
                    )
            } else if !windows.contains(where: { $0.id == gapID }) {
                try historicalFullDrainCoverageStore
                    .clearUnresolvedAuthorityIfGapNoLongerPending(
                        gapIdentifier: authority.gap.gapIdentifier
                    )
                cleared = try historicalFullDrainCoverageStore.load() == nil
            } else {
                cleared = false
            }
            if cleared {
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_authority status=stale_draining_cleared reason=%@ gap=%@ action=allow_next_exact_gap_no_transport_claim",
                    reason,
                    authority.gap.gapIdentifier
                )
            }
            return cleared
        } catch {
            AtriaDebugLog(
                "ATRIADBG historical_full_drain_authority status=stale_draining_clear_failed reason=%@ gap=%@ error=%@ action=retain_fail_closed",
                reason,
                authority.gap.gapIdentifier,
                String(describing: error)
            )
            return false
        }
    }

    enum TerminalHistoryRequestDisposition: Equatable {
        case continueNormally
        case resumeLocalPublicationAndReturn
        case resumeLocalPublicationAndContinueMotionBank
        case resumeLocalPublicationAndContinueRawDrain
    }

    /// A failed terminal *local* projection must release a newer, already
    /// authorized motion-bank request.  The old terminal journal remains the
    /// authority for its own raw rows and consumers; this only prevents that
    /// local retry from indefinitely monopolising the BLE admission lane.
    enum TerminalMaterializationReleaseDisposition: Equatable {
        case noAction
        case retainTerminalJournal
        case resumePendingMotionBank
        case scheduleRangeLossBackfill
    }

    enum HistoryCapabilityQualificationCallbackDisposition: Equatable {
        case ignore
        case requestTargetedDiscovery
        case qualified
        case terminalFailure
    }

    /// Service discovery is a two-step qualification when the first callback
    /// contains only the standard services. Once the targeted callback has
    /// completed without the proprietary service (or fails), that attempt is
    /// terminal so a later exact motion ticket can intentionally discover
    /// again instead of inheriting a stale `discoveryIssued` latch.
    nonisolated static func historyCapabilityQualificationCallbackDisposition(
        callbackMatchesQualification: Bool,
        targetedDiscoveryIssued: Bool,
        hasStrapService: Bool,
        hasError: Bool
    ) -> HistoryCapabilityQualificationCallbackDisposition {
        guard callbackMatchesQualification else { return .ignore }
        if hasError { return .terminalFailure }
        if hasStrapService { return .qualified }
        return targetedDiscoveryIssued
            ? .terminalFailure
            : .requestTargetedDiscovery
    }

    /// Durable history debt must never manufacture a gap in the live stream it
    /// is meant to repair. This subordinate policy distinguishes automatic
    /// work from attended intent, while the global realtime-continuity gate
    /// keeps every request queued until the live owner reaches a natural
    /// boundary.
    nonisolated static func shouldDeferAutomaticHistoryForLiveContinuity(
        linkConnected: Bool,
        syncInProgress: Bool,
        attendedRequest: Bool,
        nonDestructiveConnectedHistoryAllowed: Bool = false
    ) -> Bool {
        linkConnected
            && !syncInProgress
            && !attendedRequest
            && !nonDestructiveConnectedHistoryAllowed
    }

    /// Failure of an optional, connected motion-bank read is not a reason to
    /// tear down the realtime transport. The exception is scoped to the exact
    /// active history generation and a still-connected link; every ordinary
    /// history owner keeps the existing fail-closed disconnect semantics.
    nonisolated static func shouldFinishHistoricalFailureWithoutDisconnect(
        preservesConnectedRealtimeOwner: Bool,
        syncInProgress: Bool,
        expectedGeneration: UInt64,
        activeGeneration: UInt64,
        linkConnected: Bool
    ) -> Bool {
        preservesConnectedRealtimeOwner
            && syncInProgress
            && expectedGeneration == activeGeneration
            && linkConnected
    }

    enum ConnectedMotionBankHistoryBudgetDisposition: Equatable {
        case keepServing
        case finishForPowerPressure
        case finishForLiveHeartRateSilence
        case finishForAbsoluteBudget
    }

    nonisolated static let connectedMotionBankHistoryPowerRetryInterval:
        TimeInterval = 60

    /// Same-link history is optional work. Genuine heat and Low Power Mode both
    /// fail closed for a new/active motion-bank generation; standard 2A37 and
    /// the low-bandwidth present-capture bank remain the priority owners.
    nonisolated static func shouldParkConnectedMotionBankHistoryForPowerPressure(
        thermalState: ProcessInfo.ThermalState,
        lowPowerModeEnabled: Bool
    ) -> Bool {
        lowPowerModeEnabled
            || thermalState == .serious
            || thermalState == .critical
    }

    nonisolated static func connectedMotionBankHistoryPowerRetryNotBefore(
        existing: Date?,
        now: Date,
        interval: TimeInterval = connectedMotionBankHistoryPowerRetryInterval
    ) -> Date {
        max(
            existing ?? .distantPast,
            now.addingTimeInterval(max(1, interval))
        )
    }

    nonisolated static func shouldFinishConnectedMotionBankHistoryAtACKBoundary(
        applicationIsActive: Bool,
        exactMotionBankAuthorityActive: Bool
    ) -> Bool {
        !applicationIsActive && exactMotionBankAuthorityActive
    }

    /// The same-link motion-bank lane is opportunistic. It never gets the
    /// generic 30-minute productive-history allowance: continuous standard HR
    /// is the primary payload and the bounded bank ticket can retry later.
    nonisolated static func connectedMotionBankHistoryBudgetDisposition(
        startedAt: Date,
        lastAcceptedHeartRateAt: Date?,
        now: Date,
        liveSilenceLimit: TimeInterval,
        absoluteLimit: TimeInterval,
        powerPressureActive: Bool = false
    ) -> ConnectedMotionBankHistoryBudgetDisposition {
        guard !powerPressureActive else {
            return .finishForPowerPressure
        }
        guard now.timeIntervalSince(startedAt) < absoluteLimit else {
            return .finishForAbsoluteBudget
        }
        let latestLiveProof = max(lastAcceptedHeartRateAt ?? startedAt, startedAt)
        guard now.timeIntervalSince(latestLiveProof) < liveSilenceLimit else {
            return .finishForLiveHeartRateSilence
        }
        return .keepServing
    }

    private func recordConnectedMotionBankBackgroundPageCooldown(now: Date) {
        let retryNotBefore = now.addingTimeInterval(
            Self.workoutHistoricalMotionBankMinimumOffloadInterval
        )
        connectedMotionBankHistoryAdmissionRetryNotBefore = max(
            connectedMotionBankHistoryAdmissionRetryNotBefore ?? .distantPast,
            retryNotBefore
        )
        // Reuse the existing durable per-ticket cadence fence. The generation
        // already spent its ledger attempt before transport began, and the
        // active-ticket binding remains intact, so relaunch admission applies
        // `historicalMotionBankOffloadCadenceEligible` to this exact retry.
        UserDefaults.standard.set(
            now.timeIntervalSince1970,
            forKey: Self.workoutHistoricalMotionBankLastOffloadStartedAtKey
        )
    }

    nonisolated static func terminalMaterializationReleaseDisposition(
        wasInFlight: Bool,
        rangeLossBackfillPending: Bool,
        offlineHistoricalSyncInProgress: Bool,
        authorityStatus: AtriaHistoricalFullDrainCoverageStore.Authority.Status?,
        hasPendingMotionBankRequest: Bool
    ) -> TerminalMaterializationReleaseDisposition {
        guard wasInFlight,
              rangeLossBackfillPending,
              !offlineHistoricalSyncInProgress else {
            return .noAction
        }
        switch authorityStatus {
        case .historyComplete?, .coverageProven?,
             .gapResolvedConsumersPending?, .consumersCommitted?:
            return hasPendingMotionBankRequest
                ? .resumePendingMotionBank
                : .retainTerminalJournal
        case .draining?, .resolved?, nil:
            return .scheduleRangeLossBackfill
        }
    }

    /// A terminal exact-gap journal owns only its remaining local publication,
    /// not every future piece of strap history. In particular, WHOOP 4's
    /// low-bandwidth 0x69 bank closes into a durable, same-strap ticket before
    /// it asks for transport. Blocking that ticket behind an unrelated
    /// terminal journal leaves captured all-day motion permanently parked at
    /// `attempts=0`.
    ///
    /// Ordinary recovery requests still stop at the terminal journal and
    /// resume its local materialization. The sole pass-through is the
    /// already-authorized motion-bank ticket; all of its later admission,
    /// thermal, workout, reconnect and fresh-HR guards remain in force.
    /// A terminal journal whose consumer projection is still pending (its raw
    /// rows + coverage proof are durable, but `recordCommittedConsumers` has not
    /// run because that materialization is foreground-gated) used to block every
    /// non-motion-bank transport request — including the range-loss catch-up
    /// lane. That is the drain-keeping stall: after any background drain reaches
    /// terminal, the parked authority refused all further catch-up until the app
    /// was foregrounded, so a reconnect-after-long-gap backlog crawled instead of
    /// clearing. The catch-up lane is RAW-ONLY (binding nil, forward-from-cursor
    /// FIFO `0x16[0x00]`); it never mutates the parked authority's coverage or
    /// event identity, so admitting it in parallel with the deferred local
    /// publication is safe. The motion-bank pass-through keeps precedence.
    nonisolated static func terminalHistoryRequestDisposition(
        authorityStatus: AtriaHistoricalFullDrainCoverageStore.Authority.Status,
        explicitPostWorkoutBankRequest: Bool,
        rangeLossRawDrainPending: Bool = false
    ) -> TerminalHistoryRequestDisposition {
        switch authorityStatus {
        case .historyComplete, .coverageProven,
             .gapResolvedConsumersPending, .consumersCommitted:
            if explicitPostWorkoutBankRequest {
                return .resumeLocalPublicationAndContinueMotionBank
            }
            if rangeLossRawDrainPending {
                return .resumeLocalPublicationAndContinueRawDrain
            }
            return .resumeLocalPublicationAndReturn
        case .draining, .resolved:
            return .continueNormally
        }
    }

    @discardableResult
    func requestOfflineHistoricalSyncIfNeeded(
        reason: String,
        force: Bool = false,
        allowConnectedAutomaticHandoff: Bool = false,
        explicitResearchRequest: Bool = false,
        explicitPostWorkoutBankRequest: Bool = false,
        preserveConnectedRealtimeOwner: Bool = false
    ) -> Bool {
        let previousMotionBankAuthorization =
            transientMotionBankRequestAuthorization
        let previousRealtimeOwnerPreservation =
            transientConnectedRealtimeOwnerPreservation
        transientMotionBankRequestAuthorization =
            previousMotionBankAuthorization
                || explicitPostWorkoutBankRequest
        transientConnectedRealtimeOwnerPreservation =
            previousRealtimeOwnerPreservation
                || preserveConnectedRealtimeOwner
        defer {
            transientMotionBankRequestAuthorization =
                previousMotionBankAuthorization
            transientConnectedRealtimeOwnerPreservation =
                previousRealtimeOwnerPreservation
        }
        guard !readOnlyHistoryCaptureRequested else {
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=read_only_capture_owns_transport action=no_production_commands",
                          reason)
            return false
        }
        if motionHandshakeDiagnostic != nil {
            recordMotionHandshakeEvidence(event: "offline_sync_blocked", detail: reason)
            return false
        }
        let defaults = UserDefaults.standard
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        let connectedLink = peripheral?.state == .connected
        let connectingLink = peripheral?.state == .connecting
        let connectedMotionBankRequestAuthority =
            transientConnectedMotionBankHistoryRequestAuthority.flatMap {
                authority -> ConnectedMotionBankHistoryRequestAuthority? in
                guard let peripheral,
                      connectedMotionBankHistoryRequestAuthorityIsValid(
                          authority,
                          peripheral: peripheral
                      ) else {
                    return nil
                }
                return authority
            }
        let connectedRawHistoryCatchUpRequestAuthority =
            transientConnectedRawHistoryCatchUpRequestAuthority.flatMap {
                authority -> ConnectedRawHistoryCatchUpRequestAuthority? in
                guard let peripheral,
                      connectedRawHistoryCatchUpRequestAuthorityIsValid(
                        authority,
                        peripheral: peripheral,
                        forActiveGeneration: false
                      ) else { return nil }
                return authority
            }
        let exactConnectedRealtimePreservingRequest =
            connectedMotionBankRequestAuthority != nil
                || connectedRawHistoryCatchUpRequestAuthority != nil
        let exactRealtimeEpochOwned = bleCallbackEpochFence.hasActiveOwner
        var realtimeConnectInterestIDs = Set<UUID>()
        if let peripheralID = peripheral?.identifier {
            realtimeConnectInterestIDs.insert(peripheralID)
        }
        if let savedIDString = defaults.string(
            forKey: LinkDefaults.savedPeripheralUUID
        ), let savedID = UUID(uuidString: savedIDString) {
            realtimeConnectInterestIDs.insert(savedID)
        }
        let standingRealtimeConnectOwned = connectedPeripheralRetainer
            .hasRetainedConnectInterest(
                peripheralIDs: realtimeConnectInterestIDs
            )
        let explicitUserRequest = Self.isExplicitUserOfflineSyncReason(reason)
        let attendedHistoricalRequest =
            explicitUserRequest || explicitResearchRequest
        // A completed workout owns a finite banked-motion transaction. Its
        // close-and-offload is as intentional as a user Sync tap, but is
        // neither a research command nor generic background recovery. This
        // authority exists only after the durable workout intent has ended.
        let explicitHistoricalRequest =
            attendedHistoricalRequest || explicitPostWorkoutBankRequest
        if Self.shouldDeferAutomaticHistoryForLiveContinuity(
            linkConnected: connectedLink,
            syncInProgress: offlineHistoricalSyncInProgress,
            attendedRequest: attendedHistoricalRequest,
            nonDestructiveConnectedHistoryAllowed:
                exactConnectedRealtimePreservingRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false,
                explicitPostWorkoutBankRequest:
                    explicitPostWorkoutBankRequest
            )
            defaults.set(
                "deferred_live_continuity_owner",
                forKey: OfflineSyncDefaults.lastStatus
            )
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_live_continuity_owner reason=%@ post_workout=%d action=retain_exact_request_no_cancel_no_history_command",
                reason,
                explicitPostWorkoutBankRequest ? 1 : 0
            )
            return false
        }
        if gate2FullDrainProofEnabled {
            guard explicitHistoricalRequest,
                  let requestedGapID = gate2FullDrainRequestedGapID,
                  AtriaHistoricalGapLedger.allClosedRecoveryCandidates()
                    .contains(where: { $0.window.id == requestedGapID }) else {
                AtriaDebugLog(
                    "ATRIADBG gate2_full_drain status=rejected reason=missing_explicit_exact_gap gap=%@ action=no_transport",
                    gate2FullDrainRequestedGapID?.uuidString ?? "none"
                )
                return false
            }
            if let authority = try? historicalFullDrainCoverageStore.load(),
               authority.status == .draining,
               authority.gap.gapIdentifier.caseInsensitiveCompare(
                   requestedGapID.uuidString
               ) != .orderedSame {
                _ = reconcileStaleDrainingFullDrainAuthority(
                    authority,
                    reason: "gate2_requested_exact_gap"
                )
            }
            // An attended Gate 2 run names one exact gap on the command line.
            // A process-killed drain for another still-pending gap must not
            // silently replace that operator-selected target. Relinquish only
            // the interrupted transport ownership record; the older gap and
            // every row already fsynced for it remain intact and eligible for
            // a later bounded attempt.
            if let authority = try? historicalFullDrainCoverageStore.load(),
               authority.status == .draining,
               authority.gap.gapIdentifier.caseInsensitiveCompare(
                    requestedGapID.uuidString
               ) != .orderedSame {
                do {
                    let released = try historicalFullDrainCoverageStore
                        .releaseInterruptedDrainingAuthorityWhenResumeDisabled(
                            authorityIdentifier: authority.authorityIdentifier
                        )
                    if released {
                        interruptedFullDrainReacquisitionTask?.cancel()
                        interruptedFullDrainReacquisitionTask = nil
                        deferInterruptedFullDrainForCurrentLiveConnection = false
                        interruptedFullDrainReacquisitionPendingAfterTransportLoss = false
                        AtriaDebugLog(
                            "ATRIADBG gate2_full_drain status=previous_authority_released gap=%@ previous_gap=%@ action=preserve_previous_gap_and_rows_run_selected_exact_gap",
                            requestedGapID.uuidString,
                            authority.gap.gapIdentifier
                        )
                    }
                } catch {
                    AtriaDebugLog(
                        "ATRIADBG gate2_full_drain status=previous_authority_release_failed gap=%@ previous_gap=%@ error=%@ action=retain_fail_closed",
                        requestedGapID.uuidString,
                        authority.gap.gapIdentifier,
                        String(describing: error)
                    )
                }
            }
            if let authority = try? historicalFullDrainCoverageStore.load(),
               authority.status == .draining,
               authority.gap.gapIdentifier.caseInsensitiveCompare(
                    requestedGapID.uuidString
               ) != .orderedSame {
                AtriaDebugLog(
                    "ATRIADBG gate2_full_drain status=rejected reason=other_drain_authority gap=%@ authority_gap=%@ action=no_transport",
                    requestedGapID.uuidString,
                    authority.gap.gapIdentifier
                )
                return false
            }
        }
        // A terminal full-drain journal is no longer a BLE problem. Its raw
        // rows and coverage proof are already durable; only local consumer
        // projection/publication remains. Re-entering the normal recovery
        // path here used to age into a fresh-owner cutover, disconnect a
        // healthy live link, and create another gap while trying to settle the
        // previous one. Keep the radio with live HR and resume the fsynced
        // journal locally instead.
        var strandedDrainingAuthorityResumeAdmitted = false
        if let authority = try? historicalFullDrainCoverageStore.load() {
            if connectedRawHistoryCatchUpRequestAuthority != nil,
               authority.status == .draining {
                // A process-local raw token may start a new cursor slice; it may
                // not impersonate or replace a persisted exact drain authority.
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=connected_raw_catch_up_deferred reason=%@ blocker=persisted_draining_authority action=no_generation_no_command_no_pending_authority",
                    reason
                )
                return false
            }
            // P0: any fresh backlog (not just the range-loss ticket) admits
            // the raw-only catch-up lane past a parked terminal authority —
            // the lane's safety argument is unchanged (forward-from-cursor
            // FIFO, never mutates the parked journal's coverage/identity).
            let rangeLossRawDrainPending = strapBacklogPendingForCatchUp()
            let terminalDisposition = Self.terminalHistoryRequestDisposition(
                authorityStatus: authority.status,
                explicitPostWorkoutBankRequest: explicitPostWorkoutBankRequest,
                rangeLossRawDrainPending: rangeLossRawDrainPending
            )
            switch terminalDisposition {
            case .resumeLocalPublicationAndReturn,
                 .resumeLocalPublicationAndContinueMotionBank,
                 .resumeLocalPublicationAndContinueRawDrain:
                defaults.set(
                    "terminal_consumer_materialization",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                if exactConnectedRealtimePreservingRequest {
                    // A same-link glance/offload has a strict compact-only hot
                    // path. A parked terminal journal may resume later through
                    // its ordinary foreground lane; it cannot make this BLE
                    // request launch a whole-archive consumer projection.
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=terminal_consumer_materialization_deferred_for_exact_connected_history reason=%@ stage=%@ action=continue_bounded_transport_no_projection_scan",
                        reason,
                        authority.status.rawValue
                    )
                } else if !terminalMaterializationMotionBankReleaseInProgress {
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=terminal_consumer_materialization reason=%@ stage=%@ action=preserve_live_resume_local_publication",
                        reason,
                        authority.status.rawValue
                    )
                    resumePendingFullDrainPublicationIfNeeded(
                        reason: "transport_request_\(reason)"
                    )
                } else {
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=terminal_consumer_materialization_bypassed reason=%@ stage=%@ action=release_authorized_motion_bank_without_restarting_local_projection",
                        reason,
                        authority.status.rawValue
                    )
                }
                if terminalDisposition == .resumeLocalPublicationAndReturn {
                    return false
                }
                if terminalDisposition
                    == .resumeLocalPublicationAndContinueRawDrain {
                    // Catch-up (range-loss) raw drain runs in parallel with the
                    // deferred local publication of the parked terminal journal.
                    // It is forward-from-cursor FIFO and never mutates that
                    // journal's coverage/identity, so read_cursor keeps advancing
                    // in the background instead of waiting for a foreground
                    // materialization to clear the authority.
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=terminal_publication_parallel_range_loss_raw reason=%@ stage=%@ action=continue_raw_only_catch_up_through_normal_guards",
                        reason,
                        authority.status.rawValue
                    )
                } else {
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=terminal_publication_parallel_motion_bank reason=%@ stage=%@ action=continue_durable_same_strap_bank_ticket_through_normal_guards",
                        reason,
                        authority.status.rawValue
                    )
                }
            case .continueNormally where authority.status == .draining:
                let stormForStrandedResume =
                    defaults.integer(forKey: Self.protectedR10EarlyDisconnectsKey)
                        >= Self.protectedR10EarlyDisconnectLimit
                    || (defaults.object(forKey: Self.protectedR10DisconnectStormAtKey)
                        as? Double).map {
                            Date().timeIntervalSince1970 - $0 < 300
                        } ?? false
                let lastAuthorityProgressAtUnix = authority.boundaries
                    .compactMap(\.ackCompletedAtUnix)
                    .max() ?? authority.attempt.commandWriteCompletedAtUnix
                let strandedResume = Self.shouldResumeStrandedDrainingAuthority(
                    syncInProgress: offlineHistoricalSyncInProgress,
                    linkConnected: connectedLink,
                    connectedAt: connectedAt,
                    lastAcceptedHRAt: lastAcceptedHRAt,
                    lastAuthorityProgressAtUnix: lastAuthorityProgressAtUnix,
                    activeExplicitWorkout: activeExplicitWorkout,
                    recentDisconnectStorm: stormForStrandedResume,
                    now: Date()
                )
                if strandedResume {
                    strandedDrainingAuthorityResumeAdmitted = true
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=stranded_draining_authority_resume reason=%@ authority=%@ action=resume_silent_persisted_chain_from_stable_live",
                        reason,
                        authority.authorityIdentifier
                    )
                }
                guard Self.isPersistedDrainAuthorityResumeReason(reason)
                        || strandedResume else {
                    defaults.set(
                        "deferred_existing_drain_authority",
                        forKey: OfflineSyncDefaults.lastStatus
                    )
                    defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=deferred_existing_drain_authority reason=%@ action=preserve_live_wait_for_exact_persisted_resume",
                        reason
                    )
                    return false
                }
            case .continueNormally:
                break
            }
        }
        if Self.shouldDeferHistoricalSyncUntilArchiveWarmReady(
            warmState: historicalArchiveWarmState,
            syncInProgress: offlineHistoricalSyncInProgress
        ) {
            if historicalArchiveWarmState == .warming,
               let authority =
                    transientConnectedMotionBankHistoryRequestAuthority {
                transientConnectedMotionBankArchiveWarmDeferredTicketID =
                    authority.ticketID
            }
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: attendedHistoricalRequest,
                explicitPostWorkoutBankRequest:
                    explicitPostWorkoutBankRequest
            )
            defaults.set(
                historicalArchiveWarmState == .failed
                    ? "deferred_archive_warm_failed"
                    : "deferred_archive_warm",
                forKey: OfflineSyncDefaults.lastStatus
            )
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_archive_warm reason=%@ state=%@ error=%@ action=retain_request_preserve_live_no_history_command",
                reason,
                String(describing: historicalArchiveWarmState),
                historicalArchiveWarmFailure ?? "none"
            )
            return false
        }
        // Physical acceptance showed that the available 22/00 + 16/00 path
        // replays old flash history and cannot request the current local gap.
        // Do not let an explicit button, pull-to-refresh, or automatic retry
        // turn that stale replay into a competing BLE owner. Keep the durable
        // gap for a future, protocol-proven repair and leave realtime alone.
        // An already-running transaction is never interrupted here.
        //
        // Resuming a persisted `.draining` authority is the one carved-out
        // lane: that transport transaction was already admitted, physically
        // reached its first history frame (2026-07-23 handshake evidence),
        // and its exact-gap fingerprint is still pending. Refusing the resume
        // here is what stranded the authority behind this gate; it is not a
        // new full-flash decision.
        let resumingPersistedDrainAuthority = strandedDrainingAuthorityResumeAdmitted
            || (Self.isPersistedDrainAuthorityResumeReason(reason)
                && (try? historicalFullDrainCoverageStore.load())
                    .map { $0.status == .draining && $0.gap.pending } == true)
        // Operator-supervised seek trial only. The exact-recovery fence exists
        // because a full-flash replay of old rows is not gap recovery — and
        // that fence is exactly what makes the seek question unanswerable:
        // proving a seek requires an armed drain the fence refuses to grant.
        // `--atria-history-selector-sweep` is never set by any autonomous
        // lane, so this admits one attended drain whose 0x22 response drives
        // the 0x21/0x16 selector probe, and nothing else.
        let attendedSelectorSeekTrial = historySelectorSweepEnabled
        let attendedGate2FullDrainProof = gate2FullDrainProofEnabled
            && gate2FullDrainRequestedGapID != nil
            && explicitHistoricalRequest
        let fenceStormSignal =
            defaults.integer(forKey: Self.protectedR10EarlyDisconnectsKey)
                >= Self.protectedR10EarlyDisconnectLimit
            || (defaults.object(forKey: Self.protectedR10DisconnectStormAtKey)
                as? Double).map {
                    Date().timeIntervalSince1970 - $0 < 300
                } ?? false
        let fenceLastAttemptValue = defaults.object(
            forKey: OfflineSyncDefaults.lastAttemptAt
        )
        let autonomousBackgroundCatchUp =
            connectedRawHistoryCatchUpRequestAuthority != nil
            || Self.shouldAdmitAutonomousCursorAnchoredCatchUpStart(
                foregroundInteractive: foregroundInteractiveMode,
                strapBacklogPending: strapBacklogPendingForCatchUp(),
                syncInProgress: offlineHistoricalSyncInProgress,
                linkConnected: connectedLink,
                connectedAt: connectedAt,
                lastAcceptedHRAt: lastAcceptedHRAt,
                lastAttemptAt: (fenceLastAttemptValue as? Date)
                    ?? (fenceLastAttemptValue as? Double)
                        .map(Date.init(timeIntervalSince1970:)),
                activeExplicitWorkout: activeExplicitWorkout,
                recentDisconnectStorm: fenceStormSignal,
                now: Date()
            )
        if autonomousBackgroundCatchUp {
            AtriaDebugLog(
                "ATRIADBG offline_sync status=autonomous_catch_up_admitted reason=%@ action=create_cursor_anchored_chunked_catch_up_from_stable_background_epoch",
                reason
            )
        }
        if Self.shouldRefuseUnprovenExactRecoveryStart(
            fullDrainGapRecoveryEnabled:
                Self.productionHistoricalFullDrainGapRecoveryEnabled,
            syncInProgress: offlineHistoricalSyncInProgress,
            resumingPersistedDrainAuthority: resumingPersistedDrainAuthority,
            attendedSelectorSeekTrial: attendedSelectorSeekTrial,
            attendedGate2FullDrainProof: attendedGate2FullDrainProof,
            explicitPostWorkoutBankRequest: explicitPostWorkoutBankRequest,
            attendedUserRequest: attendedHistoricalRequest,
            strapBacklogPending: strapBacklogPendingForCatchUp(),
            autonomousBackgroundCatchUp: autonomousBackgroundCatchUp
        ) {
            if defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) {
                retainPendingOfflineHistoricalSyncRequest(
                    reason: reason,
                    force: force,
                    explicitRequest: attendedHistoricalRequest
                )
            }
            historicalRecoveryPresentation = .needsAttention
            defaults.set("gap_retained_exact_recovery_unproven",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=gap_retained_exact_recovery_unproven reason=%@ explicit=%d action=no_full_drain_command_preserve_live",
                          reason,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        if !offlineHistoricalSyncInProgress,
           !prepareHistoricalAdmissionLedgerIfNeeded(reason: reason) {
            if historicalAdmissionLedgerPreparationTask != nil,
               let authority =
                    transientConnectedMotionBankHistoryRequestAuthority {
                transientConnectedMotionBankAdmissionLedgerDeferredTicketID =
                    authority.ticketID
            }
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: attendedHistoricalRequest,
                explicitPostWorkoutBankRequest:
                    explicitPostWorkoutBankRequest
            )
            defaults.set(
                historicalAdmissionLedgerPreparationFailure == nil
                    ? "preparing_durable_history_ledger"
                    : "durable_history_ledger_failed",
                forKey: OfflineSyncDefaults.lastStatus
            )
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            return false
        }
        // A sequence-confirmation retry is an explicit, bounded replay of the
        // exact transition which previously failed closed. An automatic
        // range-loss retry must not acquire another history generation while
        // that replay is waiting for its fresh-HR boundary: doing so can
        // replace the retained cursor and turn one diagnostic retry into
        // competing history owners. Explicit user/repair requests remain the
        // only allowed owner during this window.
        if historySequenceConfirmationRetryTask != nil,
           !explicitHistoricalRequest {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("deferred_sequence_confirmation_replay",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_sequence_confirmation_replay reason=%@ action=retain_automatic_gap_until_explicit_replay_finishes",
                          reason)
            return false
        }
        // Aged automatic retries can carry `force`, so force alone must not
        // bypass this gate. A durable post-workout motion-bank ticket is also
        // automatic: unlike an attended user/research command, it must wait
        // through serious/critical pressure. Physical locked-phone acceptance
        // on 2026-07-28 showed that admitting this ticket under `.serious`
        // stranded the transport before its first stream-5 frame. Preserve the
        // durable request and live radio until pressure recovers. Never abort a
        // transaction already in progress here.
        //
        // Genuine heat only: the governor's mode also flags Low Power Mode as
        // `.serious`, which silently parked every overnight drain whenever the
        // user toggled LPM — banked coverage then waited for a morning unlock.
        // Exact raw catch-up has its own stricter thermal controller: critical
        // parks, serious serves only through one clean durable boundary with a
        // hard cap, and every exit preserves 2A37. Do not let this older
        // all-or-nothing automatic-history gate make that adaptive lane
        // unreachable on a warm, cabled phone. Motion-bank and every generic
        // request continue to use the conservative gate below.
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           Self.shouldDeferAutomaticOfflineSyncForThermalPressure(
            thermalPressure:
                powerThermalGovernor.shouldDeferDurableHistoryAdmissionForHeat,
            explicitUserRequest: explicitUserRequest || explicitResearchRequest
        ), !offlineHistoricalSyncInProgress {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_thermal_pressure",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=thermal_pressure mode=%@ force=%d action=retain_gap_preserve_live_radio",
                          reason,
                          powerThermalGovernor.mode.rawValue,
                          force ? 1 : 0)
            return false
        }
        // Realtime owns the physical link until a natural disconnect. This is
        // deliberately stronger than the old automatic-only guard: a physical
        // Build 5 soak proved that the Home missed-data action could classify
        // itself as attended, start a fresh-owner cutover, and cancel a healthy
        // HR/motion epoch. User intent raises the retained request's priority;
        // it never grants permission to interrupt current transmission.
        if !exactConnectedRealtimePreservingRequest,
           Self.shouldDeferHistoricalTransportForRealtimeContinuity(
            linkConnected: connectedLink || exactRealtimeEpochOwned,
            linkConnecting: connectingLink || standingRealtimeConnectOwned,
            syncInProgress: offlineHistoricalSyncInProgress
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: attendedHistoricalRequest,
                explicitPostWorkoutBankRequest:
                    explicitPostWorkoutBankRequest,
                preserveConnectedRealtimeOwner:
                    preserveConnectedRealtimeOwner
            )
            defaults.set("deferred_realtime_continuity_owner",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_realtime_continuity_owner reason=%@ connected=%d connecting=%d explicit=%d post_workout=%d action=retain_exact_request_until_natural_disconnect_no_history_command_no_cancel",
                reason,
                connectedLink ? 1 : 0,
                connectingLink ? 1 : 0,
                explicitHistoricalRequest ? 1 : 0,
                explicitPostWorkoutBankRequest ? 1 : 0
            )
            return false
        }
        let verifiedPeripheralID = defaults.string(forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID)
        let currentPeripheralID = peripheral?.identifier.uuidString
        let previouslyVerified = currentPeripheralID != nil && currentPeripheralID == verifiedPeripheralID
        var verifiedHistoryCapability = Self.supportsVerifiedHistoricalRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified
        )
        var verifiedMetricHistoryCapability = Self.supportsVerifiedHistoricalTransactionRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified,
            fullDrainGapRecoveryEnabled:
                Self.productionHistoricalFullDrainGapRecoveryEnabled
        )
        let recoverableGapPending = Self.hasValidRangeLossBackfillRequest(
            pending: defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
            requestedAt: defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double,
            now: Date()
        )
        if Self.shouldQualifyPendingHistoryByServiceDiscovery(
            exactGapPending: recoverableGapPending,
            verifiedHistoryCapability: verifiedHistoryCapability,
            model: strapModel,
            linkConnected: connectedLink,
            activeExplicitWorkout: activeExplicitWorkout,
            syncInProgress: offlineHistoricalSyncInProgress
        ) {
            if peripheral?.services?.contains(where: {
                $0.uuid == Self.UUIDs.strapService
            }) == true {
                strapModel = .strap4Class
                verifiedHistoryCapability = Self.supportsVerifiedHistoricalRecovery(
                    model: strapModel,
                    previouslyVerified: previouslyVerified
                )
                verifiedMetricHistoryCapability = Self.supportsVerifiedHistoricalTransactionRecovery(
                    model: strapModel,
                    previouslyVerified: previouslyVerified,
                    fullDrainGapRecoveryEnabled:
                        Self.productionHistoricalFullDrainGapRecoveryEnabled
                )
                AtriaDebugLog("ATRIADBG history_capability status=qualified model=strap4Class source=restored_service_cache action=continue_pending_recovery")
            } else {
                if let authority =
                        transientConnectedMotionBankHistoryRequestAuthority {
                    transientConnectedMotionBankDeferredLocalDependency =
                        .init(
                            ticketID: authority.ticketID,
                            dependency: .capabilityQualification
                        )
                }
                retainPendingOfflineHistoricalSyncRequest(
                    reason: reason, force: force,
                    explicitRequest: attendedHistoricalRequest
                )
                armHistoryCapabilityQualification(for: currentPeripheralID)
                defaults.set("qualifying_history_service",
                             forKey: OfflineSyncDefaults.lastStatus)
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                AtriaDebugLog("ATRIADBG history_capability status=qualifying model=unknown action=discover_service_only_no_characteristic_or_command")
                return false
            }
        }
        let recoveryStartValue = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart)
        let recoveryEndValue = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd)
        let recoveryStart = (recoveryStartValue as? Date)
            ?? (recoveryStartValue as? Double).map(Date.init(timeIntervalSince1970:))
        let recoveryEnd = (recoveryEndValue as? Date)
            ?? (recoveryEndValue as? Double).map(Date.init(timeIntervalSince1970:))
        let gapFingerprint = Self.historicalGapFingerprint(
            windows: AtriaHistoricalGapLedger.windows(defaults: defaults),
            recoveryStart: recoveryStart,
            recoveryEnd: recoveryEnd,
            requestedAt: defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double
        )
        let rawGapAlreadyArchived = gapFingerprint != nil
            && gapFingerprint == defaults.string(forKey: OfflineSyncDefaults.rawArchivedGapFingerprint)
        // Migrate the last production timeout recorded before the exact-gap
        // circuit breaker existed. The guard binds the app-owned timeout,
        // confirmed 16/00 write, recovery attempt and current gap to one short
        // history-owner epoch; it must never infer a timeout from an unrelated
        // app cancellation. Explicit repair is deliberately never blocked.
        if !explicitHistoricalRequest,
           defaults.string(forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint) == nil {
            let newestClosedGapEndUnix = AtriaHistoricalGapLedger
                .newestClosedRecoveryCandidate(defaults: defaults)?
                .window.end?.timeIntervalSince1970
            if Self.shouldMigrateHistoryStartTimeoutCircuitBreaker(
                lastAppCancelReason: defaults.string(forKey: "atria.ble.lastAppCancelReason"),
                lastAppCancelAtUnix: defaults.double(forKey: "atria.ble.lastAppCancelAt"),
                handshakeStatus: defaults.string(forKey: OfflineSyncDefaults.handshakeStatus),
                handshakeAtUnix: defaults.double(forKey: OfflineSyncDefaults.handshakeAt),
                backfillStartedAtUnix: defaults.double(
                    forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt
                ),
                newestClosedGapEndUnix: newestClosedGapEndUnix
            ), let gapFingerprint {
                defaults.set(
                    gapFingerprint,
                    forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
                )
                defaults.set(
                    defaults.double(forKey: "atria.ble.lastAppCancelAt"),
                    forKey: OfflineSyncDefaults.historyStartTimeoutGapAt
                )
                defaults.set("history_start_timeout_gap_migrated",
                             forKey: OfflineSyncDefaults.lastStatus)
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                AtriaDebugLog("ATRIADBG offline_sync status=history_start_timeout_gap_migrated reason=%@ action=preserve_exact_gap_suppress_automatic_owner_manual_repair_available",
                              reason)
            }
        }
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           Self.shouldSuppressAutomaticHistoricalNoRowsRetry(
            exactGapPending: recoverableGapPending,
            explicitUserRequest: explicitHistoricalRequest,
            currentGapFingerprint: gapFingerprint,
            noRowsGapFingerprint: defaults.string(
                forKey: OfflineSyncDefaults.noRowsGapFingerprint
            )
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("no_rows_gap_retained", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=no_rows_gap_retained reason=%@ detail=unchanged_durable_gap action=suppress_automatic_reentry_preserve_live_radio explicit=0",
                          reason)
            return false
        }
        // A confirmed 16/00 can time out before HISTORY_START on this strap.
        // That result is not permission to erase or mark the gap recovered,
        // but an automatic retry of the exact same gap would repeat the same
        // fresh-owner disconnect and can starve R10/live collection. Manual
        // repair remains authoritative and a materially new gap is eligible.
        let timeoutFingerprintForCurrentProfile =
            defaults.string(forKey: OfflineSyncDefaults.historyStartTimeoutProfileVersion)
                == Self.productionHistoryServeProfileVersion
                ? defaults.string(
                    forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
                )
                : nil
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           Self.shouldSuppressAutomaticHistoryStartTimeoutRetry(
            exactGapPending: recoverableGapPending,
            explicitUserRequest: explicitHistoricalRequest,
            currentGapFingerprint: gapFingerprint,
            historyStartTimeoutGapFingerprint: timeoutFingerprintForCurrentProfile
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("history_start_timeout_gap_retained",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=history_start_timeout_gap_retained reason=%@ detail=unchanged_durable_gap action=suppress_automatic_reentry_preserve_live_r10 explicit=0",
                          reason)
            return false
        }
        // Terminal sequence-gap park (belt to the scheduler gate: direct
        // callers of this method must not re-adopt the parked gap either).
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           Self.shouldSuppressAutomaticSequenceGapRetry(
            exactGapPending: recoverableGapPending,
            explicitUserRequest: explicitHistoricalRequest,
            currentGapFingerprint: gapFingerprint,
            parkedGapFingerprint: historySequenceGapIsParked(defaults)
                ? defaults.string(
                    forKey: OfflineSyncDefaults.sequenceGapFingerprint
                )
                : nil,
            parkedFrontierUnix: defaults.object(
                forKey: OfflineSyncDefaults.sequenceGapParkedFrontierUnix
            ) as? Double,
            currentFrontierUnix: defaults.object(
                forKey: OfflineSyncDefaults.drainedThroughUnix
            ) as? Double
           ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            defaults.set("sequence_gap_parked_retained",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=sequence_gap_parked_retained reason=%@ detail=terminal_unavailable_interval action=suppress_automatic_reentry_preserve_live_radio explicit=0",
                          reason)
            return false
        }
        let rawOnlyDisconnectedRecovery = Self.shouldAttemptRawOnlyHistoricalRecovery(
            exactGapPending: recoverableGapPending,
            rawHistoryVerified: verifiedHistoryCapability,
            metricHistoryVerified: verifiedMetricHistoryCapability,
            linkConnected: connectedLink,
            activeExplicitWorkout: activeExplicitWorkout,
            explicitUserRequest: explicitHistoricalRequest,
            rawGapAlreadyArchived: rawGapAlreadyArchived
        )
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           recoverableGapPending,
           verifiedHistoryCapability,
           !verifiedMetricHistoryCapability,
           !explicitHistoricalRequest,
           !rawOnlyDisconnectedRecovery {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            let status = rawGapAlreadyArchived
                ? "raw_gap_archived_awaiting_transaction_validation"
                : "gap_retained_transaction_unverified"
            defaults.set(status,
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=%@ reason=%@ detail=raw_transport_only connected=%d archived=%d action=%@ explicit=0",
                          status,
                          reason,
                          connectedLink ? 1 : 0,
                          rawGapAlreadyArchived ? 1 : 0,
                          rawGapAlreadyArchived
                            ? "await_exact_range_and_clock_validation_without_repull"
                            : "preserve_realtime_until_natural_disconnect")
            return false
        }
        // Evaluate the exact-gap handoff before clean-owner deferrals. The
        // durable journal + verified WHOOP-4 capability fence is the bounded
        // exception that prevents a healthy standing reconnect from starving
        // its own missing interval forever.
        // Drain-keeping P1b: treat a recent early-disconnect storm as a signal
        // to keep deferring connected catch-up (fall back to disconnect-cycle
        // recovery) rather than risk churning the link.
        let recentDisconnectStorm =
            defaults.integer(forKey: Self.protectedR10EarlyDisconnectsKey)
                >= Self.protectedR10EarlyDisconnectLimit
            || (defaults.object(forKey: Self.protectedR10DisconnectStormAtKey)
                as? Double).map {
                    Date().timeIntervalSince1970 - $0 < 300
                } ?? false
        let protectedHistoryHandoffAllowed =
            connectedRawHistoryCatchUpRequestAuthority != nil
            || Self.shouldAllowProtectedHistoricalRecovery(
            linkConnected: connectedLink,
            exactGapPending: recoverableGapPending,
            verifiedHistoryCapability: verifiedHistoryCapability,
            activeExplicitWorkout: activeExplicitWorkout,
            syncInProgress: offlineHistoricalSyncInProgress,
            explicitUserRequest: explicitHistoricalRequest
        )
            || Self.shouldAllowConnectedRangeLossCatchUp(
                rangeLossBackfillPending: strapBacklogPendingForCatchUp(),
                cleanOwnerState: protectedR10CleanOwnerState,
                recentDisconnectStorm: recentDisconnectStorm,
                verifiedHistoryCapability: verifiedHistoryCapability,
                activeExplicitWorkout: activeExplicitWorkout,
                syncInProgress: offlineHistoricalSyncInProgress
            )
        // Drain-keeping P2 maintenance window: when backgrounded/idle (nobody is
        // watching live HR) with a real backlog and a settled, storm-free link,
        // relax the connected-link guards below so the backlog flushes hard
        // instead of waiting for a lucky disconnect. See isFlushMaintenanceWindow.
        let flushMaintenanceWindow = Self.isFlushMaintenanceWindow(
            rangeLossBackfillPending: strapBacklogPendingForCatchUp(),
            foregroundInteractive: foregroundInteractiveMode,
            cleanOwnerState: protectedR10CleanOwnerState,
            activeExplicitWorkout: activeExplicitWorkout,
            recentDisconnectStorm: recentDisconnectStorm
        )
        if flushMaintenanceWindow {
            AtriaDebugLog(
                "ATRIADBG offline_sync status=flush_maintenance_window reason=%@ owner=%@ action=relax_connected_link_guards_for_backlog",
                reason,
                protectedR10CleanOwnerState.rawValue
            )
        }

        // A clean-owner cutover/proof/fallback owns the process radio even
        // across a disconnect. The physical V4 proof showed that admitting a
        // natural-disconnect history worker here immediately created a second
        // short link and obscured the protected-profile result.
        if !protectedHistoryHandoffAllowed,
           Self.shouldDeferAutomaticHistoryForCleanOwner(
            cleanOwner: protectedR10CleanOwner,
            state: protectedR10CleanOwnerState,
            explicitUserRequest: explicitHistoricalRequest,
            linkConnected: connectedLink
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_clean_owner_history_handoff",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=clean_owner_%@_%@ action=preserve_gap_no_history_reconnect",
                          reason,
                          protectedR10CleanOwner.rawValue,
                          protectedR10CleanOwnerState.rawValue)
            return false
        }

        if !protectedHistoryHandoffAllowed,
           Self.shouldDeferAutomaticOfflineSyncForProtectedR10Continuity(
            standardHROnlyMode: standardHROnlyMode,
            explicitUserRequest: explicitHistoricalRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_protected_r10_continuity",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=protected_r10_continuity force=%d explicit=0 action=preserve_gap_and_realtime",
                          reason,
                          force ? 1 : 0)
            return false
        }
        if !protectedHistoryHandoffAllowed,
           Self.shouldDeferOfflineSyncForProtectedR10Qualification(
            standardHROnlyMode: standardHROnlyMode,
            stableTransportProven: defaults.bool(forKey: Self.protectedR10StableTransportKey),
            explicitUserRequest: explicitHistoricalRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_protected_r10_realtime",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=protected_r10_realtime force=%d explicit=%d action=preserve_request_and_continuous_motion",
                          reason,
                          force ? 1 : 0,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        if standardHROnlyMode,
           !historyOnlyProbeMode,
           !protectedHistoryHandoffAllowed {
            UserDefaults.standard.set("disabled_protected_r10_minimal",
                                      forKey: OfflineSyncDefaults.lastStatus)
            UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=skipped reason=%@ detail=protected_r10_minimal_preserve_live connected=%d pending=%d verified=%d workout=%d explicit=%d",
                          reason,
                          connectedLink ? 1 : 0,
                          defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) ? 1 : 0,
                          verifiedHistoryCapability ? 1 : 0,
                          activeExplicitWorkout ? 1 : 0,
                          explicitHistoricalRequest ? 1 : 0)
            return false
        }
        let now = Date()
        scheduleStaleArmedRangeLossBackfillReconciliation(reason: reason, now: now)
        guard defaults.bool(forKey: OfflineSyncDefaults.enabled) else {
            defaults.set("disabled", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=skipped reason=%@ detail=disabled", reason)
            return false
        }
        let connectedSliceCooldownUntil = defaults.double(
            forKey: OfflineSyncDefaults.connectedSliceCooldownUntil
        )
        if connectedLink,
           connectedSliceCooldownUntil > now.timeIntervalSince1970,
           connectedRawHistoryCatchUpRequestAuthority == nil,
           !explicitUserRequest,
           !explicitResearchRequest,
           !flushMaintenanceWindow {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: false,
                explicitRequest: false
            )
            defaults.set(
                "deferred_connected_slice_live_cooldown",
                forKey: OfflineSyncDefaults.lastStatus
            )
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_connected_slice_live_cooldown reason=%@ remaining_s=%.0f action=preserve_live_and_exact_ticket",
                reason,
                connectedSliceCooldownUntil - now.timeIntervalSince1970
            )
            return false
        }
        guard Self.supportsVerifiedHistoricalRecovery(model: strapModel,
                                                       previouslyVerified: previouslyVerified) else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_unverified_history_capability", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=unverified_history_capability model=%@ peripheral=%@ action=fail_closed",
                          reason,
                          strapModel.rawValue,
                          currentPeripheralID ?? "none")
            return false
        }
        // A user-started workout owns the live radio. Historical replay changes
        // services/modes and has caused repeated reconnects in the background;
        // retain the request and run it after the durable workout intent closes.
        // This applies even to a force retry: force may bypass cadence, never the
        // user's active workout continuity boundary.
        if Self.shouldDeferOfflineSyncForExplicitWorkout(
            activeExplicitWorkout: activeExplicitWorkout
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_explicit_workout", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=explicit_workout_active force=%d action=preserve_live_radio",
                          reason,
                          force ? 1 : 0)
            return false
        }
        guard !historicalConsumerMaterializationInFlight else {
            if let authority =
                    transientConnectedMotionBankHistoryRequestAuthority {
                transientConnectedMotionBankDeferredLocalDependency = .init(
                    ticketID: authority.ticketID,
                    dependency: .terminalMaterialization
                )
            }
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_terminal_materialization",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=terminal_consumer_materialization_in_flight action=preserve_request",
                          reason)
            return false
        }
        guard !offlineHistoricalSyncInProgress else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("coalesced", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=coalesced reason=%@", reason)
            return false
        }
        guard postHistoryLiveRestorationTask == nil else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_post_history_live_restoration",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            return false
        }
        // Automatic archive recovery must never seize the proprietary command
        // pipe from an already-connected realtime stream. `force` is also used
        // by the aged range-loss retry state machine, so it is not evidence of
        // user intent: after 90 seconds that path previously stopped realtime
        // HR, entered history mode, disconnected, then repeated after every
        // reconnect while the exact recovery window remained pending. Wait for
        // a naturally disconnected transport instead. A deliberate user action
        // remains able to request a connected sync.
        // The exact raw lane has already proved the canonical object/epoch and
        // owns its adaptive 2A37-preserving budget. The older connected-link
        // policy additionally requires metric-gap authority and therefore
        // rejected raw-only catch-up as `deferred_connected_live_link` on the
        // physical phone. Keep that policy for every generic/motion request;
        // let only the exact raw authority reach the atomic transaction gate.
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           !flushMaintenanceWindow,
           Self.shouldDeferAutomaticOfflineSyncForConnectedLink(
            linkConnected: connectedLink,
            linkConnecting: connectingLink,
            explicitUserRequest: explicitHistoricalRequest,
            exactGapPending: recoverableGapPending,
            verifiedMetricRecovery: verifiedMetricHistoryCapability,
            automaticConnectedHandoffAllowed: allowConnectedAutomaticHandoff
                || exactConnectedRealtimePreservingRequest
        ) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_connected_live_link", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_connected_live_link reason=%@ force=%d action=preserve_realtime_until_natural_disconnect",
                          reason,
                          force ? 1 : 0)
            return false
        }
        // Historical transport shares the proprietary command pipe with live
        // HR/R10. A physical five-minute proof showed that even a successful
        // background offload could end by cancelling an otherwise healthy
        // stream. Preserve live data; the durable gap ledger keeps this request
        // pending until a natural reconnect or an explicit manual force sync.
        if connectedRawHistoryCatchUpRequestAuthority == nil,
           !force,
           !flushMaintenanceWindow,
           !(recoverableGapPending && verifiedMetricHistoryCapability),
           shouldProtectLiveStreamForOfflineSync(now: now) {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason, force: force,
                explicitRequest: attendedHistoricalRequest
            )
            defaults.set("deferred_live_link", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_live_link reason=%@ detail=live_hr_recent action=keep_ble_stream",
                          reason)
            return false
        }
        let connectedChunkedBackfill = connectedLink
        let lastAttempt = defaults.object(forKey: OfflineSyncDefaults.lastAttemptAt) as? Date
        let admittedAutomaticConnectedHandoff =
            recoverableGapPending
            && verifiedMetricHistoryCapability
            && (allowConnectedAutomaticHandoff
                || connectedMotionBankRequestAuthority != nil)
        let minimumInterval = Self.historicalAttemptMinimumInterval(
            automaticConnectedHandoff: admittedAutomaticConnectedHandoff,
            ordinaryInterval: offlineHistoricalSyncMinimumInterval(for: reason),
            // Handoff-9 CP2: the SAME receipt-computed interval the
            // eligibility gate uses — never two contradictory cooldowns.
            connectedHandoffInterval: automaticConnectedHistoryRetryInterval()
        )
        // `force` is also used internally once an automatic pending request is
        // old enough to take a safe radio handoff. It must not disable cadence
        // protection: that produced a real history transaction every ~30s
        // (hundreds of attempts) when a durable boundary could not advance.
        // Only an explicit user/research request may bypass the cooldown.
        if !explicitHistoricalRequest,
           connectedRawHistoryCatchUpRequestAuthority == nil,
           let lastAttempt,
           now.timeIntervalSince(lastAttempt) < minimumInterval {
            defaults.set("throttled", forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=skipped reason=%@ detail=throttled age_s=%.0f min_s=%.0f",
                  reason,
                  now.timeIntervalSince(lastAttempt),
                  minimumInterval)
            return false
        }
        // The former connected fresh-owner compatibility path lived here. It
        // is intentionally absent: callback-local cutover state could skip the
        // realtime gate and the atomic retainer claim. Every request now uses
        // the same disconnected, unretained transaction boundary below.
        return startOfflineHistoricalSync(
            reason: reason,
            force: force,
            explicitRequest: explicitHistoricalRequest,
            connectedChunkedBackfill: connectedChunkedBackfill,
            attemptAt: now,
            rawOnlyGapFingerprint: rawOnlyDisconnectedRecovery ? gapFingerprint : nil,
            gapFingerprint: connectedRawHistoryCatchUpRequestAuthority == nil
                ? gapFingerprint
                : nil,
            preserveConnectedRealtimeOwner:
                exactConnectedRealtimePreservingRequest,
            explicitPostWorkoutBankRequest:
                explicitPostWorkoutBankRequest
        )
    }

    @discardableResult
    private func clearHistoryCapabilityQualification(
        ifMatching expectedPeripheralID: UUID? = nil
    ) -> Bool {
        if let expectedPeripheralID {
            guard historyCapabilityQualificationPeripheralID
                    == expectedPeripheralID else { return false }
        }
        let hadQualification =
            historyCapabilityQualificationPeripheralID != nil
            || historyCapabilityQualificationFallbackTask != nil
            || historyCapabilityQualificationDiscoveryIssued
        historyCapabilityQualificationFallbackTask?.cancel()
        historyCapabilityQualificationFallbackTask = nil
        historyCapabilityQualificationPeripheralID = nil
        historyCapabilityQualificationDiscoveryIssued = false
        return hadQualification
    }

    private func armHistoryCapabilityQualification(for peripheralID: String?) {
        guard let peripheral,
              peripheral.state == .connected,
              peripheral.identifier.uuidString == peripheralID else { return }
        historyCapabilityQualificationPeripheralID = peripheral.identifier
        if serviceDiscoveryCallbackObservedForConnection,
           !historyCapabilityQualificationDiscoveryIssued {
            historyCapabilityQualificationDiscoveryIssued = true
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG history_capability status=qualification_discovery_requested trigger=completed_service_callback peripheral=%@",
                          peripheral.identifier.uuidString)
            return
        }
        guard historyCapabilityQualificationFallbackTask == nil else { return }
        historyCapabilityQualificationFallbackTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(5))
            guard let self, let peripheral,
                  !Task.isCancelled,
                  self.historyCapabilityQualificationPeripheralID == peripheral.identifier,
                  !self.historyCapabilityQualificationDiscoveryIssued,
                  peripheral.state == .connected else { return }
            self.historyCapabilityQualificationDiscoveryIssued = true
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG history_capability status=qualification_discovery_requested trigger=bounded_callback_fallback peripheral=%@",
                          peripheral.identifier.uuidString)
        }
    }

    private func handleHistoryCapabilityServiceDiscovery(
        peripheral: CBPeripheral,
        serviceUUIDs: [CBUUID]
    ) {
        serviceDiscoveryCallbackObservedForConnection = true
        let disposition = Self
            .historyCapabilityQualificationCallbackDisposition(
                callbackMatchesQualification:
                    historyCapabilityQualificationPeripheralID
                        == peripheral.identifier,
                targetedDiscoveryIssued:
                    historyCapabilityQualificationDiscoveryIssued,
                hasStrapService:
                    serviceUUIDs.contains(Self.UUIDs.strapService),
                hasError: false
            )
        switch disposition {
        case .ignore:
            return
        case .qualified:
            guard clearHistoryCapabilityQualification(
                ifMatching: peripheral.identifier
            ) else { return }
            if strapModel == .unknown, !debugForceUnknownStrapGeneration {
                strapModel = .strap4Class
            }
            AtriaDebugLog("ATRIADBG history_capability status=qualified model=strap4Class source=serialized_service_callback action=resume_pending_recovery")
            if !resumeConnectedMotionBankAfterLocalDependencyIfNeeded(
                .capabilityQualification
            ) {
                scheduleRangeLossBackfillIfNeeded(
                    reason: "history_capability_qualified"
                )
            }
        case .requestTargetedDiscovery:
            historyCapabilityQualificationDiscoveryIssued = true
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG history_capability status=qualification_discovery_requested trigger=nonproprietary_service_callback peripheral=%@",
                          peripheral.identifier.uuidString)
        case .terminalFailure:
            guard clearHistoryCapabilityQualification(
                ifMatching: peripheral.identifier
            ) else { return }
            releaseConnectedMotionBankLocalDependencyFirstRefusal(
                reason: "history_capability_targeted_service_absent",
                expectedDependency: .capabilityQualification
            )
            AtriaDebugLog(
                "ATRIADBG history_capability status=qualification_failed reason=targeted_service_absent peripheral=%@ action=rearm_present_capture_no_attempt_no_generation_no_history_command_no_cancel",
                peripheral.identifier.uuidString
            )
        }
    }

    /// Close the current live evidence boundary, then intentionally release the
    /// connected owner. `didDisconnect` hands the preserved explicit request to
    /// the already-audited disconnected recovery path, which creates the fresh
    /// service/notification epoch. Failure to prove durability leaves live BLE
    /// untouched; there is no timeout-driven disconnect and no retry loop.
    private func beginFreshHistoryOwnerCutover(reason: String) {
        guard !freshHistoryOwnerCutoverPending,
              let connectedPeripheral = peripheral,
              connectedPeripheral.state == .connected else { return }
        freshHistoryOwnerCutoverPending = true
        freshHistoryOwnerBoundaryFailureLatched = false
        let peripheralIdentifier = connectedPeripheral.identifier
        let boundarySessionID = liveSessionID
        let boundarySessionSampleCount = session.count
        let boundaryRRCount = rrArchive.count
        let boundaryResearch = ResearchAggregates(
            sensorProbeFrames: researchProbeFrameCount,
            spo2CandidateFrames: researchProbeOxygenCandidateFrames,
            skinTempCandidateFrames: researchProbeTemperatureCandidateFrames,
            skinTempCandidateValueSum: researchProbeTemperatureCandidateValueSum,
            skinTempCandidateValueCount: researchProbeTemperatureCandidateValueCount,
            spo2Offset64ValueSum: researchProbeOxygenOffset64ValueSum,
            spo2Offset64ValueCount: researchProbeOxygenOffset64ValueCount,
            spo2Offset66ValueSum: researchProbeOxygenOffset66ValueSum,
            spo2Offset66ValueCount: researchProbeOxygenOffset66ValueCount,
            strapSteps: strapStepResearchCount,
            strapRawSteps: strapStepResearchPeakCount,
            strapDeviceTimestamp: strapStepResearchDeviceTimestamp,
            strapStepState: strapStepResearchState,
            gyroCadenceResearchSteps: currentGyroCadenceResearchSessionSteps()
        )
        let boundaryRawSteps = strapStepResearchPeakCount
        let startedAt = Date()
        // A full active journal can legitimately queue behind session-store and
        // recovered-projection I/O on launch. Five seconds repeatedly failed
        // before the already-running atomic write could publish its counters.
        // Keep live HR untouched while waiting, but allow one bounded 30-second
        // window for the fixed target snapshot to become durable.
        let deadline = startedAt.addingTimeInterval(30)
        flushActiveSessionJournal(reason: "fresh_history_owner_cutover_\(reason)")
        persistStrapStepLedgerIfNeeded(
            reason: "fresh_history_owner_cutover_\(reason)",
            force: true
        )
        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_boundary_started reason=%@ action=await_atomic_fsync_then_single_cutover",
                      reason)
        Task { @MainActor [weak self] in
            guard let self else { return }
            while Date() < deadline {
                guard self.freshHistoryOwnerCutoverPending,
                      self.peripheral?.identifier == peripheralIdentifier,
                      connectedPeripheral.state == .connected else { return }
                let sessionIdentityValid = self.liveSessionID == boundarySessionID
                let journalDurable = sessionIdentityValid
                    && self.lastActiveJournalSavedSessionSampleCount
                        >= boundarySessionSampleCount
                    && self.lastActiveJournalSavedRRArchiveCount
                        >= boundaryRRCount
                    && Self.researchAggregates(
                        self.lastActiveJournalSavedResearchAggregates,
                        cover: boundaryResearch
                    )
                let stepsDurable = !self.strapStepLedgerRestoreInFlight
                    && !self.strapStepLedgerSaveInFlight
                    && self.lastStrapStepLedgerSavedRawSteps
                        >= boundaryRawSteps
                if journalDurable && stepsDurable {
                    AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_boundary_durable reason=%@ target_samples=%d target_rr=%d target_raw_steps=%d trailing_samples=%d durability=atomic_fsync action=single_intentional_disconnect_and_record_trailing_gap",
                                  reason,
                                  boundarySessionSampleCount,
                                  boundaryRRCount,
                                  boundaryRawSteps,
                                  max(0, self.session.count - boundarySessionSampleCount))
                    self.freshHistoryOwnerBoundaryFailureLatched = false
                    self.cancelPeripheralConnection(
                        connectedPeripheral,
                        reason: "explicit_history_fresh_owner_cutover"
                    )
                    return
                }
                if !self.activeJournalSaveInFlight {
                    self.flushActiveSessionJournal(
                        reason: "fresh_history_owner_cutover_tail_\(reason)"
                    )
                }
                if !self.strapStepLedgerRestoreInFlight,
                   !self.strapStepLedgerSaveInFlight {
                    self.persistStrapStepLedgerIfNeeded(
                        reason: "fresh_history_owner_cutover_tail_\(reason)",
                        force: true
                    )
                }
                try? await Task.sleep(for: .milliseconds(50))
            }
            guard self.freshHistoryOwnerCutoverPending else { return }
            self.freshHistoryOwnerCutoverPending = false
            self.freshHistoryOwnerBoundaryFailureLatched = true
            AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_boundary_failed reason=%@ elapsed_ms=%d session_match=%d target_samples=%d saved_samples=%d target_rr=%d saved_rr=%d target_raw_steps=%d saved_raw_steps=%d journal_in_flight=%d step_restore=%d step_in_flight=%d action=keep_live_link_retain_explicit_request_latch_no_packet_retry",
                          reason,
                          Int(Date().timeIntervalSince(startedAt) * 1_000),
                          self.liveSessionID == boundarySessionID ? 1 : 0,
                          boundarySessionSampleCount,
                          self.lastActiveJournalSavedSessionSampleCount,
                          boundaryRRCount,
                          self.lastActiveJournalSavedRRArchiveCount,
                          boundaryRawSteps,
                          self.lastStrapStepLedgerSavedRawSteps,
                          self.activeJournalSaveInFlight ? 1 : 0,
                          self.strapStepLedgerRestoreInFlight ? 1 : 0,
                          self.strapStepLedgerSaveInFlight ? 1 : 0)
        }
    }

    nonisolated static func researchAggregates(
        _ saved: ResearchAggregates,
        cover target: ResearchAggregates
    ) -> Bool {
        saved.sensorProbeFrames >= target.sensorProbeFrames
            && saved.spo2CandidateFrames >= target.spo2CandidateFrames
            && saved.skinTempCandidateFrames >= target.skinTempCandidateFrames
            && saved.skinTempCandidateValueSum >= target.skinTempCandidateValueSum
            && saved.skinTempCandidateValueCount >= target.skinTempCandidateValueCount
            && saved.spo2Offset64ValueSum >= target.spo2Offset64ValueSum
            && saved.spo2Offset64ValueCount >= target.spo2Offset64ValueCount
            && saved.spo2Offset66ValueSum >= target.spo2Offset66ValueSum
            && saved.spo2Offset66ValueCount >= target.spo2Offset66ValueCount
            && saved.strapSteps >= target.strapSteps
            && saved.strapRawSteps >= target.strapRawSteps
            && saved.gyroCadenceResearchSteps >= target.gyroCadenceResearchSteps
            && (target.strapDeviceTimestamp == nil
                || saved.strapDeviceTimestamp != nil)
    }

    /// Gives iOS one bounded opportunity to establish the strap bond before
    /// standard HR is available. The only protocol mutation reachable here is
    /// GET_DATA_RANGE 22/00 with response. It does not activate the history
    /// phase fence, serve/abort history, acknowledge data, or grant live proof.
    func requestOnboardingPairingPreflightIfNeeded() {
        guard let connectedPeripheral = peripheral,
              connectedPeripheral.state == .connected,
              let connectedAt else { return }
        let connectionIdentity = "\(connectedPeripheral.identifier.uuidString)|\(connectedAt.timeIntervalSince1970)"
        let alreadyAttempted = onboardingPairingPreflightAttemptedConnection
            == connectionIdentity
        guard Self.shouldAttemptOnboardingPairingPreflight(
            linkConnected: status == .connected,
            currentConnectionHasFreshHeartRate: currentConnectionHasFreshHeartRate,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            historyTransportActive: offlineHistoricalSyncInProgress
                || historyOnlyProbeEnabled
                || historyOnlyProbeMode
                || readOnlyHistoryCaptureRequested
                || readOnlyHistoryCaptureActive,
            freshHistoryOwnerCutoverPending: freshHistoryOwnerCutoverPending,
            preflightInFlight: onboardingPairingPreflightInFlight,
            alreadyAttemptedForConnection: alreadyAttempted
        ) else { return }

        onboardingPairingPreflightAttemptedConnection = connectionIdentity
        onboardingPairingPreflightGeneration &+= 1
        let generation = onboardingPairingPreflightGeneration
        onboardingPairingPreflightInFlight = true
        onboardingPairingPreflightDiscoveryRequested = true
        onboardingPairingPreflightSequence = nil
        onboardingPairingPreflightWriteResult = nil
        connectedPeripheral.discoverServices([Self.UUIDs.strapService])
        AtriaDebugLog("ATRIADBG onboarding_pairing status=armed generation=%llu peripheral=%@ command_allowlist=2200 mutation=pairing_preflight_only",
                      generation,
                      connectedPeripheral.identifier.uuidString)

        onboardingPairingPreflightTask?.cancel()
        onboardingPairingPreflightTask = Task { @MainActor [weak self] in
            guard let self else { return }
            // Discovery and any prior single-flight WR callback get a bounded
            // chance to settle. No competing write is cancelled or displaced.
            for _ in 0..<75 {
                guard !Task.isCancelled,
                      self.onboardingPairingPreflightInFlight,
                      self.onboardingPairingPreflightGeneration == generation,
                      self.peripheral?.identifier == connectedPeripheral.identifier,
                      self.peripheral?.state == .connected else {
                    self.finishOnboardingPairingPreflight(
                        generation: generation,
                        reason: "transport_interrupted"
                    )
                    return
                }
                if self.txCharacteristic != nil,
                   self.writeCompletionLedger.pending.isEmpty {
                    break
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard self.txCharacteristic != nil,
                  self.writeCompletionLedger.pending.isEmpty else {
                self.finishOnboardingPairingPreflight(
                    generation: generation,
                    reason: "tx_or_single_flight_unavailable"
                )
                return
            }

            var result = await self.sendOnboardingPairingPreflightRange(
                generation: generation
            )
            var retriesAlreadyIssued = 0
            if AtriaBLEReadOnlyHistoryCapturePolicy.permitsRangeRetry(
                after: result,
                retriesAlreadyIssued: retriesAlreadyIssued
            ) {
                retriesAlreadyIssued += 1
                AtriaDebugLog("ATRIADBG onboarding_pairing status=security_required generation=%llu action=bounded_pairing_settle_then_single_2200_retry",
                              generation)
                try? await Task.sleep(for: .seconds(
                    AtriaBLEReadOnlyHistoryCapturePolicy.pairingSettle
                ))
                guard !Task.isCancelled,
                      self.onboardingPairingPreflightInFlight,
                      self.onboardingPairingPreflightGeneration == generation,
                      self.peripheral?.identifier == connectedPeripheral.identifier,
                      self.peripheral?.state == .connected else {
                    self.finishOnboardingPairingPreflight(
                        generation: generation,
                        reason: "pairing_settle_completed_or_interrupted"
                    )
                    return
                }
                result = await self.sendOnboardingPairingPreflightRange(
                    generation: generation
                )
            }
            self.finishOnboardingPairingPreflight(
                generation: generation,
                reason: "range_write_\(result)"
            )
        }
    }

    private func sendOnboardingPairingPreflightRange(
        generation: UInt64
    ) async -> AtriaBLEReadOnlyHistoryCapturePolicy.WriteConfirmationResult {
        guard onboardingPairingPreflightInFlight,
              onboardingPairingPreflightGeneration == generation,
              !offlineHistoricalSyncInProgress,
              !historyOnlyProbeEnabled,
              !historyOnlyProbeMode,
              !readOnlyHistoryCaptureRequested,
              !readOnlyHistoryCaptureActive else { return .interrupted }
        onboardingPairingPreflightSequence = nil
        onboardingPairingPreflightWriteResult = nil
        guard sendCommand(
            Cmd.getDataRange,
            [0x00],
            mode: .withResponse,
            onboardingPairingPreflight: true
        ), let expected = writeCompletionLedger.pending.first,
           expected.command == Cmd.getDataRange,
           expected.payload == [0x00] else { return .failed }
        onboardingPairingPreflightSequence = expected.sequence
        AtriaDebugLog("ATRIADBG onboarding_pairing status=range_requested generation=%llu sequence=%d command=2200 mode=wr history_owner=0 live_authority=0",
                      generation,
                      Int(expected.sequence))

        let attempts = AtriaBLEReadOnlyHistoryCapturePolicy
            .writeConfirmationPollAttempts(
                opcode: Cmd.getDataRange,
                pollInterval: AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            )
        for _ in 0..<attempts {
            if let result = onboardingPairingPreflightWriteResult {
                return result
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  onboardingPairingPreflightInFlight,
                  onboardingPairingPreflightGeneration == generation else {
                return .interrupted
            }
        }
        return .timedOut
    }

    private func finishOnboardingPairingPreflight(
        generation: UInt64,
        reason: String
    ) {
        guard onboardingPairingPreflightGeneration == generation else { return }
        onboardingPairingPreflightInFlight = false
        onboardingPairingPreflightDiscoveryRequested = false
        onboardingPairingPreflightSequence = nil
        onboardingPairingPreflightWriteResult = nil
        onboardingPairingPreflightTask = nil
        AtriaDebugLog("ATRIADBG onboarding_pairing status=finished generation=%llu reason=%@ action=await_genuine_current_epoch_hr",
                      generation,
                      reason)
    }

    /// Advance the already-armed explicit generation on its one fresh link.
    /// Service discovery is the only radio mutation here; TX discovery and the
    /// existing notification-readiness gate remain solely responsible for
    /// starting 22/00, so no protocol command can precede confirmed RX/stream5.
    private func resumeFreshHistoryOwnerConnectionIfNeeded(
        peripheral: CBPeripheral
    ) -> Bool {
        guard let generation = freshHistoryOwnerConnectionGeneration else {
            return false
        }
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else {
            freshHistoryOwnerConnectionGeneration = nil
            AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_resume_rejected generation=%llu current=%llu active=%d action=normal_live_discovery",
                          generation,
                          offlineHistoricalSyncGeneration,
                          offlineHistoricalSyncInProgress ? 1 : 0)
            return false
        }
        freshHistoryOwnerConnectionGeneration = nil
        // The phase was already activated when the explicit request acquired
        // its generation, before the live-owner cutover. Re-activate its
        // ownership token on the fresh CoreBluetooth connection without
        // changing the proven RX + stream-5 listener or command profile.
        let usesExplicitHistoryProfile = historyTransportPhaseFence.snapshot()
            .usesExplicitHistoryProfile
        historyOnlyProbeEnabled = true
        _ = historyTransportPhaseFence.activate(
            generation: generation,
            usesExplicitHistoryProfile: usesExplicitHistoryProfile
        )
        peripheral.discoverServices(Self.UUIDs.productionHistoryServices)
        noteOfflineHistoricalSyncProgress(
            generation: generation,
            reason: "fresh_owner_connected"
        )
        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_resumed generation=%llu action=discover_history_plus_standard_hr_battery_then_await_notification_readiness commands=0",
                      generation)
        return true
    }

    /// Starts (or joins) a historical drain and suspends the caller until that
    /// exact generation reaches HISTORY_COMPLETE. Background task owners use
    /// this instead of starting an asynchronous offload and immediately telling
    /// iOS that their work finished.
    func requestOfflineHistoricalSyncAwaitingCompletion(
        reason: String,
        force: Bool = false,
        admitAutomaticConnectedHandoffIfEligible: Bool = false
    ) async -> Bool {
        let automaticConnectedHandoff = admitAutomaticConnectedHandoffIfEligible
            && automaticConnectedHistoricalHandoffIsEligible(now: Date())
        let started = requestOfflineHistoricalSyncIfNeeded(
            reason: reason,
            force: force || automaticConnectedHandoff,
            allowConnectedAutomaticHandoff: automaticConnectedHandoff
        )
        guard started || offlineHistoricalSyncInProgress else { return false }
        let generation = offlineHistoricalSyncGeneration
        while lastCompletedHistoricalSyncGeneration < generation {
            guard !Task.isCancelled else { return false }
            try? await Task.sleep(for: .milliseconds(250))
        }
        guard lastCompletedHistoricalSyncGeneration == generation else { return false }
        let onboardingRequest = reason == "onboarding_initial_import"
        guard onboardingRequest
                ? lastCompletedHistoricalSyncHasOnboardingAuthority
                : lastCompletedHistoricalSyncReachedTerminal else { return false }
        let receiptsRequired = historicalConsumerReceiptRequiredGenerations
            .contains(generation)
        guard onboardingRequest, receiptsRequired else {
            return true
        }
        // Full-drain/exact-request authorities publish five durable typed
        // receipts asynchronously after live ownership returns. Onboarding may
        // not turn that scheduled work into success. A failure/defer ends the
        // in-flight lease without a receipt and therefore fails closed here.
        while historicalConsumerMaterializationInFlight,
              !historicalConsumerReceiptedGenerations.contains(generation) {
            guard !Task.isCancelled else { return false }
            try? await Task.sleep(for: .milliseconds(250))
        }
        return Self.onboardingConsumerReceiptsAreComplete(
            required: receiptsRequired,
            receipted: historicalConsumerReceiptedGenerations.contains(generation)
        )
    }

    /// Await variant of the motion-bank offload for the BGProcessing window
    /// (2026-08-08). Starts a pending motion offload (which rides the same shared
    /// offline-historical-sync transport) and awaits that generation, exactly
    /// like `requestOfflineHistoricalSyncAwaitingCompletion` does for HR — so the
    /// background task stays alive while motion drains. Returns false immediately
    /// when nothing started (e.g. the bank is armed/capturing, or no ticket).
    func resumePendingWorkoutHistoricalMotionBankOffloadAwaitingCompletion(
        reason: String,
        maintenanceWindow: Bool = false
    ) async -> Bool {
        let priorGeneration = offlineHistoricalSyncGeneration
        _ = resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded(
            reason: reason,
            maintenanceWindow: maintenanceWindow)
        // Await ONLY a drain this call actually launched — a generation advance.
        // The IfNeeded result cannot be trusted as "a generation is now running":
        // it returns true for `retainedRequestOwnsTransport` too (a request kept
        // for a later accepted-HR/reconnect edge), which does NOT bump the
        // generation, and a false success there would make the caller publish +
        // complete the window as if motion drained. A motion offload also can
        // never ride an already-in-progress generation (its eligibility gate
        // requires !historyOwnerActive), so a genuine start is exactly a fresh
        // generation; anything else means nothing drained in THIS window.
        guard offlineHistoricalSyncGeneration > priorGeneration else { return false }
        let generation = offlineHistoricalSyncGeneration
        while lastCompletedHistoricalSyncGeneration < generation {
            guard !Task.isCancelled else { return false }
            try? await Task.sleep(for: .milliseconds(250))
        }
        return Self.historicalMotionBankOffloadCompletionSucceeded(
            launchedGeneration: generation,
            completedGeneration: lastCompletedHistoricalSyncGeneration,
            reachedTerminalWithLiveRestoredAuthority:
                lastCompletedHistoricalSyncReachedTerminal
        )
    }

    /// A generation advancing only proves that a transport attempt started.
    /// Timeout, disconnect, admission failure and post-history live-HR restore
    /// failure all retire that generation too, but must leave BGProcessing free
    /// to spend the same window on its HR fallback. The completion bit supplied
    /// here is published only after the matching generation reaches HISTORY_COMPLETE
    /// and a fresh accepted HR sample proves live ownership was restored.
    nonisolated static func historicalMotionBankOffloadCompletionSucceeded(
        launchedGeneration: UInt64,
        completedGeneration: UInt64,
        reachedTerminalWithLiveRestoredAuthority: Bool
    ) -> Bool {
        completedGeneration == launchedGeneration
            && reachedTerminalWithLiveRestoredAuthority
    }

    nonisolated static func onboardingHistoryTransportAuthorityIsValid(
        terminalReceived: Bool,
        durableTerminalAuthority: Bool,
        verifiedEmptyCursor: Bool
    ) -> Bool {
        (terminalReceived && durableTerminalAuthority) || verifiedEmptyCursor
    }

    nonisolated static func onboardingConsumerReceiptsAreComplete(
        required: Bool,
        receipted: Bool
    ) -> Bool {
        !required || receipted
    }

    /// One stateful adapter around the pure connected-handoff policy. Both the
    /// foreground retry scheduler and BGProcessing must evaluate exactly the
    /// same live-link, durable-gap, workout, freshness, age and cooldown facts;
    /// otherwise a suspended timer can starve the only iOS execution window
    /// capable of draining a connected strap backlog.
    private func automaticConnectedHistoricalHandoffIsEligible(
        now: Date
    ) -> Bool {
        // A genuine reconnect is a recovery opportunity for an overnight gap.
        // Admit one bounded cutover only from a stable epoch with fresh
        // accepted HR. The connected-slice watchdog keeps 2A37 subscribed and
        // relinquishes history if HR becomes stale; starting from an already
        // stale stream would hide a live-link failure and could churn forever.
        let defaults = UserDefaults.standard
        let currentPeripheralID = peripheral?.identifier.uuidString
        let verifiedPeripheralID = defaults.string(
            forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID
        )
        let previouslyVerified = currentPeripheralID != nil
            && currentPeripheralID == verifiedPeripheralID
        let effectiveModel: AtriaStrapModel = {
            if strapModel == .unknown,
               peripheral?.services?.contains(where: {
                   $0.uuid == Self.UUIDs.strapService
               }) == true {
                return .strap4Class
            }
            return strapModel
        }()
        let verifiedMetricRecovery = Self
            .supportsVerifiedHistoricalTransactionRecovery(
                model: effectiveModel,
                previouslyVerified: previouslyVerified,
                fullDrainGapRecoveryEnabled:
                    Self.productionHistoricalFullDrainGapRecoveryEnabled
            )
        // An ambiguous legacy coalesced envelope is intentionally retained as
        // unresolved evidence, but it cannot identify which seconds the strap
        // should recover. Only a selectable exact ledger candidate (or the
        // older explicit start/end fallback) may start an automatic transport.
        // Using `hasPendingWindows` here made quarantined legacy state wake the
        // strap forever as a raw-only drain with no possible settlement.
        let hasExactGapWindow = AtriaHistoricalGapLedger
            .oldestClosedRecoveryCandidate(defaults: defaults) != nil
            || (defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart) != nil
            && defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd) != nil)
        let requestedAtValue = defaults.object(
            forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt
        )
        let requestedAt = (requestedAtValue as? Date)
            ?? (requestedAtValue as? Double).map(Date.init(timeIntervalSince1970:))
        let lastAttemptValue = defaults.object(
            forKey: OfflineSyncDefaults.lastAttemptAt
        )
        let lastAttemptAt = (lastAttemptValue as? Date)
            ?? (lastAttemptValue as? Double).map(Date.init(timeIntervalSince1970:))
        return Self.shouldAttemptAutomaticConnectedHistoricalHandoff(
            linkConnected: peripheral?.state == .connected,
            exactGapPending: hasExactGapWindow,
            verifiedMetricRecovery: verifiedMetricRecovery,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            syncInProgress: offlineHistoricalSyncInProgress,
            connectedAt: connectedAt,
            hasContact: hasContact,
            acceptedSampleCount: session.count,
            lastAcceptedHRAt: lastAcceptedHRAt,
            requestedAt: requestedAt,
            lastAttemptAt: lastAttemptAt,
            now: now,
            stableConnectionInterval: automaticConnectedHistoryStableInterval,
            acceptedFreshnessWindow: offlineSyncLiveAcceptedHRProtectionWindow,
            minimumSamples: autoSaveMinSamples,
            minimumGapAge: rangeLossBackfillReadyForceInterval,
            // Handoff-9 CP2: a durably productive last slice earns the
            // 60-second retry; every other outcome keeps the 5-minute brake.
            attemptCooldown: automaticConnectedHistoryRetryInterval()
        )
    }

    private func recordMotionHandshakeEvidence(event: String, detail: String = "") {
        guard let diagnostic = motionHandshakeDiagnostic else { return }
        let defaults = UserDefaults.standard
        let now = Date().timeIntervalSince1970
        let sequence = defaults.integer(forKey: "atria.motionHandshake.eventSequence") + 1
        defaults.set(sequence, forKey: "atria.motionHandshake.eventSequence")
        defaults.set(event, forKey: "atria.motionHandshake.lastEvent")
        defaults.set(detail, forKey: "atria.motionHandshake.lastDetail")
        defaults.set(now, forKey: "atria.motionHandshake.lastEventAt")
        defaults.set(now, forKey: "atria.motionHandshake.\(event)At")
        AtriaDebugLog("ATRIADBG motion_handshake run=%@ seq=%d event=%@ detail=%@ unix=%.3f",
                      diagnostic.runID, sequence, event, detail, now)
    }

    /// Establish the public WHOOP response/event/data notification profile in
    /// deterministic order. CoreBluetooth can otherwise complete three CCCD
    /// writes in an arbitrary order, which makes a disconnect impossible to
    /// attribute. Every characteristic is requested at most once per fresh
    /// diagnostic connection.
    private func beginMotionHandshakeNotificationProfile(
        peripheral: CBPeripheral,
        characteristics: [CBCharacteristic]
    ) {
        guard let diagnostic = motionHandshakeDiagnostic,
              peripheral.state == .connected else { return }
        motionHandshakeProfileCharacteristics = Dictionary(
            uniqueKeysWithValues: characteristics.map { ($0.uuid, $0) }
        )
        motionHandshakeRequestedNotifyUUIDs.removeAll()
        motionHandshakeConfirmedNotifyUUIDs = Set(
            characteristics.compactMap { characteristic in
                characteristic.isNotifying ? characteristic.uuid : nil
            }
        )
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: diagnostic.useResponseEventDataProfile
        )
        let missing = required.filter {
            motionHandshakeProfileCharacteristics[$0] == nil
        }
        guard missing.isEmpty else {
            recordMotionHandshakeEvidence(
                event: "notification_profile_missing",
                detail: missing.map(\.uuidString).joined(separator: ",")
            )
            return
        }
        recordMotionHandshakeEvidence(
            event: "notification_profile_discovered",
            detail: required.map(\.uuidString).joined(separator: ",")
        )
        advanceMotionHandshakeNotificationProfile(peripheral: peripheral)
    }

    private func advanceMotionHandshakeNotificationProfile(peripheral: CBPeripheral) {
        guard let diagnostic = motionHandshakeDiagnostic,
              peripheral.state == .connected else { return }
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: diagnostic.useResponseEventDataProfile
        )
        if let nextUUID = required.first(where: {
            !motionHandshakeConfirmedNotifyUUIDs.contains($0)
                && !motionHandshakeRequestedNotifyUUIDs.contains($0)
        }), let characteristic = motionHandshakeProfileCharacteristics[nextUUID] {
            guard characteristic.properties.contains(.notify) else {
                recordMotionHandshakeEvidence(
                    event: "notification_profile_unsupported",
                    detail: nextUUID.uuidString
                )
                return
            }
            motionHandshakeRequestedNotifyUUIDs.insert(nextUUID)
            recordMotionHandshakeEvidence(
                event: "notification_profile_request",
                detail: nextUUID.uuidString
            )
            peripheral.setNotifyValue(true, for: characteristic)
            return
        }
        guard required.allSatisfy(motionHandshakeConfirmedNotifyUUIDs.contains) else {
            return
        }
        recordMotionHandshakeEvidence(
            event: "notification_profile_confirmed",
            detail: required.map(\.uuidString).joined(separator: ",")
        )
        if diagnostic.sendR10IMUSequence {
            // Public WHOOP implementations send the stream commands as soon as
            // response/event/data CCCDs are confirmed. Waiting for the later
            // standard-HR addition left the strap in a subscribed-but-unarmed
            // state and the physical link closed at 13.25 seconds before any
            // command could be evaluated.
            sendMotionHandshakeR10IMUSequenceIfReady()
        }
        scheduleMotionHandshakeStandardHRAddition(peripheral: peripheral)
    }

    private func handleMotionHandshakeNotificationState(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        error: Error?
    ) {
        guard let diagnostic = motionHandshakeDiagnostic else { return }
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: diagnostic.useResponseEventDataProfile
        )
        guard required.contains(characteristic.uuid) else {
            if characteristic.uuid == Self.UUIDs.heartRateMeasure {
                if let error {
                    recordMotionHandshakeEvidence(
                        event: "hr_notify_error",
                        detail: error.localizedDescription
                    )
                } else if characteristic.isNotifying {
                    recordMotionHandshakeEvidence(event: "hr_notify_active")
                    if diagnostic.sendR10IMUSequence {
                        sendMotionHandshakeR10IMUSequenceIfReady()
                    } else {
                        sendMotionHandshakeSingleR10ActivationIfReady()
                    }
                }
            }
            return
        }
        if let error {
            recordMotionHandshakeEvidence(
                event: "notification_profile_error",
                detail: "\(characteristic.uuid.uuidString)_\(error.localizedDescription)"
            )
            return
        }
        guard characteristic.isNotifying else {
            recordMotionHandshakeEvidence(
                event: "notification_profile_inactive",
                detail: characteristic.uuid.uuidString
            )
            return
        }
        motionHandshakeConfirmedNotifyUUIDs.insert(characteristic.uuid)
        recordMotionHandshakeEvidence(
            event: "notification_profile_active",
            detail: characteristic.uuid.uuidString
        )
        advanceMotionHandshakeNotificationProfile(peripheral: peripheral)
    }

    private func scheduleMotionHandshakeStandardHRAddition(peripheral: CBPeripheral) {
        guard let diagnostic = motionHandshakeDiagnostic,
              motionHandshakeAddHRTask == nil else { return }
        recordMotionHandshakeEvidence(event: "stream5_notify_confirmed",
                                      detail: "add_hr_after_\(Int(diagnostic.addHRDelay))s")
        motionHandshakeAddHRTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(diagnostic.addHRDelay))
            guard let self, !Task.isCancelled,
                  let peripheral, peripheral.state == .connected else { return }
            self.recordMotionHandshakeEvidence(event: "hr_service_discovery_requested")
            peripheral.discoverServices([Self.UUIDs.heartRateService])
        }
    }

    private func sendMotionHandshakeSingleR10ActivationIfReady() {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard let diagnostic = motionHandshakeDiagnostic,
              diagnostic.sendSingleR10Activation,
              !motionHandshakeActivationSent else { return }
        let defaults = UserDefaults.standard
        defaults.set(defaults.integer(forKey: "atria.motionHandshake.activationAttempts") + 1,
                     forKey: "atria.motionHandshake.activationAttempts")
        guard let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            recordMotionHandshakeEvidence(event: "activation_not_ready",
                                          detail: "missing_connected_wwr_tx")
            return
        }

        // Command 0x3F is explicitly named sendR10R11Realtime in the locally
        // validated protocol map. Payload 0x01 enables that stream. This bypass
        // is deliberately narrower than sendCommand: exactly one 3F/01 WWR is
        // possible, only after the third launch-consent switch and active HR.
        motionHandshakeActivationSent = true
        let sequence = cmdSeq
        cmdSeq &+= 1
        let frame = encodeFrame([Packet.command, sequence, Cmd.sendR10R11Realtime, 0x01])
        let now = Date().timeIntervalSince1970
        defaults.set(now, forKey: "atria.motionHandshake.activationSentAt")
        defaults.set(Int(sequence), forKey: "atria.motionHandshake.activationSequence")
        defaults.set(defaults.integer(forKey: ProtocolDefaults.packets),
                     forKey: "atria.motionHandshake.activationProtocolPacketsBaseline")
        defaults.set(defaults.integer(forKey: ProtocolDefaults.imuFrames),
                     forKey: "atria.motionHandshake.activationIMUFramesBaseline")
        defaults.set(defaults.integer(forKey: "atria.motionHandshake.activationSentCount") + 1,
                     forKey: "atria.motionHandshake.activationSentCount")
        recordMotionHandshakeEvidence(event: "activation_3f01_sent",
                                      detail: "wwr_seq_\(sequence)_bytes_\(frame.count)")
        peripheral.writeValue(frame, for: txCharacteristic, type: .withoutResponse)
    }

    /// Hardware-research profile used only behind four diagnostic launch
    /// consents: once response/event/data notifications are confirmed, send
    /// one paced 3F/01 then one 6A/01. Standard HR is added later as an
    /// independent coexistence probe. Optical 6B is omitted to
    /// reduce airtime because exact steps need R10 IMU, not raw optical data.
    private func sendMotionHandshakeR10IMUSequenceIfReady() {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard let diagnostic = motionHandshakeDiagnostic,
              diagnostic.useResponseEventDataProfile,
              diagnostic.sendR10IMUSequence,
              motionHandshakeCommandSequenceTask == nil,
              !motionHandshakeActivationSent else { return }
        let required = Self.motionHandshakeNotifyOrder(
            useResponseEventDataProfile: true
        )
        guard required.allSatisfy(motionHandshakeConfirmedNotifyUUIDs.contains),
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            recordMotionHandshakeEvidence(
                event: "r10_imu_sequence_not_ready",
                detail: "profile_or_tx_missing"
            )
            return
        }
        let runSequenceKey = "atria.motionHandshake.\(diagnostic.runID).r10IMUSequenceSent"
        guard !UserDefaults.standard.bool(forKey: runSequenceKey) else {
            recordMotionHandshakeEvidence(
                event: "r10_imu_sequence_suppressed",
                detail: "already_sent_for_run"
            )
            return
        }
        UserDefaults.standard.set(true, forKey: runSequenceKey)
        motionHandshakeActivationSent = true
        motionHandshakeCommandSequenceTask = Task { @MainActor [weak self, weak peripheral] in
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected else { return }
            let defaults = UserDefaults.standard
            let startedAt = Date()
            defaults.set(startedAt.timeIntervalSince1970,
                         forKey: "atria.motionHandshake.r10IMUSequenceStartedAt")
            defaults.set(defaults.integer(forKey: "atria.motionHandshake.r10IMUSequenceCount") + 1,
                         forKey: "atria.motionHandshake.r10IMUSequenceCount")

            let r10Sequence = self.cmdSeq
            self.cmdSeq &+= 1
            let r10Frame = encodeFrame([
                Packet.command, r10Sequence, Cmd.sendR10R11Realtime, 0x01
            ])
            self.recordMotionHandshakeEvidence(
                event: "activation_3f01_sent",
                detail: "wwr_seq_\(r10Sequence)_bytes_\(r10Frame.count)"
            )
            peripheral.writeValue(r10Frame, for: txCharacteristic, type: .withoutResponse)

            try? await Task.sleep(for: .milliseconds(120))
            guard !Task.isCancelled, peripheral.state == .connected else { return }
            let imuSequence = self.cmdSeq
            self.cmdSeq &+= 1
            let imuFrame = encodeFrame([
                Packet.command, imuSequence, Cmd.toggleIMUMode, 0x01
            ])
            self.recordMotionHandshakeEvidence(
                event: "activation_6a01_sent",
                detail: "wwr_seq_\(imuSequence)_bytes_\(imuFrame.count)"
            )
            peripheral.writeValue(imuFrame, for: txCharacteristic, type: .withoutResponse)
            defaults.set(Date().timeIntervalSince1970,
                         forKey: "atria.motionHandshake.r10IMUSequenceCompletedAt")
            self.motionHandshakeCommandSequenceTask = nil
        }
    }

    /// Production form of the physically-proven response/event/data profile.
    /// It is intentionally a separate owner from the launch-argument diagnostic:
    /// one fresh link, one ordered CCCD pass, one command pair, no repair loop.
    private func beginProtectedR10ResponseEventDataProfile(
        peripheral: CBPeripheral,
        characteristics: [CBCharacteristic],
        error: Error?
    ) {
        // Each decline leaves a named receipt: the 2026-08-13 03:51 stall sat
        // invisibly behind this guard set for eight minutes.
        guard motionHandshakeDiagnostic == nil else {
            recordProtectedV9BringUpEdge("protected_profile_rejected_diagnostic_active")
            return
        }
        guard standardHROnlyMode else {
            recordProtectedV9BringUpEdge("protected_profile_rejected_standard_hr_off")
            return
        }
        guard !historyOnlyProbeMode else {
            recordProtectedV9BringUpEdge("protected_profile_rejected_history_probe")
            return
        }
        guard protectedR10CleanOwner == .protectedV9 else {
            recordProtectedV9BringUpEdge(
                "protected_profile_rejected_owner_\(protectedR10CleanOwner.rawValue)"
            )
            return
        }
        guard protectedR10CleanOwnerState == .protectedLaunchPending else {
            recordProtectedV9BringUpEdge(
                "protected_profile_rejected_state_\(protectedR10CleanOwnerState.rawValue)"
            )
            return
        }
        guard protectedR10InitialProfilePeripheralID == peripheral.identifier else {
            recordProtectedV9BringUpEdge("protected_profile_rejected_peripheral_mismatch")
            return
        }
        guard peripheral.state == .connected else {
            recordProtectedV9BringUpEdge("protected_profile_rejected_not_connected")
            return
        }
        if let error {
            recordProtectedV9BringUpEdge("protected_profile_rejected_discovery_error")
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_discovery_error_\(error.localizedDescription)"
            )
            return
        }

        protectedR10ProfileCharacteristics = Dictionary(
            uniqueKeysWithValues: characteristics.map { ($0.uuid, $0) }
        )
        callbackPolicyState.update {
            $0.protectedProfileIsEmpty = protectedR10ProfileCharacteristics.isEmpty
        }
        protectedR10ProfileRequestedNotifyUUIDs.removeAll()
        protectedR10ProfileConfirmedNotifyUUIDs = Set(
            characteristics.compactMap { $0.isNotifying ? $0.uuid : nil }
        )
        guard let tx = protectedR10ProfileCharacteristics[Self.UUIDs.strapTX],
              tx.properties.contains(.writeWithoutResponse) else {
            persistProtectedR10CleanOwnerFallback(reason: "response_event_data_tx_missing")
            return
        }
        txCharacteristic = tx
        dbgTxReady = true

        let missing = Self.protectedR10ResponseEventDataNotifyOrder.filter {
            protectedR10ProfileCharacteristics[$0] == nil
        }
        guard missing.isEmpty else {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_characteristic_missing_\(missing.map(\.uuidString).joined(separator: "_"))"
            )
            return
        }
        let unsupported = Self.protectedR10ResponseEventDataNotifyOrder.filter {
            protectedR10ProfileCharacteristics[$0]?.properties.contains(.notify) != true
        }
        guard unsupported.isEmpty else {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_notify_unsupported_\(unsupported.map(\.uuidString).joined(separator: "_"))"
            )
            return
        }

        recordProtectedV9BringUpEdge("protected_profile_begin_accepted")
        let startedAt = Date()
        let defaults = UserDefaults.standard
        defaults.set(ProtectedR10CleanOwnerState.proving.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.set("clean_owner_v9_profile_subscribing",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        scheduleProtectedR10CleanOwnerProofTimeout(startedAt: startedAt)
        advanceProtectedR10ResponseEventDataProfile(peripheral: peripheral)
    }

    private func advanceProtectedR10ResponseEventDataProfile(peripheral: CBPeripheral) {
        guard protectedR10ResponseEventDataProofIsActive,
              peripheral.state == .connected else { return }
        if let nextUUID = Self.protectedR10ResponseEventDataNotifyOrder.first(where: {
            !protectedR10ProfileConfirmedNotifyUUIDs.contains($0)
                && !protectedR10ProfileRequestedNotifyUUIDs.contains($0)
        }), let characteristic = protectedR10ProfileCharacteristics[nextUUID] {
            protectedR10ProfileRequestedNotifyUUIDs.insert(nextUUID)
            recordProtectedV9BringUpEdge("notify_requested_\(nextUUID.uuidString)")
            peripheral.setNotifyValue(true, for: characteristic)
            incrementRadioCounter(RadioDefaults.customNotifyEnabled,
                                  reason: "protected_v9_initial_profile")
            dbgSubsReq += 1
            AtriaDebugLog("ATRIADBG protected_r10 status=profile_subscribe_requested owner=v9 ch=%@ action=ordered_once",
                          nextUUID.uuidString)
            return
        }
        guard Self.protectedR10ResponseEventDataNotifyOrder.allSatisfy(
            protectedR10ProfileConfirmedNotifyUUIDs.contains
        ) else { return }
        sendProtectedR10ResponseEventDataSequenceIfReady(peripheral: peripheral)
    }

    @discardableResult
    private func handleProtectedR10ResponseEventDataNotificationState(
        peripheral: CBPeripheral,
        characteristic: CBCharacteristic,
        error: Error?
    ) -> Bool {
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              protectedR10CleanOwner == .protectedV9,
              Self.protectedR10ResponseEventDataNotifyOrder.contains(characteristic.uuid),
              (protectedR10CleanOwnerState == .proving
                || protectedR10CleanOwnerState == .qualified) else { return false }
        if let error {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_notify_error_\(characteristic.uuid.uuidString)_\(error.localizedDescription)"
            )
            return true
        }
        guard characteristic.isNotifying else {
            persistProtectedR10CleanOwnerFallback(
                reason: "response_event_data_notify_inactive_\(characteristic.uuid.uuidString)"
            )
            return true
        }
        protectedR10ProfileConfirmedNotifyUUIDs.insert(characteristic.uuid)
        recordProtectedV9BringUpEdge("notify_confirmed_\(characteristic.uuid.uuidString)")
        activeProprietaryNotifyUUIDs.insert(characteristic.uuid)
        if characteristic.uuid == Self.UUIDs.strapStream5 {
            strapStream5NotifyConfirmed = true
            markPassiveR10SubscriptionConfirmed()
        }
        advanceProtectedR10ResponseEventDataProfile(peripheral: peripheral)
        return true
    }

    private func sendProtectedR10ResponseEventDataSequenceIfReady(peripheral: CBPeripheral) {
        guard !readOnlyHistoryCaptureRequested else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_read_only_history")
            return
        }
        guard protectedR10ResponseEventDataProofIsActive else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_proof_inactive")
            return
        }
        guard protectedR10CommandSequenceTask == nil else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_command_in_flight")
            return
        }
        guard !protectedR10ActivationSent else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_already_sent_local")
            return
        }
        guard Self.protectedR10ResponseEventDataNotifyOrder.allSatisfy(
            protectedR10ProfileConfirmedNotifyUUIDs.contains
        ) else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_notify_incomplete")
            return
        }
        guard let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_tx_unavailable")
            return
        }
        guard peripheral.state == .connected else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_disconnected")
            return
        }
        let motionBattery = motionEligibilityBatteryLevel()
        guard Self.shouldArmHighFrequencyMotion(
            batteryLevel: motionBattery,
            isCharging: motionEligibilityIsCharging,
            calibrationActive: stepCalibrationCaptureIsActive
        ) else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_low_battery")
            deferProtectedWorkoutMotionAtCommandBoundaryForLowBattery(
                batteryLevel: motionBattery
            )
            return
        }
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: Self.protectedR10ResponseEventDataSequenceSentKey) else {
            recordProtectedV9BringUpEdge("sequence_preflight_blocked_already_sent_durable")
            persistProtectedR10CleanOwnerFallback(reason: "response_event_data_sequence_already_sent")
            return
        }

        let startedAt = Date()
        recordProtectedV9BringUpEdge("sequence_started")
        defaults.set(true, forKey: Self.protectedR10ResponseEventDataSequenceSentKey)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10ActivationSentAtKey)
        defaults.set(defaults.integer(forKey: Self.protectedR10ActivationCountKey) + 1,
                     forKey: Self.protectedR10ActivationCountKey)
        defaults.set("response_event_data_commands_started",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationSent = true
        protectedR10ActivationAt = startedAt
        protectedR10FramesAfterActivation = 0
        protectedR10CommandSequenceTask = Task { @MainActor [weak self, weak peripheral] in
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            if await self.sendGate4OfficialGen4CompactMotionSequenceIfRequested(
                peripheral: peripheral,
                txCharacteristic: txCharacteristic,
                reason: "protected_profile"
            ) {
                self.protectedR10CommandSequenceTask = nil
                self.scheduleProtectedR10BatteryDiscovery(peripheral: peripheral)
                return
            }
            let imuSequence = self.cmdSeq
            self.cmdSeq &+= 1
            let imuFrame = encodeFrame([
                Packet.command, imuSequence, Cmd.toggleIMUMode, 0x01
            ])
            peripheral.writeValue(imuFrame,
                                  for: txCharacteristic,
                                  type: .withoutResponse)
            self.scheduleGate4IMUOnlyProbeStop(
                peripheral: peripheral,
                txCharacteristic: txCharacteristic,
                reason: "protected_profile"
            )
            let rawSequence = self.cmdSeq
            self.cmdSeq &+= 1
            let rawFrame = encodeFrame(
                [Packet.command, rawSequence, Cmd.startRawData]
                    + Cmd.rawCaptureDurationPayload()
            )
            #if DEBUG
            let gate4IMUOnlyProbe = ProcessInfo.processInfo.arguments.contains(
                "--atria-gate4-imu-only"
            )
            let sentCommands = gate4IMUOnlyProbe
                ? "6a01_only_debug_probe"
                : "6a01,51_duration_le"
            #else
            let gate4IMUOnlyProbe = false
            let sentCommands = "6a01,51_duration_le"
            #endif
            if !gate4IMUOnlyProbe {
                peripheral.writeValue(rawFrame, for: txCharacteristic, type: .withoutResponse)
            }
            AtriaDebugLog("ATRIADBG protected_r10 status=command_sent owner=v9 cmds=%@ seqs=%d,%d duration_ms=%u action=exactly_once_bounded_raw_motion",
                          sentCommands,
                          Int(imuSequence),
                          Int(rawSequence),
                          Cmd.workoutRawCaptureDurationMilliseconds)
            self.protectedR10CommandSequenceTask = nil
            self.scheduleProtectedR10BatteryDiscovery(peripheral: peripheral)
        }

        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10MissingFrameTimeout))
            guard let self, !Task.isCancelled,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            if self.protectedR10FramesAfterActivation == 0 {
                let retried = self.retryProtectedR10ShortBurstIfEligible(
                    now: Date(),
                    reason: "prior_qualified_zero_frame_proof"
                )
                if !retried {
                    self.persistProtectedR10CleanOwnerFallback(
                        reason: "response_event_data_missing_r10_frames"
                    )
                }
            } else {
                self.retryProtectedR10ShortBurstIfEligible(
                    now: Date(),
                    reason: "initial_proof_short_burst"
                )
            }
        }
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10EarlyDisconnectWindow))
            guard let self, !Task.isCancelled,
                  self.protectedR10ResponseEventDataProofIsActive,
                  self.peripheral?.state == .connected else { return }
            let now = Date()
            guard Self.protectedR10StabilityWindowIsProven(
                framesAfterActivation: self.protectedR10FramesAfterActivation,
                lastFrameAt: self.lastR10MotionFrameAt,
                connectedAt: self.connectedAt,
                activationAt: startedAt,
                now: now
            ) else {
                self.persistProtectedR10CleanOwnerFallback(
                    reason: "response_event_data_insufficient_r10_density"
                )
                return
            }
            self.qualifyProtectedR10RecoveryIfNeeded(
                at: now,
                status: "response_event_data_receiving_crc_valid"
            )
        }
    }

    /// Profile discovery is asynchronous, so battery truth can cross the
    /// safety boundary after bring-up was admitted but before `6A/01` would
    /// actually be written. Return the unspent attempt to a pending state and
    /// leave the healthy HR link untouched. A later battery update/lease
    /// evaluation may retry on the same connection without a relaunch.
    private func deferProtectedWorkoutMotionAtCommandBoundaryForLowBattery(
        batteryLevel: Int
    ) {
        let defaults = UserDefaults.standard
        workoutMotionLeaseProfileArmed = false
        defaults.set(ProtectedR10CleanOwnerState.protectedLaunchPending.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(false, forKey: Self.protectedR10ResponseEventDataSequenceSentKey)
        defaults.removeObject(forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.removeObject(forKey: WorkoutMotionDefaults.activationConnectionAt)
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = nil
        protectedR10CommandSequenceTask?.cancel()
        protectedR10CommandSequenceTask = nil
        protectedR10InitialProfilePeripheralID = nil
        protectedR10InitialProfileNotificationRequested = false
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        setWorkoutMotionStatus("deferred_low_battery_preserve_hr", at: Date())
        markWorkoutMotionGapIfNeeded(now: Date(), reason: "low_battery_preserve_hr")
        AtriaDebugLog("ATRIADBG workout_motion status=deferred reason=low_battery_preserve_hr battery=%d threshold=%d boundary=command_write action=return_unspent_attempt_keep_hr_and_workout",
                      batteryLevel,
                      Self.lowBatteryWarningThreshold)
    }

    private func scheduleProtectedR10BatteryDiscovery(peripheral: CBPeripheral) {
        guard protectedR10StandardDiscoveryTask == nil else { return }
        protectedR10StandardDiscoveryTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(
                Self.protectedR10PostCommandStandardDiscoveryDelay
            ))
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive else { return }
            self.protectedR10StandardDiscoveryStarted = true
            peripheral.discoverServices([
                Self.UUIDs.heartRateService,
                Self.UUIDs.batteryService,
            ])
            AtriaDebugLog("ATRIADBG protected_r10 status=standard_services_requested owner=v9 services=heart_rate,battery action=after_diagnostic_order_motion_start")
            self.protectedR10StandardDiscoveryTask = nil
        }
    }

    private func sendProtectedR10ActivationIfReady() {
        let cleanProofActive = protectedR10CleanOwner == .protectedV7
            && protectedR10CleanOwnerProofIsActive
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !historyOnlyProbeMode,
              cleanProofActive
                || (protectedR10CleanOwner == .legacy
                    && !protectedR10RollbackEnabled),
              !protectedR10ActivationSent,
              protectedR10ActivationGraceTask == nil,
              strapStream5NotifyConfirmed,
              heartRateCharacteristic?.isNotifying == true,
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else { return }

        // First observe the passive stream. A reconnect is not proof that the
        // strap forgot a previous 3F/01, and repeatedly writing that command was
        // physically correlated with early disconnects. A fresh passive frame
        // cancels this task; otherwise the persisted lease/cooldown permits at
        // most one later activation.
        let defaults = UserDefaults.standard
        let persistedActivationAt = (defaults.object(forKey: Self.protectedR10ActivationSentAtKey) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        let leaseDelay = Self.protectedR10ActivationLeaseDelay(lastActivationAt: persistedActivationAt,
                                                               now: Date())
        let observationDelay: TimeInterval
        if cleanProofActive {
            let proofStartedAt = (defaults.object(
                forKey: Self.protectedR10CleanOwnerProofStartedAtKey
            ) as? Double).map(Date.init(timeIntervalSince1970:))
            let observationAge = proofStartedAt.map {
                max(0, Date().timeIntervalSince($0))
            } ?? 0
            observationDelay = max(0.001,
                                   max(Self.protectedR10PassiveGraceDuration - observationAge,
                                       leaseDelay))
        } else {
            observationDelay = max(Self.protectedR10PassiveGraceDuration, leaseDelay)
        }
        protectedR10ActivationGraceTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(observationDelay))
            guard let self, !Task.isCancelled else { return }
            self.protectedR10ActivationGraceTask = nil
            self.sendProtectedR10ActivationNowIfReady()
        }
    }

    private func sendProtectedR10ActivationNowIfReady() {
        guard !readOnlyHistoryCaptureRequested else { return }
        let cleanProofActive = protectedR10CleanOwner == .protectedV7
            && protectedR10CleanOwnerProofIsActive
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !historyOnlyProbeMode,
              cleanProofActive
                || (protectedR10CleanOwner == .legacy
                    && !protectedR10RollbackEnabled),
              !protectedR10ActivationSent,
              strapStream5NotifyConfirmed,
              heartRateCharacteristic?.isNotifying == true,
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else { return }

        if cleanProofActive {
            let now = Date()
            let defaults = UserDefaults.standard
            let proofStartedAt = (defaults.object(
                forKey: Self.protectedR10CleanOwnerProofStartedAtKey
            ) as? Double).map(Date.init(timeIntervalSince1970:))
            let lastActivationAt = (defaults.object(
                forKey: Self.protectedR10ActivationSentAtKey
            ) as? Double).map(Date.init(timeIntervalSince1970:))
            let decision = Self.protectedR10RecoveryDecision(
                pending: true,
                connected: status == .connected && peripheral.state == .connected,
                stream5Notifying: strapStream5NotifyConfirmed,
                activationSent: false,
                passiveObservationAge: proofStartedAt.map { now.timeIntervalSince($0) },
                activationAge: nil,
                activationLeaseRemaining: Self.protectedR10ActivationLeaseDelay(
                    lastActivationAt: lastActivationAt,
                    now: now
                ),
                stableHRDuration: proofStartedAt.map { now.timeIntervalSince($0) } ?? 0,
                latestHRAge: lastRawHRNotificationAt.map { now.timeIntervalSince($0) },
                batteryLevel: motionEligibilityBatteryLevel(now: now),
                isCharging: motionEligibilityIsCharging,
                frames: protectedR10FramesAfterActivation,
                lastFrameAge: lastR10MotionFrameAt.map { now.timeIntervalSince($0) }
            )
            guard decision == .sendSingleLeasedActivation else { return }
        }

        protectedR10ActivationSent = true
        protectedR10FramesAfterActivation = 0
        let sentAt = Date()
        protectedR10ActivationAt = sentAt
        let sequence = cmdSeq
        cmdSeq &+= 1
        let frame = encodeFrame([Packet.command, sequence, Cmd.sendR10R11Realtime, 0x01])
        let defaults = UserDefaults.standard
        defaults.set(sentAt.timeIntervalSince1970, forKey: Self.protectedR10ActivationSentAtKey)
        defaults.set(defaults.integer(forKey: Self.protectedR10ActivationCountKey) + 1,
                     forKey: Self.protectedR10ActivationCountKey)
        defaults.set("activation_sent", forKey: RadioDefaults.passiveR10Status)
        AtriaDebugLog("ATRIADBG protected_r10 status=activation_sent cmd=3f data=01 mode=wwr seq=%d action=single_write",
                      Int(sequence))
        peripheral.writeValue(frame, for: txCharacteristic, type: .withoutResponse)

        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10MissingFrameTimeout))
            guard let self, !Task.isCancelled,
                  Self.shouldLatchProtectedR10RollbackForMissingFrames(
                    activationSent: self.protectedR10ActivationSent,
                    framesAfterActivation: self.protectedR10FramesAfterActivation
                  ) else { return }
            if self.protectedR10CleanOwnerProofIsActive {
                self.persistProtectedR10CleanOwnerFallback(
                    reason: "missing_r10_after_clean_owner_activation"
                )
            } else {
                self.latchProtectedR10Rollback(reason: "missing_r10_after_activation")
            }
        }
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10EarlyDisconnectWindow))
            guard let self, !Task.isCancelled,
                  self.protectedR10ActivationAt == sentAt,
                  self.peripheral?.state == .connected else { return }
            let verifiedAt = Date()
            guard Self.protectedR10StabilityWindowIsProven(
                framesAfterActivation: self.protectedR10FramesAfterActivation,
                lastFrameAt: self.lastR10MotionFrameAt,
                connectedAt: self.connectedAt,
                activationAt: sentAt,
                now: verifiedAt
            ) else {
                AtriaDebugLog("ATRIADBG protected_r10 status=stability_window_failed duration_s=%.0f frames=%d last_frame_age_s=%.1f action=rollback_without_reconnect",
                              Self.protectedR10EarlyDisconnectWindow,
                              self.protectedR10FramesAfterActivation,
                              self.lastR10MotionFrameAt.map { verifiedAt.timeIntervalSince($0) } ?? -1)
                if self.protectedR10CleanOwnerProofIsActive {
                    self.persistProtectedR10CleanOwnerFallback(
                        reason: "insufficient_clean_owner_r10_density"
                    )
                } else {
                    self.latchProtectedR10Rollback(reason: "insufficient_r10_stability_density")
                }
                return
            }
            self.qualifyProtectedR10RecoveryIfNeeded(at: verifiedAt,
                                                     status: "receiving_crc_valid")
            AtriaDebugLog("ATRIADBG protected_r10 status=stable_window_complete duration_s=%.0f frames=%d action=clear_early_disconnect_streak",
                          Self.protectedR10EarlyDisconnectWindow,
                          self.protectedR10FramesAfterActivation)
        }
    }

    private func retryProtectedR10AfterStableHRIfEligible(now: Date) {
        guard motionHandshakeDiagnostic == nil,
              standardHROnlyMode,
              !offlineHistoricalSyncInProgress,
              !historyOnlyProbeEnabled,
              !historyOnlyProbeMode,
              peripheral?.state == .connected else { return }

        if protectedR10CleanOwnerProofIsActive {
            if Self.protectedR10CleanOwnerProofHasExpired(
                proofActive: true,
                attemptAge: (UserDefaults.standard.object(
                    forKey: Self.protectedR10CleanOwnerProofStartedAtKey
                ) as? Double).map { now.timeIntervalSince1970 - $0 }
            ) {
                persistProtectedR10CleanOwnerFallback(
                    reason: "clean_owner_proof_timeout_on_hr"
                )
                return
            }
            // HR may become fresh after the 20-second passive timer. Recheck
            // only the leased command gate; never rediscover or toggle stream5.
            sendProtectedR10ActivationIfReady()
        }
    }

    private func beginProtectedR10CleanOwnerProofIfNeeded(at startedAt: Date) {
        let defaults = UserDefaults.standard
        guard protectedR10CleanOwner == .protectedV7,
              protectedR10CleanOwnerState == .protectedLaunchPending,
              strapStream5NotifyConfirmed,
              status == .connected,
              peripheral?.state == .connected else { return }
        defaults.set(ProtectedR10CleanOwnerState.proving.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set("clean_owner_v7_passive_proof",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationGraceTask?.cancel()
        protectedR10ActivationGraceTask = nil
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        scheduleProtectedR10CleanOwnerProofTimeout(startedAt: startedAt)
        sendProtectedR10ActivationIfReady()
        AtriaDebugLog("ATRIADBG protected_r10 status=clean_owner_proof_started owner=v7 grace_s=%.0f action=observe_initial_profile_no_cccd_mutation",
                      Self.protectedR10PassiveGraceDuration)
    }

    /// Handoff-13 CP0-A: whether a proof-timeout fire may terminalize. Pure:
    /// the fire must belong to the exact proof it was armed for (the durable
    /// proof timestamp is the identity — a stale timer from an older
    /// connection can neither qualify nor roll back a newer proof), and the
    /// proof must still be active.
    nonisolated static func protectedR10ProofTimeoutFireShouldTerminalize(
        capturedStartedAtUnix: TimeInterval,
        currentStartedAtUnix: TimeInterval,
        proofActive: Bool
    ) -> Bool {
        guard proofActive else { return false }
        guard currentStartedAtUnix > 0 else { return false }
        return abs(capturedStartedAtUnix - currentStartedAtUnix) < 0.5
    }

    private func scheduleProtectedR10CleanOwnerProofTimeout(startedAt: Date) {
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = Task { @MainActor [weak self] in
            let age = max(0, Date().timeIntervalSince(startedAt))
            let remaining = max(0, Self.protectedR10PassiveReprobeTimeout - age)
            try? await Task.sleep(for: .seconds(remaining))
            guard let self, !Task.isCancelled else { return }
            // Handoff-13 CP0-A: the fire is bound to the exact proof it was
            // armed for via the durable proof timestamp, not merely to "a
            // proof is active" — a replacement proof must never be
            // terminalized by its predecessor's timer.
            let currentStartedAt = UserDefaults.standard.double(
                forKey: Self.protectedR10CleanOwnerProofStartedAtKey
            )
            guard Self.protectedR10ProofTimeoutFireShouldTerminalize(
                capturedStartedAtUnix: startedAt.timeIntervalSince1970,
                currentStartedAtUnix: currentStartedAt,
                proofActive: self.protectedR10CleanOwnerProofIsActive
            ) else { return }
            self.protectedR10CleanOwnerProofTimeoutTask = nil
            self.persistProtectedR10CleanOwnerFallback(
                reason: "clean_owner_proof_timeout"
            )
        }
    }

    /// Handoff-13 CP0-A: the wall-clock deadline backstop. The 150-second
    /// proof deadline previously lived only in a suspendable `Task.sleep`
    /// (physically observed: a proof still "active" 47 minutes after
    /// activation), with the only sweep gated behind live HR publishes and
    /// silenced during history phases. This runs synchronously at process/
    /// scene/BLE edges BEFORE further protected work: an expired proof
    /// terminalizes exactly once with its own distinct reason. Safe in any
    /// transport phase — it writes owner state only, never the radio.
    @discardableResult
    func enforceProtectedR10ProofDeadlineIfNeeded(
        trigger: String
    ) -> Bool {
        guard protectedR10CleanOwnerProofIsActive else { return false }
        let startedAtUnix = UserDefaults.standard.double(
            forKey: Self.protectedR10CleanOwnerProofStartedAtKey
        )
        let age: TimeInterval? = startedAtUnix > 0
            ? Date().timeIntervalSince1970 - startedAtUnix
            : nil
        guard Self.protectedR10CleanOwnerProofHasExpired(
            proofActive: true,
            attemptAge: age
        ) else { return false }
        AtriaDebugLog(
            "ATRIADBG protected_r10 status=proof_deadline_expired trigger=%@ age_s=%.0f",
            trigger,
            age ?? -1
        )
        persistProtectedR10CleanOwnerFallback(
            reason: "proof_deadline_expired"
        )
        return true
    }

    private func qualifyProtectedR10RecoveryIfNeeded(at qualifiedAt: Date,
                                                     status: String) {
        workoutMotionLeaseProfileArmed = false
        let defaults = UserDefaults.standard
        defaults.set(0, forKey: Self.protectedR10EarlyDisconnectsKey)
        defaults.set(0, forKey: Self.protectedR10RetryCountKey)
        defaults.set(true, forKey: Self.protectedR10StableTransportKey)
        defaults.set(qualifiedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(false, forKey: Self.protectedR10PassiveReprobePendingKey)
        defaults.set(0, forKey: Self.protectedR10PassiveReprobeFailureCountKey)
        defaults.set(0, forKey: Self.protectedR10ProofChurnFailureCountKey)
        if protectedR10CleanOwner == .protectedV7
            || protectedR10CleanOwner == .protectedV9 {
            defaults.set(ProtectedR10CleanOwnerState.qualified.rawValue,
                         forKey: Self.protectedR10CleanOwnerStateKey)
            defaults.removeObject(forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
            defaults.removeObject(forKey: Self.protectedR10CleanOwnerFailureReasonKey)
            recordProtectedV9BringUpEdge("qualified")
            // v9 terminal: one bank-owner resumption under the existing
            // generation fence (mirrors the fallback terminal).
            evaluateAllDayMotionGovernor(reason: "protected_v9_qualified_terminal")
        }
        defaults.set(status, forKey: RadioDefaults.passiveR10Status)
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
    }

    /// Persist a clean pure-HR owner for the next process. The current proof
    /// link is left untouched: no CCCD disable, service rediscovery,
    /// connection cancellation or history handoff is allowed here.
    private func persistProtectedR10CleanOwnerFallback(reason: String) {
        recordProtectedV9BringUpEdge("fallback_\(reason)")
        // The v9 owner reached a terminal state: resume the workout-bank
        // owner exactly once. The governor is generation-fenced and
        // self-guarded, and the bank's durable ticket was never cleared.
        evaluateAllDayMotionGovernor(reason: "protected_v9_fallback_terminal")
        let defaults = UserDefaults.standard
        if workoutMotionLeaseProfileArmed {
            // The current per-connection proof owns the truth state. It cleared
            // stableTransport before sending the command pair, so an
            // interruption or a two-frame burst cannot honestly restore
            // `qualified` from an older epoch. Continue into pure-HR fallback;
            // HR/RR remain available while motion is reported unavailable.
            workoutMotionLeaseProfileArmed = false
            AtriaDebugLog("ATRIADBG workout_motion status=lease_bring_up_failed reason=%@ action=pure_hr_fallback_no_false_qualification",
                          reason)
        }
        let failures = defaults.integer(forKey: Self.protectedR10PassiveReprobeFailureCountKey) + 1
        defaults.set(failures, forKey: Self.protectedR10PassiveReprobeFailureCountKey)
        let fallbackOwner: ProtectedR10CleanOwner = protectedR10CleanOwner == .protectedV9
            ? .pureHRV10
            : .pureHRV8
        defaults.set(fallbackOwner.rawValue,
                     forKey: Self.protectedR10CleanOwnerKey)
        defaults.set(ProtectedR10CleanOwnerState.fallbackPending.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(false, forKey: Self.protectedR10PassiveReprobePendingKey)
        defaults.set(true, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(true, forKey: Self.protectedR10RollbackKey)
        defaults.set(reason, forKey: Self.protectedR10DisconnectStormReasonKey)
        defaults.set(reason, forKey: Self.protectedR10CleanOwnerFailureReasonKey)
        defaults.set(Date().timeIntervalSince1970, forKey: Self.protectedR10FallbackAtKey)
        defaults.removeObject(forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set(fallbackOwner == .pureHRV10
                        ? "clean_owner_v10_fallback_pending"
                        : "clean_owner_v8_fallback_pending",
                     forKey: RadioDefaults.passiveR10Status)
        retireLiveR10MotionFreshness(
            state: "passive_r10_unavailable",
            reason: "clean_owner_fallback_\(reason)"
        )
        protectedR10ActivationGraceTask?.cancel()
        protectedR10ActivationGraceTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = nil
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = nil
        protectedR10CommandSequenceTask?.cancel()
        protectedR10CommandSequenceTask = nil
        protectedR10StandardDiscoveryTask?.cancel()
        protectedR10StandardDiscoveryTask = nil
        protectedR10ProfileCharacteristics.removeAll()
        callbackPolicyState.update { $0.protectedProfileIsEmpty = true }
        protectedR10ProfileRequestedNotifyUUIDs.removeAll()
        protectedR10ProfileConfirmedNotifyUUIDs.removeAll()
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        protectedR10InitialProfilePeripheralID = nil
        protectedR10InitialProfileNotificationRequested = false
        stopR10LivenessWatchdog(reason: reason)
        AtriaDebugLog("ATRIADBG protected_r10 status=clean_owner_fallback_pending owner=%@ reason=%@ failures=%d action=keep_current_link_untouched_select_fresh_pure_hr_next_process_no_history",
                      fallbackOwner.rawValue,
                      reason,
                      failures)
    }

    /// DEBUG-only continuation of the physically observed passive R10 mode.
    /// The failed controller epoch is over, but the strap retains motion mode.
    /// Keep the v9 namespace and consumed command marker, then let the ordinary
    /// standing reconnect re-subscribe without sending any command.
    private func prepareGate4PassiveR10ReconnectAfterTimeout() {
        let defaults = UserDefaults.standard
        defaults.set(ProtectedR10CleanOwnerState.protectedLaunchPending.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(false, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(false, forKey: Self.protectedR10RollbackKey)
        defaults.removeObject(forKey: Self.protectedR10CleanOwnerProofStartedAtKey)
        defaults.set("gate4_passive_reconnect_pending",
                     forKey: RadioDefaults.passiveR10Status)
        defaults.set(defaults.integer(
            forKey: "atria.gate4.passiveReconnect.timeouts"
        ) + 1, forKey: "atria.gate4.passiveReconnect.timeouts")
        gate4RealtimeKeepaliveTask?.cancel()
        gate4RealtimeKeepaliveTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = nil
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask = nil
        protectedR10CommandSequenceTask?.cancel()
        protectedR10CommandSequenceTask = nil
        protectedR10StandardDiscoveryTask?.cancel()
        protectedR10StandardDiscoveryTask = nil
        protectedR10ProfileCharacteristics.removeAll()
        callbackPolicyState.update { $0.protectedProfileIsEmpty = true }
        protectedR10ProfileRequestedNotifyUUIDs.removeAll()
        protectedR10ProfileConfirmedNotifyUUIDs.removeAll()
        protectedR10ActivationSent = false
        protectedR10ActivationAt = nil
        protectedR10FramesAfterActivation = 0
        protectedR10InitialProfilePeripheralID = nil
        protectedR10InitialProfileNotificationRequested = false
    }

    /// Stream 5 may be subscribed exactly once as part of a newly connected
    /// protected profile. Service restoration and watchdog rediscovery happen
    /// on an established link and must never mutate its CCCD.
    private func requestProtectedR10InitialProfileNotificationIfAllowed(
        _ characteristic: CBCharacteristic,
        peripheral: CBPeripheral
    ) {
        guard standardHROnlyMode,
              !historyOnlyProbeMode,
              !protectedR10StreamSuppressed,
              characteristic.uuid == Self.UUIDs.strapStream5,
              characteristic.properties.contains(.notify),
              !characteristic.isNotifying else { return }
        guard protectedR10InitialProfilePeripheralID == peripheral.identifier else {
            AtriaDebugLog("ATRIADBG protected_r10 status=stream5_inactive action=skip_mid_link_cccd_mutation owner=%@ state=%@",
                          protectedR10CleanOwner.rawValue,
                          protectedR10CleanOwnerState.rawValue)
            if protectedR10CleanOwner == .protectedV7,
               (protectedR10CleanOwnerState == .protectedLaunchPending
                || protectedR10CleanOwnerState == .proving
                || protectedR10CleanOwnerState == .qualified) {
                persistProtectedR10CleanOwnerFallback(
                    reason: "clean_owner_stream5_inactive_after_initial_profile"
                )
            }
            return
        }
        guard !protectedR10InitialProfileNotificationRequested else { return }
        protectedR10InitialProfileNotificationRequested = true
        peripheral.setNotifyValue(true, for: characteristic)
        incrementRadioCounter(RadioDefaults.customNotifyEnabled,
                              reason: "protected_r10_initial_profile")
        dbgSubsReq += 1
        AtriaDebugLog("ATRIADBG protected_r10 status=stream5_subscribe_requested action=initial_profile_once owner=%@",
                      protectedR10CleanOwner.rawValue)
    }

    /// Only a completed CoreBluetooth callback may reject the initial v7
    /// profile. Foreground/liveness observations are intentionally excluded
    /// because they can run while the subscribe request is still in flight.
    private func persistProtectedR10FallbackForStream5Callback(reason: String) {
        guard standardHROnlyMode,
              protectedR10CleanOwner == .protectedV7,
              protectedR10CleanOwnerState == .protectedLaunchPending
                || protectedR10CleanOwnerState == .proving
                || protectedR10CleanOwnerState == .qualified else { return }
        persistProtectedR10CleanOwnerFallback(reason: reason)
    }

    /// CoreBluetooth restoration can hand back a connected peripheral whose
    /// services/characteristics are already cached without replaying every
    /// discovery callback. Rehydrate the protected R10 prerequisites directly
    /// from that cache so a Release reinstall cannot leave HR healthy while the
    /// motion stream silently stays dormant.
    private func resumeProtectedR10FromRestoredCache(_ peripheral: CBPeripheral) {
        guard standardHROnlyMode,
              !historyOnlyProbeMode,
              !protectedR10StreamSuppressed,
              peripheral.state == .connected else { return }

        var cachedHR: CBCharacteristic?
        var cachedStream5: CBCharacteristic?
        var cachedTX: CBCharacteristic?
        var cachedBattery: CBCharacteristic?
        var cachedBatteryStatus: CBCharacteristic?
        for service in peripheral.services ?? [] {
            if service.uuid == Self.UUIDs.heartRateService {
                guard let characteristics = service.characteristics else {
                    peripheral.discoverCharacteristics([Self.UUIDs.heartRateMeasure], for: service)
                    continue
                }
                cachedHR = characteristics.first { $0.uuid == Self.UUIDs.heartRateMeasure }
            } else if service.uuid == Self.UUIDs.strapService {
                guard let characteristics = service.characteristics else {
                    peripheral.discoverCharacteristics([Self.UUIDs.strapStream5, Self.UUIDs.strapTX], for: service)
                    continue
                }
                cachedStream5 = characteristics.first { $0.uuid == Self.UUIDs.strapStream5 }
                cachedTX = characteristics.first { $0.uuid == Self.UUIDs.strapTX }
            } else if service.uuid == Self.UUIDs.batteryService {
                guard let characteristics = service.characteristics else {
                    peripheral.discoverCharacteristics(
                        [Self.UUIDs.batteryLevel, Self.UUIDs.batteryLevelStatus],
                        for: service
                    )
                    continue
                }
                cachedBattery = characteristics.first { $0.uuid == Self.UUIDs.batteryLevel }
                cachedBatteryStatus = characteristics.first {
                    $0.uuid == Self.UUIDs.batteryLevelStatus
                }
            }
        }

        if let cachedHR {
            heartRateCharacteristic = cachedHR
            if cachedHR.properties.contains(.notify), !cachedHR.isNotifying {
                _ = requestHeartRateNotificationEnableIfNeeded(
                    peripheral: peripheral,
                    characteristic: cachedHR,
                    reason: "restored_heart_rate_cache"
                )
            }
        }
        if let cachedTX, cachedTX.properties.contains(.writeWithoutResponse) {
            txCharacteristic = cachedTX
            dbgTxReady = true
        }
        if let cachedStream5, cachedStream5.properties.contains(.notify) {
            if cachedStream5.isNotifying {
                activeProprietaryNotifyUUIDs.insert(Self.UUIDs.strapStream5)
                strapStream5NotifyConfirmed = true
                markPassiveR10SubscriptionConfirmed()
            } else {
                requestProtectedR10InitialProfileNotificationIfAllowed(
                    cachedStream5,
                    peripheral: peripheral
                )
            }
        }
        if let cachedBattery {
            batteryLevelCharacteristic = cachedBattery
            let batteryRefreshAllowed = Self.shouldAllowAncillaryGATTRefresh(
                historyTransportOwnsLink: recoveredDataProjectionDeferralIsActive
            )
            if batteryRefreshAllowed,
               cachedBattery.properties.contains(.notify)
                    || cachedBattery.properties.contains(.indicate) {
                let now = Date()
                let defaults = UserDefaults.standard
                let canReuseRestoredEpoch = Self.restoredCachedBatteryNotificationCanReuseEpoch(
                    characteristicIsNotifying: cachedBattery.isNotifying,
                    restoredSamePeripheral: batteryConnectionRestoredSamePeripheral,
                    confirmedAt: (defaults.object(forKey: BatteryDefaults.notificationConfirmedAt) as? Double)
                        .map(Date.init(timeIntervalSince1970:)),
                    lastError: defaults.string(forKey: BatteryDefaults.notificationLastError),
                    linkConnected: peripheral.state == .connected && status == .connected,
                    now: now
                )
                if canReuseRestoredEpoch {
                    promoteReconnectBatteryBaselineIfSafe(
                        now: now,
                        heartRateReceivedAt: lastRawHRNotificationAt,
                        validatedR10ReceivedAt: lastR10MotionFrameAt,
                        reason: "2A19_restored_cache_notify_active"
                    )
                } else if cachedBattery.isNotifying {
                    // The cached flag cannot mint a new confirmation or erase a
                    // prior callback error. Force a real off/on callback cycle.
                    if defaults.string(forKey: BatteryDefaults.notificationLastError) == nil {
                        defaults.set("restored_cache_unconfirmed",
                                     forKey: BatteryDefaults.notificationLastError)
                    }
                    defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
                    revokeBatteryNotificationLease(reason: "2A19_restored_cache_unconfirmed",
                                                   now: now)
                    pendingNotifyReenableUUIDs.insert(cachedBattery.uuid)
                    peripheral.setNotifyValue(false, for: cachedBattery)
                    armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: cachedBattery,
                        reason: "restored_cache_disable"
                    )
                } else {
                    defaults.set(now.timeIntervalSince1970,
                                 forKey: BatteryDefaults.notificationRequestedAt)
                    peripheral.setNotifyValue(true, for: cachedBattery)
                    armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: cachedBattery,
                        reason: "restored_cache_enable"
                    )
                }
            } else if !batteryRefreshAllowed {
                AtriaDebugLog("ATRIADBG battery source=2A19 status=restored_cache_observed reason=history_transport_owned action=no_cccd_recovery")
            }
        }
        if let cachedBatteryStatus {
            batteryStatusCharacteristic = cachedBatteryStatus
            // This standard, independent CCCD is safe while history owns the
            // proprietary pipe. The helper permits only the missing
            // subscription; it never reads or otherwise changes that owner.
            ensureBatteryStatusNotificationForCurrentEpoch(
                peripheral: peripheral,
                characteristic: cachedBatteryStatus,
                reason: "restored_cache"
            )
            requestBatteryStatusReadForCurrentEpoch(
                peripheral: peripheral,
                characteristic: cachedBatteryStatus,
                reason: "restored_cache"
            )
        }
        AtriaDebugLog("ATRIADBG protected_r10 status=restored_cache_rehydrated services=%d hr=%d stream5=%d tx=%d stream5_notifying=%d action=resume_minimal_transport",
                      peripheral.services?.count ?? 0,
                      cachedHR == nil ? 0 : 1,
                      cachedStream5 == nil ? 0 : 1,
                      cachedTX == nil ? 0 : 1,
                      cachedStream5?.isNotifying == true ? 1 : 0)
        sendProtectedR10ActivationIfReady()
    }

    private func latchProtectedR10Rollback(reason: String) {
        guard motionHandshakeDiagnostic == nil else { return }
        let defaults = UserDefaults.standard
        defaults.set(true, forKey: Self.protectedR10RollbackKey)
        defaults.set(false, forKey: Self.protectedR10StableTransportKey)
        defaults.removeObject(forKey: Self.protectedR10StableTransportQualifiedAtKey)
        defaults.set(reason, forKey: "atria.protectedR10.rollbackReason")
        defaults.set(Date().timeIntervalSince1970, forKey: "atria.protectedR10.rollbackAt")
        defaults.set("activation_suppressed_observing_passive_r10",
                     forKey: RadioDefaults.passiveR10Status)
        protectedR10ActivationGraceTask?.cancel()
        protectedR10ActivationGraceTask = nil
        protectedR10MissingFrameTask?.cancel()
        protectedR10MissingFrameTask = nil
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = nil
        // Never unsubscribe, cancel, rediscover, or reconnect here. Those
        // interventions caused the old loop. Keep the healthy 2A37 link and
        // apply pure-HR discovery only after the next natural connection edge.
        AtriaDebugLog("ATRIADBG protected_r10 status=activation_suppressed reason=%@ action=preserve_2a37_and_passive_stream5_no_reconnect_no_more_commands",
                      reason)
    }

    private func startOfflineHistoricalSync(reason: String, force: Bool) {
        _ = startOfflineHistoricalSync(reason: reason,
                                       force: force,
                                       explicitRequest:
                                        Self.isExplicitUserOfflineSyncReason(reason),
                                       connectedChunkedBackfill: false,
                                       attemptAt: Date(),
                                       rawOnlyGapFingerprint: nil,
                                       gapFingerprint: nil)
    }

    /// CoreBluetooth can wake the app in the background, but iOS may suspend
    /// it again immediately after the delegate callback. The verified WHOOP
    /// handshake contains short ordering delays, so acquire a finite UIKit
    /// execution lease only for the active recovery transaction. The lease is
    /// ended on every normal terminal path and never changes gap authority.
    private func beginOfflineHistoricalSyncBackgroundLease(generation: UInt64) {
        endOfflineHistoricalSyncBackgroundLease(status: "replaced")
        offlineHistoricalSyncBackgroundTaskGeneration = generation
        let defaults = UserDefaults.standard
        defaults.set("active", forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.backgroundLeaseAt)
        offlineHistoricalSyncBackgroundTask = UIApplication.shared.beginBackgroundTask(
            withName: "Atria WHOOP history recovery"
        ) { [weak self] in
            // UIKit invokes expiration handlers on the main thread, but the
            // closure is not imported as @MainActor. Do the terminal transport
            // handoff before returning from the handler: enqueueing a Task here
            // lets iOS suspend the process first, which physically left a
            // history generation marked active after its first frame while the
            // durable all-day step receipt never published.
            guard Thread.isMainThread else {
                DispatchQueue.main.sync {
                    self?.handleOfflineHistoricalSyncBackgroundLeaseExpiration(
                        generation: generation
                    )
                }
                return
            }
            MainActor.assumeIsolated {
                self?.handleOfflineHistoricalSyncBackgroundLeaseExpiration(
                    generation: generation
                )
            }
        }
        if offlineHistoricalSyncBackgroundTask == .invalid {
            defaults.set("unavailable",
                         forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        }
        AtriaDebugLog("ATRIADBG offline_sync background_lease=active generation=%llu application_state=%ld",
                      generation,
                      UIApplication.shared.applicationState.rawValue)
    }

    private func handleOfflineHistoricalSyncBackgroundLeaseExpiration(
        generation: UInt64
    ) {
        guard offlineHistoricalSyncBackgroundTaskGeneration == generation else {
            return
        }
        AtriaDebugLog("ATRIADBG offline_sync background_lease=expired generation=%llu action=disconnect_history_transport_retain_durable_prefix_and_ticket",
                      generation)
        endOfflineHistoricalSyncBackgroundLease(
            status: "expired_transport_reset_pending"
        )
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else { return }
        if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
            generation: generation,
            reason: "history_background_lease_expired_preserve_realtime"
        ) {
            return
        }
        if let historyPeripheral = peripheral,
           historyPeripheral.state == .connected {
            cancelPeripheralConnection(
                historyPeripheral,
                reason: "history_background_lease_expired_transport_reset"
            )
        } else {
            interruptOfflineHistoricalSyncForTransportLoss(
                reason: "history_background_lease_expired"
            )
        }
    }

    private func endOfflineHistoricalSyncBackgroundLease(status: String) {
        let task = offlineHistoricalSyncBackgroundTask
        offlineHistoricalSyncBackgroundTask = .invalid
        offlineHistoricalSyncBackgroundTaskGeneration = nil
        if task != .invalid {
            UIApplication.shared.endBackgroundTask(task)
        }
        let defaults = UserDefaults.standard
        defaults.set(status, forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.backgroundLeaseAt)
    }

    /// A motion-bank offload can share the connected link with standard 2A37
    /// HR. If its optional history transaction fails, end only Atria's local
    /// history generation: the durable ticket/prefix remains retryable and the
    /// physical realtime owner stays untouched. No ACK or protocol ABORT is
    /// manufactured here.
    @discardableResult
    private func finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
        generation: UInt64,
        reason: String
    ) -> Bool {
        let exactConnectedGeneration =
            activeConnectedRealtimePreservingHistoryAuthorityExists(
                generation: generation
            )
        guard Self.shouldFinishHistoricalFailureWithoutDisconnect(
            preservesConnectedRealtimeOwner:
                offlineHistoricalSyncPreservesConnectedRealtimeOwner
                    || exactConnectedGeneration,
            syncInProgress: offlineHistoricalSyncInProgress,
            expectedGeneration: generation,
            activeGeneration: offlineHistoricalSyncGeneration,
            // Once exact connected-bank authority has been installed, every
            // exit is local even if CoreBluetooth has already transitioned the
            // object. There is no useful radio reset to issue for an optional
            // ticket, and a natural disconnect must not be turned into an app
            // cancel/rebuild by the failure tail.
            linkConnected: peripheral?.state == .connected
                || exactConnectedGeneration
        ) else { return false }
        AtriaDebugLog(
            "ATRIADBG offline_sync status=failed_preserved_realtime generation=%llu reason=%@ action=finish_local_history_no_disconnect_no_ack_no_abort_retain_ticket",
            generation,
            reason
        )
        finishOfflineHistoricalSync(
            reason: reason,
            generation: generation,
            resumePendingSync: false
        )
        return true
    }

    /// The exact connected-raw lane is admitted on the promise that it is
    /// subordinate to standard 2A37. If the ordinary continuity watchdog sees
    /// that promise fail, retire only that generation before rebuilding the
    /// canonical transport. `finishOfflineHistoricalSync` retains an
    /// unacknowledged/mid-page spool and never manufactures an ACK; the
    /// persisted cooldown prevents the first post-rebuild sample (or a process
    /// restoration) from immediately repeating the same serve.
    @discardableResult
    private func preemptConnectedRawHistoryForLiveHeartRateIfNeeded(
        generation: UInt64,
        peripheral target: CBPeripheral,
        rawGap: TimeInterval,
        timeout: TimeInterval,
        now: Date
    ) -> Bool {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation,
              let authority = activeConnectedRawHistoryCatchUpAuthority(
                generation: generation
              ),
              self.peripheral === target,
              target.state == .connected,
              authority.request.strapIdentifier
                == target.identifier.uuidString,
              authority.request.callbackSource.peripheralID
                == target.identifier,
              authority.request.callbackSource.peripheralObjectID
                == ObjectIdentifier(target),
              bleCallbackEpochFence.accepts(
                source: authority.request.callbackSource,
                peripheralConnected: true
              ) else { return false }

        let retryNotBefore = Self
            .connectedRawHistoryLivePreemptionRetryNotBefore(
                now: now,
                connectedSliceCooldown:
                    automaticConnectedHistoryAttemptCooldown,
                zeroProgressRetry:
                    connectedRawHistoryCatchUpZeroProgressRetryInterval
            )
        guard finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
            generation: generation,
            reason: "exact_connected_raw_live_hr_preempt"
        ) else { return false }

        // Release the process-local FIFO hint before repairing the link. The
        // durable backlog/ticket remains authoritative and can retry only after
        // the persisted cooldown on a later exact accepted-HR boundary.
        connectedRawHistoryCatchUpContinuationPending = false
        connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
        connectedRawHistoryCatchUpEvaluationNotBefore = retryNotBefore
        connectedRawNoRadioCaptureDeferral = nil
        // Any pull queued behind this owner was minted before the failed
        // coexistence result. It cannot override the retry fence on the first
        // post-rebuild HR callback; the user can request a fresh pull after the
        // cooldown if the durable backlog still exists.
        queuedConnectedRawHistoryCatchUpIntent = nil
        let defaults = UserDefaults.standard
        defaults.set(
            "preempted_for_live_heart_rate",
            forKey: OfflineSyncDefaults.connectedSliceStatus
        )
        defaults.set(
            now.timeIntervalSince1970,
            forKey: OfflineSyncDefaults.connectedSliceAt
        )
        defaults.set(
            retryNotBefore.timeIntervalSince1970,
            forKey: OfflineSyncDefaults.connectedSliceCooldownUntil
        )
        defaults.set(
            "exact_connected_raw_live_hr_preempt",
            forKey: OfflineSyncDefaults.lastReason
        )
        // The next operation retires the CoreBluetooth session. Flush the
        // restoration-visible retry fence first so an immediate process kill
        // cannot remint this failed exact-raw attempt on relaunch.
        defaults.synchronize()
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_live_hr_preempted generation=%llu raw_gap_s=%.1f timeout_s=%.1f retry_unix=%.3f action=finish_generation_retain_spool_no_ack_then_rebuild_canonical_transport",
            generation,
            rawGap,
            timeout,
            retryNotBefore.timeIntervalSince1970
        )
        forceHardReconnectForPacketStall(
            peripheral: target,
            reason: "exact_connected_raw_live_hr_preempt",
            immediateConnectedRebuild: true
        )
        return true
    }

    /// Extends only the read-only derived-index warmup across a lock edge.
    /// The lease has no history generation, no ACK path, and no recovery
    /// state authority. If iOS expires it, the atomic snapshot is simply not
    /// published and the canonical raw/vault bytes remain untouched.
    private func beginHistoricalArchiveWarmBackgroundLease() {
        endHistoricalArchiveWarmBackgroundLease(status: "replaced")
        historicalArchiveWarmBackgroundTask = UIApplication.shared.beginBackgroundTask(
            withName: "Atria history identity index warmup"
        ) { [weak self] in
            MainActor.assumeIsolated {
                guard let self else { return }
                AtriaDebugLog("ATRIADBG historical_archive_warm background_lease=expired action=retain_raw_and_retry_no_ack_no_coverage")
                self.endHistoricalArchiveWarmBackgroundLease(status: "expired")
            }
        }
        AtriaDebugLog("ATRIADBG historical_archive_warm background_lease=%@ application_state=%ld",
                      historicalArchiveWarmBackgroundTask == .invalid ? "unavailable" : "active",
                      UIApplication.shared.applicationState.rawValue)
        historicalArchiveWarmLeaseTimeoutTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(20))
            guard !Task.isCancelled else { return }
            self?.endHistoricalArchiveWarmBackgroundLease(status: "bounded_timeout")
        }
    }

    private func endHistoricalArchiveWarmBackgroundLease(status: String) {
        historicalArchiveWarmLeaseTimeoutTask?.cancel()
        historicalArchiveWarmLeaseTimeoutTask = nil
        let task = historicalArchiveWarmBackgroundTask
        historicalArchiveWarmBackgroundTask = .invalid
        if task != .invalid {
            UIApplication.shared.endBackgroundTask(task)
        }
        AtriaDebugLog("ATRIADBG historical_archive_warm background_lease=%@", status)
    }

    /// UIKit background-task identifiers are process-local. If iOS terminates
    /// the process during a history serve, the persisted diagnostic must not
    /// continue saying "active" on the next launch: there is no in-memory
    /// owner and the durable gap is still pending. This is bookkeeping only;
    /// it neither clears a gap nor issues a BLE command.
    private func reconcileOrphanedBackgroundHistoryLeaseAtLaunch() {
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: OfflineSyncDefaults.backgroundLeaseStatus) == "active" else {
            return
        }
        defaults.set("orphaned_process_terminated",
                     forKey: OfflineSyncDefaults.backgroundLeaseStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.backgroundLeaseAt)
        AtriaDebugLog("ATRIADBG offline_sync background_lease=orphaned_process_terminated action=retain_gap_no_transport_mutation")
    }

    private func startOfflineHistoricalSync(reason: String,
                                            force: Bool,
                                            explicitRequest: Bool,
                                            connectedChunkedBackfill: Bool,
                                            attemptAt: Date,
                                            rawOnlyGapFingerprint: String?,
                                            gapFingerprint: String?,
                                            preserveConnectedRealtimeOwner: Bool = false,
                                            explicitPostWorkoutBankRequest: Bool = false) -> Bool {
        let connectedMotionBankRequestAuthority =
            transientConnectedMotionBankHistoryRequestAuthority.flatMap {
                authority -> ConnectedMotionBankHistoryRequestAuthority? in
                guard let peripheral,
                      connectedMotionBankHistoryRequestAuthorityIsValid(
                          authority,
                          peripheral: peripheral
                      ) else {
                    return nil
                }
                return authority
            }
        let connectedRawHistoryCatchUpRequestAuthority =
            transientConnectedRawHistoryCatchUpRequestAuthority.flatMap {
                authority -> ConnectedRawHistoryCatchUpRequestAuthority? in
                guard let peripheral,
                      connectedRawHistoryCatchUpRequestAuthorityIsValid(
                        authority,
                        peripheral: peripheral,
                        forActiveGeneration: false
                      ) else { return nil }
                return authority
            }
        let exactConnectedRealtimePreservingRequest =
            connectedMotionBankRequestAuthority != nil
                || connectedRawHistoryCatchUpRequestAuthority != nil
        guard historicalArchiveWarmState == .ready else {
            if historicalArchiveWarmState == .warming,
               let connectedMotionBankRequestAuthority {
                transientConnectedMotionBankArchiveWarmDeferredTicketID =
                    connectedMotionBankRequestAuthority.ticketID
            }
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitRequest
            )
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_archive_warm_at_transaction_boundary reason=%@ state=%@ action=no_attempt_no_generation_no_lease_no_command",
                reason,
                String(describing: historicalArchiveWarmState)
            )
            return false
        }
        // Never overwrite a raw ingress journal from a terminated process.
        // Its replay has no reducer/ACK authority, but preserves real frames
        // that otherwise disappear at the next generation boundary.
        if archiveOrphanHistoricalIngressIfNeeded(
            reason: reason,
            force: force,
            explicitRequest: explicitRequest
        ) {
            if orphanHistoricalIngressArchiveInFlight,
               let connectedMotionBankRequestAuthority {
                transientConnectedMotionBankDeferredLocalDependency = .init(
                    ticketID: connectedMotionBankRequestAuthority.ticketID,
                    dependency: .orphanArchive
                )
            }
            return false
        }
        // Automatic recovery is subordinate to a visible live dashboard. The
        // request stays pending and can run after backgrounding or a later
        // natural link loss; an explicit user import remains allowed.
        if foregroundInteractiveMode
            && !explicitRequest
            && !exactConnectedRealtimePreservingRequest {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: false
            )
            let defaults = UserDefaults.standard
            defaults.set("deferred_interactive_live_priority",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=%@ detail=interactive_foreground_live_priority action=retain_pending_no_history_owner force=%d",
                          reason,
                          force ? 1 : 0)
            return false
        }
        // Recheck exact epoch authority and CoreBluetooth state at the
        // transaction boundary. Restoration can activate the callback epoch
        // before MainActor publishes `self.peripheral`, and a disconnected
        // object can become connecting/connected while the request evaluates
        // its durable stores. Neither race grants history ownership.
        let transactionPeripheralState = peripheral?.state
        let transactionRealtimeEpochOwned = bleCallbackEpochFence.hasActiveOwner
        var transactionConnectInterestIDs = Set<UUID>()
        if let peripheralID = peripheral?.identifier {
            transactionConnectInterestIDs.insert(peripheralID)
        }
        if let savedIDString = UserDefaults.standard.string(
            forKey: LinkDefaults.savedPeripheralUUID
        ), let savedID = UUID(uuidString: savedIDString) {
            transactionConnectInterestIDs.insert(savedID)
        }
        let transactionStandingConnectOwned = connectedPeripheralRetainer
            .hasRetainedConnectInterest(
                peripheralIDs: transactionConnectInterestIDs
            )
        guard exactConnectedRealtimePreservingRequest
                || !Self.shouldDeferHistoricalTransportForRealtimeContinuity(
            linkConnected: transactionPeripheralState == .connected
                || transactionRealtimeEpochOwned,
            linkConnecting: transactionPeripheralState == .connecting
                || transactionStandingConnectOwned,
            syncInProgress: offlineHistoricalSyncInProgress
        ) else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitRequest,
                explicitPostWorkoutBankRequest:
                    explicitPostWorkoutBankRequest,
                preserveConnectedRealtimeOwner:
                    preserveConnectedRealtimeOwner
            )
            let defaults = UserDefaults.standard
            defaults.set("deferred_realtime_owner_at_transaction_boundary",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_realtime_owner_at_transaction_boundary reason=%@ peripheral_state=%ld epoch_owner=%d action=no_attempt_no_generation_no_history_command_no_cancel",
                reason,
                transactionPeripheralState?.rawValue ?? -1,
                (transactionRealtimeEpochOwned
                    || transactionStandingConnectOwned) ? 1 : 0
            )
            return false
        }
        let connectedRawHistoryCatchUpStartFrontierUnix =
            UserDefaults.standard.double(
            forKey: OfflineSyncDefaults.drainedThroughUnix
        )
        // `startOfflineHistoricalSync` is MainActor-isolated, so no accepted
        // realtime callback can interleave between this synchronous journal
        // flush and the atomic transport claim below. Establish the live
        // workout/session durability snapshot and save request before the
        // history phase begins owning BLE callbacks; a failed claim may cause
        // an extra flush, but never a claim that preceded that snapshot.
        flushActiveSessionJournal(reason: "offline_sync_preflight_\(reason)")
        var syncGeneration: UInt64 = 0
        let installHistoryTransportClaim = { [self] in
            // Recheck the exact callback epoch while the retainer lock excludes
            // retain-before-connect publication. Restoration and didConnect
            // retain first, so either signal closes the prepublication race.
            if let connectedMotionBankRequestAuthority {
                guard let peripheral,
                      connectedMotionBankHistoryRequestAuthorityIsValid(
                          connectedMotionBankRequestAuthority,
                          peripheral: peripheral
                      ) else {
                    return false
                }
            } else if let connectedRawHistoryCatchUpRequestAuthority {
                guard let peripheral,
                      connectedRawHistoryCatchUpRequestAuthorityIsValid(
                        connectedRawHistoryCatchUpRequestAuthority,
                        peripheral: peripheral,
                        forActiveGeneration: false
                      ) else {
                    return false
                }
            } else {
                guard !bleCallbackEpochFence.hasActiveOwner else {
                    return false
                }
            }
            offlineHistoricalSyncGeneration &+= 1
            syncGeneration = offlineHistoricalSyncGeneration
            connectedRawHistoryCleanACKFinishAuthority = nil
            connectedMotionBankHistoryCleanACKFinishAuthority = nil
            if let connectedMotionBankRequestAuthority {
                activeConnectedMotionBankHistoryGenerationAuthority = .init(
                    request: connectedMotionBankRequestAuthority,
                    generation: syncGeneration
                )
            } else {
                activeConnectedMotionBankHistoryGenerationAuthority = nil
            }
            if let connectedRawHistoryCatchUpRequestAuthority {
                activeConnectedRawHistoryCatchUpGenerationAuthority = .init(
                    request: connectedRawHistoryCatchUpRequestAuthority,
                    generation: syncGeneration,
                    startedAt: attemptAt,
                    startFrontierUnix:
                        connectedRawHistoryCatchUpStartFrontierUnix
                )
            } else {
                activeConnectedRawHistoryCatchUpGenerationAuthority = nil
            }
            _ = historyTransportPhaseFence.activate(
                generation: syncGeneration,
                usesExplicitHistoryProfile: explicitRequest
            )
            offlineHistoricalSyncInProgress = true
            return true
        }
        let historyTransportClaimed: Bool
        if exactConnectedRealtimePreservingRequest,
           let transactionPeripheral = peripheral {
            historyTransportClaimed = connectedPeripheralRetainer
                .claimExclusiveConnectedCanonicalTransport(
                    transactionPeripheral,
                    claim: installHistoryTransportClaim
                )
        } else {
            historyTransportClaimed = connectedPeripheralRetainer
                .claimHistoryTransportIfNoRetainedConnect(
                    peripheralIDs: transactionConnectInterestIDs,
                    claim: installHistoryTransportClaim
                )
        }
        guard historyTransportClaimed else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitRequest,
                explicitPostWorkoutBankRequest:
                    explicitPostWorkoutBankRequest,
                preserveConnectedRealtimeOwner:
                    preserveConnectedRealtimeOwner
            )
            AtriaDebugLog(
                "ATRIADBG offline_sync status=deferred_realtime_owner_at_atomic_claim reason=%@ action=no_attempt_no_generation_no_phase_no_history_command_no_cancel",
                reason
            )
            return false
        }
        if connectedMotionBankRequestAuthority != nil,
           pendingConnectedMotionBankSchedulingTicketID
                == connectedMotionBankRequestAuthority?.ticketID,
           let pending = pendingOfflineHistoricalSyncRequest,
           pending.force,
           pending.explicitPostWorkoutBankRequest,
           pending.preserveConnectedRealtimeOwner,
           !pending.explicitRequest {
            // The exact generation now owns this motion-only scheduling
            // request. Retire only that Boolean tuple so terminal completion
            // cannot reissue it generically; a coalesced attended request is
            // distinct user authority and deliberately remains pending.
            pendingOfflineHistoricalSyncRequest = nil
            pendingConnectedMotionBankSchedulingTicketID = nil
            pendingForcedHistoricalSyncLiveResumeAttemptedRequest = nil
            pendingForcedHistoricalSyncLiveResumeRetryNotBefore = nil
        }
        // The launch intent is now represented by the active generation (or by
        // one of the retained cutover/request states). Clearing it here keeps the
        // ownership fence finite without opening a pre-transaction scan window.
        explicitHistoryLaunchIntentPending = false
        let defaults = UserDefaults.standard
        defaults.set(attemptAt, forKey: OfflineSyncDefaults.lastAttemptAt)
        defaults.set(defaults.integer(forKey: OfflineSyncDefaults.attempts) + 1,
                     forKey: OfflineSyncDefaults.attempts)
        defaults.set("starting", forKey: OfflineSyncDefaults.lastStatus)
        defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
        // Handoff-10 CP2B: durable slice-START receipt for the connected
        // catch-up lane. If this process dies before the terminal receipt,
        // the surviving `.started` row re-arms catch-up scheduling on the
        // next launch/reconnect/accepted-HR without a foreground rescue. It
        // asserts nothing about ACK, durable persistence, or success — the
        // terminal write at the durable boundary replaces it.
        if activeConnectedRawHistoryCatchUpAuthority(
            generation: syncGeneration
        ) != nil {
            Self.storeDurableProductiveSliceReceipt(
                .init(
                    generation: syncGeneration,
                    attemptStartedAtUnix: attemptAt.timeIntervalSince1970,
                    startFrontierUnix: defaults.double(
                        forKey: OfflineSyncDefaults.drainedThroughUnix
                    ),
                    endFrontierUnix: 0,
                    durableRowsDelta: 0,
                    flushBoundaryIdentity: "slice_started_\(reason)",
                    liveRestoredAtUnix: nil,
                    gapFingerprint: currentHistoricalGapFingerprintForCadence(
                        defaults: defaults
                    ),
                    status: .started,
                    recordedAtUnix: attemptAt.timeIntervalSince1970,
                    processInstanceID: Self.processInstanceID
                ),
                defaults: defaults
            )
        }
        offlineHistoricalSyncRawOnlyGapFingerprint = rawOnlyGapFingerprint
        offlineHistoricalSyncGapFingerprint = gapFingerprint
        if !Self.continuesHistoricalRecoveryEpisode(
            historicalRecoveryPresentation
        ) {
            offlineHistoricalRecoveryEpisodeStartRows =
                historicalArchiveRows
        }
        if defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) {
            defaults.set(attemptAt.timeIntervalSince1970,
                         forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt)
        }
        offlineHistoricalSyncPreviousStandardHROnlyMode = standardHROnlyMode
        offlineHistoricalSyncStartRows = historicalArchiveRows
        offlineHistoricalSyncMadeRequestedMetricProgress = false
        offlineHistoricalSyncResolvedGapCoverage = false
        offlineHistoricalSyncReachedTerminal = false
        offlineHistoricalSyncPreservesConnectedRealtimeOwner =
            activeConnectedRealtimePreservingHistoryAuthorityExists(
                generation: syncGeneration
            )
        offlineHistoricalSyncExplicitPostWorkoutBankRequest =
            explicitPostWorkoutBankRequest
        verifiedEmptyHistoryCursorGeneration = nil
        durableTerminalAuthorityGeneration = nil
        gate4DailyBankRearmTask?.cancel()
        gate4DailyBankRearmTask = nil
        gate4DailyBankHistoryServeIdentity = nil
        gate4DailyBankHistoryStartIdentity = nil
        gate4DailyBankFullDrainAuthorityIdentity = nil
        gate4DailyBankTerminalIdentity = nil
        #if DEBUG
        if reason.hasPrefix("workout_motion_bank_daily_checkpoint_"),
           ProcessInfo.processInfo.arguments.contains(
               "--atria-gate4-rearm-bank-during-history"
           ),
           let ticketID = defaults.string(
            forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
           ),
           !ticketID.isEmpty,
           let strapIdentifier = peripheral?.identifier {
            gate4DailyBankRearmIntent = .init(
                generation: syncGeneration,
                ticketID: ticketID,
                strapIdentifier: strapIdentifier
            )
        } else {
            gate4DailyBankRearmIntent = nil
        }
        #else
        // Physical v5 proved that opening a new 0x69 bank while an older FIFO
        // ticket was still draining grew the backlog instead of converging.
        // The coexistence command remains research-only until a future
        // strap-specific capability proof can demonstrate the opposite.
        gate4DailyBankRearmIntent = nil
        #endif
        historicalConsumerReceiptRequiredGenerations.remove(syncGeneration)
        historicalConsumerReceiptedGenerations.remove(syncGeneration)
        offlineHistoricalSyncHistoryStartObserved = false
        offlineHistoricalSyncLastDurableProgressUptime = nil
        markActiveWorkoutHistoricalMotionBankAttemptForStartedGeneration(
            at: attemptAt,
            generation: syncGeneration
        )
        lastHistoricalRecoveryProgressPublishAt = nil
        lastHistoricalRecoveryProgressPublishedRecords = nil
        publishHistoricalRecoveryProgressIfNeeded(now: attemptAt)
        suspendWorkoutMotionLeaseForHistoricalSync(generation: syncGeneration)
        historyRealtimeStopRequestedGeneration = nil
        historyRealtimeStopCompletedGeneration = nil
        lastProprietaryWriteCompletion = nil
        beginOfflineHistoricalSyncBackgroundLease(generation: syncGeneration)
        offlineHistoricalSyncReason = reason
        // Production currently sends WHOOP's verified full-dump command. It
        // does not encode the local gap interval and no accepted response is
        // durably tied to that interval+attempt. Keep this drain raw-only: a
        // local exact gap is not strap-issued no-data/coverage authority.
        activeHistoricalRequestBinding = nil
        historicalFullDrainWriteEvidence = nil
        historicalAdmissionAttempt = nil
        historicalAdmissionHighestOrdinal = nil
        historicalAdmissionFailed = false
        historicalCheckpointCoordinator.begin(generation: syncGeneration)
        let persistedFullDrainAuthority = try? historicalFullDrainCoverageStore.load()
        if activeConnectedRawHistoryCatchUpAuthority(
            generation: syncGeneration
        ) != nil {
            // This slice advances only the strap's forward raw cursor. It is not
            // authority for any exact local gap or parked full-drain journal.
            selectedFullDrainGap = nil
        } else if let persisted = persistedFullDrainAuthority,
           persisted.status == .draining,
           let gapID = UUID(uuidString: persisted.gap.gapIdentifier) {
            selectedFullDrainGap = AtriaHistoricalGapLedger.recoveryCandidate(
                id: gapID,
                startUnix: persisted.gap.startUnix,
                endUnix: persisted.gap.endUnix,
                reason: persisted.gap.reason
            )
            if selectedFullDrainGap == nil {
                let oldAuthorityCleared =
                    reconcileStaleDrainingFullDrainAuthority(
                        persisted,
                        reason: "offline_sync_preflight"
                    )
                if oldAuthorityCleared {
                    selectedFullDrainGap = AtriaHistoricalGapLedger
                        .newestClosedRecoveryCandidate()
                }
            }
        } else {
            // An automatic reconnect exists to repair the gap that just
            // closed, not to make the user wait behind unrelated historical
            // outages. Older intervals remain in the durable ledger and are
            // never discarded; only this transaction's coverage authority is
            // scoped to the newest exact candidate.
            if gate2FullDrainProofEnabled,
               let requestedGapID = gate2FullDrainRequestedGapID {
                selectedFullDrainGap = AtriaHistoricalGapLedger
                    .allClosedRecoveryCandidates()
                    .first { $0.window.id == requestedGapID }
            } else {
                // Both automatic and normal user repair target the gap the
                // user just experienced. Older unresolved intervals remain in
                // the ledger for later archival sweep; they must not make a
                // manual retry ignore a fresh workout/reconnect outage.
                selectedFullDrainGap = AtriaHistoricalGapLedger
                    .newestClosedRecoveryCandidate()
            }
        }
        fullDrainTransportNonce = UUID().uuidString.lowercased()
        pendingHistoryClockCommandSequence = nil
        pendingHistoryClockCommandRequestedAtUnix = nil
        pendingHistoryClockWriteCompletedAtUnix = nil
        productionHistoryReadPreflightRequired = Self
            .shouldUseProductionHistoryReadPreflight(
                explicitRequest: explicitRequest,
                force: force,
                reason: reason
            )
        historyReadPreflightGate.reset()
        acceptedHistoryReadPreflightIdentity = nil
        productionFullDrainClockAuthorityEnabled = false
        historyClockRef = nil
        acceptedHistoryClockResponseSequence = nil
        acceptedHistoryClockDeviceUnix = nil
        acceptedHistoryClockWallUnix = nil
        acceptedHistoryClockResponseAtUnix = nil
        pendingHistoryDataRangeCommandSequence = nil
        pendingHistoryDataRangeWriteCompletedAtUnix = nil
        acceptedHistoryDataRange = nil
        pendingHistoryDataRangeRequestedAtUnix = nil
        acceptedHistoryDataRangeResponseAtUnix = nil
        acceptedHistoryDataRangeResponseUptime = nil
        acceptedHistoryStartSequence = nil
        acceptedHistoryStartAtUnix = nil
        historyFirstFrameWatchdogTask?.cancel()
        historyFirstFrameWatchdogTask = nil
        historyFirstFrameReceivedGeneration = nil
        pendingFullDrainCommandRequestedAtUnix = nil
        activeFullDrainEventIdentity = nil
        historicalIngressSpool?.remove()
        historicalIngressSpool = nil
        historicalIngressSpoolFailure = nil
        historicalIngressDeferredEvent = nil
        historicalIngressStrapIdentifier = peripheral?.identifier.uuidString
            ?? UserDefaults.standard.string(forKey: LinkDefaults.savedPeripheralUUID)
            ?? "unknown-whoop4"
        let ingressDirectory = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        )[0].appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionDirectoryName,
            isDirectory: true
        )
        let ingressURL = ingressDirectory.appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionFileName
        )
        // The orphan replay above is the sole retirement path for a prior
        // generation. If one still exists, fail closed rather than silently
        // replacing it with a new spool.
        if FileManager.default.fileExists(atPath: ingressURL.path) {
            historicalAdmissionFailed = true
            historicalIngressSpoolFailure = "orphan_ingress_not_retired"
            AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=orphan_not_archived action=withhold_ack_retain_gap", syncGeneration)
        }
        do {
            historicalIngressSpool = try AtriaWhoop4HistoricalIngressSpool(
                url: ingressURL,
                generation: syncGeneration
            )
        } catch {
            historicalAdmissionFailed = true
            historicalIngressSpoolFailure = String(describing: error)
            AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=spool_open_failed error=%@ action=withhold_ack_retain_gap",
                          syncGeneration, historicalIngressSpoolFailure ?? "unknown")
        }
        historicalAdmissionBatchInFlight = false
        historicalAdmissionBatchScheduled = false
        fullDrainHistoryEndPayloads.removeAll(keepingCapacity: false)
        fullDrainACKPermits.removeAll(keepingCapacity: false)
        latestFullDrainDurableStores = nil
        fullDrainHistoryCompletePayload = nil
        AtriaDebugLog("ATRIADBG history_request_authority status=%@ reason=%@ detail=full_flash_positive_gap_authority gap=%@ action=clock_then_drain",
                      selectedFullDrainGap == nil ? "raw_only_no_closed_gap" : "candidate_selected",
                      reason,
                      selectedFullDrainGap?.window.id.uuidString ?? "none")
        prepareHistorySequenceContinuity(for: peripheral?.identifier.uuidString)
        _ = historyDrain.begin(generation: syncGeneration)
        startHistoricalDrainTelemetry(generation: syncGeneration)
        historicalMetricDurabilityFence.begin(generation: syncGeneration)
        pendingHistoricalRawFrontierGeneration = syncGeneration
        pendingHistoricalRawFrontierUnix = nil
        noteOfflineHistoricalSyncProgress(
            generation: syncGeneration,
            reason: "generation_started"
        )
        pendingHistoryEndACK = nil
        pendingHistoryACKAttempts = 0
        historyACKGate.reset()
        historicalPageContinuationTask?.cancel()
        historicalPageContinuationTask = nil
        historicalPageContinuationGeneration = nil
        historicalPageContinuationBoundaryID = nil
        historicalPageContinuationHasFutureAttempt = false
        historicalPageContinuationReplayBackoffStep = 0
        historyFirstFrameWatchdogTask?.cancel()
        historyFirstFrameWatchdogTask = nil
        historyFirstFrameReceivedGeneration = nil
        historicalReplayACKTask?.cancel()
        historicalReplayACKTask = nil
        historicalReplayACKBoundaryID = nil
        historyDurableFlushInFlight = false
        historicalArchiveWriteFailures = 0
        // Preserve the explicit, user-approved one-shot clock repair across
        // generation setup. This flag is set from the launch argument before
        // the generation is created; resetting it here used to silently turn
        // the approved repair back into an ordinary 0x16 history request.
        // Automatic recovery never sets this flag.
        let preserveUserApprovedHistoryClockRepair = historyClockSyncEnabled
        let preserveDebugHistoryRangeProbe = historyOnlyProbeEnabled
            && (historySelectorSweepEnabled || historyDataRangeSweepEnabled)
            && !historySkipDataRangeRequest
        historyOnlyProbeEnabled = true
        cancelHistoryOnlyProbe(reason: "new_offline_generation")
        // The four-form clock experiment is not part of the validated WHOOP 4
        // recovery handshake. Sending all four WR commands back-to-back filled
        // the callback ledger and physically disconnected the strap before the
        // full-drain command. Production archives the strap's record timestamp
        // directly; explicit selector/range diagnostics may retain clock probes.
        historyClockSyncEnabled = preserveDebugHistoryRangeProbe
            || preserveUserApprovedHistoryClockRepair
        probeCommandMode = .withResponse
        if preserveDebugHistoryRangeProbe {
            if historyInitSweepCommands.isEmpty {
                historyInitSweepCommands = [
                    [Cmd.abortHistoricalTransmits, 0x00],
                    [Cmd.enterHighFreqSync, 0x00],
                ]
            }
            historySkipDataRangeRequest = false
        } else {
            // Production WHOOP 4 recovery first quiets only the proprietary
            // R10/R11 raw stream, then issues the stable, bounded offload
            // request. Standard 2A37 HR/RR remains live. Abort and
            // high-frequency-sync are research controls: inserting them here
            // can leave an otherwise connected strap returning zero rows.
            historyInitSweepCommands = Self.productionHistoricalRecoveryInitCommands()
            historySkipDataRangeRequest = true
        }
        if !preserveDebugHistoryRangeProbe {
            historyDataRangeSweepEnabled = false
        }
        historyDataRangePendingRequests.removeAll()
        ackedHistoryAckKeys.removeAll()
        realtimeArmed = false
        realtimeOn = false
        // 0x03/0 is the verified realtime-HR stop. It is sent by the history
        // handshake only after TX has been rediscovered. Sending it here made
        // recovery launch-order dependent because a restored minimal 2A37 link
        // commonly has no cached proprietary TX characteristic yet.
        txCharacteristic = nil
        UserDefaults.standard.set("armed", forKey: OfflineSyncDefaults.lastStatus)
        UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
        let initSweepLabel = historyInitSweepCommands
            .map { Self.hex($0) }
            .joined(separator: ",")
        // Legacy static-check token from the pre-HIST-1 fail-closed path:
        // live_realtime=skipped metrics_fail_closed=1
        AtriaDebugLog("ATRIADBG offline_sync status=armed reason=%@ mode=%@ init_sweep=%@ ack_mode=enddata live_realtime=skipped metrics_fail_closed=1 cmd22=%d connected_chunked=%d",
              reason,
              connectedChunkedBackfill ? "connected_chunked_backfill" : (preserveDebugHistoryRangeProbe ? "selector_probe" : "safe_history_backfill"),
              initSweepLabel,
              historySkipDataRangeRequest ? 0 : 1,
              connectedChunkedBackfill ? 1 : 0)

        if activeConnectedRealtimePreservingHistoryAuthorityExists(
            generation: syncGeneration
        ) {
            guard let current = peripheral,
                  activeConnectedRealtimePreservingHistoryAuthorityIsValid(
                    generation: syncGeneration,
                    peripheral: current
                  ) else {
                _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                    generation: syncGeneration,
                    reason:
                        "exact_connected_history_authority_lost_before_discovery"
                )
                return true
            }
            // This deadline is independent of page progress. Standard 2A37 is
            // never unsubscribed by the production history init command set;
            // the budget merely releases local proprietary command ownership.
            armConnectedRealtimePreservingHistoryBudget(
                generation: syncGeneration
            )
        }
        if let peripheral {
            dbgLast = "offline sync reconnect"
            switch peripheral.state {
            case .connected:
                if activeConnectedRealtimePreservingHistoryAuthorityExists(
                    generation: syncGeneration
                ), !activeConnectedRealtimePreservingHistoryAuthorityIsValid(
                    generation: syncGeneration,
                    peripheral: peripheral
                ) {
                    _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                        generation: syncGeneration,
                        reason:
                            "exact_connected_history_authority_lost_at_discovery"
                    )
                    return true
                }
                peripheral.discoverServices(discoveryServicesForCurrentMode)
                AtriaDebugLog("ATRIADBG offline_sync status=connected_chunked reason=%@ action=discover_services_without_live_link_deferral samples=%d",
                              reason,
                              session.count)
            case .connecting:
                // The atomic retainer claim published this history generation
                // before any later retain-before-connect could proceed. A
                // connect beginning now belongs to this safe natural-boundary
                // owner; await didConnect without issuing a second request.
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=awaiting_claimed_history_connect reason=%@ generation=%llu action=keep_single_existing_connect_no_cancel",
                    reason,
                    syncGeneration
                )
            default:
                self.peripheral = nil
                recomputeConnectionStatus(reason: "offline_sync_stale_peripheral")
                if central.state == .poweredOn {
                    startScan(reason: "offline_sync_\(reason)")
                }
            }
        } else if central.state == .poweredOn {
            startScan(reason: "offline_sync_\(reason)")
        }

        armOfflineHistoricalSyncIdleWatchdog(
            generation: syncGeneration,
            reason: reason
        )
        return true
    }

    /// Only a physically started generation may spend a bank ticket's bounded
    /// attempt or clear its exact maintenance priority. Same-link generations
    /// take the ticket/strap tuple from their typed, atomic authority; legacy
    /// disconnected bank recovery retains its existing transient path.
    private func markActiveWorkoutHistoricalMotionBankAttemptForStartedGeneration(
        at date: Date,
        generation: UInt64
    ) {
        let defaults = UserDefaults.standard
        let exactAuthority = activeConnectedMotionBankHistoryAuthority(
            generation: generation
        )
        guard exactAuthority != nil
                || transientMotionBankRequestAuthorization else { return }
        guard let ticketID = exactAuthority?.request.ticketID
                ?? defaults.string(
                    forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
                ),
        let strapIdentifier = exactAuthority?.request.strapIdentifier
                ?? peripheral?.identifier.uuidString
                ?? defaults.string(forKey: LinkDefaults.savedPeripheralUUID),
        let ticket = AtriaWhoop4MotionBankCoverageLedger.pendingOffload(
            id: ticketID,
            strapIdentifier: strapIdentifier
        ),
        ticket.effectiveRecoveryMode == .directOffload,
        let attempted =
            AtriaWhoop4MotionBankCoverageLedger.markOffloadAttempt(
                id: ticket.id,
                at: date
            ) else { return }

        if defaults.string(
            forKey:
                Self.workoutHistoricalMotionBankTransportDeferredTicketIDKey
        ) == ticket.id {
            defaults.removeObject(
                forKey:
                    Self.workoutHistoricalMotionBankTransportDeferredTicketIDKey
            )
        }

        if defaults.string(
            forKey:
                Self.workoutHistoricalMotionBankMaintenanceTicketIDKey
        ) == ticket.id {
            defaults.removeObject(
                forKey:
                    Self.workoutHistoricalMotionBankMaintenanceTicketIDKey
            )
        }
        AtriaDebugLog(
            "ATRIADBG workout_motion_bank_offload status=generation_started ticket=%@ generation=%llu attempt=%d action=consume_exact_maintenance_priority",
            ticket.id,
            generation,
            attempted.attempts
        )
    }

    /// Replays a previous-process spool before a new generation can reuse its
    /// filename. Only exact frame bytes are archived. Metadata cannot safely
    /// reconstruct an old reducer boundary, so it is intentionally ignored;
    /// this path never writes an ACK, cursor, admission record, terminal proof,
    /// or gap-coverage evidence. Any error retains the complete original file
    /// for an idempotent later retry (archive identities deduplicate frames).
    @discardableResult
    private func archiveOrphanHistoricalIngressIfNeeded(
        reason: String,
        force: Bool,
        explicitRequest: Bool,
        retainHistoricalRequest: Bool = true
    ) -> Bool {
        let ingressDirectory = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        )[0].appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionDirectoryName,
            isDirectory: true
        )
        let ingressURL = ingressDirectory.appendingPathComponent(
            AtriaWhoop4HistoricalIngressSpool.productionFileName
        )
        if orphanHistoricalIngressArchiveInFlight {
            // The caller may have just consumed the sole explicit request
            // while crossing the fresh history-owner disconnect boundary.
            // Preserve that authority until the existing replay worker
            // retires its journal; otherwise the durable prefix survives but
            // the exact drain silently stops after process restoration.
            // An exact connected-raw token cannot survive this asynchronous
            // replay, and the accepted-HR orphan sweep is raw archival only.
            // Neither is permission to manufacture a generic Boolean history
            // request that the healthy live-owner gate will reject later.
            if retainHistoricalRequest,
               transientConnectedRawHistoryCatchUpRequestAuthority == nil {
                retainPendingOfflineHistoricalSyncRequest(
                    reason: reason,
                    force: force,
                    explicitRequest: explicitRequest
                )
            }
            AtriaDebugLog(
                "ATRIADBG historyIngress status=replay_in_flight_request_retained reason=%@ force=%d explicit=%d action=resume_after_orphan_retirement",
                reason,
                force ? 1 : 0,
                explicitRequest ? 1 : 0
            )
            return true
        }

        // The v1 spool header contains no strap identifier. Prefer the
        // terminally verified history owner, but a process killed during its
        // *first* successful serve has no such terminal record yet. In that
        // narrow case, the existing live-link identity is the app's only
        // persisted pairing proof: require it to match the saved connected
        // peripheral before archiving. It is still raw-only archival, never a
        // history protocol authorization or gap-coverage assertion.
        guard let strapIdentifier = peripheral?.identifier.uuidString else {
            AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_no_connected_owner action=retain_raw_no_new_generation")
            return true
        }
        let defaults = UserDefaults.standard
        let terminallyVerifiedOwner = defaults.string(
            forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID
        )
        let currentLinkedOwner = defaults.string(forKey: LinkDefaults.savedPeripheralUUID)
        guard strapIdentifier == terminallyVerifiedOwner
                || strapIdentifier == currentLinkedOwner else {
            AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_identity_unverified action=retain_raw_no_new_generation")
            return true
        }
        // This method is also called from every accepted live HR callback. A
        // non-nil spool belongs to the *current* history reducer and may still
        // be receiving CoreBluetooth frames; never inspect or seal it here.
        guard historicalIngressSpool == nil else {
            return true
        }
        let hasIngressSource = FileManager.default.fileExists(atPath: ingressURL.path)
        guard hasIngressSource || AtriaWhoop4HistoricalOrphanVault.hasPotentialProductionEntries() else {
            return false
        }
        if retainHistoricalRequest,
           transientConnectedRawHistoryCatchUpRequestAuthority == nil {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: force,
                explicitRequest: explicitRequest
            )
        }
        // Set this before dispatch so another HR callback cannot schedule a
        // second reader while the first worker is hashing/copying the source.
        orphanHistoricalIngressArchiveInFlight = true

        let archiveWarmGroup = historicalArchiveWarmGroup
        orphanHistoricalIngressArchiveQueue.async { [weak self] in
            var openedVault: AtriaWhoop4HistoricalOrphanVault?
            var sealedOrphans: [AtriaWhoop4HistoricalOrphanVault.Entry] = []
            do {
                let orphanVault = try AtriaWhoop4HistoricalOrphanVault.production()
                openedVault = orphanVault
                if hasIngressSource {
                let orphanGeneration = try AtriaWhoop4HistoricalIngressSpool.generation(
                    at: ingressURL
                )
                // Do not make protection of real, previously received strap
                // frames depend on opening the large canonical identity index.
                // Seal the raw spool first; canonical replay below remains the
                // sole route that can ever grant ACK or coverage authority.
                let sealed = try orphanVault.seal(
                    sourceURL: ingressURL,
                    strapIdentifier: strapIdentifier,
                    generation: orphanGeneration
                )
                try FileManager.default.removeItem(at: ingressURL)
                AtriaDebugLog("ATRIADBG historyIngress status=sealed_to_orphan_vault generation=%llu bytes=%llu action=raw_only_no_ack_no_coverage",
                              orphanGeneration,
                              sealed.byteCount)
                sealedOrphans = [sealed]
                } else {
                // A process may be suspended after seal but before its large
                // canonical index becomes ready. Resume that verified raw
                // vault on every later connection to the same paired strap.
                sealedOrphans = try orphanVault.validatedEntries(for: strapIdentifier)
                }
                guard !sealedOrphans.isEmpty else {
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        self.orphanHistoricalIngressArchiveInFlight = false
                        _ = self
                            .resumeConnectedMotionBankAfterLocalDependencyIfNeeded(
                                .orphanArchive
                            )
                    }
                    return
                }
            } catch {
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.orphanHistoricalIngressArchiveInFlight = false
                    self.releaseConnectedMotionBankLocalDependencyFirstRefusal(
                        reason: "orphan_vault_open_failed",
                        expectedDependency: .orphanArchive
                    )
                    AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_vault_open_failed error=%@ action=retain_raw_no_ack_no_coverage", String(describing: error))
                }
                return
            }
            guard let orphanVault = openedVault else { return }
            let orphansToReplay = sealedOrphans
            defer {
                orphansToReplay.forEach {
                    HistoricalArchive.endDurableDrain(generation: $0.generation)
                }
            }
            var archivedFrames = 0
            var ignoredMetadata = 0
            do {
                AtriaDebugLog("ATRIADBG historyIngress status=replay_waiting_for_identity_store entries=%d", orphansToReplay.count)
                guard Self.waitForHistoricalArchiveWarm(
                    archiveWarmGroup,
                    timeout: Self.historicalArchiveWarmReplayWaitLimit
                ) else {
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        self.orphanHistoricalIngressArchiveInFlight = false
                        self.releaseConnectedMotionBankLocalDependencyFirstRefusal(
                            reason: "orphan_identity_store_warm_timeout",
                            expectedDependency: .orphanArchive
                        )
                        AtriaDebugLog(
                            "ATRIADBG historyIngress status=deferred reason=identity_store_warm_timeout entries=%d action=retain_orphan_raw_retry_on_live",
                            orphansToReplay.count
                        )
                    }
                    return
                }
                AtriaDebugLog("ATRIADBG historyIngress status=replay_identity_store_ready entries=%d", orphansToReplay.count)
                for sealedOrphan in orphansToReplay {
                    let orphanGeneration = sealedOrphan.generation
                    var cooperativeSliceStartedAt =
                        ProcessInfo.processInfo.systemUptime
                    var cooperativeSliceFrameCount = 0
                    AtriaDebugLog("ATRIADBG historyIngress status=replay_worker_started generation=%llu", orphanGeneration)
                    let spool = try orphanVault.spool(for: sealedOrphan)
                    AtriaDebugLog("ATRIADBG historyIngress status=replay_journal_opened pending=%d generation=%llu", spool.pendingCount, orphanGeneration)
                    while let event = try spool.popFirst() {
                    switch event {
                    case let .frame(payload, clock, clockAuthorityEnabled):
                        let reference = clock.map { clock in
                            let drift = Int(clock.wall) - Int(clock.device)
                            let snapped: Int
                            if abs(drift) >= 86_400 {
                                let granularity = 300
                                snapped = drift >= 0
                                    ? ((drift + granularity / 2) / granularity) * granularity
                                    : ((drift - granularity / 2) / granularity) * granularity
                            } else {
                                snapped = drift
                            }
                            return AtriaWhoop4HistoryArchivePipeline.ClockReference(
                                device: clock.device,
                                wall: clock.wall,
                                driftSeconds: drift,
                                snappedDriftSeconds: snapped
                            )
                        }
                        let computation = AtriaWhoop4HistoryArchivePipeline.prepare(
                            payload: payload,
                            clock: reference,
                            historyClockSyncEnabled: clockAuthorityEnabled
                        )
                        let persisted = AtriaWhoop4HistoryArchivePipeline.persist(
                            computation,
                            strapIdentifier: strapIdentifier,
                            generation: orphanGeneration
                        )
                        guard persisted.succeeded else {
                            throw NSError(
                                domain: "AtriaOrphanHistoricalIngress",
                                code: 1,
                                userInfo: [NSLocalizedDescriptionKey:
                                    persisted.errorDescription ?? "archive_persist_failed"]
                            )
                        }
                        archivedFrames += 1
                        cooperativeSliceFrameCount += 1
                        let pause = Self.orphanHistoryReplayPauseDuration(
                            workDuration:
                                ProcessInfo.processInfo.systemUptime
                                    - cooperativeSliceStartedAt,
                            processedFrames: cooperativeSliceFrameCount
                        )
                        if pause > 0 {
                            Thread.sleep(forTimeInterval: pause)
                            cooperativeSliceStartedAt =
                                ProcessInfo.processInfo.systemUptime
                            cooperativeSliceFrameCount = 0
                        }
                        AtriaDebugLog("ATRIADBG historyIngress status=replay_frame_persisted count=%d generation=%llu", archivedFrames, orphanGeneration)
                    case .metadata:
                        ignoredMetadata += 1
                    }
                    }
                    // `persist` is per-frame durable; synchronize the
                    // canonical archive once more before retiring this source
                    // journal. This does not imply gap coverage.
                    AtriaDebugLog("ATRIADBG historyIngress status=replay_flush_started frames=%d generation=%llu", archivedFrames, orphanGeneration)
                    _ = try HistoricalArchive.synchronizeDurableStorage(
                        generation: orphanGeneration
                    )
                    try orphanVault.retire(sealedOrphan)
                }
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.orphanHistoricalIngressArchiveInFlight = false
                    AtriaDebugLog("ATRIADBG historyIngress status=archived_orphan frames=%d metadata=%d entries=%d action=raw_only_no_ack_no_coverage",
                                  archivedFrames, ignoredMetadata, orphansToReplay.count)
                    // A first accepted HR callback can start a replay that
                    // retires only the vault entries observed at worker open.
                    // Do not strand a second sealed journal until another
                    // unrelated HR packet arrives: schedule the next bounded,
                    // identity-verified vault pass only after this canonical
                    // durability boundary succeeded. This remains raw-only;
                    // it has no ACK, cursor, or gap-coverage authority.
                    _ = self.archiveOrphanHistoricalIngressIfNeeded(
                        reason: "orphan_vault_follow_up_after_canonical_replay",
                        force: false,
                        explicitRequest: false,
                        retainHistoricalRequest: false
                    )
                    let exactMotionResumed = self
                        .resumeConnectedMotionBankAfterLocalDependencyIfNeeded(
                            .orphanArchive
                        )
                    if !exactMotionResumed,
                       let pending = self.takePendingOfflineHistoricalSyncRequest() {
                        _ = self.requestOfflineHistoricalSyncIfNeeded(
                            reason: pending.reason,
                            force: pending.force,
                            explicitResearchRequest: pending.explicitRequest,
                            explicitPostWorkoutBankRequest:
                                pending.explicitPostWorkoutBankRequest,
                            preserveConnectedRealtimeOwner:
                                pending.preserveConnectedRealtimeOwner
                        )
                    }
                }
            } catch {
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.orphanHistoricalIngressArchiveInFlight = false
                    self.releaseConnectedMotionBankLocalDependencyFirstRefusal(
                        reason: "orphan_archive_failed",
                        expectedDependency: .orphanArchive
                    )
                    AtriaDebugLog("ATRIADBG historyIngress status=deferred reason=orphan_archive_failed error=%@ action=retain_raw_no_ack_no_coverage",
                                  String(describing: error))
                }
            }
        }
        return true
    }

    private func noteOfflineHistoricalSyncProgress(
        generation: UInt64,
        reason: String,
        advancesDurableConnectedSliceHold: Bool = false
    ) {
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else { return }
        if reason == "historical_frame"
            || reason == "history_start"
            || reason == "history_end"
            || reason == "history_complete" {
            historicalPageContinuationTask?.cancel()
            historicalPageContinuationTask = nil
            historicalPageContinuationGeneration = nil
            historicalPageContinuationBoundaryID = nil
            historicalPageContinuationHasFutureAttempt = false
            // Strap history payload proves the drain actually started; only
            // then is the long post-start silent window justified.
            offlineHistoricalSyncHistoryStartObserved = true
        }
        let progressUptime = ProcessInfo.processInfo.systemUptime
        offlineHistoricalSyncLastProgressUptime = progressUptime
        if advancesDurableConnectedSliceHold {
            offlineHistoricalSyncLastDurableProgressUptime = progressUptime
        }
        if reason != "historical_frame" {
            AtriaDebugLog("ATRIADBG offline_sync watchdog=progress generation=%llu event=%@",
                          generation,
                          reason)
        }
    }

    /// A suspended or otherwise lost unstructured watchdog task must not leave
    /// history ownership stranded forever while standard heart-rate packets
    /// prove that the process is still receiving CoreBluetooth callbacks. Run
    /// the same fail-closed idle decision from those callbacks as an
    /// independent liveness path. This never ACKs, aborts, or advances the
    /// strap cursor; it only drops the link so the durable prefix can replay on
    /// a fresh history-owner generation.
    ///
    /// Do not exempt a stalled local ACK, persistence batch, or callback queue
    /// here. Those are precisely the states which can strand an owner after the
    /// task-based watchdog was suspended. Once the full idle interval elapsed,
    /// a transport reset is safer than holding the link indefinitely: no ACK is
    /// manufactured and the durable prefix remains replayable.
    private func enforceHistoricalIdleTimeoutFromGattHeartbeatIfNeeded(
        nowUptime: TimeInterval
    ) {
        guard offlineHistoricalSyncInProgress,
              let lastProgress = offlineHistoricalSyncLastProgressUptime,
              Self.historicalSyncHasStalled(
                lastProgressUptime: lastProgress,
                nowUptime: nowUptime,
                idleTimeout: offlineHistoricalSyncHistoryStartObserved
                    ? offlineHistoricalSyncIdleTimeout
                    : offlineHistoricalSyncPreStartIdleTimeout
              ),
              let stalledPeripheral = peripheral,
              stalledPeripheral.state == .connected else { return }

        let generation = offlineHistoricalSyncGeneration
        let idle = max(0, nowUptime - lastProgress)
        if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
            generation: generation,
            reason: "history_idle_timeout_gatt_heartbeat_preserve_realtime"
        ) {
            return
        }
        AtriaDebugLog("ATRIADBG offline_sync watchdog=gatt_heartbeat_idle_timeout generation=%llu idle_s=%.1f action=disconnect_without_ack_or_abort_retain_durable_prefix",
                      generation,
                      idle)
        cancelPeripheralConnection(
            stalledPeripheral,
            reason: "history_idle_timeout_gatt_heartbeat_transport_reset"
        )
    }

    private func armConnectedHistoricalSliceIfNeeded(
        generation: UInt64,
        reason: String,
        connectedChunkedBackfill: Bool
    ) {
        connectedHistoricalSliceTask?.cancel()
        connectedHistoricalSliceTask = nil
        guard connectedChunkedBackfill else { return }
        let startedAt = Date()
        connectedHistoricalSliceGeneration = generation
        connectedHistoricalSliceStartedAt = startedAt
        let defaults = UserDefaults.standard
        defaults.set(
            "monitoring_live_heart_rate",
            forKey: OfflineSyncDefaults.connectedSliceStatus
        )
        defaults.set(
            startedAt.timeIntervalSince1970,
            forKey: OfflineSyncDefaults.connectedSliceAt
        )
        connectedHistoricalSliceTask = Task { @MainActor [weak self] in
            guard let self else { return }
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(1))
                guard !Task.isCancelled,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation else {
                    return
                }
                if self.releaseConnectedHistoricalSliceIfNeeded(
                    generation: generation,
                    reason: reason,
                    now: Date()
                ) { return }
            }
        }
    }

    /// Evaluate on every served frame as well as the foreground timer. iOS may
    /// suspend a locked-phone process before a long Task sleep resumes, while
    /// the active CoreBluetooth callback is still a valid synchronous boundary
    /// at which to preserve the row and relinquish history ownership.
    @discardableResult
    private func releaseConnectedHistoricalSliceIfNeeded(
        generation: UInt64,
        reason: String,
        now: Date
    ) -> Bool {
        guard connectedHistoricalSliceGeneration == generation,
              let startedAt = connectedHistoricalSliceStartedAt,
              offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else {
            return false
        }
        let foreground = UIApplication.shared.applicationState == .active
        let minimumDuration = foreground
            ? connectedHistoricalSliceMinimumDuration
            : backgroundHistoricalSliceMinimumDuration
        let silenceLimit = foreground
            ? connectedHistoricalSliceLiveSilenceLimit
            : backgroundHistoricalSliceLiveSilenceLimit
        // Drain-keeping P4: hold a productive slice through live-HR silence when
        // nobody is watching live HR (the P2 maintenance window) and the drain is
        // still pulling durable rows. `recentDurableProgress` uses the narrower
        // flush/ACK clock; the GATT idle-timeout keeps its
        // broader protocol-liveness clock. A stalled row stream therefore stops
        // qualifying even if control retries continue and still releases below.
        let defaults = UserDefaults.standard
        let recentDisconnectStorm =
            defaults.integer(forKey: Self.protectedR10EarlyDisconnectsKey)
                >= Self.protectedR10EarlyDisconnectLimit
            || (defaults.object(forKey: Self.protectedR10DisconnectStormAtKey)
                as? Double).map {
                    now.timeIntervalSince1970 - $0 < 300
                } ?? false
        let nowUptime = ProcessInfo.processInfo.systemUptime
        let recentDurableProgress = Self.historicalSyncHasRecentDurableProgress(
            lastDurableProgressUptime:
                offlineHistoricalSyncLastDurableProgressUptime,
            nowUptime: nowUptime,
            silenceLimit: silenceLimit
        )
        // Signal-parity (2026-08-08): key the hold on the ROBUST backlog signal,
        // exactly like the admission and P3 callers of isFlushMaintenanceWindow —
        // NOT the raw rangeLossBackfillPending ticket. That ticket can be cleared
        // by the publication race while records still sit on the strap; keying the
        // hold on it dropped the hold during the flap, released the slice on 45s
        // live-HR silence, and left the 5-min connected-history cooldown to
        // dominate the duty cycle so the background frontier never advanced. The
        // hold stays fenced: background-only (isFlushMaintenanceWindow requires
        // !foregroundInteractive) and productive-only (recentDurableProgress) — a
        // stalled slice still releases below.
        let productiveBacklogHold = Self.shouldHoldProductiveBacklogSlice(
            backlogPending: strapBacklogPendingForCatchUp(now: now),
            // Fail toward live HR across lifecycle races: either the scene-owned
            // mode or UIApplication's immediate state can prove interactivity.
            foregroundInteractive: foreground || foregroundInteractiveMode,
            cleanOwnerState: protectedR10CleanOwnerState,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            recentDisconnectStorm: recentDisconnectStorm,
            recentDurableProgress: recentDurableProgress
        )
        if productiveBacklogHold {
            defaults.set(
                "held_productive_backlog_maintenance",
                forKey: OfflineSyncDefaults.connectedSliceStatus
            )
            AtriaDebugLog(
                "ATRIADBG offline_sync status=connected_slice_held_productive_backlog generation=%llu elapsed_s=%.0f progress_age_s=%.1f foreground=%d action=keep_draining_backlog_through_live_hr_silence",
                generation,
                now.timeIntervalSince(startedAt),
                offlineHistoricalSyncLastDurableProgressUptime.map {
                    max(0, nowUptime - $0)
                } ?? -1,
                foreground ? 1 : 0
            )
        }
        guard Self.shouldReleaseConnectedHistorySlice(
            sliceStartedAt: startedAt,
            lastAcceptedHeartRateAt: lastAcceptedHRAt,
            now: now,
            minimumSliceDuration: minimumDuration,
            liveSilenceLimit: silenceLimit,
            productiveBacklogHold: productiveBacklogHold
        ) else { return false }
        let liveSilence = now.timeIntervalSince(
            max(lastAcceptedHRAt ?? startedAt, startedAt)
        )
        defaults.set(
            "released_for_live_heart_rate",
            forKey: OfflineSyncDefaults.connectedSliceStatus
        )
        defaults.set(
            now.timeIntervalSince1970,
            forKey: OfflineSyncDefaults.connectedSliceAt
        )
        defaults.set(
            now.addingTimeInterval(
                automaticConnectedHistoryAttemptCooldown
            ).timeIntervalSince1970,
            forKey: OfflineSyncDefaults.connectedSliceCooldownUntil
        )
        retainPendingOfflineHistoricalSyncRequest(
            reason: "connected_slice_retry_\(reason)",
            force: false,
            explicitRequest: false
        )
        updateStrapStreamState(
            reason: "connected_history_slice_live_silence"
        )
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_slice_released generation=%llu elapsed_s=%.0f live_silence_s=%.0f foreground=%d reason=%@ action=disconnect_without_ack_or_abort_preserve_prefix_restore_live",
            generation,
            now.timeIntervalSince(startedAt),
            liveSilence,
            foreground ? 1 : 0,
            reason
        )
        connectedHistoricalSliceTask?.cancel()
        connectedHistoricalSliceTask = nil
        connectedHistoricalSliceGeneration = nil
        connectedHistoricalSliceStartedAt = nil
        if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
            generation: generation,
            reason: "history_connected_slice_live_silence_preserve_realtime"
        ) {
            return true
        }
        if let current = peripheral,
           current.state == .connected {
            cancelPeripheralConnection(
                current,
                reason: "history_connected_slice_live_silence",
                restoreRealtimeAfterHistoryGeneration: generation
            )
        } else {
            interruptOfflineHistoricalSyncForTransportLoss(
                reason: "history_connected_slice_live_silence"
            )
        }
        return true
    }

    /// A short whole-drain deadline truncated healthy physical WHOOP transfers.
    /// Watch the absence of progress instead: active data,
    /// persistence, fsync and ACK callbacks may keep a large asynchronous drain
    /// alive, while a silent transport still fails closed and retains its gap.
    private func armOfflineHistoricalSyncIdleWatchdog(
        generation: UInt64,
        reason: String
    ) {
        offlineHistoricalSyncTimeoutTask?.cancel()
        offlineHistoricalSyncTimeoutTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard let self else { return }
                try? await Task.sleep(
                    for: .seconds(self.offlineHistoricalSyncWatchdogPollInterval)
                )
                guard !Task.isCancelled,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation else {
                    return
                }
                let now = ProcessInfo.processInfo.systemUptime
                guard Self.historicalSyncHasStalled(
                    lastProgressUptime: self.offlineHistoricalSyncLastProgressUptime,
                    nowUptime: now,
                    idleTimeout: self.offlineHistoricalSyncHistoryStartObserved
                        ? self.offlineHistoricalSyncIdleTimeout
                        : self.offlineHistoricalSyncPreStartIdleTimeout
                ) else { continue }
                let idle = self.offlineHistoricalSyncLastProgressUptime.map {
                    max(0, now - $0)
                } ?? -1
                if self.finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                    generation: generation,
                    reason: "history_idle_timeout_preserve_realtime"
                ) {
                    return
                }
                // Silence is not a protocol terminal. The strap may still own
                // an unacknowledged HISTORY_END page (or be waiting inside a
                // page), so ending local history ownership and arming R10 on
                // this same connection would interleave transport epochs. Do
                // not manufacture an ACK or send ABORT here. A clean link loss
                // makes the durable prefix replayable; didDisconnect performs
                // the common fail-closed finalization and standing reconnect.
                if let stalledPeripheral = self.peripheral,
                   stalledPeripheral.state == .connected {
                    AtriaDebugLog("ATRIADBG offline_sync watchdog=idle_timeout generation=%llu idle_s=%.1f action=disconnect_without_ack_or_abort_retain_durable_prefix",
                                  generation,
                                  idle)
                    self.cancelPeripheralConnection(
                        stalledPeripheral,
                        reason: "history_idle_timeout_transport_reset"
                    )
                    return
                }
                AtriaDebugLog("ATRIADBG offline_sync watchdog=idle_timeout generation=%llu idle_s=%.1f action=finish_disconnected_without_ack_or_abort_retain_gap",
                              generation,
                              idle)
                self.finishOfflineHistoricalSync(
                    reason: "\(reason)_idle_timeout",
                    generation: generation
                )
                return
            }
        }
    }

    private func bindExactHistoricalRequestAuthorityIfAvailable(
        transportGeneration: UInt64,
        reason: String,
        exactRangeWasEncodedAndTransmitted: Bool,
        acceptedResponseDurablyTiedToAttempt: Bool
    ) {
        activeHistoricalRequestBinding = nil
        guard !reconcileConsumedHistoricalTerminalPublicationIfNeeded(
            reason: "pre_arm_\(reason)"
        ) else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=consumed_publication_reconciliation_in_flight action=no_rearm",
                          reason)
            return
        }
        guard Self.shouldBindExactHistoricalRequestAuthority(
            exactRangeWasEncodedAndTransmitted: exactRangeWasEncodedAndTransmitted,
            acceptedResponseDurablyTiedToAttempt: acceptedResponseDurablyTiedToAttempt
        ) else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=exact_range_transport_not_verified action=raw_archive_only_no_consumer_attestation",
                          reason)
            return
        }
        let defaults = UserDefaults.standard
        guard let exactRequest = AtriaBLEHistoryExactRequestPolicy.resolve(
            pending: defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
            explicitStart: defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart),
            explicitEnd: defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd),
            gapWindows: AtriaHistoricalGapLedger.windows(defaults: defaults),
            now: Date()
        ) else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=no_genuine_closed_exact_interval action=raw_archive_only_no_consumer_attestation",
                          reason)
            return
        }
        guard let peripheralIdentifier = peripheral?.identifier.uuidString
                ?? defaults.string(forKey: LinkDefaults.savedPeripheralUUID),
              !peripheralIdentifier.isEmpty else {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=peripheral_identity_missing action=raw_archive_only_no_consumer_attestation",
                          reason)
            return
        }
        let strapIdentity = strapModel.rawValue
        do {
            let authority = try historicalRequestAuthorityStore.arm(
                exactRequest: exactRequest,
                peripheralIdentifier: peripheralIdentifier,
                strapIdentity: strapIdentity,
                now: Date()
            )
            let binding = try historicalRequestAuthorityStore.bind(
                authorityGeneration: authority.generation,
                requestIdentifier: authority.requestIdentifier,
                transportGeneration: transportGeneration,
                peripheralIdentifier: peripheralIdentifier,
                strapIdentity: strapIdentity,
                now: Date()
            )
            activeHistoricalRequestBinding = binding
            AtriaDebugLog("ATRIADBG history_request_authority status=bound reason=%@ authority_generation=%llu attempt=%llu transport_generation=%llu request_identifier=%@ peripheral=%@ strap=%@ start_unix=%d end_unix=%d source=%@",
                          reason,
                          binding.authorityGeneration,
                          binding.attempt,
                          binding.transportGeneration,
                          binding.requestIdentifier,
                          peripheralIdentifier,
                          strapIdentity,
                          Int(binding.exactRequest.requestedStartUnix),
                          Int(binding.exactRequest.requestedEndUnix),
                          binding.exactRequest.sourceIdentifier)
        } catch {
            AtriaDebugLog("ATRIADBG history_request_authority status=deferred reason=%@ detail=%@ action=raw_archive_only_no_consumer_attestation",
                          reason,
                          String(describing: error))
        }
    }

    /// Closes the two-file commit after a crash between durable authority
    /// consumption and publication-journal completion. It verifies the exact
    /// consumed identity plus catalog/aggregate/completion/receipt set before
    /// completing the journal, and never creates a replacement authority.
    @discardableResult
    private func reconcileConsumedHistoricalTerminalPublicationIfNeeded(
        reason: String
    ) -> Bool {
        guard !historicalConsumerMaterializationInFlight,
              let job = try? historicalTerminalPublicationStore.load(),
              job.status == .projectionsPublished,
              (try? historicalRequestAuthorityStore.validateConsumedAuthority(
                  generation: job.authorityGeneration,
                  requestIdentifier: job.requestIdentifier,
                  peripheralIdentifier: job.peripheralIdentifier,
                  strapIdentity: job.strapIdentity,
                  exactRequest: job.exactRequest
              )) != nil else {
            return false
        }
        let timeZoneIdentifier = TimeZone.current.identifier
        let restingHeartRate = restingHR ?? 60
        let configuration = AtriaHistoricalConsumerProjectionConfiguration.production(
            restingHeartRate: restingHeartRate,
            maximumHeartRate: maxHRSetting,
            timeZoneIdentifier: timeZoneIdentifier
        )
        let publicationStore = historicalTerminalPublicationStore
        historicalConsumerMaterializationInFlight = true
        historicalArchiveQueue.async { [weak self] in
            var status = "deferred"
            var detail = "unknown"
            do {
                let result = try HistoricalArchive
                    .resumeTerminalConsumerProjectionsAfterCrash(
                        job: job,
                        configuration: configuration
                    )
                guard result.consumers.hasCompleteConsumerCoverage else {
                    throw AtriaBLEHistoryTerminalMaterializationError
                        .incompleteConsumerCoverage
                }
                try publicationStore.markAuthorityConsumedAfterReconciliation(job)
                status = "completed"
                detail = "consumed_authority_and_five_artifact_set_reverified"
            } catch {
                detail = String(describing: error)
            }
            AtriaDebugLog("ATRIADBG historical_consumers_reconcile status=%@ reason=%@ authority_generation=%llu detail=%@ raw_retained=1",
                          status,
                          reason,
                          job.authorityGeneration,
                          detail)
            Task { @MainActor [weak self] in
                self?.releaseHistoricalConsumerMaterializationOwner(
                    reason: "consumed_publication_reconciliation_finished"
                )
            }
        }
        return true
    }

    private func startHistoricalDrainTelemetry(generation: UInt64) {
        historicalDrainTelemetryTask?.cancel()
        historicalDrainTelemetry.reset(generation: generation)
        historicalDrainTelemetryTask = Task { @MainActor [weak self] in
            var tick = 0
            while !Task.isCancelled {
                do {
                    // 1s cadence: the strap kills an idle drain link at ~10s,
                    // and a 5s tick + 3s threshold lost the race by design
                    // (2026-07-24 20:15:12 continue sent as CBError 6 landed).
                    try await Task.sleep(for: .seconds(1))
                } catch {
                    return
                }
                guard !Task.isCancelled,
                      let self,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation else {
                    return
                }
                tick += 1
                if tick % 5 == 0 {
                    self.emitHistoricalDrainTelemetry(generation: generation,
                                                      trigger: "periodic")
                }
            }
        }
    }

    private func emitHistoricalDrainTelemetry(
        generation: UInt64,
        trigger: String,
        now: Date = Date()
    ) {
        guard historicalDrainTelemetry.generation == generation else { return }
        let pending = pendingHistoricalTransportEventCount
            + historyDrain.pendingPersistenceCount
            + (historicalAdmissionBatchInFlight ? 1 : 0)
        historicalDrainTelemetry.observePending(pending)
        let lastProgressAge = max(0, now.timeIntervalSince(
            historicalDrainTelemetry.lastProgressAt
        ))
        AtriaDebugLog("ATRIADBG historyDrainTelemetry trigger=%@ generation=%llu stream5_rx=%d admitted=%d decoded=%d decode_errors=%d persisted=%d persist_errors=%d pending=%d pending_high_water=%d flush_started=%d flush_ok=%d flush_errors=%d ack_sent=%d ack_ok=%d ack_errors=%d last_progress_age_s=%.1f phase=%@",
                      trigger,
                      generation,
                      historicalDrainTelemetry.stream5Received,
                      historicalDrainTelemetry.admitted,
                      historicalDrainTelemetry.decoded,
                      historicalDrainTelemetry.decodeErrors,
                      historicalDrainTelemetry.persisted,
                      historicalDrainTelemetry.persistErrors,
                      pending,
                      historicalDrainTelemetry.pendingHighWater,
                      historicalDrainTelemetry.flushStarted,
                      historicalDrainTelemetry.flushSucceeded,
                      historicalDrainTelemetry.flushErrors,
                      historicalDrainTelemetry.ackSent,
                      historicalDrainTelemetry.ackSucceeded,
                      historicalDrainTelemetry.ackErrors,
                      lastProgressAge,
                      historyDrain.phaseForDiagnostics)
    }

    // MARK: - Durable productive-slice receipt (handoff-9 CP2)

    /// Process-lifetime identity for slice-start receipts (handoff-10 CP2B):
    /// a `.started` receipt from a DIFFERENT instance proves a prior process
    /// died mid-slice and re-arms scheduling only.
    nonisolated static let processInstanceID = UUID().uuidString

    nonisolated static func loadDurableProductiveSliceReceipt(
        defaults: UserDefaults
    ) -> AtriaHistoricalDurableProductiveSliceReceipt? {
        guard let data = defaults.data(
            forKey: OfflineSyncDefaults.durableProductiveSliceReceipt
        ) else { return nil }
        return try? JSONDecoder().decode(
            AtriaHistoricalDurableProductiveSliceReceipt.self, from: data
        )
    }

    /// Replace-only-forward WITHIN one process instance: a stale callback from
    /// an older generation can never overwrite a newer finished slice's
    /// receipt. Slice generations are process-local and reset at relaunch
    /// (physically observed in handoff-10 acceptance: a prior run's
    /// generation-390 receipt silently swallowed every new process's gen-1..n
    /// writes, breaking both the earned cadence and the .started self-heal),
    /// so a receipt written by a DIFFERENT process instance is always
    /// replaceable — the current process's truth supersedes it.
    nonisolated static func storeDurableProductiveSliceReceipt(
        _ receipt: AtriaHistoricalDurableProductiveSliceReceipt,
        defaults: UserDefaults
    ) {
        if let existing = loadDurableProductiveSliceReceipt(defaults: defaults),
           existing.processInstanceID == receipt.processInstanceID,
           existing.generation > receipt.generation {
            return
        }
        guard let data = try? JSONEncoder().encode(receipt) else { return }
        defaults.set(data, forKey: OfflineSyncDefaults.durableProductiveSliceReceipt)
    }

    /// The pending-gap picture used for receipt fingerprinting — computed the
    /// same way at the durable boundary (write) and at both admission gates
    /// (read), so "the gap changed since the productive slice" is an exact
    /// value comparison, nil-safe for the cursor-anchored lane.
    private func currentHistoricalGapFingerprintForCadence(
        defaults: UserDefaults = .standard
    ) -> String? {
        let recoveryStartValue = defaults.object(
            forKey: OfflineSyncDefaults.recoveryWindowStart
        )
        let recoveryEndValue = defaults.object(
            forKey: OfflineSyncDefaults.recoveryWindowEnd
        )
        let recoveryStart = (recoveryStartValue as? Date)
            ?? (recoveryStartValue as? Double).map(Date.init(timeIntervalSince1970:))
        let recoveryEnd = (recoveryEndValue as? Date)
            ?? (recoveryEndValue as? Double).map(Date.init(timeIntervalSince1970:))
        return Self.historicalGapFingerprint(
            windows: AtriaHistoricalGapLedger.windows(defaults: defaults),
            recoveryStart: recoveryStart,
            recoveryEnd: recoveryEnd,
            requestedAt: defaults.object(
                forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt
            ) as? Double
        )
    }

    /// Handoff-9 CP2: ONE computed connected-handoff interval feeding both
    /// the eligibility gate and the transport throttle gate. Productive
    /// durable receipt → 60 s; anything else keeps the 5-minute brake.
    private func automaticConnectedHistoryRetryInterval() -> TimeInterval {
        Self.connectedHandoffRetryInterval(
            receipt: Self.loadDurableProductiveSliceReceipt(defaults: .standard),
            currentGapFingerprint: currentHistoricalGapFingerprintForCadence(),
            lastCompletedGeneration: lastCompletedHistoricalSyncGeneration,
            productiveInterval: catchUpProductiveRetryInterval,
            brakeInterval: automaticConnectedHistoryAttemptCooldown
        )
    }

    private func finishHistoricalDrainTelemetry(generation: UInt64, trigger: String) {
        emitHistoricalDrainTelemetry(generation: generation, trigger: trigger)
        if historicalDrainTelemetry.generation == generation {
            UserDefaults.standard.set(
                historicalDrainTelemetry.stream5Received > 0,
                forKey: OfflineSyncDefaults.lastDrainAttemptYieldedRows
            )
        }
        historicalDrainTelemetryTask?.cancel()
        historicalDrainTelemetryTask = nil
    }

    private func finishOfflineHistoricalSync(
        reason: String,
        generation: UInt64,
        resumePendingSync: Bool = true
    ) {
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else {
            AtriaDebugLog("ATRIADBG offline_sync status=ignored reason=%@ detail=stale_completion generation=%llu current=%llu",
                          reason,
                          generation,
                          offlineHistoricalSyncGeneration)
            return
        }
        let compactMotionBankOnly =
            activeConnectedMotionBankHistoryAuthority(
                generation: generation
            ) != nil
        let connectedRawCatchUpAuthority =
            activeConnectedRawHistoryCatchUpAuthority(
                generation: generation
            )
        let boundedConnectedRawCatchUp = connectedRawCatchUpAuthority != nil
        let connectedRawCleanACKFinishAuthority =
            connectedRawHistoryCleanACKFinishAuthority.flatMap {
                authority -> ConnectedRawHistoryCleanACKFinishAuthority? in
                guard boundedConnectedRawCatchUp,
                      authority.generation == generation,
                      let historicalIngressSpool,
                      historicalIngressSpool.matches(
                        authority.ingressBoundary
                      ) else {
                    return nil
                }
                return authority
            }
        let connectedMotionBankCleanACKFinishAuthority =
            connectedMotionBankHistoryCleanACKFinishAuthority.flatMap {
                authority -> ConnectedRawHistoryCleanACKFinishAuthority? in
                guard compactMotionBankOnly,
                      authority.generation == generation,
                      let historicalIngressSpool,
                      historicalIngressSpool.matches(
                        authority.ingressBoundary
                      ) else {
                    return nil
                }
                return authority
            }
        let connectedCleanACKFinishAuthority =
            connectedRawCleanACKFinishAuthority
                ?? connectedMotionBankCleanACKFinishAuthority
        let connectedRawCatchUpDurableBoundary =
            boundedConnectedRawCatchUp
                && !historicalAdmissionFailed
                && historicalArchiveWriteFailures == 0
                && historicalDrainTelemetry.persistErrors == 0
                && historicalDrainTelemetry.flushErrors == 0
                && (offlineHistoricalSyncReachedTerminal
                    || historicalDrainTelemetry.ackSucceeded > 0)
        let connectedRawIngressFullyAcknowledged =
            connectedRawCleanACKFinishAuthority?.ingressBoundary
                .coversEntireJournal == true
                && connectedRawCatchUpDurableBoundary
                && historicalDrainTelemetry.ackSucceeded > 0
                && pendingHistoricalTransportEventCount == 0
                && historyDrain.pendingPersistenceCount == 0
                && !historicalAdmissionBatchInFlight
                && !historicalAdmissionBatchScheduled
                && !historyDurableFlushInFlight
                && pendingHistoryEndACK == nil
                && !historyACKGate.requiresHistoryCallbackDeferral
        let connectedMotionBankCleanACKDurableBoundary =
            connectedMotionBankCleanACKFinishAuthority != nil
                && !historicalAdmissionFailed
                && historicalArchiveWriteFailures == 0
                && historicalDrainTelemetry.persistErrors == 0
                && historicalDrainTelemetry.flushErrors == 0
                && historicalDrainTelemetry.ackSucceeded > 0
        let connectedMotionBankIngressFullyAcknowledged =
            connectedMotionBankCleanACKFinishAuthority?.ingressBoundary
                .coversEntireJournal == true
                && connectedMotionBankCleanACKDurableBoundary
                && pendingHistoricalTransportEventCount == 0
                && historyDrain.pendingPersistenceCount == 0
                && !historicalAdmissionBatchInFlight
                && !historicalAdmissionBatchScheduled
                && !historyDurableFlushInFlight
                && pendingHistoryEndACK == nil
                && !historyACKGate.requiresHistoryCallbackDeferral
        let connectedCleanACKDurableBoundary =
            connectedRawCatchUpDurableBoundary
                || connectedMotionBankCleanACKDurableBoundary
        let connectedRawConsumedPrefixRetirementSafe =
            Self.shouldRetireConnectedRawConsumedPrefix(
                exactCleanACKFinishAuthority:
                    connectedCleanACKFinishAuthority != nil,
                durableBoundaryReached:
                    connectedCleanACKDurableBoundary,
                acknowledgedPages:
                    historicalDrainTelemetry.ackSucceeded,
                pendingPersistenceCount:
                    historyDrain.pendingPersistenceCount,
                admissionBatchInFlight:
                    historicalAdmissionBatchInFlight,
                admissionBatchScheduled:
                    historicalAdmissionBatchScheduled,
                hasDeferredEvent:
                    historicalIngressDeferredEvent != nil,
                durableFlushInFlight:
                    historyDurableFlushInFlight,
                hasPendingACK: pendingHistoryEndACK != nil,
                ackGateDeferringCallbacks:
                    historyACKGate.requiresHistoryCallbackDeferral
            )
        let shouldResumePendingSync = resumePendingSync
            && !boundedConnectedRawCatchUp
        let preservesConnectedRealtimeOwner =
            offlineHistoricalSyncPreservesConnectedRealtimeOwner
                || compactMotionBankOnly
                || boundedConnectedRawCatchUp
        activeConnectedMotionBankHistoryGenerationAuthority = nil
        activeConnectedRawHistoryCatchUpGenerationAuthority = nil
        connectedRawHistoryCleanACKFinishAuthority = nil
        connectedMotionBankHistoryCleanACKFinishAuthority = nil
        offlineHistoricalSyncPreservesConnectedRealtimeOwner = false
        offlineHistoricalSyncExplicitPostWorkoutBankRequest = false
        clearGate4DailyBankRearmIntent(
            reason: "history_finish_\(reason)"
        )
        let rawOnlyGapFingerprint = offlineHistoricalSyncRawOnlyGapFingerprint
        offlineHistoricalSyncRawOnlyGapFingerprint = nil
        let gapFingerprint = offlineHistoricalSyncGapFingerprint
        offlineHistoricalSyncGapFingerprint = nil
        let rows = historicalArchiveRows
        let newRows = max(0, rows - offlineHistoricalSyncStartRows)
        historyOnlyProbeEnabled = false
        if freshHistoryOwnerConnectionGeneration == generation {
            freshHistoryOwnerConnectionGeneration = nil
        }
        cancelHistoryOnlyProbe(reason: "offline_sync_finished")
        historicalMetricDurabilityFence.invalidate(generation: generation)
        pendingHistoricalRawFrontierGeneration = nil
        pendingHistoricalRawFrontierUnix = nil
        historyDurableFlushInFlight = false
        pendingHistoryEndACK = nil
        pendingHistoryACKAttempts = 0
        historyACKGate.reset()
        historicalPageContinuationTask?.cancel()
        historicalPageContinuationTask = nil
        historicalPageContinuationGeneration = nil
        historicalPageContinuationBoundaryID = nil
        historicalPageContinuationHasFutureAttempt = false
        historicalPageContinuationReplayBackoffStep = 0
        historyFirstFrameWatchdogTask?.cancel()
        historyFirstFrameWatchdogTask = nil
        historyFirstFrameReceivedGeneration = nil
        historicalReplayACKTask?.cancel()
        historicalReplayACKTask = nil
        historicalReplayACKBoundaryID = nil
        historyReadPreflightGate.reset()
        acceptedHistoryReadPreflightIdentity = nil
        productionHistoryReadPreflightRequired = false
        historyClockSyncEnabled = false
        productionFullDrainClockAuthorityEnabled = false
        historyClockRef = nil
        historyRealtimeStopRequestedGeneration = nil
        historyRealtimeStopCompletedGeneration = nil
        connectedHistoricalSliceTask?.cancel()
        connectedHistoricalSliceTask = nil
        connectedHistoricalSliceGeneration = nil
        connectedHistoricalSliceStartedAt = nil
        connectedMotionBankHistoryBudgetTask?.cancel()
        connectedMotionBankHistoryBudgetTask = nil
        endOfflineHistoricalSyncBackgroundLease(status: "terminal_\(reason)")
        historyInitSweepCommands.removeAll()
        historySkipDataRangeRequest = false
        probeCommandMode = .withoutResponse
        finishHistoricalDrainTelemetry(generation: generation, trigger: "finish")
        let ingressQueuesAreDrained = !historicalAdmissionFailed
            && pendingHistoricalTransportEventCount == 0
            && historyDrain.pendingPersistenceCount == 0
            && !historicalAdmissionBatchInFlight
            && !historicalAdmissionBatchScheduled
        let mayDiscardIngress = ingressQueuesAreDrained
            && ((!boundedConnectedRawCatchUp
                    && offlineHistoricalSyncReachedTerminal)
                || connectedRawIngressFullyAcknowledged
                || connectedMotionBankIngressFullyAcknowledged)
        if mayDiscardIngress {
            // A full terminal or an exact connected-raw ACK both prove that
            // the complete popped prefix crossed canonical durability. The
            // ACK-boundary slice stops before issuing the next 0x16, so an
            // empty queue also proves there is no unacknowledged suffix to
            // seal/replay. Failed or mid-page exits still retain the journal.
            historicalIngressSpool?.remove()
        } else if connectedRawConsumedPrefixRetirementSafe,
                  let connectedCleanACKFinishAuthority,
                  let historicalIngressSpool,
                  historicalIngressSpool.matches(
                    connectedCleanACKFinishAuthority.ingressBoundary
                  ) {
            // Only the exact dequeue offset captured inside this generation's
            // synchronous target-ACK branch is retirement authority. A queued
            // successor-page tail remains unread and is preserved, while the
            // already-fsynced/ACKed prefix is removed before the orphan worker
            // reopens the file from its header. Mid-page thermal/idle/failure
            // exits have no authority here and retain the complete journal.
            do {
                let retiredBytes = try historicalIngressSpool
                    .retireConsumedPrefix(
                        through: connectedCleanACKFinishAuthority
                            .ingressBoundary
                    )
                AtriaDebugLog(
                    "ATRIADBG historyIngress status=retired_durable_consumed_prefix generation=%llu retired_bytes=%llu unread_events=%d action=orphan_only_unacked_suffix",
                    generation,
                    retiredBytes,
                    historicalIngressSpool.pendingCount
                )
            } catch {
                // The original append-only spool remains the fail-closed
                // fallback. Duplicate replay costs I/O but cannot lose a row
                // or authorize an ACK.
                AtriaDebugLog(
                    "ATRIADBG historyIngress status=durable_prefix_retirement_failed generation=%llu error=%@ action=retain_full_spool_no_ack_no_loss",
                    generation,
                    String(describing: error)
                )
            }
        } else {
            // Preserve a failed/interrupted generation for crash diagnostics;
            // it cannot be reused as a new generation's ACK authority. Do not
            // fsync this non-authoritative cache on MainActor: canonical
            // archive/admission durability already gates every ACK, and an
            // uncommitted page remains replayable from the strap.
        }
        historicalIngressSpool = nil
        historicalIngressDeferredEvent = nil
        offlineHistoricalSyncInProgress = false
        // Keep the phase visible until the transaction is no longer active, so
        // an in-flight RX/stream4 callback is never dropped inside the drain.
        _ = historyTransportPhaseFence.deactivate(ifMatching: generation)
        HistoricalArchive.endDurableDrain(generation: generation)
        offlineHistoricalSyncTimeoutTask?.cancel()
        offlineHistoricalSyncTimeoutTask = nil
        offlineHistoricalSyncLastProgressUptime = nil
        offlineHistoricalSyncLastDurableProgressUptime = nil
        offlineHistoricalSyncStartRows = rows
        let verifiedEmptyCursor = verifiedEmptyHistoryCursorGeneration == generation
        let completedDrain = offlineHistoricalSyncReachedTerminal || verifiedEmptyCursor
        let requestedWindowMetricProgress = offlineHistoricalSyncMadeRequestedMetricProgress
        let ledgerCoverageResolved = offlineHistoricalSyncResolvedGapCoverage
        let restoredStandardHROnlyMode = Self.standardHROnlyModeAfterOfflineSync(
            modeBeforeSync: offlineHistoricalSyncPreviousStandardHROnlyMode
        )
        applyStandardHROnly(enabled: restoredStandardHROnlyMode,
                            persist: false,
                            reconnect: false,
                            reason: "offline_sync_complete_preserve_live_radio")
        if peripheral?.state == .connected {
            // History and standard HR share one physical connection, but a
            // terminal/timeout callback does not prove that 2A37's CCCD is
            // still active. Restore that subscription on every generation-
            // matching exit before touching the optional proprietary stream.
            // The helper preserves an already-healthy lease and only repairs a
            // missing/non-notifying characteristic, so completion cannot create
            // another live-data gap by toggling a working subscription.
            reassertHeartRateNotificationsIfConnected(
                reason: "offline_sync_terminal_\(reason)"
            )
            if !preservesConnectedRealtimeOwner {
                if txCharacteristic != nil {
                    armRealtime()
                } else {
                    peripheral?.discoverServices(discoveryServicesForCurrentMode)
                }
            }
        }

        guard let restorationPeripheral = peripheral,
              restorationPeripheral.state == .connected else {
            finalizeOfflineHistoricalSyncAfterLiveRestoration(
                reason: reason,
                generation: generation,
                rows: rows,
                newRows: newRows,
                rawOnlyGapFingerprint: rawOnlyGapFingerprint,
                gapFingerprint: gapFingerprint,
                requestedWindowMetricProgress: requestedWindowMetricProgress,
                ledgerCoverageResolved: ledgerCoverageResolved,
                terminalAndLiveRestored: false,
                liveRestored: false,
                resumePendingSync: shouldResumePendingSync,
                compactMotionBankOnly: compactMotionBankOnly,
                connectedRawCatchUpAuthority: connectedRawCatchUpAuthority,
                connectedRawCatchUpDurableBoundary:
                    connectedRawCatchUpDurableBoundary
            )
            return
        }

        let restorationPeripheralID = restorationPeripheral.identifier
        let restorationPeripheralObjectID = ObjectIdentifier(
            restorationPeripheral
        )
        let restorationEpoch = bleCallbackEpochFence.epoch
        let restorationRequestedAt = Date()
        let liveRestorationTimeout = boundedConnectedRawCatchUp
            ? connectedRawHistoryCatchUpBackgroundLiveSilenceLimit
            : postHistoryLiveRestorationTimeout
        postHistoryLiveRestorationGeneration = generation
        UserDefaults.standard.set("awaiting_post_history_live_sample",
                                  forKey: OfflineSyncDefaults.lastStatus)
        AtriaDebugLog("ATRIADBG offline_sync status=awaiting_live_restore reason=%@ generation=%llu epoch=%llu peripheral=%@ timeout_s=%.0f action=withhold_completion_and_gap_clear",
                      reason,
                      generation,
                      restorationEpoch,
                      restorationPeripheralID.uuidString,
                      liveRestorationTimeout)
        postHistoryLiveRestorationTask?.cancel()
        postHistoryLiveRestorationTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let deadline = restorationRequestedAt.addingTimeInterval(
                liveRestorationTimeout
            )
            var restored = false
            var repairReasserted = false
            var reconnectRequested = false
            while !Task.isCancelled, Date() < deadline {
                let samePeripheral = self.peripheral.map {
                    $0.identifier == restorationPeripheralID
                        && ObjectIdentifier($0)
                            == restorationPeripheralObjectID
                } ?? false
                let sameEpoch = self.bleCallbackEpochFence.epoch
                    == restorationEpoch
                let connected = self.peripheral?.state == .connected
                if samePeripheral,
                   sameEpoch,
                   connected,
                   let acceptedAt = self.lastAcceptedHRAt,
                   acceptedAt > restorationRequestedAt {
                    restored = true
                    break
                }
                if !samePeripheral || !sameEpoch {
                    // A same-link raw slice never turns a transient MainActor
                    // publication gap into a destructive recovery. Keep the
                    // fresh-2A37 proof bounded by this task's deadline; exact
                    // token reminting remains impossible until it succeeds.
                    if preservesConnectedRealtimeOwner {
                        try? await Task.sleep(for: .milliseconds(250))
                        continue
                    }
                    break
                }
                if !repairReasserted,
                   connected,
                   self.bleCallbackEpochFence.epoch == restorationEpoch,
                   Date().timeIntervalSince(restorationRequestedAt) >= 5 {
                    repairReasserted = true
                    self.reassertHeartRateNotificationsIfConnected(
                        reason: "offline_sync_live_restore_retry_\(reason)"
                    )
                }
                if !preservesConnectedRealtimeOwner,
                   !reconnectRequested,
                   connected,
                   Date().timeIntervalSince(restorationRequestedAt) >= 10,
                   let target = self.peripheral {
                    reconnectRequested = true
                    self.cancelPeripheralConnection(
                        target,
                        reason: "offline_sync_live_restore_rebuild_\(reason)",
                        restoreRealtimeAfterHistoryGeneration: generation
                    )
                    AtriaDebugLog(
                        "ATRIADBG offline_sync status=live_restore_rebuild generation=%llu reason=%@ action=cancel_once_then_reconnect_known",
                        generation,
                        reason
                    )
                }
                try? await Task.sleep(for: .milliseconds(250))
            }
            guard !Task.isCancelled,
                  self.postHistoryLiveRestorationGeneration == generation else { return }
            self.postHistoryLiveRestorationTask = nil
            self.postHistoryLiveRestorationGeneration = nil
            self.finalizeOfflineHistoricalSyncAfterLiveRestoration(
                reason: reason,
                generation: generation,
                rows: rows,
                newRows: newRows,
                rawOnlyGapFingerprint: rawOnlyGapFingerprint,
                gapFingerprint: gapFingerprint,
                requestedWindowMetricProgress: requestedWindowMetricProgress,
                ledgerCoverageResolved: ledgerCoverageResolved,
                terminalAndLiveRestored: completedDrain && restored,
                liveRestored: restored,
                resumePendingSync: shouldResumePendingSync,
                compactMotionBankOnly: compactMotionBankOnly,
                connectedRawCatchUpAuthority: connectedRawCatchUpAuthority,
                connectedRawCatchUpDurableBoundary:
                    connectedRawCatchUpDurableBoundary
            )
        }
    }

    private func finalizeOfflineHistoricalSyncAfterLiveRestoration(
        reason: String,
        generation: UInt64,
        rows: Int,
        newRows: Int,
        rawOnlyGapFingerprint: String?,
        gapFingerprint: String?,
        requestedWindowMetricProgress: Bool,
        ledgerCoverageResolved: Bool,
        terminalAndLiveRestored: Bool,
        liveRestored: Bool,
        resumePendingSync: Bool,
        compactMotionBankOnly: Bool,
        connectedRawCatchUpAuthority:
            ConnectedRawHistoryCatchUpGenerationAuthority?,
        connectedRawCatchUpDurableBoundary: Bool
    ) {
        let boundedConnectedRawCatchUp = connectedRawCatchUpAuthority != nil
        lastCompletedHistoricalSyncGeneration = generation
        lastCompletedHistoricalSyncReachedTerminal = terminalAndLiveRestored
            && offlineHistoricalSyncReachedTerminal
        let onboardingTransportAuthority = Self
            .onboardingHistoryTransportAuthorityIsValid(
                terminalReceived: offlineHistoricalSyncReachedTerminal,
                durableTerminalAuthority: durableTerminalAuthorityGeneration == generation,
                verifiedEmptyCursor: verifiedEmptyHistoryCursorGeneration == generation
            )
        lastCompletedHistoricalSyncHasOnboardingAuthority = terminalAndLiveRestored
            && onboardingTransportAuthority
        let rawOnlyGapArchived = rawOnlyGapFingerprint != nil
            && newRows > 0
            && terminalAndLiveRestored
        let connectedRawPageDurableAndLive = boundedConnectedRawCatchUp
            && connectedRawCatchUpDurableBoundary
            && liveRestored
        let completionStatus = connectedRawPageDurableAndLive
            ? "connected_raw_page_durable_live_restored"
            : !terminalAndLiveRestored && newRows > 0
            ? "partial_live_restore_unverified"
            : rawOnlyGapArchived
            ? "raw_gap_archived_awaiting_transaction_validation"
            : Self.historicalSyncCompletionStatus(
                newRows: terminalAndLiveRestored ? newRows : 0,
                requestedWindowMetricProgress: terminalAndLiveRestored
                    && requestedWindowMetricProgress,
                ledgerCoverageResolved: terminalAndLiveRestored
                    && ledgerCoverageResolved
            )
        let forwardCursorCaughtUp = reason.hasSuffix("_cursor_caught_up")
        let effectiveCompletionStatus = forwardCursorCaughtUp
            ? "strap_cursor_caught_up_older_gaps_retained"
            : completionStatus
        let defaults = UserDefaults.standard
        if let connectedRawCatchUpAuthority {
            let rawBoundaryNow = Date()
            scheduleConnectedRawHistoryCatchUpContinuation(
                authority: connectedRawCatchUpAuthority,
                reason: reason,
                newRows: newRows,
                cursorCaughtUp: forwardCursorCaughtUp,
                liveRestored: liveRestored,
                durableBoundary: connectedRawCatchUpDurableBoundary,
                now: rawBoundaryNow
            )
        }
        if let rawOnlyGapFingerprint, rawOnlyGapArchived {
            defaults.set(rawOnlyGapFingerprint,
                         forKey: OfflineSyncDefaults.rawArchivedGapFingerprint)
            defaults.set(Date().timeIntervalSince1970,
                         forKey: OfflineSyncDefaults.rawArchivedGapAt)
        }
        let noRowsForDurableGap = !compactMotionBankOnly
            && terminalAndLiveRestored
            && (offlineHistoricalSyncReachedTerminal
                || verifiedEmptyHistoryCursorGeneration == generation)
            && newRows == 0
            && gapFingerprint != nil
        if let gapFingerprint, noRowsForDurableGap {
            defaults.set(gapFingerprint, forKey: OfflineSyncDefaults.noRowsGapFingerprint)
            defaults.set(Date().timeIntervalSince1970, forKey: OfflineSyncDefaults.noRowsGapAt)
        }
        let publishedCompletionStatus = compactMotionBankOnly
            ? (terminalAndLiveRestored
                ? "motion_bank_compact_offload_terminal"
                : "motion_bank_compact_offload_partial")
            : (noRowsForDurableGap
                ? "no_rows_gap_retained"
                : effectiveCompletionStatus)
        defaults.set(publishedCompletionStatus, forKey: OfflineSyncDefaults.lastStatus)
        defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
        // Capture the exact durable gap-ledger state on both sides of the
        // completion decision.  Archive row counts alone cannot establish
        // whether this transaction covered the phone-away interval, so this
        // read-only evidence is the terminal counterpart to the request,
        // persistence, and ACK logs above.  `windowsForEvidence` deliberately
        // does not repair, migrate, or otherwise mutate the ledger.
        let gapCoverageBeforeCompletion = AtriaHistoricalGapLedger
            .windowsForEvidence(defaults: defaults)
        let rangeLossResolved = !compactMotionBankOnly
            && terminalAndLiveRestored
            && reconcileRangeLossBackfillPendingWithArchive(
                reason: reason,
                newRows: newRows,
                requestedWindowMetricProgress: requestedWindowMetricProgress,
                ledgerCoverageResolved: ledgerCoverageResolved
            )
        emitHistoricalGapCoverageEvidence(
            generation: generation,
            stage: "before_completion_reconcile",
            windows: gapCoverageBeforeCompletion
        )
        emitHistoricalGapCoverageEvidence(
            generation: generation,
            stage: "after_completion_reconcile",
            windows: AtriaHistoricalGapLedger.windowsForEvidence(defaults: defaults)
        )
        let episodeSavedRecords =
            Self.historicalRecoveryEpisodeSavedRecords(
                totalRows: rows,
                episodeStartRows:
                    offlineHistoricalRecoveryEpisodeStartRows
            )
        if !compactMotionBankOnly {
            if rangeLossResolved {
                historicalRecoveryPresentation = .verified
            } else if episodeSavedRecords > 0 {
                // Rows are factual progress, not proof that the exact interval was
                // recovered. Leave the gap visibly unresolved until authority clears.
                historicalRecoveryPresentation = .partial(
                    savedRecords: episodeSavedRecords
                )
            } else {
                historicalRecoveryPresentation = .needsAttention
            }
        }
        if rangeLossResolved {
            defaults.removeObject(forKey: OfflineSyncDefaults.sequenceGapFingerprint)
            defaults.removeObject(forKey: OfflineSyncDefaults.sequenceGapAttempts)
            defaults.removeObject(forKey: OfflineSyncDefaults.sequenceGapParkedAt)
            defaults.removeObject(forKey: OfflineSyncDefaults.sequenceGapParkedFrontierUnix)
            defaults.removeObject(forKey: OfflineSyncDefaults.sequenceGapLastReason)
            defaults.removeObject(forKey: OfflineSyncDefaults.noRowsGapFingerprint)
            defaults.removeObject(forKey: OfflineSyncDefaults.noRowsGapAt)
            defaults.removeObject(
                forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
            )
            defaults.removeObject(
                forKey: OfflineSyncDefaults.historyStartTimeoutGapAt
            )
            defaults.removeObject(
                forKey: OfflineSyncDefaults.historyStartTimeoutProfileVersion
            )
        }
        if !compactMotionBankOnly,
           !connectedRawHistoryCatchUpContinuationPending,
           terminalAndLiveRestored && offlineHistoricalSyncReachedTerminal {
            if activeFullDrainEventIdentity?.transportGeneration == generation
                || activeHistoricalRequestBinding?.transportGeneration == generation {
                historicalConsumerReceiptRequiredGenerations.insert(generation)
            }
            // With background ticket retries enabled, drains now routinely
            // reach terminal on a locked phone. The three lanes below run
            // whole-archive projections on `historicalArchiveQueue`; in plain
            // background that CPU profile is the documented
            // `cpu_resource_fatal` watchdog signature. Every input is already
            // fsynced, so defer only the local projection to the next active
            // foreground.
            if UIApplication.shared.applicationState == .active {
                scheduleFullDrainConsumerMaterialization(transportGeneration: generation)
                schedulePendingConsumerFollowupScanMaterialization(
                    transportGeneration: generation
                )
                scheduleTerminalConsumerMaterializationIfAuthorized(
                    transportGeneration: generation
                )
            } else {
                deferredTerminalMaterializationTransportGeneration = generation
                UserDefaults.standard.set(
                    "terminal_consumer_materialization_deferred_foreground",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=background_terminal_cpu_budget action=materialize_on_active_foreground",
                    generation
                )
            }
        }
        if !compactMotionBankOnly,
           !boundedConnectedRawCatchUp,
           Self.shouldRetryUnresolvedRangeLossAfterTerminal(
            rangeLossResolved: rangeLossResolved,
            forwardCursorCaughtUp: forwardCursorCaughtUp,
            noRowsForDurableGap: noRowsForDurableGap
        ) {
            // Saving an earlier FIFO prefix is factual progress, but it is not
            // recovery of the requested interval. Keep the existing bounded
            // live-preserving retry cadence until the cursor catches up, the
            // exact gap resolves, or the strap proves that no rows exist.
            scheduleRangeLossBackfillRetry(reason: reason)
        }
        if boundedConnectedRawCatchUp {
            evaluatePendingGlobalFrontierMotionBankCoverage(
                reason: "connected_raw_slice_\(reason)"
            )
        } else if compactMotionBankOnly
                    || !connectedRawHistoryCatchUpContinuationPending {
            evaluatePendingWorkoutHistoricalMotionBankOffload(
                reason: "history_terminal_\(reason)",
                allowRetry: terminalAndLiveRestored
            )
        }
        // A history transaction necessarily closes the low-bandwidth 0x69
        // bank before taking command ownership. The accepted-HR hot path
        // usually re-arms it, but terminal materialization and ticket retries
        // can consume that callback and leave the durable state stuck at
        // `prearmRequested=true, enabled=false` for the rest of the day.
        // This finalizer runs after the generation released transport. Any
        // generation-matching exit with restored live HR can reopen the next
        // all-day capture window; durable terminal coverage is not required to
        // resume present capture. If TX discovery is not resident yet, the
        // helper requests only the command characteristic and arms from its
        // callback.
        if liveRestored,
           !connectedRawHistoryCatchUpContinuationPending {
            armWorkoutHistoricalMotionBankIfPossible(
                reason: "history_terminal_live_restored_\(reason)"
            )
        } else {
            // The direct re-arm above is double-gated on a fresh same-epoch
            // 2A37 inside the restoration deadline; any transport-loss exit
            // gives liveRestored == false and previously re-armed NOTHING,
            // parking the bank for the rest of the day. The governor's own
            // guards (connection, battery, owner) decide safely here.
            Task { @MainActor [weak self] in
                self?.evaluateAllDayMotionGovernor(
                    reason: "history_terminal_\(reason)"
                )
            }
        }
        AtriaDebugLog("ATRIADBG offline_sync status=%@ reason=%@ generation=%llu rows=%d new_rows=%d live_restored=%d terminal_and_live_restored=%d action=%@",
                      publishedCompletionStatus,
                      reason,
                      generation,
                      rows,
                      newRows,
                      liveRestored ? 1 : 0,
                      terminalAndLiveRestored ? 1 : 0,
                      terminalAndLiveRestored
                        ? "publish_after_fresh_hr"
                        : "retain_gap_retry_realtime")
        if resumePendingSync,
           let pending = takePendingOfflineHistoricalSyncRequest() {
            requestOfflineHistoricalSyncIfNeeded(
                reason: pending.reason,
                force: pending.force,
                explicitResearchRequest: pending.explicitRequest,
                explicitPostWorkoutBankRequest:
                    pending.explicitPostWorkoutBankRequest,
                preserveConnectedRealtimeOwner:
                    pending.preserveConnectedRealtimeOwner
            )
        }
        if !connectedRawHistoryCatchUpContinuationPending {
            resumeWorkoutMotionLeaseAfterHistoricalSync(
                reason: "offline_sync_terminal_\(reason)"
            )
        }
        if !connectedRawHistoryCatchUpContinuationPending {
            onHistoricalTransportOwnershipReleased?(
                "offline_sync_terminal_\(reason)"
            )
        }
    }

    /// Converts one exact raw generation's durable result into scheduling only.
    /// The hint below cannot issue a command: the next generation still waits
    /// for a later accepted 2A37 callback to mint a new object/epoch token and
    /// repeat the atomic canonical claim.
    private func scheduleConnectedRawHistoryCatchUpContinuation(
        authority: ConnectedRawHistoryCatchUpGenerationAuthority,
        reason: String,
        newRows: Int,
        cursorCaughtUp: Bool,
        liveRestored: Bool,
        durableBoundary: Bool,
        now: Date
    ) {
        spendTerminalConsumerRawFirstSliceIfNeeded(
            generation: authority.generation
        )
        maintainPendingWorkoutMotionBankTickets(
            reason: "connected_raw_slice_boundary_\(reason)",
            now: now
        )
        let defaults = UserDefaults.standard
        if reason == "exact_connected_raw_live_hr_preempt" {
            let persistedRetry = defaults.double(
                forKey: OfflineSyncDefaults.connectedSliceCooldownUntil
            )
            let retryNotBefore = Date(
                timeIntervalSince1970: persistedRetry
            )
            connectedRawHistoryCatchUpContinuationPending = false
            connectedRawHistoryCatchUpEvaluationNotBefore =
                persistedRetry > now.timeIntervalSince1970
                ? retryNotBefore
                : nil
            connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
            connectedRawNoRadioCaptureDeferral = nil
            // Handoff-10 CP2B: a live-HR preempt is a deliberate release, not
            // a crash — retire this generation's `.started` receipt so it
            // cannot masquerade as an orphaned slice after relaunch. No
            // progress is claimed; the fast cadence is not earned.
            Self.storeDurableProductiveSliceReceipt(
                .init(
                    generation: authority.generation,
                    attemptStartedAtUnix: authority.startedAt.timeIntervalSince1970,
                    startFrontierUnix: authority.startFrontierUnix,
                    endFrontierUnix: defaults.double(
                        forKey: OfflineSyncDefaults.drainedThroughUnix
                    ),
                    durableRowsDelta: 0,
                    flushBoundaryIdentity: "connected_raw_slice_\(reason)",
                    liveRestoredAtUnix: nil,
                    gapFingerprint: currentHistoricalGapFingerprintForCadence(
                        defaults: defaults
                    ),
                    status: .noProgress,
                    recordedAtUnix: now.timeIntervalSince1970,
                    processInstanceID: Self.processInstanceID
                ),
                defaults: defaults
            )
            AtriaDebugLog(
                "ATRIADBG offline_sync status=connected_raw_catch_up_preemption_finalized generation=%llu retry_unix=%.3f cooldown_active=%d action=release_immediate_continuation_retain_backlog_without_extending_failure_cooldown",
                authority.generation,
                persistedRetry,
                persistedRetry > now.timeIntervalSince1970 ? 1 : 0
            )
            return
        }
        let progress = Self.connectedRawHistoryCatchUpSliceProgress(
            durableRows: newRows,
            startedAt: authority.startedAt,
            finishedAt: now,
            startFrontierUnix: authority.startFrontierUnix,
            endFrontierUnix: defaults.double(
                forKey: OfflineSyncDefaults.drainedThroughUnix
            )
        )
        // Handoff-9 CP2: mint the durable productive-slice receipt at this —
        // and only this — final durable boundary. `productive` requires the
        // full chain: durable flush boundary succeeded, live HR restored,
        // at least one durably persisted row, AND the frontier advanced past
        // the attempt's captured start. A received frame alone is never
        // progress. This receipt is what earns the next attempt the 60-second
        // connected retry; every other outcome keeps the 5-minute brake.
        let receiptStatus: AtriaHistoricalDurableProductiveSliceReceipt.Status
        if !durableBoundary || !liveRestored {
            receiptStatus = .failed
        } else if progress.durableRows > 0, progress.frontierAdvanceSeconds > 0 {
            receiptStatus = .productive
        } else {
            receiptStatus = .noProgress
        }
        Self.storeDurableProductiveSliceReceipt(
            .init(
                generation: authority.generation,
                attemptStartedAtUnix: authority.startedAt.timeIntervalSince1970,
                startFrontierUnix: authority.startFrontierUnix,
                endFrontierUnix: defaults.double(
                    forKey: OfflineSyncDefaults.drainedThroughUnix
                ),
                durableRowsDelta: progress.durableRows,
                flushBoundaryIdentity: "connected_raw_slice_\(reason)",
                liveRestoredAtUnix: liveRestored
                    ? now.timeIntervalSince1970 : nil,
                gapFingerprint: currentHistoricalGapFingerprintForCadence(
                    defaults: defaults
                ),
                status: receiptStatus,
                recordedAtUnix: now.timeIntervalSince1970,
                processInstanceID: Self.processInstanceID
            ),
            defaults: defaults
        )
        let backlogPending = strapBacklogPendingForCatchUp(now: now)
        let thermalState = ProcessInfo.processInfo.thermalState
        let publicationYieldRunnable =
            UIApplication.shared.applicationState == .active
            && (thermalState == .nominal || thermalState == .fair)
            && !ProcessInfo.processInfo.isLowPowerModeEnabled
        let thermalInterruption = reason.contains("power_pressure")
            || (thermalState == .critical
                && reason.contains("authority_lost"))
        let disposition = Self
            .connectedRawHistoryCatchUpContinuationDisposition(
                backlogPending: backlogPending,
                cursorCaughtUp: cursorCaughtUp,
                durableRows: progress.durableRows,
                frontierAdvanceSeconds: progress.frontierAdvanceSeconds,
                thermalState: thermalState,
                durableProgressAuthorized:
                    liveRestored && durableBoundary,
                thermalInterruption: thermalInterruption,
                consecutiveProductiveSlices:
                    connectedRawHistoryCatchUpConsecutiveProductiveSlices,
                publicationYieldNeeded:
                    connectedRawCatchUpPublicationYieldIsNeeded?() ?? false,
                publicationYieldRunnable: publicationYieldRunnable,
                productiveDelay:
                    connectedRawHistoryCatchUpProductiveRetryInterval,
                zeroProgressDelay:
                    connectedRawHistoryCatchUpZeroProgressRetryInterval,
                publicationYieldBudget:
                    connectedRawHistoryCatchUpPublicationYieldBudget
            )
        let action: String
        switch disposition {
        case .complete:
            connectedRawHistoryCatchUpContinuationPending = false
            connectedRawHistoryCatchUpEvaluationNotBefore =
                now.addingTimeInterval(
                    connectedRawHistoryCatchUpZeroProgressRetryInterval
                )
            connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
            if case .queuedPull(let intentID) = authority.request.intent,
               queuedConnectedRawHistoryCatchUpIntent?.id == intentID {
                queuedConnectedRawHistoryCatchUpIntent = nil
            }
            action = "complete"
            // A completed catch-up releases raw scheduling ownership: the
            // governor previously had no hook at this boundary, so the bank
            // stayed disarmed until a rare connect/lease event. Re-evaluate
            // through the normal policy (battery/owner guards unchanged).
            Task { @MainActor [weak self] in
                self?.evaluateAllDayMotionGovernor(
                    reason: "raw_catch_up_complete"
                )
            }
        case .awaitThermalRecovery:
            connectedRawHistoryCatchUpContinuationPending = true
            connectedRawHistoryCatchUpEvaluationNotBefore = nil
            connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
            action = "await_critical_thermal_recovery"
        case .yieldForPublication(let budget):
            beginConnectedRawHistoryCatchUpPublicationYield(
                sourceGeneration: authority.generation,
                reason: reason,
                budget: budget,
                now: now
            )
            action = String(
                format: "yield_for_publication_%.0fs",
                budget
            )
        case .resumeAfter(let delay):
            connectedRawHistoryCatchUpContinuationPending = true
            connectedRawHistoryCatchUpEvaluationNotBefore =
                now.addingTimeInterval(delay)
            let nextProductiveCount =
                connectedRawHistoryCatchUpConsecutiveProductiveSlices + 1
            if delay > connectedRawHistoryCatchUpProductiveRetryInterval {
                connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
            } else {
                connectedRawHistoryCatchUpConsecutiveProductiveSlices =
                    nextProductiveCount
            }
            action = String(format: "resume_after_%.0fs", delay)
        case .retryAfter(let delay):
            connectedRawHistoryCatchUpContinuationPending = true
            connectedRawHistoryCatchUpEvaluationNotBefore =
                now.addingTimeInterval(delay)
            connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
            action = String(format: "retry_after_%.0fs", delay)
        }
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_catch_up_slice generation=%llu reason=%@ durable_rows=%d duration_s=%.3f rows_per_s=%.3f frontier_advance_s=%.3f backlog=%d thermal=%ld action=%@ next_authority=fresh_2a37_exact_object_epoch",
            authority.generation,
            reason,
            progress.durableRows,
            progress.durationSeconds,
            progress.rowsPerSecond,
            progress.frontierAdvanceSeconds,
            backlogPending ? 1 : 0,
            thermalState.rawValue,
            action
        )
    }

    /// Installs only a process-local fairness lease after the exact raw
    /// generation has reached canonical durability, a clean ACK boundary, and
    /// fresh live-HR restoration. The continuation stays pending so generic
    /// history lanes remain suppressed, while the projection provider sees no
    /// raw scheduling ownership for this finite interval.
    private func beginConnectedRawHistoryCatchUpPublicationYield(
        sourceGeneration: UInt64,
        reason: String,
        budget: TimeInterval,
        now: Date
    ) {
        invalidateConnectedRawHistoryCatchUpPublicationYield(
            reason: "replaced"
        )
        let boundedBudget = max(1, min(
            connectedRawHistoryCatchUpPublicationYieldBudget,
            budget
        ))
        let yield = ConnectedRawHistoryCatchUpPublicationYield(
            token: UUID(),
            sourceGeneration: sourceGeneration,
            reason: reason,
            startedAt: now,
            deadline: now.addingTimeInterval(boundedBudget)
        )
        connectedRawHistoryCatchUpPublicationYield = yield
        connectedRawHistoryCatchUpContinuationPending = true
        connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
        connectedRawHistoryCatchUpEvaluationNotBefore = yield.deadline
        connectedRawHistoryCatchUpPublicationYieldTimeoutTask = Task {
            @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(boundedBudget))
            guard !Task.isCancelled, let self else { return }
            _ = self.finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                token: yield.token,
                publicationSucceeded: false,
                reason: "deadline",
                // A wall-clock adjustment must not turn the one-shot timeout
                // task into a no-op. The accepted-HR path still independently
                // observes the real deadline as a second safety fence.
                now: max(Date(), yield.deadline)
            )
        }
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_publication_yield_started token=%@ generation=%llu budget_s=%.0f reason=%@ action=release_projection_fence_keep_continuation_no_radio_command_no_cancel_no_rebuild",
            yield.token.uuidString,
            sourceGeneration,
            boundedBudget,
            reason
        )
        offerConnectedRawCatchUpPublicationYieldIfNeeded(
            reason: "raw_slice_boundary"
        )
    }

    /// AtriaApp calls this on a newly usable foreground/BGProcessing edge. One
    /// callback result always spends this fairness turn; the absolute deadline
    /// bounds only a callback which has not returned yet. No result from this
    /// callback can itself issue a history command.
    @discardableResult
    func offerConnectedRawCatchUpPublicationYieldIfNeeded(
        reason: String,
        now: Date = Date()
    ) -> Bool {
        guard let yield = connectedRawHistoryCatchUpPublicationYield else {
            return false
        }
        let publicationNeeded =
            connectedRawCatchUpPublicationYieldIsNeeded?() ?? false
        guard Self
            .connectedRawHistoryCatchUpPublicationYieldShouldRemainActive(
                publicationNeeded: publicationNeeded,
                publicationSucceeded: false,
                now: now,
                deadline: yield.deadline
            ) else {
            _ = finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                token: yield.token,
                publicationSucceeded: false,
                reason: publicationNeeded
                    ? "deadline_observed_\(reason)"
                    : "intent_cleared_\(reason)",
                now: now
            )
            return false
        }
        guard !historicalRadioTransportOwnsLink else {
            AtriaDebugLog(
                "ATRIADBG offline_sync status=connected_raw_publication_yield_offer_deferred token=%@ reason=%@ detail=radio_owner_still_active action=finish_empty_turn_no_overlap",
                yield.token.uuidString,
                reason
            )
            _ = finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                token: yield.token,
                publicationSucceeded: false,
                publicationAttemptCompleted: true,
                reason: "radio_owner_reacquired_\(reason)",
                now: now
            )
            return false
        }
        if connectedRawHistoryCatchUpPublicationYieldOfferTask != nil {
            return true
        }
        guard let offer = onConnectedRawCatchUpPublicationYield else {
            _ = finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                token: yield.token,
                publicationSucceeded: false,
                publicationAttemptCompleted: true,
                reason: "publication_provider_missing_\(reason)",
                now: now
            )
            return false
        }
        let remainingBudget = max(
            1,
            yield.deadline.timeIntervalSince(now)
        )
        connectedRawHistoryCatchUpPublicationYieldOfferTask = Task {
            @MainActor [weak self] in
            let succeeded = await offer(reason, remainingBudget)
            guard !Task.isCancelled, let self else { return }
            guard self.connectedRawHistoryCatchUpPublicationYield?.token
                    == yield.token else { return }
            self.connectedRawHistoryCatchUpPublicationYieldOfferTask = nil
            if succeeded {
                _ = self
                    .finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                        token: yield.token,
                        publicationSucceeded: true,
                        publicationAttemptCompleted: true,
                        reason: "published_\(reason)",
                        now: Date()
                    )
            } else {
                // The callback owns exactly one bounded publication attempt.
                // A false result means that attempt either made one resumable
                // chunk of progress or was not runnable; neither is authority
                // to idle the raw lane until the absolute deadline. Durable
                // intent retains the next offer, after another productive raw
                // slice and a fresh accepted-2A37 authority boundary.
                _ = self
                    .finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                        token: yield.token,
                        publicationSucceeded: false,
                        publicationAttemptCompleted: true,
                        reason: "offer_completed_without_publication_\(reason)",
                        now: Date()
                    )
            }
        }
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_publication_yield_offered token=%@ reason=%@ remaining_s=%.0f action=bounded_local_projection_no_radio_overlap",
            yield.token.uuidString,
            reason,
            remainingBudget
        )
        return true
    }

    /// Scene/BGTask lifecycle owner releases a lease it can no longer service.
    /// This invalidates the exact local token and its async result, preserves
    /// the raw scheduling hint, and performs no radio action. Consequently only
    /// a subsequent accepted 2A37 callback can resume raw catch-up.
    @discardableResult
    func releaseConnectedRawCatchUpPublicationYieldForLifecycle(
        reason: String
    ) -> Bool {
        guard connectedRawHistoryCatchUpPublicationYield != nil else {
            return false
        }
        invalidateConnectedRawHistoryCatchUpPublicationYield(
            reason: "lifecycle_\(reason)"
        )
        connectedRawHistoryCatchUpContinuationPending = true
        connectedRawHistoryCatchUpEvaluationNotBefore = nil
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_publication_yield_lifecycle_released reason=%@ action=await_fresh_2a37_exact_authority_no_radio_command",
            reason
        )
        return true
    }

    @discardableResult
    private func finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
        token: UUID,
        publicationSucceeded: Bool,
        publicationAttemptCompleted: Bool = false,
        reason: String,
        now: Date
    ) -> Bool {
        guard let yield = connectedRawHistoryCatchUpPublicationYield,
              yield.token == token else { return false }
        let publicationNeeded =
            connectedRawCatchUpPublicationYieldIsNeeded?() ?? false
        guard !Self
            .connectedRawHistoryCatchUpPublicationYieldShouldRemainActive(
                publicationNeeded: publicationNeeded,
                publicationSucceeded: publicationSucceeded,
                publicationAttemptCompleted: publicationAttemptCompleted,
                now: now,
                deadline: yield.deadline
            ) else { return false }
        connectedRawHistoryCatchUpPublicationYieldOfferTask?.cancel()
        connectedRawHistoryCatchUpPublicationYieldOfferTask = nil
        connectedRawHistoryCatchUpPublicationYieldTimeoutTask?.cancel()
        connectedRawHistoryCatchUpPublicationYieldTimeoutTask = nil
        connectedRawHistoryCatchUpPublicationYield = nil
        // Keep the scheduling hint. Clearing only its old deadline makes the
        // next accepted 2A37 callback the sole place that can mint a new exact
        // object/epoch authority.
        connectedRawHistoryCatchUpContinuationPending = true
        connectedRawHistoryCatchUpEvaluationNotBefore = nil
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_publication_yield_finished token=%@ generation=%llu succeeded=%d reason=%@ elapsed_s=%.1f action=await_fresh_2a37_exact_authority_no_radio_command",
            yield.token.uuidString,
            yield.sourceGeneration,
            publicationSucceeded ? 1 : 0,
            reason,
            max(0, now.timeIntervalSince(yield.startedAt))
        )
        return true
    }

    private func invalidateConnectedRawHistoryCatchUpPublicationYield(
        reason: String
    ) {
        guard let yield = connectedRawHistoryCatchUpPublicationYield else {
            connectedRawHistoryCatchUpPublicationYieldOfferTask?.cancel()
            connectedRawHistoryCatchUpPublicationYieldOfferTask = nil
            connectedRawHistoryCatchUpPublicationYieldTimeoutTask?.cancel()
            connectedRawHistoryCatchUpPublicationYieldTimeoutTask = nil
            return
        }
        connectedRawHistoryCatchUpPublicationYieldOfferTask?.cancel()
        connectedRawHistoryCatchUpPublicationYieldOfferTask = nil
        connectedRawHistoryCatchUpPublicationYieldTimeoutTask?.cancel()
        connectedRawHistoryCatchUpPublicationYieldTimeoutTask = nil
        connectedRawHistoryCatchUpPublicationYield = nil
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_publication_yield_invalidated token=%@ generation=%llu reason=%@ action=drop_process_local_token_no_radio_command",
            yield.token.uuidString,
            yield.sourceGeneration,
            reason
        )
    }

    /// Runs the terminal consumer materialization lanes that a
    /// background-terminal drain deferred. Each lane revalidates its own
    /// durable authority/journal and no-ops if a newer generation superseded
    /// the deferred one, so replaying all three here is safe.
    private func resumeDeferredTerminalConsumerMaterializationIfNeeded(
        reason: String
    ) {
        guard let generation =
                deferredTerminalMaterializationTransportGeneration else { return }
        deferredTerminalMaterializationTransportGeneration = nil
        AtriaDebugLog(
            "ATRIADBG historical_full_drain_publish status=resuming_deferred_terminal_materialization generation=%llu reason=%@",
            generation,
            reason
        )
        scheduleFullDrainConsumerMaterialization(transportGeneration: generation)
        schedulePendingConsumerFollowupScanMaterialization(
            transportGeneration: generation
        )
        scheduleTerminalConsumerMaterializationIfAuthorized(
            transportGeneration: generation
        )
    }

    /// User-initiated "Start fresh": accept that an unrecoverable, overwritten
    /// gap is gone and stop tracking it, so the missed-data banner clears instead
    /// of nagging about data the strap ring buffer can no longer serve. This is
    /// the same reconcile the verified strap-reset path runs (retire the draining
    /// authority, retire gap windows before `now`, clear the pending flag) MINUS
    /// any BLE command — the strap is already caught up at its frontier, so
    /// forgetting the older windows matches reality. Never sends a command, never
    /// touches metric archives, sessions, workouts, or sleep. Fail-safe: the
    /// authority abandon no-ops unless a `.draining` authority genuinely exists,
    /// and the window retirement persists a filtered list or does nothing.
    func startFreshAcceptingMissedDataLoss(reason: String) {
        let now = Date()
        let defaults = UserDefaults.standard
        let authorityAbandoned = (try? historicalFullDrainCoverageStore
            .abandonDrainingAuthorityAfterVerifiedStrapHistoryReset(
                completedAtUnix: now.timeIntervalSince1970
            )) ?? false
        let retirement = AtriaHistoricalGapLedger
            .retireWindowsBeforeVerifiedStrapHistoryReset(completedAt: now)
        // The user tapped Start fresh, so honor it: clear the pending state (and
        // the request window) that keeps the banner and the pending-recovery
        // treatment alive. With `completedAt = now` every window is older than the
        // reset point, so nothing recoverable is being discarded here.
        defaults.set(false, forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.removeObject(forKey: OfflineSyncDefaults.rangeLossBackfillReason)
        defaults.removeObject(forKey: OfflineSyncDefaults.recoveryWindowStart)
        defaults.removeObject(forKey: OfflineSyncDefaults.recoveryWindowEnd)
        assignIfChanged(\.rangeLossBackfillPending, false)
        historicalRecoveryPresentation = .idle
        reconcileHistoricalRecoveryPresentation(reason: "user_start_fresh")
        AtriaDebugLog(
            "ATRIADBG offline_sync status=user_start_fresh_accept_loss reason=%@ authority_abandoned=%d retired_windows=%d remaining_windows=%d ble_commands=0 metric_archive_mutation=0 session_mutation=0",
            reason,
            authorityAbandoned ? 1 : 0,
            retirement?.retiredWindows ?? -1,
            retirement?.remainingWindows ?? -1
        )
    }

    /// Emits only read-only per-gap coverage evidence at a history
    /// transaction boundary.  This makes a support trace auditable from
    /// request → persisted rows → durable flush/ACK → exact coverage outcome
    /// without turning diagnostics into another BLE or archive owner.
    private func emitHistoricalGapCoverageEvidence(
        generation: UInt64,
        stage: String,
        windows: [AtriaHistoricalGapLedger.Window]
    ) {
        guard !windows.isEmpty else {
            AtriaDebugLog("ATRIADBG historical_gap_coverage generation=%llu stage=%@ windows=0",
                          generation,
                          stage)
            return
        }
        for window in windows {
            let continuity = AtriaHistoricalGapLedger.continuity(for: window)
            AtriaDebugLog("ATRIADBG historical_gap_coverage generation=%llu stage=%@ gap=%@ start=%.3f end=%.3f reason=%@ observed_s=%d expected_s=%d density_percent=%d maximum_gap_s=%d p95_gap_s=%d continuous=%d",
                          generation,
                          stage,
                          window.id.uuidString,
                          window.start.timeIntervalSince1970,
                          window.end?.timeIntervalSince1970 ?? -1,
                          window.reason,
                          continuity.observedSeconds,
                          continuity.expectedSeconds,
                          continuity.densityPercent,
                          continuity.maximumGapSeconds,
                          continuity.p95GapSeconds,
                          continuity.continuous ? 1 : 0)
        }
    }

    private func interruptOfflineHistoricalSyncForTransportLoss(reason: String) {
        guard offlineHistoricalSyncInProgress else {
            cancelHistoryOnlyProbe(reason: reason)
            return
        }
        let interruptedGeneration = offlineHistoricalSyncGeneration
        if activeConnectedRealtimePreservingHistoryAuthorityExists(
            generation: interruptedGeneration
        ) {
            offlineHistoricalSyncReachedTerminal = false
            AtriaDebugLog(
                "ATRIADBG offline_sync status=exact_connected_history_interrupted reason=%@ generation=%llu action=finish_local_no_history_reissue_no_cancel_no_rebuild_retain_authority",
                reason,
                interruptedGeneration
            )
            finishOfflineHistoricalSync(
                reason: "\(offlineHistoricalSyncReason)_\(reason)",
                generation: interruptedGeneration,
                resumePendingSync: false
            )
            return
        }
        offlineHistoricalSyncReachedTerminal = false
        AtriaDebugLog("ATRIADBG offline_sync status=interrupted reason=%@ generation=%llu action=cancel_probe_retain_gap_retry_after_reconnect",
                      reason,
                      interruptedGeneration)
        finishOfflineHistoricalSync(
            reason: "\(offlineHistoricalSyncReason)_\(reason)",
            generation: interruptedGeneration,
            resumePendingSync: false
        )
    }

    @discardableResult
    private func reconcileRangeLossBackfillPendingWithArchive(reason: String,
                                                             newRows: Int = 0,
                                                             requestedWindowMetricProgress: Bool = false,
                                                             ledgerCoverageResolved: Bool = false) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return true }
        // A successful offload is not proof that it covered every live outage.
        // The durable gap ledger retires intervals only from metric-usable rows
        // spanning every expected bucket in their exact timestamp ranges.
        guard !AtriaHistoricalGapLedger.hasPendingWindows(defaults: defaults) else {
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_retained reason=%@ detail=missing_windows_not_covered windows=%d",
                          reason,
                          AtriaHistoricalGapLedger.windows(defaults: defaults).count)
            return false
        }
        let archiveDiagnostics = HistoricalArchive.diagnostics()
        let archiveAlreadyMetricReady = archiveDiagnostics.parseOK
            && archiveDiagnostics.metricUsableRows > 0
            && archiveDiagnostics.currentSessionUsableRows > 0
        // Global archive readiness says nothing about the newly missing range.
        // The gym failure had an old, healthy archive yet no rows covering the
        // workout; clearing on `archiveAlreadyMetricReady` silently discarded the
        // recovery request. Only rows appended by this sync can acknowledge it.
        let hasRequestedWindow = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart) != nil
            && defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd) != nil
        guard Self.rangeLossBackfillCanClear(newRows: newRows,
                                             hasRequestedWindow: hasRequestedWindow,
                                             requestedWindowMetricProgress: requestedWindowMetricProgress,
                                             ledgerCoverageResolved: ledgerCoverageResolved) else { return false }
        defaults.set(false, forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.removeObject(forKey: OfflineSyncDefaults.recoveryWindowStart)
        defaults.removeObject(forKey: OfflineSyncDefaults.recoveryWindowEnd)
        defaults.set(Date().timeIntervalSince1970, forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt)
        assignIfChanged(\.rangeLossBackfillPending, false)
        // Drain-keeping P3: the backlog is resolved, so retire the HR-independent
        // re-arm backstop (it also self-terminates on its next tick as a fallback).
        stopRangeLossBackfillMaintenanceTicker(reason: "range_loss_cleared")
        AtriaDebugLog("ATRIADBG offline_sync status=range_loss_backfill_cleared reason=%@ new_rows=%d metric_ready=%d metric_rows=%d current_rows=%d",
                      reason,
                      newRows,
                      archiveAlreadyMetricReady ? 1 : 0,
                      archiveDiagnostics.metricUsableRows,
                      archiveDiagnostics.currentSessionUsableRows)
        return true
    }

    /// The recovery pill must always be derivable from durable state. A
    /// latched `.needsAttention`/`.partial` that outlives its cause reads as
    /// "sync is permanently broken" and erodes trust in every real alert.
    /// This only ever downgrades to `.idle` when nothing actionable remains:
    /// no resolvable ledger window (the legacy ambiguous envelope is
    /// permanently non-actionable by design) and no pending backfill flag.
    /// Escalation continues to happen only at real events.
    private func reconcileHistoricalRecoveryPresentation(reason: String) {
        guard !offlineHistoricalSyncInProgress,
              !historicalConsumerMaterializationInFlight else { return }
        switch historicalRecoveryPresentation {
        case .needsAttention, .partial:
            break
        case .idle, .syncing, .verified:
            return
        }
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return }
        let actionable = AtriaHistoricalGapLedger
            .windows(defaults: defaults)
            .contains { !AtriaHistoricalGapLedger.isLegacyCoalescedWindow($0) }
        guard !actionable else { return }
        historicalRecoveryPresentation = .idle
        AtriaDebugLog("ATRIADBG offline_sync status=recovery_presentation_cleared reason=%@ action=no_actionable_windows_no_pending_backfill",
                      reason)
    }

    private func markRangeLossBackfillRequired(reason: String) {
        let defaults = UserDefaults.standard
        let alreadyPending = defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        if !alreadyPending || defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) == nil {
            defaults.set(Date().timeIntervalSince1970, forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt)
        }
        defaults.set(true, forKey: OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.set(reason, forKey: OfflineSyncDefaults.rangeLossBackfillReason)
        assignIfChanged(\.rangeLossBackfillPending, true)
        historicalRecoveryPresentation = .needsAttention
        // Drain-keeping P3: a backlog now exists — bring up the HR-independent
        // maintenance backstop (idempotent) even if the connected re-arm lane
        // suppresses and no other caller reaches its start.
        startRangeLossBackfillMaintenanceTickerIfNeeded(reason: reason)
        retainPendingOfflineHistoricalSyncRequest(
            reason: reason,
            force: false,
            explicitRequest: false
        )
        AtriaDebugLog("ATRIADBG offline_sync status=pending_range_loss_backfill reason=%@ action=sync_after_reconnect already_pending=%d",
              reason,
              alreadyPending ? 1 : 0)
    }

    private func preserveLongWearRangeLossRecovery(reason: String) {
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        persistActiveSessionJournalIfNeeded(reason: "\(reason)_continuity_checkpoint", force: true)
        guard longWearModeEnabled || activeExplicitWorkout else {
            // Balanced/on-demand mode still receives transient link drops. Keep
            // its live session durable and let the standard 90-second sample-gap
            // gate decide whether the reconnect belongs to a new segment.
            AtriaDebugLog("ATRIADBG active_session_journal status=checkpoint_requested reason=%@ mode=unexpected_disconnect_grace samples=%d",
                          reason,
                          session.count)
            return
        }
        // Off-wrist long-wear disconnects do not represent recoverable HR. A
        // user-started workout is still tracked from the disconnect instant if
        // its first accepted sample has not arrived yet.
        if activeExplicitWorkout || hasContact {
            let missingStart = lastAcceptedHRAt ?? Date()
            _ = AtriaHistoricalGapLedger.beginGap(at: missingStart,
                                                  reason: activeExplicitWorkout
                                                    ? "explicit_workout_disconnect"
                                                    : reason)
        }
        guard activeExplicitWorkout
                || hasContact
                || AtriaHistoricalGapLedger.hasPendingWindows() else {
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_skipped reason=%@ detail=off_wrist_no_recoverable_gap action=preserve_realtime_only",
                          reason)
            return
        }
        guard !offlineHistoricalSyncInProgress else {
            // A disconnect inside an opportunistic sync is still a missing range.
            // Mark it now; finishOfflineHistoricalSync will clear it only when
            // that same attempt actually appended rows.
            markRangeLossBackfillRequired(reason: activeExplicitWorkout
                                          ? "explicit_workout_range_loss"
                                          : "long_wear_range_loss")
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_marked reason=%@ detail=sync_in_progress explicit_workout=%d action=reconcile_on_sync_finish",
                          reason,
                          activeExplicitWorkout ? 1 : 0)
            return
        }
        let backfillReason = activeExplicitWorkout
            ? "explicit_workout_range_loss"
            : (strapStreamState == .lowBatteryShutoff
            ? "strap_low_battery_broadcast_off"
            : "long_wear_range_loss")
        markRangeLossBackfillRequired(reason: backfillReason)
        if status == .connected {
            scheduleRangeLossBackfillIfNeeded(reason: reason)
        }
    }

    private func historySequenceGapIsParked(_ defaults: UserDefaults) -> Bool {
        defaults.object(forKey: OfflineSyncDefaults.sequenceGapParkedAt) != nil
    }

    /// Counts one automatic drain attempt that died on a flash sequence
    /// discontinuity, keyed by the exact durable gap fingerprint the drain was
    /// serving. At the budget the ticket parks terminally: the gap ledger and
    /// `rangeLossBackfillPending` remain untouched (the missing interval stays
    /// visible data-quality truth), but the automatic re-arm lane goes quiet
    /// until the fingerprint changes or the drained frontier materially
    /// advances. Valid durable rows on either side of the gap are never
    /// rewritten by parking — this is scheduling state only.
    private func registerHistorySequenceGapDrainFailure(detail: String) {
        let defaults = UserDefaults.standard
        guard let fingerprint = offlineHistoricalSyncGapFingerprint else {
            AtriaDebugLog("ATRIADBG offline_sync status=sequence_gap_attempt_unkeyed detail=%@ action=skip_accounting",
                          detail)
            return
        }
        let accounting = Self.historySequenceGapAttemptAccounting(
            storedFingerprint: defaults.string(
                forKey: OfflineSyncDefaults.sequenceGapFingerprint
            ),
            storedAttempts: defaults.integer(
                forKey: OfflineSyncDefaults.sequenceGapAttempts
            ),
            currentFingerprint: fingerprint
        )
        defaults.set(fingerprint,
                     forKey: OfflineSyncDefaults.sequenceGapFingerprint)
        defaults.set(accounting.attempts,
                     forKey: OfflineSyncDefaults.sequenceGapAttempts)
        defaults.set(detail,
                     forKey: OfflineSyncDefaults.sequenceGapLastReason)
        AtriaDebugLog("ATRIADBG offline_sync status=sequence_gap_attempt_recorded attempts=%d budget=%d detail=%@",
                      accounting.attempts,
                      Self.historySequenceGapAttemptBudget,
                      detail)
        guard accounting.parked, !historySequenceGapIsParked(defaults) else {
            return
        }
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.sequenceGapParkedAt)
        defaults.set(defaults.double(
                        forKey: OfflineSyncDefaults.drainedThroughUnix
                     ),
                     forKey: OfflineSyncDefaults.sequenceGapParkedFrontierUnix)
        defaults.set("sequence_gap_parked_terminal",
                     forKey: OfflineSyncDefaults.lastStatus)
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = nil
        rangeLossBackfillMaintenanceTickerTask?.cancel()
        rangeLossBackfillMaintenanceTickerTask = nil
        AtriaDebugLog("ATRIADBG offline_sync status=sequence_gap_parked_terminal attempts=%d detail=%@ action=retain_gap_release_ownership_stop_rearm",
                      accounting.attempts,
                      detail)
    }

    /// True when the automatic lane must stay quiet for a parked sequence-gap
    /// ticket. When fresh evidence disarms suppression (changed fingerprint or
    /// materially newer drained frontier), this mints exactly ONE new attempt
    /// by unparking with the budget already spent down to its final slot.
    private func suppressAutomaticRetryForParkedSequenceGapIfNeeded(
        reason: String
    ) -> Bool {
        let defaults = UserDefaults.standard
        guard historySequenceGapIsParked(defaults) else { return false }
        let recoveryStartValue = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowStart)
        let recoveryEndValue = defaults.object(forKey: OfflineSyncDefaults.recoveryWindowEnd)
        let currentFingerprint = Self.historicalGapFingerprint(
            windows: AtriaHistoricalGapLedger.windows(defaults: defaults),
            recoveryStart: (recoveryStartValue as? Date)
                ?? (recoveryStartValue as? Double).map(Date.init(timeIntervalSince1970:)),
            recoveryEnd: (recoveryEndValue as? Date)
                ?? (recoveryEndValue as? Double).map(Date.init(timeIntervalSince1970:)),
            requestedAt: defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double
        )
        let suppressed = Self.shouldSuppressAutomaticSequenceGapRetry(
            exactGapPending: defaults.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
            ),
            explicitUserRequest: false,
            currentGapFingerprint: currentFingerprint,
            parkedGapFingerprint: defaults.string(
                forKey: OfflineSyncDefaults.sequenceGapFingerprint
            ),
            parkedFrontierUnix: defaults.object(
                forKey: OfflineSyncDefaults.sequenceGapParkedFrontierUnix
            ) as? Double,
            currentFrontierUnix: defaults.object(
                forKey: OfflineSyncDefaults.drainedThroughUnix
            ) as? Double
        )
        if suppressed {
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            defaults.set("sequence_gap_parked_retained",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=sequence_gap_parked_retained reason=%@ action=suppress_automatic_rearm_keep_gap_truth",
                          reason)
            return true
        }
        defaults.removeObject(forKey: OfflineSyncDefaults.sequenceGapParkedAt)
        defaults.removeObject(
            forKey: OfflineSyncDefaults.sequenceGapParkedFrontierUnix
        )
        defaults.set(
            max(0, Self.historySequenceGapAttemptBudget - 1),
            forKey: OfflineSyncDefaults.sequenceGapAttempts
        )
        AtriaDebugLog("ATRIADBG offline_sync status=sequence_gap_fresh_attempt_minted reason=%@ action=one_attempt_then_repark_unless_repaired",
                      reason)
        return false
    }

    private func scheduleRangeLossBackfillIfNeeded(reason: String) {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.enabled) else { return }
        guard !deferInterruptedFullDrainForCurrentLiveConnection else {
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            defaults.set("deferred_interrupted_full_drain_live_priority",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_interrupted_full_drain_live_priority reason=%@ action=hold_until_next_connection_or_explicit_diagnostic",
                          reason)
            return
        }
        scheduleStaleArmedRangeLossBackfillReconciliation(reason: reason)
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return }
        guard !offlineHistoricalSyncInProgress else { return }
        // A promoted workout-motion owner that has not yet consumed its
        // once-per-connection activation ticket needs the first quiet
        // seconds of a fresh link: this scheduler's 8-second task otherwise
        // starts a drain that the activation guard sees at ~12 seconds, so
        // the ticket burns without a command ever being sent (physically
        // reproduced 2026-08-13 03:47 IST — attempts 538→540, imuFrames=0,
        // drain owned the shared link; the 7b651294 re-adopt eviction frees
        // the CURRENT drain but cannot stop the NEXT tick from re-seizing).
        // Bounded by the owner state machine: the defer dissolves the moment
        // the activation command is consumed, the proof resolves, or the
        // owner falls back — and live HR never depends on this lane.
        if protectedR10CleanOwner == .protectedV9,
           protectedR10CleanOwnerState == .protectedLaunchPending,
           !defaults.bool(
            forKey: Self.protectedR10ResponseEventDataSequenceSentKey
           ) {
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            defaults.set("deferred_workout_motion_bring_up",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=deferred_workout_motion_bring_up reason=%@ action=hold_drain_until_activation_consumed_or_fallback",
                          reason)
            return
        }
        // Terminal sequence-gap ticket: the gap remains truthfully pending,
        // but the automatic lane must not re-arm for the unchanged evidence.
        guard !suppressAutomaticRetryForParkedSequenceGapIfNeeded(
            reason: reason
        ) else { return }
        // Drain-keeping P3: a genuine re-arm attempt is proceeding for a real
        // backlog. Refresh the clock the maintenance ticker watches so its
        // HR-independent backstop only fires once this normal loop has gone
        // silent past the floor (never while it is actively cycling). Start the
        // ticker HERE — before the connected-WHOOP4 `gap_retained_transaction_
        // unverified` early-return below — so it runs even when this lane
        // suppresses; the ticker drives the BGProcessing drain lane instead.
        lastRangeLossBackfillReArmAt = Date()
        startRangeLossBackfillMaintenanceTickerIfNeeded(reason: reason)
        let verifiedPeripheralID = defaults.string(forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID)
        let currentPeripheralID = peripheral?.identifier.uuidString
        let previouslyVerified = currentPeripheralID != nil
            && currentPeripheralID == verifiedPeripheralID
        let rawHistoryVerified = Self.supportsVerifiedHistoricalRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified
        )
        let transactionRecoveryVerified = Self.supportsVerifiedHistoricalTransactionRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified,
            fullDrainGapRecoveryEnabled:
                Self.productionHistoricalFullDrainGapRecoveryEnabled
        )
        if rawHistoryVerified,
           !transactionRecoveryVerified,
           peripheral?.state == .connected {
            rangeLossBackfillTask?.cancel()
            rangeLossBackfillTask = nil
            defaults.set("gap_retained_transaction_unverified",
                         forKey: OfflineSyncDefaults.lastStatus)
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog("ATRIADBG offline_sync status=gap_retained_transaction_unverified reason=%@ detail=decoder_ready_exact_range_or_clock_unverified action=suppress_automatic_connected_handoff_keep_gap_and_realtime",
                          reason)
            return
        }
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = Task { @MainActor in
            try? await Task.sleep(for: .seconds(8))
            guard !Task.isCancelled else { return }
            guard UserDefaults.standard.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) else { return }
            guard status != .poweredOff else { return }
            let backfillReason = UserDefaults.standard.string(forKey: OfflineSyncDefaults.rangeLossBackfillReason) ?? reason
            let now = Date()
            let protectedLiveStream = shouldProtectLiveStreamForOfflineSync()
            let automaticConnectedHandoff = automaticConnectedHistoricalHandoffIsEligible(
                now: now
            )
            let forceStaleBackfill = (!protectedLiveStream || automaticConnectedHandoff)
                && shouldForceStaleRangeLossBackfill(now: now)
            let forceReadyBackfill = (!protectedLiveStream || automaticConnectedHandoff)
                && shouldForceReadyRangeLossBackfill(now: now)
            let forceBackfill = automaticConnectedHandoff || forceStaleBackfill || forceReadyBackfill
            let action = automaticConnectedHandoff
                ? "automatic_connected_handoff"
                : forceBackfill
                ? (forceStaleBackfill ? "force_stale_backfill" : "force_ready_backfill")
                : (protectedLiveStream ? "defer_live_stream" : "sync_when_available")
            AtriaDebugLog("ATRIADBG offline_sync status=requesting_range_loss_backfill reason=%@ trigger=%@ action=%@ live_protected=%d stale_force=%d ready_force=%d",
                  backfillReason,
                  reason,
                  action,
                  protectedLiveStream ? 1 : 0,
                  forceStaleBackfill ? 1 : 0,
                  forceReadyBackfill ? 1 : 0)
            let syncStarted = requestOfflineHistoricalSyncIfNeeded(
                reason: backfillReason,
                force: forceBackfill,
                allowConnectedAutomaticHandoff: automaticConnectedHandoff
            )
            let stillPending = UserDefaults.standard.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending)
            AtriaDebugLog("ATRIADBG offline_sync status=range_loss_backfill_request_result reason=%@ started=%d pending=%d force=%d action=%@",
                          backfillReason,
                          syncStarted ? 1 : 0,
                          stillPending ? 1 : 0,
                          forceBackfill ? 1 : 0,
                          action)
            if !syncStarted, stillPending {
                scheduleRangeLossBackfillRetry(reason: reason)
            }
        }
    }

    func schedulePendingHistoricalRecovery(reason: String) {
        assignIfChanged(\.rangeLossBackfillPending,
                        UserDefaults.standard.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending))
        scheduleRangeLossBackfillIfNeeded(reason: reason)
    }

    private func scheduleRangeLossBackfillRetry(reason: String) {
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = Task { @MainActor in
            let delay = rangeLossBackfillRetryDelay()
            AtriaDebugLog("ATRIADBG offline_sync status=retry_scheduled reason=%@ delay_s=%.0f ready_force_after_s=%.0f",
                          reason,
                          delay,
                          rangeLossBackfillReadyForceInterval)
            try? await Task.sleep(for: .seconds(delay))
            guard !Task.isCancelled else { return }
            scheduleRangeLossBackfillIfNeeded(
                reason: Self.stableRangeLossBackfillRetryReason(reason)
            )
        }
    }

    /// Timers are not a reliable wake source after iOS backgrounds a locked
    /// phone. Each accepted 2A37 sample is an observed execution opportunity,
    /// so use it to admit the existing safe handoff as soon as the current
    /// connection has reached its stability window. This does not loosen any
    /// policy gate and sends no command itself; the normal request path still
    /// journals the boundary and performs the single audited cutover.
    private func attemptQualifiedRangeLossBackfillAfterAcceptedHRIfNeeded(
        now: Date
    ) {
        guard !foregroundInteractiveMode,
              !deferInterruptedFullDrainForCurrentLiveConnection,
              UserDefaults.standard.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
              ),
              !offlineHistoricalSyncInProgress,
              automaticConnectedHistoricalHandoffIsEligible(now: now) else {
            return
        }
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillTask = nil
        // A genuine re-arm: refresh the clock the P3 maintenance ticker watches so
        // an HR-healthy period keeps that HR-independent backstop quiet.
        lastRangeLossBackfillReArmAt = now
        let reason = UserDefaults.standard.string(
            forKey: OfflineSyncDefaults.rangeLossBackfillReason
        ) ?? "accepted_hr_qualified_range_loss"
        AtriaDebugLog("ATRIADBG offline_sync status=accepted_hr_qualified_handoff reason=%@ action=admit_current_epoch_without_timer_dependency",
                      reason)
        _ = requestOfflineHistoricalSyncIfNeeded(
            reason: reason,
            force: true,
            allowConnectedAutomaticHandoff: false
        )
    }

    /// Drain-keeping P3: start the bounded, HR-independent maintenance ticker that
    /// backstops the range-loss re-arm when accepted HR (and therefore the app's
    /// background wakes) goes sparse. Idempotent — a second call while running is a
    /// no-op — and it self-terminates when the backlog clears or offline sync is
    /// disabled. It sends no BLE command directly; each due tick re-enters the
    /// fully-guarded `requestOfflineHistoricalSyncIfNeeded` — the same connected-
    /// drain lane the BGProcessing task uses (P1b/P2 admission), which the
    /// `scheduleRangeLossBackfillIfNeeded` lane cannot reach on connected WHOOP 4.
    private func startRangeLossBackfillMaintenanceTickerIfNeeded(reason: String) {
        let defaults = UserDefaults.standard
        // A stale-but-nonzero debt observation still starts the backstop (the
        // tick refreshes the observation itself); only a FRESH caught-up
        // reading may keep it down. Mirrors the tick's own keep-alive rule.
        let lastObservedDebt = defaults.integer(
            forKey: OfflineSyncDefaults.flushDebtPendingRecords
        )
        guard defaults.bool(forKey: OfflineSyncDefaults.enabled),
              strapBacklogPendingForCatchUp()
                  || (currentFlushDebtLevel() != .caughtUp
                      && lastObservedDebt > Self.flushDebtCaughtUpRecords),
              rangeLossBackfillMaintenanceTickerTask == nil else { return }
        AtriaDebugLog("ATRIADBG offline_sync status=maintenance_ticker_started reason=%@ interval_s=%.0f floor_s=%.0f action=hr_independent_rearm_backstop",
                      reason,
                      rangeLossBackfillMaintenanceTickInterval,
                      rangeLossBackfillMaintenanceReArmFloor)
        rangeLossBackfillMaintenanceTickerTask = Task { @MainActor in
            while !Task.isCancelled {
                try? await Task.sleep(
                    for: .seconds(rangeLossBackfillMaintenanceTickInterval)
                )
                if Task.isCancelled { break }
                maintenanceTickRangeLossBackfillReArmIfDue()
                scheduleSyncNudgeFromCurrentState()
            }
        }
    }

    private func stopRangeLossBackfillMaintenanceTicker(reason: String) {
        guard rangeLossBackfillMaintenanceTickerTask != nil else { return }
        rangeLossBackfillMaintenanceTickerTask?.cancel()
        rangeLossBackfillMaintenanceTickerTask = nil
        AtriaDebugLog("ATRIADBG offline_sync status=maintenance_ticker_stopped reason=%@",
                      reason)
    }

    /// One maintenance tick: if the backlog is gone (or sync disabled) tear the
    /// ticker down; otherwise, when the normal re-arm loop has been silent past
    /// the floor on a settled, storm-free, flush-eligible link, re-arm the drain
    /// through the same guarded entry point the HR path uses — independent of HR.
    private func maintenanceTickRangeLossBackfillReArmIfDue() {
        let defaults = UserDefaults.standard
        // Keep the backstop alive while the LAST debt observation still shows
        // records above the caught-up floor even if the range-loss ticket
        // cleared and the observation has gone stale (2026-08-07: publication
        // cleared the ticket with ~5,400 records still on the strap and a
        // 30-min-stale observation — every lane idled and the tail never
        // drained). A FRESH caught-up observation stops the ticker as before.
        let lastObservedDebt = defaults.integer(
            forKey: OfflineSyncDefaults.flushDebtPendingRecords
        )
        let freshlyCaughtUp = currentFlushDebtLevel() == .caughtUp
        guard defaults.bool(forKey: OfflineSyncDefaults.enabled),
              !freshlyCaughtUp,
              defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending)
                  || lastObservedDebt > Self.flushDebtCaughtUpRecords else {
            stopRangeLossBackfillMaintenanceTicker(
                reason: "backlog_cleared_or_disabled"
            )
            return
        }
        let now = Date()
        let connected = peripheral?.state == .connected && status == .connected
        // Drain-keeping continuity (2026-08-07): the tick is also the
        // background self-heal for a dropped link and for a stale 0x22 debt
        // observation. The user found the app backgrounded, DISCONNECTED and
        // idle — foregrounding it was what reconnected. Nudge the existing
        // safe reconnect when the link is down (idempotent when a connect is
        // already pending), and refresh the strap status read when the debt
        // observation has gone stale on a healthy link, so the backlog signal
        // itself cannot starve the catch-up engine.
        if !foregroundInteractiveMode {
            if !connected {
                _ = reconnectToSavedPeripheralIfPossible(
                    reason: "maintenance_tick_link_down"
                )
            } else if currentFlushDebtLevel(now: now) == nil {
                requestStrapStatusRead(reason: "maintenance_tick_stale_debt")
            }
        }
        // Same recent-storm signal the connected-catch-up / maintenance-window
        // admission uses (see requestOfflineHistoricalSyncIfNeeded).
        let recentDisconnectStorm =
            defaults.integer(forKey: Self.protectedR10EarlyDisconnectsKey)
                >= Self.protectedR10EarlyDisconnectLimit
            || (defaults.object(forKey: Self.protectedR10DisconnectStormAtKey)
                as? Double).map {
                    now.timeIntervalSince1970 - $0 < 300
                } ?? false
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        let flushMaintenanceWindow = Self.isFlushMaintenanceWindow(
            rangeLossBackfillPending: true,
            foregroundInteractive: foregroundInteractiveMode,
            cleanOwnerState: protectedR10CleanOwnerState,
            activeExplicitWorkout: activeExplicitWorkout,
            recentDisconnectStorm: recentDisconnectStorm
        )
        let connectedCatchUp = Self.shouldAllowConnectedRangeLossCatchUp(
            rangeLossBackfillPending: true,
            cleanOwnerState: protectedR10CleanOwnerState,
            recentDisconnectStorm: recentDisconnectStorm,
            verifiedHistoryCapability: currentVerifiedRawHistoryCapability(),
            activeExplicitWorkout: activeExplicitWorkout,
            syncInProgress: offlineHistoricalSyncInProgress
        )
        let sinceLastReArm = lastRangeLossBackfillReArmAt.map {
            now.timeIntervalSince($0)
        }
        // Drain-keeping P6 escalation: a deep backlog re-arms on a shorter floor
        // so it closes faster; a shallow one keeps the gentle floor. Still floored
        // (never a tight loop) and still fully guarded downstream.
        let debtLevel = currentFlushDebtLevel(now: now)
        let effectiveFloor = debtLevel == .high
            ? min(rangeLossBackfillMaintenanceReArmFloor,
                  rangeLossBackfillMaintenanceTickInterval)
            : rangeLossBackfillMaintenanceReArmFloor
        guard Self.shouldReArmRangeLossBackfillOnMaintenanceTick(
            rangeLossBackfillPending: true,
            syncInProgress: offlineHistoricalSyncInProgress,
            linkConnected: connected,
            // Background only (this is a backgrounded catch-up backstop). Foreground
            // legitimately defers history to protect the live HR the user is
            // watching — driving a foreground drain here is the reverted dead-end.
            flushEligible: !foregroundInteractiveMode
                && (flushMaintenanceWindow || connectedCatchUp),
            sinceLastReArm: sinceLastReArm,
            reArmFloor: effectiveFloor
        ) else { return }
        defaults.set(now.timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.lastMaintenanceReArmAt)
        lastRangeLossBackfillReArmAt = now
        AtriaDebugLog("ATRIADBG offline_sync status=maintenance_ticker_rearm since_last_rearm_s=%@ maintenance=%d connected_catchup=%d debt=%@ floor_s=%.0f action=rearm_range_loss_backfill_independent_of_hr",
                      sinceLastReArm.map { String(format: "%.0f", $0) } ?? "never",
                      flushMaintenanceWindow ? 1 : 0,
                      connectedCatchUp ? 1 : 0,
                      debtLevel?.rawValue ?? "unknown",
                      effectiveFloor)
        // P3 fix: drive the SAME connected-drain lane the BGProcessing task uses
        // (requestOfflineHistoricalSyncIfNeeded → P1b/P2 admission), NOT the
        // scheduleRangeLossBackfillIfNeeded lane, which early-returns at the
        // `gap_retained_transaction_unverified` guard on the connected WHOOP 4 path
        // (raw verified, transaction-recovery unverified because full-drain is OFF)
        // and never reaches an arm. force:false / handoff:false mirrors what the
        // BGProcessing handler resolves to for WHOOP 4; the P1b/P2 gates inside
        // decide, and defer in foreground.
        _ = requestOfflineHistoricalSyncIfNeeded(
            reason: "maintenance_ticker",
            force: false,
            allowConnectedAutomaticHandoff: false
        )
    }

    /// The raw-history capability fence used by the connected-catch-up admission,
    /// computed the same way as inside `scheduleRangeLossBackfillIfNeeded`.
    private func currentVerifiedRawHistoryCapability() -> Bool {
        let defaults = UserDefaults.standard
        let verifiedPeripheralID = defaults.string(
            forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID
        )
        let currentPeripheralID = peripheral?.identifier.uuidString
        let previouslyVerified = currentPeripheralID != nil
            && currentPeripheralID == verifiedPeripheralID
        return Self.supportsVerifiedHistoricalRecovery(
            model: strapModel,
            previouslyVerified: previouslyVerified
        )
    }

    nonisolated static func phoneStateIsCharging(
        _ state: UIDevice.BatteryState
    ) -> Bool {
        state == .charging || state == .full
    }

    /// Drain-keeping P5: on the phone's charging edge, if a backlog is pending,
    /// re-arm the drain (and bring up the P3 backstop) through the same guarded
    /// entry point — a good moment to catch up while iOS is generous with
    /// background execution.
    private func handlePhoneChargeStateEdgeIfNeeded() {
        let nowCharging = Self.phoneStateIsCharging(UIDevice.current.batteryState)
        let previous = lastPhoneChargingState ?? false
        lastPhoneChargingState = nowCharging
        let pending = strapBacklogPendingForCatchUp()
        guard Self.shouldResumeDrainOnPhoneChargeEdge(
            previousCharging: previous,
            nowCharging: nowCharging,
            rangeLossBackfillPending: pending
        ) else { return }
        AtriaDebugLog("ATRIADBG offline_sync status=phone_charge_resume action=rearm_drain_backlog_on_external_power_edge")
        startRangeLossBackfillMaintenanceTickerIfNeeded(reason: "phone_charge_resume")
        scheduleRangeLossBackfillIfNeeded(reason: "phone_charge_resume")
    }

    /// Drain-keeping P6: persist the strap-side backlog as a first-class debt
    /// signal every time a 0x22 getDataRange response is observed. Purely
    /// diagnostic + escalation input — it advances no cursor and sends nothing.
    private func recordFlushDebt(pendingRecords: UInt32) {
        let records = Int(min(pendingRecords, UInt32(Int32.max)))
        let level = Self.flushDebtLevel(pendingRecords: records)
        let defaults = UserDefaults.standard
        defaults.set(records, forKey: OfflineSyncDefaults.flushDebtPendingRecords)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: OfflineSyncDefaults.flushDebtObservedAt)
        defaults.set(level.rawValue, forKey: OfflineSyncDefaults.flushDebtLevel)
        // P0: a freshly observed backlog arms the maintenance ticker so
        // catch-up no longer waits for the range-loss flag or a foreground.
        if level != .caughtUp {
            startRangeLossBackfillMaintenanceTickerIfNeeded(
                reason: "flush_debt_observed"
            )
        }
        scheduleSyncNudgeFromCurrentState()
    }

    /// Graceful lag measures (2026-08-05 user directive): when the backlog is
    /// deep and background catch-up is not progressing, tell the user — a
    /// foreground open (or bringing the strap close, or leaving Low Power
    /// Mode) is the fix only they can perform. All throttling/quiet-window
    /// logic lives in the scheduler's pure decision.
    private func scheduleSyncNudgeFromCurrentState(now: Date = Date()) {
        let defaults = UserDefaults.standard
        let debtObservedAt = defaults.object(
            forKey: OfflineSyncDefaults.flushDebtObservedAt
        ) as? Double
        let flushOKAt = defaults.object(
            forKey: OfflineSyncDefaults.lastDurableFlushBoundaryOKAt
        ) as? Double
        LocalNotificationScheduler.scheduleSyncNudgeIfNeeded(
            flushDebtPendingRecords: defaults.object(
                forKey: OfflineSyncDefaults.flushDebtPendingRecords
            ) as? Int,
            debtObservedAgeSeconds: debtObservedAt.map {
                now.timeIntervalSince1970 - $0
            },
            lastDurableFlushAgeSeconds: flushOKAt.map {
                now.timeIntervalSince1970 - $0
            },
            linkConnected: peripheral?.state == .connected,
            applicationIsActive:
                UIApplication.shared.applicationState == .active,
            now: now
        )
    }

    /// P0 drain decoupling (2026-08-05, user escalation "why the hell is
    /// coverage 18%"): the entire catch-up engine — connected catch-up (P1),
    /// maintenance flush window (P2), HR-independent re-arm ticker (P3),
    /// charge-resume (P5) — used to run ONLY while the exact range-loss
    /// ticket was pending. A plain strap backlog (fresh flush debt above the
    /// caught-up floor, observed via 0x22 within the staleness window) now
    /// drives the same engine through the same downstream guards. The
    /// range-loss flag keeps precedence for exact-gap accounting; this only
    /// broadens WHEN the guarded machinery is allowed to try.
    /// A drained-through frontier this far behind is itself backlog evidence.
    /// The 0x22 debt count only refreshes when a drain runs, and a drain only
    /// used to start when that count was fresh — a circular deadlock exposed
    /// 2026-08-07 (strap-off cleared the ticket; the count aged out; every
    /// lane idled 18+ min while 12 h behind). Admitting on the stale frontier
    /// is self-correcting: the drain's own 22/00 preflight refreshes the true
    /// count, which then either drives convergence or honestly reads caught-up.
    nonisolated static let frontierBacklogFloorSeconds: TimeInterval = 30 * 60

    /// UserDefaults-only backlog signal shared by the instance check AND static
    /// scheduling contexts (no `self`): ticket OR fresh non-caught-up flush debt
    /// OR a drain frontier >= 30 min stale. (2026-08-08 background-stall fix:
    /// wake-driven lanes must use THIS robust signal, not the raw
    /// `rangeLossBackfillPending` ticket — publication can falsely clear the
    /// ticket while records still sit on the strap, and every background wake
    /// then thinks there is nothing to drain.)
    /// Why a wake-driven lane should treat the strap as having HR-history
    /// backlog. `.frontierStale` is the SOFT reason (forward frontier >= 30 min
    /// behind, but no range-loss ticket and flush debt reads caught-up): the HR
    /// catch-up lane yields on this one when a motion offload is waiting, so the
    /// single shared transport isn't perpetually re-seized by HR while motion
    /// tickets starve (2026-08-08 motion-offload fix).
    enum StrapBacklogReason: Equatable {
        case none, ticket, freshDebt, frontierStale
        /// Handoff-10 CP2B: a prior process started a catch-up slice and died
        /// before its terminal receipt. Scheduling re-arms; the durable
        /// gap/debt/frontier truth is then re-evaluated normally.
        case unresolvedSliceStart
    }

    nonisolated static func strapBacklogReason(
        now: Date = Date(),
        defaults: UserDefaults = .standard,
        processInstanceID: String = AtriaBLEManager.processInstanceID
    ) -> StrapBacklogReason {
        if defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending) { return .ticket }
        if let observedAt = defaults.object(forKey: OfflineSyncDefaults.flushDebtObservedAt) as? Double,
           observedAt.isFinite,
           now.timeIntervalSince1970 - observedAt <= 15 * 60 {
            let records = defaults.integer(forKey: OfflineSyncDefaults.flushDebtPendingRecords)
            // A fresh, verified 0x22 range response is the strap's current
            // backlog authority.  When it says the cursor is caught up, do not
            // immediately fall through to an older durable phone frontier and
            // re-arm another raw drain.  The observation is deliberately
            // time-bounded: once it expires, the stale frontier may trigger one
            // new probe and refresh the truth.  A real range-loss ticket still
            // wins above this branch, and we never advance the durable frontier
            // from debt alone.
            return flushDebtLevel(pendingRecords: records) == .caughtUp
                ? .none
                : .freshDebt
        }
        // Handoff-10 CP2B: an orphaned slice-start receipt (a prior process
        // began a slice, never wrote a terminal) keeps scheduling armed even
        // when the frontier looks recent — exactly the state a mid-slice kill
        // leaves behind. It grants no ACK/durability/success authority; the
        // re-entered lane re-verifies everything on the normal brake.
        if let receipt = loadDurableProductiveSliceReceipt(defaults: defaults),
           receipt.isOrphanedStart(currentProcessInstanceID: processInstanceID) {
            return .unresolvedSliceStart
        }
        let frontier = defaults.double(forKey: OfflineSyncDefaults.drainedThroughUnix)
        if frontier > 0, now.timeIntervalSince1970 - frontier >= frontierBacklogFloorSeconds {
            return .frontierStale
        }
        return .none
    }

    nonisolated static func drainableStrapBacklogPendingFromDefaults(
        now: Date = Date(),
        defaults: UserDefaults = .standard
    ) -> Bool {
        strapBacklogReason(now: now, defaults: defaults) != .none
    }

    /// Robust "is there strap backlog to drain" accessor for wake-driven lanes
    /// (BGProcessing handler, accepted-HR catch-up).
    var hasDrainableStrapBacklog: Bool { Self.drainableStrapBacklogPendingFromDefaults() }

    /// True when the MOTION bank has a resumable (non-exhausted, not over-age)
    /// offload ticket. Motion/step coverage lags HR because the motion offload
    /// rides the same shared transport but had no dedicated background wake; this
    /// signal lets the BGProcessing lane drive a motion offload once HR is caught
    /// up (2026-08-08). Pure ledger/UserDefaults read.
    nonisolated static func resumableMotionBankOffloadPending(
        now: Date = Date(),
        defaults: UserDefaults = .standard
    ) -> Bool {
        guard let strap = defaults.string(forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID),
              let ticket = AtriaWhoop4MotionBankCoverageLedger.nextPendingOffload(
                strapIdentifier: strap, defaults: defaults)
        else { return false }
        return ticket.attempts < workoutHistoricalMotionBankMaximumOffloadAttempts
            && now.timeIntervalSince(ticket.end) < workoutHistoricalMotionBankMaximumBlockingAge
    }

    var hasResumableMotionBankOffload: Bool { Self.resumableMotionBankOffloadPending() }

    /// Typed strap-motion authority the step surfaces consume. Recomputed on
    /// demand (only when a step surface rebuilds, never per HR sample) from the
    /// durable owner/state/suppressed flags plus the freshest validated motion
    /// clock. It classifies a terminal pure-HR fallback as
    /// `unavailableInCurrentTransport`, but protected-R10 (protectedV9/qualified,
    /// or launch-pending/proving) or an active motion-bank offload as
    /// live/catchingUp/qualifying — never "unavailable" for the HR-minimal flag
    /// alone. On relaunch, with no process-local fresh-motion clock it falls
    /// through to stale/unknown rather than asserting a motion blocker.
    var strapMotionAvailability: AtriaStrapMotionAvailability {
        let now = Date()
        let freshMotionAge: TimeInterval?
        if let capturedAt = liveStrapMotionCapturedAt {
            freshMotionAge = now.timeIntervalSince(capturedAt)
        } else if let frameAt = lastR10MotionFrameAt {
            freshMotionAge = now.timeIntervalSince(frameAt)
        } else {
            freshMotionAge = nil
        }
        let priorValidMotion = UserDefaults.standard
            .double(forKey: RadioDefaults.passiveR10LastValidAt) > 0
        return AtriaStrapMotionAvailability.resolve(.init(
            cleanOwner: protectedR10CleanOwner,
            cleanOwnerState: protectedR10CleanOwnerState,
            streamSuppressed: protectedR10StreamSuppressed,
            freshMotionAge: freshMotionAge,
            hasActiveMotionBankOffload: hasResumableMotionBankOffload,
            hasPriorVerifiedMotion: priorValidMotion
        ))
    }

    private func strapBacklogPendingForCatchUp(now: Date = Date()) -> Bool {
        Self.drainableStrapBacklogPendingFromDefaults(now: now)
    }

    /// A failed next raw admission releases logical FIFO ownership, but the
    /// same exact callback epoch receives one present-capture turn before any
    /// direct motion-ticket selector can retake the radio. This is scheduling
    /// only: it neither clears the durable backlog nor authorizes a command.
    private func connectedRawNoRadioCaptureTurnIsCurrent() -> Bool {
        guard let deferral = connectedRawNoRadioCaptureDeferral,
              let current = peripheral,
              current.state == .connected,
              deferral.callbackSource.peripheralID == current.identifier,
              deferral.callbackSource.peripheralObjectID
                == ObjectIdentifier(current),
              bleCallbackEpochFence.owns(source: deferral.callbackSource)
        else { return false }
        return true
    }

    private func connectedRawNoRadioCaptureTurnRequiresPresentArm() -> Bool {
        connectedRawNoRadioCaptureTurnIsCurrent()
            && !Self.historicalMotionBankIsArmedForCurrentConnection(
            armed: workoutHistoricalMotionBankArmed,
            armedConnectionStartedAt:
                workoutHistoricalMotionBankArmedConnectionStartedAt,
            currentConnectionStartedAt: connectedAt
        )
    }

    /// Records explicit foreground interest without creating a generic history
    /// request or touching UserDefaults. The next accepted 2A37 boundary mints
    /// the exact object/epoch token; a UI reason string is never transport
    /// authority by itself.
    func queueConnectedRawHistoryCatchUpIntent(
        reason: String,
        now: Date = Date()
    ) {
        queuedConnectedRawHistoryCatchUpIntent = .init(
            id: UUID(),
            reason: reason,
            requestedAt: now
        )
        if let deferral = connectedRawNoRadioCaptureDeferral {
            connectedRawHistoryCatchUpEvaluationNotBefore =
                deferral.retryNotBefore
        } else {
            connectedRawHistoryCatchUpEvaluationNotBefore = nil
        }
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_catch_up_intent_queued reason=%@ action=await_fresh_2a37_exact_epoch_no_history_command_no_disconnect",
            reason
        )
    }

    /// Evaluates one exact raw-history slice from the accepted-HR hot path.
    /// Productive generations are paced by a process-local continuation
    /// deadline, not the global persisted attempt timestamp. Every new slice
    /// still requires a later accepted 2A37 callback to mint a fresh exact
    /// object/epoch token.
    @discardableResult
    private func attemptConnectedRawHistoryCatchUpAfterAcceptedHRIfNeeded(
        now: Date,
        trigger: String
    ) -> Bool {
        if let yield = connectedRawHistoryCatchUpPublicationYield {
            let publicationNow = Date()
            let publicationNeeded =
                connectedRawCatchUpPublicationYieldIsNeeded?() ?? false
            if Self
                .connectedRawHistoryCatchUpPublicationYieldShouldRemainActive(
                    publicationNeeded: publicationNeeded,
                    publicationSucceeded: false,
                    now: publicationNow,
                    deadline: yield.deadline
                ) {
                // Keep returning through the outer continuation-pending fence:
                // generic history and motion offload may not claim the shared
                // lane while bounded local projection owns this token.
                return false
            }
            _ = finishConnectedRawHistoryCatchUpPublicationYieldIfNeeded(
                token: yield.token,
                publicationSucceeded: false,
                reason: publicationNeeded
                    ? "deadline_observed_\(trigger)"
                    : "intent_cleared_\(trigger)",
                now: publicationNow
            )
            // Deliberately continue in this accepted-HR callback. It is the
            // first post-yield 2A37 fact and must still pass every exact
            // object/epoch/freshness guard below before a generation can start.
        }
        guard connectedRawHistoryCatchUpEvaluationNotBefore.map({ now >= $0 })
                ?? true else { return false }

        var queuedIntent = queuedConnectedRawHistoryCatchUpIntent
        if let existingQueuedIntent = queuedIntent,
           now.timeIntervalSince(existingQueuedIntent.requestedAt)
                > connectedRawHistoryCatchUpIntentLifetime {
            self.queuedConnectedRawHistoryCatchUpIntent = nil
            queuedIntent = nil
        }
        let persistedSliceCooldownUntil = UserDefaults.standard.double(
            forKey: OfflineSyncDefaults.connectedSliceCooldownUntil
        )
        if persistedSliceCooldownUntil > now.timeIntervalSince1970 {
            connectedRawHistoryCatchUpEvaluationNotBefore = Date(
                timeIntervalSince1970: persistedSliceCooldownUntil
            )
            return false
        }
        guard !offlineHistoricalSyncInProgress,
              postHistoryLiveRestorationGeneration == nil,
              let current = peripheral,
              self.peripheral === current,
              current.state == .connected else { return false }

        let explicitMotionOwnership = Self
            .explicitMotionOwnershipBlocksHistory(
                pendingWorkoutIntentActive:
                    AtriaPendingWorkoutIntent
                        .isActiveForBLEContinuity(now: now),
                inMemoryLeaseHeld: workoutMotionOwnerStartedAt != nil,
                calibrationHoldActive:
                    workoutMotionCalibrationHoldUntil.map { now < $0 } == true
            )
        guard !explicitMotionOwnership else { return false }

        if let deferral = connectedRawNoRadioCaptureDeferral {
            let exactSourceStillOwned =
                deferral.callbackSource.peripheralID == current.identifier
                    && deferral.callbackSource.peripheralObjectID
                        == ObjectIdentifier(current)
                    && bleCallbackEpochFence.owns(
                        source: deferral.callbackSource
                    )
            guard exactSourceStillOwned else {
                connectedRawNoRadioCaptureDeferral = nil
                connectedRawHistoryCatchUpEvaluationNotBefore = nil
                return false
            }
            guard now >= deferral.retryNotBefore else {
                connectedRawHistoryCatchUpEvaluationNotBefore =
                    deferral.retryNotBefore
                return false
            }
        }

        // If a productive slice parked for genuine heat, each accepted HR does
        // only this in-memory ProcessInfo check. Do not push the continuation
        // behind another fixed deadline; the first fair/nominal beat must be
        // able to resume immediately.
        let thermalPressureActive = Self
            .shouldParkConnectedRawHistoryCatchUpForPowerPressure(
                thermalState: ProcessInfo.processInfo.thermalState
            )
        if thermalPressureActive {
            // Critical heat performs only this cheap check on each accepted
            // beat. Keeping the deadline clear lets the first serious, fair,
            // or nominal beat enter its permitted duty immediately.
            connectedRawHistoryCatchUpEvaluationNotBefore = nil
            return false
        }

        let backlogReason = Self.strapBacklogReason(now: now)
        let strapBacklogPending = backlogReason != .none
        guard strapBacklogPending else {
            connectedRawHistoryCatchUpContinuationPending = false
            connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
            connectedRawNoRadioCaptureDeferral = nil
            return false
        }
        let applicationState = UIApplication.shared.applicationState
        let applicationIsBackground = applicationState == .background
        let foregroundAutomaticBacklog = applicationState == .active
        guard applicationIsBackground
                || foregroundAutomaticBacklog
                || queuedIntent != nil else { return false }

        let defaults = UserDefaults.standard
        let bankArmedAtValue = defaults.double(
            forKey: Self.workoutHistoricalMotionBankArmedAtKey
        )
        if let retryNotBefore = Self.connectedRawPresentBankRetryNotBefore(
            bankArmedForCurrentConnection:
                Self.historicalMotionBankIsArmedForCurrentConnection(
                    armed: workoutHistoricalMotionBankArmed,
                    armedConnectionStartedAt:
                        workoutHistoricalMotionBankArmedConnectionStartedAt,
                    currentConnectionStartedAt: connectedAt
                ),
            bankArmedAt: bankArmedAtValue > 0
                ? Date(timeIntervalSince1970: bankArmedAtValue)
                : nil,
            now: now,
            minimumPresentCaptureInterval:
                connectedRawHistoryCatchUpZeroProgressRetryInterval
        ) {
            connectedRawHistoryCatchUpEvaluationNotBefore = retryNotBefore
            return false
        }

        // Failed prerequisites retry at an idle cadence. A productive
        // finalizer overwrites this with its 2-8 second continuation deadline.
        connectedRawHistoryCatchUpEvaluationNotBefore = now.addingTimeInterval(
            connectedRawHistoryCatchUpIdleEvaluationInterval
        )

        let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: current.identifier,
            peripheralObjectID: ObjectIdentifier(current),
            peripheralConnected: true
        )
        guard Self.shouldMintConnectedRawHistoryCatchUpAuthority(
            applicationIsBackground: applicationIsBackground,
            queuedPullIntent: queuedIntent != nil,
            foregroundAutomaticBacklog: foregroundAutomaticBacklog,
            strapBacklogPending: strapBacklogPending,
            verifiedRawHistoryCapability:
                currentVerifiedRawHistoryCapability(),
            exactCallbackSourceAvailable: callbackSource != nil,
            syncInProgress: offlineHistoricalSyncInProgress,
            linkConnected: current.state == .connected,
            thermalPressureActive: thermalPressureActive,
            connectedAt: connectedAt,
            acceptedSampleCount: connectedEpochAcceptedHeartRateSamples,
            lastAcceptedHRAt: lastAcceptedHRAt,
            activeExplicitWorkout:
                explicitMotionOwnership,
            now: now,
            stableConnectionInterval: 60,
            acceptedFreshnessWindow: 45,
            minimumSamples: 10
        ), let callbackSource else { return false }

        let intent: ConnectedRawHistoryCatchUpIntent
        if let queuedIntent {
            intent = .queuedPull(queuedIntent.id)
        } else if applicationIsBackground {
            intent = .background
        } else {
            intent = .foregroundAutomatic
        }
        guard let authority = makeConnectedRawHistoryCatchUpRequestAuthority(
            peripheral: current,
            callbackSource: callbackSource,
            intent: intent,
            now: now
        ) else { return false }

        // Only a fully reminted exact raw authority may consume the completed
        // capture turn. Until this point the deferral remains visible to the
        // outer accepted-HR scheduler so generic forced/range-loss fallbacks
        // cannot seize the shared radio.
        connectedRawNoRadioCaptureDeferral = nil

        let previousAuthority =
            transientConnectedRawHistoryCatchUpRequestAuthority
        transientConnectedRawHistoryCatchUpRequestAuthority = authority
        defer {
            transientConnectedRawHistoryCatchUpRequestAuthority =
                previousAuthority
        }
        let priorContinuationPending =
            connectedRawHistoryCatchUpContinuationPending
        let started = requestOfflineHistoricalSyncIfNeeded(
            reason: "connected_raw_catch_up_\(trigger)",
            force: false,
            allowConnectedAutomaticHandoff: false
        )
        guard started else {
            if let retryNotBefore = Self.connectedRawNoRadioRetryNotBefore(
                priorContinuationPending: priorContinuationPending,
                admissionStarted: false,
                historyOwnerActive: offlineHistoricalSyncInProgress,
                failedAt: now,
                minimumPresentCaptureInterval:
                    connectedRawHistoryCatchUpZeroProgressRetryInterval
            ) {
                connectedRawNoRadioCaptureDeferral = .init(
                    callbackSource: authority.callbackSource,
                    failedAt: now,
                    retryNotBefore: retryNotBefore
                )
                connectedRawHistoryCatchUpContinuationPending = false
                connectedRawHistoryCatchUpConsecutiveProductiveSlices = 0
                connectedRawHistoryCatchUpEvaluationNotBefore = retryNotBefore
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=connected_raw_no_radio_capture_turn authority=%@ retry_unix=%.3f action=release_logical_fifo_owner_rearm_present_bank_defer_raw_120s_retain_backlog_no_command",
                    authority.authorityID.uuidString,
                    retryNotBefore.timeIntervalSince1970
                )
            }
            return false
        }
        connectedRawNoRadioCaptureDeferral = nil
        // A queued/fresh intent owns no FIFO lane. Publish logical continuation
        // only after atomic admission actually installed a generation; failed
        // authority/claim/local gates must leave present capture eligible.
        connectedRawHistoryCatchUpContinuationPending = true
        bindTerminalConsumerRawFirstSliceIfNeeded(
            generation: offlineHistoricalSyncGeneration
        )
        AtriaDebugLog(
            "ATRIADBG offline_sync status=connected_raw_catch_up_started authority=%@ trigger=%@ generation=%llu backlog=%@ action=sustained_same_link_keep_2a37_no_cancel_no_rebuild",
            authority.authorityID.uuidString,
            trigger,
            offlineHistoricalSyncGeneration,
            String(describing: backlogReason)
        )
        return true
    }

    /// Accepted-HR wake path for sustained exact raw catch-up. Background and a
    /// materially stale visible foreground both qualify, but only a fresh
    /// callback-source token can start a generation. While a typed continuation
    /// is active, suppress the legacy generic retry lanes; they carry no exact
    /// object/epoch authority and must not race the same-link owner.
    @discardableResult
    private func attemptAutonomousBackgroundCatchUpAfterAcceptedHRIfNeeded(
        now: Date = Date(),
        trigger: String = "accepted_hr_autonomous_catchup"
    ) -> Bool {
        if offlineHistoricalSyncInProgress {
            return activeConnectedRawHistoryCatchUpAuthority(
                generation: offlineHistoricalSyncGeneration
            ) != nil
        }
        if postHistoryLiveRestorationGeneration != nil,
           connectedRawHistoryCatchUpContinuationPending {
            return true
        }
        // No explicit HR->motion yield here (2026-08-08): this same accepted-HR
        // handler already attempted the motion offload FIRST
        // (resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded, "fresh_accepted_hr").
        // If motion could actually run it set offlineHistoricalSyncInProgress and
        // the guard above already returned — motion wins the shared transport. If
        // motion could NOT run (bank capturing, cadence not elapsed, not
        // connected), draining HR here keeps that transport productive instead of
        // idling it. An earlier optimistic ledger-only yield (hasResumableMotionBankOffload)
        // wrongly skipped HR even while motion was in fact blocked; removed.
        let started = attemptConnectedRawHistoryCatchUpAfterAcceptedHRIfNeeded(
            now: now,
            trigger: trigger
        )
        return started
            || connectedRawHistoryCatchUpContinuationPending
            || connectedRawNoRadioCaptureTurnIsCurrent()
    }

    /// The current flush-debt level, or nil when the last observation is missing
    /// or stale (older than `maxAge`) — escalation must not act on stale debt.
    private func currentFlushDebtLevel(
        now: Date = Date(),
        maxAge: TimeInterval = 15 * 60
    ) -> FlushDebtLevel? {
        let defaults = UserDefaults.standard
        guard let observedAt = defaults.object(
            forKey: OfflineSyncDefaults.flushDebtObservedAt
        ) as? Double,
              observedAt.isFinite,
              now.timeIntervalSince1970 - observedAt <= maxAge else { return nil }
        let records = defaults.integer(
            forKey: OfflineSyncDefaults.flushDebtPendingRecords
        )
        return Self.flushDebtLevel(pendingRecords: records)
    }

    private func scheduleStaleArmedRangeLossBackfillReconciliation(reason: String,
                                                                   now: Date = Date()) {
        let defaults = UserDefaults.standard
        let lastStatus = defaults.string(forKey: OfflineSyncDefaults.lastStatus) ?? ""
        let clearableStatuses = ["armed", "archived", "archive_metric_ready", "throttled", "no_rows"]
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              clearableStatuses.contains(lastStatus),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double,
              let startedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillStartedAt) as? Double,
              now.timeIntervalSince1970 - requestedAt >= rangeLossBackfillArmedTimeout else {
            return
        }
        guard !powerThermalGovernor.shouldDeferNonEssentialAnalysis else { return }
        let minimumInterval: TimeInterval = 2 * 60
        guard Self.shouldScheduleStaleRangeLossReconciliation(
            inFlight: staleRangeLossReconciliationInFlight,
            lastAttemptAt: lastStaleRangeLossReconciliationAttemptAt,
            now: now,
            minimumInterval: minimumInterval
        ) else { return }
        staleRangeLossReconciliationInFlight = true
        lastStaleRangeLossReconciliationAttemptAt = now
        // Do not clear from global archive readiness. That proves only that some
        // historical range decoded in the past, not that the requested outage is
        // present. Keep the durable request armed; didConnect / the retry state
        // machine will run another bounded sync and only `newRows > 0` may ack it.
        staleRangeLossReconciliationInFlight = false
        AtriaDebugLog("ATRIADBG offline_sync status=stale_armed_retained reason=%@ last_status=%@ requested_age_s=%.0f armed_age_s=%.0f action=retry_until_new_rows",
                      reason,
                      lastStatus,
                      now.timeIntervalSince1970 - requestedAt,
                      now.timeIntervalSince1970 - startedAt)
    }

    nonisolated static func shouldRestoreProtectedLongWearRadioInBackground(
        activeExplicitWorkout: Bool
    ) -> Bool {
        !activeExplicitWorkout
    }

    /// Preserve the radio mode that the launch safety policy persisted. A
    /// background edge must never silently undo protected standard-HR mode and
    /// re-enable a proprietary stream that failed the physical stability soak.
    /// `userSelectedBatterySaver` remains part of the signature for migration
    /// compatibility, but production safety is represented by the persisted
    /// mode itself.
    nonisolated static func shouldUseStandardHROnlyInProtectedBackground(
        userSelectedBatterySaver: Bool,
        persistedStandardHROnly: Bool,
        streamSuppressed: Bool = false
    ) -> Bool {
        _ = userSelectedBatterySaver
        return streamSuppressed || persistedStandardHROnly
    }

    /// Session durability, workout analysis and link recovery are independent
    /// of whether the proprietary full protocol or Battery Saver HR-only radio
    /// mode is active. The radio-mode parameter is intentionally retained so a
    /// regression test covers the full-protocol case that previously stalled.
    nonisolated static func shouldRunLongWearSupervisor(
        longWearEnabled: Bool,
        standardHROnlyMode: Bool
    ) -> Bool {
        _ = standardHROnlyMode
        return longWearEnabled
    }

    nonisolated static func isBLEContinuityRelevant(
        longWearEnabled: Bool,
        activeExplicitWorkout: Bool
    ) -> Bool {
        longWearEnabled || activeExplicitWorkout
    }

    /// A live workout that retained both its in-memory samples and connected
    /// strap link across an app switch needs only a cheap subscription
    /// health check. Journal restore, supervisor reconstruction, range-loss
    /// reconciliation, scanning, and service rediscovery are recovery work for
    /// missing state—not prerequisites for the first returning frame.
    nonisolated static func shouldUseFastWorkoutForegroundResume(
        activeExplicitWorkout: Bool,
        hasLiveSession: Bool,
        linkConnected: Bool
    ) -> Bool {
        activeExplicitWorkout && hasLiveSession && linkConnected
    }

    nonisolated static func shouldPreserveSessionOnUnexpectedDisconnect(
        longWearEnabled: Bool,
        activeExplicitWorkout: Bool,
        userRequestedDisconnect: Bool
    ) -> Bool {
        _ = longWearEnabled
        _ = activeExplicitWorkout
        return !userRequestedDisconnect
    }

    private func rangeLossBackfillRetryDelay(now: Date = Date()) -> TimeInterval {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double else {
            return rangeLossBackfillRetryInterval
        }
        let pendingAge = max(0, now.timeIntervalSince1970 - requestedAt)
        let lastSliceMadeDurableProgress = defaults.bool(
            forKey: OfflineSyncDefaults.lastDrainAttemptYieldedRows
        )
        return Self.rangeLossBackfillRetryDelay(
            pendingAge: pendingAge,
            readyForceInterval: rangeLossBackfillReadyForceInterval,
            retryInterval: rangeLossBackfillRetryInterval,
            lastSliceMadeDurableProgress: lastSliceMadeDurableProgress,
            progressChainInterval: rangeLossBackfillProgressChainInterval
        )
    }

    nonisolated static func rangeLossBackfillRetryDelay(
        pendingAge: TimeInterval,
        readyForceInterval: TimeInterval,
        retryInterval: TimeInterval,
        lastSliceMadeDurableProgress: Bool = false,
        progressChainInterval: TimeInterval = 8
    ) -> TimeInterval {
        guard pendingAge.isFinite,
              readyForceInterval.isFinite,
              retryInterval.isFinite,
              pendingAge >= 0,
              readyForceInterval > 0,
              retryInterval > 0 else {
            return max(0, retryInterval)
        }
        // Drain-keeping P1: actively catching up. The previous slice pulled
        // durable history rows but the gap is still open, so there is more
        // backlog waiting. Chain the next slice on the short interval instead of
        // idling the full retry cadence. The progress gate is essential — a
        // slice that yielded NOTHING falls through to the slow cadence below, so
        // this never becomes a tight 8-second reconnect loop against a strap
        // that is serving no rows.
        if lastSliceMadeDurableProgress,
           progressChainInterval.isFinite,
           progressChainInterval > 0 {
            return max(1, min(retryInterval, progressChainInterval))
        }
        guard pendingAge < readyForceInterval else {
            // An old unresolved gap is important, but age must not turn the
            // ten-minute retry cadence into a 30-second BLE ownership loop.
            // Accepted-HR admission still permits the first qualified attempt;
            // subsequent retries yield a full live/motion-bank interval.
            return retryInterval
        }
        return min(retryInterval, max(15, readyForceInterval - pendingAge))
    }

    private func shouldForceStaleRangeLossBackfill(now: Date = Date()) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double else {
            return false
        }
        return now.timeIntervalSince1970 - requestedAt >= rangeLossBackfillRetryInterval
    }

    private func shouldForceReadyRangeLossBackfill(now: Date = Date()) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: OfflineSyncDefaults.rangeLossBackfillPending),
              let requestedAt = defaults.object(forKey: OfflineSyncDefaults.rangeLossBackfillRequestedAt) as? Double else {
            return false
        }
        return now.timeIntervalSince1970 - requestedAt >= rangeLossBackfillReadyForceInterval
    }

    private func offlineHistoricalSyncMinimumInterval(for reason: String) -> TimeInterval {
        let defaults = UserDefaults.standard
        // The ticket-keyed fast interval used to be the ONLY escape from the
        // 6-hour ordinary cadence; a cleared ticket mid-backlog then throttled
        // every re-arm for hours (2026-08-08 01:20: `throttled`, last attempt
        // 5.75 h earlier, 9.6 h still on the strap). Judge the backlog itself.
        if strapBacklogPendingForCatchUp() {
            let pendingReason = defaults.string(
                forKey: OfflineSyncDefaults.rangeLossBackfillReason
            ) ?? ""
            let exactTicketLane = defaults.bool(
                forKey: OfflineSyncDefaults.rangeLossBackfillPending
            ) && (reason == pendingReason
                  || reason.contains("range_loss")
                  || reason.contains("long_wear_range_loss"))
            return Self.catchUpAttemptMinimumInterval(
                backlogPending: true,
                lastAttemptYieldedRows: exactTicketLane || defaults.bool(
                    forKey: OfflineSyncDefaults.lastDrainAttemptYieldedRows
                ),
                ordinaryInterval: offlineHistoricalSyncMinimumInterval,
                backlogInterval: rangeLossBackfillRetryInterval,
                productiveInterval: catchUpProductiveRetryInterval
            )
        }
        return offlineHistoricalSyncMinimumInterval
    }

    private func shouldProtectLiveStreamForOfflineSync(now: Date = Date()) -> Bool {
        Self.shouldProtectConnectedLinkForOfflineSync(
            connected: peripheral?.state == .connected,
            connectedAt: connectedAt,
            hasContact: hasContact,
            acceptedSampleCount: session.count,
            lastAcceptedHRAt: lastAcceptedHRAt,
            now: now,
            minimumSamples: autoSaveMinSamples,
            acceptedFreshnessWindow: offlineSyncLiveAcceptedHRProtectionWindow
        )
    }

    private func resumeForegroundScanIfNeeded(reason: String) {
        recomputeConnectionStatus(reason: "\(reason)_foreground_resume")
        guard peripheral == nil else { return }
        if hasSavedStrap, status == .connecting {
            _ = reconnectToSavedPeripheralIfPossible(reason: "\(reason)_resume_known_strap")
            return
        }
        guard status == .disconnected || status == .poweredOff else { return }
        startScan(reason: "\(reason)_resume")
    }

    private func applyStandardHROnly(enabled: Bool, persist: Bool, reconnect: Bool, reason: String) {
        let previous = standardHROnlyMode
        proprietaryNotifyFallbackTask?.cancel()
        proprietaryNotifyFallbackTask = nil
        activeProprietaryNotifyUUIDs.removeAll()
        strapStream5NotifyConfirmed = false
        standardHROnlyMode = enabled
        standardHROnlyEnabled = enabled
        if enabled {
            stopR10LivenessWatchdog(reason: "standard_hr_only_\(reason)")
        }
        if persist {
            UserDefaults.standard.set(enabled, forKey: RadioDefaults.standardHROnly)
        }
        if enabled {
            realtimeStartRetries = 0
            forceFreshScanOnRestore = true
        }
        AtriaDebugLog("ATRIADBG radio_mode mode=%@ persist=%d reconnect=%d reason=%@",
              enabled ? "protected_r10_minimal" : "full_protocol",
              persist ? 1 : 0,
              reconnect ? 1 : 0,
              reason)
        recordRadioMode(enabled ? "protected_r10_minimal" : "full_protocol", reason: reason)
        guard reconnect, previous != enabled, let peripheral else { return }
        txCharacteristic = nil
        heartRateCharacteristic = nil
        dbgTxReady = false
        realtimeArmed = false
        dbgLast = enabled ? "stable HR + R10 pending reconnect" : "full protocol pending reconnect"
        cancelPeripheralConnection(peripheral, reason: "radio_mode_\(reason)")
    }

    private static func currentSampleStatusAndReason() -> (status: String, reason: String) {
        let defaults = UserDefaults.standard
        return (evidenceToken(defaults.string(forKey: SampleDefaults.lastStatus) ?? "none"),
                evidenceToken(defaults.string(forKey: SampleDefaults.lastReason) ?? "none"))
    }

    private static func sampleFields(for saved: SavedSession) -> String {
        let sample = currentSampleStatusAndReason()
        return String(format: "hr_raw_2a37=%d hr_accepted=%d hr_zero=%d hr_artifact_held=%d hr_artifact_dropped=%d hr_raw_gaps=%d hr_accepted_gaps=%d hr_max_raw_gap_s=%.1f hr_max_accepted_gap_s=%.1f hr_sample_last_status=%@ hr_sample_last_reason=%@",
                      saved.hrRaw2A37Value,
                      saved.hrAcceptedValue,
                      saved.hrZeroValue,
                      saved.hrArtifactHeldValue,
                      saved.hrArtifactDroppedValue,
                      saved.hrRawGapsValue,
                      saved.hrAcceptedGapsValue,
                      saved.hrMaxRawGapValue,
                      saved.hrMaxAcceptedGapValue,
                      sample.status,
                      sample.reason)
    }

    private func workoutCaptureEvidence(for saved: SavedSession,
                                        readiness: WorkoutReadiness) -> WorkoutCaptureEvidence {
        let sample = Self.currentSampleStatusAndReason()
        let sampleFields = Self.sampleFields(for: saved)
        guard !readiness.ready else {
            return WorkoutCaptureEvidence(diagnosis: "candidate_valid",
                                          action: "save_or_validate_workout",
                                          sampleFields: sampleFields)
        }
        if saved.hrZeroValue > 0 || sample.status == "zero_contact" || sample.reason == "hr_zero" || sample.reason == "zero_contact" {
            return WorkoutCaptureEvidence(diagnosis: "contact_loss",
                                          action: "keep_learning_check_fit_contact",
                                          sampleFields: sampleFields)
        }
        let droppedFraction = readiness.duration > 0 ? readiness.droppedGapSeconds / readiness.duration : 0
        if readiness.streamCoveragePercent < 75
            || readiness.maxSampleGap > SavedSession.workoutContinuityGapLimit
            || droppedFraction >= 0.25 {
            return WorkoutCaptureEvidence(diagnosis: "stream_gaps",
                                          action: "keep_learning_reconnect_or_keep_phone_near",
                                          sampleFields: sampleFields)
        }
        if (saved.hrArtifactHeldValue + saved.hrArtifactDroppedValue) > 0 && readiness.thresholdGapBPM > 0 {
            return WorkoutCaptureEvidence(diagnosis: "artifact_filtering_or_motion",
                                          action: "inspect_raw_hr_artifacts",
                                          sampleFields: sampleFields)
        }
        if readiness.thresholdGapBPM > 0 {
            return WorkoutCaptureEvidence(diagnosis: "received_hr_below_threshold",
                                          action: "compare_reference_hr_before_profile_change",
                                          sampleFields: sampleFields)
        }
        if readiness.hrDistributionBelowWorkoutBand {
            return WorkoutCaptureEvidence(diagnosis: "wrist_hr_distribution_below_workout_band",
                                          action: "validate_wrist_hr_underreporting_or_profile_before_more_workouts",
                                          sampleFields: sampleFields)
        }
        if readiness.observedDuration < 10 * 60 {
            return WorkoutCaptureEvidence(diagnosis: "too_short",
                                          action: "keep_collecting",
                                          sampleFields: sampleFields)
        }
        return WorkoutCaptureEvidence(diagnosis: Self.evidenceToken(readiness.primaryBlocker),
                                      action: "keep_learning",
                                      sampleFields: sampleFields)
    }

    private func recordLinkAttempt(reason: String, peripheral: CBPeripheral?) {
        let defaults = UserDefaults.standard
        let attempts = defaults.integer(forKey: LinkDefaults.attempts) + 1
        defaults.set(attempts, forKey: LinkDefaults.attempts)
        defaults.set("connecting", forKey: LinkDefaults.lastStatus)
        defaults.set(reason, forKey: LinkDefaults.lastReason)
        refreshOfficialAppCoexistenceRisk(reason: "link_attempt")
        AtriaDebugLog("ATRIADBG ble_link status=connecting reason=%@ attempts=%d disconnects=%d failures=%d name=%@",
              reason,
              attempts,
              defaults.integer(forKey: LinkDefaults.disconnects),
              defaults.integer(forKey: LinkDefaults.failures),
              peripheral?.name ?? deviceName)
    }

    private func markPendingKnownReconnect(reason: String) {
        pendingKnownReconnectStartedAt = Date()
        pendingKnownReconnectReason = reason
    }

    private func clearPendingKnownReconnect(reason: String) {
        guard pendingKnownReconnectStartedAt != nil || !pendingKnownReconnectReason.isEmpty else { return }
        pendingKnownReconnectStartedAt = nil
        pendingKnownReconnectReason = ""
        AtriaDebugLog("ATRIADBG ble_link pending_known_reconnect status=cleared reason=%@", reason)
    }

    nonisolated static func connectedIdentityPromotionDisposition(
        savedPeripheralIdentifier: UUID?,
        connectedPeripheralIdentifier: UUID,
        evidence: FirstUseConnectionEvidence,
        standardHeartRateCandidateWasWhoopQualified: Bool
    ) -> ConnectedIdentityPromotionDisposition {
        if savedPeripheralIdentifier == connectedPeripheralIdentifier {
            return .preserveSavedBehavior
        }
        switch evidence {
        case .provisionalConnection:
            return .awaitFirstUseValidation
        case .whoopService:
            return .promoteFirstUseIdentity
        case .standardHeartRateMeasurement:
            return standardHeartRateCandidateWasWhoopQualified
                ? .promoteFirstUseIdentity
                : .rejectUnqualifiedStandardHeartRate
        }
    }

    /// The only unsaved-to-saved write. A provisional CoreBluetooth connection
    /// is not success: first use becomes durable only after WHOOP-specific GATT
    /// or 2A37 from a candidate already qualified by WHOOP scan identity.
    @discardableResult
    static func persistObservedConnectedIdentity(
        _ identifier: UUID,
        evidence: FirstUseConnectionEvidence,
        standardHeartRateCandidateWasWhoopQualified: Bool,
        defaults: UserDefaults
    ) -> Bool {
        let savedIdentifier = defaults
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        guard connectedIdentityPromotionDisposition(
            savedPeripheralIdentifier: savedIdentifier,
            connectedPeripheralIdentifier: identifier,
            evidence: evidence,
            standardHeartRateCandidateWasWhoopQualified:
                standardHeartRateCandidateWasWhoopQualified
        ) == .promoteFirstUseIdentity else {
            return false
        }
        defaults.set(
            identifier.uuidString,
            forKey: LinkDefaults.savedPeripheralUUID
        )
        return true
    }

    private func recordLinkConnected(peripheral: CBPeripheral) {
        guard let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else { return }
        let callbackEpoch = callbackSource.epoch
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: LinkDefaults.savedPeripheralUUID)
                == peripheral.identifier.uuidString else {
            AtriaDebugLog(
                "ATRIADBG ble_link status=provisional_connected reason=did_connect peripheral=%@ action=await_whoop_gatt_or_qualified_2a37_validation_saved_identity_unchanged",
                peripheral.identifier.uuidString
            )
            return
        }
        clearPendingKnownReconnect(reason: "did_connect")
        if durableConnectedIdentityRecordedEpoch == callbackEpoch {
            // Duplicate evidence from the exact saved owner must not inflate
            // durable success diagnostics, but the idempotent recovery
            // reducers still need the signal. A restored/service-observed path
            // can stamp this epoch before didConnect reaches MainActor.
            scheduleRangeLossBackfillIfNeeded(reason: "did_connect")
            reconcileHistoricalRecoveryPresentation(reason: "did_connect")
            return
        }
        durableConnectedIdentityRecordedEpoch = callbackEpoch
        if let previousSavedStrap = defaults.string(
            forKey: LinkDefaults.savedPeripheralUUID
        ), previousSavedStrap != peripheral.identifier.uuidString {
            workoutHistoryPreemptionSuccessorGate.retire()
        }
        // Remember this strap so we can re-arm a standing pending connection to it
        // on every launch / drop without scanning. "Connect once, stay connected."
        defaults.set(peripheral.identifier.uuidString, forKey: LinkDefaults.savedPeripheralUUID)
        let successes = defaults.integer(forKey: LinkDefaults.successes) + 1
        defaults.set(successes, forKey: LinkDefaults.successes)
        defaults.set("connected", forKey: LinkDefaults.lastStatus)
        defaults.set("did_connect", forKey: LinkDefaults.lastReason)
        defaults.set("none", forKey: LinkDefaults.lastError)
        persistOfficialAppCoexistenceRisk(.cleared, reason: "atria_connected")
        AtriaDebugLog("ATRIADBG ble_link status=connected successes=%d attempts=%d disconnects=%d failures=%d mtu=%d name=%@",
              successes,
              defaults.integer(forKey: LinkDefaults.attempts),
              defaults.integer(forKey: LinkDefaults.disconnects),
              defaults.integer(forKey: LinkDefaults.failures),
              dbgMTU,
              peripheral.name ?? deviceName)
        scheduleRangeLossBackfillIfNeeded(reason: "did_connect")
        reconcileHistoricalRecoveryPresentation(reason: "did_connect")
    }

    private func recordLinkObservedConnected(
        reason: String,
        peripheral: CBPeripheral,
        callbackSource: AtriaBLECallbackEpochFence.Source,
        evidence: FirstUseConnectionEvidence
    ) {
        let defaults = UserDefaults.standard
        let whoopQualifiedForStandardHeartRate =
            firstUseStandardHeartRateCandidateID == peripheral.identifier
        let savedIdentifier = defaults
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        let disposition = Self.connectedIdentityPromotionDisposition(
            savedPeripheralIdentifier: savedIdentifier,
            connectedPeripheralIdentifier: peripheral.identifier,
            evidence: evidence,
            standardHeartRateCandidateWasWhoopQualified:
                whoopQualifiedForStandardHeartRate
        )
        switch disposition {
        case .awaitFirstUseValidation:
            AtriaDebugLog(
                "ATRIADBG ble_link status=provisional_connected reason=%@ peripheral=%@ action=await_whoop_gatt_or_qualified_2a37_validation",
                reason,
                peripheral.identifier.uuidString
            )
            return
        case .rejectUnqualifiedStandardHeartRate:
            AtriaDebugLog(
                "ATRIADBG ble_link status=validation_rejected reason=%@ peripheral=%@ evidence=generic_2a37 action=retain_unsaved",
                reason,
                peripheral.identifier.uuidString
            )
            return
        case .promoteFirstUseIdentity, .preserveSavedBehavior:
            // Promotion and observed-success publication must revalidate the
            // complete delegate-entry proof at the mutation site. A UUID and
            // epoch scalar are insufficient: restoration can vend an
            // object-distinct peripheral with the same UUID, and a queued
            // MainActor task can outlive the source that originally admitted
            // it. Fail closed before touching durable identity or success.
            guard acceptsBLECallback(
                source: callbackSource,
                peripheral: peripheral
            ) else {
                AtriaDebugLog(
                    "ATRIADBG ble_link status=validation_rejected reason=%@ peripheral=%@ evidence=%@ action=stale_exact_callback_source_no_mutation",
                    reason,
                    peripheral.identifier.uuidString,
                    String(describing: evidence)
                )
                return
            }
        }
        switch disposition {
        case .promoteFirstUseIdentity:
            if let savedIdentifier,
               savedIdentifier != peripheral.identifier {
                workoutHistoryPreemptionSuccessorGate.retire()
            }
            guard Self.persistObservedConnectedIdentity(
                peripheral.identifier,
                evidence: evidence,
                standardHeartRateCandidateWasWhoopQualified:
                    whoopQualifiedForStandardHeartRate,
                defaults: defaults
            ) else { return }
            clearPendingKnownReconnect(reason: reason)
            firstUseStandardHeartRateCandidateID = nil
            scheduleRangeLossBackfillIfNeeded(reason: reason)
            reconcileHistoricalRecoveryPresentation(reason: reason)
            AtriaDebugLog(
                "ATRIADBG ble_link status=validated_identity_saved reason=%@ peripheral=%@ evidence=%@",
                reason,
                peripheral.identifier.uuidString,
                String(describing: evidence)
            )
        case .preserveSavedBehavior:
            break
        case .awaitFirstUseValidation, .rejectUnqualifiedStandardHeartRate:
            return
        }
        guard durableConnectedIdentityRecordedEpoch != callbackSource.epoch else { return }
        guard defaults.string(forKey: LinkDefaults.lastStatus) != "connected" else { return }
        durableConnectedIdentityRecordedEpoch = callbackSource.epoch
        let successes = defaults.integer(forKey: LinkDefaults.successes) + 1
        defaults.set(successes, forKey: LinkDefaults.successes)
        defaults.set("connected", forKey: LinkDefaults.lastStatus)
        defaults.set(reason, forKey: LinkDefaults.lastReason)
        defaults.set("none", forKey: LinkDefaults.lastError)
        persistOfficialAppCoexistenceRisk(.cleared, reason: "atria_observed_connected")
        AtriaDebugLog("ATRIADBG ble_link status=connected reason=%@ successes=%d attempts=%d disconnects=%d failures=%d name=%@",
              reason,
              successes,
              defaults.integer(forKey: LinkDefaults.attempts),
              defaults.integer(forKey: LinkDefaults.disconnects),
              defaults.integer(forKey: LinkDefaults.failures),
              peripheral.name ?? deviceName)
    }

    private func resetLinkDiagnosticsForDebugLaunch(arguments: [String]) {
        guard arguments.contains("--atria-reset-link-diagnostics") else { return }
        let defaults = UserDefaults.standard
        [
            LinkDefaults.attempts,
            LinkDefaults.disconnects,
            LinkDefaults.successes,
            LinkDefaults.failures,
            LinkDefaults.lastStatus,
            LinkDefaults.lastReason,
            LinkDefaults.lastError,
            LinkDefaults.lastAutoSaveStatus,
            LinkDefaults.lastAutoSaveSamples,
            LinkDefaults.lastAutoSaveDuration,
            LinkDefaults.lastDisconnectCause,
            LinkDefaults.lastDisconnectAt,
            LinkDefaults.disconnectsThisLaunch,
            LinkDefaults.officialAppCoexistenceRisk,
            LinkDefaults.officialAppCoexistenceReason
        ].forEach { defaults.removeObject(forKey: $0) }
        AtriaDebugLog("ATRIADBG ble_link reset=1 reason=launch_arg")
    }

