    private func scheduleAutoCapture() {
        autoCaptureAttempt = 0
        scheduleAutoCaptureAttempt(reason: "initial")
    }

    private func scheduleAutoCaptureAttempt(reason: String) {
        autoCaptureScheduledAt = Date()
        autoCapturePending = true
        resetRRAvailabilityWindow(&autoCaptureRRWindow, head: &autoCaptureRRWindowHead)
        lastAutoCaptureRRGateLogAt = nil
        AtriaDebugLog("ATRIADBG autoCapture schedule label=%@ reason=%@ attempt_next=%d max_attempts=%d delay_s=%.1f rr_threshold=%.2f rr_window_s=%.1f rr_min_frames=%d rr_max_gap_s=%.1f rr_timeout_s=%.1f stop_when_ready=%d stop_after_s=%.1f strict_live_rr=%d",
              captureLabel, reason, autoCaptureAttempt + 1, autoCaptureMaxAttempts,
              autoCaptureDelaySeconds, autoCaptureRRThreshold,
              autoCaptureRRWindowSeconds, autoCaptureRRMinFrames,
              autoCaptureMaxRRGapSeconds, autoCaptureRRTimeoutSeconds,
              autoStopCaptureWhenReady ? 1 : 0, autoStopCaptureAfterSeconds,
              strictLiveRRCapture ? 1 : 0)
        if autoCaptureRRThreshold > 0 {
            if autoCaptureRRTimeoutSeconds > 0 {
                autoCaptureTimeoutTask?.cancel()
                autoCaptureTimeoutTask = Task { @MainActor in
                    try? await Task.sleep(for: .seconds(autoCaptureRRTimeoutSeconds))
                    startAutoCaptureIfNeeded(reason: "timeout")
                }
            }
            return
        }
        Task { @MainActor in
            if autoCaptureDelaySeconds > 0 {
                try? await Task.sleep(for: .seconds(autoCaptureDelaySeconds))
            }
            startAutoCaptureIfNeeded(reason: "delay")
        }
    }

    private func startAutoCaptureIfNeeded(reason: String) {
        guard autoCapturePending, !isRecording else { return }
        guard autoCaptureAttempt < autoCaptureMaxAttempts else {
            autoCapturePending = false
            autoCaptureTimeoutTask?.cancel()
            autoCaptureTimeoutTask = nil
            AtriaDebugLog("ATRIADBG autoCapture exhausted label=%@ attempts=%d max_attempts=%d reason=%@",
                  captureLabel, autoCaptureAttempt, autoCaptureMaxAttempts, reason)
            return
        }
        autoCaptureAttempt += 1
        autoCapturePending = false
        autoCaptureTimeoutTask?.cancel()
        autoCaptureTimeoutTask = nil
        AtriaDebugLog("ATRIADBG autoCapture start label=%@ attempt=%d max_attempts=%d reason=%@ delay_s=%.1f rr_threshold=%.2f stop_when_ready=%d stop_after_s=%.1f",
              captureLabel, autoCaptureAttempt, autoCaptureMaxAttempts,
              reason, autoCaptureDelaySeconds, autoCaptureRRThreshold,
              autoStopCaptureWhenReady ? 1 : 0, autoStopCaptureAfterSeconds)
        toggleRecording()
    }

    private func rearmAutoCaptureAfterAbort(reason: String) {
        guard autoCaptureRRThreshold > 0 else { return }
        guard autoCaptureAttempt < autoCaptureMaxAttempts else {
            AtriaDebugLog("ATRIADBG autoCapture exhausted label=%@ attempts=%d max_attempts=%d reason=%@",
                  captureLabel, autoCaptureAttempt, autoCaptureMaxAttempts, reason)
            return
        }
        scheduleAutoCaptureAttempt(reason: reason)
    }

    private func appendAdaptiveAutoCaptureObservation(now: Date, rrnum: Int, source: String) -> Bool {
        guard autoCapturePending, autoCaptureRRThreshold > 0, !isRecording else { return false }
        guard autoCaptureScheduledAt != nil else { return false }
        guard shouldTrackRRAvailability(source: source, rrCount: rrnum) else { return false }
        if shouldSkipRealtimeZeroRRTracking(now: now,
                                           rrCount: rrnum,
                                           source: source,
                                           lastTrackedAt: &lastRealtimeZeroRRAutoCaptureUpdateAt) {
            return false
        }
        autoCaptureRRWindow.append((t: now, hasRR: rrnum > 0, source: source))
        return true
    }

    private func evaluateAdaptiveAutoCapture(now: Date) {
        guard autoCapturePending, autoCaptureRRThreshold > 0, !isRecording else { return }
        guard let scheduledAt = autoCaptureScheduledAt else { return }
        let summary = pruneRRWindow(&autoCaptureRRWindow,
                                    head: &autoCaptureRRWindowHead,
                                    now: now,
                                    maxAge: autoCaptureRRWindowSeconds)

        let totalFrames = summary.frames
        let rrFrames = summary.rrFrames
        let fraction = summary.fraction
        let frameMaxRRGap = summary.frameMaxGap
        let beatMaxRRGap = maxRRBeatGap(since: max(scheduledAt, now.addingTimeInterval(-autoCaptureRRWindowSeconds)),
                                        now: now)
        let maxRRGap = beatMaxRRGap ?? frameMaxRRGap
        let sourceLabel = summary.sourceLabel
        let gapEligible = autoCaptureMaxRRGapSeconds <= 0 || maxRRGap <= autoCaptureMaxRRGapSeconds
        let elapsed = now.timeIntervalSince(scheduledAt)
        let gateEligible = elapsed >= autoCaptureDelaySeconds && totalFrames >= autoCaptureRRMinFrames

        let shouldLogGate: Bool
        if let lastAutoCaptureRRGateLogAt {
            shouldLogGate = now.timeIntervalSince(lastAutoCaptureRRGateLogAt) >= 5
        } else {
            shouldLogGate = true
        }
        if gateEligible, shouldLogGate {
            lastAutoCaptureRRGateLogAt = now
            AtriaDebugLog("ATRIADBG autoCapture rr_gate source=%@ elapsed_s=%.1f fraction=%.3f rr_frames=%d total_frames=%d threshold=%.3f max_rr_gap_s=%.1f frame_max_rr_gap_s=%.1f beat_timeline=%d max_gap_threshold_s=%.1f gap_ok=%d window_s=%.1f min_frames=%d",
                  sourceLabel,
                  elapsed, fraction, rrFrames, totalFrames, autoCaptureRRThreshold,
                  maxRRGap, frameMaxRRGap, beatMaxRRGap == nil ? 0 : 1,
                  autoCaptureMaxRRGapSeconds, gapEligible ? 1 : 0,
                  autoCaptureRRWindowSeconds, autoCaptureRRMinFrames)
        }

        guard gateEligible, fraction >= autoCaptureRRThreshold, gapEligible else { return }
        startAutoCaptureIfNeeded(reason: String(format: "rr_fraction_%.3f", fraction))
    }

    private func updateAdaptiveAutoCapture(now: Date, rrnum: Int, source: String) {
        guard appendAdaptiveAutoCaptureObservation(now: now, rrnum: rrnum, source: source) else { return }
        if realtimePacketBatchDepth > 0, source == "0x28" {
            realtimeBatchPendingAutoCaptureAt = now
            return
        }
        evaluateAdaptiveAutoCapture(now: now)
    }

    private func resetRRAvailabilityWindow(_ window: inout [(t: Date, hasRR: Bool, source: String)],
                                           head: inout Int) {
        window.removeAll(keepingCapacity: true)
        head = 0
    }

    private func removeRRAvailabilityWindowEntries(_ window: inout [(t: Date, hasRR: Bool, source: String)],
                                                   head: inout Int,
                                                   where shouldRemove: ((t: Date, hasRR: Bool, source: String)) -> Bool) {
        guard !window.isEmpty else {
            head = 0
            return
        }
        let activeStart = min(head, window.count)
        let active = window[activeStart...].filter { !shouldRemove($0) }
        window = Array(active)
        head = 0
    }

    private func compactRRAvailabilityWindowIfNeeded(_ window: inout [(t: Date, hasRR: Bool, source: String)],
                                                     head: inout Int) {
        guard head > 0 else { return }
        if head >= window.count {
            window.removeAll(keepingCapacity: true)
            head = 0
            return
        }
        if head >= 64 && head * 2 >= window.count {
            window.removeFirst(head)
            head = 0
        }
    }

    @discardableResult
    private func pruneRRWindow(_ window: inout [(t: Date, hasRR: Bool, source: String)],
                               head: inout Int,
                               now: Date,
                               maxAge: TimeInterval,
                               minimumTime: Date? = nil) -> RRWindowSummary {
        while head < window.count {
            let sample = window[head]
            if let minimumTime, sample.t < minimumTime {
                head += 1
                continue
            }
            if now.timeIntervalSince(sample.t) > maxAge {
                head += 1
                continue
            }
            break
        }
        compactRRAvailabilityWindowIfNeeded(&window, head: &head)

        guard head < window.count else {
            return RRWindowSummary(frames: 0,
                                   rrFrames: 0,
                                   fraction: 0,
                                   span: 0,
                                   frameMaxGap: 0,
                                   sourceLabel: "none",
                                   firstTimestamp: nil)
        }
        let activeWindow = window[head...]
        guard let first = activeWindow.first else {
            return RRWindowSummary(frames: 0,
                                   rrFrames: 0,
                                   fraction: 0,
                                   span: 0,
                                   frameMaxGap: 0,
                                   sourceLabel: "none",
                                   firstTimestamp: nil)
        }

        var rrFrames = 0
        var has2A37 = false
        var has28 = false
        var firstRR: Date?
        var previousRR: Date?
        var frameMaxGap: TimeInterval = 0

        for sample in activeWindow {
            guard sample.hasRR else { continue }
            rrFrames += 1
            if sample.source == "0x2A37" {
                has2A37 = true
            } else if sample.source == "0x28" {
                has28 = true
            }
            if let previousRR {
                frameMaxGap = max(frameMaxGap, sample.t.timeIntervalSince(previousRR))
            } else {
                firstRR = sample.t
                frameMaxGap = sample.t.timeIntervalSince(first.t)
            }
            previousRR = sample.t
        }

        if let previousRR {
            frameMaxGap = max(frameMaxGap, now.timeIntervalSince(previousRR))
        } else {
            frameMaxGap = now.timeIntervalSince(first.t)
        }

        let sourceLabel: String
        if has2A37 && has28 {
            sourceLabel = "mixed"
        } else if has2A37 {
            sourceLabel = "2a37"
        } else if has28 {
            sourceLabel = "0x28"
        } else {
            sourceLabel = "none"
        }

        let frames = activeWindow.count
        return RRWindowSummary(frames: frames,
                               rrFrames: rrFrames,
                               fraction: frames > 0 ? Double(rrFrames) / Double(frames) : 0,
                               span: now.timeIntervalSince(first.t),
                               frameMaxGap: frameMaxGap,
                               sourceLabel: sourceLabel,
                               firstTimestamp: firstRR ?? first.t)
    }

    private var currentRRBufferCount: Int {
        max(0, rrBuffer.count - rrBufferHead)
    }

    private func resetRRBuffer() {
        rrBuffer.removeAll(keepingCapacity: true)
        rrBufferHead = 0
    }

    private func compactRRBufferIfNeeded() {
        guard rrBufferHead > 0 else { return }
        if rrBufferHead >= rrBuffer.count {
            rrBuffer.removeAll(keepingCapacity: true)
            rrBufferHead = 0
            return
        }
        if rrBufferHead >= 128 && rrBufferHead * 2 >= rrBuffer.count {
            rrBuffer.removeFirst(rrBufferHead)
            rrBufferHead = 0
        }
    }

    private func pruneRRBuffer(now: Date) {
        while rrBufferHead < rrBuffer.count,
              now.timeIntervalSince(rrBuffer[rrBufferHead].t) > 305 {
            rrBufferHead += 1
        }
        compactRRBufferIfNeeded()
    }

    private func currentRRBufferWindow() -> ArraySlice<RRInterval> {
        guard rrBufferHead < rrBuffer.count else { return [] }
        return rrBuffer[rrBufferHead...]
    }

    private func noteRRArchiveDidChange() {
        rrArchiveRevision &+= 1
        recentBreathworkRRSampleCache = nil
    }

    func recentBreathworkRRSamples(now: Date = Date(), maxAge: TimeInterval = 10 * 60) -> [AtriaBreathworkSession.RRSample] {
        let nowBucket = Int((now.timeIntervalSinceReferenceDate / Self.recentBreathworkRRCacheBucketSeconds).rounded(.down))
        if let cache = recentBreathworkRRSampleCache,
           cache.archiveRevision == rrArchiveRevision,
           cache.maxAge == maxAge,
           cache.nowBucket == nowBucket {
            return cache.samples
        }

        var samples: [AtriaBreathworkSession.RRSample] = []
        samples.reserveCapacity(min(rrArchive.count, 900))
        for interval in rrArchive.reversed() {
            guard now.timeIntervalSince(interval.t) <= maxAge else { break }
            guard interval.source == .standardHeartRateMeasurement2A37 else {
                // Do not reinterpret a source-ambiguous or mixed fallback tail
                // as one continuous standard 2A37 breathwork window.
                samples.removeAll(keepingCapacity: true)
                break
            }
            let roundedMS = Int(interval.ms.rounded())
            guard (300...2000).contains(roundedMS) else { continue }
            samples.append(AtriaBreathworkSession.RRSample(
                date: interval.t,
                ms: roundedMS,
                source: .standardHeartRateMeasurement2A37
            ))
            if samples.count == 900 { break }
        }
        samples.reverse()
        recentBreathworkRRSampleCache = RecentBreathworkRRSampleCache(archiveRevision: rrArchiveRevision,
                                                                      maxAge: maxAge,
                                                                      nowBucket: nowBucket,
                                                                      samples: samples)
        return samples
    }

    func startScan(reason: String = "manual") {
        guard central.state == .poweredOn else {
            pendingScanReason = reason
            AtriaDebugLog("ATRIADBG ble_scan status=skipped reason=%@ central_state=%d",
                  reason,
                  central.state.rawValue)
            return
        }
        pendingScanReason = nil
        // State restoration can hand us one unowned WHOOP object in
        // `.connecting` before `centralManagerDidUpdateState` runs. A scan
        // cannot make progress while that object occupies `self.peripheral`:
        // `didDiscover` deliberately accepts only the first candidate. More
        // importantly, the old path cancelled the restoration watchdog here,
        // leaving the app in "Waiting for Bluetooth" forever if the inherited
        // connect never completed.
        //
        // Keep the single in-flight candidate and its bounded watchdog. A real
        // `didConnect` persists the identity normally; if it stalls, the
        // watchdog clears only this unsaved candidate and begins the ordinary
        // broad fresh-bond scan. Saved straps retain their standing-connect
        // behavior unchanged.
        if let pendingPeripheral = peripheral,
           Self.shouldHoldUnsavedRestoredCandidate(
               state: pendingPeripheral.state,
               hasSavedStrap: hasSavedStrap
           ) {
            central.stopScan()
            isActivelyScanning = false
            recomputeConnectionStatus(reason: "unsaved_restored_candidate")
            startReconnectWatchdog(
                reason: "\(reason)_unsaved_restored_candidate",
                peripheral: pendingPeripheral
            )
            AtriaDebugLog(
                "ATRIADBG ble_scan status=deferred reason=%@ action=hold_unsaved_restored_candidate_with_watchdog peripheral_state=%d",
                reason,
                pendingPeripheral.state.rawValue
            )
            return
        }
        let systemConnectedCandidates =
            central.retrieveConnectedPeripherals(
                withServices: UUIDs.scanServices
            )
        let savedIdentifier = UserDefaults.standard
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        let locallyAdoptableConnectedCandidate = savedIdentifier.flatMap {
            savedID in
            systemConnectedCandidates.first { $0.identifier == savedID }
        } ?? systemConnectedCandidates.first { candidate in
            // First-time setup must not silently adopt an arbitrary nearby
            // 180D chest strap. A WHOOP identity is provisional until GATT/HR
            // validates it, but is sufficient to establish the local link.
            Self.scanCandidateHasStrapIdentity(
                advertisedServices: [],
                advertisedName: candidate.name
            )
        }
        if peripheral == nil,
           !isReadOnlyHistoryFreshCutoverScanReason(reason),
           let restored = locallyAdoptableConnectedCandidate {
            attach(to: restored, name: restored.name ?? "Strap")
            AtriaDebugLog("ATRIADBG ble_scan status=short_circuit reason=%@ action=attach_connected_peripheral",
                  reason)
            return
        }
        if !reason.contains("_retry") {
            scanRetryCount = 0
        }
        let allowBroadScan = shouldAllowBroadScan(for: reason)
        let hasEverConnected = UserDefaults.standard.integer(
            forKey: LinkDefaults.successes
        ) > 0
        let scanPlan = Self.scanOrchestrationPlan(
            broadScanAllowed: allowBroadScan,
            useBroadImmediately: shouldUseBroadScanImmediately(
                for: reason,
                allowBroadScan: allowBroadScan,
                hasEverConnected: hasEverConnected
            ),
            retryCount: scanRetryCount,
            maximumRetryCount: maxScanRetries
        )
        let useBroadScan = scanPlan.mode == .broad
        let requestedMode = useBroadScan ? "broad" : "filtered"
        if status == .scanning,
           peripheral == nil,
           !reason.contains("_retry"),
           !reason.contains("_broad"),
           let lastScanRequestedAt,
           Date().timeIntervalSince(lastScanRequestedAt) < Self.scanRequestDedupWindow,
           lastScanRequestMode == requestedMode {
            AtriaDebugLog("ATRIADBG ble_scan status=coalesced reason=%@ mode=%@ since_last_s=%.2f",
                  reason,
                  requestedMode,
                  Date().timeIntervalSince(lastScanRequestedAt))
            return
        }
        lastScanRequestedAt = Date()
        lastScanRequestMode = requestedMode
        reconnectWatchdogTask?.cancel()
        scanWideningTask?.cancel()
        if !hasSavedStrap {
            clearPendingKnownReconnect(reason: "start_scan")
        }
        isActivelyScanning = true
        recomputeConnectionStatus(reason: "start_scan")
        // Prefer a staged fresh scan: start with the expected strap/heart-rate
        // services for faster discovery, then broaden only if nothing appears.
        AtriaDebugLog("ATRIADBG ble_scan status=started reason=%@ standard_hr_only=%d retry=%d mode=%@ broad_allowed=%d",
              reason,
              standardHROnlyMode ? 1 : 0,
              scanRetryCount,
              requestedMode,
              allowBroadScan ? 1 : 0)
        central.scanForPeripherals(withServices: useBroadScan ? nil : UUIDs.scanServices,
                                   options: [CBCentralManagerScanOptionAllowDuplicatesKey: false])
        if scanPlan.schedulesWidening {
            scheduleScanWidening(reason: reason)
        }
        if scanPlan.schedulesRetry {
            scheduleScanRetry(reason: reason)
        }
    }

    nonisolated static func shouldHoldUnsavedRestoredCandidate(
        state: CBPeripheralState,
        hasSavedStrap: Bool
    ) -> Bool {
        guard !hasSavedStrap else { return false }
        return state == .connecting || state == .disconnecting
    }

    nonisolated static func scanOrchestrationPlan(
        broadScanAllowed: Bool,
        useBroadImmediately: Bool,
        retryCount: Int,
        maximumRetryCount: Int
    ) -> ScanOrchestrationPlan {
        let mode: ScanDiscoveryMode = broadScanAllowed && useBroadImmediately
            ? .broad
            : .filtered
        return ScanOrchestrationPlan(
            mode: mode,
            schedulesWidening: broadScanAllowed && mode == .filtered,
            schedulesRetry: retryCount < maximumRetryCount
        )
    }

    nonisolated static func broadScanStartsImmediately(
        reason: String,
        allowBroadScan: Bool,
        hasEverConnected: Bool,
        retryCount: Int
    ) -> Bool {
        guard allowBroadScan else { return false }
        if reason == "peer_removed_pairing"
            || reason == "onboarding_strap"
            || reason == "onboarding_primary_connect"
            || reason.hasPrefix("read_only_history_restored_cutover")
            || reason.contains("_broad")
            || retryCount > 0 {
            return true
        }
        return !hasEverConnected && Self.isInitialAutomaticSetupReason(reason)
    }

    private func shouldUseBroadScanImmediately(
        for reason: String,
        allowBroadScan: Bool,
        hasEverConnected: Bool
    ) -> Bool {
        Self.broadScanStartsImmediately(
            reason: reason,
            allowBroadScan: allowBroadScan,
            hasEverConnected: hasEverConnected,
            retryCount: scanRetryCount
        )
    }

    private func shouldAllowBroadScan(for reason: String) -> Bool {
        if isFreshBondScanReason(reason) {
            return true
        }
        if reason.contains("_broad") {
            return true
        }
        // A forgotten/replaced iOS bond removes the persisted CoreBluetooth
        // identifier. WHOOP's pairing advertisement may omit the services used
        // by the filtered scan, so a filtered-only reconnect can remain stuck
        // forever even while the strap is visibly advertising. Widen only when
        // no saved identity exists; `didDiscover` still requires a WHOOP name
        // or one of the known strap/heart-rate services before attaching.
        if !hasSavedStrap {
            return true
        }
        let hasEverConnected = UserDefaults.standard.integer(forKey: LinkDefaults.successes) > 0
        if !hasEverConnected {
            return true
        }
        if reason == "manual"
            || reason.contains("connection_guide")
            || reason.contains("home_manual")
            || reason.contains("restore_discard") {
            return true
        }
        return false
    }

    private func isFreshBondScanReason(_ reason: String) -> Bool {
        reason == "peer_removed_pairing"
            || reason == "onboarding_strap"
            || reason == "onboarding_primary_connect"
            || isReadOnlyHistoryFreshCutoverScanReason(reason)
    }

    private func isReadOnlyHistoryFreshCutoverScanReason(_ reason: String) -> Bool {
        reason.hasPrefix("read_only_history_restored_cutover")
    }

    nonisolated static func isInitialAutomaticSetupReason(_ reason: String) -> Bool {
        reason == "home_appear"
            || reason == "status_disconnected"
            || reason.hasPrefix("connection_guide")
            || reason == "scene_active_resume"
            || reason == "did_fail_to_connect_recovery"
            || reason == "central_powered_on"
    }

    nonisolated static func scanCandidateHasStrapIdentity(
        advertisedServices: [CBUUID],
        advertisedName: String?
    ) -> Bool {
        let uppercasedName = advertisedName?.uppercased()
        let hasWhoopName = uppercasedName?.contains("WHOOP") == true
            || uppercasedName?.contains("WHO") == true
        return advertisedServices.contains(UUIDs.strapService)
            || hasWhoopName
    }

    nonisolated static func shouldClaimCurrentScanCandidate(
        hasStrapIdentity: Bool,
        isActivelyScanning: Bool,
        hasCurrentPeripheralOwner: Bool
    ) -> Bool {
        hasStrapIdentity && isActivelyScanning && !hasCurrentPeripheralOwner
    }

    private func scheduleScanWidening(reason: String) {
        scanWideningTask?.cancel()
        scanWideningTask = Task { @MainActor in
            try? await Task.sleep(for: scanWideningDelay(for: reason))
            if Task.isCancelled { return }
            guard self.status == .scanning, self.peripheral == nil else { return }
            AtriaDebugLog("ATRIADBG ble_scan status=widen reason=%@ action=restart_scan_broad", reason)
            self.central.stopScan()
            self.startScan(reason: "\(reason)_broad")
        }
    }

    private func scheduleScanRetry(reason: String) {
        scanRetryTask?.cancel()
        guard scanRetryCount < maxScanRetries else { return }
        scanRetryTask = Task { @MainActor in
            try? await Task.sleep(for: scanRetryDelay(for: reason))
            if Task.isCancelled { return }
            guard self.status == .scanning, self.peripheral == nil else { return }
            self.scanRetryCount += 1
            AtriaDebugLog("ATRIADBG ble_scan status=retry reason=%@ retry=%d max=%d action=restart_scan",
                  reason,
                  self.scanRetryCount,
                  self.maxScanRetries)
            self.central.stopScan()
            self.startScan(reason: "\(reason)_retry")
        }
    }

    private func scanWideningDelay(for reason: String) -> Duration {
        let hasEverConnected = UserDefaults.standard.integer(forKey: LinkDefaults.successes) > 0
        if !hasEverConnected && Self.isInitialAutomaticSetupReason(reason) {
            return .milliseconds(900)
        }
        return .seconds(2)
    }

    private func scanRetryDelay(for reason: String) -> Duration {
        let hasEverConnected = UserDefaults.standard.integer(forKey: LinkDefaults.successes) > 0
        if !hasEverConnected && Self.isInitialAutomaticSetupReason(reason) {
            return .milliseconds(2800)
        }
        return .seconds(5)
    }

    /// Connect and start service discovery on a peripheral we found or retrieved.
    fileprivate func attach(to p: CBPeripheral, name: String) {
        let exactObjectOwnsCurrentEpoch = p.state == .connected
            && bleCallbackEpochFence.captureIfAccepted(
                peripheralID: p.identifier,
                peripheralObjectID: ObjectIdentifier(p),
                peripheralConnected: true
            ) != nil
        if p.state == .connected,
           connectedPeripheralRetainer.admitConnected(p)
            == .retainPassiveDuplicate {
            AtriaDebugLog(
                "ATRIADBG ble_scan status=attach_ignored reason=connected_same_uuid_duplicate action=retain_without_cancel"
            )
            return
        }
        scanRetryTask?.cancel()
        scanWideningTask?.cancel()
        scanRetryCount = 0
        central.stopScan()
        isActivelyScanning = false
        peripheral = p
        let savedIdentifier = UserDefaults.standard
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        if savedIdentifier != p.identifier {
            // Both callers reach `attach` only after WHOOP-specific name or
            // proprietary-service qualification. This grants standard 2A37
            // final-validation authority to this exact candidate, never to a
            // generic 180D peripheral restored without advertisement facts.
            firstUseStandardHeartRateCandidateID = p.identifier
        }
        assignIfChanged(\.deviceName, name)
        recomputeConnectionStatus(reason: "attach")
        p.delegate = self
        if exactObjectOwnsCurrentEpoch {
            // `willRestoreState` has already adopted and enabled this exact
            // connected object on the delegate lane; its MainActor publication
            // simply has not run yet. Publish it locally, but never manufacture
            // a second pending connect on the restored physical link.
            AtriaDebugLog(
                "ATRIADBG ble_scan status=attach_adopted reason=exact_restored_epoch action=no_duplicate_connect"
            )
            return
        }
        recordLinkAttempt(reason: "fresh_scan_attach", peripheral: p)
        issueSingleFlightConnect(
            p,
            central: central,
            reason: "fresh_scan_attach"
        )
        startReconnectWatchdog(reason: "fresh_scan_attach", peripheral: p)
    }

    func disconnect() {
        reconnectWatchdogTask?.cancel()
        freshScanFallbackTask?.cancel()
        freshScanFallbackTask = nil
        pendingRecoveryReconnectReason = nil
        pendingRecoveryIntent = .repairPipeline
        forceFreshScanAfterDisconnect = false
        userRequestedDisconnect = true
        if let p = peripheral {
            cancelPeripheralConnection(p, reason: "explicit_disconnect")
        }
    }

    /// A retained multi-file restore marker means canonical persistence is not
    /// safe. Stop the radio producer immediately and detach both delegates so
    /// CoreBluetooth restoration cannot reconnect behind the recovery screen.
    func suspendForCanonicalRestoreFailure() {
        guard !bluetoothStartupSuspended else { return }
        bluetoothStartupSuspended = true
        // The private CoreBluetooth lane may already be inside a callback.
        // Drain that admitted critical section before any radio, peripheral,
        // epoch, or delegate teardown so it cannot race this suspension.
        centralEventFence.retire(
            central,
            afterDraining: centralDelegateQueue,
            synchronizedTeardown: {
                // Peripheral delegates share the same CoreBluetooth lane.
                // Invalidate their exact-object epoch before this barrier
                // releases, so work queued behind it cannot capture the old
                // source during later MainActor teardown.
                bleCallbackEpochFence.invalidate()
            }
        )
        if offlineHistoricalSyncInProgress {
            offlineHistoricalSyncReachedTerminal = false
            finishOfflineHistoricalSync(
                reason: "canonical_restore_failure_suspension",
                generation: offlineHistoricalSyncGeneration,
                resumePendingSync: false
            )
        }
        if let restorationGeneration = postHistoryLiveRestorationGeneration {
            postHistoryLiveRestorationTask?.cancel()
            postHistoryLiveRestorationTask = nil
            postHistoryLiveRestorationGeneration = nil
            lastCompletedHistoricalSyncGeneration = restorationGeneration
            lastCompletedHistoricalSyncReachedTerminal = false
            lastCompletedHistoricalSyncHasOnboardingAuthority = false
            UserDefaults.standard.set(
                "post_history_live_restore_suspended",
                forKey: OfflineSyncDefaults.lastStatus
            )
            AtriaDebugLog("ATRIADBG offline_sync status=live_restore_suspended generation=%llu reason=canonical_restore_failure action=retain_gap",
                          restorationGeneration)
        }
        onSessionEnd = nil
        onSessionEndDurably = nil
        onSessionCheckpoint = nil
        stopForegroundKeepaliveWatchdog(reason: "restore_marker_retained")
        pauseLongWearAutomation(reason: "restore_marker_retained")
        reconnectWatchdogTask?.cancel()
        scanRetryTask?.cancel()
        scanWideningTask?.cancel()
        freshScanFallbackTask?.cancel()
        freshScanFallbackTask = nil
        realtimeRetry?.cancel()
        realtimeRestartTask?.cancel()
        r10ArmRetryTask?.cancel()
        r10LivenessTask?.cancel()
        proprietaryNotifyFallbackTask?.cancel()
        rangeLossBackfillTask?.cancel()
        rangeLossBackfillMaintenanceTickerTask?.cancel()
        rangeLossBackfillMaintenanceTickerTask = nil
        offlineHistoricalSyncTimeoutTask?.cancel()
        connectedHistoricalSliceTask?.cancel()
        connectedHistoricalSliceTask = nil
        connectedHistoricalSliceGeneration = nil
        connectedHistoricalSliceStartedAt = nil
        passiveR10FirstFrameTask?.cancel()
        stepCalibrationMotionPreparationTask?.cancel()
        cancelTrailingActiveJournalCheckpoint()
        activeJournalStepCheckpointTask?.cancel()
        batteryChargeExpirationTask?.cancel()
        batteryConfirmationReadTask?.cancel()
        proprietaryBatteryRefreshTimeoutTask?.cancel()
        batteryNotificationRecoveryTask?.cancel()
        motionHandshakeAddHRTask?.cancel()
        motionHandshakeCommandSequenceTask?.cancel()
        protectedR10ActivationGraceTask?.cancel()
        protectedR10MissingFrameTask?.cancel()
        protectedR10StabilityTask?.cancel()
        protectedR10CleanOwnerProofTimeoutTask?.cancel()
        // Handoff-13 CP0-A: this teardown used to cancel the proof deadline
        // and walk away with the durable state still `.proving` — an orphan
        // with no in-process deadline at all (one of the paths behind the
        // physically observed 47-minute proof). Terminalize an expired proof
        // here; a young proof keeps its persisted timestamp and the next
        // edge's synchronous sweep owns it.
        enforceProtectedR10ProofDeadlineIfNeeded(
            trigger: "suspend_for_canonical_restore_failure"
        )
        protectedR10CommandSequenceTask?.cancel()
        protectedR10StandardDiscoveryTask?.cancel()
        hrvLiveRefreshTask?.cancel()
        archiveSeedTask?.cancel()
        captureRowsFlushTask?.cancel()
        autoCaptureTimeoutTask?.cancel()
        sampleDiagnosticsFlushTask?.cancel()
        debugMissingHeartRateCharacteristicTask?.cancel()
        debugMissingHeartRateCharacteristicTask = nil
        debugActiveJournalFlushTask?.cancel()
        debugActiveJournalFlushTask = nil
        debugManualCheckpointTask?.cancel()
        debugManualCheckpointTask = nil
        captureTimer?.invalidate()
        captureTimer = nil
        central.stopScan()
        isActivelyScanning = false
        if let peripheral {
            peripheral.delegate = nil
            central.cancelPeripheralConnection(peripheral)
        }
        connectedPeripheralRetainer.releaseEverything()
        central.delegate = nil
        AtriaDebugLog("ATRIADBG ble_manager status=suspended reason=restore_marker_retained")
    }

    private func cancelPeripheralConnection(
        _ peripheral: CBPeripheral,
        reason: String,
        restoreRealtimeAfterHistoryGeneration: UInt64? = nil
    ) {
        endBackgroundReconnectLease(reason: "app_cancel_\(reason)")
        postReconnectHRReassertTask?.cancel()
        postReconnectHRReassertTask = nil
        let defaults = UserDefaults.standard
        defaults.set(reason, forKey: "atria.ble.lastAppCancelReason")
        defaults.set(Date().timeIntervalSince1970, forKey: "atria.ble.lastAppCancelAt")
        // (endBackgroundReconnectLease above also stops the silent-stream
        // watchdog; an app-owned cancel means this epoch's recovery is over.)
        defaults.set(defaults.integer(forKey: "atria.ble.appCancelCount") + 1,
                     forKey: "atria.ble.appCancelCount")
        backgroundReconnectFence.markAppOwnedCancellation(
            peripheralID: peripheral.identifier,
            restoreRealtimeAfterHistoryGeneration:
                restoreRealtimeAfterHistoryGeneration
        )
        recordReconnectLeaseStage("app_cancel_wrapper", detail: reason)
        central.cancelPeripheralConnection(peripheral)
        AtriaDebugLog("ATRIADBG ble_link status=cancel_requested reason=%@ app_cancel_count=%d",
                      reason,
                      defaults.integer(forKey: "atria.ble.appCancelCount"))
    }

    /// True once the user has paired a strap that we should keep reconnecting to.
    var hasSavedStrap: Bool {
        UserDefaults.standard.string(forKey: LinkDefaults.savedPeripheralUUID) != nil
    }

    /// THE SINGLE SOURCE OF TRUTH for the displayed status. Derives it purely from
    /// CoreBluetooth ground truth (central power state + the peripheral's real state
    /// + whether a strap is saved + whether we're scanning). Call after ANY event
    /// that can change those. Nothing else writes `status` — so heals, watchdogs, and
    /// stale/queued data can never lie (e.g. "Live" with Bluetooth off).
    func recomputeConnectionStatus(reason: String) {
        let next = derivedConnectionStatus()
        guard status != next else { return }
        status = next
        AtriaDebugLog("ATRIADBG status_derived to=%@ reason=%@ central=%ld peripheral=%ld saved=%d scanning=%d",
                      next.logToken,
                      reason,
                      Int(central.state.rawValue),
                      peripheral.map { Int($0.state.rawValue) } ?? -1,
                      hasSavedStrap ? 1 : 0,
                      isActivelyScanning ? 1 : 0)
    }

    private func derivedConnectionStatus() -> Status {
        Self.derivedConnectionStatus(
            centralState: central.state,
            peripheralState: peripheral?.state,
            hasSavedStrap: hasSavedStrap,
            isActivelyScanning: isActivelyScanning
        )
    }

    /// Only CoreBluetooth's exact `.poweredOff` state may produce the user-
    /// facing Bluetooth-off status. Authorization and platform availability
    /// are separate conditions; collapsing them into `.poweredOff` tells the
    /// user to toggle a radio that may already be on. Resetting/unknown retain a
    /// saved standing-connect presentation while CoreBluetooth recovers.
    nonisolated static func derivedConnectionStatus(
        centralState: CBManagerState,
        peripheralState: CBPeripheralState?,
        hasSavedStrap: Bool,
        isActivelyScanning: Bool
    ) -> Status {
        switch centralState {
        case .poweredOff:
            return .poweredOff
        case .unauthorized, .unsupported:
            return .disconnected
        case .poweredOn:
            if let peripheralState {
                switch peripheralState {
                case .connected:
                    return .connected
                case .connecting, .disconnecting:
                    return .connecting
                case .disconnected:
                    // We hold a peripheral ref but it's down: a saved strap means we
                    // have a standing pending connect (reconnecting), else first setup.
                    return hasSavedStrap ? .connecting : (isActivelyScanning ? .scanning : .disconnected)
                @unknown default:
                    return .connecting
                }
            }
            return isActivelyScanning
                ? .scanning
                : (hasSavedStrap ? .connecting : .disconnected)
        case .resetting, .unknown:
            return peripheralState == .connected
                ? .connected
                : (hasSavedStrap ? .connecting : .disconnected)
        @unknown default:
            return .disconnected
        }
    }

    /// Re-arm a STANDING pending connection to the saved strap — no scan. iOS keeps
    /// the request and connects whenever the strap is in range, across range loss,
    /// background, and app relaunch. This is the "connect once, stay connected"
    /// primitive. Returns false only if no strap is saved yet (first-time setup).
    nonisolated static func shouldEstablishLocalConnectionForSystemConnectedPeripheral(
        exactObjectOwnsCurrentEpoch: Bool
    ) -> Bool {
        !exactObjectOwnsCurrentEpoch
    }

    /// A CoreBluetooth object in `.connecting` already carries a standing
    /// request, while `.disconnecting` must reach its terminal callback before
    /// another request is legal. Only a settled disconnected object needs a
    /// new powered-on precheck connect.
    nonisolated static func shouldIssuePoweredOnStandingConnect(
        peripheralState: CBPeripheralState
    ) -> Bool {
        peripheralState == .disconnected
    }

    /// `didDisconnect` installs the standing reconnect synchronously because
    /// that delegate slice may be the app's last background execution. The
    /// later MainActor reducer is allowed to issue it only when the fast lane
    /// did not; `CBPeripheral.state` is not guaranteed to flip to `.connecting`
    /// before that reducer runs.
    nonisolated static func shouldIssueMainActorDisconnectReconnect(
        synchronousReconnectIssued: Bool,
        peripheralState: CBPeripheralState
    ) -> Bool {
        !synchronousReconnectIssued && peripheralState == .disconnected
    }

    nonisolated static func shouldIssueDelayedRecoveryConnect(
        peripheralState: CBPeripheralState
    ) -> Bool {
        peripheralState == .disconnected
    }

    @discardableResult
    func reconnectToSavedPeripheralIfPossible(reason: String,
                                               allowCleanOwnerLaunchCutover: Bool = false) -> Bool {
        let defaults = UserDefaults.standard
        guard let uuidString = defaults.string(forKey: LinkDefaults.savedPeripheralUUID),
              let uuid = UUID(uuidString: uuidString),
              let saved = central.retrievePeripherals(withIdentifiers: [uuid]).first else {
            return false
        }
        // Restoration claims the exact CoreBluetooth object synchronously on
        // the delegate lane, before its MainActor task can publish
        // `self.peripheral`. Treat that epoch claim as the connection
        // authority. Requiring the later UI-facing property as well creates a
        // launch race which issues `connect` on an already-restored link; the
        // duplicate pending request then surfaces as repeated connection
        // timeouts while notifications from the original link still arrive.
        let savedAlreadyOwnsCurrentEpoch = bleCallbackEpochFence
            .captureIfAccepted(
                peripheralID: saved.identifier,
                peripheralObjectID: ObjectIdentifier(saved),
                peripheralConnected: saved.state == .connected
            ) != nil
        if saved.state == .connected,
           connectedPeripheralRetainer.admitConnected(saved)
            == .retainPassiveDuplicate {
            AtriaDebugLog(
                "ATRIADBG ble_link status=reconnect_known reason=%@ action=ignore_connected_same_uuid_duplicate",
                reason
            )
            return true
        }
        saved.delegate = self
        self.peripheral = saved
        assignIfChanged(\.deviceName, saved.name ?? deviceName)
        if saved.state == .connected {
            if Self.shouldEstablishLocalConnectionForSystemConnectedPeripheral(
                exactObjectOwnsCurrentEpoch: savedAlreadyOwnsCurrentEpoch
            ) {
                // `retrievePeripherals`/`retrieveConnectedPeripherals` may
                // return a system-connected object that this replacement
                // central has never connected. Service discovery on that
                // object has no local callback epoch. Establish our local
                // connection and let didConnect create the sole canonical
                // epoch before touching GATT.
                recordLinkAttempt(
                    reason: "\(reason)_adopt_system_connected",
                    peripheral: saved
                )
                markPendingKnownReconnect(
                    reason: "\(reason)_adopt_system_connected"
                )
                issueSingleFlightConnect(
                    saved,
                    central: central,
                    reason: "\(reason)_adopt_system_connected"
                )
                startReconnectWatchdog(
                    reason: "\(reason)_adopt_system_connected",
                    peripheral: saved
                )
                recomputeConnectionStatus(reason: "event")
                AtriaDebugLog(
                    "ATRIADBG ble_link status=reconnect_known reason=%@ action=connect_system_connected_then_await_did_connect",
                    reason
                )
                return true
            }
            if beginMotionHandshakeLaunchConnectionCutoverIfNeeded(
                peripheral: saved,
                central: central,
                reason: reason
            ) {
                return true
            }
            if allowCleanOwnerLaunchCutover,
               beginProtectedR10LaunchConnectionCutoverIfNeeded(
                peripheral: saved,
                central: central,
                reason: reason
               ) {
                return true
            }
            clearPendingKnownReconnect(reason: "\(reason)_already_connected")
            recomputeConnectionStatus(reason: "event")
            if motionHandshakeDiagnostic != nil {
                recordMotionHandshakeEvidence(event: "already_connected",
                                              detail: "discover_stream5_service_only")
                saved.discoverServices([Self.UUIDs.strapService])
            } else {
                saved.discoverServices(discoveryServicesForCurrentMode)
            }
            AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=%@ action=already_connected", reason)
        } else if saved.state == .connecting || saved.state == .disconnecting {
            connectedPeripheralRetainer.adoptRestoredConnectTransition(saved)
            recomputeConnectionStatus(reason: "event")
            markPendingKnownReconnect(reason: reason)
            if saved.state == .connecting {
                startReconnectWatchdog(
                    reason: "\(reason)_existing_transition",
                    peripheral: saved
                )
            }
            AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=%@ action=keep_existing_transition peripheral_state=%d",
                          reason,
                          saved.state.rawValue)
        } else {
            recomputeConnectionStatus(reason: "event")
            recordLinkAttempt(reason: reason, peripheral: saved)
            markPendingKnownReconnect(reason: reason)
            // Standing pending connect — never times out; iOS fulfils it whenever
            // the strap becomes reachable. No scanning, no give-up.
            issueSingleFlightConnect(
                saved,
                central: central,
                reason: reason
            )
            startReconnectWatchdog(
                reason: "\(reason)_pending_connect",
                peripheral: saved
            )
            AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=%@ action=pending_connect", reason)
        }
        return true
    }

    /// A unique restoration namespace does not guarantee a physical BLE edge:
    /// iOS may hand the new process the old still-connected peripheral. Perform
    /// one persisted launch-only cutover before proof so stream 5 is established
    /// by `didConnect`, never by mutating an inherited link mid-connection.
    private func beginProtectedR10LaunchConnectionCutoverIfNeeded(
        peripheral: CBPeripheral,
        central: CBCentralManager,
        reason: String
    ) -> Bool {
        let defaults = UserDefaults.standard
        let isV7Pending = protectedR10CleanOwner == .protectedV7
            && protectedR10CleanOwnerState == .protectedLaunchPending
        let isV9Pending = protectedR10CleanOwner == .protectedV9
            && protectedR10CleanOwnerState == .protectedLaunchPending
        let cutoverKey = isV9Pending
            ? Self.protectedR10ResponseEventDataConnectionCutoverKey
            : Self.protectedR10CleanOwnerConnectionCutoverKey
        guard standardHROnlyMode,
              !historyOnlyProbeMode,
              !protectedR10StreamSuppressed,
              isV7Pending || isV9Pending,
              peripheral.state == .connected,
              !defaults.bool(forKey: cutoverKey) else {
            return false
        }
        defaults.set(true, forKey: cutoverKey)
        protectedR10InitialProfilePeripheralID = nil
        protectedR10InitialProfileNotificationRequested = false
        backgroundReconnectFence.markAppOwnedCancellation(
            peripheralID: peripheral.identifier
        )
        endBackgroundReconnectLease(reason: "protected_r10_workout_cutover")
        // A locked/background process leaves no console, so the only forensics
        // for which path tore a live link down are the persisted breadcrumbs.
        recordReconnectLeaseStage("app_cancel_r10_launch_cutover", detail: reason)
        central.cancelPeripheralConnection(peripheral)
        AtriaDebugLog("ATRIADBG protected_r10 status=clean_owner_launch_cutover owner=%@ reason=%@ action=single_disconnect_then_didconnect_profile_no_history",
                      protectedR10CleanOwner.rawValue,
                      reason)
        return true
    }

    /// Once a failed v9 link is fully down, move immediately to the fresh v10
    /// pure-HR restoration namespace. This is a single bounded owner cutover,
    /// not a retry loop: the new central follows the ordinary saved-peripheral
    /// standing-connect path and can never replay the v9 command pair.
    private func beginProtectedR10PureHRV10InProcessCutoverIfNeeded(
        disconnectedPeripheral: CBPeripheral,
        central callbackCentral: CBCentralManager,
        standingReconnectAlreadyIssued: Bool,
        reason: String
    ) -> Bool {
        let defaults = UserDefaults.standard
        guard protectedR10CleanOwner == .pureHRV10,
              protectedR10CleanOwnerState == .fallbackPending,
              !defaults.bool(forKey: Self.protectedR10PureHRV10InProcessCutoverKey) else {
            return false
        }
        defaults.set(true, forKey: Self.protectedR10PureHRV10InProcessCutoverKey)
        defaults.set(ProtectedR10CleanOwnerState.fallbackActive.rawValue,
                     forKey: Self.protectedR10CleanOwnerStateKey)
        defaults.set(true, forKey: Self.protectedR10StreamSuppressedKey)
        defaults.set(true, forKey: Self.protectedR10RollbackKey)
        defaults.set("clean_owner_v10_pure_hr_active",
                     forKey: RadioDefaults.passiveR10Status)
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        isActivelyScanning = false
        callbackCentral.stopScan()
        disconnectedPeripheral.delegate = self
        peripheral = disconnectedPeripheral
        recordLinkAttempt(
            reason: "proof_failure_fresh_pure_hr_connection",
            peripheral: disconnectedPeripheral
        )
        markPendingKnownReconnect(reason: "proof_failure_fresh_pure_hr_connection")
        if !standingReconnectAlreadyIssued {
            issueSingleFlightConnect(
                disconnectedPeripheral,
                central: callbackCentral,
                reason: "proof_failure_fresh_pure_hr_connection"
            )
        } else {
            connectedPeripheralRetainer.retain(disconnectedPeripheral)
        }
        startReconnectWatchdog(
            reason: "proof_failure_fresh_pure_hr_connection",
            peripheral: disconnectedPeripheral
        )
        recomputeConnectionStatus(reason: "event")
        AtriaDebugLog(
            "ATRIADBG protected_r10 status=v10_in_process_cutover reason=%@ action=%@",
            reason,
            standingReconnectAlreadyIssued
                ? "adopt_existing_standing_reconnect_no_duplicate"
                : "fresh_pure_hr_link_same_central_no_command_no_history"
        )
        return true
    }

    /// A user has already made the durable manual-workout commitment, so it is
    /// unacceptable to require an install/relaunch before offering strap-native
    /// steps. A pure-HR fallback cannot be changed on its inherited
    /// connection: the only safe escalation is one app-owned disconnect, then
    /// a fresh v9 central whose normal didConnect path installs the profile.
    ///
    /// This function performs no proprietary write, service discovery, or CCCD
    /// mutation. A missing physical qualification keeps pure HR in place.
    private func beginProtectedR10V8WorkoutCutoverIfNeeded(
        startedAt: Date,
        reason: String
    ) -> Bool {
        let defaults = UserDefaults.standard
        let manualWorkoutActive = AtriaPendingWorkoutIntent
            .isActiveForBLEContinuity(now: Date())
        let priorQualifiedAt = defaults.object(
            forKey: Self.protectedR10StableTransportQualifiedAtKey
        ) as? Double
        let priorCutoverLeaseAt = defaults.object(
            forKey: Self.protectedR10V8WorkoutInProcessCutoverLeaseKey
        ) as? Double
        // Deliberately NOT gated on `standardHROnlyMode`. That flag is the
        // user/radio configuration; what actually matters here is whether the
        // protected stream is suppressed, which
        // `protectedR10V8WorkoutCutoverMayStart` already requires alongside a
        // fallback owner, a fallback state, an active manual workout and a
        // prior qualification. A strap in `full_protocol` mode whose clean
        // owner has fallen back is exactly the case this escape hatch exists
        // for, and the extra conjunct made it unreachable precisely there.
        //
        // Observed 2026-07-25 on a counted 660-step walk: every may-start
        // condition held — streamSuppressed=true, cleanOwner=pure_hr_v10,
        // state=fallback_active, stableTransportQualifiedAt=20:45:58 during the
        // walk, prior cutover lease from 07-23 — and `radio.standardHROnly`
        // being false alone blocked the cutover. The R10 stream never started
        // (protocol_imu_frames=2), the step ledger stayed frozen at 19:55:57,
        // and the walk recorded 0 of 660 steps.
        guard !historyOnlyProbeMode,
              !offlineHistoricalSyncInProgress,
              let peripheral,
              peripheral.state == .connected,
              Self.protectedR10V8WorkoutCutoverMayStart(
                owner: protectedR10CleanOwner,
                state: protectedR10CleanOwnerState,
                streamSuppressed: protectedR10StreamSuppressed,
                manualWorkoutActive: manualWorkoutActive,
                priorQualifiedAt: priorQualifiedAt,
                priorCutoverLeaseAt: priorCutoverLeaseAt,
                workoutStartedAt: startedAt
              ) else { return false }

        // Record before cancelling so duplicate Start/lifecycle callbacks
        // cannot create a cutover loop. The original workout intent and its
        // range gap remain durable; the next fresh v9 owner gets exactly one
        // normal launch-style proof.
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10V8WorkoutInProcessCutoverLeaseKey)
        Self.promoteFallbackToProtectedV9ForLaunch(defaults: defaults, now: Date())
        workoutMotionActivationTask?.cancel()
        workoutMotionActivationTask = nil
        workoutMotionCommandTask?.cancel()
        workoutMotionCommandTask = nil
        setWorkoutMotionStatus("r10_step_lease_requalifying_fresh_owner", at: Date())
        backgroundReconnectFence.markAppOwnedCancellation(
            peripheralID: peripheral.identifier
        )
        endBackgroundReconnectLease(reason: "motion_handshake_cutover")
        recordReconnectLeaseStage("app_cancel_r10_v8_workout_cutover", detail: reason)
        central.cancelPeripheralConnection(peripheral)
        AtriaDebugLog("ATRIADBG protected_r10 status=v8_workout_cutover_started reason=%@ workout_start=%d action=single_disconnect_then_fresh_v9_central_no_cccd_no_command_no_history",
                      reason,
                      Int(startedAt.timeIntervalSince1970.rounded()))
        return true
    }

    /// Completes the v8 manual-workout cutover only after the old pure-HR link
    /// has emitted its disconnect callback. The physical disconnect is the
    /// fresh-link boundary we need; replacing CBCentralManager here is both
    /// unnecessary and unsafe. The 2026-07-26 counted-walk attempt replaced
    /// the manager after this callback and stranded the durable workout with
    /// no owner. Reconnect the exact saved peripheral through the established
    /// manager so didConnect can install the v9 profile on a genuinely fresh
    /// link while the workout remains intact.
    private func completeProtectedR10V8WorkoutCutoverIfNeeded(
        disconnectedPeripheral: CBPeripheral,
        central callbackCentral: CBCentralManager,
        reason: String
    ) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.object(
                forKey: Self.protectedR10V8WorkoutInProcessCutoverLeaseKey
              ) != nil,
              protectedR10CleanOwner == .protectedV9,
              protectedR10CleanOwnerState == .protectedLaunchPending,
              !protectedR10StreamSuppressed else { return false }
        standardHROnlyMode = true
        standardHROnlyEnabled = true
        isActivelyScanning = false
        callbackCentral.stopScan()
        // The explicit app-owned disconnect has already provided the genuine
        // connection edge. Mark the launch-cutover permit consumed so no
        // powered-on/restoration callback can cancel this replacement link a
        // second time before its ordered profile is installed.
        defaults.set(
            true,
            forKey: Self.protectedR10ResponseEventDataConnectionCutoverKey
        )
        disconnectedPeripheral.delegate = self
        peripheral = disconnectedPeripheral
        recordLinkAttempt(
            reason: "manual_workout_fresh_v9_connection",
            peripheral: disconnectedPeripheral
        )
        markPendingKnownReconnect(reason: "manual_workout_fresh_v9_connection")
        issueSingleFlightConnect(
            disconnectedPeripheral,
            central: callbackCentral,
            reason: "manual_workout_fresh_v9_connection"
        )
        startReconnectWatchdog(
            reason: "manual_workout_fresh_v9_connection",
            peripheral: disconnectedPeripheral
        )
        recomputeConnectionStatus(reason: "event")
        AtriaDebugLog("ATRIADBG protected_r10 status=v8_workout_cutover_completed reason=%@ action=fresh_v9_link_same_central_pending_connect_no_command_no_history",
                      reason)
        return true
    }

    /// A diagnostic restoration identifier can still inherit the physical
    /// connection owned by the previous process. A single run-scoped cutover
    /// guarantees that the response/event/data CCCDs are installed only after
    /// a genuine `didConnect` edge. Repeated launch or restoration callbacks
    /// cannot disconnect the strap again for the same run ID.
    private func beginMotionHandshakeLaunchConnectionCutoverIfNeeded(
        peripheral: CBPeripheral,
        central: CBCentralManager,
        reason: String
    ) -> Bool {
        guard let diagnostic = motionHandshakeDiagnostic,
              diagnostic.useResponseEventDataProfile,
              peripheral.state == .connected else { return false }
        let key = "atria.motionHandshake.\(diagnostic.runID).connectionCutover"
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: key) else { return false }
        defaults.set(true, forKey: key)
        motionHandshakeLaunchCutoverInProgress = true
        motionHandshakeProfileCharacteristics.removeAll()
        motionHandshakeRequestedNotifyUUIDs.removeAll()
        motionHandshakeConfirmedNotifyUUIDs.removeAll()
        backgroundReconnectFence.markAppOwnedCancellation(
            peripheralID: peripheral.identifier
        )
        recordReconnectLeaseStage("app_cancel_motion_handshake_cutover", detail: reason)
        central.cancelPeripheralConnection(peripheral)
        recordMotionHandshakeEvidence(
            event: "fresh_connection_cutover",
            detail: reason
        )
        return true
    }

    /// Explicit user action: stop reconnecting to the saved strap and forget it.
    func forgetSavedStrap(reason: String) {
        let defaults = UserDefaults.standard
        defaults.removeObject(forKey: LinkDefaults.savedPeripheralUUID)
        firstUseStandardHeartRateCandidateID = nil
        workoutHistoryPreemptionSuccessorGate.retire()
        userRequestedDisconnect = true
        reconnectWatchdogTask?.cancel()
        reconnectWatchdogTask = nil
        freshScanFallbackTask?.cancel()
        freshScanFallbackTask = nil
        clearPendingKnownReconnect(reason: "forget")
        if let peripheral {
            cancelPeripheralConnection(peripheral, reason: "forget_\(reason)")
        }
        self.peripheral = nil
        central.stopScan()
        isActivelyScanning = false
        recomputeConnectionStatus(reason: "forget")
        AtriaDebugLog("ATRIADBG ble_link status=forgotten reason=%@ action=user_forget", reason)
    }

    enum ReconnectWatchdogDisposition: Equatable {
        case observeSavedStandingRequest
        case recoverUnsavedPeripheral
    }

    /// Elapsed time alone is never authority to retire a saved CoreBluetooth
    /// request. A standing `connect` is intentionally allowed to wait for hours
    /// while the strap is out of range. History completion does not grant
    /// cancellation, central rotation, or request-reissue authority.
    nonisolated static func reconnectWatchdogDisposition(
        elapsed: TimeInterval,
        hasSavedStrap: Bool,
        peripheralState: CBPeripheralState
    ) -> ReconnectWatchdogDisposition {
        _ = elapsed
        _ = peripheralState
        if hasSavedStrap {
            return .observeSavedStandingRequest
        }
        return .recoverUnsavedPeripheral
    }

    private func startReconnectWatchdog(
        reason: String,
        peripheral: CBPeripheral
    ) {
        reconnectWatchdogTask?.cancel()
        reconnectWatchdogTask = Task { @MainActor in
            try? await Task.sleep(for: .seconds(reconnectWatchdogSeconds))
            guard !Task.isCancelled else { return }
            guard self.peripheral === peripheral,
                  self.status == .connecting,
                  peripheral.state != .connected else { return }
            switch Self.reconnectWatchdogDisposition(
                elapsed: self.reconnectWatchdogSeconds,
                hasSavedStrap: self.hasSavedStrap,
                peripheralState: peripheral.state
            ) {
            case .observeSavedStandingRequest:
                AtriaDebugLog("ATRIADBG ble_link watchdog reason=%@ action=observe_pending_connect_saved_strap peripheral_state=%d",
                              reason,
                              peripheral.state.rawValue)
                return
            case .recoverUnsavedPeripheral:
                break
            }
            self.recordLinkFailure(reason: "\(reason)_watchdog", error: nil)
            self.preserveLongWearRangeLossRecovery(reason: "\(reason)_watchdog")
            self.realtimeArmed = false
            self.txCharacteristic = nil
            self.dbgTxReady = false
            self.peripheral = nil
            cancelPeripheralConnection(peripheral, reason: "\(reason)_watchdog_fresh_scan")
            AtriaDebugLog("ATRIADBG ble_link watchdog reason=%@ timeout_s=%.0f action=fresh_scan",
                  reason,
                  reconnectWatchdogSeconds)
            self.startScan(reason: "\(reason)_watchdog_recovery")
        }
    }

    private func beginBackgroundReconnectLeaseIfNeeded(
        peripheral: CBPeripheral,
        error: Error?
    ) {
        guard hasSavedStrap,
              !backgroundReconnectLeaseReissueUsed,
              let error,
              (error as NSError).domain == CBErrorDomain,
              (error as NSError).code == CBError.connectionTimeout.rawValue else { return }
        backgroundReconnectLeaseTask?.cancel()
        postReconnectStreamWatchdogTask?.cancel()
        postReconnectStreamWatchdogTask = nil
        if backgroundReconnectLease != .invalid {
            UIApplication.shared.endBackgroundTask(backgroundReconnectLease)
            backgroundReconnectLease = .invalid
        }
        backgroundReconnectLease = UIApplication.shared.beginBackgroundTask(
            withName: "Atria bounded BLE reconnect repair"
        ) { [weak self] in
            MainActor.assumeIsolated {
                self?.handleReconnectLeaseExpiry()
            }
        }
        guard backgroundReconnectLease != .invalid else {
            recordReconnectLeaseStage("away_lease_begin_invalid",
                                      detail: "remote_range_loss")
            return
        }
        recordReconnectLeaseStage("away_lease_begun",
                                  detail: "remote_range_loss")
        AtriaDebugLog("ATRIADBG ble_link reconnect_lease=status_active reason=remote_range_loss duration_s=%.0f action=single_watchdog_owns_pending_session_no_cancel",
                      reconnectWatchdogSeconds)
        // The reconnect watchdog is the only timeout observer. A saved standing
        // request remains installed for as long as CoreBluetooth needs; elapsed
        // time and prior history state are never cancellation authority.
        startReconnectWatchdog(
            reason: "connection_timeout_pending_session",
            peripheral: peripheral
        )
    }

    /// State-restoration relaunches run without debug launch arguments, so the
    /// rolling UserDefaults trail is the durable forensic record of which lease
    /// stages executed before the locked process suspended.
    /// Sized so a full locked-reconnect run (three 90 s cycles plus setup)
    /// survives even while a link is churning at roughly one event every five
    /// seconds — about forty minutes of the densest trail observed.
    nonisolated static let reconnectLeaseTrailByteBudget = 24_000

    private nonisolated func recordReconnectLeaseStage(_ stage: String,
                                                       detail: String) {
        let defaults = UserDefaults.standard
        let now = Date().timeIntervalSince1970
        let entry = "\(Int(now))|\(stage)|\(detail)"
        let previous = defaults.string(forKey: ReconnectLeaseDefaults.trail) ?? ""
        let combined = previous.isEmpty ? entry : previous + "\n" + entry
        // 1600 bytes held about four minutes of a churning link, which is less
        // than one locked out-of-range run: on 2026-07-25 the first two of
        // three 90 s cycles had already rotated out before the trail could be
        // pulled, making that run unreadable rather than merely failed. This
        // is the only forensic channel for a backgrounded process, so it has
        // to outlast the longest evidence window it is used to judge.
        defaults.set(String(combined.suffix(Self.reconnectLeaseTrailByteBudget)),
                     forKey: ReconnectLeaseDefaults.trail)
    }

    private func endBackgroundReconnectLease(reason: String) {
        backgroundReconnectLeaseTask?.cancel()
        backgroundReconnectLeaseTask = nil
        backgroundSoftHRRepairEscalationTask?.cancel()
        backgroundSoftHRRepairEscalationTask = nil
        postReconnectStreamWatchdogTask?.cancel()
        postReconnectStreamWatchdogTask = nil
        let task = backgroundReconnectLease
        backgroundReconnectLease = .invalid
        if task != .invalid {
            UIApplication.shared.endBackgroundTask(task)
            recordReconnectLeaseStage("lease_ended", detail: reason)
            AtriaDebugLog("ATRIADBG ble_link reconnect_lease=status_ended reason=%@", reason)
        }
    }

    /// Pure gate for holding the post-`didConnect` stream lease: only a saved
    /// strap with continuous capture wanted, outside history recovery and
    /// diagnostics, on the currently accepted connection epoch.
    nonisolated static func shouldHoldPostReconnectStreamLease(
        hasSavedStrap: Bool,
        continuousCaptureWanted: Bool,
        historyRecoveryActive: Bool,
        diagnosticActive: Bool,
        callbackAccepted: Bool
    ) -> Bool {
        hasSavedStrap
            && continuousCaptureWanted
            && !historyRecoveryActive
            && !diagnosticActive
            && callbackAccepted
    }

    /// Recovery is complete only when an accepted HR sample belongs to the
    /// current connection epoch — `did_connect` alone is never success.
    nonisolated static func acceptedHRIsFreshForConnectionEpoch(
        lastAcceptedHRAt: Date?,
        connectedAt: Date?
    ) -> Bool {
        guard let lastAcceptedHRAt, let connectedAt else { return false }
        return lastAcceptedHRAt >= connectedAt
    }

    enum PostReconnectSilentStreamRepairDisposition: Equatable {
        /// Healthy stream, stale epoch, or a state the repair must not touch.
        case standDown
        /// Still silent but the single bounded repair was already spent.
        case awaitLeaseExpiry
        /// Spend the one bounded cancel/reconnect for this gap episode.
        case reissueConnect
    }

    nonisolated static func postReconnectSilentStreamRepairDisposition(
        callbackAccepted: Bool,
        continuousCaptureWanted: Bool,
        historyRecoveryActive: Bool,
        diagnosticActive: Bool,
        freshAcceptedHR: Bool,
        repairPermitAvailable: Bool
    ) -> PostReconnectSilentStreamRepairDisposition {
        guard callbackAccepted,
              continuousCaptureWanted,
              !historyRecoveryActive,
              !diagnosticActive else { return .standDown }
        if freshAcceptedHR { return .standDown }
        return repairPermitAvailable ? .reissueConnect : .awaitLeaseExpiry
    }

    /// Holds the process runnable across the `didConnect` -> discovery ->
    /// 2A37 notify -> first accepted HR pipeline. Ending the lease at
    /// `did_connect` is exactly the proven locked failure: none of the
    /// pipeline callbacks are wake-class events, so a single suspension
    /// strands a connected-but-silent link.
    private func beginPostReconnectStreamLeaseIfNeeded(
        peripheral: CBPeripheral,
        callbackEpoch: UInt64,
        reason: String
    ) {
        let historyRecoveryActive = historyOnlyProbeMode
            || historyTransportPhaseFence.snapshot().isActive
            || offlineHistoricalSyncInProgress
        guard Self.shouldHoldPostReconnectStreamLease(
            hasSavedStrap: hasSavedStrap,
            continuousCaptureWanted: heartRateCaptureIntent.snapshot(),
            historyRecoveryActive: historyRecoveryActive,
            diagnosticActive: motionHandshakeDiagnostic != nil,
            callbackAccepted: acceptsBLECallback(
                epoch: callbackEpoch,
                peripheral: peripheral
            )
        ) else {
            recordReconnectLeaseStage("stream_lease_not_needed", detail: reason)
            endBackgroundReconnectLease(reason: "post_connect_lease_not_needed")
            return
        }
        backgroundReconnectLeaseTask?.cancel()
        backgroundReconnectLeaseTask = nil
        postReconnectStreamWatchdogTask?.cancel()
        // A reissue keeps the original UIKit assertion alive across its
        // cancel/reconnect so the replacement connection reuses the remaining
        // budget; only begin a fresh assertion when none is held.
        if backgroundReconnectLease == .invalid {
            backgroundReconnectLease = UIApplication.shared.beginBackgroundTask(
                withName: "Atria post-reconnect HR stream repair"
            ) { [weak self] in
                MainActor.assumeIsolated {
                    self?.handleReconnectLeaseExpiry()
                }
            }
        }
        recordReconnectLeaseStage(
            backgroundReconnectLease == .invalid
                ? "stream_lease_begin_invalid"
                : "stream_lease_begun",
            detail: reason
        )
        AtriaDebugLog("ATRIADBG ble_link reconnect_lease=status_stream_active reason=%@ watchdog_s=%.0f action=hold_until_fresh_accepted_hr",
                      reason,
                      postReconnectStreamWatchdogSeconds)
        postReconnectStreamWatchdogTask = Task { @MainActor [weak self, weak peripheral] in
            // A single 12 s shot used to be the only scheduled trigger, and
            // every exit from it was silent. Observed 2026-07-24 22:17:33Z:
            // `stream_lease_begun` followed by 14 MINUTES with no `repair_*`
            // stage, no expiry, and a connected-but-silent link — the app sat
            // on "Connecting" and never attempted its own documented escape.
            // Re-evaluate on a bounded schedule so one missed or suspended
            // tick cannot strand the epoch. This cannot churn the radio: the
            // disposition only returns `.reissueConnect` while a repair permit
            // remains (budget 2 per epoch), and returns `.awaitLeaseExpiry`
            // once spent, so at most two radio actions occur per epoch no
            // matter how many times this loop evaluates.
            for tick in 0..<Self.postReconnectStreamWatchdogMaxTicks {
                try? await Task.sleep(
                    for: .seconds(self?.postReconnectStreamWatchdogSeconds ?? 12)
                )
                guard let self else { return }
                guard !Task.isCancelled else {
                    // Cancellation is the NORMAL success path: fresh accepted
                    // HR ends the lease and cancels this task, and a new epoch
                    // cancels it too. `try? await Task.sleep` swallows the
                    // cancellation, so this continuation resumes afterwards
                    // and would stamp `watchdog_exit_cancelled` on top of
                    // `lease_ended|fresh_accepted_hr` — making a successful
                    // reconnect read, in the very breadcrumb channel used to
                    // validate 0c1fcffd, exactly like the failure being
                    // investigated. Only record when no fresh HR arrived.
                    if !Self.acceptedHRIsFreshForConnectionEpoch(
                        lastAcceptedHRAt: self.lastAcceptedHRAt,
                        connectedAt: self.connectedAt
                    ) {
                        self.recordReconnectLeaseStage(
                            "watchdog_exit_cancelled",
                            detail: "tick=\(tick) no_repair_attempted"
                        )
                    }
                    return
                }
                // The captured reference is weak, so ARC can release it while
                // the epoch is still live — observed 2026-07-24 22:44:44Z,
                // which stranded a connected-but-silent link with no repair
                // and nothing left to re-arm it. The manager's own peripheral
                // is the authoritative reference for the current epoch; only
                // give up when it too is gone.
                guard let livePeripheral = peripheral ?? self.peripheral else {
                    // Observing only was tried and is wrong. `lease_ended` from
                    // the expiry handler is the standing connect's owner of
                    // last resort, but UIKit only fires expiration handlers for
                    // a BACKGROUNDED app — observed 2026-07-25: every
                    // `expiry_fired` in the trail sits in a background era,
                    // while the foreground strandings at 16:31:13 and 16:34:15
                    // produced no expiry at all and the app sat connected and
                    // silent (accepted samples frozen at 864839 across two
                    // pulls 57 s apart, raw age 221.7 s -> 278.3 s). In the
                    // foreground this `return` is the only exit, so nothing
                    // whatsoever re-arms the epoch.
                    //
                    // What must NOT come back is the reverted repair:
                    // `reconnectToSavedPeripheralIfPossible` re-runs
                    // `discoverServices` on an already-connected peripheral,
                    // and calling it every cycle churned a live link. So route
                    // the resolved strap through the audited terminal
                    // insurance instead — it is gated per peripheral state,
                    // only ever issues a passive `central.connect` on
                    // `.disconnected`, and records a breadcrumb for the other
                    // three states. No `discoverServices`, no scan, and at most
                    // one radio action because this exits the loop.
                    let resolution = Self.leaseExpiryShouldResolveSavedPeripheral(
                        hasLivePeripheral: false,
                        hasSavedStrap: self.hasSavedStrap,
                        continuousCaptureWanted: self.heartRateCaptureIntent.snapshot(),
                        historyRecoveryActive: self.historyOnlyProbeMode
                            || self.historyTransportPhaseFence.snapshot().isActive
                            || self.offlineHistoricalSyncInProgress
                    ) ? self.resolveSavedPeripheralForStandingConnect() : nil
                    self.recordReconnectLeaseStage(
                        "watchdog_exit_peripheral_released",
                        detail: "tick=\(tick) resolved=\(resolution?.breadcrumb ?? "not_wanted")"
                    )
                    // Same not-ready case the expiry handler defers on: a fresh
                    // central has no retrievable peripherals yet, and treating
                    // that as "no strap" is what ends an era in dormancy.
                    if case .centralNotReady = resolution {
                        self.bleCallbackEpochFence.markAwaitingPowerOn(
                            standingConnect: true
                        )
                    }
                    if let resolved = resolution?.peripheral {
                        self.ensureStandingConnectAtLeaseExpiryIfNeeded(
                            peripheral: resolved
                        )
                    }
                    return
                }
                if peripheral == nil {
                    self.recordReconnectLeaseStage(
                        "watchdog_peripheral_recovered_from_manager",
                        detail: "tick=\(tick)"
                    )
                }
                // Fresh accepted HR is the success terminal; stop evaluating.
                if Self.acceptedHRIsFreshForConnectionEpoch(
                    lastAcceptedHRAt: self.lastAcceptedHRAt,
                    connectedAt: self.connectedAt
                ) {
                    return
                }
                self.runPostReconnectSilentStreamRepairIfNeeded(
                    peripheral: livePeripheral,
                    callbackEpoch: callbackEpoch,
                    trigger: tick == 0 ? "watchdog" : "watchdog_tick_\(tick)"
                )
            }
        }
    }

    /// Lease expiry is the last guaranteed execution moment before
    /// suspension; delayed tasks may never run again (2026-07-24 cycle-2: the
    /// +12s watchdog died suspended and a zombie `connected` link produced no
    /// further wake events, regardless of which lease created the assertion).
    /// UIKit calls expiration handlers on the main thread, so the bounded
    /// repair runs synchronously against the LIVE epoch — captured epochs can
    /// be stale when the assertion outlives the connection that armed it.
    /// Whether expiry must fall back to the saved strap because the manager's
    /// own `peripheral` reference is gone. A missing reference is not evidence
    /// that the strap is gone — ARC releases it while the strap is still
    /// reachable — so standing down on it produces exactly the dormancy the
    /// terminal insurance exists to prevent. Pure so the observed stranding is
    /// covered without a live central.
    nonisolated static func leaseExpiryShouldResolveSavedPeripheral(
        hasLivePeripheral: Bool,
        hasSavedStrap: Bool,
        continuousCaptureWanted: Bool,
        historyRecoveryActive: Bool
    ) -> Bool {
        guard !hasLivePeripheral else { return false }
        return hasSavedStrap && continuousCaptureWanted && !historyRecoveryActive
    }

    /// The saved strap as Core Bluetooth still knows it. `retrievePeripherals`
    /// is a pure lookup against the central's cache: it starts no scan, issues
    /// no connect, and does not touch a live link, so resolving here cannot
    /// repeat the churn reverted in ee035304.
    /// Why a standing-connect resolution failed. `retrievePeripherals` returns
    /// an empty array whenever the central has not reached `.poweredOn`, so a
    /// bare optional conflates "there is no strap to reconnect to" with "ask
    /// again in a moment" — and only the first of those justifies standing
    /// down. Observed 2026-07-25T21:41:10+05:30: `expiry_fired
    /// peripheral_state=-1 resolved_state=-1` ended the lease with nothing
    /// armed and the app sat dormant for 76 minutes, losing every heart-rate
    /// sample of a 33-minute strength block and a 19-minute walk.
    enum StandingConnectResolution {
        case resolved(CBPeripheral)
        case noSavedStrap
        /// The central is not ready. Retry when it powers on; never stand down.
        case centralNotReady
        /// Powered on, saved identifier present, and iOS still returned
        /// nothing — unpaired, or genuinely unknown to this central.
        case retrieveEmpty

        var peripheral: CBPeripheral? {
            if case .resolved(let peripheral) = self { return peripheral }
            return nil
        }

        /// Terse breadcrumb token; the trail is the only forensics on a locked
        /// phone, and `-1` for all three causes is what made the gym failure
        /// take a full session to attribute.
        var breadcrumb: String {
            switch self {
            case .resolved(let peripheral): return "state_\(peripheral.state.rawValue)"
            case .noSavedStrap: return "no_saved_strap"
            case .centralNotReady: return "central_not_ready"
            case .retrieveEmpty: return "retrieve_empty"
            }
        }
    }

    private func resolveSavedPeripheralForStandingConnect() -> StandingConnectResolution {
        guard let uuidString = UserDefaults.standard
                .string(forKey: LinkDefaults.savedPeripheralUUID),
              let uuid = UUID(uuidString: uuidString) else { return .noSavedStrap }
        // A fresh central starts `.unknown` and reaches `.poweredOn`
        // asynchronously. The workout cutover deliberately builds one
        // (`single_disconnect_then_fresh_v9_central`), so this window is
        // reachable in normal use, not just at launch.
        guard central.state == .poweredOn else { return .centralNotReady }
        guard let saved = central.retrievePeripherals(withIdentifiers: [uuid]).first else {
            return .retrieveEmpty
        }
        return .resolved(saved)
    }

    private func savedPeripheralForStandingConnect() -> CBPeripheral? {
        resolveSavedPeripheralForStandingConnect().peripheral
    }

    private func handleReconnectLeaseExpiry() {
        // `peripheral` is nil far more often than the terminal insurance below
        // assumed. Observed 2026-07-25T15:52:42+05:30: `expiry_fired
        // peripheral_state=-1` skipped this whole block, the lease ended, and
        // the process sat with no live stream AND no pending connect — the
        // exact state this handler exists to prevent. The same hour produced
        // four `watchdog_exit_peripheral_released` strandings and raw sample
        // gaps of 2-4 minutes each. Resolve the saved strap so the standing
        // connect still gets armed; it is gated on `.disconnected`, so no
        // `discoverServices` runs against a live link.
        let wantsStandingConnect = Self.leaseExpiryShouldResolveSavedPeripheral(
            hasLivePeripheral: peripheral != nil,
            hasSavedStrap: hasSavedStrap,
            continuousCaptureWanted: heartRateCaptureIntent.snapshot(),
            historyRecoveryActive: historyOnlyProbeMode
                || historyTransportPhaseFence.snapshot().isActive
                || offlineHistoricalSyncInProgress
        )
        let resolution: StandingConnectResolution? = wantsStandingConnect
            ? resolveSavedPeripheralForStandingConnect()
            : nil
        let resolved = peripheral ?? resolution?.peripheral
        recordReconnectLeaseStage(
            "expiry_fired",
            detail: "peripheral_state=\(peripheral?.state.rawValue ?? -1)"
                + " resolved=\(resolution?.breadcrumb ?? "live_peripheral")"
        )
        // `.centralNotReady` is the case that cost a whole gym session: a fresh
        // central (the workout cutover builds one) has not powered on yet, so
        // `retrievePeripherals` is empty through no fault of the strap. Standing
        // down there is what produced 76 minutes of dormancy. Re-arm instead —
        // `centralManagerDidUpdateState` already retrieves the saved identifier
        // and connects the moment it reaches `.poweredOn`, so the only thing
        // needed is to not end this era believing there is nothing to wait for.
        if case .centralNotReady = resolution {
            bleCallbackEpochFence.markAwaitingPowerOn(standingConnect: true)
            AtriaDebugLog("ATRIADBG ble_link status=standing_connect_deferred reason=central_not_ready action=await_powered_on")
        }
        if let resolved {
            // Only the epoch we still own may be repaired; a resolved-only
            // strap has no accepted callback epoch to repair against, and
            // `ensureStandingConnect…` is the whole point of resolving it.
            if peripheral != nil {
                runPostReconnectSilentStreamRepairIfNeeded(
                    peripheral: resolved,
                    callbackEpoch: bleCallbackEpochFence.epoch,
                    trigger: "lease_expiry"
                )
            }
            ensureStandingConnectAtLeaseExpiryIfNeeded(peripheral: resolved)
        }
        endBackgroundReconnectLease(reason: "expired")
    }

    /// Terminal insurance at the last guaranteed runtime moment: never let
    /// the locked process go dormant with no live stream AND no pending
    /// connect. A standing connect is passive, loop-free, and the only
    /// primitive that survives suspension and jetsam (2026-07-24 cycle-3:
    /// a stale silent epoch stood down and nothing remained armed, so the
    /// strap's true return could never wake the app).
    private func ensureStandingConnectAtLeaseExpiryIfNeeded(
        peripheral: CBPeripheral
    ) {
        guard hasSavedStrap,
              heartRateCaptureIntent.snapshot(),
              !historyOnlyProbeMode,
              !historyTransportPhaseFence.snapshot().isActive,
              !offlineHistoricalSyncInProgress,
              motionHandshakeDiagnostic == nil,
              // A nil reference is the resolved-saved-strap case, which is
              // precisely what this insurance now exists to cover; requiring
              // identity equality against nil is what let the process go
              // dormant on 2026-07-25.
              self.peripheral == nil
                  || self.peripheral?.identifier == peripheral.identifier,
              !Self.acceptedHRIsFreshForConnectionEpoch(
                  lastAcceptedHRAt: lastAcceptedHRAt,
                  connectedAt: connectedAt
              ) else { return }
        switch peripheral.state {
        case .disconnected:
            recordReconnectLeaseStage("expiry_standing_connect_armed",
                                      detail: "was_disconnected")
            reconnectKnownPeripheralImmediately(
                peripheral,
                reason: "lease_expiry_standing_connect"
            )
        case .disconnecting:
            // The imminent didDisconnect runs the synchronous
            // standing-reconnect fast lane in its own wake slice.
            recordReconnectLeaseStage("expiry_awaiting_disconnect_fast_lane",
                                      detail: "was_disconnecting")
        case .connecting:
            recordReconnectLeaseStage("expiry_pending_connect_already_armed",
                                      detail: "was_connecting")
        case .connected:
            // Silent but nominally connected with the repair budget already
            // spent (a permitted repair would have cancelled above). Another
            // cancel here would recur at every lease era and churn the link
            // for legitimately silent straps (off-wrist/charging), so record
            // and accept dormancy — the budget already allowed two cancels.
            recordReconnectLeaseStage("expiry_connected_silent_no_budget",
                                      detail: "repairs_spent=\(postReconnectSilentStreamRepairsSpent)")
        @unknown default:
            recordReconnectLeaseStage("expiry_unknown_peripheral_state",
                                      detail: "raw=\(peripheral.state.rawValue)")
        }
    }

    private func runPostReconnectSilentStreamRepairIfNeeded(
        peripheral: CBPeripheral,
        callbackEpoch: UInt64,
        trigger: String
    ) {
        let epochOwned = bleCallbackEpochFence.owns(
            callbackEpoch: callbackEpoch,
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral)
        )
        guard epochOwned else {
            // A newer connection epoch owns recovery now; queued watchdog work
            // from the old link must not touch its peripheral.
            recordReconnectLeaseStage(
                "repair_skipped_stale_epoch",
                detail: "\(trigger) peripheral_state=\(peripheral.state.rawValue)"
            )
            return
        }
        if peripheral.state != .connected {
            // CoreBluetooth can apply our bounded cancel to the peripheral
            // object but swallow didDisconnect. In that observed state the
            // old `acceptsBLECallback` guard called the work stale solely
            // because the object was no longer `.connected`, so no standing
            // reconnect was ever armed. Epoch ownership is still intact:
            // reuse the audited terminal insurance, which connects only from
            // `.disconnected` and merely observes `.disconnecting`/
            // `.connecting`.
            recordReconnectLeaseStage(
                "repair_epoch_owned_not_connected",
                detail: "\(trigger) peripheral_state=\(peripheral.state.rawValue)"
            )
            ensureStandingConnectAtLeaseExpiryIfNeeded(peripheral: peripheral)
            return
        }
        let callbackAccepted = acceptsBLECallback(
            epoch: callbackEpoch,
            peripheral: peripheral
        )
        guard callbackAccepted else {
            // The epoch tuple was coherent above, but a connection transition
            // raced this second snapshot. The next bounded watchdog tick or
            // terminal callback owns the follow-up.
            recordReconnectLeaseStage(
                "repair_deferred_connection_transition",
                detail: "\(trigger) peripheral_state=\(peripheral.state.rawValue)"
            )
            return
        }
        let historyRecoveryActive = historyOnlyProbeMode
            || historyTransportPhaseFence.snapshot().isActive
            || offlineHistoricalSyncInProgress
        let freshAcceptedHR = Self.acceptedHRIsFreshForConnectionEpoch(
            lastAcceptedHRAt: lastAcceptedHRAt,
            connectedAt: connectedAt
        )
        let disposition = Self.postReconnectSilentStreamRepairDisposition(
            callbackAccepted: callbackAccepted,
            continuousCaptureWanted: heartRateCaptureIntent.snapshot(),
            historyRecoveryActive: historyRecoveryActive,
            diagnosticActive: motionHandshakeDiagnostic != nil,
            freshAcceptedHR: freshAcceptedHR,
            repairPermitAvailable: postReconnectSilentStreamRepairsSpent
                < Self.postReconnectSilentStreamRepairBudget
        )
        recordReconnectLeaseStage(
            "repair_\(disposition)",
            detail: "\(trigger) fresh=\(freshAcceptedHR ? 1 : 0) spent=\(postReconnectSilentStreamRepairsSpent)"
        )
        switch disposition {
        case .standDown:
            endBackgroundReconnectLease(reason: freshAcceptedHR
                ? "fresh_accepted_hr_watchdog"
                : "post_connect_repair_stand_down")
        case .awaitLeaseExpiry:
            // Permit spent, stream still silent: no further radio action.
            // The lease deliberately runs out its remaining iOS-bounded
            // budget so a slow second pipeline can still land; it ends via
            // fresh accepted HR, the expiry handler, or a lifecycle event.
            AtriaDebugLog("ATRIADBG ble_link post_connect_repair=exhausted reason=silent_stream_no_permit action=await_lease_expiry")
        case .reissueConnect:
            postReconnectSilentStreamRepairsSpent += 1
            // Stamped before any radio action so the epoch this repair is
            // about to create cannot refill the permit it just spent.
            lastSilentStreamRepairSpentAt = Date()
            if postReconnectSilentStreamRepairsSpent
                >= Self.postReconnectSilentStreamRepairBudget {
                // Second (final) slot: the first cancel provably changed
                // nothing — the link still reads `connected` and silent, the
                // signature of a wedged bluetoothd session that swallows
                // commands and callbacks (2026-07-24 v4 cycle-2: cancel
                // produced no didDisconnect at all). The only in-process
                // escape is a fresh CBCentralManager, whose poweredOn
                // callback re-enters the ordinary launch standing-connect
                // path for the saved strap.
                rebuildCentralForWedgedSessionOnce(trigger: trigger)
                return
            }
            let discoveryObserved = serviceDiscoveryCallbackObservedForConnection
            AtriaDebugLog("ATRIADBG ble_link post_connect_repair=action_reissue trigger=%@ reason=silent_stream_no_fresh_hr discovery_observed=%d peripheral_state=%d action=single_cancel_then_synchronous_standing_reconnect",
                          trigger,
                          discoveryObserved ? 1 : 0,
                          peripheral.state.rawValue)
            // Deliberately NOT marked app-owned: the didDisconnect this cancel
            // produces is a wake-class callback whose fast lane installs the
            // standing connect synchronously inside the delegate slice. That
            // pending connect is the only re-arm that survives suspension and
            // process death (2026-07-24 cycle-2 zombie link: every delayed
            // Task died suspended; only a standing connect can wake Atria on
            // the strap's return).
            central.cancelPeripheralConnection(peripheral)
        }
    }

    /// A wedged bluetoothd session reports `connected` while swallowing every
    /// command and delivering no callbacks — cancels void, discovery never
    /// answers, and no wake event can ever arrive. The only in-process escape
    /// is a fresh CBCentralManager (a new XPC session): its poweredOn
    /// callback synchronously re-enters the ordinary saved-strap
    /// standing-connect path, which survives suspension and process death.
    /// Bounded to the final repair-budget slot of a gap episode; the budget
    /// refills only on fresh accepted HR. Mirrors the proven in-process
    /// central swap used by the v10 clean-owner cutover.
    private func rebuildCentralForWedgedSessionOnce(
        trigger: String,
        centralUnavailableRecoveryAttempt: Bool = false
    ) {
        recordReconnectLeaseStage("repair_central_rebuild", detail: trigger)
        // A replacement is a new CoreBluetooth-state episode even when both
        // managers report the same raw unavailable value. Retire A's timer and
        // observation before B can callback; otherwise B sees the non-nil A
        // task, declines to schedule, and A's stale token later exits without
        // leaving any recovery path for B.
        centralUnavailableRecoveryScheduleGeneration &+= 1
        centralUnavailableRecoveryTask?.cancel()
        centralUnavailableRecoveryTask = nil
        centralUnavailableObservedState = nil
        centralUnavailableObservedAt = nil
        // `CBCentralManager` reaches `.poweredOn` asynchronously. The
        // 2026-07-26 locked soak proved that constructing the replacement in a
        // background maintenance slice and then returning is insufficient:
        // iOS suspended Atria before the powered-on callback, so no saved-strap
        // standing connect was installed and HR remained stale for 402 s.
        //
        // Hold one UIKit execution assertion across replacement -> poweredOn
        // -> standing connect -> didConnect -> first accepted HR. The existing
        // post-reconnect path reuses this assertion and only a fresh accepted
        // HR ends it; the expiration handler remains the bounded terminal
        // insurance if iOS revokes the assertion first.
        _ = rotateSilentStreamRecoveryExecutionLeaseIfNeeded(trigger: trigger)
        let defaults = UserDefaults.standard
        let retiredCentral = central!
        let baseRestoreIdentifier = installedCentralBaseIdentifier.isEmpty
            ? baseCentralRestoreIdentifier
            : installedCentralBaseIdentifier
        let currentRestoreIdentifier = installedCentralRestoreIdentifier.isEmpty
            ? centralRestoreIdentifier
            : installedCentralRestoreIdentifier
        let replacementRestoreIdentifier =
            motionHandshakeDiagnostic == nil
                ? Self.nextCentralRecoveryRestoreIdentifier(
                    baseIdentifier: baseRestoreIdentifier,
                    currentIdentifier: currentRestoreIdentifier
                )
                : baseRestoreIdentifier
        // The replacement identifier is computed here, but it is NOT published to
        // the restore-slot dictionary yet: doing so before the old central
        // finishes draining is the 2026-08-10 write-ahead crash-consistency bug.
        // Persistence is deferred to the post-drain/pre-construction commit point
        // below, after `centralEventFence.retire`.
        defaults.set(defaults.integer(forKey: KeepaliveDefaults.stallReconnects) + 1,
                     forKey: KeepaliveDefaults.stallReconnects)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: KeepaliveDefaults.lastStallReconnectAt)
        AtriaDebugLog("ATRIADBG ble_link post_connect_repair=action_central_rebuild trigger=%@ reason=wedged_session_cancel_voided action=fresh_central_then_launch_standing_connect",
                      trigger)
        // Fence the exact retired central before any epoch, peripheral, marker
        // or delegate mutation. Queued callbacks from it can no longer consume
        // the replacement's power-on markers or alter its connection state.
        centralEventFence.retire(
            retiredCentral,
            afterDraining: centralDelegateQueue,
            synchronizedTeardown: {
                bleCallbackEpochFence.invalidate()
            }
        )
        peripheral?.delegate = nil
        peripheral = nil
        // The central being discarded owns these peripherals; they cannot be
        // reconnected through its replacement, so holding them would only keep
        // dead objects alive.
        connectedPeripheralRetainer.releaseEverything()
        heartRateCharacteristic = nil
        txCharacteristic = nil
        dbgTxReady = false
        realtimeArmed = false
        isActivelyScanning = false
        retiredCentral.delegate = nil
        // Crash-consistent restore-slot handoff. Publish the replacement owner
        // only now — after the old central has drained its delegate lane, been
        // retired, and had its peripheral epoch invalidated by the drain above —
        // and still before the replacement central is constructed. A process
        // death before the drain must relaunch into the old slot, because the
        // surviving CoreBluetooth session still belongs to it; a death after the
        // drain but before/during construction must relaunch into the new slot.
        // Persisting earlier (the 2026-08-10 failure) let an interrupted swap
        // relaunch into a namespace CoreBluetooth had not yet handed over,
        // leaving bluetoothd two sessions for one strap and reaping HR CCCD
        // handle 0x002b out from under the canonical owner.
        if motionHandshakeDiagnostic == nil {
            persistCentralRecoveryRestoreIdentifier(
                replacementRestoreIdentifier,
                baseIdentifier: baseRestoreIdentifier,
                defaults: defaults
            )
            // A silent-link repair has not yet spent the separate unavailable-
            // central fallback. The real Build 4 failure was A -> B for a
            // silent link, followed by B reporting impossible `.unsupported`;
            // marking that first swap as the unavailable one-shot strands B
            // forever. Only a rebuild actually admitted by the unavailable-
            // state timer consumes the persisted one-shot. Its replacement
            // then cannot flip A/B again across force launches until an exact
            // current `.poweredOn` callback clears this bit. This pending-bit
            // write commits in the same post-drain/pre-construction window as
            // the restore-slot persistence above.
            if centralUnavailableRecoveryAttempt {
                setCentralRecoveryPending(
                    true,
                    baseIdentifier: baseRestoreIdentifier,
                    defaults: defaults
                )
            }
        }
        let delegateQueue = centralDelegateQueue
        delegateQueue?.suspend()
        central = CBCentralManager(delegate: self,
                                   queue: delegateQueue,
                                   options: [
                                       CBCentralManagerOptionRestoreIdentifierKey:
                                           replacementRestoreIdentifier,
                                       // The initial manager already owns the
                                       // system prompt. A transparent one-shot
                                       // session repair must not show it again.
                                       CBCentralManagerOptionShowPowerAlertKey: false
                                   ])
        let replacementToken = centralEventFence.install(central)
        installedCentralBaseIdentifier = baseRestoreIdentifier
        installedCentralRestoreIdentifier = replacementRestoreIdentifier
        // Marker ownership is the replacement generation itself. An old
        // admitted callback cannot consume this even if it was already running
        // when its central was retired.
        centralEventFence.markAwaitingPowerOn(
            token: replacementToken,
            standingConnect: true,
            silentStreamRebuild: true
        )
        delegateQueue?.resume()
        recomputeConnectionStatus(reason: "event")
    }

    private func reconcileCentralUnavailableRecovery(
        state: CBManagerState,
        callbackCentral: CBCentralManager,
        callbackToken: AtriaBLECentralEventFence.Token
    ) {
        if state == .poweredOn {
            centralUnavailableRecoveryScheduleGeneration &+= 1
            centralUnavailableRecoveryTask?.cancel()
            centralUnavailableRecoveryTask = nil
            centralUnavailableObservedState = nil
            centralUnavailableObservedAt = nil
            centralUnavailableRecoveryAttempts = 0
            if motionHandshakeDiagnostic == nil {
                setCentralRecoveryPending(
                    false,
                    baseIdentifier: activeCentralBaseIdentifier
                )
            }
            return
        }
        if state == .unauthorized {
            centralUnavailableRecoveryScheduleGeneration &+= 1
            centralUnavailableRecoveryTask?.cancel()
            centralUnavailableRecoveryTask = nil
            centralUnavailableObservedState = state
            centralUnavailableObservedAt = Date()
            return
        }

        let now = Date()
        if centralUnavailableObservedState != state {
            centralUnavailableObservedState = state
            centralUnavailableObservedAt = now
        }

        #if targetEnvironment(simulator)
        let runningOnSimulator = true
        #else
        let runningOnSimulator = false
        #endif
        let plan = Self.centralUnavailableRecoveryPlan(
            state: state,
            bluetoothAuthorizationAllowed:
                CBManager.authorization == .allowedAlways,
            applicationMayInteract:
                UIApplication.shared.applicationState == .active,
            runningOnSimulator: runningOnSimulator,
            hasPriorSuccessfulConnection:
                UserDefaults.standard.integer(
                    forKey: LinkDefaults.successes
                ) > 0,
            recoveryAlreadyPending: centralRecoveryIsPending(
                baseIdentifier: activeCentralBaseIdentifier
            )
        )
        guard case .rebuild(after: let delay) = plan else {
            centralUnavailableRecoveryScheduleGeneration &+= 1
            centralUnavailableRecoveryTask?.cancel()
            centralUnavailableRecoveryTask = nil
            return
        }
        if centralUnavailableRecoveryTask != nil,
           centralUnavailableObservedState == state {
            return
        }
        centralUnavailableRecoveryScheduleGeneration &+= 1
        let scheduleGeneration =
            centralUnavailableRecoveryScheduleGeneration
        centralUnavailableRecoveryTask?.cancel()
        let observedAt = centralUnavailableObservedAt ?? now
        centralUnavailableObservedAt = observedAt
        let remainingDelay = Self
            .centralUnavailableRecoveryRemainingDelay(
                observedAt: observedAt,
                now: now,
                threshold: delay
        )
        let expectedAttempt = centralUnavailableRecoveryAttempts
        centralUnavailableRecoveryTask = Task { @MainActor [weak self, weak callbackCentral] in
            try? await Task.sleep(for: .seconds(remainingDelay))
            guard let self,
                  let callbackCentral,
                  self.centralUnavailableRecoveryScheduleGeneration
                    == scheduleGeneration else { return }
            self.centralUnavailableRecoveryTask = nil
            guard
                  !Task.isCancelled,
                  self.centralUnavailableRecoveryAttempts == expectedAttempt,
                  self.centralUnavailableObservedState == state,
                  self.centralEventFence.accepts(
                    callbackToken,
                    central: callbackCentral
                  ),
                  callbackCentral.state == state,
                  CBManager.authorization == .allowedAlways,
                  UIApplication.shared.applicationState == .active,
                  !self.centralRecoveryIsPending(
                    baseIdentifier: self.activeCentralBaseIdentifier
                  ) else { return }
            self.centralUnavailableRecoveryAttempts += 1
            UserDefaults.standard.set(
                Date().timeIntervalSince1970,
                forKey: "atria.ble.centralRecovery.lastAttemptAt"
            )
            UserDefaults.standard.set(
                state.rawValue,
                forKey: "atria.ble.centralRecovery.lastObservedState"
            )
            UserDefaults.standard.set(
                self.centralUnavailableRecoveryAttempts,
                forKey: "atria.ble.centralRecovery.attempts"
            )
            self.recordReconnectLeaseStage(
                "central_unavailable_rebuild",
                detail: "state_\(state.rawValue)_attempt_\(self.centralUnavailableRecoveryAttempts)"
            )
            self.rebuildCentralForWedgedSessionOnce(
                trigger: "central_state_\(state.rawValue)_wedge",
                centralUnavailableRecoveryAttempt: true
            )
        }
    }

    private func resumeCentralUnavailableRecoveryIfNeeded() {
        guard let callbackToken = centralEventFence.capture(central) else {
            return
        }
        reconcileCentralUnavailableRecovery(
            state: central.state,
            callbackCentral: central,
            callbackToken: callbackToken
        )
    }

    @discardableResult
    private func rotateSilentStreamRecoveryExecutionLeaseIfNeeded(
        trigger: String
    ) -> Bool {
        guard UIApplication.shared.applicationState != .active else {
            recordReconnectLeaseStage("silent_stream_lease_not_needed",
                                      detail: "\(trigger) app_active")
            return false
        }
        // A non-invalid identifier is not evidence that UIKit still grants
        // execution. The failed soak retained an 80-minute-old lease ID with
        // no expiry breadcrumb. A one-shot central replacement always rotates
        // it to a fresh assertion rather than trusting stale in-memory state.
        backgroundReconnectLeaseTask?.cancel()
        backgroundReconnectLeaseTask = nil
        postReconnectStreamWatchdogTask?.cancel()
        postReconnectStreamWatchdogTask = nil
        if backgroundReconnectLease != .invalid {
            let staleLease = backgroundReconnectLease
            backgroundReconnectLease = .invalid
            UIApplication.shared.endBackgroundTask(staleLease)
            recordReconnectLeaseStage("silent_stream_lease_rotated",
                                      detail: trigger)
        }
        backgroundReconnectLease = UIApplication.shared.beginBackgroundTask(
            withName: "Atria silent HR stream repair"
        ) { [weak self] in
            MainActor.assumeIsolated {
                self?.handleReconnectLeaseExpiry()
            }
        }
        recordReconnectLeaseStage(
            backgroundReconnectLease == .invalid
                ? "silent_stream_lease_begin_invalid"
                : "silent_stream_lease_begun",
            detail: trigger
        )
        return backgroundReconnectLease != .invalid
    }

    private func armBackgroundSoftHRRepairEscalationIfNeeded(
        peripheral: CBPeripheral,
        trigger: String,
        repairStartedAt: Date
    ) {
        guard UIApplication.shared.applicationState != .active,
              peripheral.state == .connected,
              backgroundSoftHRRepairEscalationTask == nil else { return }
        guard rotateSilentStreamRecoveryExecutionLeaseIfNeeded(trigger: trigger) else {
            recordReconnectLeaseStage("soft_hr_repair_escalated_immediately",
                                      detail: "\(trigger) lease_invalid")
            escalateBackgroundSoftHRRepair(peripheral: peripheral)
            return
        }
        recordReconnectLeaseStage("soft_hr_repair_escalation_armed",
                                  detail: trigger)
        backgroundSoftHRRepairEscalationTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(12))
            guard let self, !Task.isCancelled else { return }
            let target = peripheral ?? self.peripheral
            guard let target,
                  target.state == .connected,
                  self.peripheral?.identifier == target.identifier else {
                self.backgroundSoftHRRepairEscalationTask = nil
                return
            }
            if self.lastAcceptedHRAt.map({ $0 > repairStartedAt }) == true {
                self.backgroundSoftHRRepairEscalationTask = nil
                self.recordReconnectLeaseStage("soft_hr_repair_recovered",
                                               detail: trigger)
                return
            }
            self.backgroundSoftHRRepairEscalationTask = nil
            self.recordReconnectLeaseStage("soft_hr_repair_escalated",
                                           detail: trigger)
            self.escalateBackgroundSoftHRRepair(peripheral: target)
        }
    }

    private func escalateBackgroundSoftHRRepair(peripheral: CBPeripheral) {
        persistActiveSessionJournalIfNeeded(
            reason: "hr_continuity_background_soft_repair_failed",
            force: true
        )
        if session.count < 2 {
            clearUnsavableActiveJournalIfNeeded(
                reason: "hr_continuity_background_soft_repair_unsavable"
            )
        }
        forceHardReconnectForPacketStall(
            peripheral: peripheral,
            reason: "hr_continuity_background_soft_repair_failed",
            immediateConnectedRebuild: true
        )
    }

    /// The only success terminal for a reconnect epoch: a fresh accepted HR
    /// sample. Releases the lease and restores both bounded-repair permits.
    private func completePostReconnectStreamRecoveryIfNeeded() {
        backgroundSoftHRRepairEscalationTask?.cancel()
        backgroundSoftHRRepairEscalationTask = nil
        silentStreamCentralRebuildIssued = false
        if postReconnectSilentStreamRepairsSpent > 0 || backgroundReconnectLeaseReissueUsed {
            postReconnectSilentStreamRepairsSpent = 0
            backgroundReconnectLeaseReissueUsed = false
        }
        guard backgroundReconnectLease != .invalid
                || backgroundReconnectLeaseTask != nil
                || postReconnectStreamWatchdogTask != nil
                || postReconnectHRReassertTask != nil else { return }
        postReconnectHRReassertTask?.cancel()
        postReconnectHRReassertTask = nil
        endBackgroundReconnectLease(reason: "fresh_accepted_hr")
    }

    /// CoreBluetooth can preserve a stale `isNotifying == true` bit across a
    /// range-loss reconnect even though the strap is no longer delivering
    /// 2A37. Give the new link one delayed, data-gated reassertion; a healthy
    /// stream is never toggled.
    private func schedulePostReconnectHRReassertion(
        peripheral: CBPeripheral,
        reason: String
    ) {
        postReconnectHRReassertTask?.cancel()
        postReconnectHRReassertTask = Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(6))
            guard let self, !Task.isCancelled, let peripheral,
                  self.peripheral === peripheral,
                  peripheral.state == .connected,
                  self.heartRateCaptureIntent.snapshot(),
                  !self.historyOnlyProbeMode,
                  !self.historyTransportPhaseFence.snapshot().isActive,
                  !self.offlineHistoricalSyncInProgress,
                  self.motionHandshakeDiagnostic == nil,
                  let characteristic = self.heartRateCharacteristic,
                  characteristic.properties.contains(.notify)
                    || characteristic.properties.contains(.indicate) else { return }
            let rawAge = self.lastRawHRNotificationAt.map {
                Date().timeIntervalSince($0)
            } ?? .infinity
            guard rawAge >= 4 else {
                AtriaDebugLog("ATRIADBG ble_notify_reassert status=not_needed reason=%@ raw_age_s=%.1f",
                              reason, rawAge)
                return
            }
            peripheral.setNotifyValue(true, for: characteristic)
            AtriaDebugLog("ATRIADBG ble_notify_reassert status=requested reason=%@ raw_age_s=%.1f action=post_reconnect_stale_cccd",
                          reason, rawAge)
        }
    }

    // MARK: Capture control

    private let captureCorrectionContract = "schema=2 correction=drop_300_2000_delta20_interpolate confidence=kept_over_raw"

    func toggleRecording() {
        if isRecording {
            finishRecording()
        } else {
            captureRowsFlushTask?.cancel()
            captureRowsFlushTask = nil
            let startedAt = Date()
            captureStart = startedAt
            captureCleanWindowStart = startedAt
            captureElapsedSeconds = 0
            capturedRows = 0
            assignIfChanged(\.captureSummary, "Recording a beat-to-beat heart-rate window")
            assignIfChanged(\.captureWasValidationReady, false)
            captureAbortReason = nil
            captureQualityResetCount = 0
            autoStoppedReadyCapture = false
            resetRRAvailabilityWindow(&captureRRQualityWindow, head: &captureRRQualityWindowHead)
            captureLog = ["elapsed_ms,kind,source,opcode,len,label,value"]
            lastRRBeatTime = nil
            lastRRExportElapsedMS = nil
            resetRRBuffer()
            rrSamples = 0
            hrv = 0
            assignIfChanged(\.hrvSnapshot, nil)
            tachogram.removeAll(keepingCapacity: true)
            assignIfChanged(\.hrvQuality, "waiting for beat-to-beat samples")
            assignIfChanged(\.isRecording, true)
            let startedAtUTC = ISO8601DateFormatter().string(from: captureStart)
            let context = [
                "started_at_utc=\(startedAtUTC)",
                "app_bundle=com.adidshaft.atria",
                "ios=\(metaSafe(UIDevice.current.systemVersion))",
                "model=\(metaSafe(UIDevice.current.model))",
                "strap=\(metaSafe(deviceName))",
                "label=\(metaSafe(captureLabel))",
                "strict_live_rr=\(strictLiveRRCapture ? 1 : 0)"
            ].joined(separator: " ")
            logRow(kind: "capture_meta", source: "app", opcode: "", len: "",
                   value: context)
            logRow(kind: "capture_meta", source: "app", opcode: "", len: "",
                   value: captureCorrectionContract)
            if strictLiveRRCapture {
                logRow(kind: "hrv_seed", source: "archive", opcode: "", len: "",
                       value: "skipped_strict_live_rr")
            } else {
                seedRecordingFromArchiveAsync(now: captureStart)
            }
            captureTimer?.invalidate()
            captureTimer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
                Task { @MainActor in
                    guard let self else { return }
                    let now = Date()
                    self.captureElapsedSeconds = now.timeIntervalSince(self.captureStart)
                    let cleanElapsed = now.timeIntervalSince(self.captureCleanWindowStart)
                    if self.shouldRefreshHRVSnapshot(now: now) {
                        self.requestLiveHRVSnapshotRefresh(now: now,
                                                           logKind: "hrv_timer",
                                                           shouldLogConsole: false)
                    }
                    if self.autoStopCaptureAfterSeconds > 0,
                       cleanElapsed >= self.autoStopCaptureAfterSeconds {
                        AtriaDebugLog("ATRIADBG autoCapture stop reason=timeout elapsed=%.1f clean_elapsed=%.1f",
                              self.captureElapsedSeconds, cleanElapsed)
                        self.finishRecording(stopReason: "timeout")
                    }
                }
            }
        }
    }

    private func seedRecordingFromArchiveAsync(now: Date) {
        archiveSeedTask?.cancel()
        let archive = rrArchive
        archiveSeedTask = Task { [archive, now] in
            let seed = await Task.detached(priority: .utility) {
                archive
                    .filter { now.timeIntervalSince($0.t) <= 305 }
                    .sorted { $0.t < $1.t }
            }.value
            guard !Task.isCancelled,
                  self.isRecording,
                  self.captureStart == now else { return }
            self.archiveSeedTask = nil
            guard !seed.isEmpty else { return }
            self.applyRecordingArchiveSeed(seed, now: now)
        }
    }

    private func applyRecordingArchiveSeed(_ seed: [RRInterval], now: Date) {
        let liveWindow = currentRRBufferWindow()
        rrBuffer = (seed + liveWindow).sorted { $0.t < $1.t }
        rrBufferHead = 0
        rrSamples = rrBuffer.count
        hrvGateWasOpen = true
        if let last = seed.last,
           lastRRBeatTime == nil || last.t > (lastRRBeatTime ?? .distantPast) {
            lastRRBeatTime = last.t
            let seedElapsedMS = Int((last.t.timeIntervalSince(captureStart) * 1000).rounded())
            lastRRExportElapsedMS = max(lastRRExportElapsedMS ?? seedElapsedMS, seedElapsedMS)
        }
        logRow(kind: "hrv_quality", source: "app", opcode: "", len: "",
               value: String(format: "seeded_from_archive rr=%d window_s=%.0f",
                             seed.count, now.timeIntervalSince(seed.first?.t ?? now)))
        for rr in seed {
            logRow(kind: "rr_seed", source: "archive", opcode: "RR", len: "",
                   value: String(format: "%.0f", rr.ms), at: rr.t)
        }
        requestLiveHRVSnapshotRefresh(now: now,
                                      logKind: "hrv_seed",
                                      shouldLogConsole: true)
    }

    @discardableResult
    private func refreshHRVSnapshot(now: Date,
                                    logKind: String,
                                    shouldLogConsole: Bool) -> HRVSnapshot? {
        hrvLiveRefreshGeneration &+= 1
        hrvLiveRefreshTask?.cancel()
        hrvLiveRefreshTask = nil
        recordHRVAnalysisAttempt(at: now)
        pruneRRBuffer(now: now)
        let bufferWindow = currentRRBufferWindow()
        rrSamples = bufferWindow.count
        let analyzed = HRVAnalyzer.analyze(bufferWindow,
                                           now: now,
                                           includeTachogram: shouldMaintainLiveTachogram)
        return applyHRVAnalysisResult(analyzed,
                                      now: now,
                                      logKind: logKind,
                                      shouldLogConsole: shouldLogConsole)
    }

    private func requestLiveHRVSnapshotRefresh(now: Date,
                                               logKind: String,
                                               shouldLogConsole: Bool) {
        pruneRRBuffer(now: now)
        rrSamples = currentRRBufferCount
        if hrvLiveRefreshTask != nil {
            if let pending = pendingLiveHRVRefreshRequest {
                pendingLiveHRVRefreshRequest = (now: max(pending.now, now),
                                               logKind: logKind,
                                               shouldLogConsole: pending.shouldLogConsole || shouldLogConsole)
            } else {
                pendingLiveHRVRefreshRequest = (now: now,
                                               logKind: logKind,
                                               shouldLogConsole: shouldLogConsole)
            }
            return
        }
        startLiveHRVSnapshotRefresh(now: now,
                                    logKind: logKind,
                                    shouldLogConsole: shouldLogConsole)
    }

    private func startLiveHRVSnapshotRefresh(now: Date,
                                             logKind: String,
                                             shouldLogConsole: Bool) {
        recordHRVAnalysisAttempt(at: now)
        let bufferWindow = currentRRBufferWindow()
        let includeTachogram = shouldMaintainLiveTachogram
        hrvLiveRefreshGeneration &+= 1
        let generation = hrvLiveRefreshGeneration
        hrvLiveRefreshTask = Task { [bufferWindow, now, logKind, shouldLogConsole, generation, includeTachogram] in
            let analyzed = await Task.detached(priority: .utility) {
                HRVAnalyzer.analyze(bufferWindow, now: now, includeTachogram: includeTachogram)
            }.value
            guard !Task.isCancelled, generation == self.hrvLiveRefreshGeneration else { return }
            self.hrvLiveRefreshTask = nil
            let snapshot = self.applyHRVAnalysisResult(analyzed,
                                                       now: now,
                                                       logKind: logKind,
                                                       shouldLogConsole: shouldLogConsole)
            if snapshot?.isReady == true,
               self.isRecording,
               self.autoStopCaptureWhenReady,
               !self.autoStoppedReadyCapture {
                self.autoStoppedReadyCapture = true
                AtriaDebugLog("ATRIADBG autoCapture stop reason=ready")
                self.finishRecording()
            }
            if let pending = self.pendingLiveHRVRefreshRequest {
                self.pendingLiveHRVRefreshRequest = nil
                self.startLiveHRVSnapshotRefresh(now: pending.now,
                                                 logKind: pending.logKind,
                                                 shouldLogConsole: pending.shouldLogConsole)
            }
        }
    }

    private func recordHRVAnalysisAttempt(at date: Date) {
        if isRecording {
            lastHRVAnalysisAttemptAt = date
        } else {
            lastNormalWearHRVAnalysisAttemptAt = date
            Self.persistNormalWearHRVAnalysisAttemptDate(date)
        }
    }

    @discardableResult
    private func applyHRVAnalysisResult(_ analyzed: (HRVSnapshot?, [RRSample]),
                                        now: Date,
                                        logKind: String,
                                        shouldLogConsole: Bool) -> HRVSnapshot? {
        assignIfChanged(\.hrvSnapshot, analyzed.0)
        if shouldMaintainLiveTachogram {
            tachogram = analyzed.1
        } else if !tachogram.isEmpty {
            tachogram.removeAll(keepingCapacity: true)
        }
        guard let snapshot = analyzed.0 else {
            hrv = 0
            return nil
        }

        assignIfChanged(\.hrvQuality, snapshot.readinessMessage)
        if snapshot.isReady {
            let readyAt = snapshot.analyzedAt == .distantPast ? now : snapshot.analyzedAt
            lastHRVAnalysisAt = readyAt
            latestReadyHRVSnapshot = snapshot
            let defaults = UserDefaults.standard
            defaults.set(readyAt, forKey: HRVCadenceDefaults.lastReadyAnalysisAt)
            if let encoded = Self.encodedReadyHRVSnapshot(snapshot) {
                defaults.set(encoded, forKey: HRVCadenceDefaults.readySnapshot)
            }
        }
        let metricFields: String
        if snapshot.isReady {
            let resp = snapshot.respiratoryRate.map { String(format: "%.1f", $0) } ?? "learning"
            metricFields = String(format: "rmssd=%.1f sdnn=%.1f pnn50=%.1f lnrmssd=%.2f resp=%@",
                                  snapshot.rmssd, snapshot.sdnn, snapshot.pnn50,
                                  snapshot.lnRMSSD, resp)
        } else {
            metricFields = "rmssd=learning sdnn=learning pnn50=learning lnrmssd=learning resp=learning"
        }
        logRow(kind: logKind, source: "analyzer", opcode: "", len: "",
               value: String(format: "raw=%d kept=%d rejected_out_of_range=%d rejected_delta_over_20_percent=%d rejected_hr_mismatch=%d interpolated=%d conf=%d window=%.0f max_rr_gap_s=%.1f ready=%d reason=%@ %@",
                             snapshot.raw, snapshot.kept,
                             snapshot.rejectedOutOfRange,
                             snapshot.rejectedDeltaOver20Percent,
                             snapshot.rejectedHRMismatch,
                             snapshot.interpolated,
                             snapshot.confidencePercent,
                             snapshot.windowSeconds,
                             snapshot.maxRRGapSeconds,
                             snapshot.isReady ? 1 : 0,
                             snapshot.readinessReason,
                             metricFields))
        if shouldLogConsole {
            AtriaDebugLog("ATRIADBG hrv raw=%d kept=%d rejected_out_of_range=%d rejected_delta_over_20_percent=%d rejected_hr_mismatch=%d interpolated=%d conf=%d window=%.0f max_rr_gap_s=%.1f ready=%d reason=%@ %@",
                  snapshot.raw, snapshot.kept,
                  snapshot.rejectedOutOfRange,
                  snapshot.rejectedDeltaOver20Percent,
                  snapshot.rejectedHRMismatch,
                  snapshot.interpolated,
                  snapshot.confidencePercent,
                  snapshot.windowSeconds,
                  snapshot.maxRRGapSeconds,
                  snapshot.isReady ? 1 : 0,
                  snapshot.readinessReason,
                  metricFields)
        }
        hrv = snapshot.isReady ? Int(snapshot.rmssd.rounded()) : 0
        return snapshot
    }

    private func finishRecording(stopReason: String = "manual") {
        captureTimer?.invalidate()
        captureTimer = nil
        captureRowsFlushTask?.cancel()
        captureRowsFlushTask = nil
        flushCapturedRows()
        captureElapsedSeconds = Date().timeIntervalSince(captureStart)
        let finalAbortReason = captureAbortReason
        let summary: String
        let ready: Bool
        let summaryLogValue: String
        if let h = hrvSnapshot {
            ready = h.isReady && finalAbortReason == nil
            summary = String(format: "%@ · saved %.0fs · HRV %.0fs · kept beats %d/%d · max gap %.1fs · confidence %d%% · RMSSD %@ · SDNN %@ · pNN50 %@ · ln %@ · breathing %@",
                             ready ? "Personal baseline ready" : "Still learning",
                             captureElapsedSeconds, h.windowSeconds, h.kept, h.raw,
                             h.maxRRGapSeconds,
                             h.confidencePercent,
                             ready ? String(format: "%.1f", h.rmssd) : "learning",
                             ready ? String(format: "%.1f", h.sdnn) : "learning",
                             ready ? String(format: "%.1f", h.pnn50) : "learning",
                             ready ? String(format: "%.2f", h.lnRMSSD) : "learning",
                             ready ? (h.respiratoryRate.map { String(format: "%.1f/min", $0) } ?? "learning") : "learning")
            let metricSummary: String
            if ready {
                let resp = h.respiratoryRate.map { String(format: "%.1f", $0) } ?? "learning"
                metricSummary = String(format: "rmssd=%.1f sdnn=%.1f pnn50=%.1f lnrmssd=%.2f resp=%@",
                                       h.rmssd, h.sdnn, h.pnn50, h.lnRMSSD, resp)
            } else {
                metricSummary = "rmssd=learning sdnn=learning pnn50=learning lnrmssd=learning resp=learning"
            }
            let reason = finalAbortReason ?? h.readinessReason
            let cleanElapsed = Date().timeIntervalSince(captureCleanWindowStart)
            summaryLogValue = String(format: "ready=%d stop=%@ elapsed=%.0f clean_elapsed=%.0f raw=%d kept=%d rejected_out_of_range=%d rejected_delta_over_20_percent=%d rejected_hr_mismatch=%d interpolated=%d conf=%d window=%.0f max_rr_gap_s=%.1f quality_resets=%d strict_live_rr=%d reason=%@ %@",
                                     ready ? 1 : 0, stopReason, captureElapsedSeconds, cleanElapsed,
                                     h.raw, h.kept,
                                     h.rejectedOutOfRange, h.rejectedDeltaOver20Percent,
                                     h.rejectedHRMismatch,
                                     h.interpolated, h.confidencePercent, h.windowSeconds,
                                     h.maxRRGapSeconds, captureQualityResetCount,
                                     strictLiveRRCapture ? 1 : 0,
                                     reason, metricSummary)
            logRow(kind: "capture_summary", source: "app", opcode: "", len: "",
                   value: summaryLogValue)
        } else {
            ready = false
            summary = String(format: "Still learning · saved %.0fs · waiting for beat-to-beat samples",
                             captureElapsedSeconds)
            let reason = finalAbortReason ?? "no_realtime_rr"
            let cleanElapsed = Date().timeIntervalSince(captureCleanWindowStart)
            summaryLogValue = String(format: "ready=0 stop=%@ elapsed=%.0f clean_elapsed=%.0f quality_resets=%d strict_live_rr=%d reason=%@",
                                     stopReason, captureElapsedSeconds, cleanElapsed,
                                     captureQualityResetCount, strictLiveRRCapture ? 1 : 0, reason)
            logRow(kind: "capture_summary", source: "app", opcode: "", len: "",
                   value: summaryLogValue)
        }
        AtriaDebugLog("ATRIADBG capture_summary %@", summaryLogValue)
        assignIfChanged(\.captureWasValidationReady, ready)
        if let saved = saveCaptureCSV(directory: .documentDirectory) {
            assignIfChanged(\.lastCaptureFile, saved.relativePath)
            AtriaDebugLog("ATRIADBG capture_file path=%@ rows=%d ready=%d",
                  saved.relativePath, currentCapturedRowCount, ready ? 1 : 0)
        } else {
            assignIfChanged(\.lastCaptureFile, "")
            AtriaDebugLog("ATRIADBG capture_file_error rows=%d ready=%d",
                  currentCapturedRowCount, ready ? 1 : 0)
        }
        assignIfChanged(\.captureSummary, summary)
        assignIfChanged(\.isRecording, false)
        captureAbortReason = nil
        resetRRAvailabilityWindow(&captureRRQualityWindow, head: &captureRRQualityWindowHead)
    }

    private func resetRecordingForRRQuality(reason: String,
                                            fraction: Double,
                                            rrFrames: Int,
                                            totalFrames: Int,
                                            maxGap: TimeInterval,
                                            windowSeconds: TimeInterval,
                                            now: Date,
                                            source: String,
                                            rrCount: Int) {
        guard isRecording else { return }
        captureQualityResetCount += 1
        logRow(kind: "capture_quality_reset", source: "app", opcode: "", len: "",
               value: String(format: "reason=%@ reset=%d fraction=%.3f rr_frames=%d total_frames=%d max_rr_gap_s=%.1f window_s=%.0f action=reset_hrv_keep_recording",
                             reason, captureQualityResetCount, fraction, rrFrames,
                             totalFrames, maxGap, windowSeconds))
        AtriaDebugLog("ATRIADBG capture_quality_reset reason=%@ reset=%d fraction=%.3f rr_frames=%d total_frames=%d max_rr_gap_s=%.1f window_s=%.0f action=reset_hrv_keep_recording",
              reason, captureQualityResetCount, fraction, rrFrames, totalFrames,
              maxGap, windowSeconds)
        checkpointCurrentSession(reason: "rr_quality_reset")
        resetHRVWindow(reason: "learning: RR gap reset")
        captureCleanWindowStart = now
        lastRRExportElapsedMS = nil
        resetRRAvailabilityWindow(&captureRRQualityWindow, head: &captureRRQualityWindowHead)
        captureRRQualityWindow.append((t: now, hasRR: rrCount > 0, source: source))
    }

    private func checkpointCurrentSession(reason: String) {
        if powerThermalGovernor.shouldDeferNonEssentialAnalysis {
            lastCanonicalCheckpointAt = Date()
            persistActiveSessionJournalIfNeeded(
                reason: "rr_quality_thermal_heartbeat",
                force: true,
                refreshTimestampIfUnchanged: true
            )
            AtriaDebugLog("ATRIADBG session_checkpoint status=deferred reason=%@ samples=%d rr_samples=%d source=rr_quality mode=%@",
                          reason,
                          session.count,
                          rrArchive.count,
                          effectivePowerThermalMode)
            return
        }
        guard let saved = snapshotSession(label: captureLabel.isEmpty ? "RR checkpoint" : captureLabel) else {
            AtriaDebugLog("ATRIADBG session_checkpoint status=skipped reason=%@ samples=%d rr_samples=%d source=rr_quality",
                  reason, session.count, rrArchive.count)
            return
        }
        let checkpointPersisted = onSessionCheckpoint?(saved) == true
        AtriaDebugLog("ATRIADBG session_checkpoint status=%@ reason=%@ samples=%d rr_samples=%d motion_hints=%d motion_hint_kinds=%@ motion_source=%@ motion_validated=%d hr_raw_2a37=%d hr_accepted=%d hr_zero=%d hr_artifact_held=%d hr_artifact_dropped=%d hr_raw_gaps=%d hr_accepted_gaps=%d hr_max_raw_gap_s=%.1f hr_max_accepted_gap_s=%.1f duration_s=%.0f hrv=%@ label=%@ source=rr_quality",
              checkpointPersisted ? "saved" : "store_failed",
              reason,
              saved.points.count,
              saved.rrSampleCount,
              saved.motionHintCountValue,
              saved.motionHintKindsValue,
              saved.motionEvidenceSourceValue,
              saved.motionEvidenceValidatedValue ? 1 : 0,
              saved.hrRaw2A37Value,
              saved.hrAcceptedValue,
              saved.hrZeroValue,
              saved.hrArtifactHeldValue,
              saved.hrArtifactDroppedValue,
              saved.hrRawGapsValue,
              saved.hrAcceptedGapsValue,
              saved.hrMaxRawGapValue,
              saved.hrMaxAcceptedGapValue,
              saved.duration,
              saved.hrv.map(String.init) ?? "learning",
              saved.label)
    }

    private func checkpointFromLiveEventIfNeeded(now: Date) {
        guard longWearModeEnabled else { return }
        guard session.count >= autoSaveMinSamples else { return }
        let checkpointInterval = powerThermalGovernor.shouldDeferNonEssentialAnalysis
            ? Self.thermalJournalCheckpointInterval
            : currentEventDrivenCheckpointInterval()
        guard Self.shouldRunCanonicalCheckpoint(now: now,
                                                lastCheckpointAt: lastCanonicalCheckpointAt,
                                                minimumInterval: checkpointInterval) else {
            return
        }
        if lastCanonicalCheckpointAt == nil,
           now.timeIntervalSince(sessionStart) < checkpointInterval {
            return
        }
        // Memory bounding is essential, not cosmetic: full-protocol overnight wear
        // still receives accepted HR events even when the long-wear supervisor is
        // preserving richer RR capture, so trigger the same retention roll here
        // before another full-session checkpoint snapshot.
        if rollLongWearLiveSessionIfOversized(now: now, reason: "ble_event_retention_roll") {
            lastCanonicalCheckpointAt = now
            return
        }
        if powerThermalGovernor.shouldDeferNonEssentialAnalysis {
            lastCanonicalCheckpointAt = now
            persistActiveSessionJournalIfNeeded(
                reason: "thermal_pressure_ble_event_checkpoint",
                force: true,
                refreshTimestampIfUnchanged: true
            )
            AtriaDebugLog("ATRIADBG session_checkpoint status=deferred reason=thermal_pressure_minimal_journal samples=%d rr_samples=%d source=ble_event mode=%@ interval_s=%.0f",
                  session.count,
                  rrArchive.count,
                  effectivePowerThermalMode,
                  checkpointInterval)
            return
        }
        let label = captureLabel.isEmpty
            ? (foregroundInteractiveMode ? "All-day wear" : "Unattended workout")
            : captureLabel
        guard let saved = snapshotSession(label: label) else {
            AtriaDebugLog("ATRIADBG session_checkpoint status=skipped reason=event_snapshot_failed samples=%d rr_samples=%d source=ble_event",
                  session.count, rrArchive.count)
            return
        }

        lastCanonicalCheckpointAt = now
        UserDefaults.standard.set(true, forKey: CheckpointDefaults.armed)
        UserDefaults.standard.set(checkpointInterval, forKey: CheckpointDefaults.interval)
        UserDefaults.standard.set(label, forKey: CheckpointDefaults.label)
        let appState: String
        switch UIApplication.shared.applicationState {
        case .active:
            appState = "active"
        case .inactive:
            appState = "inactive"
        case .background:
            appState = "background"
        @unknown default:
            appState = "unknown"
        }
        UserDefaults.standard.set("ble_event_\(appState)", forKey: CheckpointDefaults.source)
        let checkpointPersisted = onSessionCheckpoint?(saved) == true
        persistActiveSessionJournalIfNeeded(reason: "ble_event_checkpoint", force: true)
        UserDefaults.standard.set(checkpointPersisted ? "saved" : "store_failed", forKey: CheckpointDefaults.lastStatus)
        UserDefaults.standard.set(saved.points.count, forKey: CheckpointDefaults.lastSamples)
        UserDefaults.standard.set(Int(saved.duration.rounded()), forKey: CheckpointDefaults.lastDuration)
        AtriaDebugLog("ATRIADBG session_checkpoint status=%@ samples=%d rr_samples=%d hr_raw_2a37=%d hr_accepted=%d hr_zero=%d hr_artifact_held=%d hr_artifact_dropped=%d hr_raw_gaps=%d hr_accepted_gaps=%d hr_max_raw_gap_s=%.1f hr_max_accepted_gap_s=%.1f duration_s=%.0f avg_hr=%d peak_hr=%d hrv=%@ label=%@ mode=upsert source=ble_event app_state=%@ foreground_interactive=%d interval_s=%.0f",
              checkpointPersisted ? "saved" : "store_failed",
              saved.points.count,
              saved.rrSampleCount,
              saved.hrRaw2A37Value,
              saved.hrAcceptedValue,
              saved.hrZeroValue,
              saved.hrArtifactHeldValue,
              saved.hrArtifactDroppedValue,
              saved.hrRawGapsValue,
              saved.hrAcceptedGapsValue,
              saved.hrMaxRawGapValue,
              saved.hrMaxAcceptedGapValue,
              saved.duration,
              saved.avg,
              saved.peak,
              saved.hrv.map(String.init) ?? "learning",
              saved.label,
              appState,
              foregroundInteractiveMode ? 1 : 0,
              checkpointInterval)
    }

    /// Builds the CSV file and returns its URL for sharing/export.
    func exportCSV() -> URL? {
        saveCaptureCSV(base: FileManager.default.temporaryDirectory, relativePrefix: "tmp")?.url
    }

    private func captureFilename() -> String {
        let df = DateFormatter()
        df.dateFormat = "yyyyMMdd-HHmmss"
        let label = filenameSafe(captureLabel)
        let readiness = captureWasValidationReady ? "ready" : "learning"
        return "atria-capture-\(df.string(from: captureStart))-\(label)-\(readiness).csv"
    }

    private func saveCaptureCSV(directory: FileManager.SearchPathDirectory) -> (url: URL, relativePath: String)? {
        guard !captureLog.isEmpty else { return nil }
        guard let base = FileManager.default.urls(for: directory, in: .userDomainMask).first else { return nil }
        let folder = base.appendingPathComponent("atria-captures", isDirectory: true)
        return saveCaptureCSV(base: folder, relativePrefix: "Documents/atria-captures")
    }

    private func saveCaptureCSV(base folder: URL, relativePrefix: String) -> (url: URL, relativePath: String)? {
        guard !captureLog.isEmpty else { return nil }
        let url = folder.appendingPathComponent(captureFilename())
        do {
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            try captureLog.joined(separator: "\n").write(to: url, atomically: true, encoding: .utf8)
            AtriaGeneratedArtifactRetention.prune(in: folder,
                                                   policy: AtriaGeneratedArtifactRetention.diagnosticCaptures,
                                                   preserving: [url])
            return (url, "\(relativePrefix)/\(url.lastPathComponent)")
        } catch { return nil }
    }

    private func csvSafe(_ value: String) -> String {
        let escaped = value.replacingOccurrences(of: "\"", with: "\"\"")
        if escaped.contains(",") || escaped.contains("\"") || escaped.contains("\n") {
            return "\"\(escaped)\""
        }
        return escaped
    }

    private func metaSafe(_ value: String) -> String {
        let collapsed = value
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "\\s+", with: "_", options: .regularExpression)
        let filtered = collapsed.unicodeScalars.map { scalar in
            CharacterSet.alphanumerics.contains(scalar) || "-._:/".unicodeScalars.contains(scalar) ? Character(scalar) : "_"
        }
        return String(filtered).isEmpty ? "unknown" : String(filtered)
    }

    private func filenameSafe(_ value: String) -> String {
        String(metaSafe(value).prefix(48))
    }

    private func rebuildSessionHeartRateStats() {
        guard !session.isEmpty else {
            sessionMinHeartRate = nil
            sessionMaxHeartRate = nil
            sessionHeartRateTotal = 0
            sessionHeartRateAggregateCount = 0
            sessionHeartRateMean = 0
            sessionHeartRateM2 = 0
            return
        }

        var minRate = Int.max
        var maxRate = Int.min
        var total = 0
        var count = 0
        var mean = 0.0
        var m2 = 0.0
        for sample in session {
            minRate = min(minRate, sample.bpm)
            maxRate = max(maxRate, sample.bpm)
            total += sample.bpm
            count += 1
            let value = Double(sample.bpm)
            let delta = value - mean
            mean += delta / Double(count)
            m2 += delta * (value - mean)
        }
        sessionMinHeartRate = minRate == Int.max ? nil : minRate
        sessionMaxHeartRate = maxRate == Int.min ? nil : maxRate
        sessionHeartRateTotal = total
        sessionHeartRateAggregateCount = count
        sessionHeartRateMean = mean
        sessionHeartRateM2 = m2
    }

    private func recordSessionHeartRateStats(rate: Int) {
        sessionMinHeartRate = min(sessionMinHeartRate ?? rate, rate)
        sessionMaxHeartRate = max(sessionMaxHeartRate ?? rate, rate)
        sessionHeartRateTotal += rate
        sessionHeartRateAggregateCount += 1
        let value = Double(rate)
        let delta = value - sessionHeartRateMean
        sessionHeartRateMean += delta / Double(sessionHeartRateAggregateCount)
        sessionHeartRateM2 += delta * (value - sessionHeartRateMean)
    }

    static func shouldPublishLiveSessionSampleCount(currentCount: Int,
                                                    publishedCount: Int,
                                                    lastPublishedAt: Date?,
                                                    now: Date,
                                                    force: Bool = false) -> Bool {
        if force { return true }
        guard currentCount != publishedCount else { return false }
        if liveSessionSampleCountSemanticThresholds.contains(where: { publishedCount < $0 && currentCount >= $0 }) {
            return true
        }
        if abs(currentCount - publishedCount) >= sessionSampleCountPublishMinimumDelta {
            return true
        }
        guard let lastPublishedAt else { return true }
        return now.timeIntervalSince(lastPublishedAt) >= sessionSampleCountPublishMinimumInterval
    }

    private func publishSessionSampleCountIfNeeded(now: Date = Date(),
                                                   force: Bool = false) {
        let currentCount = session.count
        guard Self.shouldPublishLiveSessionSampleCount(currentCount: currentCount,
                                                       publishedCount: sessionSampleCount,
                                                       lastPublishedAt: lastSessionSampleCountPublishedAt,
                                                       now: now,
                                                       force: force) else { return }
        lastSessionSampleCountPublishedAt = now
        assignIfChanged(\.sessionSampleCount, currentCount)
    }

    private var currentCapturedRowCount: Int {
        max(captureLog.count - 1, 0)
    }

    private func scheduleCapturedRowsFlush() {
        if captureRowsFlushTask == nil {
            captureRowsFlushTask = Task { @MainActor [weak self] in
                try? await Task.sleep(nanoseconds: 200_000_000)
                guard let self else { return }
                self.flushCapturedRows()
                self.captureRowsFlushTask = nil
            }
        } else if currentCapturedRowCount - capturedRows >= 12 {
            flushCapturedRows()
            captureRowsFlushTask?.cancel()
            captureRowsFlushTask = nil
        }
    }

    private func flushCapturedRows() {
        assignIfChanged(\.capturedRows, currentCapturedRowCount)
    }

    private func logRow(kind: String, source: String, opcode: String, len: String, value: String, at eventTime: Date = Date(), elapsedMS: Int? = nil) {
        guard isRecording else { return }
        let ms = elapsedMS ?? Int(eventTime.timeIntervalSince(captureStart) * 1000)
        captureLog.append([
            "\(ms)",
            csvSafe(kind),
            csvSafe(source),
            csvSafe(opcode),
            csvSafe(len),
            csvSafe(captureLabel),
            csvSafe(value)
        ].joined(separator: ","))
        scheduleCapturedRowsFlush()
    }

    private func recordRawHRNotification(hr: Int, at sampleTime: Date) {
        sessionRawHRNotifications += 1
        recordWorkoutPromptQualityEvent(.raw, at: sampleTime)
        sampleDiagnostics.rawNotifications += 1
        let rawCount = sampleDiagnostics.rawNotifications
        if let lastRawHRNotificationAt {
            let gap = sampleTime.timeIntervalSince(lastRawHRNotificationAt)
            if gap > SavedSession.workoutContinuityGapLimit {
                sessionRawHRGaps += 1
                sessionMaxRawHRGap = max(sessionMaxRawHRGap, gap)
                sampleDiagnostics.rawGaps += 1
                sampleDiagnostics.maxRawGap = max(sampleDiagnostics.maxRawGap, gap)
                setSampleDiagnosticsStatus("raw_2a37", reason: "raw_gap")
                AtriaDebugLog("ATRIADBG hr_sample_gap kind=raw_2a37 gap_s=%.1f threshold_s=%.1f raw_notifications=%d accepted=%d action=missing_notification",
                      gap,
                      SavedSession.workoutContinuityGapLimit,
                      rawCount,
                      sampleDiagnostics.acceptedSamples)
            }
        }
        lastRawHRNotificationAt = sampleTime
        scheduleSampleDiagnosticsFlush()
    }

    private func recordAcceptedHRSample(rate: Int, at sampleTime: Date) {
        completePostReconnectStreamRecoveryIfNeeded()
        sessionAcceptedHRSamples += 1
        recordWorkoutPromptQualityEvent(.accepted, at: sampleTime)
        sampleDiagnostics.acceptedSamples += 1
        promoteReconnectBatteryBaselineIfSafe(
            now: sampleTime,
            heartRateReceivedAt: sampleTime,
            reason: "accepted_hr_current_connection"
        )
        publishRecentReconnectBatteryBaselineIfNeeded(now: sampleTime)
        let acceptedCount = sampleDiagnostics.acceptedSamples
        let continuityRelevant = Self.isBLEContinuityRelevant(
            longWearEnabled: longWearModeEnabled,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        )
        let hadOpenMissingWindow = continuityRelevant && AtriaHistoricalGapLedger.hasOpenWindow()
        let closeMissingWindowResult = hadOpenMissingWindow
            ? AtriaHistoricalGapLedger.closeOpenGapWithResult(
                at: sampleTime,
                minimumDuration: SavedSession.workoutContinuityGapLimit
            )
            : nil
        let closedMissingWindow = closeMissingWindowResult?.closedWindow == true
        if closeMissingWindowResult?.resolvedWindows ?? 0 > 0 {
            _ = reconcileRangeLossBackfillPendingWithArchive(
                reason: "accepted_hr_closed_covered_gap",
                ledgerCoverageResolved: true
            )
            reconcileHistoricalRecoveryPresentation(
                reason: "accepted_hr_closed_covered_gap"
            )
        }
        if let lastAcceptedHRAt {
            let gap = sampleTime.timeIntervalSince(lastAcceptedHRAt)
            if gap > SavedSession.workoutContinuityGapLimit {
                sessionAcceptedHRGaps += 1
                recordWorkoutPromptQualityEvent(.acceptedGap(gap), at: sampleTime)
                sessionMaxAcceptedHRGap = max(sessionMaxAcceptedHRGap, gap)
                sampleDiagnostics.acceptedGaps += 1
                sampleDiagnostics.maxAcceptedGap = max(sampleDiagnostics.maxAcceptedGap, gap)
                setSampleDiagnosticsStatus("accepted", reason: "accepted_gap")
                AtriaDebugLog("ATRIADBG hr_sample_gap kind=accepted_hr gap_s=%.1f threshold_s=%.1f accepted=%d raw_notifications=%d rate=%d action=coverage_gap",
                      gap,
                      SavedSession.workoutContinuityGapLimit,
                      acceptedCount,
                      sampleDiagnostics.rawNotifications,
                      rate)
                // A silent/suspended CoreBluetooth link may never produce
                // didDisconnect. Persist the exact consecutive-sample window;
                // when an open disconnect window was just closed, do not add a
                // duplicate interval for the same outage.
                if continuityRelevant, !hadOpenMissingWindow,
                   AtriaHistoricalGapLedger.recordObservedGap(
                    start: lastAcceptedHRAt,
                    end: sampleTime,
                    reason: "accepted_hr_gap",
                    minimumDuration: SavedSession.workoutContinuityGapLimit
                   ) {
                    markRangeLossBackfillRequired(reason: AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
                                                  ? "explicit_workout_range_loss"
                                                  : "long_wear_range_loss")
                    scheduleRangeLossBackfillIfNeeded(reason: "accepted_hr_gap")
                } else if closedMissingWindow {
                    AtriaDebugLog("ATRIADBG offline_sync status=missing_window_closed start_unix=%d end_unix=%d action=await_metric_history_coverage",
                                  Int(lastAcceptedHRAt.timeIntervalSince1970),
                                  Int(sampleTime.timeIntervalSince1970))
                }
            }
        } else if continuityRelevant,
                  !hadOpenMissingWindow,
                  AtriaHistoricalGapLedger.recordRestorationGapIfNeeded(
                    firstAcceptedAt: sampleTime,
                    reason: AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
                        ? "explicit_workout_process_restore_gap"
                        : "long_wear_process_restore_gap",
                    minimumDuration: SavedSession.workoutContinuityGapLimit
                  ) {
            // CoreBluetooth can deliver this pulse before the asynchronous
            // active-journal restore completes. Preserve the exact timestamp
            // outage for verified strap history rather than silently treating
            // the new process as the beginning of collection.
            markRangeLossBackfillRequired(reason: AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
                                          ? "explicit_workout_range_loss"
                                          : "long_wear_range_loss")
            scheduleRangeLossBackfillIfNeeded(reason: "process_restore_accepted_hr_gap")
        }
        _ = AtriaHistoricalGapLedger.advanceLiveContinuityAnchor(to: sampleTime)
        if sampleDiagnostics.lastReason == "accepted_gap" {
            sampleDiagnostics.lastStatus = "accepted"
            sampleDiagnostics.lastReason = "sample"
        }
        scheduleSampleDiagnosticsFlush()
    }

    fileprivate func record(
        _ rate: Int,
        at sampleTime: Date = Date(),
        callbackSource: AtriaBLECallbackEpochFence.Source? = nil
    ) {
        // ACCURACY: a 0 means the sensor lost skin contact — don't pollute the
        // series, just flag it.
        guard rate > 0 else {
            sessionZeroHRSamples += 1
            recordWorkoutPromptQualityEvent(.zero, at: sampleTime)
            sampleDiagnostics.zeroSamples += 1
            setSampleDiagnosticsStatus("zero_contact", reason: "hr_zero")
            assignIfChanged(\.hasContact, false)
            contactStableSince = nil
            pendingHRJump = nil
            recentValid.removeAll(keepingCapacity: true)
            // A real zero-contact reading proves the strap was off wrist. Do
            // not carry a pre-contact timestamp across that known-unwearable
            // interval and later request history that cannot contain pulse data.
            AtriaHistoricalGapLedger.clearLiveContinuityAnchor()
            resetHRVWindow(reason: "contact lost")
            logRow(kind: "hr", source: "0x2A37", opcode: "", len: "", value: "0", at: sampleTime)
            return
        }
        guard Self.heartRateIsPhysiologicallyPlausible(rate,
                                                       profileMaxHR: maxHRSetting) else {
            sessionDroppedArtifacts += 1
            recordWorkoutPromptQualityEvent(.droppedArtifact, at: sampleTime)
            sampleDiagnostics.droppedArtifacts += 1
            setSampleDiagnosticsStatus("artifact_drop", reason: "implausible_hr")
            AtriaDebugLog("ATRIADBG hr_artifact action=drop reason=implausible_hr rate=%d hard_upper=%d",
                          rate,
                          Self.heartRateHardUpperBound(profileMaxHR: maxHRSetting))
            logRow(kind: "hr_artifact", source: "0x2A37", opcode: "", len: "", value: "\(rate)", at: sampleTime)
            return
        }
        if !hasContact {
            contactStableSince = sampleTime
            hrvGateWasOpen = false
            pendingHRJump = nil
            recentValid.removeAll(keepingCapacity: true)
            resetHRVWindow(reason: "contact reacquired")
        }
        assignIfChanged(\.hasContact, true)

        // ACCURACY: reject isolated motion artifacts, but do not pin workout HR
        // to an old resting median. A jump is accepted if it repeats or if it is
        // a nearby second reading confirms the new level.
        if let med = median(recentValid), recentValid.count >= 3, abs(rate - med) > Self.workoutHRArtifactJumpBPM {
            let gap = lastAcceptedHRAt.map { sampleTime.timeIntervalSince($0) } ?? 0
            let pendingAge = pendingHRJump.map { sampleTime.timeIntervalSince($0.at) }
            let decision = Self.hrArtifactJumpDecision(rate: rate,
                                                       median: med,
                                                       pendingRate: pendingHRJump?.rate,
                                                       pendingAge: pendingAge,
                                                       acceptedGap: gap)
            if decision.reason == "confirmed_jump", let pending = pendingHRJump {
                pendingHRJump = nil
                AtriaDebugLog("ATRIADBG hr_artifact action=accept reason=confirmed_jump previous=%d rate=%d median=%d gap_s=%.1f", pending.rate, rate, med, gap)
                acceptHeartRate(
                    pending.rate,
                    at: pending.at,
                    callbackSource: callbackSource
                )
                acceptHeartRate(
                    rate,
                    at: sampleTime,
                    callbackSource: callbackSource
                )
                return
            }
            pendingHRJump = (rate, sampleTime)
            sessionHeldArtifacts += 1
            recordWorkoutPromptQualityEvent(.heldArtifact, at: sampleTime)
            sampleDiagnostics.heldArtifacts += 1
            setSampleDiagnosticsStatus("artifact_hold", reason: "unconfirmed_jump")
            AtriaDebugLog("ATRIADBG hr_artifact action=hold reason=unconfirmed_jump rate=%d median=%d gap_s=%.1f", rate, med, gap)
            logRow(kind: "hr_artifact", source: "0x2A37", opcode: "", len: "", value: "\(rate)", at: sampleTime)
            return
        }

        if let pending = pendingHRJump {
            sessionDroppedArtifacts += 1
            recordWorkoutPromptQualityEvent(.droppedArtifact, at: sampleTime)
            sampleDiagnostics.droppedArtifacts += 1
            setSampleDiagnosticsStatus("artifact_drop", reason: "not_confirmed")
            AtriaDebugLog("ATRIADBG hr_artifact action=drop reason=not_confirmed previous=%d rate=%d", pending.rate, rate)
            pendingHRJump = nil
        }
        acceptHeartRate(
            rate,
            at: sampleTime,
            callbackSource: callbackSource
        )
    }

    private func acceptHeartRate(
        _ rate: Int,
        at sampleTime: Date,
        callbackSource: AtriaBLECallbackEpochFence.Source?
    ) {
        if let callbackSource,
           let connectedPeripheral = peripheral {
            recordLinkObservedConnected(
                reason: "accepted_standard_2a37",
                peripheral: connectedPeripheral,
                callbackSource: callbackSource,
                evidence: .standardHeartRateMeasurement
            )
        }
        let shouldForceFirstJournalSave = longWearModeEnabled && session.isEmpty
        recordAcceptedHRSample(rate: rate, at: sampleTime)
        // A restored CoreBluetooth link can bypass both didConnect and the
        // central powered-on handoff. The first accepted 2A37 packet is the
        // final, unambiguous proof that this saved strap is live; use it to
        // schedule only raw orphan archival, never a history command or ACK.
        _ = archiveOrphanHistoricalIngressIfNeeded(
            reason: "first_accepted_hr_orphan_ingress_replay",
            force: false,
            explicitRequest: false,
            retainHistoricalRequest: false
        )
        if resumeFullDrainPublicationAfterFreshHR,
           !historicalRadioTransportOwnsLink,
           !connectedMotionBankFirstAttemptOwnsForegroundPriority {
            resumeFullDrainPublicationAfterFreshHR = false
            resumePendingFullDrainPublicationIfNeeded(
                reason: "post_restore_fresh_accepted_hr"
            )
        }
        recentValid.append(rate)
        if recentValid.count > 5 { recentValid.removeFirst() }
        appendLastHeartRate(rate)
        let displayRate = median(recentValid) ?? rate
        // Evaluate the same artifact-filtered, short-median signal shown to the
        // user, not a single raw accepted beat. The lifecycle itself is owned
        // here so background/minimized delivery still produces transitions.
        if let pulses = workoutZoneHapticLifecycle.accept(bpm: displayRate) {
            triggerWorkoutZoneHaptic(pulses: pulses)
        }
        if acceptedHeartRateBatchDepth > 0 {
            acceptedHeartRateBatchPendingDisplayRate = displayRate
            acceptedHeartRateBatchPendingDisplayAt = sampleTime
            acceptedHeartRateBatchPendingDisplayForce = acceptedHeartRateBatchPendingDisplayForce || session.isEmpty
        } else {
            publishLiveHeartDisplayIfNeeded(sampleTime: sampleTime,
                                            displayRate: displayRate,
                                            force: session.isEmpty)
        }
        lastStandardHR = (rate, sampleTime)
        lastAcceptedHRAt = sampleTime
        connectedEpochAcceptedHeartRateSamples += 1
        if let callbackSource,
           workoutHistoryPreemptionSuccessorGate
            .consumeAfterAcceptedHeartRate(
                source: callbackSource,
                sourceIsCurrent:
                    bleCallbackEpochFence.owns(source: callbackSource)
            ) {
            AtriaDebugLog(
                "ATRIADBG workout_motion status=history_preemption_successor_live callback_epoch=%llu action=allow_69_arm_on_same_accepted_hr",
                callbackSource.epoch
            )
        }
        _ = retryForegroundGlanceCheckpointAfterFreshHeartRateIfNeeded(
            at: sampleTime
        )
        // TX discovery can beat the first restored HR callback by a few
        // hundred milliseconds. Release that bounded successor-arm hold now,
        // before the typed selector below, so the durable attempts-zero ticket
        // gets one exact object/epoch admission opportunity on this sample.
        _ = consumeConnectedMotionBankPreFreshHRFirstRefusalForSelector()
        // Give a previously closed durable bank first refusal on the healthy
        // link. Opening a new bank immediately before that offload seizes the
        // radio made each intentional history cutover close a seconds-long
        // bank and create another ticket.
        if !workoutHistoricalMotionBankArmed,
           !connectedMotionBankArchiveWarmRetryGate.isHolding,
           !connectedMotionBankAdmissionLedgerRetryGate.isHolding,
           !connectedMotionBankLocalDependencyRetryGate.isHolding,
           let strapIdentifier = peripheral?.identifier.uuidString {
            // Also repairs an app termination/relaunch where the old process
            // could not observe didDisconnect and persist the scheduling hint.
            // The ledger remains authoritative; this only admits an existing
            // attempts == 0 interval to its first asynchronous drain.
            persistNextUnattemptedMotionBankMaintenanceTicketIfNeeded(
                strapIdentifier: strapIdentifier
            )
        }
        // One connected raw continuation is one serial FIFO drain even across
        // its bounded live-restoration gaps. A newly closed bank ticket cannot
        // target the fresh wall-clock interval, so the generic exact-ticket
        // selector stays out of this lane until global catch-up releases it.
        let noRadioPresentCaptureTurn =
            connectedRawNoRadioCaptureTurnIsCurrent()
        let bankOffloadStarted =
            connectedRawHistoryCatchUpContinuationPending
                || noRadioPresentCaptureTurn
                ? false
                : resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded(
                    reason: "fresh_accepted_hr"
                )
        if !bankOffloadStarted {
            // A boundary-opened 0x69 bank can remain flat during the first part
            // of a workout. The physically accepted walks were pre-armed, so
            // keep the low-bandwidth bank prepared on a healthy live link.
            if !workoutHistoricalMotionBankArmed {
                armWorkoutHistoricalMotionBankIfPossible(
                    reason: "fresh_accepted_hr_prearm",
                    prioritizePresentCaptureOverProcessRetry:
                        noRadioPresentCaptureTurn
                            || Self
                                .shouldParkConnectedMotionBankHistoryForPowerPressure(
                                    thermalState:
                                        ProcessInfo.processInfo.thermalState,
                                    lowPowerModeEnabled:
                                        ProcessInfo.processInfo.isLowPowerModeEnabled
                                )
                )
            }
            if !connectedRawHistoryCatchUpContinuationPending,
               connectedRawHistoryCatchUpPublicationYield == nil,
               !(postHistoryLiveRestorationGeneration != nil
                    && connectedRawHistoryCatchUpContinuationPending) {
                checkpointDailyHistoricalMotionBankIfNeeded(
                    at: sampleTime,
                    reason: "fresh_accepted_hr"
                )
            }
        }
        // Fresh accepted HR is the only signal allowed to grant a new R10
        // lease after a reconnect or HR outage. The scheduler coalesces the
        // one-Hz stream, so this cannot create command churn.
        if let workoutStartedAt = workoutMotionOwnerStartedAt {
            scheduleWorkoutMotionLeaseEvaluation(reason: "fresh_accepted_hr", delay: 0)
            // Do not retry the retired realtime-R10 cutover from the hot HR
            // path. Banked v24 owns step capture and must retain this healthy
            // connection for both continuous HR and 69/01.
            _ = workoutStartedAt
        }
        resetRecoveryReconnectBackoff(reason: "accepted_hr")
        fireDebugRRPresenceWatchdogIfDue(now: sampleTime, source: "accepted_hr")
        if acceptedHeartRateBatchDepth > 0 {
            acceptedHeartRateBatchPendingConsistencyAt = sampleTime
        } else {
            compareHRChannelsIfPossible(now: sampleTime, source: "2A37")
        }
        session.append(HRSample(t: sampleTime, bpm: rate))
        appendSessionPoint(rate: rate, at: sampleTime)
        recordSessionHeartRateStats(rate: rate)
        publishSessionSampleCountIfNeeded(now: sampleTime)
        logRow(kind: "hr", source: "0x2A37", opcode: "", len: "", value: "\(rate)", at: sampleTime)
        if acceptedHeartRateBatchDepth > 0 {
            acceptedHeartRateBatchNeedsJournalCheck = true
            acceptedHeartRateBatchForceJournalSave = acceptedHeartRateBatchForceJournalSave || shouldForceFirstJournalSave
            acceptedHeartRateBatchLatestCheckpointAt = sampleTime
        } else {
            if shouldForceFirstJournalSave {
                persistActiveSessionJournalIfNeeded(reason: "first_accepted_hr", force: true)
            } else {
                persistActiveSessionJournalIfNeeded(reason: "accepted_hr", force: false)
            }
            checkpointFromLiveEventIfNeeded(now: sampleTime)
            let connectedRawCatchUpStarted =
                attemptAutonomousBackgroundCatchUpAfterAcceptedHRIfNeeded(
                    now: sampleTime,
                    trigger: "accepted_hr"
                )
            if !connectedRawCatchUpStarted {
                resumePendingForcedHistoricalSyncAfterLivePersistenceIfNeeded(
                    reason: "accepted_hr"
                )
                if let callbackSource {
                    rearmPersistedInterruptedFullDrainAfterFreshHRIfNeeded(
                        reason: "accepted_hr",
                        callbackSource: callbackSource
                    )
                }
                attemptQualifiedRangeLossBackfillAfterAcceptedHRIfNeeded(
                    now: sampleTime
                )
            }
        }
    }

    private func beginAcceptedHeartRateBatch() {
        acceptedHeartRateBatchDepth += 1
    }

    private func endAcceptedHeartRateBatch(
        callbackSource: AtriaBLECallbackEpochFence.Source
    ) {
        guard acceptedHeartRateBatchDepth > 0 else { return }
        acceptedHeartRateBatchDepth -= 1
        guard acceptedHeartRateBatchDepth == 0 else { return }
        let checkpointAt = acceptedHeartRateBatchLatestCheckpointAt
        let pendingConsistencyAt = acceptedHeartRateBatchPendingConsistencyAt
        let pendingRRContinuityAt = acceptedHeartRateBatchPendingRRContinuityAt
        let pendingAutoCaptureAt = acceptedHeartRateBatchPendingAutoCaptureAt
        let pendingSegmentRRRecoveryAt = acceptedHeartRateBatchPendingSegmentRRRecoveryAt
        let pendingCurrentRRRecoveryAt = acceptedHeartRateBatchPendingCurrentRRRecoveryAt
        let pendingDisplayRate = acceptedHeartRateBatchPendingDisplayRate
        let pendingDisplayAt = acceptedHeartRateBatchPendingDisplayAt
        let pendingDisplayForce = acceptedHeartRateBatchPendingDisplayForce
        defer {
            acceptedHeartRateBatchNeedsJournalCheck = false
            acceptedHeartRateBatchForceJournalSave = false
            acceptedHeartRateBatchLatestCheckpointAt = nil
            acceptedHeartRateBatchPendingConsistencyAt = nil
            acceptedHeartRateBatchPendingRRContinuityAt = nil
            acceptedHeartRateBatchPendingAutoCaptureAt = nil
            acceptedHeartRateBatchPendingSegmentRRRecoveryAt = nil
            acceptedHeartRateBatchPendingCurrentRRRecoveryAt = nil
            acceptedHeartRateBatchPendingDisplayRate = nil
            acceptedHeartRateBatchPendingDisplayAt = nil
            acceptedHeartRateBatchPendingDisplayForce = false
        }
        // A yield inside a large callback batch can overlap a reconnect. Never
        // let deferred checkpoint/recovery actions from the retired source run
        // against the replacement link; the raw queued updates were already
        // rejected individually and this clears their batch accumulators.
        guard bleCallbackEpochFence.owns(source: callbackSource) else { return }
        if acceptedHeartRateBatchNeedsJournalCheck {
            if acceptedHeartRateBatchForceJournalSave {
                persistActiveSessionJournalIfNeeded(reason: "first_accepted_hr_batch", force: true)
            } else {
                persistActiveSessionJournalIfNeeded(reason: "accepted_hr_batch", force: false)
            }
            if let checkpointAt {
                checkpointFromLiveEventIfNeeded(now: checkpointAt)
            }
        }
        if let now = pendingConsistencyAt {
            compareHRChannelsIfPossible(now: now, source: "2A37")
        }
        if let now = pendingRRContinuityAt {
            publishRRContinuityQuality(now: now)
        }
        if let now = pendingAutoCaptureAt {
            evaluateAdaptiveAutoCapture(now: now)
        }
        if let now = pendingSegmentRRRecoveryAt {
            recoverSegmentHROnlyRRIfNeeded(now: now)
        }
        if let now = pendingCurrentRRRecoveryAt {
            recoverCurrentRRGapIfNeeded(now: now)
        }
        if let displayRate = pendingDisplayRate,
           let displayAt = pendingDisplayAt {
            publishLiveHeartDisplayIfNeeded(sampleTime: displayAt,
                                            displayRate: displayRate,
                                            force: pendingDisplayForce)
        }
        let connectedRawCatchUpStarted =
            attemptAutonomousBackgroundCatchUpAfterAcceptedHRIfNeeded(
                now: checkpointAt ?? Date(),
                trigger: "accepted_hr_batch"
            )
        if !connectedRawCatchUpStarted {
            resumePendingForcedHistoricalSyncAfterLivePersistenceIfNeeded(
                reason: "accepted_hr_batch"
            )
            rearmPersistedInterruptedFullDrainAfterFreshHRIfNeeded(
                reason: "accepted_hr_batch",
                callbackSource: callbackSource
            )
        }
    }

    private func publishLiveHeartDisplayIfNeeded(sampleTime: Date,
                                                 displayRate: Int,
                                                 force: Bool = false) {
        let minimumInterval = foregroundInteractiveMode
            ? (foregroundHighFrequencyDisplayMode
                ? Self.liveHeartDisplayMinimumInterval
                : Self.reducedForegroundLiveHeartDisplayMinimumInterval)
            : Self.backgroundLiveHeartDisplayMinimumInterval
        let governedMinimumInterval = minimumInterval * effectiveThermalCadenceMultiplier
        let shouldPublish: Bool
        if force || heartRate == 0 || liveHeartWindow.sparkline.isEmpty {
            shouldPublish = true
        } else if abs(displayRate - heartRate) >= 4 {
            shouldPublish = true
        } else if let lastPublish = lastLiveHeartDisplayPublishAt {
            shouldPublish = sampleTime.timeIntervalSince(lastPublish) >= governedMinimumInterval
        } else {
            shouldPublish = true
        }

        guard shouldPublish else { return }
        lastLiveHeartDisplayPublishAt = sampleTime
        assignIfChanged(\.heartRate, displayRate)
        retryProtectedR10AfterStableHRIfEligible(now: sampleTime)
        // Live HR streaming proves the link is up. Heal ANY non-connected status —
        // including .disconnected after CoreBluetooth state restoration
        // (`ble_restore reuse_restored`), where notifications resume but no
        // didConnect arrives, so the UI showed "Disconnected" while HR/RR data was
        // actively flowing. If we're decoding the strap's HR, we are connected.
        // Only heal to .connected if Bluetooth is on AND the peripheral is actually
        // connected. iOS does not always fire didDisconnect when Bluetooth is turned
        // off, so peripheral.state can be a stale .connected — the `central.state`
        // check is what blocks a queued HR from faking "Live" while Bluetooth is off.
        if displayRate > 0, status != .connected,
           central.state == .poweredOn, peripheral?.state == .connected {
            recomputeConnectionStatus(reason: "event")
        }
        rebuildLiveHeartWindow()
    }

    nonisolated static func hrArtifactJumpDecision(rate: Int,
                                                   median: Int,
                                                   pendingRate: Int?,
                                                   pendingAge: TimeInterval?,
                                                   acceptedGap: TimeInterval) -> (action: String, reason: String) {
        if let pendingRate,
           let pendingAge,
           pendingAge <= workoutHRArtifactConfirmSeconds,
           abs(rate - pendingRate) <= workoutHRArtifactConfirmBPM,
           (rate - median).signum() == (pendingRate - median).signum() {
            return ("accept", "confirmed_jump")
        }
        return ("hold", acceptedGap > workoutHRArtifactStaleMedianSeconds
            ? "post_gap_unconfirmed_jump"
            : "unconfirmed_jump")
    }

    private func logHRArtifactPolicySelfTest() {
        let cases: [(name: String, rate: Int, median: Int, pending: Int?, pendingAge: TimeInterval?, gap: TimeInterval)] = [
            ("isolated_jump", 145, 90, nil, nil, 1),
            ("confirmed_jump", 148, 90, 145, 2, 2),
            ("stale_gap_jump", 145, 90, nil, nil, 8)
        ]
        for item in cases {
            let decision = Self.hrArtifactJumpDecision(rate: item.rate,
                                                       median: item.median,
                                                       pendingRate: item.pending,
                                                       pendingAge: item.pendingAge,
                                                       acceptedGap: item.gap)
            AtriaDebugLog("ATRIADBG hr_artifact_policy case=%@ action=%@ reason=%@ rate=%d median=%d pending=%@ pending_age_s=%@ accepted_gap_s=%.1f",
                  item.name,
                  decision.action,
                  decision.reason,
                  item.rate,
                  item.median,
                  item.pending.map(String.init) ?? "none",
                  item.pendingAge.map { String(format: "%.1f", $0) } ?? "none",
                  item.gap)
        }
        let now = Date()
        let rrCases = [
            RRInterval(t: now.addingTimeInterval(-4), ms: 800, expectedHR: 75,
                       source: .standardHeartRateMeasurement2A37),
            RRInterval(t: now.addingTimeInterval(-3), ms: 805, expectedHR: 75,
                       source: .standardHeartRateMeasurement2A37),
            RRInterval(t: now.addingTimeInterval(-2), ms: 317, expectedHR: 75,
                       source: .standardHeartRateMeasurement2A37),
            RRInterval(t: now.addingTimeInterval(-1), ms: 795, expectedHR: 75,
                       source: .standardHeartRateMeasurement2A37)
        ]
        if let snapshot = HRVAnalyzer.analyze(rrCases, now: now).0 {
            AtriaDebugLog("ATRIADBG hrv_artifact_policy case=rr_hr_mismatch raw=%d kept=%d rejected_out_of_range=%d rejected_delta_over_20_percent=%d rejected_hr_mismatch=%d expected_rejected_hr_mismatch=1 confidence=%d ready=%d rule=drop_rr_when_implied_bpm_diff_gt_%d",
                  snapshot.raw,
                  snapshot.kept,
                  snapshot.rejectedOutOfRange,
                  snapshot.rejectedDeltaOver20Percent,
                  snapshot.rejectedHRMismatch,
                  snapshot.confidencePercent,
                  snapshot.isReady ? 1 : 0,
                  Int(HRVSnapshot.maxRRImpliedHRMismatchBPM.rounded()))
        } else {
            AtriaDebugLog("ATRIADBG hrv_artifact_policy case=rr_hr_mismatch status=failed reason=no_snapshot")
        }
    }

    fileprivate func recordHeartRateMeasurement(_ data: Data) {
        let parsed = Self.parseHeartRatePacket(data)
        recordHeartRateMeasurement(
            parsed,
            rawData: data,
            callbackSource: nil
        )
    }

    private func recordHeartRateMeasurement(
        _ measurement: ParsedHeartRatePacket?,
        rawData data: Data,
        callbackSource: AtriaBLECallbackEpochFence.Source?
    ) {
        let frameTime = measurement?.frameTime ?? Date()
        let payloadLogBudget = standardHRPayloadLogBudget(now: frameTime)
        guard let measurement else {
            if let suppressed = payloadLogBudget {
                AtriaDebugLog("ATRIADBG standardHR payload=%@ parse=failed suppressed_since_last=%d",
                      Self.hex([UInt8](data)),
                      suppressed)
            }
            return
        }

        if !replayingBufferedSessionInputs,
           r10SessionBoundaryID != nil || activeSessionRestoreInFlightGeneration != nil ||
            strapStepLedgerRestoreInFlight {
            bufferedSessionInputs.append(.heartRate(
                measurement: measurement,
                rawData: data,
                callbackSource: callbackSource
            ))
            return
        }
        if !replayingBufferedSessionInputs,
           measurement.hr > 0,
           Self.heartRateIsPhysiologicallyPlausible(measurement.hr,
                                                    profileMaxHR: maxHRSetting),
           beginAutomaticSessionBoundaryIfNeeded(
                nextSampleTime: frameTime,
                firstBufferedInput: .heartRate(
                    measurement: measurement,
                    rawData: data,
                    callbackSource: callbackSource
                )
           ) {
            return
        }

        if let suppressed = payloadLogBudget {
            AtriaDebugLog("ATRIADBG standardHR payload=%@ hr=%d rrnum=%d truncated=%d rr_ms=%@ suppressed_since_last=%d",
                  Self.hex([UInt8](data)), measurement.hr, measurement.rrValues.count,
                  measurement.truncated ? 1 : 0,
                  Self.joinInts(measurement.rrValues),
                  suppressed)
        }
        standardHRFrames += 1
        lastStandardHRSensorContactDetected = measurement.sensorContactDetected
        lastStandardHRRRFlagPresent = measurement.rrFlagPresent
        recordRawHRNotification(hr: measurement.hr, at: frameTime)
        guard Self.heartRateIsPhysiologicallyPlausible(measurement.hr,
                                                       profileMaxHR: maxHRSetting) else {
            sessionDroppedArtifacts += 1
            sampleDiagnostics.droppedArtifacts += 1
            setSampleDiagnosticsStatus("artifact_drop", reason: "implausible_hr")
            AtriaDebugLog("ATRIADBG hr_artifact action=drop reason=implausible_hr rate=%d hard_upper=%d",
                          measurement.hr,
                          Self.heartRateHardUpperBound(profileMaxHR: maxHRSetting))
            logRow(kind: "hr_artifact", source: "0x2A37", opcode: "", len: "", value: "\(measurement.hr)", at: frameTime)
            return
        }
        record(
            measurement.hr,
            at: frameTime,
            callbackSource: callbackSource
        )

        guard !measurement.rrValues.isEmpty else {
            if acceptedHeartRateBatchDepth > 0 {
                acceptedHeartRateBatchPendingSegmentRRRecoveryAt = frameTime
                acceptedHeartRateBatchPendingCurrentRRRecoveryAt = frameTime
            } else {
                recoverSegmentHROnlyRRIfNeeded(now: frameTime)
                recoverCurrentRRGapIfNeeded(now: frameTime)
            }
            return
        }
        segmentHROnlyRRRecoveryCount = 0
        lastSegmentHROnlyRRRecoveryAt = nil
        currentRRGapRecoveryCount = 0
        lastCurrentRRGapRecoveryAt = nil
        let firstStandardRR = decodedStandardRRValues == 0
        decodedStandardRRValues += measurement.rrValues.count
        lastStandardRRAt = frameTime
        if firstStandardRR {
            // Once standard BLE R-R is proven live, old 0x28 zero-RR events are
            // diagnostic noise, not evidence against the R-R stream.
            removeRRAvailabilityWindowEntries(&rrContinuityWindow,
                                              head: &rrContinuityWindowHead) {
                !$0.hasRR && $0.source == "0x28"
            }
            removeRRAvailabilityWindowEntries(&captureRRQualityWindow,
                                              head: &captureRRQualityWindowHead) {
                !$0.hasRR && $0.source == "0x28"
            }
            removeRRAvailabilityWindowEntries(&autoCaptureRRWindow,
                                              head: &autoCaptureRRWindowHead) {
                !$0.hasRR && $0.source == "0x28"
            }
        }
        if autoCapturePending, autoCaptureRRThreshold > 0,
           appendAdaptiveAutoCaptureObservation(now: frameTime,
                                               rrnum: measurement.rrValues.count,
                                               source: "0x2A37") {
            if acceptedHeartRateBatchDepth > 0 {
                acceptedHeartRateBatchPendingAutoCaptureAt = frameTime
            } else {
                evaluateAdaptiveAutoCapture(now: frameTime)
            }
        }
        addRRBatch(intervalsMS: measurement.rrValues,
                   endingAt: frameTime,
                   source: "0x2A37",
                   opcode: "2A37",
                   expectedHR: measurement.hr)
        if appendRRContinuityObservation(now: frameTime,
                                         rrCount: measurement.rrValues.count,
                                         source: "0x2A37") {
            if acceptedHeartRateBatchDepth > 0 {
                acceptedHeartRateBatchPendingRRContinuityAt = frameTime
            } else {
                publishRRContinuityQuality(now: frameTime)
            }
        }

        if verboseBLEFrameLogging {
            let impliedBPM = measurement.rrValues.map { rr in
                rr > 0 ? String(format: "%.0f", 60000.0 / Double(rr)) : "inf"
            }.joined(separator: ",")
            let hrMismatch = measurement.rrValues.filter { rr in
                guard rr > 0 else { return true }
                return abs((60000.0 / Double(rr)) - Double(measurement.hr)) > 30
            }.count
            AtriaDebugLog("ATRIADBG rr source=0x2A37 hr=%d rrnum=%d decoded=%d total_decoded=%d truncated=%d hr_mismatch=%d implied_bpm=%@ values=%@",
                  measurement.hr, measurement.rrValues.count, measurement.rrValues.count,
                  decodedStandardRRValues, measurement.truncated ? 1 : 0, hrMismatch, impliedBPM,
                  Self.joinInts(measurement.rrValues))
        }
    }

    private func recoverSegmentHROnlyRRIfNeeded(now: Date) {
        guard longWearModeEnabled, standardHROnlyMode else { return }
        guard status == .connected else { return }
        guard rrArchive.isEmpty else { return }
        guard session.count >= autoSaveMinSamples,
              let firstSample = session.first?.t,
              let lastAcceptedHRAt else { return }
        let timeout: TimeInterval = 12
        let segmentAge = now.timeIntervalSince(firstSample)
        guard segmentAge >= timeout else { return }
        let acceptedGap = now.timeIntervalSince(lastAcceptedHRAt)
        guard acceptedGap <= 5 else { return }
        if let lastSegmentHROnlyRRRecoveryAt,
           now.timeIntervalSince(lastSegmentHROnlyRRRecoveryAt) < timeout {
            return
        }
        segmentHROnlyRRRecoveryCount += 1
        lastSegmentHROnlyRRRecoveryAt = now
        recoverRRPresenceWatchdog(label: captureLabel.isEmpty ? "All-day wear" : captureLabel,
                                  status: "segment_hr_only",
                                  rrGap: segmentAge,
                                  acceptedGap: acceptedGap,
                                  timeout: timeout,
                                  consecutive: segmentHROnlyRRRecoveryCount)
    }

    private func recoverCurrentRRGapIfNeeded(now: Date) {
        guard longWearModeEnabled, standardHROnlyMode else { return }
        guard status == .connected else { return }
        guard !rrArchive.isEmpty else { return }
        guard session.count >= autoSaveMinSamples,
              let lastStandardRRAt,
              let lastAcceptedHRAt else { return }
        let timeout: TimeInterval = 30
        let rrGap = now.timeIntervalSince(lastStandardRRAt)
        guard rrGap >= timeout else { return }
        let acceptedGap = now.timeIntervalSince(lastAcceptedHRAt)
        guard acceptedGap <= 5 else { return }
        if let lastCurrentRRGapRecoveryAt,
           now.timeIntervalSince(lastCurrentRRGapRecoveryAt) < 60 {
            return
        }
        currentRRGapRecoveryCount += 1
        lastCurrentRRGapRecoveryAt = now
        recoverRRPresenceWatchdog(label: captureLabel.isEmpty ? "All-day wear" : captureLabel,
                                  status: "current_rr_gap",
                                  rrGap: rrGap,
                                  acceptedGap: acceptedGap,
                                  timeout: timeout,
                                  consecutive: currentRRGapRecoveryCount)
    }

    private func standardHRPayloadLogBudget(now: Date) -> Int? {
        guard livePacketSummaryLoggingEnabled || verboseBLEFrameLogging else { return nil }
        if verboseBLEFrameLogging { return 0 }
        guard standardHROnlyMode else { return nil }
        standardHRPayloadLogCount += 1
        if standardHRPayloadLogCount <= 5 {
            lastStandardHRPayloadLogAt = now
            let suppressed = standardHRPayloadLogSuppressed
            standardHRPayloadLogSuppressed = 0
            return suppressed
        }
        if let lastStandardHRPayloadLogAt,
           now.timeIntervalSince(lastStandardHRPayloadLogAt) < 60 {
            standardHRPayloadLogSuppressed += 1
            return nil
        }
        lastStandardHRPayloadLogAt = now
        let suppressed = standardHRPayloadLogSuppressed
        standardHRPayloadLogSuppressed = 0
        return suppressed
    }

    private func median(_ xs: [Int]) -> Int? {
        guard !xs.isEmpty else { return nil }
        switch xs.count {
        case 1:
            return xs[0]
        case 2:
            return max(xs[0], xs[1])
        case 3:
            let a = xs[0]
            let b = xs[1]
            let c = xs[2]
            if a < b {
                if b < c { return b }
                return max(a, c)
            }
            if a < c { return a }
            return max(b, c)
        case 4:
            var a = xs[0]
            var b = xs[1]
            var c = xs[2]
            var d = xs[3]
            if a > b { swap(&a, &b) }
            if c > d { swap(&c, &d) }
            if a > c {
                swap(&a, &c)
                swap(&b, &d)
            }
            if b > c { swap(&b, &c) }
            if c > d { swap(&c, &d) }
            return c
        case 5:
            var a = xs[0]
            var b = xs[1]
            var c = xs[2]
            var d = xs[3]
            var e = xs[4]
            if a > b { swap(&a, &b) }
            if c > d { swap(&c, &d) }
            if a > c {
                swap(&a, &c)
                swap(&b, &d)
            }
            if b > e { swap(&b, &e) }
            if b > c { swap(&b, &c) }
            if d > e { swap(&d, &e) }
            if c > d { swap(&c, &d) }
            if b > c { swap(&b, &c) }
            return c
        default:
            let s = xs.sorted()
            return s[s.count / 2]
        }
    }

    private static func parseHexBytes(_ raw: String) -> [UInt8]? {
        let cleaned = raw
            .replacingOccurrences(of: "0x", with: "", options: .caseInsensitive)
            .replacingOccurrences(of: "[^0-9a-fA-F]", with: "", options: .regularExpression)
        guard cleaned.count >= 2, cleaned.count.isMultiple(of: 2) else { return nil }
        var bytes: [UInt8] = []
        var index = cleaned.startIndex
        while index < cleaned.endIndex {
            let next = cleaned.index(index, offsetBy: 2)
            guard let value = UInt8(cleaned[index..<next], radix: 16) else { return nil }
            bytes.append(value)
            index = next
        }
        return bytes
    }

    private nonisolated static func hex(_ bytes: [UInt8]) -> String {
        bytes.map { String(format: "%02x", $0) }.joined()
    }

    private nonisolated static func documentsRelativePath(for url: URL) -> String {
        guard let documents = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first else {
            return url.lastPathComponent
        }
        let documentPath = documents.standardizedFileURL.path
        let filePath = url.standardizedFileURL.path
        if filePath == documentPath { return "Documents" }
        if filePath.hasPrefix(documentPath + "/") {
            return "Documents/" + String(filePath.dropFirst(documentPath.count + 1))
        }
        return url.lastPathComponent
    }

    private static func packetKind(_ type: UInt8) -> String {
        switch type {
        case Packet.command: return "command"
        case 0x24: return "command_response"
        case Packet.realtime: return "realtime"
        case Packet.realtimeRaw: return "realtime_raw_r10_r11"
        case Packet.historical: return "historical"
        case 0x30: return "event"
        case Packet.metadata: return "metadata"
        case 0x32: return "diagnostic"
        case Packet.imu: return "imu"
        default: return String(format: "unknown_%02x", type)
        }
    }

    private static func printableRuns(in bytes: [UInt8], minimumLength: Int = 4) -> [String] {
        var runs: [String] = []
        var current: [UInt8] = []
        func flush() {
            defer { current.removeAll() }
            guard current.count >= minimumLength,
                  let string = String(bytes: current, encoding: .utf8)?
                    .trimmingCharacters(in: .whitespacesAndNewlines),
                  !string.isEmpty else { return }
            runs.append(string)
        }
        for byte in bytes {
            if byte == 0x0a || byte == 0x0d || (byte >= 0x20 && byte <= 0x7e) {
                current.append(byte)
            } else {
                flush()
            }
        }
        flush()
        return runs
    }

    private static func firstRegexCapture(_ pattern: String, in text: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else {
            return nil
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        guard let match = regex.firstMatch(in: text, range: range),
              match.numberOfRanges > 1,
              let captureRange = Range(match.range(at: 1), in: text) else {
            return nil
        }
        return String(text[captureRange])
    }

    private static func diagnosticSleepMotionHint(from text: String) -> (kind: String, motionShort: String, stateFrom: String, stateTo: String)? {
        let upper = text.uppercased()
        let mentionsSleepFlag = upper.contains("SLEEPFLAG") || upper.contains("LEEPFLAG")
        let mentionsMotion = upper.contains("MOTION_SHORT")
        let mentionsDeepSleep = upper.contains("DEEPSLEEP")
        guard mentionsSleepFlag || mentionsMotion || mentionsDeepSleep else { return nil }

        let stateFrom = firstRegexCapture("from state '([A-Z_]+)'", in: text) ?? "unknown"
        let stateTo = firstRegexCapture("to '([A-Z_]+)'", in: text) ?? "unknown"
        let motionShort = firstRegexCapture("motion_short\\s*=\\s*([0-9]+(?:\\.[0-9]+)?)", in: text) ?? "learning"
        let kind: String
        if mentionsSleepFlag {
            kind = "sleepflag"
        } else if mentionsMotion {
            kind = "motion_short"
        } else {
            kind = "deepsleep"
        }
        return (kind, motionShort, stateFrom, stateTo)
    }

    private static func formatDouble(_ value: Double?) -> String {
        value.map { String(format: "%.3f", $0) } ?? "learning"
    }

    private static func formatKindCounts(_ counts: [String: Int]) -> String {
        let parts = counts.keys.sorted().map { key in
            "\(key):\(counts[key] ?? 0)"
        }
        return parts.isEmpty ? "none" : parts.joined(separator: ",")
    }

    private nonisolated static func u16le(_ bytes: [UInt8], _ offset: Int) -> UInt16 {
        guard offset + 1 < bytes.count else { return 0 }
        return UInt16(bytes[offset]) | (UInt16(bytes[offset + 1]) << 8)
    }

    private nonisolated static func u32le(_ bytes: [UInt8], _ offset: Int) -> UInt32 {
        guard offset + 3 < bytes.count else { return 0 }
        return UInt32(bytes[offset])
            | (UInt32(bytes[offset + 1]) << 8)
            | (UInt32(bytes[offset + 2]) << 16)
            | (UInt32(bytes[offset + 3]) << 24)
    }

    private static func le32(_ value: UInt32) -> [UInt8] {
        [
            UInt8(value & 0xff),
            UInt8((value >> 8) & 0xff),
            UInt8((value >> 16) & 0xff),
            UInt8((value >> 24) & 0xff),
        ]
    }

    private static func unixCandidateLabel(_ value: UInt32) -> String {
        guard value >= 1_500_000_000 && value <= 2_200_000_000 else { return "" }
        return String(format: ":unix:%@", Date(timeIntervalSince1970: TimeInterval(value)).ISO8601Format())
    }

    private func logDataRangeCommandResponse(_ payload: [UInt8]) {
        guard payload.count >= 3, payload[0] == 0x24, payload[2] == 0x22 else { return }
        let seq = payload[1]
        let status = Array(payload.dropFirst(3))
        let body = status.count >= 3 ? Array(status.dropFirst(3)) : []
        let request = historyDataRangePendingRequests.isEmpty
            ? nil
            : historyDataRangePendingRequests.removeFirst()
        let cursorRange = AtriaWhoop4HistoryCursorRange.parseCommandResponse(payload)
        let matchesProductionRequest = offlineHistoricalSyncInProgress
            && cursorRange?.requestSequenceEcho
                == pendingHistoryDataRangeCommandSequence
        if matchesProductionRequest {
            acceptedHistoryDataRange = cursorRange
            acceptedHistoryDataRangeResponseAtUnix = Date().timeIntervalSince1970
            acceptedHistoryDataRangeResponseUptime = ProcessInfo.processInfo.systemUptime
        }
        var u32Pairs: [String] = []
        if body.count >= 4 {
            for offset in stride(from: 0, through: body.count - 4, by: 2) {
                let value = Self.u32le(body, offset)
                u32Pairs.append("\(offset):\(value)\(Self.unixCandidateLabel(value))")
            }
        }
        var u16Pairs: [String] = []
        if body.count >= 2 {
            for offset in stride(from: 0, through: body.count - 2, by: 2) {
                u16Pairs.append("\(offset):\(Self.u16le(body, offset))")
            }
        }
        AtriaDebugLog("ATRIADBG data_range_response validated=%d seq=%d request_index=%d request_data=%@ status_len=%d lead=%@ body_len=%d u32=%@ u16=%@ last_realtime_unix=%@ device_unix=%.0f status=%@",
              matchesProductionRequest ? 1 : 0,
              Int(seq),
              request?.index ?? -1,
              request.map { Self.hex($0.data) } ?? "unknown",
              status.count,
              Self.hex(Array(status.prefix(3))),
              body.count,
              u32Pairs.joined(separator: ","),
              u16Pairs.joined(separator: ","),
              lastRealtimeUnix.map(String.init) ?? "none",
              Date().timeIntervalSince1970,
              Self.hex(status))
        if let cursorRange {
            recordFlushDebt(pendingRecords: cursorRange.pendingRecords)
            AtriaDebugLog("ATRIADBG historyRange status=observed response_seq=%d request_seq_echo=%d matched=%d write=%u read=%u capacity=%u pending=%u mutation=0 payload=%@",
                          Int(cursorRange.responseSequence),
                          Int(cursorRange.requestSequenceEcho),
                          matchesProductionRequest ? 1 : 0,
                          cursorRange.writeCursor,
                          cursorRange.readCursor,
                          cursorRange.capacity,
                          cursorRange.pendingRecords,
                          Self.hex(payload))
        } else {
            AtriaDebugLog("ATRIADBG historyRange status=unparsed mutation=0 payload=%@",
                          Self.hex(payload))
        }
        maybeSendHistorySelectorSweep(body: body,
                                      requestIndex: request?.index,
                                      requestData: request?.data)
    }

    private func handleCommandResponsePayload(
        _ payload: [UInt8],
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        guard payload.first == 0x24 else { return }
        handleProprietaryBatteryCommandResponse(payload)
        handleReadOnlyHistoryRangeResponse(payload)
        handleOneShotHistoryTrimCommandResponse(payload)
        // A read-only clock probe intentionally owns no production drain
        // generation. Correlate its echoed command sequence before applying
        // the stricter production-history generation gate below.
        logClockCommandResponse(payload)
        guard let generation = activeHistoricalGeneration(for: historyPhase) else { return }
        handleHistoricalACKCommandResponse(payload, generation: generation)
        handleProductionHistoryReadPreflightResponse(payload, generation: generation)
        logDataRangeCommandResponse(payload)
    }

    private func handleOneShotHistoryTrimCommandResponse(_ payload: [UInt8]) {
        guard oneShotHistoryTrimRequested,
              readOnlyHistoryCaptureActive,
              payload.count >= 4,
              payload[0] == 0x24,
              payload[2]
                == AtriaWhoop4SacrificialHistoryTrimPolicy.forceTrim.opcode,
              let expected = oneShotHistoryTrimCommandSequence,
              payload[3] == expected else { return }
        oneShotHistoryTrimCommandResponseMatched = true
        try? readOnlyHistoryCaptureStore?.append(
            event: "force_trim_response_matched",
            payload: payload,
            fields: ["request_sequence_echo": expected]
        )
        AtriaDebugLog(
            "ATRIADBG sacrificial_history_trim status=logical_response_matched sequence=%d retry=0",
            Int(expected)
        )
    }

    private func handleReadOnlyHistoryRangeResponse(_ payload: [UInt8]) {
        guard readOnlyHistoryCaptureActive,
              let expected = readOnlyHistoryRangeSequence,
              let range = AtriaWhoop4HistoryCursorRange.parseCommandResponse(payload),
              range.requestSequenceEcho == expected else { return }
        readOnlyHistoryRangeResponse = range
        readOnlyHistoryRangeResponseAt = Date()
        try? readOnlyHistoryCaptureStore?.append(
            event: "range_response_raw",
            payload: payload,
            fields: ["request_sequence_echo": expected]
        )
        AtriaDebugLog("ATRIADBG readOnlyHistory status=range_response_matched sequence=%d pending=%u mutation=0",
                      Int(expected),
                      range.pendingRecords)
    }

    private func logClockCommandResponse(_ payload: [UInt8]) {
        // WHOOP command responses carry two different sequence values:
        // [0x24, responseSequence, command, requestSequenceEcho, data...].
        // Only the echoed request sequence can bind a response to this
        // generation's command; the strap-owned response sequence is unrelated.
        guard payload.count >= 4, payload[0] == 0x24 else { return }
        let responseSequence = payload[1]
        let cmd = payload[2]
        let requestSequenceEcho = payload[3]
        guard cmd == Cmd.setClock || cmd == Cmd.getClock else { return }
        let status = Array(payload.dropFirst(3))
        var u32Pairs: [String] = []
        for offset in stride(from: 3, through: max(3, payload.count - 4), by: 1) {
            guard offset + 3 < payload.count else { continue }
            let value = Self.u32le(payload, offset)
            u32Pairs.append("\(offset):\(value)\(Self.unixCandidateLabel(value))")
        }
        if cmd == Cmd.getClock, payload.count >= 7 {
            let wall = UInt32(Date().timeIntervalSince1970)
            let plausibleClockValues = stride(
                from: 3,
                through: max(3, payload.count - 4),
                by: 1
            ).compactMap { offset -> UInt32? in
                guard offset + 3 < payload.count else { return nil }
                let value = Self.u32le(payload, offset)
                return value > 0
                    && abs(Int64(wall) - Int64(value)) <= 24 * 60 * 60
                    ? value : nil
            }
            let uniqueClocks = Set(plausibleClockValues)
            let device = uniqueClocks.count == 1 ? uniqueClocks.first! : 0
            let matchingReadOnlyProbe =
                readOnlyClockProbeRequested
                && readOnlyClockProbeIssued
                && readOnlyClockProbeSequence == requestSequenceEcho
                && device > 0
                && uniqueClocks.count == 1
            let matchingProductionRequest = offlineHistoricalSyncInProgress
                && pendingHistoryClockCommandSequence == requestSequenceEcho
                && device > 0
                && uniqueClocks.count == 1
            if matchingReadOnlyProbe {
                let defaults = UserDefaults.standard
                defaults.set(
                    Int(device),
                    forKey: "atria.diagnostic.readOnlyClock.deviceUnix"
                )
                defaults.set(
                    Int(wall),
                    forKey: "atria.diagnostic.readOnlyClock.wallUnix"
                )
                defaults.set(
                    Int(wall) - Int(device),
                    forKey: "atria.diagnostic.readOnlyClock.driftSeconds"
                )
                defaults.set(
                    Date().timeIntervalSince1970,
                    forKey: "atria.diagnostic.readOnlyClock.responseAt"
                )
                defaults.set(
                    Self.hex(payload),
                    forKey: "atria.diagnostic.readOnlyClock.responsePayload"
                )
                defaults.set(
                    "matched",
                    forKey: "atria.diagnostic.readOnlyClock.status"
                )
                readOnlyClockProbeRequested = false
                readOnlyClockProbeSequence = nil
                _ = historyTransportPhaseFence.deactivate(ifMatching: 0)
                historyOnlyProbeEnabled = false
                reassertHeartRateNotificationsIfConnected(
                    reason: "read_only_clock_complete"
                )
            }
            if matchingProductionRequest {
                historyClockRef = HistoryClockRef(device: device, wall: wall)
                acceptedHistoryClockResponseSequence = requestSequenceEcho
                acceptedHistoryClockDeviceUnix = device
                acceptedHistoryClockWallUnix = wall
                acceptedHistoryClockResponseAtUnix = Date().timeIntervalSince1970
            }
            let drift = Int(wall) - Int(device)
            let stale = abs(drift) >= 86_400
            AtriaDebugLog("ATRIADBG historyClock status=get_clock_response response_seq=%d request_seq_echo=%d device=%u wall=%u drift_s=%d stale=%d authority=%d read_only_probe=%d sane_candidates=%d status_len=%d u32=%@ payload=%@",
                  Int(responseSequence),
                  Int(requestSequenceEcho),
                  device,
                  wall,
                  drift,
                  stale ? 1 : 0,
                  matchingProductionRequest ? 1 : 0,
                  matchingReadOnlyProbe ? 1 : 0,
                  uniqueClocks.count,
                  status.count,
                  u32Pairs.joined(separator: ","),
                  Self.hex(payload))
        } else {
            AtriaDebugLog("ATRIADBG historyClock status=set_clock_response response_seq=%d request_seq_echo=%d status_len=%d u32=%@ payload=%@",
                  Int(responseSequence),
                  Int(requestSequenceEcho),
                  status.count,
                  u32Pairs.joined(separator: ","),
                  Self.hex(payload))
        }
    }

    private func maybeSendHistorySelectorSweep(body: [UInt8], requestIndex: Int?, requestData: [UInt8]?) {
        guard historySelectorSweepEnabled, !historySelectorSweepSent else { return }
        if let requiredIndex = historySelectorRangeIndex,
           requestIndex != requiredIndex {
            AtriaDebugLog("ATRIADBG historySelector validated=0 status=skip reason=range_index_mismatch required=%d request_index=%d request_data=%@ mode=%@",
                  requiredIndex,
                  requestIndex ?? -1,
                  requestData.map { Self.hex($0) } ?? "unknown",
                  historySelectorMode)
            return
        }
        guard let target = closestDataRangeUnixCandidate(body: body) else {
            AtriaDebugLog("ATRIADBG historySelector validated=0 status=skip reason=no_live_unix_candidate request_index=%d request_data=%@ mode=%@",
                  requestIndex ?? -1,
                  requestData.map { Self.hex($0) } ?? "unknown",
                  historySelectorMode)
            return
        }
        historySelectorSweepSent = true
        let live = lastRealtimeUnix
        let delta = live.map { Int64(target.value) - Int64($0) } ?? 0
        let selectors = historySelectors(for: target.value, body: body)
        AtriaDebugLog("ATRIADBG historySelector validated=0 status=scheduled mode=%@ source=cmd22 request_index=%d request_data=%@ offset=%d value=%u live_unix=%@ delta_s=%lld variants=%d",
              historySelectorMode,
              requestIndex ?? -1,
              requestData.map { Self.hex($0) } ?? "unknown",
              target.offset,
              target.value,
              live.map(String.init) ?? "none",
              delta,
              selectors.count)
        Task { @MainActor in
            for (index, selector) in selectors.enumerated() {
                AtriaDebugLog("ATRIADBG historySelector validated=0 step=%d send cmd=21 label=%@ source=cmd22 offset=%d value=%u data=%@ mode=%@",
                      index,
                      selector.label,
                      target.offset,
                      target.value,
                      Self.hex(selector.data),
                      probeCommandMode.rawValue)
                sendCommand(0x21, selector.data, mode: probeCommandMode)
                try? await Task.sleep(for: .seconds(5))
                AtriaDebugLog("ATRIADBG historySelector validated=0 step=%d send cmd=16 label=%@ data=00 mode=%@",
                      index,
                      selector.label,
                      probeCommandMode.rawValue)
                sendCommand(0x16, [0x00], mode: probeCommandMode)
                if index < selectors.count - 1 {
                    try? await Task.sleep(for: .seconds(25))
                }
            }
        }
    }

    private func closestDataRangeUnixCandidate(body: [UInt8]) -> (offset: Int, value: UInt32)? {
        guard body.count >= 4 else { return nil }
        let reference = lastRealtimeUnix ?? UInt32(Date().timeIntervalSince1970)
        var best: (offset: Int, value: UInt32, delta: UInt32)?
        for offset in stride(from: 0, through: body.count - 4, by: 2) {
            let value = Self.u32le(body, offset)
            guard value >= 1_500_000_000 && value <= 2_200_000_000 else { continue }
            let delta = value > reference ? value - reference : reference - value
            guard delta <= 86_400 * 14 else { continue }
            if best == nil || delta < best!.delta {
                best = (offset, value, delta)
            }
        }
        return best.map { ($0.offset, $0.value) }
    }

    private func historyRecord(body: [UInt8], offset: Int, length: Int) -> [UInt8]? {
        guard offset >= 0, length > 0, offset + length <= body.count else { return nil }
        return Array(body[offset..<(offset + length)])
    }

    private func historySelectors(for unix: UInt32, body: [UInt8]) -> [(label: String, data: [UInt8])] {
        let bare = Self.le32(unix)
        let currentRecord = historyRecord(body: body, offset: 56, length: 8)
        let knownBlockRecord = historyRecord(body: body, offset: 40, length: 8)
        let rangeWindow = historyRecord(body: body, offset: 40, length: 24)
        switch historySelectorMode {
        case "current-unix-prefix0":
            return [("current_unix_prefix0", [0x00] + bare)]
        case "current-unix-prefix1":
            return [("current_unix_prefix1", [0x01] + bare)]
        case "current-unix-all":
            return [
                ("current_unix_bare", bare),
                ("current_unix_prefix0", [0x00] + bare),
                ("current_unix_prefix1", [0x01] + bare),
            ]
        case "current-record8":
            return currentRecord.map { [("current_record8", $0)] } ?? []
        case "known-block-record8":
            return knownBlockRecord.map { [("known_block_record8", $0)] } ?? []
        case "range-window24":
            return rangeWindow.map { [("range_window24", $0)] } ?? []
        case "record-shape-all":
            var selectors: [(label: String, data: [UInt8])] = []
            if let knownBlockRecord {
                selectors.append(("known_block_record8", knownBlockRecord))
            }
            if let currentRecord {
                selectors.append(("current_record8", currentRecord))
            }
            if let rangeWindow {
                selectors.append(("range_window24", rangeWindow))
            }
            return selectors
        default:
            return [("current_unix_bare", bare)]
        }
    }

    private func stableContactSeconds(now: Date = Date()) -> TimeInterval {
        guard hasContact, let contactStableSince else { return 0 }
        return now.timeIntervalSince(contactStableSince)
    }

    private func resetHRVWindow(reason: String) {
        hrvLiveRefreshGeneration &+= 1
        hrvLiveRefreshTask?.cancel()
        hrvLiveRefreshTask = nil
        lastHRVAnalysisAttemptAt = nil
        resetRRBuffer()
        rrSamples = 0
        hrv = 0
        assignIfChanged(\.hrvSnapshot, nil)
        tachogram.removeAll(keepingCapacity: true)
        assignIfChanged(\.hrvQuality, reason)
        hrvGateWasOpen = false
        if isRecording {
            captureCleanWindowStart = Date()
        }
        logRow(kind: "hrv_quality", source: "app", opcode: "", len: "", value: reason)
    }

    private func shouldRefreshHRVSnapshot(now: Date, force: Bool = false) -> Bool {
        if powerThermalGovernor.shouldSuspendNonEssentialWork && !force {
            return false
        }
        guard !force else { return true }
        let window = currentRRBufferWindow()
        let cleanWindowSeconds = window.first.map { max(0, now.timeIntervalSince($0.t)) } ?? 0
        return Self.shouldAttemptHRVAnalysis(
            now: now,
            lastReadyAnalysisAt: lastHRVAnalysisAt,
            lastAttemptAt: isRecording
                ? lastHRVAnalysisAttemptAt
                : lastNormalWearHRVAnalysisAttemptAt,
            isRecording: isRecording,
            hasReadySnapshot: latestReadyHRVSnapshot?.isReady == true || hrvSnapshot?.isReady == true,
            cleanWindowSeconds: cleanWindowSeconds,
            latestRRSampleAt: window.last?.t,
            foregroundInteractive: foregroundInteractiveMode
        )
    }

    private var shouldMaintainLiveTachogram: Bool {
        foregroundInteractiveMode && isRecording
    }

