    private var realtimeRetry: Task<Void, Never>?
    private var realtimeRestartTask: Task<Void, Never>?
    private var r10ArmRetryTask: Task<Void, Never>?
    private var r10LivenessTask: Task<Void, Never>?
    private var lastR10RecoveryRearmAt: Date?
    private var lastR10RecoveryRediscoveryAt: Date?
    private var lastR10NotifyRepairAt: Date?
    nonisolated static let r10RecoveryRediscoveryMinimumInterval: TimeInterval = 60
    nonisolated static let r10LivenessStaleInterval: TimeInterval = 60
    nonisolated static let r10LivenessRearmGraceInterval: TimeInterval = 60
    nonisolated static let r10LivenessRearmMinimumInterval: TimeInterval = 10 * 60
    nonisolated static let r10NotifyRepairMinimumInterval: TimeInterval = 30
    private var lastRRBearingRealtimeFrameAt: Date?
    private var lastRealtimeRestartAt: Date?
    private var ackedHistoryAckKeys = Set<String>()
    private var rrContinuityWindow: [(t: Date, hasRR: Bool, source: String)] = []
    private var rrContinuityWindowHead = 0
    private var lastRRContinuityPublishAt: Date?
    private var lastRRContinuityLogAt: Date?
    private var lastRRContinuityLogState = ""
    private var realtimePacketBatchDepth = 0
    private var realtimeBatchPendingRRContinuityAt: Date?
    private var realtimeBatchPendingAutoCaptureAt: Date?
    private var realtimeBatchPendingConsistencyAt: Date?
    private var realtimeBatchPendingRestart: (now: Date, rrnum: Int)?
    private var realtimeBatchPendingHistorySweepUnix: UInt32?
    private var proprietaryNotifyFallbackTask: Task<Void, Never>?
    private var activeProprietaryNotifyUUIDs = Set<CBUUID>()
    private var strapStream5NotifyConfirmed = false

    /// A cached frame from immediately before a rediscovery/reconnect cannot
    /// prove that the newly armed R10 stream is alive. Requiring the frame to
    /// post-date the current arm prevents the retry loop from accepting stale
    /// motion while HR continues normally and steps remain frozen indefinitely.
    nonisolated static func r10FrameConfirmsCurrentArm(lastFrameAt: Date?,
                                                       armSentAt: Date,
                                                       now: Date,
                                                       maximumAge: TimeInterval = 5) -> Bool {
        guard let lastFrameAt,
              lastFrameAt >= armSentAt,
              now.timeIntervalSince(lastFrameAt) >= 0,
              now.timeIntervalSince(lastFrameAt) <= maximumAge else {
            return false
        }
        return true
    }

    /// Once a decoded R10 frame post-dates this arm command, the arm itself
    /// succeeded. Ongoing freshness is owned by the liveness watchdog.
    nonisolated static func r10FrameProvesCurrentArm(lastFrameAt: Date?,
                                                     evidenceEpoch: Date,
                                                     now: Date = Date()) -> Bool {
        guard let lastFrameAt else { return false }
        return lastFrameAt >= evidenceEpoch && lastFrameAt <= now
    }

    enum R10LivenessAction: Equatable {
        case none
        case rearm
        case rediscover
    }

    /// Pure policy used by the persistent R10 watchdog. Heart-rate continuity
    /// is deliberately absent: 2A37 can remain healthy while proprietary motion
    /// is frozen, which is the failure this policy must detect independently.
    nonisolated static func r10LivenessAction(
        eligible: Bool,
        connected: Bool,
        realtimeArmed: Bool,
        lastFrameAt: Date?,
        lastRearmAt: Date?,
        lastRediscoveryAt: Date?,
        now: Date,
        staleInterval: TimeInterval = r10LivenessStaleInterval,
        rearmGraceInterval: TimeInterval = r10LivenessRearmGraceInterval,
        rearmMinimumInterval: TimeInterval = r10LivenessRearmMinimumInterval,
        rediscoveryMinimumInterval: TimeInterval = r10RecoveryRediscoveryMinimumInterval
    ) -> R10LivenessAction {
        guard eligible, connected, realtimeArmed else { return .none }
        if let lastFrameAt,
           now.timeIntervalSince(lastFrameAt) >= 0,
           now.timeIntervalSince(lastFrameAt) <= staleInterval {
            return .none
        }
        guard let lastRearmAt else { return .rearm }
        let rearmAge = now.timeIntervalSince(lastRearmAt)
        if rearmAge >= rearmMinimumInterval { return .rearm }
        guard rearmAge >= rearmGraceInterval else { return .none }
        if let lastRediscoveryAt,
           now.timeIntervalSince(lastRediscoveryAt) < rediscoveryMinimumInterval {
            return .none
        }
        return .rediscover
    }

    /// A fallback transport may keep 2A37 heart-rate healthy after the dense
    /// R10 stream has been deliberately withdrawn.  That is a valid safety
    /// state, but an all-day/workout lease must not retain a durable `live`
    /// coverage claim from the last dense epoch.  This is only an accounting
    /// decision: it neither re-enables a CCCD nor reconnects the strap.
    nonisolated static func shouldOpenWorkoutMotionGapForUnavailableR10(
        motionLeaseHeld: Bool,
        historyOwnsTransport: Bool,
        r10TransportExpected: Bool,
        lastFrameAt: Date?,
        now: Date,
        staleInterval: TimeInterval = AtriaDailyStepPresentation.liveEvidenceMaximumAge
    ) -> Bool {
        guard motionLeaseHeld,
              !historyOwnsTransport,
              !r10TransportExpected,
              staleInterval > 0 else { return false }
        guard let lastFrameAt else { return true }
        let age = now.timeIntervalSince(lastFrameAt)
        return age > staleInterval
    }

    nonisolated static func shouldRepairR10Notification(
        expected: Bool,
        connected: Bool,
        isNotifying: Bool,
        lastRepairAt: Date?,
        now: Date,
        minimumInterval: TimeInterval = r10NotifyRepairMinimumInterval
    ) -> Bool {
        guard expected, connected, !isNotifying else { return false }
        guard let lastRepairAt else { return true }
        return now.timeIntervalSince(lastRepairAt) >= minimumInterval
    }

    /// The protected R10 transport blocks experimental/maintenance writes by
    /// default. A user-started workout haptic is the sole narrow exception: it
    /// is bounded to real zone transitions and is never a periodic probe.
    nonisolated static func shouldAllowProtectedTransportCommand(
        command: UInt8,
        standardHROnlyMode: Bool,
        historyOnlyProbeEnabled: Bool,
        explicitWorkoutHaptic: Bool,
        onboardingPairingPreflight: Bool = false
    ) -> Bool {
        !standardHROnlyMode
            || historyOnlyProbeEnabled
            || (explicitWorkoutHaptic && command == Cmd.runHapticsPattern)
            || (onboardingPairingPreflight && command == Cmd.getDataRange)
    }

    /// Send a COMMAND packet on CMD_TO_STRAP: [0x23, seq, cmd, data...].
    /// Returns true only after CoreBluetooth accepted a supported write path,
    /// so callers never report a blocked command as sent.
    @discardableResult
    private func sendCommand(_ cmd: UInt8,
                             _ data: [UInt8],
                             mode: CommandWriteMode,
                             explicitWorkoutHaptic: Bool = false,
                             onboardingPairingPreflight: Bool = false) -> Bool {
        var authorizedFastDrainSession:
            AtriaWhoop4SacrificialFastDrainPolicy.Session?
        if sacrificialFastDrainRequested {
            guard var candidate = sacrificialFastDrainSession else {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_fast_drain status=write_blocked command=%02x reason=missing_policy_session",
                    cmd
                )
                return false
            }
            do {
                try candidate.authorize(.init(opcode: cmd, payload: data))
                authorizedFastDrainSession = candidate
            } catch {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_fast_drain status=write_blocked command=%02x payload=%@ phase=%@ reason=%@",
                    cmd,
                    Self.hex(data),
                    String(describing: candidate.phase),
                    String(describing: error)
                )
                return false
            }
        } else if oneShotHistoryTrimRequested {
            let command =
                AtriaWhoop4SacrificialHistoryTrimPolicy.Command(
                    opcode: cmd,
                    payload: data
                )
            guard (try? AtriaWhoop4SacrificialHistoryTrimPolicy.authorize(
                command: command,
                in: oneShotHistoryTrimPhase
            )) != nil else {
                AtriaDebugLog(
                    "ATRIADBG sacrificial_history_trim status=write_blocked command=%02x payload=%@ phase=%@ reason=outside_exact_single_use_trace",
                    cmd,
                    Self.hex(data),
                    String(describing: oneShotHistoryTrimPhase)
                )
                return false
            }
        } else if readOnlyHistoryCaptureRequested {
            let allowed: Bool
            if readOnlyExactRangeCaptureRequested,
               let exactPayload = readOnlyExactRangePayload {
                allowed = AtriaBLEReadOnlyExactRangeCapturePolicy.allows(
                    opcode: cmd,
                    payload: data,
                    exactPayload: exactPayload
                )
            } else {
                allowed = AtriaBLEReadOnlyHistoryCapturePolicy.allows(
                    opcode: cmd,
                    payload: data
                )
            }
            guard allowed else {
                AtriaDebugLog("ATRIADBG readOnlyHistory status=write_blocked command=%02x payload=%@ reason=outside_exact_allowlist action=no_write",
                              cmd,
                              Self.hex(data))
                return false
            }
        }
        guard motionHandshakeDiagnostic == nil else {
            recordMotionHandshakeEvidence(event: "proprietary_tx_blocked",
                                          detail: String(format: "cmd_%02x", cmd))
            return false
        }
        guard Self.shouldAllowProtectedTransportCommand(
            command: cmd,
            standardHROnlyMode: standardHROnlyMode,
            historyOnlyProbeEnabled: historyOnlyProbeEnabled,
            explicitWorkoutHaptic: explicitWorkoutHaptic,
            onboardingPairingPreflight: onboardingPairingPreflight
        ) else {
            incrementRadioCounter(RadioDefaults.realtimeStartSkipped, reason: "standard_hr_only_write_blocked")
            AtriaDebugLog("ATRIADBG writeSkip mode=%@ reason=standard_hr_only_no_strap_writes cmd=%02x",
                  mode.rawValue, cmd)
            dbgWrite = "standard hr only blocked"
            return false
        }
        if offlineHistoricalSyncInProgress,
           activeConnectedRealtimePreservingHistoryAuthorityExists(
            generation: offlineHistoricalSyncGeneration
           ) {
            guard let current = peripheral,
                  activeConnectedRealtimePreservingHistoryAuthorityIsValid(
                    generation: offlineHistoricalSyncGeneration,
                    peripheral: current
                  ) else {
                _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                    generation: offlineHistoricalSyncGeneration,
                    reason:
                        "exact_connected_history_authority_lost_before_command"
                )
                return false
            }
        }
        guard let tx = txCharacteristic, let p = peripheral else { return false }
        let payload = [Packet.command, cmdSeq, cmd] + data
        let seq = cmdSeq
        cmdSeq &+= 1
        let frame = encodeFrame(payload)
        let hex = frame.map { String(format: "%02x", $0) }.joined()
        AtriaDebugLog("ATRIADBG send mode=%@ cmd=%02x seq=%d to=%@ props=%lu frame=%@",
              mode.rawValue, cmd, Int(seq), tx.uuid.uuidString, tx.properties.rawValue, hex)
        switch mode {
        case .withoutResponse:
            guard tx.properties.contains(.writeWithoutResponse) else {
                AtriaDebugLog("ATRIADBG writeSkip mode=wwr reason=unsupported props=%lu", tx.properties.rawValue)
                dbgWrite = "wwr unsupported"
                return false
            }
            p.writeValue(frame, for: tx, type: .withoutResponse)
        case .withResponse:
            guard tx.properties.contains(.write) else {
                AtriaDebugLog("ATRIADBG writeSkip mode=wr reason=unsupported props=%lu", tx.properties.rawValue)
                dbgWrite = "wr unsupported"
                return false
            }
            guard writeCompletionLedger.enqueue(sequence: seq,
                                                 command: cmd,
                                                 payload: data) else {
                AtriaDebugLog("ATRIADBG writeSkip mode=wr reason=single_flight_pending cmd=%02x seq=%d pending=%@ action=await_exact_callback",
                              cmd,
                              Int(seq),
                              writeCompletionLedger.pending.first.map {
                                  String(format: "%02x/%d", $0.command, Int($0.sequence))
                              } ?? "unknown")
                dbgWrite = "wr single-flight pending"
                return false
            }
            p.writeValue(frame, for: tx, type: .withResponse)
        }
        if let authorizedFastDrainSession {
            sacrificialFastDrainSession = authorizedFastDrainSession
        }
        dbgWriteMode = mode.rawValue
        dbgWrite = mode == .withoutResponse ? "sent" : "pending"
        dbgCmdSends += 1
        return true
    }

    /// Sends one history WR command and does not return success until the exact
    /// ledger entry has received its CoreBluetooth callback. The ledger itself
    /// rejects a second outstanding WR, so a late callback can never be
    /// reinterpreted as confirmation for a newer command.
    private func closeWorkoutHistoricalMotionBankForHistoryServeCutover(
        generation: UInt64,
        peripheral: CBPeripheral
    ) {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation,
              self.peripheral === peripheral else { return }
        let defaults = UserDefaults.standard
        let wasArmed = Self
            .historicalMotionBankIsArmedForCurrentConnection(
                armed: workoutHistoricalMotionBankArmed,
                armedConnectionStartedAt:
                    workoutHistoricalMotionBankArmedConnectionStartedAt,
                currentConnectionStartedAt: connectedAt
            )
        if wasArmed {
            let cutoverTicket =
                AtriaWhoop4MotionBankCoverageLedger.close(
                at: Date(),
                strapIdentifier: peripheral.identifier.uuidString,
                armedConnectionStartedAt:
                    workoutHistoricalMotionBankArmedConnectionStartedAt
                        ?? connectedAt,
                recoveryMode: .awaitingGlobalFrontier
            )
            if let cutoverTicket {
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank_offload status=frontier_ticket_created ticket=%@ generation=%llu action=exclude_generic_selector_resolve_from_compact_global_fifo",
                    cutoverTicket.id,
                    generation
                )
            }
        }
        // WHOOP 4's accepted 16/00 takes the proprietary owner and closes 0x69
        // in firmware. Mirror that boundary synchronously even if our cached
        // bit was stale: retaining `enabled=true` would make every later rearm
        // helper no-op while the coverage ledger falsely accrued time.
        let cutoverState = Self
            .historicalMotionBankStateAfterHistoryServeCutover()
        workoutHistoricalMotionBankArmed = cutoverState.processArmed
        workoutHistoricalMotionBankArmedConnectionStartedAt = nil
        defaults.set(
            cutoverState.persistedEnabled,
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        )
        defaults.set(
            cutoverState.prearmRequested,
            forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey
        )
        defaults.set(
            false,
            forKey: Self.workoutHistoricalMotionBankStopPendingKey
        )
        defaults.removeObject(
            forKey: Self.workoutHistoricalMotionBankArmedAtKey
        )
        defaults.removeObject(
            forKey: Self.workoutHistoricalMotionBankRearmNotBeforeKey
        )
        AtriaMotionBankDutyCycleDiag.note("sync_cutover")
        AtriaDebugLog(
            "ATRIADBG workout_motion_bank status=history_serve_cutover generation=%llu was_armed=%d action=close_coverage_clear_process_and_persisted_arm_retain_prearm",
            generation,
            wasArmed ? 1 : 0
        )
    }

    private func sendHistoryCommandAwaitingWriteConfirmation(
        command: UInt8,
        payload: [UInt8],
        generation: UInt64,
        timeoutAttempts: Int = AtriaBLEHistoryWriteConfirmationPolicy.maximumPollAttempts
    ) async -> AwaitedHistoryWriteResult {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else {
            return .rejected
        }
        lastProprietaryWriteCompletion = nil
        guard sendCommand(command, payload, mode: .withResponse),
              let expected = writeCompletionLedger.pending.first,
              expected.command == command,
              expected.payload == payload else {
            return .rejected
        }
        if command == Cmd.sendHistoricalData, payload == [0x00],
           let current = peripheral {
            closeWorkoutHistoricalMotionBankForHistoryServeCutover(
                generation: generation,
                peripheral: current
            )
        }
        for _ in 0..<max(1, timeoutAttempts) {
            if let completion = lastProprietaryWriteCompletion,
               completion.generation == generation,
               completion.entry == expected {
                let result = AtriaBLEReadOnlyHistoryCapturePolicy
                    .classifyWriteCompletion(
                        succeeded: completion.succeeded,
                        errorDomain: completion.errorDomain,
                        errorCode: completion.errorCode
                    )
                switch result {
                case .confirmed: return .confirmed
                case .securityRequired: return .securityRequired
                case .failed: return .failed
                case .timedOut: return .timedOut
                case .interrupted: return .failed
                }
            }
            try? await Task.sleep(
                for: .seconds(AtriaBLEHistoryWriteConfirmationPolicy.pollInterval)
            )
            guard !Task.isCancelled,
                  offlineHistoricalSyncInProgress,
                  offlineHistoricalSyncGeneration == generation else {
                return .failed
            }
        }
        return .timedOut
    }

    /// Plays a short, bounded WHOOP 4 haptic pattern for live zone coaching.
    /// Pattern 2 is the same neutral pulse used by the strap's alarm surface;
    /// `loops` maps directly to the requested one/two/three-pulse transition.
    func triggerWorkoutZoneHaptic(pulses: Int) {
        guard (1...3).contains(pulses),
              status == .connected,
              peripheral?.state == .connected,
              txCharacteristic != nil else {
            AtriaDebugLog("ATRIADBG workout_zone_haptic status=skipped pulses=%d reason=strap_not_write_ready", pulses)
            return
        }
        let sent = sendCommand(Cmd.runHapticsPattern,
                               [0x02, UInt8(pulses), 0x00, 0x00, 0x00],
                               mode: .withoutResponse,
                               explicitWorkoutHaptic: true)
        AtriaDebugLog("ATRIADBG workout_zone_haptic status=%@ pattern=2 pulses=%d transport=protected_r10_bounded",
                      sent ? "sent" : "blocked",
                      pulses)
    }

    /// Installs or updates the persisted target owned by the current explicit
    /// workout. Repeating an identical configuration preserves detector state;
    /// only a session/target/pause transition establishes a new baseline.
    func configureWorkoutZoneHaptics(workoutStartedAt: Date?,
                                     lowerTargetZone: Int?,
                                     upperTargetZone: Int?,
                                     maxHR: Int,
                                     restingHR: Int,
                                     isPaused: Bool) {
        workoutZoneHapticLifecycle.configure(
            workoutStartedAt: workoutStartedAt,
            lowerTargetZone: lowerTargetZone,
            upperTargetZone: upperTargetZone,
            maxHR: maxHR,
            restingHR: restingHR,
            isPaused: isPaused
        )
    }

    private func stopProtocolHeartbeat() {
        // WHOOP 4 does not require a periodic command-channel heartbeat. Atria
        // briefly sent the unvalidated 0x01/[0x00] command here every five
        // seconds; physical capture showed that the strap then disconnected on
        // a repeatable 16–19 second cycle. Keep the lifecycle hook so existing
        // teardown call sites remain explicit, but never write to the strap.
    }

    private func scheduleProprietaryArmFallbackIfNeeded(reason: String) {
        guard !standardHROnlyMode || historyOnlyProbeEnabled else { return }
        guard txCharacteristic != nil else { return }
        guard !strapStream5NotifyConfirmed else { return }
        guard !activeProprietaryNotifyUUIDs.isEmpty else { return }
        guard !realtimeArmed else { return }
        guard !historyOnlyProbeArmed else { return }
        guard proprietaryNotifyFallbackTask == nil else { return }
        proprietaryNotifyFallbackTask = Task { @MainActor in
            try? await Task.sleep(for: .seconds(1))
            defer { proprietaryNotifyFallbackTask = nil }
            guard !Task.isCancelled else { return }
            guard !standardHROnlyMode || historyOnlyProbeEnabled else { return }
            guard txCharacteristic != nil else { return }
            guard !strapStream5NotifyConfirmed else { return }
            guard !activeProprietaryNotifyUUIDs.isEmpty else { return }
            guard !realtimeArmed else { return }
            guard !historyOnlyProbeArmed else { return }
            AtriaDebugLog("ATRIADBG proprietary_arm_fallback status=arming reason=%@ notify_count=%d stream5_confirmed=0 history_only=%d",
                          reason,
                          activeProprietaryNotifyUUIDs.count,
                          historyOnlyProbeEnabled ? 1 : 0)
            armRealtime()
        }
    }

    private func armWhenProprietaryNotifyPairReadyIfNeeded(reason: String) -> Bool {
        guard !standardHROnlyMode || historyOnlyProbeEnabled else { return false }
        guard txCharacteristic != nil else { return false }
        guard activeProprietaryNotifyUUIDs.count >= 2 else { return false }
        guard !realtimeArmed else { return false }
        guard !historyOnlyProbeArmed else { return false }
        guard !strapStream5NotifyConfirmed else { return false }
        AtriaDebugLog("ATRIADBG proprietary_arm_fallback status=arming reason=%@ notify_count=%d stream5_confirmed=0 history_only=%d",
                      reason,
                      activeProprietaryNotifyUUIDs.count,
                      historyOnlyProbeEnabled ? 1 : 0)
        armRealtime()
        return true
    }

    private var realtimeArmed = false

    nonisolated static func shouldArmHighFrequencyMotion(batteryLevel: Int,
                                                         isCharging: Bool,
                                                         calibrationActive: Bool = false) -> Bool {
        // A physical 13% proof delivered R10 frames but dropped the BLE link
        // after roughly twelve seconds. Below the warning boundary, preserving
        // continuous HR/strain is safer than repeatedly destabilizing both
        // streams. An explicit calibration is not authority to sacrifice HR:
        // a stale seven-day calibration lease was physically observed spanning
        // multiple workouts and bypassing this gate.
        _ = calibrationActive
        return batteryLevel < 0 || isCharging || batteryLevel > lowBatteryWarningThreshold
    }

    /// The legacy boolean and the typed status can briefly disagree during
    /// CoreBluetooth restoration. Never let a stale `true` bypass the
    /// low-battery HR-protection gate unless the verified status also says the
    /// charger is actively supplying power.
    nonisolated static func hasCredibleChargingForMotion(
        isCharging: Bool,
        chargeStatus: BatteryChargeStatus
    ) -> Bool {
        isCharging && chargeStatus == .charging
    }

    private var motionEligibilityIsCharging: Bool {
        Self.hasCredibleChargingForMotion(isCharging: batteryIsCharging,
                                          chargeStatus: batteryChargeStatus)
    }

    private var stepCalibrationCaptureIsActive: Bool {
        strapStepCalibrationCaptureUntil.map { $0 > Date() } ?? false
    }

    private var r10MotionIsEligible: Bool {
        let motionBattery = motionEligibilityBatteryLevel()
        return !protectedR10StreamSuppressed
            && !standardHROnlyMode
            && !historyOnlyProbeEnabled
            && Self.shouldArmHighFrequencyMotion(
                batteryLevel: motionBattery,
                isCharging: motionEligibilityIsCharging,
                calibrationActive: stepCalibrationCaptureIsActive
            )
    }

    private var protectedR10MotionIsEligible: Bool {
        let motionBattery = motionEligibilityBatteryLevel()
        return standardHROnlyMode
            && !historyOnlyProbeEnabled
            && !historyOnlyProbeMode
            && !offlineHistoricalSyncInProgress
            && !protectedR10StreamSuppressed
            && !protectedR10RollbackEnabled
            && Self.shouldArmHighFrequencyMotion(
                batteryLevel: motionBattery,
                isCharging: motionEligibilityIsCharging,
                calibrationActive: stepCalibrationCaptureIsActive
            )
    }

    private var r10TransportIsExpected: Bool {
        r10MotionIsEligible || protectedR10MotionIsEligible
    }

    func motionEligibilityBatteryLevel(now: Date = Date()) -> Int {
        let defaults = UserDefaults.standard
        let cachedLevel = defaults.object(forKey: BatteryDefaults.level) as? Int
        let cachedAt = (defaults.object(forKey: BatteryDefaults.at) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        return Self.resolvedMotionBatteryLevel(liveLevel: batteryLevel,
                                               liveAcceptedAt: lastAcceptedBatteryLevelAt,
                                               cachedLevel: cachedLevel,
                                               cachedAt: cachedAt,
                                               now: now)
    }

    nonisolated static func resolvedMotionBatteryLevel(liveLevel: Int,
                                                       liveAcceptedAt: Date?,
                                                       cachedLevel: Int?,
                                                       cachedAt: Date?,
                                                       now: Date) -> Int {
        if (0...100).contains(liveLevel),
           batteryLevelIsFresh(lastAcceptedAt: liveAcceptedAt, now: now) {
            return liveLevel
        }
        if let cachedLevel,
           (0...100).contains(cachedLevel),
           batteryLevelIsFresh(lastAcceptedAt: cachedAt, now: now) {
            return cachedLevel
        }
        // Unknown fails open for motion. Only fresh credible low-battery truth
        // may reduce sensor detail; stale/false low values must not break steps.
        return -1
    }

    private func ensureR10LivenessWatchdog(reason: String) {
        guard r10LivenessTask == nil else { return }
        r10LivenessTask = Task { @MainActor [weak self] in
            guard let self else { return }
            AtriaDebugLog("ATRIADBG r10_watchdog status=armed reason=%@ interval_s=%.0f",
                          reason,
                          Self.r10LivenessStaleInterval)
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(Self.r10LivenessStaleInterval))
                guard !Task.isCancelled else { return }
                self.evaluateR10Liveness(now: Date(), reason: "periodic")
            }
        }
    }

    private func stopR10LivenessWatchdog(reason: String) {
        guard r10LivenessTask != nil else { return }
        r10LivenessTask?.cancel()
        r10LivenessTask = nil
        lastR10RecoveryRearmAt = nil
        lastR10NotifyRepairAt = nil
        AtriaDebugLog("ATRIADBG r10_watchdog status=stopped reason=%@", reason)
    }

    private func requestBoundedR10ActivationForSilentStream(now: Date,
                                                             reason: String) {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard r10TransportIsExpected,
              strapStream5NotifyConfirmed,
              let peripheral,
              peripheral.state == .connected,
              let stream5 = peripheral.services?
                .first(where: { $0.uuid == Self.UUIDs.strapService })?
                .characteristics?
                .first(where: { $0.uuid == Self.UUIDs.strapStream5 }),
              stream5.isNotifying else {
            reassertR10NotificationIfConnected(reason: "\(reason)_inactive_cccd", now: now)
            return
        }

        if standardHROnlyMode {
            if protectedR10CleanOwnerProofIsActive {
                sendProtectedR10ActivationIfReady()
            }
            retryProtectedR10ShortBurstIfEligible(now: now, reason: reason)
            // An already-qualified protected owner with a silent stream and an
            // active explicit workout may issue the single validated per-
            // connection activation pair through the workout motion lease. It
            // still never toggles a CCCD or resets the connection epoch.
            if workoutMotionOwnerStartedAt != nil {
                evaluateWorkoutMotionLease(now: now, reason: "\(reason)_workout_lease")
            }
            // Retired diagnostic vocabulary retained for audit continuity:
            // status=repair_scheduled mode=protected. Clean owners do not
            // schedule a CCCD repair; only the in-flight proof command gate is
            // re-evaluated above.
            AtriaDebugLog("ATRIADBG r10_watchdog status=observed mode=protected reason=%@ action=no_mid_link_cccd_or_epoch_reset",
                          reason)
            return
        }

        guard let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse),
              heartRateCharacteristic?.isNotifying == true else { return }
        let defaults = UserDefaults.standard
        let lastActivationAt = (defaults.object(
            forKey: Self.protectedR10ActivationSentAtKey
        ) as? Double).map(Date.init(timeIntervalSince1970:))
        let leaseDelay = Self.protectedR10ActivationLeaseDelay(
            lastActivationAt: lastActivationAt,
            now: now
        )
        guard leaseDelay <= 0 else {
            AtriaDebugLog("ATRIADBG r10_watchdog status=repair_deferred mode=full_protocol reason=%@ lease_remaining_s=%.0f action=preserve_hr_link",
                          reason,
                          leaseDelay)
            return
        }
        let sequence = cmdSeq
        cmdSeq &+= 1
        let frame = encodeFrame([Packet.command, sequence, Cmd.sendR10R11Realtime, 0x01])
        defaults.set(now.timeIntervalSince1970,
                     forKey: Self.protectedR10ActivationSentAtKey)
        defaults.set(defaults.integer(forKey: Self.protectedR10ActivationCountKey) + 1,
                     forKey: Self.protectedR10ActivationCountKey)
        peripheral.writeValue(frame, for: txCharacteristic, type: .withoutResponse)
        AtriaDebugLog("ATRIADBG r10_watchdog status=repair_sent mode=full_protocol reason=%@ cmd=3f data=01 seq=%d action=single_leased_write_no_reconnect",
                      reason,
                      Int(sequence))
    }

    /// One bounded, command-only retry for the observed two-frame v9 stall.
    /// This never mutates a CCCD or connection epoch and never pauses 2A37.
    /// The persisted connection stamp makes lifecycle/watchdog replays
    /// idempotent; the original density task remains the sole qualifier.
    @discardableResult
    private func retryProtectedR10ShortBurstIfEligible(now: Date, reason: String) -> Bool {
        guard !readOnlyHistoryCaptureRequested else { return false }
        guard workoutMotionOwnerStartedAt == nil else {
            AtriaDebugLog("ATRIADBG protected_r10 status=short_burst_retry_suppressed reason=%@ owner=bounded_workout_raw",
                          reason)
            return false
        }
        let defaults = UserDefaults.standard
        let retryConnectionAt = (defaults.object(
            forKey: Self.protectedR10ShortBurstRetryConnectionAtKey
        ) as? Double).map(Date.init(timeIntervalSince1970:))
        guard Self.shouldRetryProtectedR10ShortBurst(
            proofActive: protectedR10ResponseEventDataProofIsActive,
            connected: peripheral?.state == .connected,
            heartRateNotifying: heartRateCharacteristic?.isNotifying == true,
            priorPhysicalQualification: defaults.object(
                forKey: Self.protectedR10StableTransportQualifiedAtKey
            ) != nil,
            framesAfterActivation: protectedR10FramesAfterActivation,
            lastFrameAge: lastR10MotionFrameAt.map { now.timeIntervalSince($0) },
            connectedAt: connectedAt,
            retryConnectionAt: retryConnectionAt
        ), let connectedAt,
           let peripheral,
           let txCharacteristic,
           txCharacteristic.properties.contains(.writeWithoutResponse),
           protectedR10CommandSequenceTask == nil else { return false }

        // Persist before the async write so foreground/background and periodic
        // watchdog races cannot spend a second retry on this connection.
        defaults.set(connectedAt.timeIntervalSince1970,
                     forKey: Self.protectedR10ShortBurstRetryConnectionAtKey)
        defaults.set("short_burst_retry_started", forKey: RadioDefaults.passiveR10Status)
        // Give the retry its own complete density window. Keeping the original
        // deadline would leave fewer than 75 possible 1 Hz records after the
        // stale decision, making successful qualification unreachable.
        protectedR10StabilityTask?.cancel()
        protectedR10StabilityTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.protectedR10EarlyDisconnectWindow))
            guard let self, !Task.isCancelled,
                  self.protectedR10ResponseEventDataProofIsActive,
                  self.peripheral?.state == .connected else { return }
            let verifiedAt = Date()
            guard Self.protectedR10StabilityWindowIsProven(
                framesAfterActivation: self.protectedR10FramesAfterActivation,
                lastFrameAt: self.lastR10MotionFrameAt,
                connectedAt: self.connectedAt,
                activationAt: now,
                now: verifiedAt
            ) else {
                self.persistProtectedR10CleanOwnerFallback(
                    reason: "response_event_data_short_burst_retry_insufficient_density"
                )
                return
            }
            self.qualifyProtectedR10RecoveryIfNeeded(
                at: verifiedAt,
                status: "response_event_data_retry_receiving_crc_valid"
            )
        }
        protectedR10CommandSequenceTask = Task { @MainActor [weak self, weak peripheral] in
            defer { self?.protectedR10CommandSequenceTask = nil }
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive,
                  self.heartRateCharacteristic?.isNotifying == true else { return }
            let r10Sequence = self.cmdSeq
            self.cmdSeq &+= 1
            peripheral.writeValue(
                encodeFrame([Packet.command, r10Sequence, Cmd.sendR10R11Realtime, 0x01]),
                for: txCharacteristic,
                type: .withoutResponse
            )
            try? await Task.sleep(for: .seconds(Self.protectedR10CommandPacingDelay))
            guard !Task.isCancelled, peripheral.state == .connected,
                  self.protectedR10ResponseEventDataProofIsActive,
                  self.heartRateCharacteristic?.isNotifying == true else { return }
            let imuSequence = self.cmdSeq
            self.cmdSeq &+= 1
            peripheral.writeValue(
                encodeFrame([Packet.command, imuSequence, Cmd.toggleIMUMode, 0x01]),
                for: txCharacteristic,
                type: .withoutResponse
            )
            AtriaDebugLog("ATRIADBG protected_r10 status=short_burst_retry_sent reason=%@ frames=%d action=one_pair_same_connection_no_cccd_no_reconnect",
                          reason,
                          self.protectedR10FramesAfterActivation)
        }
        return true
    }

    /// One bounded link-health audit inside a BGTask execution window. A
    /// suspended app on a stable-but-idle link receives no BLE wakes (the
    /// post-install locked-phone stall, 2026-07-17), so a background wake is
    /// the only recovery opportunity between user foregrounds. It re-adopts
    /// the persisted motion lease, runs one R10 liveness evaluation, and
    /// routes a stale standard-HR subscription through the existing watchdog
    /// action. It never toggles a CCCD, reconnects, or resets an epoch
    /// itself — those decisions stay with the audited policies.
    func performBackgroundLinkAudit(reason: String) {
        evaluateR10Liveness(reason: "\(reason)_bg_audit")
        guard longWearModeEnabled, standardHROnlyMode, status == .connected else { return }
        let now = Date()
        guard let rawReference = lastRawHRNotificationAt ?? connectedAt,
              let acceptedReference = lastAcceptedHRAt ?? connectedAt else { return }
        let rawGap = max(0, now.timeIntervalSince(rawReference))
        let acceptedGap = max(0, now.timeIntervalSince(acceptedReference))
        let timeout = Self.hrContinuityWatchdogTimeout(acceptedHRTimeout: 45)
        let denseFresh = lastR10MotionFrameAt.map {
            Self.protectedR10FrameBelongsToCurrentConnection(
                lastFrameAt: $0,
                connectedAt: connectedAt
            ) && now.timeIntervalSince($0) >= 0 && now.timeIntervalSince($0) <= 10
        } == true
        guard rawGap >= timeout || (denseFresh && acceptedGap >= timeout) else { return }
        performHRContinuityWatchdogAction(status: "bg_task_stale",
                                          rawGap: rawGap,
                                          acceptedGap: acceptedGap,
                                          timeout: timeout,
                                          label: captureLabel.isEmpty ? "All-day wear" : captureLabel,
                                          immediateConnectedRebuild: true)
    }

    private func evaluateR10Liveness(now: Date = Date(), reason: String) {
        // The 60 s cadence doubles as the lease's lifecycle safety net: it
        // re-adopts a persisted workout lease after foreground/background or
        // restoration, and releases one whose pending intent no longer exists.
        // The governor runs before the restore audit so a battery-pressure
        // release goes through its own path (which records the suspension for
        // resume hysteresis) instead of the stale-intent path.
        evaluateAllDayMotionGovernor(reason: "\(reason)_all_day_audit")
        restoreWorkoutMotionLeaseIfNeeded(reason: "\(reason)_lease_audit")
        let connected = status == .connected && peripheral?.state == .connected
        let eligible = r10TransportIsExpected
        if Self.shouldOpenWorkoutMotionGapForUnavailableR10(
            motionLeaseHeld: workoutMotionOwnerStartedAt != nil,
            historyOwnsTransport: offlineHistoricalSyncInProgress || historyOnlyProbeMode,
            r10TransportExpected: eligible,
            lastFrameAt: lastR10MotionFrameAt,
            now: now
        ) {
            // The stream is intentionally unavailable in this fallback. Mark
            // the gap honestly, but do not attempt an unsafe background
            // requalification or disturb the healthy heart-rate connection.
            markWorkoutMotionGapIfNeeded(
                now: now,
                reason: "\(reason)_r10_transport_unavailable"
            )
        }
        if eligible, connected, !strapStream5NotifyConfirmed {
            reassertR10NotificationIfConnected(reason: "\(reason)_stream5_unconfirmed", now: now)
            return
        }
        let action = Self.r10LivenessAction(
            eligible: eligible,
            connected: connected,
            realtimeArmed: strapStream5NotifyConfirmed
                && (realtimeArmed || protectedR10MotionIsEligible),
            lastFrameAt: lastR10MotionFrameAt,
            lastRearmAt: lastR10RecoveryRearmAt,
            lastRediscoveryAt: lastR10RecoveryRediscoveryAt,
            now: now
        )
        switch action {
        case .none:
            break
        case .rearm:
            lastR10RecoveryRearmAt = now
            requestBoundedR10ActivationForSilentStream(now: now, reason: reason)
        case .rediscover:
            lastR10RecoveryRediscoveryAt = now
            // Inspect and repair only a truly inactive CCCD. Never reconnect or
            // toggle a healthy HR/R10 subscription for a missing frame.
            reassertR10NotificationIfConnected(reason: "\(reason)_stale_followup", now: now)
        }
    }

    // MARK: Workout motion ownership lease

    enum WorkoutMotionLeaseAction: Equatable {
        case none
        /// The link is intentionally in the protected pure-HR fallback.  A
        /// lease remains durable and its missing motion interval remains
        /// honest, but it must not repeatedly try a profile that safety logic
        /// has explicitly isolated for this connection.
        case unavailablePureHRFallback
        case missingConnectionEpoch
        case awaitHeartRate
        case beginBringUp
        case markLive
        case awaitGrace
        case activate
        case alreadyAttempted
    }

    /// Pure policy for the explicit-workout motion lease. A workout owns a
    /// persisted exact-start claim on the dense R10 epoch: after a passive
    /// grace with no fresh frame it may issue at most one already-validated
    /// activation pair per peripheral connection. A frame captured before the
    /// current connection (stale sparse passive motion) never marks workout
    /// motion live.
    /// A qualified protected owner never re-runs the CCCD sequence on a
    /// reconnected link, so `strapStream5NotifyConfirmed` stays false there
    /// even though the strap-side subscription persists and CRC-valid frames
    /// keep arriving. Any frame received on the current connection is direct
    /// proof the stream-5 subscription is live (the 2026-07-15 22:53 gym
    /// workout recorded its whole window as a gap because the flag alone
    /// gated activation).
    nonisolated static func workoutMotionStream5IsProven(
        notifyConfirmed: Bool,
        lastFrameAt: Date?,
        connectedAt: Date?
    ) -> Bool {
        if notifyConfirmed { return true }
        guard let lastFrameAt, let connectedAt else { return false }
        return lastFrameAt >= connectedAt
    }

    /// Dense R10 runs at ~1 frame/second. Requiring most of the last
    /// `workoutMotionDensityWindow` seconds to carry frames distinguishes the
    /// real motion epoch from sparse passive frames (~1 per 15 s), which
    /// defeated a single-frame freshness check on the 2026-07-15 walk
    /// (20 frames / 309 s, no activation ever issued).
    nonisolated static let workoutMotionDensityWindow: TimeInterval = 15
    nonisolated static let workoutMotionDenseFrameThreshold = 12

    nonisolated static func workoutMotionLeaseAction(
        leaseStartedAt: Date?,
        connected: Bool,
        connectedAt: Date?,
        stream5Confirmed: Bool,
        hrNotifying: Bool,
        lastFrameAt: Date?,
        denseFrameCount: Int,
        lastActivationConnectionAt: Date?,
        protectedPureHRFallback: Bool = false,
        graceInterval: TimeInterval = protectedR10PassiveGraceDuration,
        freshFrameWindow: TimeInterval = 10,
        denseFrameThreshold: Int = workoutMotionDenseFrameThreshold,
        now: Date
    ) -> WorkoutMotionLeaseAction {
        guard let leaseStartedAt, connected else { return .none }
        guard let connectedAt else { return .missingConnectionEpoch }
        // This is not a transient missing frame.  The protected owner has
        // already observed a physical instability and deliberately selected
        // an HR-only central.  Retain the workout and its R10 gap, but do not
        // generate a fresh bring-up evaluation every second.  A later,
        // explicitly started workout is the only bounded route that may earn
        // another fresh-owner qualification.
        if protectedPureHRFallback { return .unavailablePureHRFallback }
        guard hrNotifying else { return .awaitHeartRate }
        if let lastFrameAt,
           lastFrameAt >= connectedAt,
           now.timeIntervalSince(lastFrameAt) >= 0,
           now.timeIntervalSince(lastFrameAt) <= freshFrameWindow,
           denseFrameCount >= denseFrameThreshold {
            return .markLive
        }
        if !stream5Confirmed {
            if let lastActivationConnectionAt,
               abs(lastActivationConnectionAt.timeIntervalSince(connectedAt)) < 0.001 {
                return .alreadyAttempted
            }
            return .beginBringUp
        }
        // Grace is measured from the lease (workout) start only. Measuring it
        // per-connection deadlocks under link churn: on 2026-07-16 00:21 IST
        // the strap reconnected every 15–25 s, so a per-connection grace never
        // elapsed and twelve consecutive evaluations returned awaitGrace while
        // the workout stayed sparse. The one-attempt bound below remains
        // per-connection.
        guard now.timeIntervalSince(leaseStartedAt) >= graceInterval else {
            return .awaitGrace
        }
        if let lastActivationConnectionAt,
           abs(lastActivationConnectionAt.timeIntervalSince(connectedAt)) < 0.001 {
            return .alreadyAttempted
        }
        return .activate
    }

    // MARK: All-day banked-motion governor
    //
    // Ordinary day capture owns only WHOOP 4's low-bandwidth historical v24
    // bank. It never creates a workout owner, schedules the R10 evaluator, or
    // authorizes the launch-style dense profile. Explicit workouts and guided
    // calibration retain their existing higher-priority workout lease.

    enum AllDayMotionGovernorAction: Equatable {
        case hold
        case release
        case none
    }

    /// The production v24 bank is a one-command, strap-resident counter—not
    /// the retired continuous R10 flood. Keep it available through normal low
    /// battery operation, but yield below 10% to preserve HR and shutdown
    /// headroom. Daily checkpoint already uses this same physical floor.
    nonisolated static let allDayMotionBankBatteryFloor = 10

    /// Headroom above the v24 bank battery floor required to re-arm after a
    /// battery-pressure release, so the link cannot flap at the boundary.
    nonisolated static let allDayMotionResumeBatteryMargin = 5

    nonisolated static func shouldArmAllDayMotionBank(
        batteryLevel: Int,
        isCharging: Bool
    ) -> Bool {
        batteryLevel < 0
            || isCharging
            || batteryLevel >= allDayMotionBankBatteryFloor
    }

    /// Whether the all-day governor wants the v24 bank held right now.
    /// The high-frequency R10 battery gate deliberately remains stricter; it
    /// must not be reused for this low-bandwidth historical counter.
    nonisolated static func allDayMotionWantsHold(enabled: Bool,
                                                  batteryLevel: Int,
                                                  isCharging: Bool,
                                                  suspendedForBattery: Bool) -> Bool {
        guard enabled else { return false }
        guard shouldArmAllDayMotionBank(
            batteryLevel: batteryLevel,
            isCharging: isCharging
        ) else { return false }
        if suspendedForBattery,
           !isCharging,
           batteryLevel >= 0,
           batteryLevel <= allDayMotionBankBatteryFloor
                + allDayMotionResumeBatteryMargin {
            return false
        }
        return true
    }

    nonisolated static func allDayMotionGovernorAction(wantsHold: Bool,
                                                       connected: Bool,
                                                       workoutIntentActive: Bool,
                                                       calibrationHoldActive: Bool,
                                                       historyOwnerActive: Bool = false,
                                                       bankWanted: Bool,
                                                       bankArmedForCurrentConnection: Bool) -> AllDayMotionGovernorAction {
        // An explicit workout or an armed calibration session outranks the
        // governor unconditionally: it must never acquire over, release, or
        // reshape a lease another holder claimed.
        // Historical replay also owns the proprietary transport. It alone
        // decides if a verified safe command slot may re-arm v24.
        if workoutIntentActive || calibrationHoldActive || historyOwnerActive {
            return .none
        }
        if wantsHold {
            return (connected && !bankArmedForCurrentConnection) ? .hold : .none
        }
        return bankWanted ? .release : .none
    }

    /// All-day strap motion is a product capability, not a hidden opt-in.
    /// Missing preferences (including existing installs created before this
    /// setting existed) therefore default on. An explicit false remains a
    /// durable user opt-out. The governor below still yields to workouts and
    /// history, and applies the physically proven low-battery protection.
    nonisolated static func allDayMotionCaptureEnabled(
        defaults: UserDefaults = .standard
    ) -> Bool {
        defaults.object(forKey: WorkoutMotionDefaults.allDayEnabled) as? Bool ?? true
    }

    var allDayMotionCaptureEnabled: Bool {
        Self.allDayMotionCaptureEnabled()
    }

    private var allDayMotionSuspendedForBattery: Bool {
        get { UserDefaults.standard.bool(forKey: WorkoutMotionDefaults.allDaySuspendedForBattery) }
        set { UserDefaults.standard.set(newValue, forKey: WorkoutMotionDefaults.allDaySuspendedForBattery) }
    }

    private func allDayMotionGovernorWantsHold() -> Bool {
        Self.allDayMotionWantsHold(enabled: allDayMotionCaptureEnabled,
                                   batteryLevel: motionEligibilityBatteryLevel(),
                                   isCharging: motionEligibilityIsCharging,
                                   suspendedForBattery: allDayMotionSuspendedForBattery)
    }

    func evaluateAllDayMotionGovernor(reason: String) {
        let battery = motionEligibilityBatteryLevel()
        let charging = motionEligibilityIsCharging
        let batteryAllows = Self.shouldArmAllDayMotionBank(
            batteryLevel: battery,
            isCharging: charging
        )
        let defaults = UserDefaults.standard
        let bankEnabled = defaults.bool(
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        )
        let bankWanted =
            workoutHistoricalMotionBankArmed
                || bankEnabled
                || defaults.bool(
                    forKey:
                        Self.workoutHistoricalMotionBankPrearmRequestedKey
                )
        let bankArmedForCurrentConnection =
            bankEnabled
                && Self.historicalMotionBankIsArmedForCurrentConnection(
                    armed: workoutHistoricalMotionBankArmed,
                    armedConnectionStartedAt:
                        workoutHistoricalMotionBankArmedConnectionStartedAt,
                    currentConnectionStartedAt: connectedAt
                )
        let action = Self.allDayMotionGovernorAction(
            wantsHold: Self.allDayMotionWantsHold(enabled: allDayMotionCaptureEnabled,
                                                  batteryLevel: battery,
                                                  isCharging: charging,
                                                  suspendedForBattery: allDayMotionSuspendedForBattery),
            connected: peripheral?.state == .connected,
            workoutIntentActive: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            calibrationHoldActive: workoutMotionCalibrationHoldUntil.map { Date() < $0 } == true,
            historyOwnerActive: offlineHistoricalSyncInProgress || historyOnlyProbeMode,
            bankWanted: bankWanted,
            bankArmedForCurrentConnection:
                bankArmedForCurrentConnection
        )
        switch action {
        case .none:
            // Sampling pulse only: `.none` means no arming action is due,
            // but the audit tick is the steadiest clock this diagnostic has.
            if bankArmedForCurrentConnection {
                AtriaMotionBankDutyCycleDiag.note("armed")
            } else if peripheral?.state != .connected {
                AtriaMotionBankDutyCycleDiag.note("link_down")
            }
            return
        case .hold:
            allDayMotionSuspendedForBattery = false
            AtriaDebugLog("ATRIADBG all_day_motion status=v24_bank_hold battery=%d charging=%d reason=%@",
                          battery, charging ? 1 : 0, reason)
            armWorkoutHistoricalMotionBankIfPossible(
                reason: "all_day_\(reason)"
            )
        case .release:
            if !batteryAllows { allDayMotionSuspendedForBattery = true }
            AtriaDebugLog("ATRIADBG all_day_motion status=v24_bank_release battery=%d charging=%d reason=%@",
                          battery, charging ? 1 : 0, reason)
            stopWorkoutHistoricalMotionBankIfPossible(
                reason: batteryAllows ? "all_day_release_\(reason)" : "all_day_battery_\(reason)"
            )
        }
    }

    /// Begin the persisted motion ownership lease for an explicit workout.
    /// Idempotent for the same `startedAt`, so lifecycle replays cannot reset
    /// activation accounting for the current connection.
    func beginWorkoutMotionLease(startedAt: Date, reason: String) {
        releaseConnectedMotionBankPreFreshHRFirstRefusal(
            reason: "explicit_workout_\(reason)"
        )
        releaseConnectedMotionBankArchiveWarmFirstRefusal(
            reason: "explicit_workout_\(reason)"
        )
        releaseConnectedMotionBankAdmissionLedgerFirstRefusal(
            reason: "explicit_workout_\(reason)"
        )
        releaseConnectedMotionBankLocalDependencyFirstRefusal(
            reason: "explicit_workout_\(reason)"
        )
        if let owner = workoutMotionOwnerStartedAt,
           abs(owner.timeIntervalSince(startedAt)) < 0.001 {
            scheduleWorkoutMotionLeaseEvaluation(reason: "\(reason)_replay")
            return
        }
        let defaults = UserDefaults.standard
        if workoutMotionOwnerStartedAt == nil,
           let persisted = defaults.object(
            forKey: WorkoutMotionDefaults.ownerStartedAt
           ) as? Double,
           abs(persisted - startedAt.timeIntervalSince1970) < 0.001 {
            // Same workout re-adopted after a relaunch: keep the persisted
            // activation, frame and gap accounting instead of resetting it.
            workoutMotionOwnerStartedAt = startedAt
            // A persisted user-started workout outranks background history
            // recovery on the RE-ADOPT path too. Physically reproduced
            // (2026-08-12): a launch-time requalification promoted the owner
            // to protectedLaunchPending, but the pending range-loss backfill —
            // re-arming forever behind a history_sequence_gap protocol
            // violation — seized the fresh connection first; the bring-up's
            // history guard then deferred and the once-per-connection
            // activation ticket burned without a command ever being sent, on
            // every attempt. Yield history exactly when the workout still
            // needs its motion bring-up (owner promoted, no command consumed);
            // an already-qualified or fallen-back owner re-adopts untouched so
            // routine relaunches cannot churn a healthy drain.
            if protectedR10CleanOwner == .protectedV9,
               protectedR10CleanOwnerState == .protectedLaunchPending,
               !defaults.bool(
                forKey: Self.protectedR10ResponseEventDataSequenceSentKey
               ) {
                yieldHistoricalTransportToExplicitWorkoutIfNeeded(
                    reason: "\(reason)_readopt_requalify"
                )
            }
            scheduleWorkoutMotionLeaseEvaluation(reason: "\(reason)_readopt")
            return
        }
        workoutMotionOwnerStartedAt = startedAt
        workoutMotionFrameTimestamps.removeAll(keepingCapacity: true)
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: WorkoutMotionDefaults.ownerStartedAt)
        defaults.removeObject(forKey: WorkoutMotionDefaults.gapStartedAt)
        defaults.removeObject(forKey: WorkoutMotionDefaults.firstLiveFrameAt)
        defaults.removeObject(forKey: WorkoutMotionDefaults.lastLiveFrameAt)
        setWorkoutMotionStatus("grace", at: Date())
        AtriaDebugLog("ATRIADBG workout_motion status=lease_begin reason=%@ started_unix=%d",
                      reason,
                      Int(startedAt.timeIntervalSince1970.rounded()))
        armWorkoutHistoricalMotionBankIfPossible(reason: reason)
        // Banked v24 is the accepted production source for WHOOP 4 steps.
        // The legacy realtime-R10 cutover deliberately disconnected the
        // healthy HR link about four seconds into the 2026-07-27 physical
        // walk, while leaving the process-local bank bit set. The replacement
        // link therefore received neither the old R10 stream nor a fresh
        // 69/01, and the post-workout drain contained only pre-workout rows.
        // Keep Start on the existing HR connection and let the bank own motion.
        yieldHistoricalTransportToExplicitWorkoutIfNeeded(reason: reason)
        workoutMotionCutoverTask?.cancel()
        workoutMotionCutoverTask = nil
        scheduleWorkoutMotionLeaseEvaluation(reason: reason)
    }

    /// A persisted user-started workout outranks background history recovery.
    /// We deliberately do not send protocol ABORT or ACK a partial batch. A
    /// connected drain is interrupted through an ordinary link loss, so its
    /// already-durable prefix remains authoritative and its in-flight batch is
    /// safely re-served after the workout. The reconnect sees the persisted
    /// workout intent and therefore restores HR + dense motion instead of
    /// immediately reclaiming the link for history.
    private func yieldHistoricalTransportToExplicitWorkoutIfNeeded(reason: String) {
        let preservesRealtimeOwner =
            offlineHistoricalSyncPreservesConnectedRealtimeOwner
        let activeBankRequest =
            offlineHistoricalSyncExplicitPostWorkoutBankRequest
        let activeRawCatchUp = activeConnectedRawHistoryCatchUpAuthority(
            generation: offlineHistoricalSyncGeneration
        ) != nil
        let disposition = Self
            .workoutHistoricalTransportPreemptionDisposition(
                syncInProgress: offlineHistoricalSyncInProgress,
                historyProbeActive: historyOnlyProbeMode,
                // Releasing only the local owner cannot prove WHOOP stopped
                // serving an in-flight FIFO page. A connected workout
                // preemption always uses a physical disconnect fence; standard
                // HR and 69/01 resume on the replacement callback epoch.
                preservesConnectedRealtimeOwner: false,
                linkConnected: peripheral?.state == .connected
            )
        guard disposition != .noHistoryOwner else { return }
        if !activeRawCatchUp {
            retainPendingOfflineHistoricalSyncRequest(
                reason: "post_workout_resume_\(offlineHistoricalSyncReason)",
                force: activeBankRequest
                    || pendingOfflineHistoricalSyncRequest?.force == true,
                explicitRequest:
                    pendingOfflineHistoricalSyncRequest?.explicitRequest == true,
                explicitPostWorkoutBankRequest: activeBankRequest,
                preserveConnectedRealtimeOwner: preservesRealtimeOwner
            )
        }
        AtriaDebugLog("ATRIADBG workout_motion status=history_owner_preempt_requested reason=%@ generation=%llu action=disconnect_without_abort_retain_durable_prefix",
                      reason,
                      offlineHistoricalSyncGeneration)
        if disposition == .disconnectConnectedHistoryOwner,
           let connectedPeripheral = peripheral,
           connectedPeripheral.state == .connected {
            guard let predecessorSource = bleCallbackEpochFence
                .captureIfAccepted(
                    peripheralID: connectedPeripheral.identifier,
                    peripheralObjectID: ObjectIdentifier(connectedPeripheral),
                    peripheralConnected: true
                ) else {
                AtriaDebugLog(
                    "ATRIADBG workout_motion status=history_owner_preempt_deferred reason=%@ action=await_exact_current_callback_source_no_cancel_no_69",
                    reason
                )
                return
            }
            workoutHistoryPreemptionSuccessorGate.install(
                predecessorSource: predecessorSource
            )
            cancelPeripheralConnection(
                connectedPeripheral,
                reason: "explicit_workout_preempt_history"
            )
            return
        }
        interruptOfflineHistoricalSyncForTransportLoss(
            reason: "explicit_workout_preempt_history_offline"
        )
        cancelHistoryOnlyProbe(reason: "explicit_workout_preempt_history_offline")
        startScan(reason: "explicit_workout_preempt_history_offline")
    }

    /// Release the lease on successful workout stop or transactional
    /// cancellation. An open gap is recorded honestly as unrecovered; nothing
    /// here claims the strap can replay missing motion history.
    func endWorkoutMotionLease(reason: String) {
        let hadLease = workoutMotionOwnerStartedAt != nil
            || UserDefaults.standard.object(forKey: WorkoutMotionDefaults.ownerStartedAt) != nil
        // Reconciliation can observe the same already-terminal workout intent
        // more than once. Once its explicit lease is gone, the currently armed
        // 0x69 bank belongs to autonomous all-day capture. Closing that bank
        // from this no-op path created a new history ticket every reconciliation
        // tick, interrupting live capture and preventing the hourly bank from
        // accumulating useful coverage.
        guard hadLease else {
            AtriaDebugLog(
                "ATRIADBG workout_motion status=lease_release_noop reason=%@ action=retain_all_day_bank",
                reason
            )
            return
        }
        stopWorkoutHistoricalMotionBankIfPossible(reason: reason)
        stopWorkoutRawMotionIfConnected(reason: reason)
        workoutMotionCutoverTask?.cancel()
        workoutMotionCutoverTask = nil
        workoutMotionActivationTask?.cancel()
        workoutMotionActivationTask = nil
        workoutMotionCommandTask?.cancel()
        workoutMotionCommandTask = nil
        let now = Date()
        recordWorkoutMotionGapClosureIfNeeded(endedAt: now, outcome: "lease_released")
        workoutMotionOwnerStartedAt = nil
        workoutMotionFrameTimestamps.removeAll(keepingCapacity: true)
        let defaults = UserDefaults.standard
        if workoutMotionLeaseProfileArmed {
            // Never leave a lease-scoped bring-up pending after release. An
            // unfinished density proof cannot be promoted back to qualified —
            // but a bring-up that never CONSUMED its proprietary command has
            // not touched the strap either: demoting a previously qualified
            // owner there latched a near-permanent pure-HR fallback on healthy
            // hardware (physical `lease_released_before_density_proof`, with
            // 154k lifetime frames and a persisted qualification). Restore the
            // captured qualified state in that no-command case; otherwise
            // preserve HR/RR through the same evidence-honest fallback used by
            // an explicit proof failure.
            workoutMotionLeaseProfileArmed = false
            if protectedR10CleanOwnerState == .protectedLaunchPending {
                let commandConsumed = defaults.bool(
                    forKey: Self.protectedR10ResponseEventDataSequenceSentKey
                )
                let priorWasQualified = defaults.bool(
                    forKey: Self.protectedR10PreBringUpOwnerWasQualifiedKey
                )
                if priorWasQualified, !commandConsumed {
                    defaults.set(
                        ProtectedR10CleanOwnerState.qualified.rawValue,
                        forKey: Self.protectedR10CleanOwnerStateKey
                    )
                    AtriaDebugLog(
                        "ATRIADBG protected_r10 status=bring_up_abandoned_restored_qualified reason=%@ action=no_command_issued_no_fallback",
                        reason
                    )
                } else {
                    persistProtectedR10CleanOwnerFallback(
                        reason: "lease_released_before_density_proof"
                    )
                }
            }
            defaults.removeObject(
                forKey: Self.protectedR10PreBringUpOwnerWasQualifiedKey
            )
        }
        defaults.removeObject(forKey: WorkoutMotionDefaults.ownerStartedAt)
        defaults.removeObject(forKey: WorkoutMotionDefaults.gapStartedAt)
        setWorkoutMotionStatus("released", at: now)
        AtriaDebugLog("ATRIADBG workout_motion status=lease_released reason=%@", reason)
        // A released explicit lease returns v24 bank ownership to the all-day
        // governor. This does not recreate a workout owner or authorize R10.
        // A battery-pressure release re-enters with its suspension flag set
        // and stays released until the resume margin.
        Task { @MainActor [weak self] in
            self?.evaluateAllDayMotionGovernor(reason: "post_lease_release")
        }
    }

    /// Completes the bounded WHOOP 4 raw-motion transaction. STOP_RAW_DATA is
    /// reversible and idempotent, so every connected lease release closes the
    /// stream rather than risking a battery-heavy orphan after an interrupted
    /// workout.
    private func stopWorkoutRawMotionIfConnected(reason: String) {
        guard let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            return
        }
        let sequence = cmdSeq
        cmdSeq &+= 1
        peripheral.writeValue(
            encodeFrame([Packet.command, sequence, Cmd.toggleIMUMode, 0x00]),
            for: txCharacteristic,
            type: .withoutResponse
        )
        if gate4OfficialGen4CompactMotionProbeRequested {
            AtriaDebugLog("ATRIADBG workout_motion status=official_gen4_compact_motion_stopped cmds=6a00 seq=%d reason=%@ action=diagnostic_exact_inverse_no_3f_no_51",
                          Int(sequence),
                          reason)
            return
        }
        let stopSequence = cmdSeq
        cmdSeq &+= 1
        peripheral.writeValue(
            encodeFrame([Packet.command, stopSequence, Cmd.stopRawData, 0x01]),
            for: txCharacteristic,
            type: .withoutResponse
        )
        let floodStopSequence = cmdSeq
        cmdSeq &+= 1
        peripheral.writeValue(
            encodeFrame([Packet.command, floodStopSequence, Cmd.sendR10R11Realtime, 0x00]),
            for: txCharacteristic,
            type: .withoutResponse
        )
        AtriaDebugLog("ATRIADBG workout_motion status=raw_motion_stopped cmds=6a00,5201,3f00 seqs=%d,%d,%d reason=%@",
                      Int(sequence),
                      Int(stopSequence),
                      Int(floodStopSequence),
                      reason)
    }

    enum HistoricalMotionBankTXDiscoveryAction: Equatable {
        case stop
        case arm
        case none
    }

    /// Resolves a newly discovered writable strap TX characteristic without
    /// coupling all-day banking to the realtime R10 workout owner. A deferred
    /// stop always wins so discovery can never accidentally re-arm a bank that
    /// a checkpoint is already trying to close.
    nonisolated static func historicalMotionBankTXDiscoveryAction(
        stopPending: Bool,
        workoutOwnerActive: Bool,
        prearmRequested: Bool
    ) -> HistoricalMotionBankTXDiscoveryAction {
        if stopPending { return .stop }
        if workoutOwnerActive || prearmRequested { return .arm }
        return .none
    }

    nonisolated static func historicalMotionBankIsArmedForCurrentConnection(
        armed: Bool,
        armedConnectionStartedAt: Date?,
        currentConnectionStartedAt: Date?
    ) -> Bool {
        guard armed,
              let armedConnectionStartedAt,
              let currentConnectionStartedAt else { return false }
        return abs(
            armedConnectionStartedAt.timeIntervalSince(
                currentConnectionStartedAt
            )
        ) < 0.001
    }

    /// The persisted motion-owner lease is shared by manual workouts,
    /// calibration, and ordinary all-day capture. Its mere presence therefore
    /// cannot block the all-day bank checkpoint: the governor necessarily
    /// holds that lease while the bank is accumulating. Only a higher-priority
    /// owner or an unsafe transport/battery state may defer the close.
    nonisolated static func historicalMotionBankDailyCheckpointEligible(
        manualWorkoutActive: Bool,
        calibrationHoldActive: Bool,
        historyOwnerActive: Bool,
        bankArmed: Bool,
        batteryAllows: Bool
    ) -> Bool {
        !manualWorkoutActive
            && !calibrationHoldActive
            && !historyOwnerActive
            && bankArmed
            && batteryAllows
    }

    /// Drain-on-glance (2026-08-01): opening the app is the user asking
    /// "where am I now?", so a bank that has been quietly accumulating for
    /// over ten minutes closes and offloads immediately instead of waiting
    /// out the hourly maintenance fence — fresh steps credit within a minute
    /// or two of the glance. Pure so the eligibility is unit-testable:
    /// requires a healthy live link (connected + accepted HR), no history
    /// sync owning the radio, a bank open longer than `minimumOpenSeconds`,
    /// and at least `minimumGlanceInterval` since the previous
    /// glance-triggered close (persisted, so relaunches keep the fence).
    nonisolated static func historicalMotionBankGlanceCheckpointEligible(
        bankOpenSeconds: TimeInterval,
        secondsSinceLastGlanceCheckpoint: TimeInterval?,
        historySyncInProgress: Bool,
        connectedWithAcceptedHR: Bool,
        minimumOpenSeconds: TimeInterval =
            workoutHistoricalMotionBankGlanceMinimumOpenSeconds,
        minimumGlanceInterval: TimeInterval =
            workoutHistoricalMotionBankGlanceMinimumInterval
    ) -> Bool {
        guard !historySyncInProgress, connectedWithAcceptedHR else { return false }
        guard bankOpenSeconds > minimumOpenSeconds else { return false }
        if let secondsSinceLastGlanceCheckpoint,
           secondsSinceLastGlanceCheckpoint < minimumGlanceInterval {
            return false
        }
        return true
    }

    nonisolated static func historicalMotionBankOffloadEligible(
        manualWorkoutActive: Bool,
        calibrationHoldActive: Bool,
        historyOwnerActive: Bool,
        postHistoryRestorationActive: Bool,
        bankArmed: Bool,
        connectedWithAcceptedHR: Bool,
        hasPendingTicket: Bool
    ) -> Bool {
        !manualWorkoutActive
            && !calibrationHoldActive
            && !historyOwnerActive
            && !postHistoryRestorationActive
            && !bankArmed
            && connectedWithAcceptedHR
            && hasPendingTicket
    }

    /// A newly closed bank gets one immediate exact-window offload before a
    /// successor opens. Once that factual attempt has run, present capture
    /// outranks maintenance retries: keeping all-day motion disabled for each
    /// fifteen-minute retry interval loses more real data than the unresolved
    /// ticket can recover. The ticket remains durable and missing until an
    /// intentional checkpoint retries or terminally resolves it.
    nonisolated static func historicalMotionBankArmEligible(
        manualWorkoutActive: Bool,
        pendingOffloadAttempts: Int?,
        firstAttemptTransportDeferred: Bool = false
    ) -> Bool {
        manualWorkoutActive
            || pendingOffloadAttempts == nil
            || (pendingOffloadAttempts ?? 0) > 0
            || firstAttemptTransportDeferred
    }

    nonisolated static func historicalMotionBankFirstAttemptTransportDeferred(
        pendingTicketID: String?,
        pendingOffloadAttempts: Int?,
        boundTicketID: String?,
        deferredTransportTicketID: String?
    ) -> Bool {
        guard pendingOffloadAttempts == 0,
              let pendingTicketID else { return false }
        return boundTicketID == pendingTicketID
            && deferredTransportTicketID == pendingTicketID
    }

    /// Retries may interrupt present capture only at an explicit maintenance
    /// boundary (the existing hourly/battery/workout close). Attempt zero is
    /// the one immediate first drain and is always eligible.
    nonisolated static func historicalMotionBankRetryEligible(
        attempts: Int,
        maintenanceWindow: Bool,
        processInterruptedRetry: Bool
    ) -> Bool {
        attempts == 0 || maintenanceWindow || processInterruptedRetry
    }

    nonisolated static func historicalMotionBankProcessInterruptedRetryEligible(
        attempts: Int,
        ticketID: String,
        persistedActiveTicketID: String?,
        lastStartedAt: Date?,
        processLaunchStartedAt: Date
    ) -> Bool {
        attempts > 0
            && persistedActiveTicketID == ticketID
            && lastStartedAt.map { $0 < processLaunchStartedAt } == true
    }

    /// A retry from an earlier process gets first refusal only while it can
    /// actually progress toward BLE ownership. Terminal consumer
    /// materialization is local archive work: it owns no radio and may run in
    /// parallel with the low-bandwidth 0x69 capture bank. Treating a retained
    /// request in that state as active transport leaves present-day motion
    /// disabled until the local projection completes.
    nonisolated static func historicalMotionBankProcessRetryBlocksPresentCapture(
        processInterruptedRetry: Bool,
        consumerMaterializationInFlight: Bool,
        attemptDelayElapsed: Bool,
        cadenceEligible: Bool
    ) -> Bool {
        processInterruptedRetry
            && !consumerMaterializationInFlight
            && attemptDelayElapsed
            && cadenceEligible
    }

    nonisolated static func historicalMotionBankOffloadCadenceEligible(
        attempts: Int,
        now: Date,
        lastStartedAt: Date?,
        diagnosticDailyCheckpointBypass: Bool = false
    ) -> Bool {
        // A new bank owns a distinct factual capture interval. Delaying its
        // first drain behind an older ticket's maintenance timestamp leaves
        // present-day capture disabled for the whole cooldown because the
        // unresolved ticket correctly prevents a successor bank from arming.
        //
        // Keep the global fifteen-minute fence for retries of a ticket that
        // already consumed transport. A never-attempted interval must get one
        // immediate, generation-fenced offload after accepted HR returns.
        if attempts == 0 || diagnosticDailyCheckpointBypass {
            return true
        }
        guard let lastStartedAt else { return true }
        return now.timeIntervalSince(lastStartedAt)
            >= workoutHistoricalMotionBankMinimumOffloadInterval
    }

    /// A partial result is still the same user-visible recovery episode: later
    /// bounded generations may add to it without a visible relaunch or a new
    /// gap. Terminal verified/idle/attention states begin a fresh scope.
    nonisolated static func continuesHistoricalRecoveryEpisode(
        _ presentation: HistoricalRecoveryPresentation
    ) -> Bool {
        switch presentation {
        case .syncing, .partial:
            return true
        case .idle, .verified, .needsAttention:
            return false
        }
    }

    nonisolated static func historicalRecoveryEpisodeSavedRecords(
        totalRows: Int,
        episodeStartRows: Int
    ) -> Int {
        max(0, totalRows - episodeStartRows)
    }

    nonisolated static let historicalRecoveryProgressMinimumInterval:
        TimeInterval = 15
    nonisolated static let historicalRecoveryProgressMinimumRecordDelta = 250

    /// Historical row counts are presentation-only. A suspended app publishes
    /// no progress object changes; an active app receives an initial value and
    /// then a bounded time/record cadence. Terminal states use their separate
    /// exact completion assignments.
    nonisolated static func shouldPublishHistoricalRecoveryProgress(
        applicationIsActive: Bool,
        compactMotionBankOnly: Bool = false,
        savedRecords: Int,
        lastPublishedRecords: Int?,
        lastPublishedAt: Date?,
        now: Date,
        minimumInterval: TimeInterval = historicalRecoveryProgressMinimumInterval,
        minimumRecordDelta: Int = historicalRecoveryProgressMinimumRecordDelta
    ) -> Bool {
        guard applicationIsActive,
              !compactMotionBankOnly,
              savedRecords >= 0,
              savedRecords != lastPublishedRecords else { return false }
        guard let lastPublishedAt,
              let lastPublishedRecords else { return true }
        let elapsed = now.timeIntervalSince(lastPublishedAt)
        return elapsed < 0
            || elapsed >= max(0.1, minimumInterval)
            || abs(savedRecords - lastPublishedRecords)
                >= max(1, minimumRecordDelta)
    }

    private func publishHistoricalRecoveryProgressIfNeeded(now: Date = Date()) {
        let savedRecords = Self.historicalRecoveryEpisodeSavedRecords(
            totalRows: historicalArchiveRows,
            episodeStartRows: offlineHistoricalRecoveryEpisodeStartRows
        )
        guard Self.shouldPublishHistoricalRecoveryProgress(
            applicationIsActive:
                UIApplication.shared.applicationState == .active,
            compactMotionBankOnly:
                activeConnectedMotionBankHistoryAuthority(
                    generation: offlineHistoricalSyncGeneration
                ) != nil,
            savedRecords: savedRecords,
            lastPublishedRecords:
                lastHistoricalRecoveryProgressPublishedRecords,
            lastPublishedAt: lastHistoricalRecoveryProgressPublishAt,
            now: now
        ) else { return }
        lastHistoricalRecoveryProgressPublishAt = now
        lastHistoricalRecoveryProgressPublishedRecords = savedRecords
        historicalRecoveryPresentation = .syncing(savedRecords: savedRecords)
    }

    /// The inactive transport keeps exact progress private. After the returning
    /// scene has rendered, publish the current count once even when no further
    /// history row arrives to drive the normal foreground cadence.
    func catchUpHistoricalRecoveryProgressForForeground(now: Date = Date()) {
        guard offlineHistoricalSyncInProgress else { return }
        publishHistoricalRecoveryProgressIfNeeded(now: now)
    }

    /// Duty-cycle attribution must not misfile time the bank is genuinely
    /// armed: gate declines fire before the already-armed short-circuit, so
    /// an armed bank riding out a history sync would otherwise bill hours
    /// to "sync_cutover". Armed-for-this-connection wins over any fallback.
    private func noteMotionBankDutyCycle(_ fallback: String) {
        if peripheral?.state == .connected,
           Self.historicalMotionBankIsArmedForCurrentConnection(
               armed: workoutHistoricalMotionBankArmed,
               armedConnectionStartedAt:
                   workoutHistoricalMotionBankArmedConnectionStartedAt,
               currentConnectionStartedAt: connectedAt
           ) {
            AtriaMotionBankDutyCycleDiag.note("armed")
        } else {
            AtriaMotionBankDutyCycleDiag.note(fallback)
        }
    }

    /// WHOOP 4's banked v24 motion counter is the physically accepted Gate-4
    /// source. It runs independently of the unstable realtime R10 flood and
    /// therefore never blocks Start/End or competes with standard 2A37 HR.
    private func armWorkoutHistoricalMotionBankIfPossible(
        reason: String,
        prioritizePresentCaptureOverProcessRetry: Bool = false
    ) {
        let now = Date()
        let manualWorkoutActive =
            AtriaPendingWorkoutIntent.isActiveForBLEContinuity(now: now)
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { now < $0 } == true
        let explicitPresentCapturePriority =
            manualWorkoutActive || calibrationHoldActive
        // The continuation flag is a SCHEDULING latch that stays true across
        // hours of idle retry cadence while a backlog exists — treating it as
        // radio ownership disarmed the all-day bank for ~12k seconds of a
        // sampled day. A slice whose next evaluation is comfortably in the
        // future owns no radio: let the bank capture present motion in the
        // gap; the next history slice's serve cutover reclaims it cleanly.
        // The 60s floor keeps 2s productive chains from arm/disarm churn.
        let rawSliceIdleWindow: TimeInterval = 60
        let rawContinuationActivelyOwnsRadio =
            connectedRawHistoryCatchUpContinuationPending
                && !(connectedRawHistoryCatchUpEvaluationNotBefore.map {
                        $0.timeIntervalSince(now) >= rawSliceIdleWindow
                    } ?? false)
        guard !historyOnlyProbeMode,
              !freshHistoryOwnerCutoverPending,
              !Self.historicalMotionBankRearmBlockedByRawOwnership(
                historyTransportActive: offlineHistoricalSyncInProgress,
                rawContinuationPending:
                    rawContinuationActivelyOwnsRadio,
                postHistoryRawRestorationActive:
                    postHistoryLiveRestorationGeneration != nil
                        && rawContinuationActivelyOwnsRadio,
                explicitPresentCapturePriority:
                    explicitPresentCapturePriority
              ) else {
            // A bounded connected-raw continuation is one active global FIFO
            // catch-up even while transport briefly yields for live HR. The
            // physically rejected v5 flow reopened 69/01 inside this episode
            // and manufactured tickets faster than read_cursor could converge.
            noteMotionBankDutyCycle("sync_cutover")
            return
        }
        guard let peripheral, peripheral.state == .connected else {
            AtriaMotionBankDutyCycleDiag.note("link_down")
            return
        }
        guard !workoutHistoryPreemptionSuccessorGate.blocksArm(
            for: peripheral.identifier
        ) else {
            // TX discovery on the replacement link can precede 2A37. The
            // physical disconnect proved the old FIFO owner is gone, but only
            // accepted HR proves the same-strap successor epoch is healthy
            // enough to resume present motion capture. A different strap
            // retires the stale reservation in `blocksArm` above.
            noteMotionBankDutyCycle("await_fresh_hr")
            return
        }
        let defaults = UserDefaults.standard
        let presentCapturePriority =
            prioritizePresentCaptureOverProcessRetry
                || connectedRawNoRadioCaptureTurnRequiresPresentArm()
        // All-day capture is authorized only by its own v24 governor policy.
        // Manual workouts and guided calibration retain their existing
        // ability to arm the bank independently of that product preference.
        guard manualWorkoutActive
                || calibrationHoldActive
                || allDayMotionGovernorWantsHold() else {
            defaults.set(
                false,
                forKey:
                    Self.workoutHistoricalMotionBankPrearmRequestedKey
            )
            noteMotionBankDutyCycle("governor_off")
            return
        }
        let rearmNotBefore = defaults.double(
            forKey: Self.workoutHistoricalMotionBankRearmNotBeforeKey
        )
        guard rearmNotBefore <= 0
                || Date().timeIntervalSince1970 >= rearmNotBefore else {
            noteMotionBankDutyCycle("throttle")
            return
        }
        defaults.set(true,
                     forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey)
        let bound = defaults.string(
            forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
        ).flatMap { boundID in
            AtriaWhoop4MotionBankCoverageLedger.pendingOffload(
                id: boundID,
                strapIdentifier: peripheral.identifier.uuidString
            )
        }.flatMap { ticket in
            ticket.effectiveRecoveryMode == .directOffload ? ticket : nil
        }
        let lastStartedAtValue = defaults.double(
            forKey:
                Self.workoutHistoricalMotionBankLastOffloadStartedAtKey
        )
        let lastStartedAt = lastStartedAtValue > 0
            ? Date(timeIntervalSince1970: lastStartedAtValue)
            : nil
        let processInterruptedBoundRetry = bound.map {
            Self.historicalMotionBankProcessInterruptedRetryEligible(
                attempts: $0.attempts,
                ticketID: $0.id,
                persistedActiveTicketID: defaults.string(
                    forKey:
                        Self.workoutHistoricalMotionBankActiveTicketIDKey
                ),
                lastStartedAt: lastStartedAt,
                processLaunchStartedAt: processLaunchStartedAt
            )
        } == true
        let maintenanceTicket =
            freshHistoryOwnerBoundaryFailureLatched
                ? nil
                : pendingWorkoutHistoricalMotionBankMaintenanceTicket(
                    strapIdentifier: peripheral.identifier.uuidString,
                    defaults: defaults
                )
        let selectedPendingOffload =
            Self.historicalMotionBankOffloadTicketForNewGeneration(
                bound: bound,
                next: maintenanceTicket
                    ??
                    AtriaWhoop4MotionBankCoverageLedger.nextPendingOffload(
                        strapIdentifier: peripheral.identifier.uuidString
                    ),
                maintenanceWindow: maintenanceTicket != nil,
                processInterruptedBoundRetry:
                    processInterruptedBoundRetry
            )
        // A pre-start archive/thermal/atomic deferral owns no BLE transport and
        // must not leave present 0x69 capture disabled. Its separate durable
        // exact-ticket reservation is neither an attempt nor a cadence fact;
        // only the same bound attempt-zero ticket can consume it for rearming.
        let firstAttemptTransportDeferred = Self
            .historicalMotionBankFirstAttemptTransportDeferred(
                pendingTicketID: selectedPendingOffload?.id,
                pendingOffloadAttempts: selectedPendingOffload?.attempts,
                boundTicketID: bound?.id,
                deferredTransportTicketID: defaults.string(
                    forKey: Self
                        .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                )
            )
        let acceptedCurrentConnectionHR = connectedAt.flatMap {
            connectionStart in
            lastAcceptedHRAt.map { $0 >= connectionStart }
        } == true
        if firstAttemptTransportDeferred,
           !presentCapturePriority,
           !manualWorkoutActive,
           !calibrationHoldActive,
           !acceptedCurrentConnectionHR,
           let selectedPendingOffload {
            if connectedMotionBankPreFreshHRArmGate.blocksArm(
                ticketID: selectedPendingOffload.id,
                now: now
            ) {
                noteMotionBankDutyCycle("offload_first")
                return
            }
            if connectedMotionBankPreFreshHRArmGate.ticketID
                == selectedPendingOffload.id {
                // The deadline elapsed just before its MainActor timeout task
                // ran. Clear the scheduling claim and fall through to present
                // capture; do not begin another wait episode.
                _ = connectedMotionBankPreFreshHRArmGate.resolveFallback(
                    expectedTicketID: selectedPendingOffload.id
                )
                connectedMotionBankPreFreshHRArmTask?.cancel()
                connectedMotionBankPreFreshHRArmTask = nil
            } else {
                if connectedMotionBankPreFreshHRArmGate.isHolding {
                    _ = connectedMotionBankPreFreshHRArmGate.resolveFallback()
                    connectedMotionBankPreFreshHRArmTask?.cancel()
                    connectedMotionBankPreFreshHRArmTask = nil
                }
                holdConnectedMotionBankBeforeFreshHRFirstRefusal(
                    ticketID: selectedPendingOffload.id,
                    now: now
                )
                noteMotionBankDutyCycle("offload_first")
                return
            }
        }
        if let selectedPendingOffload,
           !manualWorkoutActive,
           !calibrationHoldActive,
           UIApplication.shared.applicationState == .active {
            let processInterruptedRetry =
                processInterruptedMotionBankReservedTicketID
                    == selectedPendingOffload.id
                || Self
                    .historicalMotionBankProcessInterruptedRetryEligible(
                        attempts: selectedPendingOffload.attempts,
                        ticketID: selectedPendingOffload.id,
                        persistedActiveTicketID: defaults.string(
                            forKey:
                                Self
                                    .workoutHistoricalMotionBankActiveTicketIDKey
                        ),
                        lastStartedAt: lastStartedAt,
                        processLaunchStartedAt: processLaunchStartedAt
                    )
            let attemptDelayElapsed =
                selectedPendingOffload.lastAttemptAt.map {
                    now.timeIntervalSince($0)
                        >= Self
                            .workoutHistoricalMotionBankOffloadRetryDelay(
                                attempts:
                                    selectedPendingOffload.attempts
                            )
                } ?? true
            if !presentCapturePriority,
               Self.historicalMotionBankProcessRetryBlocksPresentCapture(
                processInterruptedRetry: processInterruptedRetry,
                consumerMaterializationInFlight:
                    historicalConsumerMaterializationInFlight,
                attemptDelayElapsed: attemptDelayElapsed,
                cadenceEligible:
                    Self.historicalMotionBankOffloadCadenceEligible(
                        attempts: selectedPendingOffload.attempts,
                        now: now,
                        lastStartedAt: lastStartedAt
                    )
            ) {
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank status=arm_deferred ticket=%@ attempts=%d reason=%@ action=resume_process_interrupted_exact_ticket_first",
                    selectedPendingOffload.id,
                    selectedPendingOffload.attempts,
                    reason
                )
                noteMotionBankDutyCycle("offload_first")
                return
            }
        }
        guard presentCapturePriority || Self.historicalMotionBankArmEligible(
            manualWorkoutActive: manualWorkoutActive,
            pendingOffloadAttempts: selectedPendingOffload?.attempts,
            firstAttemptTransportDeferred:
                firstAttemptTransportDeferred
        ) else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=arm_deferred reason=%@ pending_offload_attempts=%d action=complete_first_attempt_before_present_rearm",
                reason,
                selectedPendingOffload?.attempts ?? -1
            )
            noteMotionBankDutyCycle("offload_first")
            return
        }
        guard let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            requestWorkoutHistoricalMotionBankTransportIfNeeded(
                peripheral: peripheral,
                reason: reason
            )
            noteMotionBankDutyCycle("transport_pending")
            return
        }
        if Self.historicalMotionBankIsArmedForCurrentConnection(
            armed: workoutHistoricalMotionBankArmed,
            armedConnectionStartedAt:
                workoutHistoricalMotionBankArmedConnectionStartedAt,
            currentConnectionStartedAt: connectedAt
        ),
           defaults.bool(forKey: Self.workoutHistoricalMotionBankEnabledKey) {
            AtriaMotionBankDutyCycleDiag.note("armed")
            return
        }
        guard peripheral.canSendWriteWithoutResponse else {
            // CoreBluetooth accepted no command, so neither process state nor
            // durable coverage may claim that 69/01 reached the strap.
            noteMotionBankDutyCycle("wwr_backpressure")
            return
        }
        guard writeCompletionLedger.pending.isEmpty else {
            // Never interleave a bank toggle with an unresolved with-response
            // command from an ambiguous history serve.
            noteMotionBankDutyCycle("wr_pending")
            return
        }
        let armedAt = Date()
        let persistedWasEnabled = defaults.bool(
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        )
        let persistedArmedAt = defaults.double(
            forKey: Self.workoutHistoricalMotionBankArmedAtKey
        )
        let sequence = cmdSeq
        cmdSeq &+= 1
        peripheral.writeValue(
            encodeFrame([
                Packet.command,
                sequence,
                Cmd.toggleIMUModeHistorical,
                0x01,
            ]),
            for: txCharacteristic,
            type: .withoutResponse
        )
        workoutHistoricalMotionBankArmed = true
        workoutHistoricalMotionBankArmedConnectionStartedAt = connectedAt
        AtriaWhoop4MotionBankCoverageLedger.open(
            at: persistedWasEnabled && persistedArmedAt > 0
                ? Date(timeIntervalSince1970: persistedArmedAt)
                : armedAt,
            strapIdentifier: peripheral.identifier.uuidString
        )
        AtriaMotionBankDutyCycleDiag.note("armed")
        defaults.set(true, forKey: Self.workoutHistoricalMotionBankEnabledKey)
        defaults.set(false, forKey: Self.workoutHistoricalMotionBankStopPendingKey)
        if !persistedWasEnabled || persistedArmedAt <= 0 {
            defaults.set(armedAt.timeIntervalSince1970,
                         forKey: Self.workoutHistoricalMotionBankArmedAtKey)
        }
        AtriaDebugLog("ATRIADBG workout_motion_bank status=armed cmd=6901 seq=%d reason=%@ source=whoop4_v24",
                      Int(sequence),
                      reason)
    }

    /// Materializes ordinary, unannounced walking without requiring a workout.
    ///
    /// The bank itself stays low-bandwidth and does not update the UI. Once an
    /// hour, a healthy live link closes it and launches the existing async
    /// durable history drain. The accepted-HR path is never blocked, and the
    /// short re-arm fence prevents a one-Hz HR callback from reopening 0x69
    /// between the close command and the history owner taking the radio.
    private func checkpointDailyHistoricalMotionBankIfNeeded(
        at date: Date,
        reason: String
    ) {
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { date < $0 } == true
        guard Self.historicalMotionBankDailyCheckpointEligible(
            manualWorkoutActive:
                AtriaPendingWorkoutIntent.isActiveForBLEContinuity(now: date),
            calibrationHoldActive: calibrationHoldActive,
            historyOwnerActive:
                historyOnlyProbeMode || offlineHistoricalSyncInProgress,
            bankArmed: workoutHistoricalMotionBankArmed,
            batteryAllows:
                batteryLevel < 0 || batteryLevel >= 10 || batteryIsCharging
        ) else {
            return
        }
        let defaults = UserDefaults.standard
        guard defaults.bool(
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        ) else { return }
        let armedAt = defaults.double(
            forKey: Self.workoutHistoricalMotionBankArmedAtKey
        )
        guard armedAt > 0,
              date.timeIntervalSince1970 - armedAt
                >= workoutHistoricalMotionBankDailyCheckpointInterval else {
            return
        }
        let lastCheckpoint = defaults.double(
            forKey: Self.workoutHistoricalMotionBankLastDailyCheckpointAtKey
        )
        guard lastCheckpoint <= 0
                || date.timeIntervalSince1970 - lastCheckpoint >= 5 * 60 else {
            return
        }
        defaults.set(
            date.timeIntervalSince1970,
            forKey: Self.workoutHistoricalMotionBankLastDailyCheckpointAtKey
        )
        AtriaDebugLog("ATRIADBG workout_motion_bank status=daily_checkpoint_due reason=%@ armed_seconds=%d action=async_close_and_offload",
                      reason,
                      Int(date.timeIntervalSince1970 - armedAt))
        stopWorkoutHistoricalMotionBankIfPossible(
            reason: "daily_checkpoint_\(reason)"
        )
    }

    /// Drain-on-glance (2026-08-01): a bounded variant of the hourly daily
    /// checkpoint that runs when the app becomes interactively foreground.
    /// Shares every safety gate of the hourly close (higher-priority owners,
    /// battery, armed bank) but replaces the hourly armed-duration fence with
    /// the ten-minute glance policy, so steps banked since the last close
    /// credit within ~1-2 minutes of opening the app. Re-arm happens through
    /// the existing offload finalizer, exactly like the hourly path.
    @discardableResult
    private func checkpointHistoricalMotionBankOnGlanceIfNeeded(
        at date: Date,
        reason: String
    ) -> Bool {
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { date < $0 } == true
        let historySyncInProgress =
            historyOnlyProbeMode || offlineHistoricalSyncInProgress
        guard Self.historicalMotionBankDailyCheckpointEligible(
            manualWorkoutActive:
                AtriaPendingWorkoutIntent.isActiveForBLEContinuity(now: date),
            calibrationHoldActive: calibrationHoldActive,
            historyOwnerActive: historySyncInProgress,
            bankArmed: workoutHistoricalMotionBankArmed,
            batteryAllows:
                batteryLevel < 0 || batteryLevel >= 10 || batteryIsCharging
        ) else {
            return false
        }
        let defaults = UserDefaults.standard
        guard defaults.bool(
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        ) else { return false }
        let armedAt = defaults.double(
            forKey: Self.workoutHistoricalMotionBankArmedAtKey
        )
        guard armedAt > 0 else { return false }
        let lastGlance = defaults.double(
            forKey: Self.workoutHistoricalMotionBankLastGlanceCheckpointAtKey
        )
        // Same live-link facts the offload path derives (peripheral actually
        // connected, and an accepted HR sample within this connection).
        let peripheralConnected = peripheral?.state == .connected
        let acceptedCurrentConnectionHR =
            connectedAt.flatMap { connectionStart in
                lastAcceptedHRAt.map { $0 >= connectionStart }
            } == true
        guard Self.historicalMotionBankGlanceCheckpointEligible(
            bankOpenSeconds: date.timeIntervalSince1970 - armedAt,
            secondsSinceLastGlanceCheckpoint: lastGlance > 0
                ? date.timeIntervalSince1970 - lastGlance
                : nil,
            historySyncInProgress: historySyncInProgress,
            connectedWithAcceptedHR:
                peripheralConnected && acceptedCurrentConnectionHR
        ) else { return false }
        defaults.set(
            date.timeIntervalSince1970,
            forKey: Self.workoutHistoricalMotionBankLastGlanceCheckpointAtKey
        )
        // Also stamp the daily-checkpoint fence so the hourly path's 5-minute
        // re-entry guard cannot double-close immediately after the glance.
        defaults.set(
            date.timeIntervalSince1970,
            forKey: Self.workoutHistoricalMotionBankLastDailyCheckpointAtKey
        )
        AtriaDebugLog("ATRIADBG workout_motion_bank status=glance_checkpoint_due reason=%@ armed_seconds=%d action=async_close_and_offload",
                      reason,
                      Int(date.timeIntervalSince1970 - armedAt))
        stopWorkoutHistoricalMotionBankIfPossible(
            reason: "glance_checkpoint_\(reason)"
        )
        return true
    }

    /// Consumes the scene-active retry before consulting UIKit state. An HR
    /// packet delivered after the app backgrounds therefore retires the edge
    /// without touching checkpoint defaults, and all later packets hit only the
    /// in-memory false fast path. When still active, `lastAcceptedHRAt` has
    /// already been published for this exact connection by the sole caller.
    @discardableResult
    private func retryForegroundGlanceCheckpointAfterFreshHeartRateIfNeeded(
        at date: Date
    ) -> Bool {
        guard foregroundGlanceCheckpointRetryGate.consumeAfterAcceptedHeartRate(
            applicationIsActive:
                UIApplication.shared.applicationState == .active
        ) else {
            return false
        }
        return checkpointHistoricalMotionBankOnGlanceIfNeeded(
            at: date,
            reason: "first_foreground_accepted_hr"
        )
    }

    private func scheduleGate4DailyBankRearmAfterHistoryStart(
        generation: UInt64
    ) {
        guard let intent = gate4DailyBankRearmIntent,
              intent.generation == generation,
              !workoutHistoricalMotionBankArmed,
              activeFullDrainEventIdentity?.transportGeneration == generation,
              let expectedIdentity =
                gate4DailyBankFullDrainAuthorityIdentity,
              expectedIdentity.generation == intent.generation,
              expectedIdentity.ticketID == intent.ticketID,
              expectedIdentity.strapIdentifier == intent.strapIdentifier
        else { return }
        gate4DailyBankRearmTask?.cancel()
        gate4DailyBankRearmTask = Task { @MainActor [weak self] in
            var lastDeferredReason:
                AtriaWhoop4DailyMotionBankRearmPolicy.DeferReason?
            while !Task.isCancelled {
                guard let self else { return }
                if self.workoutHistoricalMotionBankArmed {
                    self.clearGate4DailyBankRearmIntent(
                        reason: "already_armed"
                    )
                    return
                }
                let input = self.gate4DailyBankRearmPolicyInput(
                    expectedIdentity: expectedIdentity,
                    now: Date()
                )
                switch AtriaWhoop4DailyMotionBankRearmPolicy.evaluate(input) {
                case .send:
                    if self.submitGate4DailyBankRearm(
                        expectedIdentity: expectedIdentity
                    ) {
                        return
                    }
                    self.clearGate4DailyBankRearmIntent(
                        reason: "corebluetooth_submission_rejected"
                    )
                    return

                case .defer(let reason):
                    if lastDeferredReason != reason {
                        AtriaDebugLog(
                            "ATRIADBG workout_motion_bank status=gate4_rearm_deferred generation=%llu reason=%@ action=await_safe_history_command_slot",
                            generation,
                            String(describing: reason)
                        )
                        lastDeferredReason = reason
                    }
                    try? await Task.sleep(for: .milliseconds(50))

                case .cancel(let reason):
                    AtriaDebugLog(
                        "ATRIADBG workout_motion_bank status=gate4_rearm_cancelled generation=%llu reason=%@ action=terminal_fallback_only",
                        generation,
                        String(describing: reason)
                    )
                    self.clearGate4DailyBankRearmIntent(
                        reason: String(describing: reason)
                    )
                    return
                }
            }
        }
    }

    private func currentGate4DailyBankRearmIdentity(
        generation: UInt64
    ) -> AtriaWhoop4DailyMotionBankRearmPolicy.Identity? {
        guard let intent = gate4DailyBankRearmIntent,
              intent.generation == generation,
              offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation,
              let peripheral,
              peripheral.state == .connected,
              peripheral.identifier == intent.strapIdentifier,
              let connectionStartedAt = connectedAt,
              let ticketID = UserDefaults.standard.string(
                forKey:
                    Self.workoutHistoricalMotionBankActiveTicketIDKey
              ),
              ticketID == intent.ticketID else { return nil }
        return .init(
            generation: generation,
            ticketID: ticketID,
            strapIdentifier: peripheral.identifier,
            callbackEpoch: bleCallbackEpochFence.epoch,
            connectionStartedAt: connectionStartedAt
        )
    }

    private func gate4DailyBankRearmPolicyInput(
        expectedIdentity:
            AtriaWhoop4DailyMotionBankRearmPolicy.Identity,
        now: Date
    ) -> AtriaWhoop4DailyMotionBankRearmPolicy.Input {
        let defaults = UserDefaults.standard
        let currentIdentity:
            AtriaWhoop4DailyMotionBankRearmPolicy.Identity? =
                currentGate4DailyBankRearmIdentity(
                    generation: expectedIdentity.generation
                )
        let phase = historyTransportPhaseFence.snapshot()
        let activeHistoryIdentity =
            offlineHistoricalSyncInProgress
                && phase.generation == offlineHistoricalSyncGeneration
            ? currentIdentity
            : nil
        let confirmedHistoryServe:
            AtriaWhoop4DailyMotionBankRearmPolicy.ConfirmedCommand? = {
                guard let eventIdentity =
                        gate4DailyBankHistoryServeIdentity,
                      let evidence = historicalFullDrainWriteEvidence,
                      evidence.transportGeneration
                        == eventIdentity.generation,
                      evidence.command == Cmd.sendHistoricalData,
                      evidence.payload == [0x00] else { return nil }
                return .init(
                    identity: eventIdentity,
                    command:
                        AtriaWhoop4DailyMotionBankRearmPolicy
                            .historyServeCommand,
                    writeConfirmed: true
                )
            }()
        let acceptedHistoryStart:
            AtriaWhoop4DailyMotionBankRearmPolicy.Attestation? = {
                guard let eventIdentity =
                        gate4DailyBankHistoryStartIdentity,
                      acceptedHistoryStartSequence != nil else { return nil }
                return .init(identity: eventIdentity)
            }()
        let fullDrainAuthority:
            AtriaWhoop4DailyMotionBankRearmPolicy.Attestation? = {
                guard let eventIdentity =
                        gate4DailyBankFullDrainAuthorityIdentity,
                      let authority = activeFullDrainEventIdentity,
                      authority.transportGeneration
                        == eventIdentity.generation,
                      UUID(uuidString: authority.peripheralIdentifier)
                        == eventIdentity.strapIdentifier else { return nil }
                return .init(identity: eventIdentity)
            }()
        let terminal:
            AtriaWhoop4DailyMotionBankRearmPolicy.Attestation? =
                gate4DailyBankTerminalIdentity.map {
                    .init(identity: $0)
                }
        let acceptedHeartRate:
            AtriaWhoop4DailyMotionBankRearmPolicy.AcceptedHeartRate? = {
                guard let currentIdentity,
                      let lastAcceptedHRAt,
                      lastAcceptedHRAt
                        >= currentIdentity.connectionStartedAt else {
                    return nil
                }
                return .init(
                    identity: currentIdentity,
                    age: now.timeIntervalSince(lastAcceptedHRAt)
                )
            }()
        // This coexistence path remains an explicit physical diagnostic until
        // a durable, strap-specific 0x69 capability proof is available.
        // Historical-drain support is not evidence that motion-bank rearm is
        // supported, so never substitute that broader capability here.
        #if DEBUG
        let capabilityVerified =
            ProcessInfo.processInfo.arguments.contains(
                "--atria-gate4-rearm-bank-during-history"
            )
        let verifiedCapability = capabilityVerified
            ? currentIdentity.map {
                AtriaWhoop4DailyMotionBankRearmPolicy.Attestation(
                    identity: $0
                )
            }
            : nil
        #else
        let verifiedCapability:
            AtriaWhoop4DailyMotionBankRearmPolicy.Attestation? = nil
        #endif
        let manualWorkoutActive =
            AtriaPendingWorkoutIntent.isActiveForBLEContinuity(now: now)
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { now < $0 } == true
        let txSupportsWriteWithoutResponse =
            txCharacteristic?.properties.contains(.writeWithoutResponse)
                == true
        return .init(
            expectedIdentity: expectedIdentity,
            activeHistoryIdentity: activeHistoryIdentity,
            confirmedHistoryServe: confirmedHistoryServe,
            acceptedHistoryStart: acceptedHistoryStart,
            fullDrainAuthority: fullDrainAuthority,
            acceptedTerminal: terminal,
            acceptedHeartRate: acceptedHeartRate,
            operatingState: .init(
                batteryAllowsRearm:
                    batteryLevel < 0 || batteryLevel >= 10
                        || batteryIsCharging,
                manualWorkoutActive: manualWorkoutActive,
                calibrationHoldActive: calibrationHoldActive,
                stopPending: defaults.bool(
                    forKey:
                        Self.workoutHistoricalMotionBankStopPendingKey
                ),
                cutoverActive:
                    freshHistoryOwnerCutoverPending
                        || freshHistoryOwnerAdmissionPending
            ),
            commandPipe: .init(
                withResponseWritePending:
                    !writeCompletionLedger.pending.isEmpty,
                historyACKGatePending:
                    historyACKGate.requiresHistoryCallbackDeferral
                        || pendingHistoryEndACK != nil,
                replayACKPending: historicalReplayACKTask != nil,
                continuationPending:
                    historicalPageContinuationTask != nil
                        || historicalPageContinuationHasFutureAttempt,
                durableFlushPending: historyDurableFlushInFlight,
                ingressBarrierPending:
                    historicalAdmissionBatchInFlight
                        || hasPendingHistoricalTransportEvents
                        || historyDrain.pendingPersistenceCount > 0
            ),
            writeWithoutResponse: .init(
                supported: txSupportsWriteWithoutResponse,
                ready:
                    txSupportsWriteWithoutResponse
                        && peripheral?.canSendWriteWithoutResponse == true
            ),
            verifiedCapability: verifiedCapability
        )
    }

    @discardableResult
    private func submitGate4DailyBankRearm(
        expectedIdentity:
            AtriaWhoop4DailyMotionBankRearmPolicy.Identity
    ) -> Bool {
        let sequence = cmdSeq
        guard sendCommand(
            Cmd.toggleIMUModeHistorical,
            [0x01],
            mode: .withoutResponse
        ) else { return false }
        let armedAt = Date()
        workoutHistoricalMotionBankArmed = true
        workoutHistoricalMotionBankArmedConnectionStartedAt =
            expectedIdentity.connectionStartedAt
        AtriaWhoop4MotionBankCoverageLedger.open(
            at: armedAt,
            strapIdentifier:
                expectedIdentity.strapIdentifier.uuidString
        )
        AtriaMotionBankDutyCycleDiag.note("armed")
        let defaults = UserDefaults.standard
        defaults.set(
            true,
            forKey: Self.workoutHistoricalMotionBankEnabledKey
        )
        defaults.set(
            armedAt.timeIntervalSince1970,
            forKey: Self.workoutHistoricalMotionBankArmedAtKey
        )
        defaults.set(
            false,
            forKey: Self.workoutHistoricalMotionBankStopPendingKey
        )
        defaults.set(
            false,
            forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey
        )
        defaults.removeObject(
            forKey: Self.workoutHistoricalMotionBankRearmNotBeforeKey
        )
        gate4DailyBankRearmIntent = nil
        gate4DailyBankRearmTask = nil
        gate4DailyBankHistoryServeIdentity = nil
        gate4DailyBankHistoryStartIdentity = nil
        gate4DailyBankFullDrainAuthorityIdentity = nil
        gate4DailyBankTerminalIdentity = nil
        AtriaDebugLog(
            "ATRIADBG workout_motion_bank status=gate4_rearmed_during_history cmd=6901 seq=%d generation=%llu source=whoop4_v24 authority=safe_command_slot action=physical_validation_required",
            Int(sequence),
            expectedIdentity.generation
        )
        return true
    }

    private func clearGate4DailyBankRearmIntent(reason: String) {
        let hadIntent =
            gate4DailyBankRearmIntent != nil
                || gate4DailyBankRearmTask != nil
        gate4DailyBankRearmTask?.cancel()
        gate4DailyBankRearmTask = nil
        gate4DailyBankRearmIntent = nil
        gate4DailyBankHistoryServeIdentity = nil
        gate4DailyBankHistoryStartIdentity = nil
        gate4DailyBankFullDrainAuthorityIdentity = nil
        gate4DailyBankTerminalIdentity = nil
        if hadIntent {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=gate4_rearm_cleared reason=%@",
                reason
            )
        }
    }

    /// The stable 2A37 profile may already be connected without having
    /// discovered WHOOP's command characteristic. Request TX only—never a
    /// proprietary notification—so banked workout motion can arm without
    /// reopening the realtime R10 transport that failed the physical soak.
    private func requestWorkoutHistoricalMotionBankTransportIfNeeded(
        peripheral: CBPeripheral,
        reason: String
    ) {
        guard peripheral.state == .connected else { return }
        if let strapService = peripheral.services?.first(where: {
            $0.uuid == Self.UUIDs.strapService
        }) {
            peripheral.discoverCharacteristics(
                [Self.UUIDs.strapTX],
                for: strapService
            )
            AtriaDebugLog("ATRIADBG workout_motion_bank status=tx_discovery_requested reason=%@ scope=tx_only",
                          reason)
        } else {
            peripheral.discoverServices([Self.UUIDs.strapService])
            AtriaDebugLog("ATRIADBG workout_motion_bank status=service_discovery_requested reason=%@ scope=strap_service_only",
                          reason)
        }
    }

    @discardableResult
    private func stopWorkoutHistoricalMotionBankIfPossible(
        reason: String
    ) -> AtriaWhoop4MotionBankCoverageLedger.OffloadTicket? {
        let defaults = UserDefaults.standard
        let wasEnabled = workoutHistoricalMotionBankArmed
            || defaults.bool(forKey: Self.workoutHistoricalMotionBankEnabledKey)
        let hadDeferredPrearm = defaults.bool(
            forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey
        )
        guard wasEnabled || hadDeferredPrearm else { return nil }
        defaults.set(false,
                     forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey)
        // A TX-only discovery request may still be in flight when the policy
        // changes. Retire that intent without sending a stop for a bank that
        // was never armed.
        guard wasEnabled else {
            defaults.set(
                false,
                forKey: Self.workoutHistoricalMotionBankStopPendingKey
            )
            return nil
        }
        defaults.set(true, forKey: Self.workoutHistoricalMotionBankStopPendingKey)
        guard !offlineHistoricalSyncInProgress, !historyOnlyProbeMode else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=stop_deferred reason=%@ detail=history_transport_active action=retain_stop_intent_no_6900_no_command_collision",
                reason
            )
            return nil
        }
        guard let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse),
              peripheral.canSendWriteWithoutResponse,
              writeCompletionLedger.pending.isEmpty else {
            AtriaDebugLog("ATRIADBG workout_motion_bank status=stop_deferred reason=%@ action=stop_on_next_tx",
                          reason)
            return nil
        }
        let sequence = cmdSeq
        cmdSeq &+= 1
        let stoppedAt = Date()
        peripheral.writeValue(
            encodeFrame([
                Packet.command,
                sequence,
                Cmd.toggleIMUModeHistorical,
                0x00,
            ]),
            for: txCharacteristic,
            type: .withoutResponse
        )
        let closedTicket = AtriaWhoop4MotionBankCoverageLedger.close(
            at: stoppedAt,
            strapIdentifier: peripheral.identifier.uuidString,
            armedConnectionStartedAt:
                workoutHistoricalMotionBankArmedConnectionStartedAt
        )
        AtriaMotionBankDutyCycleDiag.note("stopped")
        let strapIdentifier = peripheral.identifier.uuidString
        if let closedTicket {
            // Preserve the identity returned by this exact 69/00 boundary.
            // Selecting a generic oldest attempts-zero ticket here can starve
            // this interval forever while raw history keeps rotating banks.
            defaults.set(
                closedTicket.id,
                forKey:
                    Self.workoutHistoricalMotionBankMaintenanceTicketIDKey
            )
        } else {
            persistNextUnattemptedMotionBankMaintenanceTicketIfNeeded(
                strapIdentifier: strapIdentifier,
                defaults: defaults
            )
        }
        workoutHistoricalMotionBankArmed = false
        workoutHistoricalMotionBankArmedConnectionStartedAt = nil
        defaults.set(false, forKey: Self.workoutHistoricalMotionBankEnabledKey)
        defaults.set(false, forKey: Self.workoutHistoricalMotionBankStopPendingKey)
        defaults.set(
            stoppedAt.addingTimeInterval(5).timeIntervalSince1970,
            forKey: Self.workoutHistoricalMotionBankRearmNotBeforeKey
        )
        AtriaDebugLog("ATRIADBG workout_motion_bank status=stopped cmd=6900 seq=%d reason=%@ action=async_offload",
                      Int(sequence),
                      reason)
        Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(1))
            guard let self, !Task.isCancelled else { return }
            _ = self
                .resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded(
                    reason: "workout_motion_bank_\(reason)",
                    maintenanceWindow: true
                )
        }
        return closedTicket
    }

    nonisolated static func workoutHistoricalMotionBankOffloadRetryDelay(
        attempts: Int
    ) -> TimeInterval {
        switch max(0, attempts) {
        case 0: return 0
        case 1: return 3
        case 2: return 10
        case 3: return 30
        default: return 60
        }
    }

    nonisolated static func historicalMotionBankTicketAttemptEligible(
        attempts: Int,
        applicationIsActive: Bool
    ) -> Bool {
        // Bounded background retries. Retries are already fenced by the
        // maintenance-window rule, the fifteen-minute offload cadence, the
        // per-attempt delay ladder and the exhaust cap, so a locked phone
        // performs at most one bounded retry per checkpoint boundary.
        // Requiring foreground on top of those fences meant an overnight
        // phone could never credit its banked coverage: every ticket waited
        // for a morning unlock while its data sat drained-ready on the strap.
        applicationIsActive
            || attempts < workoutHistoricalMotionBankMaximumOffloadAttempts
    }

    nonisolated static func shouldGracefullyExhaustHistoricalMotionBankOffload(
        attempts: Int,
        historyOwnerActive: Bool
    ) -> Bool {
        !historyOwnerActive
            && attempts >= workoutHistoricalMotionBankMaximumOffloadAttempts
    }

    nonisolated static func shouldEvaluateExhaustedMotionBankBeforeHotPathReturn(
        bankArmed: Bool,
        retryCooldownActive: Bool,
        boundTicketAttempts: Int?,
        historyOwnerActive: Bool
    ) -> Bool {
        guard bankArmed || retryCooldownActive,
              let boundTicketAttempts else { return false }
        return shouldGracefullyExhaustHistoricalMotionBankOffload(
            attempts: boundTicketAttempts,
            historyOwnerActive: historyOwnerActive
        )
    }

    /// Selects the ticket that a new history generation will own.
    ///
    /// A durable binding is the exact FIFO target until it is resolved.
    ///
    /// Rotating an attempted binding to a newer unattempted interval made a
    /// productive sequential drain appear to change targets even though WHOOP
    /// continued serving from its older read cursor. Preserve the bound ticket
    /// across reconnects; a newer ticket can become authority only after the
    /// prior binding is durably cleared.
    nonisolated static func historicalMotionBankOffloadTicketForNewGeneration(
        bound: AtriaWhoop4MotionBankCoverageLedger.OffloadTicket?,
        next: AtriaWhoop4MotionBankCoverageLedger.OffloadTicket?,
        maintenanceWindow: Bool = false,
        processInterruptedBoundRetry: Bool = false
    ) -> AtriaWhoop4MotionBankCoverageLedger.OffloadTicket? {
        let bound = bound.flatMap {
            $0.effectiveRecoveryMode == .directOffload ? $0 : nil
        }
        let next = next.flatMap {
            $0.effectiveRecoveryMode == .directOffload ? $0 : nil
        }
        // A process-interrupted exact transaction already owns the durable
        // binding and gets one relaunch-scoped continuation. A stale deferred
        // maintenance hint must not rotate that recovery to a newer
        // attempts=0 interval before the continuation has first refusal.
        if processInterruptedBoundRetry, let bound {
            return bound
        }
        // A retained binding remains authoritative while one sequential drain
        // is active or being reacquired. At a later intentional bank close,
        // however, an unattempted present-capture interval must receive its
        // first request before another retry of that older binding. This is a
        // transport-priority change only; the older ticket and its missing
        // coverage remain durable.
        if maintenanceWindow,
           let next,
           next.attempts == 0,
           (bound?.attempts ?? 0) > 0 {
            return next
        }
        return bound ?? next
    }

    nonisolated static func historicalMotionBankEffectiveMaintenanceWindow(
        requested: Bool,
        deferred: Bool
    ) -> Bool {
        requested || deferred
    }

    /// A closed bank must receive one first-attempt offload even when the close
    /// came from an ordinary BLE loss instead of the hourly timer. Without
    /// this durable hint, an older attempted binding wins every reconnect and
    /// newly closed all-day intervals accumulate forever at attempts == 0.
    private func persistNextUnattemptedMotionBankMaintenanceTicketIfNeeded(
        strapIdentifier: String,
        defaults: UserDefaults = .standard
    ) {
        if pendingWorkoutHistoricalMotionBankMaintenanceTicket(
            strapIdentifier: strapIdentifier,
            defaults: defaults
        ) != nil {
            return
        }
        guard let ticket =
                AtriaWhoop4MotionBankCoverageLedger.nextPendingOffload(
                    strapIdentifier: strapIdentifier
                ),
              ticket.attempts == 0 else {
            return
        }
        defaults.set(
            ticket.id,
            forKey: Self.workoutHistoricalMotionBankMaintenanceTicketIDKey
        )
    }

    private func pendingWorkoutHistoricalMotionBankMaintenanceTicket(
        strapIdentifier: String,
        defaults: UserDefaults = .standard
    ) -> AtriaWhoop4MotionBankCoverageLedger.OffloadTicket? {
        guard let ticketID = defaults.string(
            forKey:
                Self.workoutHistoricalMotionBankMaintenanceTicketIDKey
        ) else { return nil }
        guard let ticket =
                AtriaWhoop4MotionBankCoverageLedger.pendingOffload(
                    id: ticketID,
                    strapIdentifier: strapIdentifier
                ),
              ticket.effectiveRecoveryMode == .directOffload,
              ticket.attempts == 0 else {
            // Resolution, exhaustion, or an already-started attempt retires
            // only this scheduling hint. The ledger remains the coverage
            // authority and is never modified here.
            defaults.removeObject(
                forKey:
                    Self.workoutHistoricalMotionBankMaintenanceTicketIDKey
            )
            return nil
        }
        return ticket
    }

    /// Mints a raw catch-up token only from the exact callback source already
    /// accepted for the canonical connected object. The token expires before a
    /// deferred MainActor turn could reuse it as a different transport request.
    private func makeConnectedRawHistoryCatchUpRequestAuthority(
        peripheral: CBPeripheral,
        callbackSource: AtriaBLECallbackEpochFence.Source,
        intent: ConnectedRawHistoryCatchUpIntent,
        now: Date
    ) -> ConnectedRawHistoryCatchUpRequestAuthority? {
        let authority = ConnectedRawHistoryCatchUpRequestAuthority(
            authorityID: UUID(),
            strapIdentifier: peripheral.identifier.uuidString,
            callbackSource: callbackSource,
            intent: intent,
            mintedAt: now
        )
        guard connectedRawHistoryCatchUpRequestAuthorityIsValid(
            authority,
            peripheral: peripheral,
            forActiveGeneration: false,
            now: now
        ) else { return nil }
        return authority
    }

    private func connectedRawHistoryCatchUpRequestAuthorityIsValid(
        _ authority: ConnectedRawHistoryCatchUpRequestAuthority,
        peripheral: CBPeripheral,
        forActiveGeneration: Bool,
        now: Date = Date()
    ) -> Bool {
        let explicitMotionOwnership = Self
            .explicitMotionOwnershipBlocksHistory(
                pendingWorkoutIntentActive:
                    AtriaPendingWorkoutIntent
                        .isActiveForBLEContinuity(now: now),
                inMemoryLeaseHeld: workoutMotionOwnerStartedAt != nil,
                calibrationHoldActive:
                    workoutMotionCalibrationHoldUntil.map { now < $0 } == true
            )
        guard self.peripheral === peripheral,
              peripheral.state == .connected,
              authority.strapIdentifier == peripheral.identifier.uuidString,
              authority.callbackSource.peripheralID == peripheral.identifier,
              authority.callbackSource.peripheralObjectID
                == ObjectIdentifier(peripheral),
              bleCallbackEpochFence.accepts(
                source: authority.callbackSource,
                peripheralConnected: true
              ),
              !explicitMotionOwnership,
              let connectionStart = connectedAt,
              let acceptedAt = lastAcceptedHRAt,
              acceptedAt >= connectionStart else { return false }

        let applicationIsBackground =
            UIApplication.shared.applicationState == .background
        switch authority.intent {
        case .background:
            if !forActiveGeneration {
                guard applicationIsBackground else { return false }
            }
        case .foregroundAutomatic:
            if !forActiveGeneration {
                guard UIApplication.shared.applicationState == .active else {
                    return false
                }
            }
        case .queuedPull(let intentID):
            if !forActiveGeneration {
                guard queuedConnectedRawHistoryCatchUpIntent?.id == intentID else {
                    return false
                }
            }
        }

        guard !Self.shouldParkConnectedRawHistoryCatchUpForPowerPressure(
            thermalState: ProcessInfo.processInfo.thermalState
        ) else { return false }
        if forActiveGeneration {
            let liveSilenceLimit = connectedRawHistoryCatchUpLiveSilenceLimit(
                for: authority.intent
            )
            return now.timeIntervalSince(acceptedAt) >= 0
                && now.timeIntervalSince(acceptedAt)
                    < liveSilenceLimit
        }
        guard now.timeIntervalSince(authority.mintedAt) >= 0,
              now.timeIntervalSince(authority.mintedAt)
                <= connectedRawHistoryCatchUpAuthorityLifetime,
              now.timeIntervalSince(connectionStart) >= 60,
              now.timeIntervalSince(acceptedAt) >= 0,
              now.timeIntervalSince(acceptedAt) <= 45,
              connectedEpochAcceptedHeartRateSamples >= 10,
              currentVerifiedRawHistoryCapability(),
              strapBacklogPendingForCatchUp(now: now) else { return false }
        return true
    }

    private func connectedRawHistoryCatchUpLiveSilenceLimit(
        for intent: ConnectedRawHistoryCatchUpIntent
    ) -> TimeInterval {
        switch intent {
        case .background:
            return connectedRawHistoryCatchUpBackgroundLiveSilenceLimit
        case .foregroundAutomatic, .queuedPull:
            return connectedRawHistoryCatchUpForegroundLiveSilenceLimit
        }
    }

    private func activeConnectedRawHistoryCatchUpAuthority(
        generation: UInt64
    ) -> ConnectedRawHistoryCatchUpGenerationAuthority? {
        guard let authority =
                activeConnectedRawHistoryCatchUpGenerationAuthority,
              authority.generation == generation else { return nil }
        return authority
    }

    private func activeConnectedRealtimePreservingHistoryAuthorityIsValid(
        generation: UInt64,
        peripheral: CBPeripheral
    ) -> Bool {
        if let authority = activeConnectedMotionBankHistoryAuthority(
            generation: generation
        ) {
            return connectedMotionBankHistoryRequestAuthorityIsValid(
                authority.request,
                peripheral: peripheral
            )
        }
        if let authority = activeConnectedRawHistoryCatchUpAuthority(
            generation: generation
        ) {
            return connectedRawHistoryCatchUpRequestAuthorityIsValid(
                authority.request,
                peripheral: peripheral,
                forActiveGeneration: true
            )
        }
        return false
    }

    private func activeConnectedRealtimePreservingHistoryAuthorityExists(
        generation: UInt64
    ) -> Bool {
        activeConnectedMotionBankHistoryAuthority(generation: generation) != nil
            || activeConnectedRawHistoryCatchUpAuthority(
                generation: generation
            ) != nil
    }

    /// Mints the only motion-bank authority which can share a connected standard-HR link
    /// with history. The durable ticket is selected by the motion-bank ledger;
    /// a recent accepted 2A37 sample proves this exact connection is healthy;
    /// and the epoch fence binds the token to one CBPeripheral object, not just
    /// its reusable UUID. Canonical-object/pending-connect exclusion is still
    /// performed atomically at the transaction boundary.
    private func makeConnectedMotionBankHistoryRequestAuthority(
        ticket: AtriaWhoop4MotionBankCoverageLedger.OffloadTicket,
        peripheral: CBPeripheral,
        now: Date
    ) -> ConnectedMotionBankHistoryRequestAuthority? {
        guard self.peripheral === peripheral,
              peripheral.state == .connected,
              ticket.strapIdentifier == peripheral.identifier.uuidString,
              ticket.effectiveRecoveryMode == .directOffload,
              let connectionStart = connectedAt,
              let acceptedAt = lastAcceptedHRAt,
              acceptedAt >= connectionStart,
              now.timeIntervalSince(acceptedAt)
                < connectedMotionBankHistoryLiveSilenceLimit,
              let callbackSource = bleCallbackEpochFence.captureIfAccepted(
                  peripheralID: peripheral.identifier,
                  peripheralObjectID: ObjectIdentifier(peripheral),
                  peripheralConnected: true
              ) else {
            return nil
        }
        return .init(
            ticketID: ticket.id,
            strapIdentifier: ticket.strapIdentifier,
            callbackSource: callbackSource
        )
    }

    /// Revalidates the complete typed tuple before admission or a synchronous
    /// CoreBluetooth call. The persisted active-ticket binding is part of the
    /// proof so a resolved/exhausted ticket cannot leave a stale command owner.
    private func connectedMotionBankHistoryRequestAuthorityIsValid(
        _ authority: ConnectedMotionBankHistoryRequestAuthority,
        peripheral: CBPeripheral
    ) -> Bool {
        guard self.peripheral === peripheral,
              peripheral.state == .connected,
              authority.strapIdentifier == peripheral.identifier.uuidString,
              UserDefaults.standard.string(
                  forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
              ) == authority.ticketID,
              let ticket = AtriaWhoop4MotionBankCoverageLedger.pendingOffload(
                  id: authority.ticketID,
                  strapIdentifier: authority.strapIdentifier
              ),
              ticket.effectiveRecoveryMode == .directOffload else {
            return false
        }
        return bleCallbackEpochFence.accepts(
            source: authority.callbackSource,
            peripheralConnected: true
        )
    }

    private func activeConnectedMotionBankHistoryAuthority(
        generation: UInt64
    ) -> ConnectedMotionBankHistoryGenerationAuthority? {
        guard let authority =
                activeConnectedMotionBankHistoryGenerationAuthority,
              authority.generation == generation else {
            return nil
        }
        return authority
    }

    private func armConnectedRealtimePreservingHistoryBudget(
        generation: UInt64
    ) {
        connectedMotionBankHistoryBudgetTask?.cancel()
        connectedMotionBankHistoryBudgetTask = nil
        guard activeConnectedRealtimePreservingHistoryAuthorityExists(
            generation: generation
        ) else { return }
        let startedAt = Date()
        connectedMotionBankHistoryBudgetTask = Task { @MainActor [weak self] in
            guard let self else { return }
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(1))
                guard !Task.isCancelled,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation,
                      self.activeConnectedRealtimePreservingHistoryAuthorityExists(
                        generation: generation
                      ) else {
                    return
                }
                guard let current = self.peripheral,
                      self.activeConnectedRealtimePreservingHistoryAuthorityIsValid(
                        generation: generation,
                        peripheral: current
                      ) else {
                    _ = self
                        .finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                            generation: generation,
                            reason:
                                "exact_connected_history_authority_lost"
                        )
                    return
                }
                let now = Date()
                let thermalState = ProcessInfo.processInfo.thermalState
                let disposition: ConnectedMotionBankHistoryBudgetDisposition
                if let rawAuthority =
                        self.activeConnectedRawHistoryCatchUpAuthority(
                            generation: generation
                        ) {
                    // Noncritical raw catch-up is sliced synchronously at its
                    // intent/thermal clean-ACK target (one page whenever the
                    // slice is backgrounded). This timer may park critical
                    // heat or reject an invalid clock, but it never cuts
                    // through a page. A true no-progress transport remains
                    // bounded by the progress-clocked history idle watchdog.
                    disposition = Self
                        .connectedRawHistoryCatchUpBudgetDisposition(
                            startedAt: rawAuthority.startedAt,
                            lastAcceptedHeartRateAt: self.lastAcceptedHRAt,
                            now: now,
                            liveSilenceLimit: self
                                .connectedRawHistoryCatchUpLiveSilenceLimit(
                                    for: rawAuthority.request.intent
                                ),
                            thermalState: thermalState,
                            durableBoundaryReached:
                                !self.historicalAdmissionFailed
                                && self.historicalArchiveWriteFailures == 0
                                && self.historicalDrainTelemetry.persistErrors == 0
                                && self.historicalDrainTelemetry.flushErrors == 0
                                && self.historicalDrainTelemetry.ackSucceeded > 0
                        )
                } else {
                    disposition = Self
                        .connectedMotionBankHistoryBudgetDisposition(
                            startedAt: startedAt,
                            lastAcceptedHeartRateAt: self.lastAcceptedHRAt,
                            now: now,
                            liveSilenceLimit:
                                self.connectedMotionBankHistoryLiveSilenceLimit,
                            absoluteLimit:
                                self.connectedMotionBankHistoryAbsoluteLimit,
                            powerPressureActive: Self
                                .shouldParkConnectedMotionBankHistoryForPowerPressure(
                                    thermalState: thermalState,
                                    lowPowerModeEnabled:
                                        ProcessInfo.processInfo
                                            .isLowPowerModeEnabled
                                )
                        )
                }
                switch disposition {
                case .keepServing:
                    continue
                case .finishForPowerPressure:
                    if self.activeConnectedMotionBankHistoryAuthority(
                        generation: generation
                    ) != nil {
                        self.connectedMotionBankHistoryAdmissionRetryNotBefore =
                            Self.connectedMotionBankHistoryPowerRetryNotBefore(
                                existing: self
                                    .connectedMotionBankHistoryAdmissionRetryNotBefore,
                                now: now
                            )
                    }
                    _ = self
                        .finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                            generation: generation,
                            reason:
                                "exact_connected_history_power_pressure"
                        )
                    return
                case .finishForLiveHeartRateSilence:
                    _ = self
                        .finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                            generation: generation,
                            reason:
                                "exact_connected_history_live_hr_silence"
                        )
                    return
                case .finishForAbsoluteBudget:
                    _ = self
                        .finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                            generation: generation,
                            reason:
                                "exact_connected_history_absolute_budget"
                        )
                    return
                }
            }
        }
    }

    private func holdConnectedMotionBankBeforeFreshHRFirstRefusal(
        ticketID: String,
        now: Date
    ) {
        guard connectedMotionBankPreFreshHRArmGate.hold(
            ticketID: ticketID,
            now: now,
            waitLimit: Self.historicalArchiveWarmReplayWaitLimit
        ) else { return }
        connectedMotionBankPreFreshHRArmTask?.cancel()
        connectedMotionBankPreFreshHRArmTask = Task {
            @MainActor [weak self] in
            try? await Task.sleep(
                for: .seconds(Self.historicalArchiveWarmReplayWaitLimit)
            )
            guard let self, !Task.isCancelled else { return }
            _ = self.releaseConnectedMotionBankPreFreshHRFirstRefusal(
                reason: "first_hr_timeout",
                expectedTicketID: ticketID
            )
        }
        AtriaDebugLog(
            "ATRIADBG workout_motion_bank_offload status=pre_fresh_hr_first_refusal ticket=%@ wait_s=%d action=hold_successor_arm_for_exact_ticket_no_history_command",
            ticketID,
            Int(Self.historicalArchiveWarmReplayWaitLimit)
        )
    }

