    @discardableResult
    private func resumeConnectedMotionBankAfterLocalDependencyIfNeeded(
        _ dependency: ConnectedMotionBankDeferredLocalDependency
    ) -> Bool {
        guard connectedMotionBankLocalDependency == dependency else {
            return false
        }
        let resolution = connectedMotionBankLocalDependencyRetryGate
            .resolveReady(now: Date())
        connectedMotionBankLocalDependency = nil
        connectedMotionBankLocalDependencyRetryTask?.cancel()
        connectedMotionBankLocalDependencyRetryTask = nil
        switch resolution {
        case .none:
            return false
        case .rearm(let ticketID):
            armWorkoutHistoricalMotionBankIfPossible(
                reason: "\(dependency.rawValue)_ready_after_timeout",
                prioritizePresentCaptureOverProcessRetry: true
            )
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=local_dependency_first_refusal_expired dependency=%@ ticket=%@ action=rearm_present_capture_no_history_command",
                dependency.rawValue,
                ticketID
            )
            return true
        case .retry(let ticketID):
            let previousTerminalRelease =
                terminalMaterializationMotionBankReleaseInProgress
            if dependency == .terminalMaterialization {
                terminalMaterializationMotionBankReleaseInProgress = true
            }
            let started = resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded(
                reason: "\(dependency.rawValue)_ready_exact_motion_bank",
                expectedLocalDependencyTicketID: ticketID
            )
            terminalMaterializationMotionBankReleaseInProgress =
                previousTerminalRelease
            if !started {
                armWorkoutHistoricalMotionBankIfPossible(
                    reason: "\(dependency.rawValue)_ready_ineligible",
                    prioritizePresentCaptureOverProcessRetry: true
                )
            }
            return true
        }
    }

    /// Queue maintenance is deliberately permitted between exact raw slices.
    /// It issues no BLE command and preserves every closed missing-coverage
    /// interval, but prevents a sustained HR FIFO continuation from bypassing
    /// pruning/normalization forever on each accepted-HR callback.
    private func maintainPendingWorkoutMotionBankTickets(
        reason: String,
        now: Date,
        additionallyProtectedIDs: Set<String> = []
    ) {
        guard !offlineHistoricalSyncInProgress,
              !historyOnlyProbeMode,
              let connectedPeripheral = peripheral,
              connectedPeripheral.state == .connected else { return }
        let strapIdentifier = connectedPeripheral.identifier.uuidString
        let defaults = UserDefaults.standard
        let protectedKeys = [
            Self.workoutHistoricalMotionBankActiveTicketIDKey,
            Self.workoutHistoricalMotionBankTransportDeferredTicketIDKey,
            Self.workoutHistoricalMotionBankMaintenanceTicketIDKey,
        ]
        var protectedIDs = additionallyProtectedIDs
        for key in protectedKeys {
            if let identifier = defaults.string(forKey: key) {
                protectedIDs.insert(identifier)
            }
        }

        let prunedShortTickets =
            AtriaWhoop4MotionBankCoverageLedger
                .pruneUnrecoverableShortOffloads()
        let exhaustedIDs =
            AtriaWhoop4MotionBankCoverageLedger.exhaustOffloads(
                endingAtOrBefore: now.addingTimeInterval(
                    -Self.workoutHistoricalMotionBankMaximumBlockingAge
                ),
                strapIdentifier: strapIdentifier,
                protectedIDs: protectedIDs
            )
        let normalization =
            AtriaWhoop4MotionBankCoverageLedger.normalizePendingOffloads(
                strapIdentifier: strapIdentifier,
                protectedIDs: protectedIDs
            )
        let retiredIDs = Set(exhaustedIDs + normalization.removedIDs)
        for key in protectedKeys {
            guard let identifier = defaults.string(forKey: key) else {
                continue
            }
            let stillPending = AtriaWhoop4MotionBankCoverageLedger
                .pendingOffload(
                    id: identifier,
                    strapIdentifier: strapIdentifier
                ) != nil
            if retiredIDs.contains(identifier) || !stillPending {
                defaults.removeObject(forKey: key)
            }
        }
        if prunedShortTickets > 0 {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=short_tickets_pruned count=%d minimum_s=%.1f reason=%@ action=retain_as_missing_coverage_without_impossible_ble_jobs",
                prunedShortTickets,
                AtriaWhoop4MotionBankCoverageLedger
                    .minimumRecoverableOffloadDuration,
                reason
            )
        }
        if !exhaustedIDs.isEmpty {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=stale_jobs_exhausted count=%d maximum_age_s=%d reason=%@ action=retain_missing_coverage_prioritize_present_capture",
                exhaustedIDs.count,
                Int(Self.workoutHistoricalMotionBankMaximumBlockingAge),
                reason
            )
        }
        if !normalization.removedIDs.isEmpty {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=pending_jobs_normalized removed=%d retained=%d protected=%d reason=%@ action=retain_closed_missing_evidence_prioritize_new_unattempted",
                normalization.removedIDs.count,
                normalization.retainedCount,
                protectedIDs.count,
                reason
            )
        }
    }

    @discardableResult
    private func resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded(
        reason: String,
        maintenanceWindow: Bool = false,
        expectedArchiveWarmTicketID: String? = nil,
        expectedAdmissionLedgerTicketID: String? = nil,
        expectedLocalDependencyTicketID: String? = nil
    ) -> Bool {
        let now = Date()
        let retryCooldownActive =
            connectedMotionBankHistoryAdmissionRetryNotBefore.map {
                now < $0
            } == true
        if workoutHistoricalMotionBankArmed || retryCooldownActive {
            evaluateExhaustedMotionBankBeforeHotPathReturnIfNeeded(
                reason: reason,
                bankArmed: workoutHistoricalMotionBankArmed,
                retryCooldownActive: retryCooldownActive
            )
            return false
        }
        maintainPendingWorkoutMotionBankTickets(
            reason: reason,
            now: now,
            additionallyProtectedIDs: Set([
                expectedArchiveWarmTicketID,
                expectedAdmissionLedgerTicketID,
                expectedLocalDependencyTicketID,
            ].compactMap { $0 })
        )
        guard !connectedRawHistoryCatchUpContinuationPending else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=deferred reason=%@ detail=connected_raw_fifo_continuation action=no_selector_no_attempt_no_cadence_mutation",
                reason
            )
            return false
        }
        guard !connectedRawNoRadioCaptureTurnIsCurrent() else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=deferred reason=%@ detail=connected_raw_no_radio_capture_turn action=no_selector_no_attempt_no_cadence_mutation_rearm_present_bank_first",
                reason
            )
            return false
        }
        guard connectedRawHistoryCatchUpPublicationYield == nil else {
            // The low-bandwidth 0x69 present-capture rearm remains available to
            // callers after this false return, but no motion-bank offload may
            // seize the shared command/archive lane during the bounded local
            // publication lease.
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=deferred reason=%@ detail=connected_raw_publication_yield action=allow_present_capture_rearm_no_history_command",
                reason
            )
            return false
        }
        if expectedArchiveWarmTicketID == nil,
           connectedMotionBankArchiveWarmRetryGate.isHolding {
            if connectedMotionBankArchiveWarmRetryGate.shouldSuppressHotPath(
                now: now,
                applicationIsActive:
                    UIApplication.shared.applicationState == .active,
                archiveStillWarming:
                    historicalArchiveWarmState == .warming
            ) {
                return true
            }
            releaseConnectedMotionBankArchiveWarmFirstRefusal(
                reason: "archive_warm_hold_ineligible"
            )
            return true
        }
        if expectedAdmissionLedgerTicketID == nil,
           connectedMotionBankAdmissionLedgerRetryGate.isHolding {
            if connectedMotionBankAdmissionLedgerRetryGate
                .shouldSuppressHotPath(
                    now: now,
                    applicationIsActive:
                        UIApplication.shared.applicationState == .active,
                    archiveStillWarming:
                        historicalAdmissionLedgerPreparationTask != nil
                ) {
                return true
            }
            releaseConnectedMotionBankAdmissionLedgerFirstRefusal(
                reason: "history_admission_ledger_hold_ineligible"
            )
            return true
        }
        if expectedLocalDependencyTicketID == nil,
           connectedMotionBankLocalDependencyRetryGate.isHolding {
            let dependencyStillPending: Bool
            switch connectedMotionBankLocalDependency {
            case .orphanArchive?:
                dependencyStillPending =
                    orphanHistoricalIngressArchiveInFlight
            case .terminalMaterialization?:
                dependencyStillPending =
                    historicalConsumerMaterializationInFlight
            case .capabilityQualification?:
                dependencyStillPending =
                    historyCapabilityQualificationPeripheralID != nil
            case nil:
                dependencyStillPending = false
            }
            if connectedMotionBankLocalDependencyRetryGate
                .shouldSuppressHotPath(
                    now: now,
                    applicationIsActive:
                        UIApplication.shared.applicationState == .active,
                    archiveStillWarming: dependencyStillPending
                ) {
                return true
            }
            releaseConnectedMotionBankLocalDependencyFirstRefusal(
                reason: "local_dependency_hold_ineligible"
            )
            return true
        }
        let defaults = UserDefaults.standard
        let powerPressureActive = Self
            .shouldParkConnectedMotionBankHistoryForPowerPressure(
                thermalState: ProcessInfo.processInfo.thermalState,
                lowPowerModeEnabled:
                    ProcessInfo.processInfo.isLowPowerModeEnabled
            )
        if powerPressureActive,
           let retryNotBefore =
                connectedMotionBankHistoryAdmissionRetryNotBefore,
           now < retryNotBefore {
            return false
        }
        repairTransportOnlyClearedWorkoutMotionTicketIfNeeded()
        let manualWorkoutActive =
            AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { Date() < $0 } == true
        let historyOwnerActive =
            offlineHistoricalSyncInProgress || historyOnlyProbeMode
        let connectedPeripheral = peripheral.flatMap {
            $0.state == .connected ? $0 : nil
        }
        if freshHistoryOwnerBoundaryFailureLatched && !maintenanceWindow {
            // A failed durability cutover may not loop from the one-Hz HR hot
            // path. Keep the exact ticket durable and let present capture
            // resume; the next intentional bank close can retry once.
            return false
        }
        let acceptedCurrentConnectionHR =
            connectedAt.flatMap { connectionStart in
                lastAcceptedHRAt.map { $0 >= connectionStart }
            } == true
        let ticket = connectedPeripheral.flatMap { peripheral in
            let strapIdentifier = peripheral.identifier.uuidString
            var maintenanceTicket =
                pendingWorkoutHistoricalMotionBankMaintenanceTicket(
                    strapIdentifier: strapIdentifier,
                    defaults: defaults
                )
            if maintenanceWindow, maintenanceTicket == nil,
               let next =
                   AtriaWhoop4MotionBankCoverageLedger.nextPendingOffload(
                       strapIdentifier: strapIdentifier
                   ),
               next.attempts == 0 {
                defaults.set(
                    next.id,
                    forKey:
                        Self
                            .workoutHistoricalMotionBankMaintenanceTicketIDKey
                )
                maintenanceTicket = next
            }
            let effectiveMaintenanceWindow =
                Self.historicalMotionBankEffectiveMaintenanceWindow(
                    requested: maintenanceWindow,
                    deferred: maintenanceTicket != nil
                )
            let bound = UserDefaults.standard.string(
                forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
            ).flatMap { boundID in
                AtriaWhoop4MotionBankCoverageLedger
                .pendingOffload(
                    id: boundID,
                    strapIdentifier: strapIdentifier
                )
            }.flatMap { ticket in
                ticket.effectiveRecoveryMode == .directOffload ? ticket : nil
            }
            let lastStartedAtValue = defaults.double(
                forKey:
                    Self.workoutHistoricalMotionBankLastOffloadStartedAtKey
            )
            let lastStartedAt = lastStartedAtValue > 0
                ? Date(timeIntervalSince1970: lastStartedAtValue)
                : nil
            let processInterruptedBoundRetry = bound.map {
                Self.historicalMotionBankProcessInterruptedRetryEligible(
                    attempts: $0.attempts,
                    ticketID: $0.id,
                    persistedActiveTicketID: defaults.string(
                        forKey:
                            Self
                                .workoutHistoricalMotionBankActiveTicketIDKey
                    ),
                    lastStartedAt: lastStartedAt,
                    processLaunchStartedAt: processLaunchStartedAt
                )
            } == true
            let next = maintenanceTicket
                ?? AtriaWhoop4MotionBankCoverageLedger.nextPendingOffload(
                    strapIdentifier: strapIdentifier
                )
            return Self.historicalMotionBankOffloadTicketForNewGeneration(
                bound: bound,
                next: next,
                maintenanceWindow: effectiveMaintenanceWindow,
                processInterruptedBoundRetry:
                    processInterruptedBoundRetry
            )
        }
        let effectiveMaintenanceWindow =
            maintenanceWindow
                || connectedPeripheral.flatMap {
                    pendingWorkoutHistoricalMotionBankMaintenanceTicket(
                        strapIdentifier: $0.identifier.uuidString,
                        defaults: defaults
                    )
                } != nil
        if let expectedArchiveWarmTicketID,
           ticket?.id != expectedArchiveWarmTicketID {
            return false
        }
        if let expectedAdmissionLedgerTicketID,
           ticket?.id != expectedAdmissionLedgerTicketID {
            return false
        }
        if let expectedLocalDependencyTicketID,
           ticket?.id != expectedLocalDependencyTicketID {
            return false
        }
        if powerPressureActive,
           Self.historicalMotionBankOffloadEligible(
                manualWorkoutActive: manualWorkoutActive,
                calibrationHoldActive: calibrationHoldActive,
                historyOwnerActive: historyOwnerActive,
                postHistoryRestorationActive:
                    postHistoryLiveRestorationTask != nil,
                bankArmed: workoutHistoricalMotionBankArmed,
                connectedWithAcceptedHR:
                    connectedPeripheral != nil && acceptedCurrentConnectionHR,
                hasPendingTicket: ticket != nil
           ), let ticket {
            let activeTicketChanged = defaults.string(
                forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
            ) != ticket.id
            let deferredTicketChanged = defaults.string(
                forKey: Self
                    .workoutHistoricalMotionBankTransportDeferredTicketIDKey
            ) != ticket.id
            if activeTicketChanged {
                defaults.set(
                    ticket.id,
                    forKey:
                        Self.workoutHistoricalMotionBankActiveTicketIDKey
                )
            }
            if deferredTicketChanged {
                defaults.set(
                    ticket.id,
                    forKey: Self
                        .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                )
            }
            connectedMotionBankHistoryAdmissionRetryNotBefore = Self
                .connectedMotionBankHistoryPowerRetryNotBefore(
                    existing:
                        connectedMotionBankHistoryAdmissionRetryNotBefore,
                    now: now
                )
            // This reservation is neither an attempt nor a cadence fact. It
            // lets the exact attempts==0 ticket reopen present 0x69 capture,
            // while no history request, connect, cancel, or rebuild is issued.
            armWorkoutHistoricalMotionBankIfPossible(
                reason: "power_pressure_deferred_\(reason)",
                prioritizePresentCaptureOverProcessRetry: true
            )
            if activeTicketChanged || deferredTicketChanged {
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank_offload status=power_pressure_parked ticket=%@ reason=%@ action=retain_attempt_zero_rearm_present_capture_no_history_request_no_cancel",
                    ticket.id,
                    reason
                )
            }
            return false
        }
        if let ticket,
           processInterruptedMotionBankReservedTicketID == ticket.id {
            if historicalConsumerMaterializationInFlight,
               !offlineHistoricalSyncInProgress {
                // The retained request owns only a future retry. Local
                // terminal projection has no BLE transport, so release this
                // process-local claim and let the accepted-HR caller reopen
                // present all-day motion capture. The exact ticket remains in
                // the durable ledger and the pending request remains retained.
                processInterruptedMotionBankReservationTask?.cancel()
                processInterruptedMotionBankReservationTask = nil
                processInterruptedMotionBankReservedTicketID = nil
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank_offload status=local_materialization_deferred ticket=%@ reason=%@ action=release_process_claim_resume_present_capture_preserve_exact_ticket",
                    ticket.id,
                    reason
                )
                return false
            }
            if !manualWorkoutActive,
               !calibrationHoldActive,
               UIApplication.shared.applicationState == .active {
                // The first callback already retained an exact authorized
                // request. Claim later HR callbacks without re-entering
                // admission or reopening 0x69 underneath that request. A
                // bounded watchdog below releases this process-local claim if
                // transport never starts.
                return true
            }
            // Background capture and an explicit workout/calibration outrank a
            // process-local retry reservation. The exact ticket itself stays
            // durable for its later maintenance opportunity.
            processInterruptedMotionBankReservationTask?.cancel()
            processInterruptedMotionBankReservationTask = nil
            processInterruptedMotionBankReservedTicketID = nil
        }
        guard Self.historicalMotionBankOffloadEligible(
            manualWorkoutActive: manualWorkoutActive,
            calibrationHoldActive: calibrationHoldActive,
            historyOwnerActive: historyOwnerActive,
            postHistoryRestorationActive:
                postHistoryLiveRestorationTask != nil,
            bankArmed: workoutHistoricalMotionBankArmed,
            connectedWithAcceptedHR:
                connectedPeripheral != nil && acceptedCurrentConnectionHR,
            hasPendingTicket: ticket != nil
        ), let ticket else { return false }
        // A ticket whose bounded physical transport budget is already spent
        // must reach compact-store terminal evaluation even while the app is
        // backgrounded. Placing the foreground/cadence gates first retained
        // an unfillable attempts=4 ticket on every accepted-HR callback and
        // permanently prevented the successor all-day bank from arming.
        //
        // The evaluator remains the sole authority: it first admits any
        // already-durable >=90% result, otherwise it removes only the pending
        // transport job while retaining the interval as missing coverage.
        if Self.shouldGracefullyExhaustHistoricalMotionBankOffload(
            attempts: ticket.attempts,
            historyOwnerActive: historyOwnerActive
        ) {
            evaluatePendingWorkoutHistoricalMotionBankOffload(
                reason: "bounded_exhaustion_\(reason)",
                allowRetry: false
            )
            return false
        }
        let lastOffloadStartedAtValue = defaults.double(
            forKey: Self.workoutHistoricalMotionBankLastOffloadStartedAtKey
        )
        let lastOffloadStartedAt = lastOffloadStartedAtValue > 0
            ? Date(timeIntervalSince1970: lastOffloadStartedAtValue)
            : nil
        let persistedActiveTicketID = defaults.string(
            forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
        )
        let processInterruptedRetry =
            Self.historicalMotionBankProcessInterruptedRetryEligible(
                attempts: ticket.attempts,
                ticketID: ticket.id,
                persistedActiveTicketID: persistedActiveTicketID,
                lastStartedAt: lastOffloadStartedAt,
                processLaunchStartedAt: processLaunchStartedAt
            )
        guard Self.historicalMotionBankRetryEligible(
            attempts: ticket.attempts,
            maintenanceWindow: effectiveMaintenanceWindow,
            processInterruptedRetry: processInterruptedRetry
        ) else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=retry_deferred_for_present_capture ticket=%@ attempts=%d reason=%@ action=keep_bank_open_until_explicit_checkpoint",
                ticket.id,
                ticket.attempts,
                reason
            )
            return false
        }
        guard Self.historicalMotionBankTicketAttemptEligible(
            attempts: ticket.attempts,
            applicationIsActive:
                UIApplication.shared.applicationState == .active
        ) else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=retry_deferred ticket=%@ attempts=%d reason=%@ action=retain_until_foreground_evaluation_preserve_live",
                ticket.id,
                ticket.attempts,
                reason
            )
            return false
        }
        #if DEBUG
        let diagnosticDailyCheckpointBypass =
            reason.hasPrefix("workout_motion_bank_daily_checkpoint_")
                && ProcessInfo.processInfo.arguments.contains(
                    "--atria-gate4-rearm-bank-during-history"
                )
        #else
        let diagnosticDailyCheckpointBypass = false
        #endif
        guard Self.historicalMotionBankOffloadCadenceEligible(
            attempts: ticket.attempts,
            now: now,
            lastStartedAt: lastOffloadStartedAt,
            diagnosticDailyCheckpointBypass:
                diagnosticDailyCheckpointBypass
        ) else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=cadence_deferred ticket=%@ reason=%@ action=preserve_live_bank_until_bounded_retry",
                ticket.id,
                reason
            )
            return false
        }
        if let lastAttemptAt = ticket.lastAttemptAt {
            let delay = Self.workoutHistoricalMotionBankOffloadRetryDelay(
                attempts: ticket.attempts
            )
            guard now.timeIntervalSince(lastAttemptAt) >= delay else {
                return false
            }
        }
        // The connected-share exception is minted here and nowhere in the
        // general history API. A reason string, force bit, persisted pending
        // request, or a same-UUID twin cannot recreate this exact callback
        // source. The retainer will still require the object to be the sole
        // connected canonical peripheral when the generation is published.
        guard let connectedPeripheral,
              let connectedRequestAuthority =
                makeConnectedMotionBankHistoryRequestAuthority(
                    ticket: ticket,
                    peripheral: connectedPeripheral,
                    now: now
                ) else {
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=exact_live_authority_deferred ticket=%@ reason=%@ action=retain_ticket_no_history_command_no_cancel",
                ticket.id,
                reason
            )
            return false
        }
        // Bind the exact durable ticket before entering synchronous admission.
        // The binding is revalidated both at the universal continuity gate and
        // under the retainer's canonical-object lock.
        defaults.set(
            ticket.id,
            forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
        )
        // Publish the exact present-capture reservation before synchronous
        // admission. A successfully installed generation clears it while
        // spending the ticket attempt; any pre-start rejection leaves it as the
        // durable authority to reopen 0x69 without forging history ownership.
        defaults.set(
            ticket.id,
            forKey:
                Self.workoutHistoricalMotionBankTransportDeferredTicketIDKey
        )
        if processInterruptedRetry {
            processInterruptedMotionBankReservedTicketID = ticket.id
        }
        let requestResult: (
            started: Bool,
            warmDeferredTicketID: String?,
            admissionLedgerDeferredTicketID: String?,
            localDependency:
                ConnectedMotionBankDeferredLocalDependencyObservation?
        ) = {
            let previousAuthority =
                transientConnectedMotionBankHistoryRequestAuthority
            let previousWarmDeferredTicketID =
                transientConnectedMotionBankArchiveWarmDeferredTicketID
            let previousAdmissionLedgerDeferredTicketID =
                transientConnectedMotionBankAdmissionLedgerDeferredTicketID
            let previousLocalDependency =
                transientConnectedMotionBankDeferredLocalDependency
            transientConnectedMotionBankHistoryRequestAuthority =
                connectedRequestAuthority
            transientConnectedMotionBankArchiveWarmDeferredTicketID = nil
            transientConnectedMotionBankAdmissionLedgerDeferredTicketID = nil
            transientConnectedMotionBankDeferredLocalDependency = nil
            defer {
                transientConnectedMotionBankHistoryRequestAuthority =
                    previousAuthority
                transientConnectedMotionBankArchiveWarmDeferredTicketID =
                    previousWarmDeferredTicketID
                transientConnectedMotionBankAdmissionLedgerDeferredTicketID =
                    previousAdmissionLedgerDeferredTicketID
                transientConnectedMotionBankDeferredLocalDependency =
                    previousLocalDependency
            }
            let started = requestOfflineHistoricalSyncIfNeeded(
                reason: reason,
                force: true,
                allowConnectedAutomaticHandoff: false,
                explicitResearchRequest: false,
                explicitPostWorkoutBankRequest: true,
                preserveConnectedRealtimeOwner: true
            )
            return (
                started,
                transientConnectedMotionBankArchiveWarmDeferredTicketID,
                transientConnectedMotionBankAdmissionLedgerDeferredTicketID,
                transientConnectedMotionBankDeferredLocalDependency
            )
        }()
        let started = requestResult.started
        let updatedAttempts =
            AtriaWhoop4MotionBankCoverageLedger.pendingOffload(
                id: ticket.id,
                strapIdentifier: ticket.strapIdentifier
            )?.attempts ?? ticket.attempts
        let generationStarted =
            offlineHistoricalSyncInProgress
                && updatedAttempts > ticket.attempts
        let warmFirstRefusalHeld =
            ticket.attempts == 0
                && updatedAttempts == ticket.attempts
                && requestResult.warmDeferredTicketID == ticket.id
        let admissionLedgerFirstRefusalHeld =
            ticket.attempts == 0
                && updatedAttempts == ticket.attempts
                && requestResult.admissionLedgerDeferredTicketID == ticket.id
        let localDependencyFirstRefusal =
            requestResult.localDependency.flatMap { observation in
                ticket.attempts == 0
                    && updatedAttempts == ticket.attempts
                    && observation.ticketID == ticket.id
                    ? observation
                    : nil
            }
        if started || generationStarted {
            connectedMotionBankHistoryAdmissionRetryNotBefore = nil
            if defaults.string(
                forKey: Self
                    .workoutHistoricalMotionBankTransportDeferredTicketIDKey
            ) == ticket.id {
                defaults.removeObject(
                    forKey: Self
                        .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                )
            }
            // Persist cadence only after the atomic claim actually published a
            // generation and spent the ticket attempt. A pre-start archive or
            // thermal deferral gets a short process-local debounce instead, so
            // it can remint exact authority promptly when the blocker clears.
            defaults.set(
                now.timeIntervalSince1970,
                forKey: Self.workoutHistoricalMotionBankLastOffloadStartedAtKey
            )
        } else if warmFirstRefusalHeld {
            connectedMotionBankHistoryAdmissionRetryNotBefore = nil
            holdConnectedMotionBankForArchiveWarmFirstRefusal(
                ticketID: ticket.id,
                now: now
            )
        } else if admissionLedgerFirstRefusalHeld {
            connectedMotionBankHistoryAdmissionRetryNotBefore = nil
            holdConnectedMotionBankForAdmissionLedgerFirstRefusal(
                ticketID: ticket.id,
                now: now
            )
        } else if let localDependencyFirstRefusal {
            connectedMotionBankHistoryAdmissionRetryNotBefore = nil
            holdConnectedMotionBankForLocalDependencyFirstRefusal(
                localDependencyFirstRefusal,
                now: now
            )
        } else {
            connectedMotionBankHistoryAdmissionRetryNotBefore =
                now.addingTimeInterval(5)
            // The exact ticket remains pending at attempts == 0. Immediately
            // resume bounded present capture; the persisted reservation also
            // makes this safe after a process termination before another retry.
            armWorkoutHistoricalMotionBankIfPossible(
                reason: "transport_deferred_\(reason)"
            )
        }
        let retainedAuthorizedRequest =
            pendingOfflineHistoricalSyncRequest?
                .explicitPostWorkoutBankRequest == true
        if processInterruptedMotionBankReservedTicketID == ticket.id {
            if generationStarted || started {
                processInterruptedMotionBankReservationTask?.cancel()
                processInterruptedMotionBankReservationTask = nil
                processInterruptedMotionBankReservedTicketID = nil
            } else if retainedAuthorizedRequest {
                processInterruptedMotionBankReservationTask?.cancel()
                processInterruptedMotionBankReservationTask = Task {
                    @MainActor [weak self] in
                    try? await Task.sleep(for: .seconds(120))
                    guard let self,
                          !Task.isCancelled,
                          self
                              .processInterruptedMotionBankReservedTicketID
                                == ticket.id else { return }
                    self.processInterruptedMotionBankReservationTask = nil
                    self.processInterruptedMotionBankReservedTicketID = nil
                    guard !self.offlineHistoricalSyncInProgress,
                          !self.freshHistoryOwnerCutoverPending else {
                        return
                    }
                    self.armWorkoutHistoricalMotionBankIfPossible(
                        reason:
                            "process_interrupted_ticket_reservation_timeout"
                    )
                }
            } else {
                processInterruptedMotionBankReservationTask?.cancel()
                processInterruptedMotionBankReservationTask = nil
                processInterruptedMotionBankReservedTicketID = nil
            }
        }
        AtriaDebugLog(
            "ATRIADBG workout_motion_bank_offload status=%@ ticket=%@ start=%.3f end=%.3f attempt=%d reason=%@ action=async_exact_window_drain",
            generationStarted
                ? "started"
                : (started ? "cutover_pending" : "retained"),
            ticket.id,
            ticket.start.timeIntervalSince1970,
            ticket.end.timeIntervalSince1970,
            updatedAttempts,
            reason
        )
        let retainedRequestOwnsTransport =
            processInterruptedRetry
                && retainedAuthorizedRequest
                && !historicalConsumerMaterializationInFlight
        return started
            || generationStarted
            || warmFirstRefusalHeld
            || admissionLedgerFirstRefusalHeld
            || localDependencyFirstRefusal != nil
            || retainedRequestOwnsTransport
    }

    /// Builds one replacement ticket for devices that ran the retired
    /// transport-only verifier. The durable `r10_range_unrecovered` marker and
    /// a containing closed 0x69 interval are both required, so this cannot
    /// manufacture motion history or replay an unrelated workout.
    private func repairTransportOnlyClearedWorkoutMotionTicketIfNeeded() {
        let defaults = UserDefaults.standard
        let migrationKey =
            "atria.workoutHistoricalMotionBank.coverageV24Repair.v1"
        guard !defaults.bool(forKey: migrationKey),
              defaults.bool(forKey: WorkoutMotionDefaults.backfillPending),
              let peripheralID = peripheral?.identifier.uuidString,
              let reason = defaults.string(
                forKey: WorkoutMotionDefaults.backfillReason
              ),
              reason.hasPrefix("r10_range_unrecovered:") else { return }
        let range = reason.dropFirst("r10_range_unrecovered:".count)
            .split(separator: "-", maxSplits: 1)
        guard range.count == 2,
              let startUnix = TimeInterval(range[0]),
              let endUnix = TimeInterval(range[1]),
              endUnix > startUnix,
              let ticket = AtriaWhoop4MotionBankCoverageLedger
                .restorePendingOffloadIfCovered(
                    start: Date(timeIntervalSince1970: startUnix),
                    end: Date(timeIntervalSince1970: endUnix),
                    strapIdentifier: peripheralID
                ) else { return }
        defaults.set(true, forKey: migrationKey)
        AtriaDebugLog(
            "ATRIADBG workout_motion_bank_offload status=ticket_restored ticket=%@ reason=retired_transport_only_verifier action=retry_exact_v24_window_once",
            ticket.id
        )
    }

    /// A connected raw slice advances WHOOP's one global read cursor; it does
    /// not target the newest bank ticket. Re-evaluate every durable interval
    /// against compact v24 facts after each slice and resolve only exact >=90%
    /// windows. No ticket attempt, selector binding, cadence timestamp, or
    /// scalar HR frontier is created here.
    private func evaluatePendingGlobalFrontierMotionBankCoverage(
        reason: String
    ) {
        guard let current = peripheral else { return }
        let request = GlobalFrontierMotionBankEvaluationRequest(
            strapIdentifier: current.identifier.uuidString,
            callbackSource: bleCallbackEpochFence.captureIfAccepted(
                peripheralID: current.identifier,
                peripheralObjectID: ObjectIdentifier(current),
                peripheralConnected: current.state == .connected
            ),
            reason: reason
        )
        guard globalFrontierEvaluationCoalescer.request(
            whileEvaluationInFlight:
                workoutHistoricalMotionBankOffloadEvaluationInFlight
        ) else {
            // Keep the freshest exact object/epoch proof. Compact evaluation is
            // strap-scoped and may still resolve an older request, but only the
            // newest live source is ever considered for successor 69/01.
            pendingGlobalFrontierEvaluationRequest = request
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank_offload status=global_frontier_evaluation_coalesced strap=%@ reason=%@ action=one_fresh_trailing_pass",
                request.strapIdentifier,
                reason
            )
            return
        }
        startGlobalFrontierMotionBankEvaluation(request)
    }

    private func startGlobalFrontierMotionBankEvaluation(
        _ request: GlobalFrontierMotionBankEvaluationRequest
    ) {
        let pendingTickets =
            AtriaWhoop4MotionBankCoverageLedger.pendingOffloads(
                strapIdentifier: request.strapIdentifier
            )
        guard !pendingTickets.isEmpty else {
            armAfterGlobalFrontierEvaluationIfSafe(request: request)
            return
        }
        workoutHistoricalMotionBankOffloadEvaluationInFlight = true
        historicalArchiveQueue.async { [weak self, request] in
            let compactCoverages =
                AtriaWhoop4MotionTickCompactStore.shared.transportCoverages(
                    tickets: pendingTickets,
                    strapIdentifier: request.strapIdentifier
                )
            let resolvedTicketIDs = Set(
                compactCoverages.compactMap { id, coverage in
                    coverage.satisfiesNinetyPercentExactWindow ? id : nil
                }
            )
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.workoutHistoricalMotionBankOffloadEvaluationInFlight =
                    false
                defer {
                    self.runCoalescedGlobalFrontierEvaluationIfNeeded()
                }
                if !resolvedTicketIDs.isEmpty {
                    AtriaWhoop4MotionBankCoverageLedger.resolveOffloads(
                        ids: resolvedTicketIDs
                    )
                }
                let remaining = AtriaWhoop4MotionBankCoverageLedger
                    .pendingOffloads(
                        strapIdentifier: request.strapIdentifier
                    )
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank_offload status=global_frontier_compact_evaluated inspected=%d resolved=%d remaining=%d reason=%@ action=no_ticket_attempt_no_generic_selector",
                    pendingTickets.count,
                    resolvedTicketIDs.count,
                    remaining.count,
                    request.reason
                )
                guard remaining.isEmpty else { return }
                self.armAfterGlobalFrontierEvaluationIfSafe(
                    request: request
                )
            }
        }
    }

    private func runCoalescedGlobalFrontierEvaluationIfNeeded() {
        guard !workoutHistoricalMotionBankOffloadEvaluationInFlight,
              globalFrontierEvaluationCoalescer.consumeTrailingRequest(),
              let request = pendingGlobalFrontierEvaluationRequest else {
            return
        }
        pendingGlobalFrontierEvaluationRequest = nil
        startGlobalFrontierMotionBankEvaluation(request)
    }

    private func armAfterGlobalFrontierEvaluationIfSafe(
        request: GlobalFrontierMotionBankEvaluationRequest
    ) {
        guard let source = request.callbackSource,
              let current = peripheral,
              current.identifier.uuidString == request.strapIdentifier,
              source.peripheralID == current.identifier,
              source.peripheralObjectID == ObjectIdentifier(current),
              bleCallbackEpochFence.accepts(
                  source: source,
                  peripheralConnected: current.state == .connected
              ),
              !offlineHistoricalSyncInProgress,
              !connectedRawHistoryCatchUpContinuationPending,
              postHistoryLiveRestorationGeneration == nil,
              let connectedAt,
              lastAcceptedHRAt.map({ $0 >= connectedAt }) == true else {
            return
        }
        armWorkoutHistoricalMotionBankIfPossible(
            reason:
                "global_frontier_tickets_resolved_\(request.reason)"
        )
    }

    private func evaluatePendingWorkoutHistoricalMotionBankOffload(
        reason: String,
        allowRetry: Bool
    ) {
        let applicationIsActive =
            UIApplication.shared.applicationState == .active
        guard !workoutHistoricalMotionBankOffloadEvaluationInFlight,
              let peripheralID = peripheral?.identifier.uuidString,
              let ticket = {
                  let defaults = UserDefaults.standard
                  if let boundID = defaults.string(
                      forKey:
                          Self.workoutHistoricalMotionBankActiveTicketIDKey
                  ),
                     let bound = AtriaWhoop4MotionBankCoverageLedger
                        .pendingOffload(
                            id: boundID,
                            strapIdentifier: peripheralID
                        ),
                     bound.effectiveRecoveryMode == .directOffload {
                      return bound
                  }
                  return AtriaWhoop4MotionBankCoverageLedger
                      .nextPendingOffload(strapIdentifier: peripheralID)
              }() else {
            return
        }
        workoutHistoricalMotionBankOffloadEvaluationInFlight = true
        historicalArchiveQueue.async { [weak self] in
            let pendingTickets =
                AtriaWhoop4MotionBankCoverageLedger.pendingOffloads(
                    strapIdentifier: ticket.strapIdentifier
                )
            let compactCoverages =
                AtriaWhoop4MotionTickCompactStore.shared.transportCoverages(
                    tickets: pendingTickets,
                    strapIdentifier: ticket.strapIdentifier
                )
            let compactCoverage = compactCoverages[ticket.id]
                ?? AtriaWhoop4MotionTickCompactStore.shared.transportCoverage(
                    start: ticket.start,
                    end: ticket.end,
                    strapIdentifier: ticket.strapIdentifier
                )
            let compactResolvedTicketIDs = Set(
                compactCoverages.compactMap { id, candidate in
                    candidate.satisfiesNinetyPercentExactWindow ? id : nil
                }
            )
            let usedCompact =
                compactCoverage.satisfiesNinetyPercentExactWindow
            // The compact shard is synchronized at the same durable archive
            // boundary as every newly accepted v24 row. Reopening the lifetime
            // JSONL here read hundreds of megabytes after a reconnect, raised
            // thermal state to serious, and still could not cover a cursor
            // interval the strap had not served. Automatic ticket evaluation
            // is therefore compact-only in foreground and background. Legacy
            // canonical migration remains an explicit bounded maintenance
            // operation; it may not run from live-HR or reconnect callbacks.
            let coverage = compactCoverage
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.workoutHistoricalMotionBankOffloadEvaluationInFlight =
                    false
                defer {
                    self.runCoalescedGlobalFrontierEvaluationIfNeeded()
                }
                var resolvedTicketIDs = compactResolvedTicketIDs
                if coverage.satisfiesNinetyPercentExactWindow {
                    resolvedTicketIDs.insert(ticket.id)
                }
                if !resolvedTicketIDs.isEmpty {
                    AtriaWhoop4MotionBankCoverageLedger.resolveOffloads(
                        ids: resolvedTicketIDs
                    )
                    AtriaDebugLog(
                        "ATRIADBG workout_motion_bank_offload status=batch_verified count=%d pending_inspected=%d bound_ticket=%@ bound_verified=%d reason=%@ action=single_daily_receipt_refresh",
                        resolvedTicketIDs.count,
                        pendingTickets.count,
                        ticket.id,
                        resolvedTicketIDs.contains(ticket.id) ? 1 : 0,
                        reason
                    )
                }
                if coverage.satisfiesNinetyPercentExactWindow {
                    let defaults = UserDefaults.standard
                    let matchingConnectedGeneration = self
                        .activeConnectedMotionBankHistoryGenerationAuthority
                        .flatMap { authority in
                            authority.request.ticketID == ticket.id
                                ? authority.generation
                                : nil
                        }
                    if defaults.string(
                        forKey: Self
                            .workoutHistoricalMotionBankActiveTicketIDKey
                    ) == ticket.id {
                        defaults.removeObject(
                            forKey: Self
                                .workoutHistoricalMotionBankActiveTicketIDKey
                        )
                    }
                    if defaults.string(
                        forKey: Self
                            .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                    ) == ticket.id {
                        defaults.removeObject(
                            forKey: Self
                                .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                        )
                    }
                    self
                        .workoutHistoricalMotionBankOffloadEvaluationDeferredUntilForeground =
                        false
                    AtriaDebugLog(
                        "ATRIADBG workout_motion_bank_offload status=verified ticket=%@ observed=%d expected=%d density=%d max_missing=%d compact=%d reason=%@ action=clear_durable_ticket",
                        ticket.id,
                        coverage.observedSeconds,
                        coverage.expectedSeconds,
                        coverage.densityPercent,
                        coverage.maximumMissingRunSeconds,
                        usedCompact ? 1 : 0,
                        reason
                    )
                    if let matchingConnectedGeneration {
                        // The exact compact shard has already crossed its
                        // durable coverage threshold. Relinquish proprietary
                        // history locally now instead of consuming the rest of
                        // the 90-second budget; standard 2A37 remains untouched.
                        _ = self
                            .finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                                generation: matchingConnectedGeneration,
                                reason:
                                    "connected_motion_bank_compact_ticket_verified"
                            )
                    }
                    return
                }
                let historyOwnerActive =
                    self.offlineHistoricalSyncInProgress
                        || self.historyOnlyProbeMode
                if Self
                    .shouldGracefullyExhaustHistoricalMotionBankOffload(
                        attempts: ticket.attempts,
                        historyOwnerActive: historyOwnerActive
                    ),
                   AtriaWhoop4MotionBankCoverageLedger.exhaustOffload(
                       id: ticket.id
                   ) {
                    let defaults = UserDefaults.standard
                    if defaults.string(
                        forKey: Self
                            .workoutHistoricalMotionBankActiveTicketIDKey
                    ) == ticket.id {
                        defaults.removeObject(
                            forKey: Self
                                .workoutHistoricalMotionBankActiveTicketIDKey
                        )
                    }
                    if defaults.string(
                        forKey: Self
                            .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                    ) == ticket.id {
                        defaults.removeObject(
                            forKey: Self
                                .workoutHistoricalMotionBankTransportDeferredTicketIDKey
                        )
                    }
                    self
                        .workoutHistoricalMotionBankOffloadEvaluationDeferredUntilForeground =
                        false
                    AtriaDebugLog(
                        "ATRIADBG workout_motion_bank_offload status=exhausted ticket=%@ observed=%d expected=%d density=%d max_missing=%d attempts=%d reason=%@ action=preserve_missing_coverage_and_rearm_successor",
                        ticket.id,
                        coverage.observedSeconds,
                        coverage.expectedSeconds,
                        coverage.densityPercent,
                        coverage.maximumMissingRunSeconds,
                        ticket.attempts,
                        reason
                    )
                    self.armWorkoutHistoricalMotionBankIfPossible(
                        reason: "ticket_exhausted_\(reason)"
                    )
                    return
                }
                if !applicationIsActive {
                    self
                        .workoutHistoricalMotionBankOffloadEvaluationDeferredUntilForeground =
                        true
                    AtriaDebugLog(
                        "ATRIADBG workout_motion_bank_offload status=compact_pending ticket=%@ observed=%d expected=%d density=%d max_missing=%d reason=%@ action=retain_exact_ticket_no_background_archive_scan",
                        ticket.id,
                        coverage.observedSeconds,
                        coverage.expectedSeconds,
                        coverage.densityPercent,
                        coverage.maximumMissingRunSeconds,
                        reason
                    )
                } else {
                    self
                        .workoutHistoricalMotionBankOffloadEvaluationDeferredUntilForeground =
                        false
                }
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank_offload status=pending ticket=%@ observed=%d expected=%d density=%d max_missing=%d attempts=%d compact=%d reason=%@ action=%@",
                    ticket.id,
                    coverage.observedSeconds,
                    coverage.expectedSeconds,
                    coverage.densityPercent,
                    coverage.maximumMissingRunSeconds,
                    ticket.attempts,
                    usedCompact ? 1 : 0,
                    reason,
                    allowRetry
                        ? "retry_after_verified_live_restore"
                        : "retain_until_next_fresh_hr"
                )
                guard allowRetry else { return }
                self.workoutHistoricalMotionBankOffloadRetryTask?.cancel()
                let delay = Self.workoutHistoricalMotionBankOffloadRetryDelay(
                    attempts: ticket.attempts
                )
                self.workoutHistoricalMotionBankOffloadRetryTask = Task {
                    @MainActor [weak self] in
                    try? await Task.sleep(for: .seconds(delay))
                    guard let self, !Task.isCancelled else { return }
                    self.workoutHistoricalMotionBankOffloadRetryTask = nil
                    _ = self
                        .resumePendingWorkoutHistoricalMotionBankOffloadIfNeeded(
                            reason: "ticket_retry_\(reason)"
                        )
                }
            }
        }
    }

    /// A healthy present bank or a just-finished background page must not turn
    /// every accepted HR into durable ticket maintenance. The exact bound-ticket
    /// lookup uses the ledger's process cache, while an attempts=4 ticket still
    /// reaches its one terminal compact-store evaluation before the hot return.
    private func evaluateExhaustedMotionBankBeforeHotPathReturnIfNeeded(
        reason: String,
        bankArmed: Bool,
        retryCooldownActive: Bool
    ) {
        guard !workoutHistoricalMotionBankOffloadEvaluationInFlight,
              let strapIdentifier = peripheral?.identifier.uuidString else {
            return
        }
        let defaults = UserDefaults.standard
        let boundAttempts = defaults.string(
            forKey: Self.workoutHistoricalMotionBankActiveTicketIDKey
        ).flatMap { boundID in
            AtriaWhoop4MotionBankCoverageLedger.pendingOffload(
                id: boundID,
                strapIdentifier: strapIdentifier
            )
        }.flatMap { ticket in
            ticket.effectiveRecoveryMode == .directOffload
                ? ticket.attempts
                : nil
        }
        guard Self.shouldEvaluateExhaustedMotionBankBeforeHotPathReturn(
            bankArmed: bankArmed,
            retryCooldownActive: retryCooldownActive,
            boundTicketAttempts: boundAttempts,
            historyOwnerActive:
                offlineHistoricalSyncInProgress || historyOnlyProbeMode
        ) else { return }
        evaluatePendingWorkoutHistoricalMotionBankOffload(
            reason: "bounded_exhaustion_hot_gate_\(reason)",
            allowRetry: false
        )
    }

    nonisolated static func shouldRunWorkoutMotionBankCoverageEvaluation(
        applicationIsActive: Bool
    ) -> Bool {
        applicationIsActive
    }

    nonisolated static func shouldRetryUnresolvedRangeLossAfterTerminal(
        rangeLossResolved: Bool,
        forwardCursorCaughtUp: Bool,
        noRowsForDurableGap: Bool
    ) -> Bool {
        !rangeLossResolved
            && !forwardCursorCaughtUp
            && !noRowsForDurableGap
    }

    func resumeDeferredWorkoutMotionBankCoverageEvaluationIfNeeded(
        reason: String
    ) {
        guard workoutHistoricalMotionBankOffloadEvaluationDeferredUntilForeground,
              Self.shouldRunWorkoutMotionBankCoverageEvaluation(
                applicationIsActive:
                    UIApplication.shared.applicationState == .active
              ) else { return }
        evaluatePendingWorkoutHistoricalMotionBankOffload(
            reason: "foreground_\(reason)",
            allowRetry: true
        )
    }

    /// Debug-only transport probe: close IMU mode before the physically
    /// observed ~10-second controller timeout. This never runs in production;
    /// it exists to establish whether a safe duty-cycled strap-only stream is
    /// possible before implementing such a governor.
    private func scheduleGate4IMUOnlyProbeStop(
        peripheral: CBPeripheral,
        txCharacteristic: CBCharacteristic,
        reason: String
    ) {
        #if DEBUG
        guard ProcessInfo.processInfo.arguments.contains("--atria-gate4-imu-only") else {
            return
        }
        Task { @MainActor [weak self, weak peripheral] in
            try? await Task.sleep(for: .seconds(3))
            guard let self, let peripheral,
                  peripheral.state == .connected else { return }
            let sequence = self.cmdSeq
            self.cmdSeq &+= 1
            peripheral.writeValue(
                encodeFrame([Packet.command, sequence, Cmd.toggleIMUMode, 0x00]),
                for: txCharacteristic,
                type: .withoutResponse
            )
            let imuOffAt = Date()
            UserDefaults.standard.set(imuOffAt.timeIntervalSince1970,
                                      forKey: "atria.gate4.imuPulse.imuOffSentAt")
            try? await Task.sleep(for: .milliseconds(120))
            guard peripheral.state == .connected else { return }
            let floodStopSequence = self.cmdSeq
            self.cmdSeq &+= 1
            peripheral.writeValue(
                encodeFrame([
                    Packet.command,
                    floodStopSequence,
                    Cmd.sendR10R11Realtime,
                    0x00,
                ]),
                for: txCharacteristic,
                type: .withoutResponse
            )
            UserDefaults.standard.set(Date().timeIntervalSince1970,
                                      forKey: "atria.gate4.imuPulse.floodStopSentAt")
            AtriaDebugLog("ATRIADBG workout_motion status=imu_probe_pulse_stopped cmds=6a00,3f00 seqs=%d,%d reason=%@",
                          Int(sequence),
                          Int(floodStopSequence),
                          reason)
        }
        #endif
    }

    private var gate4OfficialGen4CompactMotionProbeRequested: Bool {
        #if DEBUG
        ProcessInfo.processInfo.arguments.contains(
            "--atria-gate4-official-gen4-compact-motion"
        )
        #else
        false
        #endif
    }

    private var gate4RealtimeKeepaliveProbeRequested: Bool {
        #if DEBUG
        ProcessInfo.processInfo.arguments.contains(
            "--atria-gate4-realtime-keepalive"
        )
        #else
        false
        #endif
    }

    private var gate4PassiveReconnectProbeRequested: Bool {
        #if DEBUG
        ProcessInfo.processInfo.arguments.contains(
            "--atria-gate4-passive-reconnect"
        )
        #else
        false
        #endif
    }

    nonisolated private var gate4HistoricalIMUWindowProbeRequested: Bool {
        #if DEBUG
        ProcessInfo.processInfo.arguments.contains(
            "--atria-gate4-historical-imu-window"
        ) || ProcessInfo.processInfo.arguments.contains(
            "--atria-gate4-historical-imu-prearmed-window"
        )
        #else
        false
        #endif
