    nonisolated private var gate4HistoricalIMUWindowDuration: TimeInterval {
        #if DEBUG
        ProcessInfo.processInfo.arguments.contains(
            "--atria-gate4-historical-imu-prearmed-window"
        ) ? 5 * 60 : 90
        #else
        90
        #endif
    }

    /// Diagnostic-only test of the firmware's banked-motion path. It never
    /// opens type-43 realtime raw data. The 90-second window is explicitly
    /// closed with 69/00 before the already-proven history owner is requested.
    private func startGate4HistoricalIMUWindowIfRequested(
        peripheral: CBPeripheral,
        txCharacteristic: CBCharacteristic
    ) -> Bool {
        guard gate4HistoricalIMUWindowProbeRequested,
              !gate4HistoricalIMUWindowIssued,
              peripheral.state == .connected,
              txCharacteristic.properties.contains(.writeWithoutResponse) else {
            return false
        }
        gate4HistoricalIMUWindowIssued = true
        let defaults = UserDefaults.standard
        let sequence = cmdSeq
        cmdSeq &+= 1
        peripheral.writeValue(
            encodeFrame([
                Packet.command,
                sequence,
                Cmd.toggleIMUModeHistorical,
                0x01,
            ]),
            for: txCharacteristic,
            type: .withoutResponse
        )
        let startedAt = Date()
        defaults.set(startedAt.timeIntervalSince1970,
                     forKey: "atria.gate4.historicalIMU.startedAt")
        defaults.set(Int(sequence),
                     forKey: "atria.gate4.historicalIMU.onSequence")
        let duration = gate4HistoricalIMUWindowDuration
        AtriaDebugLog(
            "ATRIADBG gate4_historical_imu status=started cmd=6901 seq=%d duration_s=%.0f action=bank_only_no_realtime_raw",
            Int(sequence),
            duration
        )
        gate4HistoricalIMUWindowTask?.cancel()
        gate4HistoricalIMUWindowTask = Task {
            @MainActor [weak self, weak peripheral] in
            guard let self else { return }
            defer { self.gate4HistoricalIMUWindowTask = nil }
            try? await Task.sleep(for: .seconds(duration))
            guard !Task.isCancelled,
                  let peripheral,
                  peripheral.state == .connected,
                  let tx = self.txCharacteristic,
                  tx.uuid == txCharacteristic.uuid else {
                defaults.set("window_interrupted",
                             forKey: "atria.gate4.historicalIMU.status")
                return
            }
            let offSequence = self.cmdSeq
            self.cmdSeq &+= 1
            peripheral.writeValue(
                encodeFrame([
                    Packet.command,
                    offSequence,
                    Cmd.toggleIMUModeHistorical,
                    0x00,
                ]),
                for: tx,
                type: .withoutResponse
            )
            let stoppedAt = Date()
            defaults.set(stoppedAt.timeIntervalSince1970,
                         forKey: "atria.gate4.historicalIMU.stoppedAt")
            defaults.set(Int(offSequence),
                         forKey: "atria.gate4.historicalIMU.offSequence")
            defaults.set("window_complete_requesting_offload",
                         forKey: "atria.gate4.historicalIMU.status")
            try? await Task.sleep(for: .seconds(1))
            let requested = self.requestOfflineHistoricalSyncIfNeeded(
                reason: "gate4_historical_imu_window",
                force: true,
                allowConnectedAutomaticHandoff: true,
                explicitResearchRequest: true
            )
            defaults.set(requested,
                         forKey: "atria.gate4.historicalIMU.offloadRequested")
        }
        return true
    }
    /// Diagnostic-only reproduction of the normal GEN4 sequence observed in
    /// the official client reversal. It deliberately excludes both raw-lab
    /// capture (`51`) and the separate R10 flood switch (`3F`).
    @discardableResult
    private func sendGate4OfficialGen4CompactMotionSequenceIfRequested(
        peripheral: CBPeripheral,
        txCharacteristic: CBCharacteristic,
        reason: String
    ) async -> Bool {
        if gate4PassiveReconnectProbeRequested,
           gate4PassiveReconnectArmed {
            UserDefaults.standard.set(
                UserDefaults.standard.integer(
                    forKey: "atria.gate4.passiveReconnect.epochs"
                ) + 1,
                forKey: "atria.gate4.passiveReconnect.epochs"
            )
            UserDefaults.standard.set(
                Date().timeIntervalSince1970,
                forKey: "atria.gate4.passiveReconnect.subscribedAt"
            )
            AtriaDebugLog(
                "ATRIADBG workout_motion status=gate4_passive_reconnect action=subscribe_only_no_command_replay reason=%@",
                reason
            )
            return true
        }
        if gate4RealtimeKeepaliveProbeRequested {
            let defaults = UserDefaults.standard
            gate4PassiveReconnectArmed =
                gate4PassiveReconnectProbeRequested
            gate4RealtimeKeepaliveTask?.cancel()
            gate4RealtimeKeepaliveTask = Task {
                @MainActor [weak self, weak peripheral] in
                guard let self else { return }
                defer { self.gate4RealtimeKeepaliveTask = nil }
                for cycle in 1...50 {
                    guard !Task.isCancelled,
                          let peripheral,
                          peripheral.state == .connected else {
                        return
                    }
                    let rawSequence = self.cmdSeq
                    self.cmdSeq &+= 1
                    peripheral.writeValue(
                        encodeFrame([
                            Packet.command,
                            rawSequence,
                            Cmd.sendR10R11Realtime,
                            0x01,
                        ]),
                        for: txCharacteristic,
                        type: .withoutResponse
                    )
                    let hrSequence = self.cmdSeq
                    self.cmdSeq &+= 1
                    peripheral.writeValue(
                        encodeFrame([
                            Packet.command,
                            hrSequence,
                            Cmd.toggleRealtimeHR,
                            0x01,
                        ]),
                        for: txCharacteristic,
                        type: .withoutResponse
                    )
                    let sentAt = Date()
                    defaults.set(cycle,
                                 forKey: "atria.gate4.realtimeKeepalive.cycles")
                    defaults.set(sentAt.timeIntervalSince1970,
                                 forKey: "atria.gate4.realtimeKeepalive.lastSentAt")
                    if cycle == 1 {
                        defaults.set(sentAt.timeIntervalSince1970,
                                     forKey: "atria.gate4.realtimeKeepalive.startedAt")
                    }
                    AtriaDebugLog(
                        "ATRIADBG workout_motion status=gate4_realtime_keepalive cycle=%d cmds=3f01,0301 seqs=%d,%d reason=%@",
                        cycle,
                        Int(rawSequence),
                        Int(hrSequence),
                        reason
                    )
                    try? await Task.sleep(for: .seconds(2))
                }
                guard !Task.isCancelled,
                      let peripheral,
                      peripheral.state == .connected else {
                    return
                }
                let stopSequence = self.cmdSeq
                self.cmdSeq &+= 1
                peripheral.writeValue(
                    encodeFrame([
                        Packet.command,
                        stopSequence,
                        Cmd.sendR10R11Realtime,
                        0x00,
                    ]),
                    for: txCharacteristic,
                    type: .withoutResponse
                )
                defaults.set(Date().timeIntervalSince1970,
                             forKey: "atria.gate4.realtimeKeepalive.stoppedAt")
            }
            return true
        }
        guard gate4OfficialGen4CompactMotionProbeRequested,
              peripheral.state == .connected else { return false }
        let defaults = UserDefaults.standard
        let sentAtKeys = [
            "atria.gate4.officialCompact.hrOnSentAt",
            "atria.gate4.officialCompact.imuOnSentAt",
            "atria.gate4.officialCompact.abortSentAt",
        ]
        var sequences: [UInt8] = []
        for (index, body) in Cmd.officialGen4CompactMotionBodies.enumerated() {
            guard !Task.isCancelled, peripheral.state == .connected else {
                return true
            }
            let sequence = cmdSeq
            cmdSeq &+= 1
            sequences.append(sequence)
            peripheral.writeValue(
                encodeFrame([Packet.command, sequence] + body),
                for: txCharacteristic,
                type: .withoutResponse
            )
            defaults.set(Date().timeIntervalSince1970,
                         forKey: sentAtKeys[index])
            if index < Cmd.officialGen4CompactMotionBodies.count - 1 {
                try? await Task.sleep(for: .milliseconds(120))
            }
        }
        defaults.set(reason,
                     forKey: "atria.gate4.officialCompact.reason")
        AtriaDebugLog("ATRIADBG workout_motion status=official_gen4_compact_motion_sent cmds=0301,6a01,1400 seqs=%d,%d,%d reason=%@ action=diagnostic_no_3f_no_51",
                      Int(sequences[0]),
                      Int(sequences[1]),
                      Int(sequences[2]),
                      reason)
        return true
    }

    /// Re-adopts a persisted lease after background/foreground transitions,
    /// CoreBluetooth state restoration, or process relaunch. A lease whose
    /// pending workout intent no longer exists is stale and is released.
    /// A missing/inactive continuity answer is NOT proof the workout ended:
    /// after a background relaunch the intent store may not be hydrated yet
    /// (2026-07-16 01:12 IST — an install relaunch released the lease and left
    /// a 43-minute workout without motion ownership). Only a definitively
    /// terminal or absent persisted intent may release the lease here; an
    /// indeterminate answer just skips this tick and retries on the next one.
    private func workoutMotionLeaseIntentIsDefinitivelyOver() -> Bool {
        // An armed guided-calibration session owns the lease exactly like a
        // workout intent; never release underneath it while its hold is live.
        if let hold = workoutMotionCalibrationHoldUntil, Date() < hold {
            return false
        }
        guard let intent = AtriaPendingWorkoutIntent.load() else { return true }
        return intent.endedAt != nil
    }

    func restoreWorkoutMotionLeaseIfNeeded(reason: String) {
        let calibrationHoldActive = workoutMotionCalibrationHoldUntil.map { Date() < $0 } == true
        if workoutMotionOwnerStartedAt == nil {
            guard let stamp = UserDefaults.standard.object(
                forKey: WorkoutMotionDefaults.ownerStartedAt
            ) as? Double else { return }
            if !AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
               !calibrationHoldActive {
                if workoutMotionLeaseIntentIsDefinitivelyOver() {
                    endWorkoutMotionLease(reason: "\(reason)_stale_intent")
                }
                return
            }
            workoutMotionOwnerStartedAt = Date(timeIntervalSince1970: stamp)
            AtriaDebugLog("ATRIADBG workout_motion status=lease_restored reason=%@ started_unix=%d",
                          reason,
                          Int(stamp.rounded()))
        } else if !AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
                  !calibrationHoldActive {
            if workoutMotionLeaseIntentIsDefinitivelyOver() {
                endWorkoutMotionLease(reason: "\(reason)_stale_intent")
            }
            return
        }
        scheduleWorkoutMotionLeaseEvaluation(reason: reason)
    }

    private func scheduleWorkoutMotionLeaseEvaluation(
        reason: String,
        delay: TimeInterval = protectedR10PassiveGraceDuration
    ) {
        guard workoutMotionOwnerStartedAt != nil else { return }
        guard !historyOnlyProbeMode, !offlineHistoricalSyncInProgress else { return }
        guard workoutMotionActivationTask == nil else { return }
        workoutMotionActivationTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(delay))
            guard let self, !Task.isCancelled else { return }
            self.workoutMotionActivationTask = nil
            self.evaluateWorkoutMotionLease(now: Date(), reason: reason)
        }
    }

    private func evaluateWorkoutMotionLease(now: Date, reason: String) {
        guard !historyOnlyProbeMode, !offlineHistoricalSyncInProgress else { return }
        guard let leaseStartedAt = workoutMotionOwnerStartedAt else { return }
        let manualWorkoutActive =
            AtriaPendingWorkoutIntent.isActiveForBLEContinuity(now: now)
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { now < $0 } == true
        // A legacy all-day owner timestamp must fail closed before any R10
        // state evaluation. All-day v24 banking has its own governor and is
        // never authority to discover, subscribe, or command realtime motion.
        guard Self.workoutMotionDenseBringUpIsAuthorized(
            manualWorkoutActive: manualWorkoutActive,
            calibrationHoldActive: calibrationHoldActive,
            leaseHeld: true
        ) else {
            if workoutMotionLeaseIntentIsDefinitivelyOver() {
                endWorkoutMotionLease(reason: "\(reason)_stale_non_workout_owner")
            }
            return
        }
        if manualWorkoutActive {
            let stepLeaseDecision = AtriaR10StepLeasePolicy.decision(
                manualWorkoutActive: true,
                historyOwnsTransport: offlineHistoricalSyncInProgress || historyOnlyProbeMode,
                connected: peripheral?.state == .connected,
                connectionStartedAt: connectedAt,
                leaseConnectionStartedAt: r10StepLeaseConnectionStartedAt,
                leaseStartedAt: leaseStartedAt,
                lastAcceptedHeartRateAt: lastAcceptedHRAt,
                now: now
            )
            switch stepLeaseDecision {
            case .grant:
                r10StepLeaseConnectionStartedAt = connectedAt
                // This is authority to *try* the bounded motion bring-up, not
                // proof that the strap has accepted it. In protected pure-HR
                // mode the saved workout can be eligible while the current
                // owner deliberately refuses R10 activation (for example a
                // prior safety fallback). Calling that state "granted" made
                // the product claim step capture although no stream-5 frame
                // could possibly arrive. Only recordWorkoutMotionFrameIfNeeded
                // promotes the status to `live`, after observed dense frames.
                setWorkoutMotionStatus("r10_step_lease_eligible_waiting_for_motion", at: now)
                AtriaDebugLog("ATRIADBG r10_step_lease status=eligible_waiting_for_motion reason=%@", reason)
            case .keep:
                break
            case .revoke(let revocation):
                // This revokes only pending R10 work. HR and the durable
                // workout intent continue; fresh HR on a later epoch may
                // grant anew.
                workoutMotionActivationTask?.cancel()
                workoutMotionActivationTask = nil
                workoutMotionCommandTask?.cancel()
                workoutMotionCommandTask = nil
                r10StepLeaseConnectionStartedAt = nil
                setWorkoutMotionStatus("r10_step_lease_revoked_\(revocation)", at: now)
                AtriaDebugLog("ATRIADBG r10_step_lease status=revoked cause=%@ reason=%@", String(describing: revocation), reason)
                return
            }
        }
        let defaults = UserDefaults.standard
        let lastActivationConnectionAt = (defaults.object(
            forKey: WorkoutMotionDefaults.activationConnectionAt
        ) as? Double).map(Date.init(timeIntervalSince1970:))
        let action = Self.workoutMotionLeaseAction(
            leaseStartedAt: leaseStartedAt,
            connected: peripheral?.state == .connected,
            connectedAt: connectedAt,
            stream5Confirmed: Self.workoutMotionStream5IsProven(
                notifyConfirmed: strapStream5NotifyConfirmed,
                lastFrameAt: lastR10MotionFrameAt,
                connectedAt: connectedAt
            ),
            hrNotifying: heartRateCharacteristic?.isNotifying == true,
            lastFrameAt: lastR10MotionFrameAt,
            denseFrameCount: workoutMotionDenseFrameCount(now: now),
            lastActivationConnectionAt: lastActivationConnectionAt,
            protectedPureHRFallback: protectedR10StreamSuppressed
                && (protectedR10CleanOwner == .pureHRV8
                    || protectedR10CleanOwner == .pureHRV10)
                && (protectedR10CleanOwnerState == .fallbackActive
                    || protectedR10CleanOwnerState == .fallbackPending),
            now: now
        )
        // A pure-HR fallback is an intentional, stable terminal state for
        // this lease evaluation—not an invitation to keep appending trace
        // lines or to schedule more work.  The durable workout and any open
        // R10 interval stay intact; no BLE operation occurs here.
        if action == .unavailablePureHRFallback {
            markWorkoutMotionGapIfNeeded(now: now,
                                         reason: "protected_pure_hr_fallback")
            if workoutMotionStatus != "unavailable_pure_hr_fallback" {
                setWorkoutMotionStatus("unavailable_pure_hr_fallback", at: now)
                AtriaDebugLog("ATRIADBG r10_step_lease status=unavailable_pure_hr_fallback action=retain_lease_and_gap_no_transport_retry")
            }
            return
        }
        // Honest on-device decision trail: Release builds strip debug logging,
        // so every evaluation persists its exact inputs and outcome where the
        // copy-only pull can read them (bounded: one rolling string).
        let trace = String(
            format: "t=%d action=%@ conn=%d connAt=%d s5flag=%d s5proven=%d hr=%d lastFrame=%d dense=%d attemptConn=%d reason=%@",
            Int(now.timeIntervalSince1970),
            String(describing: action),
            peripheral?.state == .connected ? 1 : 0,
            Int(connectedAt?.timeIntervalSince1970 ?? 0),
            strapStream5NotifyConfirmed ? 1 : 0,
            Self.workoutMotionStream5IsProven(notifyConfirmed: strapStream5NotifyConfirmed,
                                              lastFrameAt: lastR10MotionFrameAt,
                                              connectedAt: connectedAt) ? 1 : 0,
            heartRateCharacteristic?.isNotifying == true ? 1 : 0,
            Int(lastR10MotionFrameAt?.timeIntervalSince1970 ?? 0),
            workoutMotionDenseFrameCount(now: now),
            Int(lastActivationConnectionAt?.timeIntervalSince1970 ?? 0),
            reason
        )
        let previous = defaults.string(forKey: "atria.workoutMotion.evaluationTrace") ?? ""
        let lines = (previous.split(separator: "\n").suffix(39) + [Substring(trace)])
        defaults.set(lines.joined(separator: "\n"),
                     forKey: "atria.workoutMotion.evaluationTrace")
        switch action {
        case .none:
            markWorkoutMotionGapIfNeeded(now: now, reason: "\(reason)_transport_unavailable")
        case .unavailablePureHRFallback:
            // Handled before trace persistence so a stable fallback cannot
            // create a per-second preferences write loop.
            return
        case .missingConnectionEpoch:
            defaults.set("missing_connected_at", forKey: "atria.workoutMotion.invariantFailure")
            defaults.set(now.timeIntervalSince1970,
                         forKey: "atria.workoutMotion.invariantFailureAt")
            if let peripheral, peripheral.state == .connected {
                beginConnectionEpoch(peripheral: peripheral,
                                     reason: "lease_invariant_repair",
                                     now: now)
                beginHRFirstDenseBringUpIfNeeded(peripheral: peripheral,
                                                 reason: "lease_invariant_repair")
            }
            markWorkoutMotionGapIfNeeded(now: now, reason: "missing_connection_epoch")
        case .awaitHeartRate:
            if let peripheral, peripheral.state == .connected {
                beginHRFirstDenseBringUpIfNeeded(peripheral: peripheral,
                                                 reason: "lease_await_hr")
            }
            markWorkoutMotionGapIfNeeded(now: now, reason: "\(reason)_await_hr")
            scheduleWorkoutMotionLeaseEvaluation(reason: "hr_first_wait", delay: 3)
        case .beginBringUp:
            if let peripheral, peripheral.state == .connected {
                beginProtectedR10BringUpForCurrentEpoch(peripheral: peripheral,
                                                        reason: "lease_stream5_unconfirmed")
            }
        case .markLive:
            recordWorkoutMotionGapClosureIfNeeded(
                endedAt: lastR10MotionFrameAt ?? now,
                outcome: "dense_frames_observed"
            )
            if workoutMotionStatus != "live" {
                setWorkoutMotionStatus("live", at: now)
            }
        case .awaitGrace:
            scheduleWorkoutMotionLeaseEvaluation(reason: "\(reason)_grace")
        case .activate:
            sendWorkoutMotionActivationPair(now: now, reason: reason)
        case .alreadyAttempted:
            markWorkoutMotionGapIfNeeded(now: now, reason: "\(reason)_single_attempt_spent")
        }
    }

    /// Sends the WHOOP 4 bounded accelerometer pair (6A/01 then 51/u32-ms-LE)
    /// exactly once per peripheral connection while a workout lease is active.
    /// It never toggles a CCCD, reconnects, or starts the unstable 3F flood.
    private func sendWorkoutMotionActivationPair(now: Date, reason: String) {
        guard !readOnlyHistoryCaptureRequested else { return }
        guard !historyOnlyProbeMode, !offlineHistoricalSyncInProgress else { return }
        let calibrationHoldActive =
            workoutMotionCalibrationHoldUntil.map { now < $0 } == true
        guard motionHandshakeDiagnostic == nil,
              workoutMotionOwnerStartedAt != nil,
              Self.workoutMotionDenseBringUpIsAuthorized(
                  manualWorkoutActive:
                      AtriaPendingWorkoutIntent
                        .isActiveForBLEContinuity(now: now),
                  calibrationHoldActive: calibrationHoldActive,
                  leaseHeld: true
              ),
              // The full launch-style bring-up owns the command pair while it
              // is in flight; the lease's direct pair is only the fallback for
              // links where that profile could not arm.
              !protectedR10ResponseEventDataProofIsActive,
              protectedR10CleanOwnerState != .protectedLaunchPending,
              let peripheral,
              peripheral.state == .connected,
              let connectedAt,
              Self.workoutMotionStream5IsProven(
                notifyConfirmed: strapStream5NotifyConfirmed,
                lastFrameAt: lastR10MotionFrameAt,
                connectedAt: connectedAt
              ),
              heartRateCharacteristic?.isNotifying == true,
              let txCharacteristic,
              txCharacteristic.properties.contains(.writeWithoutResponse),
              workoutMotionCommandTask == nil else { return }
        let motionBattery = motionEligibilityBatteryLevel(now: now)
        guard Self.shouldArmHighFrequencyMotion(
            batteryLevel: motionBattery,
            isCharging: motionEligibilityIsCharging,
            calibrationActive: stepCalibrationCaptureIsActive
        ) else {
            setWorkoutMotionStatus("deferred_low_battery_preserve_hr", at: now)
            markWorkoutMotionGapIfNeeded(now: now, reason: "low_battery_preserve_hr")
            AtriaDebugLog("ATRIADBG workout_motion status=deferred reason=low_battery_preserve_hr battery=%d threshold=%d boundary=before_direct_command action=keep_hr_and_workout",
                          motionBattery,
                          Self.lowBatteryWarningThreshold)
            return
        }
        let defaults = UserDefaults.standard
        let attempts = defaults.integer(forKey: WorkoutMotionDefaults.activationAttempts) + 1
        defaults.set(now.timeIntervalSince1970,
                     forKey: WorkoutMotionDefaults.activationAttemptAt)
        defaults.set(connectedAt.timeIntervalSince1970,
                     forKey: WorkoutMotionDefaults.activationConnectionAt)
        defaults.set(attempts, forKey: WorkoutMotionDefaults.activationAttempts)
        setWorkoutMotionStatus("activation_sent", at: now)
        workoutMotionCommandTask = Task { @MainActor [weak self, weak peripheral] in
            defer { self?.workoutMotionCommandTask = nil }
            guard let self, let peripheral, !Task.isCancelled,
                  peripheral.state == .connected else { return }
            let commandStartedAt = Date()
            let calibrationStillActive =
                self.workoutMotionCalibrationHoldUntil.map {
                    commandStartedAt < $0
                } == true
            guard Self.workoutMotionDenseBringUpIsAuthorized(
                manualWorkoutActive:
                    AtriaPendingWorkoutIntent
                        .isActiveForBLEContinuity(now: commandStartedAt),
                calibrationHoldActive: calibrationStillActive,
                leaseHeld: self.workoutMotionOwnerStartedAt != nil
            ) else { return }
            let commandBattery = self.motionEligibilityBatteryLevel()
            guard Self.shouldArmHighFrequencyMotion(
                batteryLevel: commandBattery,
                isCharging: self.motionEligibilityIsCharging,
                calibrationActive: self.stepCalibrationCaptureIsActive
            ) else {
                self.setWorkoutMotionStatus("deferred_low_battery_preserve_hr",
                                            at: Date())
                self.markWorkoutMotionGapIfNeeded(now: Date(),
                                                   reason: "low_battery_preserve_hr")
                defaults.removeObject(
                    forKey: WorkoutMotionDefaults.activationConnectionAt
                )
                AtriaDebugLog("ATRIADBG workout_motion status=deferred reason=low_battery_preserve_hr battery=%d threshold=%d boundary=direct_command_write action=return_unspent_attempt_keep_hr_and_workout",
                              commandBattery,
                              Self.lowBatteryWarningThreshold)
                return
            }
            if await self.sendGate4OfficialGen4CompactMotionSequenceIfRequested(
                peripheral: peripheral,
                txCharacteristic: txCharacteristic,
                reason: "direct_workout_lease"
            ) {
                return
            }
            // Every physically-proven dense epoch followed the full per-link
            // v9 bring-up: ordered strapRX/stream4/stream5 notifications, then
            // the command pair. A bonded reconnect can restore stream-5 alone,
            // leaving the companion listeners inactive — re-enable only the
            // ones that are NOT already notifying (initial enablement on this
            // fresh link, never a toggle of an established subscription).
            let strapService = peripheral.services?.first {
                $0.uuid == Self.UUIDs.strapService
            }
            var enabledCompanions = 0
            for uuid in Self.protectedR10ResponseEventDataNotifyOrder {
                guard let characteristic = strapService?.characteristics?
                        .first(where: { $0.uuid == uuid }),
                      characteristic.properties.contains(.notify),
                      !characteristic.isNotifying else { continue }
                peripheral.setNotifyValue(true, for: characteristic)
                self.incrementRadioCounter(RadioDefaults.customNotifyEnabled,
                                           reason: "workout_lease_per_link_profile")
                enabledCompanions += 1
                AtriaDebugLog("ATRIADBG workout_motion status=per_link_notify_enabled ch=%@ action=initial_enable_fresh_link",
                              uuid.uuidString)
            }
            UserDefaults.standard.set(enabledCompanions,
                                      forKey: "atria.workoutMotion.lastPerLinkEnables")
            if enabledCompanions > 0 {
                try? await Task.sleep(for: .seconds(1))
                let writeAt = Date()
                let calibrationStillActive =
                    self.workoutMotionCalibrationHoldUntil.map {
                        writeAt < $0
                    } == true
                guard !Task.isCancelled,
                      peripheral.state == .connected,
                      Self.workoutMotionDenseBringUpIsAuthorized(
                          manualWorkoutActive:
                              AtriaPendingWorkoutIntent
                                .isActiveForBLEContinuity(now: writeAt),
                          calibrationHoldActive:
                              calibrationStillActive,
                          leaseHeld:
                              self.workoutMotionOwnerStartedAt != nil
                      ) else { return }
            }
            let imuSequence = self.cmdSeq
            self.cmdSeq &+= 1
            peripheral.writeValue(
                encodeFrame([Packet.command, imuSequence, Cmd.toggleIMUMode, 0x01]),
                for: txCharacteristic,
                type: .withoutResponse
            )
            self.scheduleGate4IMUOnlyProbeStop(
                peripheral: peripheral,
                txCharacteristic: txCharacteristic,
                reason: "direct_workout_lease"
            )
            let rawSequence = self.cmdSeq
            self.cmdSeq &+= 1
            #if DEBUG
            let gate4IMUOnlyProbe = ProcessInfo.processInfo.arguments.contains(
                "--atria-gate4-imu-only"
            )
            let sentCommands = gate4IMUOnlyProbe
                ? "6a01_only_debug_probe"
                : "6a01,51_duration_le"
            #else
            let gate4IMUOnlyProbe = false
            let sentCommands = "6a01,51_duration_le"
            #endif
            if !gate4IMUOnlyProbe {
                peripheral.writeValue(
                    encodeFrame(
                        [Packet.command, rawSequence, Cmd.startRawData]
                            + Cmd.rawCaptureDurationPayload()
                    ),
                    for: txCharacteristic,
                    type: .withoutResponse
                )
            }
            AtriaDebugLog("ATRIADBG workout_motion status=activation_sent cmds=%@ seqs=%d,%d duration_ms=%u reason=%@ attempt=%d action=bounded_raw_motion_per_connection",
                          sentCommands,
                          Int(imuSequence),
                          Int(rawSequence),
                          Cmd.workoutRawCaptureDurationMilliseconds,
                          reason,
                          attempts)
        }
        scheduleWorkoutMotionLeaseEvaluation(reason: "activation_followup")
    }

    /// History owns the proprietary service as one transaction. A pending
    /// workout lease remains durable, but its discovery/command tasks must not
    /// interleave with the history command epoch. The suspension is bound to
    /// the exact history generation that requested it: a stale G1 caller
    /// arriving after an explicit workout (G2) preempted history must not
    /// cancel the new owner's activation tasks or revoke its step lease.
    private func suspendWorkoutMotionLeaseForHistoricalSync(generation: UInt64) {
        guard generation == offlineHistoricalSyncGeneration,
              offlineHistoricalSyncInProgress else {
            AtriaDebugLog(
                "ATRIADBG workout_motion status=lease_suspend_rejected reason=stale_history_generation requested=%llu current=%llu in_progress=%d",
                generation,
                offlineHistoricalSyncGeneration,
                offlineHistoricalSyncInProgress ? 1 : 0
            )
            return
        }
        workoutMotionActivationTask?.cancel()
        workoutMotionActivationTask = nil
        workoutMotionCommandTask?.cancel()
        workoutMotionCommandTask = nil
        r10StepLeaseConnectionStartedAt = nil
        setWorkoutMotionStatus("r10_step_lease_revoked_history_owner", at: Date())
    }

    /// The common history finalizer reaches every terminal, timeout and
    /// transport-loss exit. Re-arm the persisted lease there exactly once;
    /// scheduling remains withheld when a queued history generation has
    /// already taken ownership synchronously.
    private func resumeWorkoutMotionLeaseAfterHistoricalSync(reason: String) {
        guard !historyOnlyProbeMode, !offlineHistoricalSyncInProgress else { return }
        scheduleWorkoutMotionLeaseEvaluation(reason: reason)
    }

    /// Every CRC-valid R10 frame belonging to the current connection feeds the
    /// lease's honest first/last-live-frame accounting and closes an open gap
    /// as an explicitly unrecovered range.
    private func recordWorkoutMotionFrameIfNeeded(receivedAt: Date) {
        guard workoutMotionOwnerStartedAt != nil else { return }
        guard let connectedAt, receivedAt >= connectedAt else { return }
        workoutMotionFrameTimestamps.append(receivedAt)
        if workoutMotionFrameTimestamps.count > 64 {
            workoutMotionFrameTimestamps.removeFirst(
                workoutMotionFrameTimestamps.count - 64
            )
        }
        let defaults = UserDefaults.standard
        if defaults.object(forKey: WorkoutMotionDefaults.firstLiveFrameAt) == nil {
            defaults.set(receivedAt.timeIntervalSince1970,
                         forKey: WorkoutMotionDefaults.firstLiveFrameAt)
        }
        defaults.set(receivedAt.timeIntervalSince1970,
                     forKey: WorkoutMotionDefaults.lastLiveFrameAt)
        // A lone sparse passive frame neither proves the dense epoch nor
        // closes an open gap; only restored ~1 Hz density does.
        guard workoutMotionDenseFrameCount(now: receivedAt)
                >= Self.workoutMotionDenseFrameThreshold else { return }
        recordWorkoutMotionGapClosureIfNeeded(endedAt: receivedAt, outcome: "dense_frames_resumed")
        if workoutMotionStatus != "live" {
            setWorkoutMotionStatus("live", at: receivedAt)
        }
    }

    /// Frames observed on the current connection inside the trailing density
    /// window. Dense 1 Hz motion yields ~15; sparse passive yields 1–2.
    private func workoutMotionDenseFrameCount(now: Date) -> Int {
        let cutoff = now.addingTimeInterval(-Self.workoutMotionDensityWindow)
        return workoutMotionFrameTimestamps.reduce(into: 0) { count, stamp in
            if stamp >= cutoff, stamp <= now,
               let connectedAt, stamp >= connectedAt {
                count += 1
            }
        }
    }

    private func markWorkoutMotionGapIfNeeded(now: Date, reason: String) {
        guard workoutMotionOwnerStartedAt != nil else { return }
        let defaults = UserDefaults.standard
        guard defaults.object(forKey: WorkoutMotionDefaults.gapStartedAt) == nil else { return }
        let gapStart = (defaults.object(
            forKey: WorkoutMotionDefaults.lastLiveFrameAt
        ) as? Double).map(Date.init(timeIntervalSince1970:))
            ?? workoutMotionOwnerStartedAt
            ?? now
        defaults.set(gapStart.timeIntervalSince1970,
                     forKey: WorkoutMotionDefaults.gapStartedAt)
        setWorkoutMotionStatus("gap", at: now)
        AtriaDebugLog("ATRIADBG workout_motion status=gap_open reason=%@ gap_start_unix=%d",
                      reason,
                      Int(gapStart.timeIntervalSince1970.rounded()))
    }

    /// Records a finished missing range for later review. The strap has no
    /// verified capability to replay arbitrary offline R10 or metric history,
    /// so the range is persisted as unrecovered — never as backfillable data.
    private func recordWorkoutMotionGapClosureIfNeeded(endedAt: Date, outcome: String) {
        let defaults = UserDefaults.standard
        guard let gapStamp = defaults.object(
            forKey: WorkoutMotionDefaults.gapStartedAt
        ) as? Double else { return }
        defaults.removeObject(forKey: WorkoutMotionDefaults.gapStartedAt)
        defaults.set(true, forKey: WorkoutMotionDefaults.backfillPending)
        defaults.set(
            String(format: "r10_range_unrecovered:%d-%d",
                   Int(gapStamp.rounded()),
                   Int(endedAt.timeIntervalSince1970.rounded())),
            forKey: WorkoutMotionDefaults.backfillReason
        )
        AtriaDebugLog("ATRIADBG workout_motion status=gap_closed outcome=%@ gap_start_unix=%d gap_end_unix=%d action=recorded_unrecovered_range",
                      outcome,
                      Int(gapStamp.rounded()),
                      Int(endedAt.timeIntervalSince1970.rounded()))
    }

    private func setWorkoutMotionStatus(_ status: String, at date: Date) {
        workoutMotionStatus = status
        let defaults = UserDefaults.standard
        defaults.set(status, forKey: WorkoutMotionDefaults.status)
        defaults.set(date.timeIntervalSince1970, forKey: WorkoutMotionDefaults.statusAt)
    }

    /// Observe the proprietary stream only after 61080005 notification is
    /// confirmed. Production may send the validated 3F/01 activation only
    /// after passive grace and under the persisted ten-minute lease.
    func armRealtime() {
        proprietaryNotifyFallbackTask?.cancel()
        proprietaryNotifyFallbackTask = nil
        if standardHROnlyMode, !historyOnlyProbeEnabled {
            realtimeOn = false
            incrementRadioCounter(RadioDefaults.realtimeStartSkipped, reason: "standard_hr_only")
            AtriaDebugLog("ATRIADBG realtimeConfig standard_hr_only=1 realtime_start=skipped")
            return
        }
        if historyOnlyProbeEnabled {
            armHistoryOnlyProbe()
            return
        }
        guard !realtimeArmed else { return }
        realtimeArmed = true
        realtimeOn = true
        decodedRealtimeRRValues = 0
        usedRealtimeRRValues = 0
        standardHRFrames = 0
        decodedStandardRRValues = 0
        lastStandardRRAt = nil
        lastRRBearingRealtimeFrameAt = nil
        lastRealtimeRestartAt = nil
        realtimeRetry?.cancel()
        r10ArmRetryTask?.cancel()
        // Include frames delivered by the newly connected notification stream
        // during the TX wait/settle period; subscription alone may resume R10.
        let r10EvidenceEpoch = connectedAt ?? Date()
        realtimeRetry = Task { @MainActor [self] in
            // Wait for discovery, then settle so every notification subscription
            // is live before assessing the passive R10 stream.
            for _ in 0..<25 where txCharacteristic == nil { try? await Task.sleep(for: .milliseconds(200)) }
            guard txCharacteristic != nil else { return }
            try? await Task.sleep(for: .seconds(3))
            let motionBattery = motionEligibilityBatteryLevel()
            guard Self.shouldArmHighFrequencyMotion(batteryLevel: motionBattery,
                                                    isCharging: motionEligibilityIsCharging,
                                                    calibrationActive: stepCalibrationCaptureIsActive) else {
                AtriaDebugLog("ATRIADBG r10_stream status=deferred reason=low_battery_preserve_hr battery=%d charging=0 threshold=%d action=keep_realtime_hr_only",
                              motionBattery,
                              Self.lowBatteryWarningThreshold)
                return
            }
            ensureR10LivenessWatchdog(reason: "full_protocol_arm")
            AtriaDebugLog("ATRIADBG r10_stream status=observe_subscribed_stream command=deferred_until_passive_grace source=standard_hr_stability")
            // Never rediscover or repeatedly write while HR is healthy.
            // Physical WHOOP 4 testing showed repeated intervention can
            // destabilize the link; the fallback below is one persisted,
            // ten-minute-leased 3F/01 only after passive observation fails.
            r10ArmRetryTask = Task { @MainActor [weak self] in
                guard let self else { return }
                for attempt in 1...2 {
                    try? await Task.sleep(for: .seconds(4))
                    guard !Task.isCancelled, self.realtimeArmed else { return }
                    if Self.r10FrameProvesCurrentArm(lastFrameAt: self.lastR10MotionFrameAt,
                                                     evidenceEpoch: r10EvidenceEpoch) {
                        AtriaDebugLog("ATRIADBG r10_stream status=alive retry=%d frames=%d",
                                      attempt - 1,
                                      self.r10MotionFrameCount)
                        return
                    }
                    AtriaDebugLog("ATRIADBG r10_stream status=observe attempt=%d reason=no_r10_frame",
                                  attempt)
                }
                if !Self.r10FrameProvesCurrentArm(lastFrameAt: self.lastR10MotionFrameAt,
                                                  evidenceEpoch: r10EvidenceEpoch) {
                    let recoveryAt = Date()
                    self.lastR10RecoveryRearmAt = recoveryAt
                    AtriaDebugLog("ATRIADBG r10_stream status=unavailable action=request_single_leased_activation")
                    self.requestBoundedR10ActivationForSilentStream(
                        now: recoveryAt,
                        reason: "initial_full_protocol_arm"
                    )
                    return
                }
            }
            if let probeCommand, let command = probeCommand.first {
                let data = Array(probeCommand.dropFirst())
                let delay = probeCommandDelaySeconds
                Task { @MainActor in
                    if delay > 0 {
                        try? await Task.sleep(for: .seconds(delay))
                    }
                    AtriaDebugLog("ATRIADBG probeCommand send cmd=%02x data=%@ delay_s=%.1f mode=%@",
                          command, data.map { String(format: "%02x", $0) }.joined(),
                          delay, probeCommandMode.rawValue)
                    sendCommand(command, data, mode: probeCommandMode)
                }
            }
            if !probeSweepCommands.isEmpty {
                let commands = probeSweepCommands
                let interval = probeSweepIntervalSeconds
                Task { @MainActor in
                    for (index, bytes) in commands.enumerated() {
                        try? await Task.sleep(for: .seconds(interval))
                        guard let command = bytes.first else { continue }
                        let data = Array(bytes.dropFirst())
                        AtriaDebugLog("ATRIADBG probeSweep send index=%d raw=%@ cmd=%02x data=%@ interval_s=%.1f mode=%@",
                              index, Self.hex(bytes), command, Self.hex(data),
                              interval, probeCommandMode.rawValue)
                        sendCommand(command, data, mode: probeCommandMode)
                    }
                }
            }
            for _ in 0..<realtimeStartRetries {
                try? await Task.sleep(for: .seconds(4))
                let rawHRProvesCurrentLink = lastRawHRNotificationAt.map { $0 >= r10EvidenceEpoch } ?? false
                let r10ProvesCurrentLink = Self.r10FrameProvesCurrentArm(
                    lastFrameAt: lastR10MotionFrameAt,
                    evidenceEpoch: r10EvidenceEpoch
                )
                if realtimeRRStreamIsAlive || rawHRProvesCurrentLink || r10ProvesCurrentLink {
                    AtriaDebugLog("ATRIADBG realtimeRetry status=stopped reason=transport_alive standard_hr_frames=%d realtime_frames=%d standard_rr=%d realtime_rr=%d raw_hr=%d r10=%d",
                          standardHRFrames, dbgRealtimeFrames, decodedStandardRRValues, decodedRealtimeRRValues,
                          rawHRProvesCurrentLink ? 1 : 0, r10ProvesCurrentLink ? 1 : 0)
                    break
                }
                AtriaDebugLog("ATRIADBG realtimeRetry status=send_start reason=no_rr_or_realtime_stream standard_hr_frames=%d realtime_frames=%d standard_rr=%d realtime_rr=%d",
                      standardHRFrames, dbgRealtimeFrames, decodedStandardRRValues, decodedRealtimeRRValues)
                break
            }
        }
    }

    private var realtimeRRStreamIsAlive: Bool {
        dbgRealtimeFrames > 0 || decodedStandardRRValues > 0 || decodedRealtimeRRValues > 0
    }

    private func shouldLogVerboseBLEFrame() -> Bool {
        guard verboseBLEFrameLogging else { return false }
        let limit = historyOnlyProbeMode ? 48 : 160
        if verboseBLEFrameLogCount < limit {
            verboseBLEFrameLogCount += 1
            return true
        }
        if !verboseBLEFrameLogSuppressed {
            verboseBLEFrameLogSuppressed = true
            AtriaDebugLog("ATRIADBG ble_frame_logging status=suppressed reason=log_budget_exhausted limit=%d history_probe=%d",
                  limit,
                  historyOnlyProbeMode ? 1 : 0)
        }
        return false
    }

    /// Historical fallback probe: production preserves standard 2A37 while it
    /// asks the strap for stored data. Proprietary realtime stays disarmed so
    /// historical frames cannot be confused with live proprietary RR evidence;
    /// all historical RR interpretations remain provisional.
    private func cancelHistoryOnlyProbe(reason: String) {
        let wasActive = historyOnlyProbeTask != nil || historyOnlyProbeArmed
        historyOnlyProbeTask?.cancel()
        historyOnlyProbeTask = nil
        historyOnlyProbeEpoch &+= 1
        historyOnlyProbeArmed = false
        if wasActive {
            AtriaDebugLog("ATRIADBG historyOnly status=cancelled reason=%@ epoch=%llu",
                          reason,
                          historyOnlyProbeEpoch)
        }
    }

    private func historyNotificationReadinessDecision()
        -> AtriaBLEHistoryNotificationReadinessGate<CBUUID>.Decision {
        AtriaBLEHistoryNotificationReadinessGate(
            requiredNotifications: Set(
                Self.shouldStopRealtimeBeforeHistoricalRecovery(
                    diagnosticSelectorOrRangeProbe: !historySkipDataRangeRequest
                ) ? Self.UUIDs.allNotify : requiredProductionHistoryNotifications
            )
        ).decision(
            linkConnected: peripheral?.state == .connected,
            txAvailable: txCharacteristic != nil,
            activeNotifications: activeProprietaryNotifyUUIDs
        )
    }

    private func historyNotificationReadinessDetail(
        _ decision: AtriaBLEHistoryNotificationReadinessGate<CBUUID>.Decision
    ) -> String {
        switch decision {
        case .waitingForConnectedLink:
            return "link_disconnected"
        case .waitingForTX:
            return "tx_missing"
        case .waitingForNotifications(let missing):
            return "missing_" + missing
                .map(\.uuidString)
                .sorted()
                .joined(separator: ",")
        case .ready:
            return "ready"
        }
    }

    /// Re-discovery is bounded by the owning offline-sync timeout. It repairs
    /// a failed/missing CCCD completion without ever issuing a history command
    /// against a partially subscribed proprietary transport.
    private func retryHistoryNotificationReadiness(
        generation: UInt64,
        reason: String
    ) {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else { return }
        historyOnlyProbeTask = nil
        historyOnlyProbeArmed = false
        txCharacteristic = nil
        UserDefaults.standard.set(
            "notification_readiness_\(reason)",
            forKey: OfflineSyncDefaults.handshakeStatus
        )
        UserDefaults.standard.set(
            Date().timeIntervalSince1970,
            forKey: OfflineSyncDefaults.handshakeAt
        )
        if let peripheral, peripheral.state == .connected {
            if activeConnectedRealtimePreservingHistoryAuthorityExists(
                generation: generation
            ), !activeConnectedRealtimePreservingHistoryAuthorityIsValid(
                generation: generation,
                peripheral: peripheral
            ) {
                _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                    generation: generation,
                    reason:
                        "exact_connected_history_authority_lost_before_rediscovery"
                )
                return
            }
            peripheral.discoverServices([Self.UUIDs.strapService])
        }
        Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(2))
            guard let self,
                  self.offlineHistoricalSyncInProgress,
                  self.offlineHistoricalSyncGeneration == generation,
                  !self.historyOnlyProbeArmed else { return }
            self.armHistoryOnlyProbe()
        }
    }

    private func failHistoryHandshakeWrite(
        generation: UInt64,
        command: UInt8,
        result: AwaitedHistoryWriteResult
    ) {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else { return }
        let status: String
        switch result {
        case .confirmed: return
        case .securityRequired: status = "security_required"
        case .rejected: status = "rejected"
        case .failed: status = "callback_failed"
        case .timedOut: status = "timeout_ambiguous"
        }
        let commandLabel = String(format: "%02x", command)
        UserDefaults.standard.set(
            "history_write_\(commandLabel)_\(status)",
            forKey: OfflineSyncDefaults.handshakeStatus
        )
        UserDefaults.standard.set(
            Date().timeIntervalSince1970,
            forKey: OfflineSyncDefaults.handshakeAt
        )
        AtriaDebugLog("ATRIADBG historyOnly status=waiting reason=history_write_%@ generation=%llu command=%@ action=rebuild_link_without_same_epoch_retry",
                      status,
                      generation,
                      commandLabel)
        historyOnlyProbeTask = nil
        historyOnlyProbeArmed = false
        if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
            generation: generation,
            reason: "history_write_\(commandLabel)_\(status)_preserve_realtime"
        ) {
            return
        }
        if let peripheral, peripheral.state == .connected {
            cancelPeripheralConnection(
                peripheral,
                reason: "history_write_\(commandLabel)_\(status)"
            )
        } else {
            interruptOfflineHistoricalSyncForTransportLoss(
                reason: "history_write_\(commandLabel)_\(status)"
            )
        }
    }

    private func armHistoryOnlyProbe() {
        proprietaryNotifyFallbackTask?.cancel()
        proprietaryNotifyFallbackTask = nil
        guard !historyOnlyProbeArmed else { return }
        historyOnlyProbeTask?.cancel()
        historyOnlyProbeEpoch &+= 1
        let probeEpoch = historyOnlyProbeEpoch
        historyOnlyProbeArmed = true
        realtimeOn = false
        realtimeRetry?.cancel()
        realtimeRestartTask?.cancel()
        r10ArmRetryTask?.cancel()
        stopR10LivenessWatchdog(reason: "history_only_probe")
        AtriaDebugLog("ATRIADBG historyOnly status=arming realtime_start=skipped")
        historyOnlyProbeTask = Task { @MainActor [weak self] in
            guard let self else { return }
            for _ in 0..<25 where txCharacteristic == nil {
                try? await Task.sleep(for: .milliseconds(200))
                guard !Task.isCancelled,
                      historyOnlyProbeArmed,
                      historyOnlyProbeEpoch == probeEpoch else { return }
            }
            guard !Task.isCancelled,
                  historyOnlyProbeArmed,
                  historyOnlyProbeEpoch == probeEpoch else { return }
            guard txCharacteristic != nil else {
                // Characteristic discovery order is not stable across reconnects.
                // Release this expired attempt so the TX discovery callback can
                // start a fresh probe for the same offline-sync generation.
                historyOnlyProbeTask = nil
                historyOnlyProbeArmed = false
                AtriaDebugLog("ATRIADBG historyOnly status=waiting reason=tx_missing action=rearm_on_tx_discovery epoch=%llu",
                              probeEpoch)
                return
            }
            let syncGeneration = offlineHistoricalSyncGeneration
            // TX discovery often wins the race against queued CCCD writes. A
            // fixed delay did not make that ordering safe. Production requires
            // callback-confirmed RX + physically verified history stream 5;
            // explicit diagnostic
            // probes retain their broader notification barrier.
            var lastReadinessDetail = ""
            var historyTransportReady = false
            for attempt in 0..<75 {
                guard !Task.isCancelled,
                      historyOnlyProbeArmed,
                      historyOnlyProbeEpoch == probeEpoch,
                      offlineHistoricalSyncInProgress,
                      offlineHistoricalSyncGeneration == syncGeneration else { return }
                let decision = historyNotificationReadinessDecision()
                if decision == .ready {
                    historyTransportReady = true
                    break
                }
                let detail = historyNotificationReadinessDetail(decision)
                if detail != lastReadinessDetail || attempt % 10 == 0 {
                    lastReadinessDetail = detail
                    AtriaDebugLog("ATRIADBG historyOnly status=waiting reason=notification_readiness generation=%llu detail=%@ attempt=%d action=withhold_realtime_stop",
                                  syncGeneration,
                                  detail,
                                  attempt + 1)
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard historyTransportReady else {
                let detail = historyNotificationReadinessDetail(
                    historyNotificationReadinessDecision()
                )
                AtriaDebugLog("ATRIADBG historyOnly status=waiting reason=notification_readiness_timeout generation=%llu detail=%@ action=rediscover_without_command",
                              syncGeneration,
                              detail)
                retryHistoryNotificationReadiness(
                    generation: syncGeneration,
                    reason: "timeout_\(detail)"
                )
                return
            }
            AtriaDebugLog("ATRIADBG historyOnly status=notification_readiness_confirmed generation=%llu active=%d action=begin_post_notify_settle",
                          syncGeneration,
                          activeProprietaryNotifyUUIDs.count)
            try? await Task.sleep(
                for: .seconds(
                    AtriaBLEHistoryWriteConfirmationPolicy.postNotificationSettleInterval
                )
            )
            guard !Task.isCancelled,
                  historyOnlyProbeArmed,
                  historyOnlyProbeEpoch == probeEpoch,
                  offlineHistoricalSyncInProgress,
                  offlineHistoricalSyncGeneration == syncGeneration else { return }
            let settledReadiness = historyNotificationReadinessDecision()
            guard settledReadiness == .ready else {
                let detail = historyNotificationReadinessDetail(settledReadiness)
                AtriaDebugLog("ATRIADBG historyOnly status=waiting reason=notification_readiness_lost_during_settle generation=%llu detail=%@ action=rediscover_without_command",
                              syncGeneration,
                              detail)
                retryHistoryNotificationReadiness(
                    generation: syncGeneration,
                    reason: "settle_lost_\(detail)"
                )
                return
            }
            let diagnosticStopsRealtime = Self.shouldStopRealtimeBeforeHistoricalRecovery(
                diagnosticSelectorOrRangeProbe: !historySkipDataRangeRequest
            )
            AtriaDebugLog("ATRIADBG historyOnly status=notification_settle_confirmed generation=%llu settle_s=%.1f action=%@",
                          syncGeneration,
                          AtriaBLEHistoryWriteConfirmationPolicy.postNotificationSettleInterval,
                          diagnosticStopsRealtime ? "allow_diagnostic_realtime_stop" : "keep_standard_hr_send_full_drain")
            if diagnosticStopsRealtime,
               historyRealtimeStopCompletedGeneration != syncGeneration {
                if historyRealtimeStopRequestedGeneration != syncGeneration {
                    guard sendCommand(Cmd.toggleRealtimeHR,
                                      [0x00],
                                      mode: .withResponse) else {
                        failHistoryHandshakeWrite(
                            generation: syncGeneration,
                            command: Cmd.toggleRealtimeHR,
                            result: .rejected
                        )
                        return
                    }
                    historyRealtimeStopRequestedGeneration = syncGeneration
                    UserDefaults.standard.set(
                        "realtime_stop_requested",
                        forKey: OfflineSyncDefaults.handshakeStatus
                    )
                    UserDefaults.standard.set(
                        Date().timeIntervalSince1970,
                        forKey: OfflineSyncDefaults.handshakeAt
                    )
                    AtriaDebugLog("ATRIADBG historyOnly status=realtime_stop_requested generation=%llu command=0300 action=await_write_confirmation",
                                  syncGeneration)
                }
                // `didWriteValueFor` is the only durable ordering fact exposed
                // by CoreBluetooth here. Never issue clock/history commands
                // merely because `writeValue` accepted the request.
                for _ in 0..<AtriaBLEHistoryWriteConfirmationPolicy.maximumPollAttempts
                    where historyRealtimeStopCompletedGeneration != syncGeneration {
                    try? await Task.sleep(
                        for: .seconds(AtriaBLEHistoryWriteConfirmationPolicy.pollInterval)
                    )
                    guard !Task.isCancelled,
                          historyOnlyProbeArmed,
                          historyOnlyProbeEpoch == probeEpoch else { return }
                }
                guard historyRealtimeStopCompletedGeneration == syncGeneration else {
                    historyOnlyProbeTask = nil
                    historyOnlyProbeArmed = false
                    UserDefaults.standard.set(
                        "realtime_stop_write_timeout_ambiguous",
                        forKey: OfflineSyncDefaults.handshakeStatus
                    )
                    UserDefaults.standard.set(
                        Date().timeIntervalSince1970,
                        forKey: OfflineSyncDefaults.handshakeAt
                    )
                    AtriaDebugLog("ATRIADBG historyOnly status=waiting reason=realtime_stop_write_timeout generation=%llu action=rebuild_link_without_same_epoch_retry",
                                  syncGeneration)
                    // A late didWrite callback has no payload identity. Retrying
                    // 03/00 on this connection would let that stale callback
                    // confirm the retry. Disconnect first; didDisconnect resets
                    // the ledger and preserves the durable gap for a clean epoch.
                    if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                        generation: syncGeneration,
                        reason: "history_realtime_stop_write_timeout_preserve_realtime"
                    ) {
                        return
                    }
                    if let peripheral, peripheral.state == .connected {
                        cancelPeripheralConnection(
                            peripheral,
                            reason: "history_realtime_stop_write_timeout_ambiguous"
                        )
                    } else {
                        interruptOfflineHistoricalSyncForTransportLoss(
                            reason: "realtime_stop_write_timeout_ambiguous"
                        )
                    }
                    return
                }
            } else if !diagnosticStopsRealtime {
                AtriaDebugLog("ATRIADBG historyOnly status=realtime_preserved generation=%llu command=0300_skipped action=continue_production_read_preflight_keep_2a37",
                              syncGeneration)
            }
            if historyClockSyncEnabled {
                // Do not combine an RTC mutation with the only served WHOOP 4
                // transaction we have captured.  The concrete successful
                // trace is exactly 22/00 -> 2.1s -> 16/00; it contains neither
                // SET_CLOCK nor GET_CLOCK.  Retain the approval outcome for
                // inspection, but move into the capture-proven serve sequence
                // rather than claiming the unverified mutation is required.
                if historyTransportPhaseFence.snapshot().usesExplicitHistoryProfile {
                    historyClockSyncEnabled = false
                    UserDefaults.standard.set(
                        "deferred_minimal_served_profile",
                        forKey: "atria.offlineSync.clockRepairStatus.v1"
                    )
                    AtriaDebugLog("ATRIADBG historyClock status=deferred reason=explicit_minimal_served_profile action=preserve_2200_settle_1600")
                } else {
                // This is deliberately opt-in at launch for the one
                // user-approved recovery repair. The WHOOP 4 historical
                // transport uses the strap RTC as part of its durable backlog
                // workflow. Keep the mutation inside the same single-flight
                // history generation: write-confirm it, allow the strap to
                // settle, then continue with the normal matched cursor and
                // page-ACK path. It is never part of automatic recovery.
                let clockResult = await performUserApprovedHistoryClockSync(
                    generation: syncGeneration
                )
                guard clockResult == .confirmed else {
                    failHistoryHandshakeWrite(
                        generation: syncGeneration,
                        command: Cmd.setClock,
                        result: clockResult
                    )
                    return
                }
                }
            }
            if historySkipDataRangeRequest {
                guard beginProductionHistoricalAdmissionAttempt(
                    generation: syncGeneration
                ) else {
                    failHistoryHandshakeWrite(
                        generation: syncGeneration,
                        command: Cmd.getDataRange,
                        result: .failed
                    )
                    return
                }
                let rangeResult = await observeProductionHistoryCursorRange(
                    generation: syncGeneration
                )
                let cursorRange: AtriaWhoop4HistoryCursorRange
                switch rangeResult {
                case .success(let observed):
                    cursorRange = observed
                case .failure(let writeResult):
                    failHistoryHandshakeWrite(
                        generation: syncGeneration,
                        command: Cmd.getDataRange,
                        result: writeResult
                    )
                    return
                }
                guard cursorRange.pendingRecords > 0 else {
                    // `observeProductionHistoryCursorRange` accepts only the
                    // response whose echoed sequence matches this generation's
                    // confirmed 22/00 write. Preserve that exact zero-pending
                    // authority; it is not a fabricated HISTORY_COMPLETE.
                    verifiedEmptyHistoryCursorGeneration = syncGeneration
                    AtriaDebugLog("ATRIADBG historyRange status=forward_cursor_caught_up generation=%llu authority=matched_2200_zero_pending action=verify_live_then_complete_empty",
                                  syncGeneration)
                    finishOfflineHistoricalSync(
                        reason: "\(offlineHistoricalSyncReason)_cursor_caught_up",
                        generation: syncGeneration,
                        resumePendingSync: false
                    )
                    return
                }
                guard let responseUptime = acceptedHistoryDataRangeResponseUptime else {
                    failHistoryHandshakeWrite(
                        generation: syncGeneration,
                        command: Cmd.getDataRange,
                        result: .failed
                    )
                    return
                }
                AtriaDebugLog("ATRIADBG historyRange status=forward_backlog_available generation=%llu pending=%u action=monotonic_settle_then_1600",
                              syncGeneration,
                              cursorRange.pendingRecords)
                let elapsed = ProcessInfo.processInfo.systemUptime - responseUptime
                let remainingSettle = max(
                    0,
                    AtriaWhoop4ProductionHistoryBootstrapPolicy
                        .postRangeResponseSettle - elapsed
                )
                try? await Task.sleep(for: .seconds(remainingSettle))
                guard !Task.isCancelled,
                      historyOnlyProbeArmed,
                      historyOnlyProbeEpoch == probeEpoch,
                      offlineHistoricalSyncInProgress,
                      offlineHistoricalSyncGeneration == syncGeneration,
                      AtriaWhoop4ProductionHistoryBootstrapPolicy
                        .hasCompletedPostResponseSettle(
                            responseUptime: responseUptime,
                            nowUptime: ProcessInfo.processInfo.systemUptime
                        ) else {
                    failHistoryHandshakeWrite(
                        generation: syncGeneration,
                        command: Cmd.getDataRange,
                        result: .failed
                    )
                    return
                }
                AtriaDebugLog("ATRIADBG historyRange status=post_response_settle_confirmed generation=%llu settle_s=2.0 clock_source=2200 action=send_verified_1600",
                              syncGeneration)
                if productionHistoryReadPreflightRequired {
                    let preflightResult = await performProductionHistoryReadPreflight(
                        generation: syncGeneration
                    )
                    guard preflightResult == .confirmed else {
                        failHistoryHandshakeWrite(
                            generation: syncGeneration,
                            command: Cmd.getClock,
                            result: preflightResult
                        )
                        return
                    }
                }
            }
            if !historyInitSweepCommands.isEmpty {
                AtriaDebugLog("ATRIADBG historyOnly status=send_init_sweep commands=%d mode=%@",
                      historyInitSweepCommands.count,
                      probeCommandMode.rawValue)
                for (index, command) in historyInitSweepCommands.enumerated() {
                    guard let cmd = command.first else { continue }
                    let data = Array(command.dropFirst())
                    if cmd == Cmd.sendHistoricalData, data == [0x00] {
                        guard historyTransportPhaseFence.armServe(
                            ifMatching: syncGeneration
                        ) != nil else {
                            failHistoryHandshakeWrite(
                                generation: syncGeneration,
                                command: cmd,
                                result: .failed
                            )
                            return
                        }
                        pendingFullDrainCommandRequestedAtUnix =
                            Date().timeIntervalSince1970
                    }
                    AtriaDebugLog("ATRIADBG historyInitSweep send index=%d cmd=%02x data=%@ mode=%@",
                          index, cmd, Self.hex(data), probeCommandMode.rawValue)
                    let writeResult = await sendHistoryCommandAwaitingWriteConfirmation(
                        command: cmd,
                        payload: data,
                        generation: syncGeneration
                    )
                    guard writeResult == .confirmed else {
                        failHistoryHandshakeWrite(
                            generation: syncGeneration,
                            command: cmd,
                            result: writeResult
                        )
                        return
                    }
                    AtriaDebugLog("ATRIADBG historyInitSweep status=write_confirmed index=%d cmd=%02x generation=%llu action=advance_single_flight",
                                  index,
                                  cmd,
                                  syncGeneration)
                    if cmd == Cmd.sendHistoricalData,
                       data == [0x00],
                       let cursorRange = acceptedHistoryDataRange,
                       cursorRange.pendingRecords > 0 {
                        // A WHOOP 4 with a nearly full flash ring can emit an
                        // old data record immediately, then delay the matching
                        // HISTORY_START while it settles the serve cursor. The
                        // Physical straps can spend more than 25 seconds
                        // selecting a deep flash backlog before they emit the
                        // matching HISTORY_START. The prior 30-second cutoff
                        // was itself the observed disconnect cause: Atria
                        // cancelled a healthy link immediately before the
                        // strap could serve actual rows. This remains a
                        // passive, background wait—no retry, ACK, abort, or
                        // UI work runs here—and a missing start still retains
                        // the exact gap rather than fabricating coverage.
                        let initialServeWaitSeconds: TimeInterval = 75
                        let initialServeDeadline = Date().addingTimeInterval(
                            initialServeWaitSeconds
                        )
                        while acceptedHistoryStartSequence == nil,
                              Date() < initialServeDeadline {
                            try? await Task.sleep(for: .milliseconds(250))
                            guard !Task.isCancelled,
                                  historyOnlyProbeArmed,
                                  historyOnlyProbeEpoch == probeEpoch,
                                  offlineHistoricalSyncInProgress,
                                  offlineHistoricalSyncGeneration == syncGeneration else {
                                return
                            }
                        }
                        guard acceptedHistoryStartSequence != nil else {
                            // This is a transport failure, not evidence that
                            // the strap lacks records. Retain the ledger gap,
                            // but circuit-break automatic retries for exactly
                            // this gap so they cannot churn the live/R10 owner.
                            // Explicit repair continues to bypass this marker.
                            if let gapFingerprint = offlineHistoricalSyncGapFingerprint {
                                let defaults = UserDefaults.standard
                                defaults.set(
                                    gapFingerprint,
                                    forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint
                                )
                                defaults.set(
                                    Date().timeIntervalSince1970,
                                    forKey: OfflineSyncDefaults.historyStartTimeoutGapAt
                                )
                                defaults.set(
                                    Self.productionHistoryServeProfileVersion,
                                    forKey: OfflineSyncDefaults.historyStartTimeoutProfileVersion
                                )
                            }
                            AtriaDebugLog("ATRIADBG historyServe status=start_timeout generation=%llu pending=%u wait_s=%.0f action=rebuild_link_without_ack_or_abort_retain_gap",
                                          syncGeneration,
                                          cursorRange.pendingRecords,
                                          initialServeWaitSeconds)
                            if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                                generation: syncGeneration,
                                reason: "history_start_timeout_preserve_realtime"
                            ) {
                                return
                            }
                            if let peripheral, peripheral.state == .connected {
                                cancelPeripheralConnection(
                                    peripheral,
                                    reason: "history_start_timeout_transport_reset"
                                )
                            } else {
                                interruptOfflineHistoricalSyncForTransportLoss(
                                    reason: "history_start_timeout"
                                )
                            }
                            return
                        }
                        AtriaDebugLog("ATRIADBG historyServe status=history_start_confirmed generation=%llu pending=%u action=continue_durable_drain",
                                      syncGeneration,
                                      cursorRange.pendingRecords)
                    }
                    if index < historyInitSweepCommands.count - 1 {
                        try? await Task.sleep(for: .seconds(5))
                        guard !Task.isCancelled,
                              historyOnlyProbeArmed,
                              historyOnlyProbeEpoch == probeEpoch else { return }
                    }
                }
                try? await Task.sleep(for: .seconds(3))
                guard !Task.isCancelled,
                      historyOnlyProbeArmed,
                      historyOnlyProbeEpoch == probeEpoch else { return }
            }
            if historySkipDataRangeRequest {
                AtriaDebugLog("ATRIADBG historyOnly status=skip_data_range reason=history_skip_range")
                return
            }
            if historyDataRangeSweepEnabled {
                let payloads = historyDataRangeSweepPayloads
                AtriaDebugLog("ATRIADBG historyOnly status=send_data_range_sweep cmd=22 payloads=%d selector_sweep=%d mode=%@",
                      payloads.count,
                      historySelectorSweepEnabled ? 1 : 0,
                      historySelectorMode)
                for (index, payload) in payloads.enumerated() {
                    AtriaDebugLog("ATRIADBG historyRangeSweep send index=%d cmd=22 data=%@ mode=%@",
                          index, Self.hex(payload), probeCommandMode.rawValue)
                    sendHistoryDataRange(index: index, data: payload)
                    if index < payloads.count - 1 {
                        try? await Task.sleep(for: .seconds(5))
                        guard !Task.isCancelled,
                              historyOnlyProbeArmed,
                              historyOnlyProbeEpoch == probeEpoch else { return }
                    }
                }
            } else {
                AtriaDebugLog("ATRIADBG historyOnly status=send_data_range cmd=22 data=00 selector_sweep=%d mode=%@",
                      historySelectorSweepEnabled ? 1 : 0,
                      historySelectorMode)
                sendHistoryDataRange(index: 0, data: [0x00])
            }
        }
    }

    /// Drains the sacrificial strap through the normal, physically verified
    /// WHOOP 4 page handshake, but intentionally does not persist the old
    /// pages. Every ACK is minted from the exact HISTORY_END token just parsed
    /// from a CRC-valid strap frame; fabricated or replayed tokens are blocked
    /// by `AtriaWhoop4SacrificialFastDrainPolicy`.
    private func startSacrificialFastDrainIfNeeded(reason: String) {
        guard sacrificialFastDrainRequested,
              !sacrificialFastDrainActive,
              !readOnlyHistoryCaptureActive,
              sacrificialFastDrainTask == nil,
              let runID = sacrificialFastDrainRunID,
              sacrificialFastDrainSession != nil else { return }
        readOnlyHistoryCaptureGeneration &+= 1
        let generation = readOnlyHistoryCaptureGeneration
        readOnlyHistoryCaptureActive = true
        sacrificialFastDrainActive = true
        sacrificialFastDrainPreRange = nil
        sacrificialFastDrainHistoryComplete = false
        sacrificialFastDrainReceivedRecords = 0
        sacrificialFastDrainEvidenceRecords = 0
        sacrificialFastDrainACKCount = 0
        sacrificialFastDrainPendingACKToken = nil
        sacrificialFastDrainLastConfirmedACKToken = nil
        sacrificialFastDrainAcknowledgedTokens.removeAll(keepingCapacity: true)
        sacrificialFastDrainACKInFlight = false
        sacrificialFastDrainStopAfterCurrentACK = false
        sacrificialFastDrainSliceAttempt = 0
        sacrificialFastDrainDeferredMetadata = nil
        sacrificialFastDrainFailedReason = nil
        readOnlyHistoryRangeSequence = nil
        readOnlyHistoryRangeWriteConfirmed = false
        readOnlyHistoryRangeResponse = nil
        readOnlyHistoryRangeResponseAt = nil
        _ = historyTransportPhaseFence.activate(generation: generation)
        do {
            let directory = FileManager.default.urls(
                for: .documentDirectory,
                in: .userDomainMask
            )[0].appendingPathComponent(
                "atria-sacrificial-fast-drain",
                isDirectory: true
            )
            readOnlyHistoryCaptureStore =
                try AtriaBLEReadOnlyHistoryCaptureStore(
                    directory: directory,
                    runID: runID.uuidString
                )
            try readOnlyHistoryCaptureStore?.append(
                event: "discard_drain_started",
                fields: [
                    "generation": generation,
                    "reason": reason,
                    "run_id": runID.uuidString,
                    "timeout_seconds":
                        AtriaWhoop4SacrificialFastDrainPolicy
                            .maximumAbortTimeout,
                    "slice_timeout_seconds":
                        AtriaWhoop4SacrificialFastDrainPolicy
                            .sliceTimeout,
                    "maximum_slice_attempts":
                        AtriaWhoop4SacrificialFastDrainPolicy
                            .maximumSliceAttempts,
                    "fabricated_ack": false,
                    "local_data_mutation": false,
                ]
            )
        } catch {
            readOnlyHistoryCaptureActive = false
            sacrificialFastDrainActive = false
            sacrificialFastDrainRequested = false
            AtriaDebugLog(
                "ATRIADBG sacrificial_fast_drain status=store_failed error=%@ action=no_command",
                String(describing: error)
            )
            return
        }

        sacrificialFastDrainTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let required = Set(self.requiredProductionHistoryNotifications)
            for _ in 0..<50 {
                guard self.sacrificialFastDrainActive,
                      self.readOnlyHistoryCaptureGeneration == generation else {
                    return
                }
                if self.peripheral?.state == .connected,
                   self.txCharacteristic != nil,
                   required.isSubset(of: self.activeProprietaryNotifyUUIDs) {
                    break
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard self.sacrificialFastDrainActive,
                  self.readOnlyHistoryCaptureGeneration == generation,
                  self.peripheral?.state == .connected,
                  self.txCharacteristic != nil,
                  required.isSubset(of: self.activeProprietaryNotifyUUIDs) else {
                self.finishSacrificialFastDrain(
                    generation: generation,
                    reason: "notification_readiness_failed",
                    accepted: false
                )
                return
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy
                    .postNotificationSettleInterval
            ))
            await self.runSacrificialFastDrainSlices(
                generation: generation
            )
        }
    }

    /// Keeps one explicit root authorization while bounding every destructive
    /// SERVE interval. A continuation always creates a new policy session and
    /// proves the strap's current cursor with 22/00 before issuing 16/00; an ACK
    /// is still minted only from metadata received in that fresh slice.
    private func runSacrificialFastDrainSlices(
        generation: UInt64
    ) async {
        guard let authorization =
                sacrificialFastDrainSession?.authorization else {
            finishSacrificialFastDrain(
                generation: generation,
                reason: "missing_root_authorization",
                accepted: false
            )
            return
        }
        var previousPreflight:
            AtriaWhoop4SacrificialFastDrainPolicy.CursorObservation?
        var rootPreflight:
            AtriaWhoop4SacrificialFastDrainPolicy.CursorObservation?

        for attempt in 1...AtriaWhoop4SacrificialFastDrainPolicy
            .maximumSliceAttempts {
            guard sacrificialFastDrainActive,
                  readOnlyHistoryCaptureGeneration == generation else {
                return
            }
            sacrificialFastDrainSliceAttempt = attempt
            sacrificialFastDrainHistoryComplete = false
            sacrificialFastDrainStopAfterCurrentACK = false
            sacrificialFastDrainDeferredMetadata = nil
            readOnlyHistoryRangeSequence = nil
            readOnlyHistoryRangeWriteConfirmed = false
            readOnlyHistoryRangeResponse = nil
            readOnlyHistoryRangeResponseAt = nil

            let preflight = await sendSacrificialFastDrainCommand(
                AtriaWhoop4SacrificialFastDrainPolicy.getDataRange,
                generation: generation
            )
            guard preflight == .confirmed,
                  let sequence = readOnlyHistoryRangeSequence,
                  await waitForOneShotHistoryRange(
                    sequence: sequence,
                    generation: generation
                  ),
                  let preRange = readOnlyHistoryRangeResponse else {
                finishSacrificialFastDrain(
                    generation: generation,
                    reason: "preflight_unproven_\(preflight)",
                    accepted: false
                )
                return
            }
            let currentPreflight =
                AtriaWhoop4SacrificialFastDrainPolicy.CursorObservation(
                    writeCursor: preRange.writeCursor,
                    readCursor: preRange.readCursor,
                    capacity: preRange.capacity,
                    pendingRecords: preRange.pendingRecords
                )
            if let previousPreflight,
               !AtriaWhoop4SacrificialFastDrainPolicy
                .hasNonRegressingContinuationPreflight(
                    previous: previousPreflight,
                    current: currentPreflight
                ) {
                try? readOnlyHistoryCaptureStore?.append(
                    event: "continuation_preflight_rejected",
                    fields: [
                        "slice_attempt": attempt,
                        "previous_read_cursor":
                            previousPreflight.readCursor,
                        "current_read_cursor":
                            currentPreflight.readCursor,
                        "capacity": currentPreflight.capacity,
                    ]
                )
                finishSacrificialFastDrain(
                    generation: generation,
                    reason: "continuation_cursor_regressed",
                    accepted: false
                )
                return
            }
            previousPreflight = currentPreflight
            if rootPreflight == nil {
                rootPreflight = currentPreflight
                sacrificialFastDrainPreRange = preRange
            }
            try? readOnlyHistoryCaptureStore?.append(
                event: "preflight_range",
                fields: [
                    "slice_attempt": attempt,
                    "write_cursor": preRange.writeCursor,
                    "read_cursor": preRange.readCursor,
                    "capacity": preRange.capacity,
                    "pending_records": preRange.pendingRecords,
                    "continuation": attempt > 1,
                ]
            )

            let serve = await sendSacrificialFastDrainCommand(
                AtriaWhoop4SacrificialFastDrainPolicy.sendHistorical,
                generation: generation
            )
            guard serve == .confirmed else {
                finishSacrificialFastDrain(
                    generation: generation,
                    reason: "serve_write_\(serve)",
                    accepted: false
                )
                return
            }
            let startedAt = Date()
            let limit =
                AtriaWhoop4SacrificialFastDrainPolicy.sliceTimeout
            while sacrificialFastDrainActive,
                  readOnlyHistoryCaptureGeneration == generation,
                  !sacrificialFastDrainHistoryComplete,
                  sacrificialFastDrainFailedReason == nil,
                  Date().timeIntervalSince(startedAt) < limit {
                try? await Task.sleep(for: .milliseconds(100))
            }
            guard sacrificialFastDrainActive,
                  readOnlyHistoryCaptureGeneration == generation else {
                return
            }
            if let failure = sacrificialFastDrainFailedReason {
                finishSacrificialFastDrain(
                    generation: generation,
                    reason: failure,
                    accepted: false
                )
                return
            }

            if !sacrificialFastDrainHistoryComplete {
                sacrificialFastDrainStopAfterCurrentACK = true
                let ackDeadline = Date().addingTimeInterval(5)
                while sacrificialFastDrainACKInFlight,
                      Date() < ackDeadline {
                    try? await Task.sleep(for: .milliseconds(100))
                }
                guard !sacrificialFastDrainACKInFlight else {
                    finishSacrificialFastDrain(
                        generation: generation,
                        reason: "slice_deadline_ack_still_in_flight",
                        accepted: false
                    )
                    return
                }
                if !sacrificialFastDrainHistoryComplete {
                    do {
                        try sacrificialFastDrainSession?
                            .recordBoundedTimeout(
                                elapsed: Date().timeIntervalSince(startedAt),
                                limit: limit
                            )
                    } catch {
                        finishSacrificialFastDrain(
                            generation: generation,
                            reason: "timeout_policy_\(error)",
                            accepted: false
                        )
                        return
                    }
                    let abort = await sendSacrificialFastDrainCommand(
                        AtriaWhoop4SacrificialFastDrainPolicy.abort,
                        generation: generation
                    )
                    guard abort == .confirmed else {
                        finishSacrificialFastDrain(
                            generation: generation,
                            reason: "bounded_slice_abort_\(abort)",
                            accepted: false
                        )
                        return
                    }
                    try? readOnlyHistoryCaptureStore?.append(
                        event: "discard_drain_checkpoint",
                        fields: [
                            "slice_attempt": attempt,
                            "historical_records_discarded":
                                sacrificialFastDrainReceivedRecords,
                            "acknowledged_chunks":
                                sacrificialFastDrainACKCount,
                            "last_confirmed_ack_token":
                                sacrificialFastDrainLastConfirmedACKToken
                                    .map(Self.hex) ?? "none",
                            "abort_confirmed": true,
                            "accepted": false,
                            "fabricated_ack": false,
                        ]
                    )
                    guard attempt <
                            AtriaWhoop4SacrificialFastDrainPolicy
                                .maximumSliceAttempts else {
                        finishSacrificialFastDrain(
                            generation: generation,
                            reason: "bounded_slice_attempt_limit",
                            accepted: false
                        )
                        return
                    }
                    sacrificialFastDrainSession = .init(
                        authorization: authorization
                    )
                    sacrificialFastDrainPendingACKToken = nil
                    sacrificialFastDrainAcknowledgedTokens.removeAll(
                        keepingCapacity: true
                    )
                    sacrificialFastDrainACKInFlight = false
                    sacrificialFastDrainDeferredMetadata = nil
                    try? await Task.sleep(for: .seconds(
                        AtriaBLEHistoryWriteConfirmationPolicy
                            .postNotificationSettleInterval
                    ))
                    continue
                }
            }

            while sacrificialFastDrainACKInFlight {
                try? await Task.sleep(for: .milliseconds(100))
                guard sacrificialFastDrainActive,
                      readOnlyHistoryCaptureGeneration == generation,
                      sacrificialFastDrainFailedReason == nil else {
                    finishSacrificialFastDrain(
                        generation: generation,
                        reason: sacrificialFastDrainFailedReason
                            ?? "final_ack_interrupted",
                        accepted: false
                    )
                    return
                }
            }

            let postflight = await sendSacrificialFastDrainCommand(
                AtriaWhoop4SacrificialFastDrainPolicy.getDataRange,
                generation: generation
            )
            guard postflight == .confirmed,
                  let postSequence = readOnlyHistoryRangeSequence,
                  await waitForOneShotHistoryRange(
                    sequence: postSequence,
                    generation: generation
                  ),
                  let postRange = readOnlyHistoryRangeResponse,
                  let rootPreflight else {
                finishSacrificialFastDrain(
                    generation: generation,
                    reason: "postflight_unproven_\(postflight)",
                    accepted: false
                )
                return
            }
            let post =
                AtriaWhoop4SacrificialFastDrainPolicy.CursorObservation(
                    writeCursor: postRange.writeCursor,
                    readCursor: postRange.readCursor,
                    capacity: postRange.capacity,
                    pendingRecords: postRange.pendingRecords
                )
            let accepted =
                AtriaWhoop4SacrificialFastDrainPolicy
                    .hasAcceptableCursorCollapse(
                        preflight: rootPreflight,
                        postflight: post
                    )
            try? readOnlyHistoryCaptureStore?.append(
                event: "postflight_range",
                fields: [
                    "slice_attempt": attempt,
                    "write_cursor": postRange.writeCursor,
                    "read_cursor": postRange.readCursor,
                    "capacity": postRange.capacity,
                    "pending_records": postRange.pendingRecords,
                    "accepted": accepted,
                ]
            )
            finishSacrificialFastDrain(
                generation: generation,
                reason: accepted
                    ? "verified_backlog_collapse"
                    : "postflight_backlog_not_collapsed",
                accepted: accepted
            )
            return
        }
    }

    private func sendSacrificialFastDrainCommand(
        _ command: AtriaWhoop4SacrificialFastDrainPolicy.Command,
        generation: UInt64
    ) async -> AtriaBLEReadOnlyHistoryCapturePolicy.WriteConfirmationResult {
        guard sacrificialFastDrainActive,
              readOnlyHistoryCaptureGeneration == generation else {
            return .interrupted
        }
        lastProprietaryWriteCompletion = nil
        guard sendCommand(
            command.opcode,
            command.payload,
            mode: .withResponse
        ), let expected = writeCompletionLedger.pending.first,
           expected.command == command.opcode,
           expected.payload == command.payload else { return .failed }
        if command == AtriaWhoop4SacrificialFastDrainPolicy.getDataRange {
            readOnlyHistoryRangeSequence = expected.sequence
            readOnlyHistoryRangeWriteConfirmed = false
            readOnlyHistoryRangeResponse = nil
            readOnlyHistoryRangeResponseAt = nil
        } else if command
                    == AtriaWhoop4SacrificialFastDrainPolicy.sendHistorical,
                  let runID = sacrificialFastDrainRunID {
            let defaults = UserDefaults.standard
            defaults.set(
                runID.uuidString,
                forKey: Self.sacrificialFastDrainConsumedRunIDKey
            )
            defaults.set(
                runID.uuidString,
                forKey: Self.sacrificialFastDrainActiveRootRunIDKey
            )
        }
        try? readOnlyHistoryCaptureStore?.append(
            event: "command",
            fields: [
                "opcode": String(format: "%02x", command.opcode),
                "payload": Self.hex(command.payload),
                "sequence": expected.sequence,
                "phase_after_accept": String(
                    describing: sacrificialFastDrainSession?.phase
                        ?? .complete
                ),
            ]
        )
        let attempts = AtriaBLEReadOnlyHistoryCapturePolicy
            .writeConfirmationPollAttempts(
                opcode: command.opcode,
                pollInterval:
                    AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            )
        for _ in 0..<attempts {
            if let completion = lastProprietaryWriteCompletion,
               completion.entry == expected {
                return AtriaBLEReadOnlyHistoryCapturePolicy
                    .classifyWriteCompletion(
                        succeeded: completion.succeeded,
                        errorDomain: completion.errorDomain,
                        errorCode: completion.errorCode
                    )
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  sacrificialFastDrainActive,
                  readOnlyHistoryCaptureGeneration == generation else {
                return .interrupted
            }
        }
        return .timedOut
    }

    private func finishSacrificialFastDrain(
        generation: UInt64,
        reason: String,
        accepted: Bool
    ) {
        guard sacrificialFastDrainActive,
              readOnlyHistoryCaptureGeneration == generation else { return }
        let path = readOnlyHistoryCaptureStore?.url.path ?? "missing"
        try? readOnlyHistoryCaptureStore?.append(
            event: "discard_drain_finished",
            fields: [
                "reason": reason,
                "accepted": accepted,
                "historical_records_discarded":
                    sacrificialFastDrainReceivedRecords,
                "evidence_records": sacrificialFastDrainEvidenceRecords,
                "acknowledged_chunks": sacrificialFastDrainACKCount,
                "ack_in_flight": sacrificialFastDrainACKInFlight,
                "pending_ack_token":
                    sacrificialFastDrainPendingACKToken
                        .map(Self.hex) ?? "none",
                "last_confirmed_ack_token":
                    sacrificialFastDrainLastConfirmedACKToken
                        .map(Self.hex) ?? "none",
                "slice_attempt": sacrificialFastDrainSliceAttempt,
                "fabricated_ack": false,
                "local_data_mutation": false,
            ]
        )
        if accepted,
           let runID = sacrificialFastDrainRunID,
           UserDefaults.standard.string(
            forKey: Self.sacrificialFastDrainActiveRootRunIDKey
           ) == runID.uuidString {
            UserDefaults.standard.removeObject(
                forKey: Self.sacrificialFastDrainActiveRootRunIDKey
            )
        }
        try? readOnlyHistoryCaptureStore?.close()
        readOnlyHistoryCaptureStore = nil
        sacrificialFastDrainTask = nil
        sacrificialFastDrainActive = false
        sacrificialFastDrainRequested = false
        sacrificialFastDrainRunID = nil
        sacrificialFastDrainSession = nil
        sacrificialFastDrainPendingACKToken = nil
        sacrificialFastDrainLastConfirmedACKToken = nil
        sacrificialFastDrainAcknowledgedTokens.removeAll(keepingCapacity: true)
        sacrificialFastDrainACKInFlight = false
        sacrificialFastDrainStopAfterCurrentACK = false
        sacrificialFastDrainDeferredMetadata = nil
        readOnlyHistoryCaptureActive = false
        readOnlyHistoryCaptureRequested = false
        historyOnlyProbeEnabled = false
        _ = historyTransportPhaseFence.deactivate(ifMatching: generation)
        AtriaDebugLog(
            "ATRIADBG sacrificial_fast_drain status=finished generation=%llu accepted=%d reason=%@ records=%d acks=%d fabricated_ack=0 local_data_mutation=0 path=%@",
            generation,
            accepted ? 1 : 0,
            reason,
            sacrificialFastDrainReceivedRecords,
            sacrificialFastDrainACKCount,
            path
        )
        reassertHeartRateNotificationsIfConnected(
            reason: "sacrificial_fast_drain_finished"
        )
        if let peripheral, peripheral.state == .connected {
            peripheral.discoverServices(discoveryServicesForCurrentMode)
        }
        onHistoricalTransportOwnershipReleased?(
            "sacrificial_fast_drain_finished"
        )
    }

    /// Runs the only destructive diagnostic admitted by this build. The
    /// current strap has been explicitly designated sacrificial by the user;
    /// the app's local archive, ledgers, workouts and pairing are not mutated.
    /// Once CoreBluetooth accepts 0x19, the run ID is consumed before waiting
    /// for a callback, so an ambiguous result can never retry the trim.
    private func startOneShotHistoryTrimIfNeeded(reason: String) {
        guard oneShotHistoryTrimRequested,
              !readOnlyHistoryCaptureActive,
              oneShotHistoryTrimTask == nil,
              let runID = oneShotHistoryTrimRunID else { return }
        readOnlyHistoryCaptureGeneration &+= 1
        let generation = readOnlyHistoryCaptureGeneration
        readOnlyHistoryCaptureActive = true
        readOnlyHistoryRangeSequence = nil
        readOnlyHistoryRangeWriteConfirmed = false
        readOnlyHistoryRangeResponse = nil
        readOnlyHistoryRangeResponseAt = nil
        oneShotHistoryTrimPreRange = nil
        oneShotHistoryTrimIssued = false
        oneShotHistoryTrimCommandSequence = nil
        oneShotHistoryTrimCommandResponseMatched = false
        _ = historyTransportPhaseFence.activate(generation: generation)
        do {
            let directory = FileManager.default.urls(
                for: .documentDirectory,
                in: .userDomainMask
            )[0].appendingPathComponent(
                "atria-sacrificial-history-trim",
                isDirectory: true
            )
            readOnlyHistoryCaptureStore =
                try AtriaBLEReadOnlyHistoryCaptureStore(
                    directory: directory,
                    runID: runID.uuidString
                )
            try readOnlyHistoryCaptureStore?.append(
                event: "trim_started",
                fields: [
                    "generation": generation,
                    "reason": reason,
                    "run_id": runID.uuidString,
                    "trace": "2200,19fefefefefefefefe00,2200",
                    "automatic_retry": false,
                    "local_data_mutation": false,
                ]
            )
        } catch {
            readOnlyHistoryCaptureActive = false
            oneShotHistoryTrimRequested = false
            AtriaDebugLog(
                "ATRIADBG sacrificial_history_trim status=store_failed error=%@ action=no_command",
                String(describing: error)
            )
            return
        }

        oneShotHistoryTrimTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let required = Set(self.requiredProductionHistoryNotifications)
            for _ in 0..<50 {
                guard self.readOnlyHistoryCaptureActive,
                      self.readOnlyHistoryCaptureGeneration == generation else {
                    return
                }
                if self.peripheral?.state == .connected,
                   self.txCharacteristic != nil,
                   required.isSubset(of: self.activeProprietaryNotifyUUIDs) {
                    break
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard self.readOnlyHistoryCaptureActive,
                  self.readOnlyHistoryCaptureGeneration == generation,
                  self.peripheral?.state == .connected,
                  self.txCharacteristic != nil,
                  required.isSubset(of: self.activeProprietaryNotifyUUIDs) else {
                self.finishOneShotHistoryTrim(
                    generation: generation,
                    reason: "notification_readiness_failed",
                    accepted: false
                )
                return
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy
                    .postNotificationSettleInterval
            ))

            let preflight = await self.sendOneShotHistoryTrimCommand(
                AtriaWhoop4SacrificialHistoryTrimPolicy.getDataRange,
                generation: generation
            )
            guard preflight == .confirmed,
                  let preflightSequence = self.readOnlyHistoryRangeSequence else {
                self.finishOneShotHistoryTrim(
                    generation: generation,
                    reason: "preflight_write_\(preflight)",
                    accepted: false
                )
                return
            }
            guard await self.waitForOneShotHistoryRange(
                sequence: preflightSequence,
                generation: generation
            ), let preRange = self.readOnlyHistoryRangeResponse else {
                self.finishOneShotHistoryTrim(
                    generation: generation,
                    reason: "preflight_response_timeout",
                    accepted: false
                )
                return
            }
            self.oneShotHistoryTrimPreRange = preRange
            try? self.readOnlyHistoryCaptureStore?.append(
                event: "preflight_range",
                fields: [
                    "write_cursor": preRange.writeCursor,
                    "read_cursor": preRange.readCursor,
                    "capacity": preRange.capacity,
                    "pending_records": preRange.pendingRecords,
                ]
            )

            let trimResult = await self.sendOneShotHistoryTrimCommand(
                AtriaWhoop4SacrificialHistoryTrimPolicy.forceTrim,
                generation: generation
            )
            // No outcome, including timeout, may retry 0x19. When the command
            // entered CoreBluetooth the policy has already advanced to the
            // sole postflight 22/00 read.
            guard self.oneShotHistoryTrimIssued else {
                self.finishOneShotHistoryTrim(
                    generation: generation,
                    reason: "trim_not_issued_\(trimResult)",
                    accepted: false
                )
                return
            }
            try? self.readOnlyHistoryCaptureStore?.append(
                event: "force_trim_write_result",
                fields: [
                    "result": String(describing: trimResult),
                    "logical_response_matched":
                        self.oneShotHistoryTrimCommandResponseMatched,
                    "automatic_retry": false,
                ]
            )
            try? await Task.sleep(for: .seconds(2))
            guard self.readOnlyHistoryCaptureActive,
                  self.readOnlyHistoryCaptureGeneration == generation,
                  self.peripheral?.state == .connected else {
                self.finishOneShotHistoryTrim(
                    generation: generation,
                    reason: "post_trim_transport_lost",
                    accepted: false
                )
                return
            }

            let postflight = await self.sendOneShotHistoryTrimCommand(
                AtriaWhoop4SacrificialHistoryTrimPolicy.getDataRange,
                generation: generation
            )
            guard postflight == .confirmed,
                  let postflightSequence = self.readOnlyHistoryRangeSequence,
                  await self.waitForOneShotHistoryRange(
                    sequence: postflightSequence,
                    generation: generation
                  ),
                  let postRange = self.readOnlyHistoryRangeResponse else {
                self.finishOneShotHistoryTrim(
                    generation: generation,
                    reason: "postflight_unproven_\(postflight)",
                    accepted: false
                )
                return
            }
            let pre = AtriaWhoop4SacrificialHistoryTrimPolicy.CursorObservation(
                writeCursor: preRange.writeCursor,
                readCursor: preRange.readCursor,
                pendingRecords: preRange.pendingRecords
            )
            let post = AtriaWhoop4SacrificialHistoryTrimPolicy.CursorObservation(
                writeCursor: postRange.writeCursor,
                readCursor: postRange.readCursor,
                pendingRecords: postRange.pendingRecords
            )
            let accepted =
                AtriaWhoop4SacrificialHistoryTrimPolicy
                    .hasAcceptablePostTrimCollapse(
                        preflight: pre,
                        postflight: post
                    )
            try? self.readOnlyHistoryCaptureStore?.append(
                event: "postflight_range",
                fields: [
                    "write_cursor": postRange.writeCursor,
                    "read_cursor": postRange.readCursor,
                    "capacity": postRange.capacity,
                    "pending_records": postRange.pendingRecords,
                    "accepted": accepted,
                ]
            )
            self.finishOneShotHistoryTrim(
                generation: generation,
                reason: accepted
                    ? "verified_backlog_collapse"
                    : "postflight_backlog_not_collapsed",
                accepted: accepted
            )
        }
    }

    private func sendOneShotHistoryTrimCommand(
        _ command: AtriaWhoop4SacrificialHistoryTrimPolicy.Command,
        generation: UInt64
    ) async -> AtriaBLEReadOnlyHistoryCapturePolicy.WriteConfirmationResult {
        guard readOnlyHistoryCaptureActive,
              readOnlyHistoryCaptureGeneration == generation,
              oneShotHistoryTrimRequested,
              let nextPhase =
                try? AtriaWhoop4SacrificialHistoryTrimPolicy.authorize(
                    command: command,
                    in: oneShotHistoryTrimPhase
                ) else { return .interrupted }
        lastProprietaryWriteCompletion = nil
        guard sendCommand(
            command.opcode,
            command.payload,
            mode: .withResponse
        ), let expected = writeCompletionLedger.pending.first,
           expected.command == command.opcode,
           expected.payload == command.payload else { return .failed }

        // Advance immediately after CoreBluetooth accepted the write. This is
        // what makes a missing callback fail closed instead of retrying 0x19.
        oneShotHistoryTrimPhase = nextPhase
        if command == AtriaWhoop4SacrificialHistoryTrimPolicy.getDataRange {
            readOnlyHistoryRangeSequence = expected.sequence
            readOnlyHistoryRangeWriteConfirmed = false
            readOnlyHistoryRangeResponse = nil
            readOnlyHistoryRangeResponseAt = nil
        } else if command
                    == AtriaWhoop4SacrificialHistoryTrimPolicy.forceTrim {
            oneShotHistoryTrimIssued = true
            oneShotHistoryTrimCommandSequence = expected.sequence
            oneShotHistoryTrimCommandResponseMatched = false
            if let runID = oneShotHistoryTrimRunID {
                UserDefaults.standard.set(
                    runID.uuidString,
                    forKey: Self.oneShotHistoryTrimConsumedRunIDKey
                )
            }
        }
        try? readOnlyHistoryCaptureStore?.append(
            event: "command",
            fields: [
                "opcode": String(format: "%02x", command.opcode),
                "payload": Self.hex(command.payload),
                "sequence": expected.sequence,
                "phase_after_accept":
                    String(describing: oneShotHistoryTrimPhase),
            ]
        )
        let attempts = AtriaBLEReadOnlyHistoryCapturePolicy
            .writeConfirmationPollAttempts(
                opcode: command.opcode,
                pollInterval:
                    AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            )
        for _ in 0..<attempts {
            if let completion = lastProprietaryWriteCompletion,
               completion.entry == expected {
                return AtriaBLEReadOnlyHistoryCapturePolicy
                    .classifyWriteCompletion(
                        succeeded: completion.succeeded,
                        errorDomain: completion.errorDomain,
                        errorCode: completion.errorCode
                    )
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  readOnlyHistoryCaptureActive,
                  readOnlyHistoryCaptureGeneration == generation else {
                return .interrupted
            }
        }
        return .timedOut
    }

    private func waitForOneShotHistoryRange(
        sequence: UInt8,
        generation: UInt64
    ) async -> Bool {
        for _ in 0..<AtriaBLEHistoryWriteConfirmationPolicy
            .maximumPollAttempts {
            if readOnlyHistoryRangeWriteConfirmed,
               readOnlyHistoryRangeResponse?.requestSequenceEcho == sequence,
               readOnlyHistoryRangeResponseAt != nil {
                return true
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  readOnlyHistoryCaptureActive,
                  readOnlyHistoryCaptureGeneration == generation else {
                return false
            }
        }
        return false
    }

    private func finishOneShotHistoryTrim(
        generation: UInt64,
        reason: String,
        accepted: Bool
    ) {
        guard readOnlyHistoryCaptureActive,
              readOnlyHistoryCaptureGeneration == generation else { return }
        let path = readOnlyHistoryCaptureStore?.url.path ?? "missing"
        try? readOnlyHistoryCaptureStore?.append(
            event: "trim_finished",
            fields: [
                "reason": reason,
                "accepted": accepted,
                "trim_issued": oneShotHistoryTrimIssued,
                "logical_response_matched":
                    oneShotHistoryTrimCommandResponseMatched,
                "automatic_retry": false,
                "local_data_mutation": false,
            ]
        )
        try? readOnlyHistoryCaptureStore?.close()
        readOnlyHistoryCaptureStore = nil
        oneShotHistoryTrimTask = nil
        readOnlyHistoryCaptureTask = nil
        readOnlyHistoryCaptureActive = false
        readOnlyHistoryCaptureRequested = false
        oneShotHistoryTrimRequested = false
        oneShotHistoryTrimRunID = nil
        historyOnlyProbeEnabled = false
        _ = historyTransportPhaseFence.deactivate(ifMatching: generation)
        AtriaDebugLog(
            "ATRIADBG sacrificial_history_trim status=finished generation=%llu accepted=%d reason=%@ trim_issued=%d response_matched=%d retry=0 local_data_mutation=0 path=%@",
            generation,
            accepted ? 1 : 0,
            reason,
            oneShotHistoryTrimIssued ? 1 : 0,
            oneShotHistoryTrimCommandResponseMatched ? 1 : 0,
            path
        )
        reassertHeartRateNotificationsIfConnected(
            reason: "sacrificial_history_trim_finished"
        )
        if let peripheral, peripheral.state == .connected {
            peripheral.discoverServices(discoveryServicesForCurrentMode)
        }
        onHistoricalTransportOwnershipReleased?(
            "sacrificial_history_trim_finished"
        )
    }

    /// Runs the audited evidence-only WHOOP 4 transaction. It is deliberately
    /// separate from offline recovery: no gap authority, reducers, ACKs, clock,
    /// realtime-stop, high-frequency mode, or metric publication are reachable.
    private func startReadOnlyHistoryCaptureIfNeeded(reason: String) {
        guard readOnlyHistoryCaptureRequested,
              !readOnlyHistoryCaptureActive,
              readOnlyHistoryCaptureTask == nil else { return }
        if sacrificialFastDrainRequested {
            startSacrificialFastDrainIfNeeded(reason: reason)
            return
        }
        if oneShotHistoryTrimRequested {
            startOneShotHistoryTrimIfNeeded(reason: reason)
            return
        }
        if readOnlyExactRangeCaptureRequested {
            if readOnlyExactRangeUsesExplicitArguments {
                guard readOnlyExactRangePayload != nil,
                      readOnlyExactRangeStartUnix != nil,
                      readOnlyExactRangeEndUnix != nil else {
                    AtriaDebugLog("ATRIADBG readOnlyHistory status=not_started mode=exact_range reason=invalid_explicit_interval action=no_command")
                    readOnlyHistoryCaptureRequested = false
                    readOnlyExactRangeCaptureRequested = false
                    historyOnlyProbeEnabled = false
                    return
                }
            } else {
                let candidate: AtriaHistoricalGapLedger.RecoveryCandidate?
                if let wanted = readOnlyExactRangeRequestedGapID {
                    candidate = AtriaHistoricalGapLedger
                        .allClosedRecoveryCandidates()
                        .first { $0.window.id == wanted }
                } else {
                    candidate = AtriaHistoricalGapLedger
                        .newestClosedRecoveryCandidate()
                }
                guard let candidate,
                      let end = candidate.window.end else {
                    AtriaDebugLog("ATRIADBG readOnlyHistory status=not_started mode=exact_range reason=no_closed_nonlegacy_gap action=no_command")
                    readOnlyHistoryCaptureRequested = false
                    readOnlyExactRangeCaptureRequested = false
                    historyOnlyProbeEnabled = false
                    return
                }
                let startUnix = UInt32(clamping: Int(
                    floor(candidate.window.start.timeIntervalSince1970)
                ))
                let endUnix = UInt32(clamping: Int(
                    ceil(end.timeIntervalSince1970)
                ))
                guard let exactPayload =
                        AtriaBLEReadOnlyExactRangeCapturePolicy.payload(
                            startUnix: startUnix,
                            endUnix: endUnix
                        ) else {
                    AtriaDebugLog("ATRIADBG readOnlyHistory status=not_started mode=exact_range reason=invalid_interval gap=%@ duration_s=%.3f action=no_command",
                                  candidate.window.id.uuidString,
                                  end.timeIntervalSince(candidate.window.start))
                    readOnlyHistoryCaptureRequested = false
                    readOnlyExactRangeCaptureRequested = false
                    historyOnlyProbeEnabled = false
                    return
                }
                readOnlyExactRangeCandidate = candidate
                readOnlyExactRangePayload = exactPayload
                readOnlyExactRangeStartUnix = startUnix
                readOnlyExactRangeEndUnix = endUnix
            }
            readOnlyExactRangeDecodedRows = 0
            readOnlyExactRangeInWindowRows = 0
        }
        readOnlyHistoryCaptureGeneration &+= 1
        let generation = readOnlyHistoryCaptureGeneration
        readOnlyHistoryCaptureActive = true
        readOnlyHistoryAbortIssued = false
        readOnlyHistoryRangeSequence = nil
        readOnlyHistoryRangeWriteConfirmed = false
        readOnlyHistoryRangeResponse = nil
        readOnlyHistoryRangeResponseAt = nil
        readOnlyHistoryServeWriteConfirmed = false
        readOnlyHistoryStarted = false
        _ = historyTransportPhaseFence.activate(generation: generation)
        let runID = "\(Int(Date().timeIntervalSince1970))-g\(generation)"
        do {
            let directory = FileManager.default.urls(for: .documentDirectory,
                                                      in: .userDomainMask)[0]
                .appendingPathComponent("atria-read-only-history-captures",
                                        isDirectory: true)
            readOnlyHistoryCaptureStore = try AtriaBLEReadOnlyHistoryCaptureStore(
                directory: directory,
                runID: runID
            )
            try readOnlyHistoryCaptureStore?.append(
                event: "capture_started",
                fields: [
                    "generation": generation,
                    "reason": reason,
                    "mode": readOnlyExactRangeCaptureRequested
                        ? "exact_range" : "full_drain_observation",
                    "gap_id": readOnlyExactRangeCandidate?
                        .window.id.uuidString ?? "none",
                    "requested_start_unix":
                        readOnlyExactRangeStartUnix.map(Int.init) ?? 0,
                    "requested_end_unix":
                        readOnlyExactRangeEndUnix.map(Int.init) ?? 0,
                    "ledger_generation": readOnlyExactRangeCandidate?
                        .ledgerGeneration ?? 0,
                    "ledger_sha256": readOnlyExactRangeCandidate?
                        .ledgerSnapshotSHA256 ?? "none",
                ]
            )
        } catch {
            readOnlyHistoryCaptureActive = false
            AtriaDebugLog("ATRIADBG readOnlyHistory status=store_failed generation=%llu error=%@ action=no_command",
                          generation,
                          String(describing: error))
            return
        }
        AtriaDebugLog("ATRIADBG readOnlyHistory status=started generation=%llu reason=%@ trace=2200_then_1600_then_1400",
                      generation,
                      reason)
        readOnlyHistoryCaptureTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let required = Set(requiredProductionHistoryNotifications)
            for _ in 0..<50 {
                guard self.readOnlyHistoryCaptureActive,
                      self.readOnlyHistoryCaptureGeneration == generation else { return }
                if self.peripheral?.state == .connected,
                   self.txCharacteristic != nil,
                   required.isSubset(of: self.activeProprietaryNotifyUUIDs) {
                    break
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard self.readOnlyHistoryCaptureActive,
                  self.readOnlyHistoryCaptureGeneration == generation,
                  self.peripheral?.state == .connected,
                  self.txCharacteristic != nil,
                  required.isSubset(of: self.activeProprietaryNotifyUUIDs) else {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "notification_readiness_failed")
                return
            }

            // Keep the verified subscription-settle boundary, then issue one
            // range request. Only an explicit authentication/encryption callback
            // may authorize one additional attempt after a bounded settle.
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.postNotificationSettleInterval
            ))
            guard self.readOnlyHistoryCaptureActive,
                  self.readOnlyHistoryCaptureGeneration == generation else { return }
            var rangeResult = await self.sendReadOnlyHistoryCommandAwaitingConfirmation(
                opcode: Cmd.getDataRange,
                generation: generation
            )
            var rangeRetries = 0
            if AtriaBLEReadOnlyHistoryCapturePolicy.permitsRangeRetry(
                after: rangeResult,
                retriesAlreadyIssued: rangeRetries
            ) {
                rangeRetries += 1
                AtriaDebugLog("ATRIADBG readOnlyHistory status=range_security_required generation=%llu action=bounded_pairing_settle_then_single_retry",
                              generation)
                try? await Task.sleep(for: .seconds(
                    AtriaBLEReadOnlyHistoryCapturePolicy.pairingSettle
                ))
                guard !Task.isCancelled,
                      self.readOnlyHistoryCaptureActive,
                      self.readOnlyHistoryCaptureGeneration == generation,
                      self.peripheral?.state == .connected else {
                    self.finishReadOnlyHistoryCapture(generation: generation,
                                                      reason: "pairing_settle_interrupted")
                    return
                }
                rangeResult = await self.sendReadOnlyHistoryCommandAwaitingConfirmation(
                    opcode: Cmd.getDataRange,
                    generation: generation
                )
            }
            guard rangeResult == .confirmed,
                  let expectedSequence = self.readOnlyHistoryRangeSequence else {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "range_write_\(rangeResult)")
                return
            }

            for _ in 0..<AtriaBLEHistoryWriteConfirmationPolicy.maximumPollAttempts {
                guard self.readOnlyHistoryCaptureActive,
                      self.readOnlyHistoryCaptureGeneration == generation else { return }
                if self.readOnlyHistoryRangeWriteConfirmed,
                   self.readOnlyHistoryRangeResponse?.requestSequenceEcho == expectedSequence,
                   self.readOnlyHistoryRangeResponseAt != nil {
                    break
                }
                try? await Task.sleep(for: .seconds(
                    AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
                ))
            }
            guard self.readOnlyHistoryRangeWriteConfirmed,
                  let range = self.readOnlyHistoryRangeResponse,
                  range.requestSequenceEcho == expectedSequence,
                  let responseAt = self.readOnlyHistoryRangeResponseAt else {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "range_write_or_response_timeout")
                return
            }
            try? self.readOnlyHistoryCaptureStore?.append(
                event: "range_response",
                fields: [
                    "request_sequence_echo": range.requestSequenceEcho,
                    "write_cursor": range.writeCursor,
                    "read_cursor": range.readCursor,
                    "capacity": range.capacity,
                    "pending_records": range.pendingRecords,
                ]
            )
            let remainingSettle = max(
                0,
                AtriaBLEReadOnlyHistoryCapturePolicy.postRangeResponseSettle
                    - Date().timeIntervalSince(responseAt)
            )
            try? await Task.sleep(for: .seconds(remainingSettle))
            guard self.readOnlyHistoryCaptureActive,
                  self.readOnlyHistoryCaptureGeneration == generation,
                  self.peripheral?.state == .connected,
                  required.isSubset(of: self.activeProprietaryNotifyUUIDs) else {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "settle_lost_transport")
                return
            }
            let responseToServe = Date().timeIntervalSince(responseAt)
            guard responseToServe >= AtriaBLEReadOnlyHistoryCapturePolicy
                .postRangeResponseSettle else {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "settle_under_2_seconds")
                return
            }
            let servePayload = self.readOnlyExactRangePayload ?? [0x00]
            let serve = await self.sendReadOnlyHistoryCommandAwaitingConfirmation(
                opcode: Cmd.sendHistoricalData,
                payload: servePayload,
                generation: generation
            )
            guard serve == .confirmed else {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "serve_write_failed")
                return
            }
            self.readOnlyHistoryServeWriteConfirmed = true
            try? self.readOnlyHistoryCaptureStore?.append(
                event: "serve_confirmed",
                fields: [
                    "opcode": "16",
                    "payload": Self.hex(servePayload),
                    "mode": self.readOnlyExactRangeCaptureRequested
                        ? "exact_range" : "full_drain_observation",
                    "range_response_to_serve_seconds": responseToServe,
                ]
            )
            AtriaDebugLog("ATRIADBG readOnlyHistory status=serve_confirmed generation=%llu command=16 payload=%@ mode=%@ response_to_serve_s=%.3f action=capture_bounded_raw",
                          generation,
                          Self.hex(servePayload),
                          self.readOnlyExactRangeCaptureRequested
                              ? "exact_range" : "full_drain_observation",
                          responseToServe)
            let deadline = Date().addingTimeInterval(
                self.readOnlyExactRangeCaptureRequested
                    ? AtriaBLEReadOnlyExactRangeCapturePolicy.captureTimeout
                    : AtriaBLEReadOnlyHistoryCapturePolicy.captureTimeout
            )
            while self.readOnlyHistoryCaptureActive,
                  self.readOnlyHistoryCaptureGeneration == generation,
                  Date() < deadline {
                try? await Task.sleep(for: .milliseconds(250))
            }
            if self.readOnlyHistoryCaptureActive,
               self.readOnlyHistoryCaptureGeneration == generation {
                self.finishReadOnlyHistoryCapture(generation: generation,
                                                  reason: "bounded_timeout")
            }
        }
    }

    private func sendReadOnlyHistoryCommandAwaitingConfirmation(
        opcode: UInt8,
        payload: [UInt8] = [0x00],
        generation: UInt64
    ) async -> AtriaBLEReadOnlyHistoryCapturePolicy.WriteConfirmationResult {
        let commandAllowed: Bool
        if readOnlyExactRangeCaptureRequested,
           let exactPayload = readOnlyExactRangePayload {
            commandAllowed = AtriaBLEReadOnlyExactRangeCapturePolicy.allows(
                opcode: opcode,
                payload: payload,
                exactPayload: exactPayload
            )
        } else {
            commandAllowed = AtriaBLEReadOnlyHistoryCapturePolicy.allows(
                opcode: opcode,
                payload: payload
            )
        }
        guard readOnlyHistoryCaptureActive,
              readOnlyHistoryCaptureGeneration == generation,
              commandAllowed else { return .interrupted }
        lastProprietaryWriteCompletion = nil
        guard sendCommand(opcode, payload, mode: .withResponse),
              let expected = writeCompletionLedger.pending.first,
              expected.command == opcode,
              expected.payload == payload else { return .failed }
        if opcode == Cmd.getDataRange {
            readOnlyHistoryRangeSequence = expected.sequence
            readOnlyHistoryRangeWriteConfirmed = false
            readOnlyHistoryRangeResponse = nil
            readOnlyHistoryRangeResponseAt = nil
        }
        try? readOnlyHistoryCaptureStore?.append(
            event: "command",
            fields: [
                "opcode": String(format: "%02x", opcode),
                "payload": Self.hex(payload),
                "sequence": expected.sequence,
            ]
        )
        let pollAttempts = AtriaBLEReadOnlyHistoryCapturePolicy
            .writeConfirmationPollAttempts(
                opcode: opcode,
                pollInterval: AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            )
        for _ in 0..<pollAttempts {
            if let completion = lastProprietaryWriteCompletion,
               completion.entry.sequence == expected.sequence,
               completion.entry.command == opcode,
               completion.entry.payload == payload {
                return AtriaBLEReadOnlyHistoryCapturePolicy.classifyWriteCompletion(
                    succeeded: completion.succeeded,
                    errorDomain: completion.errorDomain,
                    errorCode: completion.errorCode
                )
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  readOnlyHistoryCaptureActive,
                  readOnlyHistoryCaptureGeneration == generation else { return .interrupted }
        }
        return .timedOut
    }

    private func finishReadOnlyHistoryCapture(generation: UInt64, reason: String) {
        guard readOnlyHistoryCaptureActive,
              readOnlyHistoryCaptureGeneration == generation,
              !readOnlyHistoryAbortIssued else { return }
        readOnlyHistoryAbortIssued = true
        let shouldIssueAbort = AtriaBLEReadOnlyHistoryCapturePolicy.shouldIssueAbort(
            serveWriteConfirmed: readOnlyHistoryServeWriteConfirmed,
            historyStarted: readOnlyHistoryStarted
        )
        Task { @MainActor [weak self] in
            guard let self else { return }
            let abortResult: AtriaBLEReadOnlyHistoryCapturePolicy.WriteConfirmationResult
            if shouldIssueAbort {
                abortResult = await self.sendReadOnlyHistoryCommandAwaitingConfirmation(
                    opcode: Cmd.abortHistoricalTransmits,
                    generation: generation
                )
            } else {
                abortResult = .interrupted
            }
            let abortConfirmed = abortResult == .confirmed
            let frames = self.readOnlyHistoryCaptureStore?.frameCount ?? 0
            try? self.readOnlyHistoryCaptureStore?.append(
                event: "capture_finished",
                fields: [
                    "reason": reason,
                    "frames": frames,
                    "abort_issued": shouldIssueAbort,
                    "abort_confirmed": abortConfirmed,
                    "serve_write_confirmed": self.readOnlyHistoryServeWriteConfirmed,
                    "history_started": self.readOnlyHistoryStarted,
                    "mode": self.readOnlyExactRangeCaptureRequested
                        ? "exact_range" : "full_drain_observation",
                    "gap_id": self.readOnlyExactRangeCandidate?
                        .window.id.uuidString ?? "none",
                    "requested_start_unix":
                        self.readOnlyExactRangeStartUnix.map(Int.init) ?? 0,
                    "requested_end_unix":
                        self.readOnlyExactRangeEndUnix.map(Int.init) ?? 0,
                    "decoded_rows": self.readOnlyExactRangeDecodedRows,
                    "in_window_rows": self.readOnlyExactRangeInWindowRows,
                ]
            )
            try? self.readOnlyHistoryCaptureStore?.close()
            let path = self.readOnlyHistoryCaptureStore?.url.path ?? "missing"
            self.readOnlyHistoryCaptureStore = nil
            self.readOnlyHistoryCaptureActive = false
            self.readOnlyHistoryCaptureRequested = false
            self.readOnlyExactRangeCaptureRequested = false
            self.readOnlyExactRangeRequestedGapID = nil
            self.readOnlyExactRangeCandidate = nil
            self.readOnlyExactRangePayload = nil
            self.readOnlyExactRangeStartUnix = nil
            self.readOnlyExactRangeEndUnix = nil
            self.readOnlyHistoryCaptureTask = nil
            self.historyOnlyProbeEnabled = false
            _ = self.historyTransportPhaseFence.deactivate(ifMatching: generation)
            AtriaDebugLog("ATRIADBG readOnlyHistory status=finished generation=%llu reason=%@ frames=%d abort_confirmed=%d ack=0 gap_mutation=0 path=%@",
                          generation,
                          reason,
                          frames,
                          abortConfirmed ? 1 : 0,
                          path)
            self.reassertHeartRateNotificationsIfConnected(
                reason: "read_only_history_capture_finished"
            )
            self.onHistoricalTransportOwnershipReleased?(
                "read_only_history_capture_finished"
            )
        }
    }

    private func cancelReadOnlyHistoryCaptureAfterDisconnect(reason: String) {
        guard readOnlyHistoryCaptureRequested || readOnlyHistoryCaptureActive else { return }
        let generation = readOnlyHistoryCaptureGeneration
        if sacrificialFastDrainActive {
            sacrificialFastDrainTask?.cancel()
            sacrificialFastDrainTask = nil
            try? readOnlyHistoryCaptureStore?.append(
                event: "capture_disconnected",
                fields: [
                    "reason": reason,
                    "historical_records_discarded":
                        sacrificialFastDrainReceivedRecords,
                    "acknowledged_chunks":
                        sacrificialFastDrainACKCount,
                    "ack_in_flight":
                        sacrificialFastDrainACKInFlight,
                    "pending_ack_token":
                        sacrificialFastDrainPendingACKToken
                            .map(Self.hex) ?? "none",
                    "last_confirmed_ack_token":
                        sacrificialFastDrainLastConfirmedACKToken
                            .map(Self.hex) ?? "none",
                    "slice_attempt":
                        sacrificialFastDrainSliceAttempt,
                    "accepted": false,
                    "abort_confirmed": false,
                    "fabricated_ack": false,
                ]
            )
            finishSacrificialFastDrain(
                generation: generation,
                reason: "transport_disconnected_\(reason)",
                accepted: false
            )
            return
        }
        let frames = readOnlyHistoryCaptureStore?.frameCount ?? 0
        readOnlyHistoryCaptureTask?.cancel()
        readOnlyHistoryCaptureTask = nil
        oneShotHistoryTrimTask?.cancel()
        oneShotHistoryTrimTask = nil
        sacrificialFastDrainTask?.cancel()
        sacrificialFastDrainTask = nil
        try? readOnlyHistoryCaptureStore?.append(
            event: "capture_disconnected",
            fields: [
                "reason": reason,
                "frames": frames,
                "abort_confirmed": false,
                "ack_sent": false,
            ]
        )
        try? readOnlyHistoryCaptureStore?.close()
        readOnlyHistoryCaptureStore = nil
        readOnlyHistoryCaptureActive = false
        readOnlyHistoryCaptureRequested = false
        readOnlyExactRangeCaptureRequested = false
        readOnlyExactRangeRequestedGapID = nil
        readOnlyExactRangeCandidate = nil
        readOnlyExactRangePayload = nil
        readOnlyExactRangeStartUnix = nil
        readOnlyExactRangeEndUnix = nil
        readOnlyHistoryAbortIssued = true
        oneShotHistoryTrimRequested = false
        oneShotHistoryTrimRunID = nil
        sacrificialFastDrainActive = false
        sacrificialFastDrainRequested = false
        sacrificialFastDrainRunID = nil
        sacrificialFastDrainSession = nil
        sacrificialFastDrainPendingACKToken = nil
        sacrificialFastDrainACKInFlight = false
        historyOnlyProbeEnabled = false
        _ = historyTransportPhaseFence.deactivate(ifMatching: generation)
        onHistoricalTransportOwnershipReleased?("read_only_history_capture_disconnected")
        AtriaDebugLog("ATRIADBG readOnlyHistory status=disconnected generation=%llu reason=%@ frames=%d abort_confirmed=0 ack=0 gap_mutation=0 action=restore_live",
                      generation,
                      reason,
                      frames)
    }

    nonisolated static func shouldRearmHistoryOnlyProbeAfterTXDiscovery(
        historyOnlyProbeEnabled: Bool,
        historyOnlyProbeMode: Bool,
        historyOnlyProbeArmed: Bool
    ) -> Bool {
        historyOnlyProbeEnabled && historyOnlyProbeMode && !historyOnlyProbeArmed
    }

    /// Returns true while the historical probe owns TX, even when the existing
    /// attempt is still inside its discovery wait. This prevents realtime setup
    /// from competing for the proprietary command channel during a drain.
    @MainActor
    private func handleHistoryOnlyTXDiscoveryIfNeeded(reason: String) -> Bool {
        guard historyOnlyProbeEnabled, historyOnlyProbeMode else { return false }
        guard txCharacteristic != nil else { return true }
        if readOnlyClockProbeRequested {
            startReadOnlyClockProbeIfNeeded(reason: reason)
            return true
        }
        if readOnlyHistoryCaptureRequested {
            startReadOnlyHistoryCaptureIfNeeded(reason: reason)
            return true
        }
        if Self.shouldRearmHistoryOnlyProbeAfterTXDiscovery(
            historyOnlyProbeEnabled: historyOnlyProbeEnabled,
            historyOnlyProbeMode: historyOnlyProbeMode,
            historyOnlyProbeArmed: historyOnlyProbeArmed
        ) {
            AtriaDebugLog("ATRIADBG historyOnly status=tx_discovered action=rearm reason=%@ epoch=%llu",
                          reason,
                          historyOnlyProbeEpoch)
            armHistoryOnlyProbe()
        }
        return true
    }

    /// One debug-only, non-mutating clock read used to bind physical motion
    /// evidence to wall-clock workout boundaries. The history transport fence
    /// prevents another proprietary owner from sharing the command pipe.
    private func startReadOnlyClockProbeIfNeeded(reason: String) {
        guard readOnlyClockProbeRequested,
              !readOnlyClockProbeIssued,
              readOnlyClockProbeTask == nil else { return }
        readOnlyClockProbeIssued = true
        UserDefaults.standard.set(
            "waiting_for_notifications",
            forKey: "atria.diagnostic.readOnlyClock.status"
        )
        readOnlyClockProbeTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.readOnlyClockProbeTask = nil }
            let required = Set(self.requiredProductionHistoryNotifications)
            for _ in 0..<50 {
                guard self.readOnlyClockProbeRequested,
                      !Task.isCancelled else { return }
                if self.peripheral?.state == .connected,
                   self.txCharacteristic != nil,
                   required.isSubset(of: self.activeProprietaryNotifyUUIDs) {
                    break
                }
                try? await Task.sleep(for: .milliseconds(200))
            }
            guard self.readOnlyClockProbeRequested,
                  self.peripheral?.state == .connected,
                  self.txCharacteristic != nil,
                  required.isSubset(of: self.activeProprietaryNotifyUUIDs) else {
                UserDefaults.standard.set(
                    "notification_readiness_failed",
                    forKey: "atria.diagnostic.readOnlyClock.status"
                )
                return
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy
                    .postNotificationSettleInterval
            ))
            guard self.readOnlyClockProbeRequested,
                  !Task.isCancelled else { return }
            let sequence = self.cmdSeq
            guard self.sendCommand(
                Cmd.getClock,
                [0x00],
                mode: .withResponse
            ) else {
                UserDefaults.standard.set(
                    "write_rejected",
                    forKey: "atria.diagnostic.readOnlyClock.status"
                )
                return
            }
            self.readOnlyClockProbeSequence = sequence
            UserDefaults.standard.set(
                "requested",
                forKey: "atria.diagnostic.readOnlyClock.status"
            )
            AtriaDebugLog(
                "ATRIADBG read_only_clock status=requested reason=%@ command=0b payload=00 sequence=%d mutation=0",
                reason,
                Int(sequence)
            )
        }
    }

    /// Opens the durable admission incarnation before the first production
    /// bootstrap command. The physical 22 response owns clock authority; the
    /// optional v7 GET_CLOCK read is transport evidence only.
    private func beginProductionHistoricalAdmissionAttempt(
        generation: UInt64
    ) -> Bool {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation,
              let peripheralIdentifier = peripheral?.identifier.uuidString,
              let ledger = historicalAdmissionLedger else { return false }
        if let attempt = historicalAdmissionAttempt {
            return attempt.strapIdentifier == peripheralIdentifier
        }
        do {
            historicalAdmissionAttempt = try ledger.beginAttempt(
                strapIdentifier: peripheralIdentifier
            )
            return true
        } catch {
            historicalAdmissionFailed = true
            AtriaDebugLog("ATRIADBG historyAdmission status=begin_failed generation=%llu error=%@ action=retain_gap_no_command",
                          generation,
                          String(describing: error))
            return false
        }
    }

    /// Executes the mandatory first leg of the physically proven production
    /// bootstrap. Only an explicit authentication/encryption callback permits
    /// one retry; timeout, disconnect, and generic failure remain terminal for
    /// this generation. A successful WR without the exact echoed response is
    /// not enough to authorize 16/00.
    private func observeProductionHistoryCursorRange(
        generation: UInt64
    ) async -> ProductionHistoryRangeResult {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else {
            return .failure(.failed)
        }
        var retriesAlreadyIssued = 0
        while true {
            pendingHistoryDataRangeCommandSequence = nil
            pendingHistoryDataRangeWriteCompletedAtUnix = nil
            pendingHistoryDataRangeRequestedAtUnix = Date().timeIntervalSince1970
            acceptedHistoryDataRange = nil
            acceptedHistoryDataRangeResponseAtUnix = nil
            acceptedHistoryDataRangeResponseUptime = nil
            lastProprietaryWriteCompletion = nil
            guard sendCommand(Cmd.getDataRange, [0x00], mode: .withResponse),
                  let expected = writeCompletionLedger.pending.first,
                  expected.command == Cmd.getDataRange,
                  expected.payload == [0x00] else { return .failure(.rejected) }
            pendingHistoryDataRangeCommandSequence = expected.sequence
            AtriaDebugLog("ATRIADBG historyRange status=requested generation=%llu sequence=%d payload=00 attempt=%d mutation=0",
                          generation,
                          Int(expected.sequence),
                          retriesAlreadyIssued + 1)

            let writePollAttempts = max(
                1,
                Int(ceil(
                    AtriaWhoop4ProductionHistoryBootstrapPolicy
                        .rangeWriteConfirmationTimeout
                        / AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
                ))
            )
            var writeResult: AwaitedHistoryWriteResult = .timedOut
            for _ in 0..<writePollAttempts {
                if let completion = lastProprietaryWriteCompletion,
                   completion.generation == generation,
                   completion.entry == expected {
                    let classified = AtriaBLEReadOnlyHistoryCapturePolicy
                        .classifyWriteCompletion(
                            succeeded: completion.succeeded,
                            errorDomain: completion.errorDomain,
                            errorCode: completion.errorCode
                        )
                    switch classified {
                    case .confirmed: writeResult = .confirmed
                    case .securityRequired: writeResult = .securityRequired
                    case .failed: writeResult = .failed
                    case .timedOut: writeResult = .timedOut
                    case .interrupted: writeResult = .failed
                    }
                    break
                }
                try? await Task.sleep(for: .seconds(
                    AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
                ))
                guard !Task.isCancelled,
                      offlineHistoricalSyncInProgress,
                      offlineHistoricalSyncGeneration == generation else {
                    return .failure(.failed)
                }
            }

            if writeResult == .securityRequired,
               retriesAlreadyIssued == 0 {
                retriesAlreadyIssued = 1
                AtriaDebugLog("ATRIADBG historyRange status=security_required generation=%llu action=bounded_pairing_settle_then_single_retry",
                              generation)
                try? await Task.sleep(for: .seconds(
                    AtriaBLEReadOnlyHistoryCapturePolicy.pairingSettle
                ))
                guard !Task.isCancelled,
                      offlineHistoricalSyncInProgress,
                      offlineHistoricalSyncGeneration == generation,
                      peripheral?.state == .connected else {
                    return .failure(.failed)
                }
                continue
            }
            guard writeResult == .confirmed else { return .failure(writeResult) }

            for _ in 0..<AtriaBLEHistoryWriteConfirmationPolicy.maximumPollAttempts {
                if let observed = acceptedHistoryDataRange,
                   observed.requestSequenceEcho == expected.sequence,
                   let responseWall = acceptedHistoryDataRangeResponseAtUnix,
                   let responseUptime = acceptedHistoryDataRangeResponseUptime,
                   let clock = AtriaWhoop4ProductionHistoryBootstrapPolicy
                    .validatedClockAuthority(
                        range: observed,
                        responseWallUnix: responseWall
                    ) {
                    // Keep the v1 durable transport-authority field names for
                    // on-disk compatibility. Their source is now the matched
                    // GET_DATA_RANGE response, never GET_CLOCK.
                    pendingHistoryClockCommandSequence = expected.sequence
                    pendingHistoryClockCommandRequestedAtUnix =
                        pendingHistoryDataRangeRequestedAtUnix
                    pendingHistoryClockWriteCompletedAtUnix =
                        pendingHistoryDataRangeWriteCompletedAtUnix
                    acceptedHistoryClockResponseSequence = expected.sequence
                    acceptedHistoryClockDeviceUnix = clock.deviceUnix
                    acceptedHistoryClockWallUnix = clock.wallUnix
                    acceptedHistoryClockResponseAtUnix = responseWall
                    historyClockRef = .init(device: clock.deviceUnix,
                                            wall: clock.wallUnix)
                    productionFullDrainClockAuthorityEnabled = true
                    AtriaDebugLog("ATRIADBG historyRange status=matched_clock_authority generation=%llu sequence=%d pending=%u device_unix=%u drift_s=%d source=2200",
                                  generation,
                                  Int(expected.sequence),
                                  observed.pendingRecords,
                                  clock.deviceUnix,
                                  clock.driftSeconds)
                    _ = responseUptime
                    return .success(observed)
                }
                try? await Task.sleep(for: .seconds(
                    AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
                ))
                guard !Task.isCancelled,
                      offlineHistoricalSyncInProgress,
                      offlineHistoricalSyncGeneration == generation else {
                    return .failure(.failed)
                }
            }
            AtriaDebugLog("ATRIADBG historyRange status=matched_response_timeout generation=%llu sequence=%d write=1 action=retain_gap_no_1600",
                          generation,
                          Int(expected.sequence))
            return .failure(.timedOut)
        }
    }

    /// Performs the one user-approved RTC synchronization immediately before a
    /// bounded historical repair. The payload is the WHOOP 4 clock form
    /// `<unix seconds: u32 LE><subseconds: u32 LE>`. This method is reachable
    /// only through the explicit launch approval flag; automatic range-loss
    /// recovery always leaves `historyClockSyncEnabled` false.
    private func performUserApprovedHistoryClockSync(
        generation: UInt64
    ) async -> AwaitedHistoryWriteResult {
        guard historyClockSyncEnabled else { return .confirmed }
        UserDefaults.standard.set("requested",
                                  forKey: "atria.offlineSync.clockRepairStatus.v1")
        UserDefaults.standard.set(Date().timeIntervalSince1970,
                                  forKey: "atria.offlineSync.clockRepairAt.v1")
        let unixSeconds = UInt32(clamping: Int(Date().timeIntervalSince1970))
        let payload = withUnsafeBytes(of: unixSeconds.littleEndian) {
            Array($0)
        } + [0, 0, 0, 0]
        AtriaDebugLog("ATRIADBG historyClock status=user_approved_set_clock_requested generation=%llu unix=%u payload=%@ action=await_write_confirmation",
                      generation,
                      unixSeconds,
                      Self.hex(payload))
        let result = await sendHistoryCommandAwaitingWriteConfirmation(
            command: Cmd.setClock,
            payload: payload,
            generation: generation
        )
        guard result == .confirmed else {
            UserDefaults.standard.set("write_\(String(describing: result))",
                                      forKey: "atria.offlineSync.clockRepairStatus.v1")
            AtriaDebugLog("ATRIADBG historyClock status=user_approved_set_clock_failed generation=%llu result=%@ action=retain_gap_no_history_command",
                          generation,
                          String(describing: result))
            return result
        }
        // A bounded settling interval prevents the subsequent cursor request
        // from racing the strap's RTC update. No UI work or live subscription
        // runs on this task while it waits.
        try? await Task.sleep(for: .milliseconds(800))
        guard !Task.isCancelled,
              offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation else {
            return .failed
        }
        historyClockSyncEnabled = false
        UserDefaults.standard.set("write_confirmed",
                                  forKey: "atria.offlineSync.clockRepairStatus.v1")
        AtriaDebugLog("ATRIADBG historyClock status=user_approved_set_clock_confirmed generation=%llu settle_ms=800 action=continue_matched_cursor_then_1600",
                      generation)
        return .confirmed
    }

    /// Sends the one response-proven GET_CLOCK form after 22/00 has already
    /// established clock authority. This command is transport-priming evidence
    /// only: it cannot replace or mutate the range-derived clock reference.
    private func performProductionHistoryReadPreflight(
        generation: UInt64
    ) async -> AwaitedHistoryWriteResult {
        guard offlineHistoricalSyncInProgress,
              offlineHistoricalSyncGeneration == generation,
              productionHistoryReadPreflightRequired,
              historyReadPreflightGate.identity == nil else {
            return .rejected
        }
        lastProprietaryWriteCompletion = nil
        guard sendCommand(Cmd.getClock, [0x00], mode: .withResponse),
              let expected = writeCompletionLedger.pending.first,
              expected.command == Cmd.getClock,
              expected.payload == [0x00] else { return .rejected }
        let identity = AtriaWhoop4HistoryReadPreflightGate.Identity(
            generation: generation,
            commandSequence: expected.sequence
        )
        guard historyReadPreflightGate.arm(identity) else { return .rejected }
        AtriaDebugLog("ATRIADBG historyPreflight status=requested generation=%llu command=0b payload=00 sequence=%d mutation=0 attempt=1",
                      generation,
                      Int(expected.sequence))

        let deadline = Date().addingTimeInterval(2)
        while Date() < deadline {
            if acceptedHistoryReadPreflightIdentity == identity {
                try? await Task.sleep(for: .milliseconds(800))
                guard !Task.isCancelled,
                      offlineHistoricalSyncInProgress,
                      offlineHistoricalSyncGeneration == generation,
                      acceptedHistoryReadPreflightIdentity == identity else {
                    return .failed
                }
                AtriaDebugLog("ATRIADBG historyPreflight status=settled generation=%llu command=0b sequence=%d settle_ms=800 authority=transport_only clock_source=2200 action=allow_1600",
                              generation,
                              Int(expected.sequence))
                return .confirmed
            }
            if historyReadPreflightGate.identity == nil {
                return .failed
            }
            try? await Task.sleep(for: .seconds(
                AtriaBLEHistoryWriteConfirmationPolicy.pollInterval
            ))
            guard !Task.isCancelled,
                  offlineHistoricalSyncInProgress,
                  offlineHistoricalSyncGeneration == generation else {
                return .failed
            }
        }
        _ = historyReadPreflightGate.timeout(identity)
        AtriaDebugLog("ATRIADBG historyPreflight status=timeout generation=%llu command=0b sequence=%d action=withhold_1600_no_retry",
                      generation,
                      Int(expected.sequence))
        return .timedOut
    }

    private func handleProductionHistoryReadPreflightResponse(
        _ payload: [UInt8],
        generation: UInt64
    ) {
        switch historyReadPreflightGate.receiveCommandResponse(
            payload,
            generation: generation
        ) {
        case .ignored, .awaitingLogicalResponse:
            return
        case .awaitingGATTConfirmation(let identity):
            noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: "history_read_preflight_logical_buffered"
            )
            AtriaDebugLog("ATRIADBG historyPreflight status=logical_response_buffered generation=%llu command=0b request_seq_echo=%d authority=transport_only action=await_matching_gatt_callback payload=%@",
                          generation,
                          Int(identity.commandSequence),
                          Self.hex(payload))
        case .accepted(let identity):
            acceptedHistoryReadPreflightIdentity = identity
            noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: "history_read_preflight_response"
            )
            AtriaDebugLog("ATRIADBG historyPreflight status=logical_response generation=%llu command=0b request_seq_echo=%d authority=transport_only clock_source=2200 payload=%@",
                          generation,
                          Int(identity.commandSequence),
                          Self.hex(payload))
        case .failed(let identity):
            AtriaDebugLog("ATRIADBG historyPreflight status=logical_rejected generation=%llu command=0b request_seq_echo=%d action=withhold_1600_no_retry payload=%@",
                          generation,
                          Int(identity.commandSequence),
                          Self.hex(payload))
        }
    }

    private func sendHistoryDataRange(index: Int, data: [UInt8]) {
        historyDataRangePendingRequests.append((index: index, data: data))
        sendCommand(0x22, data, mode: probeCommandMode)
    }

    func stopRealtime() {
        realtimeRetry?.cancel()
        realtimeRestartTask?.cancel()
        r10ArmRetryTask?.cancel()
        stopR10LivenessWatchdog(reason: "stop_realtime")
        stopProtocolHeartbeat()
        realtimeArmed = false
        sendCommand(Cmd.toggleRealtimeHR, [0x00], mode: .withoutResponse)
        realtimeOn = false
    }

    nonisolated static func canFinishRealtimeRestart(
        taskCancelled: Bool,
        realtimeArmed: Bool,
        samePeripheral: Bool,
        sameConnectionEpoch: Bool,
        connected: Bool
    ) -> Bool {
        !taskCancelled
            && realtimeArmed
            && samePeripheral
            && sameConnectionEpoch
            && connected
    }

    private func beginRealtimePacketBatch() {
        realtimePacketBatchDepth += 1
    }

    private func endRealtimePacketBatch(
        callbackSource: AtriaBLECallbackEpochFence.Source
    ) {
        guard realtimePacketBatchDepth > 0 else { return }
        realtimePacketBatchDepth -= 1
        guard realtimePacketBatchDepth == 0 else { return }
        defer {
            realtimeBatchPendingConsistencyAt = nil
            realtimeBatchPendingRRContinuityAt = nil
            realtimeBatchPendingAutoCaptureAt = nil
            realtimeBatchPendingRestart = nil
            realtimeBatchPendingHistorySweepUnix = nil
        }
        // In particular, a retired realtime batch must not send a zero-RR
        // restart or history sweep command over a newly connected object.
        guard bleCallbackEpochFence.owns(source: callbackSource) else { return }
        if let now = realtimeBatchPendingConsistencyAt {
            compareHRChannelsIfPossible(now: now, source: "0x28")
        }
        if let now = realtimeBatchPendingRRContinuityAt {
            publishRRContinuityQuality(now: now)
        }
        if let now = realtimeBatchPendingAutoCaptureAt {
            evaluateAdaptiveAutoCapture(now: now)
        }
        if let restart = realtimeBatchPendingRestart {
            maybeRestartRealtimeAfterZeroRR(now: restart.now, rrnum: restart.rrnum)
        }
        if let realtimeUnix = realtimeBatchPendingHistorySweepUnix, historyRecentSweepEnabled {
            maybeSendRecentHistorySweep(realtimeUnix: realtimeUnix)
        }
    }

    private func maybeRestartRealtimeAfterZeroRR(now: Date, rrnum: Int) {
        let restartThreshold = realtimeRestartAfterZeroRRSeconds
        let reassertThreshold = realtimeReassertStartAfterZeroRRSeconds
        let threshold = restartThreshold > 0 ? restartThreshold : reassertThreshold
        guard threshold > 0, realtimeArmed else { return }
        if rrnum > 0 {
            lastRRBearingRealtimeFrameAt = now
            return
        }
        guard let lastRRBearingRealtimeFrameAt else { return }
        let zeroRRSeconds = now.timeIntervalSince(lastRRBearingRealtimeFrameAt)
        guard zeroRRSeconds >= threshold else { return }
        if let lastRealtimeRestartAt,
           now.timeIntervalSince(lastRealtimeRestartAt) < threshold {
            return
        }
        guard realtimeRestartTask == nil else { return }
        lastRealtimeRestartAt = now
        if restartThreshold > 0 {
            AtriaDebugLog("ATRIADBG realtimeRestart reason=zero_rr gap_s=%.1f threshold_s=%.1f",
                  zeroRRSeconds, restartThreshold)
        } else {
            AtriaDebugLog("ATRIADBG realtimeReassert reason=zero_rr gap_s=%.1f threshold_s=%.1f",
                  zeroRRSeconds, reassertThreshold)
        }
        let restartPeripheralID = peripheral?.identifier
        let restartConnectionEpoch = bleCallbackEpochFence.epoch
        realtimeRestartTask = Task { @MainActor in
            defer { realtimeRestartTask = nil }
            if restartThreshold > 0 {
                sendCommand(Cmd.toggleRealtimeHR, [0x00], mode: .withoutResponse)
                do {
                    try await Task.sleep(for: .milliseconds(500))
                } catch {
                    return
                }
            }
            guard Self.canFinishRealtimeRestart(
                taskCancelled: Task.isCancelled,
                realtimeArmed: realtimeArmed,
                samePeripheral: peripheral?.identifier == restartPeripheralID,
                sameConnectionEpoch: bleCallbackEpochFence.epoch == restartConnectionEpoch,
                connected: status == .connected && peripheral?.state == .connected
            ) else { return }
            sendCommand(Cmd.toggleRealtimeHR, [0x01], mode: .withoutResponse)
        }
    }

    private func shouldTrackRRAvailability(source: String, rrCount: Int) -> Bool {
        if rrCount > 0 { return true }
        return source == "0x28" && decodedStandardRRValues == 0
    }

    private func appendRRContinuityObservation(now: Date, rrCount: Int, source: String) -> Bool {
        guard shouldTrackRRAvailability(source: source, rrCount: rrCount) else { return false }
        if shouldSkipRealtimeZeroRRTracking(now: now,
                                           rrCount: rrCount,
                                           source: source,
                                           lastTrackedAt: &lastRealtimeZeroRRQualityUpdateAt) {
            return false
        }
        rrContinuityWindow.append((t: now, hasRR: rrCount > 0, source: source))
        if isRecording {
            captureRRQualityWindow.append((t: now, hasRR: rrCount > 0, source: source))
        }
        return true
    }

    private func publishRRContinuityQuality(now: Date) {
        if !isRecording, let lastRRContinuityPublishAt {
            let minimumInterval = foregroundInteractiveMode
                ? Self.liveRRContinuityPublishMinimumInterval
                : Self.backgroundRRContinuityPublishMinimumInterval
            if now.timeIntervalSince(lastRRContinuityPublishAt) < minimumInterval * effectiveThermalCadenceMultiplier {
                return
            }
        }
        lastRRContinuityPublishAt = now
        let continuity = pruneRRWindow(&rrContinuityWindow,
                                       head: &rrContinuityWindowHead,
                                       now: now,
                                       maxAge: 300)

        let frames = continuity.frames
        let rrFrames = continuity.rrFrames
        let fraction = continuity.fraction
        let span = continuity.span
        let frameMaxGap = continuity.frameMaxGap
        let beatMaxGap = continuity.firstTimestamp.flatMap { maxRRBeatGap(since: $0, now: now) }
        let maxGap = beatMaxGap ?? frameMaxGap
        let sourceLabel = continuity.sourceLabel
        let state: String
        if frames < 45 || span < 45 {
            state = "learning"
        } else if fraction >= 0.90 && maxGap <= HRVSnapshot.maxReadyRRGapSeconds {
            state = "ready"
        } else {
            state = "poor_contact"
        }

        assignIfChanged(\.rrContinuityFrames, frames)
        assignIfChanged(\.rrContinuityRRFrames, rrFrames)
        assignIfChanged(\.rrContinuityFraction, fraction)
        assignIfChanged(\.rrContinuityMaxGapSeconds, maxGap)
        assignIfChanged(\.rrContinuityState, state)
        assignIfChanged(\.rrContinuityDetail,
                        String(format: "%@ · %@ · RR %.0f%% · gap %.1fs · %d/%d frames",
                               state.replacingOccurrences(of: "_", with: " "),
                               sourceLabel, fraction * 100, maxGap, rrFrames, frames))

        let shouldLog: Bool
        if let lastRRContinuityLogAt {
            let logState = "\(state)-\(sourceLabel)"
            shouldLog = logState != lastRRContinuityLogState || now.timeIntervalSince(lastRRContinuityLogAt) >= 30
        } else {
            shouldLog = true
        }
        if shouldLog {
            lastRRContinuityLogAt = now
            lastRRContinuityLogState = "\(state)-\(sourceLabel)"
            AtriaDebugLog("ATRIADBG rr_quality source=%@ state=%@ fraction=%.3f rr_frames=%d total_frames=%d max_rr_gap_s=%.1f frame_max_rr_gap_s=%.1f beat_timeline=%d window_s=%.0f hrv_state=%@ rr_source_2a37_values=%d rr_source_0x28_decoded_values=%d rr_source_0x28_used_values=%d",
                  sourceLabel, state, fraction, rrFrames, frames,
                  maxGap, frameMaxGap, beatMaxGap == nil ? 0 : 1, min(span, 300),
                  hrvSnapshot?.isReady == true ? "ready" : "learning",
                  decodedStandardRRValues, decodedRealtimeRRValues, usedRealtimeRRValues)
        }
        guard isRecording else { return }
        let capture = pruneRRWindow(&captureRRQualityWindow,
                                    head: &captureRRQualityWindowHead,
                                    now: now,
                                    maxAge: 300,
                                    minimumTime: captureStart)
        let captureFrames = capture.frames
        let captureRRFrames = capture.rrFrames
        let captureFraction = capture.fraction
        let captureFrameMaxGap = capture.frameMaxGap
        let captureBeatMaxGap = maxRRBeatGap(since: captureCleanWindowStart, now: now)
        let captureMaxGap = captureBeatMaxGap ?? captureFrameMaxGap
        let captureSpan = capture.span
        if captureElapsedSeconds >= 45,
           captureFrames >= 45,
           (captureFraction < 0.90 || captureMaxGap > HRVSnapshot.maxReadyRRGapSeconds) {
            let reason = captureFraction < 0.90 ? "rr_fraction_below_0.90" : "rr_gap_over_3s"
            resetRecordingForRRQuality(reason: reason,
                                       fraction: captureFraction,
                                       rrFrames: captureRRFrames,
                                       totalFrames: captureFrames,
                                       maxGap: captureMaxGap,
                                       windowSeconds: captureSpan,
                                       now: now,
                                       source: sourceLabel == "2a37" ? "0x2A37" : "0x28",
                                       rrCount: captureRRFrames)
        }
    }

    private func updateRRContinuityQuality(now: Date, rrCount: Int, source: String) {
        guard appendRRContinuityObservation(now: now, rrCount: rrCount, source: source) else { return }
        if realtimePacketBatchDepth > 0, source == "0x28" {
            realtimeBatchPendingRRContinuityAt = now
            return
        }
        publishRRContinuityQuality(now: now)
    }

    private func maxRRBeatGap(since start: Date, now: Date) -> TimeInterval? {
        // `rrArchive` and `recentRRBeatTimes` deliberately roll with the saved
        // session. `rrBuffer` is the non-persisted physiological quality window,
        // so it is the only timeline that can legitimately bridge a storage-only
        // three-hour rollover. Prefer it only when it actually covers the quality
        // window start; otherwise retain the session-local fallbacks below.
        let continuousWindow = currentRRBufferWindow()
        if Self.shouldUseContinuousRRBuffer(
            continuityStart: start,
            firstBufferedBeat: continuousWindow.first?.t
        ) {
            return Self.maxRRBeatGap(
                inOrderedBeatTimes: continuousWindow.lazy.map(\.t),
                since: start,
                now: now
            )
        }
        if let earliestRecentBeat = recentRRBeatTimes.first, start >= earliestRecentBeat {
            return maxRRBeatGap(inRecentBeatTimesSince: start, now: now)
        }
        return maxRRBeatGap(inArchiveSince: start, now: now)
    }

    nonisolated static func shouldUseContinuousRRBuffer(
        continuityStart: Date,
        firstBufferedBeat: Date?
    ) -> Bool {
        guard let firstBufferedBeat else { return false }
        return firstBufferedBeat <= continuityStart
    }

    nonisolated static func maxRRBeatGap<C: Collection>(
        inOrderedBeatTimes beatTimes: C,
        since start: Date,
        now: Date
    ) -> TimeInterval? where C.Element == Date {
        var iterator = beatTimes.makeIterator()
        var firstInWindow: Date?
        while let beat = iterator.next() {
            guard beat <= now else { break }
            if beat >= start {
                firstInWindow = beat
                break
            }
        }
        guard let firstInWindow else { return nil }

        var maximum = firstInWindow.timeIntervalSince(start)
        var previous = firstInWindow
        while let beat = iterator.next() {
            guard beat <= now else { break }
            maximum = max(maximum, beat.timeIntervalSince(previous))
            previous = beat
        }
        return max(maximum, now.timeIntervalSince(previous))
    }

    private func maxRRBeatGap(inRecentBeatTimesSince start: Date, now: Date) -> TimeInterval? {
        Self.maxRRBeatGap(inOrderedBeatTimes: recentRRBeatTimes,
                          since: start,
                          now: now)
    }

    private func maxRRBeatGap(inArchiveSince start: Date, now: Date) -> TimeInterval? {
        Self.maxRRBeatGap(inOrderedBeatTimes: rrArchive.lazy.map(\.t),
                          since: start,
                          now: now)
    }

    /// Decode a proprietary frame; if it's REALTIME_DATA, pull RR intervals (HRV).
    private func handleProprietary(
        _ data: Data,
        sourceUUID: CBUUID,
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        let b = [UInt8](data)
        guard b.count >= 8, b[0] == 0xAA else { return }
        let len = Int(b[1]) | (Int(b[2]) << 8)
        guard b[3] == crc8([b[1], b[2]]), len + 4 <= b.count, len >= 5 else { return }
        let payload = Array(b[4..<len])
        let expectedCRC = crc32(payload)
        let actualCRC = UInt32(b[len])
            | (UInt32(b[len + 1]) << 8)
            | (UInt32(b[len + 2]) << 16)
            | (UInt32(b[len + 3]) << 24)
        guard expectedCRC == actualCRC else {
            protectedR10CRCRejectedFramesThisConnection += 1
            AtriaDebugLog("ATRIADBG frameReject reason=crc32_mismatch type=%02x len=%d expected=%08x actual=%08x full=%@",
                  payload.first ?? 0, b.count, expectedCRC, actualCRC, Self.hex(b))
            return
        }
        if readOnlyHistoryCaptureActive,
           payload.first == Packet.metadata || payload.first == Packet.historical {
            handleReadOnlyHistoricalPayload(payload, sourceUUID: sourceUUID)
            return
        }
        switch payload.first {
        case 0x24:
            handleCommandResponsePayload(payload, historyPhase: historyPhase)
            handleUnknownProtocolPayload(payload,
                                         fullFrame: b,
                                         sourceUUID: sourceUUID,
                                         historyTransportActive: historyPhase.isActive)
            return
        case Packet.metadata:
            handleHistoryMetadata(payload, historyPhase: historyPhase)
            return
        case Packet.historical:
            handleHistoricalData(payload, historyPhase: historyPhase)
            return
        default:
            break
        }
        guard payload.first == Packet.realtime, payload.count >= 10 else {
            handleUnknownProtocolPayload(payload,
                                         fullFrame: b,
                                         sourceUUID: sourceUUID,
                                         historyTransportActive: historyPhase.isActive)
            return
        }
        // payload: [type, seq, cmd, 5-byte header, HR, rrnum, RR(u16le)...]
        let realtimeUnix = payload.count >= 6 ? Self.u32le(payload, 2) : 0
        if realtimeUnix > 0 {
            lastRealtimeUnix = realtimeUnix
        }
        let hr = Int(payload[8])
        lastRealtimeHR = (hr, Date())
        compareHRChannelsIfPossible(now: lastRealtimeHR?.t ?? Date(), source: "0x28")
        let rrnum = Int(payload[9])
        let rrByteCount = min(max(0, payload.count - 10), rrnum * 2)
        let rrBytes = Array(payload[10..<(10 + rrByteCount)])
        let payloadTail = Array(payload.dropFirst(10 + rrByteCount))
        if verboseBLEFrameLogging {
            AtriaDebugLog("ATRIADBG realtimeFrame hrByte=%d rrnum=%d rrBytes=%@ payloadTail=%@ payload=%@ full=%@",
                  hr, rrnum, Self.hex(rrBytes), Self.hex(payloadTail), Self.hex(payload), Self.hex(b))
        }
        let frameTime = Date()
        let standardRecentlyActive = lastStandardRRAt.map { frameTime.timeIntervalSince($0) <= 2.5 } ?? false
        let useForMetrics = Self.shouldUseProprietaryRealtimeRRForMetrics(
            standardRecentlyActive: standardRecentlyActive
        )
        var decodedRR: [Int] = []
        var truncated = false
        for i in 0..<rrnum {
            let off = 10 + i * 2
            guard off + 1 < payload.count else {
                truncated = true
                break
            }
            let rr = Int(payload[off]) | (Int(payload[off + 1]) << 8)
            decodedRR.append(rr)
        }
        if !decodedRR.isEmpty {
            if useForMetrics {
                usedRealtimeRRValues += decodedRR.count
                for beat in Self.beatTimesEnding(at: frameTime, intervalsMS: decodedRR) {
                    addRR(Double(beat.rr),
                          at: beat.time,
                          source: "0x28",
                          opcode: "28",
                          expectedHR: nil,
                          provenance: .validatedProprietaryRealtime,
                          triggerRefresh: false)
                }
                requestDeferredHRVSnapshotRefreshIfNeeded(now: frameTime)
            } else if isRecording {
                recordUnvalidatedProprietaryRRResearch(decodedRR,
                                                       endingAt: frameTime,
                                                       opcode: "28")
            }
        }
        if useForMetrics {
            updateRRContinuityQuality(now: frameTime, rrCount: rrnum, source: "0x28")
            updateAdaptiveAutoCapture(now: frameTime, rrnum: rrnum, source: "0x28")
        }
        maybeRestartRealtimeAfterZeroRR(now: frameTime, rrnum: rrnum)
        maybeSendRecentHistorySweep(realtimeUnix: realtimeUnix)
        if !decodedRR.isEmpty || truncated {
            decodedRealtimeRRValues += decodedRR.count
            let values = decodedRR.map(String.init).joined(separator: ",")
            let impliedBPM = decodedRR.map { rr in
                rr > 0 ? String(format: "%.0f", 60000.0 / Double(rr)) : "inf"
            }.joined(separator: ",")
            let hrMismatch = decodedRR.filter { rr in
                guard rr > 0 else { return true }
                return abs((60000.0 / Double(rr)) - Double(hr)) > 30
            }.count
            if verboseBLEFrameLogging {
                AtriaDebugLog("ATRIADBG rr source=0x28 used=%d hr=%d rrnum=%d decoded=%d total_decoded=%d total_used=%d truncated=%d hr_mismatch=%d implied_bpm=%@ values=%@",
                      useForMetrics ? 1 : 0,
                      hr, rrnum, decodedRR.count, decodedRealtimeRRValues,
                      usedRealtimeRRValues,
                      truncated ? 1 : 0, hrMismatch, impliedBPM, values)
            }
        }
    }

    private func handleReadOnlyHistoricalPayload(
        _ payload: [UInt8],
        sourceUUID: CBUUID
    ) {
        guard readOnlyHistoryCaptureActive else { return }
        if sacrificialFastDrainActive {
            handleSacrificialFastDrainPayload(
                payload,
                sourceUUID: sourceUUID
            )
            return
        }
        let generation = readOnlyHistoryCaptureGeneration
        if payload.first == Packet.historical {
            guard (readOnlyHistoryCaptureStore?.frameCount ?? 0)
                    < AtriaBLEReadOnlyHistoryCapturePolicy.maximumCapturedFrames else {
                finishReadOnlyHistoryCapture(generation: generation,
                                              reason: "frame_limit")
                return
            }
            let decoded = AtriaWhoop4HistoricalRecordDecoder.decode(payload)
            let decodedTimestamp = decoded.decodedRecord?.timestampSeconds
            let inRequestedWindow: Bool?
            if let decodedTimestamp,
               let startUnix = readOnlyExactRangeStartUnix,
               let endUnix = readOnlyExactRangeEndUnix {
                readOnlyExactRangeDecodedRows += 1
                let accepted =
                    AtriaBLEReadOnlyExactRangeCapturePolicy.contains(
                        timestamp: decodedTimestamp,
                        startUnix: startUnix,
                        endUnix: endUnix
                    )
                if accepted {
                    readOnlyExactRangeInWindowRows += 1
                }
                inRequestedWindow = accepted
            } else {
                inRequestedWindow = nil
            }
            do {
                try readOnlyHistoryCaptureStore?.append(
                    event: "historical_frame",
                    payload: payload,
                    fields: [
                        "source_uuid": sourceUUID.uuidString,
                        "decoded_timestamp_unix":
                            decodedTimestamp.map(Int.init) ?? 0,
                        "in_requested_window":
                            inRequestedWindow ?? false,
                        "requested_window_applicable":
                            inRequestedWindow != nil,
                    ]
                )
            } catch {
                AtriaDebugLog("ATRIADBG readOnlyHistory status=store_write_failed generation=%llu error=%@ action=abort_no_ack",
                              generation,
                              String(describing: error))
                finishReadOnlyHistoryCapture(generation: generation,
                                              reason: "store_write_failed")
                return
            }
            if readOnlyExactRangeCaptureRequested,
               inRequestedWindow == false {
                AtriaDebugLog("ATRIADBG readOnlyHistory status=exact_range_rejected generation=%llu decoded_unix=%u requested_start=%u requested_end=%u action=abort_no_ack_preserve_gap",
                              generation,
                              decodedTimestamp ?? 0,
                              readOnlyExactRangeStartUnix ?? 0,
                              readOnlyExactRangeEndUnix ?? 0)
                finishReadOnlyHistoryCapture(
                    generation: generation,
                    reason: "exact_range_out_of_window_record"
                )
                return
            }
            let frames = readOnlyHistoryCaptureStore?.frameCount ?? 0
            if frames == 1 || frames.isMultiple(of: 10) {
                AtriaDebugLog("ATRIADBG readOnlyHistory status=frame_captured generation=%llu frames=%d source=%@ ack=0",
                              generation,
                              frames,
                              sourceUUID.uuidString)
            }
            if frames >= AtriaBLEReadOnlyHistoryCapturePolicy.maximumCapturedFrames {
                finishReadOnlyHistoryCapture(generation: generation,
                                              reason: "frame_limit")
            }
            return
        }
        do {
            try readOnlyHistoryCaptureStore?.append(
                event: "metadata",
                payload: payload,
                fields: ["source_uuid": sourceUUID.uuidString]
            )
        } catch {
            finishReadOnlyHistoryCapture(generation: generation,
                                          reason: "metadata_store_write_failed")
            return
        }
        guard let marker = try? AtriaWhoop4HistoryMetadata.parse(payload) else { return }
        switch marker {
        case .historyStart(let sequence):
            readOnlyHistoryStarted = true
            AtriaDebugLog("ATRIADBG readOnlyHistory status=history_start generation=%llu sequence=%d source=%@",
                          generation,
                          Int(sequence),
                          sourceUUID.uuidString)
        case .historyComplete, .historyEnd:
            finishReadOnlyHistoryCapture(generation: generation,
                                          reason: "terminal_marker")
        }
    }

    private func handleSacrificialFastDrainPayload(
        _ payload: [UInt8],
        sourceUUID: CBUUID
    ) {
        guard sacrificialFastDrainActive,
              sacrificialFastDrainFailedReason == nil else { return }
        let generation = readOnlyHistoryCaptureGeneration
        if payload.first == Packet.historical {
            sacrificialFastDrainReceivedRecords += 1
            let records = sacrificialFastDrainReceivedRecords
            let decoded =
                AtriaWhoop4HistoricalRecordDecoder.decode(payload)
                    .decodedRecord
            if let timestamp = decoded?.timestampSeconds,
               let evidenceStart = sacrificialFastDrainEvidenceStartUnix,
               let evidenceEnd = sacrificialFastDrainEvidenceEndUnix,
               AtriaBLEReadOnlyExactRangeCapturePolicy.contains(
                timestamp: timestamp,
                startUnix: evidenceStart,
                endUnix: evidenceEnd
               ) {
                sacrificialFastDrainEvidenceRecords += 1
                do {
                    try readOnlyHistoryCaptureStore?.append(
                        event: "evidence_historical_frame",
                        payload: payload,
                        fields: [
                            "decoded_timestamp_unix": timestamp,
                            "evidence_start_unix": evidenceStart,
                            "evidence_end_unix": evidenceEnd,
                            "evidence_record_index":
                                sacrificialFastDrainEvidenceRecords,
                            "source_uuid": sourceUUID.uuidString,
                        ]
                    )
                } catch {
                    sacrificialFastDrainFailedReason =
                        "evidence_store_write_failed"
                    return
                }
            }
            if records == 1 || records.isMultiple(of: 250) {
                try? readOnlyHistoryCaptureStore?.append(
                    event: "discard_progress",
                    fields: [
                        "historical_records_discarded": records,
                        "acknowledged_chunks":
                            sacrificialFastDrainACKCount,
                        "source_uuid": sourceUUID.uuidString,
                    ]
                )
                AtriaDebugLog(
                    "ATRIADBG sacrificial_fast_drain status=streaming generation=%llu records=%d acks=%d",
                    generation,
                    records,
                    sacrificialFastDrainACKCount
                )
            }
            return
        }

        guard payload.first == Packet.metadata,
              var policySession = sacrificialFastDrainSession else {
            sacrificialFastDrainFailedReason =
                "unexpected_non_history_payload"
            return
        }
        if let marker = try? AtriaWhoop4HistoryMetadata.parse(payload),
           case .historyEnd(_, _, let token) = marker,
           sacrificialFastDrainAcknowledgedTokens.contains(Data(token.bytes)) {
            try? readOnlyHistoryCaptureStore?.append(
                event: "duplicate_acknowledged_history_end_ignored",
                fields: ["token": Self.hex(token.bytes)]
            )
            return
        }
        if sacrificialFastDrainACKInFlight,
           let marker = try? AtriaWhoop4HistoryMetadata.parse(payload),
           case .historyEnd(_, _, let token) = marker {
            if token.bytes == sacrificialFastDrainPendingACKToken {
                try? readOnlyHistoryCaptureStore?.append(
                    event: "duplicate_history_end_while_ack_inflight",
                    fields: ["token": Self.hex(token.bytes)]
                )
                return
            }
            if sacrificialFastDrainStopAfterCurrentACK {
                try? readOnlyHistoryCaptureStore?.append(
                    event: "history_end_not_acked_after_slice_deadline",
                    fields: [
                        "token": Self.hex(token.bytes),
                        "ack_in_flight": true,
                        "slice_attempt":
                            sacrificialFastDrainSliceAttempt,
                    ]
                )
                return
            }
            guard sacrificialFastDrainDeferredMetadata == nil else {
                sacrificialFastDrainFailedReason =
                    "multiple_deferred_history_ends"
                return
            }
            sacrificialFastDrainDeferredMetadata = (
                payload: payload,
                sourceUUID: sourceUUID
            )
            try? readOnlyHistoryCaptureStore?.append(
                event: "history_end_deferred_until_prior_ack_completion",
                fields: ["token": Self.hex(token.bytes)]
            )
            return
        }
        if sacrificialFastDrainStopAfterCurrentACK,
           let marker = try? AtriaWhoop4HistoryMetadata.parse(payload),
           case .historyEnd(_, _, let token) = marker {
            try? readOnlyHistoryCaptureStore?.append(
                event: "history_end_not_acked_after_slice_deadline",
                fields: [
                    "token": Self.hex(token.bytes),
                    "ack_in_flight": false,
                    "slice_attempt":
                        sacrificialFastDrainSliceAttempt,
                ]
            )
            return
        }
        do {
            try policySession.recordMetadata(payload)
            sacrificialFastDrainSession = policySession
        } catch {
            sacrificialFastDrainFailedReason =
                "metadata_policy_\(error)"
            AtriaDebugLog(
                "ATRIADBG sacrificial_fast_drain status=failed reason=metadata_policy error=%@ payload=%@",
                String(describing: error),
                Self.hex(payload)
            )
            return
        }
        let marker: AtriaWhoop4HistoryMetadata.Marker
        do {
            marker = try AtriaWhoop4HistoryMetadata.parse(payload)
        } catch {
            sacrificialFastDrainFailedReason = "metadata_parse_failed"
            return
        }
        switch marker {
        case .historyStart(let sequence):
            try? readOnlyHistoryCaptureStore?.append(
                event: "history_start",
                fields: ["sequence": sequence]
            )
        case .historyComplete(let sequence):
            sacrificialFastDrainHistoryComplete = true
            try? readOnlyHistoryCaptureStore?.append(
                event: "history_complete",
                fields: [
                    "sequence": sequence,
                    "historical_records_discarded":
                        sacrificialFastDrainReceivedRecords,
                    "acknowledged_chunks":
                        sacrificialFastDrainACKCount,
                ]
            )
        case .historyEnd(let sequence, _, let token):
            guard !sacrificialFastDrainACKInFlight else {
                sacrificialFastDrainFailedReason =
                    "overlapping_history_end"
                return
            }
            let tokenBytes = token.bytes
            sacrificialFastDrainPendingACKToken = tokenBytes
            sacrificialFastDrainACKInFlight = true
            let command =
                AtriaWhoop4SacrificialFastDrainPolicy.Command(
                    opcode: Cmd.historicalDataResult,
                    payload: token.acknowledgementPayload
                )
            Task { @MainActor [weak self] in
                guard let self else { return }
                let result =
                    await self.sendSacrificialFastDrainCommand(
                        command,
                        generation: generation
                    )
                guard self.sacrificialFastDrainActive,
                      self.readOnlyHistoryCaptureGeneration
                        == generation else { return }
                self.sacrificialFastDrainACKInFlight = false
                self.sacrificialFastDrainPendingACKToken = nil
                guard result == .confirmed else {
                    self.sacrificialFastDrainFailedReason =
                        "ack_write_\(result)"
                    return
                }
                self.sacrificialFastDrainACKCount += 1
                self.sacrificialFastDrainLastConfirmedACKToken =
                    tokenBytes
                self.sacrificialFastDrainAcknowledgedTokens.insert(
                    Data(tokenBytes)
                )
                try? self.readOnlyHistoryCaptureStore?.append(
                    event: "history_end_ack_confirmed",
                    fields: [
                        "sequence": sequence,
                        "token": Self.hex(tokenBytes),
                        "acknowledged_chunks":
                            self.sacrificialFastDrainACKCount,
                        "historical_records_discarded":
                            self.sacrificialFastDrainReceivedRecords,
                        "fabricated_ack": false,
                    ]
                )
                if let deferred =
                    self.sacrificialFastDrainDeferredMetadata {
                    self.sacrificialFastDrainDeferredMetadata = nil
                    if self.sacrificialFastDrainStopAfterCurrentACK {
                        try? self.readOnlyHistoryCaptureStore?.append(
                            event:
                                "deferred_history_end_dropped_after_slice_deadline",
                            fields: [
                                "slice_attempt":
                                    self.sacrificialFastDrainSliceAttempt,
                            ]
                        )
                    } else {
                        self.handleSacrificialFastDrainPayload(
                            deferred.payload,
                            sourceUUID: deferred.sourceUUID
                        )
                    }
                }
            }
        }
    }

    private func compareHRChannelsIfPossible(now: Date, source: String) {
        guard hrConsistencyEnabled,
              let standard = lastStandardHR,
              let realtime = lastRealtimeHR else { return }
        let age = abs(standard.t.timeIntervalSince(realtime.t))
        guard age <= 5 else { return }
        let delta = abs(standard.bpm - realtime.bpm)
        hrConsistencyPairs += 1
        hrConsistencyDeltaSum += delta
        hrConsistencyMaxDelta = max(hrConsistencyMaxDelta, delta)
        hrConsistencyRecentDeltas.append(delta)
        if hrConsistencyRecentDeltas.count > 20 { hrConsistencyRecentDeltas.removeFirst() }
        let mean = Double(hrConsistencyDeltaSum) / Double(hrConsistencyPairs)
        let recentMax = hrConsistencyRecentDeltas.max() ?? delta
        let recentMean = Double(hrConsistencyRecentDeltas.reduce(0, +)) / Double(max(1, hrConsistencyRecentDeltas.count))
        let ready = hrConsistencyRecentDeltas.count >= 10 && recentMax <= 2 && recentMean <= 1
        let shouldLog = ready
            || hrConsistencyPairs <= 5
            || hrConsistencyPairs.isMultiple(of: 10)
            || hrConsistencyLastLogAt.map { now.timeIntervalSince($0) >= 10 } ?? true
        guard shouldLog else { return }
        hrConsistencyLastLogAt = now
        AtriaDebugLog("ATRIADBG hr_consistency source=%@ pairs=%d standard_hr=%d realtime_hr=%d delta=%d mean_delta=%.1f max_delta=%d recent_mean_delta=%.1f recent_max_delta=%d pair_age_s=%.1f ready=%d tolerance_bpm=2",
              source,
              hrConsistencyPairs,
              standard.bpm,
              realtime.bpm,
              delta,
              mean,
              hrConsistencyMaxDelta,
              recentMean,
              recentMax,
              age,
              ready ? 1 : 0)
    }

    private func handleUnknownProtocolPayload(_ payload: [UInt8],
                                              fullFrame: [UInt8],
                                              sourceUUID: CBUUID? = nil,
                                              historyTransportActive: Bool = false) {
        guard let type = payload.first else { return }
        let body = Array(payload.dropFirst())
        recordProtocolPacket(type: type, length: payload.count)
        if type == Packet.event,
           let reading = Self.parseBatteryLevelEventFrame(fullFrame) {
                guard Self.batteryEventMayUpdateProjection(
                    historyTransportActive: historyTransportActive
                ) else {
                    AtriaDebugLog("ATRIADBG battery source=event_30 status=ignored reason=history_transport_not_battery_authority level=%d",
                                  reading.level)
                    return
                }
                let level = reading.level
                let millivolts = reading.millivolts
                let charging = reading.isCharging
                let eventReceivedAt = Date()
                switch Self.batteryEventAcceptanceDecision(
                    previousLevel: batteryLevel,
                    previousAcceptedAt: lastAcceptedBatteryLevelAt,
                    reading: reading,
                    receivedAt: eventReceivedAt,
                    pending: pendingBatteryDropCandidate,
                    previousIsCached: displayedBatteryLevelIsCached,
                    requiresFreshConfirmation: UserDefaults.standard.bool(
                        forKey: BatteryDefaults.requiresFreshConfirmation
                    ),
                    previousChargeStatus: batteryChargeStatus
                ) {
                case .quarantine(let candidate):
                    pendingBatteryDropCandidate = candidate
                    AtriaDebugLog("ATRIADBG battery source=event_30 status=quarantined level=%d previous=%d confirmations=%d span_s=%.1f mv=%d charging=%d",
                                  level,
                                  batteryLevel,
                                  candidate.confirmations,
                                  candidate.lastSeenAt.timeIntervalSince(candidate.firstSeenAt),
                                  millivolts,
                                  charging ? 1 : 0)
                    scheduleBatteryConfirmationRead(incomingLevel: level)
                    return
                case .accept:
                    break
                }
                batteryConfirmationReadTask?.cancel()
                batteryConfirmationReadTask = nil
                batteryConfirmationReadLevel = nil
                pendingBatteryDropCandidate = nil
                displayedBatteryLevelIsCached = false
                batteryReadingIsRecentBaseline = false
                batteryProjectionRevision &+= 1
                UserDefaults.standard.removeObject(forKey: BatteryDefaults.requiresFreshConfirmation)
                lastAcceptedBatteryLevelAt = eventReceivedAt
                let acceptedChargeStatus = Self.acceptedBatteryEventChargeStatus(
                    reportedIsCharging: charging,
                    batteryLevel: level
                )
                batteryRiseCandidate = Self.batteryRiseCandidateAfterExplicitChargeStatus(
                    acceptedChargeStatus,
                    current: batteryRiseCandidate
                )
                if batteryRiseCandidate == nil {
                    batteryRiseCandidatePeripheralID = nil
                }
                if acceptedChargeStatus == .notCharging || acceptedChargeStatus == .full {
                    lastPlausibleBatteryRiseEvidenceAt = nil
                    lastUncorroboratedChargingStatusAt = nil
                }
                assignIfChanged(\.batteryLevel, level)
                assignIfChanged(\.batteryIsCharging, acceptedChargeStatus == .charging)
                assignIfChanged(\.batteryChargeStatus, acceptedChargeStatus)
                persistBatteryLevel(level,
                                    source: "live_battery_event",
                                    chargeStatus: acceptedChargeStatus)
                recordBatteryChargeEvidence(acceptedChargeStatus,
                                            reason: "battery_event",
                                            observedAt: eventReceivedAt)
                AtriaDebugLog("ATRIADBG battery source=event_30 status=accepted level=%d mv=%d reported_charging=%d charge_status=%@ charge_reason=latched_subscription_replay",
                              level,
                              millivolts,
                              charging ? 1 : 0,
                              acceptedChargeStatus.rawValue)
            return
        }
        if type == Packet.realtimeRaw {
            if payload.count > 1, payload[1] == AtriaR10MotionDecoder.recordType {
                r10MotionFrameCount += 1
                let receivedAt = Date()
                recordValidR10MotionEvidence(receivedAt: receivedAt)
                if let sourceUUID {
                    recordProtectedR10EvidenceMetadataIfNeeded(receivedAt: receivedAt,
                                                               sourceUUID: sourceUUID)
                }
                recordMotionHandshakeR10EvidenceIfNeeded(receivedAt: receivedAt,
                                                         payloadLength: payload.count)
                recordProtectedR10EvidenceIfNeeded(receivedAt: receivedAt)
                markStepCalibrationMotionStreamReady(receivedAt: receivedAt)
            }
            if verboseBLEFrameLogging {
                AtriaDebugLog("ATRIADBG r10_frame record_type=%02x len=%d decoded=%d total=%d",
                              payload.count > 1 ? payload[1] : 0,
                              payload.count,
                              payload.count >= 1_288 ? 1 : 0,
                              r10MotionFrameCount)
            }
            return
        }
        if type == Packet.imu {
            logIMUCandidate(payload: payload)
            return
        }
        if type == 0x32 {
            logDiagnosticPacket(payload: payload, fullFrame: fullFrame)
            return
        }
        if verboseBLEFrameLogging {
            AtriaDebugLog("ATRIADBG protocol_packet type=%02x kind=%@ len=%d body=%@ full=%@",
                  type, Self.packetKind(type), payload.count, Self.hex(body), Self.hex(fullFrame))
        }
    }

    private func recordDecodedR10Metadata(sourceUUID: CBUUID,
                                          payloadLength: Int,
                                          receivedAt: Date) {
        dbgPropFrames += 1
        let type = Packet.realtimeRaw
        let signature = "\(sourceUUID.uuidString.prefix(8).suffix(2)):\(String(format: "%02x", type))"
        if !dbgTypeSet.contains(signature) {
            dbgTypeSet.insert(signature)
            dbgLast = dbgTypeSet.sorted().joined(separator: " ")
        }
        recordProtocolPacket(type: type, length: payloadLength)
        r10MotionFrameCount += 1
        recordValidR10MotionEvidence(receivedAt: receivedAt)
        recordMotionHandshakeR10EvidenceIfNeeded(receivedAt: receivedAt,
                                                 payloadLength: payloadLength)
        recordProtectedR10EvidenceIfNeeded(receivedAt: receivedAt)
        recordProtectedR10EvidenceMetadataIfNeeded(receivedAt: receivedAt,
                                                   sourceUUID: sourceUUID)
        markStepCalibrationMotionStreamReady(receivedAt: receivedAt)
        if verboseBLEFrameLogging {
            AtriaDebugLog("ATRIADBG r10_frame record_type=%02x len=%d decoded=1 total=%d path=fast_metadata",
                          AtriaR10MotionDecoder.recordType,
                          payloadLength,
                          r10MotionFrameCount)
        }
    }

    /// A decoded R10 frame has already passed framing, CRC and fixed-layout
    /// validation. Record that source truth for every radio profile; the old
    /// implementation updated freshness only in the protected-mode branch,
    /// leaving full-protocol counts falsely stale in Home/system surfaces.
    private func recordValidR10MotionEvidence(receivedAt: Date) {
        lastR10MotionFrameAt = receivedAt
        UserDefaults.standard.set(receivedAt.timeIntervalSince1970,
                                  forKey: RadioDefaults.passiveR10LastValidAt)
        assignIfChanged(\.liveStrapMotionCapturedAt, receivedAt)
        recordWorkoutMotionFrameIfNeeded(receivedAt: receivedAt)
        auditHeartRateFromR10CallbackIfNeeded(now: receivedAt)
        promoteReconnectBatteryBaselineIfSafe(
            now: receivedAt,
            validatedR10ReceivedAt: receivedAt,
            reason: "validated_r10_current_connection"
        )
    }

    /// A locked/background app may receive thousands of R10 callbacks while
    /// its scheduled keepalive tasks never execute. Repair 2A37 from that
    /// callback-granted execution slice, paced by the same pure policy as the
    /// foreground watchdog. The final stage uses the existing immediate
    /// background rebuild path, which journals the gap before cancelling and
    /// lets `didDisconnectPeripheral` reinstall the standing connection.
    private func auditHeartRateFromR10CallbackIfNeeded(now: Date) {
        guard longWearModeEnabled,
              status == .connected,
              let peripheral,
              peripheral.state == .connected,
              dutyCycleState != .sparseSentinel,
              !offlineHistoricalSyncInProgress,
              !historyOnlyProbeMode,
              !Self.shouldSuppressWatchdogForStrapStreamState(strapStreamState),
              let rawReference = lastRawHRNotificationAt ?? connectedAt,
              let acceptedReference = lastAcceptedHRAt ?? connectedAt else {
            return
        }
        let timeout = Self.hrContinuityWatchdogTimeout(acceptedHRTimeout: 45)
        let rawGap = max(0, now.timeIntervalSince(rawReference))
        guard Self.shouldRunCallbackDrivenHeartRateAudit(
            rawHeartRateGap: rawGap,
            timeout: timeout,
            lastAuditAt: lastCallbackDrivenHeartRateAuditAt,
            now: now
        ) else {
            return
        }
        lastCallbackDrivenHeartRateAuditAt = now
        performHRContinuityWatchdogAction(
            status: "r10_callback_stale",
            rawGap: rawGap,
            acceptedGap: max(0, now.timeIntervalSince(acceptedReference)),
            timeout: timeout,
            label: captureLabel.isEmpty ? "All-day wear" : captureLabel,
            immediateConnectedRebuild: true
        )
    }

    /// A connected raw-history frame is also a real background execution edge.
    /// Once that exact serve has been durably appended to the ingress spool,
    /// use the callback as the HR-watchdog clock: the ordinary timer and R10
    /// lane may both be suspended/suppressed while history owns the transport.
    /// Only the generation-matching exact raw owner can enter this path.
    @discardableResult
    private func auditHeartRateFromExactRawHistoryCallbackIfNeeded(
        generation: UInt64,
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot,
        now: Date
    ) -> Bool {
        guard longWearModeEnabled,
              status == .connected,
              let peripheral,
              peripheral.state == .connected,
              dutyCycleState != .sparseSentinel,
              activeConnectedRawHistoryCatchUpAuthority(
                generation: generation
              ) != nil,
              historyTransportPhaseFence.acceptsServe(
                historyPhase,
                generation: generation
              ),
              !Self.shouldSuppressWatchdogForStrapStreamState(
                strapStreamState
              ),
              let rawReference = lastRawHRNotificationAt ?? connectedAt,
              let acceptedReference = lastAcceptedHRAt ?? connectedAt else {
            return false
        }
        let timeout = Self.hrContinuityWatchdogTimeout(acceptedHRTimeout: 45)
        let rawGap = max(0, now.timeIntervalSince(rawReference))
        guard Self.shouldRunCallbackDrivenHeartRateAudit(
            rawHeartRateGap: rawGap,
            timeout: timeout,
            lastAuditAt: lastCallbackDrivenHeartRateAuditAt,
            now: now
        ) else {
            return false
        }
        lastCallbackDrivenHeartRateAuditAt = now
        performHRContinuityWatchdogAction(
            status: "exact_raw_history_callback_stale",
            rawGap: rawGap,
            acceptedGap: max(0, now.timeIntervalSince(acceptedReference)),
            timeout: timeout,
            label: captureLabel.isEmpty ? "All-day wear" : captureLabel,
            immediateConnectedRebuild: true
        )
        return !offlineHistoricalSyncInProgress
            || offlineHistoricalSyncGeneration != generation
    }

    private func recordProtectedR10EvidenceMetadataIfNeeded(receivedAt: Date,
                                                            sourceUUID: CBUUID) {
        guard standardHROnlyMode, sourceUUID == UUIDs.strapStream5 else { return }
        let defaults = UserDefaults.standard
        passiveR10FirstFrameTask?.cancel()
        passiveR10FirstFrameTask = nil
        if defaults.object(forKey: RadioDefaults.passiveR10FirstValidAt) == nil {
            defaults.set(receivedAt.timeIntervalSince1970,
                         forKey: RadioDefaults.passiveR10FirstValidAt)
        }
        defaults.set(defaults.integer(forKey: RadioDefaults.passiveR10ValidFrames) + 1,
                     forKey: RadioDefaults.passiveR10ValidFrames)
        defaults.set("receiving_crc_valid", forKey: RadioDefaults.passiveR10Status)
    }

    private func recordMotionHandshakeR10EvidenceIfNeeded(receivedAt: Date,
                                                          payloadLength: Int) {
        guard motionHandshakeDiagnostic != nil else { return }
        let defaults = UserDefaults.standard
        let frames = defaults.integer(forKey: "atria.motionHandshake.r10Frames") + 1
        defaults.set(frames, forKey: "atria.motionHandshake.r10Frames")
        defaults.set(receivedAt.timeIntervalSince1970,
                     forKey: "atria.motionHandshake.lastR10At")
        if defaults.object(forKey: "atria.motionHandshake.firstR10At") == nil {
            defaults.set(receivedAt.timeIntervalSince1970,
                         forKey: "atria.motionHandshake.firstR10At")
            defaults.set(payloadLength,
                         forKey: "atria.motionHandshake.firstR10PayloadLength")
            recordMotionHandshakeEvidence(event: "first_r10_received",
                                          detail: "payload_\(payloadLength)")
        }
    }

    private func recordProtectedR10EvidenceIfNeeded(receivedAt: Date) {
        guard motionHandshakeDiagnostic == nil else { return }
        // The v9 proof is specifically evidence for the command-armed profile.
        // Frames arriving between the final CCCD callback and 3F/01 must not
        // start or qualify a separate passive epoch.
        if protectedR10ResponseEventDataProofIsActive,
           !protectedR10ActivationSent {
            return
        }
        if !protectedR10ActivationSent,
           Self.protectedR10FrameBelongsToCurrentConnection(lastFrameAt: receivedAt,
                                                            connectedAt: connectedAt) {
            if protectedR10ActivationAt == nil {
                protectedR10ActivationAt = receivedAt
                protectedR10FramesAfterActivation = 0
            }
            protectedR10FramesAfterActivation += 1
            if !UserDefaults.standard.bool(forKey: Self.protectedR10StableTransportKey),
               let passiveEpoch = protectedR10ActivationAt,
               receivedAt.timeIntervalSince(passiveEpoch) >= Self.protectedR10EarlyDisconnectWindow,
               Self.protectedR10StabilityWindowIsProven(
                framesAfterActivation: protectedR10FramesAfterActivation,
                lastFrameAt: receivedAt,
                connectedAt: connectedAt,
                activationAt: passiveEpoch,
                now: receivedAt
               ) {
                qualifyProtectedR10RecoveryIfNeeded(at: receivedAt,
                                                     status: "receiving_crc_valid_passive")
                AtriaDebugLog("ATRIADBG protected_r10 status=stable_window_complete path=passive duration_s=%.0f frames=%d action=qualify_transport",
                              receivedAt.timeIntervalSince(passiveEpoch),
                              protectedR10FramesAfterActivation)
            }
            protectedR10ActivationGraceTask?.cancel()
            protectedR10ActivationGraceTask = nil
            UserDefaults.standard.set("receiving_crc_valid_passive",
                                      forKey: RadioDefaults.passiveR10Status)
            maybeRequestProprietaryBatteryRefresh(now: receivedAt)
            return
        }
        guard protectedR10ActivationSent else { return }
        protectedR10FramesAfterActivation += 1
        if protectedR10FramesAfterActivation == 1 {
            recordProtectedV9BringUpEdge("first_crc_valid_motion_frame")
            protectedR10MissingFrameTask?.cancel()
            protectedR10MissingFrameTask = nil
            let defaults = UserDefaults.standard
            defaults.set(receivedAt.timeIntervalSince1970,
                         forKey: Self.protectedR10FirstFrameAtKey)
            defaults.set("receiving_crc_valid", forKey: RadioDefaults.passiveR10Status)
            let latency = protectedR10ActivationAt.map { receivedAt.timeIntervalSince($0) } ?? -1
            AtriaDebugLog("ATRIADBG protected_r10 status=first_frame latency_s=%.3f action=keep_minimal_stream",
                          latency)
        }
        maybeRequestProprietaryBatteryRefresh(now: receivedAt)
    }

    private func maybeRequestProprietaryBatteryRefresh(now: Date) {
        guard Self.proprietaryBatteryRefreshEnabled,
              motionHandshakeDiagnostic == nil,
              !protectedR10RollbackEnabled else { return }
        let defaults = UserDefaults.standard
        let stableTransportProven = defaults.bool(forKey: Self.protectedR10StableTransportKey)
        var qualifiedAt = (defaults.object(forKey: Self.protectedR10StableTransportQualifiedAtKey) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        // V3 may already be physically qualified on an installed build that
        // predates this timestamp. Establish the grace anchor now; never infer
        // that the additional two quiet minutes have already elapsed.
        if stableTransportProven, qualifiedAt == nil {
            defaults.set(now.timeIntervalSince1970,
                         forKey: Self.protectedR10StableTransportQualifiedAtKey)
            qualifiedAt = now
        }
        let lastAttemptAt = (defaults.object(forKey: BatteryDefaults.proprietaryRefreshLastAttemptAt) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        let circuitOpenUntil = (defaults.object(forKey: BatteryDefaults.proprietaryRefreshCircuitOpenUntil) as? Double)
            .map(Date.init(timeIntervalSince1970:))
        let requestPending = proprietaryBatteryRefreshPhase != .idle
            || defaults.bool(forKey: BatteryDefaults.proprietaryRefreshPending)
        guard Self.shouldRequestProprietaryBatteryRefresh(
            standardHROnlyMode: standardHROnlyMode,
            stableTransportProven: stableTransportProven,
            connected: status == .connected && peripheral?.state == .connected,
            currentConnectionR10Frames: protectedR10FramesAfterActivation,
            lastR10FrameAt: lastR10MotionFrameAt,
            transportQualifiedAt: qualifiedAt,
            batteryIsFresh: Self.batteryLevelIsFresh(lastAcceptedAt: lastAcceptedBatteryLevelAt,
                                                     now: now),
            activeWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity(),
            historyActive: offlineHistoricalSyncInProgress || historyOnlyProbeEnabled || historyOnlyProbeMode,
            requestPending: requestPending,
            lastAttemptAt: lastAttemptAt,
            circuitOpenUntil: circuitOpenUntil,
            now: now
        ) else { return }
        guard let peripheral,
              let service = peripheral.services?.first(where: { $0.uuid == Self.UUIDs.strapService }),
              let txCharacteristic,
              txCharacteristic.properties.contains(.write) else {
            failProprietaryBatteryRefresh(reason: "missing_service_or_wr_tx", now: now)
            return
        }

        defaults.set(now.timeIntervalSince1970,
                     forKey: BatteryDefaults.proprietaryRefreshLastAttemptAt)
        defaults.set(true, forKey: BatteryDefaults.proprietaryRefreshPending)
        proprietaryBatteryRefreshPhase = .discoveringResponse
        proprietaryBatteryRequestSequence = nil
        proprietaryBatteryResponseCharacteristic = nil
        proprietaryBatteryRefreshEnabledResponseNotify = false
        proprietaryBatteryRefreshTimeoutTask?.cancel()
        proprietaryBatteryRefreshTimeoutTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.proprietaryBatteryResponseTimeout))
            guard let self, !Task.isCancelled,
                  self.proprietaryBatteryRefreshPhase != .idle else { return }
            self.failProprietaryBatteryRefresh(reason: "response_timeout")
        }
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=discovering_rx action=one_shot stable_frames=%d",
                      protectedR10FramesAfterActivation)
        peripheral.discoverCharacteristics([Self.UUIDs.strapRX], for: service)
    }

    private func handleProprietaryBatteryResponseCharacteristic(
        _ characteristic: CBCharacteristic,
        peripheral: CBPeripheral
    ) {
        guard proprietaryBatteryRefreshPhase == .discoveringResponse else { return }
        guard characteristic.uuid == Self.UUIDs.strapRX,
              characteristic.properties.contains(.notify) else {
            failProprietaryBatteryRefresh(reason: "rx_notify_unsupported")
            return
        }
        proprietaryBatteryResponseCharacteristic = characteristic
        if characteristic.isNotifying {
            sendProprietaryBatteryRefreshCommand()
        } else {
            proprietaryBatteryRefreshPhase = .subscribingResponse
            proprietaryBatteryRefreshEnabledResponseNotify = true
            peripheral.setNotifyValue(true, for: characteristic)
        }
    }

    private func handleProprietaryBatteryResponseNotifyState(
        _ characteristic: CBCharacteristic,
        error: Error?
    ) {
        guard proprietaryBatteryRefreshPhase == .subscribingResponse,
              characteristic.uuid == Self.UUIDs.strapRX else { return }
        guard error == nil, characteristic.isNotifying else {
            failProprietaryBatteryRefresh(reason: "rx_notify_failed")
            return
        }
        sendProprietaryBatteryRefreshCommand()
    }

    private func sendProprietaryBatteryRefreshCommand() {
        guard !readOnlyHistoryCaptureRequested else {
            failProprietaryBatteryRefresh(reason: "read_only_history_capture")
            return
        }
        guard proprietaryBatteryRefreshPhase == .discoveringResponse
                || proprietaryBatteryRefreshPhase == .subscribingResponse,
              let peripheral,
              peripheral.state == .connected,
              let txCharacteristic,
              txCharacteristic.properties.contains(.write),
              proprietaryBatteryResponseCharacteristic?.isNotifying == true else {
            failProprietaryBatteryRefresh(reason: "command_prerequisite_lost")
            return
        }
        let sequence = cmdSeq
        cmdSeq &+= 1
        proprietaryBatteryRequestSequence = sequence
        proprietaryBatteryRefreshPhase = .awaitingResponse
        let frame = encodeFrame([Packet.command, sequence, Cmd.getBatteryLevel])
        peripheral.writeValue(frame, for: txCharacteristic, type: .withResponse)
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=request_sent seq=%d mode=wr action=await_single_response",
                      Int(sequence))
    }

    private func handleProprietaryBatteryCommandResponse(_ payload: [UInt8], receivedAt: Date = Date()) {
        guard proprietaryBatteryRefreshPhase == .awaitingResponse,
              let expectedSequence = proprietaryBatteryRequestSequence,
              payload.count >= 3,
              payload[0] == 0x24,
              payload[2] == Cmd.getBatteryLevel else { return }
        guard let level = Self.parseProprietaryBatteryResponse(payload,
                                                               expectedSequence: expectedSequence) else {
            failProprietaryBatteryRefresh(reason: "malformed_or_mismatched_response", now: receivedAt)
            return
        }
        switch Self.batteryLevelAcceptanceDecision(
            previousLevel: batteryLevel,
            previousAcceptedAt: lastAcceptedBatteryLevelAt,
            incomingLevel: level,
            receivedAt: receivedAt,
            pending: pendingBatteryDropCandidate,
            previousIsCached: displayedBatteryLevelIsCached,
            requiresFreshConfirmation: UserDefaults.standard.bool(
                forKey: BatteryDefaults.requiresFreshConfirmation
            )
        ) {
        case .quarantine(let candidate):
            pendingBatteryDropCandidate = candidate
            AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=quarantined level=%d previous=%d action=no_followup_read",
                          level, batteryLevel)
        case .accept:
            pendingBatteryDropCandidate = nil
            displayedBatteryLevelIsCached = false
            batteryReadingIsRecentBaseline = false
            batteryProjectionRevision &+= 1
            UserDefaults.standard.removeObject(forKey: BatteryDefaults.requiresFreshConfirmation)
            lastAcceptedBatteryLevelAt = receivedAt
            assignIfChanged(\.batteryLevel, level)
            assignIfChanged(\.batteryIsCharging, false)
            assignIfChanged(\.batteryChargeStatus, .levelOnly)
            persistBatteryLevel(level, source: "live_proprietary_1a")
            recordBatteryChargeEvidence(.levelOnly, reason: "proprietary_battery_response")
            AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=accepted level=%d", level)
        }
        finishProprietaryBatteryRefresh(success: true, reason: "response_received", now: receivedAt)
    }

    private func failProprietaryBatteryRefresh(reason: String, now: Date = Date()) {
        if proprietaryBatteryRefreshPhase == .idle,
           !UserDefaults.standard.bool(forKey: BatteryDefaults.proprietaryRefreshPending) {
            UserDefaults.standard.set(true, forKey: BatteryDefaults.proprietaryRefreshPending)
        }
        finishProprietaryBatteryRefresh(success: false, reason: reason, now: now)
    }

    private func finishProprietaryBatteryRefresh(success: Bool, reason: String, now: Date) {
        let wasPending = proprietaryBatteryRefreshPhase != .idle
            || UserDefaults.standard.bool(forKey: BatteryDefaults.proprietaryRefreshPending)
        guard wasPending else { return }
        let responseCharacteristic = proprietaryBatteryResponseCharacteristic
        let shouldDisableResponseNotify = proprietaryBatteryRefreshEnabledResponseNotify
        proprietaryBatteryRefreshTimeoutTask?.cancel()
        proprietaryBatteryRefreshTimeoutTask = nil
        proprietaryBatteryRefreshPhase = .idle
        proprietaryBatteryRequestSequence = nil
        proprietaryBatteryResponseCharacteristic = nil
        proprietaryBatteryRefreshEnabledResponseNotify = false
        let defaults = UserDefaults.standard
        defaults.set(false, forKey: BatteryDefaults.proprietaryRefreshPending)
        if success {
            defaults.set(now.timeIntervalSince1970,
                         forKey: BatteryDefaults.proprietaryRefreshLastSuccessAt)
            defaults.removeObject(forKey: BatteryDefaults.proprietaryRefreshCircuitOpenUntil)
            defaults.removeObject(forKey: BatteryDefaults.proprietaryRefreshLastFailure)
        } else {
            defaults.set(now.addingTimeInterval(Self.proprietaryBatteryRefreshFailureCircuit).timeIntervalSince1970,
                         forKey: BatteryDefaults.proprietaryRefreshCircuitOpenUntil)
            defaults.set(reason, forKey: BatteryDefaults.proprietaryRefreshLastFailure)
        }
        if shouldDisableResponseNotify,
           let responseCharacteristic,
           responseCharacteristic.isNotifying,
           peripheral?.state == .connected {
            peripheral?.setNotifyValue(false, for: responseCharacteristic)
        }
        AtriaDebugLog("ATRIADBG battery source=proprietary_1a status=%@ reason=%@ action=unsubscribe_no_retry circuit_h=%.0f",
                      success ? "complete" : "failed",
                      reason,
                      success ? 0 : Self.proprietaryBatteryRefreshFailureCircuit / 3600)
    }

    private func markPassiveR10SubscriptionConfirmed() {
        let subscribedAt = Date()
        protectedR10InitialProfilePeripheralID = nil
        protectedR10InitialProfileNotificationRequested = false
        ensureR10LivenessWatchdog(reason: "protected_stream5_subscribed")
        let defaults = UserDefaults.standard
        defaults.set("subscribed_waiting_for_crc_valid_frame",
                     forKey: RadioDefaults.passiveR10Status)
        defaults.set(subscribedAt.timeIntervalSince1970,
                     forKey: RadioDefaults.passiveR10SubscribedAt)
        // This subscription belongs to a new proof/notification epoch. A
        // frame from the preceding epoch may still be younger than the UI's
        // 15-second jitter window, but it cannot prove that this epoch is
        // carrying motion. Preserve the monotonic count and retire only its
        // live clocks until a CRC-valid R10 frame arrives.
        retireLiveR10MotionFreshness(
            state: "passive_r10_waiting",
            reason: "subscription_confirmed_waiting_for_frame"
        )
        passiveR10FirstFrameTask?.cancel()
        passiveR10FirstFrameTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(8))
            guard let self, !Task.isCancelled else { return }
            self.passiveR10FirstFrameTask = nil
            let receivedAfterSubscribe = self.lastR10MotionFrameAt.map {
                $0 >= subscribedAt
            } ?? false
            guard !receivedAfterSubscribe else { return }
            defaults.set("subscribed_no_crc_valid_frames",
                         forKey: RadioDefaults.passiveR10Status)
            self.assignIfChanged(\.liveStrapStepResearchState,
                                 "passive_r10_unavailable")
            AtriaDebugLog("ATRIADBG passive_r10 status=unavailable action=preserve_2a37_no_writes_no_reconnect")
        }
        beginProtectedR10CleanOwnerProofIfNeeded(at: subscribedAt)
        AtriaDebugLog("ATRIADBG passive_r10 status=subscribed source=stream5 hr_source=2a37 writes=0")
    }

    /// A known R10 transport boundary is stronger evidence than an age-based
    /// presentation grace period. Keep the durable/monotonic step total, but
    /// make every live projection fail closed until a newly decoded R10 frame
    /// records this epoch's motion and detector-applied step clocks again.
    private func retireLiveR10MotionFreshness(state: String, reason: String) {
        assignIfChanged(\.liveStrapMotionCapturedAt, nil)
        assignIfChanged(\.liveStrapStepCountCapturedAt, nil)
        assignIfChanged(\.liveStrapStepResearchState, state)
        UserDefaults.standard.removeObject(forKey: RadioDefaults.passiveR10LastValidAt)
        AtriaDebugLog(
            "ATRIADBG strap_steps status=freshness_retired state=%@ reason=%@ count=%d action=preserve_monotonic_count",
            state,
            reason,
            liveStrapStepResearchCount
        )
    }

    private func markStepCalibrationMotionStreamReady(receivedAt: Date) {
        guard !stepCalibrationMotionStreamReady,
              let armedAt = stepCalibrationCaptureArmedAt,
              receivedAt >= armedAt,
              let captureUntil = strapStepCalibrationCaptureUntil,
              receivedAt < captureUntil,
              // A single fresh frame is not a usable stream: sparse passive
              // frames satisfied this gate on 2026-07-16 02:35 IST and the
              // user's rest stage captured 8%. Calibration may only start on
              // proven ~1 Hz density, same bar as workout motion.
              workoutMotionDenseFrameCount(now: receivedAt)
                >= Self.workoutMotionDenseFrameThreshold else { return }
        stepCalibrationMotionStreamReady = true
        AtriaDebugLog(
            "ATRIADBG strap_step_calibration status=stream_ready fresh_r10_after_arm=1 latency_ms=%.0f",
            receivedAt.timeIntervalSince(armedAt) * 1_000
        )
    }

    private func recordProtocolPacket(type: UInt8, length: Int) {
        protocolPacketCount += 1
        protocolLastPacketType = String(format: "%02x", type)
        protocolLastPacketKind = Self.packetKind(type)
        protocolLastPacketLength = length
        if type == Packet.imu || type == Packet.realtimeRaw {
            protocolIMUFrameCount += 1
        } else if type == 0x32 {
            protocolDiagnosticFrameCount += 1
        } else if type == 0x30 {
            protocolEventFrameCount += 1
        } else {
            protocolUnknownFrameCount += 1
        }

        guard protocolDiagnosticsPersistenceEnabled else { return }
        let defaults = UserDefaults.standard
        defaults.set(protocolPacketCount, forKey: ProtocolDefaults.packets)
        defaults.set(protocolLastPacketType, forKey: ProtocolDefaults.lastPacketType)
        defaults.set(protocolLastPacketKind, forKey: ProtocolDefaults.lastPacketKind)
        defaults.set(protocolLastPacketLength, forKey: ProtocolDefaults.lastPacketLength)
        defaults.set(protocolIMUFrameCount, forKey: ProtocolDefaults.imuFrames)
        defaults.set(protocolDiagnosticFrameCount, forKey: ProtocolDefaults.diagnosticFrames)
        defaults.set(protocolEventFrameCount, forKey: ProtocolDefaults.eventFrames)
        defaults.set(protocolUnknownFrameCount, forKey: ProtocolDefaults.unknownFrames)
    }

    private func logDiagnosticPacket(payload: [UInt8], fullFrame: [UInt8]) {
        let text = Self.printableRuns(in: Array(payload.dropFirst())).joined(separator: " | ")
        if verboseBLEFrameLogging {
            AtriaDebugLog("ATRIADBG diagnostic_text validated=0 len=%d text=%@ payload=%@ full=%@",
                  payload.count, text.isEmpty ? "none" : text, Self.hex(payload), Self.hex(fullFrame))
        }
        if let hint = Self.diagnosticSleepMotionHint(from: text) {
            sleepMotionHintCount += 1
            sleepMotionHintKindCounts[hint.kind, default: 0] += 1
            sleepMotionHintKinds = Self.formatKindCounts(sleepMotionHintKindCounts)
            sleepMotionSource = "diagnostic_observe_only"
            if let motionShort = Double(hint.motionShort) {
                sleepMotionShortValues.append(motionShort)
            }
            let motionShortStats = sleepMotionShortSummary()
            AtriaDebugLog("ATRIADBG sleep_motion_hint validated=0 source=0x32 kind=%@ motion_short=%@ state_from=%@ state_to=%@ motion_short_count=%d motion_short_mean=%@ motion_short_min=%@ motion_short_max=%@ motion_short_over_1=%d motion_short_threshold=%.1f text=%@ action=observe_only_until_motion_decode_validated",
                  hint.kind,
                  hint.motionShort,
                  hint.stateFrom,
                  hint.stateTo,
                  motionShortStats.count,
                  Self.formatDouble(motionShortStats.mean),
                  Self.formatDouble(motionShortStats.min),
                  Self.formatDouble(motionShortStats.max),
                  motionShortStats.overOne,
                  motionShortAuditThreshold,
                  text.isEmpty ? "none" : text)
        }
    }

    private func sleepMotionShortSummary() -> (count: Int, mean: Double?, min: Double?, max: Double?, overOne: Int) {
        guard !sleepMotionShortValues.isEmpty else { return (0, nil, nil, nil, 0) }
        let count = sleepMotionShortValues.count
        let mean = sleepMotionShortValues.reduce(0, +) / Double(count)
        let overOne = sleepMotionShortValues.filter { $0 > motionShortAuditThreshold }.count
        return (count, mean, sleepMotionShortValues.min(), sleepMotionShortValues.max(), overOne)
    }

    private func logIMUCandidate(payload: [UInt8]) {
        let body = Array(payload.dropFirst())
        let decoded = AtriaIMUDecoder.decode(payload: payload)
        if let decoded {
            recordIMUFeatures(decoded)
        }
        var i16Pairs: [String] = []
        var magnitudes: [String] = []
        for offset in stride(from: 0, through: max(0, body.count - 2), by: 2) {
            guard offset + 1 < body.count else { continue }
            let raw = Int16(bitPattern: Self.u16le(body, offset))
            i16Pairs.append("\(offset):\(raw)")
        }
        for offset in stride(from: 0, through: max(0, body.count - 6), by: 6) {
            guard offset + 5 < body.count else { continue }
            let x = Double(Int16(bitPattern: Self.u16le(body, offset)))
            let y = Double(Int16(bitPattern: Self.u16le(body, offset + 2)))
            let z = Double(Int16(bitPattern: Self.u16le(body, offset + 4)))
            let magnitude = sqrt(x * x + y * y + z * z)
            magnitudes.append(String(format: "%d:%.1f", offset, magnitude))
        }
        if verboseBLEFrameLogging {
            AtriaDebugLog("ATRIADBG imu_candidate validated=%d validation_state=%@ len=%d offset=%d endian=%@ scale=%.0f sample_rate_hz=%@ samples=%d mean_g=%@ stillness_ratio=%@ movement_intensity=%@ bursts=%d strap_steps_research=%d step_source=strap_imu_research metric_promotions=0 i16=%@ magnitudes=%@ payload=%@",
                  decoded?.gravityValidated == true ? 1 : 0,
                  decoded?.validationState ?? "decode_failed",
                  payload.count,
                  decoded?.offset ?? -1,
                  decoded?.endian.rawValue ?? "none",
                  decoded?.scale ?? 0,
                  Self.formatDouble(imuFeatureSummary().sampleRateHz),
                  decoded?.samples.count ?? 0,
                  Self.formatDouble(decoded?.meanMagnitudeG),
                  Self.formatDouble(decoded?.stillnessRatio),
                  Self.formatDouble(decoded?.movementIntensity),
                  decoded?.activityBursts ?? 0,
                  strapStepResearchCount,
                  i16Pairs.joined(separator: ","),
                  magnitudes.joined(separator: ","),
                  Self.hex(payload))
        }
    }

    private func recordResearchProbeCandidate(payload: [UInt8], source: AtriaResearchProbe.Source) {
        if historyOnlyProbeMode, source == .historical {
            guard verboseBLEFrameLogging, researchProbeFrameCount < 3 else { return }
        }
        let summary = AtriaResearchProbe.analyze(payload: payload, source: source)
        applyModelMetadataIfExplicit(summary)
        guard researchProbeGenerationGate.acceptsForCandidateCounting(summary),
              supportsGenerationSpecificDecode,
              supportsSpO2Probe || supportsSkinTempProbe else { return }
        researchProbeFrameCount += 1
        if supportsSpO2Probe, !summary.oxygenByteCandidates.isEmpty {
            researchProbeOxygenCandidateFrames += 1
            if let offset64 = summary.oxygenValue(atOffset: 64) {
                researchProbeOxygenOffset64ValueSum += offset64
                researchProbeOxygenOffset64ValueCount += 1
            }
            if let offset66 = summary.oxygenValue(atOffset: 66) {
                researchProbeOxygenOffset66ValueSum += offset66
                researchProbeOxygenOffset66ValueCount += 1
            }
        }
        if supportsSkinTempProbe, !summary.temperatureWordCandidates.isEmpty {
            researchProbeTemperatureCandidateFrames += 1
            researchProbeTemperatureCandidateValueSum += summary.temperatureWordCandidates.reduce(0) { $0 + $1.value }
            researchProbeTemperatureCandidateValueCount += summary.temperatureWordCandidates.count
        }
        guard summary.hasAnyCandidate || researchProbeFrameCount == 1 || researchProbeFrameCount.isMultiple(of: 50) else { return }
        AtriaDebugLog("ATRIADBG sensor_research_probe source=%@ status=research_unvalidated len=%d frames=%d model_generation=%@ model_evidence=%@ spo2_enabled=%d spo2_candidate_frames=%d spo2_offsets=%@ skin_temp_enabled=%d skin_temp_candidate_frames=%d skin_temp_offsets=%@ metric_promotions=0 healthkit_write=0 raw_storage=0",
              summary.source.rawValue,
              summary.payloadLength,
              researchProbeFrameCount,
              summary.modelGeneration.rawValue,
              summary.modelEvidence.isEmpty ? "none" : summary.modelEvidence,
              supportsSpO2Probe ? 1 : 0,
              researchProbeOxygenCandidateFrames,
              supportsSpO2Probe ? summary.oxygenOffsetSummary : "disabled",
              supportsSkinTempProbe ? 1 : 0,
              researchProbeTemperatureCandidateFrames,
              supportsSkinTempProbe ? summary.temperatureOffsetSummary : "disabled")
    }

    private func applyModelMetadataIfExplicit(_ summary: AtriaResearchProbe.Summary) {
        guard summary.source == .metadata else { return }
        let mapped: AtriaStrapModel?
        switch summary.modelGeneration {
        case .strapMG:
            mapped = .strapMG
        case .strap5:
            mapped = .strap5
        case .strap4:
            mapped = .strap4
        case .strap3:
            mapped = .strap3
        case .unknown:
            mapped = nil
        }
        guard let mapped else {
            logUnknownStrapGenerationIfNeeded(summary)
            return
        }
        guard mapped != strapModel else { return }
        strapModel = mapped
        AtriaDebugLog("ATRIADBG model_gate status=metadata_explicit model=%@ evidence=%@ source=%@",
              mapped.rawValue,
              summary.modelEvidence.isEmpty ? "none" : summary.modelEvidence,
              summary.source.rawValue)
    }

    private func logUnknownStrapGenerationIfNeeded(_ summary: AtriaResearchProbe.Summary) {
        guard unknownGenerationProbeLogCount == 0 else { return }
        unknownGenerationProbeLogCount += 1
        AtriaDebugLog("ATRIADBG strap_generation status=unknown layout=%@ source=%@ evidence=%@ action=fail_closed_generation_specific_decodes",
                      summary.layoutHead,
                      summary.source.rawValue,
                      summary.modelEvidence.isEmpty ? "none" : summary.modelEvidence)
    }

    private func maybeSendRecentHistorySweep(realtimeUnix: UInt32) {
        guard historyRecentSweepEnabled, !historyRecentSweepSent, realtimeUnix > 0 else { return }
        historyRecentSweepSent = true
        let offsets = historyRecentSweepOffsets
        Task { @MainActor in
            for offset in offsets {
                let start = realtimeUnix > offset ? realtimeUnix - offset : realtimeUnix
                let end = realtimeUnix
                let payloads: [[UInt8]] = [
                    [0x00],
                    [0x01] + Self.le32(start),
                    [0x00] + Self.le32(start),
                    Self.le32(start),
                    Self.le32(start) + Self.le32(end),
                    [0x00] + Self.le32(start) + Self.le32(end),
                ]
                for (variant, data) in payloads.enumerated() {
                    AtriaDebugLog("ATRIADBG historyRecentSweep send offset_s=%u start=%u end=%u variant=%d cmd=16 data=%@",
                          offset, start, end, variant, Self.hex(data))
                    sendCommand(0x16, data, mode: probeCommandMode)
                    try? await Task.sleep(for: .seconds(5))
                }
            }
        }
    }

    private func activeHistoricalGeneration(
        for historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) -> UInt64? {
        guard let generation = historyPhase.generation,
              offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration,
              historyTransportPhaseFence.accepts(
                historyPhase,
                generation: generation
              ) else {
            return nil
        }
        return generation
    }

    private func handleHistoryMetadata(
        _ payload: [UInt8],
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        guard let generation = activeHistoricalGeneration(
            for: historyPhase
        ) else {
            AtriaDebugLog("ATRIADBG historyMeta status=ignored reason=inactive_or_stale_transport_phase")
            return
        }
        let exactRawAuthorityActive =
            activeConnectedRawHistoryCatchUpAuthority(
                generation: generation
            ) != nil
        if exactRawAuthorityActive, historicalAdmissionFailed {
            AtriaDebugLog(
                "ATRIADBG historyMeta status=ignored reason=exact_raw_admission_already_failed generation=%llu action=finish_local_no_progress_no_ack_keep_2a37",
                generation
            )
            _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: generation,
                reason: "exact_connected_raw_admission_failed"
            )
            return
        }
        guard Self.shouldAcceptConnectedRawHistoryIngress(
            exactRawAuthorityActive: exactRawAuthorityActive,
            callbackCapturedCurrentServe:
                historyTransportPhaseFence.acceptsServe(
                    historyPhase,
                    generation: generation
                ),
            admissionAttemptAvailable: historicalAdmissionAttempt != nil
        ) else {
            // This decision uses the serve token captured synchronously at
            // delegate entry. A predecessor callback queued before this
            // generation's 0x16 cannot acquire authority merely because the
            // MainActor applies it after 0x16.
            AtriaDebugLog(
                "ATRIADBG historyMeta status=ignored reason=pre_current_generation_serve generation=%llu action=no_spool_no_progress_no_flush_no_ack_keep_2a37",
                generation
            )
            return
        }
        if historicalAdmissionFailed {
            processOrderedHistoryMetadata(payload, historyPhase: historyPhase)
            return
        }
        guard enqueueHistoricalIngress(.metadata(
            payload: payload,
            phaseGeneration: historyPhase.generation
        )) else { return }
        scheduleHistoricalTransportEventDrain()
    }

    /// The ingress journal is the only retained ordering source between BLE
    /// callbacks and the slower SQLite/archive pipeline. Its contents never
    /// authorize an ACK; a write failure instead permanently retains the gap.
    @discardableResult
    private func enqueueHistoricalIngress(
        _ event: AtriaWhoop4HistoricalIngressSpool.Event
    ) -> Bool {
        guard let spool = historicalIngressSpool else {
            historicalAdmissionFailed = true
            historicalArchiveWriteFailures += 1
            AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=spool_missing action=withhold_ack_retain_gap",
                          offlineHistoricalSyncGeneration)
            return false
        }
        do {
            try spool.append(event)
            return true
        } catch {
            historicalAdmissionFailed = true
            historicalArchiveWriteFailures += 1
            historicalIngressSpoolFailure = String(describing: error)
            AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=spool_append_failed error=%@ action=withhold_ack_retain_gap",
                          offlineHistoricalSyncGeneration,
                          historicalIngressSpoolFailure ?? "unknown")
            return false
        }
    }

    private func processOrderedHistoryMetadata(
        _ payload: [UInt8],
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        guard let generation = activeHistoricalGeneration(for: historyPhase) else {
            AtriaDebugLog("ATRIADBG historyMeta status=ignored reason=inactive_or_stale_transport_phase")
            return
        }
        recordResearchProbeCandidate(payload: payload, source: .metadata)
        let marker: AtriaWhoop4HistoryMetadata.Marker
        do {
            marker = try AtriaWhoop4HistoryMetadata.parse(payload)
        } catch {
            AtriaDebugLog("ATRIADBG historyMeta status=rejected reason=%@ payload=%@",
                          String(describing: error), Self.hex(payload))
            return
        }

        switch marker {
        case .historyStart(let sequence):
            gate4DailyBankHistoryStartIdentity =
                currentGate4DailyBankRearmIdentity(
                    generation: generation
                )
            armFullDrainAuthorityAfterHistoryStart(
                sequence: sequence,
                generation: generation
            )
            scheduleGate4DailyBankRearmAfterHistoryStart(
                generation: generation
            )
            noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: "history_start"
            )
            AtriaDebugLog("ATRIADBG historyMeta status=start sequence=%d generation=%llu",
                          Int(sequence), generation)

        case .historyComplete(let sequence):
            gate4DailyBankTerminalIdentity =
                currentGate4DailyBankRearmIdentity(
                    generation: generation
                )
            fullDrainHistoryCompletePayload = payload
            noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: "history_complete"
            )
            AtriaDebugLog("ATRIADBG historyTerminal status=received sequence=%d generation=%llu pending=%d action=reduce",
                          Int(sequence),
                          generation,
                          historyDrain.pendingPersistenceCount)
            processHistoricalDrainEffects(
                historyDrain.historyComplete(generation: generation)
            )

        case .historyEnd(let sequence, let opaqueStatusWord, let token):
            let ackKey = "enddata:\(Self.hex(token.bytes))"
            let acked = ackedHistoryAckKeys.contains(ackKey)
            noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: acked ? "history_end_replay" : "history_end"
            )
            AtriaDebugLog("ATRIADBG historyMeta status=end sequence=%d status_word=%u received_records=%d sequence_restarts=%d token=%@ acked=%d payload=%@",
                          Int(sequence), opaqueStatusWord, historyDrain.currentBatchFrameCountForDiagnostics,
                          historyDrain.sequenceRestartCount, Self.hex(token.bytes),
                          acked ? 1 : 0, Self.hex(payload))
            if historicalArchiveWriteFailures > 0 {
                AtriaDebugLog("ATRIADBG historyAck skip=archive_persist_failed rows=%d rows_since_ack=%d failures=%d archive=%@",
                      historicalArchiveRows,
                      historicalArchiveRowsSinceAck,
                      historicalArchiveWriteFailures,
                      lastHistoricalArchivePath.isEmpty ? HistoricalArchive.relativePath : lastHistoricalArchivePath)
                return
            }
            let ack = token.acknowledgementPayload
            if acked {
                reackDurableHistoricalReplay(
                    generation: generation,
                    boundaryID: ackKey,
                    payload: ack
                )
                return
            }
            fullDrainHistoryEndPayloads[ackKey] = payload
            pendingHistoryEndACK = (ackKey, ack)
            AtriaDebugLog("ATRIADBG historyAck status=queued key=%@ pending_persistence=%d action=reduce",
                          ackKey,
                          historyDrain.pendingPersistenceCount)
            processHistoricalDrainEffects(
                historyDrain.historyEnd(
                    generation: generation,
                    boundaryID: ackKey,
                    ackPayload: ack
                )
            )
        }
    }

    private func armFullDrainAuthorityAfterHistoryStart(
        sequence: UInt8,
        generation: UInt64
    ) {
        let observedAt = Date().timeIntervalSince1970
        guard let currentDrainRequestedAt = pendingFullDrainCommandRequestedAtUnix,
              observedAt >= currentDrainRequestedAt else {
            AtriaDebugLog("ATRIADBG historical_full_drain_authority status=ignored generation=%llu reason=history_start_before_current_drain_request raw_only=1",
                          generation)
            return
        }
        let startAt = acceptedHistoryStartAtUnix ?? observedAt
        if acceptedHistoryStartSequence == nil {
            acceptedHistoryStartSequence = sequence
            acceptedHistoryStartAtUnix = startAt
        }
        armHistoryFirstFrameWatchdogIfNeeded(generation: generation)
        guard activeFullDrainEventIdentity == nil,
              let selected = selectedFullDrainGap,
              let gapEnd = selected.window.end,
              let nonce = fullDrainTransportNonce,
              let peripheralIdentifier = peripheral?.identifier.uuidString,
              let admissionAttempt = historicalAdmissionAttempt,
              admissionAttempt.strapIdentifier == peripheralIdentifier,
              let clockSequence = pendingHistoryClockCommandSequence,
              let clockRequestedAt = pendingHistoryClockCommandRequestedAtUnix,
              let clockWriteAt = pendingHistoryClockWriteCompletedAtUnix,
              let clockResponseSequence = acceptedHistoryClockResponseSequence,
              let deviceClockUnix = acceptedHistoryClockDeviceUnix,
              let clockWallUnix = acceptedHistoryClockWallUnix,
              let clockResponseAt = acceptedHistoryClockResponseAtUnix,
              let drainWrite = historicalFullDrainWriteEvidence,
              let drainRequestedAt = pendingFullDrainCommandRequestedAtUnix,
              drainWrite.transportGeneration == generation,
              drainWrite.command == Cmd.sendHistoricalData,
              drainWrite.payload == [0x00] else {
            AtriaDebugLog("ATRIADBG historical_full_drain_authority status=deferred generation=%llu reason=missing_gap_clock_write_or_identity raw_only=1",
                          generation)
            return
        }
        do {
            let transport = try AtriaHistoricalFullDrainCoveragePolicy
                .validateTransportAuthority(
                    peripheralIdentifier: peripheralIdentifier,
                    strapIdentity: strapModel.rawValue,
                    transportNonce: nonce,
                    transportGeneration: generation,
                    clockCommandSequence: clockSequence,
                    clockCommandRequestedAtUnix: clockRequestedAt,
                    clockWriteCompletedAtUnix: clockWriteAt,
                    clockResponseSequence: clockResponseSequence,
                    deviceClockUnix: deviceClockUnix,
                    clockWallUnix: clockWallUnix,
                    clockResponseReceivedAtUnix: clockResponseAt,
                    fullDrainCommandSequence: drainWrite.commandSequence,
                    fullDrainCommandRequestedAtUnix: drainRequestedAt,
                    fullDrainWriteCompletedAtUnix: drainWrite.writeCompletedAtUnix,
                    historyStartSequence: sequence,
                    historyStartReceivedAtUnix: startAt
                )
            let gap = AtriaHistoricalFullDrainCoverageStore.PendingGap(
                gapIdentifier: selected.window.id.uuidString.lowercased(),
                gapLedgerGeneration: selected.ledgerGeneration,
                gapLedgerSnapshotSHA256: selected.ledgerSnapshotSHA256,
                startUnix: selected.window.start.timeIntervalSince1970,
                endUnix: gapEnd.timeIntervalSince1970,
                reason: selected.window.reason,
                pending: true
            )
            let attempt = AtriaHistoricalFullDrainCoverageStore.Attempt(
                attemptIdentifier: admissionAttempt.identifier,
                attemptNumber: generation,
                peripheralIdentifier: peripheralIdentifier,
                strapIdentity: strapModel.rawValue,
                transportNonce: nonce,
                transportGeneration: generation,
                fullDrainCommandSHA256: AtriaHistoricalFullDrainCoveragePolicy.sha256(
                    Data([Cmd.sendHistoricalData, 0x00])
                ),
                commandWriteCompletedAtUnix: drainWrite.writeCompletedAtUnix,
                transportAuthority: transport
            )
            _ = try historicalFullDrainCoverageStore.arm(
                gap: gap,
                attempt: attempt,
                now: Date(timeIntervalSince1970: startAt)
            )
            activeFullDrainEventIdentity = .init(
                gapIdentifier: gap.gapIdentifier,
                attemptIdentifier: attempt.attemptIdentifier,
                peripheralIdentifier: peripheralIdentifier,
                strapIdentity: attempt.strapIdentity,
                transportNonce: nonce,
                transportGeneration: generation
            )
            gate4DailyBankFullDrainAuthorityIdentity =
                currentGate4DailyBankRearmIdentity(
                    generation: generation
                )
            AtriaDebugLog("ATRIADBG historical_full_drain_authority status=armed generation=%llu gap=%@ clock_seq=%d drain_seq=%d history_start_seq=%d",
                          generation,
                          gap.gapIdentifier,
                          Int(clockSequence),
                          Int(drainWrite.commandSequence),
                          Int(sequence))
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_drain_authority status=deferred generation=%llu reason=%@ raw_only=1 gap_retained=1",
                          generation,
                          String(describing: error))
        }
    }

    /// Once HISTORY_START arrives, the strap should emit a stream-5 row
    /// promptly. A deep flash selection may delay the start marker itself
    /// (handled by the separate 75-second serve-start wait), but a marker with
    /// no subsequent row is not an active drain. Release the radio after this
    /// bounded interval while retaining the exact gap and without ACK/abort.
    private func armHistoryFirstFrameWatchdogIfNeeded(generation: UInt64) {
        guard historyFirstFrameReceivedGeneration != generation,
              historyFirstFrameWatchdogTask == nil else { return }
        historyFirstFrameWatchdogTask = Task { @MainActor [weak self] in
            guard let self else { return }
            try? await Task.sleep(for: .seconds(self.historyFirstFrameTimeout))
            guard !Task.isCancelled,
                  self.offlineHistoricalSyncInProgress,
                  self.offlineHistoricalSyncGeneration == generation,
                  self.historyFirstFrameReceivedGeneration != generation else {
                return
            }
            let defaults = UserDefaults.standard
            defaults.set("history_first_frame_timeout",
                         forKey: OfflineSyncDefaults.handshakeStatus)
            defaults.set(Date().timeIntervalSince1970,
                         forKey: OfflineSyncDefaults.handshakeAt)
            if let gapFingerprint = self.offlineHistoricalSyncGapFingerprint {
                defaults.set(gapFingerprint,
                             forKey: OfflineSyncDefaults.historyStartTimeoutGapFingerprint)
                defaults.set(Date().timeIntervalSince1970,
                             forKey: OfflineSyncDefaults.historyStartTimeoutGapAt)
                defaults.set(Self.productionHistoryServeProfileVersion,
                             forKey: OfflineSyncDefaults.historyStartTimeoutProfileVersion)
            }
            AtriaDebugLog("ATRIADBG historyServe status=first_frame_timeout generation=%llu wait_s=%.0f action=rebuild_link_without_ack_or_abort_retain_gap",
                          generation,
                          self.historyFirstFrameTimeout)
            self.historyFirstFrameWatchdogTask = nil
            if self.finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: generation,
                reason: "history_first_frame_timeout_preserve_realtime"
            ) {
                return
            }
            if let peripheral = self.peripheral, peripheral.state == .connected {
                self.cancelPeripheralConnection(
                    peripheral,
                    reason: "history_first_frame_timeout_transport_reset"
                )
            } else {
                self.interruptOfflineHistoricalSyncForTransportLoss(
                    reason: "history_first_frame_timeout"
                )
            }
        }
    }

    private func handleHistoricalData(
        _ payload: [UInt8],
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        guard let generation = activeHistoricalGeneration(for: historyPhase) else {
            AtriaDebugLog("ATRIADBG historicalArchive status=ignored reason=inactive_or_stale_transport_phase")
            return
        }
        let exactRawAuthorityActive =
            activeConnectedRawHistoryCatchUpAuthority(
                generation: generation
            ) != nil
        if exactRawAuthorityActive, historicalAdmissionFailed {
            AtriaDebugLog(
                "ATRIADBG historicalArchive status=ignored reason=exact_raw_admission_already_failed generation=%llu action=finish_local_no_progress_keep_2a37",
                generation
            )
            _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: generation,
                reason: "exact_connected_raw_admission_failed"
            )
            return
        }
        let callbackCapturedCurrentServe = historyTransportPhaseFence.acceptsServe(
            historyPhase,
            generation: generation
        )
        let ingressAccepted = Self.shouldAcceptConnectedRawHistoryIngress(
            exactRawAuthorityActive: exactRawAuthorityActive,
            callbackCapturedCurrentServe: callbackCapturedCurrentServe,
            admissionAttemptAvailable: historicalAdmissionAttempt != nil
        )
        guard ingressAccepted else {
            AtriaDebugLog(
                "ATRIADBG historicalArchive status=ignored reason=pre_current_generation_serve generation=%llu action=no_spool_no_first_frame_no_admission_no_progress_keep_2a37",
                generation
            )
            return
        }
        cancelHistoricalPageContinuationForAcceptedCurrentServeFrameIfNeeded(
            generation: generation,
            ingressAccepted: ingressAccepted,
            callbackCapturedCurrentServe: callbackCapturedCurrentServe
        )
        recordResearchProbeCandidate(payload: payload, source: .historical)
        if historyFirstFrameReceivedGeneration != generation {
            historyFirstFrameReceivedGeneration = generation
            historyFirstFrameWatchdogTask?.cancel()
            historyFirstFrameWatchdogTask = nil
            UserDefaults.standard.set(
                "history_first_frame_received",
                forKey: OfflineSyncDefaults.handshakeStatus
            )
            UserDefaults.standard.set(
                Date().timeIntervalSince1970,
                forKey: OfflineSyncDefaults.handshakeAt
            )
            // Arm from the first real served frame, not request admission.
            // A fresh-owner cutover starts while the peripheral is temporarily
            // disconnected, so admission-time `connected` state is not a
            // reliable classifier. Every production drain must yield if it
            // starves live HR; attended Gate 2 and selector research retain
            // their explicit full-drain behavior.
            if !gate2FullDrainProofEnabled && !historySelectorSweepEnabled {
                armConnectedHistoricalSliceIfNeeded(
                    generation: generation,
                    reason: offlineHistoricalSyncReason,
                    connectedChunkedBackfill: true
                )
            }
            AtriaDebugLog("ATRIADBG historyServe status=first_frame generation=%llu action=continue_durable_drain",
                          generation)
        }
        if historicalDrainTelemetry.generation == generation {
            historicalDrainTelemetry.stream5Received += 1
            historicalDrainTelemetry.noteProgress()
        }
        guard !historicalAdmissionFailed else { return }
        let clock = historyClockRef
        let historyClockSyncEnabled = historyClockSyncEnabled
            || productionFullDrainClockAuthorityEnabled
        guard enqueueHistoricalIngress(.frame(
            payload: payload,
            clock: clock.map { .init(device: $0.device, wall: $0.wall) },
            clockAuthorityEnabled: historyClockSyncEnabled
        )) else { return }
        let callbackNow = Date()
        if auditHeartRateFromExactRawHistoryCallbackIfNeeded(
            generation: generation,
            historyPhase: historyPhase,
            now: callbackNow
        ) {
            return
        }
        if historicalDrainTelemetry.generation == generation {
            historicalDrainTelemetry.observePending(
                pendingHistoricalTransportEventCount + historyDrain.pendingPersistenceCount
            )
        }
        scheduleHistoricalTransportEventDrain()
        _ = releaseConnectedHistoricalSliceIfNeeded(
            generation: generation,
            reason: offlineHistoricalSyncReason,
            now: callbackNow
        )
    }

    /// A current-serve frame proves that the strap has already continued. This
    /// clears only the local silence fallback; it cannot ACK, advance/retire the
    /// ingress spool, mutate reducer durability, or touch either radio owner.
    private func cancelHistoricalPageContinuationForAcceptedCurrentServeFrameIfNeeded(
        generation: UInt64,
        ingressAccepted: Bool,
        callbackCapturedCurrentServe: Bool
    ) {
        guard Self.shouldCancelHistoricalPageContinuationForFrame(
            activeGeneration: historyDrain.generation,
            continuationGeneration: historicalPageContinuationGeneration,
            frameGeneration: generation,
            ingressAccepted: ingressAccepted,
            callbackCapturedCurrentServe: callbackCapturedCurrentServe
        ) else { return }
        historicalPageContinuationTask?.cancel()
        historicalPageContinuationTask = nil
        historicalPageContinuationGeneration = nil
        historicalPageContinuationBoundaryID = nil
        historicalPageContinuationHasFutureAttempt = false
        AtriaDebugLog(
            "ATRIADBG historyContinue status=cancelled generation=%llu reason=accepted_current_serve_frame action=keep_active_page_no_1600",
            generation
        )
    }

    private func scheduleHistoricalTransportEventDrain() {
        guard !historicalAdmissionBatchScheduled,
              !historicalAdmissionBatchInFlight,
              hasPendingHistoricalTransportEvents else { return }
        historicalAdmissionBatchScheduled = true
        Task { @MainActor [weak self] in
            // Coalesce one CoreBluetooth callback burst without allowing an
            // unbounded queue. Metadata remains an ordered barrier below.
            await Task.yield()
            guard let self else { return }
            self.historicalAdmissionBatchScheduled = false
            self.drainNextHistoricalTransportEventBurst()
        }
    }

    private func drainNextHistoricalTransportEventBurst() {
        guard !historicalAdmissionBatchInFlight,
              hasPendingHistoricalTransportEvents else { return }
        let exactRawAuthorityActive =
            activeConnectedRawHistoryCatchUpAuthority(
                generation: offlineHistoricalSyncGeneration
            ) != nil
        if exactRawAuthorityActive, historicalAdmissionFailed {
            _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: offlineHistoricalSyncGeneration,
                reason: "exact_connected_raw_admission_failed"
            )
            return
        }
        guard !historyACKGate.requiresHistoryCallbackDeferral else {
            AtriaDebugLog("ATRIADBG historyAdmission status=deferred reason=awaiting_ack_two_proofs generation=%llu buffered=%d action=preserve_order",
                          offlineHistoricalSyncGeneration,
                          pendingHistoricalTransportEventCount)
            return
        }
        guard let spool = historicalIngressSpool else {
            historicalAdmissionFailed = true
            historicalArchiveWriteFailures += 1
            return
        }
        let first: AtriaWhoop4HistoricalIngressSpool.Event
        let firstWasDeferred: Bool
        if let deferred = historicalIngressDeferredEvent {
            historicalIngressDeferredEvent = nil
            first = deferred
            firstWasDeferred = true
        } else {
            do {
                guard let peeked = try spool.peekFirst() else { return }
                first = peeked
            } catch {
                historicalAdmissionFailed = true
                historicalArchiveWriteFailures += 1
                AtriaDebugLog("ATRIADBG historyIngress status=failed generation=%llu reason=spool_read_failed error=%@ action=withhold_ack_retain_gap",
                              offlineHistoricalSyncGeneration, String(describing: error))
                return
            }
            firstWasDeferred = false
        }
        if exactRawAuthorityActive,
           case .frame = first,
           (historicalAdmissionLedger == nil
                || historicalAdmissionAttempt == nil) {
            // Do not pop this frame. A callback-captured serve token normally
            // makes this state unreachable, but if admission authority is
            // lost, preserve the unread suffix and release the exact shared
            // lane locally rather than latching a failure that stale END
            // markers can keep alive forever.
            AtriaDebugLog(
                "ATRIADBG historyAdmission status=failed reason=exact_raw_ledger_or_attempt_missing generation=%llu action=finish_local_preserve_unread_no_ack_no_disconnect_keep_2a37",
                offlineHistoricalSyncGeneration
            )
            historicalAdmissionFailed = true
            historicalArchiveWriteFailures += 1
            _ = finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: offlineHistoricalSyncGeneration,
                reason: "exact_connected_raw_admission_identity_missing"
            )
            return
        }
        if case let .metadata(payload, phaseGeneration) = first {
            if !firstWasDeferred {
                do { _ = try spool.popFirst() } catch {
                    historicalAdmissionFailed = true
                    historicalArchiveWriteFailures += 1
                    return
                }
            }
            processOrderedHistoryMetadata(
                payload,
                historyPhase: .init(generation: phaseGeneration)
            )
            scheduleHistoricalTransportEventDrain()
            return
        }
        // Stream5 metadata and historical data arrive on different
        // characteristics. Preserve data callbacks that were delivered just
        // after HISTORY_END while its archive fsync/ACK boundary is still in
        // flight. Once ACK acceptance returns the reducer to `.listening`,
        // `completeHistoricalACKAcceptance` releases this same ordered queue.
        // Feeding these frames immediately used to fail the entire drain as
        // `frame_received_after_batch_boundary` after otherwise healthy pages.
        guard historyDrain.canReceiveFrame else {
            AtriaDebugLog("ATRIADBG historyAdmission status=deferred reason=reducer_batch_boundary phase=%@ generation=%llu buffered=%d action=retain_until_ack",
                          historyDrain.phaseForDiagnostics,
                          offlineHistoricalSyncGeneration,
                          pendingHistoricalTransportEventCount)
            return
        }
        guard historyDrain.pendingPersistenceCount
                < Self.maximumHistoricalArchiveWorkInFlight else {
            // Archive completion schedules the next bounded spool batch.
            return
        }
        var frames: [PendingHistoricalFrameAdmission] = []
        let capacity = min(256, Self.maximumHistoricalArchiveWorkInFlight
            - historyDrain.pendingPersistenceCount)
        frames.reserveCapacity(capacity)
        if case let .frame(payload, clock, authority) = first {
            if !firstWasDeferred {
                do { _ = try spool.popFirst() } catch {
                    historicalAdmissionFailed = true
                    historicalArchiveWriteFailures += 1
                    return
                }
            }
            frames.append(.init(payload: payload,
                                generation: offlineHistoricalSyncGeneration,
                                clock: clock.map { .init(device: $0.device, wall: $0.wall) },
                                clockAuthorityEnabled: authority,
                                strapIdentifier: historicalIngressStrapIdentifier))
        }
        while frames.count < capacity, hasPendingHistoricalTransportEvents {
            let next: AtriaWhoop4HistoricalIngressSpool.Event
            do {
                guard let popped = try spool.popFirst() else { break }
                next = popped
            } catch {
                historicalAdmissionFailed = true
                historicalArchiveWriteFailures += 1
                return
            }
            guard case let .frame(payload, clock, authority) = next else {
                // Metadata is a strict barrier. It has already been removed
                // from the append-only file but remains represented by this
                // local event only for this MainActor turn.
                historicalIngressDeferredEvent = next
                break
            }
            frames.append(.init(payload: payload,
                                generation: offlineHistoricalSyncGeneration,
                                clock: clock.map { .init(device: $0.device, wall: $0.wall) },
                                clockAuthorityEnabled: authority,
                                strapIdentifier: historicalIngressStrapIdentifier))
        }
        guard !frames.isEmpty,
              let admissionLedger = historicalAdmissionLedger,
              let admissionAttempt = historicalAdmissionAttempt else {
            historicalAdmissionFailed = true
            historicalArchiveWriteFailures += 1
            AtriaDebugLog("ATRIADBG historyAdmission status=failed reason=ledger_or_attempt_missing action=withhold_reducer_and_ack")
            return
        }
        historicalAdmissionBatchInFlight = true
        historicalArchiveQueue.async { [weak self] in
            let result: Result<[AtriaWhoop4HistoryAdmissionLedger.Classification], Error>
            do {
                result = .success(try admissionLedger.classify(
                    frames: frames.map { Data($0.payload) },
                    attempt: admissionAttempt
                ))
            } catch {
                result = .failure(error)
            }
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.historicalAdmissionBatchInFlight = false
                switch result {
                case .success(let classifications):
                    guard classifications.count == frames.count else {
                        self.historicalAdmissionFailed = true
                        self.historicalArchiveWriteFailures += 1
                        return
                    }
                    for (frame, classification) in zip(frames, classifications) {
                        self.historicalAdmissionHighestOrdinal = max(
                            self.historicalAdmissionHighestOrdinal ?? 0,
                            classification.ordinal
                        )
                        self.processAdmittedHistoricalFrame(
                            frame,
                            classification: classification
                        )
                    }
                case .failure(let error):
                    self.historicalAdmissionFailed = true
                    self.historicalArchiveWriteFailures += 1
                    AtriaDebugLog("ATRIADBG historyAdmission status=failed reason=%@ action=withhold_reducer_and_ack",
                                  String(describing: error))
                }
                self.scheduleHistoricalTransportEventDrain()
            }
        }
    }

    private func processAdmittedHistoricalFrame(
        _ frame: PendingHistoricalFrameAdmission,
        classification: AtriaWhoop4HistoryAdmissionLedger.Classification
    ) {
        let payload = frame.payload
        let generation = frame.generation
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else { return }
        if historicalDrainTelemetry.generation == generation {
            historicalDrainTelemetry.admitted += 1
            historicalDrainTelemetry.noteProgress()
        }
        // The exact validated payload is a stable replay identity: WHOOP history
        // records include their device timestamp/counter, and the outer frame's
        // CRC has already been verified before this method is reached. Keeping
        // the full key avoids hash-collision data loss at the drain boundary.
        let frameKey = Self.hex(payload)
        let priorContinuity = historyDrain.continuitySnapshot
        let effects = historyDrain.receiveFrame(
            generation: generation,
            frameKey: frameKey,
            payload: payload,
            admission: classification.reducerAdmission,
            // A confirmed production full drain may keep raw pages across an
            // inner record-counter discontinuity. That UInt16 is not a BLE
            // packet sequence; a full coverage authority is deliberately not
            // required for raw retention because timestamp/cadence proof still
            // exclusively decides whether a selected gap is resolved.
            permitsUnconfirmedForwardDiscontinuity:
                Self.permitsRawFullDrainForwardDiscontinuity(
                    fullDrainWriteConfirmed:
                        historicalFullDrainWriteEvidence?.transportGeneration
                            == generation,
                    historyStartReceived: acceptedHistoryStartSequence != nil
                )
        )
        persistHistorySequenceContinuityIfChanged(from: priorContinuity)
        guard effects.contains(where: { effect in
            if case .persistFrame = effect { return true }
            return false
        }) else {
            processHistoricalDrainEffects(effects)
            AtriaDebugLog("ATRIADBG historicalArchive status=ignored reason=duplicate_or_out_of_phase generation=%llu", generation)
            return
        }
        // Capture the admission authority on the main actor before crossing to
        // the serial archive queue. The queue owns persistence order, while
        // the captured attempt remains immutable for this generation.
        let checkpointCoordinator = historicalCheckpointCoordinator
        let checkpointLedger = historicalAdmissionLedger
        let checkpointAttempt = historicalAdmissionAttempt
        historicalArchiveQueue.async { [weak self] in
            let pipelineClock = frame.clock.map {
                AtriaWhoop4HistoryArchivePipeline.ClockReference(
                    device: $0.device,
                    wall: $0.wall,
                    driftSeconds: $0.driftSeconds,
                    snappedDriftSeconds: $0.snappedDriftSeconds
                )
            }
            let computation = AtriaWhoop4HistoryArchivePipeline.prepare(
                payload: payload,
                clock: pipelineClock,
                historyClockSyncEnabled: frame.clockAuthorityEnabled
            )
            let decoded: Bool
            if case .record = computation.payload {
                decoded = true
            } else {
                decoded = false
            }
            if let logMessage = computation.logMessage {
                AtriaDebugLog("%@", logMessage)
            }
            let persistence = AtriaWhoop4HistoryArchivePipeline.persist(
                computation,
                strapIdentifier: frame.strapIdentifier,
                generation: generation
            )
            var checkpointErrorDescription: String?
            if let checkpoint = checkpointCoordinator.recordPersistence(
                    generation: generation,
                    ordinal: classification.ordinal,
                    succeeded: persistence.succeeded
                ) {
                do {
                    guard let admissionLedger = checkpointLedger,
                          let admissionAttempt = checkpointAttempt,
                          admissionAttempt.strapIdentifier == frame.strapIdentifier,
                          let archiveReceipt = try HistoricalArchive
                            .synchronizeDurableStorage(generation: generation),
                          archiveReceipt.isPromotionAuthority else {
                        throw AtriaBLEHistoryTerminalMaterializationError
                            .admissionIdentityNotDurable
                    }
                    _ = try admissionLedger.markCurrentPrefixArchiveDurableWithReceipt(
                        attempt: admissionAttempt,
                        through: checkpoint.throughOrdinal,
                        archiveReceipt: archiveReceipt
                    )
                    // Long WHOOP history serves can run for tens of minutes.
                    // The compact v24 shard is populated beside every accepted
                    // raw row, so publish it at this existing bounded
                    // durability checkpoint instead of withholding stronger
                    // all-day step receipts until the terminal frame. This
                    // derived cache never grants ACK or gap-coverage authority;
                    // a failed compact fsync leaves the canonical checkpoint
                    // valid and is retried at the next checkpoint/terminal.
                    do {
                        try AtriaWhoop4MotionTickCompactStore.shared
                            .synchronize()
                    } catch {
                        AtriaDebugLog(
                            "ATRIADBG whoop4_motion_compact status=checkpoint_flush_failed generation=%llu through_ordinal=%llu error=%@ action=retain_raw_checkpoint_retry_compact_later",
                            generation,
                            checkpoint.throughOrdinal,
                            String(describing: error)
                        )
                    }
                    checkpointCoordinator.checkpointCompleted(
                        generation: generation,
                        succeeded: true
                    )
                    AtriaDebugLog("ATRIADBG historyCheckpoint status=durable generation=%llu through_ordinal=%llu sequence=%llu action=continue_without_ack",
                                  generation,
                                  checkpoint.throughOrdinal,
                                  archiveReceipt.durableSequence)
                } catch {
                    checkpointErrorDescription = String(describing: error)
                    checkpointCoordinator.checkpointCompleted(
                        generation: generation,
                        succeeded: false
                    )
                    AtriaDebugLog("ATRIADBG historyCheckpoint status=failed generation=%llu through_ordinal=%llu error=%@ action=withhold_terminal_ack_retain_gap",
                                  generation,
                                  checkpoint.throughOrdinal,
                                  checkpointErrorDescription ?? "unknown")
                }
            }
            Task { @MainActor [weak self] in
                self?.applyHistoricalArchivePersistenceResult(
                    persistence,
                    generation: generation,
                    frameKey: frameKey,
                    decoded: decoded,
                    checkpointErrorDescription: checkpointErrorDescription
                )
            }
        }
    }

    /// Persist the small cross-generation discontinuity proof only when the
    /// reducer snapshot actually changes. Contiguous frames pay one value
    /// comparison and perform no store I/O. The rare permitted full-drain jump
    /// must save before its page ACK, while failure/ACK/terminal edges below
    /// provide explicit barriers and retry a previously failed save.
    private func persistHistorySequenceContinuityIfChanged(
        from prior: AtriaWhoop4HistoryDrainState.ContinuitySnapshot
    ) {
        guard historyDrain.continuitySnapshot != prior else { return }
        persistHistorySequenceContinuityAtBoundary()
    }

    private func persistHistorySequenceContinuityAtBoundary() {
        let current = historyDrain.continuitySnapshot
        guard current != lastPersistedHistorySequenceContinuitySnapshot else {
            return
        }
        do {
            if current.pending == nil, current.confirmed.isEmpty {
                try historySequenceContinuityStore.clear()
            } else {
                guard let strapIdentifier =
                        historySequenceContinuityStrapIdentifier else { return }
                try historySequenceContinuityStore.save(
                    current,
                    strapIdentifier: strapIdentifier
                )
            }
            lastPersistedHistorySequenceContinuitySnapshot = current
        } catch {
            // Durable replay evidence is an optimization only. Failure to save
            // never relaxes the live reducer's fail-closed sequence policy.
            AtriaDebugLog("ATRIADBG historyDrain status=continuity_persist_failed error=%@ action=retain_in_memory_fail_closed",
                          String(describing: error))
        }
    }

    private func prepareHistorySequenceContinuity(for strapIdentifier: String?) {
        guard let strapIdentifier,
              UUID(uuidString: strapIdentifier)?.uuidString == strapIdentifier else {
            historyDrain = AtriaWhoop4HistoryDrainState()
            historySequenceContinuityStrapIdentifier = nil
            lastPersistedHistorySequenceContinuitySnapshot = nil
            return
        }
        guard strapIdentifier != historySequenceContinuityStrapIdentifier else { return }
        historyDrain = AtriaWhoop4HistoryDrainState()
        historySequenceContinuityStrapIdentifier = strapIdentifier
        lastPersistedHistorySequenceContinuitySnapshot = nil
        guard let continuity = historySequenceContinuityStore.load(
            strapIdentifier: strapIdentifier
        ) else { return }
        if !historyDrain.restoreContinuitySnapshot(continuity) {
            try? historySequenceContinuityStore.clear()
            AtriaDebugLog("ATRIADBG historyDrain status=continuity_restore_rejected strap=%@ action=clear_fail_closed",
                          strapIdentifier)
        } else {
            lastPersistedHistorySequenceContinuitySnapshot = continuity
        }
    }

    private func applyHistoricalArchivePersistenceResult(
        _ result: AtriaWhoop4HistoryArchivePipeline.PersistenceResult,
                                                         generation: UInt64,
                                                         frameKey: String,
                                                         decoded: Bool,
                                                         checkpointErrorDescription: String? = nil) {
        guard offlineHistoricalSyncInProgress,
              historyDrain.generation == generation else {
            HistoricalArchive.endDurableDrain(generation: generation)
            AtriaDebugLog("ATRIADBG historicalArchive status=ignored reason=stale_persistence_callback callback_generation=%llu current_generation=%llu",
                          generation,
                          historyDrain.generation ?? 0)
            return
        }
        let drainEffects = historyDrain.persistenceCompleted(
            generation: generation,
            frameKey: frameKey,
            succeeded: result.succeeded
        )
        if historicalDrainTelemetry.generation == generation {
            if decoded {
                historicalDrainTelemetry.decoded += 1
            } else {
                historicalDrainTelemetry.decodeErrors += 1
            }
            if result.succeeded {
                historicalDrainTelemetry.persisted += 1
                historicalDrainTelemetry.noteProgress()
            } else {
                historicalDrainTelemetry.persistErrors += 1
            }
            historicalDrainTelemetry.observePending(
                pendingHistoricalTransportEventCount + historyDrain.pendingPersistenceCount
            )
        }
        if result.succeeded {
            if let checkpointErrorDescription {
                historicalAdmissionFailed = true
                historicalArchiveWriteFailures += 1
                AtriaDebugLog("ATRIADBG historyCheckpoint status=failed generation=%llu error=%@ action=withhold_ack_retain_gap",
                              generation,
                              checkpointErrorDescription)
            }
            if Self.historicalFrameRenewsIdleLease(
                persistenceSucceeded: result.succeeded,
                insertedNewFrame: result.inserted
            ) {
                noteOfflineHistoricalSyncProgress(
                    generation: generation,
                    reason: "archive_inserted_new_frame"
                )
            }
            if result.inserted {
                historicalArchiveRows += 1
                historicalArchiveRowsSinceAck += 1
                publishHistoricalRecoveryProgressIfNeeded()
            }
            // Appending a row is not durability. Hold metric evidence behind
            // the reducer's fsync boundary so a crash or disconnect cannot
            // retire a missing interval before the matching ACK is safe.
            historicalMetricDurabilityFence.recordPersistedMetric(
                generation: generation,
                metricUsable: result.metricUsable,
                effectiveUnix: result.effectiveUnix
            )
            if pendingHistoricalRawFrontierGeneration == generation,
               let effectiveUnix = result.effectiveUnix,
               effectiveUnix > 0 {
                pendingHistoricalRawFrontierUnix = max(
                    pendingHistoricalRawFrontierUnix ?? 0,
                    effectiveUnix
                )
            }
            lastHistoricalArchivePath = result.persistedPath.isEmpty ? HistoricalArchive.relativePath : result.persistedPath
            if result.archivedUndecodable {
                AtriaDebugLog("ATRIADBG historicalArchive status=archived_undecodable reason=%@ rows=%d rows_since_ack=%d failures=%d path=%@",
                      result.reason ?? "unknown",
                      historicalArchiveRows,
                      historicalArchiveRowsSinceAck,
                      historicalArchiveWriteFailures,
                      result.persistedPath)
            } else if historicalArchiveRows == 1 || historicalArchiveRows.isMultiple(of: 500) {
                AtriaDebugLog("ATRIADBG historicalArchive status=ok rows=%d rows_since_ack=%d failures=%d layout=%@ metric_usable=%d current_session_usable=%d path=%@",
                      historicalArchiveRows,
                      historicalArchiveRowsSinceAck,
                      historicalArchiveWriteFailures,
                      HistoricalArchive.layoutVersion,
                      result.metricUsable ? 1 : 0,
                      result.currentSessionUsable ? 1 : 0,
                      result.persistedPath)
            }
            processHistoricalDrainEffects(drainEffects)
            scheduleHistoricalTransportEventDrain()
            return
        }

        historicalArchiveWriteFailures += 1
        AtriaDebugLog("ATRIADBG historicalArchive status=error rows=%d rows_since_ack=%d failures=%d error=%@ action=skip_future_history_ack path=%@",
              historicalArchiveRows,
              historicalArchiveRowsSinceAck,
              historicalArchiveWriteFailures,
              result.errorDescription ?? "unknown",
              HistoricalArchive.relativePath)
        processHistoricalDrainEffects(drainEffects)
        scheduleHistoricalTransportEventDrain()
    }

    private func commitDurableHistoricalMetricFacts(
        _ facts: [AtriaHistoricalMetricDurabilityFence.Fact],
        generation: UInt64
    ) {
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else { return }
        let defaults = UserDefaults.standard
        let requestedStart = defaults.double(
            forKey: OfflineSyncDefaults.recoveryWindowStart
        )
        let requestedEnd = defaults.double(
            forKey: OfflineSyncDefaults.recoveryWindowEnd
        )
        let factDates = facts.map {
            Date(timeIntervalSince1970: TimeInterval($0.effectiveUnix))
        }
        let gapResult: AtriaHistoricalGapLedger.MetricRowResult
        if let selectedFullDrainGap {
            if activeFullDrainEventIdentity?.transportGeneration == generation {
                gapResult = AtriaHistoricalGapLedger.stageMetricUsableRows(
                    at: factDates,
                    forWindowID: selectedFullDrainGap.window.id
                )
            } else {
                gapResult = .init(matchedWindows: 0,
                                  resolvedWindows: 0,
                                  remainingWindows: AtriaHistoricalGapLedger.windows().count)
                AtriaDebugLog("ATRIADBG offline_sync status=metric_rows_withheld generation=%llu reason=full_drain_authority_inactive selected_gap=%@ raw_retained=1",
                              generation,
                              selectedFullDrainGap.window.id.uuidString)
            }
        } else if activeHistoricalRequestBinding != nil {
            gapResult = AtriaHistoricalGapLedger.recordMetricUsableRows(
                at: factDates
            )
        } else {
            gapResult = .init(matchedWindows: 0,
                              resolvedWindows: 0,
                              remainingWindows: AtriaHistoricalGapLedger.windows().count)
        }
        if gapResult.matchedWindows > 0 {
            AtriaDebugLog("ATRIADBG offline_sync status=missing_window_metric_batch_durable facts=%d matched_windows=%d resolved=%d remaining=%d generation=%llu",
                          facts.count,
                          gapResult.matchedWindows,
                          gapResult.resolvedWindows,
                          gapResult.remainingWindows,
                          generation)
        }
        if gapResult.resolvedWindows > 0,
           activeFullDrainEventIdentity == nil {
            offlineHistoricalSyncResolvedGapCoverage = true
        }
        for fact in facts {
            if Self.requestedRecoveryRowProvidesMetricProgress(
                metricUsable: true,
                effectiveUnix: fact.effectiveUnix,
                requestedStart: requestedStart,
                requestedEnd: requestedEnd
            ) {
                offlineHistoricalSyncMadeRequestedMetricProgress = true
            }
        }
    }

    private func commitDurableHistoricalRawFrontier(
        effectiveUnix: UInt32,
        generation: UInt64,
        now: Date = Date()
    ) {
        guard offlineHistoricalSyncInProgress,
              generation == offlineHistoricalSyncGeneration else { return }
        let defaults = UserDefaults.standard
        let existing = defaults.double(
            forKey: OfflineSyncDefaults.drainedThroughUnix
        )
        guard let advanced = Self.advancedDurableHistoricalFrontier(
            existing: existing,
            durableEffectiveUnix: [effectiveUnix],
            now: now
        ) else { return }
        defaults.set(advanced, forKey: OfflineSyncDefaults.drainedThroughUnix)
        AtriaDebugLog(
            "ATRIADBG offline_sync status=durable_frontier_advanced generation=%llu from_unix=%.0f through_unix=%.0f authority=canonical_flush_generation_fence",
            generation,
            existing,
            advanced
        )
    }

    private func processHistoricalDrainEffects(
        _ effects: [AtriaWhoop4HistoryDrainState.Effect]
    ) {
        for effect in effects {
            switch effect {
            case .persistFrame:
                // `handleHistoricalData` owns the asynchronous archive write so
                // it can carry the decoded metrics result back with this key.
                continue

            case .durableFlush(let generation, let boundary):
                guard offlineHistoricalSyncInProgress,
                      historyDrain.generation == generation,
                      !historyDurableFlushInFlight else { continue }
                if historicalDrainTelemetry.generation == generation {
                    historicalDrainTelemetry.flushStarted += 1
                    historicalDrainTelemetry.observePending(
                        pendingHistoricalTransportEventCount
                            + historyDrain.pendingPersistenceCount
                    )
                }
                historyDurableFlushInFlight = true
                let admissionFailed = historicalAdmissionFailed
                let admissionLedger = historicalAdmissionLedger
                let admissionAttempt = historicalAdmissionAttempt
                let admissionHighestOrdinal = historicalAdmissionHighestOrdinal
                let admissionReconciliationClock = historyClockRef.map {
                    AtriaWhoop4HistoryArchivePipeline.ClockReference(
                        device: $0.device,
                        wall: $0.wall,
                        driftSeconds: $0.driftSeconds,
                        snappedDriftSeconds: $0.snappedDriftSeconds
                    )
                }
                let admissionReconciliationClockEnabled = historyClockSyncEnabled
                    || productionFullDrainClockAuthorityEnabled
                let fullDrainIdentity = activeFullDrainEventIdentity
                let fullDrainCoverageStore = historicalFullDrainCoverageStore
                let boundaryID: String? = {
                    if case .batch(let identifier) = boundary { return identifier }
                    return nil
                }()
                let historyEndPayload = boundaryID.flatMap {
                    fullDrainHistoryEndPayloads[$0]
                }
                let expectedACKPayload = boundaryID.flatMap { identifier in
                    pendingHistoryEndACK?.key == identifier
                        ? pendingHistoryEndACK.map { Data($0.payload) } : nil
                }
                historicalArchiveQueue.async { [weak self] in
                    let error: Error?
                    var authorityResult: FullDrainFlushAuthorityResult?
                    do {
                        if let ledger = admissionLedger,
                           let attempt = admissionAttempt,
                           let ordinal = admissionHighestOrdinal {
                            let pendingFrames = try ledger.pendingFrames(
                                attempt: attempt,
                                through: ordinal
                            )
                            try HistoricalArchive.includeExistingAdmissionFramesInDurableBatch(
                                payloads: pendingFrames,
                                strapIdentifier: attempt.strapIdentifier,
                                generation: generation,
                                clock: admissionReconciliationClock,
                                historyClockSyncEnabled: admissionReconciliationClockEnabled
                            )
                        }
                        guard let archiveReceipt = try HistoricalArchive
                            .synchronizeDurableStorage(
                            generation: generation
                        ), archiveReceipt.isPromotionAuthority else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .admissionIdentityNotDurable
                        }
                        // The compact v24 shard is a derived background
                        // projection cache, never ACK authority. Flush it at
                        // the canonical raw boundary so a later locked-state
                        // ticket verifier sees every point admitted by this
                        // generation. Failure deliberately leaves the motion
                        // ticket pending without invalidating raw history.
                        do {
                            try AtriaWhoop4MotionTickCompactStore.shared
                                .synchronize()
                        } catch {
                            AtriaDebugLog(
                                "ATRIADBG whoop4_motion_compact status=flush_failed generation=%llu error=%@ action=retain_motion_ticket_raw_archive_still_durable",
                                generation,
                                String(describing: error)
                            )
                        }
                        guard !admissionFailed,
                              let ledger = admissionLedger,
                              let attempt = admissionAttempt else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .admissionIdentityNotDurable
                        }
                        let admission: AtriaWhoop4HistoryAdmissionLedger
                            .PrefixDurabilityReceipt
                        if let ordinal = admissionHighestOrdinal {
                            admission = try ledger
                                .markCurrentPrefixArchiveDurableWithReceipt(
                                attempt: attempt,
                                through: ordinal,
                                archiveReceipt: archiveReceipt
                            ).receipt
                        } else {
                            admission = try ledger
                                .recordEmptyArchiveDurabilityBoundary(
                                    attempt: attempt,
                                    archiveReceipt: archiveReceipt
                                )
                        }
                        let stores = AtriaHistoricalFullDrainCoveragePolicy.DurableStorePair(
                            raw: .init(
                                storeIdentifier: archiveReceipt.raw.storeIdentifier,
                                snapshotSHA256: archiveReceipt.raw.snapshotSHA256,
                                durableSequence: archiveReceipt.raw.durableSequence,
                                batchKeysSHA256: archiveReceipt.raw.batchKeysSHA256,
                                byteCount: archiveReceipt.raw.byteCount,
                                recordCount: archiveReceipt.raw.recordCount,
                                observedIdentityCount: archiveReceipt.raw.observedIdentityCount,
                                fsyncedAtUnix: archiveReceipt.raw.fsyncedAtUnix
                            ),
                            identity: .init(
                                storeIdentifier: archiveReceipt.identity.storeIdentifier,
                                snapshotSHA256: archiveReceipt.identity.snapshotSHA256,
                                durableSequence: archiveReceipt.identity.durableSequence,
                                batchKeysSHA256: archiveReceipt.identity.batchKeysSHA256,
                                byteCount: archiveReceipt.identity.byteCount,
                                recordCount: archiveReceipt.identity.recordCount,
                                observedIdentityCount: archiveReceipt.identity.observedIdentityCount,
                                fsyncedAtUnix: archiveReceipt.identity.fsyncedAtUnix
                            ),
                            admission: .init(
                                storeIdentifier: admission.storeIdentifier,
                                snapshotSHA256: admission.snapshotSHA256,
                                durableSequence: admission.durableSequence,
                                batchKeysSHA256: admission.snapshotSHA256,
                                byteCount: admission.byteCount,
                                recordCount: admission.recordCount,
                                observedIdentityCount: admission.recordCount,
                                fsyncedAtUnix: admission.fsyncedAtUnix
                            ),
                            admissionReceipt: admission
                        )
                        var permit: AtriaHistoricalFullDrainCoverageStore.ACKPermit?
                        if let fullDrainIdentity, let boundaryID {
                            guard let historyEndPayload,
                                  let expectedACKPayload else {
                                throw AtriaBLEHistoryTerminalMaterializationError
                                    .admissionIdentityNotDurable
                            }
                            permit = try fullDrainCoverageStore
                                .recordHistoryEndFsynced(
                                    identity: fullDrainIdentity,
                                    boundaryIdentifier: boundaryID,
                                    historyEndPayload: Data(historyEndPayload),
                                    expectedACKPayload: expectedACKPayload,
                                    stores: stores,
                                    fsyncedAt: Date(timeIntervalSince1970: max(
                                        stores.raw.fsyncedAtUnix,
                                        stores.identity.fsyncedAtUnix,
                                        stores.admission.fsyncedAtUnix
                                    ))
                                )
                        }
                        authorityResult = .init(stores: stores,
                                                boundaryID: boundaryID,
                                                permit: permit)
                        error = nil
                    } catch let caught {
                        error = caught
                    }
                    Task { @MainActor [weak self] in
                        guard let self else {
                            HistoricalArchive.endDurableDrain(generation: generation)
                            return
                        }
                        guard self.offlineHistoricalSyncInProgress,
                              self.historyDrain.generation == generation else {
                            HistoricalArchive.endDurableDrain(generation: generation)
                            return
                        }
                        self.historyDurableFlushInFlight = false
                        if self.historicalDrainTelemetry.generation == generation {
                            if error == nil {
                                self.historicalDrainTelemetry.flushSucceeded += 1
                                self.historicalDrainTelemetry.noteProgress()
                            } else {
                                self.historicalDrainTelemetry.flushErrors += 1
                            }
                            self.historicalDrainTelemetry.observePending(
                                self.pendingHistoricalTransportEventCount
                                    + self.historyDrain.pendingPersistenceCount
                            )
                        }
                        if let authorityResult {
                            self.latestFullDrainDurableStores = authorityResult.stores
                            if let boundaryID = authorityResult.boundaryID,
                               let permit = authorityResult.permit {
                                self.fullDrainACKPermits[boundaryID] = permit
                            }
                        }
                        if error == nil {
                            // This diagnostic is a last-failure value, not a
                            // permanent health verdict. Clear it only after a
                            // later successful durable boundary so an old,
                            // repaired archive fault cannot make a healthy
                            // current drain appear broken.
                            let defaults = UserDefaults.standard
                            defaults.removeObject(forKey: OfflineSyncDefaults.lastDurableFlushError)
                            defaults.removeObject(forKey: OfflineSyncDefaults.lastDurableFlushErrorAt)
                            // Truthful success-path progress signal (see schema note);
                            // the boundary field above only records the last error.
                            defaults.set(Date().timeIntervalSince1970,
                                         forKey: OfflineSyncDefaults.lastDurableFlushBoundaryOKAt)
                            self.noteOfflineHistoricalSyncProgress(
                                generation: generation,
                                reason: "durable_flush",
                                advancesDurableConnectedSliceHold: true
                            )
                        }
                        if let error {
                            self.historicalArchiveWriteFailures += 1
                            let defaults = UserDefaults.standard
                            defaults.set(String(reflecting: error),
                                         forKey: OfflineSyncDefaults.lastDurableFlushError)
                            defaults.set(Date().timeIntervalSince1970,
                                         forKey: OfflineSyncDefaults.lastDurableFlushErrorAt)
                            defaults.set(String(describing: boundary),
                                         forKey: OfflineSyncDefaults.lastDurableFlushBoundary)
                        }
                        AtriaDebugLog("ATRIADBG historyDrain status=%@ generation=%llu boundary=%@ rows_since_ack=%d error=%@",
                                      error == nil ? "durable" : "flush_failed",
                                      generation,
                                      String(describing: boundary),
                                      self.historicalArchiveRowsSinceAck,
                                      error.map(String.init(describing:)) ?? "nil")
                        let durableMetricFacts = self.historicalMetricDurabilityFence
                            .durableFlushCompleted(
                                generation: generation,
                                succeeded: error == nil
                            )
                        if error == nil {
                            if self.pendingHistoricalRawFrontierGeneration
                                    == generation,
                               let rawFrontier = self
                                    .pendingHistoricalRawFrontierUnix {
                                self.commitDurableHistoricalRawFrontier(
                                    effectiveUnix: rawFrontier,
                                    generation: generation
                                )
                            }
                            self.pendingHistoricalRawFrontierUnix = nil
                            self.commitDurableHistoricalMetricFacts(
                                durableMetricFacts,
                                generation: generation
                            )
                        }
                        let next = self.historyDrain.durableFlushCompleted(
                            generation: generation,
                            boundary: boundary,
                            succeeded: error == nil
                        )
                        self.processHistoricalDrainEffects(next)
                    }
                }

            case .sendACK(let generation, let boundaryID, let payload, let attempt):
                guard offlineHistoricalSyncInProgress,
                      historyDrain.generation == generation else { continue }
                if activeFullDrainEventIdentity?.transportGeneration == generation {
                    guard let permit = fullDrainACKPermits[boundaryID],
                          permit.boundaryIdentifier == boundaryID else {
                        historicalArchiveWriteFailures += 1
                        AtriaDebugLog("ATRIADBG historyAck status=withheld key=%@ generation=%llu reason=full_drain_durable_permit_missing gap_retained=1",
                                      boundaryID,
                                      generation)
                        continue
                    }
                }
                pendingHistoryEndACK = (boundaryID, payload)
                pendingHistoryACKAttempts = attempt
                guard txCharacteristic != nil else {
                    peripheral?.discoverServices(discoveryServicesForCurrentMode)
                    AtriaDebugLog("ATRIADBG historyAck status=write_failed key=%@ generation=%llu attempt=%d reason=tx_missing",
                                  boundaryID, generation, attempt)
                    pendingHistoryEndACK = nil
                    retryHistoricalACKAfterFailure(
                        generation: generation,
                        boundaryID: boundaryID
                    )
                    continue
                }
                AtriaDebugLog("ATRIADBG historyAck status=sending key=%@ generation=%llu attempt=%d payload=%@ write_mode=wr",
                              boundaryID,
                              generation,
                              attempt,
                              Self.hex(payload))
                let commandSequence = cmdSeq
                if sendCommand(Cmd.historicalDataResult, payload, mode: .withResponse) {
                    if historicalDrainTelemetry.generation == generation {
                        historicalDrainTelemetry.ackSent += 1
                    }
                    historyACKGate.arm(.init(
                        generation: generation,
                        boundaryID: boundaryID,
                        commandSequence: commandSequence,
                        attempt: attempt
                    ))
                } else {
                    pendingHistoryEndACK = nil
                    retryHistoricalACKAfterFailure(
                        generation: generation,
                        boundaryID: boundaryID
                    )
                }

            case .finished(let generation):
                guard offlineHistoricalSyncInProgress,
                      historyDrain.generation == generation else { continue }
                // A terminal tail without HISTORY_END has no ACK callback. Its
                // successful durable flush is the equivalent reducer boundary.
                persistHistorySequenceContinuityAtBoundary()
                offlineHistoricalSyncReachedTerminal = historyDrain.terminalWasReceived
                let fullDrainTerminalReady = finalizeFullDrainTerminalAuthority(
                    generation: generation
                )
                let durableTerminalReady = self.latestFullDrainDurableStores?.isValid == true
                    && (self.activeFullDrainEventIdentity == nil || fullDrainTerminalReady)
                if durableTerminalReady {
                    self.durableTerminalAuthorityGeneration = generation
                }
                // Enqueue completion/pruning only after terminal enumeration
                // has been enqueued on the same archive queue. Otherwise a
                // 13-day attempt can be pruned before exact coverage proof.
                if activeFullDrainEventIdentity == nil || fullDrainTerminalReady {
                    finishHistoricalAdmissionAttempt(succeeded: true,
                                                     generation: generation)
                } else {
                    AtriaDebugLog("ATRIADBG historyAdmission status=retained generation=%llu reason=full_drain_terminal_checkpoint_missing action=resume_exact_attempt",
                                  generation)
                }
                if fullDrainTerminalReady {
                    AtriaDebugLog("ATRIADBG historical_full_drain_publish status=withheld generation=%llu reason=awaiting_post_history_fresh_hr gap_retained=1",
                                  generation)
                }
                if let peripheralID = peripheral?.identifier.uuidString {
                    UserDefaults.standard.set(
                        peripheralID,
                        forKey: OfflineSyncDefaults.verifiedHistoryPeripheralID
                    )
                }
                finishOfflineHistoricalSync(
                    reason: "\(offlineHistoricalSyncReason)_terminal",
                    generation: generation
                )
                HistoricalArchive.endDurableDrain(generation: generation)

            case .failed(let generation, let failure):
                guard offlineHistoricalSyncInProgress,
                      historyDrain.generation == generation else { continue }
                // Preserve a newly observed forward-discontinuity candidate
                // immediately. Without this rare failure-edge write, repeated
                // process termination could make every replay look like its
                // first observation and fail forever.
                persistHistorySequenceContinuityAtBoundary()
                let needsSequenceConfirmationRetry: Bool = {
                    guard case .protocolViolation(let detail) = failure else {
                        return false
                    }
                    return detail.hasPrefix(
                        "history_sequence_gap_unconfirmed_previous_"
                    )
                }()
                let failedReason = offlineHistoricalSyncReason
                offlineHistoricalSyncReachedTerminal = false
                finishHistoricalAdmissionAttempt(succeeded: false,
                                                 generation: generation)
                let defaults = UserDefaults.standard
                defaults.set(String(describing: failure),
                             forKey: OfflineSyncDefaults.lastDrainFailure)
                defaults.set(Date().timeIntervalSince1970,
                             forKey: OfflineSyncDefaults.lastDrainFailureAt)
                defaults.set(generation,
                             forKey: OfflineSyncDefaults.lastDrainFailureGeneration)
                defaults.set(historyDrain.failureOriginPhaseForDiagnostics
                                ?? historyDrain.phaseForDiagnostics,
                             forKey: OfflineSyncDefaults.lastDrainFailurePhase)
                defaults.set(historyDrain.pendingPersistenceCount,
                             forKey: OfflineSyncDefaults.lastDrainFailurePendingPersistence)
                defaults.set(historyDrain.persistedFrameCount,
                             forKey: OfflineSyncDefaults.lastDrainFailurePersistedFrames)
                defaults.set(historyDrain.acknowledgedBatchCount,
                             forKey: OfflineSyncDefaults.lastDrainFailureAcknowledgedBatches)
                if case .protocolViolation(let violationDetail) = failure,
                   Self.isHistorySequenceGapFailureDetail(violationDetail) {
                    registerHistorySequenceGapDrainFailure(
                        detail: violationDetail
                    )
                }
                AtriaDebugLog("ATRIADBG historyDrain status=failed generation=%llu failure=%@ action=rebuild_link_without_ack_or_abort_retain_gap",
                              generation,
                              String(describing: failure))
                let preservedRealtimeOwner =
                    finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                        generation: generation,
                        reason: "history_drain_failed_preserve_realtime"
                    )
                if !preservedRealtimeOwner,
                   let failedPeripheral = peripheral,
                   failedPeripheral.state == .connected {
                    cancelPeripheralConnection(
                        failedPeripheral,
                        reason: "history_drain_failed_transport_reset"
                    )
                } else if !preservedRealtimeOwner {
                    finishOfflineHistoricalSync(
                        reason: "\(offlineHistoricalSyncReason)_drain_failed",
                        generation: generation
                    )
                }
                if needsSequenceConfirmationRetry && !preservedRealtimeOwner
                    && !historySequenceGapIsParked(defaults) {
                    scheduleHistorySequenceConfirmationRetry(
                        failedGeneration: generation,
                        reason: failedReason
                    )
                }
                HistoricalArchive.endDurableDrain(generation: generation)
            }
        }
    }

    /// The reducer retains the exact prior/current frame identities across
    /// `begin`, so only this immediate second generation can turn a possible
    /// BLE drop into a proven flash discontinuity. This is not a generic force
    /// retry: mismatches, persistence failures, ACK failures and every other
    /// terminal error remain on the ordinary bounded cadence.
    private func scheduleHistorySequenceConfirmationRetry(
        failedGeneration: UInt64,
        reason: String
    ) {
        historySequenceConfirmationRetryTask?.cancel()
        historySequenceConfirmationRetryTask = Task { @MainActor [weak self] in
            guard let self else { return }
            var requestedLiveConnectionRebuild = false
            for second in 0..<60 {
                try? await Task.sleep(for: .seconds(1))
                guard !Task.isCancelled else { return }
                guard !self.offlineHistoricalSyncInProgress else { continue }
                guard self.historyDrain.generation == failedGeneration else {
                    return
                }
                // The strap can leave the history service active after a
                // fail-closed page transition. In that state CoreBluetooth may
                // keep delivering characteristic callbacks without producing a
                // single valid 2A37 sample. Generic reconnect backoff treats
                // those callbacks as link health and cancels its own rebuild,
                // permanently preventing the required second-generation
                // confirmation. For this exact reducer failure only, give live
                // restoration ten seconds and then rebuild the connection once.
                // didDisconnect owns the known-strap reconnect; the retry below
                // still waits for a genuinely accepted post-connect HR sample.
                let hasAcceptedHeartRateOnCurrentConnection: Bool = {
                    guard let connectedAt = self.connectedAt,
                          let lastAcceptedHRAt = self.lastAcceptedHRAt else {
                        return false
                    }
                    return lastAcceptedHRAt >= connectedAt
                }()
                if second >= 10,
                   !requestedLiveConnectionRebuild,
                   self.postHistoryLiveRestorationTask == nil,
                   let target = self.peripheral,
                   target.state == .connected,
                   self.status == .connected,
                   !hasAcceptedHeartRateOnCurrentConnection {
                    requestedLiveConnectionRebuild = true
                    self.cancelPeripheralConnection(
                        target,
                        reason: "history_sequence_confirmation_restore_live"
                    )
                    AtriaDebugLog("ATRIADBG historyDrain status=sequence_confirmation_live_rebuild prior_generation=%llu action=cancel_once_then_reconnect_known",
                                  failedGeneration)
                    continue
                }
                guard self.postHistoryLiveRestorationTask == nil,
                      self.peripheral?.state == .connected,
                      self.status == .connected,
                      let connectedAt = self.connectedAt,
                      let lastAcceptedHRAt = self.lastAcceptedHRAt,
                      lastAcceptedHRAt >= connectedAt else { continue }

                self.historySequenceConfirmationRetryTask = nil
                let retryReason = "\(reason)_sequence_confirmation"
                AtriaDebugLog("ATRIADBG historyDrain status=sequence_confirmation_ready prior_generation=%llu action=immediate_exact_replay reason=%@",
                              failedGeneration,
                              retryReason)
                let started = self.requestOfflineHistoricalSyncIfNeeded(
                    reason: retryReason,
                    force: true,
                    explicitResearchRequest: true
                )
                AtriaDebugLog("ATRIADBG historyDrain status=sequence_confirmation_request prior_generation=%llu started=%d action=%@",
                              failedGeneration,
                              started ? 1 : 0,
                              started
                                ? "verify_exact_transition"
                                : "retain_gap_ordinary_retry")
                return
            }
            self.historySequenceConfirmationRetryTask = nil
            AtriaDebugLog("ATRIADBG historyDrain status=sequence_confirmation_deferred prior_generation=%llu reason=live_restore_not_ready action=retain_gap_ordinary_retry",
                          failedGeneration)
        }
    }

    private func finishHistoricalAdmissionAttempt(
        succeeded: Bool,
        generation: UInt64
    ) {
        guard generation == offlineHistoricalSyncGeneration,
              let ledger = historicalAdmissionLedger,
              let attempt = historicalAdmissionAttempt else { return }
        historicalArchiveQueue.async {
            do {
                try ledger.finish(attempt, succeeded: succeeded)
                AtriaDebugLog("ATRIADBG historyAdmission status=%@ generation=%llu action=terminal_state_durable",
                              succeeded ? "finished" : "failed",
                              generation)
                Task { @MainActor [self] in
                    self.scheduleHistoricalAdmissionLedgerMaintenance(
                        reason: "attempt_terminal"
                    )
                }
            } catch {
                AtriaDebugLog("ATRIADBG historyAdmission status=finish_failed generation=%llu error=%@ action=retain_gap",
                              generation,
                              String(describing: error))
            }
        }
    }

    /// Schedules one bounded derived-store retention pass. This method never
    /// writes to the strap, changes an admission attempt state, or performs
    /// maintenance inline with a BLE callback. If the app is suspended before
    /// the pass runs, the ledger remains exact and the next lifecycle/terminal
    /// opportunity retries it.
    private func scheduleHistoricalAdmissionLedgerMaintenance(reason: String) {
        guard !historicalAdmissionMaintenanceScheduled else {
            AtriaDebugLog("ATRIADBG historyAdmissionMaintenance status=coalesced reason=%@",
                          reason)
            return
        }
        guard let ledger = historicalAdmissionLedger else {
            AtriaDebugLog("ATRIADBG historyAdmissionMaintenance status=unavailable reason=%@",
                          reason)
            return
        }
        let protectedAttemptIdentifiers: Set<String>
        do {
            if let authority = try historicalFullDrainCoverageStore.load(),
               authority.status != .resolved {
                protectedAttemptIdentifiers = [
                    authority.attempt.attemptIdentifier
                ]
            } else {
                protectedAttemptIdentifiers = []
            }
        } catch {
            // An unreadable terminal journal can never grant deletion
            // authority. Defer the whole pass until its ownership is known.
            AtriaDebugLog(
                "ATRIADBG historyAdmissionMaintenance status=deferred reason=%@ error=%@ action=retain_all_rows_unknown_terminal_owner",
                reason,
                String(describing: error)
            )
            return
        }
        historicalAdmissionMaintenanceScheduled = true
        historicalArchiveQueue.asyncAfter(deadline: .now() + .milliseconds(500)) {
            [weak self, ledger, protectedAttemptIdentifiers] in
            let result: Result<AtriaWhoop4HistoryAdmissionLedger.PruneResult, Error>
            do {
                result = .success(try ledger.prune(
                    protectedAttemptIdentifiers: protectedAttemptIdentifiers
                ))
            } catch {
                result = .failure(error)
            }
            Task { @MainActor [weak self] in
                self?.historicalAdmissionMaintenanceScheduled = false
                switch result {
                case .success(let prune):
                    AtriaDebugLog("ATRIADBG historyAdmissionMaintenance status=complete reason=%@ pruned=%d deferred_eligible_above_limit=%d protected_above_limit=%d remaining=%d",
                                  reason,
                                  prune.deletedRows,
                                  prune.deferredEligibleRowsAboveLimit,
                                  prune.protectedRowsAboveLimit,
                                  prune.remainingRows)
                    // One pass deliberately removes only a bounded number of
                    // already-durable rows.  If it yielded with more such
                    // rows, continue on the same delayed maintenance lane so
                    // a large completed drain converges without waiting for
                    // an unrelated lifecycle event.  Protected rows never
                    // enter this branch, preserving the no-data-loss rule.
                    if prune.deferredEligibleRowsAboveLimit > 0 {
                        self?.scheduleHistoricalAdmissionLedgerMaintenance(
                            reason: "\(reason)_continued"
                        )
                    }
                case .failure(let error):
                    // Retention must fail open: an error retains exact
                    // duplicate authority and is retried on a future safe
                    // lifecycle boundary.
                    AtriaDebugLog("ATRIADBG historyAdmissionMaintenance status=failed reason=%@ error=%@ action=retain_exact_authority",
                                  reason,
                                  String(describing: error))
                }
            }
        }
    }

    private func finalizeFullDrainTerminalAuthority(
        generation: UInt64
    ) -> Bool {
        guard let identity = activeFullDrainEventIdentity,
              identity.transportGeneration == generation,
              let payload = fullDrainHistoryCompletePayload,
              let stores = latestFullDrainDurableStores,
              let terminalBatchNumber = historyDrain.terminalBatchNumberForCompletedDrain else {
            return false
        }
        do {
            let durableSequence = (historicalAdmissionHighestOrdinal ?? 0) + 1
            var authority = try historicalFullDrainCoverageStore.recordHistoryComplete(
                identity: identity,
                completionIdentifier: "history-complete-\(AtriaHistoricalFullDrainCoveragePolicy.sha256(Data(payload)))",
                notificationPayload: Data(payload),
                stores: stores,
                receivedAt: Date(),
                terminalBatchNumber: terminalBatchNumber,
                durableSequence: durableSequence
            )
            if authority.publication == nil {
                let chunkID = try HistoricalArchive.terminalCatalogCandidateChunkID()
                // Ordinals start at zero. An empty attempt still gets a
                // monotonic terminal boundary of one; it can be ACKed but the
                // positive coverage evaluator will reject it.
                authority = try historicalFullDrainCoverageStore.preparePublication(
                    identity: identity,
                    chunkID: chunkID,
                    terminalBatchNumber: terminalBatchNumber,
                    durableSequence: durableSequence,
                    completedAt: Date()
                )
            }
            guard authority.publication != nil else { return false }
            return true
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_drain_authority status=terminal_deferred generation=%llu error=%@ positive_timestamps=%d gap_retained=1",
                          generation,
                          String(describing: error),
                          0)
            return false
        }
    }

    /// Resumes the exact full-drain publication journal. A transport terminal
    /// is not success here: raw seal, positive cadence proof, and SessionStore's
    /// request/await fence must settle before the exact gap can be removed. The
    /// five typed consumers settle in the same transaction only when their full
    /// civil-day/lookaround dependencies are closed; otherwise they remain a
    /// durable, restartable pending stage without blocking exact gap coverage.
    private func scheduleFullDrainConsumerMaterialization(
        transportGeneration: UInt64
    ) {
        guard !historicalConsumerMaterializationInFlight else { return }
        let coverageStore = historicalFullDrainCoverageStore
        let fullScanCompletionStore = historicalFullScanCompletionStore
        let authority: AtriaHistoricalFullDrainCoverageStore.Authority
        do {
            guard let loaded = try coverageStore.load(),
                  loaded.attempt.transportGeneration == transportGeneration,
                  loaded.status == .historyComplete
                    || loaded.status == .coverageProven
                    || loaded.status == .gapResolvedConsumersPending
                    || loaded.status == .consumersCommitted else { return }
            authority = loaded
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=authority_load_%@ gap_retained=1",
                          transportGeneration,
                          String(describing: error))
            return
        }
        guard let gapID = UUID(uuidString: authority.gap.gapIdentifier) else { return }
        let identity = Self.fullDrainEventIdentity(for: authority)

        // A crash after consumer commit but before CAS/resolve resumes only the
        // exact already-committed authority; it never selects another gap.
        if authority.status == .consumersCommitted {
            historicalConsumerMaterializationInFlight = true
            Task { @MainActor [weak self] in
                guard let self else { return }
                let fenceSucceeded = await self.requestAndAwaitRecoveredDataPublication?(
                    "full_drain_resume_\(transportGeneration)"
                ) ?? false
                guard fenceSucceeded else {
                    self.finishHistoricalConsumerMaterialization(
                        reason: "committed_fence_failed"
                    )
                    return
                }
                self.commitFullDrainGapAfterConsumers(
                    authority: authority,
                    identity: identity,
                    gapID: gapID
                )
            }
            return
        }

        let restingHeartRate = restingHR ?? 60
        let configuration = AtriaHistoricalConsumerProjectionConfiguration.production(
            restingHeartRate: restingHeartRate,
            maximumHeartRate: maxHRSetting,
            timeZoneIdentifier: TimeZone.current.identifier
        )
        let admissionLedger = historicalAdmissionLedger
        historicalConsumerMaterializationInFlight = true
        historicalArchiveQueue.async { [weak self] in
            do {
                guard let self else { return }
                // Repair legacy sealed sources before either the original
                // terminal path or the later full-scan dependency path reads
                // the catalog. `gapResolvedConsumersPending` used to branch
                // around this repair entirely and retry the same incomplete
                // proof forever.
                let stableMaterializationDate = Date(
                    timeIntervalSince1970:
                        authority.publication?.completedAtUnix
                        ?? authority.historyComplete?.receivedAtUnix
                        ?? authority.gap.endUnix
                )
                // Dying threads (2026-08-05 round 7 — the symbolicated killer):
                // this terminal materialization ran whole-archive digest +
                // verify + consumer publication on this long-lived queue and
                // was THE +60s cold-launch jetsam (burst_stack: verifyFiles →
                // sha256, streamedWholeArchiveDigest, MotionEpoch.encode under
                // publishPendingConsumersUsingLatestFullScan). Each heavy step
                // now runs on a thread that dies so its transient garbage
                // returns at teardown.
                let catalogMaterialization = try AtriaTransientWorkThread.run(
                    name: "atria.terminal-catalog",
                    qualityOfService: .utility
                ) {
                    Result {
                        try HistoricalArchive
                            .materializeNextSealedCatalogDependency(
                                now: stableMaterializationDate
                            )
                    }
                }.get()
                if !catalogMaterialization.isComplete {
                    AtriaDebugLog(
                        "ATRIADBG historical_catalog_materialization status=progress generation=%llu chunk=%@ remaining=%d action=yield_preserve_live_raw",
                        transportGeneration,
                        catalogMaterialization.materializedChunkID ?? "none",
                        catalogMaterialization.remainingChunkCount
                    )
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        self.finishHistoricalConsumerMaterialization(
                            reason: "sealed_catalog_materialization_progress"
                        )
                        self.scheduleTerminalCatalogMaterializationRetry()
                    }
                    return
                }

                if authority.status == .gapResolvedConsumersPending {
                    guard let dependency = authority.pendingConsumerDependency else {
                        throw AtriaBLEHistoryTerminalMaterializationError
                            .pendingConsumerDependencyMissing
                    }
                    let previousFullScan = try fullScanCompletionStore.loadLatest()
                    let refreshedSnapshot = try AtriaTransientWorkThread.run(
                        name: "atria.terminal-evidence",
                        qualityOfService: .utility
                    ) {
                        Result {
                            try HistoricalArchive
                                .currentFullScanSnapshotEvidence(
                                    sourceChunkID: previousFullScan.sourceChunkID,
                                    sourceRawSHA256: previousFullScan.sourceRawSHA256
                                )
                        }
                    }.get()
                    let fullScanSnapshotChanged =
                        previousFullScan.catalogGeneration
                            != refreshedSnapshot.catalogGeneration
                        || previousFullScan.catalogSnapshotSHA256
                            != refreshedSnapshot.catalogSnapshotSHA256
                        || previousFullScan.aggregateSnapshotSHA256
                            != refreshedSnapshot.aggregateSnapshotSHA256
                        || !HistoricalArchive.catalogTimestampMatches(
                            raw: refreshedSnapshot.observedArchiveFirstTimestamp,
                            catalog: previousFullScan
                                .observedArchiveFirstTimestamp
                        )
                    // The re-minted record's source fields must exactly equal
                    // the ACCEPTED committed aggregate's source (the proof
                    // factory compares them with exact `==`), so they are
                    // written from the refreshed catalog-resolved evidence,
                    // never blind-copied from a record that may predate a
                    // crash-at-seal repair. `sourceChunkID` is the immutable
                    // key and is always carried forward.
                    let sourceIdentityChanged =
                        refreshedSnapshot.source.rawSHA256
                            != previousFullScan.sourceRawSHA256
                        || refreshedSnapshot.source.firstTimestamp
                            != previousFullScan.sourceFirstTimestamp
                        || refreshedSnapshot.source.lastTimestamp
                            != previousFullScan.sourceLastTimestamp
                    if fullScanSnapshotChanged {
                        guard previousFullScan.generation < UInt64.max,
                              refreshedSnapshot.catalogGeneration
                                > previousFullScan.catalogGeneration else {
                            throw Self.terminalCheckpointMissing("site\(#line)")
                        }
                        _ = try fullScanCompletionStore.recordCompletion(.init(
                            version: AtriaHistoricalFullScanCompletionStore
                                .Record.currentVersion,
                            generation: previousFullScan.generation + 1,
                            transportGeneration:
                                previousFullScan.transportGeneration,
                            transportNonce: previousFullScan.transportNonce,
                            peripheralIdentifier:
                                previousFullScan.peripheralIdentifier,
                            strapIdentity: previousFullScan.strapIdentity,
                            cursorWatermark: previousFullScan.cursorWatermark,
                            terminalAt: previousFullScan.terminalAt,
                            sourceChunkID: previousFullScan.sourceChunkID,
                            sourceRawSHA256:
                                refreshedSnapshot.source.rawSHA256,
                            sourceFirstTimestamp:
                                refreshedSnapshot.source.firstTimestamp,
                            sourceLastTimestamp:
                                refreshedSnapshot.source.lastTimestamp,
                            observedArchiveFirstTimestamp:
                                refreshedSnapshot
                                    .observedArchiveFirstTimestamp,
                            catalogGeneration:
                                refreshedSnapshot.catalogGeneration,
                            catalogSnapshotSHA256:
                                refreshedSnapshot.catalogSnapshotSHA256,
                            aggregateSnapshotSHA256:
                                refreshedSnapshot.aggregateSnapshotSHA256
                        ))
                    } else if sourceIdentityChanged {
                        // Pair-consistent variant: every snapshot digest is
                        // unchanged, only the persisted source identity is
                        // stale. Digests and catalog generation are carried
                        // forward so the same-generation snapshot equality
                        // gates keep holding; `observedArchiveFirstTimestamp`
                        // must come from the refreshed evidence (never the
                        // stale record) because the store validates
                        // observedFirst <= sourceFirst and the corrected
                        // first timestamp can precede the stale observation.
                        guard previousFullScan.generation < UInt64.max else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .fullScanGenerationExhausted
                        }
                        _ = try fullScanCompletionStore.recordCompletion(.init(
                            version: AtriaHistoricalFullScanCompletionStore
                                .Record.currentVersion,
                            generation: previousFullScan.generation + 1,
                            transportGeneration:
                                previousFullScan.transportGeneration,
                            transportNonce: previousFullScan.transportNonce,
                            peripheralIdentifier:
                                previousFullScan.peripheralIdentifier,
                            strapIdentity: previousFullScan.strapIdentity,
                            cursorWatermark: previousFullScan.cursorWatermark,
                            terminalAt: previousFullScan.terminalAt,
                            sourceChunkID: previousFullScan.sourceChunkID,
                            sourceRawSHA256:
                                refreshedSnapshot.source.rawSHA256,
                            sourceFirstTimestamp:
                                refreshedSnapshot.source.firstTimestamp,
                            sourceLastTimestamp:
                                refreshedSnapshot.source.lastTimestamp,
                            observedArchiveFirstTimestamp:
                                refreshedSnapshot
                                    .observedArchiveFirstTimestamp,
                            catalogGeneration:
                                previousFullScan.catalogGeneration,
                            catalogSnapshotSHA256:
                                previousFullScan.catalogSnapshotSHA256,
                            aggregateSnapshotSHA256:
                                previousFullScan.aggregateSnapshotSHA256
                        ))
                    }
                    let report = try AtriaTransientWorkThread.run(
                        name: "atria.terminal-consumers",
                        qualityOfService: .utility
                    ) {
                        Result {
                            try HistoricalArchive
                                .publishPendingConsumersUsingLatestFullScan(
                                    dependency: dependency,
                                    fullScanStore: fullScanCompletionStore,
                                    configuration: configuration
                                )
                        }
                    }.get()
                    guard report.hasCompleteConsumerCoverage,
                          report.inspectedSourceCount == 1,
                          report.published.count == 5,
                          report.deferredSources.isEmpty,
                          let completionGeneration = report.completionGeneration else {
                        throw AtriaBLEHistoryTerminalMaterializationError
                            .incompleteConsumerCoverage
                    }
                    let checkpointed = try coverageStore.recordProjectionsPublished(
                        identity: identity,
                        evidence: .init(
                            completionGeneration: completionGeneration,
                            inspectedSourceCount: report.inspectedSourceCount,
                            receiptCount: report.published.count,
                            artifactSHA256s: report.published.map {
                                $0.receipt.artifactSHA256
                            }.sorted()
                        )
                    )
                    let receipts = try Self.fullDrainConsumerReceipts(
                        from: report.published,
                        authority: checkpointed
                    )
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        let fenceSucceeded = await self.requestAndAwaitRecoveredDataPublication?(
                            "full_scan_pending_consumers_\(transportGeneration)"
                        ) ?? false
                        guard fenceSucceeded else {
                            self.finishHistoricalConsumerMaterialization(
                                reason: "pending_consumers_fence_failed"
                            )
                            return
                        }
                        do {
                            try self.reconcileAdditionalTerminalFullDrainGaps(
                                identity: identity
                            )
                            let committed = try coverageStore.recordCommittedConsumers(
                                identity: identity,
                                receipts: receipts,
                                committedAt: Date(timeIntervalSince1970: max(
                                    Date().timeIntervalSince1970,
                                    receipts.map(\.committedAtUnix).max() ?? 0
                                ))
                            )
                            guard committed.status == .resolved else {
                                throw AtriaBLEHistoryTerminalMaterializationError
                                    .consumerReceiptRereadFailed
                            }
                            self.finalizeAlreadyResolvedFullDrainConsumers(
                                authority: committed
                            )
                        } catch {
                            self.finishHistoricalConsumerMaterialization(
                                reason: "pending_consumers_commit_failed"
                            )
                            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=full_scan_consumer_commit_%@ raw_retained=1",
                                          transportGeneration,
                                          String(describing: error))
                        }
                    }
                    return
                }
                var current = try coverageStore.load()
                if current?.publication == nil {
                    guard let terminal = current?.historyComplete else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    let terminalBatchNumber = terminal.terminalBatchNumber
                        ?? UInt64(terminal.acknowledgedBoundaryCount)
                    let durableSequence = terminal.durableSequence
                        ?? terminal.stores.admissionReceipt.durableOrdinal.map {
                            $0 == UInt64.max ? UInt64.max : $0 + 1
                        }
                        ?? 1
                    guard terminalBatchNumber > 0,
                          durableSequence > 0,
                          durableSequence < UInt64.max else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    let chunkID = try HistoricalArchive
                        .terminalCatalogCandidateChunkID()
                    current = try coverageStore.preparePublication(
                        identity: identity,
                        chunkID: chunkID,
                        terminalBatchNumber: terminalBatchNumber,
                        durableSequence: durableSequence,
                        completedAt: Date(timeIntervalSince1970:
                            terminal.receivedAtUnix)
                    )
                }
                guard var publication = current?.publication else {
                    throw Self.terminalCheckpointMissing("site\(#line)")
                }
                var seal: HistoricalArchive.TerminalCatalogSealResult
                if publication.status == .prepared {
                    seal = try HistoricalArchive.recoverFullDrainTerminalCatalogSeal(
                        checkpoint: publication,
                        generation: transportGeneration
                    )
                    let source = seal.aggregateBuild.aggregate.source
                    current = try coverageStore.recordRawSeal(
                        identity: identity,
                        evidence: .init(
                            drainGeneration: transportGeneration,
                            contentSHA256: source.rawSHA256,
                            byteCount: source.rawByteCount,
                            rowCount: source.rawRowCount,
                            firstTimestampUnix: source.firstTimestamp.timeIntervalSince1970,
                            lastTimestampUnix: source.lastTimestamp.timeIntervalSince1970
                        )
                    )
                    guard let updated = current?.publication else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    publication = updated
                } else {
                    seal = try HistoricalArchive.recoverFullDrainTerminalCatalogSeal(
                        checkpoint: publication,
                        generation: transportGeneration
                    )
                }

                // A crash/relaunch can leave the completion checkpoint bound to
                // the pre-materialization catalog. Republish the same immutable
                // terminal request/cursor facts against the advanced verified
                // snapshots. No range or transport authority is widened.
                if publication.status == .completionPublished {
                    let refreshed = try HistoricalArchive
                        .publishTerminalCompletionAfterDrain(
                            seal: seal,
                            terminalBatchNumber: publication.terminalBatchNumber,
                            durableSequence: publication.durableSequence,
                            requestedStart: Date(timeIntervalSince1970:
                                authority.gap.startUnix),
                            requestedEnd: Date(timeIntervalSince1970:
                                authority.gap.endUnix),
                            completedAt: Date(timeIntervalSince1970:
                                publication.completedAtUnix)
                        )
                    let scanSource = seal.aggregateBuild.aggregate.source
                    _ = try fullScanCompletionStore
                        .recordCompletionAdvancingLatest(.init(
                        version: AtriaHistoricalFullScanCompletionStore.Record
                            .currentVersion,
                        generation: refreshed.completion.record.generation,
                        transportGeneration: authority.attempt.transportGeneration,
                        transportNonce: authority.attempt.transportNonce,
                        peripheralIdentifier: authority.attempt.peripheralIdentifier,
                        strapIdentity: authority.attempt.strapIdentity,
                        cursorWatermark: Date(timeIntervalSince1970: TimeInterval(
                            authority.attempt.transportAuthority.clockWallUnix
                        )),
                        terminalAt: Date(timeIntervalSince1970:
                            publication.completedAtUnix),
                        sourceChunkID: scanSource.chunkID,
                        sourceRawSHA256: scanSource.rawSHA256,
                        sourceFirstTimestamp: scanSource.firstTimestamp,
                        sourceLastTimestamp: scanSource.lastTimestamp,
                        observedArchiveFirstTimestamp: HistoricalArchive
                            .earliestCommittedAggregateTimestamp()
                            ?? scanSource.firstTimestamp,
                        catalogGeneration: refreshed.completion.record.catalogGeneration,
                        catalogSnapshotSHA256: refreshed.completion.record
                            .catalogSnapshotSHA256,
                        aggregateSnapshotSHA256: refreshed.completion.record
                            .aggregateSnapshotSHA256
                        ))
                    let refreshedEvidence =
                        AtriaBLEHistoryTerminalPublicationStore.CompletionEvidence(
                            generation: refreshed.completion.record.generation,
                            catalogGeneration: refreshed.completion.record
                                .catalogGeneration,
                            catalogSnapshotSHA256: refreshed.completion.record
                                .catalogSnapshotSHA256,
                            aggregateSnapshotSHA256: refreshed.completion.record
                                .aggregateSnapshotSHA256
                        )
                    if publication.completion != refreshedEvidence {
                        current = try coverageStore.refreshCompletionPublished(
                            identity: identity,
                            evidence: refreshedEvidence
                        )
                    }
                    guard let updated = current?.publication else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    publication = updated
                }

                if current?.status == .historyComplete {
                    guard let admissionLedger else {
                        throw AtriaBLEHistoryTerminalMaterializationError
                            .admissionIdentityNotDurable
                    }
                    let clockAuthority = authority.attempt.transportAuthority
                    let wallSeconds = clockAuthority.clockWallUnix
                    let clock = AtriaWhoop4HistoryArchivePipeline.ClockReference(
                        device: clockAuthority.deviceClockUnix,
                        wall: wallSeconds,
                        driftSeconds: Int(wallSeconds)
                            - Int(clockAuthority.deviceClockUnix),
                        snappedDriftSeconds: {
                            let drift = Int(wallSeconds)
                                - Int(clockAuthority.deviceClockUnix)
                            guard abs(drift) >= 86_400 else { return drift }
                            let granularity = 300
                            return drift >= 0
                                ? ((drift + granularity / 2) / granularity) * granularity
                                : ((drift - granularity / 2) / granularity) * granularity
                        }()
                    )
                    var timestamps: [TimeInterval] = []
                    let admissionReceipt = try terminalAdmissionReceipt(authority)
                    do {
                        let report = try admissionLedger.enumerateDurableFrames(
                            attemptIdentifier: authority.attempt.attemptIdentifier,
                            strapIdentifier: authority.attempt.peripheralIdentifier,
                            throughReceipt: admissionReceipt,
                            // 13 days at 1 Hz is 1,123,200 frames. Enumeration is
                            // SQLite-streamed, so this bounds work without making
                            // the production policy internally impossible.
                            maximumFrames: 1_500_000
                        ) { _, frame in
                            let computation = AtriaWhoop4HistoryArchivePipeline.prepare(
                                payload: Array(frame),
                                clock: clock,
                                historyClockSyncEnabled: true,
                                now: Date(timeIntervalSince1970:
                                    publication.completedAtUnix)
                            )
                            guard case .record(let record) = computation.payload,
                                  record.metricUsable else { return }
                            let unix = record.clockCorrectedUnix7 ?? record.unix7
                            let timestamp = TimeInterval(unix)
                                + TimeInterval(record.subsec11) / 32_768
                            timestamps.append(timestamp)
                        }
                        guard report.recordCount == admissionReceipt.recordCount,
                              report.byteCount == admissionReceipt.byteCount else {
                            throw AtriaWhoop4HistoryAdmissionLedger.LedgerError
                                .durablePrefixReceiptMismatch
                        }
                    } catch AtriaWhoop4HistoryAdmissionLedger.LedgerError.durablePrefixReceiptMismatch {
                        // Older builds allowed retention to prune a completed
                        // admission prefix before its terminal publication
                        // settled. The immutable raw seal is a second exact
                        // authority only when every accepted row proves it was
                        // observed inside this transport attempt—not merely
                        // captured earlier and present in the same chunk.
                        guard let terminal = authority.historyComplete,
                              let rawSeal = publication.rawSeal else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .admissionIdentityNotDurable
                        }
                        let source = seal.aggregateBuild.aggregate.source
                        guard rawSeal.drainGeneration
                                == authority.attempt.transportGeneration,
                              rawSeal.contentSHA256 == source.rawSHA256,
                              rawSeal.byteCount == source.rawByteCount,
                              rawSeal.rowCount == source.rawRowCount,
                              rawSeal.firstTimestampUnix
                                == source.firstTimestamp.timeIntervalSince1970,
                              rawSeal.lastTimestampUnix
                                == source.lastTimestamp.timeIntervalSince1970 else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .admissionIdentityNotDurable
                        }
                        timestamps = try HistoricalArchive.verifiedMetricTimestamps(
                            in: seal,
                            start: source.firstTimestamp,
                            end: source.lastTimestamp.addingTimeInterval(1),
                            observedAfter: Date(timeIntervalSince1970:
                                authority.attempt.commandWriteCompletedAtUnix),
                            observedBefore: Date(timeIntervalSince1970:
                                terminal.receivedAtUnix)
                        )
                        guard !timestamps.isEmpty else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .admissionIdentityNotDurable
                        }
                        AtriaDebugLog(
                            "ATRIADBG historical_full_drain_coverage status=sealed_observation_fallback generation=%llu admission_expected=%llu verified_metric_rows=%d action=preserve_exact_attempt_after_admission_retention",
                            authority.attempt.transportGeneration,
                            admissionReceipt.recordCount,
                            timestamps.count
                        )
                    }
                    // This candidate set is part of the immutable terminal
                    // receipt. A retry may run after newer gaps were created;
                    // recomputing against that later ledger would reject the
                    // already-persisted set and permanently wedge publication.
                    if authority.terminalGapReconciliations == nil {
                        let terminalGapEntries = try
                            AtriaHistoricalTerminalGapReconciliationCoordinator.evaluate(
                                candidates: AtriaHistoricalGapLedger
                                    .allClosedRecoveryCandidates(),
                                excludingGapIdentifier:
                                    authority.gap.gapIdentifier,
                                authority: authority,
                                decoderIdentifier:
                                    HistoricalArchive.layoutVersion,
                                decoderVersion: HistoricalArchive.schema,
                                metricTimestampsUnix: timestamps
                            )
                        _ = try coverageStore.recordTerminalGapReconciliations(
                            identity: identity,
                            entries: terminalGapEntries
                        )
                    }
                    let coverageEffect =
                        try AtriaHistoricalFullDrainCoverageCoordinator(
                            store: coverageStore
                        ).proveCoverage(
                            identity: identity,
                            decoderIdentifier: HistoricalArchive.layoutVersion,
                            decoderVersion: HistoricalArchive.schema,
                            metricTimestampsUnix: timestamps
                        )
                    if case .coveragePersisted(let proof) = coverageEffect {
                        AtriaDebugLog(
                            "ATRIADBG historical_full_drain_coverage status=persisted gap=%@ generation=%llu observed=%d expected=%d density=%d maximum_gap=%d p95_gap=%d",
                            proof.gapIdentifier,
                            proof.transportGeneration,
                            proof.observedBuckets,
                            proof.expectedBuckets,
                            proof.densityPercent,
                            proof.maximumGapSeconds,
                            proof.p95GapSeconds
                        )
                    }
                    current = try coverageStore.load()
                }

                if publication.status == .rawSealed {
                    let published = try HistoricalArchive.publishTerminalCompletionAfterDrain(
                        seal: seal,
                        terminalBatchNumber: publication.terminalBatchNumber,
                        durableSequence: publication.durableSequence,
                        requestedStart: Date(timeIntervalSince1970: authority.gap.startUnix),
                        requestedEnd: Date(timeIntervalSince1970: authority.gap.endUnix),
                        completedAt: Date(timeIntervalSince1970: publication.completedAtUnix)
                    )
                    let scanSource = seal.aggregateBuild.aggregate.source
                    _ = try fullScanCompletionStore
                        .recordCompletionAdvancingLatest(.init(
                        version: AtriaHistoricalFullScanCompletionStore.Record.currentVersion,
                        generation: published.completion.record.generation,
                        transportGeneration: authority.attempt.transportGeneration,
                        transportNonce: authority.attempt.transportNonce,
                        peripheralIdentifier: authority.attempt.peripheralIdentifier,
                        strapIdentity: authority.attempt.strapIdentity,
                        cursorWatermark: Date(timeIntervalSince1970: TimeInterval(
                            authority.attempt.transportAuthority.clockWallUnix
                        )),
                        terminalAt: Date(timeIntervalSince1970: publication.completedAtUnix),
                        sourceChunkID: scanSource.chunkID,
                        sourceRawSHA256: scanSource.rawSHA256,
                        sourceFirstTimestamp: scanSource.firstTimestamp,
                        sourceLastTimestamp: scanSource.lastTimestamp,
                        observedArchiveFirstTimestamp: HistoricalArchive
                            .earliestCommittedAggregateTimestamp()
                            ?? scanSource.firstTimestamp,
                        catalogGeneration: published.completion.record.catalogGeneration,
                        catalogSnapshotSHA256: published.completion.record.catalogSnapshotSHA256,
                        aggregateSnapshotSHA256: published.completion.record.aggregateSnapshotSHA256
                        ))
                    current = try coverageStore.recordCompletionPublished(
                        identity: identity,
                        evidence: .init(
                            generation: published.completion.record.generation,
                            catalogGeneration: published.completion.record.catalogGeneration,
                            catalogSnapshotSHA256: published.completion.record.catalogSnapshotSHA256,
                            aggregateSnapshotSHA256: published.completion.record.aggregateSnapshotSHA256
                        )
                    )
                    guard let updated = current?.publication else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    publication = updated
                }

                let source = seal.aggregateBuild.aggregate.source
                let settlement = try AtriaHistoricalConsumerProjectionCoordinator
                    .settlementReadiness(
                        sourceFirstTimestamp: source.firstTimestamp,
                        sourceLastTimestamp: source.lastTimestamp,
                        completionStart: Date(timeIntervalSince1970: authority.gap.startUnix),
                        completionEnd: Date(timeIntervalSince1970: authority.gap.endUnix),
                        dailyConfiguration: configuration.daily
                    )
                if case .pendingFutureEvidence(let requiredStart, let requiredEnd) = settlement {
                    guard let pendingAuthority = try coverageStore.load() else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        let fenceSucceeded = await self.requestAndAwaitRecoveredDataPublication?(
                            "full_drain_exact_gap_\(transportGeneration)"
                        ) ?? false
                        guard fenceSucceeded else {
                            self.finishHistoricalConsumerMaterialization(
                                reason: "exact_gap_fence_failed"
                            )
                            return
                        }
                        self.commitFullDrainGapPendingConsumers(
                            authority: pendingAuthority,
                            identity: identity,
                            gapID: gapID,
                            dependency: .init(
                                requiredStartUnix: requiredStart.timeIntervalSince1970,
                                requiredEndUnix: requiredEnd.timeIntervalSince1970,
                                sourceChunkID: source.chunkID,
                                sourceRawSHA256: source.rawSHA256
                            )
                        )
                    }
                    return
                }

                let resumed = try HistoricalArchive
                    .resumeFullDrainConsumerProjectionsAfterCrash(
                        checkpoint: publication,
                        requestedStart: Date(timeIntervalSince1970: authority.gap.startUnix),
                        requestedEnd: Date(timeIntervalSince1970: authority.gap.endUnix),
                        configuration: configuration
                    )
                guard resumed.consumers.hasCompleteConsumerCoverage,
                      resumed.consumers.inspectedSourceCount == 1,
                      resumed.consumers.published.count == 5,
                      resumed.consumers.deferredSources.isEmpty else {
                    throw AtriaBLEHistoryTerminalMaterializationError
                        .incompleteConsumerCoverage
                }
                if publication.status == .completionPublished {
                    current = try coverageStore.recordProjectionsPublished(
                        identity: identity,
                        evidence: .init(
                            completionGeneration: resumed.completion.generation,
                            inspectedSourceCount: resumed.consumers.inspectedSourceCount,
                            receiptCount: resumed.consumers.published.count,
                            artifactSHA256s: resumed.consumers.published.map {
                                $0.receipt.artifactSHA256
                            }.sorted()
                        )
                    )
                }
                let receipts = try Self.fullDrainConsumerReceipts(
                    from: resumed.consumers.published,
                    authority: authority
                )

                Task { @MainActor [weak self] in
                    guard let self else { return }
                    let fenceSucceeded = await self.requestAndAwaitRecoveredDataPublication?(
                        "full_drain_terminal_\(transportGeneration)"
                    ) ?? false
                    guard fenceSucceeded else {
                        self.finishHistoricalConsumerMaterialization(
                            reason: "terminal_fence_failed"
                        )
                        return
                    }
                    do {
                        let committedAt = Date(timeIntervalSince1970: max(
                            Date().timeIntervalSince1970,
                            receipts.map(\.committedAtUnix).max() ?? 0
                        ))
                        try self.reconcileAdditionalTerminalFullDrainGaps(
                            identity: identity
                        )
                        _ = try coverageStore.recordCommittedConsumers(
                            identity: identity,
                            receipts: receipts,
                            committedAt: committedAt
                        )
                        guard let reread = try coverageStore.load(),
                              reread.consumerCommit?.receipts == receipts,
                              reread.status == .consumersCommitted
                                || reread.status == .resolved else {
                            throw AtriaBLEHistoryTerminalMaterializationError
                                .consumerReceiptRereadFailed
                        }
                        UserDefaults.standard.removeObject(
                            forKey:
                                Self.terminalConsumerDependencyMismatchKey
                        )
                        UserDefaults.standard.removeObject(
                            forKey:
                                Self.terminalConsumerDependencyMismatchAtKey
                        )
                        if reread.status == .resolved {
                            self.finalizeAlreadyResolvedFullDrainConsumers(
                                authority: reread
                            )
                        } else {
                            self.commitFullDrainGapAfterConsumers(
                                authority: reread,
                                identity: identity,
                                gapID: gapID
                            )
                        }
                    } catch {
                        self.finishHistoricalConsumerMaterialization(
                            reason: "consumer_commit_failed"
                        )
                        AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=consumer_commit_%@ gap_retained=1",
                                      transportGeneration,
                                      String(describing: error))
                    }
                }
            } catch AtriaHistoricalFullDrainCoveragePolicy.Rejection
                .noUsableTimestamps {
                do {
                    let released = try coverageStore
                        .releaseHistoryCompleteAuthorityWithoutGapCoverage(
                            identity: identity
                        )
                    guard released else {
                        throw Self.terminalCheckpointMissing("site\(#line)")
                    }
                    UserDefaults.standard.set(
                        "terminal_gap_uncovered_raw_retained",
                        forKey: OfflineSyncDefaults.lastStatus
                    )
                    UserDefaults.standard.set(
                        "no_overlapping_history_rows",
                        forKey: OfflineSyncDefaults.lastReason
                    )
                    UserDefaults.standard.set(
                        false,
                        forKey:
                            OfflineSyncDefaults.rangeLossBackfillPending
                    )
                    AtriaDebugLog(
                        "ATRIADBG historical_full_drain_publish status=gap_uncovered generation=%llu action=preserve_gap_and_raw_release_priority_publish_partial_metrics",
                        transportGeneration
                    )
                    Task { @MainActor [weak self] in
                        guard let self else { return }
                        self.rangeLossBackfillTask?.cancel()
                        self.rangeLossBackfillTask = nil
                        self.pendingOfflineHistoricalSyncRequest = nil
                        self.pendingConnectedMotionBankSchedulingTicketID = nil
                        self.assignIfChanged(
                            \.rangeLossBackfillPending,
                            false
                        )
                        let exactMotionResumed = self
                            .releaseHistoricalConsumerMaterializationOwner(
                                reason: "terminal_gap_uncovered"
                            )
                        let published = exactMotionResumed
                            ? false
                            : await self
                                .requestAndAwaitRecoveredDataPublication?(
                                    "full_drain_uncovered_partial_metrics"
                                ) ?? false
                        UserDefaults.standard.set(
                            published
                                ? "partial_history_published_gap_preserved"
                                : "partial_history_publication_deferred",
                            forKey: OfflineSyncDefaults.lastStatus
                        )
                        self.onHistoricalTransportOwnershipReleased?(
                            "terminal_gap_uncovered"
                        )
                    }
                } catch {
                    UserDefaults.standard.set(
                        String(reflecting: error),
                        forKey:
                            "atria.offlineSync.terminalArchiveFailureDiagnostic.v1"
                    )
                    Task { @MainActor [weak self] in
                        self?.finishHistoricalConsumerMaterialization(
                            reason: "uncovered_terminal_release_failed"
                        )
                    }
                }
            } catch AtriaHistoricalActivityInspectionProofFactory
                .FactoryError.completionCoverageMismatch {
                UserDefaults.standard.set(
                    String(
                        reflecting:
                            AtriaHistoricalActivityInspectionProofFactory
                                .FactoryError.completionCoverageMismatch
                    ),
                    forKey:
                        "atria.offlineSync.terminalArchiveFailureDiagnostic.v1"
                )
                UserDefaults.standard.set(
                    Date(),
                    forKey: "atria.offlineSync.terminalArchiveFailureAt.v1"
                )
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=completionCoverageMismatch action=cache_unchanged_terminal_snapshot_release_archive_lane",
                    transportGeneration
                )
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    if let fingerprint = self
                        .terminalConsumerCoverageFailureFingerprint(
                            authority: authority
                        ) {
                        UserDefaults.standard.set(
                            fingerprint,
                            forKey: Self.terminalConsumerCoverageFailureKey
                        )
                        UserDefaults.standard.set(
                            Date(),
                            forKey: Self.terminalConsumerCoverageFailureAtKey
                        )
                    }
                    self.finishHistoricalConsumerMaterialization(
                        reason: "terminal_completion_coverage_mismatch"
                    )
                }
            } catch AtriaHistoricalConsumerProjectionCoordinator
                .CoordinatorError.pendingDependencyMismatch {
                if let fingerprint = Self
                    .terminalConsumerDependencyFingerprint(
                        authority: authority,
                        timeZoneIdentifier: TimeZone.current.identifier
                    ) {
                    UserDefaults.standard.set(
                        fingerprint,
                        forKey: Self.terminalConsumerDependencyMismatchKey
                    )
                    UserDefaults.standard.set(
                        Date(),
                        forKey:
                            Self.terminalConsumerDependencyMismatchAtKey
                    )
                }
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=pendingDependencyMismatch action=cache_exact_authority_mismatch_release_archive_lane",
                    transportGeneration
                )
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    self.finishHistoricalConsumerMaterialization(
                        reason: "terminal_dependency_model_mismatch"
                    )
                    self.scheduleTerminalConsumerDependencyRetry()
                }
            } catch {
                UserDefaults.standard.set(
                    String(reflecting: error),
                    forKey: "atria.offlineSync.terminalArchiveFailureDiagnostic.v1"
                )
                UserDefaults.standard.set(
                    Date(),
                    forKey: "atria.offlineSync.terminalArchiveFailureAt.v1"
                )
                AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=%@ gap_retained=1",
                              transportGeneration,
                              String(describing: error))
                Task { @MainActor [weak self] in
                    self?.finishHistoricalConsumerMaterialization(
                        reason: "terminal_archive_failed"
                    )
                    // Handoff-12: this generic terminal catch was the one
                    // failure lane with no self re-arm — a transient
                    // publicationCheckpointMissing (catalog snapshot changed
                    // before its generation advanced; physically observed as
                    // site37794) parked the consumers until an unrelated
                    // trigger. Reuse the same bounded 15-minute retry the
                    // dependency-mismatch sibling already earns; the
                    // suppression caches still bound repeat attempts.
                    self?.scheduleTerminalConsumerDependencyRetry()
                }
            }
        }
    }

    /// Finishing a terminal publication must release the request that arrived
    /// while publication owned the archive lane. Otherwise one completed old
    /// drain can leave a newer reconnect/workout gap pending indefinitely.
    @discardableResult
    private func releaseHistoricalConsumerMaterializationOwner(
        reason: String
    ) -> Bool {
        guard historicalConsumerMaterializationInFlight else { return false }
        historicalConsumerMaterializationInFlight = false
        return resumeConnectedMotionBankAfterLocalDependencyIfNeeded(
            .terminalMaterialization
        )
    }

    private func finishHistoricalConsumerMaterialization(reason: String) {
        let wasInFlight = historicalConsumerMaterializationInFlight
        let exactMotionResumed =
            releaseHistoricalConsumerMaterializationOwner(reason: reason)
        if exactMotionResumed { return }
        let defaults = UserDefaults.standard
        let authorityStatus =
            (try? historicalFullDrainCoverageStore.load())?.status
        let releaseDisposition =
            Self.terminalMaterializationReleaseDisposition(
                wasInFlight: wasInFlight,
                rangeLossBackfillPending: defaults.bool(
                    forKey: OfflineSyncDefaults.rangeLossBackfillPending
                ),
                offlineHistoricalSyncInProgress: offlineHistoricalSyncInProgress,
                authorityStatus: authorityStatus,
                hasPendingMotionBankRequest:
                    pendingOfflineHistoricalSyncRequest?
                        .explicitPostWorkoutBankRequest == true
            )
        switch releaseDisposition {
        case .noAction:
            return
        case .retainTerminalJournal:
            UserDefaults.standard.set(
                "terminal_consumer_materialization_deferred",
                forKey: OfflineSyncDefaults.lastStatus
            )
            defaults.set(
                reason,
                forKey: OfflineSyncDefaults.lastReason
            )
            AtriaDebugLog(
                "ATRIADBG historical_full_drain_publish status=deferred stage=%@ reason=%@ action=retain_terminal_journal_preserve_live_no_ble_rearm",
                authorityStatus?.rawValue ?? "none",
                reason
            )
            return
        case .resumePendingMotionBank:
            guard let pending = takePendingOfflineHistoricalSyncRequest() else {
                return
            }
            defaults.set(
                "terminal_consumer_materialization_releasing_motion_bank",
                forKey: OfflineSyncDefaults.lastStatus
            )
            defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
            AtriaDebugLog(
                "ATRIADBG historical_full_drain_publish status=deferred stage=%@ reason=%@ action=retain_terminal_journal_release_authorized_motion_bank_no_local_projection_retry",
                authorityStatus?.rawValue ?? "none",
                reason
            )
            terminalMaterializationMotionBankReleaseInProgress = true
            defer { terminalMaterializationMotionBankReleaseInProgress = false }
            _ = requestOfflineHistoricalSyncIfNeeded(
                reason: pending.reason,
                force: pending.force,
                explicitResearchRequest: pending.explicitRequest,
                explicitPostWorkoutBankRequest:
                    pending.explicitPostWorkoutBankRequest,
                preserveConnectedRealtimeOwner:
                    pending.preserveConnectedRealtimeOwner
            )
        case .scheduleRangeLossBackfill:
            scheduleRangeLossBackfillIfNeeded(
                reason: "terminal_materialization_finished_\(reason)"
            )
        }
    }

    /// Turns a later ordinary full drain into immutable scan evidence for an
    /// older authority whose five consumer projections need wider context.
    /// This does not claim exact-range BLE support and never removes raw data.
    private func schedulePendingConsumerFollowupScanMaterialization(
        transportGeneration: UInt64
    ) {
        guard !historicalConsumerMaterializationInFlight,
              let nonce = fullDrainTransportNonce,
              let peripheralIdentifier = peripheral?.identifier.uuidString,
              let cursorWallUnix = acceptedHistoryClockWallUnix else { return }
        let coverageStore = historicalFullDrainCoverageStore
        let scanStore = historicalFullScanCompletionStore
        let strapIdentity = strapModel.rawValue
        let completedAt = Date()
        do {
            guard let authority = try coverageStore.load(),
                  authority.status == .gapResolvedConsumersPending,
                  authority.attempt.transportGeneration != transportGeneration else { return }
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_scan status=deferred generation=%llu reason=authority_load_%@ raw_retained=1",
                          transportGeneration, String(describing: error))
            return
        }

        historicalConsumerMaterializationInFlight = true
        historicalArchiveQueue.async { [weak self] in
            do {
                guard let self else { return }
                let seal = try HistoricalArchive.sealCatalogChunkAfterTerminalDrain(
                        generation: transportGeneration,
                        completedAt: completedAt
                      )
                let priorGeneration: UInt64
                let priorScan: AtriaHistoricalFullScanCompletionStore.Record?
                do {
                    priorScan = try scanStore.loadLatest()
                    priorGeneration = priorScan?.generation ?? 0
                } catch AtriaHistoricalFullScanCompletionStore.StoreError.missingCompletion {
                    priorScan = nil
                    priorGeneration = 0
                }
                let publication: HistoricalArchive.FullScanAggregatePublicationResult
                if let seal {
                    publication = try HistoricalArchive.publishFullScanAggregateAfterDrain(
                        seal: seal,
                        completedAt: completedAt
                    )
                } else if let priorScan {
                    publication = try HistoricalArchive.currentFullScanSnapshotEvidence(
                        sourceChunkID: priorScan.sourceChunkID,
                        sourceRawSHA256: priorScan.sourceRawSHA256
                    )
                } else {
                    throw AtriaBLEHistoryTerminalMaterializationError.noNewRawChunk
                }
                guard priorGeneration < UInt64.max else {
                    throw AtriaBLEHistoryTerminalMaterializationError
                        .fullScanGenerationExhausted
                }
                _ = try scanStore.recordCompletion(.init(
                    version: AtriaHistoricalFullScanCompletionStore.Record.currentVersion,
                    generation: priorGeneration + 1,
                    transportGeneration: transportGeneration,
                    transportNonce: nonce,
                    peripheralIdentifier: peripheralIdentifier,
                    strapIdentity: strapIdentity,
                    cursorWatermark: Date(timeIntervalSince1970: TimeInterval(cursorWallUnix)),
                    terminalAt: completedAt,
                    sourceChunkID: publication.source.chunkID,
                    sourceRawSHA256: publication.source.rawSHA256,
                    sourceFirstTimestamp: publication.source.firstTimestamp,
                    sourceLastTimestamp: publication.source.lastTimestamp,
                    observedArchiveFirstTimestamp: publication.observedArchiveFirstTimestamp,
                    catalogGeneration: publication.catalogGeneration,
                    catalogSnapshotSHA256: publication.catalogSnapshotSHA256,
                    aggregateSnapshotSHA256: publication.aggregateSnapshotSHA256
                ))
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    let exactMotionResumed = self
                        .releaseHistoricalConsumerMaterializationOwner(
                            reason: "full_scan_archive_committed"
                        )
                    if !exactMotionResumed {
                        self.resumePendingFullDrainPublicationIfNeeded(
                            reason: "full_scan_archive_committed"
                        )
                    }
                }
            } catch {
                Task { @MainActor [weak self] in
                    self?.releaseHistoricalConsumerMaterializationOwner(
                        reason: "full_scan_archive_failed"
                    )
                    AtriaDebugLog("ATRIADBG historical_full_scan status=deferred generation=%llu reason=%@ raw_retained=1",
                                  transportGeneration, String(describing: error))
                }
            }
        }
    }

    /// Reconciles all non-primary gaps proven by this same sealed terminal.
    /// Projection publication is required by the store before any intent can
    /// be prepared. The primary authority is deliberately committed last, so
    /// a crash between secondary entries resumes this journal on relaunch.
    private func reconcileAdditionalTerminalFullDrainGaps(
        identity: AtriaHistoricalFullDrainCoverageStore.EventIdentity
    ) throws {
        guard Self.validGapLedgerResolutionSnapshot() != nil else {
            throw AtriaBLEHistoryTerminalMaterializationError
                .gapLedgerQuarantined
        }
        guard var authority = try historicalFullDrainCoverageStore.load(),
              authority.publication?.status == .projectionsPublished else {
            throw Self.terminalCheckpointMissing("site\(#line)")
        }
        for snapshot in authority.terminalGapReconciliations ?? [] {
            guard snapshot.status == .coverageProven
                    || snapshot.status == .resolutionPrepared,
                  let gapID = UUID(uuidString: snapshot.gap.gapIdentifier),
                  let proof = snapshot.coverageProof else { continue }

            var entry = snapshot
            var exact = AtriaHistoricalGapLedger.recoveryCandidate(
                id: gapID,
                startUnix: entry.gap.startUnix,
                endUnix: entry.gap.endUnix,
                reason: entry.gap.reason
            )
            guard let ledgerBeforeIntent = Self.validGapLedgerResolutionSnapshot() else {
                throw AtriaBLEHistoryTerminalMaterializationError
                    .gapLedgerQuarantined
            }
            let sameIDBeforeIntent = ledgerBeforeIntent.contains {
                $0.id == gapID
            }
            if entry.status == .coverageProven {
                // An already-absent row has no transaction ambiguity to solve;
                // do not retroactively claim this terminal removed it.
                guard exact != nil || sameIDBeforeIntent else { continue }
                authority = try historicalFullDrainCoverageStore
                    .prepareTerminalGapResolution(
                        identity: identity,
                        gapIdentifier: entry.gap.gapIdentifier,
                        at: Date()
                    )
                guard let prepared = authority.terminalGapReconciliations?
                    .first(where: {
                        $0.gap.gapIdentifier == entry.gap.gapIdentifier
                    }) else {
                    throw Self.terminalCheckpointMissing("site\(#line)")
                }
                entry = prepared
                guard Self.validGapLedgerResolutionSnapshot() != nil else {
                    throw AtriaBLEHistoryTerminalMaterializationError
                        .gapLedgerQuarantined
                }
                exact = exact ?? AtriaHistoricalGapLedger.recoveryCandidate(
                    id: gapID,
                    startUnix: entry.gap.startUnix,
                    endUnix: entry.gap.endUnix,
                    reason: entry.gap.reason
                )
            }

            guard let ledgerBeforeStaging = Self.validGapLedgerResolutionSnapshot() else {
                throw AtriaBLEHistoryTerminalMaterializationError
                    .gapLedgerQuarantined
            }
            if exact == nil,
               ledgerBeforeStaging.contains(where: {
                   $0.id == gapID
               }) {
                authority = try historicalFullDrainCoverageStore
                    .finishTerminalGapResolution(
                        identity: identity,
                        gapIdentifier: entry.gap.gapIdentifier,
                        resolved: false,
                        at: Date()
                    )
                continue
            }

            _ = AtriaHistoricalGapLedger.stageMetricUsableRows(
                at: Self.coverageDates(
                    from: proof,
                    cadenceSeconds: authority.configuration.cadenceSeconds,
                    gapStartUnix: entry.gap.startUnix
                ),
                forWindowID: gapID
            )
            guard let ledgerAfterStaging = Self.validGapLedgerResolutionSnapshot() else {
                throw AtriaBLEHistoryTerminalMaterializationError
                    .gapLedgerQuarantined
            }
            // Staging coverage advances the durable ledger generation. Bind
            // the delete CAS to that new canonical generation, not the
            // pre-staging selection snapshot.
            exact = AtriaHistoricalGapLedger.recoveryCandidate(
                id: gapID,
                startUnix: entry.gap.startUnix,
                endUnix: entry.gap.endUnix,
                reason: entry.gap.reason
            )
            let sameIDStillExists = ledgerAfterStaging.contains {
                $0.id == gapID
            }
            let removed = exact.map {
                AtriaHistoricalGapLedger.commitResolvedWindow(candidate: $0)
            } ?? false
            guard Self.validGapLedgerResolutionSnapshot() != nil else {
                throw AtriaBLEHistoryTerminalMaterializationError
                    .gapLedgerQuarantined
            }
            let resolved = removed || !sameIDStillExists
            authority = try historicalFullDrainCoverageStore
                .finishTerminalGapResolution(
                    identity: identity,
                    gapIdentifier: entry.gap.gapIdentifier,
                    resolved: resolved,
                    at: Date()
                )
            AtriaDebugLog("ATRIADBG historical_full_drain_reconcile gap=%@ generation=%llu status=%@ density=%d maximum_gap=%d p95_gap=%d",
                          entry.gap.gapIdentifier,
                          authority.attempt.transportGeneration,
                          resolved ? "resolved" : "preserved_exact_cas_mismatch",
                          proof.densityPercent,
                          proof.maximumGapSeconds,
                          proof.p95GapSeconds)
        }
    }

    /// Exact metric coverage and app-facing raw recovery are sufficient to
    /// close the missing-data window. Typed sleep/activity/workout projections
    /// stay pending when their honest dependency range extends into the future;
    /// no receipt or empty outcome is fabricated for that unsettled range.
    private func commitFullDrainGapPendingConsumers(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority,
        identity: AtriaHistoricalFullDrainCoverageStore.EventIdentity,
        gapID: UUID,
        dependency: AtriaHistoricalFullDrainCoverageStore.PendingConsumerDependency
    ) {
        guard authority.status == .coverageProven
                || authority.status == .gapResolvedConsumersPending else {
            finishHistoricalConsumerMaterialization(
                reason: "pending_consumers_invalid_authority"
            )
            return
        }
        if authority.status == .gapResolvedConsumersPending {
            offlineHistoricalSyncResolvedGapCoverage = true
            _ = reconcileRangeLossBackfillPendingWithArchive(
                reason: "full_drain_exact_gap_consumers_pending_resume",
                requestedWindowMetricProgress: true,
                ledgerCoverageResolved: true
            )
            finishHistoricalConsumerMaterialization(
                reason: "pending_consumers_already_resolved"
            )
            onHistoricalTransportOwnershipReleased?(
                "full_drain_gap_already_resolved_consumers_pending"
            )
            return
        }
        do {
            _ = try historicalFullDrainCoverageStore.recordPendingConsumerDependency(
                identity: identity,
                dependency: dependency
            )
            let prepared = try historicalFullDrainCoverageStore
                .prepareGapResolution(identity: identity, at: Date())
            guard commitFullDrainGapLedgerCAS(authority: prepared, gapID: gapID) else {
                finishHistoricalConsumerMaterialization(
                    reason: "pending_consumers_gap_cas_failed"
                )
                return
            }
            let resolved = try historicalFullDrainCoverageStore.resolve(
                identity: identity,
                at: Date()
            )
            guard resolved.status == .gapResolvedConsumersPending else {
                throw AtriaBLEHistoryTerminalMaterializationError
                    .incompleteConsumerCoverage
            }
            offlineHistoricalSyncResolvedGapCoverage = true
            _ = reconcileRangeLossBackfillPendingWithArchive(
                reason: "full_drain_exact_gap_consumers_pending",
                requestedWindowMetricProgress: true,
                ledgerCoverageResolved: true
            )
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=gap_resolved_consumers_pending generation=%llu gap=%@ required_end=%.3f receipts=0 raw_retained=1",
                          authority.attempt.transportGeneration,
                          authority.gap.gapIdentifier,
                          dependency.requiredEndUnix)
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=pending_resolve_%@ gap_already_removed=1",
                          authority.attempt.transportGeneration,
                          String(describing: error))
        }
        finishHistoricalConsumerMaterialization(
            reason: "pending_consumers_complete"
        )
        onHistoricalTransportOwnershipReleased?(
            "full_drain_gap_resolved_consumers_pending"
        )
    }

    private func commitFullDrainGapAfterConsumers(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority,
        identity: AtriaHistoricalFullDrainCoverageStore.EventIdentity,
        gapID: UUID
    ) {
        guard authority.status == .consumersCommitted else {
            finishHistoricalConsumerMaterialization(
                reason: "consumer_commit_invalid_authority"
            )
            return
        }
        do {
            let prepared = try historicalFullDrainCoverageStore
                .prepareGapResolution(identity: identity, at: Date())
            guard commitFullDrainGapLedgerCAS(authority: prepared, gapID: gapID) else {
                finishHistoricalConsumerMaterialization(
                    reason: "consumer_commit_gap_cas_failed"
                )
                return
            }
            _ = try historicalFullDrainCoverageStore.resolve(
                identity: identity,
                at: Date()
            )
            historicalConsumerReceiptedGenerations.insert(
                authority.attempt.transportGeneration
            )
            offlineHistoricalSyncResolvedGapCoverage = true
            _ = reconcileRangeLossBackfillPendingWithArchive(
                reason: "full_drain_consumers_committed",
                requestedWindowMetricProgress: true,
                ledgerCoverageResolved: true
            )
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=resolved generation=%llu gap=%@ receipts=5",
                          authority.attempt.transportGeneration,
                          authority.gap.gapIdentifier)
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=resolve_%@ gap_already_removed=%d",
                          authority.attempt.transportGeneration,
                          String(describing: error),
                          1)
        }
        finishHistoricalConsumerMaterialization(reason: "consumer_commit_complete")
    }

    /// `recordCommittedConsumers` advances a future-dependent authority from
    /// gap-resolved-pending directly to resolved. The exact ledger row was
    /// already removed by the earlier prepared transaction, so this path only
    /// completes app-facing reconciliation and never performs a second delete.
    private func finalizeAlreadyResolvedFullDrainConsumers(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority
    ) {
        guard authority.status == .resolved,
              authority.consumerCommit != nil,
              authority.resolvedAtUnix != nil else {
            finishHistoricalConsumerMaterialization(
                reason: "resolved_consumers_invalid_authority"
            )
            return
        }
        offlineHistoricalSyncResolvedGapCoverage = true
        historicalConsumerReceiptedGenerations.insert(
            authority.attempt.transportGeneration
        )
        _ = reconcileRangeLossBackfillPendingWithArchive(
            reason: "full_drain_consumers_committed_after_pending",
            requestedWindowMetricProgress: true,
            ledgerCoverageResolved: true
        )
        AtriaDebugLog("ATRIADBG historical_full_drain_publish status=resolved_after_consumers_pending generation=%llu gap=%@ receipts=5 ledger_delete_replayed=0",
                      authority.attempt.transportGeneration,
                      authority.gap.gapIdentifier)
        finishHistoricalConsumerMaterialization(
            reason: "resolved_consumers_complete"
        )
    }

    private func commitFullDrainGapLedgerCAS(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority,
        gapID: UUID
    ) -> Bool {
        guard authority.gapResolutionPreparedAtUnix != nil else {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=gap_resolution_intent_missing gap_retained=1",
                          authority.attempt.transportGeneration)
            return false
        }
        if let proof = authority.coverageProof {
            _ = AtriaHistoricalGapLedger.stageMetricUsableRows(
                at: Self.coverageDates(from: proof,
                                       cadenceSeconds: authority.configuration.cadenceSeconds,
                                       gapStartUnix: authority.gap.startUnix),
                forWindowID: gapID
            )
        }
        guard let ledgerBeforeCAS = Self.validGapLedgerResolutionSnapshot() else {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=gap_ledger_quarantined gap_retained=1",
                          authority.attempt.transportGeneration)
            return false
        }
        let exact = AtriaHistoricalGapLedger.recoveryCandidate(
            id: gapID,
            startUnix: authority.gap.startUnix,
            endUnix: authority.gap.endUnix,
            reason: authority.gap.reason
        )
        let sameIDStillExists = ledgerBeforeCAS.contains {
            $0.id == gapID
        }
        let removed = exact.map {
            AtriaHistoricalGapLedger.commitResolvedWindow(candidate: $0)
        } ?? false
        guard Self.validGapLedgerResolutionSnapshot() != nil else {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=gap_ledger_quarantined_after_cas gap_retained=1",
                          authority.attempt.transportGeneration)
            return false
        }
        // With the fsynced exact intent above, `!sameIDStillExists` is the
        // unambiguous crash-resume case after a successful CAS but before the
        // authority's resolved fsync. A changed/compacted row reusing the UUID
        // never reaches resolve.
        guard removed || !sameIDStillExists else {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=gap_candidate_cas_mismatch gap_retained=1",
                          authority.attempt.transportGeneration)
            return false
        }
        return true
    }

    /// Resolution is authorized only from the canonical valid ledger. The
    /// ledger deliberately exposes durable corruption as a non-selectable
    /// sentinel so callers cannot confuse quarantine with an empty ledger.
    /// Empty is valid here: it is the expected crash-resume state after an
    /// exact CAS succeeded but before the full-drain authority was fsynced.
    nonisolated static func gapLedgerSnapshotIsValidForResolution(
        _ windows: [AtriaHistoricalGapLedger.Window]
    ) -> Bool {
        !windows.contains {
            $0.reason.hasPrefix("durable_gap_ledger_corrupt_")
        }
    }

    private nonisolated static func validGapLedgerResolutionSnapshot()
        -> [AtriaHistoricalGapLedger.Window]? {
        guard AtriaHistoricalGapLedger.durableStateIsValid() else { return nil }
        let windows = AtriaHistoricalGapLedger.windows()
        guard AtriaHistoricalGapLedger.durableStateIsValid(),
              gapLedgerSnapshotIsValidForResolution(windows) else { return nil }
        return windows
    }

    private nonisolated static func fullDrainEventIdentity(
        for authority: AtriaHistoricalFullDrainCoverageStore.Authority
    ) -> AtriaHistoricalFullDrainCoverageStore.EventIdentity {
        .init(
            gapIdentifier: authority.gap.gapIdentifier,
            attemptIdentifier: authority.attempt.attemptIdentifier,
            peripheralIdentifier: authority.attempt.peripheralIdentifier,
            strapIdentity: authority.attempt.strapIdentity,
            transportNonce: authority.attempt.transportNonce,
            transportGeneration: authority.attempt.transportGeneration
        )
    }

    private nonisolated static func fullDrainConsumerReceipts(
        from publishedReceipts: [AtriaHistoricalConsumerReceiptLedger.Published],
        authority: AtriaHistoricalFullDrainCoverageStore.Authority
    ) throws -> [AtriaHistoricalFullDrainCoverageStore.ConsumerReceipt] {
        guard let terminal = authority.historyComplete else {
            throw Self.terminalCheckpointMissing("site\(#line)")
        }
        return try publishedReceipts.map { published in
            let kind: String
            switch published.receipt.kind {
            case .activity: kind = "activity"
            case .dailyMetrics: kind = "daily_metrics"
            case .sleep: kind = "sleep"
            case .steps: kind = "steps"
            case .workout: kind = "workout"
            case .replayIdentity:
                throw AtriaBLEHistoryTerminalMaterializationError
                    .unexpectedConsumerKind
            }
            let receiptData = try Data(contentsOf: published.receiptURL)
            return .init(
                kind: kind,
                receiptSHA256: AtriaHistoricalFullDrainCoveragePolicy.sha256(receiptData),
                artifactSHA256: published.receipt.artifactSHA256,
                sourceRawSnapshotSHA256: terminal.stores.raw.snapshotSHA256,
                sourceIdentitySnapshotSHA256: terminal.stores.identity.snapshotSHA256,
                sourceAdmissionSnapshotSHA256: terminal.stores.admission.snapshotSHA256,
                gapIdentifier: authority.gap.gapIdentifier,
                attemptIdentifier: authority.attempt.attemptIdentifier,
                completionIdentifier: terminal.completionIdentifier,
                commitIdentifier: published.receiptURL.lastPathComponent,
                committedAtUnix: published.receipt.settledAt.timeIntervalSince1970
            )
        }.sorted { $0.kind < $1.kind }
    }

    private nonisolated static func coverageDates(
        from proof: AtriaHistoricalFullDrainCoveragePolicy.CoverageProof,
        cadenceSeconds: Int,
        gapStartUnix: TimeInterval
    ) -> [Date] {
        guard cadenceSeconds > 0 else { return [] }
        var dates: [Date] = []
        dates.reserveCapacity(proof.observedBuckets)
        for index in 0..<proof.expectedBuckets {
            let byte = index / 8
            let bit = UInt8(1 << UInt8(index % 8))
            guard proof.coveredBucketBits.indices.contains(byte),
                  proof.coveredBucketBits[byte] & bit != 0 else { continue }
            dates.append(Date(timeIntervalSince1970:
                gapStartUnix + Double(index * cadenceSeconds)))
        }
        return dates
    }

    private nonisolated func terminalAdmissionReceipt(
        _ authority: AtriaHistoricalFullDrainCoverageStore.Authority
    ) throws -> AtriaWhoop4HistoryAdmissionLedger.PrefixDurabilityReceipt {
        guard let receipt = authority.historyComplete?.stores.admissionReceipt else {
            throw AtriaBLEHistoryTerminalMaterializationError
                .admissionIdentityNotDurable
        }
        return receipt
    }

    private func resetTerminalConsumerRawFirstSliceRefusal() {
        terminalConsumerRawFirstSliceTimeoutTask?.cancel()
        terminalConsumerRawFirstSliceTimeoutTask = nil
        terminalConsumerRawFirstSliceRefusal = nil
    }

    private func shouldDeferTerminalConsumerMaterializationForRawFirstSlice(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority,
        reason: String,
        now: Date = Date()
    ) -> Bool {
        if terminalConsumerRawFirstSliceRefusal?.authorityIdentifier
            != authority.authorityIdentifier {
            resetTerminalConsumerRawFirstSliceRefusal()
            terminalConsumerRawFirstSliceRefusal = .init(
                authorityIdentifier: authority.authorityIdentifier,
                deadline: now.addingTimeInterval(
                    terminalConsumerRawFirstSliceBudget
                ),
                rawGeneration: nil,
                spent: false
            )
        }
        guard var refusal = terminalConsumerRawFirstSliceRefusal else {
            return false
        }
        let activeExplicitWorkout = Self
            .explicitMotionOwnershipBlocksHistory(
                pendingWorkoutIntentActive:
                    AtriaPendingWorkoutIntent
                        .isActiveForBLEContinuity(now: now),
                inMemoryLeaseHeld: workoutMotionOwnerStartedAt != nil,
                calibrationHoldActive:
                    workoutMotionCalibrationHoldUntil.map { now < $0 }
                        == true
            )
        let shouldDefer = Self
            .shouldDeferTerminalConsumerMaterializationForRawFirstSlice(
                applicationIsActive:
                    UIApplication.shared.applicationState == .active,
                strapBacklogPending:
                    strapBacklogPendingForCatchUp(now: now),
                verifiedRawHistoryCapability:
                    currentVerifiedRawHistoryCapability(),
                linkConnected:
                    peripheral?.state == .connected
                        && status == .connected,
                activeExplicitWorkout: activeExplicitWorkout,
                rawThermalPressureActive: Self
                    .shouldParkConnectedRawHistoryCatchUpForPowerPressure(
                        thermalState: ProcessInfo.processInfo.thermalState
                    ),
                publicationYieldActive:
                    connectedRawHistoryCatchUpPublicationYield != nil,
                rawFirstSliceSpent: refusal.spent,
                now: now,
                deadline: refusal.deadline
            )
        guard shouldDefer else {
            refusal.spent = true
            terminalConsumerRawFirstSliceRefusal = refusal
            terminalConsumerRawFirstSliceTimeoutTask?.cancel()
            terminalConsumerRawFirstSliceTimeoutTask = nil
            return false
        }

        resumeFullDrainPublicationAfterFreshHR = true
        if terminalConsumerRawFirstSliceTimeoutTask == nil {
            let authorityIdentifier = refusal.authorityIdentifier
            let deadline = refusal.deadline
            let delay = max(0.1, deadline.timeIntervalSince(now))
            terminalConsumerRawFirstSliceTimeoutTask = Task {
                @MainActor [weak self] in
                try? await Task.sleep(for: .seconds(delay))
                guard !Task.isCancelled,
                      let self,
                      let current = self
                        .terminalConsumerRawFirstSliceRefusal,
                      current.authorityIdentifier == authorityIdentifier,
                      !current.spent else { return }
                let transition = Self
                    .transitionTerminalConsumerRawFirstSlice(
                        state: current,
                        event: .deadlineReached(max(Date(), deadline))
                    )
                guard transition.shouldResumeLocalMaterialization else {
                    return
                }
                self.terminalConsumerRawFirstSliceRefusal = transition.state
                self.terminalConsumerRawFirstSliceTimeoutTask = nil
                self.resumePendingFullDrainPublicationIfNeeded(
                    reason: "raw_first_slice_deadline"
                )
            }
        }
        UserDefaults.standard.set(
            "terminal_consumer_materialization_deferred_raw_first_slice",
            forKey: OfflineSyncDefaults.lastStatus
        )
        UserDefaults.standard.set(reason, forKey: OfflineSyncDefaults.lastReason)
        AtriaDebugLog(
            "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=raw_first_slice deadline_unix=%.3f action=await_one_exact_raw_generation_then_existing_publication_yield",
            authority.attempt.transportGeneration,
            refusal.deadline.timeIntervalSince1970
        )
        return true
    }

    private func bindTerminalConsumerRawFirstSliceIfNeeded(
        generation: UInt64
    ) {
        guard let refusal = terminalConsumerRawFirstSliceRefusal else {
            return
        }
        let transition = Self.transitionTerminalConsumerRawFirstSlice(
            state: refusal,
            event: .bindRawGeneration(generation)
        )
        terminalConsumerRawFirstSliceRefusal = transition.state
    }

    private func spendTerminalConsumerRawFirstSliceIfNeeded(
        generation: UInt64
    ) {
        guard let refusal = terminalConsumerRawFirstSliceRefusal else {
            return
        }
        let transition = Self.transitionTerminalConsumerRawFirstSlice(
            state: refusal,
            event: .finishRawGeneration(generation)
        )
        guard transition.shouldResumeLocalMaterialization else { return }
        terminalConsumerRawFirstSliceRefusal = transition.state
        terminalConsumerRawFirstSliceTimeoutTask?.cancel()
        terminalConsumerRawFirstSliceTimeoutTask = nil
        resumeFullDrainPublicationAfterFreshHR = true
        AtriaDebugLog(
            "ATRIADBG historical_full_drain_publish status=raw_first_slice_spent generation=%llu action=resume_terminal_materialization_through_existing_publication_yield",
            generation
        )
    }

    /// Called after SessionStore installs the recovered-data publication fence.
    /// It never starts BLE; it only resumes an already-fsynced terminal journal.
    func resumePendingFullDrainPublicationIfNeeded(reason: String) {
        guard !historicalRadioTransportOwnsLink,
              !connectedMotionBankFirstAttemptOwnsForegroundPriority else {
            // A same-link motion-bank generation keeps standard HR healthy, but
            // its callback/file budget must not overlap a whole-archive terminal
            // publisher. Keep one edge-triggered intent; accepted HR consumes it
            // only after the exact radio owner has fully released.
            resumeFullDrainPublicationAfterFreshHR = true
            return
        }
        do {
            guard let authority = try historicalFullDrainCoverageStore.load(),
                  authority.status == .historyComplete
                    || authority.status == .coverageProven
                    || authority.status == .gapResolvedConsumersPending
                    || authority.status == .consumersCommitted else {
                resetTerminalConsumerRawFirstSliceRefusal()
                return
            }
            // A CoreBluetooth restoration launch is CPU-budgeted background
            // time. Terminal consumer settlement can scan the full retained
            // archive and must never consume that lease: doing so has produced
            // repeated cpu_resource_fatal terminations before live ownership
            // could remain resident. The journal is already fsynced, so defer
            // only this local projection until the UI is genuinely active.
            guard Self.shouldRunTerminalConsumerMaterialization(
                applicationIsActive:
                    UIApplication.shared.applicationState == .active
            ) else {
                UserDefaults.standard.set(
                    "terminal_consumer_materialization_deferred_foreground",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                UserDefaults.standard.set(
                    reason,
                    forKey: OfflineSyncDefaults.lastReason
                )
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu stage=%@ reason=background_cpu_budget action=preserve_live_wait_for_foreground",
                    authority.attempt.transportGeneration,
                    authority.status.rawValue
                )
                return
            }
            guard !shouldDeferTerminalConsumerMaterializationForRawFirstSlice(
                authority: authority,
                reason: reason
            ) else { return }
            guard prepareHistoricalAdmissionLedgerIfNeeded(
                reason: "terminal_publication_\(reason)"
            ) else {
                resumeFullDrainPublicationAfterFreshHR = true
                UserDefaults.standard.set(
                    "preparing_terminal_admission_ledger",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=preparing_admission_ledger trigger=%@ action=resume_when_ledger_ready",
                    authority.attempt.transportGeneration,
                    reason
                )
                return
            }
            guard peripheral?.state == .connected,
                  status == .connected,
                  let connectedAt,
                  let lastAcceptedHRAt,
                  lastAcceptedHRAt >= connectedAt else {
                resumeFullDrainPublicationAfterFreshHR = true
                AtriaDebugLog("ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=awaiting_current_epoch_fresh_hr gap_retained=1",
                              authority.attempt.transportGeneration)
                return
            }
            let defaults = UserDefaults.standard
            // A fresh cached failure suppresses regardless of what the
            // fingerprint would say (the daily bound), so short-circuit
            // BEFORE computing it: the fingerprint acquires the shared
            // archive-catalog lock, and taking that lock on the main thread
            // while the .utility archive lane holds it through hundreds of
            // megabytes of hashing was the 2026-07-31 foreground hang —
            // NSLock donates no priority, so the UI froze without a watchdog
            // kill. Two UserDefaults reads settle the common case instead.
            // The daily bound guards the fingerprint's archive-lock cost on
            // the main thread — but it must not outlive the condition that
            // caused the failure. If the pending dependency's REQUIRED END
            // has passed since the failure was cached, satisfiability itself
            // changed and the bound no longer describes the same situation
            // (2026-08-06: a pre-midnight completionCoverageMismatch parked
            // publication a full day even though its window closed at 00:10).
            // Two already-decoded fields — no lock, no scan, no hang risk.
            let dependencyWindowPassedSince: (Date) -> Bool = { cachedAt in
                guard let dependency = authority.pendingConsumerDependency,
                      dependency.isValid else { return false }
                let end = Date(timeIntervalSince1970: dependency.requiredEndUnix)
                return end <= Date() && cachedAt < end
            }
            // Retire the cached failure ENTIRELY when its window has since
            // passed — otherwise the fingerprint-equality suppressions below
            // would keep skipping the real attempt even after the daily
            // bound yields (observed 2026-08-06 09:21: bound bypassed, then
            // snapshot_unchanged from the equality site).
            if let staleCachedAt = defaults.object(
                forKey: Self.terminalConsumerCoverageFailureAtKey
            ) as? Date,
               dependencyWindowPassedSince(staleCachedAt) {
                defaults.removeObject(
                    forKey: Self.terminalConsumerCoverageFailureKey
                )
                defaults.removeObject(
                    forKey: Self.terminalConsumerCoverageFailureAtKey
                )
                // The persisted typed diagnostic must retire with the cache:
                // the seed-from-diagnostic path below otherwise re-mints the
                // exact keys just removed (observed 2026-08-06 09:28 —
                // retire ran, seeding resurrected the 23:28 failure).
                defaults.removeObject(
                    forKey: "atria.offlineSync.terminalArchiveFailureDiagnostic.v1"
                )
                defaults.removeObject(
                    forKey: "atria.offlineSync.terminalArchiveFailureAt.v1"
                )
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=coverage_failure_cache_retired reason=dependency_window_passed generation=%llu",
                    authority.attempt.transportGeneration
                )
            }
            if let freshCachedAt = defaults.object(
                forKey: Self.terminalConsumerCoverageFailureAtKey
            ) as? Date,
               defaults.string(
                   forKey: Self.terminalConsumerCoverageFailureKey
               ) != nil,
               Date().timeIntervalSince(freshCachedAt) >= 0,
               Date().timeIntervalSince(freshCachedAt)
                   < Self.terminalConsumerCoverageFailureRetryInterval,
               !dependencyWindowPassedSince(freshCachedAt) {
                defaults.set(
                    "terminal_consumer_coverage_snapshot_unchanged",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=coverage_failure_daily_bound action=skip_fingerprint_and_archive_rescan",
                    authority.attempt.transportGeneration
                )
                return
            }
            let terminalCoverageFailureFingerprint =
                terminalConsumerCoverageFailureFingerprint(
                    authority: authority
                )
            var cachedTerminalCoverageFailureFingerprint =
                defaults.string(
                    forKey: Self.terminalConsumerCoverageFailureKey
                )
            if Self.shouldSeedTerminalConsumerCoverageFailureFromDiagnostic(
                cachedFingerprint:
                    cachedTerminalCoverageFailureFingerprint,
                currentFingerprint:
                    terminalCoverageFailureFingerprint,
                persistedFailureDiagnostic: defaults.string(
                    forKey:
                        "atria.offlineSync.terminalArchiveFailureDiagnostic.v1"
                )
            ), let terminalCoverageFailureFingerprint {
                // Builds installed after a deterministic failure already
                // persisted its typed diagnostic but not the newer snapshot
                // lease. Bind that existing failure to today's unchanged
                // durable authority without paying for one more watchdog-risk
                // scan merely to rediscover the same error.
                defaults.set(
                    terminalCoverageFailureFingerprint,
                    forKey: Self.terminalConsumerCoverageFailureKey
                )
                if defaults.object(
                    forKey: Self.terminalConsumerCoverageFailureAtKey
                ) == nil {
                    defaults.set(
                        defaults.object(
                            forKey:
                                "atria.offlineSync.terminalArchiveFailureAt.v1"
                        ) as? Date ?? Date(),
                        forKey: Self.terminalConsumerCoverageFailureAtKey
                    )
                }
                cachedTerminalCoverageFailureFingerprint =
                    terminalCoverageFailureFingerprint
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=migrated_completion_coverage_mismatch action=seed_unchanged_terminal_snapshot_without_rescan",
                    authority.attempt.transportGeneration
                )
            }
            if Self.shouldSuppressUnchangedTerminalConsumerCoverageFailure(
                cachedFingerprint:
                    cachedTerminalCoverageFailureFingerprint,
                currentFingerprint: terminalCoverageFailureFingerprint,
                cachedAt: defaults.object(
                    forKey: Self.terminalConsumerCoverageFailureAtKey
                ) as? Date,
                now: Date()
            ) {
                defaults.set(
                    "terminal_consumer_coverage_snapshot_unchanged",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                defaults.set(reason, forKey: OfflineSyncDefaults.lastReason)
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=unchanged_completion_coverage_mismatch action=retain_terminal_journal_skip_full_archive_rescan",
                    authority.attempt.transportGeneration
                )
                return
            }
            // Any changed terminal authority, full-scan checkpoint, current
            // catalog image, time-zone, or projection algorithm invalidates
            // the deterministic failure. Preserve the raw journal and retry
            // against the new immutable dependency set.
            if defaults.string(
                forKey: Self.terminalConsumerCoverageFailureKey
            ) != nil, terminalCoverageFailureFingerprint != nil {
                defaults.removeObject(
                    forKey: Self.terminalConsumerCoverageFailureKey
                )
                defaults.removeObject(
                    forKey: Self.terminalConsumerCoverageFailureAtKey
                )
            }
            let dependencyFingerprint =
                Self.terminalConsumerDependencyFingerprint(
                    authority: authority,
                    timeZoneIdentifier: TimeZone.current.identifier
                )
            if Self.shouldSuppressTerminalConsumerDependencyRetry(
                cachedFingerprint: defaults.string(
                    forKey: Self.terminalConsumerDependencyMismatchKey
                ),
                currentFingerprint: dependencyFingerprint,
                cachedAt: defaults.object(
                    forKey: Self.terminalConsumerDependencyMismatchAtKey
                ) as? Date,
                now: Date()
            ) {
                defaults.set(
                    "terminal_consumer_dependency_incompatible",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                defaults.set(
                    reason,
                    forKey: OfflineSyncDefaults.lastReason
                )
                AtriaDebugLog(
                    "ATRIADBG historical_full_drain_publish status=deferred generation=%llu reason=pending_dependency_model_mismatch_cached action=retain_old_journal_release_archive_lane",
                    authority.attempt.transportGeneration
                )
                return
            }
            // A changed publication model or an expired bounded backoff must
            // get a fresh attempt. The exact terminal journal remains durable,
            // so clearing only this retry lease cannot lose raw history.
            defaults.removeObject(
                forKey: Self.terminalConsumerDependencyMismatchKey
            )
            defaults.removeObject(
                forKey: Self.terminalConsumerDependencyMismatchAtKey
            )
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=resuming generation=%llu stage=%@ reason=%@",
                          authority.attempt.transportGeneration,
                          authority.status.rawValue,
                          reason)
            scheduleFullDrainConsumerMaterialization(
                transportGeneration: authority.attempt.transportGeneration
            )
        } catch {
            AtriaDebugLog("ATRIADBG historical_full_drain_publish status=resume_deferred reason=%@ error=%@ gap_retained=1",
                          reason,
                          String(describing: error))
        }
    }

    /// A glance close publishes this durable, exact attempts-zero reservation
    /// before its one-second asynchronous admission task runs. It closes the
    /// small pre-generation window in which an unrelated terminal publisher (or
    /// an accepted-HR resume edge) could otherwise seize the archive lane first.
    /// Once the attempt starts the maintenance marker retires; if power pressure
    /// parks it, present capture is rearmed and therefore releases this priority.
    private var connectedMotionBankFirstAttemptOwnsForegroundPriority: Bool {
        guard !workoutHistoricalMotionBankArmed,
              let connected = peripheral,
              connected.state == .connected else { return false }
        return pendingWorkoutHistoricalMotionBankMaintenanceTicket(
            strapIdentifier: connected.identifier.uuidString,
            defaults: .standard
        ) != nil
    }

    nonisolated static func shouldRunTerminalConsumerMaterialization(
        applicationIsActive: Bool
    ) -> Bool {
        applicationIsActive
    }

    private func scheduleTerminalConsumerDependencyRetry() {
        terminalConsumerDependencyRetryTask?.cancel()
        terminalConsumerDependencyRetryTask = Task { @MainActor [weak self] in
            try? await Task.sleep(
                for: .seconds(
                    Self.terminalConsumerDependencyMismatchRetryInterval
                )
            )
            guard !Task.isCancelled, let self else { return }
            self.terminalConsumerDependencyRetryTask = nil
            self.resumePendingFullDrainPublicationIfNeeded(
                reason: "terminal_dependency_retry"
            )
        }
    }

    private func scheduleTerminalCatalogMaterializationRetry() {
        terminalCatalogMaterializationRetryTask?.cancel()
        terminalCatalogMaterializationRetryTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(250))
            guard !Task.isCancelled, let self else { return }
            self.terminalCatalogMaterializationRetryTask = nil
            self.resumePendingFullDrainPublicationIfNeeded(
                reason: "sealed_catalog_materialization_retry"
            )
        }
    }

    nonisolated static func shouldSuppressTerminalConsumerDependencyRetry(
        cachedFingerprint: String?,
        currentFingerprint: String?,
        cachedAt: Date?,
        now: Date,
        retryInterval: TimeInterval =
            terminalConsumerDependencyMismatchRetryInterval
    ) -> Bool {
        guard let cachedFingerprint,
              let currentFingerprint,
              cachedFingerprint == currentFingerprint,
              let cachedAt,
              retryInterval > 0 else {
            return false
        }
        let age = now.timeIntervalSince(cachedAt)
        return age >= 0 && age < retryInterval
    }

    /// One coverage-mismatch retry per day at most. The unchanged-fingerprint
    /// rule alone was not enough on real hardware: every background drain that
    /// seals a chunk advances the catalog identity, which re-armed the full
    /// archive projection on the next foreground. For an authority whose gap
    /// rows the strap has never served, each of those retries allocates the
    /// whole projection working set and fails identically — physical
    /// 2026-07-31 20:30 IST evidence: Atria frontmost at ~3.4 GB against its
    /// per-process jetsam limit, hanging until force-quit. Catalog growth from
    /// live capture is not new evidence about a historical gap; a bounded
    /// daily retry (the failure timestamp refreshes on every failure) plus
    /// the existing projection-model escape keeps an eventual real recovery
    /// reachable without letting the doomed path own the foreground.
    nonisolated static let terminalConsumerCoverageFailureRetryInterval:
        TimeInterval = 24 * 60 * 60

    nonisolated static func
        shouldSuppressUnchangedTerminalConsumerCoverageFailure(
            cachedFingerprint: String?,
            currentFingerprint: String?,
            cachedAt: Date? = nil,
            now: Date = Date()
        ) -> Bool {
        guard let cachedFingerprint,
              let currentFingerprint else {
            return false
        }
        if cachedFingerprint == currentFingerprint {
            // Handoff-12: fingerprint equality used to suppress forever — the
            // fingerprint carries no clock or frontier term, so a stable
            // authority could park every terminal consumer permanently
            // (physically observed Aug-13: sleep projection starved behind
            // one cached coverage failure). Equality still suppresses, but
            // only inside the same bounded retry interval as inequality.
            guard let cachedAt else { return true }
            let age = now.timeIntervalSince(cachedAt)
            return age >= 0
                && age < Self.terminalConsumerCoverageFailureRetryInterval
        }
        guard let cachedAt else { return false }
        let age = now.timeIntervalSince(cachedAt)
        return age >= 0
            && age < Self.terminalConsumerCoverageFailureRetryInterval
    }

    nonisolated static func
        shouldSeedTerminalConsumerCoverageFailureFromDiagnostic(
            cachedFingerprint: String?,
            currentFingerprint: String?,
            persistedFailureDiagnostic: String?
        ) -> Bool {
        guard cachedFingerprint == nil,
              currentFingerprint != nil,
              let persistedFailureDiagnostic else {
            return false
        }
        return persistedFailureDiagnostic.contains(
            "completionCoverageMismatch"
        )
    }

    private func terminalConsumerCoverageFailureFingerprint(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority
    ) -> String? {
        guard let dependencyFingerprint =
                Self.terminalConsumerDependencyFingerprint(
                    authority: authority,
                    timeZoneIdentifier: TimeZone.current.identifier
                ),
              let fullScan = try? historicalFullScanCompletionStore
                .loadLatest(),
              let catalogFingerprint = HistoricalArchive
                .terminalConsumerRetryCatalogFingerprint() else {
            return nil
        }
        return Self.terminalConsumerCoverageFailureFingerprint(
            dependencyFingerprint: dependencyFingerprint,
            fullScanVersion: fullScan.version,
            fullScanGeneration: fullScan.generation,
            fullScanTransportGeneration: fullScan.transportGeneration,
            sourceChunkID: fullScan.sourceChunkID,
            sourceRawSHA256: fullScan.sourceRawSHA256,
            observedArchiveFirstTimestamp:
                fullScan.observedArchiveFirstTimestamp,
            cursorWatermark: fullScan.cursorWatermark,
            catalogGeneration: fullScan.catalogGeneration,
            catalogSnapshotSHA256: fullScan.catalogSnapshotSHA256,
            aggregateSnapshotSHA256: fullScan.aggregateSnapshotSHA256,
            currentCatalogFingerprint: catalogFingerprint
        )
    }

    nonisolated static func terminalConsumerCoverageFailureFingerprint(
        dependencyFingerprint: String?,
        fullScanVersion: Int,
        fullScanGeneration: UInt64,
        fullScanTransportGeneration: UInt64,
        sourceChunkID: String,
        sourceRawSHA256: String,
        observedArchiveFirstTimestamp: Date,
        cursorWatermark: Date,
        catalogGeneration: UInt64,
        catalogSnapshotSHA256: String,
        aggregateSnapshotSHA256: String,
        currentCatalogFingerprint: String?
    ) -> String? {
        guard let dependencyFingerprint,
              !dependencyFingerprint.isEmpty,
              fullScanGeneration > 0,
              !sourceChunkID.isEmpty,
              !sourceRawSHA256.isEmpty,
              let currentCatalogFingerprint,
              !currentCatalogFingerprint.isEmpty else {
            return nil
        }
        return [
            "terminal_consumer_coverage_failure_v1",
            dependencyFingerprint,
            String(fullScanVersion),
            String(fullScanGeneration),
            String(fullScanTransportGeneration),
            sourceChunkID,
            sourceRawSHA256,
            String(Int64((
                observedArchiveFirstTimestamp.timeIntervalSince1970 * 1_000
            ).rounded())),
            String(Int64((
                cursorWatermark.timeIntervalSince1970 * 1_000
            ).rounded())),
            String(catalogGeneration),
            catalogSnapshotSHA256,
            aggregateSnapshotSHA256,
            currentCatalogFingerprint,
        ].joined(separator: "|")
    }

    nonisolated private static func terminalConsumerDependencyFingerprint(
        authority: AtriaHistoricalFullDrainCoverageStore.Authority,
        timeZoneIdentifier: String
    ) -> String? {
        guard authority.status == .gapResolvedConsumersPending,
              let dependency = authority.pendingConsumerDependency else {
            return nil
        }
        return [
            "pending_consumer_dependency_v2",
            AtriaHistoricalActivityProjection.algorithmVersion,
            AtriaHistoricalDailyConsumerProjection
                .dailyMetricsAlgorithmVersion,
            AtriaHistoricalDailyConsumerProjection.stepsAlgorithmVersion,
            AtriaHistoricalSleepProjection.algorithmVersion,
            AtriaHistoricalWorkoutProjection.algorithmVersion,
            authority.gap.gapIdentifier,
            authority.attempt.attemptIdentifier,
            dependency.sourceChunkID,
            dependency.sourceRawSHA256,
            String(Int64((dependency.requiredStartUnix * 1_000).rounded())),
            String(Int64((dependency.requiredEndUnix * 1_000).rounded())),
            timeZoneIdentifier,
        ].joined(separator: "|")
    }

    /// Runs only for a durable exact request bound to this reducer attempt and
    /// this physical strap. Ordinary manual/all-history drains remain useful as
    /// raw archives but cannot create catalog no-data attestations.
    private func scheduleTerminalConsumerMaterializationIfAuthorized(
        transportGeneration: UInt64
    ) {
        guard !historicalConsumerMaterializationInFlight,
              let binding = activeHistoricalRequestBinding,
              binding.transportGeneration == transportGeneration,
              let terminalBatchNumber = historyDrain.terminalBatchNumberForCompletedDrain else {
            AtriaDebugLog("ATRIADBG historical_consumers status=deferred transport_generation=%llu detail=exact_authority_or_durable_rows_missing raw_retained=1",
                          transportGeneration)
            return
        }
        let currentPeripheralIdentifier = peripheral?.identifier.uuidString
        guard currentPeripheralIdentifier == binding.peripheralIdentifier,
              strapModel.rawValue == binding.strapIdentity else {
            AtriaDebugLog("ATRIADBG historical_consumers status=deferred transport_generation=%llu detail=peripheral_or_strap_identity_mismatch raw_retained=1",
                          transportGeneration)
            return
        }

        let durableFrameCount = historyDrain.durableFrameCountForCompletedDrain
        let publicationStore = historicalTerminalPublicationStore
        let pendingResumeJob: AtriaBLEHistoryTerminalPublicationStore.Job?
        do {
            pendingResumeJob = try publicationStore.loadPending(matching: binding)
        } catch {
            AtriaDebugLog("ATRIADBG historical_consumers status=deferred transport_generation=%llu detail=resume_journal_%@ raw_retained=1",
                          transportGeneration,
                          String(describing: error))
            return
        }
        guard pendingResumeJob != nil || durableFrameCount != nil else {
            AtriaDebugLog("ATRIADBG historical_consumers status=deferred transport_generation=%llu detail=no_new_raw_and_no_matching_resume_job raw_retained=1",
                          transportGeneration)
            return
        }

        let completedAt = Date()
        let timeZoneIdentifier = TimeZone.current.identifier
        let restingHeartRate = restingHR ?? 60
        let configuration = AtriaHistoricalConsumerProjectionConfiguration.production(
            restingHeartRate: restingHeartRate,
            maximumHeartRate: maxHRSetting,
            timeZoneIdentifier: timeZoneIdentifier
        )
        let authorityStore = historicalRequestAuthorityStore
        let fullDrainWriteEvidence = historicalFullDrainWriteEvidence
        historicalConsumerMaterializationInFlight = true
        historicalArchiveQueue.async { [weak self] in
            var status = "deferred"
            var detail = "unknown"
            var publishedReceipts = 0
            do {
                _ = try authorityStore.validateTerminal(
                    binding: binding,
                    peripheralIdentifier: binding.peripheralIdentifier,
                    strapIdentity: binding.strapIdentity
                )
                var resumeJob: AtriaBLEHistoryTerminalPublicationStore.Job
                let report: AtriaHistoricalConsumerProjectionCoordinator.Report
                if let pendingResumeJob {
                    resumeJob = pendingResumeJob
                } else {
                    guard let durableFrameCount,
                          let transportWrite = fullDrainWriteEvidence,
                          transportWrite.transportGeneration == transportGeneration else {
                        throw AtriaBLEHistoryTerminalMaterializationError.noNewRawChunk
                    }
                    let candidateChunkID = try HistoricalArchive
                        .terminalCatalogCandidateChunkID()
                    resumeJob = try publicationStore.prepareStaged(
                        binding: binding,
                        chunkID: candidateChunkID,
                        terminalBatchNumber: terminalBatchNumber,
                        durableSequence: durableFrameCount,
                        completedAt: completedAt,
                        transportWrite: transportWrite
                    )
                }

                if resumeJob.status == .prepared {
                    let seal = try HistoricalArchive.recoverTerminalCatalogSeal(
                        job: resumeJob,
                        generation: transportGeneration
                    )
                    let source = seal.aggregateBuild.aggregate.source
                    resumeJob = try publicationStore.markRawSealed(
                        resumeJob,
                        evidence: .init(
                            drainGeneration: transportGeneration,
                            contentSHA256: source.rawSHA256,
                            byteCount: source.rawByteCount,
                            rowCount: source.rawRowCount,
                            firstTimestampUnix: source.firstTimestamp.timeIntervalSince1970,
                            lastTimestampUnix: source.lastTimestamp.timeIntervalSince1970
                        )
                    )
                    detail = "raw_sealed"
                }

                if resumeJob.status == .rawSealed {
                    let seal = try HistoricalArchive.recoverTerminalCatalogSeal(
                        job: resumeJob,
                        generation: resumeJob.originalTransportGeneration
                    )
                    let result = try HistoricalArchive.publishTerminalCompletionAfterDrain(
                        seal: seal,
                        terminalBatchNumber: resumeJob.terminalBatchNumber,
                        durableSequence: resumeJob.durableSequence,
                        requestedStart: binding.exactRequest.requestedStart,
                        requestedEnd: binding.exactRequest.requestedEnd,
                        completedAt: resumeJob.completedAt
                    )
                    let record = result.completion.record
                    resumeJob = try publicationStore.markCompletionPublished(
                        resumeJob,
                        evidence: .init(
                            generation: record.generation,
                            catalogGeneration: record.catalogGeneration,
                            catalogSnapshotSHA256: record.catalogSnapshotSHA256,
                            aggregateSnapshotSHA256: record.aggregateSnapshotSHA256
                        )
                    )
                    detail += "_completion_published"
                }

                let resumed = try HistoricalArchive
                    .resumeTerminalConsumerProjectionsAfterCrash(
                        job: resumeJob,
                        configuration: configuration
                    )
                report = resumed.consumers
                guard report.hasCompleteConsumerCoverage else {
                    detail = "incomplete_consumer_coverage_published_\(report.published.count)_deferred_\(report.deferredSources.count)"
                    throw AtriaBLEHistoryTerminalMaterializationError.incompleteConsumerCoverage
                }
                if resumeJob.status == .completionPublished {
                    resumeJob = try publicationStore.markProjectionsPublished(
                        resumeJob,
                        evidence: .init(
                            completionGeneration: resumed.completion.generation,
                            inspectedSourceCount: report.inspectedSourceCount,
                            receiptCount: report.published.count,
                            artifactSHA256s: report.published.map {
                                $0.receipt.artifactSHA256
                            }.sorted()
                        )
                    )
                }
                _ = try authorityStore.markConsumed(
                    binding: binding,
                    peripheralIdentifier: binding.peripheralIdentifier,
                    strapIdentity: binding.strapIdentity,
                    completedAt: Date()
                )
                try publicationStore.markAuthorityConsumed(resumeJob,
                                                            matching: binding)
                status = "committed"
                publishedReceipts = report.published.count
                detail += "_deferred_sources_\(report.deferredSources.count)"
            } catch {
                if detail == "unknown" { detail = String(describing: error) }
            }
            AtriaDebugLog("ATRIADBG historical_consumers status=%@ authority_generation=%llu attempt=%llu transport_generation=%llu receipts=%d detail=%@ raw_retained=1",
                          status,
                          binding.authorityGeneration,
                          binding.attempt,
                          transportGeneration,
                          publishedReceipts,
                          detail)
            Task { @MainActor [weak self] in
                guard let self else { return }
                if status == "committed", publishedReceipts == 5 {
                    self.historicalConsumerReceiptedGenerations.insert(
                        binding.transportGeneration
                    )
                }
                if self.activeHistoricalRequestBinding == binding {
                    self.activeHistoricalRequestBinding = nil
                }
                let exactMotionResumed = self
                    .releaseHistoricalConsumerMaterializationOwner(
                        reason: "terminal_projection_finished"
                    )
                if !exactMotionResumed,
                   !self.offlineHistoricalSyncInProgress,
                   let pending = self.takePendingOfflineHistoricalSyncRequest() {
                    _ = self.requestOfflineHistoricalSyncIfNeeded(
                        reason: pending.reason,
                        force: pending.force,
                        explicitResearchRequest: pending.explicitRequest,
                        explicitPostWorkoutBankRequest:
                            pending.explicitPostWorkoutBankRequest,
                        preserveConnectedRealtimeOwner:
                            pending.preserveConnectedRealtimeOwner
                    )
                }
            }
        }
    }

    private enum AtriaBLEHistoryTerminalMaterializationError: Error {
        case noNewRawChunk
        case incompleteConsumerCoverage
        case admissionIdentityNotDurable
        case publicationCheckpointMissing
        case unexpectedConsumerKind
        case consumerReceiptRereadFailed
        case gapLedgerQuarantined
        case pendingConsumerDependencyMissing
        case fullScanGenerationExhausted
    }

    private func retryHistoricalACKAfterFailure(
        generation: UInt64,
        boundaryID: String
    ) {
        Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(500))
            guard let self,
                  self.offlineHistoricalSyncInProgress,
                  self.historyDrain.generation == generation else { return }
            self.processHistoricalDrainEffects(
                self.historyDrain.ackCompleted(
                    generation: generation,
                    boundaryID: boundaryID,
                    succeeded: false
                )
            )
        }
    }

    private func handleHistoricalACKWriteResult(
        completedWrite: AtriaWhoopWriteCompletionLedger.Entry?,
        error: Error?
    ) {
        guard offlineHistoricalSyncInProgress,
              let pendingHistoryEndACK,
              let generation = historyDrain.generation,
              let completedWrite else { return }
        let decision = historyACKGate.completeGATT(
            generation: generation,
            boundaryID: pendingHistoryEndACK.key,
            commandSequence: completedWrite.sequence,
            succeeded: error == nil
        )
        switch decision {
        case .ignored:
            AtriaDebugLog("ATRIADBG historyAck status=ignored_gatt_callback key=%@ generation=%llu completed_seq=%d reason=identity_mismatch",
                          pendingHistoryEndACK.key,
                          generation,
                          Int(completedWrite.sequence))
        case .awaitingGATTConfirmation:
            // This callback is itself the missing GATT proof, so this state is
            // unreachable from `completeGATT`.
            assertionFailure("history ACK gate still awaiting GATT from GATT completion")
        case .awaitingLogicalResponse(let identity):
            noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: "history_ack_gatt_confirmed"
            )
            AtriaDebugLog("ATRIADBG historyAck status=gatt_confirmed key=%@ generation=%llu attempt=%d command_seq=%d action=await_logical_0x17",
                          identity.boundaryID,
                          identity.generation,
                          identity.attempt,
                          Int(identity.commandSequence))
            scheduleHistoricalACKLogicalResponseTimeout(identity)
        case .acceptedByGATT(let identity):
            AtriaDebugLog("ATRIADBG historyAck status=gatt_accepted key=%@ generation=%llu attempt=%d command_seq=%d action=advance_durable_reducer",
                          identity.boundaryID,
                          identity.generation,
                          identity.attempt,
                          Int(identity.commandSequence))
            completeHistoricalACKAcceptance(
                identity,
                responseSequence: nil,
                responsePayload: nil
            )
        case .failed(let identity):
            failHistoricalACKAttempt(
                identity,
                reason: error.map { "gatt_\($0.localizedDescription)" }
                    ?? "gatt_rejected"
            )
        case .accepted(let identity, let responseSequence, let responsePayload):
            AtriaDebugLog("ATRIADBG historyAck status=reordered_proofs_complete key=%@ generation=%llu attempt=%d command_seq=%d action=accept_buffered_logical_0x17",
                          identity.boundaryID,
                          identity.generation,
                          identity.attempt,
                          Int(identity.commandSequence))
            completeHistoricalACKAcceptance(
                identity,
                responseSequence: responseSequence,
                responsePayload: responsePayload
            )
        }
    }

    private func handleHistoricalACKCommandResponse(
        _ payload: [UInt8],
        generation: UInt64
    ) {
        switch historyACKGate.receiveCommandResponse(payload, generation: generation) {
        case .ignored, .awaitingLogicalResponse, .acceptedByGATT:
            return
        case .awaitingGATTConfirmation(let identity):
            AtriaDebugLog("ATRIADBG historyAck status=logical_response_buffered key=%@ generation=%llu attempt=%d command_seq=%d payload=%@ action=await_matching_gatt_callback",
                          identity.boundaryID,
                          identity.generation,
                          identity.attempt,
                          Int(identity.commandSequence),
                          Self.hex(payload))
            scheduleHistoricalACKLogicalResponseTimeout(identity)
        case .failed(let identity):
            AtriaDebugLog("ATRIADBG historyAck status=logical_rejected key=%@ generation=%llu attempt=%d command_seq=%d payload=%@ action=retry_same_payload",
                          identity.boundaryID,
                          identity.generation,
                          identity.attempt,
                          Int(identity.commandSequence),
                          Self.hex(payload))
            failHistoricalACKAttempt(identity, reason: "logical_rejected_or_malformed")
        case .accepted(let identity, let responseSequence, let responsePayload):
            completeHistoricalACKAcceptance(
                identity,
                responseSequence: responseSequence,
                responsePayload: responsePayload
            )
        }
    }

    private func scheduleHistoricalACKLogicalResponseTimeout(
        _ identity: AtriaWhoop4HistoryACKGate.Identity
    ) {
        Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(2))
            guard let self else { return }
            guard case .failed(let timedOut) = self.historyACKGate.timeout(identity) else {
                return
            }
            AtriaDebugLog("ATRIADBG historyAck status=logical_timeout key=%@ generation=%llu attempt=%d command_seq=%d action=retry_same_payload",
                          timedOut.boundaryID,
                          timedOut.generation,
                          timedOut.attempt,
                          Int(timedOut.commandSequence))
            self.failHistoricalACKAttempt(timedOut, reason: "logical_timeout")
        }
    }

    private func failHistoricalACKAttempt(
        _ identity: AtriaWhoop4HistoryACKGate.Identity,
        reason: String
    ) {
        guard offlineHistoricalSyncInProgress,
              historyDrain.generation == identity.generation,
              pendingHistoryEndACK?.key == identity.boundaryID else { return }
        if historicalDrainTelemetry.generation == identity.generation {
            historicalDrainTelemetry.ackErrors += 1
        }
        historyACKGate.reset()
        pendingHistoryEndACK = nil
        let retainedPostACKIngress = pendingHistoricalTransportEventCount
        if retainedPostACKIngress > 0 {
            // Do not delete disk ingress after an ACK failure. The strap may
            // have advanced beyond these rows, so this generation cannot
            // retire its gap; retaining the journal keeps crash diagnostics.
            historicalAdmissionFailed = true
            historicalArchiveWriteFailures += 1
        }
        noteOfflineHistoricalSyncProgress(
            generation: identity.generation,
            reason: "history_ack_failed"
        )
        AtriaDebugLog("ATRIADBG historyAck status=attempt_failed key=%@ generation=%llu attempt=%d command_seq=%d reason=%@ discarded_post_ack_callbacks=%d action=bounded_reducer_retry",
                      identity.boundaryID,
                      identity.generation,
                      identity.attempt,
                      Int(identity.commandSequence),
                      reason,
                          retainedPostACKIngress)
        retryHistoricalACKAfterFailure(
            generation: identity.generation,
            boundaryID: identity.boundaryID
        )
    }

    private func completeHistoricalACKAcceptance(
        _ ackIdentity: AtriaWhoop4HistoryACKGate.Identity,
        responseSequence: UInt8?,
        responsePayload: [UInt8]?
    ) {
        guard offlineHistoricalSyncInProgress,
              historyDrain.generation == ackIdentity.generation,
              let pendingHistoryEndACK,
              pendingHistoryEndACK.key == ackIdentity.boundaryID,
              pendingHistoryACKAttempts == ackIdentity.attempt else { return }
        if let identity = activeFullDrainEventIdentity,
           let permit = fullDrainACKPermits[pendingHistoryEndACK.key] {
            do {
                _ = try historicalFullDrainCoverageStore.recordMatchingACK(
                    identity: identity,
                    permit: permit,
                    actualACKPayload: Data(pendingHistoryEndACK.payload),
                    ackAttempt: pendingHistoryACKAttempts,
                    completedAt: Date()
                )
            } catch {
                AtriaDebugLog("ATRIADBG historyAck status=authority_record_failed key=%@ generation=%llu error=%@ action=retry_same_payload",
                              pendingHistoryEndACK.key,
                              ackIdentity.generation,
                              String(describing: error))
                failHistoricalACKAttempt(
                    ackIdentity,
                    reason: "authority_record_failed"
                )
                return
            }
        }
        ackedHistoryAckKeys.insert(pendingHistoryEndACK.key)
        historicalArchiveRowsSinceAck = 0
        if historicalDrainTelemetry.generation == ackIdentity.generation {
            historicalDrainTelemetry.ackSucceeded += 1
            historicalDrainTelemetry.noteProgress()
            historicalDrainTelemetry.observePending(
                pendingHistoricalTransportEventCount + historyDrain.pendingPersistenceCount
            )
        }
        noteOfflineHistoricalSyncProgress(
            generation: ackIdentity.generation,
            reason: "history_ack_logically_accepted",
            advancesDurableConnectedSliceHold: true
        )
        AtriaDebugLog("ATRIADBG historyAck status=accepted key=%@ generation=%llu attempt=%d command_seq=%d proof=%@ response_seq=%d response=%@",
                      pendingHistoryEndACK.key,
                      ackIdentity.generation,
                      ackIdentity.attempt,
                      Int(ackIdentity.commandSequence),
                      responsePayload == nil ? "confirmed_gatt_write" : "confirmed_gatt_write_plus_logical_response",
                      Int(responseSequence ?? 0),
                      responsePayload.map(Self.hex) ?? "none")
        fullDrainACKPermits.removeValue(forKey: pendingHistoryEndACK.key)
        fullDrainHistoryEndPayloads.removeValue(forKey: pendingHistoryEndACK.key)
        self.pendingHistoryEndACK = nil
        let postACKEffects = historyDrain.ackCompleted(
            generation: ackIdentity.generation,
            boundaryID: ackIdentity.boundaryID,
            succeeded: true
        )
        // The matching canonical flush and GATT ACK are now both complete.
        // Persist the reducer's post-ACK discontinuity snapshot once before any
        // local finish or 0x16 continuation can advance to another page.
        persistHistorySequenceContinuityAtBoundary()
        processHistoricalDrainEffects(postACKEffects)
        // A connected motion-bank serve is optional maintenance. On an inactive
        // app, one canonical page is the complete local slice: capture the exact
        // consumed prefix and finish before the next-page command is armed.
        if offlineHistoricalSyncInProgress,
           activeConnectedMotionBankHistoryAuthority(
                generation: ackIdentity.generation
           ) != nil,
           Self.shouldFinishConnectedMotionBankHistoryAtACKBoundary(
                applicationIsActive:
                    UIApplication.shared.applicationState == .active,
                exactMotionBankAuthorityActive: true
           ) {
            recordConnectedMotionBankBackgroundPageCooldown(now: Date())
            if let historicalIngressSpool {
                connectedMotionBankHistoryCleanACKFinishAuthority = .init(
                    generation: ackIdentity.generation,
                    boundaryID: ackIdentity.boundaryID,
                    ingressBoundary: historicalIngressSpool
                        .captureDurablyAcknowledgedPrefixBoundary()
                )
            }
            if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: ackIdentity.generation,
                reason: "exact_connected_motion_bank_background_ack_boundary"
            ) {
                return
            }
            connectedMotionBankHistoryCleanACKFinishAuthority = nil
        }
        // End an exact raw slice only in this synchronous clean-boundary
        // window, before 0x16 can request another page. The thermal-qualified
        // ACK target amortizes discovery/range setup while keeping the burst
        // finite. The
        // local finalizer removes the spool only if every reducer/admission
        // queue is empty; no disconnect, rebuild, protocol abort, or synthetic
        // ACK is issued on this path.
        if offlineHistoricalSyncInProgress,
           let connectedRawAuthority =
                activeConnectedRawHistoryCatchUpAuthority(
                    generation: ackIdentity.generation
                ),
           Self.shouldFinishConnectedRawHistoryCatchUpAtACKBoundary(
                acknowledgedPages: historicalDrainTelemetry.ackSucceeded,
                minimumAcknowledgedPages: Self
                    .connectedRawHistoryCatchUpTargetAcknowledgedPages(
                        thermalState: ProcessInfo.processInfo.thermalState,
                        backgroundSlice: {
                            if case .background =
                                connectedRawAuthority.request.intent {
                                return true
                            }
                            // A foreground slice may cross the lock edge before
                            // its first ACK. Bound the now-background transport
                            // at that same clean boundary instead of retaining
                            // its larger foreground target after suspension.
                            return UIApplication.shared.applicationState
                                != .active
                        }()
                    )
           ) {
            if let historicalIngressSpool {
                connectedRawHistoryCleanACKFinishAuthority = .init(
                    generation: ackIdentity.generation,
                    boundaryID: ackIdentity.boundaryID,
                    ingressBoundary: historicalIngressSpool
                        .captureDurablyAcknowledgedPrefixBoundary()
                )
            }
            if finishConnectedHistoryFailureWithoutDisconnectIfNeeded(
                generation: ackIdentity.generation,
                reason: "exact_connected_raw_ack_burst_boundary"
            ) {
                return
            }
            // A stale/reentrant finish cannot carry this one-shot boundary
            // into another terminal path.
            connectedRawHistoryCleanACKFinishAuthority = nil
        }
        armHistoricalPageContinuationAfterACK(
            generation: ackIdentity.generation,
            boundaryID: ackIdentity.boundaryID
        )
        // The ordered callback queue may already contain the next HISTORY_START
        // and rows from the same stream5 notification burst. Release them only
        // after the reducer has consumed the accepted ACK transition.
        scheduleHistoricalTransportEventDrain()
    }

    /// The strap can replay the just-ACKed page if 0x16 reaches it before its
    /// cursor transition settles. The exact boundary is already durable and
    /// its original ACK was confirmed, so repeating that identical ACK is
    /// idempotent and is the only safe way to release the replayed page.
    private func reackDurableHistoricalReplay(
        generation: UInt64,
        boundaryID: String,
        payload: [UInt8]
    ) {
        guard historicalReplayACKBoundaryID != boundaryID else { return }
        historicalReplayACKTask?.cancel()
        historicalReplayACKBoundaryID = boundaryID
        historicalReplayACKTask = Task { @MainActor [weak self] in
            guard let self else { return }
            var result: AwaitedHistoryWriteResult = .rejected
            for attempt in 1...2 {
                guard !Task.isCancelled,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation,
                      self.ackedHistoryAckKeys.contains(boundaryID),
                      self.pendingHistoryEndACK == nil else { return }
                AtriaDebugLog("ATRIADBG historyAck status=reack_durable_replay generation=%llu key=%@ attempt=%d action=repeat_exact_confirmed_payload",
                              generation,
                              boundaryID,
                              attempt)
                result = await self.sendHistoryCommandAwaitingWriteConfirmation(
                    command: Cmd.historicalDataResult,
                    payload: payload,
                    generation: generation
                )
                if result == .confirmed { break }
                try? await Task.sleep(for: .milliseconds(500))
            }
            guard !Task.isCancelled,
                  self.offlineHistoricalSyncInProgress,
                  self.offlineHistoricalSyncGeneration == generation else { return }
            self.historicalReplayACKTask = nil
            self.historicalReplayACKBoundaryID = nil
            if result == .confirmed {
                self.historicalPageContinuationReplayBackoffStep = min(
                    6,
                    self.historicalPageContinuationReplayBackoffStep + 1
                )
                self.armHistoricalPageContinuationAfterACK(
                    generation: generation,
                    boundaryID: boundaryID
                )
            }
            self.noteOfflineHistoricalSyncProgress(
                generation: generation,
                reason: "history_replay_reack_\(result)"
            )
            AtriaDebugLog("ATRIADBG historyAck status=reack_%@ generation=%llu key=%@ action=%@",
                          String(describing: result),
                          generation,
                          boundaryID,
                          result == .confirmed
                            ? "await_strap_owned_next_page"
                            : "retain_gap_await_repeated_history_end")
        }
    }

    /// A confirmed ACK is the sole permission to ask the strap to continue.
    /// Physical WHOOP 4 testing showed the read cursor advancing while the
    /// device then remained silent until another 0x16/0x00. Reissuing that
    /// idempotent serve command does not mutate the cursor, ACK a page, trim
    /// storage, or discard rows. The task is canceled synchronously by any
    /// subsequently accepted history row or marker.
    private func armHistoricalPageContinuationAfterACK(
        generation: UInt64,
        boundaryID: String
    ) {
        // A confirmed, durable ACK is the only interval in which the WR pipe
        // is clear before a continuation task owns it. Give the diagnostic
        // coexistence policy that exact synchronous slot; scheduling the
        // continuation first made its `continuationPending` fence permanently
        // true and the bank could never re-arm during a real drain.
        _ = submitGate4DailyBankRearmAtDurableBoundaryIfSafe(
            generation: generation
        )
        if Self.shouldRetainHistoricalPageContinuation(
            existingGeneration: historicalPageContinuationGeneration,
            existingBoundaryID: historicalPageContinuationBoundaryID,
            existingHasFutureAttempt:
                historicalPageContinuationHasFutureAttempt,
            requestedGeneration: generation,
            requestedBoundaryID: boundaryID
        ) {
            AtriaDebugLog(
                "ATRIADBG historyContinue status=retained generation=%llu boundary=%@ action=keep_earlier_deadline",
                generation,
                boundaryID
            )
            return
        }
        historicalPageContinuationTask?.cancel()
        historicalPageContinuationGeneration = generation
        historicalPageContinuationBoundaryID = boundaryID
        historicalPageContinuationHasFutureAttempt = true
        historicalPageContinuationArmNonce &+= 1
        let armNonce = historicalPageContinuationArmNonce
        historicalPageContinuationTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer {
                if self.historicalPageContinuationArmNonce == armNonce {
                    self.historicalPageContinuationTask = nil
                    self.historicalPageContinuationGeneration = nil
                    self.historicalPageContinuationBoundaryID = nil
                    self.historicalPageContinuationHasFutureAttempt = false
                }
            }
            // Start promptly instead of imposing a fixed one-minute stall on
            // every page. If the strap replays this already-durable boundary,
            // reackDurableHistoricalReplay backs the next attempt off
            // exponentially; no row is skipped and no un-fsynced page is ACKed.
            let delays = Self.historicalPageContinuationDelays(
                replayBackoffStep:
                    self.historicalPageContinuationReplayBackoffStep
            )
            for (index, delay) in delays.enumerated() {
                try? await Task.sleep(for: .seconds(delay))
                guard !Task.isCancelled,
                      self.offlineHistoricalSyncInProgress,
                      self.offlineHistoricalSyncGeneration == generation,
                      self.historyDrain.generation == generation,
                      self.pendingHistoryEndACK == nil,
                      !self.historyACKGate.requiresHistoryCallbackDeferral,
                      !self.hasPendingHistoricalTransportEvents,
                      !self.historicalAdmissionBatchInFlight,
                      self.peripheral?.state == .connected else { return }
                guard Self.shouldSendHistoricalPageContinuation(
                    replayACKArmed: self.historicalReplayACKTask != nil,
                    writeInFlight: !self.writeCompletionLedger.pending.isEmpty
                ) else {
                    // A replay ACK owns the single-flight pipe. End this arm
                    // before that ACK's completion rearms the same boundary;
                    // retaining this task here would let its 0x16 race 0x17.
                    self.historicalPageContinuationHasFutureAttempt = false
                    AtriaDebugLog(
                        "ATRIADBG historyContinue status=deferred generation=%llu boundary=%@ reason=replay_ack_or_write_in_flight action=await_confirmed_ack_rearm",
                        generation,
                        boundaryID
                    )
                    return
                }

                let attempt = index + 1
                self.historicalPageContinuationHasFutureAttempt =
                    attempt < delays.count
                AtriaDebugLog("ATRIADBG historyContinue status=sending generation=%llu boundary=%@ attempt=%d silence_s=%.0f command=1600 authority=acked_durable_boundary",
                              generation,
                              boundaryID,
                              attempt,
                              delay)
                guard self.historyTransportPhaseFence.armServe(
                    ifMatching: generation
                ) != nil else { return }
                self.pendingFullDrainCommandRequestedAtUnix =
                    Date().timeIntervalSince1970
                let result = await self.sendHistoryCommandAwaitingWriteConfirmation(
                    command: Cmd.sendHistoricalData,
                    payload: [0x00],
                    generation: generation
                )
                guard !Task.isCancelled else { return }
                self.noteOfflineHistoricalSyncProgress(
                    generation: generation,
                    reason: "history_continuation_\(result)"
                )
                AtriaDebugLog("ATRIADBG historyContinue status=%@ generation=%llu boundary=%@ attempt=%d action=%@",
                              String(describing: result),
                              generation,
                              boundaryID,
                              attempt,
                              attempt < delays.count
                                ? "await_history_or_bounded_retry"
                                : "await_history_idle_watchdog")
            }
        }
    }

    @discardableResult
    private func submitGate4DailyBankRearmAtDurableBoundaryIfSafe(
        generation: UInt64
    ) -> Bool {
        guard let intent = gate4DailyBankRearmIntent,
              intent.generation == generation,
              !workoutHistoricalMotionBankArmed,
              let expectedIdentity =
                gate4DailyBankFullDrainAuthorityIdentity,
              expectedIdentity.generation == intent.generation,
              expectedIdentity.ticketID == intent.ticketID,
              expectedIdentity.strapIdentifier == intent.strapIdentifier
        else { return false }

        switch AtriaWhoop4DailyMotionBankRearmPolicy.evaluate(
            gate4DailyBankRearmPolicyInput(
                expectedIdentity: expectedIdentity,
                now: Date()
            )
        ) {
        case .send:
            return submitGate4DailyBankRearm(
                expectedIdentity: expectedIdentity
            )

        case .defer(let reason):
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=gate4_rearm_boundary_deferred generation=%llu reason=%@ action=retain_intent",
                generation,
                String(describing: reason)
            )
            return false

        case .cancel(let reason):
            AtriaDebugLog(
                "ATRIADBG workout_motion_bank status=gate4_rearm_boundary_cancelled generation=%llu reason=%@ action=terminal_fallback_only",
                generation,
                String(describing: reason)
            )
            clearGate4DailyBankRearmIntent(
                reason: String(describing: reason)
            )
            return false
        }
    }

    nonisolated static func shouldRetainHistoricalPageContinuation(
        existingGeneration: UInt64?,
        existingBoundaryID: String?,
        existingHasFutureAttempt: Bool,
        requestedGeneration: UInt64,
        requestedBoundaryID: String
    ) -> Bool {
        existingGeneration == requestedGeneration
            && existingBoundaryID == requestedBoundaryID
            && existingHasFutureAttempt
    }

    nonisolated static func shouldSendHistoricalPageContinuation(
        replayACKArmed: Bool,
        writeInFlight: Bool
    ) -> Bool {
        !replayACKArmed && !writeInFlight
    }

    nonisolated static func historicalPageContinuationDelays(
        replayBackoffStep: Int
    ) -> [TimeInterval] {
        let boundedStep = min(6, max(0, replayBackoffStep))
        let multiplier = 1 << boundedStep
        return [
            TimeInterval(min(60, multiplier)),
            TimeInterval(min(60, 3 * multiplier)),
        ]
    }

    private nonisolated static func joinInts(_ values: [Int]) -> String {
        values.map(String.init).joined(separator: ",")
    }

    /// Add an RR interval and recompute clinical HRV over the last 5 minutes.
    private func addRR(_ ms: Double,
                       at beatTime: Date,
                       source: String,
                       opcode: String,
                       expectedHR: Int?,
                       provenance: AtriaRRSourceProvenance,
                       triggerRefresh: Bool = true) {
        var now = beatTime
        let previousRRBeatTime = lastRRBeatTime
        if let previous = previousRRBeatTime, now <= previous {
            now = previous.addingTimeInterval(0.001)
        }
        lastRRBeatTime = now
        recentRRBeatTimes.append(now)
        pruneRecentRRBeatTimesIfNeeded(now: now)
        let interval = RRInterval(t: now,
                                  ms: ms,
                                  expectedHR: expectedHR,
                                  source: provenance)
        rrArchive.append(interval)
        noteRRArchiveDidChange()
        appendRRPoint(ms: ms, at: now, source: provenance)
        let rrGap = previousRRBeatTime.map { now.timeIntervalSince($0) } ?? 0
        refreshRRPresenceOnRealInterval(at: now, source: source, rrGap: rrGap)
        let stableSeconds = stableContactSeconds(now: now)
        guard stableSeconds >= 10 else {
            resetHRVWindow(reason: String(format: "contact %.0fs/10s", stableSeconds))
            return
        }
        if !hrvGateWasOpen {
            resetRRBuffer()
            hrvGateWasOpen = true
            assignIfChanged(\.hrvQuality, "collecting beat-to-beat samples")
            logRow(kind: "hrv_quality", source: "app", opcode: "", len: "",
                   value: "clean_rr_window_started")
            return
        }
        rrBuffer.append(interval)
        if isRecording {
            var exportElapsedMS = Int((now.timeIntervalSince(captureStart) * 1000).rounded())
            if let previous = lastRRExportElapsedMS, exportElapsedMS <= previous {
                exportElapsedMS = previous + 1
            }
            lastRRExportElapsedMS = exportElapsedMS
            logRow(kind: "rr", source: source, opcode: opcode, len: "", value: String(format: "%.0f", ms),
                   at: now, elapsedMS: exportElapsedMS)
        }
        if triggerRefresh, shouldRefreshHRVSnapshot(now: now) {
            requestLiveHRVSnapshotRefresh(now: now,
                                          logKind: "hrv",
                                          shouldLogConsole: currentRRBufferCount.isMultiple(of: 15))
        }
    }

    private func addRRBatch(intervalsMS: [Int],
                            endingAt frameTime: Date,
                            source: String,
                            opcode: String,
                            expectedHR: Int?) {
        guard !intervalsMS.isEmpty else { return }

        let stableSeconds = stableContactSeconds(now: frameTime)
        let hasStableContact = stableSeconds >= 10
        let shouldOpenGate = hasStableContact && !hrvGateWasOpen
        if shouldOpenGate {
            resetRRBuffer()
            hrvGateWasOpen = true
            assignIfChanged(\.hrvQuality, "collecting beat-to-beat samples")
            logRow(kind: "hrv_quality", source: "app", opcode: "", len: "",
                   value: "clean_rr_window_started")
        } else if !hasStableContact {
            resetHRVWindow(reason: String(format: "contact %.0fs/10s", stableSeconds))
        }

        let beats = Self.beatTimesEnding(at: frameTime, intervalsMS: intervalsMS)
        let previousPacketBeatTime = lastRRBeatTime
        let appendPayload = makeRRBatchAppendPayload(beats: beats,
                                                     previousBeatTime: lastRRBeatTime,
                                                     expectedHR: expectedHR)
        if !appendPayload.intervals.isEmpty {
            lastRRBeatTime = appendPayload.beatTimes.last
            recentRRBeatTimes.append(contentsOf: appendPayload.beatTimes)
            rrArchive.append(contentsOf: appendPayload.intervals)
            noteRRArchiveDidChange()
            persistActiveSessionJournalForRRIfNeeded(reason: "standard_rr_batch", now: frameTime)
            if shouldMaintainSessionPointCaches, !appendPayload.rrPoints.isEmpty {
                rrPointsCache.append(contentsOf: appendPayload.rrPoints)
            }
            if hrvGateWasOpen && !shouldOpenGate {
                rrBuffer.append(contentsOf: appendPayload.intervals)
            }
        }

        if isRecording {
            for interval in appendPayload.intervals {
                var exportElapsedMS = Int((interval.t.timeIntervalSince(captureStart) * 1000).rounded())
                if let previous = lastRRExportElapsedMS, exportElapsedMS <= previous {
                    exportElapsedMS = previous + 1
                }
                lastRRExportElapsedMS = exportElapsedMS
                logRow(kind: "rr", source: source, opcode: opcode, len: "",
                       value: String(format: "%.0f", interval.ms),
                       at: interval.t, elapsedMS: exportElapsedMS)
            }
        }

        pruneRecentRRBeatTimesIfNeeded(now: lastRRBeatTime ?? frameTime)
        let rrGap = previousPacketBeatTime.map { max(0, frameTime.timeIntervalSince($0)) } ?? 0
        refreshRRPresenceOnRealInterval(at: frameTime, source: source, rrGap: rrGap)

        if hasStableContact && !shouldOpenGate {
            requestDeferredHRVSnapshotRefreshIfNeeded(now: frameTime)
        }
    }

    /// Preserve proprietary RR words in an explicit research-only capture row.
    /// They never enter rrBuffer/rrArchive, HRV, recovery, or HealthKit until the
    /// exact layout version has independent beat-aligned validation.
    private func recordUnvalidatedProprietaryRRResearch(_ intervalsMS: [Int],
                                                        endingAt frameTime: Date,
                                                        opcode: String) {
        guard isRecording else { return }
        for beat in Self.beatTimesEnding(at: frameTime, intervalsMS: intervalsMS) {
            logRow(kind: "rr_research_unvalidated",
                   source: "0x28",
                   opcode: opcode,
                   len: "",
                   value: String(beat.rr),
                   at: beat.time)
        }
    }

    private func requestDeferredHRVSnapshotRefreshIfNeeded(now: Date) {
        guard shouldRefreshHRVSnapshot(now: now) else { return }
        requestLiveHRVSnapshotRefresh(now: now,
                                      logKind: "hrv",
                                      shouldLogConsole: currentRRBufferCount.isMultiple(of: 15))
    }

    private func pruneRecentRRBeatTimes(now: Date) {
        lastRecentRRBeatPruneAt = now
        recentRRBeatTimes.removeAll {
            now.timeIntervalSince($0) > Self.recentRRBeatWindowSeconds
        }
    }

    private func pruneRecentRRBeatTimesIfNeeded(now: Date) {
        if let lastRecentRRBeatPruneAt,
           now.timeIntervalSince(lastRecentRRBeatPruneAt) < Self.recentRRBeatPruneMinimumInterval,
           recentRRBeatTimes.count < 720 {
            return
        }
        pruneRecentRRBeatTimes(now: now)
    }

    private func appendSessionPoint(rate: Int, at sampleTime: Date) {
        guard shouldMaintainSessionPointCaches else { return }
        if sessionOriginTime == nil {
            sessionOriginTime = sampleTime
        }
        guard let origin = sessionOriginTime else { return }
        sessionPointsCache.append(SavedSession.Point(t: sampleTime.timeIntervalSince(origin), bpm: rate))
    }

    private func appendRRPoint(ms: Double,
                               at beatTime: Date,
                               source: AtriaRRSourceProvenance) {
        guard shouldMaintainSessionPointCaches else { return }
        guard let origin = sessionOriginTime, beatTime >= origin else { return }
        rrPointsCache.append(SavedSession.RRPoint(t: beatTime.timeIntervalSince(origin),
                                                  ms: Int(ms.rounded()),
                                                  source: source))
    }

    private func makeRRBatchAppendPayload(beats: [(rr: Int, time: Date)],
                                          previousBeatTime: Date?,
                                          expectedHR: Int?) -> RRBatchAppendPayload {
        guard !beats.isEmpty else {
            return RRBatchAppendPayload(intervals: [], beatTimes: [], rrPoints: [])
        }

        var adjustedBeatTimes: [Date] = []
        adjustedBeatTimes.reserveCapacity(beats.count)

        var intervals: [RRInterval] = []
        intervals.reserveCapacity(beats.count)

        var rrPoints: [SavedSession.RRPoint] = []
        rrPoints.reserveCapacity(sessionOriginTime == nil ? 0 : beats.count)

        var previous = previousBeatTime
        let origin = sessionOriginTime

        for beat in beats {
            var beatTime = beat.time
            if let previous, beatTime <= previous {
                beatTime = previous.addingTimeInterval(0.001)
            }
            previous = beatTime
            adjustedBeatTimes.append(beatTime)

            let interval = RRInterval(t: beatTime,
                                      ms: Double(beat.rr),
                                      expectedHR: expectedHR,
                                      source: .standardHeartRateMeasurement2A37)
            intervals.append(interval)

            if let origin, beatTime >= origin {
                rrPoints.append(SavedSession.RRPoint(t: beatTime.timeIntervalSince(origin),
                                                     ms: beat.rr,
                                                     source: .standardHeartRateMeasurement2A37))
            }
        }

        return RRBatchAppendPayload(intervals: intervals,
                                    beatTimes: adjustedBeatTimes,
                                    rrPoints: rrPoints)
    }

    private func rebuildSessionCaches() {
        sessionActiveCaloriesCache = nil
        guard let first = session.first else {
            sessionOriginTime = nil
            sessionPointsCache.removeAll(keepingCapacity: true)
            rrPointsCache.removeAll(keepingCapacity: true)
            return
        }

        sessionOriginTime = first.t
        sessionPointsCache = session.map {
            SavedSession.Point(t: $0.t.timeIntervalSince(first.t), bpm: $0.bpm)
        }
        rrPointsCache = rrArchive
            .filter { $0.t >= first.t }
            .map {
                SavedSession.RRPoint(t: $0.t.timeIntervalSince(first.t),
                                     ms: Int($0.ms.rounded()),
                                     source: $0.source)
            }
    }

    /// Keeps routine durability checkpoints O(new samples) while preserving the
    /// exact full calculation for strength-workout exclusion windows.
    private func activeCaloriesForSnapshot(rest: Int,
                                           profile: AthleteProfile,
                                           excludedIntervals: [ExcludedInterval]) -> Double? {
        guard excludedIntervals.isEmpty else {
            let activeSamples = AtriaStrengthLog.samplesExcludingIntervals(
                session,
                excludedIntervals: excludedIntervals
            )
            return Metrics.activeCalories(activeSamples, rest: rest, profile: profile)
        }
        guard let first = session.first, let last = session.last, session.count > 1 else { return nil }

        if var cache = sessionActiveCaloriesCache,
           cache.sessionID == liveSessionID,
           cache.origin == first.t,
           cache.restingHeartRate == rest,
           cache.profile == profile,
           cache.sampleCount > 0,
           cache.sampleCount <= session.count,
           session[cache.sampleCount - 1].t == cache.lastTimestamp {
            if cache.sampleCount < session.count {
                var calories = cache.calories ?? 0
                if profile.hasEnergyProfile {
                    for index in cache.sampleCount..<session.count {
                        calories += Metrics.activeCalories(
                            [session[index - 1], session[index]],
                            rest: rest,
                            profile: profile
                        ) ?? 0
                    }
                }
                cache.sampleCount = session.count
                cache.lastTimestamp = last.t
                cache.calories = profile.hasEnergyProfile ? calories : nil
                sessionActiveCaloriesCache = cache
            }
            return cache.calories
        }

        let calories = Metrics.activeCalories(session, rest: rest, profile: profile)
        sessionActiveCaloriesCache = SessionActiveCaloriesCache(
            sessionID: liveSessionID,
            origin: first.t,
            sampleCount: session.count,
            lastTimestamp: last.t,
            restingHeartRate: rest,
            profile: profile,
            calories: calories
        )
        return calories
    }

    private var shouldMaintainSessionPointCaches: Bool {
        longWearModeEnabled
    }

    private func updateSessionPointCacheMode() {
        if shouldMaintainSessionPointCaches {
            rebuildSessionCaches()
        } else {
            sessionOriginTime = session.first?.t
            sessionPointsCache.removeAll(keepingCapacity: true)
            rrPointsCache.removeAll(keepingCapacity: true)
        }
    }

    fileprivate func record(frame: AtriaFrame) {
        guard storeProprietaryFrames else { return }
        logRow(kind: "frame", source: frame.source,
               opcode: String(format: "%02X", frame.opcode),
               len: "\(frame.declaredLen)", value: frame.hex)
        frames.append(frame)
        if frames.count >= maxFrames * 2 {
            frames.removeFirst(frames.count - maxFrames)
        }
    }

    /// Atomically closes the current HR/RR/R10 accounting segment. The motion
    /// queue is marked before the SavedSession is built, so no main-actor queue
    /// wait is needed and no post-marker motion can leak into the old session.
    private func finishSession(label: String, reason: String) async -> SessionBoundaryOutcome {
        await performSessionBoundary(label: label,
                                     persistenceReason: reason,
                                     nextSessionStart: Date(),
                                     resetWhenUnsavable: false)
    }

    /// Drains the detector to an exact FIFO marker without ending the live
    /// session. Workout Start/Pause/Resume/End use this before reading their
    /// all-day step coordinate, eliminating the cadence-limited UI projection
    /// as an accounting boundary.
    func synchronizeCurrentR10MotionAccounting() async -> Date? {
        // Do not make Start/End wait on a boundary for a transport that is
        // honestly unavailable. Pure-HR fallback has no R10 packets to drain.
        guard let connectedAt,
              Self.workoutMotionStream5IsProven(
                notifyConfirmed: strapStream5NotifyConfirmed,
                lastFrameAt: lastR10MotionFrameAt,
                connectedAt: connectedAt
              ) else { return nil }
        while r10SessionBoundaryID != nil {
            guard !Task.isCancelled else { return nil }
            try? await Task.sleep(for: .milliseconds(2))
        }
        let preparation = r10MotionPipeline.enqueueBoundaryPreparation()
        guard let id = reserveSessionBoundary() else { return nil }
        let token = await preparation.value()
        guard !Task.isCancelled else {
            await abortSessionBoundary(id: id, token: token)
            return nil
        }
        guard r10SessionBoundaryID == id else {
            _ = await r10MotionPipeline.abortBoundary(token)
            return nil
        }
        while acceptedHeartRateBatchDepth > 0 || realtimePacketBatchDepth > 0 {
            guard !Task.isCancelled else {
                await abortSessionBoundary(id: id, token: token)
                return nil
            }
            await Task.yield()
        }
        await abortSessionBoundary(id: id, token: token)
        return max(preparation.enqueuedAt,
                   token.finalSnapshot?.receivedAt ?? preparation.enqueuedAt)
    }

    /// True when the live HR buffer still contains samples captured before the
    /// persisted workout start, i.e. the exact-start session boundary has not
    /// been committed for this workout.
    nonisolated static func workoutStartBoundaryIsRequired(firstSampleAt: Date?,
                                                           startedAt: Date) -> Bool {
        guard let firstSampleAt else { return false }
        return firstSampleAt < startedAt
    }

    /// Exact workout-start ownership guard for saving the live buffer. A
    /// workout label may only be applied when every buffered sample is at or
    /// after the persisted workout `notBefore` start; otherwise the buffer is
    /// still the pre-existing all-day journal and must keep its own label.
    nonisolated static func workoutCheckpointLabel(
        requested: String,
        allDayLabel: String,
        firstSampleAt: Date?,
        notBefore: Date?
    ) -> (label: String, preservedAllDay: Bool) {
        guard let notBefore, let firstSampleAt,
              firstSampleAt < notBefore else {
            return (requested, false)
        }
        return (allDayLabel, true)
    }

    /// Transactionally cuts the live all-day session at the persisted workout
    /// start. The pre-workout segment is saved durably under its own all-day
    /// label and journal identity; the fresh live segment starting exactly at
    /// `startedAt` is the only state a later workout save may relabel. On
    /// persistence failure nothing is relabelled and the original all-day
    /// journal is retained (fail closed).
    @discardableResult
    func commitWorkoutStartSessionBoundary(startedAt: Date) async -> Bool {
        guard Self.workoutStartBoundaryIsRequired(firstSampleAt: session.first?.t,
                                                  startedAt: startedAt) else {
            UserDefaults.standard.set(startedAt.timeIntervalSince1970,
                                      forKey: WorkoutMotionDefaults.boundaryStartedAt)
            AtriaDebugLog("ATRIADBG workout_boundary status=not_required samples=%d started_unix=%d",
                          session.count,
                          Int(startedAt.timeIntervalSince1970.rounded()))
            return true
        }
        let allDayLabel = captureLabel.isEmpty ? "All-day wear" : captureLabel
        let outcome = await performSessionBoundary(
            label: allDayLabel,
            persistenceReason: "workout_start_boundary",
            nextSessionStart: startedAt,
            resetWhenUnsavable: false
        )
        if outcome.persisted {
            UserDefaults.standard.set(startedAt.timeIntervalSince1970,
                                      forKey: WorkoutMotionDefaults.boundaryStartedAt)
        }
        AtriaDebugLog("ATRIADBG workout_boundary status=%@ label=%@ saved_samples=%d started_unix=%d action=%@",
                      outcome.persisted ? "committed" : "persist_failed",
                      allDayLabel,
                      outcome.saved?.points.count ?? 0,
                      Int(startedAt.timeIntervalSince1970.rounded()),
                      outcome.persisted ? "all_day_segment_sealed" : "retain_all_day_journal_fail_closed")
        return outcome.persisted
    }

    @discardableResult
    func checkpointCurrentSession(label: String,
                                  reason: String,
                                  strengthSets: [LoggedSet] = [],
                                  excludedIntervals: [ExcludedInterval] = [],
                                  notBefore: Date? = nil) async -> Bool {
        guard r10SessionBoundaryID == nil else {
            AtriaDebugLog("ATRIADBG session_checkpoint status=skipped reason=boundary_busy source=live_workout_end")
            return false
        }
        let preparation = r10MotionPipeline.enqueueBoundaryPreparation()
        guard let id = reserveSessionBoundary() else { return false }
        let token = await preparation.value()
        guard r10SessionBoundaryID == id else {
            _ = await r10MotionPipeline.abortBoundary(token)
            return false
        }
        // A terminal workout intent is already durable before this checkpoint
        // begins.  Do not let a continuously arriving BLE batch hold the
        // post-End UI path forever: aborting this *secondary* boundary keeps
        // the live journal and every buffered sample intact for recovery.
        guard await waitForSessionInputBatchesToDrainForWorkoutCompletion() else {
            await abortSessionBoundary(id: id, token: token)
            AtriaDebugLog("ATRIADBG session_checkpoint status=deferred reason=input_batches_busy source=live_workout_end action=retain_live_journal")
            return false
        }
        let ownership = Self.workoutCheckpointLabel(
            requested: label,
            allDayLabel: captureLabel.isEmpty ? "All-day wear" : captureLabel,
            firstSampleAt: session.first?.t,
            notBefore: notBefore
        )
        if ownership.preservedAllDay {
            // The exact-start boundary was never committed, so this buffer is
            // still the pre-workout all-day journal. Saving it under a workout
            // label would relabel hours of unrelated wear (the F799A190
            // corruption); keep its own identity and let the confirmed-workout
            // window own only samples at or after the persisted start.
            AtriaDebugLog("ATRIADBG session_checkpoint status=label_preserved reason=missing_workout_start_boundary requested_label=%@ retained_label=%@ not_before_unix=%d",
                          label,
                          ownership.label,
                          Int((notBefore?.timeIntervalSince1970 ?? 0).rounded()))
        }
        let label = ownership.label
        guard let saved = snapshotSession(label: label,
                                          strengthSets: strengthSets,
                                          excludedIntervals: excludedIntervals,
                                          motionSnapshotOverride: token.finalSnapshot) else {
            await abortSessionBoundary(id: id, token: token)
            AtriaDebugLog("ATRIADBG session_checkpoint status=skipped reason=%@ samples=%d rr_samples=%d label=%@ source=live_workout_end",
                  reason,
                  session.count,
                  rrArchive.count,
                  label)
            return false
        }
        let persisted = onSessionCheckpoint?(saved) == true
        await abortSessionBoundary(id: id, token: token)
        persistActiveSessionJournalIfNeeded(reason: "live_workout_end_checkpoint", force: true)
        AtriaDebugLog("ATRIADBG session_checkpoint status=%@ reason=%@ samples=%d rr_samples=%d duration_s=%.0f avg_hr=%d peak_hr=%d label=%@ source=live_workout_end mode=upsert reset_live_session=0",
              persisted ? "saved" : "store_failed",
              reason,
              saved.points.count,
              saved.rrSampleCount,
              saved.duration,
              saved.avg,
              saved.peak,
              saved.label)
        return persisted
    }

    private func shouldRollActiveSessionAfterLongGap(nextSampleTime: Date) -> Bool {
        let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        guard (longWearModeEnabled || activeExplicitWorkout || sessionAwaitingUnexpectedReconnect),
              !session.isEmpty else { return false }
        let previous = [lastRawHRNotificationAt, lastAcceptedHRAt, session.last?.t].compactMap { $0 }.max()
        guard let previous else { return false }
        let gap = nextSampleTime.timeIntervalSince(previous)
        guard gap >= activeJournalSegmentGapLimit else {
            sessionAwaitingUnexpectedReconnect = false
            return false
        }
        return true
    }

    /// Bound the live session during continuous all-day wear: once the current
    /// segment spans `longWearLiveSessionRetentionSpan`, finalize it to disk and
    /// segment-roll to a fresh one so the four live arrays can't grow unbounded
    /// (the OOM/jetsam cause — handoff #1). Uses the same persist-then-reset
    /// primitive as the >=90s-gap roll: `persistFinishedSession` calls
    /// `onSessionEnd` (`store.add`, which upserts by id), so the full record is
    /// preserved on disk before `resetLiveSessionState` clears the live arrays and
    /// mints a new `liveSessionID`. The next received sample resumes ~1s later, so
    /// the day's contiguous segments re-cluster into one aggregate sleep/wear
    /// candidate (`sleepClusters` bridges gaps <=2h). Mode-independent by design:
    /// full-protocol overnight capture still needs the same memory bound while
    /// preserving richer RR/IMU evidence. Returns without rolling unless long-wear
    /// mode is active with enough samples and the span cap is met.
    /// Pure trigger for the retention roll, extracted so the 3h-cap logic is
    /// unit-testable without standing up a live AtriaBLEManager (AtriaPerfFixesTests):
    /// roll once the live segment has enough samples AND spans the retention cap.
    static func shouldRollLiveSession(spanSeconds: TimeInterval,
                                      sampleCount: Int,
                                      minSamples: Int,
                                      retentionSpan: TimeInterval) -> Bool {
        sampleCount >= minSamples && spanSeconds >= retentionSpan
    }

    @discardableResult
    private func rollLongWearLiveSessionIfOversized(now: Date, reason: String) -> Bool {
        guard longWearModeEnabled else { return false }
        guard let first = session.first else { return false }
        let span = now.timeIntervalSince(first.t)
        guard Self.shouldRollLiveSession(spanSeconds: span,
                                         sampleCount: session.count,
                                         minSamples: autoSaveMinSamples,
                                         retentionSpan: longWearLiveSessionRetentionSpan) else { return false }
        return startSessionBoundary(label: captureLabel.isEmpty ? "All-day wear" : captureLabel,
                                    persistenceReason: reason,
                                    nextSessionStart: now,
                                    resetWhenUnsavable: false,
                                    firstBufferedInput: nil)
    }

    /// Detects all sample-timestamp-driven accounting boundaries before the
    /// packet mutates any session-local HR/RR counters. The triggering packet is
    /// retained in the same FIFO as packets that arrive while persistence runs.
    private func beginAutomaticSessionBoundaryIfNeeded(
        nextSampleTime: Date,
        firstBufferedInput: BufferedSessionInput
    ) -> Bool {
        guard !session.isEmpty else { return false }
        let label = captureLabel.isEmpty ? "All-day wear" : captureLabel
        if shouldRollActiveSessionAfterLongGap(nextSampleTime: nextSampleTime) {
            return startSessionBoundary(label: label,
                                        persistenceReason: "long_gap_rollover",
                                        nextSessionStart: nextSampleTime,
                                        resetWhenUnsavable: true,
                                        firstBufferedInput: firstBufferedInput)
        }
        // A civil midnight is deliberately not a live-session boundary. Today
        // is wake-to-wake, so forcing an asynchronous persistence/reset here
        // can interrupt the very accumulator that must retain post-midnight
        // activity until a completed main sleep establishes the next day.
        // Memory remains bounded by the retention roll below; disconnect gaps
        // still receive their own durable boundary above.
        guard longWearModeEnabled, let first = session.first,
              Self.shouldRollLiveSession(
                spanSeconds: nextSampleTime.timeIntervalSince(first.t),
                sampleCount: session.count,
                minSamples: autoSaveMinSamples,
                retentionSpan: longWearLiveSessionRetentionSpan
              ) else {
            return false
        }
        return startSessionBoundary(label: label,
                                    persistenceReason: "long_wear_retention_roll",
                                    nextSessionStart: nextSampleTime,
                                    resetWhenUnsavable: false,
                                    firstBufferedInput: firstBufferedInput)
    }

    @discardableResult
    private func startSessionBoundary(
        label: String,
        persistenceReason: String,
        nextSessionStart: Date,
        resetWhenUnsavable: Bool,
        firstBufferedInput: BufferedSessionInput?
    ) -> Bool {
        guard r10SessionBoundaryID == nil else {
            if let firstBufferedInput { bufferedSessionInputs.append(firstBufferedInput) }
            return true
        }
        let preparation = r10MotionPipeline.enqueueBoundaryPreparation()
        guard let id = reserveSessionBoundary() else { return false }
        if let firstBufferedInput { bufferedSessionInputs.append(firstBufferedInput) }
        Task { @MainActor [weak self] in
            guard let self else { return }
            _ = await self.completeSessionBoundary(
                id: id,
                motionPreparation: preparation,
                label: label,
                persistenceReason: persistenceReason,
                nextSessionStart: nextSessionStart,
                resetWhenUnsavable: resetWhenUnsavable,
                prebuiltSavedSession: nil,
                handedOffRawSteps: nil
            )
        }
        return true
    }

    private func reserveSessionBoundary() -> UUID? {
        guard r10SessionBoundaryID == nil else { return nil }
        let id = UUID()
        r10SessionBoundaryID = id
        return id
    }

    private func performSessionBoundary(
        label: String,
        persistenceReason: String,
        nextSessionStart: Date,
        resetWhenUnsavable: Bool
    ) async -> SessionBoundaryOutcome {
        while r10SessionBoundaryID != nil {
            guard !Task.isCancelled else {
                return SessionBoundaryOutcome(saved: nil, persisted: false)
            }
            try? await Task.sleep(for: .milliseconds(2))
        }
        let preparation = r10MotionPipeline.enqueueBoundaryPreparation()
        guard let id = reserveSessionBoundary() else {
            return SessionBoundaryOutcome(saved: nil, persisted: false)
        }
        return await completeSessionBoundary(
            id: id,
            motionPreparation: preparation,
            label: label,
            persistenceReason: persistenceReason,
            nextSessionStart: nextSessionStart,
            resetWhenUnsavable: resetWhenUnsavable,
            prebuiltSavedSession: nil,
            handedOffRawSteps: nil
        )
    }

    private func completeSessionBoundary(
        id: UUID,
        motionPreparation: AtriaR10MotionPipeline.BoundaryPreparation,
        label: String,
        persistenceReason: String,
        nextSessionStart: Date,
        resetWhenUnsavable: Bool,
        prebuiltSavedSession: SavedSession?,
        handedOffRawSteps: Int?
    ) async -> SessionBoundaryOutcome {
        let token = await motionPreparation.value()
        guard r10SessionBoundaryID == id else {
            _ = await r10MotionPipeline.abortBoundary(token)
            return SessionBoundaryOutcome(saved: nil, persisted: false)
        }
        await waitForSessionInputBatchesToDrain()
        await beginActiveJournalBoundaryFence(id: id)
        let saved = prebuiltSavedSession ?? snapshotSession(
            label: label,
            motionSnapshotOverride: token.finalSnapshot
        )
        if saved == nil, !resetWhenUnsavable {
            await abortSessionBoundary(id: id, token: token)
            return SessionBoundaryOutcome(saved: nil, persisted: false)
        }

        let persisted: Bool
        if let saved {
            persisted = await persistFinishedSessionDurably(saved, reason: persistenceReason)
        } else {
            persisted = true
        }
        guard persisted else {
            // Persistence failure is a transaction abort: the live HR/RR state,
            // R10 generation and detector accounting segment remain untouched.
            await abortSessionBoundary(id: id, token: token)
            return SessionBoundaryOutcome(saved: saved, persisted: false)
        }

        let rawStepsToHandOff = handedOffRawSteps ?? token.markerRawSteps
        guard let transition = await r10MotionPipeline.commitBoundary(
            token,
            handedOffRawSteps: rawStepsToHandOff,
            handedOffGyroCadenceResearchSteps: token.markerGyroCadenceResearchSteps,
            nextGeneration: token.generation &+ 1
        ) else {
            await abortSessionBoundary(id: id, token: token)
            return SessionBoundaryOutcome(saved: saved, persisted: false)
        }

        // No suspension is allowed between installing the generation fence and
        // clearing main-actor session state. The pipeline holds post-marker R10
        // frames until the manager explicitly releases them below.
        let previousStepLedgerSegmentID = liveSessionID
        let nextLiveSessionID = UUID()
        r10MotionPipelineGeneration = transition.generation
        if rawStepsToHandOff == token.markerRawSteps {
            rotateStrapStepLedgerAfterExactBoundary(
                from: previousStepLedgerSegmentID,
                finalizedSnapshot: token.finalSnapshot,
                finalizedGyroCadenceResearchSteps: token.markerGyroCadenceResearchSteps,
                to: nextLiveSessionID,
                nextSegmentStartedAt: nextSessionStart,
                reason: persistenceReason
            )
        } else {
            resegmentStrapStepLedgerAfterUnhandedBoundary(
                from: previousStepLedgerSegmentID,
                observedSnapshot: token.finalSnapshot,
                carriedSnapshot: transition.carriedSnapshot,
                observedGyroCadenceResearchSteps: token.markerGyroCadenceResearchSteps,
                carriedGyroCadenceResearchSteps: transition.carriedGyroCadenceResearchSteps,
                to: nextLiveSessionID,
                nextSegmentStartedAt: nextSessionStart,
                reason: persistenceReason
            )
        }
        resetLiveSessionStateAfterR10Boundary(
            start: nextSessionStart,
            carriedMotionSnapshot: transition.carriedSnapshot,
            nextLiveSessionID: nextLiveSessionID
        )
        if let saved {
            clearFinishedSessionJournal(after: saved, reason: persistenceReason)
        } else {
            ActiveSessionJournal.clear()
        }
        await endActiveJournalBoundaryFence(id: id, committed: true)
        var releasedMotion = await r10MotionPipeline.releaseCommittedBoundaryFrames(
            token,
            generation: transition.generation
        )
        if !releasedMotion {
            releasedMotion = await r10MotionPipeline.forceReleaseCommittedBoundaryFrames(
                generation: transition.generation
            )
            AtriaDebugLog("ATRIADBG session_boundary status=%@ reason=%@ generation=%llu action=force_release",
                          releasedMotion ? "motion_release_recovered" : "motion_release_failed",
                          persistenceReason,
                          transition.generation)
        }
        guard releasedMotion else {
            // Never clear the manager boundary or report success while the
            // pipeline may still be fencing post-marker motion.
            return SessionBoundaryOutcome(saved: saved, persisted: false)
        }
        if persistenceReason == "long_gap_rollover" {
            sessionAwaitingUnexpectedReconnect = false
        }
        let bufferedInputCount = bufferedSessionInputs.count
        r10SessionBoundaryID = nil
        replayBufferedSessionInputs()
        if !session.isEmpty {
            // A committed rollover cleared the old journal and cancelled its
            // trailing checkpoint. Replaying the first new-segment HR can
            // start an asynchronous save, but the rest of the replay may land
            // behind that writer without a durable restart request. Force a
            // post-replay handoff: it writes immediately when idle, or marks a
            // pending save that the in-flight writer must drain.
            persistActiveSessionJournalIfNeeded(
                reason: "\(persistenceReason)_post_boundary_replay",
                force: true
            )
        }
        AtriaDebugLog(
            "ATRIADBG session_boundary status=committed reason=%@ saved_samples=%d raw_steps=%d generation=%llu buffered_inputs=%d",
            persistenceReason,
            saved?.points.count ?? 0,
            rawStepsToHandOff,
            transition.generation,
            bufferedInputCount
        )
        return SessionBoundaryOutcome(saved: saved, persisted: true)
    }

    private func waitForSessionInputBatchesToDrain() async {
        while acceptedHeartRateBatchDepth > 0 || realtimePacketBatchDepth > 0 {
            await Task.yield()
        }
    }

    /// A normal segmentation boundary can wait until its input FIFO is quiet:
    /// it owns the stream transition.  Explicit workout completion is
    /// different—the user's terminal intent has already been atomically
    /// persisted, so its UI must not be held hostage by a never-empty realtime
    /// stream.  A timeout aborts only this optional checkpoint; the old live
    /// journal and buffered packets remain the recovery authority.
    private func waitForSessionInputBatchesToDrainForWorkoutCompletion(
        timeout: Duration = .milliseconds(250)
    ) async -> Bool {
        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: timeout)
        while acceptedHeartRateBatchDepth > 0 || realtimePacketBatchDepth > 0 {
            guard clock.now < deadline else {
                AtriaDebugLog("ATRIADBG session_checkpoint status=input_batches_timeout hr_depth=%d realtime_depth=%d source=live_workout_end",
                              acceptedHeartRateBatchDepth,
                              realtimePacketBatchDepth)
                return false
            }
            await Task.yield()
        }
        return true
    }

    /// Prevents an incremental write captured from the old live session from
    /// landing after its journal has been cleared or its cursor fields reset.
    /// HR/RR and R10 are already held at their boundary gates while this waits.
    private func beginActiveJournalBoundaryFence(id: UUID) async {
        activeJournalBoundaryFenceID = id
        cancelTrailingActiveJournalCheckpoint()
        activeJournalStepCheckpointTask?.cancel()
        activeJournalStepCheckpointTask = nil
        activeJournalPendingSave = false
        activeJournalPendingForcedSave = false
        activeJournalPendingTimestampRefresh = false
        while activeJournalSaveInFlight {
            await Task.yield()
        }
    }

    private func endActiveJournalBoundaryFence(id: UUID, committed: Bool) async {
        guard activeJournalBoundaryFenceID == id else { return }
        if committed {
            activeJournalPendingSave = false
            activeJournalPendingForcedSave = false
            activeJournalPendingTimestampRefresh = false
            activeJournalBoundaryFenceID = nil
            return
        }

        activeJournalPendingSave = false
        activeJournalPendingForcedSave = false
        activeJournalPendingTimestampRefresh = false
        activeJournalBoundaryFenceID = nil
        persistActiveSessionJournalIfNeeded(
            reason: "session_boundary_abort_restore",
            force: true,
            refreshTimestampIfUnchanged: true
        )
    }

    private func abortSessionBoundary(
        id: UUID,
        token: AtriaR10MotionPipeline.BoundaryToken
    ) async {
        let aborted = await r10MotionPipeline.abortBoundary(token)
        guard r10SessionBoundaryID == id else { return }
        if aborted, let snapshot = token.finalSnapshot {
            applyR10MotionSnapshot(snapshot, schedulesCheckpoint: false)
        }
        await endActiveJournalBoundaryFence(id: id, committed: false)
        r10SessionBoundaryID = nil
        replayBufferedSessionInputs()
    }

    private func replayBufferedSessionInputs() {
        guard !bufferedSessionInputs.isEmpty else { return }
        let buffered = bufferedSessionInputs
        bufferedSessionInputs.removeAll(keepingCapacity: true)
        replayingBufferedSessionInputs = true
        defer { replayingBufferedSessionInputs = false }
        for input in buffered {
            switch input {
            case let .heartRate(measurement, rawData, callbackSource):
                recordHeartRateMeasurement(
                    measurement,
                    rawData: rawData,
                    callbackSource: callbackSource
                )
            case let .realtime(packet):
                handleParsedRealtimePacket(packet)
            }
        }
    }

    private func resetLiveSessionStateAfterR10Boundary(
        start: Date,
        carriedMotionSnapshot: AtriaR10MotionPipeline.Snapshot?,
        nextLiveSessionID: UUID
    ) {
        session.removeAll(keepingCapacity: true)
        publishSessionSampleCountIfNeeded(now: start, force: true)
        lastSessionSampleCountPublishedAt = nil
        sessionOriginTime = nil
        sessionPointsCache.removeAll(keepingCapacity: true)
        rrPointsCache.removeAll(keepingCapacity: true)
        sessionActiveCaloriesCache = nil
        sessionMinHeartRate = nil
        sessionMaxHeartRate = nil
        sessionHeartRateTotal = 0
        sessionHeartRateAggregateCount = 0
        sessionHeartRateMean = 0
        sessionHeartRateM2 = 0
        // Invalidate the off-main historical-motion cache for the new segment so a
        // previous session's value can never be reused, and clear the in-flight flag
        // so a fresh refresh can always start (defense-in-depth; origin-keying
        // already prevents cross-session reads, but this survives frequent resets).
        cachedHistoricalMotion = nil
        cachedHistoricalMotionOrigin = nil
        cachedHistoricalMotionAt = nil
        historicalMotionRefreshInFlight = false
        replaceLastHeartRates([])
        rrArchive.removeAll(keepingCapacity: true)
        noteRRArchiveDidChange()
        recentRRBeatTimes.removeAll(keepingCapacity: true)
        lastRRBeatTime = nil
        lastStandardRRAt = nil
        lastActiveJournalSavedSessionSampleCount = 0
        lastActiveJournalSavedRRArchiveCount = 0
        lastActiveJournalPersistedSampleCount = 0
        lastActiveJournalPersistedRRCount = 0
        lastActiveJournalSavedResearchAggregates = .zero
        activeJournalNeedsFullRebase = false
        cancelTrailingActiveJournalCheckpoint()
        resetSessionMotionDiagnostics(carriedMotionSnapshot: carriedMotionSnapshot)
        resetSessionSampleDiagnostics()
        sessionStart = start
        lastAcceptedHRAt = nil
        lastRawHRNotificationAt = nil
        lastStandardHR = nil
        pendingHRJump = nil
        recentValid.removeAll(keepingCapacity: true)
        liveSessionID = nextLiveSessionID
        liveSessionEventTimeZoneIdentifier = TimeZone.current.identifier
        activeJournalDirtySamples = 0
        activeJournalPendingSave = false
        activeJournalPendingTimestampRefresh = false
        lastCanonicalCheckpointAt = nil
        segmentHROnlyRRRecoveryCount = 0
        lastSegmentHROnlyRRRecoveryAt = nil
        currentRRGapRecoveryCount = 0
        lastCurrentRRGapRecoveryAt = nil
    }

    private func appendLastHeartRate(_ rate: Int) {
        lastHeartRates.append(rate)
        if rate > 0 {
            lastHeartRatesTotal += rate
            lastHeartRatesPositiveCount += 1
            lastHeartRatesPeak = max(lastHeartRatesPeak ?? rate, rate)
        }
        if lastHeartRates.count > 60 {
            let removed = lastHeartRates.removeFirst()
            if removed > 0 {
                lastHeartRatesTotal -= removed
                lastHeartRatesPositiveCount = max(0, lastHeartRatesPositiveCount - 1)
                if lastHeartRatesPeak == removed {
                    lastHeartRatesPeak = lastHeartRates.lazy.filter { $0 > 0 }.max()
                }
            }
        }
    }

    private func replaceLastHeartRates(_ values: [Int]) {
        lastHeartRates = values
        lastHeartRatesTotal = 0
        lastHeartRatesPositiveCount = 0
        lastHeartRatesPeak = nil
        for value in values where value > 0 {
            lastHeartRatesTotal += value
            lastHeartRatesPositiveCount += 1
            lastHeartRatesPeak = max(lastHeartRatesPeak ?? value, value)
        }
        rebuildLiveHeartWindow()
    }

    private func rebuildLiveHeartWindow() {
        let average = lastHeartRatesPositiveCount > 0
            ? Int((Double(lastHeartRatesTotal) / Double(lastHeartRatesPositiveCount)).rounded())
            : nil
        let sparkline = compactHeartSparkline(lastHeartRates)
        assignIfChanged(\.liveHeartWindow,
                        LiveHeartWindow(sparkline: sparkline,
                                        average: average,
                                        peak: lastHeartRatesPeak))
    }

    private func compactHeartSparkline(_ values: [Int], targetCount: Int = 18) -> [Int] {
        guard values.count > targetCount, targetCount > 1 else { return values }
        let maxIndex = values.count - 1
        let step = Double(maxIndex) / Double(targetCount - 1)
        return (0..<targetCount).map { sample in
            let index = min(maxIndex, Int((Double(sample) * step).rounded()))
            return values[index]
        }
    }

    var recentFramesNewestFirst: [AtriaFrame] {
        Array(frames.suffix(maxFrames).reversed())
    }

    private func maybeHandleCommandResponseFrame(
        _ frame: AtriaFrame?,
        uuid: CBUUID,
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        guard let frame, frame.opcode == 0x24 else { return }
        AtriaDebugLog("ATRIADBG cmdResp ch=%@ payload=%@",
              uuid.uuidString,
              frame.payload.map { String(format: "%02x", $0) }.joined())
        handleCommandResponsePayload(
            [UInt8](frame.payload),
            historyPhase: historyPhase
        )
        record(frame: frame)
    }

    private func handleParsedProprietaryUpdate(
        _ update: ParsedProprietaryUpdate,
        uuid: CBUUID,
        historyPhase: AtriaBLEHistoryTransportPhaseFence.Snapshot
    ) {
        switch update {
        case .realtime(let packet):
            dbgRealtimeFrames += 1
            handleParsedRealtimePacket(packet)
        case .commandResponse(let frame):
            maybeHandleCommandResponseFrame(
                frame,
                uuid: uuid,
                historyPhase: historyPhase
            )
        case .historyMetadata(let payload):
            handleHistoryMetadata(payload, historyPhase: historyPhase)
        case .historical(let payload):
            handleHistoricalData(payload, historyPhase: historyPhase)
        case .unknown(let payload, let fullFrame):
            handleUnknownProtocolPayload(payload,
                                         fullFrame: fullFrame,
                                         historyTransportActive: historyPhase.isActive)
        }
    }

    private static let mainActorPacketApplyYieldInterval = 6

    @discardableResult
    nonisolated static func trimPendingQueue<Element>(_ queue: inout [Element],
                                                       consumedCount: inout Int,
                                                       limit: Int) -> Int {
        precondition(limit >= 0)
        precondition(consumedCount >= 0 && consumedCount <= queue.count)
        let unconsumedCount = queue.count - consumedCount
        guard unconsumedCount > limit else { return 0 }

        if consumedCount > 0 {
            queue.removeFirst(consumedCount)
            consumedCount = 0
        }
        let overflow = queue.count - limit
        queue.removeFirst(overflow)
        return overflow
    }

    /// Attributes every evicted HR receipt to the link that produced it. The
    /// packet that happens to push the queue over its limit is not evidence of
    /// ownership for the older prefix being dropped.
    nonisolated static func heartRateIngressDropAttributions(
        _ receipts: [HeartRateIngressDropReceipt]
    ) -> [HeartRateIngressDropAttribution] {
        var attributed: [HeartRateIngressDropAttribution] = []
        var attributedIndexBySource: [AtriaBLECallbackEpochFence.Source: Int] = [:]
        attributed.reserveCapacity(receipts.count)
        attributedIndexBySource.reserveCapacity(min(receipts.count, 8))
        for receipt in receipts {
            if let index = attributedIndexBySource[receipt.callbackSource] {
                let existing = attributed[index]
                attributed[index] = HeartRateIngressDropAttribution(
                    droppedCount: existing.droppedCount + 1,
                    firstDroppedAt: min(existing.firstDroppedAt, receipt.receivedAt),
                    lastDroppedAt: max(existing.lastDroppedAt, receipt.receivedAt),
                    callbackSource: receipt.callbackSource
                )
            } else {
                attributed.append(HeartRateIngressDropAttribution(
                    droppedCount: 1,
                    firstDroppedAt: receipt.receivedAt,
                    lastDroppedAt: receipt.receivedAt,
                    callbackSource: receipt.callbackSource
                ))
                attributedIndexBySource[receipt.callbackSource] = attributed.count - 1
            }
        }
        return attributed
    }

    private func handleParsedRealtimePackets(_ updates: [PendingRealtimeUpdate]) async {
        guard let callbackSource = updates.first(where: {
            bleCallbackEpochFence.owns(source: $0.callbackSource)
        })?.callbackSource else { return }
        beginRealtimePacketBatch()
        defer { endRealtimePacketBatch(callbackSource: callbackSource) }
        for (index, update) in updates.enumerated() {
            guard update.callbackSource == callbackSource,
                  bleCallbackEpochFence.owns(source: callbackSource) else {
                continue
            }
            let packet = update.packet
            dbgPropFrames += 1
            dbgRealtimeFrames += 1
            handleParsedRealtimePacket(packet)
            if index < updates.count - 1,
               (index + 1).isMultiple(of: Self.mainActorPacketApplyYieldInterval) {
                await Task.yield()
            }
        }
    }

    private nonisolated func enqueueRealtimePacket(_ update: PendingRealtimeUpdate) {
        var shouldScheduleDrain = false
        realtimePacketQueueLock.lock()
        pendingRealtimePackets.append(update)
        Self.trimPendingQueue(&pendingRealtimePackets,
                              consumedCount: &pendingRealtimePacketHead,
                              limit: Self.pendingRealtimePacketLimit)
        if !realtimePacketDrainScheduled {
            realtimePacketDrainScheduled = true
            shouldScheduleDrain = true
        }
        realtimePacketQueueLock.unlock()
        guard shouldScheduleDrain else { return }
        Task { [weak self] in
            await self?.drainPendingRealtimePackets()
        }
    }

    private nonisolated func dequeuePendingRealtimePacketBatch(
        limit: Int
    ) -> [PendingRealtimeUpdate] {
        realtimePacketQueueLock.lock()
        let availableCount = pendingRealtimePackets.count - pendingRealtimePacketHead
        let count = min(limit, availableCount)
        let batch = count > 0
            ? Array(pendingRealtimePackets[pendingRealtimePacketHead..<(pendingRealtimePacketHead + count)])
            : []
        if count > 0 {
            pendingRealtimePacketHead += count
            if pendingRealtimePacketHead >= pendingRealtimePackets.count {
                pendingRealtimePackets.removeAll(keepingCapacity: true)
                pendingRealtimePacketHead = 0
            } else if pendingRealtimePacketHead >= 64,
                      pendingRealtimePacketHead * 2 >= pendingRealtimePackets.count {
                pendingRealtimePackets.removeFirst(pendingRealtimePacketHead)
                pendingRealtimePacketHead = 0
            }
        }
        realtimePacketQueueLock.unlock()
        return batch
    }

    private nonisolated func finishRealtimePacketDrainIfIdle() -> Bool {
        realtimePacketQueueLock.lock()
        let isIdle = pendingRealtimePacketHead >= pendingRealtimePackets.count
        if isIdle {
            pendingRealtimePackets.removeAll(keepingCapacity: true)
            pendingRealtimePacketHead = 0
            realtimePacketDrainScheduled = false
        }
        realtimePacketQueueLock.unlock()
        return isIdle
    }

    private nonisolated func drainPendingRealtimePackets() async {
        var batchesSinceRunLoopTurn = 0
        while true {
            let batch = dequeuePendingRealtimePacketBatch(limit: Self.realtimePacketBatchSize)
            if batch.isEmpty {
                if finishRealtimePacketDrainIfIdle() {
                    return
                }
                continue
            }
            await applyRealtimePacketBatch(batch)
            batchesSinceRunLoopTurn += 1
            if batchesSinceRunLoopTurn >= 8 {
                // A resumed app can receive a large CoreBluetooth backlog.
                // Yielding alone may immediately reschedule this same drain;
                // a tiny suspension gives the main run loop a real frame turn.
                batchesSinceRunLoopTurn = 0
                try? await Task.sleep(for: .milliseconds(2))
            } else {
                await Task.yield()
            }
        }
    }

    private func applyRealtimePacketBatch(_ updates: [PendingRealtimeUpdate]) async {
        await handleParsedRealtimePackets(updates)
    }

    private func handlePendingHeartRateUpdates(_ updates: [PendingHeartRateUpdate]) async {
        guard let callbackSource = updates.first(where: {
            bleCallbackEpochFence.owns(source: $0.callbackSource)
        })?.callbackSource else { return }
        beginAcceptedHeartRateBatch()
        defer { endAcceptedHeartRateBatch(callbackSource: callbackSource) }
        for (index, update) in updates.enumerated() {
            guard update.callbackSource == callbackSource,
                  bleCallbackEpochFence.owns(source: callbackSource) else {
                continue
            }
            recordHeartRateMeasurement(
                update.packet,
                rawData: update.rawData,
                callbackSource: callbackSource
            )
            if index < updates.count - 1,
               (index + 1).isMultiple(of: Self.mainActorPacketApplyYieldInterval) {
                await Task.yield()
            }
        }
    }

    private nonisolated func enqueueHeartRateUpdate(_ update: PendingHeartRateUpdate) {
        var shouldScheduleDrain = false
        heartRatePacketQueueLock.lock()
        pendingHeartRateUpdates.append(update)
        let unconsumedCount = pendingHeartRateUpdates.count - pendingHeartRateUpdateHead
        let overflowCount = max(0, unconsumedCount - Self.pendingHeartRateUpdateLimit)
        if overflowCount > 0 {
            let droppedRange = pendingHeartRateUpdateHead..<(pendingHeartRateUpdateHead + overflowCount)
            let receipts = pendingHeartRateUpdates[droppedRange].map {
                HeartRateIngressDropReceipt(receivedAt: $0.receivedAt,
                                            callbackSource: $0.callbackSource)
            }
            for attribution in Self.heartRateIngressDropAttributions(receipts) {
                let overflow = HeartRateIngressOverflow(
                    droppedCount: attribution.droppedCount,
                    firstDroppedAt: attribution.firstDroppedAt,
                    lastDroppedAt: attribution.lastDroppedAt
                )
                if let last = pendingHeartRateIngressOverflows.last,
                   last.callbackSource == attribution.callbackSource {
                    pendingHeartRateIngressOverflows[pendingHeartRateIngressOverflows.count - 1] =
                        PendingHeartRateIngressOverflow(
                            overflow: last.overflow.merged(with: overflow),
                            callbackSource: attribution.callbackSource
                        )
                } else {
                    pendingHeartRateIngressOverflows.append(
                        PendingHeartRateIngressOverflow(
                            overflow: overflow,
                            callbackSource: attribution.callbackSource
                        )
                    )
                }
            }
        }
        let removed = Self.trimPendingQueue(&pendingHeartRateUpdates,
                                            consumedCount: &pendingHeartRateUpdateHead,
                                            limit: Self.pendingHeartRateUpdateLimit)
        assert(removed == overflowCount)
        if !heartRatePacketDrainScheduled {
            heartRatePacketDrainScheduled = true
            shouldScheduleDrain = true
        }
        heartRatePacketQueueLock.unlock()
        guard shouldScheduleDrain else { return }
        Task { [weak self] in
            await self?.drainPendingHeartRateUpdates()
        }
    }

    private nonisolated func dequeuePendingHeartRateUpdateBatch(
        limit: Int
    ) -> PendingHeartRateDrainBatch {
        heartRatePacketQueueLock.lock()
        let overflows = pendingHeartRateIngressOverflows
        pendingHeartRateIngressOverflows.removeAll(keepingCapacity: true)
        let availableCount = pendingHeartRateUpdates.count - pendingHeartRateUpdateHead
        let count = min(limit, availableCount)
        let batch = count > 0
            ? Array(pendingHeartRateUpdates[pendingHeartRateUpdateHead..<(pendingHeartRateUpdateHead + count)])
            : []
        if count > 0 {
            pendingHeartRateUpdateHead += count
            if pendingHeartRateUpdateHead >= pendingHeartRateUpdates.count {
                pendingHeartRateUpdates.removeAll(keepingCapacity: true)
                pendingHeartRateUpdateHead = 0
            } else if pendingHeartRateUpdateHead >= 64,
                      pendingHeartRateUpdateHead * 2 >= pendingHeartRateUpdates.count {
                pendingHeartRateUpdates.removeFirst(pendingHeartRateUpdateHead)
                pendingHeartRateUpdateHead = 0
            }
        }
        heartRatePacketQueueLock.unlock()
        return PendingHeartRateDrainBatch(updates: batch, overflows: overflows)
    }

    private nonisolated func finishHeartRatePacketDrainIfIdle() -> Bool {
        heartRatePacketQueueLock.lock()
        let isIdle = pendingHeartRateUpdateHead >= pendingHeartRateUpdates.count
        if isIdle {
            pendingHeartRateUpdates.removeAll(keepingCapacity: true)
            pendingHeartRateUpdateHead = 0
            heartRatePacketDrainScheduled = false
        }
        heartRatePacketQueueLock.unlock()
        return isIdle
    }

    private nonisolated func drainPendingHeartRateUpdates() async {
        var batchesSinceRunLoopTurn = 0
        while true {
            let drained = dequeuePendingHeartRateUpdateBatch(limit: Self.heartRatePacketBatchSize)
            for pendingOverflow in drained.overflows {
                await recordHeartRateIngressOverflow(pendingOverflow)
            }
            if drained.updates.isEmpty {
                if finishHeartRatePacketDrainIfIdle() {
                    return
                }
                continue
            }
            await applyPendingHeartRateUpdates(drained.updates)
            batchesSinceRunLoopTurn += 1
            if batchesSinceRunLoopTurn >= 8 {
                batchesSinceRunLoopTurn = 0
                try? await Task.sleep(for: .milliseconds(2))
            } else {
                await Task.yield()
            }
        }
    }

    private func applyPendingHeartRateUpdates(_ updates: [PendingHeartRateUpdate]) async {
        await handlePendingHeartRateUpdates(updates)
    }

    /// A bounded ingress queue protects the callback thread, but it must never
    /// turn overload into an invisible health-data hole. Persist the exact
    /// receive-time envelope, queue verified history recovery, and force the
    /// live journal checkpoint. No samples are manufactured or interpolated.
    private func recordHeartRateIngressOverflow(
        _ pending: PendingHeartRateIngressOverflow
    ) {
        guard bleCallbackEpochFence.owns(source: pending.callbackSource) else {
            return
        }
        let overflow = pending.overflow
        let start = lastAcceptedHRAt ?? overflow.firstDroppedAt
        let end = max(start, overflow.lastDroppedAt)
        let gap = end.timeIntervalSince(start)
        sessionRawHRGaps += 1
        sessionAcceptedHRGaps += 1
        sessionMaxRawHRGap = max(sessionMaxRawHRGap, gap)
        sessionMaxAcceptedHRGap = max(sessionMaxAcceptedHRGap, gap)
        sampleDiagnostics.rawGaps += 1
        sampleDiagnostics.acceptedGaps += 1
        sampleDiagnostics.maxRawGap = max(sampleDiagnostics.maxRawGap, gap)
        sampleDiagnostics.maxAcceptedGap = max(sampleDiagnostics.maxAcceptedGap, gap)
        setSampleDiagnosticsStatus("ingress_overflow", reason: "heart_rate_queue_drop")
        let continuityRelevant = Self.isBLEContinuityRelevant(
            longWearEnabled: longWearModeEnabled,
            activeExplicitWorkout: AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
        )
        let recordedGap = continuityRelevant && AtriaHistoricalGapLedger.recordObservedGap(
            start: start,
            end: end,
            reason: "heart_rate_ingress_overflow",
            minimumDuration: SavedSession.workoutContinuityGapLimit
        )
        if recordedGap {
            markRangeLossBackfillRequired(
                reason: AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
                    ? "explicit_workout_range_loss" : "long_wear_range_loss"
            )
            scheduleRangeLossBackfillIfNeeded(reason: "heart_rate_ingress_overflow")
        }
        AtriaDebugLog("ATRIADBG hr_ingress_overflow dropped=%d start_unix=%.3f end_unix=%.3f gap_s=%.3f ledger_gap=%d action=retain_missing_window_no_interpolation",
                      overflow.droppedCount,
                      start.timeIntervalSince1970,
                      end.timeIntervalSince1970,
                      gap,
                      recordedGap ? 1 : 0)
        persistActiveSessionJournalIfNeeded(reason: "heart_rate_ingress_overflow", force: true)
        flushSampleDiagnostics()
    }

    private func handleParsedRealtimePacket(_ packet: ParsedRealtimePacket) {
        if !replayingBufferedSessionInputs,
           r10SessionBoundaryID != nil || activeSessionRestoreInFlightGeneration != nil ||
            strapStepLedgerRestoreInFlight {
            bufferedSessionInputs.append(.realtime(packet))
            return
        }
        if packet.realtimeUnix > 0 {
            lastRealtimeUnix = packet.realtimeUnix
        }
        if hrConsistencyEnabled {
            lastRealtimeHR = (packet.hr, packet.frameTime)
            if realtimePacketBatchDepth > 0 {
                realtimeBatchPendingConsistencyAt = packet.frameTime
            } else {
                compareHRChannelsIfPossible(now: packet.frameTime, source: "0x28")
            }
        }

        let rrnum = packet.rrValues.count
        let standardRecentlyActive = lastStandardRRAt.map { packet.frameTime.timeIntervalSince($0) <= 2.5 } ?? false
        let useForMetrics = Self.shouldUseProprietaryRealtimeRRForMetrics(
            standardRecentlyActive: standardRecentlyActive
        )
        if useForMetrics {
            if !packet.rrValues.isEmpty {
                usedRealtimeRRValues += packet.rrValues.count
                addRRBatch(intervalsMS: packet.rrValues,
                           endingAt: packet.frameTime,
                           source: "0x28",
                           opcode: "28",
                           expectedHR: nil)
            }
            updateRRContinuityQuality(now: packet.frameTime, rrCount: rrnum, source: "0x28")
            if autoCapturePending, autoCaptureRRThreshold > 0 {
                updateAdaptiveAutoCapture(now: packet.frameTime, rrnum: rrnum, source: "0x28")
            }
        } else if isRecording, !packet.rrValues.isEmpty {
            recordUnvalidatedProprietaryRRResearch(packet.rrValues,
                                                   endingAt: packet.frameTime,
                                                   opcode: "28")
        }
        if realtimePacketBatchDepth > 0 {
            realtimeBatchPendingRestart = (now: packet.frameTime, rrnum: rrnum)
            if packet.realtimeUnix > 0 {
                realtimeBatchPendingHistorySweepUnix = packet.realtimeUnix
            }
        } else {
            maybeRestartRealtimeAfterZeroRR(now: packet.frameTime, rrnum: rrnum)
            if historyRecentSweepEnabled {
                maybeSendRecentHistorySweep(realtimeUnix: packet.realtimeUnix)
            }
        }

        if !packet.rrValues.isEmpty || packet.truncated {
            decodedRealtimeRRValues += packet.rrValues.count
        }
    }

    @discardableResult
    private func persistFinishedSessionDurably(
        _ saved: SavedSession,
        reason: String
    ) async -> Bool {
        if longWearModeEnabled,
           saved.duration < minimumFinishedLongWearDuration,
           reason != "user_stop",
           reason != "manual_finish" {
            persistActiveSessionJournalIfNeeded(
                reason: "\(reason)_short_fragment_checkpoint",
                force: true
            )
            ActiveSessionJournal.recordClose(status: "retained_short_fragment",
                                             reason: reason,
                                             label: saved.label,
                                             samples: saved.points.count,
                                             duration: saved.duration)
            return false
        }
        guard let onSessionEndDurably,
              await onSessionEndDurably(saved) else {
            ActiveSessionJournal.recordClose(status: "store_failed",
                                             reason: reason,
                                             label: saved.label,
                                             samples: saved.points.count,
                                             duration: saved.duration)
            AtriaDebugLog(
                "ATRIADBG active_session_journal status=retained reason=durable_store_failed finish_reason=%@ label=%@ samples=%d",
                reason,
                saved.label,
                saved.points.count
            )
            return false
        }
        return true
    }

    @discardableResult
    private func persistFinishedSession(_ saved: SavedSession, reason: String) -> Bool {
        if longWearModeEnabled,
           saved.duration < minimumFinishedLongWearDuration,
           reason != "user_stop",
           reason != "manual_finish" {
            persistActiveSessionJournalIfNeeded(reason: "\(reason)_short_fragment_checkpoint", force: true)
            ActiveSessionJournal.recordClose(status: "retained_short_fragment",
                                             reason: reason,
                                             label: saved.label,
                                             samples: saved.points.count,
                                             duration: saved.duration)
            AtriaDebugLog("ATRIADBG session_finish status=skipped reason=long_wear_short_fragment finish_reason=%@ samples=%d rr_samples=%d duration_s=%.0f min_duration_s=%.0f label=%@ action=retain_active_journal",
                          reason,
                          saved.points.count,
                          saved.rrSampleCount,
                          saved.duration,
                          minimumFinishedLongWearDuration,
                          saved.label)
            return false
        }
        guard onSessionEnd?(saved) == true else {
            ActiveSessionJournal.recordClose(status: "store_failed",
                                             reason: reason,
                                             label: saved.label,
                                             samples: saved.points.count,
                                             duration: saved.duration)
            AtriaDebugLog("ATRIADBG active_session_journal status=retained reason=store_failed finish_reason=%@ label=%@ samples=%d",
                  reason,
                  saved.label,
                  saved.points.count)
            return false
        }
        clearFinishedSessionJournal(after: saved, reason: reason)
        return true
    }

    func clearFinishedSessionJournal(after saved: SavedSession, reason: String) {
        activeJournalDirtySamples = 0
        activeJournalPendingTimestampRefresh = false
        cancelTrailingActiveJournalCheckpoint()
        lastActiveJournalSavedSessionSampleCount = 0
        lastActiveJournalSavedRRArchiveCount = 0
        lastActiveJournalPersistedSampleCount = 0
        lastActiveJournalPersistedRRCount = 0
        lastActiveJournalSavedResearchAggregates = .zero
        activeJournalNeedsFullRebase = false
        ActiveSessionJournal.recordClose(status: "cleared",
                                         reason: reason,
                                         label: saved.label,
                                         samples: saved.points.count,
                                         duration: saved.duration)
        ActiveSessionJournal.clear()
        AtriaDebugLog("ATRIADBG active_session_journal status=cleared reason=%@ label=%@ samples=%d duration_s=%.0f close_recorded=1",
              reason,
              saved.label,
              saved.points.count,
              saved.duration)
    }

    @discardableResult
    private func clearUnsavableActiveJournalIfNeeded(reason: String) -> Bool {
        guard longWearModeEnabled, !session.isEmpty, session.count < 2 else { return false }
        let label = captureLabel.isEmpty ? "All-day wear" : captureLabel
        let duration = max(0, (session.last?.t ?? sessionStart).timeIntervalSince(sessionStart))
        activeJournalDirtySamples = 0
        activeJournalPendingTimestampRefresh = false
        cancelTrailingActiveJournalCheckpoint()
        lastActiveJournalSavedSessionSampleCount = 0
        lastActiveJournalSavedRRArchiveCount = 0
        lastActiveJournalPersistedSampleCount = 0
        lastActiveJournalPersistedRRCount = 0
        lastActiveJournalSavedResearchAggregates = .zero
        activeJournalNeedsFullRebase = false
        ActiveSessionJournal.recordClose(status: "cleared_unsavable",
                                         reason: reason,
                                         label: label,
                                         samples: session.count,
                                         duration: duration)
        ActiveSessionJournal.clear()
        AtriaDebugLog("ATRIADBG active_session_journal status=cleared reason=%@ label=%@ samples=%d duration_s=%.0f action=drop_unsavable_stale_segment",
                      reason,
                      label,
                      session.count,
                      duration)
        return true
    }

    /// Refresh the off-main historical-gravity motion summary for the current live
    /// session window. Runs the multi-MB archive parse on a utility queue so it can
    /// never block the MainActor (the freeze `snapshotSession` used to cause). Rate-
    /// limited to ~30 s and keyed by the session origin, so a new rolled/reset
    /// segment invalidates the previous value. Fire-and-forget; the result is picked
    /// up by the next `snapshotSession`.
    private func refreshHistoricalMotionCache(start: Date, end: Date) {
        guard !historicalMotionRefreshInFlight else { return }
        guard !HistoricalArchive
            .exactRecoveryProjectionOwnsArchivePriority() else {
            return
        }
        if cachedHistoricalMotionOrigin == start,
           let at = cachedHistoricalMotionAt,
           Date().timeIntervalSince(at) < 30 {
            return
        }
        historicalMotionRefreshInFlight = true
        HistoricalArchive.consumerProjectionQueue.async { [weak self, start, end] in
            guard !HistoricalArchive
                .exactRecoveryProjectionOwnsArchivePriority() else {
                Task { @MainActor [weak self] in
                    self?.historicalMotionRefreshInFlight = false
                }
                return
            }
            let summary = HistoricalArchive.motionFeatureSummary(start: start, end: end)
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.cachedHistoricalMotion = summary
                self.cachedHistoricalMotionOrigin = start
                self.cachedHistoricalMotionAt = Date()
                self.historicalMotionRefreshInFlight = false
            }
        }
    }

    /// Snapshot the current HR session into a persistable record without
    /// resetting it, so unattended long runs survive debugger/device drops.
    func snapshotSession(label: String,
                         strengthSets: [LoggedSet] = [],
                         excludedIntervals: [ExcludedInterval] = [],
                         motionSnapshotOverride: AtriaR10MotionPipeline.Snapshot? = nil) -> SavedSession? {
        guard let first = session.first, let last = session.last, session.count > 1 else { return nil }
        let start = first.t
        let points: [SavedSession.Point]
        if sessionPointsCache.count == session.count,
           sessionOriginTime == start {
            points = sessionPointsCache
        } else {
            points = session.map { SavedSession.Point(t: $0.t.timeIntervalSince(start), bpm: $0.bpm) }
        }

        let rrPoints: [SavedSession.RRPoint]
        if sessionOriginTime == start,
           rrPointsCache.count == rrArchive.count {
            rrPoints = rrPointsCache
        } else {
            rrPoints = rrArchive
                .filter { $0.t >= start && $0.t <= last.t.addingTimeInterval(1) }
                .map { SavedSession.RRPoint(t: $0.t.timeIntervalSince(start),
                                            ms: Int($0.ms.rounded()),
                                            source: $0.source) }
        }
        let motionShortStats = sleepMotionShortSummary()
        let liveIMU = motionSnapshotOverride.map {
            (stillnessRatio: Optional($0.stillnessRatio),
             movementIntensity: Optional($0.movementIntensity),
             sampleRateHz: Optional(Double(AtriaStrapPedometer.sampleRateHz)))
        } ?? imuFeatureSummary()
        // `Snapshot.steps` is the legacy accelerometer-peak coordinate. The
        // saved Session must use the same gyro coordinate as Home so a segment
        // roll/relaunch cannot reintroduce the inferior source.
        let snapshotStrapSteps = max(
            strapStepResearchCount,
            currentGyroCadenceResearchSessionSteps()
        )
        // A count of zero is valid evidence only after this session has
        // received at least one strap R10 motion frame.  Keep unknown separate
        // from zero so sleep detection cannot mistake a missing step channel
        // for stillness.
        let strapStepEvidenceAvailable = (motionSnapshotOverride?.frames
            ?? protocolIMUFrameCount) > 0
        // Historical-gravity motion evidence NEVER parses the archive on the
        // MainActor here (device-reported tab-switch freeze, 2026-07-09): it reads
        // the background-refreshed off-main cache (`cachedHistoricalMotion`, keyed by
        // this session's `start`). If the cache isn't warm for this session yet (its
        // first checkpoint, or a just-rolled segment) it falls back to nil -- the
        // HR-only sleep tier -- and kicks off an off-main refresh so the next
        // checkpoint has it (negligible for multi-hour sleep windows). Still skipped
        // entirely under thermal / Low-Power pressure (shouldDeferNonEssentialAnalysis),
        // mirroring the long-wear supervisor's own autosave/diagnostic deferral.
        let historicalIMU: HistoricalArchive.MotionFeatureSummary?
        // A live stillness value must NOT suppress the historical cache. The
        // classifier below reads its features only from `historicalIMU`, so
        // nulling it whenever live motion happened to decode meant the live
        // value blocked the one accepted source and was then discarded itself
        // — every such session recorded motionEvidenceSource=unavailable and
        // classified as `imu_missing` (observed 106 of 107 sessions). Thermal
        // and Low-Power deferral remain, since those are about not doing the
        // work at all.
        if powerThermalGovernor.shouldDeferNonEssentialAnalysis {
            historicalIMU = nil
        } else if cachedHistoricalMotionOrigin == start {
            historicalIMU = cachedHistoricalMotion
            refreshHistoricalMotionCache(start: start, end: last.t)
        } else {
            historicalIMU = nil
            refreshHistoricalMotionCache(start: start, end: last.t)
        }
        // The live 0x33 decoder still infers offset/endian/scale. Preserve those
        // values as diagnostics, but only validated historical gravity may
        // influence sleep/wake classification.
        let classifierIMUStillnessRatio = historicalIMU?.stillnessRatio
        let classifierIMUMovementIntensity = historicalIMU?.movementIntensity
        let motionEvidenceSource = historicalIMU != nil ? "historical_gravity" : sleepMotionSource
        let motionEvidenceValidated = historicalIMU?.lowMotionReady ?? false
        let sessionAggregateMatchesCache = sessionOriginTime == start
            && sessionPointsCache.count == session.count
            && sessionHeartRateAggregateCount == session.count
        let averageHR: Int
        let hrStandardDeviation: Double
        let minimumHR: Int
        if sessionAggregateMatchesCache, let sessionMinHeartRate {
            averageHR = sessionHeartRateTotal / max(sessionHeartRateAggregateCount, 1)
            hrStandardDeviation = sqrt(max(0, sessionHeartRateM2) / Double(sessionHeartRateAggregateCount))
            minimumHR = sessionMinHeartRate
        } else {
            averageHR = session.map(\.bpm).reduce(0, +) / max(session.count, 1)
            hrStandardDeviation = Self.standardDeviation(session.map { Double($0.bpm) })
            minimumHR = session.map(\.bpm).min() ?? averageHR
        }
        let restingHeartRate = restingHR ?? min(averageHR, minimumHR)
        let sleepWake = AtriaSleepWakeResearch.classify(duration: last.t.timeIntervalSince(start),
                                                        averageHR: averageHR,
                                                        restingHR: restingHeartRate,
                                                        imuStillnessRatio: classifierIMUStillnessRatio,
                                                        imuMovementIntensity: classifierIMUMovementIntensity,
                                                        strapSteps: strapStepEvidenceAvailable ? snapshotStrapSteps : nil,
                                                        strapStepEvidenceAvailable: strapStepEvidenceAvailable,
                                                        windowStart: start,
                                                        hrStandardDeviation: hrStandardDeviation)
        let respiratoryRate = sleepWake.state == "sleep_research" && hrvSnapshot?.isReady == true
            ? hrvSnapshot?.respiratoryRate
            : nil
        let profile = AthleteProfile.load()
        let activeCalories = activeCaloriesForSnapshot(rest: restingHeartRate,
                                                       profile: profile,
                                                       excludedIntervals: excludedIntervals)
        let caloriesConfidence: String? = session.count > 1 ? (profile.hasEnergyProfile ? "estimate" : "needs_profile") : nil
        return SavedSession(id: liveSessionID, start: start, end: last.t,
                            label: label.trimmingCharacters(in: .whitespaces), points: points,
                            hrv: hrv > 0 ? hrv : nil,
                            respiratoryRate: respiratoryRate,
                            rrPoints: rrPoints.isEmpty ? nil : rrPoints,
                            hrvReferenceValidated: false,
                            motionHintCount: sleepMotionHintCount,
                            motionHintKinds: sleepMotionHintKinds,
                            motionEvidenceSource: motionEvidenceSource,
                            motionEvidenceValidated: motionEvidenceValidated,
                            motionShortCount: motionShortStats.count > 0 ? motionShortStats.count : nil,
                            motionShortMean: motionShortStats.mean,
                            motionShortMin: motionShortStats.min,
                            motionShortMax: motionShortStats.max,
                            motionShortOverOneCount: motionShortStats.count > 0 ? motionShortStats.overOne : nil,
                            imuSampleCount: motionSnapshotOverride?.samples
                                ?? (decodedIMUSampleCount > 0 ? decodedIMUSampleCount : nil),
                            imuFrameCount: motionSnapshotOverride?.frames
                                ?? (protocolIMUFrameCount > 0 ? protocolIMUFrameCount : nil),
                            imuSampleRateHz: liveIMU.sampleRateHz,
                            imuScale: imuInferredScale,
                            imuEndian: imuInferredEndian,
                            imuStillnessRatio: liveIMU.stillnessRatio ?? historicalIMU?.stillnessRatio,
                            imuMovementIntensity: liveIMU.movementIntensity ?? historicalIMU?.movementIntensity,
                            imuActivityBursts: decodedIMUSampleCount > 0 ? imuActivityBurstCount : nil,
                            imuValidationState: decodedIMUSampleCount > 0 ? imuValidationState : nil,
                            strapStepResearchCount: snapshotStrapSteps > 0 ? snapshotStrapSteps : nil,
                            strapStepResearchAgreement: nil,
                            strapStepResearchState: snapshotStrapSteps > 0
                                ? strapStepResearchState : nil,
                            sleepWakeResearchState: sleepWake.state == "learning" ? nil : sleepWake.state,
                            sleepWakeResearchConfidence: sleepWake.confidence == "none" ? nil : sleepWake.confidence,
                            sleepWakeResearchReason: sleepWake.reason,
                            sensorResearchProbeFrames: researchProbeFrameCount > 0 ? researchProbeFrameCount : nil,
                            spo2ResearchCandidateFrames: researchProbeOxygenCandidateFrames > 0 ? researchProbeOxygenCandidateFrames : nil,
                            skinTempResearchCandidateFrames: researchProbeTemperatureCandidateFrames > 0 ? researchProbeTemperatureCandidateFrames : nil,
                            skinTempResearchCandidateValueSum: researchProbeTemperatureCandidateValueCount > 0 ? researchProbeTemperatureCandidateValueSum : nil,
                            skinTempResearchCandidateValueCount: researchProbeTemperatureCandidateValueCount > 0 ? researchProbeTemperatureCandidateValueCount : nil,
                            spo2ResearchCandidateOffset64ValueSum: researchProbeOxygenOffset64ValueCount > 0 ? researchProbeOxygenOffset64ValueSum : nil,
                            spo2ResearchCandidateOffset64ValueCount: researchProbeOxygenOffset64ValueCount > 0 ? researchProbeOxygenOffset64ValueCount : nil,
                            spo2ResearchCandidateOffset66ValueSum: researchProbeOxygenOffset66ValueCount > 0 ? researchProbeOxygenOffset66ValueSum : nil,
                            spo2ResearchCandidateOffset66ValueCount: researchProbeOxygenOffset66ValueCount > 0 ? researchProbeOxygenOffset66ValueCount : nil,
                            biologicalSex: profile.biologicalSex,
                            activeCalories: activeCalories,
                            caloriesConfidence: caloriesConfidence,
                            hrRaw2A37: sessionRawHRNotifications,
                            hrAccepted: sessionAcceptedHRSamples,
                            hrZero: sessionZeroHRSamples,
                            hrArtifactHeld: sessionHeldArtifacts,
                            hrArtifactDropped: sessionDroppedArtifacts,
                            hrRawGaps: sessionRawHRGaps,
                            hrAcceptedGaps: sessionAcceptedHRGaps,
                            hrMaxRawGap: sessionMaxRawHRGap,
                            hrMaxAcceptedGap: sessionMaxAcceptedHRGap,
                            strengthSets: strengthSets.isEmpty ? nil : strengthSets,
                            excludedIntervals: excludedIntervals.isEmpty ? nil : excludedIntervals,
                            eventTimeZoneIdentifier: liveSessionEventTimeZoneIdentifier)
    }

    private func resetSessionMotionDiagnostics(
        carriedMotionSnapshot: AtriaR10MotionPipeline.Snapshot?
    ) {
        sleepMotionHintCount = 0
        sleepMotionHintKinds = "none"
        sleepMotionHintKindCounts.removeAll(keepingCapacity: true)
        sleepMotionShortValues.removeAll(keepingCapacity: true)
        sleepMotionSource = "unavailable"
        resetIMUFeatureStats(carriedMotionSnapshot: carriedMotionSnapshot)
    }

    private func recordIMUFeatures(_ decoded: AtriaIMUDecoder.DecodeResult) {
        let now = Date()
        if let previous = imuLastFrameAt {
            let delta = now.timeIntervalSince(previous)
            if delta > 0.02, delta < 10 {
                imuSampleRateHzSum += Double(decoded.samples.count) / delta
                imuSampleRateHzCount += 1
            }
        }
        imuLastFrameAt = now
        decodedIMUSampleCount += decoded.samples.count
        imuInferredScale = decoded.scale
        imuInferredEndian = decoded.endian.rawValue
        rollStrapStepResearchDayIfNeeded(now: now, currentSessionCount: strapStepResearchCount)
        let stepEstimate = AtriaStrapStepResearch.estimate(samples: decoded.samples,
                                                           sampleRateHz: imuFeatureSummary().sampleRateHz)
        // This decoder path is not the validated fixed-layout R10 pipeline.
        // Preserve its peaks solely as diagnostics; it may never advance the
        // user-facing daily total as a fallback.
        strapStepResearchPeakCount += stepEstimate.peaks
        if strapStepResearchCount == 0 {
            strapStepResearchState = stepEstimate.state
            assignIfChanged(\.liveStrapStepResearchState, strapStepResearchState)
        }
        imuStillnessRatioSum += decoded.stillnessRatio
        imuMovementIntensitySum += decoded.movementIntensity
        imuActivityBurstCount += decoded.activityBursts
        if decoded.gravityValidated {
            imuGravityValidatedFrameCount += 1
        }
        imuValidationState = imuGravityValidatedFrameCount > 0 ? "gravity_validated_research" : "research_unvalidated"
    }

    /// Restores motion continuity independently from HR/RR journal recovery.
    /// The pipeline queue serializes this seed with already-arriving R10 frames,
    /// so the durable prefix is added once and its watermark rejects replay.
    private func restoreStrapStepLedgerAtLaunch() {
        let launchSessionID = liveSessionID
        Task { @MainActor [weak self] in
            let record = await Task.detached(priority: .utility) {
                AtriaStrapStepLedger.loadForRestore()
            }.value
            guard let self else { return }
            guard let record else {
                self.strapStepLedgerRestoreInFlight = false
                self.lastStrapStepLedgerSaveAt = Date()
                let pending = self.strapStepLedgerSavePending
                self.strapStepLedgerSavePending = false
                if self.strapStepResearchPeakCount > 0
                    || self.currentGyroCadenceResearchSessionSteps() > 0 {
                    if pending {
                        self.persistStrapStepLedgerIfNeeded(reason: "launch_restore_pending",
                                                            force: true)
                    } else {
                        self.scheduleStrapStepLedgerCheckpoint(now: Date())
                    }
                }
                self.resumeActiveSessionRestoreAfterStrapStepLedger()
                return
            }

            let restored = await self.r10MotionPipeline.seed(
                committedRawSteps: record.segmentRawSteps,
                lastAcceptedDeviceTimestamp: record.deviceTimestamp,
                committedGyroCadenceResearchSteps: record.segmentGyroCadenceResearchSteps
            )
            // A normal launch can receive fresh R10/HR while the tiny file is
            // decoded. Adopt the durable segment identity only if no other
            // restore or boundary has already installed a different identity.
            if self.liveSessionID == launchSessionID,
               self.r10SessionBoundaryID == nil,
               self.session.isEmpty,
               self.activeSessionRestoreInFlightGeneration == nil,
               self.lastActiveJournalSavedSessionSampleCount == 0 {
                self.liveSessionID = record.segmentID
                self.sessionStart = min(self.sessionStart, record.segmentStartedAt)
            }
            // Existing ledgers may contain a legacy `segmentSteps` peak value.
            // Promote only their independently checkpointed gyro total; absent
            // gyro evidence fails closed instead of silently changing history.
            self.strapStepResearchCount = max(
                self.strapStepResearchCount,
                record.segmentGyroCadenceResearchSteps ?? 0
            )
            self.strapStepResearchPeakCount = max(self.strapStepResearchPeakCount, restored.rawSteps)
            self.strapStepResearchDeviceTimestamp = Self.newestR10DeviceTimestamp(
                existing: record.deviceTimestamp,
                incoming: self.strapStepResearchDeviceTimestamp
            )
            self.lastStrapStepLedgerSavedRawSteps = record.segmentRawSteps
            self.lastStrapStepLedgerSavedGyroCadenceResearchSteps =
                record.segmentGyroCadenceResearchSteps ?? 0
            self.strapStepLedgerGyroCumulativePrefix = max(
                0,
                (record.cumulativeGyroCadenceResearchSteps ?? 0)
                    - (record.segmentGyroCadenceResearchSteps ?? 0)
            )
            self.lastStrapStepLedgerSaveAt = record.updatedAt
            self.strapStepLedgerUnhandedRestoreRebindSourceSegmentID = self.liveSessionID != record.segmentID
                ? record.segmentID
                : nil
            self.strapStepLedgerRestoreInFlight = false
            let pending = self.strapStepLedgerSavePending
            self.strapStepLedgerSavePending = false
            self.publishLiveStrapStepResearchIfNeeded(force: true)
            if self.strapStepResearchPeakCount > record.segmentRawSteps
                || self.currentGyroCadenceResearchSessionSteps()
                    > (record.segmentGyroCadenceResearchSteps ?? 0) {
                if pending {
                    self.persistStrapStepLedgerIfNeeded(reason: "launch_restore_pending",
                                                        force: true)
                } else {
                    self.scheduleStrapStepLedgerCheckpoint(now: Date())
                }
            }
            AtriaDebugLog(
                "ATRIADBG strap_step_ledger status=restored segment_match=%d raw_steps=%d watermark=%u",
                self.liveSessionID == record.segmentID ? 1 : 0,
                restored.rawSteps,
                record.deviceTimestamp ?? 0
            )
            self.resumeActiveSessionRestoreAfterStrapStepLedger()
        }
    }

    /// Timer coalescing: every accepted R10 stream gets one bounded durability
    /// check per 15s. The check computes the open gyro span only when it fires;
    /// unchanged stationary snapshots still perform no disk write.
    private func scheduleStrapStepLedgerCheckpoint(now: Date,
                                                   minimumDelay: TimeInterval = 0) {
        guard !strapStepLedgerRestoreInFlight,
              strapStepLedgerCheckpointTask == nil else { return }
        let delay = max(
            minimumDelay,
            Self.strapStepLedgerCheckpointDelay(lastSavedAt: lastStrapStepLedgerSaveAt,
                                                 now: now)
        )
        strapStepLedgerCheckpointTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(delay))
            guard let self, !Task.isCancelled else { return }
            self.strapStepLedgerCheckpointTask = nil
            self.persistStrapStepLedgerIfNeeded(reason: "r10_changed_count", force: true)
        }
    }

    private func persistStrapStepLedgerIfNeeded(reason: String, force: Bool) {
        guard !strapStepLedgerRestoreInFlight else {
            strapStepLedgerSavePending = strapStepLedgerSavePending || force
            return
        }
        let gyroCadenceResearchSteps = currentGyroCadenceResearchSessionSteps()
        guard Self.strapStepLedgerHasUnsavedResearchSteps(
            currentRawSteps: strapStepResearchPeakCount,
            persistedRawSteps: lastStrapStepLedgerSavedRawSteps,
            currentGyroSteps: gyroCadenceResearchSteps,
            persistedGyroSteps: lastStrapStepLedgerSavedGyroCadenceResearchSteps
        ) else { return }
        if !force,
           let lastStrapStepLedgerSaveAt,
           Date().timeIntervalSince(lastStrapStepLedgerSaveAt) < Self.strapStepCheckpointMaximumAge {
            scheduleStrapStepLedgerCheckpoint(now: Date())
            return
        }
        guard !strapStepLedgerSaveInFlight else {
            strapStepLedgerSavePending = true
            return
        }

        strapStepLedgerCheckpointTask?.cancel()
        strapStepLedgerCheckpointTask = nil
        strapStepLedgerSaveInFlight = true
        let segmentID = liveSessionID
        let segmentStartedAt = sessionStart
        let segmentSteps = strapStepResearchCount
        let segmentRawSteps = strapStepResearchPeakCount
        let deviceTimestamp = strapStepResearchDeviceTimestamp
        let state = strapStepResearchState
        let unhandedRebindingSourceSegmentID = strapStepLedgerUnhandedRestoreRebindSourceSegmentID
        let savedAt = Date()
        Task.detached(priority: .utility) { [weak self] in
            let result: Result<(AtriaStrapStepLedger.Record, URL?), Error> = Result {
                do {
                    let record = try AtriaStrapStepLedger.checkpoint(
                        segmentID: segmentID,
                        segmentStartedAt: segmentStartedAt,
                        segmentSteps: segmentSteps,
                        segmentRawSteps: segmentRawSteps,
                        deviceTimestamp: deviceTimestamp,
                        state: state,
                        gyroCadenceResearchSteps: gyroCadenceResearchSteps,
                        now: savedAt,
                        unhandedRebindingSourceSegmentID:
                            unhandedRebindingSourceSegmentID
                    )
                    return (record, nil)
                } catch AtriaStrapStepLedger.SaveError.malformed {
                    let recovered = try AtriaStrapStepLedger
                        .recoverMalformedFileAndCheckpoint(
                            segmentID: segmentID,
                            segmentStartedAt: segmentStartedAt,
                            segmentSteps: segmentSteps,
                            segmentRawSteps: segmentRawSteps,
                            deviceTimestamp: deviceTimestamp,
                            state: state,
                            gyroCadenceResearchSteps:
                                gyroCadenceResearchSteps,
                            now: savedAt
                        )
                    return (
                        recovered.record,
                        recovered.quarantinedMalformedURL
                    )
                }
            }
            await self?.finishStrapStepLedgerSave(result,
                                                  segmentID: segmentID,
                                                  reason: reason)
        }
    }

    private func finishStrapStepLedgerSave(
        _ result: Result<(AtriaStrapStepLedger.Record, URL?), Error>,
        segmentID: UUID,
        reason: String
    ) {
        strapStepLedgerSaveInFlight = false
        var failureRetryDelay: TimeInterval?
        switch result {
        case let .success((record, quarantinedMalformedURL)):
            strapStepLedgerConsecutiveSaveFailures = 0
            strapStepLedgerLastFailureDescription = nil
            if liveSessionID == segmentID {
                if strapStepLedgerUnhandedRestoreRebindSourceSegmentID != nil {
                    strapStepLedgerUnhandedRestoreRebindSourceSegmentID = nil
                }
                lastStrapStepLedgerSavedRawSteps = max(lastStrapStepLedgerSavedRawSteps,
                                                       record.segmentRawSteps)
                lastStrapStepLedgerSavedGyroCadenceResearchSteps = max(
                    lastStrapStepLedgerSavedGyroCadenceResearchSteps,
                    record.segmentGyroCadenceResearchSteps ?? 0
                )
                strapStepLedgerGyroCumulativePrefix = max(
                    0,
                    (record.cumulativeGyroCadenceResearchSteps ?? 0)
                        - (record.segmentGyroCadenceResearchSteps ?? 0)
                )
                lastStrapStepLedgerSaveAt = record.updatedAt
            }
            if let quarantinedMalformedURL {
                AtriaDebugLog("ATRIADBG strap_step_ledger status=recovered_malformed reason=%@ raw_steps=%d quarantine=%@ durability=atomic_fsync",
                              reason,
                              record.segmentRawSteps,
                              quarantinedMalformedURL.lastPathComponent)
            } else {
                AtriaDebugLog("ATRIADBG strap_step_ledger status=saved reason=%@ raw_steps=%d",
                              reason,
                              record.segmentRawSteps)
            }
        case let .failure(error):
            strapStepLedgerConsecutiveSaveFailures = min(
                strapStepLedgerConsecutiveSaveFailures + 1,
                30
            )
            let transient = Self.strapStepLedgerFailureIsTransient(error)
            failureRetryDelay = transient
                ? Self.strapStepLedgerRetryDelay(
                    consecutiveFailureCount: strapStepLedgerConsecutiveSaveFailures
                )
                : Self.strapStepLedgerStructuralFailureCooldown
            let description = error.localizedDescription
            let now = Date()
            if Self.shouldLogStrapStepLedgerFailure(
                previousDescription: strapStepLedgerLastFailureDescription,
                lastLoggedAt: strapStepLedgerLastFailureLogAt,
                description: description,
                now: now
            ) {
                strapStepLedgerLastFailureDescription = description
                strapStepLedgerLastFailureLogAt = now
                AtriaDebugLog(
                    "ATRIADBG strap_step_ledger status=save_failed reason=%@ error=%@ transient=%d retry_in_s=%.1f failures=%d",
                    reason,
                    description,
                    transient ? 1 : 0,
                    failureRetryDelay ?? 0,
                    strapStepLedgerConsecutiveSaveFailures
                )
            }
        }
        let pending = strapStepLedgerSavePending
        strapStepLedgerSavePending = false
        if let failureRetryDelay {
            // Keep only the newest in-memory snapshot. A failed write never
            // advances the durable watermark, while one anchored retry task
            // prevents incoming 10 Hz frames from producing 10 Hz disk I/O.
            strapStepLedgerSavePending = pending
            scheduleStrapStepLedgerCheckpoint(now: Date(),
                                              minimumDelay: failureRetryDelay)
            return
        }
        if pending {
            persistStrapStepLedgerIfNeeded(reason: "coalesced_pending_\(reason)", force: true)
        } else if Self.strapStepLedgerHasUnsavedResearchSteps(
            currentRawSteps: strapStepResearchPeakCount,
            persistedRawSteps: lastStrapStepLedgerSavedRawSteps,
            currentGyroSteps: currentGyroCadenceResearchSessionSteps(),
            persistedGyroSteps: lastStrapStepLedgerSavedGyroCadenceResearchSteps
        ) {
            scheduleStrapStepLedgerCheckpoint(now: Date())
        }
    }

    nonisolated static func strapStepLedgerHasUnsavedRawSteps(
        currentRawSteps: Int,
        persistedRawSteps: Int
    ) -> Bool {
        currentRawSteps > max(0, persistedRawSteps)
    }

    nonisolated static func strapStepLedgerHasUnsavedResearchSteps(
        currentRawSteps: Int,
        persistedRawSteps: Int,
        currentGyroSteps: Int,
        persistedGyroSteps: Int
    ) -> Bool {
        strapStepLedgerHasUnsavedRawSteps(currentRawSteps: currentRawSteps,
                                         persistedRawSteps: persistedRawSteps)
            || currentGyroSteps > max(0, persistedGyroSteps)
    }

    nonisolated static func strapStepLedgerCheckpointDelay(
        lastSavedAt: Date?,
        now: Date,
        minimumInterval: TimeInterval = strapStepCheckpointMaximumAge
    ) -> TimeInterval {
        guard let lastSavedAt else { return max(0.05, minimumInterval) }
        return max(0.05, minimumInterval - max(0, now.timeIntervalSince(lastSavedAt)))
    }

    nonisolated static let strapStepLedgerStructuralFailureCooldown: TimeInterval = 30

    nonisolated static func strapStepLedgerRetryDelay(
        consecutiveFailureCount: Int,
        baseDelay: TimeInterval = 1,
        maximumDelay: TimeInterval = 30
    ) -> TimeInterval {
        guard consecutiveFailureCount > 0 else { return max(0.05, baseDelay) }
        let exponent = min(consecutiveFailureCount - 1, 10)
        return min(maximumDelay, max(0.05, baseDelay) * pow(2, Double(exponent)))
    }

    nonisolated static func strapStepLedgerFailureIsTransient(_ error: Error) -> Bool {
        guard let saveError = error as? AtriaStrapStepLedger.SaveError else { return true }
        return saveError == .unavailableStorage
    }

    nonisolated static func shouldLogStrapStepLedgerFailure(
        previousDescription: String?,
        lastLoggedAt: Date?,
        description: String,
        now: Date,
        minimumInterval: TimeInterval = 30
    ) -> Bool {
        guard previousDescription == description, let lastLoggedAt else { return true }
        return now.timeIntervalSince(lastLoggedAt) >= max(1, minimumInterval)
    }

    /// The existing session transaction has already proved the exact old raw
    /// prefix durable before this is called. Rotate the tiny ledger while R10
    /// post-marker frames remain fenced, preserving cumulative continuity.
    private func rotateStrapStepLedgerAfterExactBoundary(
        from segmentID: UUID,
        finalizedSnapshot: AtriaR10MotionPipeline.Snapshot?,
        finalizedGyroCadenceResearchSteps: Int?,
        to nextSegmentID: UUID,
        nextSegmentStartedAt: Date,
        reason: String
    ) {
        strapStepLedgerCheckpointTask?.cancel()
        strapStepLedgerCheckpointTask = nil
        let now = Date()
        // `Snapshot.steps` remains the diagnostic accelerometer coordinate.
        // The primary ledger field now tracks the same validated gyro total
        // exposed by Home; raw peak steps stay in their own field for audits.
        let finalizedSteps = finalizedGyroCadenceResearchSteps ?? 0
        let finalizedRawSteps = finalizedSnapshot?.rawSteps ?? 0
        let deviceTimestamp = finalizedSnapshot.flatMap {
            $0.deviceTimestamp > 0 ? $0.deviceTimestamp : nil
        } ?? strapStepResearchDeviceTimestamp
        do {
            if AtriaStrapStepLedger.load(now: now) == nil {
                _ = try AtriaStrapStepLedger.checkpoint(
                    segmentID: segmentID,
                    segmentStartedAt: sessionStart,
                    segmentSteps: finalizedSteps,
                    segmentRawSteps: finalizedRawSteps,
                    deviceTimestamp: deviceTimestamp,
                    state: finalizedSnapshot?.state ?? strapStepResearchState,
                    gyroCadenceResearchSteps: finalizedGyroCadenceResearchSteps,
                    now: now
                )
            }
            let rotated = try AtriaStrapStepLedger.rotate(
                from: segmentID,
                finalizedSteps: finalizedSteps,
                finalizedRawSteps: finalizedRawSteps,
                deviceTimestamp: deviceTimestamp,
                finalizedGyroCadenceResearchSteps: finalizedGyroCadenceResearchSteps,
                to: nextSegmentID,
                nextSegmentStartedAt: nextSegmentStartedAt,
                now: now
            )
            lastStrapStepLedgerSavedRawSteps = rotated.segmentRawSteps
            lastStrapStepLedgerSavedGyroCadenceResearchSteps =
                rotated.segmentGyroCadenceResearchSteps ?? 0
            strapStepLedgerGyroCumulativePrefix = max(
                0,
                (rotated.cumulativeGyroCadenceResearchSteps ?? 0)
                    - (rotated.segmentGyroCadenceResearchSteps ?? 0)
            )
            lastStrapStepLedgerSaveAt = rotated.updatedAt
            strapStepLedgerSavePending = false
            AtriaDebugLog("ATRIADBG strap_step_ledger status=rotated reason=%@ cumulative_steps=%d",
                          reason,
                          rotated.cumulativeSteps)
        } catch {
            AtriaDebugLog("ATRIADBG strap_step_ledger status=rotate_failed reason=%@ error=%@",
                          reason,
                          error.localizedDescription)
        }
    }

    /// A zero-handoff boundary carries the complete detector prefix into the
    /// new generation. Transfer ledger ownership to that new segment instead
    /// of leaving a mismatched old UUID that would reject every later write.
    private func resegmentStrapStepLedgerAfterUnhandedBoundary(
        from segmentID: UUID,
        observedSnapshot: AtriaR10MotionPipeline.Snapshot?,
        carriedSnapshot: AtriaR10MotionPipeline.Snapshot?,
        observedGyroCadenceResearchSteps: Int?,
        carriedGyroCadenceResearchSteps: Int?,
        to nextSegmentID: UUID,
        nextSegmentStartedAt: Date,
        reason: String
    ) {
        strapStepLedgerCheckpointTask?.cancel()
        strapStepLedgerCheckpointTask = nil
        let now = Date()
        let observedSteps = observedGyroCadenceResearchSteps ?? 0
        let observedRawSteps = observedSnapshot?.rawSteps ?? 0
        let carriedSteps = carriedGyroCadenceResearchSteps ?? 0
        let carriedRawSteps = carriedSnapshot?.rawSteps ?? 0
        let deviceTimestamp = observedSnapshot.flatMap {
            $0.deviceTimestamp > 0 ? $0.deviceTimestamp : nil
        } ?? strapStepResearchDeviceTimestamp
        do {
            if AtriaStrapStepLedger.load(now: now) == nil {
                _ = try AtriaStrapStepLedger.checkpoint(
                    segmentID: segmentID,
                    segmentStartedAt: sessionStart,
                    segmentSteps: observedSteps,
                    segmentRawSteps: observedRawSteps,
                    deviceTimestamp: deviceTimestamp,
                    state: observedSnapshot?.state ?? strapStepResearchState,
                    gyroCadenceResearchSteps: observedGyroCadenceResearchSteps,
                    now: now
                )
            }
            let resegmented = try AtriaStrapStepLedger.resegmentPreservingUnhandedPrefix(
                from: segmentID,
                observedSteps: observedSteps,
                observedRawSteps: observedRawSteps,
                deviceTimestamp: deviceTimestamp,
                observedGyroCadenceResearchSteps: observedGyroCadenceResearchSteps,
                to: nextSegmentID,
                carriedSteps: carriedSteps,
                carriedRawSteps: carriedRawSteps,
                carriedGyroCadenceResearchSteps: carriedGyroCadenceResearchSteps,
                nextSegmentStartedAt: nextSegmentStartedAt,
                now: now
            )
            lastStrapStepLedgerSavedRawSteps = resegmented.segmentRawSteps
            lastStrapStepLedgerSavedGyroCadenceResearchSteps =
                resegmented.segmentGyroCadenceResearchSteps ?? 0
            strapStepLedgerGyroCumulativePrefix = max(
                0,
                (resegmented.cumulativeGyroCadenceResearchSteps ?? 0)
                    - (resegmented.segmentGyroCadenceResearchSteps ?? 0)
            )
            lastStrapStepLedgerSaveAt = resegmented.updatedAt
            strapStepLedgerSavePending = false
            AtriaDebugLog(
                "ATRIADBG strap_step_ledger status=resegmented reason=%@ carried_raw_steps=%d cumulative_steps=%d",
                reason,
                resegmented.segmentRawSteps,
                resegmented.cumulativeSteps
            )
        } catch {
            AtriaDebugLog("ATRIADBG strap_step_ledger status=resegment_failed reason=%@ error=%@",
                          reason,
                          error.localizedDescription)
        }
    }

    private func applyR10MotionSnapshot(
        _ snapshot: AtriaR10MotionPipeline.Snapshot,
        schedulesCheckpoint: Bool = true
    ) {
        guard Self.shouldApplyR10MotionSnapshot(
            snapshotGeneration: snapshot.generation,
            activeGeneration: r10MotionPipelineGeneration
        ) else {
            AtriaDebugLog(
                "ATRIADBG r10_snapshot status=rejected reason=stale_generation snapshot=%llu active=%llu",
                snapshot.generation,
                r10MotionPipelineGeneration
            )
            return
        }
        let now = Date()
        let previousSteps = strapStepResearchCount
        let previousRawSteps = strapStepResearchPeakCount
        rollStrapStepResearchDayIfNeeded(now: now, currentSessionCount: strapStepResearchCount)
        decodedIMUSampleCount = max(decodedIMUSampleCount, snapshot.samples)
        imuInferredScale = 4_096
        imuInferredEndian = AtriaIMUDecoder.Endian.little.rawValue
        imuStillnessRatioSum = snapshot.stillnessRatio * Double(max(1, snapshot.frames))
        imuMovementIntensitySum = snapshot.movementIntensity * Double(max(1, snapshot.frames))
        imuActivityBurstCount = snapshot.activityBursts
        imuGravityValidatedFrameCount = snapshot.gravityValidatedFrames
        imuSampleRateHzSum = Double(AtriaStrapPedometer.sampleRateHz)
        imuSampleRateHzCount = 1
        // The snapshot was already evaluated on the R10 serial queue. Do not
        // synchronously rescan its entire open motion span on MainActor here:
        // that can delay live application long enough to make an otherwise
        // continuous workout boundary appear stale.
        let gyroCadenceSteps = snapshot.gyroCadenceResearchSteps
        let reconciledTotals = Self.monotonicStrapStepTotals(
            currentSteps: strapStepResearchCount,
            currentRawSteps: strapStepResearchPeakCount,
            incomingSteps: gyroCadenceSteps,
            incomingRawSteps: snapshot.rawSteps
        )
        // R10 work runs on its own serial queue and publishes back to the main
        // actor. A restore, reconnect, or explicit pipeline reset can therefore
        // leave a durable session prefix here while a delayed/connection-local
        // snapshot contains a smaller count. Never replace that prefix with the
        // lower snapshot. The pipeline remains responsible for adding future
        // motion to its seeded/committed prefix; this guard only prevents stale
        // state from moving daily and workout totals backwards.
        strapStepResearchCount = reconciledTotals.steps
        strapStepResearchPeakCount = reconciledTotals.rawSteps
        if snapshot.deviceTimestamp > 0 {
            strapStepResearchDeviceTimestamp = Self.newestR10DeviceTimestamp(
                existing: strapStepResearchDeviceTimestamp,
                incoming: snapshot.deviceTimestamp
            )
        }
        // Preserve the pipeline's provenance. The gyro detector remains a
        // preliminary strap-only source until it passes the controlled
        // physical walking acceptance run; do not advertise a different
        // state internally than the UI publishes.
        strapStepResearchState = snapshot.state
        if let capturedAt = snapshot.receivedAt,
           liveStrapStepCountCapturedAt.map({ capturedAt >= $0 }) ?? true {
            assignIfChanged(\.liveStrapStepCountCapturedAt, capturedAt)
        }
        publishLiveStrapStepResearchIfNeeded(now: now)
        assignIfChanged(\.liveStrapStepResearchState, strapStepResearchState)
        imuValidationState = "r10_fixed_layout_calibrating"
        if schedulesCheckpoint {
            scheduleStrapStepLedgerCheckpoint(now: now)
        }
        if schedulesCheckpoint,
           reconciledTotals.steps != previousSteps
                || reconciledTotals.rawSteps != previousRawSteps {
            let checkpointDue = Self.shouldCheckpointStrapSteps(
                currentSteps: reconciledTotals.steps,
                persistedSteps: lastActiveJournalSavedResearchAggregates.strapSteps,
                lastCheckpointAt: lastActiveJournalSaveAt,
                now: now
            )
            persistActiveSessionJournalIfNeeded(reason: "r10_step_update",
                                                force: checkpointDue)
            scheduleTrailingStrapStepCheckpoint(now: now,
                                                forceJustRequested: checkpointDue)
        }
    }

    /// Schedules the time half of the time+count checkpoint contract. The task
    /// is anchored to the earliest unsaved step and never postponed by later
    /// steps, so a short walk that ends below the count limit is still durable.
    /// If an incremental save is already in flight, retrying waits without doing
    /// I/O until that save settles.
    private func scheduleTrailingStrapStepCheckpoint(
        now: Date,
        forceJustRequested: Bool,
        retryAfterInFlightSave: Bool = false
    ) {
        guard strapStepResearchCount > lastActiveJournalSavedResearchAggregates.strapSteps else {
            activeJournalStepCheckpointTask?.cancel()
            activeJournalStepCheckpointTask = nil
            return
        }
        guard activeJournalStepCheckpointTask == nil else { return }

        let delay: TimeInterval
        if retryAfterInFlightSave {
            delay = 0.5
        } else if forceJustRequested {
            // The write started with the latest count. Recheck one complete
            // policy interval later only in case more steps arrived mid-save.
            delay = Self.strapStepCheckpointMaximumAge
        } else if let lastActiveJournalSaveAt {
            delay = max(0.05, Self.strapStepCheckpointMaximumAge
                - max(0, now.timeIntervalSince(lastActiveJournalSaveAt)))
        } else {
            delay = 0.05
        }

        activeJournalStepCheckpointTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(delay))
            guard let self, !Task.isCancelled else { return }
            self.activeJournalStepCheckpointTask = nil
            let firedAt = Date()
            guard self.strapStepResearchCount
                    > self.lastActiveJournalSavedResearchAggregates.strapSteps else { return }
            if self.activeJournalSaveInFlight {
                self.scheduleTrailingStrapStepCheckpoint(
                    now: firedAt,
                    forceJustRequested: false,
                    retryAfterInFlightSave: true
                )
                return
            }
            let due = Self.shouldCheckpointStrapSteps(
                currentSteps: self.strapStepResearchCount,
                persistedSteps: self.lastActiveJournalSavedResearchAggregates.strapSteps,
                lastCheckpointAt: self.lastActiveJournalSaveAt,
                now: firedAt
            )
            if due {
                self.persistActiveSessionJournalIfNeeded(
                    reason: "r10_step_trailing_checkpoint",
                    force: true
                )
            }
            self.scheduleTrailingStrapStepCheckpoint(now: firedAt,
                                                     forceJustRequested: due)
        }
    }

    /// Returns true only for newly confirmed cumulative steps. A count limit
    /// bounds loss during brisk movement, while a time limit captures a small
    /// trailing remainder during slow movement. Future/corrupt checkpoint
    /// clocks fail safe by requesting one write; neither branch creates or
    /// extrapolates a step.
    nonisolated static func shouldCheckpointStrapSteps(
        currentSteps: Int,
        persistedSteps: Int,
        lastCheckpointAt: Date?,
        now: Date,
        maximumUnpersistedSteps: Int = strapStepCheckpointMaximumUnpersistedSteps,
        maximumCheckpointAge: TimeInterval = strapStepCheckpointMaximumAge
    ) -> Bool {
        let delta = currentSteps - max(0, persistedSteps)
        guard delta > 0 else { return false }
        if delta >= max(1, maximumUnpersistedSteps) { return true }
        guard let lastCheckpointAt else { return true }
        let age = now.timeIntervalSince(lastCheckpointAt)
        return age < 0 || age >= max(1, maximumCheckpointAge)
    }

    struct StrapStepTotals: Equatable {
        let steps: Int
        let rawSteps: Int
    }

    nonisolated static func shouldApplyR10MotionSnapshot(
        snapshotGeneration: UInt64,
        activeGeneration: UInt64
    ) -> Bool {
        snapshotGeneration == activeGeneration
    }

    /// Reconciles an asynchronously delivered motion snapshot with the
    /// already-restored/session-persisted prefix. Counts may intentionally reset
    /// only when `resetLiveSessionState` starts a new persisted segment; within
    /// one live session they are cumulative and must be monotonic.
    nonisolated static func monotonicStrapStepTotals(currentSteps: Int,
                                                     currentRawSteps: Int,
                                                     incomingSteps: Int,
                                                     incomingRawSteps: Int) -> StrapStepTotals {
        StrapStepTotals(steps: max(0, max(currentSteps, incomingSteps)),
                        rawSteps: max(0, max(currentRawSteps, incomingRawSteps)))
    }

    /// Snapshot callbacks can reach the MainActor out of order even though the
    /// detector itself is serial. Keep the persisted replay watermark moving
    /// only forward, including across the UInt32 seconds-clock wrap.
    nonisolated static func newestR10DeviceTimestamp(existing: UInt32?,
                                                     incoming: UInt32?) -> UInt32? {
        guard let incoming, incoming > 0 else { return existing }
        guard let existing, existing > 0 else { return incoming }
        let delta = incoming &- existing
        return delta > 0 && delta < (UInt32.max / 2 + 1) ? incoming : existing
    }

    private func imuFeatureSummary() -> (stillnessRatio: Double?, movementIntensity: Double?, sampleRateHz: Double?) {
        guard protocolIMUFrameCount > 0, decodedIMUSampleCount > 0 else { return (nil, nil, nil) }
        let frames = Double(max(r10MotionFrameCount > 0 ? r10MotionFrameCount : protocolIMUFrameCount, 1))
        let sampleRate = imuSampleRateHzCount > 0 ? imuSampleRateHzSum / Double(imuSampleRateHzCount) : nil
        return (imuStillnessRatioSum / frames, imuMovementIntensitySum / frames, sampleRate)
    }

    static func shouldPublishLiveStrapStepResearch(currentCount: Int,
                                                   publishedCount: Int,
                                                   force: Bool = false) -> Bool {
        if force { return true }
        return currentCount != publishedCount
    }

    private func publishLiveStrapStepResearchIfNeeded(now: Date = Date(),
                                                      force: Bool = false) {
        rollStrapStepResearchDayIfNeeded(now: now, currentSessionCount: strapStepResearchCount)
        guard Self.shouldPublishLiveStrapStepResearch(currentCount: strapStepResearchCount,
                                                      publishedCount: liveStrapStepResearchCount,
                                                      force: force) else {
            return
        }
        assignIfChanged(\.liveStrapStepResearchCount, strapStepResearchCount)
        assignIfChanged(\.liveStrapStepResearchTodayCount,
                        Self.dayScopedStrapStepCount(sessionCount: strapStepResearchCount,
                                                     dayBaseline: strapStepResearchDayBaseline))
    }

    nonisolated static func dayScopedStrapStepCount(sessionCount: Int, dayBaseline: Int) -> Int {
        max(0, sessionCount - min(max(0, dayBaseline), max(0, sessionCount)))
    }

    private func rollStrapStepResearchDayIfNeeded(now: Date,
                                                  currentSessionCount: Int,
                                                  calendar: Calendar = .current) {
        let day = calendar.startOfDay(for: now)
        guard !calendar.isDate(day, inSameDayAs: strapStepResearchDay) else { return }
        strapStepResearchDay = day
        strapStepResearchDayBaseline = max(0, currentSessionCount)
        assignIfChanged(\.liveStrapStepResearchTodayCount, 0)
    }

    private func currentGyroCadenceResearchSessionSteps() -> Int {
        r10MotionPipeline.gyroCadenceResearchStepsSynchronously()
    }

    /// Freshness-qualified cumulative coordinate available only to a workout
    /// that explicitly froze the ambulatory gyro source at Start.
    func ambulatoryWorkoutGyroStepCoordinate(now: Date) -> AtriaWorkoutStepCoordinate? {
        let segment = currentGyroCadenceResearchSessionSteps()
        return AtriaWorkoutStepCoordinate.makeCumulative(
            savedPrefixHydrated: !strapStepLedgerRestoreInFlight,
            cumulativeCount: min(
                AtriaStrapStepLedger.maximumCount,
                strapStepLedgerGyroCumulativePrefix + segment
            ),
            // Use the detector-applied clock, not raw transport receipt. The
            // latter can advance before the serial cadence evaluator consumes
            // the frame and would let a tap borrow post-action motion.
            hasEvidence: liveStrapStepCountCapturedAt != nil,
            capturedAt: liveStrapStepCountCapturedAt,
            isConnected: status == .connected,
            reconnectPending: pendingKnownReconnectStartedAt != nil,
            rangeLossBackfillPending: rangeLossBackfillPending,
            hasContinuousValidatedMotion: hasContinuousValidatedWorkoutMotion(now: now),
            now: now
        )
    }

    /// A step detector timestamp alone is deliberately insufficient for a
    /// workout step boundary.  The physical strap can emit a lone passive R10
    /// frame while the dense stream is unavailable.  Require the same current
    /// connection density proof used by the motion lease before exposing a
    /// strap-only count as ready or saving it on workout completion.
    func hasContinuousValidatedWorkoutMotion(now: Date = Date()) -> Bool {
        guard status == .connected,
              peripheral?.state == .connected,
              workoutMotionOwnerStartedAt != nil,
              !rangeLossBackfillPending,
              pendingKnownReconnectStartedAt == nil else {
            return false
        }
        return workoutMotionDenseFrameCount(now: now)
            >= Self.workoutMotionDenseFrameThreshold
    }

    /// Pure compatibility helper retained for calibration tests and older
    /// research exports. Runtime ownership now lives on the R10 queue.
    nonisolated static func gyroCadenceResearchSessionSteps(
        restoredPrefixSteps: Int,
        shadowTotalSteps: Double,
        sessionBaselineSteps: Double
    ) -> Int {
        let delta = max(0, shadowTotalSteps - sessionBaselineSteps)
        let combined = Double(max(0, restoredPrefixSteps)) + delta
        return min(Int(combined.rounded()), 10_000_000)
    }

    private static func standardDeviation(_ values: [Double]) -> Double {
        guard values.count >= 2 else { return 0 }
        let mean = values.reduce(0, +) / Double(values.count)
        let variance = values.reduce(0) { $0 + pow($1 - mean, 2) } / Double(values.count)
        return sqrt(variance)
    }

    private func resetIMUFeatureStats(
        resetResearchAggregates: Bool = true,
        carriedMotionSnapshot: AtriaR10MotionPipeline.Snapshot? = nil
    ) {
        decodedIMUSampleCount = 0
        imuGravityValidatedFrameCount = 0
        imuStillnessRatioSum = 0
        imuMovementIntensitySum = 0
        imuActivityBurstCount = 0
        imuValidationState = "unavailable"
        imuSampleRateHzSum = 0
        imuSampleRateHzCount = 0
        imuLastFrameAt = nil
        imuInferredScale = nil
        imuInferredEndian = nil
        r10MotionFrameCount = 0
        lastR10MotionFrameAt = nil
        assignIfChanged(\.liveStrapMotionCapturedAt, nil)
        assignIfChanged(\.liveStrapStepCountCapturedAt, nil)
        strapStepResearchCount = 0
        strapStepResearchDay = Calendar.current.startOfDay(for: Date())
        strapStepResearchDayBaseline = 0
        assignIfChanged(\.liveStrapStepResearchTodayCount, 0)
        strapStepResearchPeakCount = 0
        strapStepResearchDeviceTimestamp = nil
        strapStepResearchState = "research_unvalidated"
        if let carriedMotionSnapshot {
            strapStepResearchCount = carriedMotionSnapshot.steps
            strapStepResearchPeakCount = carriedMotionSnapshot.rawSteps
            strapStepResearchDeviceTimestamp = carriedMotionSnapshot.deviceTimestamp > 0
                ? carriedMotionSnapshot.deviceTimestamp : nil
            strapStepResearchState = carriedMotionSnapshot.state
            // This is accounting carry, not a frame processed in the new
            // segment. Freshness stays empty until a new-generation callback.
        }
        publishLiveStrapStepResearchIfNeeded(force: true)
        assignIfChanged(\.liveStrapStepResearchState, strapStepResearchState)
        if resetResearchAggregates {
            researchProbeFrameCount = 0
            researchProbeOxygenCandidateFrames = 0
            researchProbeOxygenOffset64ValueSum = 0
            researchProbeOxygenOffset64ValueCount = 0
            researchProbeOxygenOffset66ValueSum = 0
            researchProbeOxygenOffset66ValueCount = 0
            researchProbeTemperatureCandidateFrames = 0
            researchProbeTemperatureCandidateValueSum = 0
            researchProbeTemperatureCandidateValueCount = 0
        }
    }

    private func resetSessionSampleDiagnostics() {
        sessionRawHRNotifications = 0
        sessionAcceptedHRSamples = 0
        sessionZeroHRSamples = 0
        sessionHeldArtifacts = 0
        sessionDroppedArtifacts = 0
        sessionRawHRGaps = 0
        sessionAcceptedHRGaps = 0
        sessionMaxRawHRGap = 0
        sessionMaxAcceptedHRGap = 0
        lastRawHRNotificationAt = nil
    }

    private func applyCoexistenceRiskForDebugLaunch(arguments: [String]) {
#if DEBUG
        guard let riskIndex = arguments.firstIndex(of: "--atria-force-coexistence-risk"),
              arguments.indices.contains(arguments.index(after: riskIndex)) else { return }
        let value = arguments[arguments.index(after: riskIndex)]
        guard let risk = OfficialAppCoexistenceRisk(rawValue: value) else {
            AtriaDebugLog("ATRIADBG official_app_coexistence_debug status=invalid value=%@", value)
            return
        }
        persistOfficialAppCoexistenceRisk(risk, reason: "debug_launch_arg")
        AtriaDebugLog("ATRIADBG official_app_coexistence_debug status=forced value=%@", value)
#endif
    }

    private func applyOfflineSyncForDebugLaunch(arguments: [String]) {
#if DEBUG
        guard arguments.contains("--atria-force-offline-sync") else { return }
        let reason = value(after: "--atria-force-offline-sync-reason",
                           in: arguments) ?? "debug_launch_arg"
        let livePersistenceReady = peripheral?.state == .connected
            && status == .connected
            && connectedAt.map { connectedAt in
                lastAcceptedHRAt.map { $0 >= connectedAt } ?? false
            } == true
        guard livePersistenceReady else {
            retainPendingOfflineHistoricalSyncRequest(
                reason: reason,
                force: true,
                explicitRequest: true
            )
            AtriaDebugLog("ATRIADBG offline_sync_debug status=waiting_live_persistence reason=%@ action=retain_explicit_force_until_current_epoch_hr",
                          reason)
            return
        }
        let started = requestOfflineHistoricalSyncIfNeeded(
            reason: reason,
            force: true,
            explicitResearchRequest: true
        )
        AtriaDebugLog("ATRIADBG offline_sync_debug status=%@ reason=%@",
                      started ? "started" : "not_started",
                      reason)
#endif
    }

    /// Installs standard 180D/2A37 discovery inside the CoreBluetooth delegate
    /// execution slice. New connections and restored-connected peripherals use
    /// one enable-only path, outside unrelated MainActor reconciliation.
    @discardableResult
    nonisolated private func beginSynchronousHeartRateDiscoveryFastLane(
        peripheral: CBPeripheral,
        callbackEpoch: UInt64,
        historyRecoveryActive: Bool,
        diagnosticActive: Bool,
        reason: String
    ) -> Bool {
        let continuousCaptureWanted = heartRateCaptureIntent.snapshot()
        guard Self.shouldSynchronouslyDiscoverHeartRateAfterConnect(
            continuousCaptureWanted: continuousCaptureWanted,
            peripheralConnected: peripheral.state == .connected,
            historyRecoveryActive: historyRecoveryActive,
            diagnosticActive: diagnosticActive
        ), bleCallbackEpochFence.accepts(
            callbackEpoch: callbackEpoch,
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else { return false }

        peripheral.delegate = self
        let cachedService = peripheral.services?.first(where: {
            $0.uuid == Self.UUIDs.heartRateService
        })
        let cachedMeasurement = cachedService?.characteristics?.first(where: {
            $0.uuid == Self.UUIDs.heartRateMeasure
        })
        let defaults = UserDefaults.standard
        defaults.set("\(reason)_requested", forKey: BackgroundHRDiscoveryDefaults.stage)
        defaults.set(Date().timeIntervalSince1970, forKey: BackgroundHRDiscoveryDefaults.at)
        defaults.set(callbackEpoch, forKey: BackgroundHRDiscoveryDefaults.epoch)
        defaults.set(peripheral.identifier.uuidString,
                     forKey: BackgroundHRDiscoveryDefaults.peripheralID)
        defaults.set(cachedService != nil, forKey: BackgroundHRDiscoveryDefaults.cachedService)
        defaults.set(cachedMeasurement != nil,
                     forKey: BackgroundHRDiscoveryDefaults.cachedCharacteristic)
        if let cachedMeasurement,
           continuousCaptureWanted,
           !historyRecoveryActive,
           (cachedMeasurement.properties.contains(.notify)
               || cachedMeasurement.properties.contains(.indicate)),
           (Self.shouldSynchronouslyEnableDiscoveredHeartRateNotification(
               continuousCaptureWanted: continuousCaptureWanted,
               supportsNotifications: cachedMeasurement.properties.contains(.notify)
                   || cachedMeasurement.properties.contains(.indicate),
               isNotifying: cachedMeasurement.isNotifying
           ) || reason.contains("did_connect")) {
            peripheral.setNotifyValue(true, for: cachedMeasurement)
            defaults.set("\(reason)_cached_2a37_notify_requested",
                         forKey: BackgroundHRDiscoveryDefaults.stage)
            defaults.set(false, forKey: BackgroundHRDiscoveryDefaults.notifying)
        }
        if let cachedService {
            peripheral.discoverCharacteristics(
                [Self.UUIDs.heartRateMeasure],
                for: cachedService
            )
        }
        peripheral.discoverServices([Self.UUIDs.heartRateService])
        AtriaDebugLog("ATRIADBG ble_discovery status=requested_sync service=180D reason=%@ epoch=%llu",
                      reason,
                      callbackEpoch)
        return true
    }

    deinit {
        terminalConsumerDependencyRetryTask?.cancel()
        terminalCatalogMaterializationRetryTask?.cancel()
        if let motionCompactStoreObserver {
            NotificationCenter.default.removeObserver(
                motionCompactStoreObserver
            )
        }
        if let phoneChargeStateObserver {
            NotificationCenter.default.removeObserver(
                phoneChargeStateObserver
            )
        }
    }
}

// MARK: - CBCentralManagerDelegate
extension AtriaBLEManager: CBCentralManagerDelegate {
    nonisolated func centralManagerDidUpdateState(_ central: CBCentralManager) {
        guard let centralToken = centralEventFence.capture(central) else {
            AtriaDebugLog(
                "ATRIADBG ble_central status=callback_rejected reason=retired_manager callback=state state=%d",
                central.state.rawValue
            )
            return
        }
        // Freeze the callback-entry state. A later radio transition may occur
        // before MainActor runs; switching on a live re-read lets an old
        // powered-off callback masquerade as the newer state (or vice versa).
        let observedState = central.state
        guard centralEventFence.accepts(centralToken, central: central) else {
            return
        }
        let pendingLegacyPowerOnMarkers =
            bleCallbackEpochFence.powerOnMarkerSnapshot()
        let pendingCentralPowerOnMarkers =
            centralEventFence.powerOnMarkerSnapshot(token: centralToken)
        if pendingLegacyPowerOnMarkers.silentStreamRebuild
            || pendingCentralPowerOnMarkers.silentStreamRebuild {
            recordReconnectLeaseStage(
                "central_rebuild_state_\(observedState.rawValue)",
                detail: "callback_received"
            )
        }
        // CORE FIX (launch-start timing): issue the standing connect to the
        // saved strap directly on centralQueue, synchronously, BEFORE hopping
        // to @MainActor. At cold start the main actor can be saturated by the
        // launch render + deferred-load work for seconds; central.connect()
        // and retrievePeripherals(withIdentifiers:) are CoreBluetooth calls
        // safe to make from the manager's own delegate queue and must not
        // wait behind that UI work. The later @MainActor hop only publishes
        // state (peripheral, status, pendingKnownReconnectStartedAt) — it
        // never gates the radio's pursuit of the strap. This keeps the single
        // existing launch path (retrieve saved identifier + central.connect,
        // no scan) — no new reconnect variant is introduced.
        var earlyPendingConnect: CBPeripheral?
        if observedState != .poweredOn {
            bleCallbackEpochFence.invalidate()
        }
        if observedState == .poweredOn {
            guard centralEventFence.accepts(
                centralToken,
                central: central
            ) else { return }
            let legacyPowerOnMarkers =
                bleCallbackEpochFence.consumePowerOnMarkers()
            let centralPowerOnMarkers =
                centralEventFence.consumePowerOnMarkers(token: centralToken)
            let defaults = UserDefaults.standard
            // Connection-diagnostics logging (2026-07-06): this precheck used
            // to log ONLY the success branch, so the two most common real-world
            // causes of "auto-connect not working" -- no saved strap identifier
            // yet, and a saved identifier iOS can no longer retrieve (unpaired /
            // out of range at boot) -- left no trace in the ATRIADBG connection
            // timeline. Log each branch explicitly (zero runtime cost). The
            // connect call and its success line are byte-for-byte unchanged.
            if let uuidString = defaults.string(forKey: LinkDefaults.savedPeripheralUUID),
               let uuid = UUID(uuidString: uuidString) {
                if let saved = central.retrievePeripherals(withIdentifiers: [uuid]).first {
                    if Self.shouldIssuePoweredOnStandingConnect(
                        peripheralState: saved.state
                    ) {
                        issueSingleFlightConnect(
                            saved,
                            central: central,
                            reason: "powered_on_precheck"
                        )
                        earlyPendingConnect = saved
                        AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=powered_on_precheck action=pending_connect_early")
                    } else {
                        if saved.state == .connecting
                            || saved.state == .disconnecting {
                            connectedPeripheralRetainer
                                .adoptRestoredConnectTransition(saved)
                        }
                        AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=powered_on_precheck action=keep_existing_state saved_uuid=1 peripheral_state=%d",
                                      saved.state.rawValue)
                    }
                } else {
                    AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=powered_on_precheck action=retrieve_empty saved_uuid=1")
                    // ATRIADBG is unreachable on a locked phone, so a strap
                    // that iOS can no longer retrieve left no durable trace —
                    // which is why the 2026-07-25 gym dormancy took a whole
                    // session to attribute. The trail is the only forensics
                    // that survives; this is a breadcrumb write, no behaviour.
                    recordReconnectLeaseStage("powered_on_retrieve_empty",
                                              detail: "saved_uuid=1")
                }
            } else {
                AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=powered_on_precheck action=no_saved_uuid saved_uuid=0")
            }
            if legacyPowerOnMarkers.silentStreamRebuild
                || centralPowerOnMarkers.silentStreamRebuild {
                recordReconnectLeaseStage(
                    earlyPendingConnect == nil
                        ? "central_rebuild_standing_connect_not_issued"
                        : "central_rebuild_standing_connect_issued",
                    detail: earlyPendingConnect == nil
                        ? "saved_peripheral_not_disconnected"
                        : "pending_connect"
                )
            }
            if legacyPowerOnMarkers.standingConnect
                || centralPowerOnMarkers.standingConnect {
                // The deferred era ends here: the precheck above has already
                // retrieved and connected the saved strap if iOS knows it, so
                // the flag's job is done either way. Record which, so a repeat
                // is diagnosable rather than silent.
                recordReconnectLeaseStage(
                    "standing_connect_resumed_on_power_on",
                    detail: earlyPendingConnect == nil ? "no_pending_connect" : "pending_connect"
                )
            }
        }
        Task { @MainActor in
            guard self.centralEventFence.accepts(
                centralToken,
                central: central
            ), central.state == observedState else {
                AtriaDebugLog(
                    "ATRIADBG ble_central status=callback_followup_rejected reason=retired_or_superseded_state observed=%d current=%d",
                    observedState.rawValue,
                    central.state.rawValue
                )
                return
            }
            self.reconcileCentralUnavailableRecovery(
                state: observedState,
                callbackCentral: central,
                callbackToken: centralToken
            )
            switch observedState {
            case .poweredOn:
                assignIfChanged(\.bluetoothPermissionDenied, false)
                assignIfChanged(\.isBluetoothReady, true)
                let reason = pendingScanReason ?? "central_powered_on"
                pendingScanReason = nil
                if let peripheral, peripheral.state == .connected,
                   readOnlyHistoryCaptureRequested {
                    // `willRestoreState` owns the command-free cutover for a
                    // restored read-only launch. Never discover proprietary
                    // services on the inherited encryption/command epoch.
                    AtriaDebugLog("ATRIADBG readOnlyHistory status=restored_epoch_held reason=central_powered_on commands=0")
                } else if let peripheral, peripheral.state == .connected {
                    // Some restored links reach the central powered-on path
                    // before `willRestoreState` has delivered its MainActor
                    // work. Preserve the orphan journal before this branch can
                    // hand off to a motion-profile cutover.
                    _ = archiveOrphanHistoricalIngressIfNeeded(
                        reason: "central_powered_on_orphan_ingress_replay",
                        force: false,
                        explicitRequest: false,
                        retainHistoricalRequest: false
                    )
                    if !beginMotionHandshakeLaunchConnectionCutoverIfNeeded(
                        peripheral: peripheral,
                        central: central,
                        reason: "powered_on_\(reason)"
                    ) {
                        peripheral.discoverServices(discoveryServicesForCurrentMode)
                    }
                } else if let earlyPendingConnect {
                    // The standing connect was already issued synchronously
                    // above; this only publishes bookkeeping/UI state for it.
                    earlyPendingConnect.delegate = self
                    self.peripheral = earlyPendingConnect
                    assignIfChanged(\.deviceName, earlyPendingConnect.name ?? deviceName)
                    recomputeConnectionStatus(reason: "event")
                    recordLinkAttempt(reason: "powered_on_\(reason)", peripheral: earlyPendingConnect)
                    markPendingKnownReconnect(reason: "powered_on_\(reason)")
                    self.startReconnectWatchdog(
                        reason: "powered_on_\(reason)_pending_connect",
                        peripheral: earlyPendingConnect
                    )
                    AtriaDebugLog("ATRIADBG ble_link status=reconnect_known reason=powered_on_%@ action=pending_connect", reason)
                } else if reconnectToSavedPeripheralIfPossible(
                    reason: "powered_on_\(reason)",
                    allowCleanOwnerLaunchCutover: true
                ) {
                    // Fallback path (e.g. saved peripheral was already connected,
                    // or became available only after the early precheck ran).
                    // Re-armed a standing pending connection to the known strap.
                    // No scan needed — iOS reconnects when it is in range.
                } else {
                    // No saved strap yet (first-time setup) — scan to find one.
                    startScan(reason: reason)
                }
                self.recomputeConnectionStatus(reason: "central_powered_on")
            case .poweredOff:
                assignIfChanged(\.bluetoothPermissionDenied, false)
                assignIfChanged(\.isBluetoothReady, false)
                interruptOfflineHistoricalSyncForTransportLoss(
                    reason: "bluetooth_powered_off"
                )
                preserveLongWearRangeLossRecovery(reason: "central_powered_off")
                self.isActivelyScanning = false
                self.recomputeConnectionStatus(reason: "central_powered_off")
            case .unauthorized:
                assignIfChanged(\.bluetoothPermissionDenied, true)
                assignIfChanged(\.isBluetoothReady, false)
                interruptOfflineHistoricalSyncForTransportLoss(
                    reason: "bluetooth_unauthorized"
                )
                preserveLongWearRangeLossRecovery(reason: "central_unauthorized")
                self.isActivelyScanning = false
                self.recomputeConnectionStatus(reason: "central_unauthorized")
            default:
                assignIfChanged(\.bluetoothPermissionDenied, false)
                assignIfChanged(\.isBluetoothReady, false)
                interruptOfflineHistoricalSyncForTransportLoss(
                    reason: "bluetooth_unavailable"
                )
                preserveLongWearRangeLossRecovery(reason: "central_unavailable")
                self.isActivelyScanning = false
                self.recomputeConnectionStatus(reason: "central_unavailable")
            }
        }
    }

    nonisolated static func canonicalRestoredPeripheralIndex(
        identifiers: [UUID],
        states: [CBPeripheralState],
        savedPeripheralIdentifier: UUID?
    ) -> Int? {
        guard identifiers.count == states.count else { return nil }
        if let savedPeripheralIdentifier {
            let matching = identifiers.indices.filter {
                identifiers[$0] == savedPeripheralIdentifier
            }
            return matching.min { lhs, rhs in
                func restorationRank(_ state: CBPeripheralState) -> Int {
                    switch state {
                    case .connected:
                        return 0
                    case .connecting:
                        return 1
                    default:
                        return 2
                    }
                }
                let lhsRank = restorationRank(states[lhs])
                let rhsRank = restorationRank(states[rhs])
                return lhsRank == rhsRank ? lhs < rhs : lhsRank < rhsRank
            }
        }
        return identifiers.count == 1 ? 0 : nil
    }

    nonisolated func centralManager(_ central: CBCentralManager, willRestoreState dict: [String: Any]) {
        guard let centralToken = centralEventFence.capture(central) else {
            AtriaDebugLog("ATRIADBG ble_central status=callback_rejected reason=retired_manager callback=will_restore")
            return
        }
        let restored = (dict[CBCentralManagerRestoredStatePeripheralsKey] as? [CBPeripheral]) ?? []
        AtriaDebugLog("ATRIADBG ble_restore peripherals=%d", restored.count)
        let savedPeripheralIdentifier = UserDefaults.standard
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        guard let canonicalIndex = Self.canonicalRestoredPeripheralIndex(
            identifiers: restored.map(\.identifier),
            states: restored.map(\.state),
            savedPeripheralIdentifier: savedPeripheralIdentifier
        ) else {
            for candidate in restored {
                candidate.delegate = nil
                connectedPeripheralRetainer.release(candidate)
                if candidate.state == .connected || candidate.state == .connecting {
                    central.cancelPeripheralConnection(candidate)
                }
            }
            AtriaDebugLog(
                "ATRIADBG ble_restore status=rejected reason=no_unambiguous_saved_peripheral peripherals=%d action=cancel_noncanonical_and_wait_for_powered_on_recovery",
                restored.count
            )
            return
        }
        let restoredPeripheral = restored[canonicalIndex]
        // A connected restoration does not emit `didConnect`, so it must claim
        // canonical object identity on the delegate queue before epoch,
        // delegate, discovery, or MainActor state is touched. Restoration may
        // replace an object-distinct pending precheck representation, but it
        // never displaces another already-connected canonical owner.
        let restoredConnectedAdmission:
            AtriaBLEConnectedPeripheralRetainer.ConnectedAdmission?
        if restoredPeripheral.state == .connected {
            restoredConnectedAdmission =
                connectedPeripheralRetainer.adoptRestoredConnected(
                    restoredPeripheral
                )
        } else if restoredPeripheral.state == .connecting
                    || restoredPeripheral.state == .disconnecting {
            connectedPeripheralRetainer
                .adoptRestoredConnectTransition(restoredPeripheral)
            restoredConnectedAdmission = nil
        } else {
            connectedPeripheralRetainer.retain(restoredPeripheral)
            restoredConnectedAdmission = nil
        }
        for (index, candidate) in restored.enumerated() where index != canonicalIndex {
            candidate.delegate = nil
            if candidate.identifier == restoredPeripheral.identifier {
                // Object-distinct twins can represent one physical BLE link.
                // Cancelling either representation can tear down both; fence
                // the non-owning object until its own terminal callback.
                connectedPeripheralRetainer.retainPassiveDuplicate(candidate)
                AtriaDebugLog(
                    "ATRIADBG ble_restore status=retained_same_uuid_duplicate peripheral=%@ canonical=%@ action=passive_no_cancel",
                    candidate.identifier.uuidString,
                    restoredPeripheral.identifier.uuidString
                )
            } else {
                connectedPeripheralRetainer.release(candidate)
                if candidate.state == .connected || candidate.state == .connecting {
                    central.cancelPeripheralConnection(candidate)
                }
                AtriaDebugLog(
                    "ATRIADBG ble_restore status=discarded_noncanonical peripheral=%@ canonical=%@",
                    candidate.identifier.uuidString,
                    restoredPeripheral.identifier.uuidString
                )
            }
        }
        if restoredConnectedAdmission == .retainPassiveDuplicate {
            AtriaDebugLog(
                "ATRIADBG ble_restore status=duplicate_connected_ignored reason=canonical_same_uuid_owner_exists action=retain_without_cancel_no_shared_state_mutation peripheral=%@",
                restoredPeripheral.identifier.uuidString
            )
            return
        }
        let restorationAt = Date()
        let persistedLongWear = UserDefaults.standard.bool(forKey: LongWearDefaults.enabled)
        let persistedWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity(
            now: restorationAt
        )
        let restorationGapBegan =
            (persistedLongWear || persistedWorkout)
            && AtriaHistoricalGapLedger.beginRestorationGapFromDurableAnchorIfNeeded(
                restorationAt: restorationAt,
                reason: persistedWorkout
                    ? "explicit_workout_process_restore_gap"
                    : "long_wear_process_restore_gap"
            )
        let restoreCallbackEpoch: UInt64
        let restoreCallbackSource: AtriaBLECallbackEpochFence.Source?
        if restoredPeripheral.state == .connected {
            restoreCallbackEpoch = bleCallbackEpochFence.activate(
                peripheralID: restoredPeripheral.identifier,
                peripheralObjectID: ObjectIdentifier(restoredPeripheral)
            )
            restoreCallbackSource = AtriaBLECallbackEpochFence.Source(
                epoch: restoreCallbackEpoch,
                peripheralID: restoredPeripheral.identifier,
                peripheralObjectID: ObjectIdentifier(restoredPeripheral)
            )
        } else {
            restoreCallbackEpoch = bleCallbackEpochFence.epoch
            restoreCallbackSource = nil
        }
        // A connected restoration does not emit `didConnect`. Assign the
        // delegate and start the same enable-only HR transaction synchronously;
        // iOS may suspend this restoration launch before MainActor is serviced.
        restoredPeripheral.delegate = self
        if restoredPeripheral.state == .connected {
            _ = beginSynchronousHeartRateDiscoveryFastLane(
                peripheral: restoredPeripheral,
                callbackEpoch: restoreCallbackEpoch,
                historyRecoveryActive: historyTransportPhaseFence.snapshot().isActive,
                diagnosticActive: motionHandshakeDiagnostic != nil,
                reason: "state_restore_connected_background_safe"
            )
        }
        Task { @MainActor in
            guard self.centralEventFence.accepts(
                centralToken,
                central: central
            ) else { return }
            if restorationGapBegan {
                self.markRangeLossBackfillRequired(
                    reason: persistedWorkout
                        ? "explicit_workout_range_loss"
                        : "long_wear_range_loss"
                )
            }
            guard restoredPeripheral.state != .connected
                    || self.acceptsBLECallback(
                        epoch: restoreCallbackEpoch,
                        peripheral: restoredPeripheral
                    ) else { return }
            // State restoration starts a canonical CoreBluetooth epoch. Any
            // in-memory history owner belongs to the suspended epoch and must
            // be unwound before the restored peripheral can publish callbacks.
            // Durable raw rows and the gap authority survive; no stale history
            // generation may claim completion through this new connection.
            if self.offlineHistoricalSyncInProgress {
                self.interruptOfflineHistoricalSyncForTransportLoss(
                    reason: "canonical_state_restore_suspension"
                )
            }
            if self.forceFreshScanOnRestore {
                AtriaDebugLog("ATRIADBG ble_restore status=reuse_restored reason=fresh_scan_deferred peripherals=%d standard_hr_only=%d",
                      restored.count,
                      self.standardHROnlyMode ? 1 : 0)
            } else if self.standardHROnlyMode {
                AtriaDebugLog("ATRIADBG ble_restore status=reuse_restored reason=standard_hr_only peripherals=%d",
                      restored.count)
            }
            restoredPeripheral.delegate = self
            self.peripheral = restoredPeripheral
            self.assignIfChanged(\.deviceName, restoredPeripheral.name ?? self.deviceName)
            switch restoredPeripheral.state {
            case .connected:
                if self.readOnlyHistoryCaptureRequested {
                    self.readOnlyHistoryRestoreCutoverPending = true
                    self.batteryConnectionRestoredSamePeripheral = false
                    self.reconnectWatchdogTask?.cancel()
                    self.recomputeConnectionStatus(reason: "read_only_history_restore_cutover")
                    self.cancelPeripheralConnection(
                        restoredPeripheral,
                        reason: "read_only_history_restored_epoch_cutover"
                    )
                    AtriaDebugLog("ATRIADBG readOnlyHistory status=restored_epoch_rejected action=cancel_then_fresh_scan commands=0 request_preserved=1")
                    return
                }
                // Run raw-only ingress replay before any restored-link motion
                // cutover can return early. CoreBluetooth commonly restores an
                // already-connected strap without ever producing didConnect.
                _ = self.archiveOrphanHistoricalIngressIfNeeded(
                    reason: "state_restore_orphan_ingress_replay",
                    force: false,
                    explicitRequest: false,
                    retainHistoricalRequest: false
                )
                self.protectedR10InitialProfilePeripheralID = nil
                self.protectedR10InitialProfileNotificationRequested = false
                self.batteryConnectionRestoredSamePeripheral =
                    Self.batteryRestorationPreservesNotificationEpoch(
                        restoredPeripheralIdentifier: restoredPeripheral.identifier,
                        savedPeripheralIdentifier: savedPeripheralIdentifier,
                        restoredPeripheralIsConnected: true
                    )
                self.clearPendingKnownReconnect(reason: "state_restore_connected")
                self.recomputeConnectionStatus(reason: "event")
                self.reconnectWatchdogTask?.cancel()
                self.beginConnectionEpoch(peripheral: restoredPeripheral,
                                          reason: "state_restore_connected")
                // A connected CoreBluetooth restoration does not emit
                // `didConnect`. Hold the same bounded stream-repair lease used
                // by a normal connection so an already-connected but silent
                // restored link cannot remain indefinitely on Pending.
                self.beginPostReconnectStreamLeaseIfNeeded(
                    peripheral: restoredPeripheral,
                    callbackEpoch: restoreCallbackEpoch,
                    reason: "state_restore_connected"
                )
                self.protectedR10ActivationGraceTask?.cancel()
                self.protectedR10ActivationGraceTask = nil
                self.protectedR10ActivationSent = false
                self.protectedR10ActivationAt = nil
                self.protectedR10FramesAfterActivation = 0
                self.protectedR10MissingFrameTask?.cancel()
                self.protectedR10MissingFrameTask = nil
                self.protectedR10StabilityTask?.cancel()
                self.protectedR10StabilityTask = nil
                // Handoff-13 CP0-A: restoration is a process relaunch — the
                // persisted proof may already be far past its deadline.
                self.enforceProtectedR10ProofDeadlineIfNeeded(
                    trigger: "will_restore_state"
                )
                // CoreBluetooth restoration is a process relaunch mid-link:
                // the persisted workout lease re-arms on this restored
                // connection epoch with the same one-attempt bound.
                self.restoreWorkoutMotionLeaseIfNeeded(reason: "state_restore_connected")
                self.evaluateAllDayMotionGovernor(reason: "state_restore_connected")
                if self.beginMotionHandshakeLaunchConnectionCutoverIfNeeded(
                    peripheral: restoredPeripheral,
                    central: central,
                    reason: "state_restore_connected"
                ) {
                    return
                }
                if self.beginProtectedR10LaunchConnectionCutoverIfNeeded(
                    peripheral: restoredPeripheral,
                    central: central,
                    reason: "state_restore_connected"
                ) {
                    return
                }
                if savedPeripheralIdentifier != restoredPeripheral.identifier,
                   Self.scanCandidateHasStrapIdentity(
                    advertisedServices: [],
                    advertisedName: restoredPeripheral.name
                   ) {
                    self.firstUseStandardHeartRateCandidateID =
                        restoredPeripheral.identifier
                }
                guard let restoreCallbackSource else { return }
                self.recordLinkObservedConnected(
                    reason: "state_restore_connected",
                    peripheral: restoredPeripheral,
                    callbackSource: restoreCallbackSource,
                    evidence: .provisionalConnection
                )
                self.scheduleRangeLossBackfillIfNeeded(reason: "state_restore_connected")
                if self.beginRetiredBatteryProbeRecoveryIfNeeded(restoredPeripheral) {
                    return
                }
                if self.motionHandshakeDiagnostic != nil {
                    self.recordMotionHandshakeEvidence(event: "restored_connected")
                    restoredPeripheral.discoverServices([Self.UUIDs.strapService])
                } else {
                    if self.denseBringUpIsWanted {
                        self.beginHRFirstDenseBringUpIfNeeded(
                            peripheral: restoredPeripheral,
                            reason: "state_restore_connected"
                        )
                    } else {
                        restoredPeripheral.discoverServices(self.discoveryServicesForCurrentMode)
                    }
                    self.resumeProtectedR10FromRestoredCache(restoredPeripheral)
                }
                AtriaDebugLog("ATRIADBG ble_restore status=connected name=%@", self.deviceName)
            case .connecting, .disconnecting:
                self.batteryConnectionRestoredSamePeripheral = false
                self.recomputeConnectionStatus(reason: "event")
                self.markPendingKnownReconnect(reason: "state_restore_transition")
                if restoredPeripheral.state == .connecting {
                    self.startReconnectWatchdog(
                        reason: "state_restore_transition",
                        peripheral: restoredPeripheral
                    )
                } else {
                    self.startReconnectWatchdog(
                        reason: "state_restore_transition",
                        peripheral: restoredPeripheral
                    )
                }
                AtriaDebugLog(
                    "ATRIADBG ble_restore status=transition peripheral_state=%d name=%@ action=keep_existing_no_duplicate_connect",
                    restoredPeripheral.state.rawValue,
                    self.deviceName
                )
            case .disconnected:
                self.batteryConnectionRestoredSamePeripheral = false
                self.recomputeConnectionStatus(reason: "event")
                self.markPendingKnownReconnect(reason: "state_restore")
                connectedPeripheralRetainer.retain(restoredPeripheral)
                self.startReconnectWatchdog(reason: "state_restore", peripheral: restoredPeripheral)
                // The later powered-on delegate callback is the sole owner of
                // the standing connect and issues it synchronously. Calling it
                // again from this deferred MainActor restoration task creates
                // two requests while CoreBluetooth still reports disconnected.
                AtriaDebugLog(
                    "ATRIADBG ble_restore status=disconnected name=%@ action=publish_only_powered_on_precheck_owns_connect",
                    self.deviceName
                )
            @unknown default:
                self.batteryConnectionRestoredSamePeripheral = false
                self.recomputeConnectionStatus(reason: "event")
                self.markPendingKnownReconnect(reason: "state_restore_unknown")
                self.startReconnectWatchdog(
                    reason: "state_restore_unknown",
                    peripheral: restoredPeripheral
                )
                AtriaDebugLog(
                    "ATRIADBG ble_restore status=transition peripheral_state=%d name=%@ action=wait_unknown_no_duplicate_connect",
                    restoredPeripheral.state.rawValue,
                    self.deviceName
                )
            }
        }
    }

    nonisolated func centralManager(_ central: CBCentralManager,
                        didDiscover peripheral: CBPeripheral,
                        advertisementData: [String: Any], rssi RSSI: NSNumber) {
        guard let centralToken = centralEventFence.capture(central) else {
            AtriaDebugLog("ATRIADBG ble_central status=callback_rejected reason=retired_manager callback=did_discover")
            return
        }
        let advName = (advertisementData[CBAdvertisementDataLocalNameKey] as? String) ?? peripheral.name
        let advServices = (advertisementData[CBAdvertisementDataServiceUUIDsKey] as? [CBUUID]) ?? []
        // Standard 180D is shared by chest straps, watches and gym equipment.
        // First-time setup may attach only with WHOOP-specific evidence: its
        // proprietary service or its advertised/system name. This prevents an
        // unrelated nearby HR device from becoming the saved standing peer.
        let isStrap = Self.scanCandidateHasStrapIdentity(
            advertisedServices: advServices,
            advertisedName: advName
        )
        guard isStrap else { return }
        let name = advName ?? "Strap"
        Task { @MainActor in
            guard self.centralEventFence.accepts(
                centralToken,
                central: central
            ), Self.shouldClaimCurrentScanCandidate(
                hasStrapIdentity: isStrap,
                isActivelyScanning: self.isActivelyScanning,
                hasCurrentPeripheralOwner: self.peripheral != nil
            ) else { return }   // first current-scan match wins
            self.lastScanMatchAt = Date()
            AtriaDebugLog("ATRIADBG ble_scan status=matched name=%@ rssi=%@ services=%d",
                  name,
                  RSSI,
                  advServices.count)
            self.attach(to: peripheral, name: name)
        }
    }

    nonisolated func centralManager(_ central: CBCentralManager, didConnect peripheral: CBPeripheral) {
        guard let centralToken = centralEventFence.capture(central) else {
            AtriaDebugLog("ATRIADBG ble_central status=callback_rejected reason=retired_manager callback=did_connect")
            return
        }
        // Complete only this exact object's pending request before any duplicate
        // callback fast-return. A stale same-UUID completion cannot release a
        // newer request owned by a different CoreBluetooth representation.
        connectedPeripheralRetainer.completeConnectRequest(peripheral)
        // A duplicate completion for the exact already-live object is not a
        // new connection epoch. This occurs when CoreBluetooth coalesces more
        // than one pending connect request; reactivating the fence here would
        // invalidate legitimate queued HR/motion and count a phantom success.
        // A genuine reconnect is unaffected because didDisconnect invalidates
        // this exact tuple before another didConnect can arrive.
        if bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) != nil {
            AtriaDebugLog(
                "ATRIADBG ble_epoch status=duplicate_connect_ignored reason=exact_live_epoch action=no_epoch_or_radio_mutation peripheral=%@",
                peripheral.identifier.uuidString
            )
            return
        }
        // `didConnect` can arrive late for an object-distinct copy of the same
        // physical strap. Retain the callback object first: releasing a
        // connected duplicate can force CoreBluetooth to tear down the shared
        // underlying link. A merely connecting twin does not block this
        // successful object. A fully connected twin keeps ownership, while the
        // duplicate remains retained until a terminal callback or central
        // teardown; no cancel, delegate mutation, epoch change, or discovery is
        // safe or necessary on this duplicate edge.
        let connectedCallbackAdmission =
            connectedPeripheralRetainer.admitConnected(peripheral)
        if connectedCallbackAdmission == .retainPassiveDuplicate {
            AtriaDebugLog("ATRIADBG ble_epoch status=duplicate_connect_ignored reason=connected_same_uuid_twin action=retain_without_cancel_no_shared_state_mutation peripheral=%@",
                          peripheral.identifier.uuidString)
            return
        }
        proprietaryFrameReassembler.reset()
        let callbackEpoch = bleCallbackEpochFence.activate(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral)
        )
        let peripheralObjectID = ObjectIdentifier(peripheral)
        let diagnosticActive = motionHandshakeDiagnostic != nil
        let interruptedHistoryGeneration: UInt64? = {
            guard heartRateCaptureIntent.snapshot(),
                  !diagnosticActive else { return nil }
            return historyTransportPhaseFence.claimRealtimeRestore(
                peripheralID: peripheral.identifier,
                peripheralObjectID: peripheralObjectID,
                callbackEpoch: callbackEpoch
            )
        }()
        let interruptedHistoryClaimIsCurrent =
            interruptedHistoryGeneration.map {
                historyTransportPhaseFence.acceptsRealtimeRestoreClaim(
                    peripheralID: peripheral.identifier,
                    peripheralObjectID: peripheralObjectID,
                    interruptedGeneration: $0,
                    callbackEpoch: callbackEpoch
                )
            } ?? false
        let mtu = peripheral.maximumWriteValueLength(for: .withoutResponse) + 3
        // Locked range return can grant this callback as the process's final
        // execution slice. Do not put the essential 180D -> 2A37 discovery
        // behind the large MainActor connection reset below: iOS may suspend us
        // before that task reaches its final radio call. This is an enable-only
        // production fast lane, fenced to the just-activated connected epoch;
        // sparse capture, explicit history, and diagnostic profiles remain
        // untouched.
        // Fresh-owner history activates the thread-safe phase fence before
        // CoreBluetooth reconnects. Honor it here, before the MainActor resume,
        // so the background-safe 180D fast lane cannot overlap the required
        // proprietary-only 6108 discovery on the same callback.
        let historyRecoveryActive =
            historyTransportPhaseFence.snapshot().isActive
                || (
                    interruptedHistoryGeneration != nil
                        && !interruptedHistoryClaimIsCurrent
                )
        guard centralEventFence.accepts(
            centralToken,
            central: central
        ) else { return }
        _ = beginSynchronousHeartRateDiscoveryFastLane(
            peripheral: peripheral,
            callbackEpoch: callbackEpoch,
            historyRecoveryActive: historyRecoveryActive,
            diagnosticActive: diagnosticActive,
            reason: "did_connect_background_safe"
        )
        Task { @MainActor in
            guard self.centralEventFence.accepts(
                centralToken,
                central: central
            ), self.acceptsBLECallback(
                epoch: callbackEpoch,
                peripheral: peripheral
            ) else {
                AtriaDebugLog("ATRIADBG ble_epoch status=stale_connect_ignored epoch=%llu current=%llu peripheral=%@",
                              callbackEpoch,
                              self.bleCallbackEpochFence.epoch,
                              peripheral.identifier.uuidString)
                return
            }
            // A fresh CBCentralManager's powered-on fast lane can connect the
            // saved strap without ever passing through `attach`. Retain that
            // exact connected object immediately. The e3bc545 physical run
            // otherwise reached the foreground keepalive with
            // `self.peripheral == nil`, which rediscovered a retrieved copy as
            // "missing_peripheral" while valid HR was already arriving and
            // helped turn every connection into a short reconnect burst.
            peripheral.delegate = self
            self.connectedPeripheralRetainer.retain(peripheral)
            self.peripheral = peripheral
            self.assignIfChanged(\.deviceName, peripheral.name ?? self.deviceName)
            self.recomputeConnectionStatus(reason: "did_connect_retained")
            if let interruptedHistoryGeneration,
               self.historyTransportPhaseFence.acceptsRealtimeRestoreClaim(
                peripheralID: peripheral.identifier,
                peripheralObjectID: peripheralObjectID,
                interruptedGeneration: interruptedHistoryGeneration,
                callbackEpoch: callbackEpoch
               ) {
                // The delegate queue already retired this exact transport
                // generation before installing the standing reconnect. Finish
                // only that old MainActor reducer now; a newer generation
                // invalidates the claim and is never interrupted here.
                if self.offlineHistoricalSyncInProgress,
                   self.offlineHistoricalSyncGeneration
                    == interruptedHistoryGeneration {
                    self.interruptOfflineHistoricalSyncForTransportLoss(
                        reason:
                            "history_slice_live_restore_connected"
                    )
                }
                UserDefaults.standard.set(
                    false,
                    forKey: "atria.ble.disconnectOfflineSyncActive"
                )
                _ = self.historyTransportPhaseFence
                    .settleRealtimeRestoreClaim(
                        peripheralID: peripheral.identifier,
                        peripheralObjectID: peripheralObjectID,
                        interruptedGeneration:
                            interruptedHistoryGeneration,
                        callbackEpoch: callbackEpoch
                    )
                AtriaDebugLog(
                    "ATRIADBG offline_sync status=interrupted_owner_handoff_settled generation=%llu epoch=%llu action=restore_2a37_no_history_command",
                    interruptedHistoryGeneration,
                    callbackEpoch
                )
            }
            // Do NOT end the reconnect lease at `did_connect`: the stream is
            // not recovered until an accepted HR sample lands on this epoch.
            // Ending here is the proven locked-background failure (2026-07-24
            // cycle 1: connected, discovery response never processed, counter
            // frozen until the app was foregrounded).
            self.beginPostReconnectStreamLeaseIfNeeded(
                peripheral: peripheral,
                callbackEpoch: callbackEpoch,
                reason: "did_connect_background_safe"
            )
            self.schedulePostReconnectHRReassertion(
                peripheral: peripheral,
                reason: "did_connect_background_safe"
            )
            // `didDisconnect` can be delayed behind a Bluetooth-off/on state
            // change.  In that ordering the synchronous fast lane above
            // correctly sees the old history fence and declines to overlap
            // proprietary history traffic, but there may be no valid history
            // owner left to clear it.  Never let that stale epoch strand the
            // replacement connection without 2A37: retain the durable gap,
            // drop only the local owner, then rerun the enable-only HR fast
            // lane.  A deliberately armed fresh-owner cutover remains the
            // explicit exception and continues through its normal path below.
            let disconnectObservedWithHistoryOwner = UserDefaults.standard.bool(
                forKey: "atria.ble.disconnectOfflineSyncActive"
            )
            let staleHistoryPhase = self.historyTransportPhaseFence.snapshot().isActive
            if Self.shouldReleaseInterruptedHistoryOwnerForLiveReconnect(
                offlineSyncInProgress: self.offlineHistoricalSyncInProgress,
                historyPhaseActive: staleHistoryPhase,
                disconnectObservedWithHistoryOwner: disconnectObservedWithHistoryOwner,
                freshOwnerCutoverPending: self.freshHistoryOwnerCutoverPending,
                freshOwnerAdmissionPending: self.freshHistoryOwnerAdmissionPending,
                freshOwnerConnectionArmed: self.freshHistoryOwnerConnectionGeneration != nil
            ) {
                let generation = self.offlineHistoricalSyncGeneration
                if self.offlineHistoricalSyncInProgress {
                    self.interruptOfflineHistoricalSyncForTransportLoss(
                        reason: "interrupted_history_owner_reconnect_live_release"
                    )
                } else {
                    self.cancelHistoryOnlyProbe(
                        reason: "interrupted_history_owner_reconnect_live_release"
                    )
                    _ = self.historyTransportPhaseFence.deactivate()
                }
                UserDefaults.standard.set(false,
                                          forKey: "atria.ble.disconnectOfflineSyncActive")
                UserDefaults.standard.set(
                    "interrupted_history_owner_released_for_live_reconnect",
                    forKey: OfflineSyncDefaults.lastStatus
                )
                AtriaDebugLog("ATRIADBG offline_sync status=interrupted_owner_released_for_live_reconnect generation=%llu action=rerun_2a37_discovery_no_history_command",
                              generation)
                _ = self.beginSynchronousHeartRateDiscoveryFastLane(
                    peripheral: peripheral,
                    callbackEpoch: callbackEpoch,
                    historyRecoveryActive: false,
                    diagnosticActive: self.motionHandshakeDiagnostic != nil,
                    reason: "did_connect_interrupted_history_owner_live_release"
                )
            }
            self.writeCompletionLedger.reset()
            self.heartRateNotificationEnableGate.reset()
            self.heartRateInactiveCallbackRetryIssued = false
            self.batteryNotificationRecoveryTask?.cancel()
            self.batteryNotificationRecoveryTask = nil
            self.batteryNotificationRecoveryAttempt = 0
            self.pendingNotifyReenableUUIDs.remove(Self.UUIDs.batteryLevel)
            self.batteryConnectionRestoredSamePeripheral = false
            self.recentReconnectBatteryBaselineProjectionPublished = false
            self.batteryStatusNotificationConfirmedAt = nil
            self.batteryStatusReadRequestedAt = nil
            self.lastPlausibleBatteryRiseEvidenceAt = nil
            self.lastUncorroboratedChargingStatusAt = nil
            self.batteryRiseCandidate = Self.batteryRiseCandidateAfterReconnect(
                self.batteryRiseCandidate,
                candidatePeripheralID: self.batteryRiseCandidatePeripheralID,
                connectedPeripheralID: peripheral.identifier,
                now: Date()
            )
            if self.batteryRiseCandidate == nil {
                self.batteryRiseCandidatePeripheralID = nil
            }
            if UserDefaults.standard.bool(forKey: BatteryDefaults.proprietaryRefreshPending) {
                failProprietaryBatteryRefresh(reason: "stale_pending_request_after_connect")
            }
            reconnectWatchdogTask?.cancel()
            // `backgroundReconnectLeaseReissueUsed` is deliberately NOT reset
            // here: `did_connect` is not recovery. Both bounded-repair permits
            // are restored only by a fresh accepted HR sample
            // (`completePostReconnectStreamRecoveryIfNeeded`), so a
            // connect/stall cycle can never loop repairs.
            freshScanFallbackTask?.cancel()
            freshScanFallbackTask = nil
            isActivelyScanning = false
            recomputeConnectionStatus(reason: "did_connect")
            // A reconnect is a new trust boundary. Proprietary restoration
            // traffic has produced false 0/100 values that otherwise survive in
            // memory across the link drop. Keep a credible mid-range value as a
            // visibly cached baseline, but never carry a boundary sentinel into
            // the new connection without a fresh stable series.
            let now = Date()
            self.batteryBaselineValidationStartedAt = now
            let defaults = UserDefaults.standard
            defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
            defaults.removeObject(forKey: BatteryDefaults.statusNotificationConfirmedAt)
            defaults.removeObject(forKey: BatteryDefaults.statusReadRequestedAt)
            defaults.set("new_link_unconfirmed",
                         forKey: BatteryDefaults.notificationLastError)
            let credibleLevel = defaults.object(forKey: BatteryDefaults.credibleLevel) as? Int
            let credibleAt = (defaults.object(forKey: BatteryDefaults.credibleAt) as? Double)
                .map(Date.init(timeIntervalSince1970:))
            let reconnectLevel = Self.reconnectBatteryDisplayLevel(
                currentLevel: self.batteryLevel,
                credibleLevel: credibleLevel,
                credibleAt: credibleAt,
                now: now,
                maxAge: Self.activeBatterySubscriptionBaselineMaximumAge
            )
            if reconnectLevel != self.batteryLevel {
                self.assignIfChanged(\.batteryLevel, reconnectLevel)
                self.lastAcceptedBatteryLevelAt = reconnectLevel >= 0 ? credibleAt : nil
            }
            self.pendingBatteryDropCandidate = nil
            self.batteryNotificationEpochHadRejectedCallback = false
            self.displayedBatteryLevelIsCached = reconnectLevel >= 0
            self.batteryReadingIsRecentBaseline = reconnectLevel >= 0
            defaults.removeObject(forKey: BatteryDefaults.notificationLeaseAt)
            defaults.set(true, forKey: BatteryDefaults.requiresFreshConfirmation)
            assignIfChanged(\.batteryIsCharging, false)
            assignIfChanged(\.batteryChargeStatus, .levelOnly)
            recordBatteryChargeEvidence(batteryChargeStatus, reason: "did_connect")
            beginConnectionEpoch(peripheral: peripheral, reason: "did_connect", now: now)
            motionHandshakeCommandSequenceTask?.cancel()
            motionHandshakeCommandSequenceTask = nil
            motionHandshakeProfileCharacteristics.removeAll()
            motionHandshakeRequestedNotifyUUIDs.removeAll()
            motionHandshakeConfirmedNotifyUUIDs.removeAll()
            protectedR10CommandSequenceTask?.cancel()
            protectedR10CommandSequenceTask = nil
            protectedR10StandardDiscoveryTask?.cancel()
            protectedR10StandardDiscoveryTask = nil
            protectedR10ProfileCharacteristics.removeAll()
            callbackPolicyState.update { $0.protectedProfileIsEmpty = true }
            protectedR10ProfileRequestedNotifyUUIDs.removeAll()
            protectedR10ProfileConfirmedNotifyUUIDs.removeAll()
            protectedR10StandardDiscoveryStarted = false
            protectedR10InitialProfilePeripheralID = standardHROnlyMode
                && !historyOnlyProbeMode
                && !protectedR10StreamSuppressed
                ? peripheral.identifier
                : nil
            protectedR10InitialProfileNotificationRequested = false
            protectedR10ActivationGraceTask?.cancel()
            protectedR10ActivationGraceTask = nil
            protectedR10ActivationSent = false
            protectedR10ActivationAt = nil
            protectedR10FramesAfterActivation = 0
            protectedR10MissingFrameTask?.cancel()
            protectedR10MissingFrameTask = nil
            protectedR10StabilityTask?.cancel()
            protectedR10StabilityTask = nil
            // Handoff-13 CP0-A: a fresh connection is the first reliable
            // post-suspension edge — synchronously terminalize any proof that
            // outlived its 150 s deadline before protected work resumes.
            enforceProtectedR10ProofDeadlineIfNeeded(trigger: "did_connect")
            // A new connection epoch grants an active workout lease one fresh
            // bounded activation attempt after passive grace; repeated
            // lifecycle callbacks on the same connection cannot resend it.
            restoreWorkoutMotionLeaseIfNeeded(reason: "did_connect")
            // Ordinary all-day capture may arm only the low-bandwidth v24
            // bank. It cannot make the dense bring-up check below true.
            evaluateAllDayMotionGovernor(reason: "did_connect")
            // Dense motion has only ever been sustained on links brought up by
            // the complete launch-style sequence (fresh discovery, ordered
            // profile, command pair, stability proof) — bonded auto-reconnects
            // stay sparse and die within ~25 s regardless of what is sent on
            // them (2026-07-16 00:50 telemetry). Only an explicit workout or
            // calibration lease can re-enter that profile; ordinary all-day
            // v24 banking is deliberately excluded.
            if denseBringUpIsWanted,
               standardHROnlyMode,
               !historyOnlyProbeMode,
               protectedR10CleanOwner == .protectedV9,
               protectedR10CleanOwnerState == .qualified,
               !protectedR10StreamSuppressed {
                workoutMotionLeaseProfileArmed = true
                AtriaDebugLog("ATRIADBG workout_motion status=lease_full_bring_up_armed action=hr_first_then_launch_style_profile_per_connection")
            }
            dbgMTU = mtu
            recordLinkConnected(peripheral: peripheral)
            // If the previous process was terminated between receiving stream-5
            // bytes and its archive callback, claim those exact bytes as soon
            // as the same verified strap reconnects. This work stays entirely
            // off the BLE callback path and never promotes a historical gap to
            // covered; it merely prevents a later recovery generation from
            // replacing the journal before it is durably archived.
            _ = archiveOrphanHistoricalIngressIfNeeded(
                reason: "did_connect_orphan_ingress_replay",
                force: false,
                explicitRequest: false,
                retainHistoricalRequest: false
            )
            if self.freshHistoryOwnerAdmissionPending {
                self.freshHistoryOwnerAdmissionPending = false
                if let pending = self.takePendingOfflineHistoricalSyncRequest() {
                    let started = self.requestOfflineHistoricalSyncIfNeeded(
                        reason: pending.reason,
                        force: pending.force,
                        explicitResearchRequest: pending.explicitRequest,
                        explicitPostWorkoutBankRequest:
                            pending.explicitPostWorkoutBankRequest,
                        preserveConnectedRealtimeOwner:
                            pending.preserveConnectedRealtimeOwner
                    )
                    if started {
                        self.freshHistoryOwnerConnectionGeneration =
                            self.offlineHistoricalSyncGeneration
                        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_admitted_on_did_connect generation=%llu action=claim_current_connection_once",
                                      self.offlineHistoricalSyncGeneration)
                        if self.resumeFreshHistoryOwnerConnectionIfNeeded(
                            peripheral: peripheral
                        ) {
                            return
                        }
                    }
                }
            }
            if readOnlyHistoryCaptureRequested {
                AtriaDebugLog("ATRIADBG readOnlyHistory status=service_discovery_requested service=61080001 commands=0")
                peripheral.discoverServices([Self.UUIDs.strapService])
                return
            }
            if resumeFreshHistoryOwnerConnectionIfNeeded(
                peripheral: peripheral
            ) {
                return
            }
            if beginRetiredBatteryProbeRecoveryIfNeeded(peripheral) {
                return
            }
            if motionHandshakeDiagnostic != nil {
                recordMotionHandshakeEvidence(event: "connected",
                                              detail: "discover_stream5_service_only")
                peripheral.discoverServices([Self.UUIDs.strapService])
            } else {
                if denseBringUpIsWanted {
                    beginHRFirstDenseBringUpIfNeeded(peripheral: peripheral,
                                                     reason: "did_connect")
                } else {
                    peripheral.discoverServices(discoveryServicesForCurrentMode)
                }
            }
        }
    }

    nonisolated func centralManager(_ central: CBCentralManager,
                        didDisconnectPeripheral peripheral: CBPeripheral, error: Error?) {
        guard let centralToken = centralEventFence.capture(central) else {
            AtriaDebugLog("ATRIADBG ble_central status=callback_rejected reason=retired_manager callback=did_disconnect")
            return
        }
        let terminalAdmission =
            connectedPeripheralRetainer.beginTerminalCallback(peripheral)
        if terminalAdmission == .ignorePassiveDuplicate {
            peripheral.delegate = nil
            connectedPeripheralRetainer.release(peripheral)
            AtriaDebugLog("ATRIADBG ble_epoch status=stale_terminal_callback_ignored callback=did_disconnect reason=active_same_uuid_twin peripheral=%@",
                          peripheral.identifier.uuidString)
            return
        }
        proprietaryFrameReassembler.reset()
        let terminalCallbackEpoch =
            bleCallbackEpochFence.invalidate(
                ifMatching: peripheral.identifier,
                peripheralObjectID: ObjectIdentifier(peripheral)
            )
        // The link is already down, so releasing here cannot tear one down.
        // The fast lane below re-retains whatever it re-issues a connect on,
        // and every other connect path retains at its own call site. Ordering
        // matters: release first, so a suppressed reconnect does not leave a
        // dead peripheral held for the life of the process.
        connectedPeripheralRetainer.releaseDisconnected(peripheralID: peripheral.identifier)
        let terminalHistoryPhase = historyTransportPhaseFence.snapshot()
        var fastLaneDisposition = backgroundReconnectFence.consumeDisposition(
            peripheralID: peripheral.identifier,
            continuousCaptureWanted: heartRateCaptureIntent.snapshot(),
            historyTransportActive: terminalHistoryPhase.isActive,
            activeHistoryTransportGeneration:
                terminalHistoryPhase.generation,
            diagnosticActive: motionHandshakeDiagnostic != nil
        )
        if case let .reconnectRealtimeAfterHistoryRelease(generation) =
            fastLaneDisposition,
           !historyTransportPhaseFence.retireForRealtimeRestore(
            ifMatching: generation,
            peripheralID: peripheral.identifier
           ) {
            // MainActor cleanup may already have released this generation. In
            // that case ordinary realtime reconnect is safe. A different
            // active generation is a newer owner and remains fail-closed.
            fastLaneDisposition =
                historyTransportPhaseFence.snapshot().isActive
                    ? .suppressHistoryOwner
                    : .reconnectRealtime
        }
        let synchronousReconnectIssued =
            fastLaneDisposition.requestsRealtimeReconnect
                && centralEventFence.accepts(centralToken, central: central)
                && peripheral.state == .disconnected
        if synchronousReconnectIssued {
            // Install CoreBluetooth's standing request before yielding to
            // MainActor. This callback can be the locked app's final execution
            // slice; without a pending connect, range return cannot wake Atria.
            peripheral.delegate = self
            issueSingleFlightConnect(
                peripheral,
                central: central,
                reason: "did_disconnect_background_safe"
            )
            AtriaDebugLog("ATRIADBG ble_link status=reconnect_requested_sync reason=did_disconnect_background_safe peripheral=%@",
                          peripheral.identifier.uuidString)
            Task { @MainActor [weak self, weak peripheral] in
                guard let self, let peripheral else { return }
                guard self.centralEventFence.accepts(
                    centralToken,
                    central: central
                ) else { return }
                self.beginBackgroundReconnectLeaseIfNeeded(
                    peripheral: peripheral,
                    error: error
                )
            }
        } else {
            AtriaDebugLog("ATRIADBG ble_link status=reconnect_fast_lane_suppressed reason=%@ peripheral_state=%d",
                          String(describing: fastLaneDisposition),
                          peripheral.state.rawValue)
        }
        Task { @MainActor in
            guard self.centralEventFence.accepts(
                centralToken,
                central: central
            ), Self.acceptsDisconnectCallbackFollowup(
                trackedPeripheralIsDisconnectedInstance:
                    self.peripheral === peripheral,
                terminalEpochIsCurrent:
                    self.bleCallbackEpochFence.epoch == terminalCallbackEpoch
            ) else {
                AtriaDebugLog("ATRIADBG ble_epoch status=stale_disconnect_ignored peripheral=%@ terminal_epoch=%llu current_epoch=%llu",
                              peripheral.identifier.uuidString,
                              terminalCallbackEpoch,
                              self.bleCallbackEpochFence.epoch)
                return
            }
            self.releaseConnectedMotionBankPreFreshHRFirstRefusal(
                reason: "did_disconnect"
            )
            self.releaseConnectedMotionBankArchiveWarmFirstRefusal(
                reason: "did_disconnect"
            )
            self.releaseConnectedMotionBankAdmissionLedgerFirstRefusal(
                reason: "did_disconnect"
            )
            self.releaseConnectedMotionBankLocalDependencyFirstRefusal(
                reason: "did_disconnect"
            )
            // This is the natural boundary which may later permit an ordinary
            // gap retry.  It never starts history here; realtime reconnect is
            // still installed first below.
            self.deferInterruptedFullDrainForCurrentLiveConnection = false
            self.interruptedFullDrainReacquisitionTask?.cancel()
            self.interruptedFullDrainReacquisitionTask = nil
            if self.readOnlyHistoryRestoreCutoverPending {
                self.readOnlyHistoryRestoreCutoverPending = false
                self.writeCompletionLedger.reset()
                self.heartRateNotificationEnableGate.reset()
                self.reconnectWatchdogTask?.cancel()
                self.freshScanFallbackTask?.cancel()
                self.freshScanFallbackTask = nil
                self.batteryConnectionRestoredSamePeripheral = false
                self.txCharacteristic = nil
                self.heartRateCharacteristic = nil
                self.dbgTxReady = false
                // The strap may remain non-advertising after an app-owned
                // cancellation even though iOS still knows the paired
                // peripheral. Install a direct standing connection to that
                // exact peripheral instead of depending on a scan result.
                // didConnect still creates the fresh notification epoch that
                // the diagnostic requires.
                self.peripheral = peripheral
                peripheral.delegate = self
                self.recordLinkAttempt(
                    reason: "read_only_history_restored_direct_reconnect",
                    peripheral: peripheral
                )
                self.markPendingKnownReconnect(
                    reason: "read_only_history_restored_direct_reconnect"
                )
                self.issueSingleFlightConnect(
                    peripheral,
                    central: central,
                    reason: "read_only_history_restored_direct_reconnect"
                )
                self.startReconnectWatchdog(
                    reason: "read_only_history_restored_direct_reconnect",
                    peripheral: peripheral
                )
                self.recomputeConnectionStatus(
                    reason: "read_only_history_restore_direct_reconnect"
                )
                AtriaDebugLog("ATRIADBG readOnlyHistory status=direct_reconnect_started reason=restored_epoch_disconnected commands=0 request_preserved=%d",
                              self.readOnlyHistoryCaptureRequested ? 1 : 0)
                return
            }
            self.cancelReadOnlyHistoryCaptureAfterDisconnect(
                reason: error?.localizedDescription ?? "link_disconnected"
            )
            self.writeCompletionLedger.reset()
            self.heartRateNotificationEnableGate.reset()
            self.heartRateInactiveCallbackRetryIssued = false
            self.batteryConnectionRestoredSamePeripheral = false
            self.recentReconnectBatteryBaselineProjectionPublished = false
            if proprietaryBatteryRefreshPhase != .idle
                || UserDefaults.standard.bool(forKey: BatteryDefaults.proprietaryRefreshPending) {
                failProprietaryBatteryRefresh(reason: "link_disconnected_during_request")
            }
            let wasRealtimeArmedAtDisconnect = realtimeArmed
            let wasR10RetryActiveAtDisconnect = r10ArmRetryTask != nil
            let protectedActivationWasSent = protectedR10ActivationSent
            let protectedActivationStartedAt = protectedR10ActivationAt
            let protectedFrames = protectedR10FramesAfterActivation
            let cleanOwnerProofWasActive = protectedR10CleanOwnerProofIsActive
            // Handoff-12 CP0: capture proof-attribution evidence BEFORE the
            // teardown below clears it. These fields feed the disconnect
            // context record; nothing here mutates radio state.
            let confirmedNotifyUUIDsAtDisconnect =
                protectedR10ProfileConfirmedNotifyUUIDs
                    .map(\.uuidString)
                    .sorted()
                    .joined(separator: ",")
            let crcRejectedFramesAtDisconnect =
                protectedR10CRCRejectedFramesThisConnection
            let proofStartedAtUnix = UserDefaults.standard.double(
                forKey: Self.protectedR10CleanOwnerProofStartedAtKey
            )
            let centralStateAtDisconnect = self.central?.state.rawValue ?? -1
            let pureHRV10CutoverWasPending = protectedR10CleanOwner == .pureHRV10
                && protectedR10CleanOwnerState == .fallbackPending
            protectedR10CRCRejectedFramesThisConnection = 0
            protectedR10ActivationGraceTask?.cancel()
            protectedR10ActivationGraceTask = nil
            protectedR10MissingFrameTask?.cancel()
            protectedR10MissingFrameTask = nil
            protectedR10StabilityTask?.cancel()
            protectedR10StabilityTask = nil
            protectedR10CleanOwnerProofTimeoutTask?.cancel()
            protectedR10CleanOwnerProofTimeoutTask = nil
            motionHandshakeCommandSequenceTask?.cancel()
            motionHandshakeCommandSequenceTask = nil
            motionHandshakeProfileCharacteristics.removeAll()
            motionHandshakeRequestedNotifyUUIDs.removeAll()
            motionHandshakeConfirmedNotifyUUIDs.removeAll()
            protectedR10CommandSequenceTask?.cancel()
            protectedR10CommandSequenceTask = nil
            protectedR10StandardDiscoveryTask?.cancel()
            protectedR10StandardDiscoveryTask = nil
            protectedR10ProfileCharacteristics.removeAll()
            callbackPolicyState.update { $0.protectedProfileIsEmpty = true }
            protectedR10ProfileRequestedNotifyUUIDs.removeAll()
            protectedR10ProfileConfirmedNotifyUUIDs.removeAll()
            protectedR10StandardDiscoveryStarted = false
            recomputeConnectionStatus(reason: "event")
            freshScanFallbackTask?.cancel()
            freshScanFallbackTask = nil
            batteryConfirmationReadTask?.cancel()
            batteryConfirmationReadTask = nil
            batteryConfirmationReadLevel = nil
            batteryLevelCharacteristic = nil
            batteryStatusCharacteristic = nil
            batteryStatusNotificationConfirmedAt = nil
            batteryStatusReadRequestedAt = nil
            lastBatteryReadRequestedAt = nil
            realtimeArmed = false        // re-arm realtime after reconnect
            r10ArmRetryTask?.cancel()
            stopR10LivenessWatchdog(reason: "did_disconnect")
            stopProtocolHeartbeat()
            proprietaryNotifyFallbackTask?.cancel()
            proprietaryNotifyFallbackTask = nil
            activeProprietaryNotifyUUIDs.removeAll()
            strapStream5NotifyConfirmed = false
            // The old R10 lease is bound to the prior BLE epoch. Never let it
            // survive range loss, Bluetooth-off, or an app-owned reconnect.
            r10StepLeaseConnectionStartedAt = nil
            protectedR10InitialProfilePeripheralID = nil
            protectedR10InitialProfileNotificationRequested = false
            let defaults = UserDefaults.standard
            defaults.removeObject(forKey: BatteryDefaults.notificationLeaseAt)
            defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
            defaults.removeObject(forKey: BatteryDefaults.statusNotificationConfirmedAt)
            defaults.removeObject(forKey: BatteryDefaults.statusReadRequestedAt)
            defaults.set("link_disconnected",
                         forKey: BatteryDefaults.notificationLastError)
            let disconnects = defaults.integer(forKey: LinkDefaults.disconnects) + 1
            let errorText = error?.localizedDescription ?? "nil"
            defaults.set(disconnects, forKey: LinkDefaults.disconnects)
            defaults.set("disconnected", forKey: LinkDefaults.lastStatus)
            defaults.set("did_disconnect", forKey: LinkDefaults.lastReason)
            defaults.set(errorText, forKey: LinkDefaults.lastError)
            let connectedDuration = connectedAt.map { Date().timeIntervalSince($0) } ?? 0
            let disconnectNow = Date()
            let wasUserRequestedDisconnect = userRequestedDisconnect
            let lastAppCancelAt = defaults.double(forKey: "atria.ble.lastAppCancelAt")
            let recentAppCancel = lastAppCancelAt > 0
                && abs(disconnectNow.timeIntervalSince1970 - lastAppCancelAt) <= 15
            let disconnectCause: String
            if wasUserRequestedDisconnect {
                disconnectCause = "user_requested"
            } else if recentAppCancel {
                let reason = defaults.string(forKey: "atria.ble.lastAppCancelReason") ?? "unknown"
                disconnectCause = "atria_cancel:\(reason)"
            } else if let nsError = error as NSError? {
                disconnectCause = "corebluetooth:\(nsError.domain):\(nsError.code)"
            } else {
                disconnectCause = "remote_link_loss_no_error"
            }
            // Read before overwriting: the gap since the previous disconnect is
            // the only ambient-stability signal available here, and the proof
            // decision below needs it to tell "this owner caused a drop" apart
            // from "this link was already dropping at that cadence".
            let previousDisconnectAt = defaults.double(forKey: LinkDefaults.lastDisconnectAt)
            let ambientDisconnectInterval: TimeInterval? = previousDisconnectAt > 0
                ? disconnectNow.timeIntervalSince1970 - previousDisconnectAt
                : nil
            defaults.set(disconnectCause, forKey: LinkDefaults.lastDisconnectCause)
            defaults.set(disconnectNow.timeIntervalSince1970, forKey: LinkDefaults.lastDisconnectAt)
            defaults.set(max(0, disconnects - linkDisconnectCountAtLaunch),
                         forKey: LinkDefaults.disconnectsThisLaunch)
            let atriaOwnedOfflineSyncDisconnect = offlineHistoricalSyncInProgress
                || historyOnlyProbeEnabled
                || historyOnlyProbeMode
                || freshHistoryOwnerCutoverPending
            let previousProofInterruptions = defaults.integer(
                forKey: Self.protectedR10ProofChurnFailureCountKey
            )
            let proofDisconnectDecision = Self.protectedR10ProofDisconnectDecision(
                proofWasActive: cleanOwnerProofWasActive,
                cleanOwner: protectedR10CleanOwner,
                activationWasSent: protectedActivationWasSent,
                framesAfterActivation: protectedFrames,
                proofDuration: protectedActivationStartedAt.map {
                    disconnectNow.timeIntervalSince($0)
                } ?? -1,
                lastFrameAge: lastR10MotionFrameAt.map {
                    disconnectNow.timeIntervalSince($0)
                } ?? -1,
                userRequestedDisconnect: wasUserRequestedDisconnect,
                atriaOwnedOfflineSyncDisconnect: atriaOwnedOfflineSyncDisconnect,
                ambientDisconnectInterval: ambientDisconnectInterval
            )
            let gate4PassiveReconnectAfterTimeout =
                gate4PassiveReconnectProbeRequested
                && gate4PassiveReconnectArmed
                && cleanOwnerProofWasActive
                && protectedFrames > 0
                && !wasUserRequestedDisconnect
                && !atriaOwnedOfflineSyncDisconnect
            if cleanOwnerProofWasActive || pureHRV10CutoverWasPending {
                if gate4PassiveReconnectAfterTimeout {
                    prepareGate4PassiveR10ReconnectAfterTimeout()
                } else {
                    // Handoff-12 CP0: the terminal reason alone proved
                    // unattributable (the Aug-13 06:22→07:10 attempt left no
                    // way to tell decoder rejection from silence from ambient
                    // churn). Persist the full disconnect context before the
                    // fallback, on BOTH decision branches — the decision
                    // string records whether the owner actually beat ambient
                    // churn or the fallback was purely proof-integrity.
                    let nsError = error as NSError?
                    let context = ProtectedR10ProofDisconnectContext(
                        atUnix: disconnectNow.timeIntervalSince1970,
                        decision: proofDisconnectDecision == .fallbackToPureHR
                            ? "owner_beat_ambient_churn"
                            : "ambient_or_unattributed",
                        errorDomain: nsError?.domain,
                        errorCode: nsError?.code,
                        centralState: centralStateAtDisconnect,
                        confirmedNotifyUUIDs: confirmedNotifyUUIDsAtDisconnect,
                        framesAfterActivation: protectedFrames,
                        crcRejectedFrames: crcRejectedFramesAtDisconnect,
                        activationAgeSeconds: protectedActivationStartedAt.map {
                            disconnectNow.timeIntervalSince($0)
                        },
                        proofStartedAgeSeconds: proofStartedAtUnix > 0
                            ? disconnectNow.timeIntervalSince1970
                                - proofStartedAtUnix
                            : nil,
                        connectedDurationSeconds: connectedDuration,
                        owner: protectedR10CleanOwner.rawValue,
                        ownerState: protectedR10CleanOwnerState.rawValue,
                        ownerGenerationUnix:
                            connectedAt?.timeIntervalSince1970 ?? 0,
                        lastRollbackReason: defaults.string(
                            forKey: "atria.protectedR10.rollbackReason"
                        ),
                        ambientDisconnectIntervalSeconds:
                            ambientDisconnectInterval
                    )
                    if let contextData = try? JSONEncoder().encode(context) {
                        defaults.set(
                            contextData,
                            forKey: Self.protectedR10ProofDisconnectContextKey
                        )
                    }
                    if proofDisconnectDecision == .fallbackToPureHR {
                        defaults.set(previousProofInterruptions + 1,
                                     forKey: Self.protectedR10ProofChurnFailureCountKey)
                    }
                    persistProtectedR10CleanOwnerFallback(
                        reason: "clean_owner_proof_disconnect"
                    )
                }
            }
            let previousProtectedEarlyDisconnects = defaults.integer(
                forKey: Self.protectedR10EarlyDisconnectsKey
            )
            if motionHandshakeDiagnostic == nil,
               protectedActivationWasSent,
               !cleanOwnerProofWasActive,
               !wasUserRequestedDisconnect,
               !atriaOwnedOfflineSyncDisconnect,
               connectedDuration > 0,
               connectedDuration <= Self.protectedR10EarlyDisconnectWindow {
                let early = previousProtectedEarlyDisconnects + 1
                defaults.set(early, forKey: Self.protectedR10EarlyDisconnectsKey)
                AtriaDebugLog("ATRIADBG protected_r10 status=early_disconnect count=%d duration_s=%.1f frames=%d",
                              early, connectedDuration, protectedFrames)
                if Self.shouldLatchProtectedR10RollbackForEarlyDisconnect(
                    activationSent: protectedActivationWasSent,
                    connectedDuration: connectedDuration,
                    previousEarlyDisconnects: previousProtectedEarlyDisconnects
                ) {
                    latchProtectedR10Rollback(reason: "repeated_early_disconnects")
                }
            }
            if motionHandshakeDiagnostic != nil {
                recordMotionHandshakeEvidence(
                    event: "disconnected",
                    detail: String(format: "duration_%.1fs_error_%@", connectedDuration, errorText)
                )
            }
            defaults.set(connectedDuration, forKey: "atria.ble.lastConnectedDuration")
            defaults.set(lastRawHRNotificationAt.map { disconnectNow.timeIntervalSince($0) } ?? -1,
                         forKey: "atria.ble.disconnectRawHRAge")
            defaults.set(lastR10MotionFrameAt.map { disconnectNow.timeIntervalSince($0) } ?? -1,
                         forKey: "atria.ble.disconnectR10Age")
            defaults.set(offlineHistoricalSyncInProgress,
                         forKey: "atria.ble.disconnectOfflineSyncActive")
            defaults.set(wasRealtimeArmedAtDisconnect,
                         forKey: "atria.ble.disconnectRealtimeArmed")
            defaults.set(wasR10RetryActiveAtDisconnect,
                         forKey: "atria.ble.disconnectR10RetryActive")
            defaults.set(disconnectNow.timeIntervalSince1970,
                         forKey: "atria.ble.lastDisconnectDiagnosticAt")
            // Preserve one interrupted full-drain handoff only for a physical
            // loss. `recentAppCancel` covers intentional owner cutovers and
            // watchdog resets; replaying either here would create an extra
            // command/reconnect loop on the following live epoch.
            if Self.shouldRetainInterruptedFullDrainReacquisition(
                fullDrainAuthorityActive: offlineHistoricalSyncInProgress
                    && activeFullDrainEventIdentity != nil,
                userRequestedDisconnect: wasUserRequestedDisconnect,
                recentAppCancel: recentAppCancel
            ) {
                interruptedFullDrainReacquisitionPendingAfterTransportLoss = true
                AtriaDebugLog("ATRIADBG offline_sync status=interrupted_full_drain_transport_loss_retained action=await_fresh_accepted_hr_then_bounded_existing_authority_reacquisition")
            }
            AtriaDebugLog("ATRIADBG ble_link disconnect_cause=%@ this_launch=%d total=%d",
                          disconnectCause,
                          defaults.integer(forKey: LinkDefaults.disconnectsThisLaunch),
                          disconnects)
            let useFreshScan = forceFreshScanAfterDisconnect
            let reconnectPolicy = useFreshScan ? "fresh_scan" : "reconnect_same_peripheral"
            forceFreshScanAfterDisconnect = false
            if wasUserRequestedDisconnect {
                sessionAwaitingUnexpectedReconnect = false
            }
            if atriaOwnedOfflineSyncDisconnect {
                AtriaDebugLog("ATRIADBG official_app_coexistence status=ignored reason=atria_owned_offline_sync_disconnect action=keep_current_risk")
            } else if !wasUserRequestedDisconnect && connectedDuration > 0 && connectedDuration < 90 {
                persistOfficialAppCoexistenceRisk(.suspected, reason: "short_disconnect_after_connect")
            }
            let activeExplicitWorkout = AtriaPendingWorkoutIntent.isActiveForBLEContinuity()
            let shouldPreserveLongWearSession = Self.shouldPreserveSessionOnUnexpectedDisconnect(
                longWearEnabled: longWearModeEnabled,
                activeExplicitWorkout: activeExplicitWorkout,
                userRequestedDisconnect: wasUserRequestedDisconnect
            )
            userRequestedDisconnect = false
            // Firmware bank state dies with the physical BLE connection.
            // Close its durable coverage at this real transport boundary,
            // preserve the desired/prearm intent, and never let either the
            // persisted or process-local bit bridge two connection epochs.
            if workoutHistoricalMotionBankArmed
                || defaults.bool(
                    forKey: Self.workoutHistoricalMotionBankEnabledKey
                ) {
                AtriaWhoop4MotionBankCoverageLedger.close(
                    at: disconnectNow,
                    strapIdentifier: peripheral.identifier.uuidString,
                    armedConnectionStartedAt:
                        workoutHistoricalMotionBankArmedConnectionStartedAt
                            ?? connectedAt
                )
                AtriaMotionBankDutyCycleDiag.note("link_down")
                persistNextUnattemptedMotionBankMaintenanceTicketIfNeeded(
                    strapIdentifier: peripheral.identifier.uuidString,
                    defaults: defaults
                )
                defaults.set(
                    false,
                    forKey: Self.workoutHistoricalMotionBankEnabledKey
                )
                defaults.set(
                    true,
                    forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey
                )
                defaults.removeObject(
                    forKey: Self.workoutHistoricalMotionBankArmedAtKey
                )
                // The process-local armed bit must fall with the connection:
                // a stale `true` short-circuits the 1 Hz accepted-HR prearm on
                // the replacement link and suppresses all-day capture there.
                workoutHistoricalMotionBankArmed = false
                workoutHistoricalMotionBankArmedConnectionStartedAt = nil
                AtriaDebugLog(
                    "ATRIADBG workout_motion_bank status=connection_epoch_closed reason=ble_disconnect at=%.3f action=durable_ticket_rearm_after_fresh_hr",
                    disconnectNow.timeIntervalSince1970
                )
            }
            workoutHistoricalMotionBankArmed = false
            workoutHistoricalMotionBankArmedConnectionStartedAt = nil
            connectedAt = nil
            txCharacteristic = nil
            heartRateCharacteristic = nil
            lastMissingHeartRateDiscoveryAt = nil
            dbgTxReady = false
            interruptOfflineHistoricalSyncForTransportLoss(
                reason: "ble_disconnect"
            )
            // Don't fragment long-wear runs on transient lifecycle/radio drops.
            // The active journal is enough durability for a reconnect; the
            // session should only be finished on explicit stop or long-gap roll.
            var autoSaveStatus = "skipped"
            var autoSaveSamples = session.count
            var autoSaveDuration = 0
            if shouldPreserveLongWearSession {
                sessionAwaitingUnexpectedReconnect = !wasUserRequestedDisconnect
                preserveLongWearRangeLossRecovery(reason: "disconnect")
                autoSaveStatus = session.isEmpty ? "skipped_continuity_empty" : (activeExplicitWorkout
                    ? "checkpointed_explicit_workout_continuity"
                    : "checkpointed_continuity")
                autoSaveDuration = max(0, Int(((session.last?.t ?? sessionStart).timeIntervalSince(sessionStart)).rounded()))
            } else if session.count >= autoSaveMinSamples {
                let label = captureLabel.isEmpty ? "Auto-saved" : captureLabel
                autoSaveStatus = "pending_async_boundary"
                autoSaveDuration = max(0, Int(((session.last?.t ?? sessionStart)
                    .timeIntervalSince(sessionStart)).rounded()))
                Task { @MainActor in
                    let outcome = await finishSession(
                        label: label,
                        reason: "disconnect_auto_save"
                    )
                    let finalStatus = outcome.persisted ? "saved" : "store_failed"
                    let finalSamples = outcome.saved?.points.count ?? session.count
                    let finalDuration = Int((outcome.saved?.duration ?? 0).rounded())
                    let defaults = UserDefaults.standard
                    defaults.set(finalStatus, forKey: LinkDefaults.lastAutoSaveStatus)
                    defaults.set(finalSamples, forKey: LinkDefaults.lastAutoSaveSamples)
                    defaults.set(finalDuration, forKey: LinkDefaults.lastAutoSaveDuration)
                    AtriaDebugLog(
                        "ATRIADBG disconnect_session_boundary status=%@ samples=%d duration_s=%d",
                        finalStatus,
                        finalSamples,
                        finalDuration
                    )
                }
            } else if clearUnsavableActiveJournalIfNeeded(reason: "disconnect_unsavable") {
                autoSaveStatus = "cleared_unsavable"
                autoSaveSamples = session.count
                autoSaveDuration = max(0, Int(((session.last?.t ?? sessionStart).timeIntervalSince(sessionStart)).rounded()))
            }
            defaults.set(autoSaveStatus, forKey: LinkDefaults.lastAutoSaveStatus)
            defaults.set(autoSaveSamples, forKey: LinkDefaults.lastAutoSaveSamples)
            defaults.set(autoSaveDuration, forKey: LinkDefaults.lastAutoSaveDuration)
            AtriaDebugLog("ATRIADBG ble_link status=disconnected reason=did_disconnect error=%@ disconnects=%d autosave=%@ samples=%d duration_s=%d action=%@",
                  errorText,
                  disconnects,
                  autoSaveStatus,
                  autoSaveSamples,
                  autoSaveDuration,
                  reconnectPolicy)
            if self.freshHistoryOwnerCutoverPending {
                self.freshHistoryOwnerCutoverPending = false
                if let pending = self.takePendingOfflineHistoricalSyncRequest() {
                    AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_disconnected reason=%@ force=%d explicit=%d action=reuse_disconnected_history_path",
                                  pending.reason,
                                  pending.force ? 1 : 0,
                                  pending.explicitRequest ? 1 : 0)
                    let started = self.requestOfflineHistoricalSyncIfNeeded(
                        reason: pending.reason,
                        force: pending.force,
                        explicitResearchRequest: pending.explicitRequest,
                        explicitPostWorkoutBankRequest:
                            pending.explicitPostWorkoutBankRequest,
                        preserveConnectedRealtimeOwner:
                            pending.preserveConnectedRealtimeOwner
                    )
                    if started {
                        self.freshHistoryOwnerConnectionGeneration =
                            self.offlineHistoricalSyncGeneration
                        // The nonisolated background reconnect fast lane can
                        // complete before this MainActor block records history
                        // ownership (especially while the phone is locked). In
                        // that ordering didConnect already performed normal HR
                        // discovery and no second callback will arrive. Claim
                        // the connected epoch immediately; otherwise install
                        // the standing connection that will be claimed by
                        // didConnect. Both paths preserve the same generation
                        // fence and issue no history command before notification
                        // readiness is confirmed.
                        if peripheral.state == .connected {
                            self.peripheral = peripheral
                            peripheral.delegate = self
                            _ = self.resumeFreshHistoryOwnerConnectionIfNeeded(
                                peripheral: peripheral
                            )
                        } else if Self.shouldIssueMainActorDisconnectReconnect(
                            synchronousReconnectIssued:
                                synchronousReconnectIssued,
                            peripheralState: peripheral.state
                        ) {
                            peripheral.delegate = self
                            self.issueSingleFlightConnect(
                                peripheral,
                                central: central,
                                reason: "fresh_history_owner_disconnect_followup"
                            )
                        } else if synchronousReconnectIssued {
                            AtriaDebugLog(
                                "ATRIADBG offline_sync status=fresh_owner_generation_preserved generation=%llu action=use_existing_synchronous_reconnect_no_duplicate",
                                self.offlineHistoricalSyncGeneration
                            )
                        }
                        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_generation_preserved generation=%llu action=claim_next_connection_once",
                                      self.offlineHistoricalSyncGeneration)
                        return
                    }
                    if peripheral.state == .connecting {
                        // The background-safe callback installed the reconnect
                        // before this MainActor turn. The request is already
                        // retained by the transaction-boundary guard; consume
                        // it from `didConnect` with the completed-cutover
                        // authority instead of manufacturing another cutover.
                        self.freshHistoryOwnerAdmissionPending = true
                        AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_admission_awaiting_did_connect reason=%@ action=retain_completed_cutover_authority",
                                      pending.reason)
                        return
                    }
                    AtriaDebugLog("ATRIADBG offline_sync status=fresh_owner_admission_failed reason=%@ action=restore_live_once_request_retained",
                                  pending.reason)
                }
            }
            if self.motionHandshakeDiagnostic != nil {
                if self.motionHandshakeLaunchCutoverInProgress {
                    self.motionHandshakeLaunchCutoverInProgress = false
                    self.peripheral = peripheral
                    peripheral.delegate = self
                    self.recordMotionHandshakeEvidence(
                        event: "fresh_connection_requested",
                        detail: "after_controlled_cutover"
                    )
                    self.recordLinkAttempt(
                        reason: "motion_handshake_fresh_connection",
                        peripheral: peripheral
                    )
                    self.issueSingleFlightConnect(
                        peripheral,
                        central: central,
                        reason: "motion_handshake_fresh_connection"
                    )
                    self.recomputeConnectionStatus(reason: "event")
                } else {
                    if self.peripheral === peripheral {
                        self.peripheral = nil
                    }
                    self.recomputeConnectionStatus(reason: "event")
                    self.recordMotionHandshakeEvidence(
                        event: "diagnostic_stopped",
                        detail: "single_connection_complete_no_reconnect"
                    )
                }
                return
            }
            if wasUserRequestedDisconnect {
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                recomputeConnectionStatus(reason: "event")
                AtriaDebugLog("ATRIADBG ble_link status=disconnected reason=user_disconnect action=stay_disconnected")
                return
            }
            // The explicit-workout v8 escape hatch clears the old owner inside
            // its successful cutover. Ordinary standing reconnects reuse this
            // exact CBPeripheral; clearing it before we know a cutover applies
            // produces the proven `connected` callbacks + nil manager owner
            // contradiction on every automatic reconnect.
            if self.completeProtectedR10V8WorkoutCutoverIfNeeded(
                disconnectedPeripheral: peripheral,
                central: central,
                reason: "manual_workout_old_owner_disconnected"
            ) {
                return
            }
            if cleanOwnerProofWasActive && !gate4PassiveReconnectAfterTimeout {
                // The failed physical link is now fully down. Replace its v9
                // central exactly once with the fresh v10 pure-HR namespace;
                // never reconnect or replay commands through the failed owner.
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "event")
                if self.beginProtectedR10PureHRV10InProcessCutoverIfNeeded(
                    disconnectedPeripheral: peripheral,
                    central: central,
                    standingReconnectAlreadyIssued:
                        synchronousReconnectIssued,
                    reason: "proof_disconnect"
                ) {
                    return
                }
                AtriaDebugLog("ATRIADBG protected_r10 status=proof_disconnect_stopped action=v10_cutover_already_consumed_no_loop_no_history")
                return
            }
            if Self.shouldDeferAutomaticHistoryUntilAfterRealtimeReconnect(
                preservesLongWearSession: shouldPreserveLongWearSession,
                rangeLossBackfillPending: defaults.bool(
                    forKey: OfflineSyncDefaults.rangeLossBackfillPending
                )
            ) {
                // A disconnect callback may be the final background execution
                // window iOS grants for hours. Starting the optional history
                // worker here used to return before installing CoreBluetooth's
                // standing reconnect. If that worker was then suspended, neither
                // realtime HR/RR nor R10 motion had an owner to wake the app.
                // Keep the exact missing range durable, reconnect realtime first,
                // and let the already-scheduled foreground/BG maintenance path
                // perform history recovery only after live continuity is safe.
                AtriaDebugLog("ATRIADBG offline_sync status=deferred reason=disconnect_realtime_first pending=1 explicit_workout=%d action=install_standing_reconnect",
                              activeExplicitWorkout ? 1 : 0)
            }
            if synchronousReconnectIssued {
                // The delegate fast lane already installed the one standing
                // request. CoreBluetooth may still report `.disconnected`
                // until after this MainActor turn, so state cannot be used to
                // infer that another connect is needed.
                recordLinkAttempt(
                    reason: "did_disconnect_reconnect",
                    peripheral: peripheral
                )
                markPendingKnownReconnect(
                    reason: "did_disconnect_reconnect"
                )
                startReconnectWatchdog(
                    reason: "did_disconnect_reconnect",
                    peripheral: peripheral
                )
                recomputeConnectionStatus(reason: "event")
                AtriaDebugLog(
                    "ATRIADBG ble_link status=reconnect_preserved reason=did_disconnect_background_safe action=single_synchronous_request_no_mainactor_duplicate"
                )
                return
            }
            if useFreshScan {
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                recomputeConnectionStatus(reason: "event")
                let freshReason = longWearModeEnabled ? "long_wear_disconnect" : "stale_data_recovery"
                // Even on a forced fresh recovery, prefer a standing pending connect
                // to the KNOWN strap over scanning — it reconnects without giving up.
                if reconnectToSavedPeripheralIfPossible(reason: "\(freshReason)_known_strap") {
                    return
                }
                AtriaDebugLog("ATRIADBG ble_link status=disconnected reason=%@ action=fresh_scan",
                      freshReason)
                startScan(reason: freshReason)
                return
            }
            // Auto-reconnect: keep the strap connected as it moves in/out of range.
            recordLinkAttempt(reason: "did_disconnect_reconnect", peripheral: peripheral)
            markPendingKnownReconnect(reason: "did_disconnect_reconnect")
            if Self.shouldIssueMainActorDisconnectReconnect(
                synchronousReconnectIssued: synchronousReconnectIssued,
                peripheralState: peripheral.state
            ) {
                self.issueSingleFlightConnect(
                    peripheral,
                    central: central,
                    reason: "did_disconnect_reconnect"
                )
            } else {
                AtriaDebugLog("ATRIADBG ble_link status=reconnect_preserved reason=did_disconnect_background_safe peripheral_state=%d action=keep_existing_standing_request",
                              peripheral.state.rawValue)
            }
            startReconnectWatchdog(reason: "did_disconnect_reconnect", peripheral: peripheral)
            recomputeConnectionStatus(reason: "event")
        }
    }

    nonisolated func centralManager(_ central: CBCentralManager,
                        didFailToConnect peripheral: CBPeripheral,
                        error: Error?) {
        guard let centralToken = centralEventFence.capture(central) else {
            AtriaDebugLog("ATRIADBG ble_central status=callback_rejected reason=retired_manager callback=did_fail_to_connect")
            return
        }
        let terminalAdmission =
            connectedPeripheralRetainer.beginTerminalCallback(peripheral)
        if terminalAdmission == .ignorePassiveDuplicate {
            peripheral.delegate = nil
            connectedPeripheralRetainer.release(peripheral)
            AtriaDebugLog("ATRIADBG ble_epoch status=stale_terminal_callback_ignored callback=did_fail_to_connect reason=active_same_uuid_twin peripheral=%@",
                          peripheral.identifier.uuidString)
            return
        }
        let failedCallbackEpoch = bleCallbackEpochFence.epoch
        proprietaryFrameReassembler.reset()
        let savedPeripheralIdentifier = UserDefaults.standard
            .string(forKey: LinkDefaults.savedPeripheralUUID)
            .flatMap(UUID.init(uuidString:))
        let terminalHistoryPhase = historyTransportPhaseFence.snapshot()
        var fastLaneDisposition = backgroundReconnectFence.consumeDisposition(
            peripheralID: peripheral.identifier,
            continuousCaptureWanted: heartRateCaptureIntent.snapshot(),
            historyTransportActive: terminalHistoryPhase.isActive,
            activeHistoryTransportGeneration:
                terminalHistoryPhase.generation,
            diagnosticActive: motionHandshakeDiagnostic != nil
        )
        if case let .reconnectRealtimeAfterHistoryRelease(generation) =
            fastLaneDisposition,
           !historyTransportPhaseFence.retireForRealtimeRestore(
            ifMatching: generation,
            peripheralID: peripheral.identifier
           ) {
            fastLaneDisposition =
                historyTransportPhaseFence.snapshot().isActive
                    ? .suppressHistoryOwner
                    : .reconnectRealtime
        }
        let synchronousReconnectIssued = Self
            .shouldSynchronouslyReconnectAfterFailedConnect(
                disposition: fastLaneDisposition,
                failedPeripheralIsSaved:
                    savedPeripheralIdentifier == peripheral.identifier,
                peripheralIsDisconnected: peripheral.state == .disconnected
            )
            && !Self.isPeerRemovedPairingError(error)
        if synchronousReconnectIssued,
           centralEventFence.accepts(centralToken, central: central) {
            // A locked/background failure callback may be the last execution
            // slice before suspension. Reinstall the standing request before
            // yielding to MainActor so return-to-range can wake Atria.
            peripheral.delegate = self
            issueSingleFlightConnect(
                peripheral,
                central: central,
                reason: "did_fail_to_connect_background_safe"
            )
            AtriaDebugLog(
                "ATRIADBG ble_link status=reconnect_requested_sync reason=did_fail_to_connect_background_safe peripheral=%@",
                peripheral.identifier.uuidString
            )
        } else {
            // No replacement request owns this object. It is now safe to
            // release this exact failed CoreBluetooth instance. A different
            // same-UUID object may already own the live link.
            connectedPeripheralRetainer.release(peripheral)
        }
        Task { @MainActor in
            guard self.centralEventFence.accepts(
                centralToken,
                central: central
            ), Self.acceptsFailedConnectCallback(
                trackedPeripheralIsFailedInstance:
                    self.peripheral === peripheral,
                trackedPeripheralIsAbsent: self.peripheral == nil,
                synchronousReconnectIssued: synchronousReconnectIssued,
                callbackEpochIsCurrent:
                    self.bleCallbackEpochFence.epoch == failedCallbackEpoch
            ) else {
                AtriaDebugLog("ATRIADBG ble_epoch status=stale_connect_failure_ignored peripheral=%@",
                              peripheral.identifier.uuidString)
                return
            }
            if synchronousReconnectIssued {
                self.peripheral = peripheral
                peripheral.delegate = self
            }
            self.endBackgroundReconnectLease(reason: "connect_failed")
            self.writeCompletionLedger.reset()
            reconnectWatchdogTask?.cancel()
            freshScanFallbackTask?.cancel()
            freshScanFallbackTask = nil
            recordLinkFailure(reason: "did_fail_to_connect", error: error)
            connectedAt = nil
            self.realtimeArmed = false
            self.r10ArmRetryTask?.cancel()
            self.stopProtocolHeartbeat()
            self.proprietaryNotifyFallbackTask?.cancel()
            self.proprietaryNotifyFallbackTask = nil
            self.activeProprietaryNotifyUUIDs.removeAll()
            self.strapStream5NotifyConfirmed = false
            self.protectedR10InitialProfilePeripheralID = nil
            self.protectedR10InitialProfileNotificationRequested = false
            self.txCharacteristic = nil
            self.heartRateCharacteristic = nil
            self.lastMissingHeartRateDiscoveryAt = nil
            self.dbgTxReady = false
            if self.motionHandshakeDiagnostic != nil {
                self.motionHandshakeLaunchCutoverInProgress = false
                self.motionHandshakeCommandSequenceTask?.cancel()
                self.motionHandshakeCommandSequenceTask = nil
                self.motionHandshakeProfileCharacteristics.removeAll()
                self.motionHandshakeRequestedNotifyUUIDs.removeAll()
                self.motionHandshakeConfirmedNotifyUUIDs.removeAll()
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "event")
                self.recordMotionHandshakeEvidence(
                    event: "diagnostic_stopped",
                    detail: "fresh_connection_failed_no_retry"
                )
                return
            }
            if self.protectedR10CleanOwner == .protectedV9,
               (self.protectedR10CleanOwnerState == .protectedLaunchPending
                || self.protectedR10CleanOwnerState == .proving) {
                self.persistProtectedR10CleanOwnerFallback(
                    reason: "response_event_data_connect_failed"
                )
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "event")
                if self.beginProtectedR10PureHRV10InProcessCutoverIfNeeded(
                    disconnectedPeripheral: peripheral,
                    central: central,
                    standingReconnectAlreadyIssued:
                        synchronousReconnectIssued,
                    reason: "v9_connect_failed"
                ) {
                    return
                }
                AtriaDebugLog("ATRIADBG protected_r10 status=connect_failed owner=v9 action=v10_cutover_already_consumed_no_loop")
                return
            }
            if synchronousReconnectIssued {
                // The delegate lane already installed the sole replacement
                // request. A failed request can still sample `.disconnected`
                // on this MainActor turn; scheduling the ordinary delayed
                // recovery as well would recreate the same two-request loop as
                // didDisconnect.
                self.peripheral = peripheral
                peripheral.delegate = self
                self.recordLinkAttempt(
                    reason: "did_fail_to_connect_reconnect",
                    peripheral: peripheral
                )
                self.markPendingKnownReconnect(
                    reason: "did_fail_to_connect_reconnect"
                )
                self.startReconnectWatchdog(
                    reason: "did_fail_to_connect_reconnect",
                    peripheral: peripheral
                )
                self.recomputeConnectionStatus(reason: "event")
                AtriaDebugLog(
                    "ATRIADBG ble_link status=reconnect_preserved reason=did_fail_to_connect_background_safe action=single_synchronous_request_no_delayed_duplicate"
                )
                return
            }
            switch fastLaneDisposition {
            case .reconnectRealtime:
                break
            case .reconnectRealtimeAfterHistoryRelease:
                // The delegate slice already installed the only replacement
                // request permitted for this interrupted generation. Do not
                // let delayed MainActor recovery add a scan or second connect.
                if synchronousReconnectIssued {
                    self.peripheral = peripheral
                    peripheral.delegate = self
                } else if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "event")
                return
            case .suppressHistoryOwner:
                self.interruptOfflineHistoricalSyncForTransportLoss(
                    reason: "history_owner_connect_failed"
                )
                self.recomputeConnectionStatus(reason: "event")
                return
            case .suppressAppOwnedCancellation,
                 .suppressDiagnostic,
                 .suppressCaptureInactive:
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "event")
                AtriaDebugLog(
                    "ATRIADBG ble_link status=connect_failure_retry_suppressed reason=%@ peripheral=%@",
                    String(describing: fastLaneDisposition),
                    peripheral.identifier.uuidString
                )
                return
            }
            let savedUUID = UserDefaults.standard.string(forKey: LinkDefaults.savedPeripheralUUID)
                .flatMap(UUID.init(uuidString:))
            if Self.isPeerRemovedPairingError(error) {
                UserDefaults.standard.removeObject(
                    forKey: LinkDefaults.savedPeripheralUUID
                )
                self.clearPendingKnownReconnect(reason: "peer_removed_pairing")
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "peer_removed_pairing")
                AtriaDebugLog("ATRIADBG ble_link status=stale_bond_removed reason=peer_removed_pairing action=scan_for_fresh_identity data_preserved=1")
                self.startScan(reason: "peer_removed_pairing")
                return
            }
            let disposition = Self.failedConnectRecoveryDisposition(
                isSavedPeripheral: savedUUID == peripheral.identifier,
                isActuallyConnecting: peripheral.state == .connecting)
            switch disposition {
            case .reconnectKnownAfterBackoff:
                self.peripheral = peripheral
                peripheral.delegate = self
                self.recomputeConnectionStatus(reason: "event")
                self.requestFreshScanReconnect(peripheral: peripheral,
                                               reason: "did_fail_to_connect_recovery")
            case .waitForExistingConnect:
                self.peripheral = peripheral
                peripheral.delegate = self
                self.recomputeConnectionStatus(reason: "event")
                AtriaDebugLog("ATRIADBG ble_link status=failed reason=did_fail_to_connect action=wait_existing_connect")
            case .scan:
                if self.peripheral === peripheral {
                    self.peripheral = nil
                }
                self.recomputeConnectionStatus(reason: "event")
                self.startScan(reason: "did_fail_to_connect_recovery")
            }
        }
    }
}

// MARK: - CBPeripheralDelegate
extension AtriaBLEManager: CBPeripheralDelegate {
    nonisolated func peripheral(_ peripheral: CBPeripheral, didDiscoverServices error: Error?) {
        guard let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else {
            AtriaDebugLog("ATRIADBG ble_discovery status=ignored reason=stale_service_callback epoch=%llu peripheral=%@",
                          bleCallbackEpochFence.epoch,
                          peripheral.identifier.uuidString)
            return
        }
        let callbackEpoch = callbackSource.epoch
        let fastLaneDefaults = UserDefaults.standard
        fastLaneDefaults.set("did_discover_services",
                             forKey: BackgroundHRDiscoveryDefaults.stage)
        fastLaneDefaults.set(Date().timeIntervalSince1970,
                             forKey: BackgroundHRDiscoveryDefaults.at)
        fastLaneDefaults.set(callbackEpoch,
                             forKey: BackgroundHRDiscoveryDefaults.epoch)
        if let error {
            fastLaneDefaults.set(error.localizedDescription,
                                 forKey: BackgroundHRDiscoveryDefaults.error)
        } else {
            fastLaneDefaults.removeObject(forKey: BackgroundHRDiscoveryDefaults.error)
        }
        if let error {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                let capabilityDisposition = Self
                    .historyCapabilityQualificationCallbackDisposition(
                        callbackMatchesQualification:
                            self.historyCapabilityQualificationPeripheralID
                                == peripheral.identifier,
                        targetedDiscoveryIssued:
                            self.historyCapabilityQualificationDiscoveryIssued,
                        hasStrapService: false,
                        hasError: true
                    )
                if capabilityDisposition == .terminalFailure,
                   self.clearHistoryCapabilityQualification(
                       ifMatching: peripheral.identifier
                   ) {
                    self.releaseConnectedMotionBankLocalDependencyFirstRefusal(
                        reason: "history_capability_discovery_error",
                        expectedDependency: .capabilityQualification
                    )
                    AtriaDebugLog(
                        "ATRIADBG history_capability status=qualification_failed reason=service_discovery_error peripheral=%@ action=rearm_present_capture_no_attempt_no_generation_no_history_command_no_cancel",
                        peripheral.identifier.uuidString
                    )
                }
                if self.protectedR10CleanOwner == .protectedV9,
                   (self.protectedR10CleanOwnerState == .protectedLaunchPending
                    || self.protectedR10CleanOwnerState == .proving) {
                    self.persistProtectedR10CleanOwnerFallback(
                        reason: "response_event_data_service_discovery_error_\(error.localizedDescription)"
                    )
                }
            }
            return
        }
        let serviceUUIDs = (peripheral.services ?? []).map(\.uuid)
        let connectionEvidence: FirstUseConnectionEvidence =
            serviceUUIDs.contains(Self.UUIDs.strapService)
                ? .whoopService
                : .provisionalConnection
        Task { @MainActor in
            guard self.acceptsBLECallback(
                source: callbackSource,
                peripheral: peripheral
            ) else { return }
            self.recordLinkObservedConnected(
                reason: "service_discovery",
                peripheral: peripheral,
                callbackSource: callbackSource,
                evidence: connectionEvidence
            )
        }
        let workoutBankTransportRequested =
            Self.workoutBankTransportCurrentlyRequested(fastLaneDefaults)
        let callbackPolicy = callbackPolicyState.snapshot()
        let strapDiscoveryOwner = Self.resolveStrapDiscoveryOwner(
            historyRecoveryActive: historyOnlyProbeMode,
            diagnosticActive: motionHandshakeDiagnostic != nil,
            standardHROnlyMode: callbackPolicy.standardHROnly,
            protectedV9Owner: protectedR10CleanOwner == .protectedV9,
            launchOrProofActive: protectedR10CleanOwnerState == .protectedLaunchPending
                || protectedR10CleanOwnerState == .proving,
            workoutBankTransportRequested: workoutBankTransportRequested
        )
        let resolvedServiceOwnerEdge =
            "service_owner_resolved_\(strapDiscoveryOwner.rawValue)"
        Task { @MainActor in
            self.recordProtectedV9BringUpEdge(resolvedServiceOwnerEdge)
        }
        for service in peripheral.services ?? [] {
            let characteristics: [CBUUID]?
            if motionHandshakeDiagnostic != nil {
                switch service.uuid {
                case Self.UUIDs.strapService:
                    if motionHandshakeDiagnostic?.useResponseEventDataProfile == true {
                        characteristics = [Self.UUIDs.strapRX,
                                           Self.UUIDs.strapStream4,
                                           Self.UUIDs.strapStream5,
                                           Self.UUIDs.strapTX]
                    } else {
                        characteristics = motionHandshakeDiagnostic?.sendSingleR10Activation == true
                            ? [Self.UUIDs.strapStream5, Self.UUIDs.strapTX]
                            : [Self.UUIDs.strapStream5]
                    }
                case Self.UUIDs.heartRateService:
                    characteristics = [Self.UUIDs.heartRateMeasure]
                default:
                    characteristics = nil
                }
            } else if callbackPolicy.onboardingPairingPreflight,
                      service.uuid == Self.UUIDs.strapService {
                // Pairing preflight needs only the command characteristic. It
                // deliberately subscribes to no history stream.
                characteristics = [Self.UUIDs.strapTX]
            } else if historyOnlyProbeMode {
                switch service.uuid {
                case Self.UUIDs.strapService:
                    let diagnosticStopsRealtime = Self
                        .shouldStopRealtimeBeforeHistoricalRecovery(
                            diagnosticSelectorOrRangeProbe:
                                !callbackPolicy.historySkipsDataRange
                        )
                    let requiredNotifications = diagnosticStopsRealtime
                        ? Self.UUIDs.allNotify
                        : requiredProductionHistoryNotifications
                    characteristics = [Self.UUIDs.strapTX] + requiredNotifications
                case Self.UUIDs.heartRateService:
                    // Standard 2A37 remains a completely separate callback
                    // path from proprietary RX/stream5 history parsing.
                    characteristics = [Self.UUIDs.heartRateMeasure]
                case Self.UUIDs.batteryService:
                    characteristics = [Self.UUIDs.batteryLevel]
                default:
                    characteristics = nil
                }
            } else if strapDiscoveryOwner == .protectedV9BringUp {
                // A pending/proving v9 bring-up owns strap discovery even when
                // the workout bank holds a durable request — the requalifier
                // exists exactly when a workout is running (2026-08-13 stall).
                if service.uuid == Self.UUIDs.strapService {
                    characteristics = callbackPolicy.protectedProfileIsEmpty
                        ? Self.protectedStandardHRCharacteristics(
                            for: service.uuid,
                            streamSuppressed: protectedR10StreamSuppressed,
                            cleanOwner: protectedR10CleanOwner
                        )
                        : nil
                } else if callbackPolicy.protectedStandardDiscoveryStarted {
                    characteristics = Self.protectedStandardHRCharacteristics(
                        for: service.uuid,
                        streamSuppressed: protectedR10StreamSuppressed,
                        cleanOwner: protectedR10CleanOwner
                    )
                } else {
                    characteristics = nil
                }
            } else if strapDiscoveryOwner == .workoutBank,
                      service.uuid == Self.UUIDs.strapService {
                var requested = Self.protectedStandardHRCharacteristics(
                    for: service.uuid,
                    streamSuppressed: protectedR10StreamSuppressed,
                    cleanOwner: protectedR10CleanOwner
                ) ?? []
                if !requested.contains(Self.UUIDs.strapTX) {
                    requested.append(Self.UUIDs.strapTX)
                }
                characteristics = requested
            } else if callbackPolicy.standardHROnly, !historyOnlyProbeMode {
                if gate4HistoricalIMUWindowProbeRequested,
                   service.uuid == Self.UUIDs.strapService {
                    characteristics = [Self.UUIDs.strapTX]
                } else {
                    characteristics = Self.protectedStandardHRCharacteristics(
                        for: service.uuid,
                        streamSuppressed: protectedR10StreamSuppressed,
                        cleanOwner: protectedR10CleanOwner
                    )
                }
            } else {
                characteristics = Self.discoveryCharacteristics(for: service.uuid)
            }
            guard let characteristics else { continue }
            if service.uuid == Self.UUIDs.strapService {
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    if self.strapModel == .unknown, !self.debugForceUnknownStrapGeneration {
                        self.strapModel = .strap4Class
                        AtriaDebugLog("ATRIADBG model_gate status=assume_4_class reason=proprietary_service service=%@", service.uuid.uuidString)
                    }
                }
            }
            guard bleCallbackEpochFence.accepts(
                source: callbackSource,
                peripheralConnected: peripheral.state == .connected
            ) else {
                AtriaDebugLog("ATRIADBG ble_discovery status=aborted reason=stale_service_task callback=%llu current=%llu",
                              callbackSource.epoch,
                              bleCallbackEpochFence.epoch)
                return
            }
            peripheral.discoverCharacteristics(characteristics, for: service)
        }
        // A strap that attached via name/HR-service matching but does NOT expose
        // the 4.0-class 61080001 service is likely newer hardware (5.0/MG). It must
        // surface as unknown — never silently inherit strap4Class capabilities.
        Task { @MainActor in
            guard self.acceptsBLECallback(
                source: callbackSource,
                peripheral: peripheral
            ) else { return }
            self.handleHistoryCapabilityServiceDiscovery(
                peripheral: peripheral,
                serviceUUIDs: serviceUUIDs
            )
        }
        if !serviceUUIDs.contains(Self.UUIDs.strapService) {
            let serviceList = serviceUUIDs.map(\.uuidString).joined(separator: ",")
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                if self.strapModel == .unknown {
                    AtriaDebugLog("ATRIADBG model_gate status=unrecognized_service reason=no_4_class_service services=%@", serviceList)
                }
            }
        }
    }

    nonisolated func peripheral(_ peripheral: CBPeripheral,
                    didDiscoverCharacteristicsFor service: CBService, error: Error?) {
        guard let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else {
            AtriaDebugLog("ATRIADBG ble_discovery status=ignored reason=stale_characteristic_callback epoch=%llu peripheral=%@ service=%@",
                          bleCallbackEpochFence.epoch,
                          peripheral.identifier.uuidString,
                          service.uuid.uuidString)
            return
        }
        let callbackEpoch = callbackSource.epoch
        let fastLaneDefaults = UserDefaults.standard
        fastLaneDefaults.set("did_discover_characteristics_\(service.uuid.uuidString)",
                             forKey: BackgroundHRDiscoveryDefaults.stage)
        fastLaneDefaults.set(Date().timeIntervalSince1970,
                             forKey: BackgroundHRDiscoveryDefaults.at)
        fastLaneDefaults.set(callbackEpoch,
                             forKey: BackgroundHRDiscoveryDefaults.epoch)
        if let error {
            fastLaneDefaults.set(error.localizedDescription,
                                 forKey: BackgroundHRDiscoveryDefaults.error)
        } else {
            fastLaneDefaults.removeObject(forKey: BackgroundHRDiscoveryDefaults.error)
        }
        let discoveredStandardHeartRateMeasurement = error == nil
            && service.uuid == Self.UUIDs.heartRateService
            && (service.characteristics ?? []).contains {
                $0.uuid == Self.UUIDs.heartRateMeasure
            }
        if discoveredStandardHeartRateMeasurement {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                self.recordLinkObservedConnected(
                    reason: "standard_2a37_discovery",
                    peripheral: peripheral,
                    callbackSource: callbackSource,
                    evidence: .standardHeartRateMeasurement
                )
            }
        }
        if motionHandshakeDiagnostic != nil {
            let characteristics = service.characteristics ?? []
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                if let tx = characteristics.first(where: {
                    $0.uuid == Self.UUIDs.strapTX
                }), self.motionHandshakeDiagnostic?.sendSingleR10Activation == true
                    || self.motionHandshakeDiagnostic?.sendR10IMUSequence == true {
                    self.txCharacteristic = tx
                    self.recordMotionHandshakeEvidence(
                        event: "activation_tx_discovered",
                        detail: "write_without_response_\(tx.properties.contains(.writeWithoutResponse) ? 1 : 0)"
                    )
                }
                if let heartRate = characteristics.first(where: {
                    $0.uuid == Self.UUIDs.heartRateMeasure
                }) {
                    self.heartRateCharacteristic = heartRate
                    self.recordMotionHandshakeEvidence(
                        event: "hr_characteristic_discovered"
                    )
                    if heartRate.properties.contains(.notify), !heartRate.isNotifying {
                        peripheral.setNotifyValue(true, for: heartRate)
                    } else if heartRate.isNotifying {
                        self.handleMotionHandshakeNotificationState(
                            peripheral: peripheral,
                            characteristic: heartRate,
                            error: nil
                        )
                    }
                }
                if service.uuid == Self.UUIDs.strapService {
                    self.beginMotionHandshakeNotificationProfile(
                        peripheral: peripheral,
                        characteristics: characteristics
                    )
                }
            }
            return
        }
        let workoutBankTransportRequested =
            Self.workoutBankTransportCurrentlyRequested(fastLaneDefaults)
        let callbackPolicy = callbackPolicyState.snapshot()
        let strapDiscoveryOwner = Self.resolveStrapDiscoveryOwner(
            historyRecoveryActive: historyOnlyProbeMode,
            diagnosticActive: motionHandshakeDiagnostic != nil,
            standardHROnlyMode: callbackPolicy.standardHROnly,
            protectedV9Owner: protectedR10CleanOwner == .protectedV9,
            launchOrProofActive: protectedR10CleanOwnerState == .protectedLaunchPending
                || protectedR10CleanOwnerState == .proving,
            workoutBankTransportRequested: workoutBankTransportRequested
        )
        if service.uuid == Self.UUIDs.strapService {
            let resolvedCharacteristicOwnerEdge =
                "characteristic_owner_resolved_\(strapDiscoveryOwner.rawValue)"
            Task { @MainActor in
                self.recordProtectedV9BringUpEdge(resolvedCharacteristicOwnerEdge)
            }
        }
        // The bank's durable request no longer vetoes the v9 profile: the
        // resolver already ranked them (2026-08-13 priority-inversion fix).
        if service.uuid == Self.UUIDs.strapService,
           strapDiscoveryOwner == .protectedV9BringUp {
            let characteristics = service.characteristics ?? []
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                self.beginProtectedR10ResponseEventDataProfile(
                    peripheral: peripheral,
                    characteristics: characteristics,
                    error: error
                )
            }
            return
        }
        var foundTX: CBCharacteristic?
        var foundHeartRateCharacteristic: CBCharacteristic?
        var foundBatteryLevelCharacteristic: CBCharacteristic?
        var foundBatteryStatusCharacteristic: CBCharacteristic?
        var radioCounters: [(key: String, reason: String)] = []
        var skippedCustomNotify = false
        var usedStandardHROnly = false
        var requestedCustomNotifyCount = 0
        var passiveR10AlreadyNotifying = false
        var protectedStream5NeedingInitialSubscribe: CBCharacteristic?
        let requiredHistoryNotifications: Set<CBUUID>? = historyOnlyProbeMode
            ? Set(Self.shouldStopRealtimeBeforeHistoricalRecovery(
                diagnosticSelectorOrRangeProbe:
                    !callbackPolicy.historySkipsDataRange
            ) ? Self.UUIDs.allNotify : requiredProductionHistoryNotifications)
            : nil
        let discoveryUsesProtectedStandardHR = Self.discoveryShouldUseProtectedStandardHR(
            standardSnapshot: callbackPolicy.standardHROnly,
            historyOnlyProbeMode: historyOnlyProbeMode
        )
        let alreadyActiveProprietaryNotifications = discoveryUsesProtectedStandardHR
            ? Set<CBUUID>()
            : Self.alreadyActiveProprietaryNotifications(
                (service.characteristics ?? []).map { ($0.uuid, $0.isNotifying) }
            )
        for ch in service.characteristics ?? [] {
            if ch.uuid == Self.UUIDs.strapRX,
               UserDefaults.standard.bool(forKey: BatteryDefaults.proprietaryRefreshPending) {
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    self.handleProprietaryBatteryResponseCharacteristic(ch,
                                                                        peripheral: peripheral)
                }
                continue
            }
            switch ch.uuid {
            case UUIDs.heartRateMeasure, UUIDs.batteryLevel, UUIDs.batteryLevelStatus:
                if ch.properties.contains(.notify) || ch.properties.contains(.indicate) {
                    if ch.uuid == UUIDs.heartRateMeasure {
                        // Do the first CCCD enable on the delegate queue. When a
                        // locked return-to-range callback is our final execution
                        // slice, hopping to MainActor first can strand the link
                        // connected with isNotifying=false indefinitely.
                        let supportsNotifications = ch.properties.contains(.notify)
                            || ch.properties.contains(.indicate)
                        let requestedSynchronously = Self.shouldSynchronouslyEnableDiscoveredHeartRateNotification(
                            continuousCaptureWanted: heartRateCaptureIntent.snapshot(),
                            supportsNotifications: supportsNotifications,
                            isNotifying: ch.isNotifying
                        )
                        if requestedSynchronously,
                           bleCallbackEpochFence.accepts(
                            source: callbackSource,
                            peripheralConnected: peripheral.state == .connected
                           ) {
                            peripheral.setNotifyValue(true, for: ch)
                            fastLaneDefaults.set("discovered_2a37_notify_requested",
                                                 forKey: BackgroundHRDiscoveryDefaults.stage)
                            fastLaneDefaults.set(false,
                                                 forKey: BackgroundHRDiscoveryDefaults.notifying)
                            AtriaDebugLog("ATRIADBG ble_notify_enable status=requested_sync reason=heart_rate_characteristic_discovered_background_safe")
                        }
                        // Sparse duty cycle keeps HR notify OFF across reconnects.
                        // The independent 2A19 subscription remains safe to keep.
                        Task { @MainActor in
                            guard self.acceptsBLECallback(
                                source: callbackSource,
                                peripheral: peripheral
                            ) else { return }
                            if self.dutyCycleState != .sparseSentinel {
                                if !ch.isNotifying,
                                   !requestedSynchronously {
                                    _ = self.requestHeartRateNotificationEnableIfNeeded(
                                        peripheral: peripheral,
                                        characteristic: ch,
                                        reason: "heart_rate_characteristic_discovered"
                                    )
                                }
                            } else {
                                AtriaDebugLog("ATRIADBG duty_cycle action=skip_hr_notify_subscribe reason=reconnect_sparse")
                            }
                        }
                    }
                }
                if ch.uuid == UUIDs.batteryLevel || ch.uuid == UUIDs.batteryLevelStatus {
                    if ch.uuid == UUIDs.batteryLevel {
                        foundBatteryLevelCharacteristic = ch
                    } else {
                        foundBatteryStatusCharacteristic = ch
                    }
                }
                if ch.uuid == UUIDs.heartRateMeasure {
                    foundHeartRateCharacteristic = ch
                }
            case UUIDs.manufacturerName, UUIDs.modelNumber,
                 UUIDs.firmwareRevision, UUIDs.hardwareRevision:
                if bleCallbackEpochFence.accepts(
                    source: callbackSource,
                    peripheralConnected: peripheral.state == .connected
                ) {
                    peripheral.readValue(for: ch)
                }
            case UUIDs.strapTX:
                if discoveryUsesProtectedStandardHR,
                   !protectedR10StreamSuppressed
                    || gate4HistoricalIMUWindowProbeRequested
                    || workoutBankTransportRequested {
                    foundTX = ch
                    usedStandardHROnly = true
                } else if discoveryUsesProtectedStandardHR {
                    usedStandardHROnly = true
                    radioCounters.append((RadioDefaults.txSkipped, "protected_r10_rollback"))
                } else {
                    foundTX = ch
                }
            default:
                if discoveryUsesProtectedStandardHR,
                   !protectedR10StreamSuppressed,
                   ch.uuid == Self.UUIDs.strapStream5,
                   ch.properties.contains(.notify) {
                    if !ch.isNotifying {
                        protectedStream5NeedingInitialSubscribe = ch
                    } else {
                        passiveR10AlreadyNotifying = true
                    }
                } else if discoveryUsesProtectedStandardHR, UUIDs.allNotify.contains(ch.uuid) {
                    // Do not mutate proprietary CCCDs while protecting 2A37.
                    // Enabling stream 5 and later disabling the restored
                    // subscription both caused repeated physical disconnects.
                    // A fresh restoration namespace plus an ingest guard below
                    // leaves these characteristics entirely untouched.
                    skippedCustomNotify = true
                    radioCounters.append((RadioDefaults.customNotifySkipped, "standard_hr_only"))
                } else if UUIDs.allNotify.contains(ch.uuid),
                   ch.properties.contains(.notify) {
                    if let requiredHistoryNotifications,
                       !requiredHistoryNotifications.contains(ch.uuid) {
                        // Do not mutate unrelated proprietary CCCDs merely
                        // because CoreBluetooth retained them in the service's
                        // characteristic cache from a prior connection.
                        AtriaDebugLog("ATRIADBG historyOnly status=notify_skipped ch=%@ reason=not_required_for_production_full_drain action=keep_2a37_primary",
                                      ch.uuid.uuidString)
                    } else if !ch.isNotifying,
                              bleCallbackEpochFence.accepts(
                                source: callbackSource,
                                peripheralConnected: peripheral.state == .connected
                              ) {
                        peripheral.setNotifyValue(true, for: ch)
                        requestedCustomNotifyCount += 1
                        radioCounters.append((RadioDefaults.customNotifyEnabled, "full_protocol"))
                    }
                }
            }
        }
        if foundBatteryLevelCharacteristic != nil || foundBatteryStatusCharacteristic != nil {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                if let foundBatteryLevelCharacteristic {
                    self.batteryLevelCharacteristic = foundBatteryLevelCharacteristic
                }
                if let foundBatteryStatusCharacteristic {
                    self.batteryStatusCharacteristic = foundBatteryStatusCharacteristic
                    self.ensureBatteryStatusNotificationForCurrentEpoch(
                        peripheral: peripheral,
                        characteristic: foundBatteryStatusCharacteristic,
                        reason: "battery_characteristic_discovered"
                    )
                    self.requestBatteryStatusReadForCurrentEpoch(
                        peripheral: peripheral,
                        characteristic: foundBatteryStatusCharacteristic,
                        reason: "battery_characteristic_discovered"
                    )
                }
                if foundBatteryLevelCharacteristic != nil {
                    self.requestStrapStatusRead(reason: "battery_characteristic_discovered")
                }
            }
        }
        // Set the command characteristic and request realtime HR + RR intervals
        // (the HRV source) in ONE task, so tx is assigned before we send. Verified
        // command: [0x23, seq, 0x03, 0x01] → CMD_RESP ack → REALTIME_DATA stream.
        if foundTX != nil || foundHeartRateCharacteristic != nil || !radioCounters.isEmpty || requestedCustomNotifyCount > 0 || protectedStream5NeedingInitialSubscribe != nil || !alreadyActiveProprietaryNotifications.isEmpty || passiveR10AlreadyNotifying || skippedCustomNotify || usedStandardHROnly {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                if let heartRateCharacteristic = foundHeartRateCharacteristic {
                    self.heartRateCharacteristic = heartRateCharacteristic
                    self.lastMissingHeartRateDiscoveryAt = nil
                    self.scheduleDebugMissingHeartRateCharacteristicAfterDiscoveryIfNeeded()
                    if heartRateCharacteristic.isNotifying {
                        self.beginProtectedR10BringUpForCurrentEpoch(
                            peripheral: peripheral,
                            reason: "2a37_already_active"
                        )
                    } else if self.denseBringUpIsWanted {
                        _ = self.requestHeartRateNotificationEnableIfNeeded(
                            peripheral: peripheral,
                            characteristic: heartRateCharacteristic,
                            reason: "dense_hr_first_characteristic_discovered"
                        )
                    }
                }
                if usedStandardHROnly {
                    self.dbgLast = "standard hr only"
                } else if skippedCustomNotify {
                    self.dbgLast = "skipped custom notify"
                }
                if requestedCustomNotifyCount > 0 {
                    self.dbgSubsReq += requestedCustomNotifyCount
                }
                if let protectedStream5NeedingInitialSubscribe {
                    self.requestProtectedR10InitialProfileNotificationIfAllowed(
                        protectedStream5NeedingInitialSubscribe,
                        peripheral: peripheral
                    )
                }
                if !alreadyActiveProprietaryNotifications.isEmpty {
                    self.activeProprietaryNotifyUUIDs.formUnion(alreadyActiveProprietaryNotifications)
                    self.strapStream5NotifyConfirmed = alreadyActiveProprietaryNotifications.contains(Self.UUIDs.strapStream5)
                    AtriaDebugLog("ATRIADBG ble_restore_notifications status=seeded active=%d stream5=%d",
                                  self.activeProprietaryNotifyUUIDs.count,
                                  self.strapStream5NotifyConfirmed ? 1 : 0)
                }
                if passiveR10AlreadyNotifying {
                    self.activeProprietaryNotifyUUIDs.insert(Self.UUIDs.strapStream5)
                    self.strapStream5NotifyConfirmed = true
                    self.markPassiveR10SubscriptionConfirmed()
                }
                for counter in radioCounters {
                    self.incrementRadioCounter(counter.key, reason: counter.reason)
                }
                if let tx = foundTX {
                    self.txCharacteristic = tx
                    self.dbgTxReady = true
                    if self.startGate4HistoricalIMUWindowIfRequested(
                        peripheral: peripheral,
                        txCharacteristic: tx
                    ) {
                        AtriaDebugLog("ATRIADBG gate4_historical_imu status=owns_tx action=suppress_other_motion_commands")
                    } else if !self.handleHistoryOnlyTXDiscoveryIfNeeded(reason: "characteristics_discovered") {
                        let defaults = UserDefaults.standard
                        switch Self.historicalMotionBankTXDiscoveryAction(
                            stopPending: defaults.bool(
                                forKey: Self.workoutHistoricalMotionBankStopPendingKey
                            ),
                            workoutOwnerActive: self.workoutMotionOwnerStartedAt != nil,
                            prearmRequested: defaults.bool(
                                forKey: Self.workoutHistoricalMotionBankPrearmRequestedKey
                            )
                        ) {
                        case .stop:
                            self.stopWorkoutHistoricalMotionBankIfPossible(
                                reason: "deferred_tx_discovered"
                            )
                        case .arm:
                            self.armWorkoutHistoricalMotionBankIfPossible(
                                reason: "tx_discovered"
                            )
                        case .none:
                            break
                        }
                        if discoveryUsesProtectedStandardHR {
                            self.sendProtectedR10ActivationIfReady()
                        } else if self.strapStream5NotifyConfirmed {
                            self.armRealtime()
                        } else if !self.armWhenProprietaryNotifyPairReadyIfNeeded(reason: "characteristics_discovered_notify_pair_ready") {
                            self.scheduleProprietaryArmFallbackIfNeeded(reason: "characteristics_discovered")
                        }
                    }
                }
            }
        } else if let tx = foundTX {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                self.txCharacteristic = tx
                self.dbgTxReady = true
                if !self.handleHistoryOnlyTXDiscoveryIfNeeded(reason: "tx_only_discovered"),
                   !self.armWhenProprietaryNotifyPairReadyIfNeeded(reason: "tx_only_discovered_notify_pair_ready") {
                    self.scheduleProprietaryArmFallbackIfNeeded(reason: "tx_only_discovered")
                }
            }
        }
    }

    nonisolated func peripheral(_ peripheral: CBPeripheral,
                    didWriteValueFor characteristic: CBCharacteristic, error: Error?) {
        guard let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else {
            AtriaDebugLog("ATRIADBG writeResult status=ignored reason=stale_ble_source current=%llu peripheral=%@",
                          bleCallbackEpochFence.epoch,
                          peripheral.identifier.uuidString)
            return
        }
        let msg = error.map { "ERR:\($0.localizedDescription.prefix(18))" } ?? "ok"
        AtriaDebugLog("ATRIADBG writeResult to=%@ -> %@", characteristic.uuid.uuidString, msg)
        Task { @MainActor in
            guard self.acceptsBLECallback(
                source: callbackSource,
                peripheral: peripheral
            ) else {
                AtriaDebugLog("ATRIADBG writeResult status=ignored reason=stale_ble_epoch callback=%llu current=%llu",
                              callbackSource.epoch,
                              self.bleCallbackEpochFence.epoch)
                return
            }
            self.dbgWrite = msg
            if let error {
                let nsError = error as NSError
                let defaults = UserDefaults.standard
                defaults.set(nsError.domain,
                             forKey: OfflineSyncDefaults.lastWriteErrorDomain)
                defaults.set(nsError.code,
                             forKey: OfflineSyncDefaults.lastWriteErrorCode)
                defaults.set(nsError.localizedDescription,
                             forKey: OfflineSyncDefaults.lastWriteErrorDescription)
                defaults.set(Date().timeIntervalSince1970,
                             forKey: OfflineSyncDefaults.lastWriteErrorAt)
            }
            // `startOfflineHistoricalSync` deliberately clears the cached TX
            // reference before rediscovery. A valid callback for the final
            // pre-rediscovery write can arrive during that window; matching it
            // against the transient property would drop the callback and shift
            // every later FIFO identity by one command. The callback epoch and
            // peripheral checks above already fence stale links, so bind the
            // completion to WHOOP's stable TX UUID instead.
            if characteristic.uuid == Self.UUIDs.strapTX {
                let completedWrite = self.writeCompletionLedger.completeNext()
                if let completedWrite {
                    let nsError = error as NSError?
                    self.lastProprietaryWriteCompletion = .init(
                        generation: self.offlineHistoricalSyncInProgress
                            ? self.offlineHistoricalSyncGeneration : nil,
                        entry: completedWrite,
                        succeeded: error == nil,
                        errorDomain: nsError?.domain,
                        errorCode: nsError?.code
                    )
                }
                if let completedWrite,
                   self.onboardingPairingPreflightInFlight,
                   completedWrite.command == Cmd.getDataRange,
                   completedWrite.payload == [0x00],
                   self.onboardingPairingPreflightSequence
                        == completedWrite.sequence {
                    let nsError = error as NSError?
                    self.onboardingPairingPreflightWriteResult =
                        AtriaBLEReadOnlyHistoryCapturePolicy
                            .classifyWriteCompletion(
                                succeeded: error == nil,
                                errorDomain: nsError?.domain,
                                errorCode: nsError?.code
                            )
                    AtriaDebugLog("ATRIADBG onboarding_pairing status=range_write_callback generation=%llu sequence=%d result=%@ mutation=0",
                                  self.onboardingPairingPreflightGeneration,
                                  Int(completedWrite.sequence),
                                  error == nil ? "confirmed" : "failed")
                }
                if let completedWrite,
                   self.readOnlyHistoryCaptureActive,
                   completedWrite.command == Cmd.getDataRange,
                   completedWrite.payload == [0x00],
                   self.readOnlyHistoryRangeSequence == completedWrite.sequence {
                    self.readOnlyHistoryRangeWriteConfirmed = error == nil
                    AtriaDebugLog("ATRIADBG readOnlyHistory status=range_write_%@ generation=%llu sequence=%d mutation=0",
                                  error == nil ? "confirmed" : "failed",
                                  self.readOnlyHistoryCaptureGeneration,
                                  Int(completedWrite.sequence))
                }
                if let completedWrite,
                   completedWrite.command == Cmd.toggleRealtimeHR,
                   completedWrite.payload == [0x00],
                   self.offlineHistoricalSyncInProgress,
                   self.historyRealtimeStopRequestedGeneration
                        == self.offlineHistoricalSyncGeneration {
                    if error == nil {
                        self.historyRealtimeStopCompletedGeneration =
                            self.offlineHistoricalSyncGeneration
                        UserDefaults.standard.set(
                            "realtime_stop_confirmed",
                            forKey: OfflineSyncDefaults.handshakeStatus
                        )
                        UserDefaults.standard.set(
                            Date().timeIntervalSince1970,
                            forKey: OfflineSyncDefaults.handshakeAt
                        )
                        AtriaDebugLog("ATRIADBG historyOnly status=realtime_stop_confirmed generation=%llu sequence=%d command=0300",
                                      self.offlineHistoricalSyncGeneration,
                                      Int(completedWrite.sequence))
                    } else {
                        self.historyRealtimeStopRequestedGeneration = nil
                        AtriaDebugLog("ATRIADBG historyOnly status=realtime_stop_failed generation=%llu sequence=%d action=retain_pending_for_retry",
                                      self.offlineHistoricalSyncGeneration,
                                      Int(completedWrite.sequence))
                    }
                }
                if let completedWrite,
                   completedWrite.command == Cmd.getClock,
                   completedWrite.payload == [0x00],
                   self.offlineHistoricalSyncInProgress,
                   let preflightIdentity = self.historyReadPreflightGate.identity,
                   preflightIdentity.generation == self.offlineHistoricalSyncGeneration,
                   preflightIdentity.commandSequence == completedWrite.sequence {
                    switch self.historyReadPreflightGate.completeGATT(
                        generation: self.offlineHistoricalSyncGeneration,
                        commandSequence: completedWrite.sequence,
                        succeeded: error == nil
                    ) {
                    case .awaitingLogicalResponse(let identity):
                        self.noteOfflineHistoricalSyncProgress(
                            generation: identity.generation,
                            reason: "history_read_preflight_gatt_confirmed"
                        )
                        AtriaDebugLog("ATRIADBG historyPreflight status=gatt_confirmed generation=%llu command=0b sequence=%d action=await_matching_logical_response",
                                      identity.generation,
                                      Int(identity.commandSequence))
                    case .accepted(let identity):
                        self.acceptedHistoryReadPreflightIdentity = identity
                        self.noteOfflineHistoricalSyncProgress(
                            generation: identity.generation,
                            reason: "history_read_preflight_reordered_proofs_complete"
                        )
                        AtriaDebugLog("ATRIADBG historyPreflight status=reordered_proofs_complete generation=%llu command=0b sequence=%d authority=transport_only action=settle_then_allow_1600",
                                      identity.generation,
                                      Int(identity.commandSequence))
                    case .failed(let identity):
                        AtriaDebugLog("ATRIADBG historyPreflight status=gatt_failed generation=%llu command=0b sequence=%d action=withhold_1600_no_retry",
                                      identity.generation,
                                      Int(identity.commandSequence))
                    case .ignored, .awaitingGATTConfirmation:
                        break
                    }
                } else if let completedWrite,
                   completedWrite.command == Cmd.getClock,
                   completedWrite.payload == [0x00],
                   self.offlineHistoricalSyncInProgress,
                   self.pendingHistoryClockCommandSequence == completedWrite.sequence {
                    if error == nil {
                        self.pendingHistoryClockWriteCompletedAtUnix =
                            Date().timeIntervalSince1970
                        AtriaDebugLog("ATRIADBG historyClock status=get_clock_write_confirmed generation=%llu sequence=%d",
                                      self.offlineHistoricalSyncGeneration,
                                      Int(completedWrite.sequence))
                    } else {
                        self.pendingHistoryClockCommandSequence = nil
                        AtriaDebugLog("ATRIADBG historyClock status=get_clock_write_failed generation=%llu sequence=%d action=retain_gap",
                                      self.offlineHistoricalSyncGeneration,
                                      Int(completedWrite.sequence))
                    }
                }
                if let completedWrite,
                   completedWrite.command == Cmd.getDataRange,
                   completedWrite.payload == [0x00],
                   self.offlineHistoricalSyncInProgress,
                   self.pendingHistoryDataRangeCommandSequence
                        == completedWrite.sequence {
                    if error == nil {
                        self.pendingHistoryDataRangeWriteCompletedAtUnix =
                            Date().timeIntervalSince1970
                        AtriaDebugLog("ATRIADBG historyRange status=write_confirmed generation=%llu sequence=%d mutation=0",
                                      self.offlineHistoricalSyncGeneration,
                                      Int(completedWrite.sequence))
                    } else {
                        self.pendingHistoryDataRangeCommandSequence = nil
                        AtriaDebugLog("ATRIADBG historyRange status=write_failed generation=%llu sequence=%d action=continue_verified_full_drain",
                                      self.offlineHistoricalSyncGeneration,
                                      Int(completedWrite.sequence))
                    }
                }
                if let completedWrite,
                   completedWrite.command == Cmd.sendHistoricalData,
                   completedWrite.payload == [0x00],
                   error == nil,
                   self.offlineHistoricalSyncInProgress {
                    self.historicalFullDrainWriteEvidence = .init(
                        transportGeneration: self.offlineHistoricalSyncGeneration,
                        commandSequence: completedWrite.sequence,
                        command: completedWrite.command,
                        payload: completedWrite.payload,
                        writeCompletedAtUnix: Date().timeIntervalSince1970
                    )
                    self.gate4DailyBankHistoryServeIdentity =
                        self.currentGate4DailyBankRearmIdentity(
                            generation:
                                self.offlineHistoricalSyncGeneration
                        )
                    UserDefaults.standard.set(
                        "full_drain_write_confirmed",
                        forKey: OfflineSyncDefaults.handshakeStatus
                    )
                    UserDefaults.standard.set(
                        Date().timeIntervalSince1970,
                        forKey: OfflineSyncDefaults.handshakeAt
                    )
                    AtriaDebugLog("ATRIADBG historical_full_drain_write status=confirmed generation=%llu sequence=%d command=1600 exact_interval_authority=0",
                                  self.offlineHistoricalSyncGeneration,
                                  Int(completedWrite.sequence))
                    if let historyStartSequence = self.acceptedHistoryStartSequence {
                        self.armFullDrainAuthorityAfterHistoryStart(
                            sequence: historyStartSequence,
                            generation: self.offlineHistoricalSyncGeneration
                        )
                        self.scheduleGate4DailyBankRearmAfterHistoryStart(
                            generation: self.offlineHistoricalSyncGeneration
                        )
                    }
                }
                if error != nil,
                   self.proprietaryBatteryRefreshPhase == .awaitingResponse {
                    self.failProprietaryBatteryRefresh(reason: "write_failed")
                }
                if completedWrite?.command == Cmd.historicalDataResult {
                    self.handleHistoricalACKWriteResult(
                        completedWrite: completedWrite,
                        error: error
                    )
                } else if self.pendingHistoryEndACK != nil {
                    AtriaDebugLog("ATRIADBG historyAck status=ignored_write_callback completed_cmd=%@ completed_seq=%@",
                                  completedWrite.map { String(format: "%02x", $0.command) } ?? "unknown",
                                  completedWrite.map { String($0.sequence) } ?? "unknown")
                }
            }
        }
    }

    nonisolated func peripheral(_ peripheral: CBPeripheral,
                    didUpdateNotificationStateFor characteristic: CBCharacteristic, error: Error?) {
        guard let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else {
            AtriaDebugLog("ATRIADBG notifyState ch=%@ status=ignored reason=stale_ble_source current=%llu peripheral=%@",
                          characteristic.uuid.uuidString,
                          bleCallbackEpochFence.epoch,
                          peripheral.identifier.uuidString)
            return
        }
        let short = String(characteristic.uuid.uuidString.prefix(8))
        let notifying = characteristic.isNotifying
        let err = error?.localizedDescription
        let isData = characteristic.uuid == UUIDs.strapStream5
        if characteristic.uuid == Self.UUIDs.heartRateMeasure {
            let fastLaneDefaults = UserDefaults.standard
            fastLaneDefaults.set(notifying ? "2a37_notify_active" : "2a37_notify_inactive",
                                 forKey: BackgroundHRDiscoveryDefaults.stage)
            fastLaneDefaults.set(Date().timeIntervalSince1970,
                                 forKey: BackgroundHRDiscoveryDefaults.at)
            fastLaneDefaults.set(notifying,
                                 forKey: BackgroundHRDiscoveryDefaults.notifying)
            if let err {
                fastLaneDefaults.set(err, forKey: BackgroundHRDiscoveryDefaults.error)
            } else {
                fastLaneDefaults.removeObject(forKey: BackgroundHRDiscoveryDefaults.error)
            }
        }
        AtriaDebugLog("ATRIADBG notifyState ch=%@ notifying=%d err=%@", characteristic.uuid.uuidString, notifying ? 1 : 0, error?.localizedDescription ?? "nil")
        Task { @MainActor in
            guard self.acceptsBLECallback(
                source: callbackSource,
                peripheral: peripheral
            ) else {
                AtriaDebugLog("ATRIADBG notifyState ch=%@ status=ignored reason=stale_ble_epoch callback=%llu current=%llu",
                              characteristic.uuid.uuidString,
                              callbackSource.epoch,
                              self.bleCallbackEpochFence.epoch)
                return
            }
            if characteristic.uuid == Self.UUIDs.batteryLevelStatus {
                if err == nil,
                   notifying,
                   self.peripheral?.identifier == peripheral.identifier,
                   peripheral.state == .connected {
                    let confirmedAt = Date()
                    self.batteryStatusNotificationConfirmedAt = confirmedAt
                    UserDefaults.standard.set(
                        confirmedAt.timeIntervalSince1970,
                        forKey: BatteryDefaults.statusNotificationConfirmedAt
                    )
                    AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=notify_confirmed")
                } else if self.batteryStatusCharacteristic?.uuid == characteristic.uuid {
                    self.batteryStatusNotificationConfirmedAt = nil
                    UserDefaults.standard.removeObject(
                        forKey: BatteryDefaults.statusNotificationConfirmedAt
                    )
                }
            }
            if characteristic.uuid == Self.UUIDs.heartRateMeasure {
                // Every CoreBluetooth completion settles the one shared enable
                // request. Failure/inactive completion must clear it too so the
                // next paced watchdog pass can retry instead of being stranded.
                self.heartRateNotificationEnableGate.settle(
                    peripheralID: peripheral.identifier
                )
                self.pendingNotifyReenableUUIDs.remove(characteristic.uuid)
                AtriaDebugLog("ATRIADBG ble_notify_enable status=settled notifying=%d error=%@",
                              notifying ? 1 : 0,
                              err ?? "nil")
                if notifying {
                    self.heartRateInactiveCallbackRetryIssued = false
                } else {
                    let supportsNotifications = characteristic.properties.contains(.notify)
                        || characteristic.properties.contains(.indicate)
                    if Self.shouldImmediatelyReenableInactiveHeartRateNotification(
                        peripheralMatches: self.peripheral?.identifier == peripheral.identifier,
                        peripheralConnected: peripheral.state == .connected
                            && self.status == .connected,
                        supportsNotifications: supportsNotifications,
                        isNotifying: notifying,
                        sparseSentinel: self.dutyCycleState == .sparseSentinel,
                        retryAlreadyIssued: self.heartRateInactiveCallbackRetryIssued
                    ) {
                        self.heartRateInactiveCallbackRetryIssued = true
                        _ = self.requestHeartRateNotificationEnableIfNeeded(
                            peripheral: peripheral,
                            characteristic: characteristic,
                            reason: "2a37_inactive_callback"
                        )
                        AtriaDebugLog("ATRIADBG ble_notify_enable status=callback_retry reason=2a37_inactive_background_return action=enable_once")
                    }
                }
                if err == nil, notifying,
                   self.peripheral?.identifier == peripheral.identifier {
                    self.heartRateCharacteristic = characteristic
                    self.beginProtectedR10BringUpForCurrentEpoch(
                        peripheral: peripheral,
                        reason: "2a37_notify_confirmed"
                    )
                } else if self.denseBringUpIsWanted {
                    self.scheduleWorkoutMotionLeaseEvaluation(
                        reason: "hr_notify_retry",
                        delay: 3
                    )
                }
            }
            if characteristic.uuid == Self.UUIDs.batteryLevel {
                guard Self.shouldAllowAncillaryGATTRefresh(
                    historyTransportOwnsLink: self.recoveredDataProjectionDeferralIsActive
                ) else {
                    self.batteryNotificationRecoveryTask?.cancel()
                    self.batteryNotificationRecoveryTask = nil
                    self.pendingNotifyReenableUUIDs.remove(characteristic.uuid)
                    AtriaDebugLog("ATRIADBG battery source=2A19 status=notify_callback_observed reason=history_transport_owned action=no_cccd_recovery")
                    return
                }
                let defaults = UserDefaults.standard
                if let err {
                    self.batteryNotificationEpochHadRejectedCallback = true
                    defaults.set(err, forKey: BatteryDefaults.notificationLastError)
                    defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
                    self.revokeBatteryNotificationLease(reason: "2A19_notify_error")
                    // Do not remove the off/on marker here. In particular, a
                    // failed `setNotify(false)` normally leaves isNotifying
                    // true; the recovery watchdog must retry/rediscover rather
                    // than treating that error as a completed disable.
                    self.armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        reason: "notify_state_error"
                    )
                } else if notifying {
                    // A successful subscribe/reactivation starts a clean battery
                    // notification epoch. Rejected callbacks from a prior failed
                    // epoch cannot strand this active change-driven lease.
                    self.batteryNotificationEpochHadRejectedCallback = false
                    defaults.set(Date().timeIntervalSince1970,
                                 forKey: BatteryDefaults.notificationConfirmedAt)
                    defaults.removeObject(forKey: BatteryDefaults.notificationLastError)
                    let confirmedAt = Date()
                    if Self.batteryLevelIsFresh(
                        lastAcceptedAt: self.lastAcceptedBatteryLevelAt,
                        now: confirmedAt
                    ), defaults.string(forKey: BatteryDefaults.source) == "live_2A19" {
                        defaults.set(confirmedAt.timeIntervalSince1970,
                                     forKey: BatteryDefaults.notificationLeaseAt)
                    }
                    self.promoteReconnectBatteryBaselineIfSafe(
                        now: Date(),
                        heartRateReceivedAt: self.lastRawHRNotificationAt,
                        validatedR10ReceivedAt: self.lastR10MotionFrameAt,
                        reason: "2A19_notify_became_active"
                    )
                    self.completeBatteryNotificationRecovery()
                } else {
                    self.batteryNotificationEpochHadRejectedCallback = true
                    defaults.set("inactive", forKey: BatteryDefaults.notificationLastError)
                    defaults.removeObject(forKey: BatteryDefaults.notificationConfirmedAt)
                    self.revokeBatteryNotificationLease(reason: "2A19_notify_inactive")
                    self.pendingNotifyReenableUUIDs.remove(characteristic.uuid)
                    peripheral.setNotifyValue(true, for: characteristic)
                    self.armBatteryNotificationRecoveryWatchdog(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        reason: "notify_off_enable"
                    )
                }
                return
            }
            if self.motionHandshakeDiagnostic != nil {
                self.handleMotionHandshakeNotificationState(
                    peripheral: peripheral,
                    characteristic: characteristic,
                    error: error
                )
                return
            }
            if self.handleProtectedR10ResponseEventDataNotificationState(
                peripheral: peripheral,
                characteristic: characteristic,
                error: error
            ) {
                return
            }
            if characteristic.uuid == Self.UUIDs.strapRX,
               self.proprietaryBatteryRefreshPhase == .subscribingResponse {
                self.handleProprietaryBatteryResponseNotifyState(characteristic,
                                                                 error: error)
                return
            }
            if notifying, characteristic.uuid == Self.UUIDs.heartRateMeasure {
                self.sendProtectedR10ActivationIfReady()
            }
            if let err {
                self.pendingNotifyReenableUUIDs.remove(characteristic.uuid)
                self.dbgLast = "suberr \(short):\(err.prefix(14))"
                if isData {
                    self.strapStream5NotifyConfirmed = false
                    if self.standardHROnlyMode {
                        self.persistProtectedR10FallbackForStream5Callback(
                            reason: "clean_owner_stream5_notification_error"
                        )
                    } else {
                        self.reassertR10NotificationIfConnected(reason: "stream5_notify_error")
                    }
                }
            } else if !notifying,
                      self.pendingNotifyReenableUUIDs.remove(characteristic.uuid) != nil {
                if Self.shouldEnableNotifications(isNotifying: characteristic.isNotifying) {
                    peripheral.setNotifyValue(true, for: characteristic)
                    AtriaDebugLog("ATRIADBG ble_notify_reassert status=reenable_after_off ch=%@",
                                  characteristic.uuid.uuidString)
                } else {
                    AtriaDebugLog("ATRIADBG ble_notify_reassert status=already_notifying ch=%@ action=skip_enable",
                                  characteristic.uuid.uuidString)
                }
            }
            if err != nil {
                return
            } else if notifying {
                self.dbgSubsActive += 1
                if Self.UUIDs.allNotify.contains(characteristic.uuid) {
                    self.activeProprietaryNotifyUUIDs.insert(characteristic.uuid)
                    if isData {
                        self.strapStream5NotifyConfirmed = true
                        if self.r10TransportIsExpected {
                            self.ensureR10LivenessWatchdog(reason: "stream5_notify_active")
                        }
                        if self.standardHROnlyMode,
                           !self.historyOnlyProbeEnabled,
                           Self.shouldObservePassiveR10InProtectedStandardHR(
                            characteristicUUID: characteristic.uuid
                           ) {
                            self.markPassiveR10SubscriptionConfirmed()
                        } else {
                            self.armRealtime()     // full protocol data char ready
                        }
                        self.sendProtectedR10ActivationIfReady()
                    } else if self.armWhenProprietaryNotifyPairReadyIfNeeded(reason: "notify_pair_ready") {
                    } else {
                        self.scheduleProprietaryArmFallbackIfNeeded(reason: "notify_state_\(short)")
                    }
                }
            } else if Self.UUIDs.allNotify.contains(characteristic.uuid) {
                self.activeProprietaryNotifyUUIDs.remove(characteristic.uuid)
                if isData {
                    self.strapStream5NotifyConfirmed = false
                    if self.standardHROnlyMode {
                        self.persistProtectedR10FallbackForStream5Callback(
                            reason: "clean_owner_stream5_notification_inactive"
                        )
                    } else {
                        self.reassertR10NotificationIfConnected(reason: "stream5_notify_inactive")
                    }
                }
            }
        }
    }

    nonisolated func peripheral(_ peripheral: CBPeripheral,
                    didUpdateValueFor characteristic: CBCharacteristic, error: Error?) {
        guard let callbackSource = bleCallbackEpochFence.captureIfAccepted(
            peripheralID: peripheral.identifier,
            peripheralObjectID: ObjectIdentifier(peripheral),
            peripheralConnected: peripheral.state == .connected
        ) else {
            AtriaDebugLog("ATRIADBG value_update ch=%@ status=ignored reason=stale_ble_source current=%llu peripheral=%@",
                          characteristic.uuid.uuidString,
                          bleCallbackEpochFence.epoch,
                          peripheral.identifier.uuidString)
            return
        }
        let historyPhase = historyTransportPhaseFence.snapshot()
        if let error {
            if characteristic.uuid == Self.UUIDs.batteryLevelStatus {
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    self.batteryStatusReadRequestedAt = nil
                    let defaults = UserDefaults.standard
                    defaults.removeObject(forKey: BatteryDefaults.statusReadRequestedAt)
                    defaults.set(error.localizedDescription,
                                 forKey: BatteryDefaults.statusReadLastError)
                }
            }
            if characteristic.uuid == Self.UUIDs.batteryLevel {
                let receivedAt = Date()
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    self.recoverBatteryNotificationAfterValueError(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        errorDescription: error.localizedDescription,
                        receivedAt: receivedAt
                    )
                }
            }
            AtriaDebugLog("ATRIADBG value_update ch=%@ status=rejected error=%@",
                          characteristic.uuid.uuidString,
                          error.localizedDescription)
            return
        }
        let uuid = characteristic.uuid
        let receivedAt = Date()
        guard let data = characteristic.value else {
            if uuid == Self.UUIDs.batteryLevelStatus {
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    self.batteryStatusReadRequestedAt = nil
                    let defaults = UserDefaults.standard
                    defaults.removeObject(forKey: BatteryDefaults.statusReadRequestedAt)
                    defaults.set("missing 2A1B characteristic value",
                                 forKey: BatteryDefaults.statusReadLastError)
                }
            }
            if uuid == Self.UUIDs.batteryLevel {
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    self.recoverBatteryNotificationAfterValueError(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        errorDescription: "missing 2A19 characteristic value",
                        receivedAt: receivedAt
                    )
                }
            }
            AtriaDebugLog("ATRIADBG value_update ch=%@ status=rejected reason=missing_value",
                          uuid.uuidString)
            return
        }
        let isProprietaryNotification = UUIDs.allNotify.contains(uuid)
        let isPendingOneShotBatteryResponse = uuid == Self.UUIDs.strapRX
            && UserDefaults.standard.bool(forKey: BatteryDefaults.proprietaryRefreshPending)
        if isProprietaryNotification,
           standardHROnlyMode,
           !Self.shouldAcceptProtectedProprietaryNotification(
            characteristicUUID: uuid,
            streamSuppressed: protectedR10StreamSuppressed,
            pendingOneShotBatteryResponse: isPendingOneShotBatteryResponse,
            historyRecoveryActive: historyPhase.isActive
           ) {
            // A restored legacy subscription may briefly deliver after an app
            // update. Ignore it completely; never decode it into steps or let
            // it influence the protected standard-HR connection.
            return
        }
        if !isProprietaryNotification {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                self.recordRealGattData(at: receivedAt, source: uuid.uuidString)
                self.enforceHistoricalIdleTimeoutFromGattHeartbeatIfNeeded(
                    nowUptime: ProcessInfo.processInfo.systemUptime
                )
                if central.state == .poweredOn, peripheral.state == .connected, self.status != .connected {
                    self.recomputeConnectionStatus(reason: "event")
                }
            }
        }
        if uuid == UUIDs.heartRateMeasure {
            let parsed = Self.parseHeartRatePacket(data)
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                self.recordHeartRateReadPollResultIfNeeded(parsed: parsed)
                if let parsed {
                    self.noteDutyCycleHeartRate(parsed.hr)
                }
            }
            enqueueHeartRateUpdate(PendingHeartRateUpdate(packet: parsed,
                                                          rawData: data,
                                                          receivedAt: receivedAt,
                                                          callbackSource: callbackSource))
            return
        }
        if uuid == UUIDs.batteryLevel {
            UserDefaults.standard.set(receivedAt.timeIntervalSince1970,
                                      forKey: BatteryDefaults.notificationLastCallbackAt)
            guard let newLevel = Self.parseBatteryLevel(data) else {
                Task { @MainActor in
                    guard self.acceptsBLECallback(
                        source: callbackSource,
                        peripheral: peripheral
                    ) else { return }
                    self.recoverBatteryNotificationAfterValueError(
                        peripheral: peripheral,
                        characteristic: characteristic,
                        errorDescription: "malformed 2A19 payload",
                        receivedAt: receivedAt
                    )
                }
                AtriaDebugLog("ATRIADBG battery source=2A19 status=rejected reason=malformed bytes=%@",
                              Self.hex([UInt8](data)))
                return
            }
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                // A GATT value from a CB-connected peripheral proves the link is
                // live. Record the activity and heal a status that a watchdog or a
                // transient central blip wrongly left non-connected (after state
                // restoration no didConnect fires, so HR is the only other healer
                // and it can't fire during a low-radio HR silence).
                if central.state == .poweredOn, peripheral.state == .connected, self.status != .connected {
                    self.recomputeConnectionStatus(reason: "event")
                }
                switch Self.batteryLevelAcceptanceDecision(
                    previousLevel: self.batteryLevel,
                    previousAcceptedAt: self.lastAcceptedBatteryLevelAt,
                    incomingLevel: newLevel,
                    receivedAt: receivedAt,
                    pending: self.pendingBatteryDropCandidate,
                    previousIsCached: self.displayedBatteryLevelIsCached,
                    requiresFreshConfirmation: UserDefaults.standard.bool(
                        forKey: BatteryDefaults.requiresFreshConfirmation
                    ),
                    trustedCurrentConnectionNotification: Self.batteryValueBelongsToCurrentConnection(
                        peripheralConnected: peripheral.state == .connected,
                        connectionStartedAt: self.connectedAt,
                        receivedAt: receivedAt
                    )
                ) {
                case .quarantine(let candidate):
                    self.pendingBatteryDropCandidate = candidate
                    AtriaDebugLog("ATRIADBG battery level=%d source=2A19 status=quarantined previous=%d confirmations=%d span_s=%.1f reason=implausible_instant_drop bytes=%@",
                                  newLevel,
                                  self.batteryLevel,
                                  candidate.confirmations,
                                  candidate.lastSeenAt.timeIntervalSince(candidate.firstSeenAt),
                                  Self.hex([UInt8](data)))
                    self.scheduleBatteryConfirmationRead(incomingLevel: newLevel)
                    return
                case .accept:
                    self.batteryConfirmationReadTask?.cancel()
                    self.batteryConfirmationReadTask = nil
                    self.batteryConfirmationReadLevel = nil
                    self.pendingBatteryDropCandidate = nil
                    self.displayedBatteryLevelIsCached = false
                    self.batteryReadingIsRecentBaseline = false
                    self.batteryProjectionRevision &+= 1
                    UserDefaults.standard.removeObject(
                        forKey: BatteryDefaults.requiresFreshConfirmation
                    )
                    if self.batteryNotificationTransportIsActive(now: receivedAt) {
                        UserDefaults.standard.set(receivedAt.timeIntervalSince1970,
                                                  forKey: BatteryDefaults.notificationLeaseAt)
                    } else {
                        // A packet may still be fresh and displayable while the
                        // failed CCCD epoch is rebuilding. Keep its real sample
                        // clock, but never let it recreate the revoked lease.
                        UserDefaults.standard.removeObject(
                            forKey: BatteryDefaults.notificationLeaseAt
                        )
                    }
                }
                let previousAcceptedBatteryAt = self.lastAcceptedBatteryLevelAt
                self.lastAcceptedBatteryLevelAt = receivedAt
                // 2A19 exposes percentage, not external-power state. A bounded
                // rise spanning real time may prove Charging after the packet
                // passes the current-link truth gates. A decline is still strong
                // not-charging evidence; 100% has its separate truth gate.
                let previous = batteryLevel
                let chargeEvidenceFromThisRead = Self.chargeEvidenceFromBatteryLevelChange(
                    previousLevel: previous,
                    newLevel: newLevel
                )
                if previous >= 0 {
                    let delta = newLevel - previous
                    if chargeEvidenceFromThisRead == .full {
                        lastPlausibleBatteryRiseEvidenceAt = nil
                        lastUncorroboratedChargingStatusAt = nil
                        batteryRiseCandidate = nil
                        batteryRiseCandidatePeripheralID = nil
                        assignIfChanged(\.batteryIsCharging, false)
                        assignIfChanged(\.batteryChargeStatus, .full)
                        assignIfChanged(\.batteryRecentlyDropping, false)
                        clearBatteryDropMarker()
                    } else if delta > 0 {
                        lastPlausibleBatteryRiseEvidenceAt = receivedAt
                        batteryRiseCandidate = Self.updatedBatteryRiseCandidate(
                            current: batteryRiseCandidate,
                            previousLevel: previous,
                            previousAcceptedAt: previousAcceptedBatteryAt,
                            newLevel: newLevel,
                            receivedAt: receivedAt
                        )
                        batteryRiseCandidatePeripheralID = batteryRiseCandidate == nil
                            ? nil : peripheral.identifier
                        if batteryChargeStatus != .charging {
                            assignIfChanged(\.batteryIsCharging, false)
                            assignIfChanged(\.batteryChargeStatus, .levelOnly)
                        }
                        assignIfChanged(\.batteryRecentlyDropping, false)
                        clearBatteryDropMarker()
                        if let batteryRiseCandidate,
                           Self.batteryRiseCandidateProvesCharging(batteryRiseCandidate) {
                            // This path originates Charging from an accepted,
                            // bounded mid-range increase spanning real time. A
                            // raw or stale stream-4 bit never renews it.
                            assignIfChanged(\.batteryIsCharging, true)
                            assignIfChanged(\.batteryChargeStatus, .charging)
                            persistBatteryChargeStatus(
                                .charging,
                                source: "live_2A19_charge_trajectory",
                                observedAt: receivedAt
                            )
                            recordBatteryChargeEvidence(
                                .charging,
                                reason: "battery_rise_trajectory",
                                observedAt: receivedAt
                            )
                        }
                        // A post-unplug percentage rise is not corroboration for
                        // a previously latched 2A1B powered bit.
                        lastUncorroboratedChargingStatusAt = nil
                    } else if delta < 0 {
                        lastPlausibleBatteryRiseEvidenceAt = nil
                        lastUncorroboratedChargingStatusAt = nil
                        batteryRiseCandidate = nil
                        batteryRiseCandidatePeripheralID = nil
                        assignIfChanged(\.batteryIsCharging, false)
                        assignIfChanged(\.batteryChargeStatus, .notCharging)
                        assignIfChanged(\.batteryRecentlyDropping, true)
                    } else if batteryChargeStatus == .charging,
                              !Self.shouldPreserveFreshChargingEvidence(
                                currentStatus: batteryChargeStatus,
                                lastEvidenceAt: lastActiveBatteryChargeEvidenceAt,
                                receivedAt: receivedAt
                              ) {
                        assignIfChanged(\.batteryIsCharging, false)
                        assignIfChanged(\.batteryChargeStatus, .levelOnly)
                    }
                } else if chargeEvidenceFromThisRead == .full {
                    assignIfChanged(\.batteryChargeStatus, .full)
                    assignIfChanged(\.batteryRecentlyDropping, false)
                    clearBatteryDropMarker()
                }
                assignIfChanged(\.batteryLevel, newLevel)
                if self.r10MotionIsEligible, self.realtimeArmed {
                    self.ensureR10LivenessWatchdog(reason: "battery_eligible")
                    self.evaluateR10Liveness(now: receivedAt, reason: "battery_eligible")
                }
                persistBatteryLevel(batteryLevel, source: "live_2A19", chargeStatus: chargeEvidenceFromThisRead)
                if let chargeEvidenceFromThisRead {
                    recordBatteryChargeEvidence(chargeEvidenceFromThisRead,
                                                reason: "battery_level",
                                                observedAt: receivedAt)
                } else if batteryChargeStatus != .charging {
                    recordBatteryChargeEvidence(batteryChargeStatus,
                                                reason: "battery_level",
                                                observedAt: receivedAt)
                }
                AtriaDebugLog("ATRIADBG battery level=%d source=2A19 bytes=%@ persisted=1",
                      batteryLevel,
                      Self.hex([UInt8](data)))
            }
            return
        }
        if uuid == UUIDs.batteryLevelStatus {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                let statusReadRequestedAt = self.batteryStatusReadRequestedAt
                let readCanAuthorize = Self.batteryStatusReadCanAuthorizeCharging(
                    peripheralConnected: peripheral.state == .connected
                        && self.status == .connected,
                    connectionStartedAt: self.connectedAt,
                    readRequestedAt: statusReadRequestedAt,
                    statusReceivedAt: receivedAt
                )
                self.batteryStatusReadRequestedAt = nil
                let defaults = UserDefaults.standard
                defaults.removeObject(forKey: BatteryDefaults.statusReadRequestedAt)
                defaults.set(receivedAt.timeIntervalSince1970,
                             forKey: BatteryDefaults.statusReadCallbackAt)
                if central.state == .poweredOn, peripheral.state == .connected, self.status != .connected {
                    self.recomputeConnectionStatus(reason: "event")
                }
                if let parsedStatus = Self.parseBatteryChargeStatus(data) {
                    let proposedStatus: BatteryChargeStatus = batteryLevel >= 100 && parsedStatus == .charging ? .full : parsedStatus
                    let hasPlausibleRiseEvidence = self.pendingBatteryDropCandidate == nil && (
                        self.batteryChargeStatus == .charging
                            || self.batteryChargeStatus == .full
                            || Self.hasFreshBatteryRiseEvidence(
                                lastRiseAt: self.lastPlausibleBatteryRiseEvidenceAt,
                                receivedAt: receivedAt
                            )
                    )
                    guard let status = Self.acceptedBatteryChargeStatus(
                        proposedStatus,
                        batteryLevel: self.batteryLevel,
                        hasPlausibleRiseEvidence: hasPlausibleRiseEvidence,
                        currentConnectionPowerStateConfirmed: Self.batteryStatusNotificationCanAuthorizeCharging(
                            peripheralConnected: peripheral.state == .connected
                                && self.status == .connected,
                            connectionStartedAt: self.connectedAt,
                            notificationConfirmedAt: self.batteryStatusNotificationConfirmedAt,
                            statusReceivedAt: receivedAt
                        ) || readCanAuthorize
                    ) else {
                        self.lastUncorroboratedChargingStatusAt = nil
                        if self.batteryChargeStatus == .charging,
                           Self.shouldPreserveFreshChargingEvidence(
                            currentStatus: self.batteryChargeStatus,
                            lastEvidenceAt: self.lastActiveBatteryChargeEvidenceAt,
                            receivedAt: receivedAt
                           ) {
                            // A raw powered bit is neither positive nor negative
                            // evidence. Ignore it without refreshing or erasing
                            // a still-fresh independently proven trajectory.
                            AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=ignored proposed=%@ level=%d reason=fresh_rise_trajectory_owns_authority bytes=%@",
                                          proposedStatus.rawValue,
                                          self.batteryLevel,
                                          Self.hex([UInt8](data)))
                            return
                        }
                        if self.batteryChargeStatus == .notCharging
                            || self.batteryChargeStatus == .full {
                            // Negative/terminal truth outranks an unvalidated
                            // powered bit. Do not weaken it back to Unknown.
                            AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=ignored proposed=%@ level=%d reason=terminal_status_owns_authority bytes=%@",
                                          proposedStatus.rawValue,
                                          self.batteryLevel,
                                          Self.hex([UInt8](data)))
                            return
                        }
                        // A powered/full status packet cannot overrule a
                        // disputed level. Keep every projection fail-closed and
                        // leave the last credible percentage untouched.
                        self.assignIfChanged(\.batteryIsCharging, false)
                        self.assignIfChanged(\.batteryChargeStatus, .levelOnly)
                        self.recordBatteryChargeEvidence(.levelOnly,
                                                         reason: "battery_status_quarantined",
                                                         observedAt: receivedAt)
                        AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=quarantined proposed=%@ level=%d level_disputed=%d bytes=%@",
                                      proposedStatus.rawValue,
                                      self.batteryLevel,
                                      self.pendingBatteryDropCandidate == nil ? 0 : 1,
                                      Self.hex([UInt8](data)))
                        return
                    }
                    assignIfChanged(\.batteryIsCharging, status == .charging)
                    assignIfChanged(\.batteryChargeStatus, status)
                    self.batteryRiseCandidate = Self.batteryRiseCandidateAfterExplicitChargeStatus(
                        status,
                        current: self.batteryRiseCandidate
                    )
                    if self.batteryRiseCandidate == nil {
                        self.batteryRiseCandidatePeripheralID = nil
                    }
                    if status == .notCharging || status == .full {
                        self.lastPlausibleBatteryRiseEvidenceAt = nil
                        self.lastUncorroboratedChargingStatusAt = nil
                    } else if status == .charging {
                        self.lastUncorroboratedChargingStatusAt = nil
                    }
                    if self.r10MotionIsEligible, self.realtimeArmed {
                        self.ensureR10LivenessWatchdog(reason: "charging_eligible")
                        self.evaluateR10Liveness(now: receivedAt, reason: "charging_eligible")
                    }
                    if status == .charging || status == .full {
                        self.pendingBatteryDropCandidate = nil
                        assignIfChanged(\.batteryRecentlyDropping, false)
                        clearBatteryDropMarker()
                    }
                    if readCanAuthorize {
                        persistBatteryChargeStatus(status,
                                                   source: "live_2A1B_read",
                                                   observedAt: receivedAt)
                    } else {
                        persistBatteryChargeStatus(status,
                                                   source: "live_2A1B",
                                                   observedAt: receivedAt)
                    }
                    recordBatteryChargeEvidence(status,
                                                reason: "battery_status",
                                                observedAt: receivedAt)
                }
                AtriaDebugLog("ATRIADBG battery_charge source=2A1B status=%@ bytes=%@",
                      self.batteryChargeStatus.rawValue,
                      Self.hex([UInt8](data)))
            }
            return
        }
        if uuid == UUIDs.manufacturerName {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                assignIfChanged(\.manufacturer, String(data: data, encoding: .utf8) ?? "—")
            }
            return
        }
        if uuid == UUIDs.modelNumber || uuid == UUIDs.firmwareRevision || uuid == UUIDs.hardwareRevision {
            let text = (String(data: data, encoding: .utf8) ?? "")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                switch uuid {
                case UUIDs.modelNumber: assignIfChanged(\.modelNumber, text)
                case UUIDs.firmwareRevision: assignIfChanged(\.firmwareRevision, text)
                case UUIDs.hardwareRevision: assignIfChanged(\.hardwareRevision, text)
                default: break
                }
                AtriaDebugLog("ATRIADBG deviceinfo model=%@ hw=%@ fw=%@",
                              modelNumber, hardwareRevision, firmwareRevision)
            }
            return
        }

        let frameSource = Self.label(for: uuid)
        if uuid == UUIDs.strapStream7 {
            Task { @MainActor in
                guard self.acceptsBLECallback(
                    source: callbackSource,
                    peripheral: peripheral
                ) else { return }
                recordResearchProbeCandidate(payload: [UInt8](data), source: .diagnostic)
            }
        }

        let completeFrames = proprietaryFrameReassembler.feed(
            data,
            source: frameSource,
            scope: .init(
                historyGeneration: historyPhase.generation,
                historyServeToken: historyPhase.serveToken
            )
        )
        guard !completeFrames.isEmpty else { return }
        Task { @MainActor in
            guard self.acceptsBLECallback(
                source: callbackSource,
                peripheral: peripheral
            ) else { return }
            self.recordRealGattData(at: receivedAt, source: uuid.uuidString)
            if central.state == .poweredOn, peripheral.state == .connected, self.status != .connected {
                self.recomputeConnectionStatus(reason: "event")
            }
        }

        let storesProprietaryFrames = storeProprietaryFramesMode
        let captureUntil = strapStepCalibrationCaptureUntil
        var pendingMainActorWork: [PendingProprietaryMainActorWork] = []
        pendingMainActorWork.reserveCapacity(completeFrames.count)
        for completeFrame in completeFrames {
            if let captureUntil, receivedAt <= captureUntil {
                AtriaStrapCalibrationArchive.shared.recordMotionFrame(
                    completeFrame,
                    source: frameSource,
                    receivedAt: receivedAt
                )
            }
            if let r10Frame = AtriaR10MotionDecoder.decode(frame: completeFrame) {
                // CoreBluetooth already invokes this delegate on one serial
                // lane. Submit to the pipeline from that lane directly so a
                // later MainActor boundary marker cannot overtake a frame that
                // this callback has admitted. The pipeline still revalidates
                // the exact source immediately before detector mutation, and
                // both publication hops reject a retired source.
                if bleCallbackEpochFence.owns(source: callbackSource) {
                    r10MotionPipeline.ingest(
                        r10Frame,
                        receivedAt: receivedAt,
                        sourceIsValid: { [weak self] in
                            self?.bleCallbackEpochFence.owns(
                                source: callbackSource
                            ) == true
                        }
                    ) { [weak self] snapshot in
                        guard let self,
                              self.bleCallbackEpochFence.owns(
                                source: callbackSource
                              ) else { return }
                        Task { @MainActor [weak self] in
                            guard let self,
                                  self.bleCallbackEpochFence.owns(
                                    source: callbackSource
                                  ) else { return }
                            self.applyR10MotionSnapshot(snapshot)
                        }
                    }
                }
                if !storesProprietaryFrames {
                    let payloadLength = max(0, completeFrame.count - 8)
                    pendingMainActorWork.append(.r10Metadata(payloadLength: payloadLength))
                    continue
                }
            }

            let parsedRealtimePacket = storesProprietaryFrames
                ? nil
                : Self.parseFastRealtimeProprietaryPacket(completeFrame)
            if let parsedRealtimePacket {
                enqueueRealtimePacket(PendingRealtimeUpdate(
                    packet: parsedRealtimePacket,
                    callbackSource: callbackSource
                ))
                continue
            }
            let parsedProprietaryUpdate = storesProprietaryFrames
                ? nil
                : Self.parseProprietaryUpdate(completeFrame, source: frameSource)
            let parsedStoredFrame = storesProprietaryFrames
                ? AtriaFrame.parse(completeFrame, source: frameSource)
                : nil
            pendingMainActorWork.append(.frame(completeFrame,
                                               parsedUpdate: parsedProprietaryUpdate,
                                               storedFrame: parsedStoredFrame,
                                               historyPhase: historyPhase))
        }

        guard !pendingMainActorWork.isEmpty else { return }
        let callbackTicket = proprietaryCallbackTicketIssuer.issue()
        let callbackBatch = PendingProprietaryCallbackBatch(
            callbackSource: callbackSource,
            peripheral: peripheral,
            characteristicUUID: uuid,
            receivedAt: receivedAt,
            work: pendingMainActorWork
        )
        Task { @MainActor in
            let ready = self.proprietaryCallbackOrderBuffer.enqueue(
                ticket: callbackTicket,
                element: callbackBatch
            )
            for batch in ready {
                self.applyOrderedProprietaryCallbackBatch(batch)
            }
        }
    }

    /// Applies complete proprietary callback batches in delegate-entry order.
    /// This is especially important because HISTORY_END metadata and the last
    /// historical data notification may arrive on different characteristics.
    private func applyOrderedProprietaryCallbackBatch(
        _ batch: PendingProprietaryCallbackBatch
    ) {
        guard acceptsBLECallback(
            source: batch.callbackSource,
            peripheral: batch.peripheral
        ) else {
            AtriaDebugLog("ATRIADBG value_update status=ignored reason=stale_ble_epoch callback=%llu current=%llu ch=%@",
                          batch.callbackSource.epoch,
                          bleCallbackEpochFence.epoch,
                          batch.characteristicUUID.uuidString)
            return
        }
        for work in batch.work {
                if case let .r10Metadata(payloadLength) = work {
                    recordDecodedR10Metadata(sourceUUID: batch.characteristicUUID,
                                             payloadLength: payloadLength,
                                             receivedAt: batch.receivedAt)
                    continue
                }
                guard case let .frame(
                    completeFrame,
                    parsedProprietaryUpdate,
                    parsedStoredFrame,
                    callbackHistoryPhase
                ) = work else {
                    continue
                }
                dbgPropFrames += 1
                if shouldLogVerboseBLEFrame() {
                    AtriaDebugLog("ATRIADBG frame ch=%@ len=%d hex=%@",
                                  batch.characteristicUUID.uuidString.prefix(8).description,
                                  completeFrame.count,
                                  Self.hex([UInt8](completeFrame)))
                }
                let typeByte = Self.protocolTypeByte(in: completeFrame)
                let sig = "\(batch.characteristicUUID.uuidString.prefix(8).suffix(2)):\(String(format: "%02x", typeByte))"
                if !dbgTypeSet.contains(sig) {
                    dbgTypeSet.insert(sig)
                    dbgLast = dbgTypeSet.sorted().joined(separator: " ")
                }
                if Self.isRealtimeProtocolFrame(completeFrame, typeByte: typeByte) {
                    dbgRealtimeFrames += 1
                }
                // The nonisolated callback may pre-parse historical packets for
                // the production reducer before this MainActor batch runs. The
                // read-only diagnostic owns complete raw frames instead: route
                // them through its CRC-checked recorder before any parsed update
                // can claim or discard them as an inactive production transfer.
                if readOnlyHistoryCaptureActive {
                    handleProprietary(
                        completeFrame,
                        sourceUUID: batch.characteristicUUID,
                        historyPhase: callbackHistoryPhase
                    )
                    continue
                }
                if let parsedProprietaryUpdate {
                    if case .realtime = parsedProprietaryUpdate {
                        dbgRealtimeFrames -= 1
                    }
                    handleParsedProprietaryUpdate(
                        parsedProprietaryUpdate,
                        uuid: batch.characteristicUUID,
                        historyPhase: callbackHistoryPhase
                    )
                } else {
                    if storeProprietaryFrames, let parsedStoredFrame {
                        record(frame: parsedStoredFrame)
                    }
                    handleProprietary(
                        completeFrame,
                        sourceUUID: batch.characteristicUUID,
                        historyPhase: callbackHistoryPhase
                    )
                }
            }
    }

    private func persistBatteryLevel(_ level: Int, source: String, chargeStatus: BatteryChargeStatus? = nil) {
        guard level >= 0 && level <= 100 else { return }
        let defaults = UserDefaults.standard
        let now = Date().timeIntervalSince1970
        if let chargeStatus {
            recordChargePatternHourIfTransitioning(to: chargeStatus, defaults: defaults)
        }
        let previous = defaults.object(forKey: BatteryDefaults.level) as? Int
        if let previous, previous > level {
            defaults.set(previous, forKey: BatteryDefaults.previousLevel)
            defaults.set(defaults.object(forKey: BatteryDefaults.at) as? Double ?? now, forKey: BatteryDefaults.previousAt)
            defaults.set(previous - level, forKey: BatteryDefaults.dropDelta)
            defaults.set(now, forKey: BatteryDefaults.dropAt)
        }
        defaults.set(level, forKey: BatteryDefaults.level)
        defaults.set(now, forKey: BatteryDefaults.at)
        defaults.set(source, forKey: BatteryDefaults.source)
        if !Self.isBatterySentinel(level) {
            defaults.set(level, forKey: BatteryDefaults.credibleLevel)
            defaults.set(now, forKey: BatteryDefaults.credibleAt)
        }
        if let chargeStatus {
            defaults.set(chargeStatus.rawValue, forKey: BatteryDefaults.chargeStatus)
            defaults.set(now, forKey: BatteryDefaults.chargeAt)
            defaults.set(source, forKey: "atria.battery.chargeSource")
        }
        updateStrapStreamState(reason: "battery_level", defaults: defaults)
        let effectiveChargeStatus = chargeStatus ?? batteryChargeStatus
        LocalNotificationScheduler.scheduleStrapChargeReminder(
            batteryLevel: level,
            isCharging: effectiveChargeStatus == .charging || effectiveChargeStatus == .full)
    }

    /// Records the local hour-of-day the first time a battery update observes a
    /// transition INTO `.charging` (i.e. the previously persisted charge status
    /// was something other than charging). Keeps at most the last 14 entries and
    /// dedupes to at most one record per rolling 4 h window so a single long
    /// charge session on the dock doesn't flood the sample with one hour value.
    private func recordChargePatternHourIfTransitioning(to status: BatteryChargeStatus,
                                                        defaults: UserDefaults,
                                                        now: Date = Date(),
                                                        calendar: Calendar = .current) {
        guard status == .charging else { return }
        let previousStatus = defaults.string(forKey: BatteryDefaults.chargeStatus)
        guard previousStatus != BatteryChargeStatus.charging.rawValue else { return }

        let lastRecordedAt = defaults.double(forKey: ChargePatternDefaults.lastRecordedAt)
        if lastRecordedAt > 0,
           now.timeIntervalSince1970 - lastRecordedAt < Self.chargePatternDedupeWindow {
            AtriaDebugLog("ATRIADBG charge_pattern status=skipped reason=dedupe_window_active last_s_ago=%.0f",
                          now.timeIntervalSince1970 - lastRecordedAt)
            return
        }

        let hour = calendar.component(.hour, from: now)
        var hours = defaults.array(forKey: ChargePatternDefaults.hours) as? [Int] ?? []
        hours.append(hour)
        if hours.count > Self.chargePatternMaxEntries {
            hours.removeFirst(hours.count - Self.chargePatternMaxEntries)
        }
        defaults.set(hours, forKey: ChargePatternDefaults.hours)
        defaults.set(now.timeIntervalSince1970, forKey: ChargePatternDefaults.lastRecordedAt)
        AtriaDebugLog("ATRIADBG charge_pattern status=recorded hour=%d sample_count=%d",
                      hour,
                      hours.count)
    }

    private func persistBatteryChargeStatus(_ status: BatteryChargeStatus,
                                            source: String,
                                            observedAt: Date = Date()) {
        let defaults = UserDefaults.standard
        recordChargePatternHourIfTransitioning(to: status, defaults: defaults)
        Self.persistBatteryChargeStatusProjection(status,
                                                  source: source,
                                                  defaults: defaults,
                                                  now: observedAt)
        if status == .charging || status == .full {
            clearBatteryDropMarker()
        }
        // A 2A1B packet contains charge state only. Re-persisting the in-memory
        // percentage here used to refresh its timestamp and make a stale or
        // disputed 0/100 look like fresh level evidence across widgets and
        // notifications. Only an accepted level-bearing packet may do that.
        updateStrapStreamState(reason: "battery_charge_status", defaults: defaults)
    }

    private func clearBatteryDropMarker() {
        let defaults = UserDefaults.standard
        defaults.removeObject(forKey: BatteryDefaults.dropDelta)
        defaults.removeObject(forKey: BatteryDefaults.dropAt)
    }

    // Heart Rate Measurement per BLE spec: flags byte, uint8/uint16 BPM,
    // optional Energy Expended, then R-R intervals in 1/1024 seconds.
    nonisolated static func parseHeartRateMeasurement(
        _ data: Data
    ) -> (hr: Int, rr: [Int], truncated: Bool, sensorContactDetected: Bool?, rrFlagPresent: Bool)? {
        guard !data.isEmpty else { return nil }
        let flags = data[data.startIndex]
        let sensorContactDetected: Bool? = flags & 0x04 != 0
            ? flags & 0x02 != 0
            : nil
        let rrFlagPresent = flags & 0x10 != 0
        var index = 1
        let hr: Int
        if flags & 0x01 != 0 {
            guard index + 1 < data.count else { return nil }
            hr = Int(data[index]) | (Int(data[index + 1]) << 8)
            index += 2
        } else {
            guard index < data.count else { return nil }
            hr = Int(data[index])
            index += 1
        }
        if flags & 0x08 != 0 {
            guard index + 1 < data.count else { return nil }
            index += 2
        }
        var rr: [Int] = []
        var truncated = false
        if rrFlagPresent {
            let remainingBytes = max(data.count - index, 0)
            rr.reserveCapacity(remainingBytes / 2)
            while index + 1 < data.count {
                let raw = Int(data[index]) | (Int(data[index + 1]) << 8)
                rr.append((raw * 1_000 + 512) / 1_024)
                index += 2
            }
            truncated = index < data.count
        }
        return (hr, rr, truncated, sensorContactDetected, rrFlagPresent)
    }

    private nonisolated static func parseHeartRatePacket(_ data: Data) -> ParsedHeartRatePacket? {
        guard let measurement = parseHeartRateMeasurement(data) else { return nil }
        return ParsedHeartRatePacket(hr: measurement.hr,
                                     rrValues: measurement.rr,
                                     truncated: measurement.truncated,
                                     sensorContactDetected: measurement.sensorContactDetected,
                                     rrFlagPresent: measurement.rrFlagPresent,
                                     frameTime: Date())
    }

    private static func beatTimesEnding(at frameTime: Date, intervalsMS: [Int]) -> [(rr: Int, time: Date)] {
        guard !intervalsMS.isEmpty else { return [] }

        var remainingAfter = 0
        for rr in intervalsMS {
            remainingAfter += rr
        }

        var beats: [(rr: Int, time: Date)] = []
        beats.reserveCapacity(intervalsMS.count)
        for rr in intervalsMS {
            remainingAfter -= rr
            beats.append((rr: rr, time: frameTime.addingTimeInterval(-Double(remainingAfter) / 1000.0)))
        }
        return beats
    }

    private func shouldSkipRealtimeZeroRRTracking(now: Date,
                                                  rrCount: Int,
                                                  source: String,
                                                  lastTrackedAt: inout Date?) -> Bool {
        guard rrCount == 0, source == "0x28" else {
            lastTrackedAt = now
            return false
        }
        if let lastTrackedAt,
           now.timeIntervalSince(lastTrackedAt) < Self.zeroRRTrackingMinimumInterval {
            return true
        }
        lastTrackedAt = now
        return false
    }

    private nonisolated static func protocolTypeByte(in data: Data) -> UInt8 {
        guard let first = data.first else { return 0 }
        guard first == 0xAA, data.count > 4 else { return first }
        return data[data.index(data.startIndex, offsetBy: 4)]
    }

    private nonisolated static func isRealtimeProtocolFrame(_ data: Data, typeByte: UInt8) -> Bool {
        data.first == 0xAA && data.count > 4 && typeByte == Packet.realtime
    }

    private nonisolated static func parseProprietaryUpdate(_ data: Data,
                                                           source: String) -> ParsedProprietaryUpdate? {
        guard data.count >= 8, data.first == 0xAA else { return nil }
        let lenLowIndex = data.index(after: data.startIndex)
        let lenHighIndex = data.index(lenLowIndex, offsetBy: 1)
        let headerCRCIndex = data.index(lenHighIndex, offsetBy: 1)
        let len = Int(data[lenLowIndex]) | (Int(data[lenHighIndex]) << 8)
        guard data[headerCRCIndex] == crc8([data[lenLowIndex], data[lenHighIndex]]),
              len + 4 <= data.count,
              len >= 5 else { return nil }

        let payloadStart = data.index(headerCRCIndex, offsetBy: 1)
        let payloadEnd = data.index(data.startIndex, offsetBy: len)
        guard payloadStart < payloadEnd else { return nil }
        let payload = data[payloadStart..<payloadEnd]
        let expectedCRC = crc32(payload)
        let actualCRC = UInt32(data[payloadEnd])
            | (UInt32(data[data.index(payloadEnd, offsetBy: 1)]) << 8)
            | (UInt32(data[data.index(payloadEnd, offsetBy: 2)]) << 16)
            | (UInt32(data[data.index(payloadEnd, offsetBy: 3)]) << 24)
        guard expectedCRC == actualCRC else { return nil }

        switch payload.first {
        case Packet.realtime:
            guard payload.count >= 10 else { return nil }
            let heartRateIndex = payload.index(payload.startIndex, offsetBy: 8)
            let rrCountIndex = payload.index(payload.startIndex, offsetBy: 9)
            let rrnum = Int(payload[rrCountIndex])
            var decodedRR: [Int] = []
            decodedRR.reserveCapacity(rrnum)
            var truncated = false
            if rrnum > 0 {
                var rrIndex = payload.index(rrCountIndex, offsetBy: 1)
                for _ in 0..<rrnum {
                    let next = payload.index(rrIndex, offsetBy: 2, limitedBy: payload.endIndex)
                    guard let next, next <= payload.endIndex else {
                        truncated = true
                        break
                    }
                    let lo = Int(payload[rrIndex])
                    let hi = Int(payload[payload.index(after: rrIndex)])
                    decodedRR.append(lo | (hi << 8))
                    rrIndex = next
                }
            }

            let realtimeUnix: UInt32
            if payload.count >= 6 {
                realtimeUnix = UInt32(payload[payload.index(payload.startIndex, offsetBy: 2)])
                    | (UInt32(payload[payload.index(payload.startIndex, offsetBy: 3)]) << 8)
                    | (UInt32(payload[payload.index(payload.startIndex, offsetBy: 4)]) << 16)
                    | (UInt32(payload[payload.index(payload.startIndex, offsetBy: 5)]) << 24)
            } else {
                realtimeUnix = 0
            }

            return .realtime(ParsedRealtimePacket(realtimeUnix: realtimeUnix,
                                                  hr: Int(payload[heartRateIndex]),
                                                  rrValues: decodedRR,
                                                  truncated: truncated,
                                                  frameTime: Date()))
        case 0x24:
            guard let frame = AtriaFrame.parse(data, source: source) else { return nil }
            return .commandResponse(frame)
        case Packet.metadata:
            return .historyMetadata([UInt8](payload))
        case Packet.historical:
            return .historical([UInt8](payload))
        case .some:
            return .unknown(payload: [UInt8](payload), fullFrame: [UInt8](data))
        case .none:
            return nil
        }
    }

    private nonisolated static func parseFastRealtimeProprietaryPacket(_ data: Data) -> ParsedRealtimePacket? {
        guard data.count >= 14, data.first == 0xAA else { return nil }
        let lenLowIndex = data.index(after: data.startIndex)
        let lenHighIndex = data.index(lenLowIndex, offsetBy: 1)
        let headerCRCIndex = data.index(lenHighIndex, offsetBy: 1)
        let len = Int(data[lenLowIndex]) | (Int(data[lenHighIndex]) << 8)
        guard len >= 10, len + 4 <= data.count else { return nil }
        guard data[headerCRCIndex] == crc8([data[lenLowIndex], data[lenHighIndex]]) else { return nil }

        let payloadStart = data.index(headerCRCIndex, offsetBy: 1)
        let payloadEnd = data.index(data.startIndex, offsetBy: len)
        guard payloadStart < payloadEnd else { return nil }
        let payload = data[payloadStart..<payloadEnd]
        guard payload.count >= 10, payload.first == Packet.realtime else { return nil }

        let checksumStart = payloadEnd
        let checksumEnd = data.index(checksumStart, offsetBy: 4)
        guard checksumEnd <= data.endIndex else { return nil }
        let expectedCRC = crc32(payload)
        let actualCRC = UInt32(data[checksumStart])
            | (UInt32(data[data.index(checksumStart, offsetBy: 1)]) << 8)
            | (UInt32(data[data.index(checksumStart, offsetBy: 2)]) << 16)
            | (UInt32(data[data.index(checksumStart, offsetBy: 3)]) << 24)
        guard expectedCRC == actualCRC else { return nil }

        let realtimeUnix = UInt32(payload[payload.index(payload.startIndex, offsetBy: 2)])
            | (UInt32(payload[payload.index(payload.startIndex, offsetBy: 3)]) << 8)
            | (UInt32(payload[payload.index(payload.startIndex, offsetBy: 4)]) << 16)
            | (UInt32(payload[payload.index(payload.startIndex, offsetBy: 5)]) << 24)
        let heartRateIndex = payload.index(payload.startIndex, offsetBy: 8)
        let rrCountIndex = payload.index(payload.startIndex, offsetBy: 9)
        let rrCount = Int(payload[rrCountIndex])
        var decodedRR: [Int] = []
        decodedRR.reserveCapacity(rrCount)
        var truncated = false
        if rrCount > 0 {
            var rrIndex = payload.index(rrCountIndex, offsetBy: 1)
            for _ in 0..<rrCount {
                let next = payload.index(rrIndex, offsetBy: 2, limitedBy: payload.endIndex)
                guard let next, next <= payload.endIndex else {
                    truncated = true
                    break
                }
                let lo = Int(payload[rrIndex])
                let hi = Int(payload[payload.index(after: rrIndex)])
                decodedRR.append(lo | (hi << 8))
                rrIndex = next
            }
        }

        return ParsedRealtimePacket(realtimeUnix: realtimeUnix,
                                    hr: Int(payload[heartRateIndex]),
                                    rrValues: decodedRR,
                                    truncated: truncated,
                                    frameTime: Date())
    }

    private nonisolated static func parseRealtimeProprietaryPacket(_ data: Data) -> ParsedRealtimePacket? {
        parseFastRealtimeProprietaryPacket(data)
            ?? {
                guard let update = parseProprietaryUpdate(data, source: ""),
                      case .realtime(let packet) = update else { return nil }
                return packet
            }()
    }

    // Heart Rate Measurement per BLE spec: flags byte, then uint8 or uint16 BPM.
    static func parseHeartRate(_ data: Data) -> Int {
        parseHeartRateMeasurement(data)?.hr ?? 0
    }

    nonisolated static func label(for uuid: CBUUID) -> String {
        switch uuid {
        case UUIDs.strapRX:      return "RX/resp"
        case UUIDs.strapStream4: return "stream4"
        case UUIDs.strapStream5: return "stream5"
        case UUIDs.strapStream7: return "stream7"
        default:                 return uuid.uuidString.prefix(8).lowercased()
        }
    }

}
